INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silahlar Sustuğunda', 'silahlar-sustugunda-ozgur-kokturk-oe2jl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sustuğunda silahlar gelecek barışın sesi

Umudu tükenmez bir sevda gibi

Ağlayan anaların yaşı silindiğinde...

Bak 

Dinle

Duy şarkılarını

Bir çocuk bu

Bu bir genç kız

Bu yaşlı adam

Sarı, kahverengi, beyaz tenli

Müslüman, yahudi, nasrani

Hep aynı şarkıyı söylüyor 

Hüzünler coşkuya

Kederler sevince dönüşüyor...

Sustuğunda silahlar gelecek barışın sesi

Umudu tükenmez bir sevda gibi

Ağlayan anaların yaşı silindiğinde...', 'Sustuğunda silahlar gelecek barışın sesi Umudu tükenmez bir sevda gibi Ağlayan anaların yaşı silindiğinde... Bak  Dinle Duy şarkılarını Bir ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/silahlar-sustugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Nazlısın-Sesli Şiir Video Slayt', 'oyle-nazlisin-sesli-siir-video-slayt-bekir-alim-un73f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman doldu gayrı git yavaş yavaş

Süzülen bir fidan gibi nazlısın

Yüregin ter temiz gözlerinde yaş

Gelinlik kız gibi öyle yaslısın

Sözlerinde güven ihtişam vardı

Şiirlerde adın mevsim bahardı

Doymadan ayrıldık bir hüzün sardı

Haftada ay''da bir aramazmısın

Salınıp yürüsen yer gök imrenir

Bilmemki bu işe nasıl ne denir

Asillik sendedir sende demlenir

Girsen şu kalbime yaramazmısın

Son bahar gelmiştin gittin yaz ile

Türküler söylerdik binbir haz ile

Gel otur yanıma cilve naz ile

Verdigin sözünde duramazmısın

Derindir der; Alim deryanın dibi

İçimde fırtına esiyor tipi

Daldan dala konan kelebek gibi

İstesen yurt yuva kuramazmısın

Şiir ve Yorum:Bekir ALİM

iframe src=''http://depo.mynet.com/dosya/e5ce4166f9335279bb968e91fc0c1265-73167/Oyle-Nazlisin-Bekir-Alim/1'' frameborder=''no'' scrolling=''no'' width=''194px'' height=''77px''/iframe', 'Zaman doldu gayrı git yavaş yavaş Süzülen bir fidan gibi nazlısın Yüregin ter temiz gözlerinde yaş Gelinlik kız gibi öyle yaslısın Sözlerind...', ARRAY['Türk Edebiyatı','Şiir','Bekir Alim']::text[], 8.5, '{"poet":"Bekir Alim","poet_slug":"bekir-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyle-nazlisin-sesli-siir-video-slayt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkla Konuşmak', 'karanlikla-konusmak-oguzkan-bolukbasi-r5gw4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnadına yapıyorsun biliyorum

Sevmenin bir şekli bu

Orospu cilveleriyle can yakmak

Eteklerini rüzgara katmak için sokaklara çıkmak

Canın kavga istiyor

Senin için bıçaklar çekilsin

“El ayak çekilsin ben yapacağımı bilirim” de diyemem

Sen sakızını balon yaparken 

Benim gözlerim fecir kızıllığında

Şart mıdır tüm kasabanın yüreğini hoplatmak

İnadına yapıyorsun biliyorum

Daha mı çok üzerine düşeceğim

Yoksa toparlandım gidiyorum mu diyeceğim

Sınamaktan ziyade ateş yakmak, boğazımdan aşağı boşaltmak lavları

Dudakları ağlamaya büzülmüş halde

Fena halde 

Herhalde

Benim sevgimden şüpheye düşmemek için

Şart mıdır tüm kasabanın yüreğini hoplatmak

Senin ardından

Sokaklara takılmış tüm fahişelerin yalancı aşklarına tav oluyorum

Senin ardından

Gül taşıyan gönüllerin hanelerinden kovuluyorum

Senin ardından

Benzetilmemiş nesneler gibi savruluyorum

Yerimde başkası olsa

Tasını tarağını toplayıp giderdi uzayın derinliklerinde görünmeyen bir yere

Belki aldığını bırakmayan kara deliklere

Benim yaptığıma aşk denir sadece

Böylece arsız ve umarsız

Belki de kara sevda

Asılsız bir hayalin çölünde yalınayak

Resmin duvarda

Hareketsiz izliyor yaptıklarımı

Senin gibi

Sessiz ve sessiz

Bir gün olur da resim ses verirse

Daha ümitliyim bu durumdan

Senin sessizliğine de katlanır hale geleceğim

Şimdi yalnızca karanlıkla konuşuyorum.', 'İnadına yapıyorsun biliyorum Sevmenin bir şekli bu Orospu cilveleriyle can yakmak Eteklerini rüzgara katmak için sokaklara çıkmak Canın kavg...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/karanlikla-konusmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Dünyam Sana Özel...', 'benim-dunyam-sana-ozel-efsun-aydin-87m2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dünya kurdum kendime senin de içinde olduğun

Gülünç olaylarla süsleyip, farklı konulara ağladığımız bir dünya…

Bir toz bulutunun bazı bazı üzerine kaplayıp,

Görmemize engel olduğu gerçekler…

Dur diyemediğimiz dokunuşlar,

SEviyorum seni de ondan diye kurulan bağlılık cümleleri,

Çıkış noktasından uzaklaşmak ve bir kez daha içinde sıkışmak…

Sonra dinlemek kalp atışlarımızı…

Ve herşeyin bir anda donması…

Bir kadeh kırmızı şarap,

Belki atıştırılan bir iki meze…

Hafif bir baş dönmesi…

Gizli duygularla yüzleşmek,

Dans etmek …

Sen, ben ve kurduğum dünya…', 'Bir dünya kurdum kendime senin de içinde olduğun Gülünç olaylarla süsleyip, farklı konulara ağladığımız bir dünya… Bir toz bulutunun bazı ba...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-dunyam-sana-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar ve çocuk', 'ruzgar-ve-cocuk-gulseren-onay-qvxyi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman çıksa rüzgar,

Çocuk korkar…

Uçurtmasını almış 

Elinden,

Yanında annesine rağmen….

GÜLSEREN ONAY

18/07/2005/ANTALYA', 'Ne zaman çıksa rüzgar, Çocuk korkar… Uçurtmasını almış  Elinden, Yanında annesine rağmen…. GÜLSEREN ONAY 18/07/2005/ANTALYA...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruzgar-ve-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muammâ...', 'muamm-ulvi-ziya-qfogc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Takdir-i İlâhi muammâdır; acaba,ne gâyeler gütmüş

İnsanlar birçok defâ aldanarak koynunda yılan büyütmüş...

Asırlarca,devşirmenin gücünden medet umup; pâdişahlar

Devletin selâmeti için oğlunu,kardeşini öldürtmüş...

Kanlarına karışmış gayrımüslimin kanı...

Murat,Bafo''yu sevmiş; Kânunî,Rokselan''ı...

Âsi Enver,Niyâzi yurt edinmiş Balkan''ı...

Bu koskoca devleti daha kimler böldürtmüş...

Düşündükçe gönlümün artıyor her an gamı...

Rüşvete yönelenler helal bilmiş haramı...

Hırvat,Boşnak,Gürcü''den ülkenin sadrazamı...

Çelik gibi devleti daha neler çürütmüş? ...

Kadınlar siyasete elini daldırmasa...

Yurdu savunan güçler kazanlar kaldırmasa...

Her otuz senede bir düşmanlar saldırmasa...

Çok mu uzun yaşardı; yoksa,daha mı kısa...

Kimler Türk Milletini dikenlerden yürütmüş ? ...', 'Takdir-i İlâhi muammâdır; acaba,ne gâyeler gütmüş İnsanlar birçok defâ aldanarak koynunda yılan büyütmüş... Asırlarca,devşirmenin gücünden m...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/muamma-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun...', 'yaziklar-olsun-ulvi-ziya-0917t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zulmet çökmüş gibi ruhlar; karardıkça kararır...

Vicdanlarda tüten duman,yükselir arşa varır...

Herkes birçok yanlışını yutturur gerçek diye; 

Şeytan bile kendisini lafla haklı çıkarır...', 'Zulmet çökmüş gibi ruhlar; karardıkça kararır... Vicdanlarda tüten duman,yükselir arşa varır... Herkes birçok yanlışını yutturur gerçek diye...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yaziklar-olsun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Kokulu Sevdiğim', 'hasret-kokulu-sevdigim-filiz-sarikaya-rwcod', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşününce

Yağmurlar iner

Demir atar gözlerime

Yıldızsız, aysız geceler yüreğime

Sevdamı bulutlara yüklerim

Sana getirsinler diye

Rüzgar esmez,

Uyurum geceler, günler boyu

Zaman geçmez

Hasretim bitmez

Sevda başımdan gitmez', 'Seni düşününce Yağmurlar iner Demir atar gözlerime Yıldızsız, aysız geceler yüreğime Sevdamı bulutlara yüklerim Sana getirsinler diye Rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Filiz Sarıkaya']::text[], 8.5, '{"poet":"Filiz Sarıkaya","poet_slug":"filiz-sarikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hasret-kokulu-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-arzu-gulucudur-mou62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah....Ahhh 

Diye başlardı hatıralarda kalanlar... 

''Offff... Offf'' lara karışırdı aniden cümleler 

Pişmanlık sözleri ardın sıra dökülür dillerden 

''KEŞKE'' ler binbir hece 

Keşke yapmasaydım 

Keşke sevmeseydim 

Keşke demeseydim 

Uzar gider... 

Yaşanmışlıklar ardın sıra... 

Yaşananlar keza.. 

Yaşanacaklar merhaba... 

Keşkeler elveda...

ELVEDA...', 'Ah....Ahhh  Diye başlardı hatıralarda kalanlar...  ''Offff... Offf'' lara karışırdı aniden cümleler  Pişmanlık sözleri ardın sıra dökülür dill...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/elveda-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamâne''nin Kudurganlığı Hakkında...', 'zam-ne-nin-kudurganligi-hakkinda-ulvi-ziya-24ixq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şeytan iğfal eder beyni; insan,mânen kudurur...

Yaptığı her mel''anete özel fetvâ uydurur...

Hatâları,cürümleri hoş görünür kendine; 

Var olanı yok eder,acımadan insan vurur...

O ne habis gâyedir ki yaşatmayıp öldürür...

O ne pis bir mâyedir ki vatan millet böldürür...

Kanların aktığı yerde sevgi çiçeği bitmez; 

Güzel amaç hayat verir,ağlayanı güldürür...

Kul hakkını gözetmeyen zararlı yaratıktır...

Cemiyetin baş düşmanı,zehirli bir atıktır...

Hayat hakkı en mukaddes hakkıdır her insanın; 

İnsan canı almak,Allah''a mahsus pratiktir...

Kirlenmiş bir beyinde tersyüz olur hakîkatlar...

Ulvî fikirler bile bombaya dönüşür,patlar...

Yapmak,yıkmak anlaşılır; yaşatmaksa öldürmek...

Acımasız ellerde yok olur gider hayatlar...

Öyle şeyler yapılır ki; akla,hayâle sığmaz...

Susar dil,gördüğünden incinir göz,yürek çatlar...

Keşfiyle,îcâdıyla övünüp durur insanlık; 

Hep,vahşetiyle birlikte ilerleyip çağ atlar...', 'Şeytan iğfal eder beyni; insan,mânen kudurur... Yaptığı her mel''anete özel fetvâ uydurur... Hatâları,cürümleri hoş görünür kendine;  Var ola...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zamane-nin-kudurganligi-hakkinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencereler', 'pencereler-kemal-tahir-ozcan-tc0op', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya bir pencereden,gönlüme bet  görünür.

Bir başka pencereden,heryer mabet görünür.

Açılmaz  kapalıdır, gönlüme   perdeleri,

Bir pencere ki zannım,hep muhabbet görünür.', 'Dünya bir pencereden,gönlüme bet  görünür. Bir başka pencereden,heryer mabet görünür. Açılmaz  kapalıdır, gönlüme   perdeleri, Bir pencere k...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pencereler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanatımız Hayâtımız...', 'sanatimiz-hay-timiz-ulvi-ziya-qwnjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağzımızla kuş tutsak da rağbet görmez sanatımız...

İltimaslı at birinci,bizim uçsa da atımız...

Kuralları kalleş yazmış,hüküm ise nâmerttedir; 

Kadersizler yarışması; ki o,bizim hayâtımız...', 'Ağzımızla kuş tutsak da rağbet görmez sanatımız... İltimaslı at birinci,bizim uçsa da atımız... Kuralları kalleş yazmış,hüküm ise nâmerttedi...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanatimiz-hayatimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar Ver', 'karar-ver-halil-i-brahim-kecebas-eu690', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karar ver artık aşkımız için,

Ya ben olayım yanında yaşlanan

Ya da bitsin seni beklediğim an.

Bildiğim yoktu beni sevdiğini,

Seni kaybedince anladım; 

Gözlerim kurudu yine ağladım.

Aylarca yollarını bekledim.

Rüyalarımda karşıladım seni,

Hayalin yatıştırdı gidişini.

Gittiğin şehirde seni bulabilsem

Ve söylesem hala sevdiğimi.

Görür müyüm gözlerinde gözlerimi? 

Seni tanımasaydım bundan iyiydi,

Yokluğun yakıyor içimi.

Sanki bir kor biçimi.

Ruhum oldukça,özleyecek seni.

Her daim düşüncemde varsın,

Sen unutamadığım kadınsın…', 'Karar ver artık aşkımız için, Ya ben olayım yanında yaşlanan Ya da bitsin seni beklediğim an. Bildiğim yoktu beni sevdiğini, Seni kaybedince...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Keçebaş']::text[], 8.5, '{"poet":"Halil İbrahim Keçebaş","poet_slug":"halil-i-brahim-kecebas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karar-ver-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tende Aşk', 'tende-ask-arzu-gulucudur-3ipt6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanın dakikası kaçadır

      Akıl gitmiş baştan yardadır

      Yar anlamaz derdimden sözü hep aşkadır

      Aşk aşk dedikleri dakikası kaçadır

      Söz ola devran döne aşka

      Sevda bilir neler çektiğini başka

      Kimse bilmez derdimİ aşktan başka

      Aşk aşk dedikleri nedir yardan başka

      Devir aşk devri deyip geçme

      Değişti devran aşk artık beden içre

      Gözü kör dili lal yardan başka

      Aşk Aşk dedikleri nedir bir parça tenden başka..', 'Zamanın dakikası kaçadır       Akıl gitmiş baştan yardadır       Yar anlamaz derdimden sözü hep aşkadır       Aşk aşk dedikleri dakikası kaç...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tende-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Olmak...', 'i-nsan-olmak-ulvi-ziya-4hui9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan olan; yurduna gönül verir,hoş bakar...

Havâsında,suyunda cennetten nişâne var...

Allah''a açılmış el,ağacın her bir dalı; 

Hangi vicdanlı kişi,zümrüt ormanı yakar ? ...

Ağacın niyâzına YARATAN cevap verir...

Semâdan rahmet iner,dağ taş,her yan göverir...

Sanki cennetten sûret görünür yeryüzünde; 

Bunu görebilenin,kalbi taş olsa erir...

Ruhları dinlendirir kopkoyu gölgeleri

Coşkun akan nehirler...Çağlayan bölgeleri...

Buzlu kaynak suları kavun karpuz çatlatır; 

Lezzet alıp serinler,toplumun bilgeleri...

Çeşit çeşit canlılar içinde sefâ sürer...

Uçan kuşlar dallarda yuva yaparak ürer...

Her cinsten yaratığa menfaatı pek çoktur; 

İnsan olan,ormana iyi niyetle girer...

Dünyânın bir ucunda bulunsa bile orman

İyi bil ki; her canlı,her insan için derman...

Ağaç yetiştirmeli uygun olan her yerde; 

Hayat huzurludur,zümrüt bol olduğu zaman...

Ey kararmış kalpliler ormanı yakmak niçin? 

Hasma ait de olsa,orman hepimiz için...

Dost/düşman ayırdetmez,havamızı temizler; 

Eğer insan iseniz,bu fenâ işten kaçın...

Yansın tâ ciğerinden ormana od düşüren...

Kasten ateşe verip,sadistçe zevk devşiren...

Kasıt olmasa bile,çok dikkat edilmeli; 

İnsan olarak çıksın,oraya insan giren...

Torununu düşünsün istikbâli kemiren...', 'İnsan olan; yurduna gönül verir,hoş bakar... Havâsında,suyunda cennetten nişâne var... Allah''a açılmış el,ağacın her bir dalı;  Hangi vicdan...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/insan-olmak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaflet...', 'gaflet-ulvi-ziya-6j8ya', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nice baharlar geçti ömrümüzden; nice yazlar,kışlar...

Hebâ olup gitti,yaşam diye ördüğümüz nakışlar...

Bundan böyle,zirveye çıkıp kahkaha atsak ne fayda; 

Hüznümüz kâfi bize,elin olsun utku ve alkışlar...', 'Nice baharlar geçti ömrümüzden; nice yazlar,kışlar... Hebâ olup gitti,yaşam diye ördüğümüz nakışlar... Bundan böyle,zirveye çıkıp kahkaha at...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gaflet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilen Kadına', 'sevilen-kadina-tayfun-isildar-olozk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum, düşüm oluyorsun

canımdaki alıcı kuşum oluyorsun

yetmiyorsun, hüzün oluyorsun

yanımda değilsin ama

sevgilim oluyorsun

paylaşalım derken yaşamı

tamda yanı başımdaydın derken

aramışlığım, sevdam,  sevgilim derken

gecem oluyorsun

cama alnımı dayıyorum, yağmurum 

kavga derken, yoldaşım

dönüp bakıyorum aniden yok oluyorsun

yokluğun felaketim oluyor.

anlamıyorsun…

bekle dediğimde yüreğine

martı oluyorsun sonsuz denizlerde

kuş uçumu hayatı geçiyoruz

sen kuş kanadı oluyorsun

bense ateşböceği

sonrasını bilmiyorum

hiç ummadığım bir yerde 

yaşanmamış bir aşkın baş kadını oluyorsun

bekliyoruz sesini

bekliyoruz gölgeni

sen gene senin oluyorsun.

seninle okyanusları özlerken

sesinde türküleri beklerken

paylaşmak varken yaşamı

direnmek varken…

yaşanmamışlıkları sana

yaşanacakları geleceğe teslim edip

demirlerini çekiyorum yüreğimin

bu denizde gene senin resmin

seyir defterime seni yazıyorum yine

suskunluğum tarihe değil

suskunluğum sana,

sakın unutma galibi değilsin aşkın

elini tuttuğum o yerde

o kıyıcıkta ben olacağım aynı saatte

ellerimde ay ışığı gözlerim, lodos sonrasının sarhoşluğunda

git desem yalnızlığıma

adresini kaybetmiş mektuplar gibi kalır bende 

ismi benden bilinir  ihanetlerin, sonrası buz keser çiçekler

diyettir ödenir aşka 

vurgundur,

gelir bulur

meçhul dediğimiz  kendisini eş seçer 

aşksa yalnız gezer, acıyı sever

yaşadıklarımız gibi

sonrası …

sorulmaz, 

gidilen yer  neresiyse aynı aşkla dönülmez

  15/11/2001   ÇENGELKÖY', 'Seni düşünüyorum, düşüm oluyorsun canımdaki alıcı kuşum oluyorsun yetmiyorsun, hüzün oluyorsun yanımda değilsin ama sevgilim oluyorsun payla...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Işıldar']::text[], 8.5, '{"poet":"Tayfun Işıldar","poet_slug":"tayfun-isildar","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sevilen-kadina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan Dağı', 'hasan-dagi-yavuz-bayram-caliskan-optrb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eylül''de doruğu kara bürünür

Eteğindeki köyler bir bir görünür

Bulutlur gelir tepesine sarınır

Anadolumun incisi, canım Hasandağı

Büyüğün ardında küçüğü vardır

Çıkış yolları pek zorlu ve dardır

Aksaray''ın sırtını dayadığı yerdir

Anadolumun papatyası canım Hasandağı

Volkanın izleri çevrede görülür

Lav taşlarından duvarlar örülür

Yufka ekmeklere peynir dürülür

Anadolumun yüreği canım Hasandağı

Pınarlarından çıkan sular pek tatlıdır

Otlayan koyunlar kekik etlidir

Yamacındaki güzeller gamze hatlıdır

Anadolumun sevdası canım Hasandağı

Koruluk ormanları meşedir

Aksaray''ın çiçeği, Hasandağı neşedir

Yüzyıllar geçse de bitmeyecek sevdadır

Anadolumun toprağı canım Hasandağı

Yavuz Bayram günün doğduğu yere bakar

Dostlarla bir olur dağına çıkar

Sevdalar tüter, gönüller yakar

Anadolumun çınarı canım Hasandağı', 'Eylül''de doruğu kara bürünür Eteğindeki köyler bir bir görünür Bulutlur gelir tepesine sarınır Anadolumun incisi, canım Hasandağı Büyüğün ar...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasan-dagi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etmedim', 'etmedim-ufuk-coban-db6e3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bendeki hayat hep başkasına adandı isteyerek,

Sevgi sözcükleri belki azdı ama hep gerçekti,

Gözlerimde aynı duygu, aynı düşler geldi geçti,

Yalnızlıklara çıktı nedense bütün yollar istemeyerek.

Sevmeyi o kadar çok istedim ki ölürcesine,

Gözlerde kaybolmayı o kadar istedimki bir ömür boyu,

Engeller çıktı karşıma, kaldı elim kolum bağlı,

Sonu hep yalan oldu, sessizlik oldu, gözler hep ağladı.

Karşılıksız yaptım, ne yaptıysam sevgi çiçeğime,

Bir damla su verdiysem kendimdendi, bendeki sevgidendi.

Değer bilseydi biri, gözlerimden alırdı dalmaları,

Hayat ne verdiysem hep aldı, hep götürdü benden umutları.

Bir ışıksız oda yüreğim, duvarları resimlerle dolu,

Eskilere, hatıralara, yağmurları bırakmış yıllar oldu,

Hayat bana tek şey öğretti, yılların kışları ardından,

Hak etmedim mutluluğu, hak etmedim kimsenin dokunuşunu.

18/07/2005 13:10', 'Bendeki hayat hep başkasına adandı isteyerek, Sevgi sözcükleri belki azdı ama hep gerçekti, Gözlerimde aynı duygu, aynı düşler geldi geçti, ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/etmedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğü istedim', 'ozgurlugu-istedim-tayfun-isildar-8t842', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi,  senden kalan neye değsem 

kırılıyor inatla 

her kuş kendine uçuyor 

her göç, kendine göçüyor birazda

sen…gitmeler zamanının erkenci  saati

vuruşun zamana değil, kendine 

bil ki,galibi yok aşkın

tarihin not tutucuları,

yazın benden olanı 

pembe üçkağıtlar değil, anlattığım

aşkın sunaklarında akıtıldı kanım

tüm bıçakların sırtı, 

tenimle sınandı inatla 

ama bildiğim tek şey var 

yollarına kazıdığım ayak izlerim

ne talan olmuş coğrafyalar, 

ne eskitilmiş sevgiler düşledim

ben

sadece

özgürlüğü 

istedim

03-02-2005	

ümraniye', 'şimdi,  senden kalan neye değsem  kırılıyor inatla  her kuş kendine uçuyor  her göç, kendine göçüyor birazda sen…gitmeler zamanının erkenci ...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Işıldar']::text[], 8.5, '{"poet":"Tayfun Işıldar","poet_slug":"tayfun-isildar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozgurlugu-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mâzi İle Âti Arasında...', 'm-zi-i-le-ti-arasinda-ulvi-ziya-29hcl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi şöhretiyle mest ve mağrur; kimi malıyla,parasıyla...

Kimi âleme hükmetmeye çalışır sonsuz ihtirasıyla...

Herşeyin fâni olduğunu bilir de gâfildir insan oğlu; 

Gelip geçer,konup göçer,topraklara karışır sırasıyla...', 'Kimi şöhretiyle mest ve mağrur; kimi malıyla,parasıyla... Kimi âleme hükmetmeye çalışır sonsuz ihtirasıyla... Herşeyin fâni olduğunu bilir d...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mazi-ile-ati-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar...', 'yillar-ulvi-ziya-qjwek', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar ömrümüzü alıp sürükleyen ırmaktır...

Vuslat denizine; saman çöpü misâli,sessiz...

Maksat,RABBİN huzuruna yüz akıyla varmaktır...

İster kalabalık içinde ol,ister kimsesiz...', 'Yıllar ömrümüzü alıp sürükleyen ırmaktır... Vuslat denizine; saman çöpü misâli,sessiz... Maksat,RABBİN huzuruna yüz akıyla varmaktır... İste...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yillar-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-kocibey-murat-gumus-7y9zz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimler uydurmuş karşının ışıklarını! 

Işıkların karşıdan gelenini…

Gelsin otursun, buyursun.

Ama karşı olmasın içimin sıcak çocuğu.

Tellerimize konan kuşlar, 

Bize neden ve ne kadar dünyamız olduğunu anlatır dizi dizi

Çevrelemişiz kendi esaretimizi 

Ve demişiz adına:

Bizim olan ve bizden sonra olacak çizgi.

Tabii ya! tabii ki…

Karşı ışıklar yaksa da kendi içini,

Ancak uzağında duran içindir

Karşı ışıklar betimlemesi…', 'Kimler uydurmuş karşının ışıklarını!  Işıkların karşıdan gelenini… Gelsin otursun, buyursun. Ama karşı olmasın içimin sıcak çocuğu. Tellerim...', ARRAY['Türk Edebiyatı','Şiir','Koçibey Murat Gümüş']::text[], 8.5, '{"poet":"Koçibey Murat Gümüş","poet_slug":"kocibey-murat-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayna-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Bölü Dört', 'dort-bolu-dort-kocibey-murat-gumus-mxbc0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bütün elmayı,

dört bölü dört oranında paylaşmaktır

 aşk…

Manava ödenen bedeldir 

Evlilik…

Ve boşanmanın tanımıdır 

Foseptik…

Kızanlar psişik! 

Pışşıkk ……', 'Bir bütün elmayı, dört bölü dört oranında paylaşmaktır  aşk… Manava ödenen bedeldir  Evlilik… Ve boşanmanın tanımıdır  Foseptik… Kızanlar ps...', ARRAY['Türk Edebiyatı','Şiir','Koçibey Murat Gümüş']::text[], 8.5, '{"poet":"Koçibey Murat Gümüş","poet_slug":"kocibey-murat-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dort-bolu-dort-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N Eksi Bir', 'n-eksi-bir-kocibey-murat-gumus-rgsum', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve ne yaşarsan bir eksik kalıyor

n’ler dünyasında.

Hep eksiler komşu birin yanına.

Belki de n kümesi

Sandığımız kadar geniş değil..

Kimbilir.', 'Ve ne yaşarsan bir eksik kalıyor n’ler dünyasında. Hep eksiler komşu birin yanına. Belki de n kümesi Sandığımız kadar geniş değil.. Kimbilir...', ARRAY['Türk Edebiyatı','Şiir','Koçibey Murat Gümüş']::text[], 8.5, '{"poet":"Koçibey Murat Gümüş","poet_slug":"kocibey-murat-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/n-eksi-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimin Sesi...', 'sevgimin-sesi-i-brahim-ethem-bingul-g1srs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerini yum ve dinle sevgimin sesini

Selâm gönderdim sana, sabah rüzgârlarıyla

Dokunup yanağına okşasın yâr tenini

Ve sana hatırlatsın beni, arzularımla...

Unutmak mümkün değil, bal rengi gözlerini

Özlüyorum dudağının masumiyetini

Hele '' seviyorum '' derken mahcubiyetini

Bulutlar, sular ve seven şu kalbim şahitti...

Biliyorum asla unutmadın o geceyi

Ben ise unuttum adından başka her şeyi

İnan ki senin olmayan sevdalı bir çift göz

Bakmaz, bakamaz bana senin gibi, sözüm söz

www.iebingul.com', 'Gözlerini yum ve dinle sevgimin sesini Selâm gönderdim sana, sabah rüzgârlarıyla Dokunup yanağına okşasın yâr tenini Ve sana hatırlatsın ben...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgimin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim', 'o-benim-murat-tali-beuwq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'o benim

yokluğuna ses vermediğin

yalnızlığına ortak etmediğinim

o benim

ıssız kalakalan ortalıklarda

üşüyüp örtemediğin sıcaklığınla

o benim

en uzak yalnızlığın

terkedilmiş kendim

senin, en unutası 

şehirlerindeyim', 'o benim yokluğuna ses vermediğin yalnızlığına ortak etmediğinim o benim ıssız kalakalan ortalıklarda üşüyüp örtemediğin sıcaklığınla o benim...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/o-benim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rize''de Bir Otel Odası', 'rize-de-bir-otel-odasi-mustafa-saglam-8f7sf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rize''de,

İkinci sınıf bir otel odası

Bir yatak, bir masa, bir sandalye

Ve iki pencere

Yüksekten bakıyor denize

Köşede bir çekmece

Çekmecede birkaç mektup

Harflere bakılırsa Rusça

Okunaklı, akışkan bir yazı

İki de resim arasında

Bir kadın, bir erkek 

İkisinin de saçları sarı

Kağıtlar biraz solmuş

Belli ki epey olmuş yazılalı

Erkek genç, yakışıklı

Kadın ise

Sibirya gecelerinde

Jivago''nun Lara''sı

Gözlerinde şuh bir bakış

En kadınca arzular

Çağırırcasına dönüp bakanları.

Kimbilir, şu yatakta

Üç kuruş uğruna

Kaç kez aldattı sevgilisini

Aşkını kaç kez katletti

Karadeniz''in sularına baka baka

Bilmediği ülkenin tanımadığı insanlarıyla...

Belki de perdeyi çekmiştir

Görmemek için yüzünü

Şu karşı bozkırlarda

Neler oldu,  ne yaptı

Ne kadar kaldı

Bilmem döndü mü yine

Hiçbirşey olmamışçasına

Rusya topraklarına

Yoksa, unutuldu mu

Son mu buldu

O güzelim sözler

Bitmeyecek olan sevgi

Rize''de bir otel odasında', 'Rize''de, İkinci sınıf bir otel odası Bir yatak, bir masa, bir sandalye Ve iki pencere Yüksekten bakıyor denize Köşede bir çekmece Çekmecede ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sağlam']::text[], 8.5, '{"poet":"Mustafa Sağlam","poet_slug":"mustafa-saglam","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/rize-de-bir-otel-odasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemde Hala', 'ulkemde-hala-fidan-bulut-lpk77', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ver elini korkma

Ülkemde hala dağlarım var

Ovalar talandan artakalan

Hala çiçekler açabiliyor

Ağaçlar yeşil var gücüyle

Korkma artık çık ordan

Bir bulut arası nefes bulalım

Koşacak kırlarımız bitmeden

Gün batımını bir daha izleyelim

Yıldızları sayacak tepelerimiz de var

Hem de yeşili yeşil kahvesi kahve

Toprağında kokular hala taze

Bırakalım bankaları kavgasında

Kravatlı amcalar kursun geleceği

Camların arkasındaki hayatlardan sıyrılalım

Derelerin şırıltısını dinleyelim bikmadan

Bırak kavgaları onların olsun

Biz karışmadan çıkalım zırhlardan

Ayaklarımız çamur önümüz berrak olsun

Çıkar elbiselerini olduğun gibi gel

Elbiseler de onların olsun

Yaşadık saydıkları geçmiş planladıkları gelecekleri de

Biz uzanalım korkmadan ülkemize

Ver elini.........................', 'Ver elini korkma Ülkemde hala dağlarım var Ovalar talandan artakalan Hala çiçekler açabiliyor Ağaçlar yeşil var gücüyle Korkma artık çık ord...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ulkemde-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Keçisi', 'gunah-kecisi-tulay-sustam-bp9fy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güneş; 

bulutun arkasına saklanıp

mavi gökyüzünü, siyaha boyamasaydı...

ve bulut; 

güneş''in yokluğunda gözyaşı dökmeseydi...

candostum! ...

yok yere ve hiç sebepsiz

beni yüreğinin kapısına bırakmasaydı

koyun koyuna büyüdüğüm

''''karıncaları'''' ezmezdim...

affet beni bulut! ...

bütün suç güneş''in.

Ay''da ki beyaz leke benim...', 'güneş;  bulutun arkasına saklanıp mavi gökyüzünü, siyaha boyamasaydı... ve bulut;  güneş''in yokluğunda gözyaşı dökmeseydi... candostum! ... ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunah-kecisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarar Ziyan', 'zarar-ziyan-hakan-liman-qnziq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ziyan edilmiş şiirlerimiz var,

Oraya buraya yazılmış..

Eskiden yalnızlıktan yazardık

Artık parasızlıktan..

Bu kadar mı yenik düştün romantizm? 

Ey aşk

Bu kadar mı küstün bize? 

Ve ölüm,

Ne kadar yakınsın bilinmez ama

Bu kadar mı hissedilir nefesin? 

Herkesin beyaz giydiği bir gecede 

Unutturan öpücükler eksik kalmasın yanağımızdan..

Ve zaman durmasın hiçbir zaman

Saatler hep o anı göstersin

Islak ıslak bakan gözlerine şarkılar yazılası

Ve hatta yazılmış kadınlar geçsin ömrümüzden

Babanın hatırasına hürmeten

Ağlayalım bir kez daha..

Annemizi hatırlayıp bir kez daha ağlayalım

Sonra bir kez de boşa geçmiş ömrümüze ağlayalım

Oraya buraya yazılıp ziyan edilmiş şiirlere..

Sonra gülelim

En nihayetinde gülelim

Hep birlikte

Tüm sevdiklerimiz, ailemiz, dostlarımız

Sen ve ben..

Doyasıya gülelim..

O teknede, o ağustos akşamında gözümüzden yaş gelene kadar

Gülelim

İkibinaltı mı olur ikibinyedi mi

Yoksa ikibinonyedi mi bilmem

Ama o ağustos akşamı bizim olsun

Bir ömür hatırlansın..

Sonra kuşlar gelsin,

Besleyelim onları kuru simitle..

Gün batsın

Alkol su gibi aksın

Babam sarhoş olsun 

Annen kızsın bana yine, ama sevsin beni çaktırmadan..

Hayat kaldığı yerden devam etsin sonra,

Şiir tadında olmaz ki, 

Koşturmacayla

Otobüse yetişmekle, metroyu kaçırmakla,

Vapurdan uzaklara bakmakla..

İstanbul devam etsin kaldığı yerden..

Birkaç zaman daha taşısın bizim yükümüzü de..

Sonra el sallasın bize,

Kaçalım güneylere..

O çoğunun ıskaladığı ekim akşamlarını biz yaşayalım

Deli memet rüzgarı yüzümüze vursun 

Ve ta içimizde hissedelim huzuru..

Ben sigaradan körelmiş sesimle şarkı söylerim köhne bir barda

Sense boncukların yanına hayallerini dizip

Sunarsın benim geçtiğim yollardan geçen çocuklara..

Hayatın tadına varırız orada..

Nirvanaya değil belki ama

Kendi dünyamıza kavuşuruz o evde..

Sonra bir kızımız olur, neden olmasın.. 

Sana benzer..

Ay yüzlü,

Kırmızı yanaklı..

Şehir gürültüsünden uzak,

Tüm kötülüklerden, yalanlardan hariç büyür..

Neden olmasın..

Neden olmasın..

Sen şiirlerini harcama yeter ki..

Oraya buraya yazma, ziyan etme..

Çünkü biz azaldık..

Teker teker yok etmeye çalıştılar..

Başaramadılar..

Hamdık, olduk..

Birkaç kişi kaldık içinde umudu büyüten..

Ve biz ne şanslıyız ki 

Birbirimizi bulduk..

Sen şiirlerini ziyan etme çiçeğim..

Gün gelecek,

İçinde umudu büyütenler kazanacak bu savaşı..

17 Temmuz 05 

03.35', 'Ziyan edilmiş şiirlerimiz var, Oraya buraya yazılmış.. Eskiden yalnızlıktan yazardık Artık parasızlıktan.. Bu kadar mı yenik düştün romantiz...', ARRAY['Türk Edebiyatı','Şiir','Hakan Liman']::text[], 8.5, '{"poet":"Hakan Liman","poet_slug":"hakan-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/zarar-ziyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günle Gelen', 'gunle-gelen-ozgur-kokturk-mxl81', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güne düştü şimdi yürek geçti geceden 

Sarıldı umudun en beyazına 

Devrik bir şiir kurdum bir tek heceden 

Karıştı sevdam bahar rüzgârına', 'Güne düştü şimdi yürek geçti geceden  Sarıldı umudun en beyazına  Devrik bir şiir kurdum bir tek heceden  Karıştı sevdam bahar rüzgârına...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gunle-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devri Alem', 'devri-alem-yavuz-agir-k8c45', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir acayıp devri alem,

Sonunu hiç düşünmezler.

Bir garip dünyadayız,

Kötülükten hiç üşenmezler..

Yapraklar gazel oldu,

Külünü düşünmezler..

Bahara ereyim derken,

Kışını hiç düşünmezler...

Bilirim insanlar darda.

Göçer giderler bu diyardan.

Hoş bir haber gelsede yardan

Bıkar giderim bu candan.....', 'Bir acayıp devri alem, Sonunu hiç düşünmezler. Bir garip dünyadayız, Kötülükten hiç üşenmezler.. Yapraklar gazel oldu, Külünü düşünmezler.. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/devri-alem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bursa gibi sever misin beni', 'bursa-gibi-sever-misin-beni-fidan-bulut-fh9m0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baksam gözlerine görür müyüm Bursa''nın yeşilini

Saçlarında yeni sürülmüş tarlalarımın kahvesini

Şeftali ağaçlarının çiçekleri dökülür mü yanaklarına

Tophanenin dik yokuşu yorar mı seni

Gelsen ramazan topuyla oynasak

Emir sultanda af dilesek yüzümüz tutmadan

Yıldız tepede yıldızlar şahitti yitirdiklerimize

Tövbeler etsek her yatır başı

Ve yine bozsak tövbeleri yıldıztepede

Habersiz gelen yağmurunda yıkansak

Ve yine kirlensek Uludağın eteklerinde

Saklar mı dersin bizi orman denesek mi

Ve yine ovada çıksak gün gibi aşikar 

Bayram yerine alır mı beni de köyümün taze kızları

Sen çerez yollar mısın sana oynamam için

Kaçsak keles yaylasına el ele

Hatta daha da yukarı, teleferiğe kafa tutsak

Yaban domuzları kovalasa

Ve yorulunca seyretsek bursa yı alsak içimize

Pınar başı dolansa ayaklarımıza

Bir koşu tirilye de alsak soluğu şaşırsak yolu

Muzur muzur gülüşüp bakışsak

Yıldıztepenin yıldızları parlasa gözlerimizde

Ve yine Bursa yı alıp arkamıza yumup gözlerimizi

Bulsak o küçük bahçeyi utansak da uslanmadan

Sever misin beni de Bursa gibi', 'Baksam gözlerine görür müyüm Bursa''nın yeşilini Saçlarında yeni sürülmüş tarlalarımın kahvesini Şeftali ağaçlarının çiçekleri dökülür mü yan...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bursa-gibi-sever-misin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Gibi', 'bir-omur-gibi-yilmaz-korkankorkmaz-jdi2f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'niyesini 

ne olurunu 

düşünmeden

başımı dizlerine dayayıp 

en beklentisiz anında 

belki de en genç sırlarınla

bir ömür gibi

yaşamak seni

delikanlı zamanlarımızı terk etmeden

bir sevdayı yüreklenip

ellerinin sıcağına doyabilmek

orda bir yerde

suskun ve tenha düşler içinde

bir ömür gibi

yaşamak seni', 'niyesini  ne olurunu  düşünmeden başımı dizlerine dayayıp  en beklentisiz anında  belki de en genç sırlarınla bir ömür gibi yaşamak seni del...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Korkankorkmaz']::text[], 8.5, '{"poet":"Yılmaz Korkankorkmaz","poet_slug":"yilmaz-korkankorkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-omur-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahvali Dervişan', 'ahvali-dervisan-abdullah-odabas-oqqso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derviş olan aşka düşer,

Kaynayuban coşup taşar,

Ciğerciği yanar pişer,

Ah edecek dervişlerin.

Allah ile olur işi,

Durmaz akar gözü yaşı,

Belli olmaz yazı kışı,

Aşka düşen dervişlerin.

Seherlerde eder dua,

Matlupları hemen rıza,

Duaları savar gaza,

Aşka düşen dervişlerin.

Taam arzu etmez canı,

Bulacağız ihvalını,

Cennette Hak Cemalını,

Canı diler dervişlerin.

Dost cemalin eyle nasip,

Habibin dertlere tabip,

Ol servere eyle garip,

Aşkı yakar dervişlerin.

Yarab uyar bu kemteri,

Gitsin bulsun dervişleri,

Nasihat söyler dilleri,

Nerde bulam dervişleri.

Sohbetleri hoştur heman,

Aklı olan eder devam,

Lezzet almaz bundan avam,

Bulacağız dervişleri.

Avam bilmez hasdan haber,

Beyhude gezer derbeder,

Bulsa dervişi zemmeder,

Bulacağız dervişleri.

Yarab avam etme beni,

Ne hoş olur havas hali,

Göster bana doğru yolu,

Nerde bulam dervişleri.

Vecdi hallar baştan döner,

Aşka düşmüş ciğer yanar,

Ağaçtan atlara biner,

Gönlü alçak dervişlerin.

Abdinem ismim Abdullah,

Affına muhtacım billah,

Zikri fikrim hemen Allah,

Döner dili dervişlerin.

Meftuni mahfet varını,

Sil gönülden ağyarını,

Koy elden kibri,kinini,

Sever isen dervişleri.', 'Derviş olan aşka düşer, Kaynayuban coşup taşar, Ciğerciği yanar pişer, Ah edecek dervişlerin. Allah ile olur işi, Durmaz akar gözü yaşı, Bel...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ahvali-dervisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın', 'adin-yilmaz-korkankorkmaz-ric26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bütün suyunu 

çekmişse bir ömür

tükenecek bir gecesi bile

kalmamıştır zamanın

ve karlı bir kışta

muştusuz bir yalandır adın', 'bütün suyunu  çekmişse bir ömür tükenecek bir gecesi bile kalmamıştır zamanın ve karlı bir kışta muştusuz bir yalandır adın...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Korkankorkmaz']::text[], 8.5, '{"poet":"Yılmaz Korkankorkmaz","poet_slug":"yilmaz-korkankorkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Aşkı', 'allah-aski-abdullah-odabas-8967n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah diyelim gardaşlar,

Akıtalım gözden yaşlar,

Dağlar taşlar ve ağaçlar,

Allah diyelim biz,Allah.

Allah diyelim Aşk ile,

İkrar gerek cümle kula,

Mükafatın didar ola,

Allah diyelim biz,Allah.

Allah diyelim her vakit,

Gözden kanlı yaş akıt,

Namaz içinde beş vakit,

Allah diyelim biz,Allah.

Seher vaktinde her zaman,

Kalbinde var ise iman,

Fazilet vaktidir uyan,

Allah diyelim biz,Allah.

Mümin olan asla yatmaz,

Şeytan kemendini atmaz,

Münafık işini tutmaz,

Allah diyelim biz,Allah.

Münafıktan seçilelim,

Reyhan gibi açılalım,

Bülbül gibi ötüşelim,

Allah diyelim biz,Allah.

Allah desin dilimiz,

Od görmesin elimiz,

Sıratta asan yolumuz,

Allah diyelim biz,Allah.

Meftuni derdine ağlar,

Her seher ciğerin dağlar,

Sular gibi hemen çağlar,

Allah diyelim biz,Allah.', 'Allah diyelim gardaşlar, Akıtalım gözden yaşlar, Dağlar taşlar ve ağaçlar, Allah diyelim biz,Allah. Allah diyelim Aşk ile, İkrar gerek cümle...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/allah-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitsin', 'gitsin-huseyin-sigirtmac-4sk87', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağıtmak istersen barut gibiyiz.

Bir kıvılcım yolla, ateş ver gitsin.

Tarihten süzülen neslin dibiyiz.

Gücün yetiyorsa yere ser gitsin.

Gücün yetmiyorsa bizi bize vur.

Parçalayıp yönet, plan, düzen kur.

Motif motif işle, kültürünle dur.

Tohumun yeşersin topla,der gitsin.

Din ve ırk diyerek gel böl insanı.

Nifak yarat ayır dili, lisanı.

Ceddime oku da, gel gör isyanı.

Kurtulsun bu vatan, sağır, kör gitsin.

Sığırtmaç ibrettir alana sözün.

Tarihi hatırla açılsın gözün.

Atamız dirilir, vermez ya izin! 

Esaretse yaşam, bizi vur gitsin.', 'Dağıtmak istersen barut gibiyiz. Bir kıvılcım yolla, ateş ver gitsin. Tarihten süzülen neslin dibiyiz. Gücün yetiyorsa yere ser gitsin. Gücü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz ile', 'soz-ile-i-brahim-kilinc-bk153', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinleyin destanı tüm sevdalılar

Bu; aşka, sevdaya yeni tanımdır

Can cana eziyet etmez sanmayın

Canıma kasteden benim canımdır

Elbette hükmeder, sultan değil mi

Elbette zulmeder, canan değil mi

Gönül sarayında tek han değil mi

Ah ile inleten benim canımdır

Sevgi, sevgiliyi mutlu görmektir

İçi kan ağlarken ona gülmektir

Beklemeden birşey, çok şey vermektir

Canım adadığım benim canımdır

Sevgililer cilve ile naz ile

Âşıklara zulmederler söz ile

Sükût edip, ara sıra  göz ile

Bana da zulmeden benim canımdır', 'Dinleyin destanı tüm sevdalılar Bu; aşka, sevdaya yeni tanımdır Can cana eziyet etmez sanmayın Canıma kasteden benim canımdır Elbette hükmed...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soz-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzlık Bitmemeli Aşk Bitmemeli', 'sonsuzlik-bitmemeli-ask-bitmemeli-ertugrul-sakar-dnk4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz gökyüzünü buluyordu bir mavide

Hem birlikte hemde ayrıydı sanki

Yağmur bulutlarından  bir şemsiyeyi

Yüreğinde emzirmek  için tutuyordu

Her an ona bakınca duruyordu

Sonsuzluğun merdiveninde bir basamak

Dalgalar iç gözleriyle sorguluyordu

Sıcak atmosferlerin kanaması bir yasak

Ne kadar uzak yakınında durmak bile

Ne kadar düz bir çizgi oluşum

Duyguların sarhoşları  koşar sahile

Seni yorgan gibi örtmek kahroluşum

Deniz gökyüzünü bırakır bir çizgide

Kopmayan ayrılıkları giyinir usulca

Gece yıldızların buluştuğu bir sergide

Bir hasta titreyerek kan kusar alca

Ressam kırma paletini, şair bitirme sözünü

Sonsuzluk bitmemeli, aşk bitmemeli', 'Deniz gökyüzünü buluyordu bir mavide Hem birlikte hemde ayrıydı sanki Yağmur bulutlarından  bir şemsiyeyi Yüreğinde emzirmek  için tutuyordu...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sonsuzlik-bitmemeli-ask-bitmemeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olursa olsun sabret', 'ne-olursa-olsun-sabret-mikdat-bal-z26v4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmiyorsan sev diyen yok

Zorla sana öv diyen yok

Hele hele söv diyen yok

Sus ta adam sanılasın

Bari iyi anılasın

Karışırsın bir yetkin yok

Bir yere hiç bir katkın yok

Konuşursun bir etkin yok

Sus ta adam sanılasın

İyi diye kanılasın

Kendini sorumlu görme

Hop diye her lafa girme

Sorulmadan cevap verme

Sus ta adam sanılasın

Bari iyi anılasın

Ne olursa olsun sabret

Ne çok alçal, ne de kibret

Olma insanlara ipret

Sus ta adam sanılasın

Bari iyi anılasın

Bal der seni tanıyorum

Seni iyi sanıyorum

Yok sa ki aldanıyorum

Sus ta adam sanılasın

Ya böyle inanılasın', 'Sevmiyorsan sev diyen yok Zorla sana öv diyen yok Hele hele söv diyen yok Sus ta adam sanılasın Bari iyi anılasın Karışırsın bir yetkin yok ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-olursa-olsun-sabret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimle Söyleşim -1- / Bir Garip Yolcu', 'kendimle-soylesim-1-bir-garip-yolcu-serap-demirturk-un1rt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Senin için, sana dair,senden gelen bende kalan nice duyguları yazmak isterdim ama, ama kırıldı kalemim.''dedi.''Deli gönül  bilseydi keşke nasıl ve nice olduğunu, neler vermezdim.''dedi. Dedi de boğazına koca bir yumruk düğümlendi. Yitip gitmişti işte, hiç dinlemeden, konuşmasına fırsat vermeden...''Yüce dağlara sorsam, der mi ki bana bu nedensiz yok oluşunu? '' derken; ''Yok, sen yok olma da tek ayrı ol benden.''dedi içinden.

 ''Garibin ölüsünü üç günde duyarlarmış, ya benim garip gönlümün acısı? Sağır mı oldu gönlün ey sevilen? Yazık ettin.'' dedi ve ağır adımlarla yol aldı karlı dağlara doğru. ''Kim demiş ki sevenler unutmaz? Bak, unutulanlarda asılı kaldım...'' türküsü dilinde, bir türlü akıtamadığı gözyaşları içinde ağır aksak ilerledi...', '''Senin için, sana dair,senden gelen bende kalan nice duyguları yazmak isterdim ama, ama kırıldı kalemim.''dedi.''Deli gönül  bilseydi keşke na...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kendimle-soylesim-1-bir-garip-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmez Döngü', 'bitmez-dongu-ali-i-nal-rhkx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bitmeyen bir döngü aslında

nicelerinin aynen geçtiği

birbirine benzeyen yollarda

her güzel yeni bir rüya

her ayrılıkta ise

çekilen aynı eza

sonra döner herşey başa

zor olan anlamak belkide

görmek tektarlanan gerçeği

kiminle, nerede ne zaman farketmez 

yok bir farkı birbirinden

yaşanılan aynı cefa

ikmale kalmışız belliki

ders çıkartmanın 

ve kendini bilmenin

zorlu sınavında.', 'bitmeyen bir döngü aslında nicelerinin aynen geçtiği birbirine benzeyen yollarda her güzel yeni bir rüya her ayrılıkta ise çekilen aynı eza ...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bitmez-dongu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Legal Aşklar İntihardadır', 'legal-asklar-i-ntihardadir-bayram-celikel-r3r9v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur sonrası toprak kokusuna hasrettik biz

Birde illegal''de olsa buluşmamızı düşlerdik

Gecenin bi vaktinde

Bütün legal Aşklar intihar''dadır 

Bizim doğduğumuz kentte

Nefesimi nefesimde hissettiğimde başlardı özlemin

Kurak çöllerde su özlemi olurdu hep dudaklarımda

Çığlık yankıları olurdun sesimde 

Sana seslenişlerimde kaybolurdu sesim

Adımlarımın atıldığı tüm yollarda

Sırat köprüleri kurulurdu

Uçurumdan aşağıya düşüyor

Milyon kez ölüyordum

Sana yakına gelemiyordum birtürlü

Oysa bir adım atabilsem 

Fırat dicelesine kavuşacak

Yıkılacaktı nemrutlar 

Sevmenin yasaklandığı kentteydik biz.

Kendini ihbar et desem 

Serseri kurşunlara gebeydi beynim

Nezor Sevmiştik

Bukadar ucuzamı gitsin Sevdamız

Kaç mavi gecede hayaller kurardım

Ay ve Yıldızlar şahit

Seni bana yasak eden bu kenti

Sırtlayıp uçurumdan aşağıya atmak istedim

Tek başıma Biçare Kalır 

Yorgun düşerdim Akşamlar misali

Bıraksam hüznümüde sevdam gibi

İllegal çarpar yüreğim

Legal Aşklar intihardadır 

Bizim doğduğumuz kentte

Özgürlük Gravatlıların bile elinde değildi

Rüzgarın gökyüzüne sığmadığı zamanlar olurdu

Yüreğimiz umutlara gebeydi hep

Bu nasıl yürektiki! ! ! 

seni düşündükçe tüketmek tüm ütopyaları

Sana kavuşmak demek bu kentte

Sattülarab çöl olması gibi

Legal aşklar intihardadır

bizim doğduğumuz kentte

Öyleyse ihbar et kendini desem

Koca kente sığdıramadıkları yüreğime 

söz geçirmez olurum

Ölüm Nasıl bişi birbilsem

Ya Ölüncede Özlersem', 'Yağmur sonrası toprak kokusuna hasrettik biz Birde illegal''de olsa buluşmamızı düşlerdik Gecenin bi vaktinde Bütün legal Aşklar intihar''dadı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Çelikel']::text[], 8.5, '{"poet":"Bayram Çelikel","poet_slug":"bayram-celikel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/legal-asklar-intihardadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasa Meylin', 'olmasa-meylin-ali-i-nal-huzgy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'olmasa da meylin benden yana

gönül akmış bir kez sana

bakmasada gözlerin 

baktığım gibi sana 

neyleyim tutuşmuş bir kere

sevdanın ateşi 

sönmez bir daha

çekmek kahrını bir sefa

sanma sakın incedir

boynum senden başkasına

bir ah dahi etmeden

her ne gelirse gelsin başa

yanında olmak dahi

sanki bitmeyen bir rüya

beklenilen umutsuzca

belkide sendin yıllarca

başlamadan söndürsen dahi

ateşini sevdanın başta

bir kez gördü gözler

artık silinmez hüyası 

közü kalır yıllar boyunca', 'olmasa da meylin benden yana gönül akmış bir kez sana bakmasada gözlerin  baktığım gibi sana  neyleyim tutuşmuş bir kere sevdanın ateşi  sön...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olmasa-meylin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Aşkına', 'allah-askina-abdullah-odabas-qwri2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey gönül eyle feragat,olsun Allah aşkına,

Verme viraneye gönül,olsun Allah aşkına.

Fitnedir o aldatır,bakma anın sözüne,

Türlü cilve naz ile hem,sürme çekmiş gözüne.

Evliyalar embiyalar,bakmaz oldu yüzüne,

Aç kulağın dinle beni,olsun Allah aşkına.

Akil isen fırsatı,fevt etme bir saniye,

Fahri alem geldi geçti,bakmadı bu faniye,

Çok hükümdar hüküm kıldı,Davutoğlu haniya,

Aç kulağın dinle beni,olsun Allah aşkına.

Masivadan çek elini,kulluk eyle Halika,

Rızık verir derya içre,dilsiz olan balığa,

Şakir ol hem şükreyle,gün bu günkü haline,

Aç kulağın dinle beni,olsun Allah aşkına.

Emrü nehyi eyle eda,çok fikir et ölümü,

Ya ilahi son nefeste,sen la’l etme dilimi,

Tariki müstakim üzre,sabir eyle yolumu,

Aç kulağın dinle beni,olsun Allah aşkına.

Sen uyandır cümlemizi,ya gani perverdigâr,

Verme fırsat nefs-ü şeytan,etmesin bizi şikâr,

Vechinle kılıp müşerref,adın içre ver karar,

Aç kulağın dinle beni,olsun Allah aşkına.

Ey Meftuni ağla durma,hicretine ol hazır,

Yerde gökte birdir Allah,hem hüda hazır nazır,

Bu dünyada nevt şarabın,içecek vezir kizir,

Aç kulağın dinle beni,olsun Allah aşkına.', 'Ey gönül eyle feragat,olsun Allah aşkına, Verme viraneye gönül,olsun Allah aşkına. Fitnedir o aldatır,bakma anın sözüne, Türlü cilve naz ile...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/allah-askina-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ariften Bir Nişan', 'ariften-bir-nisan-abdullah-odabas-i3ybm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arif belli sözünden,

Kan yaş akar gözünden,

Gider Kur’an izinden,

Kurban canım arifan.

Arif halkta görülür,

Eski hırka bürünür,

Kalbi,pası silinir,

Kurban canım arifan.

Arz’a Sema vat’a bak,

Direksiz kurmuştur Hak,

Dahi yedişer tabak,

Kurban canım arifan.

Her ne halk etti ahad,

Böcük,cücük,haşerat,

Hakkı ederler isbat,

Kurban canım arifan.

Arif asla gam yemez,

Tan uykusu uyumaz,

Namaz kazaya koymaz,

Kurban canım arifan.

Arifle eyle kelam,

Gardaş bizden et selam,

Nasip eylesin Hüdam,

Kurban canım arifan.

Meftuni sen derde yan,

Ara bul derde derman,

Hüda’nın emri Kur’an,

Kurban canım arifan.', 'Arif belli sözünden, Kan yaş akar gözünden, Gider Kur’an izinden, Kurban canım arifan. Arif halkta görülür, Eski hırka bürünür, Kalbi,pası s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ariften-bir-nisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Okları Yasta', 'umudun-oklari-yasta-necmi-unsal-z5bcw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağırladığımız bu konuk geceler sabaha kavuşur.

Karanlıklar alır yükünü, bilinmez bir yere savuşur.

Sevgiler, hüzünler;  derin imge damlar sessizce sehere.

Kırılmak, alınmak bırakır sevinci kuytu, loş bir yere.

Dünya kalabalık, yürümekteyiz bir tenha patikada.

Ne duygular akar kör zamana, geçen her bir dakikada.

Kaybettik yıldızın sihrini, baharın yeşil barışını.

Kuş cıvıltıları süslerdi seherin berrak yarışını.

Gönül deryasına siyahlar döküldü, yaz yağmuru eksik.

Hayat mutat işler bezginliğinde ve yorgun; akım kesik.

Nisan yağmurunun ardından hayata gamla bakar hasta.

Sevgiler hasretle gerili, umudun okları da yasta.

27 Mayıs 2004 Perşembe, Danimarka-Køge  18.34

6+6+6', 'Ağırladığımız bu konuk geceler sabaha kavuşur. Karanlıklar alır yükünü, bilinmez bir yere savuşur. Sevgiler, hüzünler;  derin imge damlar se...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umudun-oklari-yasta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yok oldun', 'sen-yok-oldun-melek-bagac-g1oj0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yok oldun

Sen

Zoru sevdin

Inat ettin

Basardin

Ben

Seni sevdim

Senden hoslandim

Seni özel yaptim

Sen

Incittin

Kirdin

Üzdün

Ben

Sana alistim

Sana deger verdim

Seni birakamadim

Aslinda

Sen ben oldukca

Ben sen oldum

Ben sen oldukca

Sen yok oldun



18.07.05

15:34', 'Sen yok oldun Sen Zoru sevdin Inat ettin Basardin Ben Seni sevdim Senden hoslandim Seni özel yaptim Sen Incittin Kirdin Üzdün Ben Sana alist...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-yok-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahı Beklerken', 'sabahi-beklerken-i-lyas-ozkan-8s3xl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişti herşey gülüm

Zaman başkalaştı.

Yahut, başkalaşanlar

Onu başkalaştı sandı.

Uykularım bile değişik; 

Misafirim olmaz göz kapaklarıma.

Şimdilerde bekleyip dururum,

Gelse de zerresi uykunun...

Heyhat! Değişti herşey gülüm...

Unutmam sandıklarım

Silindi zihnimden bir bir

İsmini bile bilmem şimdi çoğunun...

Ve unutmam diyenler,

Arayıp sormaz oldu! 

Deli-dolu gençlik çağım,

Geçip gitti.. yelkenler,

Suya indi gülüm! 

Sevdanın en hasını,

Ben yaşadım sanırdım..

Sevdam, Mecnûn’unkinden

Daha öteydi gülüm! 

Ne Ferhat’ın, ne Kerem’in

Esâmesi okunmazdı ben varken...

Çöllerde dolaşan Mecnûn’a inat

Sevgilinin gönül ülkesinde

Sürgün yaşadım...

Gül rengi şafaklarda

Sevgiliye en güzel şiiri

Ben yazmalıydım...

Çerağlar gibi yanıp

Aşkın ateşiyle,

Nasıl yanmak gerek

Göstermeliydim...

Ve görmeliydi herkes; 

Mum misâli nasılmış erimek...

Girdabı sonsuz bir gülün

Kıvrımlarında kayboldum.

Gülüm, değişti herşey, başkalaştı! 

Zaman çarkları

Hızlıca dönüp durmakta...

Günler, aylar, yıllar

Akrep-yelkovan kıskacında.

Hasret düştü payıma; 

A gülüm, akıp giderken zaman! 

Hicran azığım oldu.

Aha böğrümün ta şurasında

Bir ok saplandı

Bin azaplı.

Titrek kanadıyla, bir bilsen

Bin ızdıraplı...

Sabahı beklerken şimdilerde,

Ey, karanlık gecemin

Aydınlık mehtabı! 

Yeter, hasret kâsesinden

Hüzün yudumladığım! 

Gurbetin çileli yollarında

Yaralı ceylan olduğum yeter! 

Kaç mevsimdir,

Beklerken baharı-yazı

Ve dilimde gönlün,

Gülzâra dönme niyâzı; 

Bitsin gayrı

Ne hüzün, ne hasret,

Tahammülüm kalmadı

Hepsi ruha eziyet! 

Mevsimler, kıştı şimdiye dek

Ve kışlar, zemheri.

Altın kâsede sunuldu; 

Öyle tattırdılar

Kıvrandıran zehri...! 

Uykusuz gözlerimle

Sabahı beklerken gülüm; 

Uzat ellerini, tutuver elimden.

Bana sen gereksin

Başkaları anlamaz hâlimden! 

Gel, tutuver elimden

Dudağımdaki vâveyla dinsin! 

Gökkuşağının tüm renkleri,

Derin bakışlarında

Gönlüme dolsun; 

Mevsim bahar,

Gözüm aydın olsun...! 

Şimdilerde gülüm,

Sabahı beklerken; 

Bekletme fazla, çıkıp gel

Şafak sökerken...! 

(19.05.2005

Perşembe)', 'Değişti herşey gülüm Zaman başkalaştı. Yahut, başkalaşanlar Onu başkalaştı sandı. Uykularım bile değişik;  Misafirim olmaz göz kapaklarıma. ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/sabahi-beklerken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehid''e Mektup', 'sehid-e-mektup-saim-bastik-lvy3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani bir yemin etmiştik; 

Allah''a,Kur''ana,Bayrağa,

Vatana ve Silaha yemin olsun! 

Şehitlerim,Gazilerim emin olsun...

Kavlimize sadığız şehidim rahat uyu! 

Kara bir eylül gecesi kervanımız basıldı

Darağaçları kuruldu ardından kahpelerce! 

Ve yeni şehitler gönderdik vatan için uçmağa

İmamoğlu''na,Önkuzu''ya ve diğerlerine yoldaş.

Pehlivanoğlu,Duracık ve Esendağ

Son yolculuklarına giderken

Hepsininde dudaklarından aynı söz dökülüyordu

Vatanı kurtardık diyen vatansızlara inat; 

VATAN SAĞOLSUN! ! ! 

Ya kalanlar,

Kalanlar da zindanları mesken tuttu çaresiz.

Ve bir soysuzun talimatıyla işkenceden geçirildik firesiz.

Ama yılmadık,yıkılmadık.

Kırıldık,kırıldık ama eğilmedik hiçbir zaman

Yüreğimiz kanasa da oluk oluk

Gelecek nesillere sakladık hıncımızı,öfkemizi.

Ve içimize akıttık gözyaşlarımızı

Kahpeler göremediler ağladığımızı.

O kızarmayan yüzlerine haykırdık öfkeyle; 

BİZ BİR ÖLÜR BİN DİRİLİRİZ 

Şimdi yeşerdi kırılan filizler yeniden,

Doğrulduk kalktık düştüğümüz yerden

Genç kızlarımız ana,yiğitlerimiz baba oldular,

Boy verdiler, soy verdiler kutlu sevdamıza.

Ve şimdi yine haykırıyoruz

Ana,baba,çoluk çoçuk heb bir ağızdan; 

YASTIĞIMIZ MEZAR TAŞI

YORGANIMIZ  KAR OLSUN.

BİZ BU YOLDAN DÖNER İSEK

NAMUS BİZE AR OLSUN! ! ! 

Arzederim...                    

03/05/1999', 'Hani bir yemin etmiştik;  Allah''a,Kur''ana,Bayrağa, Vatana ve Silaha yemin olsun!  Şehitlerim,Gazilerim emin olsun... Kavlimize sadığız şehid...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sehid-e-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Sürgünü', 'hasret-surgunu-i-lyas-ozkan-sp3hl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok erken yaşta düştü şu gurbet ele yolum

Gariplik.. iliklerime dek hissediyorum

Bilmezdim hasret nedir; gör ki derinden tattım

Her ağan günle hicranıma, bin hicran kattım

Ocaklar gibi yandım, eridim mum misâli

Ufka mıhlandı bakışım, beklerken visâli

Hani nerde âh, çocukluğumun şen günleri

Ne kadar sürer bilmem, şu hasret sürgünleri

Daha ne kadar aksın, yanağımdan gözyaşım

Dert ve ızdırapla ne kadar zonklasın başım

Elbet geçer Safrani, hüzünden eser kalmaz

Birgün biter acı ve ızdırap; keder kalmaz...

(02.05.2005

Salı)', 'Çok erken yaşta düştü şu gurbet ele yolum Gariplik.. iliklerime dek hissediyorum Bilmezdim hasret nedir; gör ki derinden tattım Her ağan gün...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hasret-surgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-i-lyas-ozkan-3zihu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine yalnız yürürüm kaldırımlarda,

Bir tek ayak sesim duyulur art arda.

Ne bu, ses sadâ yok.. hayalet şehirde miyim? 

Nerdesiniz ey? ! Kimse sesim duymaz mı? 

Yandım hayli zamandır, çektiğim az mı? 

(23.02.2005

Çarşamba)', 'Yine yalnız yürürüm kaldırımlarda, Bir tek ayak sesim duyulur art arda. Ne bu, ses sadâ yok.. hayalet şehirde miyim?  Nerdesiniz ey? ! Kimse...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizligim-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Beytullah', 'ask-i-beytullah-abdullah-odabas-e1p5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklerim ben dost kapısın,

Muradım Hak’tan isterem.

Kovsa dahi girmem ondan,

Muradım Hak’tan isterem

Halkeyledi bizi yoktan,

Aslımız haki topraktan,

Tasdik ettik anı çoktan,

Muradım Hak’tan isterem

Kalu bela dedik bizler,

Senet oldu iş bu sözler,

Ahdi misak hacer gözler,

Muradım Hak’tan isterem

İlahi bozdurma misag,

Şeytan eder bizi tutsak,

Şerrinden kıl bizi ırak,

Muradım Hak’tan isterem

Ol mübarek evset taşı,

Yoluna koymuşam başı,

Yüzüm sürüp döksem yaşı,

Muradım Hak’tan isterem

Tavaf kılam Beyt-i Azam,

O yolda mahvolsun sinem,

Pervaneveş hemen dönem,

Muradım Hak’tan isterem

Ab-ı Zemzem içir Yarab,

Merve,Safa kaçır Yarab,

Arafata göçür Yarab,

Muradım Hak’tan isterem

Arafat’ta vakfe duram,

Her derdime derman bulam,

Dertli,aciz,mücrim kulam,

Muradım Hak’tan isterem

Şeytanlara taşlar atam,

Kurbanlara kurban katam,

Kumlara sarılam yatam,

Muradım Hak’tan isterem

Kurban olam ravzasına,

Tazelendi derdim yine,

Yarab eriştir o güne,

Muradım Hak’tan isterem

Ravzasından güller kokar,

Dokunan canları yakar,

Ne mutlu göz ona bakar,

Muradım Hak’tan isterem

Çar-i yari ashapları,

Biz severiz hep onları,

Göster bize o canları,

Muradım Hak’tan isterem

Meftuni açmış elini,

Arzeder gonca gülünü,

Dönder hicaza yolunu,

Muradım Hak’tan isterem', 'Beklerim ben dost kapısın, Muradım Hak’tan isterem. Kovsa dahi girmem ondan, Muradım Hak’tan isterem Halkeyledi bizi yoktan, Aslımız haki to...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ask-i-beytullah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Bir Sevda', 'i-nce-bir-sevda-ali-i-nal-sxe6k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dokunmaya bile çekinmek

kırılır diye belki

o narin, ince belini

sarmak nasip olsa belki

akan nehrin taradığı

saçlarında güneşin kokusu

düşen her bir kelime

dudaklarından ince ince

kabartır yüreğimi 

her duyduğumda sesini

bakarken korkmak belkide

gözerinin derinliklerine

içimden geçen her dalga

bir kez daha yakar

her bir bakışında bana

nafile olsa dahi 

sermek bütün hayalleri

bir umut açılan kalbimin

dağılıp gitsede yerlere

vuslat sana varmak değil

aşkına varmak bütün dileğim', 'dokunmaya bile çekinmek kırılır diye belki o narin, ince belini sarmak nasip olsa belki akan nehrin taradığı saçlarında güneşin kokusu düşen...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ince-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yanık Kokar', 'sevda-yanik-kokar-arzu-gulucudur-oabt8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevişmeler gözlerde...

Tenden öte.... gönüllerde...

Aldatışlar uzak...

Dilden, sözden geçmekte

Kervanlara katılmış sevdalı sözler

Kervancılar bir bir ölmekte...

Yükü ağır sevdanın

Kalbi yakar

Ateşi har

Sinesi buruk

Gölge gölge düşmüş yüreklere

Dağ dağ kabarmış

Yıldırımlar düşercesine alevli

Kor kor yanık kokar

Sevda yanığı derler kimi zaman

Yada sevdasına yanmış gönüllere uzanır

Diyar diyar destanlar yazdırır

Kimini dağ dağ gezdirir

Kimi çöl olur yangısı için

Sevda yanık kokar

Ağırdır yükü

Kalbi yakar

Ateşi har

Sinesi buruk...', 'Sevişmeler gözlerde... Tenden öte.... gönüllerde... Aldatışlar uzak... Dilden, sözden geçmekte Kervanlara katılmış sevdalı sözler Kervancıla...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevda-yanik-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılası talan...', 'yikilasi-talan-zafer-zengin-etnika-vmsq4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıkılası talan

olmasan

kalınacak cennetle

cehennem arasında

ara yer

ara geçit

bekleme salonu

çizimler ve eskizler denenir

kibar olsun diye

adına tasarım denir

belki özeldir.

tasarlamak fitne fesat

kadın ve adama bakıp

renk vermek boyutlamak

derin yer şu içimiz boğulmasak

çırpma çizgisi; 

İkisi kalır bir baştan 

Bir sondan

Bağlılar kopmaktan



öyle  geldi ki; 

kaçmak gereksiz

utangaçlıkla

seyri gül cefalar

acıları azaltırlar

unutulmuş göğsünde dünya

ne varsa onda var

çiçek bahçelerinde

börtü böcek işine bakar

öz suyu yürüdü ellerimde

sıçratmadım tek damla

ayrılığa bir mektup

bir bitiş

bir sus

-memenden ver, uyuyayım-

batar gün

yeniden  doğar

kokun akla zarar

tadı bal zulüm

hayat varsa

ölümde var

çekilmezdi

ortasına sevda koymasalar

ne sanırsın aramayı

her seferinden

dönmez gemiler

gittikleri yerden

-derler ki ala bora-

bitmedi büyüme

erkenden gelen

dinlenirsin dibe çöken

kapla kendini tuz sızlanma

alışır bir yerde

alışır tuza yara

sabah serinliği

alışırsa yara tuza



onu düşün

sırf onu

utanç ve yalan

insana ait olan

öpüşür güvercinler

yok işte

ne utanç ne yalan

insanda var

yıkılası talan

dol

an

us

an

23 Şubat ’05  ''  Evvel aşk vardı ''', 'Yıkılası talan olmasan kalınacak cennetle cehennem arasında ara yer ara geçit bekleme salonu çizimler ve eskizler denenir kibar olsun diye a...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/yikilasi-talan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce sana...', 'once-sana-zafer-zengin-etnika-hpy5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

önce

sana

sonra

yine

sana

I.

yüreğimin iklimi

değişen elbisem

gelip tut yakamdan

yağmaya zorla

bahar ertesi

incitirsem 

yüzümün ıslağına

karışma

Kendimedir ceza

II.

gece ortası

yangınlara bağla

bir kere ölmekte

dokunmaz yalnızlığa

kalmakta var

az yalnız

çok yalnızların

ortasında

keşke varız olsa

III.

o gülüşün

çocuk yüzlerin narince

ince parmak sevimlice

dokunsa hayat kopar iç’imde

az gördüm

kadınlarla adamların 

üstünde

kimi masum

kimi ipini koparmış

at  sürüsünde

batmak lazım

bulaşmak sevdaya

sızımı öp dudağınla

yarım bırakma

IV.

kaçmak 

soluklanıp soğumak

soğumak

acı çekmemek belki

sırtımdaki ter

gömleğim şimdi

V.

özlemeyi öğrettin yüreğime

özledim sessizce

özlemeyle de olmuyor

gidenler dönmeyince

bir şey söyle

VI.

gece gel ansızın

sadece gece

yüreğimin üstüne

üremeler

okumalar

bırakıyorum

ellerine ellerimle

sessizce

özleminle

dönüyorum

kendime

bili

yo

rum

de



ve

gülümse

.

07 04 2005', '. önce sana sonra yine sana I. yüreğimin iklimi değişen elbisem gelip tut yakamdan yağmaya zorla bahar ertesi incitirsem  yüzümün ıslağına k...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/once-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Beni Yolcu Et', 'hadi-beni-yolcu-et-banu-aka-x4xmf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem ki

Kaç defa daha

Duyacağım

Senin dudaklarından 

Dökülmüş bile olsa

Duymak istemediğim

''Hadi beni yolcu et''

Kelimelerini

Belki

Biraz da olsa

Serinlerdi yüreğim

Seni yolcu ettikten sonra

Seni beklediğim yere

Dönecek olsaydın', 'Bilmem ki Kaç defa daha Duyacağım Senin dudaklarından  Dökülmüş bile olsa Duymak istemediğim ''Hadi beni yolcu et'' Kelimelerini Belki Biraz d...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hadi-beni-yolcu-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın...', 'sakin-suleyman-saylan-5a7c5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SAKIN...

Sevmek güzelim o kadar kolay değildir; 

sevmek saygı ister, uyum ister,

özveriyle sulanır,

bağlılık ister,

güven ister...

Başına buyruk uyumsuzsan,

özgürlüklerin dorukta,

hep senin bildiklerin doğruysa,

dediğin dedik çaldığın düdükse,

sonunda

kuşkular saracaksa ömrünü

sevme sakın sen...

Sevmek güzelim o kadar kolay değildir; 

sevenin gözü kör,

kulağı sağırdır gerektiğinde,

gerektiğinde

zehir de içersin sevdiğinin elinden,

eğer seviyorsan! 

Sevdiğin için yaşamaktır sevmek,

birlikte yaşarsın

becerebilirsen.

“Rabbena, hep bana” diyorsan eğer,

rahatsız ediyorsa seni atın üstündeki semer

sakın,

sakın ola

sevmeyi deneme; 

hem sana yazık olur,

hem de sevdiğine...

        Süleyman SAYLAN

        Ankara-İzmir yataklı treni,  13.11.2000 saat: 23.50', 'SAKIN... Sevmek güzelim o kadar kolay değildir;  sevmek saygı ister, uyum ister, özveriyle sulanır, bağlılık ister, güven ister... Başına bu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sakin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hâle Geldik', 'ne-h-le-geldik-nihat-malkoc-6yxzm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizi bize değil,tarihe sorun

Bugünkü ahvali siz hayra yorun

Ayrı telden çalar dedeyle torun

Ferhat’ın şahsında dağları deldik

Özünden ayrılıp ne hâle geldik

Körelmiş vicdanlar yazık bu çağa

Her gün otururlar başka kucağa

Yürek köz köz,ateş düştü ocağa

Şarka âb-ı hayat,garba eceldik

Kıblemiz değişti,ne hâle geldik

Ecnebi harsını Türk’e pazarlar

Ecdadıma kanlı ferman yazarlar

Satılık beyinler her gün azarlar

Düşmana kasırga,dostlara yeldik

Savurdu kara yel,ne hâle geldik

Yaralı sinemi yakar acılar

Hürriyete hasret kızlar,bacılar

Kanımızı emer,vampir öcüler

Eski hâlimizle daha güzeldik

Ecdada küsünce ne hâle geldik

Ne zaman tükenir bu zulüm,talan

Sünepe hissiyat ruhumu çalan

Üç buçuk soysuzun azığı yalan

Ferhat için dağdık,Mecnun’a çöldük

Vicdanlar cüzdanda,ne hâle geldik

Her mecliste gıybet dolanır dile

Garibin azığı,ekmeği çile

Zakkum boy atınca kıyarlar güle

Gönül bahçesinde açmamış güldük

Çorak topraklarda ne hâle geldik

İyi fiyat bulsa vatanı satar

Mâziden kaçtıkça çamura batar

Metresine kızıp eşine çatar

Yüce dağ başında aşılmaz beldik

Soluklar kesildi,ne hâle geldik

Her millete adam gibi baş gerek

Zalimin gözüne kanlı yaş gerek

Bunca sıkıntıya bağır taş gerek

Önüne geleni süpüren seldik

Tılsım çözülünce ne hâle geldik

18 Temmuz 2005/TRABZON', 'Bizi bize değil,tarihe sorun Bugünkü ahvali siz hayra yorun Ayrı telden çalar dedeyle torun Ferhat’ın şahsında dağları deldik Özünden ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ne-hale-geldik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Handen.. Başa Belaymış..', 'her-handen-basa-belaymis-nusret-akbayir-9cgb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey sesi billur, kendi nazenin sevdam,

Ben seni göz yaşı dökmek için mi sevdim..

Ey benim yaşama gücüm, gönül ziyam,

Ben seni bu ayrılık olsun diye mi.. sevdim..

Ey asude gönlümdeki en son isyanım,

Sevmen ayrılık demekmiş.. farkedemedim..

Ey yüreğime ısrarla yazılmış fermanım,

Her tebessümün rüyaymış ben çözemedim..

Ey yalancı yarim, beyhude.. figanım,

Her rikkatin, bir riyaymış.. ben göremedim..

Ey melanet-i vuslatım, son hezeyanım,

Her handen başa belaymış ben bilemedim..

..

17/07/2005/.n.a../

İzmir./..**/', 'Ey sesi billur, kendi nazenin sevdam, Ben seni göz yaşı dökmek için mi sevdim.. Ey benim yaşama gücüm, gönül ziyam, Ben seni bu ayrılık olsu...', ARRAY['Türk Edebiyatı','Şiir','Nusret Akbayır']::text[], 8.5, '{"poet":"Nusret Akbayır","poet_slug":"nusret-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zz-her-handen-basa-belaymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gibi, Benim Gibi...', 'senin-gibi-benim-gibi-suleyman-saylan-1el4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SENİN  GİBİ,  BENİM  GİBİ...

Eşeleme külleri,

Sönmüş sandığın ocağımda

Korları görürsün; 

Henüz yaşın çok genç,

O korlarla yanar,

Üzülürsün.

Önemsiz gibi görünen

Önemli şeyler yıkar,

Kahreder insanı.

Bir de bakarsın ki; 

Önemsiz saydığın önemli şeyler

Birikmiş mazinde.

Bakarsın ki; 

Gücün kalmamış,

Yorulmuşsun, tükenmişsin...

İnsansan eğer,

Sen de yıkılırsın,

Yüreğin kanar derinden...

Yol sayılırsa eğer, 

Ben yolunu buldum; 

İçerek unutuyorum

Önemsiz gibi görünen önemli şeyleri

Ve seni...

Ben ne kadar içersem içeyim,

Unutursam unutayım,

Ne kadar yorgun, ne kadar bitkin,

Tükenmiş, çaresiz olursam olayım; 

Ayılınca yeniden yaşıyor

En can alıcı haliyle, 

Yadsıyamadığım önemli şeyler; 

Senin gibi, 

Sana tutuklu benim gibi...

   Süleyman SAYLAN

   Ankara, 17.07.2000 saat: 01.12', 'SENİN  GİBİ,  BENİM  GİBİ... Eşeleme külleri, Sönmüş sandığın ocağımda Korları görürsün;  Henüz yaşın çok genç, O korlarla yanar, Üzülürsün....', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/senin-gibi-benim-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yaz Son Kez...', 'bir-siir-yaz-son-kez-ahmet-suat-kocal-ha80c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şiir yaz son kez...

İçinde aşk olsun, sevda olsun,

Yer verme yalana, gerçek olsun.

Doyasıya yaşa her şeyi bu gün,

Yarın öl, düşmana bayram olsun...

Bir şiir yaz son kez...

Bakma, gülme, nefes bile alma,

Rahat ol, saçını başını da yolma.

Atomlarına ayrıl, yine de aldırma

Yarın öl, cenazende dahi ağlama...

Bir şiir yaz son kez...

Sokaklardan, caddelerden geç,

Her şey emrine amade, sen seç.

Bil değerini,  yaşamaktan vazgeç,

Yarın öl, buradan omuzlarda geç...

Bir şiir yaz son kez...

Şarkılar sussun, sussun tüm nameler,

Eğilsin, gündüzlere mahkum geceler.

Kime ne, ne söyler ne sayıklar heceler,

Yarın öl, ağlamasın ardından yürekler...

Bir şiir yaz son kez...

Nasıl da amansız yazıyorsan eskiden,

Her kelimeye yeni anlam yüklemeden.

Rahat ol ve gerçekleri hiç gizlemeden,

Yarın öl, kimseye haber dahi vermeden...

Bir Şiir Yaz son kez...

Yarın öl, kimseye haber dahi vermeden,

Yarın öl, yakınında kimseyi istemeden...

Yeter ki öl, hiç karşılık bile beklemeden,

Ve bir şiir yaz son kez; ölmeyi düşünmeden...', 'Bir şiir yaz son kez... İçinde aşk olsun, sevda olsun, Yer verme yalana, gerçek olsun. Doyasıya yaşa her şeyi bu gün, Yarın öl, düşmana bayr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-siir-yaz-son-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yüzünden', 'senin-yuzunden-suleyman-saylan-in7tx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SENİN  YÜZÜNDEN

Gitgide ayyaş oluyorum senin yüzünden; 

Nasıl girmişsen kalbime,

Gönlümü nasıl çalmışsan,

Evrenin her yerinde arıyorum,

Bulamıyorum kendimi...

Değer misin bu sevgiye,

Değmez misin,

Düşünmüyorum bile.

Düşünmekten utandığım için

İçiyorum habire...

Belki, o da belki,

Unuturum diye...

Eroin misin, esrar mısın,

Nesin sen? 

Damarlarımda dolaşan kana karışmış,

Esir almışsın beni.

Esirinim...

Aşırı dozda alınca seni düşlerimde; 

Gitgide bağımlı oluyorum,

Kanatlanıyorum.

Konacak bir dal bulamayınca; 

Takatsız kalıyorum

Sensizlik denizinde,

Batıyorum derinlere.

Gitgide ayyaş oluyorum ben

Senin yüzünden...

           Süleyman SAYLAN                                           

           Ankara, 07.06.1999 saat: 00.20', 'SENİN  YÜZÜNDEN Gitgide ayyaş oluyorum senin yüzünden;  Nasıl girmişsen kalbime, Gönlümü nasıl çalmışsan, Evrenin her yerinde arıyorum, Bula...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/senin-yuzunden-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaza Yolculuk', 'beyaza-yolculuk-ufuk-coban-ql2om', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyaza uzanan uzun bir yolculuktur düşleri süsleyen,

Zaman zaman umutsuzca, zaman zaman umarsızca büyüyen.

Belki sabır taşlarıyla bezenmiş bir yuvanın duvarlarında çınlayan,

Hoş bir sedadır vaktini bekleyen, beklerken büyüyen.

Günleri dolduran dakikalar bile çaresiz kalır sabrın karşısında,

Hızla akmak için elinden geleni yapar bu kutsal yolda.

Kuşlar bile müjdeler vaktin dolduğunu, zaman tükendiğinde,

Tabi tükenmek bilirse, bunca güzelliğin yanında.

Son nokta umuttur, candır, vazgeçilmeyecek bir arzudur,

Ne yapsın gönül, düşündükçe deli dalgalar gibi kudurur.

Bilir ki sonunda en büyük mutluluk onundur,

Paylaşmadıktan sonra neye yarar ki, bu öyle bir duygudur.

Güneş bir kaç kez daha fazla doğup batsa ne olur ki? 

Fırtınalar daha çabuk kopup nihayete erse kim takar ki? 

Zaman benim, sen de benim hayatım,

Bir ömür boyu beyninden, kalbinden akar giderim.

1999', 'Beyaza uzanan uzun bir yolculuktur düşleri süsleyen, Zaman zaman umutsuzca, zaman zaman umarsızca büyüyen. Belki sabır taşlarıyla bezenmiş b...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beyaza-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevabımdır.', 'cevabimdir-ali-osman-yilmaz-wt8g0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek,

Ama hiç bir şey beklemeden,

Ölesiye sevmek,

İşte bu,öyle bir yürek,

Kim istemez sevilmek? 

Maharetmidir beklemek? 

Sevdinmi,adam gibi sevecek,

Aşk dediğin,sevda dediğin,

Böyle  yürekte,

Filiz verecek.

Bu bir yürek,

Doyasıya sevmesi gerek,

Onu da delicesine sevecek,

Sevdasıyla  saracak,

Harında kor,

Ateşinde kül edecek,

Göz göze geldiğinde,

Gözlerinde kaybedecek,

Velhasıl bu adamın yüreğine,

Kırmızı gül gibi çılgın,

Bir kadın gerek.

İşte o zaman bu yürek,

Her tıklayışında kükreyerek,

O yürekle el ele verecek,

Sevdalı yunuslar gibi,

Engin denizlerin maviliklerinde,

Mutluluk adasına doğru

Aşklarının sonsuzluğuna,

Birlikte yüzecek.', 'Sevmek, Ama hiç bir şey beklemeden, Ölesiye sevmek, İşte bu,öyle bir yürek, Kim istemez sevilmek?  Maharetmidir beklemek?  Sevdinmi,adam gib...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cevabimdir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl buyur etmeli', 'nasil-buyur-etmeli-fidan-bulut-742bz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığına hapsolmuş ruhum

Seni düşünmekteyim aç ve çıplak

Çaresiz yorgun yalın ayak

Duvar diplerine sinmişim

Gözlerim uzak tepelerde aç kurtlar gibi

Bedenim kömürlük köşelerinde gizli

Hangisi daha kötü

Bedenime işlemiş çöp kokusu kömür isi mi

Ruhuma işlemiş insanlık kiri mi

Ne hırçın pençeler yaralayabiliyor kalın derimi

Ne prangalar yakabiliyor canımı

Dar mekanlar dip köşeler yabancı değil

Dört metrekarede de alırız nefes

Ruhumuz da bedenimiz de sığar evelallah

Seni koyacak yer bulamıyorum ne yazık

Bir gözüm bir kalbim var ağırlayabileceğim

Ama sen de oraya nasıl gireceğini bilemezsin ki

Geniş caddelerde temiz sokaklarda topuklarına kadar temiz

Yeşil bahçelerde ince belli bardaklar elinde

Buyur edemem ya bir balıkçı kulübesine

Üzülüyorum da sana hiç çamur oynamamış olmana

O yüzden dir bilemezsin çamurlu sevdaları

Yollarını açıvermişler önüne hep ne yazık

Dar sokakların çıkmazların tadını bilemezsin

Aslında bilseydin tabakların meyvenin tadını nasıl bozduğunu

Yakalanma korkusuna inat güzelleşir tadı 

Sadece meyvenin mi güzelim

Korkular dik tutar insanın başını hayata

Korkular açar gözleri kulakları

Koşmayı öğrenirsin hınca hınç

Sanırsın aldığın yara madalyan gururun

Acısına kanına inat

Ve gün gelir korkusunu da yener ihanetle

Seni büyüten seni sen yapan korkuna ihanet

Ve yenik düştüğünün sevdalar olduğunu

Ve karşı durduğun dünyaya bakıp alay ederken

Yiğitliği yine sevdaların bozduğunu

Ve kırbaçların yakamadığı göz pınarlarını

Bir çift gözün nasıl yaktığını

Sinmişken bile meydan okumak

Dünyaya açlığına kirine kafa tutmak varken

O bir çift gözde 

Eridiğini çocuklaştığını görmek

Anlatamam ki benzemez ki

Ne okuduğun ronamlaraına

Ne de süslü şiirleine

Zor ama güzel be gülüm

Gecenin ayazında ruhunu hapsetmek sana', 'Gecenin karanlığına hapsolmuş ruhum Seni düşünmekteyim aç ve çıplak Çaresiz yorgun yalın ayak Duvar diplerine sinmişim Gözlerim uzak tepeler...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/nasil-buyur-etmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cüce adamsın....', 'cuce-adamsin-i-shak-ozlu-xafd0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özel kalemin randevu veriyor,

Dünya başkanları sana geliyor.

Elini sıkan dört köşe dönüyor,

Ülkesinde yaban seni seviyor,

Yiğit adamsın vesselam.

Bizim geçmişimiz senin bugünün,

Geçmiş tarihlerde bize gelirler,

Bizim el etegimizi öperler,

Türlü türlü vaatler verirlerdi,

Büyük adamsın vesselam.

Zaman senin durma öttür borunu,

Şimdilik düşünme kötü sonunu,

Aciz dünyanın özğürlük sorunu,

Çözüm için bekler kanlı yolunu,

Kötü adamsın vesselam.

Zaman bu anlamazsın gelir geçer,

Bir gün güvendigin ülkende göçer,

Rüzğar eken elbet fırtına biçer,

Unutma Azrail senide seçer,

Cüce adamsın vesselam.

Başın yukarılarda geziyorsun,

Müslüman devletleri eziyorsun,

Haçlılara komuta ediyorsun,

Savaşla geldin kanla gidiyorsun,

Aktör adamsın vesselam.

Ülken adına adım atıyorsun,

Ülken adına Bomba saçıyorsun,

Ülken için ateşler yakıyorsun,

Ülken için ileri bakıyorsun,

Kızsamda yazsamda gerçek degişmez,

Çirkin adamsın bay w.Bush.', 'Özel kalemin randevu veriyor, Dünya başkanları sana geliyor. Elini sıkan dört köşe dönüyor, Ülkesinde yaban seni seviyor, Yiğit adamsın vess...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cuce-adamsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haddime Mi', 'haddime-mi-ahmet-suat-kocal-jtssu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu satırlar ardında tek hikmet-i vücudum, 

Haddime mi namütenahi olmaya çalışmak. 		

Tekemmül beynimde, aşikardır yoruldum, 

Cihetim budur bundan sonra, malikle yaşamak...', 'Bu satırlar ardında tek hikmet-i vücudum,  Haddime mi namütenahi olmaya çalışmak. 		 Tekemmül beynimde, aşikardır yoruldum,  Cihetim budur b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haddime-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ın Selamı', 'allah-in-selami-hasan-cam-enca8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeniden dogdu güneş, bu sabah parlıyor

Gözlerim mayhoş, uykusuzum yine

Utanç, pişmanlık var içimde, yıllar öncesine

Bakamıyorum, dünkü batırdıgım güneşe

Şuçluyor,suçluyor vefasız zalim, nankör diye

Hücrelerim delindi, ukte vuramadım sevgime

Selamsız dost atlamayan, gelincik çiçegime

Selamün aleyküm vesselam,ALLAHIN selamı

Yarımdı ay, incidi yıldızlar.üzgündü bu gece

Bir nebze aydınlattılar yüregimi, sen gidince

Ne zalimimki,onlar dayanmadı, batırdıgım güneşe

Hepsi yok oldular birer, birer bugün dogan güneşe

Şuçluyor,şuçluyor vefasız zalim, nankör diye

Hücrelerim delindi, ukte vuramadım sevgime

Selamsız dost atlamayan, gelincik çiçegime

Selamün aleyküm vesselam,ALLAHIN selamı

18,07 2005

.ümraniye         İstanbul

[email protected]', 'Yeniden dogdu güneş, bu sabah parlıyor Gözlerim mayhoş, uykusuzum yine Utanç, pişmanlık var içimde, yıllar öncesine Bakamıyorum, dünkü batır...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/allah-in-selami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek ile dövüş', 'felek-ile-dovus-i-lhami-arslantas-f6ecl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu köhne dünyanın kahrı zulmünü; 

Çok direndim çekemedim  ey..! oğul. 

Dişe diş dövüştüm  felek ile ben; 

Sökemedim  bir dişini ey.....!  oğul.

Sakın ha  yeltenme böyle bir işe,

Felek  ile  girme  yakın  dövüşe,

O kazandı her dem  bense bir tuşa,

Yıkamadım  çok denedim ey..! . oğul.

Ben keskendim ama o esah vurdu,

Ne zaman kaçtıysam karşıma durdu,

Köreldi bedenim  dert başa  sardı,

Çakamadım  kazık gibi ey...!  oğul.

Ne imiş bu ümmet ne imiş kulluk? 

Baştan  eksik değil kerkenez,çulluk,

Namuslu  aç sefil, namertte  bolluk,

Yakamadım  ben insanı  ey....! oğul.

Namerdi mert diye üstümde saydı,

Bir  feryat  eyledim el,alem duydu,

Gözümü çıkartıp karşıma koydu,

Bakamadım  iki gözle ey....! oğul

Sızladı vicdanım, ürperdi tüyüm,

Kelepten sağıldım hep süyüm süyüm,

İlhami''yim körüm hem de kör düğüm,

Takamadım kör iğneyi  ey....!  oğul.', 'Şu köhne dünyanın kahrı zulmünü;  Çok direndim çekemedim  ey..! oğul.  Dişe diş dövüştüm  felek ile ben;  Sökemedim  bir dişini ey.....!  oğ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/felek-ile-dovus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir güzelin edasına vurgunum', 'bir-guzelin-edasina-vurgunum-i-lhami-arslantas-j7z7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne güzel de ad yakışmış şanına

Deste düşer ak gerdanın yanına

Ben sevmesem kimler girer kanına

Bir güzelin edasına vurgunum

Gülüşü var tövbe eder ağlayan

Mecnun olur bir kez gönül bağlayan

Benim gönlüm deli dolu  çağlayan

Bir güzelin edasına vurgunum

Dudağında her kelamın nazı var

Sohbetinin lezzeti var tuzu var

Dimağımda  aşk adının izi  var

Bir güzelin edasına vurgunum

Suya gider pınar başı şenlenir

Karşısında dilsiz olan dillenir

Yanağında gamzeleri güllenir

Bir güzelin edasına vurgunum

Der ilhami can katardı  bir cana

Çok aht ettik gelemedik yan yana

Bana göre her halinde bin mana

Bir güzelin edasına vurgunum', 'Ne güzel de ad yakışmış şanına Deste düşer ak gerdanın yanına Ben sevmesem kimler girer kanına Bir güzelin edasına vurgunum Gülüşü var tövbe...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-guzelin-edasina-vurgunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir Hangi Çöp Kamyonunda Gidiyor? ..', 'kim-bilir-hangi-cop-kamyonunda-gidiyor-ahmet-suat-kocal-id0si', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir geçmişimi düşündüm bir de seni meleğim,

Ben de bütün hatıraların yavaş yavaş soluyor.

Ne yüreklere ne akıllara sığardı “sevda” değim,

Şimdi kim bilir hangi çöp kamyonunda gidiyor? ..

Ne çok mücadele etmiştim kaybetmemek için,

Soluk bir sevda var yüreğimde, yad’ını istiyor.

Satır satır, sayfa sayfa ağladım inan için için,

Şimdi kim bilir hangi çöp kamyonunda gidiyor? ..

Her sevda benim, her ayrılık senin eserin sanki,

	Sana bir şey anlatamadım, yüreğim o’na yanıyor.

	Topladım pılımı pırtımı, nerde bilmiyorum inan ki

	Şimdi kim bilir hangi çöp kamyonunda gidiyor? ..

	Her şey sen, sanki sen de her şeydin deli yüreğimde,

	Aşka, umuda dair ne varsa bende, ağır ağır ölüyor.

	Son bir şarkısın, bilmiyorum artık gerçekler nerde,

	Şimdi kim bilir hangi çöp kamyonunda gidiyor? ..

	Bilemiyorum varlığın mı, yokluğun mu tek yalan,

	Yoruldum, bu bilmece beni yüreğimden vuruyor.

	Aşkım, sevdam sen miydin bana geçmişten kalan,

Şimdi kim bilir hangi çöp kamyonunda gidiyor? ..

	Her şey yalan, her şey rüya; bir deli sensiz ölüyor,

	Bu sevda kim bilir hangi çöp kamyonunda gidiyor? ...', 'Bir geçmişimi düşündüm bir de seni meleğim, Ben de bütün hatıraların yavaş yavaş soluyor. Ne yüreklere ne akıllara sığardı “sevda” değim, Şi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kim-bilir-hangi-cop-kamyonunda-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş...', 'bekleyis-mehmet-demir-atmali-nm030', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '--Askerden Sevgiliye...

Şakağıma düşen aklar; 

İçinde mazimi saklar...

Çatlamıştır bal dudaklar; 

Beni bekleyi, bekleyi...

Issız kalmış boş konaklar,

Silinmiştir mor benekler,

Kızarmıştır al yanaklar; 

Günü bekleyi, bekleyi...

Saçlarım hiç taranmamış,

Renkten renge bürünmemiş,

Gözyaşlarım arınmamış; 

Seni bekleyi, bekleyi...

Askerde ben yaşlanmışım,

Mehmetçik''ken, hoşlanmışım.

Olgunlaşıp, işlenmişim; 

Anı bekleyi, bekleyi...

 17.4.1979', '--Askerden Sevgiliye... Şakağıma düşen aklar;  İçinde mazimi saklar... Çatlamıştır bal dudaklar;  Beni bekleyi, bekleyi... Issız kalmış boş ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bekleyis-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgelerin İz Düşümünde', 'golgelerin-i-z-dusumunde-cemal-karsavran-zw68d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yokuştur uzundur ve de sarptır

engebeli ve de düştür

rakımı yüksek de olsa

çilesiz bülbül olmaz derler ya

eziktir yüreğim seviye

kıskanırım sarhoş gece ve dallardan

insanlığımdan utanaraktan

makul değil belki bu durum

zamansız ve de mekansız

duygularımın yerçekiminde 

acizane bahar vurgunuyum

yeşile ala ve de kırda papatyaya

dönencemin ipinde şiir

aşk arar sevdalı yüreğim

gölgelerin iz düşümünde', 'yokuştur uzundur ve de sarptır engebeli ve de düştür rakımı yüksek de olsa çilesiz bülbül olmaz derler ya eziktir yüreğim seviye kıskanırım ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/golgelerin-iz-dusumunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkumiyetimi Bağışla Benim', 'mahkumiyetimi-bagisla-benim-cemal-karsavran-opna7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaç zaman oldu görüşmeyeli

baharla doğan çiğdem

o eski halinden eser yok şimdi

kırların ve doğanın süsü

saçına iliştirilen sevgililerin

çisi çisi yağar nisan yağmuru

infilak eden  sevgilerin üstüne

ğine gözlerimde bir eski bahar

dillenirse eğer susmak bilmez

esip esip ılık lodos rüzgarıyla

martıların kanatlarında güler

çayır çimen olur dağ bayır

imzasız şiirler yazılırken adına

güncellenip nevruz dönümlerinde

divan kurulur besteler çalar

eskidikçe yenilenen ruhlara

mavi mutluluklar sunulur

çünkü sen anları bağışlarsın sevgiye

iflas etmiş mutluluğun güncesi

gelip konmasaydı kaş ucuma

dileklerim kabul olmazdı bu kadar

ey mutluluk çemberim varlığın

mahkumiyetimi bağışla benim', 'kaç zaman oldu görüşmeyeli baharla doğan çiğdem o eski halinden eser yok şimdi kırların ve doğanın süsü saçına iliştirilen sevgililerin çisi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mahkumiyetimi-bagisla-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi, beyaz ve siyah...', 'mavi-beyaz-ve-siyah-ulas-guleviz-sj8og', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi, beyaz  ve  siyah...

Mavi beyaz  kadar  az ,

beyazsa

tebessümlü  bir  gülümseme  kadardır  hayatta.

Yani  ne  mavi  beyaz  kadardır

ne de  beyaz, maviyi  dengeleyecek  güçtedir.

Güç  siyahtadır, güç  hayatta ! 

Hayatınızda  mavilikler, gözlerinizde

beyazlıklarsa , sadece  saçlarınızdaysa

siyahın, beni, seni, bizi  yendiği

açıkça  ortadadır.

Ama  unutulmaması  gereken  bir şey  var ki,

o da  minnacık  bir  beyaz  ve  minnacık  bir  mavi

tonlarca  siyahı  yenmeye  yetecektir

eğer  istersen.', 'Mavi, beyaz  ve  siyah... Mavi beyaz  kadar  az , beyazsa tebessümlü  bir  gülümseme  kadardır  hayatta. Yani  ne  mavi  beyaz  kadardır ne ...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mavi-beyaz-ve-siyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürekli konuşuyordu', 'surekli-konusuyordu-ulas-guleviz-ilp6w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sürekli  konuşuyordu

yorgundu  bedeni

ama yaşadıklarını  herkes  bilsin  istiyordu 

Yıpranmış  elleriyle

yıllardır  giydiği  ceketinin  ceplerini  karıştırdı

ve  tütün  tabakasını  bulup  kapağını  açtı 

Yüz  ifadesi  ve  giysileri  yoksulluğun  tarifini  veriyordu 

ama  bu  haliyle  bile  bonkör  biriydi 

Cebinden  çıkardığı  tütünden  herkese  ikram  etti  

Kendisi de

sardığı  tütünü  yakıp  içerken  hem  konuşuyor

hem de  tütünü  içine  çekip

ağzına  gelenleri  belli  aralıklarla   tükürüyordu 

Bu  durum  onda  alışkanlık  yapmış  olmalıydı

tütün  bittiği  halde  belli  aralıklarla  tükürmeye  devam  etti 

Onun  gönlünü  almak

bir  çocuğun  gönlünü  almaktan  daha  kolay

ve  kalıcıydı 

Üzerindeki  ceket  ve  ayağındaki  ayakkabının

kendine  ait  olmadığı  belliydi

Üzerine  giydiği  giysiler

başkalarına  göre 

onu  ciddiye  almamak  için  yeterliydi 

Ama  gerçekler  öyle  demiyordu

O

giydiği  ceketi  belki  bir  ömür  giydi 

 ve  biliyor  ki

o  ceket  onun  hayatının  gizemleriyle  dolu

Sanki  ceplerinde  yaşadığı  acılar 

yorgunluklar  var 

Kıyafetinden  ve  teninden  anlaşılıyor ki

o  büyük  bir  savaş  vermiş 

Hep  ezilmiş 

hor  görülmüş

ve  hiç  bir  zaman  ciddiye  alınmamış 

hâli  hatırı  bile  sorulmamış  çoğu  zaman

ve  böyle  bıkmadan

durmaksızın  konuşması  ondan', 'Sürekli  konuşuyordu yorgundu  bedeni ama yaşadıklarını  herkes  bilsin  istiyordu  Yıpranmış  elleriyle yıllardır  giydiği  ceketinin  cepl...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Güleviz']::text[], 8.5, '{"poet":"Ulaş Güleviz","poet_slug":"ulas-guleviz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/surekli-konusuyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetimin Feryadı...', 'yetimin-feryadi-mehmet-demir-atmali-srv82', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Yuvasız kuşlara...

Ana kucağını,

Baba ocağını,

Anlatırmısınız bana? 

Nasın bir şey....? 

Anne sütü emenler! 

Tadını söylermisiniz...? 

Oğlunu çağıran analar,

Beni de çağırırmısınız...? 

Çocuklar...! 

İsminizle çağrılmak,

Doyasıya bağırmak,

Nazlanarak ağlamak,

Nasıl bir şey...? 

Baba bana para ver,

Derken utanırmısınız..? 

Babanıza koşarken,

Neşe içinde yaşarken,

Kucağında nazlanmak,

Ona ''Baba'' demek; 

Nasıl bir şey...? 

Rüyalarda ağlarsınız,

Sizi biri kucaklar ya...

Ona Anamm dersiniz galiba...

Onun kucağına sığınmak,

Onun kollarında uyumak; 

Nasıl bir şey...? 

Babanız şehirde döner,

Onu hep özlersiniz ya,

Yolunu gözlersiniz ya,

Hani, hediye beklemek; 

Nasıl bir şey...? 

Severek evlenirsiniz,

Ve Aşık olursunuz...

Karıcığım dersiniz ya...

Baba ocağında evlenmek; 

Nasıl bir şey...? 

Evlenirken, el öpersiniz.

Size düğür gideyler ya...

''Anamm-Babamm'' dersiniz...

Onların elini öpmek; 

Nasıl bir şey...? 

Yetimlik ne zor şey....

 4.5.1978', '-Yuvasız kuşlara... Ana kucağını, Baba ocağını, Anlatırmısınız bana?  Nasın bir şey....?  Anne sütü emenler!  Tadını söylermisiniz...?  Oğlu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yetimin-feryadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığıntı Koyu', 'siginti-koyu-ahmet-ziya-pektas-c77f8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınalı bir gündü.

Sığıntı koyunda iki kişi.

Yalnız ve çaresizlik içinde.

Gelecekten umutsuz.

Üşüyen elleri birbirine kenetler,

Ciğerlerine işleyen soğuk.

Sığıntı koyunun, sığıntı aşıklar,

Sevda ateşiyle ısınırlar.

Buruk bir sevdadır yüreklerinde.

Hüzünlü günleri, silerler hafızalarından.

Yeniden kenetler elleri ellere,

Sevdayla dolu hisler.

Fırtınalı bir günde,

Fırtınalı bir aşk yaşamıştı,

Sığıntı koyundaki düşler.', 'Fırtınalı bir gündü. Sığıntı koyunda iki kişi. Yalnız ve çaresizlik içinde. Gelecekten umutsuz. Üşüyen elleri birbirine kenetler, Ciğerlerin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siginti-koyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykum', 'uykum-ahmet-ziya-pektas-6x38u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz kapaklarım bana ihanet ediyor.

Bitirmek istiyor, oynadığı rolü.

Dudaklarım açılıp kapanıyor,

Esniyor insafsızca.

Arkadaşım uyku,

Seninle sohbet edemem şimdi.

Ne olur git başımdan.

Akşamleyin buyur gel.

Senin de işin hep ters gider.

Gündüz gelip, gece gidersin.

Bir gün de vakitli gelsen.

Niçin akranlarına benzemezsin.

Bir gün sana küseceğim,

Arkadaşlığımı keseceğim.', 'Göz kapaklarım bana ihanet ediyor. Bitirmek istiyor, oynadığı rolü. Dudaklarım açılıp kapanıyor, Esniyor insafsızca. Arkadaşım uyku, Seninle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uykum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanla Dostluk', 'yalanla-dostluk-ahmet-ziya-pektas-c7xdh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazı şeyleri açıklamak neden zor? 

Basit kalır bazen, bütün gerçekler.

Ağlamaklı bakışlar fırlatır, bir çift göz.

Yufka yüreğini yakar hüzünlü günler.

Yalanla tokalaşır ellerin.

Can ciğer dost olursun bir zaman.

Çok zaman geçer üstünden,

Ölümünün gerçeklerin.

Sahte bir oyun içinde,

Rolünü kaparsın artık.

Her şey güzeldir sence.

Değirmenin çarkı,

Dönüyordur düzgünce.

Gün gelir seni de sarar şüphe.

Kara bir leke gibi yapışır yüzüne.

Bir zamanlar senin yaptığın gibi,

Yapışır yalanın ihaneti.

Koparıp almak istersin,

Çabalaman nafile.

Gücün yetmez tükenir.

Yalanla kurduğun dostluk,

Acı bir sondur artık.', 'Bazı şeyleri açıklamak neden zor?  Basit kalır bazen, bütün gerçekler. Ağlamaklı bakışlar fırlatır, bir çift göz. Yufka yüreğini yakar hüzün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalanla-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla Yarış', 'zamanla-yaris-ahmet-ziya-pektas-nh8r9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şeyler alır benden,

Zaman akıp giderken.

Yaşamış olduklarım,

Ve,

Yaşanmamışlar.

Ağlamak mı gerek, gülmek mi? 

Bilemiyorum.

Geçen yıllara mı üzülmek gerek? 

Kaçar yıllar, yıllar kaçar benden.

Kovalarım ben.

Bir de bakarım,

Yıllar benim ardımda.

Kısır bir döngü etrafında,

Döndüğümüzü anlarım.

Geçer defalarca, beni geçer.

Yorgun düşer dizlerim,

Dinlenirim.

O yorulmaz, hiç yorulmaz.

Döner defalarca.

Anlarım artık,

Yakalamam imkânsız.

Bırakıp koşmayı, yürümeye başlarım.

Sona varmak için yürürüm.

Sonuma varmak için.

Bir güneş doğar gönlümde,

Sarar bedenimi sessizce.

Güç gelir, kuvvet gelir.

Azimle koşarım hedefe.

Durmak, dinlenmek yok artık.

Kaybettiğim yılları,

Bir bir geçerim.

Geçerim en son yılları.

Sonuncuyu geçince,

Sana rastlarım.

Rahatlarım.

Senin için koştuğumu,

Sevgin ile koştuğumu anlarım.

Sarılırım dört elle,

Sarılırım hayata.

Yıllar geçmiyor artık,

Geçemiyor beni yıllar.

Ben, sen ve sevgimiz.

Niçin yılları düşünelim ki biz.', 'Bir şeyler alır benden, Zaman akıp giderken. Yaşamış olduklarım, Ve, Yaşanmamışlar. Ağlamak mı gerek, gülmek mi?  Bilemiyorum. Geçen yıllara...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/zamanla-yaris-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar ki Çocuktular…', 'onlar-ki-cocuktular-hikmet-feridun-demir-6lceb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Henüz başındaydılar yaşamın...

Kanlarından demlendi birileri…

İlahlar dahi o kadar yüce olmadılar.. 

Demlenmek, Kandan demlenmek için…

Körpecik bedenleri delik deşik edildi…

Kan toprağa aktı, kızıla boyandı toprak...

Kiminin parça parça oldu bedenleri…

Mezarları dahi olmadı kiminin…

Onlar ki çocuktular…

ve onlar ölüme giderken farkında bile olmadılar yaşamın…

Birileri akan kana çanak tuttular…

Çanaktan bir damlada olsa dudaklarına sürebilmek için...

Onlar ki çocuktular ve henüz yaşamın başındaydılar…

Kimi savundu yere düşen savunmasız körpe bedenleri…

İnsanlığın onuru için gerekli olanı yaptı kimileri…

Çocukluklarına acıdı kimileri, 

kimileride parçalamak istedi körpe bedenleri…

Kimi korkusunda kalbinin kapısına kilit vurdu…

Kimisi sayelerinde kendilerine yer edindi…

Çanaktan dudaklarına kanı sürebilmek icin...

Topraga dökülen kan yalandı…

Dostları yanlarında yoktular…

Gözleri görmezdi onların artık…

Kalbleri his etmezdi artık...

Sevdigini söyemenin ne zararı olabilirdi ki…

Ve onlar yürüyüşlerde artık bayraktılar…

Onlar ki henüz çocuktular...

Sevişmeyi dahi tatmamıştılar doyasıya...

Aşık olacak yaştaydılar…

Ve onlar İlahtılar, Nümayişlerde...

Yaşarken onlar….

Henüz çocuktular...

Haziran 1978

Malatya', 'Henüz başındaydılar yaşamın... Kanlarından demlendi birileri… İlahlar dahi o kadar yüce olmadılar..  Demlenmek, Kandan demlenmek için… Körpe...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/onlar-ki-cocuktular-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-yucel-karakilic-tsijz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Terkettiğin günü, yas ilan ettim,

Matem tutup, karaları bağladım.

Hasretinle kendimi talan ettim,

Çocuk gibi, hüngür hüngür ağladım.

''Hayır doğru değil, olamaz'' dedim,

Çıldırdım, haykırdım, sabredemedim,

Ne laftan anladım, ne söz dinledim,

Çocuk gibi, hüngür hüngür ağladım.

Fırtınalar koptu, yufka özümde,

Sular seller çoştu, iki gözümde,

Hıçkıra, hıçkıra elim yüzümde,

Çocuk gibi, hüngür hüngür ağladım.

Hatıran akıyor her göz yaşında,

Damla izleri var sokak taşında,

Köprü altlarında, köşe başında,

Çocuk gibi, hüngür hüngür ağladım.

Yükledin omzuma bunca vebali,

Parmakla gösterdi beni ahali,

Memesi kaybolmuş bebek misali,

Çocuk gibi, hüngür hüngür ağladım.

Sen söyle! Yaptığın reva mı, hak mı? 

Sevipte, saadet beklemek çok mu? 

Ya! Kadın değilmisin, vicdanın yok mu? 

Çocuk gibi, hüngür hüngür ağladım.

Kahrımdan, saçımı başımı yolup,

Ah çekerek, yüreğimi dağladım.

Erkekliği ayak altına alıp,

Çocuk gibi, hüngür hüngür ağladım.', 'Terkettiğin günü, yas ilan ettim, Matem tutup, karaları bağladım. Hasretinle kendimi talan ettim, Çocuk gibi, hüngür hüngür ağladım. ''Hayır ...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/agladim-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Bakalım', 'bil-bakalim-ufuk-coban-ndwup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Planlamak yada hissedip düşünmek,

Aynı şeyleri aynı anda.

Zamanı kovalarcasına sabırsızlanmak,

Aynı amaç ve aynı kişi uğruna,

Rüzgarla yarışmaktan bile zordur bazen.

Günler geçse mi, geçmese mi derken,

Üzülmenin ne olduğunu bile unutur insan.

Ne olduğunu söylemem sen merak ederken,

Üzülme boşuna anlarsın dikkatli bakarsan.

1999', 'Planlamak yada hissedip düşünmek, Aynı şeyleri aynı anda. Zamanı kovalarcasına sabırsızlanmak, Aynı amaç ve aynı kişi uğruna, Rüzgarla yarış...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bil-bakalim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrularım-1', 'yavrularim-1-mehmet-demir-atmali-omcod', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çığlıkla göz açtığın gün hayata,

Anlamını bilemediler yavrum...

Ruhumuzun izlerini Ayet''te; 

Hiç bir zaman silemediler yavrum...

Minnacık ellerin, Anamın eli,

Elmacık yanağın, bahçemin gülü.

Küçücük şu kalbin, ümitle dolu; 

Anan-Baban gülemediler yavrum...

''Nazlı Hilal'' gibi dalgalanasız,

''Ayşegül''üm'' gibi bilgelenesiz,

Bayrağım altında gölgelenesiz; 

Bu vatanı bölemediler yavrum...

Bağladınız beni, siz ocağıma.

Az mı aldım sizi, ben kucağıma,

Alışageldiniz hep sıcağıma; 

Sevgimizi çalamadılar yavrum...

Babanız Mehmet''in özü incedir,

Ana''ya-Baba''ya saygı Dincedir...

Evladın duası ataya goncadır; 

Gülümüzü yolamadılar yavrum...

10.11.1987

Kızım Nazlı Hilal ve Ayşagül''e...', 'Çığlıkla göz açtığın gün hayata, Anlamını bilemediler yavrum... Ruhumuzun izlerini Ayet''te;  Hiç bir zaman silemediler yavrum... Minnacık el...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yavrularim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gördüm', 'seni-gordum-levent-genc-10q0o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir iklim boyu uzamıştı boyun,

Gözlerinde hüzün vardı,

Aşk budur dediğim,

baktığın ilk andı...

Ellerim saçlarını sardı,

Yaralı sevdamı bir hâl aldı,

Avuçlarındaydı yüreğim,

Gördüğüm düşte kaldı...', 'Bir iklim boyu uzamıştı boyun, Gözlerinde hüzün vardı, Aşk budur dediğim, baktığın ilk andı... Ellerim saçlarını sardı, Yaralı sevdamı bir h...', ARRAY['Türk Edebiyatı','Şiir','Levent Genç']::text[], 8.5, '{"poet":"Levent Genç","poet_slug":"levent-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-gordum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Eyleme Zamanı', 'dar-eyleme-zamani-cemal-karsavran-ppkej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana şiir yazdığımı söylemek için 

Zamanı sana ayarladım 

Acılarımı dindirecek ilaç icat edilmedi 

Yalnızlığımı geçiştirecek 

Yalnızca sensin 

Gönül bahçem de 

Dolunay’ım mehtab’ım 

Nar çatlağı pembe düşüm 

Hayat damarlarımda dolanırsın

Her şeyi nasıl anlatabilirim 

Elinin elime değeceği an

Gözlerimin gözlerinde kayboluşu

Sonu yok olsa da bu gidişin

Sevgi  aşkın kıskacında

Yüreğimde kıvılcımları 

Kimi zaman sıcak bir hüzün yüklüyüm 

Dolunay gülüşlü yakamoz akşamlarda 

Sarı bir bayram yaşıyor yüreğim

Deliler gibi yarına umutlarım 

Gizemine tapıyorum 

Her şey var sende gökyüzü zümrüt 

Ağlarımda şiir ve yaşama dair ne varsa 

Uğultulu şaşkın bir günün 

Yaşlı aşkıyla anıyorum 

Tüm güzellikleri

Gözlerim kıpırdamadan 

Gerekli bir gelecek gibi yaşıyorum 

Uzatıyorum ellerini 

Parmaklarımın ucu mavi bir yolculuk 

Hayatın beyaz perdesinde 

Güne sır geçirir gözlerin 

Düşlere düş katar gecelerin 

Paylaşımların candan yürekten 

Esirinim zincirler yüreğimde 

Dar eyleme zamanı', 'Sana şiir yazdığımı söylemek için  Zamanı sana ayarladım  Acılarımı dindirecek ilaç icat edilmedi  Yalnızlığımı geçiştirecek  Yalnızca sensi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dar-eyleme-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyumamıştı', 'uyumamisti-ozan-turk-wkhpx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski bir ses düşün

Düşünki bu günkü gibi 

Çınlıyor kulaklarında

Düşünki bu günkü gibi

Yaramaz

Meme isteyen çocuk…

Bir gecesini unutmam hiç

Kızıla kaçan bir tarladaydım

Gelincik avında

Ve bacaklarımda bir ağırlık

Tarla kadar

Sonra bir ruzgar sardı gelincik diyarını

Bir derin “of” çekmişim o an,

Yorgun ve baldırım kadar 

Uyandı,

Unutulmaz uykusundan

En güzeli dünlerin,

En başa aldı tüm yaşanılmayanları

Zaten

Hiç uyumamıştı…', 'Eski bir ses düşün Düşünki bu günkü gibi  Çınlıyor kulaklarında Düşünki bu günkü gibi Yaramaz Meme isteyen çocuk… Bir gecesini unutmam hiç K...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyumamisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-sedat-akguden-p6lms', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçki sigara gibi

Bağımlıyım derdin sana

Oysa

Üçgün bile sürmedi aşkımız

Be insafsız', 'İçki sigara gibi Bağımlıyım derdin sana Oysa Üçgün bile sürmedi aşkımız Be insafsız...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalanci-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek İstiyorum.', 'bilmek-i-stiyorum-ali-osman-yilmaz-4ewrj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzelim,Aşkım,

Sevdasında  yanıp,

Kül olduğum,

Kimbilir,nerelerdesin? 

Oralarda senin,

Yaşamak için ne yaptığın,

Hiç ilgilendirmiyor beni.

Gönlünde  düşler kurduğun,

Yüreğini kıpır,kıpır attıran,

O meçhule,adım atmaya,

Cesaretin, varmı  senin? 

Bunu bilmek istiyorum...

Ne haldesin kimbilir,

Aşk için,düşlerinde  hala,

Aptallar gibi görünmeye,

Yüreğin varmı? 

Bunu bilmek istiyorum.

Uzaydaki gezegenlerin,

Kaç tane olduğuyla,

İnan,ilgilenmiyorum.

Ben senden,

Sana sunulmuş olan kaderini,

Değiştirmeye  niyetin varmı? 

Yaşamındaki  ihanetlere,

Hala dayanıp,dayanmadığını,

Daha çok, acı çekmekten korkup,

Kozana kapanıp kapanmadığını,

Bilmek istiyorum.

Dünyadaki herkesten,

Hiç bir şeyi saklamadan,

Ve düzeltmeye çalışmadan,

Acılarımla,acılarını harmanlayarak,

El ele birlikte,

Tek bir kimesne olarak,

Oturmaya yüreğin varmı,

Bilmek istiyorum.

Sevinçlerimle sevinçlerini,

Hüzünlerimle hüzünlerini,

Göz göze gelip sarıldığımızda,

Ten tene sevişmemizden sonra,

Benimle birlikte  sonsuza,

Kanat açabilirmisin? 

Hiç bir şeye sınır koymadan,

Bize bakan gözlere,

Arkamızdan söylenen sözlere,

Kulak asmadan hemde,

Sabahlara kadar çılgınca,

Parmak uçlarımızda dansederken,

Aşkın girdabında  yok olup,

Mevlananın  döndüğü gibi,

Kollarımda dönebilirmisin? 

Bilmek istiyorum.

Eğer bir gün yeniden,

Buluşursak bu kez,

Olduğun gibi görünmeye,

Yada göründüğün gibi olmaya,

Ardında bıraktığın her şeyde,

Güzellikleri görebilecekmisin? 

Ellerimi sana uzattığımda,

Ellerimizin sıcaklığında,

Göz bebeklerime bakarak,

Bana güvenebilecekmisin? 

Ben göz bebeklerinde,

Yok olmak istiyorum dediğimde,

Sana güvenebilecekmiyim,

İşte sevgilim,Aşkım,ateşim,

Ben bunu bilmek istiyorum.', 'Güzelim,Aşkım, Sevdasında  yanıp, Kül olduğum, Kimbilir,nerelerdesin?  Oralarda senin, Yaşamak için ne yaptığın, Hiç ilgilendirmiyor beni. G...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/bilmek-istiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Anneme', 'canim-anneme-sedat-akguden-v18y0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne aksütüne 

Su karıştırma cesaretini gösterebildiler

Ne de! 

Cigan gözlü kedilerin çirit attığı 

Oyunlara getirebildiler Sevigini', 'Ne aksütüne  Su karıştırma cesaretini gösterebildiler Ne de!  Cigan gözlü kedilerin çirit attığı  Oyunlara getirebildiler Sevigini...', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canim-anneme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadın Sensin', 'o-kadin-sensin-cemal-karsavran-k4xr4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adı bende saklı hecelerimde

Masum bir tebessüm yüzünde

Şaşkın bakışlarım arar her yerde

Alternatifi yok o kadın sendin

Çillerin yüzünde al beni diyor

Her yanın oynaktır hem de işveli

Dudağın tatlı bir elma şekeri

Aklım san ki sende bende değil ki

Katil gözleri dağlar yüreğim

Oturup karşımda dursun isterim

Ağ gibi sarmalayıp ruhumu

Uğruna yandığım o kadın sendin

Gözlerimi ayıramam üstünden

Her nereye gitsen bende peşinden

Kakülün altına gizlensen bile

Bakmaya doyamadığım o kadın sensin', 'Adı bende saklı hecelerimde Masum bir tebessüm yüzünde Şaşkın bakışlarım arar her yerde Alternatifi yok o kadın sendin Çillerin yüzünde al b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-kadin-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin Vapura', 'gittigin-vapura-ozan-turk-qolv4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çok içmiştim ardından

Ne öfkelenmiştim sana

Kaç şişe şahittir ayyaşlığımda

Sana yazmışlığıma

Ve kaç hüzün sahiptir sana

Ve hiç hatırlamadım seni

En az

Bir fincan kahve kadardı yani hatrın

O kadar umurumda değildin ki,

Öyle aklıma gelmiyorsun

Öyle boş vermişim ki seni

Hala,

Yakaladığımda binemem

Gittiğin vapura…', 'Ne çok içmiştim ardından Ne öfkelenmiştim sana Kaç şişe şahittir ayyaşlığımda Sana yazmışlığıma Ve kaç hüzün sahiptir sana Ve hiç hatırlamad...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gittigin-vapura-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salya sümük', 'salya-sumuk-ozan-turk-b1xgk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Salya sümük sevişmelerden çıktı,

Hamam suları bağlattı göğsüne,

Güneş O’na rest çekti,

Ay O olmadan gecemize gelmez oldu…

Salya sümük sevişmelerden geldi,

Bir daha açılmamaya yeminli bacakları,

Yıllanmış namusunun

Surları kesildi…', 'Salya sümük sevişmelerden çıktı, Hamam suları bağlattı göğsüne, Güneş O’na rest çekti, Ay O olmadan gecemize gelmez oldu… Salya sümük sevişm...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/salya-sumuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altı renk', 'alti-renk-ozan-turk-12g8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çaya şekeri sensiz atmak ne illet şey,

Her an bir acıyla yaşıyorum,

Adına yaşamak denirse bu hüsranın,

Yaşıyorum yaşlanarak…

Bir eli gökyüzünü gösterir gibi,

Bir eli seni,

Ve boyunları bükük duruyorlar,

Dalgalar akıyor içlerinden,

Bel ağrılarıyla kıvranıyorlarmış gibi,

Geriliyorlar 

Bu sabah İstanbul da,

Tüm beyaz yelkenler…

Ne kadar az kişi kaldı tabiat,

Ne kadar soluk bir renk oldu yeşil birden,

Gök kemerde

Altı renk hiç çekilmiyor…', 'Çaya şekeri sensiz atmak ne illet şey, Her an bir acıyla yaşıyorum, Adına yaşamak denirse bu hüsranın, Yaşıyorum yaşlanarak… Bir eli gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alti-renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç bir vapur yaramaz hiçbir denizi', 'hic-bir-vapur-yaramaz-hicbir-denizi-ozan-turk-9uj1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bir vapur yaramaz hiçbir denizi,

Barış Manço Gemisi’nin Marmara’yı yardığı gibi...

		

Manço,

Marmara’yı yara yara karşı kıyıya gidiyordu,

Ve sanki karşı kıyı artık benim memleket sınırlarıma girmiyordu...

Manço,

Marmara’yı yara yara karşı kıyıya gidiyordu,

Ve

O an deniz acaip bir hal alıyordu...

Sen,

Herzamanki gibi vapurun kıçına oturmuştun,

Bağdaş kurmuş çayının gelmesini bekliyordun,

Çayın geldi,sigaranı yaktın sonra,

Kıyıda kalmış cayır cayır bir bana...

Halbuki benim tercihim,

Vapur kıçlarında hep biradan yanaydı

Varsa konyak...

Manço,

Marmarayı yarmaya başlamıştı artık,

Benim,senin gözlerinde yavaş yavaş küçülme vaktim gelmişti...

Uzaklıştıkça uzaklaşıyor kaçıyordu vapur...

Uzaklaştıkça uzaklaşıyordun gözgöre göre

Ve,

Artık benim,senin gözlerinde yavaş yavaş bir nokta olma vaktim geliyordu...

Çayından son yudumunu,

Sigarandan son nefesini almıştın biliyorum...

Bense,

Senin sigaranın külleriyle,

İç acıtan cümleleri sonlardırmaktan kovuluyordum...

Siliniyordum...

Hiç bir vapur yaramaz hiç bir denizi,

Senin vapurunun,

Yardığı gibi denizimi...', 'Hiç bir vapur yaramaz hiçbir denizi, Barış Manço Gemisi’nin Marmara’yı yardığı gibi... 		 Manço, Marmara’yı yara yara karşı kıyıya gidiyordu...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hic-bir-vapur-yaramaz-hicbir-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar bir mahalleden geçti aşk', 'dar-bir-mahalleden-gecti-ask-ozan-turk-79w2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dar bir mahalleden geçti aşk,

Ağır adımlarla,

Aşkın garip yüzü belirdi mahallenin ağaçlarında,

Üstünde eski bir parka,

Cebinde on lirayla...

Kar yağıyordu aşkın üstüne,

Parmaklarının ucuna kadar,

Dondu aşk...

Tanrı misafiriydi,

Kafasını sokacak sıcak bir göğsü yoktu...

Dar bir mahallenin

Pezevenk kokulu sisinde öldü aşk,

Biraz boğularak,

Biraz donarak,

Cebinde on lirası vardı,

				

Ve üstünde eski bir parka

Güzel eylemlerden kalma

İstanbul’dan geçti,aşkın evladı,

Bir hışımla...', 'Dar bir mahalleden geçti aşk, Ağır adımlarla, Aşkın garip yüzü belirdi mahallenin ağaçlarında, Üstünde eski bir parka, Cebinde on lirayla......', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dar-bir-mahalleden-gecti-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Makinası', 'zaman-makinasi-ozan-turk-tdwni', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En özlediğim,

Ve hasretlendiğim,

Bir şarkıyı bile bulur bulmaz

Çevirip çevirip dinlerken ben,

Kimbillir ne olurdu

Bir zaman makinası olsa elimde...', 'En özlediğim, Ve hasretlendiğim, Bir şarkıyı bile bulur bulmaz Çevirip çevirip dinlerken ben, Kimbillir ne olurdu Bir zaman makinası olsa el...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zaman-makinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sen O -Biz Siz Onlar', 'ben-sen-o-biz-siz-onlar-ozan-turk-y9fvy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben; 

Acemi,

Sen; 

Heyecanım

O; 

Saygı duyulan,	

Biz; 

Suskun,üzgün,çaresiz,

Siz,

Mutlu,tasasız,dertsiz,

Onlar,

Şaşkın,izliyorlar...', 'Ben;  Acemi, Sen;  Heyecanım O;  Saygı duyulan,	 Biz;  Suskun,üzgün,çaresiz, Siz, Mutlu,tasasız,dertsiz, Onlar, Şaşkın,izliyorlar......', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-sen-o-biz-siz-onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyacağım', 'duyacagim-ozan-turk-cjyi7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gök bardaktan,

Boşaldı yağmur,

Gözlerimi aldı,

Esir gözlü,

Kör dinliyorum

Yağmurun ezgisini,

Göremedim

Meğer,

Bulutmuş resmimi çeken,

Çakan şimşeklerle,

Aniden,

Artık,

Tüm bulutlarım

Ve evren,

İnanacaklar benim kör olduğuma,

Ama düşünmüyorlar ki,

Her zaman,

En iyi duyanlar,

Körlerdir,

Duyacağım,

Fısıltılarını bile,

Duyacağım...', 'Gök bardaktan, Boşaldı yağmur, Gözlerimi aldı, Esir gözlü, Kör dinliyorum Yağmurun ezgisini, Göremedim Meğer, Bulutmuş resmimi çeken, Çakan ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/duyacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gencecik Mahkum', 'gencecik-mahkum-ozan-turk-dys08', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı aşk dalıydı dikenli,

Toy gençlikte yürekli coşku,

Çürür gibiydi parçalanarak,

Ümitsiz bezgin, çocuk

Değer yargılarının dört duvarında

Tutsak yerdeydi...', 'Kırmızı aşk dalıydı dikenli, Toy gençlikte yürekli coşku, Çürür gibiydi parçalanarak, Ümitsiz bezgin, çocuk Değer yargılarının dört duvarınd...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gencecik-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avcun', 'avcun-ozan-turk-7zbhd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiçbir yeri tanımadı ellerim,

Avcunun içi gibi,

Avcunu...

		

Gittiği gitmediği,

Kalıp kalmadığı,

Sevip sevmediği,

Öpüp koklamadığı,

		

Hiçbir yeri tanımadı ellerim,

Avcunun içi gibi,

Avcunu...', 'Hiçbir yeri tanımadı ellerim, Avcunun içi gibi, Avcunu... 		 Gittiği gitmediği, Kalıp kalmadığı, Sevip sevmediği, Öpüp koklamadığı, 		 Hiçbi...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/avcun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Güneşlenir', 'deniz-guneslenir-ozan-turk-8uz24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi denizden çıkan öykü,

Saçlarına almış bir tutam deniz,

Geldi,

Saçlarıma sıraladı damla damla,

Ve ben o an kör oldum,

Kızıl Öykü saçlarını ilk yüzme vurduğunda,

Ben daha çocuktum,

Ve merakla soruyordum ileriyi, her şeyi,

Şimdi saçlarında bir tutam deniz,

Bir serzenişli öykünün,

Öykü deniz,

Ben güneş,

Güneş kör,

Deniz güneşlenir…', 'Şimdi denizden çıkan öykü, Saçlarına almış bir tutam deniz, Geldi, Saçlarıma sıraladı damla damla, Ve ben o an kör oldum, Kızıl Öykü saçları...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deniz-guneslenir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz-Eski biz', 'biz-eski-biz-ozan-turk-gr2qf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonu gelmez bir yolculuktu bizimkisi,

Eski aşklar gergefinde,

Işık tutsada,

Simsiyah denizimize mehtabıyla aykız,

Biz eski hüsranların peşindeydik...

Şimdi biz yeni bir perdeye,

Demek istedekte merhaba,

Şimdi biz,

O eski biz değiliz...

Şimdi biz

Eski bizi izlemekte,

Eski biz

Bize gülmekte,

Deli miyiz

Divane miyiz', 'Sonu gelmez bir yolculuktu bizimkisi, Eski aşklar gergefinde, Işık tutsada, Simsiyah denizimize mehtabıyla aykız, Biz eski hüsranların peşin...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-eski-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Kısa', 'kisa-kisa-ozan-turk-i4r6b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En iyisi sen

Eskisi gibi

Aşklara giden yelkende beyaz ol

Bense renksiz rüzgar', 'En iyisi sen Eskisi gibi Aşklara giden yelkende beyaz ol Bense renksiz rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kisa-kisa-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Çizgi', 'kursun-cizgi-ozan-turk-ivztg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çizgi ne kadar düz olabilirse 

Benim en düzgün çizgim

Değil hayatım

Bir silgi ne kadar silerse kurşunu

Sen, kurşunla çizilmiş çizgimi

Silemezsin.

Senin silebildiğin çizgide sürüklenense

Sürüklenmiyordum güzel,

Yürüyordum önceleri

Ne kadar düz ise bir çizgi

Benim çizgim değil gözlerin

Benim kurşunla çizdiğim

Saçlarındır, kokusu burnumda

Bir çizgi ne kadar düz olabilirse

Benim en düzgün çizgim

Değil, değillerim

Bir silgi nasıl silerse kurşunu

Sen kurşunla çizilmişlerimi

Silemezsin…', 'Bir çizgi ne kadar düz olabilirse  Benim en düzgün çizgim Değil hayatım Bir silgi ne kadar silerse kurşunu Sen, kurşunla çizilmiş çizgimi Si...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kursun-cizgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim demiş unutamazsın', 'kim-demis-unutamazsin-ozan-turk-4rslc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşık olunca unutamazsın 

                                     derler

Ben unutuyorum seni,

Zor olmuyor seni görmediğim zamanlarda

çünkü,

ne zaman görsem seni

bir daha aşık oluyorum…', 'Aşık olunca unutamazsın                                       derler Ben unutuyorum seni, Zor olmuyor seni görmediğim zamanlarda çünkü, ne z...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kim-demis-unutamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı', 'marti-huseyin-kantar-5drv5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kirli bir camın arkasından 

coşkulu denize bakıyorum

bulanık suyun hırçın dalgaları

kendi ile yarışıyor adeta

bir yandanda motorun boğuk sesi,

o bir zaman özgür olan martıların çığlıklarına karışıyor,

rüzgar estikçe coşuyor deniz,

uçtukça uçuyor martı,

alıp götürüyor beni,

senden uzaklara', 'kirli bir camın arkasından  coşkulu denize bakıyorum bulanık suyun hırçın dalgaları kendi ile yarışıyor adeta bir yandanda motorun boğuk ses...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kantar']::text[], 8.5, '{"poet":"Hüseyin Kantar","poet_slug":"huseyin-kantar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/marti-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıncı Ay', 'altinci-ay-ozan-turk-naovg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baba aldı tabutu eline

bakıyordu,

Ana, ağlıyordu

Çocuk altı aylık 

ölüydü 

Baba aldı tabutu

Cenaze arabası yoktu

Çocuk bagajdaydı

Ana, ağlıyordu

Çocuk altı aylık ölüydü

baba, 

tabut, 

çocuk, 

ana, 

bakıyordu,

ağlıyordu,

altıncı aydı…', 'Baba aldı tabutu eline bakıyordu, Ana, ağlıyordu Çocuk altı aylık  ölüydü  Baba aldı tabutu Cenaze arabası yoktu Çocuk bagajdaydı Ana, ağlıy...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/altinci-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Kısa 2', 'kisa-kisa-2-ozan-turk-zh872', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırlarını yolladığın vakit hayata,

Ay kuşlarıyla,

Artık hayata karşı,

Hiçbir kozun kalmamış demektir.

Bende o kuşları yakalıyorum şimdi,

Dirensin diye insan hayata...', 'Sırlarını yolladığın vakit hayata, Ay kuşlarıyla, Artık hayata karşı, Hiçbir kozun kalmamış demektir. Bende o kuşları yakalıyorum şimdi, Dir...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kisa-kisa-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Kısa 3 (O Ada)', 'kisa-kisa-3-o-ada-ozan-turk-q9i6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zifirinde ışıldayan bir gemi var,

Limanda.

O gemi götürecek bizi,

Özgür kuşlarla

Özgür türkülerin söylendiği,

Ateş çemberi 

O

Adaya', 'Zifirinde ışıldayan bir gemi var, Limanda. O gemi götürecek bizi, Özgür kuşlarla Özgür türkülerin söylendiği, Ateş çemberi  O Adaya...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kisa-kisa-3-o-ada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerimiz', 'gunlerimiz-ozan-turk-rkt0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günlerimiz,

Bir kazanda,

Sabah,

Öğle,

Akşam,

Günlerimiz,

Bir kazanda,

Geçmiş yılların aynası,

Sıkıldım,

Aynı günleri içmekten,

Doydum...', 'Günlerimiz, Bir kazanda, Sabah, Öğle, Akşam, Günlerimiz, Bir kazanda, Geçmiş yılların aynası, Sıkıldım, Aynı günleri içmekten, Doydum......', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gunlerimiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan (Annem''in şiiridir eski bir kağıtta bulduk yarısını)', 'i-nsan-annem-in-siiridir-eski-bir-kagitta-bulduk-yarisini-ozan-turk-8q2ex', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan,

Dünya felsefesinde tek cevapsız soru

İnsan,

İnsanı anlamak, çözmek

Hele bir insanken

Sabah çık evden

Bak hele bir suratlarına

Kaşlar çatık

Gözler şiş

Küfre gerek yok

Dokunsan yeter cinayete ramak kalmasına

İnsan,

O büyük, o cevapsız insan

Hayat ne güzelde bulmuş cevabını

Bununla da kalmamış

Köle edinmiş insanı

İnsan,

Bak yüzüne 

Ellerine bak,

Yürüyüşüne

Ve nasıl kendi yarattığı bir robot oluşuna

Ve fark edememesine insan olduğunu

Ve sevgisini içindeki

Ve farklı olabileceğini

Gülebileceğini içten

İnsan,

Odur ki insan

Hayatın öğrencisi olmuştur

Yaratacakken hayatı…', 'İnsan, Dünya felsefesinde tek cevapsız soru İnsan, İnsanı anlamak, çözmek Hele bir insanken Sabah çık evden Bak hele bir suratlarına Kaşlar ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/insan-annem-in-siiridir-eski-bir-kagitta-bulduk-yarisini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul şiiri (Hani her şairde olan kadar - 17 de yazmıştım)', 'i-stanbul-siiri-hani-her-sairde-olan-kadar-17-de-yazmistim-ozan-turk-sh24e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul,

Biliyorum sende gizli

Mum ışığında

Denize dalıp uzun uzun

Tahta masalarda 

Kırmızı şarabın tadı

Bir sana mahsus biliyorum

Ve keman sesi ile 

Bir akşam yemeği boğazda

Yada

Bir sahil kenarında ayyaşça

Bir sende büyüsü tadın

İstanbul

Ve senin gölgende inmedi mi

En büyük aşklar

Senin ışıklarında değil mi? 

En gizli kaçamaklar

Ve ömrümün en hızlı,

En acımasız

En deli dolu ve içimi yakan

Sevgim

Senin isminin şehrinde kalmadı mı

Ölüm sessizliği içinde uğurlandı fırtına

Bembeyaz

Büyüsü sende gizli 

İstanbul…', 'İstanbul, Biliyorum sende gizli Mum ışığında Denize dalıp uzun uzun Tahta masalarda  Kırmızı şarabın tadı Bir sana mahsus biliyorum Ve keman...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-siiri-hani-her-sairde-olan-kadar-17-de-yazmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru(Düz yazı aslında)', 'soru-duz-yazi-aslinda-ozan-turk-evo2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkesin dediği kadar o ürkütücü ormana gidip korkmak,

O her aşığın aynı yerinde oturup aşık olmak,

Çok iyi bir insandının mezarına gidip ağlamak,

Bir orospu çocuğuyla  gerçekten tanışıp arkadaş olmak,

Kavgaya sebep bir şey mi hakikatte yoksa kıskanıldığından mı çıkar kavga bunu öğrenmek,

Ve bir saniye olsun insanların baktığı gözle bakmak sevişmeye,

Bir kızı nasılda tavlayıp eve attığımı anlatmak insan arkadaşlarıma,

Bir hoşça kal bile demeden çekip gitmeyi öğrenmek,

İlk kez gördüğüm biri bile olsa o an seni seviyorum diyebilmek,

Ve bir çocuk gibi binmek inmek kaygısıyla salıncaklara,

Ve sonra büyüdüm deyip racon kesmek millete,

		

Bilin bakalım hangisini istiyorum,

İnsan olmak mı? 

Yoksa umut fırınının kepenklerini indirdiği bu kentte ekmek olmak mı? ...', 'Herkesin dediği kadar o ürkütücü ormana gidip korkmak, O her aşığın aynı yerinde oturup aşık olmak, Çok iyi bir insandının mezarına gidip ağ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/soru-duz-yazi-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Kısa 4(Kendine İyi Bak)', 'kisa-kisa-4-kendine-i-yi-bak-ozan-turk-6xhps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki de hep başlamak istediğim hevesle,

		Ve hep neyselerle  bitirdiğim sen,

		Kendine iyi bak ben yokken...', 'Belki de hep başlamak istediğim hevesle, 		Ve hep neyselerle  bitirdiğim sen, 		Kendine iyi bak ben yokken......', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kisa-kisa-4-kendine-iyi-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahzuni Anısına', 'mahzuni-anisina-ozan-turk-tsrf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep mahzundu 

Mahzuni

Balık nasıl derdi,

     Nasıl ayrılamazsa denizinden 

		Mahzuni ayrılamaz  halkından.  

         Hep mahzundu Mahzuni Usta

Emekçi,yürekli aşık

Sevgi dolu 

Mahzundu.

Şimdi -di''li geçmişliğin

Çaresizliğinde,

Mahzunuz,

Mahzuni''siz,

Mahzunuz sevgisiz.

Mahzun kalacak Geleceğimiz,

Mahzun...', 'Hep mahzundu  Mahzuni Balık nasıl derdi,      Nasıl ayrılamazsa denizinden  		Mahzuni ayrılamaz  halkından.            Hep mahzundu Mahzuni ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mahzuni-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahil', 'sahil-ozan-turk-s61no', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuklar ne güzel koşar

Bilir misin? 

Sen düşünürken ne halt edeceğini

Çenen ellerinde,

Daha dün gibidir aşkı,

Dedenin nenene

Bilir misin? 

Sen sorgularken seni...

Hayat nasıl akıp gider

Bilir misin? 

Sen dururken öylece 

Sabit bir kayada...', 'Çocuklar ne güzel koşar Bilir misin?  Sen düşünürken ne halt edeceğini Çenen ellerinde, Daha dün gibidir aşkı, Dedenin nenene Bilir misin?  ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sahil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık', 'satilik-ozan-turk-84m25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Altmışbeş yıllık bir hayat,

En sonunda rahatladım,

Artık ya oturmalıyım evimde,

Yada uzanmalı en sevdiğim kanepeye,

Altmışbeş yılın sonunda,

Böyle olmadı dün gece,

Böyle olmadığı ortaya çıktı,

Dün gece,

Topkapı’da bu kentte,

Uzun ve karanlık sokakta,

Nöbeti bitmiş bir taksinin yanında,

Kıvrılmış bulundu,

Altmışbeş yıllık hayatın sonunda,

Bir cebi yırtıktı,

Diğer cebinden ise,

Bir kağıt parçası çıktı,

Açtılar baktılar,

Alamadığı ilaçların reçetesiydi,

Altmışbeş yılın reçetesi,

Ölmüştü,

		

Bu ölüm aniden gelmemişti,

Geleceği aylar öncesinden belli,

Hayatı aylar öncesinden,

Satılıktı...', 'Altmışbeş yıllık bir hayat, En sonunda rahatladım, Artık ya oturmalıyım evimde, Yada uzanmalı en sevdiğim kanepeye, Altmışbeş yılın sonunda,...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/satilik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çık Gel', 'cik-gel-ufuk-coban-ooo12', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni yalnız bırakma bitanem uzaklarda,

Hayatın adımları yaşanmıyor sensiz.

Gel gir yüreğime yalnız kalmıyor,

Nefes almıyor, gülmüyor, yaşamıyor.

Zamanı gelmedi mi artık kalk gel,

Gel ki eski yerine canım dönsün geri,

Hayat sensiz bir hiç anlamadın mı? 

Gel bu cana yarısı sende saklı.

Gözlerimde renk kalmadı yokluğunda,

Bakmıyor güneşin olmadığı yere,

Yetmedi mi sakladığın gülüşünü

Yeter artık son ver yaptığına.

Uzaklaştırma beni hayattan,

Umutlarımı karartma nefesinin ardından.

Bir ses de mi yok aşkımın adına,

Bu kadar kolay mı herşey sana.

Çık gel hasretin yollarından,

Gel sarıl bir kez vedanın ardından,

Sende bitti mi bu kadar sevdan? 

Çık gel istersen vazgeçsin bu can.

Beni öldür ama düşürme sevdamı ayaklara,

Sen kalmasan da bir parça bırak,

Ne istersen ol, ama gel birkez,

Gözlerimde son umut düşecek birazdan.

18/07/2005 22:45', 'Beni yalnız bırakma bitanem uzaklarda, Hayatın adımları yaşanmıyor sensiz. Gel gir yüreğime yalnız kalmıyor, Nefes almıyor, gülmüyor, yaşamı...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cik-gel-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Kısa 5', 'kisa-kisa-5-ozan-turk-wz4a5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir meşk ve sevda ile yaşamalı insan hayatı,

		Takdir-i İlahi yanlış koysa da kuralı...', 'Bir meşk ve sevda ile yaşamalı insan hayatı, 		Takdir-i İlahi yanlış koysa da kuralı......', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kisa-kisa-5-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Kanım Acıyor', 'kanim-aciyor-nurten-altinok-vr4rv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgunum

Taşıyamıyor artık sahte gülüşlerin yükünü yüzümdeki maske

Korkuyorum

Kaynak tutmayan belim ayrılıverecek bir gün orta yerinden ikiye

Gidiyorum 

Eser  kalmamış eski dönüş sevinçlerimden hiç birşey geriye

Hoş geldin diyenim

Şimdi kapı arkası kilitli odalarda 

Güle güle diyenim

Uzanıp da yatıvermiş kara topraklarda

Gidiyorum

Bir ben 

Umutlarını bahar dallarında solduran

Yorgun kadın 

Bir de ben

Yıkılmışlığımla güçlü görünmeye çalışan 

Vurgun kadın

Yorgunum

Yüzümdeki maske isyan ediyor artık sahte gülüşlere

Kanım acıyor…', 'Yorgunum Taşıyamıyor artık sahte gülüşlerin yükünü yüzümdeki maske Korkuyorum Kaynak tutmayan belim ayrılıverecek bir gün orta yerinden ikiy...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kanim-aciyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir deli özlem bu..', 'bir-deli-ozlem-bu-tutku-bakay-ehin0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlüyorum seni,

Yalansız bir özlem bu

Dolansız, saf bir özlem.

Yeni doğan bir çoçuğun

Minicik elleri gibi

Yumuşak ve mazlum

bir özlem bu...

Gökyüzü kadar büyük

Senin kadar yüce

bir özlem bu...

Hasretten ağlayanan sevdalıların

Yıllarca kavuşamayanların

İki gün bile dayanılamayan

bir özlem bu...

Ne yapacağini bilmeyen

Telefonlar bekleyen

Ağlayan, isyan eden

Kendisini harap eden

bir özlem bu...

Yolda yürürken

Otobüslere dört gözle bakan

Belki, onu görürüm diye

Kıpır kıpır yerinde duramayan

Salak salak, bos bos gezinen

Seni arayan bir özlem bu.

Bulutlara baktığında bile

Sanki seni göreceğini sanan

Orda olmadiğını bilen

Ama yinede şansını deneyen

bir deli özlem bu...

Yani güzelim,

Bir kalpsizi bile,

Ağlatabilecek,

bir deli özlem bu...', 'Özlüyorum seni, Yalansız bir özlem bu Dolansız, saf bir özlem. Yeni doğan bir çoçuğun Minicik elleri gibi Yumuşak ve mazlum bir özlem bu... ...', ARRAY['Türk Edebiyatı','Şiir','Tutku Bakay']::text[], 8.5, '{"poet":"Tutku Bakay","poet_slug":"tutku-bakay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-deli-ozlem-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik peri ve Serçesi', 'minik-peri-ve-sercesi-tutku-bakay-8kxvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlar, bulutlara aşkindan ağlar olmuş,

Bir gün ona dokunmak

Saniyelik bile olsa onun sıcaklığını

Hissetmekmiş tek hedefi..

Her gece, güneşin doğusuyla feryat yakmaya baslar,

Ona seslenişi her yeri sallar,

İçindeki sevda ateşi gün geçtikce büyür

Bazense patlarmış..

Biz insanlar bunlara doğa desek te; 

Milyonlarca yıldır bir aşk hikayesi

Sürüp gidermiş..

Bulutlar, her gün tüm zerafetiyle salarmış eteklerini,

Bilmezmiş dağların ona sevdalı olduğunu

Onun için her gün ağlayıp, özlemler çektiğini..

Onu unut demiş bir gün bir kara ağaç

Kavuşamazsın hiçbir zaman, birleşemezsin

O kadar yükseğe ulaşamazsın..

Ve bir gün eğmiş boynunu aşık dağ

Yaşlanmışta iyice..

Son kez bağırmış umutsuzca bulutlara

Seni Seviyorum…. seni seviyorum..

Susmuş..

Yıllar geçmiş artık, çökmüş yaşlı dağ

ölümü ister olmuş çoğu zaman

Onsuz yaşamaktansa, yok olmakmış

Her gece dilediği tek dua..

Soğuk bir şubat sabahı 

Bulutların arasından bir peri düşmüş

Dağın eteklerine..

O kadar güzelmiş ki

Yaşlı dağ etkilenmiş ve sormuş:

“Sen kimsin” diye,

Konuşmamış rüzgar saçlı peri,

Gülümsemiş ve ellerini dağın kalbine yaslayıp

“Bende Seni Seviyorum” demiş.

Yaşlı dağ, gözyaşlarını tutamamış bir an

Sarılmakmış tek istediği sevdalısına

Onu öpmek, saçlarını koklamak..

Tüm sevinci ve heyecanı bir anda yok olmuş,

Onun bir eli yoktu perisini sarsın

Bir başı yoktu ki dizine yatsın

Sadece bir kalbi vardı kimsenin bilmediği

Derinliğinde gizli..

Rüzgar Saçlı Peri, inmiş dağın eteklerinden kalbine

Yaşlı dağın, ağlamaları yeri göğü sarsıp

İçindeki ates her yeri yakmaktaymış.

Rüzgar Saçlı Peri, buldu dağın kalbini.

Ve bir bıçakla yardi kendi yüreğini,

Kalbini çıkartıp ikiye boldu,

Yarısını dağın sonu belirsiz karanlık uçurumuna bıraktı,

Sonra yere yığıldı güzel peri, ölüyordu..

Ama mutluydu..

Belki de o da sevmekteydi milyonlarca yıldır onu..

Koca dağın karanlığından bir serçe uçarak kondu perinin dudaklarına

Onun hareketsiz vücudunu yerde gördü,

Ve ağlamaya başladı, hıçkırarak..

Milyonlarca yılın özlem şarkısını söyleyip

Arada bir durup ona bakmaktaydı..

Serçenin gözyaşları, tekrar hayata getirdi periyi

Bir ödül dü bu yılların hasretine karşılık..

Peri, önce şaşırdı sonra ise serçeyi eline alıp

Bir öpücük kondurdu

Ağlamaktan kurumuş gagasına..

Dağ bir anda yerle bir oldu,

Bulutlar kayboldu..

Gecenin karanlığı, şimşeklerle gündüze dönüştü.

En parlak yıldızlar adlarını yazdı o gün gökyüzüne

Minik Peri

ve 

Serçesi..', 'Dağlar, bulutlara aşkindan ağlar olmuş, Bir gün ona dokunmak Saniyelik bile olsa onun sıcaklığını Hissetmekmiş tek hedefi.. Her gece, güneşi...', ARRAY['Türk Edebiyatı','Şiir','Tutku Bakay']::text[], 8.5, '{"poet":"Tutku Bakay","poet_slug":"tutku-bakay","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/minik-peri-ve-sercesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğin Bile Güzeldir Senin', 'sessizligin-bile-guzeldir-senin-tutku-bakay-nq5cq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessizliğin bile güzeldir senin,

Gözlerinin parıltısı, saçlarının hoyratlığı,

Yeter bazen bana…

Çayırda gezen bir ceylansın.! 

Ne aradığını bilmeyen..

Çoğu zamanda bir tavşan,

Ürkek, temkinli, atılgan..

Kaçarsın durmak istememecesine.

Bense bir serçeyim,

Özgürce kanatlarını çırpan

Savunmasız, sevgiyi arayan…

Masmavi denizlerin

Mercanları gibi..

Konuşmasan da duyarım içinde yankılananları,

Kalbinden geçen her şeyi.

Nefesin kadar yakınımdır sana,

Senden ayrı olduğum zamanlarda…

Kalbime dokunduğun zaman hissederim seni,

O an gözlerimi kapatır.! ,,

Melek olup yanına gelirim,

Sen beni göremesen de,

Ellerindedir Ellerim.', 'Sessizliğin bile güzeldir senin, Gözlerinin parıltısı, saçlarının hoyratlığı, Yeter bazen bana… Çayırda gezen bir ceylansın.!  Ne aradığını ...', ARRAY['Türk Edebiyatı','Şiir','Tutku Bakay']::text[], 8.5, '{"poet":"Tutku Bakay","poet_slug":"tutku-bakay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sessizligin-bile-guzeldir-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-tutku-bakay-6266u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum..

Gidiyorum belirsiz dunyalara

Bilmedigim diyarlara umarsizca

Sebebimle beraber gidiyorum

Yalnizligimla sarmas dolas.! 

Gelecegimi bilerek bir yerlere

Arkama bakmadan acimasizca

Olmayan bir yuvayi kurmak icin

Kendimi oldururcesine gidiyorum.! 

Gidiyorum..

Kimesinin beni tanimadigi diplere

Korkmadan hic cekinmeden

Cesaretimle gidiyorum

Tabutumla basbasa.!', 'Gidiyorum.. Gidiyorum belirsiz dunyalara Bilmedigim diyarlara umarsizca Sebebimle beraber gidiyorum Yalnizligimla sarmas dolas.!  Gelecegimi...', ARRAY['Türk Edebiyatı','Şiir','Tutku Bakay']::text[], 8.5, '{"poet":"Tutku Bakay","poet_slug":"tutku-bakay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gidiyorum-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başıda sonuda bir', 'basida-sonuda-bir-kaan-isik-ojmfg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'keşke tamamını yaza bilseydim', 'keşke tamamını yaza bilseydim...', ARRAY['Türk Edebiyatı','Şiir','Kaan Işık']::text[], 8.5, '{"poet":"Kaan Işık","poet_slug":"kaan-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/basida-sonuda-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-huseyin-kantar-pvifg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kısa mesafelerde koşmak

nefesin bitince durmak

yolun sonu bu

anneme verdiğim sözden uzak', 'kısa mesafelerde koşmak nefesin bitince durmak yolun sonu bu anneme verdiğim sözden uzak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kantar']::text[], 8.5, '{"poet":"Hüseyin Kantar","poet_slug":"huseyin-kantar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelirsin', 'sen-gelirsin-kaan-isik-260bg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmurlar yağar

Toprak kokusu kaplar 

Hafif rüzgar titretir dalları

Martılar ağlar

Sahipsiz kimsesiz kediler 

Sinerler sokak aralarına

Dünya yavaşlar

Güneş ağırdan alır 

İşine geç kalır

Ay fazladan çalışır

Senin gelmediğin gecelerde

Her şey her canlı

Güzelliğini verir

Masumiyetini sergiler

Doğa hazırlanır

Masumiyetle yıkanır

Sokaklar ağaçlar 

Gri ruhsuz binalar

Aralarından geçersin

Bir otobüs bir vapurdan 

Sonra bana doğru gelirsin

Seninle hareketlenir 

Güneş hızlanır 

İşine geç kaldığını anlar

Sen yürürsün sokak aydınlanır

Ay saklanır

Bulutlar siler göz yaşlarını

Martılar  bir vapur

Bir parça simitle güler

Kediler  sokak aralarından sıyrılır

Alımlı yürürler

Dünya hızlanır 

Sen gelirsin….', 'Yağmurlar yağar Toprak kokusu kaplar  Hafif rüzgar titretir dalları Martılar ağlar Sahipsiz kimsesiz kediler  Sinerler sokak aralarına Dünya...', ARRAY['Türk Edebiyatı','Şiir','Kaan Işık']::text[], 8.5, '{"poet":"Kaan Işık","poet_slug":"kaan-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-gelirsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet', 'adalet-ahmet-ziya-pektas-5r9ha', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hıçkırık tuttu zamanı.

Bir ileri, bir geri.

Yerinde sayıyordu sanki.

Gizlice yürüyormuş.

İşte o an anladım gerçeği.

Bir yalnızlık türküsü,

Çınladı kulaklarımda.

Beni benden alıp gitti.

Karalar bağladı sevdam.

Ölümüydü gönlümün.

Son gülüşüydü bekleyenin.

Uzaktan uzağa, son bir bakış fırlattı.

Gözlerimle buluştu bir an.

Başımla onayladım adaleti.

Adaletsizliğin adaletini onayladım.

Kimin ne olduğu belli.

Bense bu bozuk düzene,

Ayak uyduramayan bir kişi.', 'Hıçkırık tuttu zamanı. Bir ileri, bir geri. Yerinde sayıyordu sanki. Gizlice yürüyormuş. İşte o an anladım gerçeği. Bir yalnızlık türküsü, Ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/adalet-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım İşte', 'agladim-i-ste-ahmet-ziya-pektas-7b7uk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim,

Gözünüz aydın.

Sonunda oldu istediğiniz işte.

İstemeden oldu.

Ağlamak bu kadar,

Bu kadar mı lazım size? 

Ağladım işte,

Ağladım sonunda.

Görmesin anam, babam,

Görmesin kardeşlerim.

Sevdiğim görmesin beni.

Yanağımdaki incileri görmesin kimse.

Süzülüp düşüyor ardı sıra,

Ardı sıra düşüyor yaşlar.

Tutmak istesem de durmuyor,

Dinmek bilmiyorlar.', 'Gözlerim, Gözünüz aydın. Sonunda oldu istediğiniz işte. İstemeden oldu. Ağlamak bu kadar, Bu kadar mı lazım size?  Ağladım işte, Ağladım son...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agladim-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-ahmet-ziya-pektas-xgu0q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir karanlık çöker Karadeniz’e.

Üzgünlüğü yüzünden okunur güneşin.

Eder sevinci tahtından matem.

Ezik bir türkü çalınır kulaklarıma,

Kendimle vedalaşırım.

Umursamaz tavırları, çarparım duvara.

Seni ne çok sevdiğimi,

Giderken daha iyi anlarım.

Sızlar yüreğim inceden.

Koyverir kendini gözlerim.

Süzülür yanağımdan yaş.

Dilim dönmez veda sözüne.

Kalmak istese de yüreğim,

Alır götürür beni ayaklarım.

Titrer ellerim son kelimeyi yazarken.

Yazdığım tüm şiirleri yakarım tek tek.

Senden geri kalan ne varsa,

Silerim bir bir.

Asarım sensizliğimi.

Zamanı gelmiştir artık,

Al beni sonsuzluğa.

Gitmeye hazırım artık.

Hiçbir zaman benim olmayan,

Şu koskoca Dünya’dan,

Mutluluğu tatmadan.

Kirlenmiş düşüncelerle,

Ayrılmaya hazırım artık.

Geride düşünenlerim olmasın istiyorum.

Mutsuzluğumun mutluluğunu,

Doyasıya yaşamaya gidiyorum.', 'Bir karanlık çöker Karadeniz’e. Üzgünlüğü yüzünden okunur güneşin. Eder sevinci tahtından matem. Ezik bir türkü çalınır kulaklarıma, Kendiml...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/elveda-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-ahmet-ziya-pektas-4soqt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saatler geçti sensizliğimin üstünden.

Gözlerimde kuruyan yaş,

Dudaklarımda kalan,

Söylenmemiş sözlerden başka,

Değişen hiçbir şey yok şimdilik.

Her geçen dakika bir ızdırap,

Sonsuz bir ölüm bence.

Defalarca seni görmeye geliyorum.

Söyleyebilmek için sevdiğimi,

Gönlüne girmek istediğimi.

Cesaretimi yitiriyorum seni görünce.

Sızlayan yüreğime su serpiyorum.

Dindirebilmek için acısını,

Ve,

Unutturabilmek için sevdasını.

Daha beter seviyor seni.

Buram buram hasret kokuyor sevdam.

Hem yanımdasın, hem çok uzakta.

Öksüz bir geceye kurşun sıkmakta.

Kızaran yüzüme, ne olur hiç bakma.

Ben istemedim sevmeyi.

Gönül, şu gönül var ya,

Ağlatır insanı, hiç ağlamamış olsa da.', 'Saatler geçti sensizliğimin üstünden. Gözlerimde kuruyan yaş, Dudaklarımda kalan, Söylenmemiş sözlerden başka, Değişen hiçbir şey yok şimdil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gonul-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunluk', 'suskunluk-ahmet-ziya-pektas-a61q6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çırpındı yine Karadeniz.

Kıskançlığı ihanetin, özgürlüğü.

Beni alıp gitmeyen,

Saatlere küskünüm.

Çırpındı yine deli gönül.

Kırılmış kanadı özgürlüğün.

Seni bana getiren,

Rotasını şaşırmış gemi.

Zamanımı harcayan gar,

Ve hiç gelmeyen kara tren.

Solan kır çiçeğim.

Papatyam, menekşem,

Kadersiz kardelenim.

Size ne yaptım ben? 

Açı, susuzum ve zulüm.

Boynuma vurulan zincir,

Sefaletim bir ömür.

Hiç gelmeyen sevgili.

Umutsuzca bekleyiş.

Esirliğim,

Ve,

Mahşer günü.

Kurtuluştur bir zaman.

Yırtılır sonra en son sayfa.

Yakılır anılar.

Mazide kalanlar,

Bitip tükenmez acı.

Kapanır gönül pencerem.

Bir duba vurur kıyıya.

Parçalanır birkaç yüz.

Solar resimler albümlerde.

Ve,

Susar masumane tavırla,

Susar Karadeniz’im.

Bir daha konuşmamak kaydıyla.', 'Çırpındı yine Karadeniz. Kıskançlığı ihanetin, özgürlüğü. Beni alıp gitmeyen, Saatlere küskünüm. Çırpındı yine deli gönül. Kırılmış kanadı ö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/suskunluk-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda', 'yagmurda-ahmet-ziya-pektas-i7r3p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurla beraber yürüyorum.

Hep seni düşünerek.

Sevdamın verdiği acıyı,

Ta içimde hissederek.

Sonsuz bir uzaklığı hayal ediyorum.

En uzak noktanın başında,

Seni beklemek.

Sevmek doyasıya, kendini özleterek.

Dakikalar geçiyor.

Sensizliğimin ardından.

Tenime kadar işliyor yağmur.

Aşk ateşiyle yanan yüreğimi,

Hafifletmek ne demek,

Körüklüyor habire.

Memleketimi düşünüyorum bir an.

Memleket yağmurlarını.

Avunmaya çalışıyorum.

Sensiz geçen günlerime yanıyorum.

Yağmurda kol kola yürümek.

Birlikte ağlayıp, birlikte gülmek.

Sevda kolyelerimizi takmak.

Hiç çıkarmadan ölmek.

Atıp bir kenara yalnızlığımı,

Seni sevmek var ya,

Doyasıya seni sevmek.', 'Yağmurla beraber yürüyorum. Hep seni düşünerek. Sevdamın verdiği acıyı, Ta içimde hissederek. Sonsuz bir uzaklığı hayal ediyorum. En uzak no...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yagmurda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilık Su ve Bayatlamış Ekmek Tadında Hayat', 'ilik-su-ve-bayatlamis-ekmek-tadinda-hayat-melih-coskun-gmokg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ilık su ve bayatlamış ekmek tadında hayat

Biriktirip de söyleyemediklerim gibi 

Çok özleyip de yaşayamadıklarım gibi

Korkusuz gözlerle bakabilirim artık her şeye 

Kırılacak yeri kalmadı kalbimin diğer zulümlere

Kurtuldu sen kelimesi bütün tekilliğinden 

Hepiniz 

Hepiniz birden gelin üzerime...

Çektim şiirimden o sesi 

Dağıldı kelimelerim bir bir 

İskeleti sökülmüş gibi 

Her parçası yeni bir hayata 

Her parçası yeni bir sevdaya vursun diye,

Tadına varmak için yaratmanın 

Ve yeniden varolmak için 

Kendimi yokluktan sayarken. 

Hiçbir kafiye yakışmadı bu kadar hiçbir şiire

Hiçbir söz bu kadar güzel tarif edemedi güzelliğini 

Bir ömrün sebebiydi seni sevmek

Ve şair olmaktı anlatabilmek seni...

Seni sevmek; 

Susmamak demekti ilelebet 

Ağzımı bıçak açmadığı zamanlarda bile

Gözlerimle de olsa anlatabilmek. 

Kazımak ıssızlığın ortasına adını 

Sonra susmak 

İzlemek seni

Ellerini, yüzünü 

İzlemek bakışlarına vuran o imkansızlığını.

Kahkahaların bile 

Bıçak yarası gibi kanadığı bir günde anladım ki

Düşlerde acıtır insanı.

Ilık su ve bayatlamış ekmek tadında gelirken üzerime hayat

Hala bir sebebi vardır yaşamanın

Hala sevilecek birileri vardır 

Ve hala bir dava vardır uğruna ölünecek...', 'Ilık su ve bayatlamış ekmek tadında hayat Biriktirip de söyleyemediklerim gibi  Çok özleyip de yaşayamadıklarım gibi Korkusuz gözlerle bakab...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ilik-su-ve-bayatlamis-ekmek-tadinda-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madenciler 4', 'madenciler-4-mehmet-halil-7fgj3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ocakların kapısında tabela,

Madencilerin yürekleri asılı,

‘’ekmek yediğin kaba sıçma’’

Madencinin yüreğine aşılı.

Bu onları işe alırken yazıldı

Madenci,

O kara kayaları,

Bir insanı tanıdığı kadar tanıyordu

‘’kara hava’’ dedikleri zehirli hava

İşte orada kıvrılmış yatıyordu.

ciddiyetle keder bir olmuşlar

Madencinin suratına oturmuşlar.

Madende sıkışan gaz da,

İninde sıkıştırılmış kurt gibi,

Üstlerine atlamaya hazırdı.

Gel anlat bunu patronlara,

Gel anlat bunu patronlara.

Onları işe alan gözlerine bakıyordu,

İşe değil, bu gün riske sokuyordu,

aldıran yok teknik raporlara

Sana,  ekmek veren eli ısırma,

Yüreklerde tabela asılı.

Verilen ekmek ölüme karşı.

Madenciler,

Çaresizlik ve umut içinde

Ya açlık, işsizlik, ya ölüm,

Umutları sadece bir mucize,

Midelerine saplanmış bir olta,

Döne döne çekiyordu madene.

Burada savaş yasaları geçerli,

Ölüm var diye savaştan dönülmez

Savaşta binlerce kişi ölüyor

Ölümün önüne geçilmez.

Madencinin  gözlerinde panik

Madende ölüme değer verilmez

Ve grüzo patlar o vardiya da,

Kıyılır yüzlerce cana.

Rapor istenir.

‘’Can kaybı varmı? ’’ denilmez

‘’Ayak kapandımı’’ diye sorulur.

ayak kapanınca kömür üremez.

Ölenin yerine yenisi bulunur.

madenciden vazgeçilir, 

madenden vazgeçilmez.

şunu bil ki

Yanan her kömür tozu,

Bir madencinin ruhu.', 'Ocakların kapısında tabela, Madencilerin yürekleri asılı, ‘’ekmek yediğin kaba sıçma’’ Madencinin yüreğine aşılı. Bu onları işe alırken yazı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/madenciler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Ölüm', 'sensizlik-olum-mehmet-bicik-72jsy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılığına katlanmak, ölümden zor.

Hayatım tükeniyor acıyla, elemle..

Sensiz yüreğim yanıp kavruluyor,

Ellerini arıyorum en sıcak düşlerimle,

Nedir çektiğim acılar gel de bana sor..

Tükenip gider sensiz kahrolası zaman.

Uzaklardayım şimdi senden çok uzak..

Gayri yan baba hasretiyle, sen de yan.

Çözülmez ne yapsan da kurulan tuzak,

Ellerim ellerinden çok uzak olduğundan..

Bakma minik kuşum gelir diye yollara,

İçim can atıyor ama gelemiyorum sana..

Ciğerimi parçalama gidip başka kollara,

İnan sensiz olmak ölüm geliyor bana,

Kendimi yakarım vermem seni yâd ellere..

12 Şubat 2002, Kırca', 'Ayrılığına katlanmak, ölümden zor. Hayatım tükeniyor acıyla, elemle.. Sensiz yüreğim yanıp kavruluyor, Ellerini arıyorum en sıcak düşlerimle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-olum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-mehmet-bicik-fuolh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gül vardı,

Öpüp kokladığım…

Bir gül vardı,

Kokusuna doyamadığım…

Bir gül vardı,

Bir de ben…

Şimdi:

Gül de yok,

Ben de yokum…

13 Kasım 2001, Burhaniye', 'Bir gül vardı, Öpüp kokladığım… Bir gül vardı, Kokusuna doyamadığım… Bir gül vardı, Bir de ben… Şimdi: Gül de yok, Ben de yokum… 13 Kasım 20...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gul-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütün', 'tutun-mehmet-bicik-6nx76', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadehimde içki

Aklımda yâr…

Gönülde 

Eski sevdâlar…

Başımdan 

Eksik olmaz belâlar…

Takabamda tütün,

Sar, Allah’ım, sar…

Ahsen’siz, ah sensiz

Dünyada benim ne işim var? ..

13 Şubat 2002, Kırca', 'Kadehimde içki Aklımda yâr… Gönülde  Eski sevdâlar… Başımdan  Eksik olmaz belâlar… Takabamda tütün, Sar, Allah’ım, sar… Ahsen’siz, ah sensiz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tutun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Vermek İçin', 'askimi-vermek-i-cin-hatice-bediroglu-p5wwl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş kızıla kesmiş

Kaybolurken dağın ardında

Ateş gibi yanan yüreğimi de

Alıp götürür yanında

Anında laciverde döner

Uçsuz bucaksız denizin rengi

Hırslanmış dalgalar

Ha babam döver kıyıları

Kucaklarken geceyi

Koyu karanlıklar

İçimizde

Sevdanın gözleri ağlar

Dolaşırken

Yalnızlığın acı hüznü

Iğıl ığıl damarlarımızda

Bir bekleyiştir başlar

Sonrasında

Güneş

Yeniden doğmayı bekler

Sevdiğini

Sıcacık sarmak için

Deniz sabahı bekler

En güzel mavileri

Sevdiğine sunup

Serin sularında ağırlamak için

Ben sabahı beklerim

Yüreğim elimde

Aşkımı

Sana vermek için

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Güneş kızıla kesmiş Kaybolurken dağın ardında Ateş gibi yanan yüreğimi de Alıp götürür yanında Anında laciverde döner Uçsuz bucaksız denizin...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/askimi-vermek-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülçin Torunoğlu''na Geç Kalan Konuşma', 'gulcin-torunoglu-na-gec-kalan-konusma-firat-turan-tx3fa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geç kalmışlığımdı,beni hep hatıralarla bağlı kılan.

Kopamadım hiçbir anıdan,

Veremedim belki de bu yüzden; 

Yüreğime yük ettiklerimi geleceğe.

Paylaşalım şimdi seninle tüm kozlarımızı,

Bilirim kızgınsın bana,

Yani,şu mantığının yılmaz savunucusu,

Belki de sence ''işgüzar'',

Belki de korkak adama.

İlk  Konuşma; 

Paylaşalım şimdi seninle tüm kozlarımızı,

Sen ve ben! 

Hazırmısın yüreğimdeki ince sızı? 

Ama önce sen beni dinle.

Duy; 

Konuşmak isterdim ben ırmaklar gibi.

Hiç engelsiz değil ama hep özgür.

Ne olur anla; 

Kayıp bir şehrin,sessiz sokakları gibiydim.

Ama biliyorum loş bir  mapusu andırıyordum sana,

Ve bendim bu algıya sebep,

Çünkü paylaşamadığım her aşk dörtlüğü için,

Bir çentik atmıştım sende saklı yarama...

Cevaben; 

Şimdi benim sıram,

Benim ben; yüreğindeki ince sızı.

Dinle beni! 

Mantığının yılmaz savunucusu korkak adam.

Ne söylememi istersin? 

Aşk denen ırmakta sürüklenmemi engelleyen,

O taptığın mantığının dallarına mı kızayım,

Yoksa sana,sessiz sokaklarında o kayıp şehrin,

Örselenmiş bir yüreğin öyküsünü mü yazayım? 

(18.07.2005-01.08.2008)', 'Geç kalmışlığımdı,beni hep hatıralarla bağlı kılan. Kopamadım hiçbir anıdan, Veremedim belki de bu yüzden;  Yüreğime yük ettiklerimi geleceğ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Turan']::text[], 8.5, '{"poet":"Fırat Turan","poet_slug":"firat-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gulcin-torunoglu-na-gec-kalan-konusma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir gibi', 'siir-gibi-hekim-coskun-d61yd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir şiir gibi

hani herkesin söylemek isteyip te söyleyemediği türden

kelimeler herkesin dudaklarına kadar gelir de bir türlü söylenemeyen

mutlu anlarda bir hoş olur ya insan	

ya...

ne bileyim işte.	

mesela çok güzel bir akşam üstü; 

güneş daha yeni sıcaklığıyla terk etmiş beni ve bizi,

hafiften bir esinti var diyelim.

ha üşüdük, üşüyecek kaygılarımız da yok,

nasıl olsa yarın yeniden doğacağını bildiğimizden olsa gerek,

dilimin ucunda ama bir türlü söyleyemiyorum! 

ya…

hani sevgi gibi aşk gibi,

özlem gibi.

seni seviyorum değil! 

bu başka bir şey.

tabiî ki seviyorum…

bir söyleyebilsem.

şiir gibi bir şey, 

diyelim ki; ; her şey,sen, ben, biz.

yalnızlığımız kalabalıklara karışmış,

yığınlar halinde hep bir ağızdan söylemek istiyoruz,

dilimizin ucunda…

ama söyleyemiyoruz.

ya ne bileyim işte,

şiir gibi bir şey! 

mesela; 

yine bir akşam üstü güneş yokluğunu hissettirmiş,

ama yarın yeniden doğacağının rahatlığı içindeyken biz,

ben, sen ve herkes gibi.

hani kelimelerin yetersiz kaldığında,

bir şiir gibi! 

ya…

bildiğin gibi değil! 

tabiî ki, seviyorum, aşığımda.

bu bir şiir gibi, dilimin ucunda,…

ben, sen, biz, herkes gibi.

kalabalık bir mutluluk içindeyiz,

hep bir ağızdan,

dilimizin ucunda bir şiir gibi.

dünya bir yana demediğimiz! 

umursadığımız her şey.

bende varım içinde,

sende varsın,

börtü böcekte,

ama her şey…

ne var ne yok her şey.

ya..

ha.! ! ! ? ? ? 

oda değil.

şiir gibi bir şey.

………………….

…………………..', 'bir şiir gibi hani herkesin söylemek isteyip te söyleyemediği türden kelimeler herkesin dudaklarına kadar gelir de bir türlü söylenemeyen mu...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/siir-gibi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-firat-turan-ql0cj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ince çizgi sevda,

Düş ile gerçek arasında.

Bir infaz belki de,

Soğuk bir mapus damında.

Mısralarla aklanan bir kağıt,

Ya da bilemiyorum bu sevdaya değil de,

Sensizliğe ağıt....

(10.02.2002)', 'Bir ince çizgi sevda, Düş ile gerçek arasında. Bir infaz belki de, Soğuk bir mapus damında. Mısralarla aklanan bir kağıt, Ya da bilemiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Turan']::text[], 8.5, '{"poet":"Fırat Turan","poet_slug":"firat-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört yeminim var...', 'dort-yeminim-var-zafer-zengin-etnika-yw525', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

I.

yürüyen yapraklar

hayatın dilinden konuşur

bakışmak düzlem ‘üstünde

açıp ellerini ‘kendine

dualarla

sövgülerle

yıkmak bir yanlarını

tepeden dibe

dipten başlarsan

çöker üstüne

duyarsın acını

feryadını

anlarsın

ağlarsın

II.

dört yeminim ‘vardı

adını bildiğim ‘kitaplarda

dördüne et’tim

kesilen  eldim

III.

şarabın gölgesinde ‘rengim

ve ne zaman ‘bir ah duysam

hayat ‘derim

sanaydı büyüttüğüm ‘çiçeklerim

dilinin ucuyla ‘kesmeseydin

keşkelerimi ‘sevmezdim

IV.

git’tim

adı öyle kal’dı

olmamıştı

büyümeye atılmıştım

atıldığımda  kal’dım

anlayın işte

üst üste yığ’ıldım

sağ’ıldım

bur’dayım

bıyığımda ‘baş parmağım

rengimi anlatır ‘dövmelerim

kollarıma kazımışım

avucumu sormayın

yangında kül ‘is’de kalanım

V.

gidiyorum

hoş kalınız ‘bayım ‘bayanım

insanlığı dinleyeceğim ‘gece

sabaha yine buradayım

dar alnım ‘dokunmayın

uyanırsam ‘çocuk ağlarım

ve sonra

memeleri dudağımdan ‘almayın

dört yeminimi ‘sus’a kazıyın

bırakın ‘koparmayın

duruyorum

VI.

olmadım

sus’a çok varım

o anlayanım

anlattığım

dört yemini ‘dışta bıraktım

iç’te elim 

dar(a) dayım

dört yeminin yalın  ‘kal’(an) ıyım

sırayım

V.

ses

bekler

içimde

dört yeminim var

etmedim kimseye

bile

bile

24 05 2005

.', '. I. yürüyen yapraklar hayatın dilinden konuşur bakışmak düzlem ‘üstünde açıp ellerini ‘kendine dualarla sövgülerle yıkmak bir yanlarını tep...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/dort-yeminim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma şekeri...', 'elma-sekeri-zafer-zengin-etnika-4wwdn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

elma şekeriyle

seni  kan''dırdım

üstünde bıyıklarım olmasa

anlamazdın

ve mesela

bir daha

daha

/renk kopar karıştığında

dışım şeker

iç''im çeker

çekirdek düşer

sap dalımdan gider

/ vaktidir düşmenin ''huzura

seni kandırdım

bıyığımın altıyla

ağlaya ağlaya

ağlasın diye

iki ölçek

gözyaşı bırakıyorum  tanrıya

ak''lı elma şekerinde ''hala

saçları okşanmamışya

/bahsi geçen yalnızlık

en çok 

çekirdeğini sevdim iç''in''in

dişimle taştım

taş kesilip 

içinde yanmıştım

taştan mezarlar yaptım

azı sana

birazını tanrıya sakladım

/kim ölecek önce meraktayım

elma şekeri bendim

aklandım

 zaten  ''ölmekten anlamazdım

anlamadığımdan ''korkardım

/ burası bana

göz geçer  ''kırmızı

sızımdan

kül sarar an''ı

sızımı anlamayı

güldürüyorken milyonları

sızım gülmeyen

unutanlardı

elma şekeri

rengiyle hayatı boyardı

bu yüzden tanrı

en çok çocuklara satardı

elma şekeri; ben öl''düm

şiire saklayın iç''imi

sonra rüzgara ısmarlayın

al''ın hayın...

30 01 2005 '' kopan dumanlara  '' 

.', '. elma şekeriyle seni  kan''dırdım üstünde bıyıklarım olmasa anlamazdın ve mesela bir daha daha /renk kopar karıştığında dışım şeker iç''im çe...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/elma-sekeri-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci', 'i-kinci-aysun-erat-3e5o4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En çok, kendimi seviyordum senden önce.

Şimdi, kendimden çok seni…

Hayret! 

Kim derdi ki? 

Pabucumu dama atacağım bir gün.

Aslında…

Çok bozuluyorum içten içe, bu işe.

Ama,

Yine de olgunluğu elden bırakmıyorum.

Demek kaderde, ikinci olmak da varmış.

Dünya hali işte! 

Ne yaparsın? 

Buna da alışacağım zamanla.

Sakın! Benim için üzülme.

Daha çok nasıl sevilirsin sen? 

Bana onu söyle.

07/2005', 'En çok, kendimi seviyordum senden önce. Şimdi, kendimden çok seni… Hayret!  Kim derdi ki?  Pabucumu dama atacağım bir gün. Aslında… Çok bozu...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ikinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Malı Var', 'baba-mali-var-suheyl-turkoglu-as5qv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uçan kuşa,

Kelebeğe,

Denize batan,

Güneşe,

Hayranlığım var.

Kan bağında,

Yalancı gülüşe,

Düşman kardeşe,

Sönük güneşe,

İsyanım var,

Düşman gibi,

Kardeş kardeşe,

Çözülmüş gönül bağı,

Paylaşılamayan,

Baba malı var.', 'Uçan kuşa, Kelebeğe, Denize batan, Güneşe, Hayranlığım var. Kan bağında, Yalancı gülüşe, Düşman kardeşe, Sönük güneşe, İsyanım var, Düşman g...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/baba-mali-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil Kokulu Aşk', 'karanfil-kokulu-ask-dilek-ozdemir-lzwlw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kemanın yorgun ezgilerinde 

boşluğa bakarken gözlerim

ve bitti derken sözlüğümdeki kelimeler

ve düşlerken ölümümü üstüne basa basa yalnızlığın

kuşlar bensiz uçuyordu

Bir şimşek çakışıyla aydınlandı dünya

kabuslu bir gecenin sabahında

Karanfilin ağırbaşlı kokusuydu

çok uzaklardan gelip beni bulan

ve yavaşca dokunan omuzuma

O an değdi ilkbahar alnıma

İçimde yeşeren sebepsiz sevinçler

karanfil kokuyordu

Umutların soluğu dolandı boynuma

ve varlığında kahpe hayatı bağışladım 

ve kefensiz gömüldü acılarım

Karanfil kokarken dünya 

kuşlar ellerime konuyordu

Buyur dedim

Buyur yüreğime karanfil kokulu aşk

hoş geldin, getirdin safalar

sen bana gençliğimden yadigar', 'Bir kemanın yorgun ezgilerinde  boşluğa bakarken gözlerim ve bitti derken sözlüğümdeki kelimeler ve düşlerken ölümümü üstüne basa basa yalnı...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karanfil-kokulu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimlesin', 'benimlesin-ahmet-ziya-pektas-2j7oa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir duygudur, sarar seni.

Kararır düşüncelerin.

Korkularınla baş başa kalırsın bir an.

Yalnızlığın seni ne denli,

Etkilediğine şaşarsın.

Günlerin,

Hep birilerini aramakla geçer.

Bir an, bulduğunu sanırsın.

Seni de arkandan vurur,

Bitirir seni kahpe felek.

Bir kanser gibi sarar bedenini ihanet.

İşte o an,

Lanet edersin yaşadığına.

Ölümü içinde tatmak istersin.

Kin beslersin her şeye.

Mazini hatırladıkça,

Gözlerin yaşla dolar.

Küfredersin zalimlere.

Gözyaşı verenlere küfredersin.

Günden güne erirsin.

Erirsin mum misali.

Bitip tükendiğini sandığında,

Kendi kendine yettiğini anlarsın.

İçine bir mutluluk çöker.

Seni ne çok sevdiğimi anlarsın.

Rahatla yalnızlığım rahatla.

Seni benden başka seven yoktur.

İçindeki fırtınayı,

Benden iyi bilen yoktur.

Rahatla sevdiceğim.

Sevgimi sana vereceğim.

Artık yalnız değilsin.

Bundan böyle benimlesin.', 'Bir duygudur, sarar seni. Kararır düşüncelerin. Korkularınla baş başa kalırsın bir an. Yalnızlığın seni ne denli, Etkilediğine şaşarsın. Gün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/benimlesin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet Birgün', 'elbet-birgun-ahmet-ziya-pektas-s17a8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçaklardan sarkan,

Buz kütleleri arasında dolaşır ruhum.

Bir kar tanesi düşer alnıma.

Akar gözlerim, eriyen kar misali yanağıma.

Bir çiçek arar ellerim,

Uçsuz bucaksız beyaz örtüde.

Kaybolan çiçeklerin hayaline dalarım.

Sonra,

Sonra bir garibin zemheriye yenik düştüğü,

Yenildiği günü hatırlarım.

Ayağında eski postal ve yırtık bir gömleğiyle,

Zincirler haşin bir sevdayla onu kendine.

Uzanır garip, tutar sevdanın ellerini.

O an,

Gök, deniz birleşir.

Sessiz bir karanlık çöker üzerine.

Bir rüzgâr eser uzaklardan.

Denizin oğluna, denizden çağrı gelir.

Artık dönmelisin kendine.

Bir bulut iner gökten yere.

Bir kıvılcım çakar garibin gözlerinde.

Sonra,

Bu acılar bitmeyecek bilirim.

Yırtar ellerim, 

Bir düş kadar gerçek kapkaranlık geceyi.

Bu irin çölleri üzerinde açacak,

Elbet bir gün açacak kardelenler bilirim.', 'Saçaklardan sarkan, Buz kütleleri arasında dolaşır ruhum. Bir kar tanesi düşer alnıma. Akar gözlerim, eriyen kar misali yanağıma. Bir çiçek ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/elbet-birgun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir Misin?', 'gelir-misin-ahmet-ziya-pektas-esi5i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gençtim, ihtiyarladım.

Tutmaz oldu bacaklarım.

Susadım, çok susadım.

Bir yudum su verir misin? 

Yalnız kaldım bu alemde.

Gelenim yok, gidenim yok.

Yiyemem ki, aşım soğuk.

Isıtmaya gelir misin? 

Sırtımda yırtık palto.

Postallarımsa delik.

Ciğerimde kahpe soğuk.

Giydirmeye gelir misin? 

Ahşap evim, kirli rafım,

Bir de eski anılarım var.

Gözlerim yaşla dolar.

Avutmaya gelir misin? 

Bir şeyim yok, her şeyim var.

Güzel günler geride yar.

Mezarlıkta bir taşım var.

Ziyarete gelir misin?', 'Gençtim, ihtiyarladım. Tutmaz oldu bacaklarım. Susadım, çok susadım. Bir yudum su verir misin?  Yalnız kaldım bu alemde. Gelenim yok, gideni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelir-misin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-ahmet-ziya-pektas-wusb6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arabacı beni de bekle.

Alacak son bir eşyam kaldı.

Kapatacak son bir bavulum.

Sonra gidebiliriz bu şehirden.

Sessiz bir şekilde ayrılalım.

Duyulmasın gidişimiz.

Acılarla dolu göğsüm.

Gözyaşı görmek istemiyorum.

Camı açma sakın.

Bu şehrin havasından bıktım.

Bıçak gibi kesiyor yüreğimi.

Ve, sevdamı siliyor daha beter.', 'Arabacı beni de bekle. Alacak son bir eşyam kaldı. Kapatacak son bir bavulum. Sonra gidebiliriz bu şehirden. Sessiz bir şekilde ayrılalım. D...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidelim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-ahmet-ziya-pektas-4b9nh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum gideceksin.

Bırakıp bizi kendimizle baş başa.

Bir daha görüşemeyeceğiz belki.

Vatanın iki ayrı noktasında,

Aramıza girecek nice mesafeler.

Bilmem ki ne demeli şimdi.

Oturup sensizliğe ağlamalı mı? 

Kuruyuncaya kadar gözyaşları.

Yahut,

Gülmeli gidişinin şaşkınlığına.

Atmalı kendini bir boşluğa.

Sensizliğimi yakmalı belki.

İçimdeki acıyı koparıp atmalı.

Nafile değil mi güzelim, nafile.

Biliyorum intikam alıyorsun.

On ayrılık boyu aramayışıma.

Sen de ağlatmak istiyorsun beni,

Ağladığın o günlerin acısına.

Yanılıyorsun gülüm, gerçekler böyle değil.

İnan aradım seni yoruluncaya kadar.

Telefon başında uyudum kaç gece.

Kaç gece sabahladım uğruna,

Kesilinceye kadar telefonun sesi.

Sonunda anladım yalnızlığın,

İçimdeki korkunç çığlığını.

Kaleme sarıldım geceleyin.

Yoruluncaya kadar yazdım,

Tükeninceye kadar inan.

Unutmadım seni hiçbir zaman.

Her anımda sen vardın.

Gündüzümde gecemdeydin.

Ulaşılmaz düşümdeydin.

Geldim sonunda sana.

Bitirmek için özlemeyi,

Öldürmek için yalnızlığı.

Gidiyorsun şimdi sen, gidiyorsun.

Ölmüş yalnızlığımı, tekrar diriltiyorsun.', 'Biliyorum gideceksin. Bırakıp bizi kendimizle baş başa. Bir daha görüşemeyeceğiz belki. Vatanın iki ayrı noktasında, Aramıza girecek nice me...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gitme-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem Kaçtı', 'golgem-kacti-ahmet-ziya-pektas-rb04b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bıraktı beni hain.

Yarı yolda bırakıp kaçtı.

Şu yaralı gönlüme,

Bir çizikte o attı.

Çekip yüreğime hançeri,

Defalarca sapladı.

Ta içime işledi,

Soğukluğu hançerin.

Kalbimin derinliklerinden,

Fışkırdı feryat.

Kuşlar bile ağladı bana.

Aç kurtlar gibi,

Üşüştü başıma ihanet.

Acımadan parçaladı,

Dağıttı yüreğimi dört bir yana.

Her düşen parça bir filiz oldu.

Yeşertti beni yeniden.

Boy gösterdim, geliştim.

Sensiz de olsa,

Kavuştum bedenime.

Yarım da olsa tattım mutluluğu.

Yine de, unutmadım ihanetini.

Gidişini unutmadım.

Yalnızlığım, sensizliğim.

Canımdan çok sevdiğim.

Habersizce kaçtı benden.

Eşim, kara benzerim.

Gölgem kaçtı.', 'Bıraktı beni hain. Yarı yolda bırakıp kaçtı. Şu yaralı gönlüme, Bir çizikte o attı. Çekip yüreğime hançeri, Defalarca sapladı. Ta içime işle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/golgem-kacti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-ahmet-ziya-pektas-7p13q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve,

Gün gelir uyanır,

Daldığı düşten Karadeniz.

Elinden alınan sevdasını,

Arar kıyılarda.

Köpürür ve indirir hançeri.

Yırtar geceyi soluksuz.

İnler tepeden tırnağa gökyüzü.

Ağlar yalansız bulutlar.

Kabarır Karadeniz nefretle.

Erir martıların çığlıkları dalgalarda.

Örtülmüş kıyılardaki sevdasını,

Aralar dalgalarıyla.

Yavaşça çeker kendine.

Kurtaracağı zamanı,

Bekler sabırla.

Saniyeler asır gibidir.

Geçmez bilmez zamansız.

İndirir şah damardan nefreti.

Katmer güllerinin açtığı kıyılar,

Diretir.

Denizime karşı koyar.

Bırakmaz elindekini.

Köpürür denizim yeniden.

Martılar saldırır kıyıya,

Uçsuz bucaksız.

Yutar kıyıları yavaşça nefret.

Usulca çeker kendine.

Tam kavuşacağı an,

Sevdanın ihaneti çarpar yüzüne.

Saldırgan duygularını yırtar.

Suskunluğa adım atar yeniden.

Artık anlamıştır gerçeği.

Ölüm ile yaşam arasında,

Sevda denen kavrama,

Kör kütük bağlanmak boşuna.', 'Ve, Gün gelir uyanır, Daldığı düşten Karadeniz. Elinden alınan sevdasını, Arar kıyılarda. Köpürür ve indirir hançeri. Yırtar geceyi soluksuz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ihanet-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-ahmet-ziya-pektas-vczgi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kardelenim.

Güzel nazlı çiçeğim.

Neden boynun bükük duruyor senin? 

Şu koskoca dünyada,

Yalnız kaldınsa bileyim.

Karı delip görünmen,

Herkesi nekadar mutlu ediyor, bir bilsen.

Sen baharın müjdecisi,

Mutluluklara açılan penceresin.

Bukadar sevildiğin halde,

Niçin boynun bükük senin.

Hayat felsefenin değişmesinin nedeni ne? 

Yoksa,

Senide mi dostların vurdu sırtından? 

Senide mi aldattılar,

Maneviyatsız bir değer uğruna.

Yaptığın işten sıkıldıysan eğer,

Bana kulak ver.

Çünkü,

Ben de arkadaşsızım senin gibi.

Yalnızlığın ne olduğunu ben de bilirim.

Ver elini senle dost olalım.

Boynumuzu kaldırıp,

Dünyaya,

Olabildiğince özgür bakalım.', 'Kardelenim. Güzel nazlı çiçeğim. Neden boynun bükük duruyor senin?  Şu koskoca dünyada, Yalnız kaldınsa bileyim. Karı delip görünmen, Herkes...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kardelen-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimisi', 'kimisi-ahmet-ziya-pektas-nspvj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hamaldır yük taşır kimisi,

Kimisi çocuğunu taşır sırtında.

Lahana taşır, Pazı, Karayemiş taşır sırtında,

Ekmeğini kazanır kimisi.

Kimisi ailesini taşır sırtında,

Hayata yenik düşmemek için, çalışır kimisi.

Kimisi dünyayı taşır sırtında.

Altında ezilmemek için, kalın tutar ensesini.

Kimisi feleğin sillesini taşır,

Kimisi namusunu.

Kimisi namussuzluğunu taşır sırtında.

Kimisi hiçbir şey taşımaz sırtında.

Onun taşıdığı tek şey,

Avareliğinin ve tembelliğinin verdiği yüktür.

Onu bile zor taşır ya sırtında.', 'Hamaldır yük taşır kimisi, Kimisi çocuğunu taşır sırtında. Lahana taşır, Pazı, Karayemiş taşır sırtında, Ekmeğini kazanır kimisi. Kimisi ail...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-ahmet-ziya-pektas-4xd74', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi nedir, bilir misin küçüğüm? 

Nasıldır,

Neye benzer, bilir misin? 

Sevgi,

Kardeşliktir, mutluluktur.

Çıkarcı olmayan dostluklar,

Unutulmayan arkadaşlıklardır.

Sevilenin yanında,

Sevenin kendini bulmasıdır.

Toprakta yeşeren bir filiz,

Gül dalında açan bir goncadır.

Gökyüzünde,

Özgürce kanat çırpmaktır.

Sevgi sensin küçüğüm.

Sözlerin, gülüşün ve bütün hareketlerin.

Sevginin kıymetini bil küçüğüm.

Henüz sevgisizliği tatmadan.

Lakin,

Büyüdüğünde hiç bulamayabilirsin.

Yinede unutma ki küçüğüm,

Sevgi,

Yenecektir bir gün sevgisizliği.', 'Sevgi nedir, bilir misin küçüğüm?  Nasıldır, Neye benzer, bilir misin?  Sevgi, Kardeşliktir, mutluluktur. Çıkarcı olmayan dostluklar, Unutul...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kucugum-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Şiiri', 'mutlulugun-siiri-ahmet-ziya-pektas-x68oq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitti artık gönlümün dayanılmaz acısı.

Hasretin bağrımdaki çekilmeyen acısı.

Karanlık geceleri gündüzlere çeviren,

Gündüzü unutup karanlıkla eğlenen.

Sensiz geçen her gecem, dakikam.

Efkârla muhabbeti koyulaştırıp,

Hasrete gebe şiirlerin yazıldığı saatler.

Ürkek dakikaların beni tükettiği anlar.

Bitti.

Kâh hırçın bir deniz olup saldırdığım kıyılar,

Kâh eski bir oyunu oynadığım sahneler.

Yağmurla dertleşip ağladığım saatler,

Sonra,

Birden gözümde beliren hayalin.

Ben yaklaştıkça, senin kaçtığın.

Düşlerimin hasretle yoğrulduğu saatler.

Sigarayla başlayan çile günlerinin,

Beni tutsak eden köleliği.

Bitti.', 'Bitti artık gönlümün dayanılmaz acısı. Hasretin bağrımdaki çekilmeyen acısı. Karanlık geceleri gündüzlere çeviren, Gündüzü unutup karanlıkla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutlulugun-siiri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Anlatsam', 'nasil-anlatsam-ahmet-ziya-pektas-hdw1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana nasıl seslensem.

Sesimi nasıl duyurabilsem uzaklara.

Kuşların gittiği yöne ben de,

Ben de sesimi bıraksam.

Takılıp kuşların kanadına,

Bir umutta olsa,

Belki ulaşır gelir sana.

Ne içim, ne dışım.

Artık anlatacak bir şeyim yok gibi.

Anlatamadığım yüreğimi açsam sana.

Açsam yüreğimi,

Sıcacık avuçlarına bırakıp,

Susmanın tadına varsam.

Dudaklarımdan düşmeyecek kelimeler.

Avuçlarına bıraktığım kalbim,

Kalbimin sana özlemini dinleyeceksin.

Seni nasıl sevdiğini,

Ecele bile gülerek geçtiğini,

Mutluluğun en güzel şiirini,

Sensizliğin acı bestesini dinleyeceksin.

Sensiz çıktığım yolların,

Izdırap veren uzunluğunu.

Aç bir midenin,

Gönül tokluğunu dinleyeceksin.

Ta başlangıçtan ele alıp mutluluğu,

Zerre zerre işleyeceksin.

Yaşanmışları tekrar yaşayacaksın.

Yaşanmamış yıllarımıza daha sıkı,

Sımsıkı sarılacaksın.

Sensiz geçen her günün,

Başıboş sarhoşluğunu.

Saatlerin bitmez tükenmez,

Tören geçişini izleyeceksin.

Ve yüreğim.

Seni delicesine seven,

Şu gariban ve de mesut yüreğim.

Sürekli ayrılık darbesiyle sarsılıp,

Yine de,

Hasrete gem vuracak kadar,

Güçlü ve dimdik ayakta.

Senin için her şeyin iyisini,

En mükemmelini dileyen,

Her şeyden kıskanan şu kalbim.

Yine, 

Sana çarpmaya devam edecek.

Yine deli gibi sevecek.

Ve,

Öyle bir dile gelecek ki kalbim.

Hiç bitmeyecek gibi anlatacak.

Yorulup ta sustuğu an,

Son bir söz,

Son bir söz daha duyacaksın dilinden.

Ölümüne sevdiğim, ölsem de seninleyim.', 'Sana nasıl seslensem. Sesimi nasıl duyurabilsem uzaklara. Kuşların gittiği yöne ben de, Ben de sesimi bıraksam. Takılıp kuşların kanadına, B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/nasil-anlatsam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan Bahar', 'unutulan-bahar-ahmet-ziya-pektas-7af54', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fışkırdı bahar toprağın bağrından.

Bak,

Nisan yağmurları yağıyor artık.

Görünür güzellikler, kapalı kapılar ardından.

Kaç bahar daha geçecek böyle habersiz.

Biz kaçıncı baharı yaşayacağız.

Bir bahar daha akıp gidiyor elimizden.

Bir bahar daha kışa uzatıyor ellerini.

Ve,

Bir kış daha, ezip geçiyor baharı bağrından.

Söyle,

Neden biz de gülleri kucaklamıyoruz? 

Neden Nergis’e değmez burnumuz? 

Kuş cıvıltılarını, neden duymaz olmuşuz? 

Kışa sarılmış bir kez ellerimiz.

Vay beni, vay, vay.

Biz baharları unutmuşuz.

Zemherileri arşınlamakla,

Bir zemheri olup çıkmışız.', 'Fışkırdı bahar toprağın bağrından. Bak, Nisan yağmurları yağıyor artık. Görünür güzellikler, kapalı kapılar ardından. Kaç bahar daha geçecek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unutulan-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver Ellerini', 'ver-ellerini-ahmet-ziya-pektas-ocrk6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklenen bahar gelirse bir gün,

Açmayan çiçekler açacak o gün.

Bir tutam sevda yeşerecek çöl ortasında.

Susuz kalmış bir pınar, saldıracak kurağa.

Acımasız bir hançer gömülecek pınara.

Nefret ile kin ile.

Bölecek pınarı bir baştan bir başa.

Pınarın sustuğu yerde bir filiz yeşerecek.

Yeşerecek sessizce hançere inat.

Hançerler sevdalarla yok edilecek.

Sevdaya sevda ile sarılmak.

Kırılan bir güle yaşamayı anlatmak.

Sevdalara yaşayıp, sevdalara ölmek.

Karanlık zindanları, gül bahçesine çevirmek.

Sevdasız sevdaya, sevdayı öğretmek.

Yahut,

Soldurmak gönülde açan gülleri.

Açmayan güllere hesap sordurmak.

Bir kalbi deşmek derinlemesine.

Sineye çekmek olup bitenleri.

Suskunlukla susturmak dökülen incileri.

Dinleyen gözlerde oluşan büyük nefreti,

Masum bir çift gözle izlemek.

Bu mu? 

Bu mu be kardeşim sevda kılıcı? 

Bu mu yenecek nefret hançerini? 

Biz böyle günlere doğmadık mı? 

Ölüm fermanımız yazılmadı mı? 

Böyle saatlere.

Ver güzel ellerini, gülümse.

Savaşımız nefret ile.

İki büyük sevda, iki büyük can,

Canlandıralım sevdayı,

Yürekteki kor ile.', 'Beklenen bahar gelirse bir gün, Açmayan çiçekler açacak o gün. Bir tutam sevda yeşerecek çöl ortasında. Susuz kalmış bir pınar, saldıracak k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ver-ellerini-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ahmet-ziya-pektas-a8fcy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sıkıcı günlerden biri daha geçiyor.

Ben, yine yalnızlığımla baş başayım.

Allah’ım! 

Nedir bu çektiklerim? 

Bu ızdırap, bu çileler neden? 

Bir gün olsun gülemeyecek miyim ben? 

Yaşamın monotonluğu içinde kıvranıyorken,

Hayat çizgimin kısaldığını hissettim birden.

Kalbim kırık, gözlerim üzgün.

Toz pembe bir dünya içinde,

Siyah-Beyaz yaşıyorum günbegün.', 'Sıkıcı günlerden biri daha geçiyor. Ben, yine yalnızlığımla baş başayım. Allah’ım!  Nedir bu çektiklerim?  Bu ızdırap, bu çileler neden?  Bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizligim-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjdeler verin.', 'mujdeler-verin-i-shak-ozlu-csvei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deryaya yakın uçan canım kuşlar,

Eşlik etsin size güzel bulutlar,

Müjdeler verin yolum gözleyene,

Geliyorum dinsin gözünde yaşlar.

Yunus balıkları öncünüz olsun,

Kanadınıza sonsuz kuvvet dolsun,

Selam söyleyin yolcu bekliyene,

Varışınızla muhabbbeti bulsun.

Akşam kızılı denize vurmadan,

Uçun kuşlar uçun yolda durmadan.

Müjdeler isteyin geliyor deyin,

Sevdiğim özlemle size sormadan.', 'Deryaya yakın uçan canım kuşlar, Eşlik etsin size güzel bulutlar, Müjdeler verin yolum gözleyene, Geliyorum dinsin gözünde yaşlar. Yunus bal...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mujdeler-verin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5.Mevsim', '5-mevsim-gulseren-onay-z204a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dört mevsim biliyorum; 

Sonbahar, kış,

İlkbahar, yaz...

Beşincisi de varmış...

Öğretti aşkın...

Bir görüşte 

Yaşattı yüreğime 

Her mevsimden biraz...

GÜLSEREN ONAY

19/07/2005/ANTALYA', 'Dört mevsim biliyorum;  Sonbahar, kış, İlkbahar, yaz... Beşincisi de varmış... Öğretti aşkın... Bir görüşte  Yaşattı yüreğime  Her mevsimden...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/5-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Yüzbaşı', 'sahte-yuzbasi-ali-dilki-iq41e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'On yedi kırk beşte içeri girdi

Şöylece bir baktı kerizi gördü

Hepimize sanal bir eşya verdi

Bizi dolandırdı sahte yüzbaşı

Tunay krediden çekti bir buçuk

İbo sıkıntıdan dudakta uçuk

Hepimiz dinledik ağzımız açık

Bizi dolandırdı sahte yüzbası

Şeref para için evine gitti

Beni de olayın içine itti

Halit çok geçmeden telefon etti

Bizi dolandırdı sahte yüz başı

Anladı içerde çok imiş armut

Üstümüzden geçti kara bir bulut

Bir sazan misali zıpladı Mahmut

Bizi dolandırdı sahte yüzbaşı

Fevzi dört yüz milyon geldi yatırdı

Bal diye sirkeye parmak batırdı

O gün bütün herkes şapa oturdu

Bizi dolandır sahte yüzbaş

Herkes marakından çıldırıyordu

Zeki hep çayları dolduruyordu

N e kimse danıştı ne kimse sordu

Bizi dolandırdı sahte yüzbaşı

Demekki hepimiz avanak böndü

Gittiğiğmiz yolsa hep aynı yöndü

Ben de gol yiyordum direkten döndü

Bizi dolandırdı sahte yüzbaşı

ALİ der; yıldızı arması vardı

Bizi makaraya sarması vardı

Israrla üstünde durması vardı

Bizi dolandırdı sahte yüzbaşı.

Bizim Anadolu Gazatesi

06. 06. 2004  Sayı: 12767', 'On yedi kırk beşte içeri girdi Şöylece bir baktı kerizi gördü Hepimize sanal bir eşya verdi Bizi dolandırdı sahte yüzbaşı Tunay krediden çek...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sahte-yuzbasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğanlı', 'soganli-mevlut-i-hsani-mawfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğanlı dağların yüceden yüce,

Methine nihayet yoktur netice,

Güzelsin baharın,yazın gelince,

Cevherdir toprğın,taşın soğanlı.

Sürüler her yandan gelirler sana,

Suların soğuktur,benzer dermana,

Adın dağılmıştır senin her yana,

Var mıdır bir yanda eşin soğanlı.

Bir yanın ovadır, bir yanın orman,

Yavuz, Sultan Murad okumuş ferman,

Sana feda ettik doksan bin kurban,

Dumanlı, savaşlı başın soğanlı.

Baharında yaylalar, yurtlar geniştir,

Sana Enver Paşa kanlı demiştir,

Nice yaralını kurt, kuş yemiştir,

Başından geçeni düşün soğanlı.

Mevlüt İhsaninin yadigarından,

Usanmadım dumanından, karından,

Çok güzeli ayırmışsın yarından,

Bellisiz baharın, kışın soğanlı..', 'Soğanlı dağların yüceden yüce, Methine nihayet yoktur netice, Güzelsin baharın,yazın gelince, Cevherdir toprğın,taşın soğanlı. Sürüler her y...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt İhsani']::text[], 8.5, '{"poet":"Mevlüt İhsani","poet_slug":"mevlut-i-hsani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soganli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-mevlut-i-hsani-x7yky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyanın dönüşü kudretin sırrı

Işılır gün doğar döner akşamlar

Her saatin ayrı ayrı rengi var

Dağlara siyah tül iner akşamlar

Ara garip yalcu pınarı baştan

Su sesi geliyor karşi yamaçtan

Süzülür dereye çakıldan taştan

Eşsiz gelin gibi iner akşamlar

Karşiki yaylada çobanın mali

Bir yırtık keçesi birde kavali

Bir yaban tezegi bir kuru çali

Ufaktan ataşi yanar akşamlar

Aldandın dünyanın bilmem nesine 

Mevlam neler koymuş kudret tasına

Koyun yavrusuna kuş yuvasına

Çırpına çırpına döner akşamlar', 'Dünyanın dönüşü kudretin sırrı Işılır gün doğar döner akşamlar Her saatin ayrı ayrı rengi var Dağlara siyah tül iner akşamlar Ara garip yalc...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt İhsani']::text[], 8.5, '{"poet":"Mevlüt İhsani","poet_slug":"mevlut-i-hsani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aksamlar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Vah Hey', 'hey-vah-hey-mevlut-i-hsani-8eo4o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derdimi ne diyem döktüm yaşımı

Ağrı gibi duman aldı başımı

Her nere gidersem koymaz peşimi 

Hasretlik sinemi dağlar hey vah hey

Mevlüt ihsaniyem bu derdim daim

Gönlümün virane bağlarındayım

Hayatın ne karlı dağlarındayım

Bırakmaz aşayım dağlar hey vah hey

Mevlüt ihsaniyem yoktur idaram

Sinem göz göz oldu belirsiz yaram

Dertlerim yaş ile dosta maceram

Söylersiz sırrımı dağlar hey vah hey', 'Derdimi ne diyem döktüm yaşımı Ağrı gibi duman aldı başımı Her nere gidersem koymaz peşimi  Hasretlik sinemi dağlar hey vah hey Mevlüt ihsan...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt İhsani']::text[], 8.5, '{"poet":"Mevlüt İhsani","poet_slug":"mevlut-i-hsani","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hey-vah-hey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir demet hoşgörü', 'bir-demet-hosgoru-i-shak-ozlu-za82y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen diyorsun illa ki ben ben ben,

Ben diyorum hayır ben ben ben,

Ben sen olmayacagıma göre sende ben,

Az sen gel birazda ben olalım bir beden.

Yok aslında birbirimizden farkımız,

Aynı amaç için çalıyor şarkımız.

Bir demet hoşgörü,az sayğı ve bir tutam sevği,

Katıversek nakarata çalar bizim türkümüz..', 'Sen diyorsun illa ki ben ben ben, Ben diyorum hayır ben ben ben, Ben sen olmayacagıma göre sende ben, Az sen gel birazda ben olalım bir bede...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-demet-hosgoru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehid''in Feryadı', 'bir-sehid-in-feryadi-ekrem-sama-rozl4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Engel olmak için biz, alevden o sele,

Süngümüzü kuşandık, çektik de besmele,

Kurtuldu vatan, namus, Kuran ve istikbal,

İmanın şahlandığı, yerdir Çanakkale! 

Ey tarih! Dile gel de, açık açık anlat,

Neler uğruna şehit, oldu bunca evlat? 

Şehitler çimentodur, vatan toprağında,

Kanları solmayacak, şanlı bayrağında,

Şehidi şehit yapan, değerler bilinsin,

Yarınlar kaybolmasın, kültür tuzağında! 

Ey tarih! Şüphelendim, doğrusunu anlat,

Bizleri anlıyor mu, bu günkü genç evlat? 

Alaylar şehit oldu, uğruna tevhidin,

Görmek mi istersiniz, cephelere gidin! 

Künyeleri taştadır, ölen düşmanların,

İsmi bile bilinmez, şu kadar şehidin! 

Ey tarih! Sebebini, gel açıkça anlat,

Çanakkale Şehidi, niçin üvey evlat? 

İşgalciye yapılmış, abide ve mezar,

Kaçanların taşında, hep ''kahraman'' yazar,

Silahla alamadı, ölüsüne verdik,

Torunlarıysa şimdi, Türk''e mezar kazar...

Ey tarih! Ben şaşkınım, biliyorsan anlat,

Bizi vuranlar nasıl, bize olmuş evlat? ! ..

(İstanbul:19.07.2005)', 'Engel olmak için biz, alevden o sele, Süngümüzü kuşandık, çektik de besmele, Kurtuldu vatan, namus, Kuran ve istikbal, İmanın şahlandığı, ye...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-sehid-in-feryadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Küçük Kalbim Var', 'bir-kucuk-kalbim-var-ufuk-coban-bm6r5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir küçük kalbim var, göründüğü gibi olmayan,

Sığdırdığım herşeyimi okyanuslara sığmayan.

Dışında öyle bir sur var ki onu koruyan,

Yalandan, ihanetten ve sevgisiz kalmaktan.

Bazen bana yetmez, daha çok sevdikçe seni,

Fazlası sığmaz kalbime, sarar bedenimi.

Ellerim, gözlerim, ele verir sevgimi,

Ben belli etmesem de, onlar söyler ne kadar sevdiğimi.

Her atışında söyler sen yoksun,

Yalnızlığına çare arar, kim bulsun? 

Herşey yavaş yavaş beni terk ediyor, ama olsun,

Bir küçük kalbim var, al o da senin olsun.

1999', 'Bir küçük kalbim var, göründüğü gibi olmayan, Sığdırdığım herşeyimi okyanuslara sığmayan. Dışında öyle bir sur var ki onu koruyan, Yalandan,...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-kucuk-kalbim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İstemedim Kızım', 'ben-i-stemedim-kizim-mehmet-bicik-ztb4p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben istemedim kızım

Senin boynu bükük kalmanı,

Gönülden yaralanmanı,

Acılara dalmanı,

Kızım ben istemedim…

Kızım ben istemedim

Oyuncaksız büyümeni,

Buruk buruk gülmeni,

Ezilip büzülmeni,

Ben istemedim kızım…

Ben istemedim kızım

Sensiz geçen zamanı,

Sana acınarak bakılan ânı,

Toplumdan dışlanmanı,

Kızım ben istemedim…

Kızım ben istemedim

Sevgisiz bir hayat sürmeni,

İnsan öğüten değirmeni,

Ölmeden mezara girmeni,

Ben istemedim kızım…

Ben istemedim kızım

Hayatın kararsın,

Mutluluğa hasret kalasın,

Gözlerin başka çocuklarda olsun,

Kızım ben istemedim…

Kızım ben istemedim 

Sensizliği,

İlgisizliği,

Sevgisizliği,

Ben istemedim kızım…

Ben 

Seni istedim kızım.

Ben hep seni istedim…

19 Temmuz, 2005 Salı

Burhaniye 07:55', 'Ben istemedim kızım Senin boynu bükük kalmanı, Gönülden yaralanmanı, Acılara dalmanı, Kızım ben istemedim… Kızım ben istemedim Oyuncaksız bü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-istemedim-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burak', 'burak-ahmet-agdere-x0o1y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün burak, sevgilimden bir yonca getirdi 

Akşamüstü, göz pınarlarımdan içirdi 

Dağıttı, mil çekilen şehrin bulutlarını 

Eski günlerin hatrına, yüreğinden geçirdi', 'Bugün burak, sevgilimden bir yonca getirdi  Akşamüstü, göz pınarlarımdan içirdi  Dağıttı, mil çekilen şehrin bulutlarını  Eski günlerin hatr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/burak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya sevgili ol', 'ya-sevgili-ol-yusuf-koc-g3ej7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görünüp gidiyorsun bir anda,

ağustosta esen meltem gibi,,

iz bile bırakmıyorsun arkanda,

boşa geçmiş uzun yıllar gibi...

         yoruldum artık yalan dillerden,

         ya  sevgili ol bana, ya da uzak dur benden...

gel diyorsun en sıcak sesinle,

bir sadık evcil gibi geliyorum..

sanki oyun oynuyorsun benimle,

gözlerinde aldırmazlığı görüyorum...

        bıktım artık bir gel bir git demenden,

        ya sevgili ol bana ya da uzak dur benden...

çaktığında yıldırımlar ağlıyorsun,

loş ışıkta büzülmüşsün köşeye..

bir kurtarıcı gibi sarılıyorsun,

sonra boşveriyorsun herşeye,,,

         yetti tamam ayrıl artık köşenden,

         ya sevgili ol bana ya da uzak dur benden...

iyi adamsın diye avutuyorsun,

yalanlar sıralanıyor dilinde...

bıkınca varlığımdan yüz asıyorsun,

kasırga estiriyorsun her seferinde...

          bitti artık, usandım bana ceza vermenden,

          ya sevgili ol bana ya da uzak dur benden..!', 'Görünüp gidiyorsun bir anda, ağustosta esen meltem gibi,, iz bile bırakmıyorsun arkanda, boşa geçmiş uzun yıllar gibi...          yoruldum a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Koç']::text[], 8.5, '{"poet":"Yusuf Koç","poet_slug":"yusuf-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ya-sevgili-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-dilek-alesoy-fycdp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tam da bitecekken hüznü ayrılığın,

Yenisi çıktı karşımıza

Acının.

Daha kaç yüzü var hüznün

Tanımadığımız.

Çekilir mi bu dert,

Geçer mi zaman sancısız? 

Daha kaç vakit bekleriz kim bilir,

Vuslatı! ! ! 

                                 (29.01.2005)', 'Tam da bitecekken hüznü ayrılığın, Yenisi çıktı karşımıza Acının. Daha kaç yüzü var hüznün Tanımadığımız. Çekilir mi bu dert, Geçer mi zaman...', ARRAY['Türk Edebiyatı','Şiir','Dilek Alesoy']::text[], 8.5, '{"poet":"Dilek Alesoy","poet_slug":"dilek-alesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vuslat-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevda Nedir Bilir misin?', 'sen-sevda-nedir-bilir-misin-huseyin-erdogan-914b3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen sevda nedir bilir misin? 

hiç uyuyamadığın oldu mu geceleri? 

bir dakika bile gözlerini kırpmadan 

hiç sabahı ettin mi benim gibi? 

yüreğinde hiç hissettin mi aşkın ateşini? 

gözlerinden anladın mı delice sevildiğini? 

sen yüreğimde rengarenk açan bir çiçeksin

yılın dört mevsimi yaz olsa da hiç solma sakın

gönlümde gece gündüz uçan bir kelebeksin

her geçen gün bana biraz daha olmalısın yakın

sana aşık olmak ne de güzelmiş meğer

seni sensiz yaşamak ise ölümden bile beter

benim de yüzümün gülmesini istersen eğer

ne olursun bir gün bizim buralara çıkıp geliver

                                               19.07.2005', 'sen sevda nedir bilir misin?  hiç uyuyamadığın oldu mu geceleri?  bir dakika bile gözlerini kırpmadan  hiç sabahı ettin mi benim gibi?  yüre...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-sevda-nedir-bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Olmak', 'siir-olmak-gulsen-gonenc-ra4ke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başın dizlerimde,

Sen yine şiirler oku,

Kan kokanlardan; 

Okurken titresim dizlerim.

Sonra bir tane de vanilya kokandan; 

Uyuyalım.

Rüyada

Sen ben ol,

Ben de sen.

Hiç uyanmayalım, şiir olalım.', 'Başın dizlerimde, Sen yine şiirler oku, Kan kokanlardan;  Okurken titresim dizlerim. Sonra bir tane de vanilya kokandan;  Uyuyalım. Rüyada S...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siir-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalinde susmuşsa', 'hayalinde-susmussa-gulseren-onay-cvct2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umursamam 

Gecenin yalnız karanlığını...

Geceler hep yalnızdır.

Hayalinin

Suskunluğu ürkütür beni...

GÜLSEREN ONAY', 'Umursamam  Gecenin yalnız karanlığını... Geceler hep yalnızdır. Hayalinin Suskunluğu ürkütür beni... GÜLSEREN ONAY...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayalinde-susmussa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Konuşması', 'askin-konusmasi-caglar-asik-ycs3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlar taç edilmiş, o güzel başlara.

Güneş yollanmış, o etkileyici bakışlara.

Süpernovalar patlamış, aşkla gönül uzayına.

Kana kana, alsın gönlünü bırak sende o uzaya.

&

Aşıkın yüreği derindir, yanar hep harlaya harlaya.

Aşık benzemiş patlayacak yıldıza, bir süpernovaya.

Dağılabilmek için, sevgiyle, aşkına gönül uzayına.

Acele et, uçuver sevdiğine, sonsuz gönül aşkına.

İstanbul - 19.07.2005', 'Yıldızlar taç edilmiş, o güzel başlara. Güneş yollanmış, o etkileyici bakışlara. Süpernovalar patlamış, aşkla gönül uzayına. Kana kana, alsı...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askin-konusmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım Yalnız Kaldı', 'yalnizligim-yalniz-kaldi-isik-aktas-1ia52', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özleminin sarhoşluğu

                   yalnızlığımı acıtıyor.

yüreğimden adın geçti,

kulağımdan sesin,

yalnızlığım yalnız kaldı.

nirvanayım şimdi ben,

adım; sonsuzluk,

yok oluyorum,

su,

hava,

rüzgar.

yüreğim fırtına,

içim çağlayan,

ben sonsuzluk.

yüreğimden adın geçti,

kulağımdan sesin.

bilir misin ki o ben''im.

yalnızlığım yalnız kaldı.

yalnızlığım

yalnız

kaldı...

              16.07.2005/Cumartesi 20.40 Çağlayan', 'Özleminin sarhoşluğu                    yalnızlığımı acıtıyor. yüreğimden adın geçti, kulağımdan sesin, yalnızlığım yalnız kaldı. nirvanayım...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizligim-yalniz-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte o benim', 'i-ste-o-benim-mehmet-isikoglu-x14se', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İŞTE O BENİM

Her dala et atmış emek sarfetmiş

Eller yararına yollar kat etmiş

Zararı ziyanı sineye çekmiş

Birisi var ise işte o benim

Ömrünü harcamış gezmiş dolaşmış

Vatan demiş millet demiş hep koşmuş

Takati tükenmiş sonunda susmuş

Birisi var ise işte o benim

Toplum menfaati için çalışan

Barış için kapı kapı dolaşan

Elindeki malı elle paylaşan

Birisi var ise işte o benim

Haklının hakkını çokca kollayan

Her yüze güleni dostum belleyen

Ömür boyu boşa kürek sallayan

Birisi var ise işte o benim

Hep pişiren pişirdiğin yemeyen

Hep koşturan hiç yorulmak bilmeyen

Hak adedipte karşılığın almayan

Birisi var ise o benim işte

Darılmak bilmeyen dostu hoş gören

Dostum diyenlere canını veren

İşini bilmeyen zarara giren

Birisi var ise işte o benim

Can kıymeti bilmeyen hiçe sayan

İnsanlık uğruna başını koyan

Mazlumun sesini içinde duyan

Birisi var ise işte o benim

Kendini başkası uğruna ezen

Göçmen kuşlar gibi durmadan gezen

İşleri bir türlü tutmayan düzen

Birisi var ise işte o benim

Şans ile beraber yerde yatmayan

Helal mallarına haram katmayan

Bu yaşa gelipte mekan tutmayan 

Birisi var ise işte o benim

Oyun bilmez her müziğe dans eden

Ömrünü geçiren boş dava güden

Hep inanan gücün alan güvenden

Birisi var ise işte o benim

Uçaklar kaldıran havada uçan

Şirketler kurarak fabrika açan

Sounda iflasla deliğe kaçan

Birisi var ise işte o benim

Varlığı yokluğu mükemmel tadan

Nasibini almış zevkten tasadan

Köşeyi dönmeyen öyle kısadan

Birisi var ise işte o benim

Hoşgörülü iyilikten zevk alan

Her zaman vicdanen müsterih olan

Yıkılmadan dim dik ayakta kalan

Mehmet Işıkoğlu İşte o benim

12.3.1997', 'İŞTE O BENİM Her dala et atmış emek sarfetmiş Eller yararına yollar kat etmiş Zararı ziyanı sineye çekmiş Birisi var ise işte o benim Ömrünü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/iste-o-benim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölsem de Kurtulsam.', 'olsem-de-kurtulsam-suleyman-saylan-44rju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÖLSEM  DE  KURTULSAM.

Bazı aptallıklarım vardır benim; 

Dizboyu,

Hem de çok,

Sonu enayiliklerle biten...

Gördüğüm herkesi insan sanırım,

Her insanı da dürüst...

Kaypak,

Kandırıkçı olabileceklerini,

Sahtekar, düzenbaz,

Kalleş olabileceklerini

Düşünemem hiç,

Yakıştıramam.

Yalandan sevebileceklerine,

 “seviyorum” diye kandırabileceklerine

İnanamam.

Yüreğim elvermez,

Başka türlü düşünemem.

Utanırım düşünürsem,

Yıkılırım,

Gerekçe bulamam...

İnsanın karakterine gölge düşüremem,

Yakıştıramam karaktersizliği

İnsanlara,

İnsanlarla özdeşleştiremem.

Tanımadığım, yapmadığım

Böyle davranışlarla

İnsanları karalayamam.

Bir insanın

Para için satılabileceğini,

Sizi de satabileceğini

Asla düşünemem.

Bu denli aşağılık değildir

İnsan...

Bazı aptallıklarım vardır benim; 

Dizboyu,

Enayiliklerle biten...

İnsan yüreklidir,

Merttir,

Temizdir,

Kirletemem.                            

Hele,

Kötülüklerin kaynağı,

Anası, odağı değildir

Tövbe...                                              

Haketmediklerini istemez insanlar,

Hakedenlerin önünü kesmez,

Engellemez,

Kıskanmaz,

Üstelik sevinir bile...

Çalışkandır,

Çalışmadan kazanırsa utanır,

Kaçar haksız kazançtan,

Haramdan...

Çocuklarına haram yedirmekten korkar.

Adildir kararları, hakçadır,

Dürüsttür,

Vicdanlıdır,

Aydındır, aydınlıktır.

Şeytanca düşünceleri yoktur,

Asla

Ayaklı şeytan değildir,

Kar aklığında temiz,

Çiçek kadar güzeldir

İnsan olan insan...

İnsan

İçten pazarlıklı,

Bukelamun kılıklı,

Art niyetli,

Kötü niyetli değildir, 

İstese de olamaz

Korkar vicdanından,

Vicdanının azabından...

Fırsat düşkünü,

Karşılıksız asla,

Yiyici,

Uçkurcu,

Hırsız başı...

Ne kötü yakıştırmalar bunlar

İnsan için,

İnsanları karalamak için.                                   

Hele kaypaklıkla suçlamak insanı,

Akıl almaz, 

Affedilmez bir suçtur bence,

İftiradır

En asılsızından.

Bal yapan arıdır insan,

Meyva veren ağaçtır,

Taşlanır. 

Bazı aptallıklarım vardır benim,

Dizboyu...

Sonu enayiliklerle biten.

Katlanamıyorum,

Dayanamıyorum,

Yakıştıramıyorum enayiliği kendime.

Ölsem de kurtulsam

Bu güzel(!)   İnsanlardan.

             Süleyman SAYLAN 

             Ankara, 25.03.2001 saat: 02.48', 'ÖLSEM  DE  KURTULSAM. Bazı aptallıklarım vardır benim;  Dizboyu, Hem de çok, Sonu enayiliklerle biten... Gördüğüm herkesi insan sanırım, Her...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/olsem-de-kurtulsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesapsızdık!', 'hesapsizdik-efsun-aydin-l5q03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün sana yazmak istedim

Çünkü rüyamda gördüm seni…

Bana ihtiyacın var besbelli

Aramakta çözüm getirmez sana

Baştan silmek gerek hayatını

İçinden beni çıkartarak elbette

Sonra bakmak gerek aynaya 

Yüzleşmek hatalarla

Ve bir daha yaşamamak 

O  bildik hikayede ki seni ve beni

Kimseler bilmezken biz biliyorduk üstelik …

Kırık kalplerde ki sevgiyi besledik biz.

Biliyoruz ki olmazdı…

Aslında biz hep olmazda tutuklu kaldık.

Ve sadece hesapsızdık!', 'Bugün sana yazmak istedim Çünkü rüyamda gördüm seni… Bana ihtiyacın var besbelli Aramakta çözüm getirmez sana Baştan silmek gerek hayatını İ...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hesapsizdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borç Alacak Aşk', 'borc-alacak-ask-fidan-bulut-0mizn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne alacaklı belli ne borçlu

Anlamadım hangimiz suçlu

Yaptığımız sadece sorgu

Artık yaşayamazmıyız

Suçlu benim hayır aşkım asıl benim

Ya kimse kim

Bunları bir kalem geçemezmiyiz

Sana borçlu olan benim bana beni verdin

Ah aşkım asıl ben borçluyum

Son baharımda dalımda açan son çiçeksin

Tamam sen yine borçlu kal

Sen çiçeği ol

Bir kenara bırakamazmıyız

Engelleri kayırmak 

Bir bizim boynumuza mı borç

Bizi biz ayırmak

Bir bize mi farz

Her sabah başlayıp

Gün batımlarında ayrılmalardan yorulmadık mı

Hadi sen benim elimi tut

Söz ben de senin gözlerinin içine bakacağım', 'Ne alacaklı belli ne borçlu Anlamadım hangimiz suçlu Yaptığımız sadece sorgu Artık yaşayamazmıyız Suçlu benim hayır aşkım asıl benim Ya kims...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/borc-alacak-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslu', 'uslu-alper-bayrak-82igs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uslu Çocuklardık biz

Sevilmeyi istemeden

Beklemeyi öğrendik

Arsızlık etmeden beklersek eğer

Her türlü güzelliği 

Hak edecektik

Neler geçti önümüzden, neler

Kahreden bir tevekkülle biz

Sonsuzluğa rest çektik.', 'Uslu Çocuklardık biz Sevilmeyi istemeden Beklemeyi öğrendik Arsızlık etmeden beklersek eğer Her türlü güzelliği  Hak edecektik Neler geçti ö...', ARRAY['Türk Edebiyatı','Şiir','Alper Bayrak']::text[], 8.5, '{"poet":"Alper Bayrak","poet_slug":"alper-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uslu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağdure Öğrenci', 'magdure-ogrenci-elazigli-mustafa-kaya-m35mf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mağdure öğrenci 

 hangi süslü hançerler kesti zamanı 

 hangi kıskançlıklar ayırdı kitaptan 

 ve hangi sokaklar karanlıktı 

 ve niçin bu metropol’de ışıksız sokakla lambaları... 

 geçtiğim her yerde 

 sürüklendiğim her sahilde 

 hikayene rastlıyorum. 

 çöl kumları kadar acı çeksemde 

 ışığı gördüm gözlerinde n e b i ‘nin izini süren..... 

 yaşadığımız şehir gökdelenlerle taş üstüne taş 

 sevgiye mezar süzüşler 

 ardında konuşulamayan bir hüzünlü tarih 

 oysa,olan bitene güzellik katan fikirlerin var 

 yeni mezarlar açan şehre inat 

 yüzünde gezdirdiğin ışık yeter 

 buraların sesi değil sesin 

 buraların yeri, yerin değil senin 

 ışık hep ışık saçan bir meleksin 

 ötelerden gelen nefesin 

 bükülmez yüreğin 

 tükenmez enerjinle sen hiç kaybetmedin....

07.02.2002 istanbul

Mustafa KAYA', 'mağdure öğrenci   hangi süslü hançerler kesti zamanı   hangi kıskançlıklar ayırdı kitaptan   ve hangi sokaklar karanlıktı   ve niçin bu metr...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/magdure-ogrenci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Çiçekler Bendeydi...', 'o-cicekler-bendeydi-efsun-aydin-qwrkw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEni çok özledim ben…

Anlayamazsın ama sen.

Farklı bakarsın sevgiye sen

Kalbin başka der, dilin başka senin

Kırarsın yeri gelince en sevdiğini de ya sen

Özürü içinde gizlidir hep delen geçen gözlerinin…

Çoğu zaman taşırsın sevgiyi her gittiğin yere de

Bir tek beni almazsın yanına sen…

Beni kalbinde taşıdığın ve atamadığın o kadar belli ki…

Yüreğimde yaşıyorum seni…

O kalp ne zaman durur o zaman susarsın içimde…

Bir başka dünyada bir başka aşka kadar…

Sonra yeniden seviyorum lar…

O bildik kalp atışları..

Ben o çiçekleri hiç soldurmadım …

Sana yemin ederim.', 'SEni çok özledim ben… Anlayamazsın ama sen. Farklı bakarsın sevgiye sen Kalbin başka der, dilin başka senin Kırarsın yeri gelince en sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-cicekler-bendeydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm - 4', 'koyum-4-elazigli-mustafa-kaya-niwzg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'benim  doğduğum

topraklarda

sarı  dikenli  tarlalar

böğürtlen  çalılıkları

dut  ağaçları

ark  boyunca  kavaklar

bağlar

bahçeler

dere  tepe  bostanlıklar

uzakta  fırat  akardı...

kaç  bayır  aşardık  da

kenger  sakızı  kanatırdık

göller  de  çimerdik

kaç  göl  vardı

yosun  ve  kurbağa  yaşardı

mişmiş  ağaçlarına  çıkardık

payam  çırpardık

şahra  taşırdık

uzunca  patikalardan  geçerek

su  kenarı  boy  boy  dörülmüş  tarlalardan..

bulgur  kaynatılan  kazanlara  koşardık

mendil  mendil  bulgur  yerdik

loğ  çekilmiş  düzgün  damlar

bekmez  serili

beyaz  çarşaflar  üzerinde.. 

ak  yazmalı  nenelerimiz

annelerimiz  ekmek  pişirmekte

saç  üzerinde  mayalı  ekmek

terayağı  hazırdı

çağalarına  sürmek  için  nenelerimiz...

yayık  yaymayı  severdim

yorulmazdı  annelerimiz  nasıl? 

saatler  sonrası

ayran  üzeri  yağı  çekerdik

közü  duran  ocağa

küller  altına  patates  konur

isot  yapılır

cezveyle  kahve  yapardı  aksakallı  dedem

ince  zayıf  zarif  suyu 

 cirik çeşmesi

kalın  kaba  güçlü suyu

 hakko  efsanesi

benim  doğduğum  topraklarda

acının

yokluğun

sevdaların  kokusu  yaşar...

                                                          14.08.2003

                                                           kızılay/ankara', 'benim  doğduğum topraklarda sarı  dikenli  tarlalar böğürtlen  çalılıkları dut  ağaçları ark  boyunca  kavaklar bağlar bahçeler dere  tepe  ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/koyum-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Sevda', 'nasil-sevda-i-sa-erkol-ljq3l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Durup dururken yine aşık olmuşum,

Bu nasıl sevda ki, bilemiyorum.

Aşk şarabı diye dertle dolmuşum

İçiyorum, sarhoş olamıyorum.

Yüzüne bakmaya cesaretim yok

Mutluluk hiç, hüzünlerse çok

Attım gönül yayından sana doğru bir ok

Hedefe varır mı? Bilemiyorum.

Gönlüm taşkın dere gibi çağlıyor

Aşkın da yüreğimi dağlıyor

gözüm hiç durmuyor, her gün ağlıyor

Ağlıyorum ama gülemiyorum', 'Durup dururken yine aşık olmuşum, Bu nasıl sevda ki, bilemiyorum. Aşk şarabı diye dertle dolmuşum İçiyorum, sarhoş olamıyorum. Yüzüne bakmay...', ARRAY['Türk Edebiyatı','Şiir','İsa Erkol']::text[], 8.5, '{"poet":"İsa Erkol","poet_slug":"i-sa-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasil-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hep Pazar Günleri Vururlar', 'beni-hep-pazar-gunleri-vururlar-ahmet-nural-ozturk-brtq0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni hep pazar günleri vururlar

Hem de onmayası yerden

Hem de yaz kış demeden

Bundan öderim kalan borçlarımı

Veda ederim aşklarıma cumartesiden

...........

........

......

......', 'Beni hep pazar günleri vururlar Hem de onmayası yerden Hem de yaz kış demeden Bundan öderim kalan borçlarımı Veda ederim aşklarıma cumartesi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beni-hep-pazar-gunleri-vururlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam - 2', 'babam-2-elazigli-mustafa-kaya-lfey9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bugün ne oldu

ağustos’un on dokuzu

ankara’da evimiz gecekondu

babam vefat edeli kaybolduk

doldurulamadı evimizdeki boşluk

kimse konuşmuyor

kimse konu bulamıyor

geziniyorum odalarında evin

sessiz hıçkırıklar birikiyor,siz de dinleyin

merak ederdim çekmecesi olan masayı

çekmecesinde telefon rehberi,bıyık makası

kullanmaya hazır boş sahifeler, bir ayna iki taraflı

bir gözlük,birkaç kalem ve tırnak makası 

tahtadan bir masa ve iskemlesi 

salonda bir köşeye dayalı

her yeni günde babam ve masası

iki sevgili gibi kavuşurlardı

masa babamla anlamlı

gözlüğünü çekmeceden çıkarır

raftan Kur’an-ı alır

sessiz fakat sesli

her sabah okurdu..okurdu 

belli aralıklarla gün boyu

şimdi boş masa sandalye 

oturdum kalktım

açıp kapadım çekmecesini

babamın yaptığı gibi

olmadı hiç biri

tutmadı yerini

evin içi böyle

dışı bahçe

bahçe öksüz kaldı

her sabah teftiş edilirdi 

her bir ağacın sevgisi farklı

babamla bakımlı

babamla rengarenkti 

güneş doğuncaya kadar gezinirdi bahçede

çiçeğe,toprağa eğilirdi şefkatle

akşam olur her akşam

siyah beyaz grundig televizyon

haberleri hiç aksatmazdı 

ardından deniz hava tahminleri kaçmazdı

dünyayı takip etmeden duramazdı

toplumsal olaylar canını acıtsa da

duyarsız hiç kalmadı

çocukların pamuk amcasıydı

mahallenin de

herkes bir yanını kaybetti

vefat edince babam

sokaklar çok aradı onu

sevimli şakacı adamı

insanlar hep sordu

ağaçlar aşısız

çocukları babasız

kaldı

o herkesin pamuk amcasıydı …

Mustafa KAYA

21/11/1996 - Ankara', 'bugün ne oldu ağustos’un on dokuzu ankara’da evimiz gecekondu babam vefat edeli kaybolduk doldurulamadı evimizdeki boşluk kimse konuşmuyor k...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/babam-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışık', 'karisik-elazigli-mustafa-kaya-7djgy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'köşegen cadde bir kedi

açık büfe gölgeler

nal çivisi farlar

delip geçiyor yıldızlar

kat kat gök yaranlar

küçülen başlar oldu

bir tutam papatya

suyu çıkarılan.

eğilip doğrulan insan

makaslara girer 

kırpılan ot değil

duygular.

birkaç kuruş geldi

onur..

uçurumlara kol açtı,

vitrin kağıtları.

x sıfır çözümlerini

tartmaz yer.

boşluk simsiyah

görüleni görememek

aydınlığı karanlıkta bilmek

çapraz kurşunlanmak değil mi? 

pençesinin korkusu indi

sinmiş bir ürkek kedinin

yalanı en doğru konuşan şehire.

sek sek oynanan cesetler

kör kuyu bu bahar

ip ssalmadı susuz

çıkılmaz gün ışığına

salıncak kurdu tuzak

yine aynı masal

kırmızı elma zehir

artık dolu nutuk

çalıntı eller tutuyor dertleri

Mustafa KAYA

07/04/2001 - ANKARA', 'köşegen cadde bir kedi açık büfe gölgeler nal çivisi farlar delip geçiyor yıldızlar kat kat gök yaranlar küçülen başlar oldu bir tutam papat...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/karisik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunalım', 'bunalim-elazigli-mustafa-kaya-je8jv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kış büyüledi bu kez herkesi şaşırttı solgun yüzleri mutsuz bedenleri yılgın sözleri bahara çevirdi lapa lapa...

Yine yapayalnızım, inadına kışa rağmen tüm hayatın vazgeçilmez renklerine ne kadar dayanabilirim Ankarada...

Sanki herkes çok mutlu geliyor bana hiç dertleri yok gibi deli oluyorum caddelerin bu kahkahalarına Kızılayda....

Biraz nefes almak için duraladım çılgın trafiğin karşısında…

..

Mustafa KAYA

01-08-1999 / Ankara', 'Kış büyüledi bu kez herkesi şaşırttı solgun yüzleri mutsuz bedenleri yılgın sözleri bahara çevirdi lapa lapa... Yine yapayalnızım, inadına k...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bunalim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Yarası', 'dost-yarasi-bahri-yildirim-4azvh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşman kurşun atsa 

Göğüs gererim ama

Dost gül atarsa

Dokunur yaprağı ölürüm.

Düşman en çok karanlığı sever

Ben,inadına 

Aydınlığa yürürüm.

Bulutlanır hjer sabah yüreğim

Dostu düşümde görürüm

Dost dosta her an sevdalı bilirim

Sevdalardan kaleler yaparım yüreğime

Dost için...

Ama; 

Dost gül atarsa ölürüm.', 'Düşman kurşun atsa  Göğüs gererim ama Dost gül atarsa Dokunur yaprağı ölürüm. Düşman en çok karanlığı sever Ben,inadına  Aydınlığa yürürüm. ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dost-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal ve gerçek', 'hayal-ve-gercek-elazigli-mustafa-kaya-jkq1x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'artık her şey hayal 

geçmiş yanmıştı 

sözleri bahar genç kızın hikayesinde 

unutulmaz o mutlu günler 

yoktu artık 

ayna paramparça olmuş 

sis kaplamış 

geçmek bilmiyordu 

unutmak için 

deniz şehri terketti 

ankara yeniden 

bir gelinlik gibi 

sarmıştı ruhunu 

umutları 

ölümlü zevkleri aştı genç kızın 

avuçlarında tutuyor şimdi 

yaşanmış ne varsa 

sessiz bir akşamdı 

uykusuz gecelerinden biri başlayacak 

ankara bilmeyecek gözyaşını 

saçlarını kestiğini de 

usulca döktü derdini geceye 

ve bir yıldız kaydı 

anılarını birbir toplamak için mi? 

serserisi olmak istedi

duygularının önünde 

uçmak...uçmak... 

zamanın derinliklerinde 

ankara dar gelmemeli 

saatler geçiyor 

bir haber gelmedi 

umut diye sarıldığı ne varsa bitmemeli 

ankara görmeyecek yanlızlığını 

sözleri bahar kadar güzel genç bir kızın 

unut gitsin değildi

keyifli bir gündü 

anladı 

sorguladı

umutlarını yeniden 

topraktan çıkardı... 

19.07.2005 / ankara

mustafa kaya', 'artık her şey hayal  geçmiş yanmıştı  sözleri bahar genç kızın hikayesinde  unutulmaz o mutlu günler  yoktu artık  ayna paramparça olmuş  si...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hayal-ve-gercek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Masalı', 'bir-ask-masali-bahri-yildirim-fqhug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana bir aşk masalı anlatayım

Beni iyi dinle ama.

Önce bir varmış,

Sonra bir yokmuş

Önceden hemen sonra 

Hepsi birden kaybolmuş

Onca emekten sonra

O kadar düşten sonra

Geriye kocaman bir hiç kalmış

O da kimin umurunda

Kimseler hatırlamamış zaten

Kimindi? 

Kiminleydi? 

Kim yaşadı? 

Kim öldü uğruna? 

Hiç kimse bilememiş 

Bu büyük aşkın!  hazin sonunu

Yinede adet yerini bulsun diye söylenmiş

''''Onlar ermiş muradına

Biz çıkalım kerevetine''''

.......

Beğendin mi masalımı? 

Bu aşkı yazmaya korkan kalemim', 'Sana bir aşk masalı anlatayım Beni iyi dinle ama. Önce bir varmış, Sonra bir yokmuş Önceden hemen sonra  Hepsi birden kaybolmuş Onca emekten...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-ask-masali-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Dörtlükleri', 'gece-dortlukleri-ozgur-kokturk-e78ns', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece yarısı düşer aklıma gözlerin 

Düşlerimi parçalar kırılgan yüreğin 

Seni söyler yazdığım dizelerim 

Gece yarısı düşer aklıma gözlerin

Ve bu gecenin tam ortasında 

Yine sana döner sözlerim 

Beni alıp sana götüren yollarda 

Gecenin ortasına şiir gibi düşerim

Gecenin sonuna doğru yaklaşırım 

Gece bitmez sesin gelmeyince 

Ben yine hayallere düşerim 

Güneş doğmaz yüzün gülmeyince

Gece bitti ben yine buradayım 

Sevdalım, şiirimle başbaşayım 

Sorma beni geceye, güne 

Ne güneşte, ne yıldızdayım

Bitti sandım geceyi karanlık silinirken 

Ufkumda ağarmıyor güneşimi görmeden 

Sayıklamalar sardı beni hayaller içinde 

Gece bitmemiş dostlar şafağın kıyısındayken

Gecede kaybolmaz direncin

Gecenden kaçsan geceme düşersin 

Bu coşkunluğa pay biçemem 

Umudumu üleştiren gecemdesin

Gecenin soluğu ensemde nefes nefes 

Benim bendimi geçmiş sınır sınır 

Bu nasıl yürek, bu gece ne enfes 

Canım canıma düşmüş kıpır kıpır

Yıldırım düşer yüreğimin ortasına 

Gece çarpar geçer umutlarımı 

Sayıklamalar sarar düşlerimden kalan 

Bugünümü, dünümü, yarınımı

Gün geldi yüreğe gecenin içinde 

Gül kokusu sindi her zerresine 

Yaşadım, umutlandım, mutlandım 

Sevdamı söyledim her dizede...', 'Gece yarısı düşer aklıma gözlerin  Düşlerimi parçalar kırılgan yüreğin  Seni söyler yazdığım dizelerim  Gece yarısı düşer aklıma gözlerin Ve...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gece-dortlukleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras Çocukları', 'miras-cocuklari-fidan-bulut-3c9vt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz........ mirası yemiş çocuklar

Geçirdik işte bir çocukluk

Biraz hıncahınç az mutlu biraz buruk

Büyüdük de aslında hasbel kader

Akranlarımız düşerken kaygısına geleceğin

Mutlu yarınların yollarına planlar çizerken

Biz loş sevdalarda kaybolduk

Meğer sevgisizlikmiş belimizi büken

Yanlış göğüslerde kaybettiren

Kimse söylemedi ki daha erken vakit var diye

Elinde hazinen değerini bilsene

Ne eilimzdekini gördük ne aklımızdakini

Varsa yoksa elin sevdası

Evlanmişiz bir yuva sevdasıyla kimimiz

Denizde ufku gördük bulutlar aşıp

Göğe erdik sanarak

Kimimzin harbi sağlam kimimizin eh işte

Kimimizde küllüm yalan evlilikler

Ona da sahip çıkamamışız ya

Çekmiş bizi köhneler çıkmaz dar sokaklar

Binbir ahdla hulusi kalble edilen tövbeler

Bir bir bozulur inatla

Elalem gıpta ede dursun

Hanımlık beylik bozar bizi

İşlemiş birkere

İçten içe azar elaltı yaşarız biz bizi

Severiz pisliği aykırılık kalkanımız

.......... mirası yemişiz bir kere', 'Biz........ mirası yemiş çocuklar Geçirdik işte bir çocukluk Biraz hıncahınç az mutlu biraz buruk Büyüdük de aslında hasbel kader Akranlarım...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/miras-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Karanlığı Saçlarım', 'gece-karanligi-saclarim-isik-aktas-7t077', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçlarım,

gece karanlığına isyan.

yalnızlık nirvanasında

benim özgür yüreğim.

ne zaman,

rüzgar geçse saçlarımdan; 

yüreğimin elleri

dolaşır gece karanlığında.

düşlerim de saçlarım; 

siyah-beyaz,

hem özgürlük-hem esaret saçlarım

uzun, upuzun bir yol,

kocaman kocaman yalnızlıklar.

giden,

dönemedi daha.

gece karanlığı saçlarıma

bahar gelir mi acaba...

                                           (16.07.2005/Cumartesi-20.00 Çağlayan)', 'Saçlarım, gece karanlığına isyan. yalnızlık nirvanasında benim özgür yüreğim. ne zaman, rüzgar geçse saçlarımdan;  yüreğimin elleri dolaşır ...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gece-karanligi-saclarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynu Bükük Baharların Armonisi', 'boynu-bukuk-baharlarin-armonisi-isik-aktas-ixd73', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boynu bükük baharların armonisinde 

hayat alabora.

dört nala gidiyor zaman

yetiş yetişebilisen.

özgürlüğün özgürlüğünü aldılar elinden

yaşam can çekişiyor,

boynu bükük baharlar

ellerimden öpüyor.

boynu

          bükük

                    baharların

                                     armonisi

türbe yeşili hayat

mezar taşı kırmızı

azrail, gök mavisi giyinmiş.

bu kadar mı güzel beklenir ölüm,

saçlarımdan al beni.

                                    16.07.2005/Cumartesi-01.00/Şişli', 'Boynu bükük baharların armonisinde  hayat alabora. dört nala gidiyor zaman yetiş yetişebilisen. özgürlüğün özgürlüğünü aldılar elinden yaşam...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/boynu-bukuk-baharlarin-armonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmayacağım', 'seni-unutmayacagim-bahri-yildirim-aue9g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana yıkık umutlar vermedim hiç

Ben göndermedim sana o soğuk havaları

Sevmedim hiç kahrolası sensizliği

Sevemedim.

Yalan mı söyleyeyim

Bazen bir yağmur altında

Bazen göz yaşlarıma karışık

Bazen susamışlıklarımla dolusun

Bazen apaydınlık gecemde parlayan 

Bir ışık gibisin,doluyorsun odama

Bazende gecenin rengini çalmış gibi gözlerin

Beni taşıyor sana

Yorgunluğum çöküyor ay aşığı akşamlarıma

Işığım oluyorsun,ışıyor yüreğim

Sahillerime vuran deli dalgalar gibisin bazen de

Sığmıyor,taşıyorsun kocaman denizlere 

Deniz gibisin valla

Öyle  ya da böyle.

Uzun sözün kısası ben aht ettim biliyorsun

Gözlerini açmadan daha

Sabahları paylaşmadan

Öpmeden yanağındaki özlemi

Sancı düşmeden sevgimize

Çilesini doldurmadan bu yürek

Seni unutmayacağım', 'Ben sana yıkık umutlar vermedim hiç Ben göndermedim sana o soğuk havaları Sevmedim hiç kahrolası sensizliği Sevemedim. Yalan mı söyleyeyim B...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-unutmayacagim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit Osman', 'sehit-osman-mehmet-kindap-kq6uz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir karısıyla dört de çocuğu vardı

Benim büyük dedem adı Osman''dı

O şahindi, atmacaydı, kartaldı

Benim büyük dedem adı Osman''dı

Gemi gemi uzaklardan geldiler

Şu güzelim yurdumuza doldular

Tüm Dünya''dan emperyalist ordular

Rum, İngiliz, Anzak hepsi düşmandı

Şerife çocuklar sana emanet

Osman düştü yola hakkın helâl et

Güzel Anadolum canım memleket

Düşman geldi çattı durmak olmazdı

Örenköy''den gitti Çanakkale''ye

Süngüyle savaştı topla tüfeğe

Kurtar vatanımı şehit al diye

Dua etti osman hergün yalvardı

Çanakkale Çanakkale ben geldim

Canımı verdim de seni vermedim

Vuruldum alnımdan ama ölmedim

Can toprağa düştü artık VATANdı

Bir karısıyla dört de çocuğu kaldı

Benim büyük dedem adı Osman''dı

O şahindi,atmacaydı,kartaldı

Benim büyük dedem şehit Osman''dı

(2005 Ankara)', 'Bir karısıyla dört de çocuğu vardı Benim büyük dedem adı Osman''dı O şahindi, atmacaydı, kartaldı Benim büyük dedem adı Osman''dı Gemi gemi uz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kındap']::text[], 8.5, '{"poet":"Mehmet Kındap","poet_slug":"mehmet-kindap","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehit-osman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Düşlerim', 'yagmurlu-duslerim-isik-aktas-ubgmm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlu düşler istiyorum

sırılsıklam

koşmak, koşmak, koşmak

sonsuzluğa...

yüreğimin deli dansına

rüzgar yetişemiyor,

dalgalar kırmızı vuruyor kıyıya,

zenci çocuğun sütbeyazı gözyaşları,

ellerim kalbimin sesi,

ayaklarımla görüyorum evreni,

saçlarım yakamoz,

kulaklarım insan suretlerini izliyor,

gözlerimle dinliyorum

                                   baharın ezgisini

ve 

    yağmurlu düşlerim,

           rahvan atın terkisinde.

gelin olmuş hayatım sonsuzluğa

            davullu-zurnalı

            çalıyorlar,

            çalıyorlar,

            çalıyorlar...

Yağmurlu düşlerimi düşlüyorum...

                                                        (16.07.2005/Cumartesi-01.30 Şişli)', 'Yağmurlu düşler istiyorum sırılsıklam koşmak, koşmak, koşmak sonsuzluğa... yüreğimin deli dansına rüzgar yetişemiyor, dalgalar kırmızı vuruy...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yagmurlu-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunun adı ne? ? ? ? ?', 'bunun-adi-ne-fidan-bulut-vfm1f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şehitler verilir

Ateşli top tüfekli savaşlarda

Şehitler verilir

Toz toprak kan revan siperlerde

Namlunun ucunda candır şandır şehitlik

Şehitlik gençlik

Ya şimdi giden gençlik

Yenip yutulan gençlik

Arka sokak izbe köşelerin 

Siperlerden farkı ne

Bir şırınga ucu mutluluğun farkı mermiden

Körkütük sarhoş çıplaklığın

Adı medeniyet ahlaksızlığın

Top güllelerden farkı

Ufkunuzu aştık çağı geçtik

Yakala dünyayı

Varoşlarda tükenen hayatların hesabı

Dağlara feda ettiğimiz canların hesabı

Kimi bir avuç gökyüzü

Kimi bir kese altına sattığımız beyinlerin hesabını

Ne soracak kan azgını bir komutan

Ne de toprak açı bir mihrak

Aklım ermez biz bizden ne isteriz

Şehitler ölmez

Yitirilen gençlik geri gelmez.........', 'Şehitler verilir Ateşli top tüfekli savaşlarda Şehitler verilir Toz toprak kan revan siperlerde Namlunun ucunda candır şandır şehitlik Şehit...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bunun-adi-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tipi', 'tipi-mehmet-metin-senturk-z8r7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yanan sobanın tavanda raks eden alevini düşlüyorum tipide

soğuk değil yalnızlık işliyor iliklerime...

kartaneleriyle dokunuyor yüzüme sonsuzluk! 

ne çok istiyorum şimdi kartanesi olmanı

beynimde uğulduyor oysa soluk sensizlik

sensizliğin yankısı bu sessizlik

sobanın alevleri azaldı

annem uyuyor

sen uyuyorsun

kar hızlanıyor sen üşüyorsun

gözkapaklarımla örtüyorum sırtını

kayboluyorsun

sonsuzlukla yarışıyor gelecek

sonsuzluğa karışıyor gelecek', 'yanan sobanın tavanda raks eden alevini düşlüyorum tipide soğuk değil yalnızlık işliyor iliklerime... kartaneleriyle dokunuyor yüzüme sonsuz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Metin Şentürk']::text[], 8.5, '{"poet":"Mehmet Metin Şentürk","poet_slug":"mehmet-metin-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tipi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alevlerin Dansı', 'alevlerin-dansi-isik-aktas-vsok6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidenlere...

ruhum ellerimde

sonsuzluğun kapılarındaki alevlerin gölgesinde

raksediyor müzik.

incecik bir sızı

                         taa derinlerden.

kanunun sesi

                          ağla diyor,

                                            ağla,

                          kanat içini.

aşk geldi bu gece yine

aç yüreğini,

uzat ellerini,

bırak ruhunu alevlere,

bırak ki 

buluşsun sevgiliyle...

                                   (18.07.2005/Pazartesi-02.30 Şişli)', 'Gidenlere... ruhum ellerimde sonsuzluğun kapılarındaki alevlerin gölgesinde raksediyor müzik. incecik bir sızı                          taa ...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alevlerin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bardaklarını Kırma', 'bardaklarini-kirma-tayfun-isildar-2uj3a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bardaklarını kırma daha çok… su içeceksin.

Yaralarsa zamanın işidir,

göreceksin.

Acın azaldığında arkana bakma, 

her yeni coğrafyada,

kendini deneyeceksin.

Çıktığın her yolculuktan, 

yeni haberlerle döneceksin

çok sevip,

az sevileceksin

insansın ya, 

kalbin sıkışacak ama, sen sıkılaşacaksın.

Şimdi yelkenlerini indirme, 

martıların kentinde, 

bir dilim ekmek peşinde, inadına seveceksin.

Kutsal sandığın her şey kırılır,

sakın ağlama,

tek bildiğin doğru, gitmek istediğin yoldur 

unutma, ezberi olmayan aşktır 

sen ezberini bozma.

16-12-2004', 'Bardaklarını kırma daha çok… su içeceksin. Yaralarsa zamanın işidir, göreceksin. Acın azaldığında arkana bakma,  her yeni coğrafyada, kendin...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Işıldar']::text[], 8.5, '{"poet":"Tayfun Işıldar","poet_slug":"tayfun-isildar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bardaklarini-kirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmalı mı Yazmamalı mı', 'yazmali-mi-yazmamali-mi-fidan-bulut-5fxlr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kaç kelimeye 

Bir kaç zaman dilmine

Takılmış durmuşum

Yanı başımda güzellik geç bulmuşum

Ne güzel süt beyaz bir yaprak

İnce narin bir kalem

Bu kadar yakışırmıydınız siz önceden de

Ben sizi görmemişim

Şimdi kalın parmaklarım yakar mı canını

Ya karamsar yüreğim kirletir mi seni

Elime alsam ince belinden

Gezdirsem yaprağın saflığında

Ne yapmalı acaba 

Yazmalı mı seyretmeli mi

Sakladıklarını içindekileri

Bir bir dökmeli mi

Desenize yine bir feda var ortada

Ya duygularıma gem vuracağım

Ya da sizi feda edeceğim

Ne yapmalı acaba bilmem ki.........', 'Bir kaç kelimeye  Bir kaç zaman dilmine Takılmış durmuşum Yanı başımda güzellik geç bulmuşum Ne güzel süt beyaz bir yaprak İnce narin bir ka...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yazmali-mi-yazmamali-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Gizlidir Yüreğimde Sevdalar**', 'gizlidir-yuregimde-sevdalar-seyhmus-sevilmez-sq45e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gizlidir  yüreğimde sevdalar

Gizemine erişilmeyen tılsımlar gibi…

Sana karşı olan sevgim,

Bir gerdekteki sırlar kadar saf ve temiz,

Duvağın, beyaz gülün asilliğiyle gizlerken yüzünü

Başka eller mi açıp görecekti o mağrur gözünü? 

Yine yarım kaldı bir şeyler,

Karalarken şiir diye seni,

Tükendi, tükenmez(!)  kalem

Yazamadığım satırlarımda

Bir sürü soru işareti ve sen varsın…

Ahhh… Gönlüm! ,

Ellerimle deşip, tuza bastığım yaram,

Yine ıslak ıslak kayıyor, kemiği olmayan dilim,

Sürçeceksin  he mi? ,

Yine“bir daha sevmek mi? ” diyeceksin

Tövbe de! 

Şimdi yüreğimden kan akar, gözlerimden yaş

Ne o…? 

Ölüm için mi yaşandı bunca telaş? 

Hayatın adil terazisinde tartındık 

Neden hep ağır bastın be ihanet? 

Sebebi,

Yarasa gibi, emip durduğun iliklerimden mi? 

Yoksa duvağınla hapsettiğin gözlerindeki esir kalan ben mi? 

Anladım ki,

Seninle ne bir şiir biter, ne de roman,

Ayrılık için,yılmadan kovalayacak beni zaman…

Şahitsiz bir nikah masasında, at artık imzanı! 

Mutlu sonla bitmeyen eserlerin kahramanı….', 'Gizlidir  yüreğimde sevdalar Gizemine erişilmeyen tılsımlar gibi… Sana karşı olan sevgim, Bir gerdekteki sırlar kadar saf ve temiz, Duvağın,...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gizlidir-yuregimde-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-zekeriya-yeniyol-gvcyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşamlar herkesten kaçar; 

Gelir bana sığınır..

Ben herkeste kaçar

Gecelere sığınırım...

Günlerle boğuşup,soyunup üzerimden; 

Akşamın gölgesinde tebdili kıyafet! 

Dostların aynasında gülümseyen yüzümle,

Kapanır gözlerim dost gecelerde.

Sen,akşamları  evinde beklerken

Beni evimde akşamlar bekler! ...

Sen gecelere soyunurken; 

Soyunur bana geceler! ...

                              19.12.04', 'Akşamlar herkesten kaçar;  Gelir bana sığınır.. Ben herkeste kaçar Gecelere sığınırım... Günlerle boğuşup,soyunup üzerimden;  Akşamın gölges...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Yeniyol']::text[], 8.5, '{"poet":"Zekeriya Yeniyol","poet_slug":"zekeriya-yeniyol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geceler-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olan', 'zor-olan-burak-cicek-sx5td', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıymet bilmek için ikimizden birinin gitmesi mi gerek? 

Keşke anlayabilseydik kalabilerek.

Biliyorum bu aşk; ne masal, ne çocuk oyunu

Gitmesi Kolay

Zor olan Sevmek', 'Kıymet bilmek için ikimizden birinin gitmesi mi gerek?  Keşke anlayabilseydik kalabilerek. Biliyorum bu aşk; ne masal, ne çocuk oyunu Gitmes...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zor-olan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözdüm Seni', 'cozdum-seni-sahin-erturk-546qc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu peşindeyim

Çözmek için çok uğraştım

Nihayet dün daha yeni

Çözdüm güzel,çözdüm seni

Düğüm,düğüm bağlanmıştım

Her sözüne inanmıştım

Seni gözde büyütmüştüm

Çözdüm güzel,çözdüm seni

Senin aşkın bir palavra

Kanmam artık her yalana

Haydi çek git,git yoluna

Çözdüm güzel çözdüm seni

(19.07.2005-İstanbul/Yeni)', 'Yıllar oldu peşindeyim Çözmek için çok uğraştım Nihayet dün daha yeni Çözdüm güzel,çözdüm seni Düğüm,düğüm bağlanmıştım Her sözüne inanmıştı...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cozdum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilebilir Misiniz?', 'bilebilir-misiniz-caglar-asik-xpbjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir babanın gönlünde yatanları.

Coşup coşupta çağlamalarını.

İçinde gürleyen göz yaşlarını.

Derman arayan konuşmalarını.

&

Duyarsızlıktan sıkıntılarını.

Sevgisizlikten bıkmalarını.

İlgisizlikten yılmalarını.

Sessizlikten ağlamalarını.

&

Sevdiğini, canını, cananını.

Siperle koruduğu aşklarını.

Yanan kor yürek diyarlarını.

Kovaladığı gerçek duygularını.

&

İdeallerine hep bağlanmasını.

Hiç bitmeyen koşuşturmasını.

Yorgun argın eve gelmesini.

Helalce kazanıp harcamasını.

&

Selamla gönül almasını.

Dostları arayıp sormasını.

Dertlilere ilaç sunmasını.

Sözle gönüle taht kurmasını.

&

İstenmeden vermesini.

Bekletmeden gelmesini.

Söylenmeden duymasını.

Görmeden de hissetmesini.

&

Kirletmeden giymesini.

Islatmadan yüzmesini.

Yıkmadan yapmasını.

Kırmadan uyarmasını.

&

Dostluk için çaba harcamasını.

Güçlüyken düşkünü kaldırmasını.

Her canlının aslında hep aradığını.

Arananın tüm canlara nasıl ulaştığını.

İstanbul – 19.07.2005', 'Bir babanın gönlünde yatanları. Coşup coşupta çağlamalarını. İçinde gürleyen göz yaşlarını. Derman arayan konuşmalarını. & Duyarsızlıktan sı...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bilebilir-misiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımsın', 'askimsin-yavuz-bayram-caliskan-hoixr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şehirler kaldı arada ezilecekler,

Yakamozlarda kader olup yazılacaklar,

Ay ışığı yürek yeter bana, güneş sizde kalsın,

Benim ışığım senden güzelim.

Dağ mısın durusun? 

Volkan mısın yürürsün? 

Dumanın nerede, külün nerede? 

Kalbim senin için atsa da içini bir sen doldurursun.

Sabrı kalmayan mavi şiirlerle sen güldürürsün.

Tutma kara geceleri uçup gitsin duman gibi,

Seveyim seni bir an gibi.

Hikâyemiz anlatılsın şiirlerde

Şarkılar söylensin dillerde

Bir sıcaklık olsun ellerde

Telaşıyla yaşansın zamanlar, 

Sevdiğim soluk ol ruhuma gir

Uyku ol geceme gir

Aşk ol heceme gir

Rüya ol beynime gir

Dünyalara sayıklayayım seni.

Aşkımsın kanımdasın

Ruhumdasın aklımdasın

Şehirlerce uzak olsan

Ne yazar sen benim canımdasın.', 'Şehirler kaldı arada ezilecekler, Yakamozlarda kader olup yazılacaklar, Ay ışığı yürek yeter bana, güneş sizde kalsın, Benim ışığım senden g...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askimsin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can mı Kaldı Bende', 'can-mi-kaldi-bende-sahin-erturk-iyfec', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözünden,gönlünden attın ya beni

Yatlara,katlara sattın ya beni

Yaşarken mezara soktun ya beni

Deniz gözlüm neden saldırıyorsun

Sana verecek,can mı kaldı bende

(18.07.2005-İstanbul-Yeni)', 'Gözünden,gönlünden attın ya beni Yatlara,katlara sattın ya beni Yaşarken mezara soktun ya beni Deniz gözlüm neden saldırıyorsun Sana verecek...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/can-mi-kaldi-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / İHANET', 'bir-dortluk-de-sen-yaz-i-hanet-siir-perisi-grubu-ke4e6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/İHANET'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

1 

Alnının ortasında, kara lekesi. 

Umurunda değil ki, ihanetçinin! 

Yüzünde parçalanmış ar''ın perdesi. 

Utanma duygusu yok, ihanetçinin! ............Turan Orak 

2 

yalancıdır kisvesi kargadır sesi 

kardeşleri şeytandır ihanetçinin 

doğruya yar mı olur sahte işvesi 

kalleşlik kanındadır ihanetçinin...................Turhan Toy 

3 

çekilmeye hazırdır vurur her zaman 

kılıcı kınındadır ihanetçinin 

tanınmaz bir bakışla, sakının aman 

maskesi yanındadır ihanetçinin.....................Rahim Taş 

4 

Sevene hep sırtından, vurur hançeri 

Marifet şanında var, ihanetçinin 

Her zaman asilikte, bir yeniçeri 

Bahane anında var, ihanetçinin.......Hıfzı özbekmez 

5 

ihtiyacın olunca sırt döner gider 

mazereti olur mu ihanetçinin 

güveni hiçe sayıp ihanet eder 

vefası bulunur mu ihanetçinin……………………S.Nizamoğulları 

6 

Vefayı bilmeyende vefa arama 

Sonu hep ihanettir ihanetçinin 

Yürekten sevenlerde vefa var amma 

Her zevki hıyanettir ihanetçinin..................Ertuğrul Şakar 

7 

Kuzuyu parçalayan, kurdu seyreder 

Ağzında salyalar, ihanetçinin 

Sırtlanlarda unutur geldiği yeri 

Saldırır dostu olmaz ihanetçinin..........Canan Palabıyık 

8 

Sevda yükü taşımaz, yüreği bitik 

Nasır tutmuş bilinmez, gecesi hain 

ihaneti içerir, heceler yitik 

Vazgeçilmezi zevk-i, ihanetçinin.........Şebnem Sönmez 

9 

Sevgin de yalansa çıkarmış ortaya 

Belki de bugün, belki çıkar haftaya 

İlaç sorulur mu ki yatan hastaya 

Ar''ı namusu yokmuş ihanetçinin! .......(Kartal62Serdar Sayıl)  

10 

Yemeği ekmeği aşı gıdası ihanet 

Suyu havası hayat pınarı ihanet 

Ona sorulur mu ne neden niçin 

Hayat Kaynağı kanı canı ihanet …………….Necmiye Sarpkaya 

11 

İhanet taşı bir patlayan mermi 

Vurduğu bedenimin en narin yeri 

Bir sızıdır bırakır bilinmezliklere 

Acı''dır acı ihanetin gerçek dostu.............Atıl Kesmen 

12 

Belli etmez rengini sevgi nefesi 

Düşünce gölgesi akan zehir suyu 

Dinmez bakışı nefretin adi tohumu 

İhanettir sevgi bilmez gönül yolu..............Atıl Kesmen 

13 

Neler uydurur neler, ne bahaneler 

Fikri zikri bir olmaz ihanetçinin 

Aldanma bakışına, aksa yaşına 

Tuzağı sevgindedir ihanetçinin..............Talip Kaplan 

14 

kamufle eder kendin,aldatır seni, 

şöhret hırsı kaplamış,bütün bedeni, 

yağ gibi yüze çıkar,üstelik e mi, 

karadul gibi ömrü,ihanetçinin...............Murat Nail Güney 

15 

Sevginin kılıfına bürünür gezer 

Konuştuğu kişiye inciler dizer 

Kuşkuludur herkese hileler sezer 

İhanet marifettir kimi insana................Mehmet Işıkoğlu 

16 

Tanınmaz yüzünden masumca bakar 

Sanırsın gözünden yaşları akar 

Sonunda torbadan yılanlar çıkar 

Karakteri budur ihanetçinin..................Mehmet Işıkoğlu 

17 

Kendine olmadı ki, sana olsun yar 

Dost gibi görünerek ne koparsa kar 

Maskesinin altında başka bir yüz var 

İlgisine aldanma ihanetçinin......................Ayşe Korkmaz 

18 

Bozuktur bu devirde, insan mayası 

Etme ihanet elbet çıkar foyası 

Baki değildir geçer kurşun yarası 

Uğrama ihanete geçmez acısı...................Hayrettin Orak 

19 

Lugatinda merhamet arama sakin 

Raslanmaz kitabinda ihanetcinin 

Etrafina dikkatli gozlerle bakin 

Birden cok yuzu vardir ihanetcinin......................Aynur Ilkay 

20 

Sanirsin dusuremez seni tuzaga 

Sozleri tatli olur ihanetcinin 

Aramak icin gitme evden uzaga 

Koynunda yatiyorsun ihanetcinin.........................Aynur Ilkay 

21 

Asla yakistiramaz bir kere insan 

Yemin dilinde tesbih ihanetcinin 

Tekrar tekrar aldatir ona kanarsan 

Dini mezhebi yoktur ihanetcinin........................Aynur Ilkay 

22 

Sinsi bir alev gibi,yakar ihanet 

Ardında küller kalır, kokar ihanet 

Bedelini düşünmez, ucuz ihanet 

Nedeni hiç bilinmez, acı iha…………………..Nalan Palabıyık 

Şiir Perisi Grubumuzun her hafta düzenlediği ''Bir Dörtlük de Sen Yaz'' aktivitesi sonucu oluşan ortak bir eserdir.', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/İHANET'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / HÜZÜN', 'bir-dortluk-de-sen-yaz-huzun-siir-perisi-grubu-bo23g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/HÜZÜN'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

1. 

Kurtuldum günahtan, şerden kurtuldum. 

Çamur batağından çıktım çok şükür. 

Sıyrıldım acıdan, dertten sıyrıldım. 

HÜZÜN girdabından çıktım çok şükür.................Turan Orak 

2. 

simgesidir hüznün buğulu gözler 

ürkek kelimeler, titreyen sözler 

gönül elden kayıp gideni özler 

yüreklerde ağrı, sızıdır hüzün.......................Rahim Taş 

3. 

hüzünlüydü dünüm, bugün kurtuldum 

aydınlandı gözüm, Rabbe çok şükür 

karamsardı ünüm, bak unutuldum 

meydanlarda sözüm, Rabbe çok şükür...............Turhan Toy 

4. 

Hüzün bulutları yağmura döndü 

Sağanak halinde şiire düştü 

Şairi kendinden aldı götürdü 

Hecedir, dizedir, şiirdir hüzün………………S.Nizamoğulları 

5. 

Döküldü günahlar avuçlarıma 

Döküldü elemler kederler korlar 

Yüreğimi yakar oluk oluk hüzün 

Gaflet ve delalet devam etmede ……………………Necmiye Sarpkaya 

6. 

Taş toprak olmaktan artık sıyrıldım 

Bir filiz içimden çıktı çok şükür 

Aşk derdine düşüp tenden ayrıldım 

Hüzün ellerimi tuttu çok şükür............ Ertuğrul ŞAKAR 

7. 

Yaz bitmiş peşinden geliyormuş güz 

O güzel kalem kaşta, sürmeli göz 

Kalb kırarmış acımasız bir kaç söz 

İçten yakarmış insanı bu hüzün…………………….Serdar Sayıl 

8. 

Huzur bulmak için gezdiğim yerde 

Gönül mehtabının önünde perde 

Neşe hüzmeleri teğet geçiyor 

Bozuyor akordu hüzün tellerde........................Mehmet Işıkoğlu 

9. 

Ağlayan gözlerin şahidi sanki 

gönlüm yetmiş yerden kırık inanki 

hele o gidenin son sözü varki 

Sevdanın hüznünden bıktım çok şükür........... Hıfzı Özbekmez 

10. 

Hüzünler ki; bize vermez kaygılar, 

Onsuz hayat, tuzsuz yemek a dostum. 

Hüzne dönük gözyaşına saygılar, 

Kandil diye hüznü, tavana astım………………………..A.Rıza Navruz 

11. 

Dökülür dişleri, saçı kırlaşır 

Yaşamla ölümün yüzü birleşir 

İçine garip bir sızı yerleşir 

Şu yalan dünyanın özüdür hüzün …………………..Ayşe Korkmaz 

12. 

Yalancı yüreğin koştum peşinden 

Kaçıncı sevdanın düştüm gözünden 

Bu sabah güneşle doğdum yeniden 

HÜZÜN duvarını yıktım çok şükür............Hülya Hüyüktepe 

13 

Yürekten, gönülden hesap sormadım 

Dünümden, günümden pişman olmadım 

Dostlarım sağolsun yalnız kalmadım 

HÜZÜN pencere mi açmadım şükür..........Hülya Hüyüktepe 

14. 

Solmasın avucundaki gonca gül 

Asılmasın yüzün ne olur her an gül 

Sızlamasın yüreğin istediğin yerde kal 

Üzülme, bana da hüzün işlemeli yorgan al…………..Meral Yağcıoğlu 

15. 

Ömrümün manası senle olmaktı 

Sen geldin ya, dertler bitti çok şükür 

Senle ömür boyu mutlu olmaktı 

Hüznü defterimden sildim çok şükür………………….Mehmet Selim Toğluk 

16 

Ben anlamam zevku sefadan, 

Payımı almışım derdu cefadan, 

Ne zaman göçersem bu dünyadan, 

Kurtulurum o zaman hüzün denen beladan..............Hayrettin Orak 

17. 

Saçlarındadır gecem dudağında gündüzüm 

Elveda yalnızların anası bozkırlara 

Yerler ağzını açmış bekliyor beni hüzün 

Zifiri karanlıkta günü çekmişler dara..........Zülfikar Yapar Kaleli2. 

18. 

Dem vurup serhadde, Şam''dan Hizan''a 

Şafaksız düşünden çıktım çok şükür... 

Ardınca nefsimi koyup mizana, 

Bir hüznün peşinden çıktım çok şükür......... Hakan İlhan Kurt

Şiir Perisi Grubumuzun her hafta düzenlediği ''Bir Dörtlük de Sen Yaz'' aktivitesi sonucu oluşan ortak bir eserdir.', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/HÜZÜN'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR ...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Kokulu Akşamlar', 'mum-kokulu-aksamlar-arzu-gulucudur-abxer', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mum kokulu akşamlarda başladı hüzünlü şarkılar

Şarkılar da mum kokardı...

Akşamlar gibi...

Hüzünlüydü Aşiyan yolları

Buruk bir acı ve kemancı...

Şehrin keşmekeşliğine inat

Gündüzün kör karanlığından sıyrılıp

Silerdi günün ışıklarını geceler

Bir bir yanardı kentin sokakları 

Sonrada bir bir sönerdi...

Mum kokardı geceler

                       soğuk

                       hüzünlü

                       ve sessiz....

Eski bir şarkıcı dolaşırdı caddede

''Biz mehtaba çıkardık'' başlıklarında bir kürd''i licazkar

Ardından bekçi düdükleri...

Bir bir sönen mumlar...

Kapanan kapılar ardın sıra

Ve kapanan gece sabaha

Mum kokulu bir akşamdan

Bahar kokulu bir sabaha...', 'Mum kokulu akşamlarda başladı hüzünlü şarkılar Şarkılar da mum kokardı... Akşamlar gibi... Hüzünlüydü Aşiyan yolları Buruk bir acı ve kemanc...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mum-kokulu-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekingen Gözler', 'cekingen-gozler-yavuz-bayram-caliskan-272y0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sizin yabancınız değilim

Genzimdeki ılık kokunuz

Elimi ısıtan o sımsıcak avuçlarınız

Kulağıma fısıldadığınız kadife sesiniz

Unutulur mu o mağrur gülüşleriniz

Galiba ben sizde kalıyorum

Kira bile almıyorsunuz

Gözlerinizdeki bulutlarda olmasa

Yüreğim su almayacak

Gemilerde batmayacak

Çekingen gözlerinizden bir kadeh

Mezesiz sarhoşum galiba', 'Sizin yabancınız değilim Genzimdeki ılık kokunuz Elimi ısıtan o sımsıcak avuçlarınız Kulağıma fısıldadığınız kadife sesiniz Unutulur mu o ma...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cekingen-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / ARAYIŞ', 'bir-dortluk-de-sen-yaz-arayis-siir-perisi-grubu-besoh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/ARAYIŞ'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı) 

1 

Özlem sabır taşırdı, gözler ARAYIŞlarda. 

Sızlamakta duygular, söyle yaren nerdesin? 

Bedeni ateş sardı, sözler haykırışlarda. 

Kırılmakta umutlar, söyle canan nerdesin? ................Turan Orak 

2. 

gittiğin günden beri gözlerim hep yollarda 

sormadığım bir çiçek kuş kalmadı nerdesin 

yakamozlar serseri erirken dalgalarda 

arayışım son buldu sen benimle serdesin.................Turhan Toy 

3. 

Zamanı yiyen başlar, zonklasın yavaş yavaş 

Şimal yıldızı senin zühreni arıyorum. 

Hür insanlık uğruna, başlasın kutlu savaş 

Yanıyor yerler gökler, ben beni arıyorum..........Zülfikar Yapar Kaleli 

4. 

ARAYIŞlar hep bana, bana mı zimmetlendi 

Ey bahtımın güneşi, geceleri nerdesin? 

Yüreğimdeki közler yeniden alevlendi 

Gönlüme su serpecek mavi gözlüm nerdesin? ............ M. Selim TOĞLUK 

5 

Seni arıyorum ey gözümün naz çiçeği 

Gözümün iliştiği yüreğin eriştiği 

İklimde bestelenen notada arıyorum 

Adı konmamış yerde seni ararım seni...........Çobanyıldızı Necmiye 

6. 

Arayışım son bulmaz olsan da uzaklarda 

Nereye gidersen git her zaman sen bendesin 

İçime sızı düşer kor kızıl akşamlarda 

Faydasız bekleyişim dönülmez bir yerdesin.............Sevil Nizamoğulları 

7 

Selamına ağladım martı kanatlarında 

Bir teselli aradım hüzün bulutlarında 

Sevdana esir oldum masum bakışlarında 

Nerdesin kara gözlüm, Leyla sensiz olur mu? …………….Leyla AKGÜL 

8 

Ararım seni esen yelde yağan yağmurda, 

Ararım bir ceylanın keskin bakışlarında, 

Ararım gezdiğimiz sevda patikasında, 

Ararım seni gülüm arar durmaksızın....................Hayrettin Orak 

9 

umutlarda azaldı, bak boş ARAYIŞlarda. 

gönlümdeki gülleri, deren canan nerdesin? 

işim oldu kadere, lanet haykırışlarda. 

bu gönlüme ilhamı, veren canan nerdesin? ..........Hıfzı ÖZBEKMEZ 

10 

yalnız kaldım gitgide arıyorum bir çıkış 

kanıyor yaralarım, derde derman nerdesin 

hüzünleri işledim kalbime nakış nakış 

artıyor acılarım, içten yanan nerdesin………………………………..Rahim Taş 

11 

Sevda bahçem kurudu, şehirler yıkılmakta 

Aşk peşine takılmış, yüreğim yakılmakta 

Pencereme tünemiş martılar ağlamakta 

Senden başka ilaç yok dertlerim arayışta………… Hülya Hüyüktepe 

12 

Zaman mekan yok oldu sensizlik can yakıcı 

Canan sevdan kor oldu yokluğun en acısı 

Bilmem bende biter mi yüreğin şu sancısı 

Senden başka çare yok gözlerim arayışta ………..Hülya Hüyüktepe 

13. 

Dolaştığım sokaklar çıkmazlara varıyor 

Beklediğim yarınlar umutlarla büyüyor 

Arayışım son bulmaz yürek seni istiyor 

Gel gönlüme sevgili kaç zamandır nerdesin………..Hülya Hüyüktepe 

14. 

Sevgimi canım kaybettim ben arayıştayım 

Doldurdun mu yarim nerde benim demli çayım 

Senle başlar bilirim gündüzüm, gecem, ay''ım 

Sevgimi canım kaybettim ben arayıştayım……………….Serdar Sayıl 

15. 

Kızım seni beklerken, sevgi ektin kalbime 

Hayatı dert ederken, ışık oldun harbime 

Şimdi tuttuk elinden, hayatı sımsıkı biz 

Arayışım biterken, yeni yolsun gönlüme……………..Erdoğan Ergin 

16. 

Hep Sılam olacaksın, sana biz varacağız 

Yasemin olacaksın, balını alacağız 

Şimdi anladık sırrı, bebekte saklıymış giz 

Ailem diyeceksin, sevgiyi karacağız.......................Erdoğan Ergin 

17. 

Ne şarkılar anlamlı, ne şiirin tadı var; 

Sanma ki özlemedim, senelerin adı var; 

Aramızda yalnızca bir martı kanadı var; 

Ben çöllerde Leylayım; bu aşkta sen nerdesin? ................Ayşe Korkmaz 

18. 

Ömür denen yollarda aradım seni hergün, 

Zamanın tüneline çok haykırdım, nerdesin.? 

Ömrümün son deminde düşündüm, buldum birgün, 

Meğer gerçekte yoksun, sen yalnızca serdesin...............Mehmet Nacar 

19. 

Kuş yemi,insan demi,aşk cemi arayışta 

Söz dile,bülbül güle,kor küle yenik düşer 

Kum camı,şeytan hamı,cüz tamı arayışta 

Kul kula,sevgi mala,can yola yenik düşer.............Ertuğrul ŞAKAR 

20. 

Özlemlerim bitmedi, koca bir yıl tüketti 

Kim buldu sahiplendi, kim düşürüp kaybetti 

Arayışım aşk sözü, ömrümün saklı güzü 

Yıllar kimi eskitti, aşklar kimi terk etti...................Ahmet Hakan Yılmaztürk

Şiir Perisi Grubumuzun her hafta düzenlediği ''Bir Dörtlük de Sen Yaz'' aktivitesi sonucu oluşan ortak bir eserdir.', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/ARAYIŞ'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-arayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansıza inat seni seviyorum', 'i-mkansiza-inat-seni-seviyorum-ezgi-besen-5dv2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ŞİİR''DİR  SANA-

belki  gün  bitti

ve  belki  cama  dayayıp başımı

düşünme  vakti  geldi,

tükkenmekte  değilim,

yaşlanmakta  hiç  değilim,

ama  unutmaya  başladım  artık

sevgi  denen aşk  denen  o  uğraşı...

şarap  tadında  bıraktım  aşkı

yıllanmasına  veriyorum  ömrümü

ölsem  bile  mutlu  öle  bilmek  için...', 'ŞİİR''DİR  SANA- belki  gün  bitti ve  belki  cama  dayayıp başımı düşünme  vakti  geldi, tükkenmekte  değilim, yaşlanmakta  hiç  değilim, am...', ARRAY['Türk Edebiyatı','Şiir','Ezgi Besen']::text[], 8.5, '{"poet":"Ezgi Besen","poet_slug":"ezgi-besen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/imkansiza-inat-seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Yüreklim', 'cennet-yureklim-mehmet-selim-bataroglu-8ouzr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Parmaklarımın ucunda gizledim hep,

Önüne sereceğim, kırmızı halılarını yüreğimin.

Uzatıyor, dokunuyordum. 

Gizlerime, gizlediklerime.

Bir varsın, bir yoksun...

Bir dağsın, bir yoksunluğumsun...

Yoksunluğum, kendimle savaşlarım oldu sonra.

Seni, kendime anlattım.

Anlatamadıklarıma da,anlattım

Dalgalarımın köpüğü oldun, denizimin.

Oynaştın, sebiler gibi çakıl taşlarıyla

Bir bir topladın yüreğinin taşlarını,

Kocaman deryanda kaybettin,

İnce sızlayan iniltilerini de.

Derinliğine bıraktın acılarını,

Güneşin sıcaklığını bekledin hep,

Isıtmayacağını bile bile, 

Onca derinliklerde.

Ama bekledin...

Güneş olmayı aklından bile geçirmedin.

Sıcaklığında erimeyi göze alamadı,

Vurgun yemiş yüreğin...

Sen, sakın üzülme, üzülme...

Senli güneş de doğacak bir gün.

Mağaralar gibi inleyen,

Dağlar gibi haykıran,

Başını taşlara vuran derenin, 

Sessiz haykırışında bulacaksın kendini

Ve ben cennet yüreklim... 

Sana, o en bildik notalarımla sesleneceğim.

Üzüldüğümde de üzülme sakın.

Bilmediğim türkülerde, sana seni söyleyeceğim.

Bilmediğim notaları, besteleyeceğim sana.

Cümlelerini kuramadığım, sözler yakacağım sana. 

Ve kendimi, kendimle sunacağım sana...', 'Parmaklarımın ucunda gizledim hep, Önüne sereceğim, kırmızı halılarını yüreğimin. Uzatıyor, dokunuyordum.  Gizlerime, gizlediklerime. Bir va...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Bataroğlu']::text[], 8.5, '{"poet":"Mehmet Selim Bataroğlu","poet_slug":"mehmet-selim-bataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cennet-yureklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-i-lknur-cekici-ee6kc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlasın gözlerim

Dursun yüreğim

Senden ayrı hayatı

Yıllar yılı ben neyleyim

Geceme bıraktın dipsiz uçurum

Alnıma kazıdın kapkara yazı

Doğmasın artık sensiz bir yazgı

Bıraktığın yere yap mezarımı

Adıma yakılsın ağıtlar

Gecene serilsin al kanlar

Bırakıp da gittiğin o mezar

Estirsin ruhunda ayazlar', 'Ağlasın gözlerim Dursun yüreğim Senden ayrı hayatı Yıllar yılı ben neyleyim Geceme bıraktın dipsiz uçurum Alnıma kazıdın kapkara yazı Doğmas...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agit-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes Nefese', 'nefes-nefese-suna-aras-1kp24', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tutuşmuş mendili denizin

Oynak köpüklü sularda mest

Bahtsız kızın kulesi

Yüreğimi çekiyor incir sepetinde yılan

Kapanmak kapılar ardına kırk kilidin

O aşka, aşkla boğulan

Işığı yanlış çağıran sevdalı gibi

Dönüşü olmayan yol

Karalansa haritası silinsem

Dünya, özlemin çoğaldıkça izim yitse

Bekleyip durasın beni

Nefes nefese.

Gözlerin ki yalnızlığım

Mezar içim

Gizemli yolculuk

Denizin gizli çekici

Çırpındıkça ben yılanlara sarınsam

İmdadım olmasa, gök delinse, kopsa tufan

Ah o sular cesedimi vermese

Bekleyip durasın beni

Nefes nefese.

Yakamozlar göz kırpışın

Uzak karanlık yüreğin

Yasak yolum

Korkutan derinlik, gövdeme saplanan sancı

Bir çeken bir ürküten dipsiz boşluk

Ey uğursuz boğuntu

Sürükle az daha şeytan üçgeni

Yar yüzünün düştüğü yol

Onarılmaz acım rasgele

Bekleyip durasın beni

Nefes nefese.', 'Tutuşmuş mendili denizin Oynak köpüklü sularda mest Bahtsız kızın kulesi Yüreğimi çekiyor incir sepetinde yılan Kapanmak kapılar ardına kırk...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/nefes-nefese-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Bir Kadın...', 'bu-gece-bir-kadin-seynur-i-nal-pgah4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece bir kadın 

Tüm hayal kırıklıklarını

Doldurup örselenmiş ömrüne

Uzak diyarlara göçecek…

Bu gece bir kadın

Lâl olmuş dilindeki vuslat türküleri

Hasret iklimlerinde okunsun diye

Rüzgâra emanet edecek… 

Bu gece bir kadın

İçinde dinmeyen sızı

Düşleri kan revan

Kirpiklerini usulca umuda örtecek…

Bu gece bir kadın

Yağmalanmış

Küskün yüreğini

Onmaz aşklar mezarlığına gömecek…', 'Bu gece bir kadın  Tüm hayal kırıklıklarını Doldurup örselenmiş ömrüne Uzak diyarlara göçecek… Bu gece bir kadın Lâl olmuş dilindeki vuslat ...', ARRAY['Türk Edebiyatı','Şiir','Seynur İnal']::text[], 8.5, '{"poet":"Seynur İnal","poet_slug":"seynur-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gece-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamam Böcekleri', 'hamam-bocekleri-fidan-bulut-mbxoc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçücük bir otel odasında

Kuru tahtaya yakın şilte yatakta

Eski zamanlar tadında

Bir çekimlik nargile nefesinde

Feri sönmüş gözlerin

Bu kadar mı özler ölmeyi

İyiki varsınız hamam böcekleri

Size takılmasa gözleri 

Hatırlamayacak nefesini

Aklına gelmez mi hiç

İlk öptüğünde komşu kızını

Bıyıkların terlememişti bile

İlk kaçışındı panzerlerden

Yine o gün gibi heyecanlıydın

Bıraktığın ilk bakir gençliğinde

Kız hala sakızını çiğniyordu

Hayatın kollarına atarken çiğnediği sakız

Davan da çabuk terketti seni

Ne öptüğn kızlar var yanında

Ne de tek yürek tek nefes olduğun yol arkadaşların

Bir kısmı onurlu ya yolunda ya yer altında

Bir kısmı jakuzili saunalarında

İyiki varsınız hamam böcekleri

Size takılmasa gözleri

Hatırlamayacak nefesini', 'Küçücük bir otel odasında Kuru tahtaya yakın şilte yatakta Eski zamanlar tadında Bir çekimlik nargile nefesinde Feri sönmüş gözlerin Bu kada...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hamam-bocekleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz Geceler', 'uykusuz-geceler-halay-sadi-2zrf2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daraldım mı ne

Yoksa sıcaklardan mı

Gölgem bile bana yük

Hele gölge gibi peşimde dolanan

İnceleyen bir çift göz

Ah işte onu hiç sormayacaksın

Evimde yaşayıp

Hiç yerinden kalkmadan

Yaşamını sürdüren insan

Geç bunu da bir kalem

Ya her akşam misafirler

Yoğurt var mı, buz ver

Çay bitti mi, limonlu olsun

Sodalar dolaptalar

Fıstık kaldı mı hanım

Hıyar-acur varsa bizahmet yenge

Saati kaçınca gelmiyor ki zıkkım uyku

Hele de bu yorgunlukla

Gündüze kayıyor düşünceler

Amirler,memurlar,adam kayırmalar

Bir bir gözlerimin önünde belirip kaybolurlar

Memleketim gelir aklıma

Akıl erdiremediğim babamı düşünürüm

Mal derdine düşen kardeşimi ve yılan karısını

Oğluyla geçim derdine düşen bacımı

Aralarında yitip giden annemle

Nemlenir gözlerim, yutkunurum

Oğlum gelir aklıma acaba yatmış mıdır

Yoksa hala bilgisayar başında mı

Kalkar bakarım, odasını havalandırır

Yüzüne bakarak usulca konuşurum

Oku,yüz,basket oyna,gitar çal, sosyal ol oğul

Bugününü dolu yaşa,yarınına sağlam temeller at

Odama dönerim, koca bebeğim yan dönmüş

Kolunu yatağın sonuna kadar uzatmış

Belli ki dokunmaya çalışmış

Açılan belini kapatırım,beni arayan elini

Öperim usulca,avuçlarımın arasına alırım

Dışarısı aydınlık, yeni bir gün..

Ailem yanımda,sağlıkları yerinde

E kalanı da çözülür zamanla

Şimdi uykunun en tatlı zamanı

Zemberekler boşalmadan uyumalı.

12.7.2005', 'Daraldım mı ne Yoksa sıcaklardan mı Gölgem bile bana yük Hele gölge gibi peşimde dolanan İnceleyen bir çift göz Ah işte onu hiç sormayacaksı...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/uykusuz-geceler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefsiz', 'serefsiz-oguzkan-bolukbasi-ygz5o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özel mesaj şifremi kırıp benim adıma kişilere olur olmaz, ahlaksızca mesajlar gönderen şerefsiz neredeysen ortaya çık. ortaya çıkamazsın nasıl olsa, sen yaratık sen iki ayak üzerinde gezinen pislik, bir gün nasıl olsa ele geçeceksin, ilk tükürüğün benden tuuuuuuuuuuu senin onursuz suratına.', 'özel mesaj şifremi kırıp benim adıma kişilere olur olmaz, ahlaksızca mesajlar gönderen şerefsiz neredeysen ortaya çık. ortaya çıkamazsın nas...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/serefsiz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mevsim Döndü Sen Dönmedin', 'bir-mevsim-dondu-sen-donmedin-ask-yazari-mustafa-cifci-p44w9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'MUSTAFA ÇİFCİ

BİR MEVSİM DÖNDÜ, SEN DÖNMEDİN

Soğuk bir sonbahar akşamıydı gidişin. 

Hava kararmış, yağmur yağmaya başlamıştı. 

Düşlerimize yağmur yağıyordu, rüzgar  üşütüyordu ellerimizi. 

Gözlerin donuk, bedenin halsizdi. 

Gizli bir el  kalkışa hazırlanan otobüse binmen için  seni sürükler gibiydi. 

Sanki kalmak istiyordun.

“Baharda dönerim” demiştin, hatırlıyor musun? 

“Sakın beni unutma, bekle.”

Ben seni unutmadım sevgili.

Ben seni unutmadım.

Bütün kış,  baharda döneceğin günün  hayali ile ısındım.

 Minik öpücüklerle uyandırıp, güneşin doğuşunu gösterecektim sana. 

Çiçeklerin, denizin, kumsalın, güneşin  tadına birlikte varacak, 

gün batımlarında denizle birleşen ufuk çizgisini birlikte seyredecek,

ay ışığında mutluluk şarkımızı söyleyecektik.

   Yalan değil, kaçamak sevdalara takıldım yokluğunda  bir süre. 

Sana benzeyen her şeyi sevdim ben.  Sevdiğim  her şeyde senden izler vardı.

Aradığımı buldum sandım ama yanıldım, bulduğum sen değildin. 

Olmadık zamanlarda aklıma düştün, zamansız yaralandım.

Her sabah, seni bulmak için yollara düşmek geldi içimden, ama gidemedim. 

Yalnızlığın acısıyla gurur  satın alır oldum her gece. 

“Gelir” dedim kendi kendime. Söz verdi, gelmesi gerek. Bekledim.

Kendimi paramparça hissettim ama yine de sana kızamadım.

Unuttum  kötü sözlerini. Unuttum kapında bekletildiğimi. 

Unuttum telefonlarıma cevap vermediğini. Kavgalarımızı unuttum. 

Bir tek seni unutmadım sevgili.

Bir tek seni unutamadım. 

Hep dönmeni bekledim.

Zamanla alıştım acılara, ölüm ilanlarında kendiliğinden silinen adreslere. 

Alıştım sevdiklerimin yokluğuna. 

Ama yalnızlığa alışamadım. Hasrete alışamadım.

Sensizliğe alışamadım. Hep dönmeni bekledim.

Olmadı gülüm. Bir araya gelemedik. 

Oysa daha yolun başındaydık,  tomurcuktuk daha çatlamaya hazır, 

bahar  gelmeden  ayrıldık.  Şimdi artan yalnızlığım, senin büyüyen yokluğun var. Duvarlarda gözlerinin izi,  kapı kollarında parmak izlerin saklı. 

Sen  neredesin sevgili? Varlığın nerede? 

Bir mevsim döndü sen dönmedin.

Düşlerim  böyle dağınık değildi eskiden. 

Kara bulutlar gibi kümelenip bir yere, acılarım  yüreğimde çöreklenmezdi 

gece yarılarında.  Özlemlerim hiç bu kadar uzak olmamıştı gün ışığına. 

Hasret  bu kadar büyümemişti.

Şimdi göçebe olmuş yüreğimle her sabah yeni yolculuklara çıkıyorum. 

Gün ışığına çoğalmış hasretimle hızla kaçıyorum kara ağızlı tünellerin içinden. 

Umudun türküsünü söylüyorum öksüz bakışlarımla…', 'MUSTAFA ÇİFCİ BİR MEVSİM DÖNDÜ, SEN DÖNMEDİN Soğuk bir sonbahar akşamıydı gidişin.  Hava kararmış, yağmur yağmaya başlamıştı.  Düşlerimize y...', ARRAY['Türk Edebiyatı','Şiir','Aşk Yazarı Mustafa Çifci']::text[], 8.5, '{"poet":"Aşk Yazarı Mustafa Çifci","poet_slug":"ask-yazari-mustafa-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bir-mevsim-dondu-sen-donmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışacağız', 'alisacagiz-selahattin-yetgin-4gwgg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu filmi izlemeyi ne çok istersek

Şiirlerimiz düşecek ıslak gecelere,

Sokaklarda çılgın gölgeler gibi yürüyüp

İki ayrı yürekte yaşamayı öğreneceğiz.

Ben bu şehrin belalısı, sen sevdalısı,

Çatılarda yağmur beklemeye alışacağız

Alışacağız karanlıklarda kör yaşamalara,

Melânkolik sevdalara da katlanacağız.

Sözüm şu''ki yarım kaldı çayım,

Yalnızlık oldu dudağımdan dökülen,

Kavı ıslanmış kibritlere döndüm,

Çürüdü elimdeki tahta kaşığım.

Bir gece sabaha karşı bulacaksın beni,

Suskun kalemimi alacaksın cebimden,

Derin soluğunu hissedeceğim sonra,

Yorgun gözlerimle bakacağım son kez sana.', 'Bu filmi izlemeyi ne çok istersek Şiirlerimiz düşecek ıslak gecelere, Sokaklarda çılgın gölgeler gibi yürüyüp İki ayrı yürekte yaşamayı öğre...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alisacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz yaşlarım', 'goz-yaslarim-sair-gaddar-16-ys46b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gittin sonunda,

Gittin,

Gidişini görmemek için,

Gözlerimi kapattım,

O kadar insafsızca  gidişti ki,

Dağlar dayanamadı,

Bu gidişe,

Her yer koptu,

Sanki sanki kıyamet zamanıydı,

Fırtınalar koptu yüreğimden,

Sanki azrail canımı almak için bekliyordu,

Ve sen ezgim sen,

Arkandaki kıyamete bakmadan,

Gittin.

...

Gittikten sonra,

Ateşler çıktı söndürdüler,

Denizler dalgalandı durdurdular,

Okyanuslar kurudu doldurdular,

Ama içimdeki ateş,

Hala alevlenmekte,

Cehennem ateşine döndüm,

Bu kadar insafsızca gidiş olmamalıydı,

Ama sen ama sen gittin.

...

Bir yıkım gibiydi gidişin,

Gönül bahçemi kurutupta gittin,

Ellerimi boş bırakıpta gittin,

Duygularımı çalıpta gittin,

Ve sen insafsız hayatımı yıkıpta gittin.

...

Gözlerinden okuyordum koparacaksın kıyameti,

Ve gözlerin söylüyordu gideceğini,

Beni idamla cezalandıracağını,

Gerçi gideceğine inanmıyordum,

Ama sen insafsız beni yanıltıpta gittin,

Göz yaşlarımla bırakıpta gittin,

Sevgi fidanlarımı koparımpta gittin,

Ve sen insafsız yüreğimi alıpta gittin,

Gittin gittin gittin.

...

Gitme aşkı yaşayalım,

Gitme seni baş tacım yaparım,

Gitme Tüm acıları geride bırakalım,

Gitme sevdayı beraber taşıyalım,

Gidersen dünyayı yıkarım,

Demeden gittin.

...

Arkandan ne göz yaşları döktüm,

Ne senin için ağıtlar yaktım,

Ne de seni sevdiğimi haykırdım,

Çünkü gitmiştin artık,

Ve sen artık yoktun.

...

Bu can hergün kanasa,

Ömür boyu cezaya çarpsa,

Ne yazar,

Zaten artık yoksun,

Ve bidaha olmayacaksın.

...

Bak şimdi gözler körleşmiş ağlamaktan,

Dağlar patladı bizi haykırmaktan,

Denizler kurudu bizim için dalgalandığından,

Ve bir candı ki senin için senin için yaşayan,

Ve sen insafsız arkana bakmadan gittin,

Gittin gittin gittin.

...

Git diyemedim canım yanıyordu,

Git diyemedim dilim dolanıyordu,

Git diyemedim ezgim yüreğim kanıyordu,

Ve sen beni yıkıpta gittin,

Beni parçalayıpta gittin,

Yüreğimi alıpta gittin,

Gittin gittin gittin.

...

Şimdi kayıplardayım,

Sensiz küşe başlarındayım,

Her gece seni çaldıran şarkılardayım,

Seni anlatan dudaklardayım,

Senin için bu yuollardayım.

...

Ezgi demek ne güzel gelir insanlara,

Ezgi mutluluk anlatır sanki,

Ezgi gitti denizler kurudu,

Ezgi gitti ağlayanlar bıraktı,

Ezgi gitti bu can onsuz yaşadı,

Ezgi demek acıların baş parmağı,

Ezgi demek hayatın zevksiz anlamı,

Ezgi demek yıkılmak demek,

Ezgimi beni alıpta gitti,

Ezgim beden var can yok,

Ezgim aşk var yaşatan yok,

Ben cansızda olurum,

Ama ezgim artık yok,

Yok yok yok.

...

Ezgim sen içimde kopan fırtınaları görmedin,

Ezgim bu beden de can taşır bilmedin,

Gidersen olacakları düşünmedin,

Ve sen insafsız gözünü kırpmadan,

Gittin gittin gittin.

...

Anladım bu can sensiz olmaz,

Sen varken gözlerim yaşarmaz,

Canım yanmaz,

Ezgim olsunda acılar çekeyim,

Ezgim olsunda sensiz öleyim,

Ezgim olsada bu canı sana vereyim,

Diyemedim gittin.

...

Şimdi sana birkaç cümlem olacak,

Bu cümlelerim senide yıkacak,

Sanada acılar tattıracak,

Ezgim sana sesleniyorum,

Ben ezgim ben,ne demek,

Ben yolu gösteriyorum,

Sana sesleniyorum,

Git git git git artık git,

Git ezgim git,

İstediğim herşeye sahip olsamda,

Şunu bilki sensiz mutsuzum.

Git artık git.

...', 'Sen gittin sonunda, Gittin, Gidişini görmemek için, Gözlerimi kapattım, O kadar insafsızca  gidişti ki, Dağlar dayanamadı, Bu gidişe, Her ye...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":123,"source_url":"https://www.antoloji.com/goz-yaslarim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört mevsim Sürmeli Sevdalar', 'dort-mevsim-surmeli-sevdalar-ask-yazari-mustafa-cifci-qahjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmurlu bir gün gelmiştin bu kente

akşamdı / yol üstünde buluşmuş, bir cafede oturmuştuk

kısa saçların vardı omuzlarına dağılan

gözlerinde tatlı bir içtenlik

konuştukca açılıyor, kendimizi birbirimizde buluyorduk 

mevsim kara kış olsada

tutunca ellerinden kalbim kocaman ağustos

maskeli sevdalardan kaçarken buluşmuş,

yürek sesimizi birleştirmiş gibi mutluyduk

fırtına uzaklara götürmüştü düşlerimi

dostluğun en saf, en doğal halini paylaşıyorduk

ve ellerin çok güzeldi

sen geldin, bahar geldi ansızın

dağların ardını aşıp, gidilmemiş denizlere yelken açtım

yalnız değildim. sen vardın. uzak kentlere gidip geldim

duygularım çoştu. sevincimi uçurtmalara yükledim

adım adım yaklaşırken otobüs durağına

soğudu ellerim. üşüdüm. gölge olup seni takip etmek, 

diz çöküp kalman için yalvarmak istedim

çünkü seni çok sevdim

ama yapamadım sevgili. yapamadım

çünkü bu aşk dört mevsimlikti

ne gölge olmak

ne de diz çöküp yalvarmak deð il

hissedebilmekti

söz vermekle aşk yaşanmıyordu

sanki birden yaşlandık ayrılırken

hasret büyüdü

kışın ortasında, bahara

bahardan, sonbahara düştük

sen ellerini unuttun bende

bense yüreğimi sende 

severken ayrılığa düşmekti bunun adı

hasret kalmak, özlemek, hayalini kurmaktı

bu nasıl hayattı

sen gittin, kırıldı yüzümdeki sevinç

koyulaştı sessizlik ben karanlık oldum

sen gittin, yarım kaldım ben

sen gittin, düşlerime ağladım

sen gittin, tenha oldu bütün sokaklar

bu kent seninle güzelmiş

yaşam telaşında hızla kirlenirken dostluklar

hatırlanan bir şeyler vardı gözlerinde

akşam ağır çökmüştü ellerime

yılların yükünü otobüs duraklarına yığıyordum 

akşamdı. bir bir aydınlanırken evlerin odaları

ben ışığı yanmayan yollarda yürüyordum

uzun yollardan gelmiştin

uzun yolculuklara çıkmanın zamanıydı belki de

mevsim kara kış, günü birlik olsada ziyaretin

tutunca   ellerinden kalbim kocaman ağustos şenliğinde



düşün ki, tekrar gelmişsin bu koca kente bir sabah

uyku tutmamış gözlerim, seni beklemişim gece boyu

‘şehri gezelim’ diyorsun, ‘ne var ki evde, dört duvar arası’

el ele tutuşup

şehrin dar sokaklarından geçip, sahile inmişiz

bu şehirde kötü anılarını hatırlamış gibiş

martıların çığlıklarında yalnızlığa düşüyor yüzün

yol üstlerinde akşamdan kalma tinerci çocuklar

gülüşün kirleniyor dudaklarında. gözlerinde telaş büyüyor

küfürleri duyuyorsun açık pencerelerden 

bardağı taşıran son damla oluyor ağlayan çocuk sesi

elini elimden çekiyorsun, dudakların buzlaşıyor 

gözlerinde deniz küçülüyor, anlamı yok gemilerin

kaptan boş yere bekliyor, bütün tayfalar firarda

‘yapma’ diyorum, ‘ne olur, yanındayım işte’

‘sevgin yeter bana. bu dostluk yeter''

boşlukta sallanan bir tebessümle zora ki gülümsüyorsun

yüreğinde yalnız olduğunu hissediyorum

hızla koşuyoruz arkamızda sanki tazı köpekleri

kapanmaya hazırlanan loş ışıklı cafe sığınma yerimiz oluyor

anlamını bilmesekte kendimizden geçiyoruz yabancı şarkılarda

gün doğuyor.herkes evine giderken biz hala sokaktayız

kendi kendimizi kandıyoruz, sevgi bahane

‘sorun değil, boş ver’, diyorsun, ‘unut gitsin’

en azından eğlenir gibi yaptık, ağlamamak için

gece kötü bitiyor. biz kendimize ağlıyoruz.

kaybolmuş çocuklar kırgın ellerimiz

anlıyorsun sen de

ne kadar kalabalık olsakta

yalnızız biz

 bu koca kentte insanlar yalnız

sen de yalnızsın biraz 

ben de yalnız

‘yarın akşam yolcuyum’, diyorsun

‘gidiyorum’

uzun yollardan gelmiştin

geri dönmenin zamanıdır, yolun uzun

olsun. git.

gitsen de bitmeyecek ya bu dostluk

gitsen de unutmayacaksın ya

göndermek istemezdim ya seni

ama gitmelisin. gitmen gerek

seni sevdim

 gidebilirsin

gitmiş olsanda uzaklara

çünkü hep yüreğimdesin

kısa dostlukları sevmiyorum ben

 parlayıp sönen yıldızlar gibi

olmamalı sevgiler 

 dört mevsim sürmeli dostluklar

ve ellerin çok güzeldi senin

ellerin ben de saklı', 'yağmurlu bir gün gelmiştin bu kente akşamdı / yol üstünde buluşmuş, bir cafede oturmuştuk kısa saçların vardı omuzlarına dağılan gözlerinde ...', ARRAY['Türk Edebiyatı','Şiir','Aşk Yazarı Mustafa Çifci']::text[], 8.5, '{"poet":"Aşk Yazarı Mustafa Çifci","poet_slug":"ask-yazari-mustafa-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":103,"source_url":"https://www.antoloji.com/dort-mevsim-surmeli-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-selahattin-yetgin-i33v3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine tırmanıyorum fırtına tepelerini,

Azığım şiirlerim, katığım sen,

Yürüyorum bitimsiz yollarda,

Bıraktım geride, anılarımı, sevinçlerimi.

Ne varsa belleğimde attım bilinmezliklere,

Neyim varsa kopardım sana dair

Islığım şarkılara karıştı, karıştım senelere,

Yürüyorum seninle, yalancı sensizliklere.

Koluna yapıştım zamanın  kara gözlüm

Nerede akşam, orada sabah anlayacağın

Bir yerlerde sevecek birilerini bulurum elbet,

Elbet yüreğimde kalacak sevgili bulurum.

Gidiyorum üzüm gözlerinin ülkesinden,

Yıkık kentlerde sürme sakın izimi,

Ölü ozanlar ülkesine gidiyorum

Gün olur okursun, sana yazdığım son şiirimi.', 'Yine tırmanıyorum fırtına tepelerini, Azığım şiirlerim, katığım sen, Yürüyorum bitimsiz yollarda, Bıraktım geride, anılarımı, sevinçlerimi. ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidiyorum-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Bugündür', 'yarin-bugundur-selahattin-yetgin-q2e8z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamansız yağmurlar yağıyor yurduma. İnsanların yaşam koşuşturmacasında seni arıyorum. Aklımın ve yüreğimin yüzdelerini gün boyu sen meşgul ediyorsun. Sen dolanıyorsun bir tek damarlarımda. Ellerimin terinde sen, gözlerimin ferinde sen, ruhumun yorgun köşelerinde sen varsın.

	Çocukların rengarenk bir gökkuşağı oluşturduğu uzak mahallelerde dolaşıyorum bir başıma. Dizleri kan içerisinde bir çocuğu kaldırıyorum tozlu yerlerden. İpeksi saçlarında ellerimi dolaştırıp susturuyorum onu. Sonra kalabalık sokaklardan geçip sana yürüyorum tekrar. 

	Oysa, sen yoksun. Senden bana kalan anıların bir tek. Bu anı labirentlerinde ne kadar dolaşsam, ne kadar onlardan kurtulmaya çalışsam beceremiyorum. Kapalı kalmış bir kuş gibi sağa sola çarpıp son çırpınışlarımı da uğruna harcıyorum. Ne kadar çabalasam biliyorum ki senden kurtuluş yok, biliyorum ki kurtulmak imkansız senden.

	Hayal kuyularına dalacağım şimdi. Kör karanlıklarda, dakikalarca süren bir düşüş yaşayıp yakalayacağım seni. Baharları getiren, yurduma sevgi çiçekleri ektiğin günleri hatırlayıp, bir masal atına binip gidişine kadar bir bir hatırlayacağım.

	Seni bana getiren rüzgarlar bu mevsim uğramadı yakınıma. Gözlerime tozlar doldu da yılmadım gelişini beklemekten. Kırıldım, içlendim, gelişine fallar açtım. Ama sen gelmedin. Biliyorum, seni beklemek, senin tekrar gelişine şarkılar adamak nafile gönlümü avutmaktan başka bir şey değil. Kulağıma dolan sevdiğin şarkılar yakar oldu yüreğimi. Sen başka yarınlarda, başka kollardasın şimdi. Ellerin bir başkasını ısıtmakta, gözlerin bir başka göze bakmakta. Ve en acısı, en zor''u birtanem o lapiska saçlarını bir başkası okşamakta.

	Beni sorarsan eğer, yine buralardayım. Kırık merdivenli, loş ışıklı yerlerde, küskünlüklerimin bedelini ödemekteyim. Bir elimde kalem, bir elimde sevdamın ruleti, durmaksızın şansımı döndürmeye çalışıyorum. Akşamların erken indiği buralarda gecelerle dost, gündüzlerin kaypak dönencesiyle ömür tüketiyorum.

	İşte böyle yağmur gözlüm... Umut karelerinin hiçbirinde yokum artık. Hiçbir negatifte aslım yok. Uçurtmasını kaybetmiş çocuklar gibi bir o yana, bir bu yana koşar oldum. Dizlerime erken inen ağrıları hissetmesem aldırmayacağım geçen zamana. Nice yarınlar var önümde deyip, herşeye boş vereceğim. İçinde yaşadığım iğrenç daireye aldırmayacağım anlayacağın. İçerisinde sen olmasan bu yalan dünyayı ateşe verip yakacağım kara gözlüm.

  Sonraya bırakılmış güzel günlerimizi çocuk yüreklerine ekip, bir zaman seninle durgun günler yaşadık. Ben belki dün öldüm, sen içindeki ateşle yarını bekliyorsun. Ben, uyudum uyanışsız uykulara dalıp, sen buğday gövdelerinde hasata durdun. Üzülüp yüreğimi gösterdim sana, görmedin. Söğütten düdükler yaptın çocuklara. Ağaçlardaki limon çiçeklerine konduk şifa diye. Yabancı kaldık sevişen yüreklere. Aşıkların peşinde gölge olduk yürüdük peşi sıra. Ne yaptıksa yıkamadık içimizdeki kör tabuları ne fayda.

	Bu olmazlar çemberinde dönerken dünya, sen içindeki volkanları çağırdın yüreğime. Ben ellerimdeki Mayıs çiçekleriyle sana baharları sundum. Kabaran denizlerin köpük kulelerinde bir zamanın alevli sırtında katetdik sonra karanlıkları. Bir yıkık evde bulduk kendimizi. O evlerde sarıldım sana doyasıya. Odanın tavanına resmini çizdim. En gizemli resimlerle süsledik odayı. Bir gül koyduk vazoya, yanıbaşına taze su. Dünya küçüldü yüreğimizde, kucakladık dünyayı. Yuvarlandık karlı tepelerden bir sevgi topu olduk, düştük yüreklere, dağıldık, kaybolduk...', 'Zamansız yağmurlar yağıyor yurduma. İnsanların yaşam koşuşturmacasında seni arıyorum. Aklımın ve yüreğimin yüzdelerini gün boyu sen meşgul e...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarin-bugundur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Sevgilim', 'yagmur-sevgilim-ask-yazari-mustafa-cifci-8ivxs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen yoksun bu gece.

sen yoksun, yağmur var bu gece.

ıslanmak için sokaklarda yürüdüğümüz yollar bomboş bu gece.

bu gece yağmur var.

yağmurun altında ağlıyorsun, gözyaşların damla damla yanaklarında.

yağmur ve mektupların var bu gece.

''...iyiliklerin ardından içimizi buz gibi yapan, bizi üzen bir şeyler hep sinsice yaklaşır değil mi?  acaba bir gün, bir şiirinizde, ıslanmamak için koşarken, yolun kıyısındaki bir taşın oyuğunda ışıldar bir vaziyette iken beni görüp avucunuza aldığınızı yazacak mısınız? 

acaba birileri, benim, yalnızca bir avucu dolduracak kadar saf yağmur suyu olduğumu bilecekler mi? 

giderek avuçlarınızda ıslanıp, şırıl şırıl akan dere sularına verdiğiniz bir damla gözyaşı  içinde olduğumu bilecekler mi? ”

korkarım bilmeyecekler sevgili! 

bilemeyecekler…

bu kadar saf ve temiz bir sevdanın,

bir yağmur damlasında saklı olduğunu kimse bilmeyecek.

kimse anlamayacak, uzaklığının bu kadar yakın olduğunu.

bir yıldız da buluştuğumuzu, yağmurdan hızlı hızlı kaçan insanlar bilmeyecek.

seni  ne çok sevmişim yağmur damlası

ama sen yoksun bu gece

mektupların var

''cama vuran her damla minik bir öpücük olsun buradan ta oralara giden. her damla da, benim bir gülücüğümü görün pencerenizde. her damlanın çıkardığı seste, benim sesimi duyar gibi olun. her damla, tertemiz bir nefes olsun siz de aşka giden....''

ağlamak kadar gülmek var yaşamda....

''duyguların en yoğun halini, özlemlerin en büyüğünü, 

sevdanın en zorunu istiyorum belki de.

bir sen, bir de yağmur var hayatımda.

yağmur damlaları saçlarından kayıp, alnından kirpiklerine dökülür, gözlerinden, yüzüne dağılıp yanaklarını okşar, dudaklarına çarpıp, boynundan hızla kayıp ince gömleğini ve dantelli sütyenini ıslatır, göğüslerinin arasından süzülüp akardı.....

avuçlarımı yüzüne değdirir, parmaklarımı dudaklarında gezdirirdim. utanır gibi olurdun kimi zaman, çekinir, gözlerini, gözlerimden kaçırırdın. bazen de, utanç halini yağmura salmış gibi, hiçbir şeye aldırmadan, sımsıkı sarılırdın bana. ıslak saçlarını okşar, nemli dudaklarından öperdim.....

bu gece yalnızım....

sen yoksun bu gece...

bu gece yağmur var. yalnız ağlıyorum ıslak camların önünde. 

gözyaşım yağmur damlası.

bu gece ıslanmak istemiyorum. söyle yağmura,

dinsin, yağmasın bu gece....

''gözyaşını bilirim diyenlerin aslında bilmediklerini anlarsın bir gün ayrılıklarında hiç ağlamadıklarını görünce. yeşili severim diyenlerin, 

sevmediklerini anlarsın bastıkları zaman bir ot parçası gibi yeşil çimenlere. güzeli severim diyenlerin de, bir gün tokatladıklarını pembe ve masum bir yüzü,

yanıldığını anlarsın.....''

ben seni ne çok sevmişim yağmur damlası...

seni ne çok sevmişim…

''yıllarca senin dilinden konuşmuşum,

senin gözlerinle görmüşüm, senin yüreğince sevmişim, düşlerimi seninle büyütmüşüm. yorgun ve sonu gelmeyen özlemlerimi yağmur damlalarında beslemişim…

oysa sen,

teslim olmuşsun baskılara,yasaklara takılı kalmışsın

yenilmişsin. yenilgiler intikama dönüşmüş boş yere. 

gururun kırılmış, sen yıkılmışsın. her gün biraz daha akışı olmayan nehirlere dönmüşsün…..

ben seni ne kadar çok sevmişsem,

aramıza hep yağmurlar girmiş

hep ıslak kalmış el ele tutuşan ellerimiz.

gözlerine hep hüzün yerleşmiş. 

seni ne kadar çok öptüysem, o kadar uzaklara düşmüşüm. 

ayrı gecelerde hep sana ağlamışım. yokluğun büyümüş, 

yalnız kalmışım. ben seni, ne kadar sevdiysem 

incinen çocuk bakışlarında kalmışım. 

hep koşmuş, yetişememişim yol ayrımlarına. 

seni ne kadar çok uğurladıysam, o kadar çok beklemişim 

dönüşü olmayan yollarda.

sen hep uzaklara gider olmuşsun.

sonbahar ayrılık demek olmuş..

ben senin,

eylül gecelerinin ay ışığında güzelleşen yüzünün tutkunu olmuşum. 

fırtınanın önünde sürüklenip,

saçlarına takılıp eriyen bir kar tanesinde, yağmur damlası olmuşum...

zordu bir tanem...

hayatın gerçeğini düşlerinin ıslığıyla bestelenmiş, 

kanayan bir şarkıya dönüştüren yüreğinin atışlarını dinlemek.

o ıslığın seni götürdüğü yere kadar çekip gitmişsin sen.

yankı seslerinde anlamışım seni kaybettiğimi

bağbozumu hayallerimde ıslak kalan düşlerim kurumamış

ve sen yağmurda yürürken hep susar olmuşsun

el ele tutan ellerimiz ise hep ıslak kalmış

dudaklarımızda bir garip yağmur şarkısı...

ben sana tutkun,

sen bahar yağmurlarına aşıktın.

buğulu camlara resmini çizerdim, güneşle birlikte yok olurdun….

koşarak gelsen, diyorum yağmurlu bir gecede,

çocuk bakışların gözlerimde.

ellerin ıslak, gömleğin ıslak, sarılsan boynuma. sımsıkı kuçaklasam seni, usulca öpsem yağmurlu dudaklarından. ateşe kesilse birden üşümüş bedenin. 

ellerin sımsıcak olsa avuçlarımda.

bu aşk hep sıcak kalsa. ''boş ver'' desen bana.'' boş ver, yaşamak işte bu sevgilim'' geri dönüşü olmayan bir yola çıksak birlikte. 

bir sen, bir ben, bir de yağmurlar olsa. mutluluk ellerimizde olsa. 

doyulur mu yaşama? 

ama korkuyorum aramıza mevsimlerin girmesinden.

korkuyorum sana geç kalmaktan. kaybetmekten korkuyorum seni.

oysa aşk,

her gün büyütmeli kendini ayrılıklarda.

bu gece yağmur var. ıslak camların önündeyim....

ya sen? 

sen neredesin yağmur damlası? 

yalnız mısın? 

yoksa,

bütün kadehlerin sana kalktığı bir masa da 

baş oyuncu musun bu gece? 

ödünç alınmış, 

yapmacık gülücüklerin karşısında mısın? 

sen neredesin yağmur sevgili? 

neredesin? ….', 'sen yoksun bu gece. sen yoksun, yağmur var bu gece. ıslanmak için sokaklarda yürüdüğümüz yollar bomboş bu gece. bu gece yağmur var. yağmurun...', ARRAY['Türk Edebiyatı','Şiir','Aşk Yazarı Mustafa Çifci']::text[], 8.5, '{"poet":"Aşk Yazarı Mustafa Çifci","poet_slug":"ask-yazari-mustafa-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":93,"source_url":"https://www.antoloji.com/yagmur-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Çökmüş Kalkmaz', 'huzun-cokmus-kalkmaz-ahmet-nural-ozturk-tzo6g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizlere dalarım

Yakamoza dalgalara

Mehtabın altında sörf yaparım deniz kızlarıyla

Hüzün kalksın kalkmaz

Yollara düşerim

Taksilere

Otobüslere

Kamyonlara

Katar katar trenlere yayan gidenlere

Kervan kervan develere

Sürü sürü kuşlara

Hasret geçsin geçmez

...........

.........

.......



Sürü süre kuşlara

Hasret geçsin geçmez

........

........

.......

........', 'Denizlere dalarım Yakamoza dalgalara Mehtabın altında sörf yaparım deniz kızlarıyla Hüzün kalksın kalkmaz Yollara düşerim Taksilere Otobüsle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/huzun-cokmus-kalkmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Ayrılığı', 'eylul-ayriligi-ask-yazari-mustafa-cifci-jukre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün ışığının  solgun renkleri karşı yamaçlara yaslandığında, kapı önünde oturur, uzakları seyrederdim. Gün tutunmaya çalışır gibi ağaç dallarına düşer, ağır ağır kaybolur, yok olurdu. Her yer  toprak rengine bürünüp, güneş bir başka diyarlara göç ederken,  gökyüzünde aydede görünür, sanki bana gülümser, göz kırpardı. Uzaktan gelen çocuk seslerini duyardım. Ağlayan bebelere seslerine üzülürdüm. Sessizlik kapladığında çevreyi tatlı bir huzur dolardı sokaklara. Ben eylül akşamlarını çok severdim. Okulların açılmasına az bir zaman kala, kitaplarımın tozunu alır, şiir defterimi tekrar kaplar, yeni çekilip henüz yaptırılmayan fotograf makinasındaki filmi çıkarır, çantamın en dip köşesine yerleştirirdim. 

	Eylül benim için biraz fotograf demekti.

	Kimi geceler uyku tutmaz, yatağımın içinde dönüp dururdum. Bazen sıkıntıdan ne yapacağını bilemeden pencereden bakar, evin içinde gezinir, balkonda oturur, ay ışığında hayallere dalardım.

	Eylül benin için  ayışığında  yalnızlık demekti.

	Yaprak dökümüydü eylül.

	Anıların sarıp sarmalanıp hatıra defterinde saklandığı, yeni hatıra defterlerin satın alındığı dönemdi eylülün bir diğer adı. 

Bir başka şehre göç demekti eylül.

 	Babamın bir başka kente tayin edilmesi demekti. 

Sevdiklerimden ayrılmaktı eylül.

	Çocukluğumun geçtiği o şehirden ayrılmadan bir gece önce, yine birlikteydik sevdigim kızla.

	İsmi  Eylül’dü. Ben kendisine ‘Eylül Kız’ derdim.

	Ellerime sarılmış, yalvarır gibi “gitme” diyordu. “Unuttun mu sözlerimizi? Hayallerimizi unuttun mu? Her şeyi olduğu gibi bırakıp nereye gidiyorsun? ”

	Her şeyi yüzüstü bırakıp gidiyordum.

	“Gelirim bir gün”, demiştim. Gitmek zorundaydım. Kendim de inanmıştım bir gün geri döneceğime.

	“Yalan” demişti. “Bu eylül ayrılığıdır, bir daha geri dönmezsin. Ayrılık olmayacak diye birbirimize söz vermiştik. Okul bitiminde ben çalışacak sen okuluna devam edecektin. Hani bir de kızımız olacaktı, unuttun mu? ”

	“Hayır unutmadım”, demiştm. “Unutur muyum hiç? ”

	“İsmi ne olacaktı? ”, diye sormuştu gözlerime bakarak. Gözleri ağlayacakmış gibi doluydu. 

	“Yaprak” demiştim. “Adını yaprak koyacağız. Sen Eylül, kızımız ‘Eylül Yaprağı’ olacak.”

	“Evet”, dedi sözlerimi onaylarcasına. “Yoksa dönecek misin? Bir gün kaldığımız yerden devam edecek miyiz? Bu hayat bizim olacak mı? ”

	Hiç bir şey söylemeden  uzaklara bakmıştım. 

Güneş batmak üzereydi. 

	Dünyanın diğer yanında aydınlık başlıyordu.

	Eylül biraz inanmaktı yaşamın büyüsüne. Hayallere dalmaktı.

	“Daha büyümedik bile”, dedi hüzün yüklü sesiyle. “Daha evlenmedik, çocuklarımıza isim bulduk. Torun veremedik anneme. Sevişemedik bile. Daha bir araya gelemedik. Ve şimdi de gideceğini söylüyorsun. Nasılda kolay söylüyorsun.”

	Kolay olmadığını ikimizde biliyorduk. Hiç bir şey kolay ve basit değildi.

Gitmekte zor, kalmakta imkansızdı.

	“Seni öpmek istiyorum” demiştim  neşe olsun diye. “Öpüşmekte sevişmektir bana göre bilirsin.

	“Olmaz” dedi. “Günlerdir saatlerce yalnız başbaşa kaldık ama beni öpmek istediğini hiç söylemedin o zamanlar. Elimi tutman yetiyordu sana. Oysa ben de öpüşmek istiyordum.”

	Utanmış gibi başını öne eğmişti. 

	Eylül biraz çocuk olmak demekti.

	Utanmaktı biraz.

	O akşam el ele tutuşup, büyük binaların gölgelerinden şehrin bütün sokaklarını dolaşmıştık. O şehrin bütün sokakları  güzel anılarımızla süslenmişti. Kentin uzak mahalle araları, gecekondu  evleri, çay kahvehaneleri, sokak araları, ağaç gölgeleri  sevgimizle dolmuştu. Sahile inmiş, ayaklarımızı deniz suyuyla yıkamıştık. Çıplak ayakla kumların üstünde yürümüş, koşmuştuk. 

Uzaklarda martılar çığlık çığlıktı. Sanki martılarında kapılarını çalmıştı eylül ayrılığı, hepsi ağlıyordu sanki. 

	Eylül biraz çığlık atmak gibiydi, sessiz de olsa.

	Biraz da ağlamaktı. 

	Bir başka kente yerleşip ayrılığın  acısıyla uyumanın zor olduğu gecelerdi eylül.

	Geceleri bir türlü uyku tutmuyordu. 

	Aşkların en güzeli de olsa, vedalaşmanın adıydı eylül.

	İlk yaz çiçeklerinin, bahar çoşkusunun mevsim dökümüydü.

	Sonbaharın adıydı eylül. 

	Eylül yaprak dökümüydü.

	Çoşkunun, sevdanın, duygunun,heyecanın yaşanıp, ayrılık anlarında susmanın adıydı.

	Dudakların sustuğu anlardı  eylül.

	Bir adım yalnızlığa gitmekti.

	Susmaktı eylül. 

Hüznün yürekte çoğalmasıydı.

	Acıydı, gözyaşıydı eylül. 

	Yaşamışsan eğer bahar aşklarını, eylül acı çekmenin zamanıydı. 

Sanki bir şeylerin bedelini ödemek gibiydi.

	Rüzgarın saçları dağıttığı rüzgarın adıydı eylül.

	Eylül sevdiğim kızın adıydı.

	Ve eylül ayrılık demekti.

	Kimi zaman bir çıkış gibi gördüğümüz yol aslında bizi bir uçurumun kenarına götürebiliyordu..

	Yüreğimizin tamamını dolduran sevdamız gün geliyor yerlerinde yeller esebiliyordu.

	İnsan bir çok şeyi kazanıp sonrada kaybedebiliyordu.

	Yok olanların yerlerini yenilerle doldurabiliyorsak yitirmeyiz yaşama sevincimizi, ellerimizin sıcaklığını.

	Zaten geriye ne kalıyor ki, koskoca bir yalandan başka.

	Bu gerçek insanlığın tarihine bakıldığında anlaşılıyor ama bizler hayatın bu gerçek yanını göremiyoruz.

	Bir zamanlar delicesine sevdiğim, onun herşeyine aşık olduğum insanı kaybetmiş olsamda yine hayatımda vazgeçemediğim sarı saçlı bir dostum var…

	Kimi zaman cep telefonunu ofisinde unutup,  geri alması için saatlerce kapının açılmasını beklediği için beni de bekletmiş olsada… 

	Karşısındaki eczacı çocuk her gün ona çikolata göndermiş olsada….

	Bende sanırdım ki sadece eczanelerde ilaç satılıyor..

	Ve pahalı araçıyla hava atan gencin gül göndermesi..

	Hiç biri umurumda değil, önemli değil o kadar…

	Çünkü çikolata alerji yapıyor sevdiğimi, yapmıştai kaşımaktan kolları, elleri kızarmış..

	Çiçeğe gelince, onun zaten kendisi çiçek…', 'Gün ışığının  solgun renkleri karşı yamaçlara yaslandığında, kapı önünde oturur, uzakları seyrederdim. Gün tutunmaya çalışır gibi ağaç dalla...', ARRAY['Türk Edebiyatı','Şiir','Aşk Yazarı Mustafa Çifci']::text[], 8.5, '{"poet":"Aşk Yazarı Mustafa Çifci","poet_slug":"ask-yazari-mustafa-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/eylul-ayriligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-arda-sila-i91fl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ve ben bir elmanın farklı renkte açmış iki yarısı gibiyiz,

Sen sihaysın ben beyazım, yada ben siyahım sen beyazsın,

Sen gül goncası ben onu çevereleyen  ve saran dikenli ağacı,

Sen ve ben farklı olsakta birlikte tek parça ve mutlu olabiliriz,

Farklarımız önemli değil, aslolan birlikte yaşayabileceklerimiz, 

Birbirine benzeyen iki insan birleşip tek parça olmaz,

Olsa da hayat sıkıcı ve monoton olur bir süre sonra,

İnsan tıpkı kendisi gibi olanla farklı bir şey yaşayamaz,

Seni sen olduğun için sevdim, bana benzediğin için değil,

Önemli olan aşktır, sevgidir, saygıdır, farklılıklar da rengidir.', 'Sen ve ben bir elmanın farklı renkte açmış iki yarısı gibiyiz, Sen sihaysın ben beyazım, yada ben siyahım sen beyazsın, Sen gül goncası ben ...', ARRAY['Türk Edebiyatı','Şiir','Arda Sıla']::text[], 8.5, '{"poet":"Arda Sıla","poet_slug":"arda-sila","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ve-ben-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Beş Geçiyor-DENEME', 'aski-bes-geciyor-deneme-meral-yagcioglu-gzrqx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaderin sillesi sinede şakladı 

Tarumar duygular yürekte patladı

Vuslatsız ayrılık ateşinde yandı

Küle döndü yürek külleri dağıldı

Koptu hayat ipi hayalleri vardı 

Suya düştü bir bir ümidi kalmadı

Sevdiği el oldu yüreği yaralı

Elde ne sevdalı ne de aşk masalı

Aşkı beş geçiyor hüzün vakti geldi 

Ağla yaslı gönül sevda yeli dindi

Acıdan başkası yüzüne gülmedi 

Mezarını kazın ölüm vakti şimdi 

		04/06/2005', 'Kaderin sillesi sinede şakladı  Tarumar duygular yürekte patladı Vuslatsız ayrılık ateşinde yandı Küle döndü yürek külleri dağıldı Koptu hay...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aski-bes-geciyor-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Çıkmazı', 'sevda-cikmazi-filiz-sarikaya-8z1gy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinde aradığı neydi gözlerimin

Ellerinde hissetmek,

Kalbinden istediği neydi.....? 

Bir umut ışığı.....

Sıcak bir dokunuş.....

Bir yudum sevgi.....

.......

Şimdi

Gözlerim buğulu

Ellerim soğuk

Kalbim kırık

Sevda çıkmazlarına düştü gönlüm.....', 'Gözlerinde aradığı neydi gözlerimin Ellerinde hissetmek, Kalbinden istediği neydi.....?  Bir umut ışığı..... Sıcak bir dokunuş..... Bir yudu...', ARRAY['Türk Edebiyatı','Şiir','Filiz Sarıkaya']::text[], 8.5, '{"poet":"Filiz Sarıkaya","poet_slug":"filiz-sarikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MektuP', 'mektup-levent-nalcacioglu-rf7px', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne senden bir haber var,

Ne de gönderdiğin mektuptan...

Hadi mektup postaya takıldı,

Peki gülüm sesin nerde...? 

Yoksa sen öldün mü...? 

Yoksa kara toprak senide mi aldı...? 

Yoksa ölüm mektubunmu gelen...? 

Yoksa benmiyim ölen...?', 'Ne senden bir haber var, Ne de gönderdiğin mektuptan... Hadi mektup postaya takıldı, Peki gülüm sesin nerde...?  Yoksa sen öldün mü...?  Yok...', ARRAY['Türk Edebiyatı','Şiir','Levent Nalçacıoğlu']::text[], 8.5, '{"poet":"Levent Nalçacıoğlu","poet_slug":"levent-nalcacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mektup-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / YETENEK', 'bir-dortluk-de-sen-yaz-yetenek-siir-perisi-grubu-va106', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/YETENEK'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

1. 

Kendine güvenen, çıksın ortaya 

Döksün orta yere YETENEĞİNİ 

Kalbiyle övünen, dizsin mısraya 

Sersin orta yere YETENEĞİNİ.................Turan Orak 

2. 

Hazineler dolu insan beyninde 

Her kişinin vardır ayrı hüneri 

Saklanmış duruyor biraz derinde 

Çıkmalı meydana yetenekleri..............Mehmet Işıkoğlu 

3. 

her işten anlayan sözüm sanadır 

hünerim çok sanıp ukala olma 

ölüm kapımızda toprak anadır 

kalpleri kırıpta vakitsiz solma....................Turhan Toy 

4. 

Yeni baslamisim daha emeklemeye.. 

Yetenekli ariyorsunuz bende ne gezer, 

Arayisada iki satir yazamadim üzgünüm 

Ilham gelmeyince gönüle,kalem ne yazar..........Miyase Çavuşoğlu 

5. 

Ekilmez biçilmezi, doğurmaza yükledim 

Yatmazın, uyumazın, bacasına ekledim 

Yıldızlarla sevişip, ayla kucaklaşacak 

Bu mübarek sevdayı yıllar yılı bekledim..........Zülfikar Yapar Kaleli 

6. 

Sen benim sitemim, belalı başım 

Gönlümde kederim, gözümde yaşım 

Hem benim sevgilim, hem gönüldaşım 

Benliğimden çırılçıplak soy beni...................Zülfikar Yapar Kaleli 

7. 

Söz ki; nefse ağır gelir, yenilmez, 

Yetenek gönlünün sergisi şair! 

Söz ki; yığınına şiir denilmez, 

Yetenek Allah''ın vergisi şair! ......................Zülfikar Yapar Kaleli 

8. 

Siirim siir olsun okunsun isterim 

Yüreklere dokunsun aglatsin derim 

Anladim ki ilham yetmez yazmaya, 

Allah vergisi yetenek olmayinca.................Miyase Çavuşoğlu 

9. 

görüp duydugumuz her bir olaya 

hoşgörüyle yaklasmaktır yetenek 

imkansızı zora, zoru kolaya 

dönüştürüp övünmektir yetenek...................Rahim Taş 

10. 

Şiir yazma artık, diyorlar bana 

Duyup, yazma da dur, hadi kolaysa 

Yetenek yok ama, gam her yazımda 

Bakıp, yazma da dur, hadi kolaysa.............Erdoğan Ergin 

11. 

Düşlerim firardayken geceler çığlık dolu 

Sen mahkum kabuslarda, ben sensizlik yorgunu 

Üşümüş aşk yangını, sen gittiğinden beri 

Gidişini anlamaz, alevin çoçukluğu...................Ayşe İsmetoğlu 

12. 

Son kuşlarda uçtu,geçtiler göçe 

Bekleme vakti geçti,ufuklarda da 

İmkan tanı artık pak yüreklere 

Yetenekler çıkar ne yetenekler.......................Necmiye Sarpkaya 

13. 

Aşkıyla yanmışsan bir güzel güle 

Gönlünde ateştir közdür YETENEK 

Bülbül gibi yanıp tutuşsan bile 

Amayı gördüren gözdür YETENEK.......HIFZI ÖZBEKMEZ 

14. 

Gönülden gönüle varışlar gibi 

Yiğidin alnını karışlar gibi 

Yıkılmaz yerinde duruşlar gibi 

Yürekten verilen sözdür YETENEK.........HIFZI ÖZBEKMEZ 

15. 

Bazen ele verir türlü maharet 

Bazen dile verir olanca kuvvet 

İnsanda var olan her çeşit servet 

Kullanabilenler olur bahtiyar.........................Mehmet Işıkoğlu 

16. 

Hüzünler yaşadım bitmez gibiydi 

Hayali gözümden gitmez gibiydi 

Vuslata muradım yetmez gibiydi 

Kışın ayazında yazdır YETENEK.......HIFZI ÖZBEKMEZ 

17. 

Latifim gönlümün kör düğümünde 

Gönülle sevenin son düğününde 

Allah’ ın her günü üç öğününde 

Derdimi dinleyen sazdır YETENEK....... HIFZI ÖZBEKMEZ 

18. 

Yazım ol düş şiire, yetenek sende 

Sözüm ol düş dile, sezerek beyne 

Yazık etme bana, düşerek yere 

Söz bende, düş bende, şiir içinde...................Erdoğan ERGİN 

19. 

Allah vergisi insan da yetenek 

O insan''sa insana vurmaz değnek 

Çok güzel olurdu yenen çiğ börek 

ALlah vergisi insan da yetenek……………………………Serdar Sayıl 

20. 

Şair değilim ki şiir yazamam 

Ressam değilim ki resim yapamam 

Allah vermemiş ki satın alamam 

Var mı sandınız siz bende yetenek? ....................Sevil Nizamoğulları 

21 

Yeteneğim yok der şiirler yazar 

İlham Perisidir,kalplerde nazar 

Onun eseridir bu sanal pazar 

Sevil hiç yok mudur sende yetenek.........Ertuğrul Şakar 

22. 

bir kolum kırıldı öteki titrer 

kalem bana bakar boş kağıt ister 

her dem her kelime katre yaş bekler 

çöl gözlerde serap olur yetenek............................Levent Saral 

23. 

ağır bir bestede lal olur dilim 

kalemim buz tutar açmaz güllerim 

son şiir son satır yazmak gayretim 

sevgiliye mektup olur yetenek...............................Levent Saral 

24. 

Hayat bir oyundur, kader kurgusu 

Yetenek dediğin Allah vergisi 

Parayla pulla da yoktur ilgisi 

Karlarda boy veren çiçek gibidir...................Ayşe Korkmaz 

25. 

Nerededir kim bilir, kömürde saklı altın 

Tebessümdür ilhamı,gümüşten yazıların 

Hüner kalemde değil, kalemde atar yürek 

Şiir doğmamış çocuk, adı konmuş YETENEK…………Mevsimsiz Kardelen 

26. 

Nerededir kim bilir, kömürde saklı altın 

Tebessümdür ilhamı,gümüşten yazıların 

Hüner kalemde değil, kalemde atar yürek 

Şiir doğmamış çocuk, adı konmuş YETENEK………Miyase Çavuşoğlu

Şiir Perisi Grubumuzun her hafta düzenlediği ''Bir Dörtlük de Sen Yaz'' aktivitesi sonucu oluşan ortak bir eserdir.', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/YETENEK'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun Şİİ...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":132,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-yetenek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / VEFA', 'bir-dortluk-de-sen-yaz-vefa-siir-perisi-grubu-5h8bj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/VEFA'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

1. 

Kapına kul oldum, yaranamadım. 

sürdün durdun beni, vefasızsın sen. 

Yoluna çul oldum, hiç aldırmadım. 

Üzdün durdun beni, vefasızsın sen...........Turan Orak 

2. 

Takıldım gözüne, kurtulamadım. 

Bağlandım özüne, ayrılamadım. 

İnandım sözüne, uyanamadım. 

Üzdün durdun beni, vefasızsın sen...........Turan Orak 

3. 

Tek başıma kalsam vefalı dostum 

Hep senin adını haykıracağım 

Ömrümce hep seni vefalı dostum 

Ölsem de ismini haykıracağım.................Necmiye Sarpkaya 

4. 

Bugünler zillette, dünler sefasız 

Gönüller pazarcı, başlar kafasız 

Oğullar hayırsız, avrat vefasız 

Torunu görmeden pozlanmamalı..............Zülfikâr Yapar Kaleli 

5. 

Pervane misali kondum dalına; 

Aşk dedin, kul oldum aşkın yoluna; 

Kalbimi çıkarıp, verdim eline; 

İçten vurdun beni, vefasızsın sen...............Ayşe Korkmaz 

6. 

Vefasız hatırı kollamaz ise 

Ulaşmaz mektubu pullamaz ise 

Gidip de bir haber yollamaz ise 

Yaşları yanağa düzmek güzeldir …………….Zülfikar Yapar Kaleli 

7. 

Bekledim kış bitecek önü bahardır, yazdır 

Gördüm ki baharların pahası kıştan azdır 

Bir kez daha anladım, bu toprak vefasızdır 

Başım düşmüş eşiğe pahası olmaz kızım.................Zülfikar Yapar Kaleli 

8 

Gözsüzdü cihana bakmazdı gönül 

Engindi, yükseğe çıkmazdı gönül 

Su gibi her yana akmazdı gönül 

Bir vefasız yâra yaslanmamış mı? ..................Zülfikar Yapar Kaleli 

9 

Dost vefadan, düşman cefadan bıkmaz 

Sular boz bulanık bir yere akmaz 

İki sonbahardan bir bahar çıkmaz 

Nedir kara kışta bu cilve bu naz..............Zülfikar Yapar Kaleli 

10 

Gözündeki yara gördü yâr beni 

Sitemliydi, yara sürdü yar beni 

Bir vefasız yâra verdi yâr beni 

Sahrada Leyla’yı buldum diyemem...................Zülfikar Yapar Kaleli 

11 

Hiç vefa görmemiş dördün üçünde 

Eğil utanmadan ama niçin de 

Secdeye kapanmış huşu içinde 

Mevla''ya varınca göz yaşı döker...................Zülfikar Yapar Kaleli 

12 

Geçen günlerime bir göz gezdirdim 

Vallahi vurguncu düzeni dedim 

Ve düzen suyunda çoğunu gördüm 

Ahdine vefalı yar bulamadım......................Zülfikar Yapar Kaleli 

13 

Hiç vefa görmemiş dördün üçünde 

Eğil utanmadan ama niçin de 

Secdeye kapanmış huşu içinde 

Mevla''ya varınca göz yaşı döker....................Zülfikar Yapar Kaleli 

14 

Hiç vefa görmedim, laf mertlerinde, 

Hep ortak yaşadım tüm dertlerinde, 

Türk gibi düşünüp, Türk yurtlarında, 

İslam-i yaşayıp, kalmayı dene..................Zülfikar Yapar Kaleli 

15. 

Sevince aşık ki vefa bekliyor 

Günlerim geçtikçe cefa ekliyor 

Aklım hep sende bu kafa tekliyor 

Sevince aşık ki vefa bekliyor …………………….kartal62(serdar sayıl-2005)  

16. 

Sahte sevdalara boşuna yandım 

Dilinden dökülen sözüne kandım 

Dostluğu, sevgiyi bilirsin sandım 

Aldanmışım sana, vefasızsın sen..............Sevil Nizamoğulları 

17. 

Zuhâl kaydı, dolunayım bîvefâ. 

Cefâ gördüm, nazlıcandan bin cefâ. 

Gamzede bulmadım billahi sefâ, 

Harmanında yâr eyledi har beni. …………………………Ali Rıza Navruz 

18. 

Ömrümü verdimde bir gün bilmedin 

Gözümün yaşını döktün silmedin 

Çağırdım çağırdım yine gelmedin 

Benim ciğerimi yaktın vefasız....... Hıfzı Özbekmez 

19. 

Bir gün güldürmedin daim ağlattın 

Gözümün yaşını her gün çağlattın 

Gönlümü hep dertler ile dağlattın 

Gençken mezarımı kazdın vefasız......Hıfzı Özbekmez 

20. 

Geçmiş yılda bana hiç uğramadın 

Yeni yılda bari gel artık vefa 

Şiir Perisi''nde anıldı adın 

Beni güldür sende gül artık vefa.........Ertuğrul Şakar 

21 

eger ki görmezsek dostlardan vefa 

hayatımızı her an ederiz zehir 

dostun kapısını calmak bir defa 

ha bugun ha yarın ederiz tehir…………………….Rahim Taş 

22. 

ahdine vefalı dostlar kaldı mı 

bu kadar insanla ıssız bu şehir 

yoksa vefamızı yıllar çaldı mı 

şimdi durgun durgun akar bu nehir...............Turhan Toy 

23. 

Geçmiş yılda bana hiç uğramadın 

Yeni yılda bari gel artık vefa 

Şiir Perisi''nde anıldı adın 

Beni güldür sende gül artık vefa.........Ertuğrul Şakar 

24. 

Ey aşık bekleme, gidenden vefa 

Destanlar eskidi, yazılmaz şimdi 

Çektiğin dert fazla, yeter bu cefa 

Ölsen, aşk mezarın, kazılmaz şimdi......Erdoğan Ergin 

25. 

Pişirir insanı kendi çevresi 

Dostuyla oluşur yapı taşları 

Onlarla gelişir yaşam nüvesi 

Olmalı vefalı arkadaşları..........................Mehmet Işıkoğlu.. 

26. 

düşman edindiysen eğer, bekle sen cefa 

ama gerçek dostun varsa, bitmez hiç vefa 

dostu, düşmanını bilsen, sürersin sefa 

sende vefalı dostlarına, aç kalbini bir defa...........Şeyhmus Sevilmez

Şiir Perisi Grubumuzun her hafta düzenlediği ''Bir Dörtlük de Sen Yaz'' aktivitesi sonucu oluşan ortak bir eserdir.', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/VEFA'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR P...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":132,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-vefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin O Gidiş.', 'gittin-o-gidis-saim-bastik-py02b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne dedim de küstün böyle sebepsiz? 

Çatıp kaşlarını gittin o gidiş.

Giderken ardından baktım çaresiz

Çatıp kaşlarını gittin o gidiş.

Bir kusur mu ettim bilmem ki neden? 

Elveda demeden gittin aniden.

N''oldu diyecektim kalktım yerimden

Çatıp kaşlarını gittin o gidiş.

Çöktü viran oldu gönül sarayım

Kime gidip haberini sorayım.

Ben bu gidişini neye yorayım? 

Çatıp kaşlarını gittin o gidiş.

Neredeysen bir haber ver geleyim

Gittiğin yollara kurban olayım

Neden gittin sebebini bileyim

Çatıp kaşlarını gittin o gidiş.

Gidişini hayra yoruyormusun? 

HARÎMÎ''yi halâ soruyormusun? 

Nasıl sevdiğimi bilmiyormusun? 

Çatıp kaşlarını gittin o gidiş.

Saim BASTIK (HARÎMÎ) -19/07/2005', 'Ne dedim de küstün böyle sebepsiz?  Çatıp kaşlarını gittin o gidiş. Giderken ardından baktım çaresiz Çatıp kaşlarını gittin o gidiş. Bir kus...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gittin-o-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim...?', 'kim-dilek-egri-grh5a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ayrılık insanı 

aptallaştırıyor belliki...! 

hayatının merkezine koyduğun insan 

çekip gidince; 

coğrafyan şaşıyor

kıtaların ve aklın her biri bir yerde...

tesellilerde pek kar etmiyor.

herkes yaşamış

okkalı bir aşk acısı...

madem herkes acılı

terkeden kim

bunca insanı...? 

(16/05/05)', 'ayrılık insanı  aptallaştırıyor belliki...!  hayatının merkezine koyduğun insan  çekip gidince;  coğrafyan şaşıyor kıtaların ve aklın her bi...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Sana', 'bir-tek-sana-mustafa-ocaktan-tm7nj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman olacak bilmiyorum; 

Mevsim sonbahar gibi,

Gönlümde o buruk hatıran,

Bir tek sana geleceğim.

Sana güzel çiçekler getirmeden,

Gözlerimde yaş,elerimde kan

Yanıp kül olacak zaman

Senden af dileyeceğim...

Bir tek sana geleceğim.

Ben bileceğim ceylan gözlüm

Her şey yalan,her şey manasız.

Sana lal olmuş dil getireceğim,

Bir tek sana geleceğim.', 'Ne zaman olacak bilmiyorum;  Mevsim sonbahar gibi, Gönlümde o buruk hatıran, Bir tek sana geleceğim. Sana güzel çiçekler getirmeden, Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ocaktan']::text[], 8.5, '{"poet":"Mustafa Ocaktan","poet_slug":"mustafa-ocaktan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tek-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkındamısın?', 'farkindamisin-bekir-alim-aoy8o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorgu sual etmeden gelip ansızın girdin

Şu zavallı kalbimi çaldın fakında mısın? 

Öyle bir sevda ki bu yaktın, yıktın devirdin

Ne varsa yüreğimden aldın farkında mısın? 

Hercai olmasaydın ter temiz o sevgimde

Bil’ ki yine severdim ölümüne hemi de

Yanına al istersen bu cansız bedenide

Ferman yazıp kabrime daldın farkında mısın? 

Hiçbir şeyi dert etmem ağlatıp incintme sen

Yanıp kavrulsa bu ten küle dönse bu beden

Ey benim alın yazım vefasız sevgilim sen

Sevdanla bu kalbimde kaldın farkında mısın? 

Adını cümlelerde gözyaşımla yazarım

Sana sözüm yok amma şans talihe kızarım

İşte budur kaderim dertten gönül pazarım

Âlim’i dertten derde saldın farkında mısın? 

08.04.2005 CUMA', 'Sorgu sual etmeden gelip ansızın girdin Şu zavallı kalbimi çaldın fakında mısın?  Öyle bir sevda ki bu yaktın, yıktın devirdin Ne varsa yüre...', ARRAY['Türk Edebiyatı','Şiir','Bekir Alim']::text[], 8.5, '{"poet":"Bekir Alim","poet_slug":"bekir-alim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/farkindamisin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Eder Kim Görse Benim Halime', 'ah-eder-kim-gorse-benim-halime-ekrem-kemal-kirmaci-ek8zi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah eder kim görse benim halime.

Vefasız yar kalbi yaralar  durur.

Düşman ağlar, görse mahzun halime.

Çeresiz bu gönlüm sızılar durur.

Deva arar eller gönül yareme.

Yar diye sevdiğim hançeri vurur.

Düşman ağlar görse mahzun halime.

Çaresiz bu gönlüm sızılar durur.', 'Ah eder kim görse benim halime. Vefasız yar kalbi yaralar  durur. Düşman ağlar, görse mahzun halime. Çeresiz bu gönlüm sızılar durur. Deva a...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kemal Kırmacı']::text[], 8.5, '{"poet":"Ekrem Kemal Kırmacı","poet_slug":"ekrem-kemal-kirmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ah-eder-kim-gorse-benim-halime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Taş Yok mu?', 'bir-tas-yok-mu-ekrem-kemal-kirmaci-grflq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir taş yok mu başımı koymak için.

Bu yaralı kalbime vurmak için.

Hani nerde, kiminle vefasız yar? 

Gül derdiğim göğsün de şimdi kim var? 

Bir taş yok mu başına çalmak için! 

Hala seven kalbime vurmak için.

Hani  nerde, kiminle vefasız yar.

Gül derdiğim göğsünde şimdi kim var.', 'Bir taş yok mu başımı koymak için. Bu yaralı kalbime vurmak için. Hani nerde, kiminle vefasız yar?  Gül derdiğim göğsün de şimdi kim var?  B...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kemal Kırmacı']::text[], 8.5, '{"poet":"Ekrem Kemal Kırmacı","poet_slug":"ekrem-kemal-kirmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-tas-yok-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-saim-bastik-amkpw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gönlümü falakaya yatırdım

Ne yapsan nafile işin iş dedi.

Uslanması için acı çektirdim

Beni bırak,sen önüme düş dedi.

Ne sevdalar gördün hep acı çektin

Ne yaralar aldın kendinden geçtin

Günlerce sızlayıp gözyaşı döktün

Bunu sen istedin, sende suç dedi.

Her sevdiğin seni ağlatmadı mı? 

Sana hep karalar bağlatmadı mı? 

Herbiri bir yerden kanatmadı mı? 

Bunlar ufak işler,  haydi geç dedi.

Gönül,ben usandım pes artık dedim

Benimle inadı kes artık dedim

Bak seni duyan yok sus artık dedim

HARÎMÎ yakamdan,  artık düş dedi.

11/07/2005', 'Dün gönlümü falakaya yatırdım Ne yapsan nafile işin iş dedi. Uslanması için acı çektirdim Beni bırak,sen önüme düş dedi. Ne sevdalar gördün ...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Beni Bırakmıyor', 'aklim-beni-birakmiyor-dilek-kalindemir-fzds4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Ne kadar içsem de,

ne kadar istesem de,

sarhoş olamıyorum; 

aklım beni bırakmıyor! '' diyordu

filmdeki kadın...

Aklım beni bırakmıyor! 

Resimdeki gözyaşları gibi...

Görünmeyen el gibi...

İçimde bir sızı gibi..

Aklım beni bırakmıyor...

Bıraksaydı

bu kadar masum kalmazdım...

Aklım beni bırakmıyor...

Aşka doymayışım,

aşkı arayışım bu yüzden midir? 

Kim bilir? 

Yitirdiğim ya da hiç bulamadığım herşey için,

gidemediğim tüm şehirler,

çıkamadığım bütün yollar için yine ağlarken bile..

aklım beni bırakmıyor! 

Bak, oturmuş sana şiir yazıyorum...

(Ekim 2003)', '''Ne kadar içsem de, ne kadar istesem de, sarhoş olamıyorum;  aklım beni bırakmıyor! '' diyordu filmdeki kadın... Aklım beni bırakmıyor!  Resi...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kalındemir']::text[], 8.5, '{"poet":"Dilek Kalındemir","poet_slug":"dilek-kalindemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aklim-beni-birakmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykırı Yaşamak', 'aykiri-yasamak-omer-arslan-5xfp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aykırı yaşamak istiyorum hayatı

Hayatın çerçevesi kırık

Gözlüklerinden yırtık bakarak

Ürkerek dokunmak istemiyorum ellerine

Ve ürpermeni de,her dokunuşumda,tenine

Sümen altı ettiğim ve hiç açmadığım

Bakir düşünceleri haykırmak; güpegündüz

Hem de sokak ortasında

Çekinmeden hiç kimseden ve de korkmadan

Aykırı yaşamak istiyorum hayatı

Toprak suya gebe

Çiçekler bahara sevdalı

Bense sana

Ürpermeden tut ellerimi tutsana

Körebe oymadan yüreğimle

Yörük çadırları gibi göçmeyen bir sevdayı

Aykırı yaşamak istiyorum

Hiçbir intihar eylemci saldırmadan yüreğime

Hiçbir hırsız gönül cebimde ki imgeleri çalmadan

Bıkmadan usanmadan ve hiçbir şeye aldırmadan

Hiçbir günaha girmeden  şu masum bedenim

Aykırı yaşamak istiyorum', 'Aykırı yaşamak istiyorum hayatı Hayatın çerçevesi kırık Gözlüklerinden yırtık bakarak Ürkerek dokunmak istemiyorum ellerine Ve ürpermeni de,...', ARRAY['Türk Edebiyatı','Şiir','Ömer Arslan']::text[], 8.5, '{"poet":"Ömer Arslan","poet_slug":"omer-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aykiri-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatağını Bulurmuş Coşan Nehirler', 'yatagini-bulurmus-cosan-nehirler-esin-ege-pt6tl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar mahzun ve çekingendik ilk günlerde. Ve bir o kadarda mahcup. Ergin yaşlarımızda biz acemi çocuklar gibi saf ve kırılgandık bire o kadar da deli. 

Adım atarken birbirimize dünyanın bütün aşkları arasına serilmiş o vahşi tutkulu arzulardan uzaktık. 

Ayrı diyarlarda sürdürdüğümüz yaşantılarımıza rağmen bedenlerimiz en acı esaretini yaşarken ve zalimce dikenli tellere takılmış yaralı bir kuş gibi çırpınırken,  ruhlarımız fırtınalara kapılmış birbirlerine doğru, vahşi kısraklar gibi koşuyorlardı.

Sen bana ben sana….Birbirimize  Ruhum sana, fikrim sana,  yüreğim sana ….sen yalnızca bana koşuyordun hissediyordum, biliyordum.

Fırtınalar kopuyordu yüreklerimizde, yeni fidanlar sürgün veriyordu  köhne viran düşlerimizde. 

Öylesine bir gerçek vardı ki, bütün acı gerçeklere rağmen ısrarla,inatla,bağıra bağıra geliyordu, ve korkusuzca aşka gelmiş karanlık gecelerin en kuytu köşelerinde çırılçıplak dans ediyordu.

Ürkektik, çekingendik, neler oluyor anlayamıyorduk  bile. Ama olanlar her neyse tatmadığımız bilmediğimiz aşk tadında sevda tadında bir şeylerdi.Biz aşkı tanıyorduk, aşkı öğreniyorduk kısacık zamanlarda yüreklerimizde.Biz birbirimize sevdalanıyorduk biz birbirimize akıyorduk, koşuyorduk.

Sanki kırk yıllık gebeliğinin ardından bir ananın  bacaklarının arasından bağıra çağıra doğurduğu bebek seslerin gerçeği gibi bir şeyler doğuyordu. Evet bir şeyler doğuyordu dünyamıza geç kalmışlıkların acısı çıkacaktı doğuyordu bir şeyler aramızda.

Ne  sen dur diyebildin ne ben bu geç kalmış doğumlara. Varsın olsun dedik ne çıkar ne zaman biteceği belli olmayan bu hayat yolunda gerçekleri  yok saymak.Tüm nimetleriyle  bize sunulan bu hayatta hiç yaşamadan gitmek korkusu sardı içimizi. Bir kez daha sunmazdı asla  yaradan böylesi bir sevdayı  yüreklerimize, tanımazdı kader bir ikinci kez bu şansı bizlere.

Sevda çıkmazında yaşlanmamalıydı ruhumuz. Sevdiğimiz için meydan okuyup baş kaldırdığımız için acı çekmeliydik, bir köşede sinip kabullenerek değil kaderi.

Yüreğimizdeki nehirler coştu deli bir derya oldu yatağını parçaladı. Aktılar bir birlerine bir kuytu köşede buldular gerçeklerini, özlerini.

Bereketli bir toprakta nasıl filizlenirde coşarsa bir sarmaşık. Ve nasıl kendiyle sarmaş dolaş olursa dalları,  işte bir sarmaşık misali dolandı ruhlarımız, kalplerimiz. Bize sormadı yüreklerimiz gitmek için, ne laf dinlediler nede söz bütün yalın ve acı gerçeklere rağmen, öyle ki  bedenlerimizi arkada bırakıp tek bir can olup yürüdüler el ele..

Ten geride ruh ötede şimdi. 

Bu özlem ne zaman biter diye ağladım, göz yaşlarımla ıslandı omuzların, güldün gözlerime bal rengi gözlerinle bakarak, işte yanındayım dedin. Oysa ben en büyük hasretlerimi senin yanında yaşadım. Sen yanımdayken bile kokuna, gülüşüne,bakışan hasret kaldım. 

Anladım ki özlemlerimin dinmesi için senin gelmen yetmiyor çünkü başım göğsündeyken bile yanı başında da hasretim sana.

Gelmeni beklemiyorum çünkü gelmelerin gitmeleri getiriyor ve ben sensizliğin en derin kuyularında katran karası acılar çekiyorum. Ölmek ne ki ölüm bir kurtuluş ve dinmesidir acılarımın. Bu ölümden beter derin bir sensizlik çukuru ve düştükçe dibini göremiyorum.

Ne yaşamak kurtarır bu sevdayı nede gün ışığında  kaçıp götürmek uzaklara. Bizim yüreklerimizde sürecek saltanatı kimseler bilmeyecek  ve biz bir asır yaşamış gibi  bahtiyar öleceğiz bir gün. Hiçbir yeis olmayacak içimizde ayrı geçen günlerimiz için. Sevmek için yüreklerimiz sevişmek için hayallerimiz var bizim. 

Derler ki yatağını bulurmuş coşan nehirler bir gün ….bizim yatağımız yüreklerimiz oldu  bir tanem….', 'Ne kadar mahzun ve çekingendik ilk günlerde. Ve bir o kadarda mahcup. Ergin yaşlarımızda biz acemi çocuklar gibi saf ve kırılgandık bire o k...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yatagini-bulurmus-cosan-nehirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerken', 'beklerken-dilek-kalindemir-stdtm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Merhaba'' diyebilmek için çıkılan yollardan,

kucakları dolu dönmek için ümitle bekler yürekler...

O “merhaba”nın son merhaba olmasını isterler

tekrar ayrılmamak için.

Ben hep,

dinlediğim şarkıların sözlerine takılıp kalıyorum.

Ve hiç yazılmamış kelimeler,

hiç kurulmamış cümleler arıyorum

“biz”i anlatmak için.

“Öylesine” yaşamamak için sevgiyi,

özlemenin adını değiştirmek,

hep yanımdaymışsın,

hep aynı şehirdeymişiz gibi

konuşmak istiyorum telefonda...

Uzakta olduğunu unutmak,

kavga etmek istiyorum seninle

sudan bir sebeplerden...

Başbaşa televizyon seyrettiğimizi

düşlemek istiyorum.

Adımı duymak istiyorum sesinden...

Ve zor olanı,

kendimce kolaylaştırmaya çalışıyorum,

beklerken...

(Temmuz 2003)', '''Merhaba'' diyebilmek için çıkılan yollardan, kucakları dolu dönmek için ümitle bekler yürekler... O “merhaba”nın son merhaba olmasını isterl...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kalındemir']::text[], 8.5, '{"poet":"Dilek Kalındemir","poet_slug":"dilek-kalindemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beklerken-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fransız Küfürler', 'fransiz-kufurler-ozan-turk-wsjex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bilmediğin bir yere

Hem de bir şehire

Hatta o şehrin gene hiç bilmediğin ülkesine

Gönderdin mi hiç

Kendim dediğin 

Benim dediğin

Beş yaşlarındasın henüz

Düşmüşsün bir ağaca tırmanırken

Yaranmış

Kabuk tutmuş? 

Ne anlar 

Kaşıntısını bir yaranın

O kadar güzelliğini

İçini kurcalarken

Dilini bile bilmezken 

Bambaşka bir ülke

Sen daha onun dişinin kovuğuna gelmezken

Ve ezbere bildiğin sokaklardan 

Küfrederek geçerken

Ve bu kadar mahallen 

Şehrinken sen

Hiç Fransızca edebilir misin 

Küfürleri

Ya da hiç üfleyebilir misin avucunda

Fransız sevinçleri...', 'Hiç bilmediğin bir yere Hem de bir şehire Hatta o şehrin gene hiç bilmediğin ülkesine Gönderdin mi hiç Kendim dediğin  Benim dediğin Beş yaş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fransiz-kufurler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben - "siz hiç ay aşığında ağladınız mı" Kitabından', 'ben-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-vdzoq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '"Nefsini bilen Rabbini bilir."

İnsan, kendi özünü keşfettiğinde koca bir coğrafyanın hüzünlü ve mağrur hafızasına dönüşür. "Nefsini bilen Rabbini bilir" hikmetiyle başlayan yolculuklar, sadece bireysel bir uyanışın değil; asırlardır acıyla yoğrulmuş, şehadetle harmanlanmış ve mazlumun çığlığıyla dertlenmiş bir milletin kimlik arayışıdır. 

Toprağın sabrını, Yunus’un nefesini, Mevlana’nın merhametini ve Anadolu’nun buruk güzelliğini bağrında taşıyan bu beden ve ruh , sınırları haritaları aşan kadim bir vicdanın aynasıdır.

​Gazze’den Türkistan’a, Kafkaslar’dan Çanakkale’ye  uzanan coğrafyada dökülen her gözyaşı onun sinelerinde sızlar, yakılan her ağıt onun kimliği olur. 

Çünkü bu "Ben", kibirden sıyrılıp "hiç"liği kuşanmış; kendini yok saydıkça bir millete, bir vatana ve insanlığın sığınacağı son limana dönüşmüş bir ruhtur.

​Kendi yokluğunda vatanın varlığını bulan derin, gururlu ve mahzun haykırışların adıdır "ben".

Ben 

Ben toprağım mevcudatı taşırım

Güller açar bülbül öter tenimle

Ben dört mevsim yaşatırsam yaşarım

Ölmek varsa feda olsun canımla

Ben azığım ben ekmeğim ben aşım

Ben tevazu ben insanım ben eşim

Ben anayım ben babayım kardeşim

Ben arıyım esrar vardır fenimle

Ben ırmağım aşkla çağlar dereler

Ben çiçeğim şifa bulur yaralar

Ben tevazu benden çirkin huriler

Ben Hicazım Kafkasya''yla Van''ımla

Ben komşuda yara varsa hastayım

Ben güzele ballı dilli besteyim

Ben hicranlı Türkistan''da yastayım

Ben yaşadım hoşgörüyle dinimle

Ben şehidim Çanakkale şahittir

Ben faniyim her şey Ona aittir

Ben bir hiçim hiç olanlar yiğittir

Ben insanım oynamayın genimle

Ben ay yıldız sevdalıyım allara

Ben ölürüm yan baktırmam ellere

Ben Şeyh Şamil kulluk etmem kullara

Ben renk verdim gönderime kanımla

Ben bin yıllık mehteranım ülküye

Ben  aşk ile duâ olur türküye

“Ben” ben değil benim adım Türkiye

Ben koşarım zapt edilmez şanımla

Ben Yunus''u Mevlana''yı dinlerim

Ben Çeçenim Çeçenya’da inlerim

Ben her gece Filistin’de kinlerim

Ben bir devim elleşmeyin benimle

_________________Benim adım Türkiye', '"Nefsini bilen Rabbini bilir." İnsan, kendi özünü keşfettiğinde koca bir coğrafyanın hüzünlü ve mağrur hafızasına dönüşür. "Nefsini bilen Ra...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ben-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antikacıda Demli Bir Çay', 'antikacida-demli-bir-cay-i-sa-erkol-g3pvg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir seni unutmazdı yüreğim

Birde Mustafa Ağabeyin demli bir çayını

Seni anımsar buraya gelirdim

Bir seni severdim, birde demli bir çayı

Antikalarla doluydu her tarafı

Ve yok yok dercesine bir kütüphanesi

İçeriye girince çay kokusu kaplardı

Burası seni düşündüğüm çay meyhanesi

Antikacıda demli bir çay elimde kalemim

Harf harf doldurur seni sayfalar

Kulağımda sesin, karşımda hayalin

Bir sen varsın bana birde demli yudumlar

Ortada bir soba, ağır ağır yanıyor

Ocakta çayın kaynama sesleri

Şu akan şelale ruhumu dinlendiriyor

Bir seni seviyorum, birde burdaki hisleri

Sol tarafta radyolar, bilmem ki kaç yıllık

Camlar buğulanmış, adını yazıyorum

Duvarda halı motifleri bir kaç asırlık

Bir çayımı içiyor bir seni anımsıyorum

Duvarda manzara, orman içinde bir kulübe

Önünde bir dere kıvrılıpta gidiyor

Sevdamız gibi ağaçlar sonbahara gebe

Ben çayımı içiyorum, aklım seni anıyor

Dedim ya! Bir seni düşlüyorum birde çayı

Bir seni seviyorum bir de bu antikacıyı

Doldur be Mustafa Ağabey demli bir bardak çay

İçeyim,unuturum belki bu yalan sevdayı.', 'Bir seni unutmazdı yüreğim Birde Mustafa Ağabeyin demli bir çayını Seni anımsar buraya gelirdim Bir seni severdim, birde demli bir çayı Anti...', ARRAY['Türk Edebiyatı','Şiir','İsa Erkol']::text[], 8.5, '{"poet":"İsa Erkol","poet_slug":"i-sa-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/antikacida-demli-bir-cay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah', 'ah-huseyin-sibic-fy3lr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle kurduğum ümidim vardı,

Unuttum bil inan Allah aşkına...

Artık senin yokluğun bana kârdı,

O doymaz hevesin dönsün şaşkına...

Artık yalan sözlerin için ağla,

Bitmez olsun,dertlerin için ağla,

Yerlere kapan için için ağla,

Göz yaşın sel olsun dönsün taşkına...

Gamlansın gönlün rahat bulduğunda,

Kan ağlasın için zevk duyduğunda,

Bin şüphe duy, her mutlu olduğunda,

Gönlündeki sevinç, dönsün kuşkuna...

(18.07.2005)', 'Seninle kurduğum ümidim vardı, Unuttum bil inan Allah aşkına... Artık senin yokluğun bana kârdı, O doymaz hevesin dönsün şaşkına... Artık ya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ah-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle konuşunca', 'senle-konusunca-yilmaz-ozturk-lxvvb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senle konuşunca tuhaf bir haller oluyor bana

Sesini duyunca ruhum sığmıyor vücuduma

Sanki beni benden alıp daldırıyor rüyalara

Rüyamda seni görüyorum beni bende sanma

Sesini duyunca titriyor ellerim sanki parkinson

Nasıl bir duygudur Allah`ım sana şükürler olsun

İnsan bukadar severmi sende yok oluyorum

Bilmiyorum neden konuşunca senle her sesi unutuyorum

Kulaklarım duymuyor sanki olmuş sağır

İlacı senin sesin senle konuşmak şifa oluyor

Hele birde gözlerine bakınca  elektrik çarpıyor

Sesinden can bulduk bu can sende yaşıyor', 'Senle konuşunca tuhaf bir haller oluyor bana Sesini duyunca ruhum sığmıyor vücuduma Sanki beni benden alıp daldırıyor rüyalara Rüyamda seni ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senle-konusunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyı...', 'aciyi-serhat-kulu-biwo1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acıyı bal eyledim,

Sen yağlı ilmeğe giderken

son dileğim.

Gün ola devran döne,

Yollarına düşeceğim...', 'Acıyı bal eyledim, Sen yağlı ilmeğe giderken son dileğim. Gün ola devran döne, Yollarına düşeceğim......', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aciyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sandım', 'sen-sandim-serhat-kulu-d6obr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensizliğimi yorgan yaptım kendime,

Sardım üşüyen bedenime

Uyandım gecenin bir vakti,

kan ter içinde...

Yine sen geldin sandım...

yine...', 'Sensizliğimi yorgan yaptım kendime, Sardım üşüyen bedenime Uyandım gecenin bir vakti, kan ter içinde... Yine sen geldin sandım... yine......', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-sandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Söz Söyle', 'bir-soz-soyle-huseyin-sibic-cf1fp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutlulukla dolup taşardım,

Sadece bil demen yeterken.

Emrine âmade koşardım,

Sadece gel demen yeterken.

Başkasını nasıl severim? 

İstersen ecele gülerim,

Ömrümü uğruna sererim,

Sadece öl demen yeterken.

Seninle kalmıyor kederim,

Gönlümü aşkınla güderim,

Bırakıpta nasıl giderim? 

Sadece kal demen yeterken.

Mutluluk ürüyor özümde,

Gam,tasa kalmıyor yüzümde,

Nem mi,yaş mı kalır gözümde? 

Sadece sil demen yeterken.

Nice dertle çağlar mıyım ben? 

Ele ümit bağlar mıyım ben? 

Ömrü billah ağlar mıyım ben? 

Sadece gül demen yeterken.

(18.06.2005)', 'Mutlulukla dolup taşardım, Sadece bil demen yeterken. Emrine âmade koşardım, Sadece gel demen yeterken. Başkasını nasıl severim?  İstersen e...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-soz-soyle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E-mail', 'e-mail-sair-yatakkusu-r1e76', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevmek öyle kötü birşey ki

köle olmak, ricasına kalmak

hürriyetini bağlamak

belirsizliğe

hatta herşeyden vazgecip

ondan en ufak bir şeyi

beklemeden

yaşamaya

kalkmak

aşık olmak aptalca birşey

biter bile bile yalvarlayıp

zorlamak hatta

altan alıp

olmamak

de ağlamak

hep', 'sevmek öyle kötü birşey ki köle olmak, ricasına kalmak hürriyetini bağlamak belirsizliğe hatta herşeyden vazgecip ondan en ufak bir şeyi bek...', ARRAY['Türk Edebiyatı','Şiir','Şair Yatakkuşu']::text[], 8.5, '{"poet":"Şair Yatakkuşu","poet_slug":"sair-yatakkusu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/e-mail-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemek...', 'i-stemek-zafer-zengin-etnika-w1clk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.



yukarıdan aşağı/aşağıdan yukarı /yan yana

İstemek / 

kanın kaynama noktası

sana değil

bana sarılsın sızı

bana sarılsın sızı

sana değil

kanın kaynama noktası



Koşmak

incitip geçmişi

karışır aklın köşesi

terki diyar etmeli

dönüş yok

düş üşümemeli

düş üşümemeli

dönüş yok

terki diyar etmeli

karışır aklın köşesi

incitip geçmişi



İstemek

aranmanın yanı sıra sesin gelsin

kaldırıp perdeleri gülümsesin

sesin bilsin küsmesin

istiyorsan alıp gideceksin

istiyorsan alıp gideceksin

sesin bilsin küsmesin

kaldırıp perdeleri gülümsesin

aranmanın yanı sıra sesin gelsin



Isınmak

gözler yeter  adamı yakmaya

öyle bakıp durma ağustos ortasında

her an tutuşurum yalnızlığımla

elini sokup yol açma yangına

yanmaların sonu yok yan yana

yanmaların sonu yok yan yana

elini sokup yol açma yangına

her an tutuşurum yalnızlığımla

öyle bakıp durma ağustos ortasında

gözler yeter  adamı yakmaya





davet

gözlerimi öp en çok

dalmasın bakarken

dalmasın bakarken

gözlerimi öp en çok

kendine at beni karıştır

karıştır beni at kendine

bir iç''im su...

14 07 2005

.', '. yukarıdan aşağı/aşağıdan yukarı /yan yana İstemek /  kanın kaynama noktası sana değil bana sarılsın sızı bana sarılsın sızı sana değil kan...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/istemek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaos', 'kaos-murat-tali-wcqsh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşam, salakların birleşik gücüyle yönetilen bir kaostur.', 'Yaşam, salakların birleşik gücüyle yönetilen bir kaostur....', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kaos-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Gülücüğümü çaldın!', 'sen-benim-gulucugumu-caldin-ayse-i-smetoglu-ptudp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim gülücüğümü çaldın! 

Sadece geriliyor dudaklarım,

Mecburi istikamette! 

Ağlayışlar ceplerime doluşurken 

Kuyulara saklandı kahkaham...

Arta kalan senden 

Hevessiz bir yaşam düştü payıma 

Çabuk kabullendim acının dostluğunu

Bitiriyorum, bitmeden 

Sana dair ne varsa ....

Hıçkırımın uğultusu, 

Yankılanırken geceler boyunca,

Mevsimsiz gülüşlerim 

İntikam kursağına gömülü..

Son bir tebessüm, son bir umut ışığı

Benliğimi sarsa da 

Anladım ki sevgim de ölümlü... 

Artık! 

Yaralı serçe gibi gözlerim; billur billur 

Gözyaşlarım isyanda; çığlık çığlık 

Sararmış tenimde bir matem; sessiz sedasız 

Benim gönlümde,delice kalabalık, 

Sende,hüzünler bile kaygısız... 

Sen benim gülücüğümü çaldın! 

Hüküm giydi aklım, kederleri 

Nefesim esarette o günden beri 

Anlaşılmadı duygular nedense,

Ve sonunda koparken  aramızdaki bağlar

Derinlerden geliyordu sesi 

Meğer,

Çocuksu hayallerim ağlar....', 'Sen benim gülücüğümü çaldın!  Sadece geriliyor dudaklarım, Mecburi istikamette!  Ağlayışlar ceplerime doluşurken  Kuyulara saklandı kahkaham...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-benim-gulucugumu-caldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharat / öğret bana...', 'baharat-ogret-bana-zafer-zengin-etnika-03nym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

tutunmak derken

hayat değildi

bahsi gecen pencere

balkon demiri

köprü ayakları

halatlar 

sendin

| oysa ölümü bile yendim

karabiber hapşurmasın da

çok yaşa diyen olmasa da |

sürükle şimdi ağlarında

bana bıraktığın yalnızlıkları

sar kollarına

ve ağla

kim daha yabancı şimdi

geride bıraktığı anılara



ve küstün şimdi

seni sevmeyen zamana

kaç kişiyi yakacaksın

affetmeyen bakışınla



ey hayat

şimdi ölüler sürme toprağa

yılgınlıklar var daha

görmezler

zencefil bilmez tadını

tarçın konuşur

çıkmamış canda umuda

küçük taylar sarılır hayata

şarabi renklerle gelen

sonbaharda



şimdi çık sokağa

meydan oku asfalta

bank da oturanlara

denize 

martılara

batacaksa bu şehir

sensiz batmalı

yoksa yedi tepesini

yerinden söküp atmalı

eylül geliyor hüzün

sen hüzünlü gülüm

kanım yüreğine sürülsün



kim yenebilir

hangi ordular

sevmeye başlamış

körpecik yüreği aşkla

öğret bana...

M.Ö 777 Eylülün üçü 

İpek yolu kimlere çalıştı

.', '. tutunmak derken hayat değildi bahsi gecen pencere balkon demiri köprü ayakları halatlar  sendin | oysa ölümü bile yendim karabiber hapşurm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/baharat-ogret-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehterle-Marşla.', 'mehterle-marsla-veysel-alkan-xmf5r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ABD ve AB oynuyor oyun.

Diyorlar Irak''a girmeyin durun.

Gittikçe artarsa bölgede sorun,

Mehterle coşarız,Marşla coşarız...

Hedefte Bağdat olur,kalplerde iman.

Durduramaz hiç bir güç,Türk coştuğu an.

Çağlarız sel gibi Anadolu''dan,

Mehterle akarız,Marşla akarız...

Bozup durma kafamızı hey amerika! 

Aklını başına al kalleş pkk''a! 

Bu zulüm sürerse; Kuzey Irak''a,

Mehterle gireriz,Marşla gireriz...

Gördük insanlığınız, sizi terk etmiş.

Gelip size öğretiriz; adalet neymiş? 

Kim mazlumun yanında kimler zalimmiş? 

Mehterle söyleriz,Marşla söyleriz...

Zincir mi vurursunuz Müslüman Türk''e? 

Ne zaman esirmişiz, ne zaman köle? 

Bir CUMA sabahı TÜRKMEN KERKÜK''e,

Mehterle geliriz,Marşla geliriz...

Bizimle ulaşır bölgeye huzur,

Sizin gibi canilerin devri son bulur,

Bütün halklar arkadaş, hep can dost olur,

Mehterle Sevdirip,Marşla severiz...



Sürekli İşimize karışan, bize İnsan Haklarından bahseden,ama insan halinden anlamayan ve de Türk''ü tanımayanlara cevaptır.', 'ABD ve AB oynuyor oyun. Diyorlar Irak''a girmeyin durun. Gittikçe artarsa bölgede sorun, Mehterle coşarız,Marşla coşarız... Hedefte Bağdat ol...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mehterle-marsla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu yıldızdı götürdü', 'bu-yildizdi-goturdu-ozan-turk-c3eed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceden şehre giren telaşlı bir yıldız

Yanıp sönüyor durmadan

Bir şeyler var söyleyeceği sanki

Sanki bir haber

Milenyum turnası bir yıldız sanki…

Bir yıldız 

Geceden başladı yanmalarına

Ve dev Hüseyin’in vedası

Oturdu karanlığa

Önce bir söz vardı bağırındığı

Sonra bir dolu kahkaha istediği

Bir yıldız

Geceden başladı yanmalarına

Can Hüseyin’in

Gözlerine girip çıktı

Bir defa daha denemelerin

İnançlı yeminleri

Ah bu yıldızdır

Bir kez daha

Evet aynı bu yıldızdı

Bir kez daha 

Götürmüştü 

Bir şehirden 

İlk bin adımından sonra

Bir azizeyi…', 'Geceden şehre giren telaşlı bir yıldız Yanıp sönüyor durmadan Bir şeyler var söyleyeceği sanki Sanki bir haber Milenyum turnası bir yıldız s...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-yildizdi-goturdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Atatürk', 'olumsuz-ataturk-sair-yatakkusu-c2fo7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boğaz''ı,

güldüğümüz parkları,

ağladığım parkları,

tepelerde ki gecekonduları,

Cevizlibağ''a, sana,

E5''te aşırı hızla giden taksileri,

kızları kovalayan

orospu çocuğu kalbime göre

fazla ağır olan

bazen ufacık hatıraları,

istemiyorum artık.

Zehra, Aşkım

Sonsuz Aşkım

ölsem de,

üzüntüye boğulsam da

dolunay geceleri

batsa da Dolmabahçe''nin

tüm kayıkları

senin için

ebediyen

Tünel''den Taksim''e kadar

her köşesini öpüşmelerimizi kıskandığı

Beyoğlu''nun en ufak sokağın

hayaleti olarak

İstanbul''a döneceğim.

Ölümsüz Atatürk''ün olacağım.

atlı heykellerim

büstlerim

heryerde.

kan rengi sancakların yansıttığı,

sönen bir ay ile

Yenilmez Umut olan

tek bir yıldız

sana Aşkımızı hatırlatır

sancakların gölgesinde

kusana kadar

orijinalı fransızca; 

Je ne voulais plus du Bosphore 

des parcs où nous riions, 

des parcs où je pleurais, 

des taudis sur les collines, 

des taxis jaunes à fond sur le E5 

qui volaient vers toi vers Cevizlibağ, 

de ces souvenirs si infimes parfois, 

trop forts pour mon petit coeur de salope, 

de coureur de jupons. 

Zehra mon Amour, 

mon Amour Infini, 

même si je meurs, 

si j''ai les boules, 

même si des nuits de pleine lune 

sombrent les caïques de Dolmabahçe 

pour toi, 

à jamais je hanterai, 

de Péra la moindre ruelle, 

où de Tünel à Taksim 

chaque coin jalousa nos baisers, 

je reviendrai à İstanbul, 

je serai ton Immortel Atatürk 

avec mes statues équestres 

mes bustes 

tout partout 

ombrés de drapeaux couleur sang 

où se reflètent de la lune un croissant finissant 

et une unique étoile pour que 

l''Espoir Invincible 

te rappelle 

notre Amour 

jusqu''à en gerber.', 'Boğaz''ı, güldüğümüz parkları, ağladığım parkları, tepelerde ki gecekonduları, Cevizlibağ''a, sana, E5''te aşırı hızla giden taksileri, kızları...', ARRAY['Türk Edebiyatı','Şiir','Şair Yatakkuşu']::text[], 8.5, '{"poet":"Şair Yatakkuşu","poet_slug":"sair-yatakkusu","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/olumsuz-ataturk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Peygamberi', 'ask-i-peygamberi-abdullah-odabas-yna5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben aşığım güzele,

Ol taüsi ezele,

Dost bahçesin gezele,

Gel gör anda neler var.

Gönlüm geçmez güzelden,

Ol taüsi ezelden,

Aşık söyler gazelden,

Gel gör anda neler var.

Gönlüm gözüm güzelde,

Ol taüsi ezelde,

Evim barkım mezarda,

Gel gör anda neler var.

Gönlüm gözüm bir yana,

Ol taüsi seyrana,

Yarın mahşer divana,

Gel gör anda neler var.

Gönlüm gözüm özrüler,

Ol taüsi arzular,

Kurban ana kuzular,

Gel gör anda neler var.

Ol taüsi ba sefa,

Ruh-i  paki Mustafa,

Ederdi haktan haya,

Gel gör anda neler var.

Her bir damla terinde,

Nice hikmet var anda,

Oku mektep irfanda.

Gel gör anda neler var.

Meftuni kurban sana,

Şefaat eyle bana,

Günahlarım affola,

Gel gör anda neler var.', 'Ben aşığım güzele, Ol taüsi ezele, Dost bahçesin gezele, Gel gör anda neler var. Gönlüm geçmez güzelden, Ol taüsi ezelden, Aşık söyler gazel...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ask-i-peygamberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki dünya', 'i-ki-dunya-fevzi-kunucen-918az', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hanlar hamamlar

Çinili köşkler kervan saraylar

Ojeli tırnaklar,rujlu dudaklar

Hepsi hepsi sizin

Vay haline garipler köyü

Oy oy size 

Geceleri el yordamıyla 

Sevişen ahali

FEVZİ KÜNÜÇEN', 'Hanlar hamamlar Çinili köşkler kervan saraylar Ojeli tırnaklar,rujlu dudaklar Hepsi hepsi sizin Vay haline garipler köyü Oy oy size  Geceler...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkindi Namazının İzdüşümü', 'i-kindi-namazinin-i-zdusumu-nuri-yilmaz-qcgdz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsim sonbahar, vakit ikndi...

Tatlı bir hüzün sardı her tarafı şimdi.

O Kutlu Nur Dünya vaktinin ikindisinde  indi.

Dalga dalga zaman denizinin kıyısına yayıldı.

*****          *****          *****

Dünya hilkatından bu yana inkilaplar geçiriyor.

Her inkilabta ruhuma bir izdüşüm bırakıyor

Sema denizinde yolcu gemimiz hızlı ilerliyor.

Ramak kaldı tayın olunmuş limana varmaya.

*****          *****          *****

Dünya, seyri esnasında   yaz yerini güze bıraktı.

Ağaçların yaprakları bir bir sarardı.

Mevsim bestelere  hüzünlü bir nota bıraktı.

Serin  bir meltem gibi ruh denizimde dalgalandı.

*****          *****          *****

Şu an öğle sergisinin levhaları kallkıyor.

ikndi vaktı, şarkısını besteliyor.

Bir ihtiyar  bahçede ikindiyi kiliyor.

Bu seyrimde  ruhuma tatlı bir hüzün düşüyor.

*****          *****          *****

Selefler son kez süzüyor halefleri ıslak gözlerle.

Dünyanında gözlerinde yaşlar akıyor hicranla

Ruhum ''''Allah ısmarladık'''' diyor buralara.

İkindi namazının izdüşümü ruhuma düşüyor sevinçle.

*****          *****          *****

Selam verdi geçti rüzgar dağlara.

Veda bir musikinin notaları bıraktı ruhlara.

Bu o hüzünlü şiirdır okuyurum yarınlara.

Ruhumdaki ikindi namazının izdüşümü beni götürdü surura.

*****          *****          *****

Yapraklar sarı ve alın binbir çeşit renk ve deseninde..

Ağaçların başlarında ve akan nehirlerde...

Islak çimenlerde, yağmurlu havuzlarda..

İkindi namazının izdüişümü çümbüşlü geçitir ruhumda.

*****          *****          *****

Kimi betbahlar bu tatlı hüzünden korktu.

Çünkü bu şirin helvayı tadabilecek dimağları yoktu.

İman ehline ne keder, bu bir muştu...

İkindi namazının izdüşümü ruhumda nur-u  imala oluştu.

*****          *****          *****

Ağaçların dalardan sarı ayvalar da bir bir  düştü.

Her gün bir taşı düşerek evim harabeye dünüştü.

Gönlüme ahbaları görme umudu düştü.

Bu ta çocukluğumda kalma bir düştü.', 'Mevsim sonbahar, vakit ikndi... Tatlı bir hüzün sardı her tarafı şimdi. O Kutlu Nur Dünya vaktinin ikindisinde  indi. Dalga dalga zaman deni...', ARRAY['Türk Edebiyatı','Şiir','Nuri Yılmaz']::text[], 8.5, '{"poet":"Nuri Yılmaz","poet_slug":"nuri-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ikindi-namazinin-izdusumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözü kör olsun', 'gozu-kor-olsun-ismail-turkel-41v3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dumanlar cökmüs daglarbasina.

Görünmüyor bizim ellerin yolu.

Sürmeler cekmis kara kasina.

Bir selvi gibi uzamis boyu.

Cekil duman cekil Göremsilami.

Belki sevdigim gecerse yoldan.

Sallar yazmasin Verir selamini.

Gülmesi dahi Tadlidir baldan.

Süzülmüs duman inmis Ovaya.

Gülün icinde görünmez olmus.

Umutlarim hep giti havaya.

Ben koklamadan yapragi solmus.

Dumanlidagin bozuk havasi.

Kurdu cok olur Gezmeye gelmez.

Döner basimda kara sevdasi.

Daglar altinda Sevenler ölmez.

GÜneyim ister kalksin dumanlar.

Bülbül gülünü Arayib bulsun.

Kavussun birine Can ile canlar.

Sarilsin gülüne hep mutlu olsun.

Asik güneyim sevmem dumani.

Sevmiyeninzati yoktur imani.

ALLAH kuluna verir dermani.

Sevgi bilmeyenin gözü körolsun.', 'Dumanlar cökmüs daglarbasina. Görünmüyor bizim ellerin yolu. Sürmeler cekmis kara kasina. Bir selvi gibi uzamis boyu. Cekil duman cekil Göre...', ARRAY['Türk Edebiyatı','Şiir','Ismail Türkel']::text[], 8.5, '{"poet":"Ismail Türkel","poet_slug":"ismail-turkel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozu-kor-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berivanına', 'berivanina-halil-colak-jgqnq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Berivanına

Teşne oldum Zühre’m senin bakışına

Nesim vurdu,kalbimin ateşine

Zebun etti felek sevdiğimin gülüşüne

Sermest-i visal oldum aşkımın berivanına 

Halil Çolak 19.7.2005 Ankara', 'Berivanına Teşne oldum Zühre’m senin bakışına Nesim vurdu,kalbimin ateşine Zebun etti felek sevdiğimin gülüşüne Sermest-i visal oldum aşkımı...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/berivanina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut mudur Yaşamak?', 'bir-umut-mudur-yasamak-ozgur-cem-agca-sgouo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir umut mudur yaşamak,

Yoksa bin unut mu? 

Bin birden büyüktür

Ve diyebilirsin ki; 

Yaşamın kuralı budur! 

Ben de derim ki; 

Bir binden büyüktür

Umutsa bir 

Unutsa bin.

Yaşamak,matematik değildir.

Yaşamak,umudun ta kendisidir.

Umut,bir''dir

Ve 1>1000.

                                                    29/09/2003

                                                    GAZİANTEP', 'Bir umut mudur yaşamak, Yoksa bin unut mu?  Bin birden büyüktür Ve diyebilirsin ki;  Yaşamın kuralı budur!  Ben de derim ki;  Bir binden büy...', ARRAY['Türk Edebiyatı','Şiir','Özgür Cem Ağca']::text[], 8.5, '{"poet":"Özgür Cem Ağca","poet_slug":"ozgur-cem-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-umut-mudur-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yap''ma'' be nefise', 'yap-ma-be-nefise-behcet-gulenay-3ikoo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uyanır uyanmaz çıkıp balkona

serin bir mağara gibi karşıma durup

öyle bak(ma)  bana nefise 

gözlerin, gözlerin… söyleyemem

darmadağın ediyor insanı

baldır bacak 

her gün de camlar silinir (mi) ? 

düşmezsin biliyorum

(ama)  ben ayıp şeyler düşünemem

	

şelaleye uzanır gibi dudaklar

bir gülün yapraklarında gezdirilir (mi) ? 

hele kapı önünde gidip gidip gelmelerin

yap(ma) 

öyle yürü(me)  be nefise

sarhoş bir değirmen taşı gibi

döndürüyorsun başımı

ellerin

ellerin memleket gibi

söyle rahat dursunlar

tamda soğumuşken atardamarımdaki magma

bu ne(yin)  davet(i)  be nefise

insanı öper gibi ısır(ma)  dudaklarını ıslak ıslak

yap(ma)  be nefise

ben ayıp şeyler düşünemem

ben …

                                      Temmuz 2005

Behçet Gülenay', 'uyanır uyanmaz çıkıp balkona serin bir mağara gibi karşıma durup öyle bak(ma)  bana nefise  gözlerin, gözlerin… söyleyemem darmadağın ediyor...', ARRAY['Türk Edebiyatı','Şiir','Behçet Gülenay']::text[], 8.5, '{"poet":"Behçet Gülenay","poet_slug":"behcet-gulenay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yap-ma-be-nefise-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürüyor...', 'olduruyor-suleyman-saylan-wnxg4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖLDÜRÜYOR...

“Nasılsın” diye sormayın sakın; 

adını bile bilmediğim,

ucu bucağı olmayan bir denizde 

“çürüdü” diye atılmış,

sahipsiz bir sandal gibiyim...

Tükenmişim,

azgın dalgaların ortasında

yalpalıyorum durmadan

bir sağa, bir sola.

Hangi rüzgar esiyor,

nereden esiyor,

amansız dalgalar hangi yönde,

belli değil...

Bu anlamsız alaca karanlık niye,

deniz fenerleri nerede? 

Ay doğuyor mu, batıyor mu belirsiz

yoksa,

ay sandığım güneş mi? 

Dalgalar hepten insafsız çıktı; 

ne kıyılara atıp kurtarıyor beni,

ne de batırıp derinlere

öldürüyor...

    Süleyman  SAYLAN

    Ankara, 05.11.1986', 'ÖLDÜRÜYOR... “Nasılsın” diye sormayın sakın;  adını bile bilmediğim, ucu bucağı olmayan bir denizde  “çürüdü” diye atılmış, sahipsiz bir san...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olduruyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bikalbin Selim', 'bikalbin-selim-abdullah-odabas-1yko5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey gönül olsan mala memalik,

Uhrada etmez asla metelik,

Birazda olursa torbası delik,

“illa menetallahe bikalbin selim.”

Cem etsen cihanın sim-ü zerini,

Vermezsen fakire kırkta birini,

Nareder akıbet senin yerini,

“illa menetallahe bikalbin selim.”

Aldanma cihanda mala eyale,

Düşürür seni dipsiz hayale,

Nihayet koyar kıldan çuvala,

“illa menetallahe bikalbin selim.”

Aklı olan etmez cihana ülfet,

Birikir başına bir sürü külfet,

Kılmazsan eğer farz ile sünnet,

“illa menetallahe bikalbin selim.”

Aklı olan hemen cihandan kaçar,

Hiç vefası yoktur yel gibi geçer,

Gafilin ayağı köprüde sürçer,

“illa menetallahe bikalbin selim.”

Nar-ı cehimin çekilmez kahrı,

Zakkumdur acıdır içilmez zehri,

Beyhude geçirme bu aziz ömrü,

“illa menetallahe bikalbin selim.”

Halika eyle hulustan amel,

Birden bire gelir kapıya ecel,

Geriye kalır bir sürü çeçel,

 “illa menetallahe bikalbin selim.”

Bitir her işini eyle tedarik,

Gel olur bir gün bizde giderik,

İsrafil surunu çalınca düdük,

“illa menetallahe bikalbin selim.”

Ziruhtan kalmaz o gün bir eser,

Herkes bu dünyadan ümidin keser,

Darılmış evlat babaya küser,

“illa menetallahe bikalbin selim.”

Kalmaz cihanın Musa İsa’sı,

Yoktur hiç bir kimse çıkacak sesi,

Meftuni kalbinden silsenya pası,

“illa menetallahe bikalbin selim.”', 'Ey gönül olsan mala memalik, Uhrada etmez asla metelik, Birazda olursa torbası delik, “illa menetallahe bikalbin selim.” Cem etsen cihanın s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bikalbin-selim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kantar Tartar', 'kantar-tartar-suleyman-saylan-vsuwv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KANTAR  TARTAR

Herkesin keyfine göre dünya yok,

Olmadı, olmayacak...

Her dünyada

Ben varım, sen varsın, o var,

Akıllı ol,

Hepimize yeter bu dünya.

Özgür olmak hakkınsa

Özgürlüklerimi tanı,

Sakın saygısızlık etme

Saygı görmek istersen...

Yığın yığın sevgim var; 

Sana yettikten,

Bana yettikten,

Ona yettikten sonra tükenmez,

Artar...

Sevgi istiyorsan

Sevmeyi öğren.

Dediğin dedik,

Çaldığın düdük değildir,

Gereksiz havlama

Komşun incinir.

Terazim sırat köprüsünden beterdir,

Ben sarrafım seni tartamam,

Seni ancak kantar tartar...

      Süleyman  SAYLAN

      Ankara, 19.07.2000 saat: 02.20', 'KANTAR  TARTAR Herkesin keyfine göre dünya yok, Olmadı, olmayacak... Her dünyada Ben varım, sen varsın, o var, Akıllı ol, Hepimize yeter bu ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kantar-tartar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-i-smail-haki-simsek-mnjp6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tuttuğumda daha on yediydim

Bir sevda dalı; istemeden kırmışım...

Kırmızı bir darb-ı meselmişim

Daha yaşken söylenmişim...

Mişler...bakireymişler

Tanrı şahidim olsun,

Ben gözlerimi sakındım hep aşktan...

Şeytana da hiç tapmadım

Hiç çıkartmadım onu baştan...

Mişleri saydım; 

Her sevdanın sonunda biraz daha şaşırdım...

Mişler...bakireymişler', 'Tuttuğumda daha on yediydim Bir sevda dalı; istemeden kırmışım... Kırmızı bir darb-ı meselmişim Daha yaşken söylenmişim... Mişler...bakireym...', ARRAY['Türk Edebiyatı','Şiir','İsmail Haki Şimşek']::text[], 8.5, '{"poet":"İsmail Haki Şimşek","poet_slug":"i-smail-haki-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hikaye-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Esmâ ül Hüsnâ', 'esm-ul-husn-hikmet-kucuk-jt5hz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel Allah,  isimlerinde  duruldum,

Muktedirsin, güçlüsün sana vuruldum.

Melîksin elindedir saltanat,

Hâliksin, Bâri’sin yarattın kâinât.

Latîfsin berraklık sana özel,

Cemîlsin güzellik sende güzel.

Afüvsün affetmeyi seversin,

Nûrsun kâinattaki cevhersin.

Ululuğunda dengin yoktur, Azîmsin,

İşlerin yerli yerindedir Hakîmsin.

Varlığında son yok Bâkîsin, Vârissin,

Öldürdükten sonra dirilten Bâissin.

Her şeyi görensin, bilensin yâ Şehîd,

Müzilsin tutarsın alçaltırsın yâ Hafîd.

Şüphe yoktur varlığında Haksın,

Vâhid demişler sana çünkü teksin.

Evvelsin senden öncesi yoktur.

Rezzâksın senin rızkın pek çoktur.

Kime ne, Mukaddimsin öne alırsın,

Metînsin her zaman kuvvetli kalırsın.

Hafîzsın gözetensin mülkleri,

Hasîbsin sorgularsın halkları.

Kâinat idarende, Vâlîsin,

Şan, şeref, izzet sende Alîsin.

Bedîsin, sanatında Mâhirsin,

Varlığına delil çok, Zâhirsin.

Basîrsin her hâlükarda görensin,

Raûfsun şefkat ağı örensin.

Kayyûmsun, her an, her yere nâzırsın,

Bersin iyilik yapmaya hazırsın.

Ararsan ey Vâcid bulursun,

Muhsîsin ayrıntılı bilirsin.

Muhyîsin ki her şeye canı verensin,

Muîdsin yaratmayı tekrar edensin.

Fettâhsın iyilik kapısını açtın,

Selâmsın esenliği her yere saçtın.

Geriye bırakan Muahhirsin,

Şekil veren sensin Musavvirsin.

Sametsin kimseye ihtiyacın yok,

Kavîsin, Kâdirsin kuvvetin pek çok.

Dârsın gerekirse zarar verensin,

Bâsitsın mahlûka rızkı serensin.

Mâcidsin, Mecîdsin, şereflisin, şanlısın,

Haysın hayatı kendinden canlısın.

Rakîpsin bakışların gözetler,

Kebîr ismin ululuğu özetler.

Alîmsin, Habîrsin her şeyleri bilensin,

Gaffârsın, Gafûrsun  günahları silensin.

Mukîtsin nîmetlerin pek çoktur,

Bâtınsın seni gören hiç yoktur.

Velîsin dostluğunla yandım,

Vekîlsin güvenip dayandım.

Kötülüğe engelsin Mâni’sin,

Kimseye muhtaç değil Ganîsin.

Kâbızsın ruhları sen alırsın,

Âhirsin her şey gider kalırsın.

Muksitsin, Adlsin, adâlet gelir senden,

Tevvâbsın affedersin, dilemek benden.

Zü’l-celâli ve’l ikramsın, Celîlsin,

Cömertliğe, azamete delilsin.

Va’dine güvendim adın mü’min,

Kâinâtı gözetirsin yâ Müheymin.

Kerîmsin çok çok veren cömertsin,

Şekûrsun biz nankörüz sen mertsin.

Reşîdsin bizi irşâd edersin,

Câmi’sin, sen toplayıp derlersin.

Mütekebbirsin büyüklenen şahsın,

Cebbârsın sözü geçen padişahsın.

Mülk elindedir, adın Mâlik’ül-mülktür,

Mübdi’sin senin yaratman ilktir.

Şifâ bize İlahî Şâfi’sin,

Sen yetersin sadece, Kâfîsin.

Muğnîsin verdin zengin oldum,

Hamîdsin övdüm huzur doldum.

Sabûrsun süre verdin, sabrettin,

Kahhârsın vakti geldi kahrettin.

Halîmsin hiç acele etmezsin,

Müntakimsin zâlimi affetmezsin.

Faydan öyle çok ki Nâfi’sin,

Merhametin çok geniş Vâsi’sin.

Yâ Vedûd çok sevilensin, sevensin,

Yâ Vehhâb, elin açık bol verensin.

Semi’sin, ki her şeyleri duyarsın,

Hakemsin hükmü hemen koyarsın.

Kuddûssün eksik ne gezer şanında,

Hâdîsin yol gösterirsin anında.

Mümîtsin sen, tutar öldürürsün,

Mücîbsin, istersek, güldürürsün.

Râfi’sin, Muizsin, şeref ve izzetlisin,

Ey Azîz kuvvetlisin pek azametlisin.

Müteâlsin yücelerden daha da yücesin,

Terbiye eden yâ Rab, ne de güzel hecesin.

Yâ Rahmân, yâ Rahîm deriz elleri açarız,

Sen acımazsan acep, nerelere kaçarız.

                                             (Eskişehir 24/11/2003)', 'Güzel Allah,  isimlerinde  duruldum, Muktedirsin, güçlüsün sana vuruldum. Melîksin elindedir saltanat, Hâliksin, Bâri’sin yarattın kâinât. L...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/esma-ul-husna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi,''yol'' demeye görsün...', 'birisi-yol-demeye-gorsun-aynur-uluc-q6w0k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazı sözcükler vardır; anlamı kendini aşar. Ağızdan çıkarken o bir kaç harfte kolayca söyleniveren şeyi anlatmaya gelince sıra, dünyanın bütün alfabeleri bir araya gelse yetmez olur çoğu kez. Aşk böyle bir sözdür, emek böyle bir söz. Ben, başka bir sözden dem vuracağım şimdi, alfabeyi yetiremeyeceğimi bile bile... 

Birisi yol demeye görsün. Yanımıza azık bile almayı akıl edemeden, nasıl içimiz gider, yoldan önce. Yollara sevdalanırız en çok. Bizi yollara çıkaranlara sevdalanırız, kendimiz bilmesek de... Her yeni kavşakta bulup farklı tadını, virajın henüz göremediğimiz devamında öğreniriz, hayatı. Eldeki verilerimizle henüz bilmediğimiz yere ait tahminler yürütür, oraya vardığımızda ise karşılaştığımız yaşamın sıcak şaşırtıcılığıyla yeniden düşünerek öğreniriz acıyı, tatlıyı, kavramları, hep bir yanıyla eksik kalan; bir türlü öğrenmeyi bitiremediğimiz sevdayı. 

Bazen yollarımız kesişir birileriyle. Birisi el verir, hiç ummadığın bir anda. Haydi benimle gel der. Benimle yürü Sen onunla yürürken, o da seninle yürür, ister istemez. Senin öğrendiğin ona yol olur, onun öğrendiği sana. Ancak sanılanın aksine, yollar daha kolay alınmaz hâl böyle olunca. Birbirinin yaralarına dokunarak alır, aldırırsın gerçek yolu çünkü... Yol alırken daha aksi biri oluruz. Daha kırılgan, daha kırıcı. Üstüne üstlük daha bilmiş, daha ukalâ. Hatalar yaparız sık sık. Tamirini düşünürken büyüyeceğimiz hatalar. Bizi var olduğumuz kalıptan daha üst bir safhaya taşıyacak olan kocaman hatalar. Ve kaçınılmaz olarak kocaman bedeller öderiz elbette. Kolaydan öğrenilmez çünkü hayat. 

Yaşam sürdükçe yollar da sürüyor. Raylar akıyor trenlerin altından. Ama kaç kişi geliyor bizimle rayların devamında? 

Yol kavramı, birisiyle birlikte yürümeyi içinde taşıdığı gibi, bir gün ayrılmayı da bağrında taşıyor ne yazık ki. Doğmuş olmak, ölmeyi nasıl içinde taşıyorsa öyle bir dinginlikte taşıyor hem de...Yolu birlikte alırken duyduğumuz üretken coşkulu tada karşılık, ayrılma kavşağında nasıl da içimi acıtan bir şey var. Sanki onlarla birlikte biraz da kendimi bırakıyormuşum gibi, o insanların gizli iç ceplerinde.  Ben de biraz gidiyormuşum gibi kendimden usul usul; yitiyormuşum gibi iç burkan bir duygu; unutmaları, unutulmaları sorgulayan bir kuşku, içimde. 

Birkaç yıl kadar önce izlediğim bir filmin sonundaki cümleler, bu noktada yetişiyor imdadıma şimdi. Esas kadın, ayrılığın üstünden geçen yıllar, yollar sonrasında şöyle diyordu, kendi kendine söylenir gibi:Yüzünü sesini unuttum. Bir daha hiç hatırlayamayacağım sanıyorum. Sonra birden kendimde sesini buluyorum, yüzümde gülüşünü. Hafızanın bir oyunu bu insana.* 

Ben de, bu cümleleri beynimdeki birçok cümle içinden çıkarıp bulmuş olmaktan mutlu oluyorum şimdi ve teşekkür ediyorum hafızamın bu oyununa...

Aynur Uluç



*Karşı Pencere / Yönetmen: Ferzan Özpetek



Hayal Dergisi

2010 / Sayı 32', 'Bazı sözcükler vardır; anlamı kendini aşar. Ağızdan çıkarken o bir kaç harfte kolayca söyleniveren şeyi anlatmaya gelince sıra, dünyanın büt...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/birisi-yol-demeye-gorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yüz Kolonileri', 'yeni-yuz-kolonileri-ozan-turk-uo46a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık geri verilebilir tüm 

Tarihi geçmiş zaferler

Artık hedefini şaşırmış

Birkaç mermi olabilir

Emek verilmiş sözler…

Artık birkaç kişi daha uyuyamasın yer altında

Birkaç gecekondu daha yıkılsın

Çocukların üstüne benzinler dökülsün

Birkaç eski konak 

Daha utansın tarihinden

Artık

Bir kaç gariban daha yaşamasın köprü altında…

Birkaç köy daha boşaltılsın

Anadolu’da

Ve birkaç şehre daha tükürülsün

Artık geri verilebilir

Tüm tarihi geçmiş zaferler

Kolonilerle bulunsa da 

Bambaşka yüzler…', 'Artık geri verilebilir tüm  Tarihi geçmiş zaferler Artık hedefini şaşırmış Birkaç mermi olabilir Emek verilmiş sözler… Artık birkaç kişi dah...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yeni-yuz-kolonileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüzük', 'i-ki-yuzuk-sahin-yenilmez-80yu9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki yüzük

İki hayatı birbirine ekleyen metal

İki hayat 

Birbirinden habersiz,

Yüzük hiçbir anlam taşımıyor aslında

Hayatların kesişme noktasındaki mucizeden başka.

İki kalp birlikte atacağına

Daha da yabancılaşıyor aslında..

Yaşamlar başka

İnsanlar başka

Yüzük hiçbir anlam taşımıyor aslında...', 'İki yüzük İki hayatı birbirine ekleyen metal İki hayat  Birbirinden habersiz, Yüzük hiçbir anlam taşımıyor aslında Hayatların kesişme noktas...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-yuzuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylesene Doktor...', 'soylesene-doktor-ahmet-suat-kocal-59d6y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söylesene doktor, diğer odalarda soğuk mu,

Orada yatanlar da benim gibi üşüyor mu? 

Onlar da garip ve kimsesiz mi yoksa,

Batmış mı güneşleri gün ortasında? ..

Söylesene doktor, ne zaman bitecek bu iğneler,

Hiç uyanık kalamıyorum, böyle mi geçecek günler? 

Cam kenarına oturup, seyredemeyecek miyim dışarıyı,

Hissedemeyecek miyim güneşi, düşen damlaları? ..

Söylesene doktor, yan odadaki hastaya ne oldu,

Her zaman inlerdi, bugünlerde artık sustu.

Taburcu olup, sessizce evine mi yerleşti,

Yoksa bir anda dar-ül bekaya mı göç etti? ..

Söylesene doktor, ne kadar yaşarım ben,

Girebilir miyim toprağa gün yüzü görmeden? 

Haydi! Bana çok yaşayamayacağımı söyle,

Ağlayayım, gözlerimde buruk bir tebessümle...

Gözlerin niye doldu doktor, sen niye ağlıyorsun,

İlk kez ben ölmeyeceğim, bunu sen de biliyorsun.

Haydi gül biraz, yenik düşme kahpe hayata,

Aldırma tükenen canlara, yaşanmayan sevdalara...

Bak doktor, ben ne kadar rahatım,

Özlemişim ölmeyi, buna artık inandım.

Yaşamak, uçurumlarda dans etmekti bence,

Ben bunu başardım hem de en güzeliyle...

Hey doktor, bir taneme söyler misin sevdiğimi,

Gittiğim yerde sonsuza dek onu bekleyeceğimi...', 'Söylesene doktor, diğer odalarda soğuk mu, Orada yatanlar da benim gibi üşüyor mu?  Onlar da garip ve kimsesiz mi yoksa, Batmış mı güneşleri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/soylesene-doktor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığın Boşluk', 'biraktigin-bosluk-sahin-yenilmez-0gv0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıraktığın boşlukta

Yeni bir hayata yetecek kadar umut kalmadı

Acısını çektiğim hasretin bile

Boşluğunu dolduramadı..

Gözlerin, geceleri gözlerimi kapatmamın tek sebebi

Özlemin, gecenin zulasında berbat bir baş ağrısı

Resmine bakamıyorum bile

Demlenirken üç beş nöbetlerinde

Ağlamamak için cüzdanımın en gizli köşesinde..

Hayata sensiz bakmak

Hayatımı değiştirmiyor ki

Hep aynı sahneler 

Hep aynı kadehler..

Bıraktığın boşlukta

Hayatın boşluğunda

Bir umut kayboldu sen gidince.

Bu yaşadıklarım buğulu bir hüznün aynası

Yansıması yok benden başkasına

Ağlamak istemiyorum ama

İçimde birkaç yağmur damlası..', 'Bıraktığın boşlukta Yeni bir hayata yetecek kadar umut kalmadı Acısını çektiğim hasretin bile Boşluğunu dolduramadı.. Gözlerin, geceleri göz...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biraktigin-bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedadır Bu Gidişin Adı', 'vedadir-bu-gidisin-adi-funda-bahceci-92qoh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşları neye yarar

şehirden uzaklaşır deniz.

         Dalgalanmaz kıyılarında

eskisi kadar sık sevgilinin etekleri.

                                    Bu sebepten dir; 

                                                Alıp başını gidişi.

         Bulutlarını toplar deniz

yüklenir dalgalarını.

          Kalın bir sis kaplar

şal gibi örter üstünü.

                

                                    Dönecek gibi yol almaz

                                            Vedadır bu gidişin adı.', 'Gözyaşları neye yarar şehirden uzaklaşır deniz.          Dalgalanmaz kıyılarında eskisi kadar sık sevgilinin etekleri.                      ...', ARRAY['Türk Edebiyatı','Şiir','Funda Bahçeci']::text[], 8.5, '{"poet":"Funda Bahçeci","poet_slug":"funda-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vedadir-bu-gidisin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstavrit suretinde yaşam', 'i-stavrit-suretinde-yasam-sair-dusotesi-4ir76', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'henüz bir istavrit çekti

al yanaklı deniz gözlü çocuk

tahtadan oltası

yedilik yüzü yetmişlik elleriyle

öyle kavradıki

oltada çırpınan isvriti 

istavrit olasım geldi yetmişlik ellerinde

ağlayan sonbaharlar ve anaforlarda yutulan 

büyük yelkenli aşklar kadar hüzünlüydü

bir istavrit yaşamı

ama bir okadar da vazgeçilmezdi

ayrılmak o yarılmış toprak hamurlu bileklerde

uzaklaşmak istedim 

yürümedi bileklerim

deniz gözlü çocuğun elleri

birer coğrafyaydı 

uğruna savaşlar verilecek

ne ki istavritin atlantisi

hayat çizgilerinden ırmakların çağladığı avuçların ötesinde

mesele onurlu ölmek değil mi

kelebek öyküsü yaşamlarımızda

yahut yaşayabilmek onurlu bir sevda uğruna

ölememek değilmi hergün öldürülürken biraz

ve aslında pekte önemli değil sadece ölmek biraz

işin önemlisi pullarını dağıta bilmek sürüklenirken

o koca çağlayanlarda

bir keman sesindeki ince sızıyı anlamak asl olan

ağlayabilmek salya sümük vurdum duymaz

utanmadan bakabilmek 

fıratın tufanında aks eden çehrene

şavkıya biliyomusun 

ay doğmaz it ürüyen gecelerde 

yaşamak bu işte

yaşamak ve ölmek bir istavrit suretinde', 'henüz bir istavrit çekti al yanaklı deniz gözlü çocuk tahtadan oltası yedilik yüzü yetmişlik elleriyle öyle kavradıki oltada çırpınan isvrit...', ARRAY['Türk Edebiyatı','Şiir','Şair Düşötesi']::text[], 8.5, '{"poet":"Şair Düşötesi","poet_slug":"sair-dusotesi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/istavrit-suretinde-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-osman-karaduman-1ccnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımda sana

Özlemlerimde yüreğime

Çaresizliğimde ise sevgine

Sığınıyorum bir liman gibi...

24.05.2003', 'Yalnızlığımda sana Özlemlerimde yüreğime Çaresizliğimde ise sevgine Sığınıyorum bir liman gibi... 24.05.2003...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gibi-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-osman-karaduman-bnlgo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önümden geçerken iki sevgili

Yüreğim burulur gözlerim nemli

