INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '65 Nolu Rubai', '65-nolu-rubai-omer-hayyam-ei9um', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sâki, arttır canımdan diri kalanı,

Halk sohbetinde çok az yeri kalanı.

Bilirim, dün şaraptan kaldı bir kadeh; 

Kim bilir ki ömrümden geri kalanı? 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Sâki, arttır canımdan diri kalanı, Halk sohbetinde çok az yeri kalanı. Bilirim, dün şaraptan kaldı bir kadeh;  Kim bilir ki ömrümden geri ka...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/65-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '68 Nolu Rubai', '68-nolu-rubai-omer-hayyam-3bhh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gerçeği bilemezsin, harcama emek,

