INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '81 Nolu Rubai', '81-nolu-rubai-omer-hayyam-j9qfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya derdiyle harap olmadan böyle,

Bol bol içelim kızıl şaraptan şöyle.

Dünya kanlımız; şarap, dünyanın kanı; 

Kanlısının kanını kim içmez; söyle? 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Dünya derdiyle harap olmadan böyle, Bol bol içelim kızıl şaraptan şöyle. Dünya kanlımız; şarap, dünyanın kanı;  Kanlısının kanını kim içmez;...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/81-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '83 Nolu Rubai', '83-nolu-rubai-omer-hayyam-wzzio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadeh bir bedendir ki, ondan can doğar,

Yasemine benzerken, erguvan doğar.

Hayır, yanlış söyledim; aslında şarap,

Ateşten gebe kalan bir sudan doğar! 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Kadeh bir bedendir ki, ondan can doğar, Yasemine benzerken, erguvan doğar. Hayır, yanlış söyledim; aslında şarap, Ateşten gebe kalan bir sud...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/83-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '85 Nolu Rubai', '85-nolu-rubai-omer-hayyam-bm57g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey şarap; güzelliğin kadehe çöker,

Bağladığın akıllar, ipi zor söker.

Senden birazcık içen, inan ki herkes; 

İçindeki cevheri avcuna döker! 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Ey şarap; güzelliğin kadehe çöker, Bağladığın akıllar, ipi zor söker. Senden birazcık içen, inan ki herkes;  İçindeki cevheri avcuna döker! ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/85-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz/ün Gelimi', 'soz-un-gelimi-ali-aydogdu-xz0nd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'birine  koldu 

diğerine kanat

ötekilere inat 

biri  kolun aldı

diğeri yolun kazdı

ötekiler '''' hey  '''' dedi bir ağızdan,  ''''düşme '''' 

hepsi, o''nlar  kıvamında şimdi 

o''nlar kadar  kalabalık

ve dar sokaklara

enine sığar daha

biri  kol oldu

diğeri  kanat 

ötekiler sustu 

o,   ben değildim

öteki de ben değildim

sende  ne ilktin,

 ne son şiirimde 

ben olsam,

dışında kalırdım maceranın 

sen olsam 

utanırdım 

acaba '' sızdır bütün mesele 

belki'' siz git,  gideceksen 

menzil  her yerde', 'birine  koldu  diğerine kanat ötekilere inat  biri  kolun aldı diğeri yolun kazdı ötekiler '''' hey  '''' dedi bir ağızdan,  ''''düşme ''''  hepsi, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydoğdu']::text[], 8.5, '{"poet":"Ali Aydoğdu","poet_slug":"ali-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soz-un-gelimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '90 Nolu Rubai', '90-nolu-rubai-omer-hayyam-o1dfq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şarabı ışık, güneş gibi içmeli,

İçmeli dolu dolu ve deli deli.

Bir tanıdık sokakta beni görünce:

Merhabalar Ey Şarap; deyip, geçmeli! 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Şarabı ışık, güneş gibi içmeli, İçmeli dolu dolu ve deli deli. Bir tanıdık sokakta beni görünce: Merhabalar Ey Şarap; deyip, geçmeli!  (Hayy...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/90-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '91 Nolu Rubai', '91-nolu-rubai-omer-hayyam-1ezfs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şarap; gurur, benliği alır hep geme.

Şarap çözer düğümü, zor ve güç deme.

Şeytan bir yudum şarap içmiş olsaydı; 

Bin kez secde ederdi her gün Adem''e! 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Şarap; gurur, benliği alır hep geme. Şarap çözer düğümü, zor ve güç deme. Şeytan bir yudum şarap içmiş olsaydı;  Bin kez secde ederdi her gü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/91-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Diyememki', 'gitme-diyememki-baran-demir-6kcez', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gitme diyememki 

bir damlaydı gözümden akan

önceleri sadece suydu

bedenimden akıp giden

vurdum duymaz olmuştum

sönen ışıklara sönen gözlere

tek tek kapanmakta ışıklar

tek tek susmakta

yitip giden artık atmayan yüreklere

sonraları ufak ufak anımsamakta

topraga karışıp giden göz damlalarını

hayatları,sevdaları,acıları,hüzünleri

ne gelir elden gidenlerin ardından

türküler agıtlar yakmakmaktan başka 

gitme diyememki', 'gitme diyememki  bir damlaydı gözümden akan önceleri sadece suydu bedenimden akıp giden vurdum duymaz olmuştum sönen ışıklara sönen gözlere ...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitme-diyememki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '98 Nolu Rubai', '98-nolu-rubai-omer-hayyam-znnoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şarap; azlık, çokluğa gönüllerde çaredir.

Yetmişiki millette ve her yerde çaredir.

Bir çeşit ilâçtır o, perhize kalkma sakın; 

Şarabın bir damlası, binbir derde çaredir! 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Şarap; azlık, çokluğa gönüllerde çaredir. Yetmişiki millette ve her yerde çaredir. Bir çeşit ilâçtır o, perhize kalkma sakın;  Şarabın bir d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/98-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak beni', 'birak-beni-ahmet-kesici-l969b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırak beni 

	 

Hadi git. 

Hadi bırak beni. 

Ardına bakma, veda etme bana. 

Oralı olma kırgınlığıma. 

Kızgınlığıma aldırma. 

Hadi git. 

Hadi bırak beni. 

Geri geleceğine söz ver. 

Döneceğim de 

Bir daha geri dönme 

Beklet beni buralarda. 

Günlerim kararsın. 

Yüreğimde çıkardığın yangın gecelerimi aydınlatsın. 

Hep ha geldi, ha gelecek sanayım. 

Ama sen gelme, beklet beni. 

Yüzüme gülme. 

Yüzündeki hüznü dök yüzüme. 

Kır kalbimi. 

Üz beni. 

Yalan sözler söyle, kandır beni. 

Seni seviyorum de, inandır beni. 

Sonra bir başkasını sev,  aldat beni! ! ! 

Ardından ukalalık yap, 

Bencilce yüzüme bak. 

yak yüreğimi, 

ağlat beni. 

Ağlat ki başımda duman bulut olsun. 

Ağlat ki gözyaşım yağmura yandaş olsun. 

Allah’ın aşkına bir şeyler yap, 

Unuttur bana kendini.! 

Geri geleceğine söz ver. 

Döneceğimde. 

Sakın dönme. 

Dönersen eğer, masa üstünde bitmiş sigara paketi, 

İzmaritle dolmuş küllük, 

ardında beni göreceksin çökmüş, bitmiş. 

Bembeyaz duvarların da odamın, 

Kararmış beni göreceksin. 

Belki acıyacaksın halime, 

Belki sarılıp öpmek isteyeceksin. 

Belki de, 

Tiksineceksin perişan halimden. 

Bu sebepten, 

Giderken 

Vur, 

ÖLDÜR BENİ...! ! ! 

Ahmet Kesici', 'Bırak beni  	  Hadi git.  Hadi bırak beni.  Ardına bakma, veda etme bana.  Oralı olma kırgınlığıma.  Kızgınlığıma aldırma.  Hadi git.  Hadi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/birak-beni-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '99 Nolu Rubai', '99-nolu-rubai-omer-hayyam-7iif3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendi içmez, içeni kınamaya bayılır

Yüzünden aldatmaca, sahtekârlık yayılır

Şarap içmiyor diye, kasılıp gezer ama; 

Yedikleri yanında şarap meze sayılır! 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Kendi içmez, içeni kınamaya bayılır Yüzünden aldatmaca, sahtekârlık yayılır Şarap içmiyor diye, kasılıp gezer ama;  Yedikleri yanında şarap ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/99-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağmalı saatler', 'agmali-saatler-ozan-turk-5hesg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydi kalk

Bak 

Sabahın kaçıdır sende

Haydi kalk

Kimseler uyanmamıştır daha yaşadıklarında

Bu saatleri insanın

Yaşadıklarının ağma vaktidir

Şimdi gülebilirsin içinden gelen yere bakarak

İçinden geldiği gibi 

Bu ağma saatleri yaşadıklarının

Bu yıldızları seyre dalmışlardır ömrünün yıldızları

Haydi kalk

Bak saatin kaçı oldu sende

O sıcak yatağını bırak

Kalk

Ve gül içinden geldiği gibi

İçinden gelen yere bakarak hem de

Gül şimdi bu ağmalı saatlere…', 'Haydi kalk Bak  Sabahın kaçıdır sende Haydi kalk Kimseler uyanmamıştır daha yaşadıklarında Bu saatleri insanın Yaşadıklarının ağma vaktidir ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/agmali-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '100 Nolu Rubai', '100-nolu-rubai-omer-hayyam-utrvc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldız ve ay her zaman gökte olacak.

Saf şaraptan iyiyi sanma bulacak.

Şarap satan insana ben çok şaşarım,

Satıp, ondan güzel bir mal mı alacak? 

(Hayyam''ın Türkçe Yüzü-Türkçe Yeniden Yazan-Yalçın Aydın Ayçiçek-Can Yayınları)', 'Yıldız ve ay her zaman gökte olacak. Saf şaraptan iyiyi sanma bulacak. Şarap satan insana ben çok şaşarım, Satıp, ondan güzel bir mal mı ala...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/100-nolu-rubai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğmak...Yeniden Yaşamak...', 'yeniden-dogmak-yeniden-yasamak-abbas-yurt-9wpac', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeniden doğmak, yeniden yaşamak. 

Masumca bakışlardaki kaçamak, 

Sevgidir o, amaç onu anlamak, 

Amaç onu tekrar, tekrar yaşamak. 

Anlatabilir misin bana aşkı, 

Bülbülün gül için yaptığı meşki, 

Feda etmez misin sarayı, köşkü, 

Sevdiğinle yaşamak için aşkı. 

Mümkün mü? Tarif etmen güzelliği, 

Güldeki, çiçekteki tazeliği, 

Doğa bu, doğanın özelliği, 

İşte budur hayatın güzelliği. 

Kulak ver dinle kalbinin sesini, 

Gör yüzdeki sevgi ifadesini, 

Tutuver biran için nefesini, 

Ruhunla okşa sevginin sesini. 

Yakalamak istesek de sevgiyi, 

Koruyamayız bir türlü dengeyi, 

Boşver, bırak gitsin kısır döngüyü, 

Kaybetme sen özündeki sevgiyi. 

05.06.2001 

Abbas Yurt', 'Yeniden doğmak, yeniden yaşamak.  Masumca bakışlardaki kaçamak,  Sevgidir o, amaç onu anlamak,  Amaç onu tekrar, tekrar yaşamak.  Anlatabili...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yeniden-dogmak-yeniden-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Ninnisi', 'gece-ninnisi-cem-karadeniz-1bcxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudağımda ayak izin

Bağıra çağıra yazmak istiyorum gövdene

Ey gözlerinin alaca yokuşunda edindiğim

Sevgi yandaşı

Aydınlık türküsü

Zor zaman ustası,

Ben dün yine sana sevgimi

İçime kustum,

Ay dolu gecelerde

Yalnız bir gece ninnisi söylercesine 

Tutkun sokaklar

Suskun yıldızlar

Ve

Vücudunu saran benim yavrucak

Hadi benim altımda uyu…

(04/09/99 & camyuva-antalya)', 'Dudağımda ayak izin Bağıra çağıra yazmak istiyorum gövdene Ey gözlerinin alaca yokuşunda edindiğim Sevgi yandaşı Aydınlık türküsü Zor zaman ...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-ninnisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-abbas-yurt-20939', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde değil ki seni sevmemek, 

Çünkü gülüm ben sensiz yaşayamam. 

Mümkün mü senin için ölmemek, 

Bu canımı sensiz taşıyamam. 

Suç mudur seni sevmek melek yüzlüm, 

Su kadar temiz, bebek kadar mazlum, 

Biliyor musun benim ahu gözlüm, 

Güneş olsam sensiz ışıyamam. 

14.02.2002 

Abbas Yurt', 'Elimde değil ki seni sevmemek,  Çünkü gülüm ben sensiz yaşayamam.  Mümkün mü senin için ölmemek,  Bu canımı sensiz taşıyamam.  Suç mudur sen...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk - Bir Yudum Umut Resmi', 'ataturk-bir-yudum-umut-resmi-cem-karadeniz-dcl3c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen,

Yüzyılların tanık olduğu coşkuyu

Dillendiren yudum yudum ezgilerce

Söylenmemişleri bir yana koyup

Söylenememiş aydınlıkları çizensin…

Sen, 

Gözlerince uzak bir ufka inanıp bir ömür

Gözlerini yumduğun anları hayata sokup 

Gözkapaklarını saran simsiyah kuşağı

Gözbebeklerinin şavkında boğansın…

Sen, 

Tanımsız korkuları hapsedip inancına

Korbeyaz doğruları heybende unutup

İnancında eksiltip başaramama telaşını

Bir tutam aydınlığı dingin halka saçansın…

Sen,

Devrimi doğuran kararlı bakış

Esareti yıkan balyoz

Emperyalizmin yüzünde patlayan tokat

Son bir söz köleliğe dair…

Sen,

O’sun işte devirip giden köhne yangını

Unutulmuşluğun çığlığıyla uyanan sabah

Bir çıtırtının öznesi sessizlikte

Son hecesi, yükselen bir haykırışın.

Yaraya basılan sinsi tuz değil

Mutluluk türküleri, aydınlık sevdaların.

Başkaldırışın özgür yüzüsün sen,

Ablukadan arda kalmış

Dev bir şiir; 

Bilmem hangi şairin kaleminden sökülmüş

Kimbilir hangi sanatçının can verdiği

Notasız bir senfoni,

Berrak bir derenin coşkusuna takılmış

Devasa bir yangın resmisin,

Suyun ritminde şırıl şırıl raks

Omuz omuza halkıyla, dizi dizi halay

Gözgöze romantik bir vals

Memede çocuk susamış özgürlüğe…

Dedim ya

Gökyüzü zamansız yarılır kimi gün

El değmemiş korkuları yırtar zaman

Parçaları birleştiren mavi bakışlı adam

Ufka dalar ıssız aydınlıkta

Ve karanlığa bir damla düşer sessiz

Yalnız bir damla

Ki yetim kalmış bir sonbahar sabahı; 

Ağlayışı sezinleyen yürek

Özleyiş çizgisini aşar

Sonsuzluğa kanat çırpar yorgun martı

İnanılası bir gelecek getirir fısıltın

Mutlu yarınlar müjdeler maviyi anlatışın

Bedeninin uzaklığınca yakın fikrin

Sen bulutların şarkısı

Bir bebeğin düşlediği enginliksin.

M Kemal Atatürk

(10 Kasım 1998 - Antalya)', 'Sen, Yüzyılların tanık olduğu coşkuyu Dillendiren yudum yudum ezgilerce Söylenmemişleri bir yana koyup Söylenememiş aydınlıkları çizensin… S...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ataturk-bir-yudum-umut-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Gün Küçükken', 'ben-bir-gun-kucukken-cem-karadeniz-eewnx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İpotek bir kalpti bıraktığın dün gece

Yâdsınmış bir yüzyıl sevdasına dair,

Gözlerinde kelebeklerin uçtuğu

Bir sevda dinletisiydi yüreğin; 

Yılgın bir vazgeçiş aksiydi sanki

Sevdalı bir çiftin özleyişi baharı; 

Soluğun, doğurgan bir vazgeçiş tınısı

Ve yalnızlık anlatısı birkaç satır,

Keşkeye kalkan bir vapur ürküntüsü adın

Ve adının tekrarına takılı bir leylak 

Pişman karaltısında gecenin...

Sen 

Öpmelerin yansıdığı zamansız bir seviş

Keşke ile başlayan tümcesel dokunuş

Aykırı bir sevda rüyası resmisin

Bir yanı yoksunluğunu anımsatıyorken

Karanlık bir gece yolcusu diğer yanı; 

Olsun varsın dönmeyişleri bahar sabahında...

Cem K.

01.06.1999

Kemer- Antalya', 'İpotek bir kalpti bıraktığın dün gece Yâdsınmış bir yüzyıl sevdasına dair, Gözlerinde kelebeklerin uçtuğu Bir sevda dinletisiydi yüreğin;  Y...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-bir-gun-kucukken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat!', 'dikkat-mustafa-dogan-kuzgun-rg45y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umut çimlerini yeşile boyayan

Bütün kederleri benimle beraberken yok olan

Dudağımdan çıkan birkaç sözle avunan

Sevda türkülerini ağlayarak okuyan

Son nefesinde bile adımı sayıklayan

Bir sevgili arıyorum.', 'Umut çimlerini yeşile boyayan Bütün kederleri benimle beraberken yok olan Dudağımdan çıkan birkaç sözle avunan Sevda türkülerini ağlayarak o...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dikkat-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınsın', 'kadinsin-cem-karadeniz-r3po3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Damla damla sıcaklığın sarıyor gövdemi

Aklımın ucundan geçerken uğramış

Bir gelincik kokusu teninin şarkısı.

Göğüsler küçük, kalçalar dört köşe

Gerdan göbek fazladan; 

Yine de düştü mü adamın aklına bir kez

Kolay çıkacak kadın değilsin,

Yazık ki ancak o kadarsın…

(18/12/98 04:00 kemer)', 'Damla damla sıcaklığın sarıyor gövdemi Aklımın ucundan geçerken uğramış Bir gelincik kokusu teninin şarkısı. Göğüsler küçük, kalçalar dört k...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kadinsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin öykü...', 'bin-oyku-zafer-zengin-etnika-u4gcj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

Bin

Öykü

Dinlerim

Dizlerinin

Dibinde

Sen 

İste

Can

Olursun

Elin

İç’ime

Değdiğinde

Sana

Gelirim

İç’im

Sen

İste

-  Sen susunca h/iç’e takılıyor ayağım  -

Çocuğum

Kızma bana

Büyümedim

İç’te

22 12 2004

.', '. Bin Öykü Dinlerim Dizlerinin Dibinde Sen  İste Can Olursun Elin İç’ime Değdiğinde Sana Gelirim İç’im Sen İste -  Sen susunca h/iç’e takılı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bin-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlaşılmaz Masal Anlatımı', 'anlasilmaz-masal-anlatimi-cem-karadeniz-4porh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gölgelerde saklı bir şarkıydı sevdiğim

Bir salkım elma yalanında

yalnız bir kurtçuktum ben

Sen ise

İnce bir damak kıvrımı iki diş arasında.

Kol kola girmiş iki tükürük taneciği

düşüverdi rüyama

Ki ben daha çocuk çocuk yansırdım aynalara; 

Oysa yalnız ben mi efkâr kışkırtan

bu talihsiz sahnelere? 

Ki o gün yazılmıştı

tadınsız bir başlangıç yeminine götüren öfke yöngesi.

Ellerin miydi bilmem koşarak kaçma çabasındaki? 

Ve olur da kırparsa gözkapaklarını felek çıkmazı,

Bir merhaba aksine doğan

ıssız bir yalnızlık anımsatır

soysuz gölgelerde gönül hırsızı.

Coştunda eller mi azarladı? 

Çünkü bir bardak su terinde

tersine gelişmiş bir azınlık sevgi dediğin.

Olur mu böyle yalnızlık salgısı uzantılar her gecede? 

Ellerin değil miydi ıslatan gözlerimin buğusunu

tel tel kadayıf kızartısında? 

Ve anlatılan yalanlardan mütevellit,

Sakallı bir kız çocuğu doğuran 

lepiska saçlı oğlancık,

Gönlünü kaptırmış maviş gözlü bir dana yavrusuna.

Anında yayılmış bu sevda akıntısı şehrin tılsımına.

Yarasalar, yaramayasa bir serzenişle

kopuk gözkapaklarından; 

Uzak iklimler arzular olmuş.

Bir yılan ürküntüsü taşımış adı

yıllar yılıkaranlık bir gar anımsatöründe.

Anasının koynundan kopardığı

bir tutam kıl hırçınlığında hüzün taşımış yüreğine.

Yılların içinden geçip,

beyaz bir sakal bulutu griliğinde dokunmuş geleceğine.

Satırlarda kaybolmuş bir eskici kadın çığlığı dolanmış kirpiğine.

Ve ellerde beliren buruş bir cinayet öykünmüş düşüncesine. 

Böyle gelmiş böyle gider bir masal anlatımı bu da işte. 

Ne kadar gerçek olabilirse, o kadar yalan…

(haziran 2000 kemer)', 'Gölgelerde saklı bir şarkıydı sevdiğim Bir salkım elma yalanında yalnız bir kurtçuktum ben Sen ise İnce bir damak kıvrımı iki diş arasında. ...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/anlasilmaz-masal-anlatimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De gülüm...', 'de-gulum-zafer-zengin-etnika-ud1hy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

ve gülüm

rüzgar estiği yönde hep haklıydı

karış içine

sıyrıl toprağın üstünden

kapıl rengine

iklim senle

rüzgarla senle gelsin

ve bilirim

ellerin sıcaktır

ikindilerde

camlar suskun

şehir kendini okur

hep mavi olsun ufkun

gül sadece

gül yüzüne

rüzgarım bende

dokun elime

ikindide

belki bütün gece

sen bende

ben sende

rüzgarız ikimizde

söyle gülüm

nereye gidelim

bahar gelince

sen söyle

gözüm sende

de gülüm 

de hele

08.01.2005

.', '. ve gülüm rüzgar estiği yönde hep haklıydı karış içine sıyrıl toprağın üstünden kapıl rengine iklim senle rüzgarla senle gelsin ve bilirim ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/de-gulum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Ormanın Günlüğü', 'asi-ormanin-gunlugu-cem-karadeniz-znuyg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günler sonra bir gün

Şafak vaktiydi yine

Ve orman perisi

Ve orman

Ve perisi

Ve

Sen girdin düşlerimin çığlığına,

Bir ton daha koyu

Bir ömre yaslı hüzün okunuyor

Kirpiklerinin satır arasında

Sonbahar dallarında sapsarı bekleyişler

Yokluğunca isyankâr

Varlığınca kırgın

Özlemince yalnız

Kuralsız bir sözcük oyunu.

Bir bardak dem koyusu

Bir tutam tuz acısı

Bir avuç özlem yakısı

Yüreğimin bilmecesi…

Cem Karadeniz

25/12/98 01:30 

Kemer Antalya', 'Günler sonra bir gün Şafak vaktiydi yine Ve orman perisi Ve orman Ve perisi Ve Sen girdin düşlerimin çığlığına, Bir ton daha koyu Bir ömre y...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/asi-ormanin-gunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı kaldı bana...', 'aci-kaldi-bana-zafer-zengin-etnika-qsmgj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

I.

Acı kaldı

Baktım giderken

Hüznümü de almışsın yanına

Dönüşünde

Kül gülüşünle

Merhem getir içime

İçim yanıyor 

Sen susuz gidince

Yalnız  kalıyorum

Deli kahkahalar

Takılan yüzümle

II.

Bu sabah

Seni düşünürken

Yüzümü kestim sessizce

Dönersen

Hüznümü sür yüzüme

Aşk olsun  kalmadı

Gözlerim kan taşı

Ağır ilmekler ellerimde

Serçe parmağım kangren

Ve uyuşmalar

Satır arası renk saklıyor

III.

Gece

Mora kesiyor düşünmeyi

Bir kez olsun emmedin ki

Kan damlar dudağımdan

Ahh İç kanatır yazmak akşamdan

IV.

Anasın acılarıma

Kadın ve sevgili

Hüznümü aldın

Acı kaldı

Dönersen 

Geldim deyip ağlama

Ben çocuğum

Ağlamak miras bana

Kendimi doğurmuşum

Sensiz kalan

Senden artan yalnızlığa

25 02 2005

.', '. I. Acı kaldı Baktım giderken Hüznümü de almışsın yanına Dönüşünde Kül gülüşünle Merhem getir içime İçim yanıyor  Sen susuz gidince Yalnız ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/aci-kaldi-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair Bir Düş Oyunu', 'sana-dair-bir-dus-oyunu-cem-karadeniz-ldyf8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boğuyor gecenin siyah türküsü aydınlığı

Ellerin dertli yarınları kavrıyor

Göremiyorsun yazık; 

Kıvılcımları kucaklıyor yıldızlar

Ki beynim ateş parçası

Daralan bir kıskançlık var tenimde

Gövdem daralıyor

Hissiz avuntular avuçluyor zamanı

Aynalar sensiz izliyor güzelliğini

Anımsanan dostluğun ancak

Dokunuşunla kalkan bir kadeh dudak izin

Özlemiyorum eskisi gibi öpüşünü

Sevişmek hayali kirletmiyor çarşafımı

Issız bacak aran düşlerimde.

Tenimden yüreğine taşınmış ürpertin,

Bir sigara yakılası tasalar

Köhne iskelenin dalgalarla dansı

Rüzgârda can çekişen gözyaşı taneleri

Çarpan kapının ürperten çığlığı

Ve cep kanyağının son yudumu

Sana dair bir düş kurumun alt yazısı artık

Alkışlanan son durağı senaryonun…

Cem K.

30/01/99 05:00

Çamyuva - Kemer', 'Boğuyor gecenin siyah türküsü aydınlığı Ellerin dertli yarınları kavrıyor Göremiyorsun yazık;  Kıvılcımları kucaklıyor yıldızlar Ki beynim a...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ancak-sana-dair-bir-dusoyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatacaktım...', 'anlatacaktim-zafer-zengin-etnika-kmugk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.



anlatmaz mı kelime 

kendi kendini

bize 

sevda 

ölüm 

özgürlük 

ya da adları her neyse 

biraz şiir 

hangisi eğilir 

düşlerimden içeri 

eğil sen de gir 

kızmayasın diye 

tanrı benken 

| enel hak der mansur | 

sevmezdi kendini 

bu yüzden göstermez 

kendi zaten bende

ara sıra sevdalanır 

döker şiirle içini 

meraklı bakma 

okumadın ki 

| çok kitabınız var | 

anlatacaktım 

küstüm kendime 

beni dinleme 

düşünmek kapı içinde 

anlatacaktım 

o son dendi 

sürem bitti 

git 

güle güle 

deli de 

sobele 

12.12.2004 

 

.', '. anlatmaz mı kelime  kendi kendini bize  sevda  ölüm  özgürlük  ya da adları her neyse  biraz şiir  hangisi eğilir  düşlerimden içeri  eğil...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/anlatacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askıda Senden Arda Kalan Öpüş', 'askida-senden-arda-kalan-opus-cem-karadeniz-cz1ok', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin en çok sıcağına aldandım,

Dokunuşundaki esrardı dizelerimde 

Kenetlenen

Ve yalnızlık tortusu birkaç satır; 

Seni bana getiren ayaklarındaki coşku

Elverir ki ıssızlığımı boğazlamasın

Ben senin en çok ürpermene düştüm gece 

Yarıları

Ve olmaz olsun bir şiir yakısındaki gözlerine

Ve avucumda kalan ıslaklığına

Ve sevişmenin kutsiyeti kollarımdaki

Arzulu ısırışlarına beynimi

Ve dilaltındaki hazine

Ve kollarını dolayışın rüyama,

Kopardığın her bir saç telimde

Yüreğimi taşıdım geleceğe

Köprüler kurdum dingin yarınına aşkın

Oysa dalgalandı yüreğim resmin resmin

Bakış fırtınası bir asa dürtüsüydü

Dokunuş titreyişli haykırışındı

Ben sana en çok sonbaharda vuruldum...

Sevgi

Dostluk

Aşk

Aldanış

Öfke

Hırçın

Sadık

Ve sen işte be yavrum,

Sol yanımdaki alımlı beyazlık

Dilimin dokunuşu sıcaklığına karnının

Yanı başında bir deprem telaşı taşıdı hep

Birazdan başlayacak o mutlu fırtınaydın 

Yatağımda

Çarşafıma dolanan senin adındı

Rüyamdaki çıplak kızın aksiydin sen

İki yastık arasına sıkışmış bir hayalin

İki bakış arasındaki tadıydın

Birleşebilme umudu oldun 

		İki terli vücudun

Bulutlardaki kucaklaşmanın adı oldun,

Haykırışlarla boşalırken gövdeme

Melek melek sardın yüzümü

Gözlerim sana kayıverdi kopmamacasına

Dedim ya

Bitmez bir sevda kalıntısı korkusuyla

Elinden tutup kaldırdığın 

O yalnız adamdı, yükledin dizelerime

İyi ki sen varsın

İyi ki hep senin gözlerinde izlenecek

O boşalma telaşı kokuşlu yarınımız; 

Eyvallah dost sevgili

Güzel insan

Yar bakışlı 

Anlam katışlı

Güzeller bir tanesi sevgilim benim

Sana az bile söyledim

Ne çok sevdim seni gece yarıları

Ne çok boşaldım derinliğine karanlığın

Sen sen sen sen

Hep sen...

(04.08.99 & 05.50 -Çamyuva)', 'Senin en çok sıcağına aldandım, Dokunuşundaki esrardı dizelerimde  Kenetlenen Ve yalnızlık tortusu birkaç satır;  Seni bana getiren ayakları...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/askida-senden-arda-kalan-opus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendin', 'sendin-cem-karadeniz-y0eis', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceydi kahve koyusu teninden geçen,

Ateşböceği yanışlı bir esintiydin; 

Mutluluk anımsatan bir resimdi gözlerin, 

Sen yankılanan şiir resmi penceremden; 

Adında gizli bir satırdı hayat,

Çözebilme çabasıydın gözlerimin; 

Duyarsızca saçılmış bakıştın,

Yankılandın tenimde; 

Islak bir ten aksiydi yansıyan aynamdan,

Sendin

Sen dolu geceyi aydınlatan öykü duvarı…

Cem K.

07/05/1999 - 03:00

Antalya', 'Geceydi kahve koyusu teninden geçen, Ateşböceği yanışlı bir esintiydin;  Mutluluk anımsatan bir resimdi gözlerin,  Sen yankılanan şiir resmi...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sendin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıdım su''ya durmuş /Fırat ve Ruko...', 'agidim-su-ya-durmus-firat-ve-ruko-zafer-zengin-etnika-6101w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

Az kaldı taşın öyküsüne

Destan dizeceğim memleketime

Dize dize

Kelimelerle

aa canım taşlarla yatanım 

sırtı yanığım

kemikleri kırığım

unuttum gülmeyi

düştüm sensizken deliliklere

Yalanıyla

Çok kalmaz yanımda

İnsan kadın olsa da

Yıkma içimi

Dağlama

Gözlerimi boyama

Merhamet et bağışla

Ağıdım sana taşım

Saç bırakmayan tarağın

Perdah çeken bıçağın

Fırat senin akışın

Taşım vardı sana

Sevdiğim yanımdayken 

Kaydırdığım

Koşup kenarına

Saklandığımda

Attığım

Dizginlemek için elini ayağını

Taştan köprülerim

Demiryollarım

Taşım vardı sana fırat

Gülümü kopardığın

| Hiç büyümedim gülüm

Hızlı koşanlardan geri kalmak zor insana

Anlatmak zor değil

Meyven varsa sırtına atıp 

Üşümemek için sarıyorsun elini

Dolamaya et

Yaraya çeşit otlar

Derin ha iyileşmez 

Yar dokunmayınca

Eme''nin anasıda öldü

Gök gözlü ruko

Sen rukiye derdin

Genç yaş

- İnmede yok telaş-

Zemheri geldiğinde

Özlüyorsun toprağın kokusunu

Diz boyu kar

Adımların sana dönüyor

Yorulmak nedir karda yürüyünce anlıyorsun

Tipi vurunca yüzüne

Senin içinde boğulman kadar

Nefessiz kalıyor insan

Ve yeşerince her yer baharda

Yemyeşil olur munzur dibinde

Her köy her tarla

Nasıl dinç kalkar hava

Saklandığı karın altında

Görürsün erzincan’da

Baharda |

Yayılmış elin

Serilmiş ovaya saçın

Nazlı gelin

Yaralı sevda

Al fırat

Al benide yanına

Denize çıkar yolumuz

Bağla beni hışmına

Ateş düşmüş ocağıma

Bir de sen yakma

| Kan durmasın diye

Ağıdımı suya attım

Maviye boyadım

Maviadım|

Ağıdım su''ya durmuş

Türkü olmuş

Oyy fırat fırattt...

05.01.2005

.', '. Az kaldı taşın öyküsüne Destan dizeceğim memleketime Dize dize Kelimelerle aa canım taşlarla yatanım  sırtı yanığım kemikleri kırığım unut...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/agidim-su-ya-durmus-firat-ve-ruko-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinin sıcak rengi / Necla / Erik ağacı / Ben...', 'ellerinin-sicak-rengi-necla-erik-agaci-ben-zafer-zengin-etnika-jts3m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

Sıcaktı o zaman yazlar

Serkeş koşturmalar sürerken

Gözlerimi dikmişim gün ortası

Nejla ve elbisesine takılmışlar

Soramadım kimin memesi daha büyük

Tutundum mu kiraz dallarına

Kopar kökünden kıyamet

Çektikçe hasret nejla’ya

Sarıl yaz günü o sıcakta uykulara

Soramadım kimin gözleri daha kahve

Gülümserdi yeni renk bulmuş teni

Aynı ellerinin sıcak rengi

Birazı utangaç birazı pembe

Öpünce can düşerdi içime

Sormadım neden gitti son güldüğünde

Nejla sonbaharda akşam üstü

Verdiler itin birine bana küstü

Dedim dilim yok param iç yaram

Dedi canı verdim  almazsan haram

Sormadım kim öğretti bize ayrılığı

Dedi en çok para hayırlı evlat anaya babaya

Genç iken aşık olmak kolay çocuğa

Çürüdü nejla iri hamdi’nin koynunda

Bıraktı süt memelerini erik ağacında

Sormadım eriğe dişim neden kamaşır hala

Nejla öptüm yanağın hala burnumda

Duman elimde sigarada ip ağaçta

Kalsın ak göğsünde bulutların

Sen getir sıcağını unutmuş koynuma

Sormadım el dururken ip neden sarıldı boynuna

Erik toplar gözlerim baharın memelerinden

Gideyim nejla’yı hatırlayıp delirmeden

Nevruz mu unutmuşum bilmeden

Nejla gitmiş beni bırakmış görmeden

Sardım; dirseklerimi tutar ellerim

Nefesini duyar kulağım

Nejla’ya

Erik ağacına

Bir de bana

dokunmayın ağlayayım

30 11 2004  “ Adamına sevdalar “

.', '. Sıcaktı o zaman yazlar Serkeş koşturmalar sürerken Gözlerimi dikmişim gün ortası Nejla ve elbisesine takılmışlar Soramadım kimin memesi da...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ellerinin-sicak-rengi-necla-erik-agaci-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-adnan-efe-ozkan-11yyf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yamalı uykuların rüyasısın...

Geceyi dar eden sesizliğin,

Sevdayı var eden güzelliğinle.

Sen bölünmüş hayatın anlamısın...

Olmayınca yerine konulmayan,

Olunca tadına doyulmayan.

Sen sevdaların beyazısın....

Ağlatılınca kirlenmeyen,

Sevilince şımarmayan.', 'Sen yamalı uykuların rüyasısın... Geceyi dar eden sesizliğin, Sevdayı var eden güzelliğinle. Sen bölünmüş hayatın anlamısın... Olmayınca yer...', ARRAY['Türk Edebiyatı','Şiir','Adnan Efe Özkan']::text[], 8.5, '{"poet":"Adnan Efe Özkan","poet_slug":"adnan-efe-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-593-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri Sevdam', 'gri-sevdam-adnan-efe-ozkan-zg59v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan kızgınlığım da sevgimden.

Seven kızarmı deme! 

Siyahta sevdanın renginden.

Bakma benim gri rengime,

Sen beyazsın, hem de kardan,

Eridinde düştün elime.

Sensiz yürürken bu yoldan,

Ölmek var ya tek kelime.

Sen dünyamsın yalnız benim,

Sana kurdum umutları.

Bembeyaz güzel bir gelin,

Duvak yaptım yıldızları.', 'Sana olan kızgınlığım da sevgimden. Seven kızarmı deme!  Siyahta sevdanın renginden. Bakma benim gri rengime, Sen beyazsın, hem de kardan, E...', ARRAY['Türk Edebiyatı','Şiir','Adnan Efe Özkan']::text[], 8.5, '{"poet":"Adnan Efe Özkan","poet_slug":"adnan-efe-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gri-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasip eyle Allah’ım', 'nasip-eyle-allah-im-mikdat-bal-qawcr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya Rab affeyle bizi

Cemi-i cümlemizi

Yoluna gelmemizi

Nasip eyle Allah’ım

Hidayete ermeyi

Hakikatı görmeyi

Cennetine girmeyi

Nasip eyle Allah’ım

Sana bir yol bulmayı

Hidayette kalmayı

Hayırlı kul olmayı

Nasip eyle Allah’ım

Sevdiklerini sevmek

Yerdiklerini yermek

Övdüklerini övmek

Nasip eyle Allah’ım

Gönlümüzü açmayı

Düşmanlıktan kaçmayı

Kardeşliği seçmeyi

Nasip eyle Allah’ım

Terkedip uykuları

Bize hoş duyguları

Hürmet ve saygıları

Nasip eyle Allah’ım

Senin yolundan gider

Adaletle hukmeder

Türk’e yakışan Lider

Nasip eyle Allah’ım', 'Ya Rab affeyle bizi Cemi-i cümlemizi Yoluna gelmemizi Nasip eyle Allah’ım Hidayete ermeyi Hakikatı görmeyi Cennetine girmeyi Nasip eyle Alla...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nasip-eyle-allah-im-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum', 'umudum-adnan-efe-ozkan-72z65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük bir denizde koca fırtına,

Görünmez gece, kara bir deniz.

Kocaman dalgalar çöktü sırtıma,

Korkan bir yürek, soluk bir beniz.

Sen benim umudum, deniz fenerim.

Kıyıda bekleyen güzel yolcumsun.

Sen benim yolumda garip kaderim,

Sen tutunduğum tek umudumsun.

Boğulmakta var, sana varmakta.

Bu koca denizde belirsiz kader.

Ölmenin tek yolu sana vanmakta,

Bu borcu bu gönül nasılsa öder.

Bir balık olupta sana yüzmek var,

Kaderin ağına düşüp ölmekte.

Bu koca deniz yüreğime dar,

Mutluluğun yolu sana gelmekte.', 'Küçük bir denizde koca fırtına, Görünmez gece, kara bir deniz. Kocaman dalgalar çöktü sırtıma, Korkan bir yürek, soluk bir beniz. Sen benim ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Efe Özkan']::text[], 8.5, '{"poet":"Adnan Efe Özkan","poet_slug":"adnan-efe-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umudum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni görmüş', 'seni-gormus-halil-colak-d5qrb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül niçin ağlarsın hazin, hazin yakarsın yüreğimi

Hasret kaldın çoktandır görmediğin gönlünün çiçeğini

Ey gözüm bahar bulutu gibi ağlar hem açılırsın

İkinci baharın güzelliği için mi hep bana nazlanırsın

Bitmez tükenmez aşkın için gözlerimden akan yaşım

En katı kalpler, tunçtan olsaydı erirdi kır çiçeğim

Bırak yüzünün çiçek bahçesine sümbül sacını sacım

Elerimi beline dolasam cihana değer bil benim için

O güzelliğine ne canlar, yanmış, kavrulmuş durmuş

Mecnun ki aşkı Leyla için kendini çöllerde bulmuş

O buğulu gözlerinde beni can damarımdan vurmuş

O an zaman işlemez olmuş, bu can o an seni görmüş

Halil Çolak25.7,2005 Ankara', 'Gönül niçin ağlarsın hazin, hazin yakarsın yüreğimi Hasret kaldın çoktandır görmediğin gönlünün çiçeğini Ey gözüm bahar bulutu gibi ağlar he...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-gormus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmüyorsun beni', 'gormuyorsun-beni-halil-colak-xgjo0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün düşündüm durdum seni

Derinlemesine

Yansızlığımın çaresi sen misin diye 

Saatlerce bekledim yazarsın diye

Unutmuşsun belli beni

Atmışsın aklının hatırlanmayan köşesine

Boşu boşuna beklemişim 

Sabahtan akşama kadar seni

Belki hatırlar beni....

Çünkü unutmuşsun beni

Hatırlamadın ki arayasın beni

Yıldızındım hani ben senin

Hani ben senin için özeldim

Güneş doğdu sana

Başka diyardan, başka ufuktan

Güneş doğduğu zaman yıldızlar 

Kaybolur görünmez güneşin ışığından

Güneşin parlak Işıkları

Kamaştırıyor,

Güzel yeşil gözlerini.

Düşündüm onun için, görmüyorsun

Hatırlamıyorsun beni

Buna rağmen

Seni çok seviyorum seni

Sen görmüyor yorsun

Duymuyorsun beni........

Halil Çolak 25.7.2005 Ankara', 'Dün düşündüm durdum seni Derinlemesine Yansızlığımın çaresi sen misin diye  Saatlerce bekledim yazarsın diye Unutmuşsun belli beni Atmışsın ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gormuyorsun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzettim', 'farzettim-adnan-efe-ozkan-8y4us', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farzettim, benim olmuşsun...

Fakatlarla,belkilerle,olmazlarla.

Farzettim, bana çıkmışsın...

Fallarla,rüyalarla,oyunlarla.

Farzettim, hep seni sevsem...

Fimlerle,şarkılarla,şiirlerle.

Farzettim,sani içmişim...

Fasıllarla,türkülerle,ezgilerle.

Farzettim,gece yanımdasın...

Farketmeden,gizlice,delice.

Farzettim...hep ben mi? 

Farzet ki... sende olsun', 'Farzettim, benim olmuşsun... Fakatlarla,belkilerle,olmazlarla. Farzettim, bana çıkmışsın... Fallarla,rüyalarla,oyunlarla. Farzettim, hep sen...', ARRAY['Türk Edebiyatı','Şiir','Adnan Efe Özkan']::text[], 8.5, '{"poet":"Adnan Efe Özkan","poet_slug":"adnan-efe-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/farzettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Köşe Senindir Sokaklarımda', 'her-kose-senindir-sokaklarimda-murat-avci-ozan-wfanw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '​Sanma ki sükûtum unuttuğumdan,

Bir içli bestesin dudaklarımda.

Hayalin, hatıran çıkmaz aklımdan,

Süzülen damlasın yanaklarımda.

​

En uzak yerlerin ötesindesin,

Gönlümün en kuytu köşesindesin.

Unutmak, aklımın neresindesin?

Adındır çınlayan kulaklarımda.

​

Zehrini kanıma katmış olsan da,

Yanarım aklıma düştüğün anda.

Bulamam cismimi hiçbir mekânda,

Her köşe senindir sokaklarımda.', '​Sanma ki sükûtum unuttuğumdan, Bir içli bestesin dudaklarımda. Hayalin, hatıran çıkmaz aklımdan, Süzülen damlasın yanaklarımda. ​ En uzak y...', ARRAY['Türk Edebiyatı','Şiir','Murat Avcı Ozan']::text[], 8.5, '{"poet":"Murat Avcı Ozan","poet_slug":"murat-avci-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/her-kose-senindir-sokaklarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gecem', 'her-gecem-adnan-efe-ozkan-xyuzx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gecede haram oldu...

Uyku haram,sevgi haram,şiir haram.

Zaten sen olmayınca,

Neyle iyi oldu aram? 

Bu gecede bir duvar var,

Taş duvar,lanet duvar,soğuk duvar.

Önümde bir gece var,

Uzun,karanlık ama dar.

Sen uykuda, rüyalarda,

Nasıl uyku,hangi rüya ve nerede? 

Ben burdayım kuytularda,

Ağır, taş gibi gecede.

Sırtıma vurdum geceyi,

Hain gece,kara gece,katil gece.

Sen yaptım her heceyi

Duysan bilirdin her gece', 'Bu gecede haram oldu... Uyku haram,sevgi haram,şiir haram. Zaten sen olmayınca, Neyle iyi oldu aram?  Bu gecede bir duvar var, Taş duvar,lan...', ARRAY['Türk Edebiyatı','Şiir','Adnan Efe Özkan']::text[], 8.5, '{"poet":"Adnan Efe Özkan","poet_slug":"adnan-efe-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-gecem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba Demektense...', 'acaba-demektense-cem-karadeniz-k3ov5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görüyorsun ya

Günler bitiveriyor öylesi anılarla,

Bitimsiz sanılan saniyeler

Boş gözlerin umutlarını süpürüveriyor durmaksızın; 

Özlenen dudaklar, kordan buzullarca yangın

Şakaklarımdan kan kırmızı özlem damlıyor yine,

Bakışlarım ürkek gecenin kanalığında

İstediğimse umut yakılası gecelerde…

İmgesel bir doğru istesem senden

Ellerinle yakar mısın gözlerim,

Dudaklarımı kemirir mi ölgün gülümseyişler

Bitimsiz öpücüklerle uğurlasan düşlerini

İncitmez mi yalnızlığını; 

Belki evet demek istersin de söyleyemezsin,

Yılların üzerinden anıların göz kırar gibidir çünkü…

İşte zil çalıyor

Arka kapıda şüpheler pusuda; 

Acaba demektense?', 'Görüyorsun ya Günler bitiveriyor öylesi anılarla, Bitimsiz sanılan saniyeler Boş gözlerin umutlarını süpürüveriyor durmaksızın;  Özlenen dud...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zamanda-acaba-demektense-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk yahut Ayrılık', 'ask-yahut-ayrilik-sener-ozdemir-1qsoa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk yorgunu bir kalbim var,

Bir enkaz da sen bırak zararı yok...', 'Aşk yorgunu bir kalbim var, Bir enkaz da sen bırak zararı yok......', ARRAY['Türk Edebiyatı','Şiir','Şener Özdemir']::text[], 8.5, '{"poet":"Şener Özdemir","poet_slug":"sener-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ask-yahut-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk-i Sevda', 'terk-i-sevda-murat-avci-ozan-rzk78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '​Cisminin zerresi kalmadı bende,

İsmine söylesen o da terk etse.

Biçare yıllardır tozlu albümde,

Resmine söylesen o da terk etse.

​

​Hicranın elinden bağrım delindi,

Gençliğim tükendi, ömür silindi.

O vefasız mazi sanki dün gibi,

Aşkına söylesen o da terk etse.

​

Ne bir selamın var ne bir haberin,

İçimde kor gibi sönmez eserin.

Yüreğe kazınmış izleri derin,

Yadına söylesen o da terk etse.

​

Hayalin sinmiş de her bir köşeye,

Düşmandır bu gönül artık neşeye.

Mahkûm etti beni dertle şişeye,

Efkara söylesen o da terk etse.

​Kelamın edilmez oldu dilimde,

Mızrabın kırıldı gönül telimde.

Ne çare acıyor hâla içimde,

Derdine söylesen o da terk etse.', '​Cisminin zerresi kalmadı bende, İsmine söylesen o da terk etse. Biçare yıllardır tozlu albümde, Resmine söylesen o da terk etse. ​ ​Hicranı...', ARRAY['Türk Edebiyatı','Şiir','Murat Avcı Ozan']::text[], 8.5, '{"poet":"Murat Avcı Ozan","poet_slug":"murat-avci-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cisminin-zerresi-kalmadi-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Gün Doğuyor...', 'yeni-bir-gun-doguyor-cem-karadeniz-qn2ms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni bir gün doğuyor

Masmavi bir ışık seli akıyor gökyüzünden

Sapsarı buğday tarlalarını dolaşıp

Kan kırmızı gelinciklerle kucaklaşıyor

Ansızın bir ses

Bir tatlı fısıltı yankılanıyor doruklarda

Ask diyor, sevgi diyor yankılar arasından

Usulca çiçek açıyor ağaçlar

Yapraklarını çeviriyorlar gökyüzüne

Arılar vızıl vızıl

Kuşlar 

Kanat çırpınışlarıyla yarıyor gökyüzünü 

Uykusamış bir çoban çınarın gölgesinde

Ve 

Sen birtanem, oradasın görüyorum

Kollarını açmış bakıyorsun

Sevgi dolu bir bakış gözlerinde

Canımın için bir gülümseyiş dudaklarında

Ve 

Yıllar yılı bitmeyen bir özlem

Olduğu halde yüreğinde…', 'Yeni bir gün doğuyor Masmavi bir ışık seli akıyor gökyüzünden Sapsarı buğday tarlalarını dolaşıp Kan kırmızı gelinciklerle kucaklaşıyor Ansı...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yeni-bir-gun-doguyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldür Felek...', 'guldur-felek-mehmet-demir-atmali-258es', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güldür felek, sen güldür; 

Alemi bana güldür...

Dostun beni inciten; 

Taşı değil, bir Gül''dür...

Hallac-ı Mansurca''dan; 

Enel-Hak diyen Gül''dür...

Beni Hakk''a götüren; 

Renklerin Raksı Gül''dür...

Çiçeklerin içinde; 

En nadidesi Gül''dür...

Bülbül''ün tek tutkusu; 

Nazlı, dikenli Gül''dür...

Beni Sevda''ya salan; 

Yeşil gözlü bir Gül''dür...

Benim gönlümü çalan; 

Hırsızcıktan bir Gül''dür...

19.9.2003', 'Güldür felek, sen güldür;  Alemi bana güldür... Dostun beni inciten;  Taşı değil, bir Gül''dür... Hallac-ı Mansurca''dan;  Enel-Hak diyen Gül''...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guldur-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-cem-karadeniz-byo53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi anlamadan önce

Sevginin ne olduğunu ancak

Hissetmeden anlatabilirdim

Şimdi hissediyorum ama

Anlatamıyorum sevmek nedir diye…

Cem K.

Kasım 1993

Ankara', 'Seni sevdiğimi anlamadan önce Sevginin ne olduğunu ancak Hissetmeden anlatabilirdim Şimdi hissediyorum ama Anlatamıyorum sevmek nedir diye… ...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olmuyor-anlatamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Avuntum', 'son-avuntum-cem-karadeniz-cm0o9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir damla gözyaşı ver bana

Sana susadığımda içeyim yudum yudum

Bir parça umut ver bana gözlerinden

Üşüdüğümde yokluğunda içimi ısıtayım

Ve bir tutam umut ver bana bir tanem

Yokluğunda bir gün dönecek deyip avunayım

(10.09.99 - 04.30 & ankara)', 'Bir damla gözyaşı ver bana Sana susadığımda içeyim yudum yudum Bir parça umut ver bana gözlerinden Üşüdüğümde yokluğunda içimi ısıtayım Ve b...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-avuntum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-cem-karadeniz-zm42a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neler neler geçiyor aklımdan

Bitimsiz saniyelerce uzayan yalnızlığım

Kederli türküsünü mırıldanırken

Issız koylarda kayıp gemiler misali

Yüreğimin loş ışıklı yollarında

Küskün bakışlarımı seyrediyorum…

Düşüncelerim sen dolu maviliklerde

Eski bir Akdeniz masalı düşlüyor

Dalgalı yürek sularım

Bir o yana bir bu yana

Alevlenirken ruhumun tükenmiş ateşi yeniden

Sana dokunmak geçiyor aklımın bir ucundan

Bir öpücük kondurmak yumuşak alnına; 

Kelimeler dikenli sanki

Dudaklarımı zorluyor sinsice

Oysa neler neler geçiyor aklımdan

Bir bilsen…

(ankara 1994)', 'Neler neler geçiyor aklımdan Bitimsiz saniyelerce uzayan yalnızlığım Kederli türküsünü mırıldanırken Issız koylarda kayıp gemiler misali Yür...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-bilsen-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Başladı Bir Öykü', 'boyle-basladi-bir-oyku-cem-karadeniz-svv7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgârlar savuruyor bedenimi

En uzak iklimlere

Yıllanmış bir şişe şarap

Hüznünü yansıtıyor yılgın anıların

Alnıma düşen bir damla ıslaklık

Nihavent bir aşkın ilk notası sanki

Kendine esir olmuş

Issız bir başlangıç tınısı

Lambalar ıssız bir mum ışığı aksinde

Islak ıslak kaybolurken

Nedensiz bir gülümseme sarıyor çehremi

Çakmak çakmak parlıyor gözbebeklerim

Ayışığıyla kol kola

Raks eden bir yıldız tanesi

Sessizliğe buruk bir veda ile 

Laf ebesi bir şiir resminde

Aksediyor sessizce

Nihayetsiz bir sen sıcaklığında…

(15/06/99 05:45 & cıck park - antalya)', 'Rüzgârlar savuruyor bedenimi En uzak iklimlere Yıllanmış bir şişe şarap Hüznünü yansıtıyor yılgın anıların Alnıma düşen bir damla ıslaklık N...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/boyle-basladi-bir-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-cem-karadeniz-azvky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanguruları düşündün mü hiç? 

Zıplamayı dans bilirler bozkırlarda,

Düşündün mü hiç geyikleri şafakta? 

Ürkek gözlerle bakarlar suya

Güzel gözler görseler de karşılarında,

Düştü mü gorillerin iç çekişi aklına? 

Mendebur bir sırıtıştan umulan medet

Kenef bakışlı damakların gergin küskünlüğü.

Bunları düşündüm ben yokluğunda

Yokluğunda

Beklerken dönüşünü gözlerim aynalarda,

Gelmedin…

Gel! 

Gel artık gül yüzlü dana

Hüznümün öküzsel avuntusu gel hadi…

Parmaklanmış bir sonbahar hecesi gözlüm,

Tavşanımsı korkularımın havuçsal arayışı

Kulaksızlığa özlem

Gel! 

(03.02.99 - 06:30 & Cıck - Çamyuva)', 'Kanguruları düşündün mü hiç?  Zıplamayı dans bilirler bozkırlarda, Düşündün mü hiç geyikleri şafakta?  Ürkek gözlerle bakarlar suya Güzel gö...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğimize', 'gelecegimize-cem-karadeniz-5np5a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece

Bembeyaz bir gelecek anlattı yine

Gözlerinden yüreğime; 

Kanatlanıp da gökyüzünü yırtan kelebekler kokladı

Mutluluk tadında avuçlarını,

Yüreğin tutkun bir Akdeniz masalına

Ilık ılık okşadı coşkun yarınını aşkın

Ben ise güneşi yakaladım teninde

Işığının etrafında bir pervane

Ya da

Bir at sineği ısrarında mahkûm geleceğimize…

(06/09/99 kemer antalya)', 'Gece Bembeyaz bir gelecek anlattı yine Gözlerinden yüreğime;  Kanatlanıp da gökyüzünü yırtan kelebekler kokladı Mutluluk tadında avuçlarını,...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelecegimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanıyorum', 'i-naniyorum-cem-karadeniz-woim2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özleyişlerin sıcaklığı inde 

Bir merhaba diyebilmek,

Umutların gölgesinde

Bir öpücük kondurmak alnına sevgilinin,

Göz alabildiğince yakın

Göz alabildiğince candan

Bir aydınlığı sığınmak; 

Ölgün gülümseyişlere son veren

Bitkin gözlere de hoşça kal diyebilmek

Ne zor..

Bitimsiz duyguların 

Betimsel analizini yapacak

Ya da 

İmgesel yalnızlığımı anlatacak değilim

Oysa ne çok isterdim gözlerini kucağımda

İnanılmaza inanmak seninle…

(ankara 1995)', 'Özleyişlerin sıcaklığı inde  Bir merhaba diyebilmek, Umutların gölgesinde Bir öpücük kondurmak alnına sevgilinin, Göz alabildiğince yakın Gö...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/inaniyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odam', 'odam-ulya-erkman-7022t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derbeder ruhumun

   Derbeder odasi

   Icimin aynasi 

   Kucuk odam

   Yattigim oturdugum

   Yedigim yemedigim 

   Guldugum agladigim

   Kucuk odam

   Gomulmus sanki

   Butun omrum icine

   Dile gelmis cocukluk

   Genclik dolu umitle

   Sonra gelir kaderin

   Sira sira darbesi

   Olur gecen gunlerim

   Istirap hengamesi



   Yasandikca bir bir 

   Omrumun hep caglari

   Nasil dememki bu oda 

   Hatiralar mezari

   Gomerken her an

   Bir hatirayi buraya

   Tek cicek diken yok

   Bu kimsesiz mezara

   Bir omrun olusu

   Nasil sigarsa topraga

   Sigdi benimde hatiram

   Bu avuc ici odaya

   Ey mechul dost

   Kimsen birgun yatacak

   Benim kucuk odamda

   Birsey var sana yapacak

   yapayanliz kalinca

   Gomuludur gozlerim

   Dort duvara tavana

   Mihlidir bir hickirik

   Odandaki sukuna

   Umit isigi ile canlanan

   Golgecikler sezersen

   Ve butun bunlarla se

   Artik beni seversen

   Yaparmisin bilmemki

   Soylesem istegimi

   Koyarmisinki vazoma

   Sevdigim cicegimi? 

   Sonra bir an durupta

   Dermisin su sozumu

   Bu kucucuk odada 

   butun bir omur gomulu', 'Derbeder ruhumun    Derbeder odasi    Icimin aynasi     Kucuk odam    Yattigim oturdugum    Yedigim yemedigim     Guldugum agladigim    Kucu...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/odam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün Gelecek', 'o-gun-gelecek-cem-karadeniz-8u6g9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitimsiz bekleyişlerin

Martısal analizini yapacak

Ya da

Özleyişlerin yitik sihrini

Yeniden canlandıracak değilim

Gel gör ki yaşam bir kartopu sanki

Hiç ummadığın yerde karşında 

Ve bir anda kayıp soğuk güneş altında,

Öylesi birkaç dize

Gri sabahları müjdeler bazen

Uykusamış gözler yılgın

Bazen kahkahalar özümsenir

Samimi dokunuşlar

Nefreti çağrıştırır belki

Yalnız bir bebek eli gibi

Islak ve soğuktur geceler

Karmaşalarla günaydın dersin 

Betimsel anılara

Belki de son kez; 

Oysa

Bekleyebilmek olsaydı sonunda 

Bembeyaz bir aydınlık seli gibi

Hiç karamazdı umutlar

Özleyişlerin yitik sihri merhaba derdi

Bir kez daha

Ve yılların yanı başında bir söğüt

Serin serin öpüverirdi alnından 

Mutlu günler sevgi dolu dokunuşlar gibi…

(kadıköy 96)', 'Bitimsiz bekleyişlerin Martısal analizini yapacak Ya da Özleyişlerin yitik sihrini Yeniden canlandıracak değilim Gel gör ki yaşam bir kartop...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/o-gun-gelecek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dünya Ki', 'bir-dunya-ki-mehmet-ali-kalkan-z2g35', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gitmeli birlik izinde,

Tok olan bilmeli açı.

Senlik benlik denizinde,

Atmak gerekmez kulacı.

Sabır yumağını öre,

Hak''tan ayrı olmaz töre,

Ameller niyete göre,

Mutlak almalı ilacı.

Doğru değil dost zemmetmek,

Dost görevi himmet etmek,

İnanmışa gıybet etmek,

Ölü etinden de acı.

Ha hatunu,ha da eri,

Tarağın dişi her biri,

Ehl-i takva iman eri,

Hak için olur duacı.

İlahiyle,nefesiyle,

Saba saba bestesiyle,

Candan içre ''''Hu'''' sesiyle,

Taşımalı hiçlik tacı.

Bir dünya ki hapisi yok,

Bir dünyaki kapısı yok,

Bir dünya ki tapusu yok,

Burada herkes kiracı.

Dua ile,zikir ile,

Nimetlere şükür ile,

''''Her dem taze fikir'''' ile,

Büyüsün gönül ağacı.', 'Gitmeli birlik izinde, Tok olan bilmeli açı. Senlik benlik denizinde, Atmak gerekmez kulacı. Sabır yumağını öre, Hak''tan ayrı olmaz töre, Am...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-dunya-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orman', 'orman-cem-karadeniz-jrzsl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '* ortaokul ikinci sınıfta yazdığım ilk şiir

Bu dünyanın güzeli

Gökle denize eş olanı

Nedir diye sorarsa biri bana

Hemen “Orman! ” derim ona…

Yemyeşil bir örtüdür

Bin bir çiçek bin bir kuş

Her şey güzeldir orada

Benim güzel ormanım...

(1987 FİKİRTEPE)', '* ortaokul ikinci sınıfta yazdığım ilk şiir Bu dünyanın güzeli Gökle denize eş olanı Nedir diye sorarsa biri bana Hemen “Orman! ” derim ona…...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/orman-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsal Arayış', 'umutsal-arayis-cem-karadeniz-9448g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı kucaklayan kollar günlerce

Gün gelir koparıverir umudun zincirlerini

Dedim ya umutlar vardır tozpembe

Umutlar vardır kararmış, kapkara; 

Başıboş saniyeler kürek çekercesine inatçı

Noktasal hedeflere koşarcasına inançlı

Ve yılmamacasına savaşçı sevgi dolu günler adına 

Başı dik pırıltılı gözbebekleri 

Bitmemecesine uzayan yollarca 	ulaşılmaz sevgiler

Kimi zaman avuçlarındaymışçasına yaksa da tenini

Yüreğini kuşatsa da yangın yangın duygular

Yine de sürmeli mücadele

Mavzerleri kucaklar gibi sert kimi zaman

Kimi zaman zarif ve yumuşak

Menekşelerine su verircesine

Ama bitimsiz daima 

Sonu gelmeyen dizeler gibi...

(ankara 1996)', 'Yalnızlığı kucaklayan kollar günlerce Gün gelir koparıverir umudun zincirlerini Dedim ya umutlar vardır tozpembe Umutlar vardır kararmış, ka...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umutsal-arayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Bir Gece Ninnisi', 'yalniz-bir-gece-ninnisi-cem-karadeniz-n0s8q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle özlemiştim ki sesini

Bir çift kahverengi kanatla uçtum,

Aydınlığın ötesini karalık sanırdım

Yastığının gölgesinde pırıltıyı buldum…

	

(21.07.99 - 03.20 & Cıck park kemer)', 'Öyle özlemiştim ki sesini Bir çift kahverengi kanatla uçtum, Aydınlığın ötesini karalık sanırdım Yastığının gölgesinde pırıltıyı buldum… 	 (...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalniz-bir-gece-ninnisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam...Anam! ! !', 'anam-anam-mehmet-demir-atmali-5jepf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni terk edip de gittin,

Sen ölünce, ben de bittim.

Senin öğüdünü tuttum...

Gümanına sığınırım....

Sana Ana diyemedim,

Gül kokuna doyamadım,

Mezarına koyamadım...

Amanına sığınırım...

Borana tutulduğumda,

Kenara atıldığımda,

Kalleşçe satıldığımda; 

Limanına sığınırım...

Özledim seni kabrinde,

Eğer var ise kaderde,

Kavuşur belki Mahşer''de; 

Rahmanına sığınırım...

Yetim idin, gün görmedin...

Bir gün murada ermedin,

Mehmed''ini hiç yormadın; 

İmanına sığınırım....

1.1.1999', 'Beni terk edip de gittin, Sen ölünce, ben de bittim. Senin öğüdünü tuttum... Gümanına sığınırım.... Sana Ana diyemedim, Gül kokuna doyamadım...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anam-anam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-cem-karadeniz-cxcfd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '*yasama elele kosanlara...

Gökyüzüne akan bir yıldız

Ve ışıltılı bir çığlık telaşıdır birlikte yaşam

Ve dostluk damlacıklarıyla bezenmiş

Sadık bir umut ağacı

Ve sımsıkı kenetli 

Bir yuva saadeti gizliyse yüreklerde

Güzeldir yaşam

(Ekim 2000 Üsküdar)', '*yasama elele kosanlara... Gökyüzüne akan bir yıldız Ve ışıltılı bir çığlık telaşıdır birlikte yaşam Ve dostluk damlacıklarıyla bezenmiş Sad...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasamak-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son şövaliye', 'son-sovaliye-sair-yatakkusu-pabc7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski kitaplardaki şövalye gibi

kimse onu almasın diye,

altımda,

kanayan yüreğimin altında,

daha dün kalçamda sallanan

yüz defa şanlı olan kılıcımı

yatırdım.

Borum, ne kraliçe ne kral

ne de bir saat evvel ölen, yok olan

kardeşlerimi çağırmaz artık.

Kılıç, kırık boruyla

bende kalan herşey.

Şimdiyse,

eskiden kel ayılarla

kahverengi akbabalarla

kaplı olan tepelerden

akar Selçuk askerler

aşkımızın çevreyolunda

zalim arabalar gibi.', 'Eski kitaplardaki şövalye gibi kimse onu almasın diye, altımda, kanayan yüreğimin altında, daha dün kalçamda sallanan yüz defa şanlı olan kı...', ARRAY['Türk Edebiyatı','Şiir','Şair Yatakkuşu']::text[], 8.5, '{"poet":"Şair Yatakkuşu","poet_slug":"sair-yatakkusu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/son-sovaliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-mehmet-ali-kalkan-2jqjw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başlamak söylemek ile,

Selam kelamdan öncedir.

Hak ilmiyle amel eyle,

Kalem kılıçtan incedir.

Dün bebektin şimdi nesin? 

Bir bir azalır nefesin,

İman ile besleyesin,

Fıtrat su bekler goncadır.

El ayıbıyla uğraşma,

Doğrudan eğriye koşma,

Ya Hak söyle ya konuşma,

İnandığın kalbincedir.

Daneli eyle harmanı,

Tabip''te ara dermanı,

Gönülün alev zamanı,

Doğru odun buluncadır.

Ya şer ya Hak,yok ortası,

Alem var alem ertesi,

Ben içinde ben ötesi,

Ol ummana dalıncadır...', 'Başlamak söylemek ile, Selam kelamdan öncedir. Hak ilmiyle amel eyle, Kalem kılıçtan incedir. Dün bebektin şimdi nesin?  Bir bir azalır nefe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-228-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ataturk - Ne Mutlu Sana -başöğretmen', 'ataturk-ne-mutlu-sana-basogretmen-cem-karadeniz-cvrsp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce mavi gözlerin vardı

Deniz  deniz  ürperten karanlığı

Kararlı bakışların sonra

Aydınlığa yolaçan bakışların

İnadına geçerdin ötesine zamanın

Binlerce ayak sesi ardında

Artarak ilerledi seninle

Sonsuzluğa açılan kapıdan

Türkü türkü aktılar yarınlara

Destan destan yazdılar geleceği

Kanlarıyla yeşettiler bahçelerimin yurdumun

Ve,insanca yaşadılar geçmişi…

Onurun ve başkaldırının ilk notasıydın

İlk hecesiydin yurt sevgisinin

İlk seninle aralandı özgürlük kapısı

Senin sesin  rehber oldu görmez gözlere

İlk isminle merhaba dedim alfabeye

Hecelerden pisagora seninle ulaştım

Varabileceğim son noktanın aslında son nokta olmadığını öğrettin…

Yarınların karanlığını ışığınla aydınlatacak

Düşüncelerin meşalesini ellerden indirmeyeceğiz…

Ne mutlu sana! 

M. Kemal ATATÜRK

(10  Kasım 1999 taksim)', 'Önce mavi gözlerin vardı Deniz  deniz  ürperten karanlığı Kararlı bakışların sonra Aydınlığa yolaçan bakışların İnadına geçerdin ötesine zam...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ataturk-ne-mutlu-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk - 10 Kasım', 'ataturk-10-kasim-cem-karadeniz-9aw1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '10 Kasım 1938. Yüzyılların ötesinden gelen bir çığlığın, kendisini bin yıllar sonrasına taşıyacak o devasa koridora açıldığı o gün. Düşüncenin kanat takıp uçtuğu, engin bir sevda düşüyle gökyüzünün çalkalandığı o gün. O bitimsiz mavi anlatı.

Ve o 10 Kasım’ın 61 yıl sonraya yansıyan mavi ışıldayışlı gözlerindeki gerçe.

Zaman zaman dindiğim fırtınalarda, kimi gün söküldüğüm aydınlıkta, bazen de ısındığım kavgamda mavi bir ayrıntı adı yankılandıysa eğer, eğer sonsuzluğa kanat çırpan o martıya gebeyse zaman ve dudaklarda bayraklaşan O’nun adıysa eğer, demek ki her 10 Kasım’a umudu yayan her bir tören, her bir insan, her birinde taptaze bir bahar sabahı esintisince yepyeni başlangıçlar yaymış halkın dingin düşlerine ve o umut açmış düşlerin gerçeğe döndüğü anların kapısını.

Bugün 61 yıl sonra Ata’yı anarken bizce önemli olan Zübeyde Hanım’ın oğlu, vaktiyle 70/75 kilo ağırlığında ve 1.75 kadar boyunda olan ve 10 Kasım 1938’de aramızdan ayrılan bu ölümlü insanı hatırlamaktan çok O’nu göremeyen kuşakların, yüz milyonlarca Türk’ün daha yıllar boyu bağlılık duyacakları, ulusça daha yıllarca bir ışık kaynağı olarak kendisine başvurulacak olan varlık, “Ölümsüz Devlet Adamı Atatürk” ya da “Düşünceler, ilkeler, amaçlar ve inançlar için kavgalardan kurulu manevi varlık olan Atatürk” olmalıdır.

İşte bizi devlet adamı Atatürk’ün karşısına götüren gerçek budur…

Yani Atatürk Safiye Hanım’ın değil de Hamiyet Hanım’ın sesini daha çok beğenseydi, çocukluğunda karga kovalamamış, parklarda oynamış olsaydı yahut fasulye ve pilavı değil de pırasa ve baklavayı daha çok sevseydi, kısacası etten ve kemikten kurulu, çoktan ölmüş Mustafa Kemal’in tercihleri şöyle değil de böyle olsaydı, biz Atatürk’ü yine aynı ölçüde sevecektik.

Biz fizik Mustafa Kemal’in bu tercihlerini öğrenerek Atatürk’e biraz daha yaklaşmadık ve O’nu daha yakından tanımış olmadık.

Ya ne oldu? 

Uzun süren bir savaştan yaralı, yorgun ve fakir çıkmış bir milleti aydınlık yola yöneltmiş olan, yaptığı devrimler ve attığı adımlarla gelecekteki ilerleme ve gelişmenin temellerini atan ve şartlarını hazırlayan Atatürk’ü tanıdık.

10 Kasım’da hepimize düşen görev geriye dönüp bir bakmak ve dürüst ve samimi olarak nerede bulunduğumuzu görebilmektir.

61 yıldır her 10 Kasım’da söylenegelen her şeyi bir buket yapıp bizden öncekilere sunalım. Sonra bir bakalım. O buketin bıraktığı boşluğa biz neler koyabileceğiz. Bakalım o boşluğun hakkını verebilecek miyiz? 

Ebediyete akıp giden 61. yıldönümleri beklemeksizin, her yıl bir buket yapmalı arda kalanlardan ve daha büyük bir buket için kolları sıvamalıyız.

“Bugün O’nun için ne yaptım? ” sorusunu kendimize sormalı, dün, yarın ve tüm günlere yaymalıyız bu bitmez senfoninin berrak ezgisini…

O halde haydi bizi ülkemin aydınlık geleceğine götürecek yola hep birlikte çıkalım ve haydi karanlığın tabutuna bir omuz da biz verelim. Ki gün ışısın dalga dalga ki sonsuzluk aksın ılık ılık, ki koşalım haydi 10 Kasım trenine yetişelim. Acıların, yıkıntıların üzüntüsünü karanlığı garda bırakıp temiz bir geleceğe yollanalım hep birlikte.

Bir kez daha yaşayalım o ince ayırdı; 

“Ne mutlu Türk olana.” değil, “Ne Mutlu Türk’üm Diyene! ” diyelim ve öylece haykıralım karanlığın üstüne…', '10 Kasım 1938. Yüzyılların ötesinden gelen bir çığlığın, kendisini bin yıllar sonrasına taşıyacak o devasa koridora açıldığı o gün. Düşüncen...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ataturk-10-kasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şubat 14', 'subat-14-cem-karadeniz-nv4or', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1 gerçeğe

4 çığlık düştü

Şuursuzca titredi sesim

Uzun uzun dinledim

Boşluğa düşmüş

Apansız bir yıldız kaygısını.

Tutamadım sesini…

(14/02/2005 umraniye)', '1 gerçeğe 4 çığlık düştü Şuursuzca titredi sesim Uzun uzun dinledim Boşluğa düşmüş Apansız bir yıldız kaygısını. Tutamadım sesini… (14/02/20...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/subat-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Zor', 'sensizlik-zor-kadir-guler-zliuu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahilde el ele tutuşurduk.

Güneşin batışında seyrederdik durgun denizi.

Düşünürdük gelecek güzel günleri.

Hayaller kurardık, en derin duygularla.

Dalgalara inat koşuşurduk uçsuz bucaksız kumsalda.

Her defasında buse kondurdum dudaklarına.

Yorulurduk, otururduk kumlara sere serpe.

Çok hoşuma giderdi senle kumsalda oturmak.

Bakardım derin derin güzelliğine.

Alamazdım gözlerimi güzelliğinden.

Bıkmadan usanmadan hep bakardım gözlerine.

Akşamleyin çay bahçesinde seyrederdim mehtabı.

O güzel iğde ağacının altında.

Senin kokunla karışırdı iğde kokusu.

Seni solurdum her nefeste.

Çok hoşuma giderdi ay ışığında ellerini tutmak.

Hoşuma giderdi gülüşlerini duymak.

Hiç istemezdim ki gece olsun.

Yaklaşırdı ayrılık vakti her saniye.

Kaçmak isterdim senle her defasında çok uzaklara.

Her şeyden, her yerden uzak.

Sadece sen ve ben.

Ayrılık vakti gelirdi her defasında.

Bırakmak istemezdim seni ne olur sende gel! 

Ellerim ellerine kenetlenirdi hep.

Evet şimdi anlıyorum sensizlik zor.

Hem de çok ama çok zor.', 'Sahilde el ele tutuşurduk. Güneşin batışında seyrederdik durgun denizi. Düşünürdük gelecek güzel günleri. Hayaller kurardık, en derin duygul...', ARRAY['Türk Edebiyatı','Şiir','Kadir Güler']::text[], 8.5, '{"poet":"Kadir Güler","poet_slug":"kadir-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensizlik-zor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-cem-karadeniz-1qx38', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk

Ellerinde başlayan

Vakitsiz bir oynaşma hastalığı

Gizemli bir kapı

İsterik kahkahalarına tutkunun,

Liseli bir genç kızın türküsünde

İsimsiz bir gelecek tadı

Maviye tutsak umutların

(14 subat 2005 - umraniye)', 'Sonsuzluk Ellerinde başlayan Vakitsiz bir oynaşma hastalığı Gizemli bir kapı İsterik kahkahalarına tutkunun, Liseli bir genç kızın türküsünd...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgilim-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili''ye', 'sevgili-ye-cem-karadeniz-f7mwt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söylenmemiş sözler gizlenir gecede,

En soğuk iklimlerde yeşerir

Vaftiz yoksunu

Gazap çiçekleri.

İsimsiz bir öfke kaplar

Lambalar sönük

İnsansız sokakları.

Lüle lüle oynaşır saçların

Ellerin kavuşamaz aydınlığa; 

Resimlerde ışıyan

Gizli bir ürküntü doğar ellerinde

Üstüne doğar güneş,

Nedendir bilinmez bir kıpırtı

Ümit taşır karanlığa,

Nihayetsiz bir gülümseyiş

Kaplar çehreni,

Usulca göğe uzanır eller

Titrek yalnızlıklar

Loş ışıklı odalarda kalır,

Uyanır neşen yeniden

Olmaz olsun kaygılar

Lanetlenir sessizce,

Susar sevgisizlik

Uzar günler aydınlığa

Nehirlerce akar aşka...

(14 Şubat  2005 - Ümraniye)', 'Söylenmemiş sözler gizlenir gecede, En soğuk iklimlerde yeşerir Vaftiz yoksunu Gazap çiçekleri. İsimsiz bir öfke kaplar Lambalar sönük İnsan...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgili-ye-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Valentine''s Day', 'valentine-s-day-cem-karadeniz-v296b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vallahi değmedi yüreğime

Alnımın terinde ışıdı sesin

Leylak kokuşlu saçların

Esti gecede düşünceme

Nehir tadında sevda yokuşu

Tutunmuş bir yıldız geceye

Islak ıslak yağıyor gece

Nefes nefes karanlık

Ellerinde ölüyor

Dinlerken sesini sevgimin

Ay yoksunluğuna küs

Yalnızlığına inat…

(14 Şubat 2005  - Ümraniye)', 'Vallahi değmedi yüreğime Alnımın terinde ışıdı sesin Leylak kokuşlu saçların Esti gecede düşünceme Nehir tadında sevda yokuşu Tutunmuş bir y...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/valentine-s-day-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Gördüm...', 'neler-gordum-mehmet-demir-atmali-woto2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karnından konuşan Aydınlar(!)  gördüm..

Kuş Dili konuşan Maymunlar gördüm...

İki yüzlülere rahmet okutan; 

Doksandokuz yüzlü Şeytanlar gördüm...

Dansözlere taş çıkartan kıvraklar,

Zevkinden dört köşe olmuş kaypaklar,

Boynuz kulağı geçmiş dalkavuklar; 

Sırtı kitap yüklü Hayvanlar gördüm...

12.2.2002', 'Karnından konuşan Aydınlar(!)  gördüm.. Kuş Dili konuşan Maymunlar gördüm... İki yüzlülere rahmet okutan;  Doksandokuz yüzlü Şeytanlar gördü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neler-gordum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mehmet-ali-kalkan-l5wht', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zulüm,kara,dipsiz kazan,

Sevgi bin çiçek atımı.

Yaz gidende gelir hazan,

Ay dolanır gün bitimi,

Aşksız insan yavan,çorak..

          Gündün şenlik giderim de,

          Karşımdalar gece gece,

          Kördüğümler içerimde,

          Dilimdeler hece hece,

          Aşk kuşlardan bir kelaynak.

Hep pınarlar temiz,serin,

Bomboş isen tamamen dol,

''''Ya olduğun gibi görün,

Ya göründüğün gibi ol.''''

Aşk yalana karşı çatlak.

          Sonluluğun dermanında,

          Biçilecek gök ekindir,

          Çilekeşin harmanında,

          Yağmur bir acılı kindir,

          Gönül aşığa sığınak.

Eller açılanda niyaz,

Kem düşünce bizden beri,

Ötelerde kuru ayaz,

İçerisi yangın yeri,

Aşk bitmeyen billur kaynak.

           Bilinince ilahi Hak,

           Erir,biter kalmaz elem,

           Aşk  O''nadır,O''dur mutlak,

           Divandadır bütün alem,

           Bir olana aşk muhakkak...', 'Zulüm,kara,dipsiz kazan, Sevgi bin çiçek atımı. Yaz gidende gelir hazan, Ay dolanır gün bitimi, Aşksız insan yavan,çorak..           Gündün ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-401-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hedef', 'hedef-mehmet-ali-kalkan-okbns', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnanan hedefe yürür,

Hacca revan ya karınca! 

Rahmet günahı süpürür,

Yaradan''a yakarınca.

Yolundan şaşma Kitab''ın,

Sonucu var her hesabın,

Çeşit çeşit türlü kabın,

Alacağı miktarınca.

Ben dönerim dünya döner,

Şems''i bilen mum mu dener? 

Şer gözlere perde iner,

Örümcek ağa durunca.

Ve dahi tükenir takat,

Ne hırs kalır.ne de vaat,

Bu dünyaya durur saat,

Vakit eceli vurunca.

Hayat,hayatı bitirir,

Önüne Sırat getirir,

Elbette murat getirir,

Aç ruhunu doyurunca.

Türlü renge boyanırsın,

Bilir isen dayanırsın,

Uyur iken uyanırsın,

''''Rabbin kim? '''' diye sorunca.

Mükafat nefse durdadır,

Olanı hayra yordadır,

İpi tutan huzurdadır,

Yüce Divan''a varınca...', 'İnanan hedefe yürür, Hacca revan ya karınca!  Rahmet günahı süpürür, Yaradan''a yakarınca. Yolundan şaşma Kitab''ın, Sonucu var her hesabın, Ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hedef-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Toprak', 'bir-avuc-toprak-halil-kesken-5sx70', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen de herkes gibi bir avuç toprak,

Bir avuç su ve ruhtan ibaretsin.

Ama benim için o kadar farklısın ki

Gözlerindeki yangını gördükçe itfaiyeci,

Kalbindeki kavgayı gördükçe polis,

Bitip tükenmek bilmeyen sorularını duydukça; 

Öğretmen olmak istiyorum...

Toprağının verimliliğini,

Suyunun berraklığını,

Ruhunun inceliğini görüpte sana aşık olmamak,

Bu iki madde ve ruhun en iyilerini birleştirene,

Seni yaradana şükretmemek,

Ve bu güzelliğin de beni beğenmesi,

Beni sevmesi için dua etmemek elimde mi? 

Bir toprağı, bir suyu, bir de seni sevdim ölesiye

Bakma böyle konuştuğuma

Belki de sadece kendimi düşünüyorumdur...

Toprak olmasaydı aç kalır,

Su olmasaydı çok fazla yaşayamazdım.

Ama sen olmasaydın...? 

İşte o zaman ne olurdu bilemiyorum

Muhtemelen yine yaşardım ama,

toprak ve sudan ibaret ruhsuz bir çamurdan,

Bir heykelden farksız olurdum.

Ve o cansız heykeller gibi yapayalnız kalırdım.

İyi ki oradasın, iyi ki varsın ruhum...

12.04.2004', 'Sen de herkes gibi bir avuç toprak, Bir avuç su ve ruhtan ibaretsin. Ama benim için o kadar farklısın ki Gözlerindeki yangını gördükçe itfai...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-avuc-toprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastayım', 'hastayim-halil-kesken-x4bgb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz değmesin gözüne

Kıskancım ne yapayım

Bir şu canım sözüne

Bir de sana hastayım

Kapkara kirpiklere

Uyuyan bebeklere

Bir şu mavi göklere

Bir de sana hastayım

Ateş çıksın kırkbire

Panik yapma boş yere

Bir şu gonca güllere

Bir de sana hastayım

Doktorum sensin benim

Neyim var söyleyeyim

Bir seni seven kalbim

Bir de sana hastayım', 'Göz değmesin gözüne Kıskancım ne yapayım Bir şu canım sözüne Bir de sana hastayım Kapkara kirpiklere Uyuyan bebeklere Bir şu mavi göklere Bi...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hastayim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Diyorsan', 'sevdim-diyorsan-halil-kesken-cdbp9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçücük bir sorunda

Veda ettin bu aşka

Hatanı anladıysan

Af diliyorsan başka

Anladım diken gülden

Çıkmam artık sözünden

Seni canı gönülden

Sevdim diyorsan başka

Kalbimle, yüreğimle

Hem de tüm benliğimle

Ben kendi isteğimle

Geldim diyorsan başka

Yaşamda ve ölümde

Biriz artık her demde

Maziyi bir kalemde

Sildim diyorsan başka

11.07.2003', 'Küçücük bir sorunda Veda ettin bu aşka Hatanı anladıysan Af diliyorsan başka Anladım diken gülden Çıkmam artık sözünden Seni canı gönülden S...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdim-diyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Damlacık', 'son-damlacik-halil-kesken-z055u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlarken görmüşsün beni dün akşam

İnan ki o yaşlar yalancıktandı

Ağlıyor olsam da sevinme buna

Gözümden damlayan Son Damlacıktı

Ardıma bakmadan çeker giderim

Ben yalnız bir defa veda ederim

İçimdeki ateş küllenmesede

Sanma ki bu aşka geri dönerim

Bir daha ağlamam senin arkandan

Sana olan sevgim bu kadarcıktı

Şimdiye kadar hep ağlıyordum ya

bu sefer damlayan Son Damlacıktı

Yolumuz ayrıydı yıllar öncesi

Biz birbirimizi unutmalıydık

Vuralım bu aşka en son darbeyi

Kurusun gözümdeki bu Son DamlacıK', 'Ağlarken görmüşsün beni dün akşam İnan ki o yaşlar yalancıktandı Ağlıyor olsam da sevinme buna Gözümden damlayan Son Damlacıktı Ardıma bakma...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-damlacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-halil-kesken-u909q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her zaman birlikte sevgilim diye

Söz vermiştin bana demek boş yere

Ayrılmak ne demek diyordun oysa

Unutmuş gibiydin düğün gününde

Söyle mutlumusun bu hayatında

Hiç gurur duydun mu yaptıklarınla

Şimdi aşkımızın hazin sonuna

İster gül sevgilim, istersen ağla

En kütü günümdü ömrüm boyunca

Başkasının olup gitmiştin o gün

Çiçeğini bana attıktan sonra

Darısı başına demiştin o gün

O çiçeğin hala duruyor bende

Arada bir bakıp kahrediyorum

Benim sonum olan düğün gününden

Hatıradır diye hep saklıyorum

19.12.2001', 'Her zaman birlikte sevgilim diye Söz vermiştin bana demek boş yere Ayrılmak ne demek diyordun oysa Unutmuş gibiydin düğün gününde Söyle mutl...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-gun-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamcıya', 'aksamciya-halil-kesken-zwpdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine aynı masa aynı meyhane

Almışsın yerini kendi halince

Bir de o müziği koysalar teybe

Bizim akşamcının değme keyfine

Devam et akşamcı, afiyet olsun

Yeter ki senin canın sağolsun

Bir de şarkı tuttur kendi kendine

Benim için de iç, iç şerefine

Mangalda kül bırakmaz nara atarsa

Mezeler yetişmez havasındaysa

Hele muhabbetin ortasındaysa

Bizim akşamcının değme keyfine', 'Yine aynı masa aynı meyhane Almışsın yerini kendi halince Bir de o müziği koysalar teybe Bizim akşamcının değme keyfine Devam et akşamcı, af...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamciya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Çek', 'aci-cek-halil-kesken-eba2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendin yaşayıp ta gör

İşte bak sana gerçek

Sevip sevilme nankör

Benim gibi acı çek

Aşka susa, dön çöle

Kapımda ol bir köle

Özür dile, af dile

Benim gibi acı çek

Unutama her gün iç

Geriye kalsın bir hiç

Nefret ektin, hasret biç

Benim gibi acı çek', 'Kendin yaşayıp ta gör İşte bak sana gerçek Sevip sevilme nankör Benim gibi acı çek Aşka susa, dön çöle Kapımda ol bir köle Özür dile, af dil...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aci-cek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zevk Verecekse', 'zevk-verecekse-halil-kesken-uwy3o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın tat vermedi deyip gidersin

Göm beni tarihe tat verecekse

Ölene dek hayatından silersin

Ruhun muradına tam erecekse

Kırdığın kalemdi sevmedim sözün

Boynuma dolandı oynadım sözün

Şimdi açık olsun her iki gözün

İdamımı görmek zevk verecekse

Ayrılık şarapsa al şişeden iç

Çık aşk pazarına, değerini biç

Bir daha geriye dönüp bakma hiç

Bir tek kişi benden çok sevecekse', 'Aşkın tat vermedi deyip gidersin Göm beni tarihe tat verecekse Ölene dek hayatından silersin Ruhun muradına tam erecekse Kırdığın kalemdi se...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zevk-verecekse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söze ve Göze Doğru', 'soze-ve-goze-dogru-sahin-yenilmez-6pd7x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söze güvenirken yalancı dudaklarda

Yalanları sıralar bazen ardı ardına

Suskunluğu tutar kendi dilimizin,

Karanlığa taşırken hayallerimizi

Evrenselleşiyor artık umutlarımız

Düşlerimiz hep uzak diyarlarda.

Göze güvenirken yalancı bakışlarda

Kör oluruz bir anda

Korkaklığı tutar kendi gözlerimizin

Nereye baksak tuzak,

Resimlere taşırken hayallerimizi

Biz hep farklı açıdan bakarak

Kendimize çekeriz tüm kötülükleri.

Söze ve göze doğru uzanırken düşlerimiz

Boşluğa düşeriz bir anda

Bazen aklımıza gelmiyor değil nasıl öleceğimiz

Bir şeyi bilmeden yaşarken dünyada.', 'Söze güvenirken yalancı dudaklarda Yalanları sıralar bazen ardı ardına Suskunluğu tutar kendi dilimizin, Karanlığa taşırken hayallerimizi Ev...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soze-ve-goze-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-halil-kesken-de6w6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok özledim deyip gelsen her sabah

Felek yazımızı kara yazamaz

Bir merhaba deyip gülsen her sabah

Bu güzel büyüyü kimse bozamaz

Dudağın bir çift laf atmaz mı bana

Güzel bir tebessüm etmez mi bana

Küçük bir öpücük yetmez mi bana

Bu güzel büyüyü kimse bozamaz

Yüzünü görmezsem ters gider işim

Yalnız özlemimden değil gelişim

Gün batana kadar rast gider işim

Bu güzel büyüyü kimse bozamaz', 'Çok özledim deyip gelsen her sabah Felek yazımızı kara yazamaz Bir merhaba deyip gülsen her sabah Bu güzel büyüyü kimse bozamaz Dudağın bir ...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buyu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkaklığımdan inan ki...', 'korkakligimdan-inan-ki-zafer-zengin-etnika-yp1y2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

canım

bağışla beni

taşıyamadım

bu kadar uzaklığı

taşıyamadım gözlerini

nasıl ölsemde

kar etsem ömrüne

istersen

bir parçamı al

sür güzel gözlerine

bağışla beni

taşıyamadım sevgini

deliliğimden değil 

korkaklığımdan inan ki

22 07 2005

.', '. canım bağışla beni taşıyamadım bu kadar uzaklığı taşıyamadım gözlerini nasıl ölsemde kar etsem ömrüne istersen bir parçamı al sür güzel gö...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/korkakligimdan-inan-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sönmedi Bu Aşkın Ateşi', 'sonmedi-bu-askin-atesi-i-brahim-nazim-ulker-0q55c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sevda yaşadık; sevdadan öte,

Kendi bildiklerimiz ve bilindiklerimizle.

Yandırdık yüreğimizin kandillerini,

Bir volkanı, bir civan delikanlılığı,

Ve bir cihanı ateşlendirdik.

Benzinlere bulayıp kibritini çakar gibi.

Büyüdü yangınım soluksuz, amansız,

Aralıksız büyüdü gitti.

Seninse sönerken yangının apansız bitti.

Kızgın, acı yağlar,

Cehennemdeki lavlar boşalır oldu damarlarımdan.

Ne ağlayabildim,

Ne verebildim can,

Can; çekişiyor hayatla,

Ben çekiştim canla,

Sense gittin umarsızca.

Ateşim göklere ulaştı,

Velhasıl göklerde yandı.

Sönmedi bu sevdanın ateşi...

Ne yağmurlardı; 

Bir deli dicle gibi çağladı,

Ne karlardı; 

Munzuru kapladı.

Sönmedi bu aşkın ateşi dayandı.

Ne tufanlar, ne poyrazlar,

Ne zemheri de ayazlar,

Sönmedi söndüremedim bu sevdanın ateşini.

Munzurdan çığlar düştü,

Dicle, ceyhunla coştu,

Dünya alemim yinede yandı tutuştu.

Bu aşkın, bu sevdanın ateşini söndüremedim sönmedi.

Sönmedi bu aşkın ateşi...', 'Bir sevda yaşadık; sevdadan öte, Kendi bildiklerimiz ve bilindiklerimizle. Yandırdık yüreğimizin kandillerini, Bir volkanı, bir civan delika...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sonmedi-bu-askin-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden kalanlar sana saklananlar', 'senden-kalanlar-sana-saklananlar-ahmet-karaca-30v7b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birgün biriktirdiğim bütün umutlarımı cebime koyup

 Düşücem yollara

 Gezicem dünyayı karış karış

 Ne yalçın dağlar korkutacak gözümü

 Ne de engin denizler

 Birgün başarana dek sürecek bu yarış

 Dünyanın neresinde olursam olayım 

 Nerde bir aşktan anlayan görsem 

 Usulca sokulucam yanına 

 Anlatıcam derdimi

 Elbet bulucam birgün bana yardım edecek biri 

 Elbet birgün gösterecek biri bana aradığım şeyi 

 Elbet elbet bigün başarıcam 

 İnsanlar hep çift yaratılırmış derdi babam

 Senmişsin gibi severek onu

 Sana yaptığım hiçbir yanlışı ona yapmamaya çalışarak

 Bir ömür geciricem onunla

 Ve bir gün  onu da alıp yanıma 

 Çıkıcam karşına

 Tam karşında tutucam ellerini

 Onun mutluluğuna baktıkça anlayacaksın 

 Seni ne kadar sevdiğimi

 Senin için neleri yapabileceğimi gösterecek sana

 Uçsuz bucaksız uzaklardaki bir dağ köyünün

 Tıpkı ama tıpkı sana benzeyen güzelinin 

 Işıldayan gözleri', 'Birgün biriktirdiğim bütün umutlarımı cebime koyup  Düşücem yollara  Gezicem dünyayı karış karış  Ne yalçın dağlar korkutacak gözümü  Ne de ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Karaca']::text[], 8.5, '{"poet":"Ahmet Karaca","poet_slug":"ahmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senden-kalanlar-sana-saklananlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzüm', 'gokyuzum-ufuk-coban-ponsb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilemezdim bu kadar acı olacağını,

Ayrılığın canımı yakacağını.

Belki de ben istedim bu dayanılmazlığı,

Bir küçük mutluluğa ekerek bütün acılarımı.

İstemezdim üzülmeni gülerken bir damlaya,

Damla şimdi sel oldu gözlerimin yanında.

İnan elimde olsa, yapabilsem, düşünmezdim onu da,

Koşardım kalan son gücümle olabilmek için yanında.

Katlanmayı öğrenmek gerek zamanla büyürken,

Belki de herşey zor gelecek bunları görürken.

Gün gelipte pişmanlık aldığında düşünürken,

Özür bile kurtarmayacak gözlerini yumarken.

Yağmurlarım şimdi başka diyarlara gitti,

Dağlarım ise yalnızlığı öğrendi,

Denizlerimde kopan fırtınalar bitti.

Gökyüzüm de hiç olmadığı kadar karanlık şimdi.

Beni unutma bitanem..........

1999', 'Bilemezdim bu kadar acı olacağını, Ayrılığın canımı yakacağını. Belki de ben istedim bu dayanılmazlığı, Bir küçük mutluluğa ekerek bütün acı...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gokyuzum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dili', 'gonul-dili-bahri-orhan-e17h0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinden ışıltıyı alıp salıversem, 

Ruhuma eminim ab-ı hayat olurdu. 

Yeşerirken umutlarım yeni sevdalara,

Damla olur düşerdin bu çorak toprağa.

Sürünenler ararsan peşinde derbeder,

Güvercinin olur muştular taşırdım sana,

Kelebek olur konardım nazenin dalına,

Uçardım kanatlanarak şu batan ufuğa.

Koklamak mı arzun bir çiçeği dalında,

Bahçende yetiştiririm dikensiz gülleri.

Ağlamak istersen sessiz ve nedensiz,

Akan o pınar ben olurum çağlayanlara.', 'Gözlerinden ışıltıyı alıp salıversem,  Ruhuma eminim ab-ı hayat olurdu.  Yeşerirken umutlarım yeni sevdalara, Damla olur düşerdin bu çorak t...', ARRAY['Türk Edebiyatı','Şiir','Bahri Orhan']::text[], 8.5, '{"poet":"Bahri Orhan","poet_slug":"bahri-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-dili-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ciddi misin?', 'ciddi-misin-melike-asat-ki1ya', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'CİDDİ MİSİN? 

püskülleri savaşır durur yeni örtünün

kaç kereler konuşuldu burada

ciddiyet 

camlarla savaşır durur gölgeleri ışığın

kaç kereler mahvedildi bir aşk

bu ciddiyette

elleri karışır düşüncenin savaşında 

kaç kereler düşündü 

bu güzelim şarkıda o’nu

anlamını yitirsin bu ciddiyet

saçlarını toplayan 

toka gibiydi canı burnunda sessizlik 

her şeye bir ‘neden? ’ mi sorulur 

bu cevaplar şehrinde', 'CİDDİ MİSİN?  püskülleri savaşır durur yeni örtünün kaç kereler konuşuldu burada ciddiyet  camlarla savaşır durur gölgeleri ışığın kaç kerel...', ARRAY['Türk Edebiyatı','Şiir','Melike Asat']::text[], 8.5, '{"poet":"Melike Asat","poet_slug":"melike-asat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ciddi-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söğüt Dalı', 'sogut-dali-selahattin-durna-ttj0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söğüt Dalı

....................

Yapamam

Su bulmaz beni

Rüzgar uğramaz bana

Kıyı kalmışım,kenar düşmüşüm; 

Toprak elimden tutmaz.

Gün ısıtmaz,

Şavkı vurmaz ayın bana

Doğumum yıldız geçe,

Yüreğim gecekondu

Yol sokak uğramaz ki

Bulamam

Yol benden ayrıcadır

Saat hep erte durur

Hangi kula danışsam

Hangi aynaya baksam

Hep ayruğu gösterir.

Diyemem,

Söz benim ebced’imdir.

Ocaklar kotarsa içim

Közüm ırağa düşer

Dilim bir karmaşık şifre

Kim uğraşır,kim çözer.

Bilemem

Kuş hangi söze konar

Hangi düşe bandırır

Kelebek kanadını

Yeşile vurasım gelir

Çiçeğe durasım gelir

Yağmur beni ıslatmaz

Varamam,

Bahar neyler ki beni

Kuru bir söğüt dalı

Ayağım yeri bulmaz,

Göğe avuç açamam

Kim farkeder,kim görür

İçimdeki yaprağı.

                                                     SELAHADDİN DURNA

                                                                28şubat2001', 'Söğüt Dalı .................... Yapamam Su bulmaz beni Rüzgar uğramaz bana Kıyı kalmışım,kenar düşmüşüm;  Toprak elimden tutmaz. Gün ısıtmaz...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sogut-dali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinem', 'hasretinem-selahattin-durna-cm4yg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretinem

	Yoldaşım olsan

	Yüreğimin

	Bir muhkem kuytusunda

	İşkencede adını sorsalar

	Söylemesem.

	Leyla olsan

	Çöle vursam nefesimi

     Su olsan

	De,suyun resmi olsan

     Islansa içim.

	Yol olsan

	Yürüsem bir uzağı

	Bir kuru ekmek olsan

	Acıksam sana

	Doymasam.

	Bir bitmez rüya olsan

	Uyusam seni

	Uyanmasam.

					Eylül98', 'Hasretinem 	Yoldaşım olsan 	Yüreğimin 	Bir muhkem kuytusunda 	İşkencede adını sorsalar 	Söylemesem. 	Leyla olsan 	Çöle vursam nefesimi      ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretinem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığında Son Mektup - 1 -', 'ayisiginda-son-mektup-1-mustafa-dogan-kuzgun-om2c0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gene böyle bir geceydi

Ve delicesine yağıyordu yağmur

Şimşekler çakıyor, sular diz boyu dalgalanıyordu

Gecenin umut dolu meltemi sanki ölüm kokuyordu.

Saman alevi gibi geldi ve geçti

Sanki Tanrının lâneti yalnız beni seçti

Yağmur bana yağdı, şimşek bana çaktı

Yalnız beni dondurdu ve yalnız beni yaktı.

Gözlerimi açtığımda boş bir odada

Pencere ve kapı demirli, rutubetliydi hava

Bir kanepe, bir kalem, bir kağıt ve masa

Hepsi biraz dert yüklüydü, biraz gam ve tasa.

Suçum; sevmekti, gönül vermekti

Suçum; kötüye kötü, iyiye iyi demekti

Suçum; her güleni dostum bilmekti

Suçum; insanlığa değer vermekti.

Cezam; ölümdü bana göre

Cezam; bir daha hiç sevmemekti

Cezam; seveni, sevileni kötülemekti

Cezam; bütün yanlışa doğru demekti.

Karar; ölüm dediler, ölmedim

Karar; sürgün dediler, gitmedim

Karar; sevme dediler, delice sevdim

Son karar sabah dediler, bekleyemedim...', 'Gene böyle bir geceydi Ve delicesine yağıyordu yağmur Şimşekler çakıyor, sular diz boyu dalgalanıyordu Gecenin umut dolu meltemi sanki ölüm ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayisiginda-son-mektup-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap Vermedin', 'cevap-vermedin-alper-torun-z7did', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana şarkılar söyledim,

Dinlemedin.

Sana şiirler okudum,

İstemedin.

Sana sevdadan bahsettim,

Doğru değil dedin.

Doğru nedir demedim,

Cevap vermedin.', 'Sana şarkılar söyledim, Dinlemedin. Sana şiirler okudum, İstemedin. Sana sevdadan bahsettim, Doğru değil dedin. Doğru nedir demedim, Cevap v...', ARRAY['Türk Edebiyatı','Şiir','Alper Torun']::text[], 8.5, '{"poet":"Alper Torun","poet_slug":"alper-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cevap-vermedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevda', 'bir-sevda-huseyin-kerim-b2ad7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevdadır bendeki,karanlıkta gizlenen

Ölümüne ben varım,hiç korkmadan kimseden

Neden gizli bilirmisin, yaşatmazlar bir tanem

Geçmişde ben olsaydım,haykırırdım çekinmeden

Şimdi kendi içimde, çekilmişim  tenhaya

Beklerim bir gün elbet,o  ruh çıkar ortaya

Bagırsamda,çagırsamda,haykırsamda dünyaya

Hiç korkmamki bir tanem,canlar katılır canıma

Ben buyum,biz buyuz,er meydanı karşıda

........................................................................

İnanma gülüm inanma,bunlar sadece bir rüya

Hep sıkdım ben dişimi,çıkmam şimdi ortaya

..........................................................................

Canımdan can verdim,vatan dedi   al dedim

Bir damla yaş akmadı,ugruna feda ettim

Yıllar gecti aradan,bir baktımki arkaya

Herşey.... hiçbirşeymiş... boş yere yandı canan

Oturdum  ağladım,sen görmedin ben kıvrandım

Görseydin çok utanırdım,erkekler  aglamazdı', 'Bir sevdadır bendeki,karanlıkta gizlenen Ölümüne ben varım,hiç korkmadan kimseden Neden gizli bilirmisin, yaşatmazlar bir tanem Geçmişde ben...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim']::text[], 8.5, '{"poet":"Hüseyin Kerim","poet_slug":"huseyin-kerim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-sevda-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşan Kalemim', 'konusan-kalemim-kamber-bal-yla4b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdimi bilen bir dostum var

Yanımdan ayrılmaz konuşan kalemim

Ne söylersen o yazar

Kalbimi kırmaz konuşan kalemim

Ne usluluk, ne üstünlük

Ne dargınlık, ne küskünlük

Hiç bilmez kibirlilik

Alçak gönüllü konuşan kalemim

Onunladır bütün yazım kışım

Sakin olur yorulmaz başım

En çok sevdiğim tek arkadaşım

Yoldaşımdır konuşan kalemim

Sıkılmak bilmem birlikte olunca

Bütün işler gider tam yolunca

Bazen okşarım onu usulca

Usludur konuşan kalemim

Canı sıkılmaz, hep yazar

Özgürlüğü uğruna ufukları gezer

Takılmış ki ona bir Bal’lı nazar

Hayat-ı alemde ölmez konuşan kalemim

1983', 'Derdimi bilen bir dostum var Yanımdan ayrılmaz konuşan kalemim Ne söylersen o yazar Kalbimi kırmaz konuşan kalemim Ne usluluk, ne üstünlük N...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/konusan-kalemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâbus', 'k-bus-alper-torun-c0c5y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykulara dalarım bir başıma

Rüyalar görürüm tek kişilik

Dört başı mamur.

Kimi zaman bir dekor olurum tiyatro sahnesinde,

Kimi zaman çürümeye yüz tutmuş bir sandal

Dil iskelesinde...

Küçük dalgaların kucağında

çırpınırken nazlı nazlı,

geceye bakarken akşam,

gün batıya kaçtığında,

serin sabahlarla vuslatında karanlığın,

karlar yağarken üşümüş sırtıma,

Yalnızlık örter üzerimi perde perde.

Kapanır göz kapaklarım 

paslı demir kapılar misali

ağır, ıslak, gürültüyle...

Ve sıçrayarak uyanırım 

kan ter içinde...', 'Uykulara dalarım bir başıma Rüyalar görürüm tek kişilik Dört başı mamur. Kimi zaman bir dekor olurum tiyatro sahnesinde, Kimi zaman çürümeye...', ARRAY['Türk Edebiyatı','Şiir','Alper Torun']::text[], 8.5, '{"poet":"Alper Torun","poet_slug":"alper-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kabus-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islaklığın Kuraklığı', 'islakligin-kurakligi-tarhan-simsek-70sgt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ISLAKLIĞIN KURAKLIĞI

Islaktı hava

Duygularım ıslaktı

Ve kolundaki 

Zamana dair anlar sırılsıklamdı.

Güneş tüm sıcaklığıyla

Islatıyordu

Bizli mekânları.

Tek başımaydım

Ve

Bu ıslaklığı

Kurutuyordum gönlümde

Birden sen çıkageldin

Gönlümde 

Bir 

Ömür boyu

Bırakacağın ıslaklığınla geldin.

Islaktı hava

Islanıyordun.

Bu ıslaklığın

Bir

Kuraklık arıyor gibiydi.

Yağmur 

Islatıyordu şehrin 

Senli mekanlarını.

Çocuk ıslaklığı kokuyordu tenin

Aşka dair

Kitapların ıslanıyor

Ve

Bu kitaplardaki

Yeşil yaşam hayat buluyordu.

Ve yine

O kitaplardaki

Sevda sözleri

Sen gibi

Islanıyordu.

Şehir ıslanıyor

Karıncalar sele kapılıyordu.

Ve 

Gündüz geceye varamadan ıslanıyordu.

Dışarıda duyulan melodi

Islak bir aşkın evliliğini

Nağmeliyordu kulaklarımıza.

Oysa biz

İleride kuruyacak

Bir tanesi

Tamamen 

Çoraklaşacak

İki

Gönlü ıslatıyorduk.

Islaktı hava

Son gördüğümde 

O gözlerin

Bir

Okyanus ıslaklığındaydı.

“Gel Zaman; Git Mekân”

Yıllar

Yeryüzünü

Onca ıslatmışlığa rağmen

Tamamen kurutmuştu.

Güneş

Sanki

Yıllardan beridir

Ayrılmamıştı

Bu enkazın üzerinden.

Gök kuru, yer kuruydu

Gönlündeki dalgalar

Kupkuruydu.

Kuruyup gitmişti onca ıslaklık

Yağmurlar

Artık 

Değer biçmiyordu buraya.

Tek bir damlanın bile

İzi yoktu gözlerde.

Kitapların belki yoktu yanında

Ama

Belliydi

Onlar da kurumuştu.

Yıllar

(Ama çok yıllar önce) 

Görüp de unutamadığım

O gözler

Siyah beyaz bir karaya çalmıştı.

Çoraklaşmış 

Ve

Karaya çalmış

O pınarlar

Tüm hüzünleriyle

Akreplere ve yılanlar

Mekân olmuştu.

Aylardan Nisan

Ama kurak bir Nisan

(Hem nerede eski Nisan’lar) 

İlkbaharın

O kışkırtıcı yağmurlarından

Eser yoktu.

Nisan kurak

Şemsiyeler kuraktı

Ve

O

Diri göğüslerini saran

O ince kumaş

Kupkuraktı.

Yıllar öncesinin

O çocuk ıslaklığındaki tenin

Şimdi

Bir ergen yangın yeriydi artık.

Ayak parmakların kuraktı

Ve 

Kelimeler

Sadece

Yedi harften oluşuyordu

Yani

K-U-R-A-K-T-I…

Yağmalanmış bedenin

Bu kuraklıkta

Çöl bedevilerinin

Sofralarına mekân olmuştu.

Ve daha da

Kurak çöl vahalarına götürülüyordu.

Dışarıda duyulan o melodi

O eski ıslaklığa aldanıp

(Hani vardıya) 

Evlenen âşıkların

Mutsuzluğunu

Terennüm ediyordu kulaklara.

Sen kuraktın

Kurutulmuş

Kitap sayfalarına mahkûm edilen

Bir çiçeğin kuraklığındaydın.

Kuraktı hava.

Bu keşmekeş kuraklıkta

Düşlerindi tek ıslak olan 

Evet

Sırılsıklamlığa vuran düşlerindi.

Ama

Gerçek yaşamın

Tek bir çiçeğe bile

Sahip olamayacak kuraklıktaydı.

Kuraktı hava

Ve

Son gördüğümde

O gözler

Bir alevin kızıllığında yanıyordu.

Tarhan ŞİMŞEK

HAKKARİ / 2002', 'ISLAKLIĞIN KURAKLIĞI Islaktı hava Duygularım ıslaktı Ve kolundaki  Zamana dair anlar sırılsıklamdı. Güneş tüm sıcaklığıyla Islatıyordu Bizli...', ARRAY['Türk Edebiyatı','Şiir','Tarhan Şimşek']::text[], 8.5, '{"poet":"Tarhan Şimşek","poet_slug":"tarhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":146,"source_url":"https://www.antoloji.com/islakligin-kurakligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Aşklarımın Kahramanı', 'i-simsiz-asklarimin-kahramani-melih-coskun-1fosu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç ummadığın anlarda 

Tersten esen bir rüzgardır 

Bu yazılanlar

Olmadık zamanlarda 

Damdan düşercesine 

Aşık olmak gibi...

Cebindeki son parayı 

Köşe başında bekleyen esmer yüzlü 

Çocuğun eline verip 

Yürümek  yürek rahatlığıyla evinin yolunda   

Ellerimle yontup bütün acıları 

Çamurlaştırıyorum 

Tuzlu tadıyla gözyaşımın 

Sana bir kuş yapıyorum ellerimle 

Uçmayı öğrenmemiş

Şefkatine muhtaç bir kuş yapıyorum ellerimle 

Uçmayı öğretirsin diye ona belki bir gün 

Aşklar yaratıyorum 

İsimleri 

Ve adresleri olmayan 

Ve sıyrılıp 

Bulaştığım bütün kirlerinden dünyanın 

Silip yeniden çizmek istiyorum 

Yollara tırnaklarımla kazıdığım o yürek resmini...

Sevmek böyle bir şey işte 

Güneşli bir günün öğleninde aniden bastıran yağmur 

Esmer bir çocuğa verilen 

Cebimdeki son para 

Sırtımda kuruyan gömlek gibi... 

Sevmeler yaratıyorum 

Bakışlarınla büyüt o kuşu 

Ona uçmayı öğret ellerinle 

Sen, isimsiz aşklarımın kahramanı 

Çözüldü beynimde yüreğinin bütün şifreleri

Hiçbir köşe başından medet ummadan 

Kendi ellerimle yaratıyorum artık sevgiyi...', 'Hiç ummadığın anlarda  Tersten esen bir rüzgardır  Bu yazılanlar Olmadık zamanlarda  Damdan düşercesine  Aşık olmak gibi... Cebindeki son pa...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/isimsiz-asklarimin-kahramani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüz', 'i-ki-yuz-huseyin-sigirtmac-u67qj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçi başka dışı başka, belirsiz.

Güvenme masumca bakar iki yüz.

Kalbi fitne yüklü, alttan ve sessiz.

Fırsat bulsa yıkıp yakar iki yüz.

Maskeler bürümüş yalan yüzüne.

Kıskançlık yapışmış çıkmaz özüne.

İhanet yerleşmiş bakan gözüne.

Doğru çöküp yanlış kalkar iki yüz.

Taht kurmuş beynine kin ile nefret.

Kendi kendini yer bu nasıl bir dert? 

Yalan dolan aslı olamaz ki mert.

Bir pula insanı satar iki yüz.

Her türlü melanet yaşar ininde.

Doğruluktan uzak, hile yanında.

Sığırtmaç denklemi çözdü sonunda.

Tuzlamaya değmez kokar iki yüz.', 'İçi başka dışı başka, belirsiz. Güvenme masumca bakar iki yüz. Kalbi fitne yüklü, alttan ve sessiz. Fırsat bulsa yıkıp yakar iki yüz. Maskel...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-yuz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Aşık', 'suskun-asik-kamber-bal-mzngi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi seyre daldın mı hiç? 

Yıldızdaki o manayı bilir misin? 

Koparıp ruhunu göklere saldın mı hiç? 

Geride kalan bedeni bilir misin? 	

Gece senden şarkı istedi mi hiç? 

Gökler kalbini bana ver dedi mi? 

Sevdiğin peri misali seni gördüğünde

Tutup elini sevmesini bilir misin? 

Açılsa gözlerinde gök mavisi

Dinmese kulaklarında gönül sesi

Büyüse üzeride sevgi gölgesi

Uzanıp altına yatmasını bilir misin? 

Alıp götürse seni, gece göklere

Bıraksa boşluğa birden bire

Uyku gelse o ela gözlere

Bir daha uyanmasını bilir misin? 

Şarkı söylese gönüller senin için

Selamına kalksa o sinsi gece

Ufukta ki güneşle gel dense

Sonsuza dek gitmesini bilir misin? 

Arılar senin için çalışsa her an

Çiçekler tacın olsa, bitmese zaman

Her şey ölü, sen olsan yaşayan

Yediğin Bal’ın kıymetini bilir misin? 

 26.10.1985

www.kamberbal.com', 'Geceyi seyre daldın mı hiç?  Yıldızdaki o manayı bilir misin?  Koparıp ruhunu göklere saldın mı hiç?  Geride kalan bedeni bilir misin? 	 Gec...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/suskun-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-meral-vurgun-5cwqj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dost sesleri gelir uzaklardan 

ansızın gelirim diyen

delip kulağımı akar içime

tarifsiz sancılar saplanır yüreğime

fırtınalar koparır sol yanımda

dokunma yarama bu gece

bak dizelerim bile talan

''kınanmak yiğit başina''der şair

dostlar kınasın beni

gayrısı boş ve yalan

umuda açtım kollarımı 

ufka durup baktım gözlerine

nereden kanarsa kanasın yürek

sürme ellerini, akkorlarım  küllensin

ne bu sürgün, ne bu hasret

ben sende alevlenip 

seninle yanmışım

aç göğsünü çılgın dağ yellerine

savrulan saçlar olsun

yürek tel tel dağılsın

vursun dipsiz kuyulara

aksın, çağlasın, kanasın

bu devri alem uyansın

peşin ödedik

ağırdı  bedeller

yargılı yargısız ip ucunda boynumuz 

kimi zaman kaşla göz arasında yok edildik

kayıp saydılar bizi 

astılar, kestiler 

kafa derimizi yüzdüler

tarih utandı yol bilmez karanlığından

çağlar tanıktır

nice düğünler kurduk

omuz omuza halaya durduk 

vurulduk, vurulduk, vurulduk

af dilemedik, affetmedik

biz ki

sevda yüreklim

alnımıza dizdik yıldızları

başımızda ay gözlerimizde güneş 

şavkıdık tarihlerce 

ışıttık uçurumları

törene gerek yok

bir şiir koyun başucuma

çok kişilik ölmeliyim ben

Asya''dan Afika''ya kadar uzanmalı mezarım...', 'dost sesleri gelir uzaklardan  ansızın gelirim diyen delip kulağımı akar içime tarifsiz sancılar saplanır yüreğime fırtınalar koparır sol ya...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ses-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Var mı?', 'umut-var-mi-burhanettin-akdag-ea6gk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yılların yorgunu ruhum

Bin kere pişman olsam da

Koşuyorum ardı sıra sevginin

Acaba umut hangi baharda? 

Sora sora ezberledi, bıkmadı kalbim

Beynime aşkın tarifini sormaktan

Beceremesem de sevmeyi yıllardır

Acaba umut var mı hazanda? 

Birgün yığılıp kalacak bedenim

Taşımayacak bacaklarım, serileceğim

Üzerime örtülecek gazeteler

Acaba umut var mı kara toprakta? 

(21.12.2004)', 'Yılların yorgunu ruhum Bin kere pişman olsam da Koşuyorum ardı sıra sevginin Acaba umut hangi baharda?  Sora sora ezberledi, bıkmadı kalbim ...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umut-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vatan Bizimdir', 'bu-vatan-bizimdir-burhanettin-akdag-3p94n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al kanlar akıttık yanık bağrında 

Çok şehitler verdik kadrin bilecek 

Zor savaşlar yaptık hilâl uğrunda 

Bu vatan bizimdir bizim kalacak. 

Karlı dağlar aştık hesabın sorduk 

Sabır ve sükunla hedefe vardık 

Darbeler yesek de yeniden kurduk

Bu vatan bizimdir bizim kalacak. 

Yıllar geçip gitti sormadık niçin? 

Durmaksızın koştuk bugünler için 

Bin derdi yüklendik yolunda göçün

Bu vatan bizimdir bizim kalacak. 

Üstün gayret verdik imar ederken 

Toprağı işledik yeşermez derken 

Zoru başarırken uyandık erken 

Bu vatan bizimdir bizim kalacak. 

(25.07.2005)', 'Al kanlar akıttık yanık bağrında  Çok şehitler verdik kadrin bilecek  Zor savaşlar yaptık hilâl uğrunda  Bu vatan bizimdir bizim kalacak.  K...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-vatan-bizimdir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Kadın Olsam!', 'ah-bir-kadin-olsam-tarhan-simsek-cbcmh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“AH BİR KADIN OLSAM”

Ahhh bir kadın olsam.

Birileri tutulsa güzelliğime

Bana vurulsa.

Ferhat olsa, Mecnun olsa

Ve hatta olduysa Sezar olsa.

Ah bir kadın olsam.

İşvelensem,

Edalı bir yelloz olsam

Bir paşa konağında

Haremin en gözdesi olsam.

Ahh bir kadın olsam.

Keşke olsam.

Olsam da birileri

Bu sitede 

Şu yazacağım anlamsız şiire bile

Methiyeler dizse.

“*Sanal Alem’in Avcılarına İthafen Yazılmıştır. Lütfen Ördüğünüz Ağların Ayarlarıyla Oynamayın. Şiirimiz Sinemaskop Ebatlıdır (! ! ? ?) ”', '“AH BİR KADIN OLSAM” Ahhh bir kadın olsam. Birileri tutulsa güzelliğime Bana vurulsa. Ferhat olsa, Mecnun olsa Ve hatta olduysa Sezar olsa. ...', ARRAY['Türk Edebiyatı','Şiir','Tarhan Şimşek']::text[], 8.5, '{"poet":"Tarhan Şimşek","poet_slug":"tarhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ah-bir-kadin-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yazdım', 'bir-siir-yazdim-tarhan-simsek-fuwsy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“BİR ŞİİR YAZDIM”

Devran döner,

Şiir yazılır; 

Şiirler yazılır, 

Ve devran durur.

Gün olur

En hayın pusulara inat

Bir cinayet teşebbüsüne nail

Bir şiir yazılır.

Ne yazmalı? 

Herkesten gayrım ne olmalı? 

Yok yok

Bir taş atmalı kuyuya

Bin şair çıkartmamalı.

Gece, yok yok

Yıldız, hı hı

Yarin yanağı, değil

O olmadı, şu bulmadı

Öylesini yazmalı ki

Ne kimse anlamalı

Ne de kimse sevmemeli

Evet, 

Ne yazsam? 

Şiir bu

Öyle sıradan olmamalı.

“Yazık olmamalı 

Süleyman Efendi’nin nasırlarına”

Hah buldum

Evreka 

Hay bin kunduz

Crom adına

Sen benim…

Tarhan ŞİMŞEK

	2004/HAKKARİ', '“BİR ŞİİR YAZDIM” Devran döner, Şiir yazılır;  Şiirler yazılır,  Ve devran durur. Gün olur En hayın pusulara inat Bir cinayet teşebbüsüne na...', ARRAY['Türk Edebiyatı','Şiir','Tarhan Şimşek']::text[], 8.5, '{"poet":"Tarhan Şimşek","poet_slug":"tarhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-siir-yazdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Bırakma', 'sakin-birakma-burhanettin-akdag-i70we', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üzülme, karartma gönlünü sevdaya gülüm

Bulunur elbet çaresi, gelir gönlünün prensi

Daralma, bunalma, ezme ruhunu

İnsanı yıkan, ümitsizlik ve yeistir sultanım

İlla seveceğiz diye birşey yok gülüm

Bulunur elbet çaresi, gelir seni seven yürek

Dünyanın sonu değil ki karşılıksız sevgi

İnsanı yıkan, vefasızlık ve ilgisizliktir sultanım

Biliyorum, sevgisiz yaşamak çok zordur gülüm

Bulunur elbet çaresi, gönlünün dengi, ruh ikizi

Sabırla, duyguyla, ilmek ilmek dokunan sevgi

İnsanı bezdiren, yılgınlık ve kırgınlıktır sultanım

Üzülme, kapatma gönlünü sevdaya gülüm

Bulunur elbet çaresi, bir sevgi pınarı

Kana kana, soluksuz içilir aşk şarabı

İnsanı yıpratan, vazgeçmek ve bırakmaktır sultanım

Bırakma hiç sevmeyi, koş ardından sevginin

Vazgeçme kavuşmaktan, aşk oduyla yanmaktan

Hergün yeniden tazele duygularını, umutlarını

Hiç durma, sevdanın  ardından  yıllarca koş sultanım', 'Üzülme, karartma gönlünü sevdaya gülüm Bulunur elbet çaresi, gelir gönlünün prensi Daralma, bunalma, ezme ruhunu İnsanı yıkan, ümitsizlik ve...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sakin-birakma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Durdurmak', 'zamani-durdurmak-burhanettin-akdag-7ojlz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mümkün olsaydı zamanı durdurmak

Çocukluğumu isterdim önce

Sorumsuzca, sevgiyle şen şakrak

Alabildiğince, umut dolu yıllara koşarak

___Yarışırdım zamanla.

Mümkün olsaydı zamanı durdurmak

Gençliğimi isterdim sonrasında

Yaşayamadıklarımı, yaşanmamışlıklarımı

Daha bir akılla, daha bir kuvvetli yaşayarak

___Savaşırdım zamanla..

Mümkün olsaydı zamanı durdurmak

Aşkın en olgun çağını isterdim hep

Yudumlarken yaşadıklarımı, geleceğin hayaliyle

Daha dolu, daha keyifli, doyumsuzca yaşayarak

___Oynaşırdım zamanla.

(25.07.2005)', 'Mümkün olsaydı zamanı durdurmak Çocukluğumu isterdim önce Sorumsuzca, sevgiyle şen şakrak Alabildiğince, umut dolu yıllara koşarak ___Yarışı...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zamani-durdurmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu gurbeti terketsem ne yazardım!', 'su-gurbeti-terketsem-ne-yazardim-mikdat-bal-8r5uz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu gurbeti terketsem ne yazardım! 

İlhamımın yüzde doksanı hasret

Ben gurbetsiz kafiyeyi bozardım

Şiirimin dili, aksanı hasret', 'Şu gurbeti terketsem ne yazardım!  İlhamımın yüzde doksanı hasret Ben gurbetsiz kafiyeyi bozardım Şiirimin dili, aksanı hasret...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/su-gurbeti-terketsem-ne-yazardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-selvi-celik-yk7ba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Terk eylersem şu cihanı,

Yüzüne son defa gülmeden giderim.

Ömrüne kıyamam sana bırakır,

Sevğimi canına katarda giderim.

Ağlamasın deniz ğözlerin durulsun.

Fırata akan nehirler kurusun.

Sözünü tutmayan ğónül yorulsun.

Seni ateşe atmadan giderim.

Virane bahcemin gülleri

 ne baharda açtı ne yazda.

Kurak mevsimlerde kaldı emeklerim.

Yarınlarını çalmadan giderim.

Ruhum dolunaya kitlendi.

Dogmadi güneş yağmadı yağmur,

Seni sen diye bilmeden önce.

Sevdalari destanlari bırakır giderim.

Meçnun leyla''sına yanar.

Yunus Emre diyar diyar konar.

Mevlana Rabia''sını sorar.

Yağmur güneşini arar.

Seni topraga vermeden giderim.

Adımı koymuşsun melek.

Hani nerde kahpe felek.

Ayrılık mustak ölüm hak.

Aşk bohcamı sırtlanır giderim.', 'Terk eylersem şu cihanı, Yüzüne son defa gülmeden giderim. Ömrüne kıyamam sana bırakır, Sevğimi canına katarda giderim. Ağlamasın deniz ğözl...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gidecegim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizin Hiç Babanız Öldümü?', 'sizin-hic-babaniz-oldumu-bahtiyar-arslan-u5wap', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'babanız mı öldü? 

soğuk bir hastane odasında, annenizin kollarında...

kırıldımı dizleriniz? 

saç başmı yoldunuz? 

son kez göremedim diye, kahırdan...

sıvazlarken omzunu

yaralı bir kuş gibi çırpınarak

abiniz mi öldü kollarınızda

yandımı yüreğiniz acıdan...

dayanamayıp acısına, oğlunun

kimse bilmeden

duymadan kimse

söyleyemeden son sözlerini

annenizde mi öldü, gecenin koynunda sessizce...

yüreğiniz mi yandı acıdan? 

bir ağaç duldası bulun kendinize

ve yağmuru bekleyin, ağıt dolu türkülerle...

ve bilirmisiniz 

yıkarmış bütün acıları yağmur, minicik elleriyle...', 'babanız mı öldü?  soğuk bir hastane odasında, annenizin kollarında... kırıldımı dizleriniz?  saç başmı yoldunuz?  son kez göremedim diye, ka...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sizin-hic-babaniz-oldumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu', 'avuntu-mehmet-bicik-pvjye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolumuz düştü gurbet ele,

İnceden vurduk sazın tele,

Şu ayrılığı bile bile,

İçerimize gömdük kardeş…

Her gördüğümüzü dost bildik.

Gözyaşlarımızı çok sildik.

Eskiden biz böyle değildik,

Deyip teselli bulduk kardeş…

Acılarımız çoğaldı kat kat.

Çekilmez oldu artık hayat.

Hiç bir şeyden alamadık tat,

Anılarımızla avunduk kardeş…

Umudumuzu hiç yitirmedik.

Âilemize de halel getirmedik.

Aşkımızı, sevgimizi bitirmedik,

Her gün sararıp solduk kardeş..

26 Temmuz, 2005 Burhaniye 01:00', 'Yolumuz düştü gurbet ele, İnceden vurduk sazın tele, Şu ayrılığı bile bile, İçerimize gömdük kardeş… Her gördüğümüzü dost bildik. Gözyaşları...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/avuntu-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Öyküdür Kimi Aşk', 'bir-garip-oykudur-kimi-ask-bekir-mutlu-gokcesu-1ftl8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gelmek mi sana? 

Yoksa savrulmak mı daha

Daha uzağa...

Ayaklarımda tozu 

Dudaklarımda tuzu denizin

Ve aklımdan neler geçer

İkimize dair

Düşünmemeye çalışırken bizi...

Bu yaklaşmak mı sana? 

Dönüp dolaşıp gelmek mi yoksa

Seninle sensizliğimin başladığı yere

Ya da kalakalmak mı? 

Hiç başlamadık ki biz daha diye...

Bu tükenmeye yüz tutmak mı yoksa

Hiç bitmeyeceğimizi bile bile...

Bir garip öyküdür kimi aşk

Bir tebessümdür yüzünde sadece

Ve elinde değildir ağlamak

Yakıştıramazsın kendine

Özlersin...

Seversin...

Sebebini hiç bilemezsin

Gülersin, gülmek istersin sadece...', 'Bu gelmek mi sana?  Yoksa savrulmak mı daha Daha uzağa... Ayaklarımda tozu  Dudaklarımda tuzu denizin Ve aklımdan neler geçer İkimize dair D...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-garip-oykudur-kimi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Beni Dinliyorum', 'ben-beni-dinliyorum-mehmet-bicik-0h1wn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece, 

yalnızım yine..

Ben,

Ben’le, 

duygularımla 

baş başayım..

Sadece,

kendimi dinliyorum…

Ve,

âniden

Bir sancı başlıyor

Kâlbimde,

İnliyorum…

Önceleri,

Bir’di derdim.

Şimdi binliyorum…

Günler geçtikçe, 

Sancılarım arttıkça,

Yaşamın benim için

Haram olduğunu anlıyorum…

Ağırdan alıyorsam,

Biraz vurdumduymazsam,

Sesimi yükseltmiyorsam,

Sanmayın kimseyi tınlıyorum…

Ben, 

sadece, 

kendimi dinliyorum…

27 Mart 1998, Malatya', 'Bu gece,  yalnızım yine.. Ben, Ben’le,  duygularımla  baş başayım.. Sadece, kendimi dinliyorum… Ve, âniden Bir sancı başlıyor Kâlbimde, İnli...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-beni-dinliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-yavuz-agir-118ng', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufkumun güneşi ol,

Bahtıma doğda gel.

Aydınlığa kucak aç

Adımı semaya yazda gel..

Ufkuma yıdız ol

Sevgilere kucak aç.

Yollarına çiçek ektim

Demet demet topla gel.

Sevdanın simgesi ol 

Herkes duysun adını.

Aşıklar çeşmesi seni bekler

Kana kana içte gel...', 'Ufkumun güneşi ol, Bahtıma doğda gel. Aydınlığa kucak aç Adımı semaya yazda gel.. Ufkuma yıdız ol Sevgilere kucak aç. Yollarına çiçek ektim ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-185-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trende', 'trende-salih-erdem-w1ctv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ise bulanmış camlarını

kaçıncı gözyaşı siliyor

kimbilir kaçıncı eller bu

vedalara sallanıyor

vedaların izleri camlarında

vagonlarında ter kokusu

koparken eller ayrılığa

dumanınla çiz ne olur

her istasyona bir nota

...................................elveda

is yığınım kara gurbetim

yırtar hasreti gözlerin

yırtar da gecenin karanlığını

kıvrılarak uzayıp giden

rayların neden yaslı

is yığınım kara gurbetim

her makasta biter umudum

her makasta başlar hasretim

08.03.1994 kırıkhan', 'ise bulanmış camlarını kaçıncı gözyaşı siliyor kimbilir kaçıncı eller bu vedalara sallanıyor vedaların izleri camlarında vagonlarında ter ko...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/trende-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa oğlu salih', 'mustafa-oglu-salih-salih-erdem-wrlm2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1966 yılında

babam tarayıp kitapları

“salih” düşmüş nüfus kaydıma

benim talihsiz güzel anam

gün yazdan kışa dönmeden

belemiş beni beşiğime

sonra dönmüş işine gücüne

gözümü tarlalarda açtım

yalnız bırakmamak için anamı

var gücümle çalıştım

……………..kızgın güneşin altında

bir yalım olup 

……………..bende toprakla yandım

terim aktı damla damla

…………….toprağa karıştım

sonra üstümden attım tozumu 

harman yerinde esen yellere

bir erkek gibi çalışan anama bakıp 

…………………………………….şaşarak

sen bir öğretmen kadınısın

neyine gerek senin çalışmak 

……………………………….derdi 

bazı köylüler işten güçten bıkarak

oysa beş çocuklu bir aileye yetmezdi

………………………öğretmen maaşı

ve köy yerindesin

herkes çalışırken

yakıştıramazdık kendimize aylaklığı

eksik olmadık ovadan tarladan

eşekle 

……...atla 

…………..yollarda çoğu zaman yayan

çalıştık bir zaman

………………..toz duman içinde

terledik toz terimize karıştı

yüzümüz terden çamur içinde 

………………..yandık güneşin gölgesinde

yandık ki ne yandık

ve hâlâ içim yanık

ve hâlâ uykularına doyamam

doyamam ağaç gölgelerine

ilk sigaramı beş yaşında içtim

ve babamdan öldüresiye dayak yedim

sonra yıllar yılı sigarayla seviştim

paramın olmadığına yandım bakkal önlerinde

babamın parasını çaldım

o zamanlar köyde insan çoktu

mahallenin çocuğu bir ordu

bir ordu bir olup

harmanda dövenle döndük

sonra attık kendimizi havuza

………………...havuzda soğuk sulara

sıcak yaz akşamları

…………………ateş böceklerinin peşinde koştum

elimde sapanım 

peşinde koştum kuşların

ve ben de bildim arkadaşımı

dere yamaçlarında paylaşırken kuru katığımı 

onun hiç haberi olmadı ya

ilk aşkımı ilkokulda yaşadım

şimdi beş çocukla 

bir hayırsızın elinde

hatırladıkça içim acır 

…………………..acırım

“adam olmak için okumak gerek”

büyükler hep böyle derdi

acıpayam ilk gurbet

sonra denizli çorum

geçti öğrenme yıllarım

öğrenmenin yaşı yokmuş

zamanla anladım

askerliğe batıda başladım 

………….izmir - hacılar kırı

sonra doğuda erzincan 

………….gördüm karlı dağları

öğrendim ki

adamlığın yolu 

……kalemden kitaptan geçmezmiş

adam olmak için

önce insan olmak gerekmiş

büyüdük

bir bir uçtuk yuvadan

işmiş aşmış görevmiş

mevsim göç mevsimiymiş

köyde genç namına kimse kalmadı

çekilecek çile büyük şehirlerdeymiş

aldım kalemi elime

kırıkhan ilk görev yerim

sonra safranbolu

ve sonra aydın

…………postumu buraya yaydım

yalanım yok

gittiğim her yeri bildim vatan

sağ olsunlar

onlarda ayırmadılar beni evlattan

bu arada 

ben de yol aldım zamandan

derlerdi de duyardım

hanesi varmış ya

…………bu yalan dünyanın

bende girdim içine

ve çoğaldım sevgiyle

yaradanım verdi bana soy

işim 

…..gücüm 

……………sağlığım yerinde

çalıştım çabaladım

kalmadı dünya malına ahım

daha ne isterim

yeter ki taşıyamayacağımı

yaradanım bana taşıtmasın

sesim kimseye benzemesin diye

dönüp bakmadım uzun süre şiire

oysa aşk 

her insanın gözünde ayrı parlar

………………damarında farklı akarmış

şimdi şimdi görüyorum

sevginin ifadesi aynı olmasın diye

tanrım her kulunu ayrı yaratmış

ben bunu nasıl atlamışım

yazmadan boşa geçen bu zaman

en büyük yanlışımmış

bir bir kopardım zamandan

……………..zamanın yaprağını

zaman da zamanla 

……………..kolumu kanadımı

elimle koydum toprağa

…………….2004 sonbaharında canımı

küçük bir su perisi

ondan bize miras kaldı

sonradan koyacakmış yokluğu

yanar da 

yanarım

………hâlâ ağlarım anama

ve hâlâ çocuk gibiyim

geçmedi utangaçlığım

geçmedi içimden heyecanlarım

başkalarına olmadığı gibi

kendime de etmedim hiç ısrar

dedim ki hep

zorla güzellik olmaz

akacak olan kan da damarda durmaz

bir gün bende bulurum yolumu

durulurum elbet

durulur bu çalkantılar 

bir su misali ömrüm

döner dolaşır yatağına akar

kimseden saklım olmadı 

kalmadı içimde hiçbir sır

“zihnimle cenk eden 

…………………...kelimelerden

kâğıda düşenlerdi 

…………………...okuduklarınız”

05.05.2005 aydın', '1966 yılında babam tarayıp kitapları “salih” düşmüş nüfus kaydıma benim talihsiz güzel anam gün yazdan kışa dönmeden belemiş beni beşiğime s...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":154,"source_url":"https://www.antoloji.com/mustafa-oglu-salih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni unutursun', 'beni-unutursun-salih-erdem-iwbxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gücün yeter mi

küllenmiş ateşleri yeniden yakmaya

senin çaban boşa dostum

ırmaklar karıştı okyanusa

şimdi bir gitar telindeyim

yalnızlığım dökülüyor

titriyorum gecede

notalar savruluyor yıldız karanlığına

birazdan yaylılarla inecek son perde

bana bakma sen

girme kapılarımdan içeriye

gözlerime deli gibi bakma öyle

ortak olma her acıma

benim gibi savrulursun

boynunu niye büktün

neden mehtaplı deniz gibi durgunsun

kelimeler dökülmüyor ağzından

suskunsun konuşmuyorsun

söylesene

hayatı kendine zehretmeye mecbur musun

evlensene sen

…………….çocuğun olur

beni unutursun', 'gücün yeter mi küllenmiş ateşleri yeniden yakmaya senin çaban boşa dostum ırmaklar karıştı okyanusa şimdi bir gitar telindeyim yalnızlığım d...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beni-unutursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semazen', 'semazen-salih-erdem-auhft', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir elin yere dönük

bir elini aç gökyüzüne

tıpkı semazen gibi

kapat gözlerini

elinin altındakileri düşün

sonra üstündekileri

dur

sıyrılıp çıkma bedeninden

düşün dünde kalanları

yarının ne getireceğini

bir lokma bir hırka değil derdimiz

duamız yan gelip yatana değil

ne hırsıza

.................ne dolandırıcıya

............................................ne de açgöze

aç gözlerini

insanların yüzüne bak / renk renk

her yaradılan elbet kabulümüz

insanların yüzüne bak

eşi mesut insanların yüzüne

güneşte alnı kırışana

hayatla her dem yarışana

terden sırılsıklam olana

ama insana insan olana

aç yüreğini aç ellerini kucakla

kucakla hayatın içindekilerini

ve d ı ş ı n d a k i l e r i 

12.08.1994 kırca', 'bir elin yere dönük bir elini aç gökyüzüne tıpkı semazen gibi kapat gözlerini elinin altındakileri düşün sonra üstündekileri dur sıyrılıp çı...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/semazen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-fevzi-gunenc-dhy68', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Resmini görünce kırmızı güller açıyor yanaklarımda

içime serinlik doluyor

inciye dönüşüyor dişlerim

ağzım kulaklarıma varıyor

seninle ben oluyorum belki bir yerde

benimle sen olduğunu sanıyorum biraz da...

Bir resim nasıl da yakınlaştırıyor uzakları

hiç bir resme bakınca böyle güzel olmamıştım.', 'Resmini görünce kırmızı güller açıyor yanaklarımda içime serinlik doluyor inciye dönüşüyor dişlerim ağzım kulaklarıma varıyor seninle ben ol...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/resim-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşeli türküleri yükselmiyor', 'neseli-turkuleri-yukselmiyor-salih-erdem-x2x5z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yırtılan ağları diker gibi

bağlarız geceyi gündüze

tek şahidimiz yıldızlar

umudu sereriz inatla

sessizce dökülür dualar

nazına kahpeliğine

keskin bir poyrazla

pulları dökülür göğün

acısı dayanılmaz

suyuna düşer gülümüz

sigara altına bir demli çay

umut olsun türkümüz

hani coşkun ak köpüklü dalgalar

nerede rengini verdiğin

salkım saçak yosunlar

anamız yarimiz

sanki eski sevdalara küsmüş gibisin

biz yine o eski belalın

ama

artık sen bize yar değil gibisin

ey martılar

peşlerine takılmayın teknelerin

neşeli türküleri yükselmiyor dönenlerin

16.06.1994 kırıkhan', 'yırtılan ağları diker gibi bağlarız geceyi gündüze tek şahidimiz yıldızlar umudu sereriz inatla sessizce dökülür dualar nazına kahpeliğine k...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neseli-turkuleri-yukselmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-meyus-cetin-vjaaj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni var ya benden sorsalar

Yüreğimden binlerce kere oklasalar

Bir tutam saçın için vursalar

Uğrunda yıllarca kırbaçlasalar

Bir sen varsın sen', 'Seni var ya benden sorsalar Yüreğimden binlerce kere oklasalar Bir tutam saçın için vursalar Uğrunda yıllarca kırbaçlasalar Bir sen varsın s...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-594-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler', 'turkuler-salih-erdem-9olif', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kokusunu taşırsın tomurcuk baharın

titreşir tellerinde canlanır çiçekler

eşkıya türeyince ak karlı dağların

başkaldırır dizelerin isyanı söyler

başın hoş olmadı zulümle esaretten

yaktın ateşini aydın sivas antepten

genç osmandın düşmedi al sancak elinden

vurunca teline barut kokusu tüter

pir sultanı emrahı karacaoğlan’ı

çamlıbelden duyulur köroğlu fermanı

dillerde tarihin tek silinmez destanı

ezgi tünelinden sıralanırda geçer

göçler dizilir katarla avşar elinden

yıldız dağında dumanlar binbir kederlen

acılı bir feryattır yemen çöllerinden

bağrı yanık anaları bilirde seçer

aşıkların sözü geçer de dağa taşa

güzellerin inatçıdır gelmez imana

bir bakıştır köy yolunda çeşme başında

sevdalar söze gelir de söyleşir diller

ırmaklar sevişip ummana yol buldu mu

kabarır dalgalar hayat gönül coşkusu

girdi mi araya bir ayrılık oyunu

yakar hasretlik rüzgarın gurbetten eser

ihtiyarların gönlünde gençlik baharın

sitemler sel olur gürül gürül çağlarsın

yetim yavruları sıcak sarar kolların

söylenir yıllar yılı uyutur ninniler

görmeyen gözlerin yolu rengi ışığı

tohumu kara toprağın hakkın aşığı

ölümde ayrılık bir kapıyı çaldı mı

acı ağıtlar yakılır mevlaya gider

kuşların gibi hür vursun tellere eller

söylensin aşklar dostluklar dikenli güller

varsın ak yamalık vursun suskun güzeller

kovulmasın vurulmasın söyleyen diller

kalpte yandıkça rüzgarsız dumansız ateş

yurdum dört yanın olur ana bacı kardeş

her gecenin sonunda doğsa da bir güneş

hiç susmasın çalınsın söylensin türküler

22-23.02.1995 safranbolu', 'kokusunu taşırsın tomurcuk baharın titreşir tellerinde canlanır çiçekler eşkıya türeyince ak karlı dağların başkaldırır dizelerin isyanı söy...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/turkuler-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluş', 'kurtulus-oguz-yirmibes-ezzjh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uçurumun kenarında atlamayı beklemek

Yeni doğan sabahı izlemek gibidir

Biraz sonra öleceğini bile bile 

Onun içine girmektir

Ağlamak sabırsızlıktan yada korkudan

Yorulmak beklemekten 

Sıkılmak artık bu bekleyişten

Kararlı olmayı isterken 

Kendini karasızlığın en dibinde bulmak

Ve mutlulukları artık arka cebine koymak

Susturulmuş olmayı hissederken 

Susturmakla suçlanmak

Seslenirken ölüm, kulaklarından ruhuna

Ve yakaladıysa seni

Beyninden kalbe giden yollarda

Aşkın bile engelleyemiyorsa olanları

Daralıyorsan onca özgürlüğün içinde

Bitmiştir artık her şey

Ve hayat dediğin labirentin 

Son sokaklarından geçiyor son odalarına giryorsundur

Bu yeni günün sana verdiği

Yada verebileceği tek şey

Kurtuluş...

Kurtulmak bütün bu olanlardan

Belki biraz canın yanacak ama 

Kurtulacaksın artık o yalnız akşamlardan', 'Uçurumun kenarında atlamayı beklemek Yeni doğan sabahı izlemek gibidir Biraz sonra öleceğini bile bile  Onun içine girmektir Ağlamak sabırsı...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kurtulus-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam içinde anlamda gizem perdesi kaldırılışı diyaloğumsu parçalaması', 'anlam-icinde-anlamda-gizem-perdesi-kaldirilisi-diyalogumsu-parcalamasi-akin-akca-khv9b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'A: “Herkeste biseps vardır.”

B: “Hayır, herkeste triseps yoktur! ...”

B: “Bazıları, doğarken kolsuz da doğabilir.”

-

Biseps olayındaki anlamla,triseps olayındaki anlam hafif bir anlaşmazlık ortamı doğuruyor gibi gözüküyor ancak (belki de)  bu karmaşanın “kolsuzluk” olayıyla bağdaştırılarak açıklanması duruma belli bir düzen getiriyor. Sonuç olarak, yapışık doğan ikizler veya kolsuz doğanlar hatta veya sonradan bacaksız (!)  denilecek olan veletler :)  hayatın kendisi anlamınca, (onlar da)  çelişmiyor kendileriyle, fakat bazenleri insanlar tarafından doğaya aykırı olarak addedilebiliyor. Aklıma geldi. Çabuk anlatılması sebebiyle, ne kadar açıklayabildi bilmem

Yani, ilk iki dizedeki biseps triseps olayı belli bir karmaşa iken sanki, son dizedeki çolaklık ise daha bir karmaşaya götürüyor gibi. Fakat bu, kaotik ortamı durultacak gerçek bir gerçek.. v.s.

Bu, bu şekil açıkladığım ilk ve bu şekil açıklayacağım son diyaloğumsu :)', 'A: “Herkeste biseps vardır.” B: “Hayır, herkeste triseps yoktur! ...” B: “Bazıları, doğarken kolsuz da doğabilir.” - Biseps olayındaki anlam...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlam-icinde-anlamda-gizem-perdesi-kaldirilisi-diyalogumsu-parcalamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bej', 'bej-akin-akca-fo7qg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bej üzerine griler serpiştirilmiştir,

Uzaydaki ak noktaları gibi yıldızların.

Sonra geçirilen üzre, penye kazak; 

Pembedir onun rengi, 

ama takıştırılır merserize tercihan; 

böylece bir espri konu olur –

Ankara Oran yolunda; 

Mavi dolmuşta gibi, he ha ha…

Budur, ayrılık gelir.

Ne var ki, baştaki bejdir.

Başlı başına ya da basil başına –

O canım, sen, bir başına! 

- grinin tonları (bu)   değildir.

Halbuki beje, Az ak katılmıştır.

Değil fazlasından,

Mermer taşlı mezar değil.

Beyaz değil bütünüyle:

Su gibi ama

Ve/ ancak Hayatın renkleriyle de,

Beşiğin saf sallanışıyla.

O halde, haydi az solfej! 

Ne çıkar şan dersinde

Az düşünmekten sanki? 

Gitar hala tıngırdatacak! 

Zaten gönlün susmayacak! 

Suçlayacaksa da, yap sen, tek! 

Işık üzerine sürüştürülen bej; 

İster gül tarlası, kırmızı ruj.

Sevinç, hepten zaten senin elinde; 

Bunu, vakit ayırıp düşündüğünde.

-

Başlık üzerine bir link :)

http://www.stilmoda.com/bay.asp', 'Bej üzerine griler serpiştirilmiştir, Uzaydaki ak noktaları gibi yıldızların. Sonra geçirilen üzre, penye kazak;  Pembedir onun rengi,  ama ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bej-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş boğazlık bilmez Göz-Geveze Balıklar', 'bos-bogazlik-bilmez-goz-geveze-baliklar-akin-akca-s1otc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün

Balıkların fotoğrafını çektim

Sakarya’da, 

cep telle:

Şaşkındı buna balıkçı, ulu orta; 

diğer balıkçılar da şaşkındı,

geriden izleyen seyirciler de.

Balıklar,

uykuda ölmüş gibi uzanmış.

Demek, cıvıl cıvıl yaşam için 

uyanmış ve güzelleşmişler

şuurlu; yaşam kaynatıyorlar! 

Onların,

yuvarlanmıyordu tabi ki,

gözbebekleri. Balıkçılar ama 

coşku içindeydi:

Kendi sevinçlerini balıkçılara 

kanalize etmişlerdi ve 

mutluluklarını, tüm umutlarını.

*

Onlar,

(Burda o, her gün geçerken görürüm) 

sanki, bacağını gerçekten kaybetmiş 

ama dilenci insanların önünde

tevazuyla geçit törenindeler.

Ve herkes gibi aldırmaksızın,

geçip gidiyorlar yollarına …

Doğru, 

dilenmekle bağdaşmaz ki bu dilenme 

durumu: 

Balıklar ancak; ‘hayatta kaybetmiş de

düşünemedikleri için’ 

‘o dilenciler, bastonuna tek eliyle 

asılı titreşip duran gözüken 

bu bacaksız çolakları’; 

“evlerine kapanmıyor 

dilenciler” diyebiliyorlar.

Çünkü

–onları cansız 

görebilirken bazıları-

acı çekenler için onlar,

göz yaşı dökebiliyorlar

-

Açıklama:

Not: fotoğraf çekilmedi, ancak bakış fırlatıldı

Onlar=onları: balıklar', 'Bugün Balıkların fotoğrafını çektim Sakarya’da,  cep telle: Şaşkındı buna balıkçı, ulu orta;  diğer balıkçılar da şaşkındı, geriden izleyen ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bos-bogazlik-bilmez-goz-geveze-baliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ram Bellek', 'ram-bellek-meyus-cetin-0huef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendimi dolar işaretleri ile

Açılmış yedek word dosyaları

Bir ucu kapatılmamış bir parantez

Yüklemi olmayan cümleler 

Bayraksız bir direk

Gece yatmadan hayal kuran insan kadar

YALNIZ, BOŞ HİSSEDİYORUM', 'Kendimi dolar işaretleri ile Açılmış yedek word dosyaları Bir ucu kapatılmamış bir parantez Yüklemi olmayan cümleler  Bayraksız bir direk Ge...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ram-bellek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürken', 'urken-gokhan-oflazoglu-i4c2e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzgün yıl geldi işte saklandığı kuytudan.

Sevinçler de taşır, burkar, kırar da.

Kaldığımız yerden sürer sarsak, savruk

günlerimiz; biz herşeyi anlamışken birden

yiteriz. Gene boş bir beyaz kağıt, eski

bilgelikler akar derinden, boşluk neler öğretir, 

bıkmaz ısrarla isteriz, daha erken. Susun,

burda söyleyecek fazla bir şey yok.

Dil uzar türkü olur, ne dinlesek erken.

Haykırın o zaman, bitsin sızısı dev gözün,

hem gören hem ürken.

26/07/2005', 'Üzgün yıl geldi işte saklandığı kuytudan. Sevinçler de taşır, burkar, kırar da. Kaldığımız yerden sürer sarsak, savruk günlerimiz; biz herşe...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/urken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtar! ...', 'i-htar-asima-azra-wndnk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz sedasız bir denizin boylamlarında

Kulaçlarıma vuran rüzgârların yaşıydı

Ben sudan yeni çıkmış balık şaşkınlığında

Karadaki durumum bu aşkın açılımıydı

Oysa bilekleri sargılı bir hayatta

Tek iz kalmama ihtimali kadarken aşk

Ve karanlığa kurulmuşken tüm saatler

Vaktinden önce çalan da isyanın alarmıydı', 'Sensiz sedasız bir denizin boylamlarında Kulaçlarıma vuran rüzgârların yaşıydı Ben sudan yeni çıkmış balık şaşkınlığında Karadaki durumum bu...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ihtar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyelim', 'soyleyelim-gokhan-oflazoglu-9jf98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kavrarım ruhum da

terkedecek, kalacağım

boş beden. Türküsüz

yanan meşale aydınlatmaz,

bu yol da bitmez, ulaşmaz.

Ruhum, ben, bedenim.

Bu türküyü birlikte

söyleyelim.

26/07/2005', 'Kavrarım ruhum da terkedecek, kalacağım boş beden. Türküsüz yanan meşale aydınlatmaz, bu yol da bitmez, ulaşmaz. Ruhum, ben, bedenim. Bu tür...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/soyleyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi', 'birisi-halil-colak-btu89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birisi var ki öyle bir birisi 

Deli mi divane mi anlayamadığım birisi

Gerçek mi sahte mi kavrayamadığım birisi

Yandırdı aşkıyla beni öyle bir birisi

Benim maneviyatım mı? 

Yoksa hayatım mı? 

Derdim mi dermanım mı? 

Cayamadığım birisi

Kimi ne eş 

Kimi ne dost

Kimi ne ise kardeş 

Benim neyim olur soramadığım birisi

Aşkıyla yandırır 

Bakışıyla söndürür

Tek sözüyle öldürür

Beni mahvı perişan etti birisi

Ömrümün baharı 

Derdimin dermanı 

Yaramım merhemi

İşte o birisi

Halil çolak 26.7.2005', 'Birisi var ki öyle bir birisi  Deli mi divane mi anlayamadığım birisi Gerçek mi sahte mi kavrayamadığım birisi Yandırdı aşkıyla beni öyle bi...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birisi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-gokhan-oflazoglu-ecojx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir resimle başlayabilirsiniz

resmetmeye hayatınızı.

Kanatlanan bir martı olabilir,

damarları belirgin bir yaprak.

Bazen bir resim biz, ya da

biz resim gibiyiz.

26/07/2005', 'Bir resimle başlayabilirsiniz resmetmeye hayatınızı. Kanatlanan bir martı olabilir, damarları belirgin bir yaprak. Bazen bir resim biz, ya d...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/resim-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eridim tükendim sarardim', 'eridim-tukendim-sarardim-muhammed-murad-uzun-tjq39', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Var sizim var acim daraldim

Yanlizim bahdsizim bunaldim

Yarsizim asksizim yiprandim

Eridim tükendim sarardim

Gücendim itildim kirildim 

Vuruldum bozuldum yikildim 

Tutuldum tutustum yakildim

Eridim tükendim sarardim

Sizlarim vahlarim aglarim

Ölürüm caglarim yasarim

Yanarim cosarim yazarim

Eridim tükendim sarardim', 'Var sizim var acim daraldim Yanlizim bahdsizim bunaldim Yarsizim asksizim yiprandim Eridim tükendim sarardim Gücendim itildim kirildim  Vuru...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eridim-tukendim-sarardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esma''ül-Hüsna', 'esma-ul-husna-mikdat-bal-9yu0w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah vardır birdir O, ortağı, benzeri yok

Her şeyi yaratan O, bize nimetleri çok

Odur bizi dirilten, Odur bizi öldüren

Odur bizi ağlatan, Odur bizi güldüren

Rızkımızı veren O, Odur bizi besleyen

Hidayet eden Odur, Odur bizi sesleyen

Dilediğini aziz ederek yücelten O

Dilediğini zelil ederek küçülten O

Geceyi yaratan O gündüzü yaratan O

Her şeyi aydınlatan her şeyi karatan O

O ezeldir, evveldir, O ebettir, ahirdir

Aşikardır, gizlidir, hem batın hem zahirdir

O Alimdir Habirdir, her şeyi bilen Odur

Kaderi O yazmıştır, ekleyen silen Odur

Kafir mü’min demeden, her cana rızık veren

RAHMAN sıfatı ile, rahmetini gönderen

RAHİM dir, mü’minleri, mağfiret eden Odur

MELİK tir, alemlere, yanlız hukmeden Odur

KUDDÜS dür, O her şeyden münezzehtir uzaktır

SELAM dır, selameti, bütün mahluka Haktır

MÜ’MİN dir, gönüllere imanı indiren O

Her kulunu kayıran, derdini dindiren O

MUHEYMİN dir, gözetip,her şeyi koruyan O

AZİZ dir, gücü sonsuz, besleyip doyuran O

CEBBAR dır, dilediği her şeyi yaptıran O

MÜTEKEBBİR, yücedir, kendine taptıran O

HALİK tır, mahlukatı ol emriyle var etti

BâRİ dir, denge kurdu, her şeyi karar etti

MUSAVVİR dir, her şeye ayrı bir şekil verdi

Hayvanata iç güdü. insana akıl verdi

GAFFAR dır, kullarına mağfireti pek çoktur

KAHHAR dır, azabına karşı çıkacak yoktur

VEHHAB dır, bahşeden o, sayısız nimetleri

REZZAK tır, besleyen O sayısız ümmetleri

FETTAH tır, müşkülleri zorlukları açan O

En büyük elemlere, rahmetini saçan O

ALİM dir, O her şeyi her şeyiyle bilendir

KABID dır, O zengini fakir yapabilendir

BASIT tır,  genişleten,  kulu zengin eden O

HâFİD dir, alçaltan O, RAFİ dir yükselten O

MUİZZ, izzet veren O, MÜZİLL,  zillet veren O

SEMİ dir, duyan Odur, hem BASİR dir gören O

HAKEM dir, O hükmünü, yerine getirendir

ADİL dir, adaletle, O hükmünü verendir

LâTİF tir, lütfeden O, HABİR dir haberdardır

O her şeyi biliyor, gizli ya aşikardır

HALİM dir, hilmi çoktur, AZİM azametlidir

ĞAFÜR dur, çok affeder, kula mağfiretlidir

ŞEKÜR dür, şükredene, daha çok ihsan eder

Her hale şükredenin işini asan eder

ALİYY dir, pek yüksektir, her şeyin üstündedir

KEBİR dir, pek büyüktür, her şeyin fevkındedir

HAFİZ dir, O her şeyi, koruyan kayırandır

MUKİT tir, her mahlukun rızkını ayırandır

HASİB dir, hatasızdır hesabında yanılmaz

CELİL dir, Celle şanuh, hiç bir mekana sığmaz

KERİM dir, keremi bol, RAKİB dir gözetler O

MÜCİB dir, düalara, hem icabet eder O

VASİ’ dir, çok geniştir, müsaadekârdır O

HAKİM dir, her işinde çok hikmeti vardır O

VEDÜD dür, hem sevilen, hem de sevdiren Odur

Muhammed Mustafayı bize övdüren Odur

MECİD dir, şanı yüce, BAİS tir diriltendir

ŞEHİD dir, her olayı görüp te bildirendir

HAKK tır, O bir gerçektir, ezeli ve ebedi

VEKİL dir, kullarına her kim tevekkül etti

KAVİ dir, pek güçlüdür, METİN dir pek sağlamdır

VELİYY dir, kullarına, en iyi dost olandır

HAMİD dir, hamdolunan, senayla öğülendir

EL-MUHSİ, O her şeyin sayısını bilendir

MUBDİ, mahlükatını yoktan var eden Odur

Örneksiz bir şekilde, Kün’le yaratan Odur

MUİD, tekrar yaratan, MUHYİ can, ruh verendir

EL-MUMİT, her canlıyı, hikmetle öldürendir

EL-HAYY, kendi yaşıyor, mahluku yaşatıyor

EL-KAYYUM, yeri göğü, tutuyor kuşatıyor

EL-VACİD, ne isterse, anında onu bulur

EL-MACİD, kullarına, hesapsız lüyfu olur

VAHİD, yoktur benzeri, tektir ortağı yoktur

SAMED, O tek mercidir, ihsanı boldur, çoktur

KADİR dir, O her şeye gücü yeter, MUKTEDİR

Her zalimi yok eden, nihayetsiz güçtedir

MUKADDİM dir, dilerse bir şeyi öne alan

MUAHHİR dir, tehire gücü yetkisi olan

EVVEL dir, başlangıcı yoktur ilktir, ezeldir

AHİR dir, sonu yoktur bu Allah’a özeldir

ZAHİR dir, gören gözler, Onu her yerde görür

BATIN dır, O gizlidir, kalbe gönüle sürur

VALİ dir, alemleri, tek başına yönetir

EL-MÜTEALİ dir O, O herşeyden yücedir

EL-BERR dir, kullarına her şeyi bahşedendir, 

ET-TEVVAB,  tövbe eden kulunu affedendir

MÜNTEKİM dir, zalimden intikamları alan

AFÜVV dür, çok affeden, bağışlaması olan

RAÜF tür, kullarına kolaylık, ihsan eder

Kerem ve re''fetiyle, işleri asan eder

O tek MALİKÜ’L MÜLK tür, her şey onun mülküdür

Mülk onun varlık onun alemlerin ilkidir

ZÜ’L-CELAL-İ VE’L-İKRAM, fazlı keremi çoktur

MUKSİT tir her işinde tesadüfe yer yoktur

EL-CAMİ, toplayandır, toplar neyi dilerse

ĞANİYYdir,  çok zengindir bitmez ne kadar verse

EL-MUĞNİ, zengin eder dilediği kimseyi

EL-MANİ, engelleyen istediği her şeyi

DARR dır, elem verici şeyleri yaratan O

Bunlar bir imtihandır, çareyi aratan O

NAFİ dir, her menfaat  verenleri yarattı

EN-NUR dur, gönülleri, semaları nur etti

EL-Hâdi, doğru yola kullarını iletir

BEDİ dir, yaratandır  “ol”  demesi iledir

BAKİ dir, varlığının sonu  yoktur mülk Onun

VARİS tir, her şey onun, son da Onun ilk Onun

REŞİD, hikmet sahibi, ezeli takdir ile

SABÜR, çok sabırlıdır, en yüce sabır ile', 'Allah vardır birdir O, ortağı, benzeri yok Her şeyi yaratan O, bize nimetleri çok Odur bizi dirilten, Odur bizi öldüren Odur bizi ağlatan, O...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":114,"source_url":"https://www.antoloji.com/esma-ul-husna-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemle Yaşamak', 'kalemle-yasamak-ozan-ozel-wxg0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimisi var

kalemiyle dost

iç içe 

aldatmadan 

ve aldanmadan

harf harf

satır satır 

yaşar

kimisi var

kalemiyle küs

hatta kavgalı

yalan yanlış

tekme tokat

anlamsız 

soru işaretleriyle

yaşar! 

kimisi sen

kimisi ben...', 'kimisi var kalemiyle dost iç içe  aldatmadan  ve aldanmadan harf harf satır satır  yaşar kimisi var kalemiyle küs hatta kavgalı yalan yanlış...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kalemle-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asabi - Meçhul Kitabından', 'asabi-mechul-kitabindan-omer-ekinci-micingirt-lt4s3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahtekârlara tahammül edemeyenlere "asabi" diyorlar. Micingirt

​Asabi

​Sokaklar çilesiz, ruhlar kaygısız

Dilim isyan demez ama asabi

Dede ganyan oynar, torun saygısız

Haram yiyor yavru, meme asabi

​Bu mudur istikbal, bir akıl verin

Gerçek mi, vehim mi, hakikat serin

Keyfiyet zehirli, irade derin

"Şu Boğaz Harbi"nde Şam''a asabi

​Kavga ütopyalar nifak kin, birlik

Sefalet paye şan haytalık şerlik

Kâbuslar tufanlar, izm’e askerlik

Meydan okur zındık, dine asabi

​Abdın terazisi bozuldu kinden

Ki öksüz hakikat, bihaber dinden

Hamal ipten kaçar, hasat ekinden

Yalancı yatsıya, muma asabi

​Doğru can çekişir kizbin sisinde

Ve zillet revaçta kirli basında

Vampirler kan içer her defasında

Bir sorun Ömer’e kime asabi', 'Sahtekârlara tahammül edemeyenlere "asabi" diyorlar. Micingirt ​Asabi ​Sokaklar çilesiz, ruhlar kaygısız Dilim isyan demez ama asabi Dede ga...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/asabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ağla', 'gul-agla-i-lhan-koruyucu-jop4b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül Ağla

Hayatın zorlukları olsa da,

Gülmek isterim ben kendim.

Ama bazen öyle zor ki dünya

Ağlamak olmasa ne de zor olurdu...

.......

Kanarak ağlayabilsem içtenlikle,

Dağlayarak, merhem olan varsa

Yine de mutlu olur sevinirim

İçtenlikle öyle yada böyle gülsem de! 

.......

Çılgınca düşüncelerime bir kötek,

Bayat ekmeği yiyerek

Birlikte gülmek yada ağlamak

Paylaşarak, anlaşarak gülsek yada ağlasak...

İlhan KORUYUCU', 'Gül Ağla Hayatın zorlukları olsa da, Gülmek isterim ben kendim. Ama bazen öyle zor ki dünya Ağlamak olmasa ne de zor olurdu... ....... Kanar...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-agla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kız', 'gul-kiz-vecdi-murat-soydan-la1y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ondördünde  kocaya gittiğinde,

Oyun sanıyordu evliliği zahir.

Evcilik oynarım diye,

Oyuncak bebeğini de götürmüştü.

Bir anası ağladı ardından.

Gerisi, yalan ağladı.

Babası Tilki Süleyman,

Bir tomar gavur parasına  sattı gül gibi kızı.

Traktör alacaktı başlık parasına.

Kocası sidikli Nuri

Gerdek gecesi,

Kız çıkmadı diye

İt kovalar  gibi 

Tekmeleyip, atıverdi  kapının önüne.

Gül kız…

Ağladı, yalvardı.

Kusur bende değil dediyse de,

İnandıramadı kimseyi

Baba evine döndü garibim

Zulüm gördü, işkence gördü.

Yine de sesini çıkarmadı 

Babası,satılığa her çıkarışında 

Defolu mal misali geri geldi.

Horlandı, dışlandı.

Borsa misali,

Değeri de düştü Gül kızın

En son Hacıların Ömer’e gelin gittiğinde

Kapıdaki uyuz eşek bile para etti de

Kendi para etmedi.

Bir kat giysiyle  bir çift terlikti sermayesi.

Talihi gibi, yüzü de gülmedi,

Kocası hem alkolik, hem kumarbazdı

Altı aya kalmadı, en son tarlayı da 

Kumar masasında bıraktı

Daha da yetinmedi

Bankadan ipotek yapar gibi

Sözleşme yaptı kavatlarla.

Ya karını alırız altından, ya  canını dediler

Canı tatlı geldi piçin.

Gül gibi karısını, alemin çakallarına

Kendi eliyle verdi.

Kurtlar sofrasına düşmüştü bir kere.

Vücudu,  sermayesi olmuştu nasılsa.

Bu kahpe dünyada, 

Kahpece yaşamak ona göre değildi.

Ödenmiş veya ödenecek tüm bedelleri

Küçücük yüreğine sığdırmıştı.

Yüreği yaralı,  bahtı karalıydı

Nerde akşamsa, orda sabahlamak vardı

Tiksinti verici de olsa,

Kaderde, yüzlerce  kocayla yatmak da vardı.

Kimi eğlendi,  kimi alaya aldı

Kimi sofrasında meze yaptı.

Kimi  de bir gecede imam nikahı kıyıp

Sabaha boşadı.

Bu gün Karaköy’de görürsünüz Gül kızı,

Yarın  Bend deresinde.

Öbür gün bir meçhule gidecektir nasılsa.

Gül kız kim diye sorarsanız tanımazlar.

Adı Kader’dir  Gül kızın.

Ah benim açmadan solan tomurcuk gülüm.

Ah benim talihsiz  kınalı kuzum

Yüreğim yanıyor,

Bataklıkta açan,

Bilmem kaçıncı güldür bu.

Kaderin Kader’e oynadığı 

Bilmem kaçıncı oyundur bu.

Sen utanma bacım

Baban utansın 

İstanbul utansın

Yurdum utansın

Sen ağlama bacım

Bir ben ağlayayım,

Bir de anan ağlasın.

Bir ben yanayım sana

Bir de baban yansın ahir dünyada.

Vecdi Murat SOYDAN

26/05/2005-Mihalıççık/ESKİŞEHİR

sebahat akkiraz - DEÐ ME FELEK', 'Ondördünde  kocaya gittiğinde, Oyun sanıyordu evliliği zahir. Evcilik oynarım diye, Oyuncak bebeğini de götürmüştü. Bir anası ağladı ardında...', ARRAY['Türk Edebiyatı','Şiir','Vecdi Murat Soydan']::text[], 8.5, '{"poet":"Vecdi Murat Soydan","poet_slug":"vecdi-murat-soydan","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/gul-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla', 'hatirla-gulseren-onay-x45rl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutamazsın belki,

Ama 

Sızlanma biten aşkın ardından...

Elbet

Dinecek sağnak,

Kasırganın uğultusu susacak...

Hatırlasana

Dünya da yangındaydı

Güneşten koptuğunda....

GÜLSEREN ONAY', 'Unutamazsın belki, Ama  Sızlanma biten aşkın ardından... Elbet Dinecek sağnak, Kasırganın uğultusu susacak... Hatırlasana Dünya da yangınday...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hatirla-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-zuhal-aksulu-uhcyd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzun zamandan beri ilk defa yıkmıştım oysa içimdeki duvarları.. Kimsesiz ruhumu ve yorgun kalbimi tüm siyahlardan, soğuklardan koruyan duvarları..... 

Dokunmadan gitti kalbime.. Ruhuma.. Sıcağıma... 

Yok şimdi duvarlar içimde.. Sadece üşüyen, titrek bir kalp ve asi ruhumun gariban çığlıkları var... 

Belki duyar... 

Belki.. 

Belki duvar...', 'Uzun zamandan beri ilk defa yıkmıştım oysa içimdeki duvarları.. Kimsesiz ruhumu ve yorgun kalbimi tüm siyahlardan, soğuklardan koruyan duvar...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/duvar-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gariban Çığlıklarım', 'gariban-cigliklarim-zuhal-aksulu-zc35l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karşımda duvar olsa ağlardı

Benim şu gariban çığlıklarıma

Taş mısın be mubarek

Kalbimin sesini duysana', 'Karşımda duvar olsa ağlardı Benim şu gariban çığlıklarıma Taş mısın be mubarek Kalbimin sesini duysana...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gariban-cigliklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız', 'yildiz-zuhal-aksulu-9tfj3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece bir yıldız kaydı

Süzüldü gecede sessizce

Onda kaçırdığın gözlerini gördüm

Gözlerime bakarken ilgisizce...', 'Dün gece bir yıldız kaydı Süzüldü gecede sessizce Onda kaçırdığın gözlerini gördüm Gözlerime bakarken ilgisizce......', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yildiz-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandım', 'sandim-zuhal-aksulu-9cuzz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdim

Sevildim sandım

Geldim

Benimsin sandım

Gittim

Gelirsin sandım

Sevmedin, gelmedin

Cehennemde kor gibi yandım...', 'Sevdim Sevildim sandım Geldim Benimsin sandım Gittim Gelirsin sandım Sevmedin, gelmedin Cehennemde kor gibi yandım......', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sandim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum', 'dogum-asya-yildiz-tcoyk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki dudak arası sevgi kustum,

İlk aylarım çok ağırdı sevgili...

Keskin bir sancı yokluğunu sarıp

Acımasız parçalıyordu beyin hücrelerimi.

Gecelerim sevdama ninni söyleyerek geçti,

Gündüz düşlerimde ismini sayıkladım.

İki dudak arası kustum sevdamı

İlk ayların kimyasal tepkimesi buydu.

Yeryüzüm yeni bir iklime teslim şimdi,

Büyük, beyaz ve masum bir bulut evim,

Bahçemde kırçiçekleri güneşle cilveleşir.

İçimde bir ''canım'' can, yüreğimle beslenir,

Yükledim özleminin kanatlarına müjdemi,

Okyanustan aşırıp yıldıza haber verdim.

Katık yapıp gözlerini doyurdum kendimi,

Yine kazındı midem, tuttum, öptüm, kokladım

Geride bıraktığın aşk kokan hatıraları.

Ne yapsam doymuyorum! Ah ne doyumsuzum! 

İçim hala çocuk, ben hala kadınıyım aşkın

Yüreğimi yüreğine yaslayıp besliyorum geleceği.

Bir geceydi ve gözlerime uyku girmemişti,

Nefes aldırmayan, sıcak bir Temmuz gecesi.

Titriyordum, üşüyordum, terliyordum, anlıyordum

Vakti gelmişti işte, sancılar yolumu çiziyordu.

Yumup kara gözlerimi, doğurdum aşk bebeğimi

Kanımı akıtıp yeni bir sayfa açtım hayata...', 'İki dudak arası sevgi kustum, İlk aylarım çok ağırdı sevgili... Keskin bir sancı yokluğunu sarıp Acımasız parçalıyordu beyin hücrelerimi. Ge...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dogum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Ölümü Göze Almaz mıydım?', 'senin-i-cin-olumu-goze-almaz-miydim-huseyin-erdogan-1z0ob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bil ki artık sensiz yapamıyorum

neredeyse nefes bile alamıyorum

sakın abarttığımı zannetme

galiba ben sana aşık oluyorum

bir gün beni sevdiğini söylersen

heyecandan tir tir titrer bedenim

beni sevinçten uçurmak istersen eğer

haydi sevdiğim bunu bir deneyiver yeter

ah! o güzel yüreğine bir girebilsem

rengarenk güller karanfiller açabilsem

bir daha hiç solar mıydım canım? 

o güzel sıcacık ellerini bir tutabilsem

ölünceye değin hiç bırakır mıydım? 

söyle sevdiğim söyle  aşkım

senin için ölümü göze almaz mıydım? 

                                  26.07.2005', 'bil ki artık sensiz yapamıyorum neredeyse nefes bile alamıyorum sakın abarttığımı zannetme galiba ben sana aşık oluyorum bir gün beni sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-olumu-goze-almaz-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A n a m', 'a-n-a-m-necati-keceli-i8nsc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Toprak seni bizden aldı, alalı

    Bir daha şu yüzüm gülmedi anam

    İçim de hasretin kaldı, kalalı

    Bir daha şu yüzüm gülmedi anam

    Aklıma geldikçe içim kanıyor 

    Geçmiyor özlemin yürek yanıyor

    Bir gün gelecekmiş gibi sanıyor

    Bir daha şu yüzüm gülmedi anam

    Canından can verip beni büyüttün 

    Ninniler söyleyip diz de uyuttun 

    Bana yol gösterip elimden tuttun 

    Bir daha şu yüzüm gülmedi anam

    Damla, damla kanın var bedenimde 

    Miski amber gibi kokun tenimde 

    Sadece hayalin kaldı beynimde 

    Bir daha şu yüzüm gülmedi anam

    Sarılıp öperdin karnım doyunca 

    İçim rahatlardı sesin duyunca 

    Unutmak mümkün mü ömür boyunca 

    Bir daha şu yüzüm gülmedi anam

    Hiç kimse biçemez kıymet bedeli

    Resimler olmasa, olurdum deli 

    Hayalin yaşattı gittin gideli 

    Bir daha şu yüzüm gülmedi anam

    Bizleri dünyaya getiren cana

    Can veren bedene ruhuma kana 

    Necati der, ana diyelim ana 

    Bir daha şu yüzüm gülmedi anam

    Necati KEÇELİ

    İZMİR', 'Toprak seni bizden aldı, alalı     Bir daha şu yüzüm gülmedi anam     İçim de hasretin kaldı, kalalı     Bir daha şu yüzüm gülmedi anam     ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/a-n-a-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nef’i', 'nef-i-emrah-pelvanoglu-jv32n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'suyu yormalı derken suya

	düştü o baş ağrısı

gölgeni gövden oydu kaç yola

mübalâğa bir idam

sen Ömer’di bil bu başkası

hem günah hem kahır hem bir i’lamdır ölüm

yüzün isyanla güllere mağrur 

bu ne düzen bu ne dirlik bu ne devran olsun

gururlusun ve tövbende bir kaza

“sen hünkârım çok yaşa, soyun kurusun”

hem dua hem ilenç hem bir asidir ölüm

şehr-i âlem tükendi ki sen

mavi bir fahriye gibi

her ne söylediysen cevabı 

“len teranî” olsun

ah şu fermanı yok bilen 

hükmü adil yaslı zaman

balıklara gömsün seni oysa

hem suç hem ceza hem bir adalettir ölüm', 'suyu yormalı derken suya 	düştü o baş ağrısı gölgeni gövden oydu kaç yola mübalâğa bir idam sen Ömer’di bil bu başkası hem günah hem kahır h...', ARRAY['Türk Edebiyatı','Şiir','Emrah Pelvanoğlu']::text[], 8.5, '{"poet":"Emrah Pelvanoğlu","poet_slug":"emrah-pelvanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nef-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-fidan-bulut-bxd73', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üzülme anne; 

Güneşle ay arası zamanda

Göle maya çaldım.

Üzülme anne; 

Ben yarınımı bu günden aldım.

Unutmazsın bilirim

Sadece bunu da bil

Ben onurumu kirpiğinin ucundan,

Yüreğimi dik başından bulmuşum.

Sevdamı yanına yolladım

Onu ancak sen saklarsın......

Hatırlar mısın bana o kızı alacaktın

Onun gül düşlerini ona, yüreğimi sana bıraktım

Sormayacağım yediğin dayakların devamını

Öğrendim anne acıtanın tekme tokat olmadığını..

Utandım anne

Nasırlı ellerini hocamdan saklamanı istediğim

Ak örtünü hor gördüğüm için

Şerefinmiş bilemedim

Kırılma anne cahillik işte........

Sev demiştin anne

Ben isyanlarda seni seyrederken

Nasıl hala gülebildiğine şaşarken

Sev demiştin...

Oysa 

Gül yüzünde açan kan çiçekleri

Bana yol oldu sandım,

Gücüm yetecekmiş gibi

Her şeyi yeni baştan yazacaktım.

Sevmekmiş anahtar kelime

Bize verilen kitaplarda yazmayı unutmuşlar.

Haklıymışsın anne

Sevmek 

Dünya kadar dünya olmak

Sevmek çıkarsızca

Hayattan sonra hayat olmak

Üzülme anne

Korkmuyorum artık ölümden

Hala korktuğum karanlık kadar.........', 'Üzülme anne;  Güneşle ay arası zamanda Göle maya çaldım. Üzülme anne;  Ben yarınımı bu günden aldım. Unutmazsın bilirim Sadece bunu da bil B...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/annem-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedavadan Az Pahalı', 'bedavadan-az-pahali-fidan-bulut-91gm9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimde bir kalp

Hiç kullanılmamış,

Bir ruh hiç okunmamış.

Bedavadan az pahalı,

Bir sıcak el karşılığı.

Umduğu

Bir kez de olsa

Döndüğünde arkasını

Gitme diyen bir ses olsaydı...............', 'Elimde bir kalp Hiç kullanılmamış, Bir ruh hiç okunmamış. Bedavadan az pahalı, Bir sıcak el karşılığı. Umduğu Bir kez de olsa Döndüğünde ark...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bedavadan-az-pahali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terör İslamda Olmaz', 'teror-i-slamda-olmaz-caglar-asik-1vsri', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmaz kardeşim, olmaz.

Terör, islamda olmaz.

Vardır diyenler, densiz.

Çamur atanlar, arsız.

&

Körle bir sanma, sakın.

Sabit fikirli, şaşkın.

Terör, islamda olmaz.

İslam, sevgisiz olmaz.

&

Bilgi, saptıran akım.

Sabit fikire tapkın.

İslam terörle esmez.

Gerçek, gün gibi bilmez.

&

İslam, başlara taçtır.

Gönlü dolanda, tahttır.

Nurla dolanan, vardır.

Terör, islamsız vardır.

&

Olmaz, islamda terör.

Durmaz, çamurla terör.

Almaz terörü islam.

Kirle, var olmaz islam.

&

Temiz olandır, islam.

Anmaz, terörü islam.

Olmaz, müslüman terör.

Ölsün, ağlatan terör.

&

Cahil, terörist olur.

Kafir, inaçsız olur.

Çamur atma, ne olur.

İslam temizde olur.

&

Ağlar, yürekler sözsüz.

Terör, islamsız, dinsiz.

Yapan terörist amma.

Sakın, islama çatma.

&

İstanbul – 26.07.2005

Çağlar Aşık – Terör İslamda Olmaz - (Hece:7)', 'Olmaz kardeşim, olmaz. Terör, islamda olmaz. Vardır diyenler, densiz. Çamur atanlar, arsız. & Körle bir sanma, sakın. Sabit fikirli, şaşkın....', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/teror-islamda-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Japon Gülü', 've-japon-gulu-dilek-kesgin-5fc0e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuruyan topraklardı belki,

Yağmur sonrası kokusuyla anıların içine sürüklercesine kızıl..

Tan ağarırken bulutlarla kucaklaşan güneşin süzüntüleriydi

Ve alacakaranlıkta umutla şafağı bekleyenin gözleri..

Kan kırmızısı..

Düşlerinin kuytusunda sıçradığında

Etrafı saran buğulu bir gece lambasının ışığıydı.

Ve Japon Gülü..

İlkokul sıralarında konu başlıklarını özenle yazdığı kalemiydi,

Bir de çantasında yük sandığı kitaplarının kaplığı..

Çingenenin kulağında raks eden o masum; ama bir o kadar da

İhtiras dolu çiçek! 

Giysileriydi, hiç üzerinden çıkarmadığı

Saklanırken iki dalın arkasına, oyunların gölgesinde..

Yeni giydiği yüksek topuklarla yürümeye çalışan bir tazenin 

Dudağındaki boyaydı, baştan çıkaran..

Yıllarca saklanmış tozlu bir defter arasında 

Ve hep güzellikleri, mutlu aşkları anımsatan bir gül goncasıydı,

Vazgeçemediği..

Yazmasının oyasıydı bir köylü güzelinin..

Ve yanakları..

Saçlarının kınasıydı alımının yanı sıra çeşme başında.

Son model bir otomobildi düşlerinde satın aldığı..

Sıfır kilometrede bir spor arabaydı belki de

Yaşamına güç katan hayalinin köşesindeki..

Ve nar gibi kızarmış dalında,

Isırılmayı bekleyen bir elma! 

Öyküsünün başlangıcı gibi,

Sonu da kırmızı bir çizgiden ibaretti..

Yaşama kırmızı bakmasının sebebi bu muydu? 

Onca sıkıntının arasında, hep yanan bir yürek taşırdı..

Belli ki, düşen korlardı içine, ayrılışlarda..

Ve hasretin şafakla birleştiği yerdeki o kırmızı çizilirdi yeniden..

Yine o kırmızı çizgiydi karşıma çıkan..

Bazen üç nokta; ama kırmızı...

Ve Japon Gülü! 

(Bostanlı, 27.08.2002)', 'Kuruyan topraklardı belki, Yağmur sonrası kokusuyla anıların içine sürüklercesine kızıl.. Tan ağarırken bulutlarla kucaklaşan güneşin süzünt...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ve-japon-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ölüm Gibi Seviyorum', 'seni-olum-gibi-seviyorum-dilek-kesgin-i6nyo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek, ölüm gibidir,

Ne zaman karşına çıkacağı belli olmaz! 

Ölen insan değer kazanır,

Ve sevince insana değer vermeye başlarsın! 

Seni bir ölüm gibi seviyorum..

Kendi ölümüm gibi..

Ne zaman seni sevsem beyaz giyiyorum, ölmüşüm gibi,

Sevdam kefenim oluyor.

Ne zaman seni sevsem siyah giyiyorum, ölmüşsün gibi,

Sevdam yasım oluyor.

Yeşili kırmızı, kırmızıyı yeşil görüyorum..

Kör oluyorum seni sevince..

Ben, kör olmayı seviyorum..

Seni sevince çıtırdayan bir şeyler oluyor içimde,

Yağmurlu havalarda ortaya çıkan salyangoza basıldığında çıkan sese benziyor biraz..

Ben ölmüyorum bu çıtırtıyla..

Yaşamıma yaşam katıyor içimdeki çıtırtılar..

Çaya batırıldığında, bir parçası kopup kalan bisküviye benziyorum şimdi..

Seni sevdikçe bir parçam hep kopuyor..

Hep, ‘Sen’ oluyor o parçam.

Yağmurdan sonra bir yaprak üzerinde eğreti duran su damlasıyım seni sevince..

Her yağmurdan sonra, sana süzülüyorum..

Sulandıkça uzayan sarmaşıklar gibiyim..

Seni sevdikçe uzuyor, dolanıyorum her yanına..

Sarılıyorum dallarımla sana..

Rüzgar oluyorum seni sevince..

Bazen durulmuş bir meltem,

Bazen şiddetli bir kasırga..

Ama hep sana esiyorum.

Beyaz giymeyi, içimdeki çıtırtıları,

Bisküvi gibi parçalanmayı,

Dolanıp sarmalamayı seni,

Esmeyi,

Bazen yavaş, bazen şiddetli..

Siyah giymeyi..

Seni bir ölüm gibi seviyorum! 

(Bostanlı, 13.05.2002)', 'Sevmek, ölüm gibidir, Ne zaman karşına çıkacağı belli olmaz!  Ölen insan değer kazanır, Ve sevince insana değer vermeye başlarsın!  Seni bir...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seni-olum-gibi-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşçiler', 'i-sciler-ahmet-mansuroglu-2ni4c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alınlarında ter, ellerinde nasır var

Ekmek parasının yorgun savaşçıları onlar

Emeği büyük bütçesi dar

Vatanım, bayrağım der işçiler

İşçi tarlada çalışır, işçi fabrikada

İliğilendirmez onları süs, giyim ve moda

Soğukta üşüse, sıcakta yansada

Her türlü güçlüğe katlanır işçiler

İşçi var gücü ile çalışır,yorulmaz

Yanlışlık namertlik onda bulunmaz

Yılda bir kere bile bile hatırı sorulmaz

Soranlara sevgi dolu işçiler

İşçi soğan ekmeği iştahla yer

Bu günde karnım doydu çok şükür der

Doğruluktan şaşmaz, Allah yoluna gider

Vatanım,bayrağımder işçiler

Evde yolunu gözler hanım, çocuklar

Eldeki imkanlarla devlet onu kucaklar

Haklarını koruyan sendikası var

Azı çok sayar sabırlıdır işçiler

İşçiler ülkemizin mimarı

Sevgi ile kucaklıyalım onları

Yaşantısı kıştır, görmez baharı

Her türlü güçlüğe katlanır işçiler

Kömür kokar, tütün kokar elleri

Ülkemizdeki her güzellik onun eseri 

Saygıdır, sevgidir gönlümdeki yeri

Can dostu vatan aşığıdır işçiler.

  Antakya - Hatay', 'Alınlarında ter, ellerinde nasır var Ekmek parasının yorgun savaşçıları onlar Emeği büyük bütçesi dar Vatanım, bayrağım der işçiler İşçi tar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/isciler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin esmerleşen teninde yazdım', 'gunesin-esmerlesen-teninde-yazdim-dilek-kesgin-32l05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin esmerleşen teninde yazdım

Hasret dolu yalnızlığımı..

Sevdamı anlattım

Her bir ışık demetinde..

	

Süzülürken buluttan,

Coşkusunu anlattım yüreğimin..

Tutkumu yükleyip o buluta,

Sevdaya hasret diyarlara gönderdim..

Ölümü yazdım,

Parşömen kağıdı inceliğindeki duvara..

Güneşsiz kalıp ölüme nasıl boyun eğdiğimi..

Ve hayatımın güneşi olmanla dirildiğimi...

(Bostanlı, 17.03.2002)', 'Güneşin esmerleşen teninde yazdım Hasret dolu yalnızlığımı.. Sevdamı anlattım Her bir ışık demetinde.. 	 Süzülürken buluttan, Coşkusunu anla...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kesgin']::text[], 8.5, '{"poet":"Dilek Kesgin","poet_slug":"dilek-kesgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunesin-esmerlesen-teninde-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ercan-karakulah-dbvl4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni kaybettiğimde kabarıyor öfkem 

Aklımı yitiriyorum, 

Kokunu duyduğumda yatışıyor yüreğim, 

Herşeye boşveriyorum, 

Çünkü Ben hala omzundaki Beni, 

Yüreğimdeki SENİ SEVİYORUM, 

Tutamadığımda ellerini tutmuyor ellerim, 

felç geçiriyorum, 

Dokunduğumda tenine titriyor bedenim, 

Kendimden geçiyorum, 

Çünkü Ben hala yüzündeki Beni, 

Aynadaki SENİ SEVİYORUM. 

                                                gr_hayal', 'Seni kaybettiğimde kabarıyor öfkem  Aklımı yitiriyorum,  Kokunu duyduğumda yatışıyor yüreğim,  Herşeye boşveriyorum,  Çünkü Ben hala omzunda...', ARRAY['Türk Edebiyatı','Şiir','Ercan Karakülah']::text[], 8.5, '{"poet":"Ercan Karakülah","poet_slug":"ercan-karakulah","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-271-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Diyemem Yokluğuna-IV', 'sevda-diyemem-yokluguna-iv-ugur-deniz-ulkegul-1fv02', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-I-

/ Yazılmamış bir mektup hükmünde/

Yine sabah oldu

Bir sonra ki akşama ertelendi düşler…

Uyku tutmuyor

Sıcağın dokunmazken tenime

Buz kesiği gözyaşım, sana aldanışım

Kahrolası gidişler….

Her doğan gün

Çırılçıplak bir mavinin

Mahrem dokunuşu gibi yüreğime

Bu yüzden

Utanıyorum pencereden bakmaya

Yağmur damlası kaçıyor gözlerime…

Garip bir hüzne boğuyor beni

Şehrin ıssız görüntüsü…

Sultanahmet’in büyüsü

Sarayburnu ve Galata Köprüsü

Hani Sen yoksun ya! 

Say ki

Yarım kalan bir sevdanın öyküsü…

Kolumda saat, delirmiş yelkovan

Döndükçe içine düştüğüm girdap

Adını sensizlik koyduğum, zaman

Gözlerim kan çanağı, yüreğim bitap…

-II-

/Yine küfrettim sigaranın dumanına/

Geçip gidiyor yanımdan şehir

“Mavi çarşıda ölüm”

Kirleniyor gökyüzü, bulutlar…

Müşteri bekliyor kadın

Sermayesi olmuş yalnızlığın

Teninde dolaşırken kalabalıklar….

Rakı sofrasından kalkmış biri

Yalpalıyor şarkı söylerken

Anlaşılmıyor söyledikleri…

Gülümsüyor bir çocuk

Mendil tutan küçük elleri

Gözlerinde bir anlam! 

“Çözün artık şu kelepçeleri…”

Şimdi sus! 

Ürkmesin aklımda gülüşün

Yoksa ne anlamı kalır ağlamanın

Bir düşün! ...

-III-

/Zor iştir sevdalanmak türküye/

Açıktı gömleğinin düğmesi

Güle öykünen saçlarının kokusu

Yastığa düşen yorgunluğum

Aşk’ın (son)  nefesi…

Biliyorduk

Zifiri gitmelere gebeydi zaman

Kadınsı, tutkulu, doğurgan…

Sonra acılar büyütüldü

Umutlar yeşersin diye

Nice sevdalar

Kuytu bir sonbahara gömüldü…

Eylül dendi çocuklara

Bizler hasret kaldık uçurtmalara…

Şimdi yoksun

Henüz yazılmamış bir şiirin

Bitirilmemiş bir öykünün

Yaşanmamış bir sevdanın

Ortasında duruyorsun…

Bu yüzden yarım kalıyor

Yüzümde beliren gülüş

Sesimde titreyen tını

Tenimde

Rüzgarın değdiği dokunuş…

Bu yüzden yarım kalıyor

Bakışlarımda öfke

Dilimde kahkaha

Yüreğimde

Haykırırcasına bekleyen dua…

Bu kadar sen kokarken şehir

Böylesi alışmışken gözlerine

Söylesene gülüm

Yokluğunla ne söyleşilir? 

-IV-

/Yokluğunda var saydığım sızılar…/

Yoksa gözlerin

Bir avuç özlem olur

Kayar ellerimden….

Yoksa sözlerin

Mezar taşlarına dönüşür

Kan güllerinden…

İşte bu yüzden

Öylesi yenildim ki çokluğuna

Ben sevdiğim, ben

-Hiçbir zaman! -

Sevda diyemem yokluğuna...', '-I- / Yazılmamış bir mektup hükmünde/ Yine sabah oldu Bir sonra ki akşama ertelendi düşler… Uyku tutmuyor Sıcağın dokunmazken tenime Buz kes...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/sevda-diyemem-yokluguna-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabul Edemiyorum DEĞİL Etmiyorum!', 'kabul-edemiyorum-degi-l-etmiyorum-efsun-aydin-ips0n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hala deli olduğum yanlarımdan bi haber öylece takılmıyor musun, 

Dayanamıyorum.

Bana yalan söylediğinde ki yüz ifadene acıyorum

Senden bu yaptığının bedelini ağır ödetmek istiyorum

Sen hayatımda ki en yalancı adamsın.

Hiçbirşeyine inanmıyorum 

Gösterdiğim özveriyi, saygıyı, anlayışı, güveni ve bağlılığı asla haketmemişsin.

Sanki bir hiçsin artık benim için…

Böyle böyle çıkacaksın hayatımdan

Yüzüme bakmaya, gözlerini gözlerimi değdirmeye korkar olacaksın

Kızaracak teninin rengi her bana baktığında

Her seslendiğinde itirafını bekleyeceğim,

Evet sana yalan söyledim çünkü ….

Diye! ! ! 

Neden her ne ise

Ben de öyle bir yara açtın ki sen! 

Gerçekten çok pişman olacaksın

Gözlerinin önünde kaybedeceksin bende ki sevgini…

Ve gün be gün nasıl tükettiğini beni..

Kalbimde terbiyesizlikle bezenen bir sevgi için yer yok…

Sadece o pisliği akıtmak için zaman vereceğim…

Sonra bensiz kalacaksın.

Sana yemin ederim…

Yalvaracaksın!', 'Hala deli olduğum yanlarımdan bi haber öylece takılmıyor musun,  Dayanamıyorum. Bana yalan söylediğinde ki yüz ifadene acıyorum Senden bu ya...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kabul-edemiyorum-degil-etmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşkelerden Uzak Bir Yaşam', 'keskelerden-uzak-bir-yasam-esin-ege-7dkkx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşam  yüce yaratıcı tarafından bize sadece bir kere sunulmuş en açık en güzel ve en mukaddes  armağandır. 

Ama insan oğlu sadece bir kere sahip olabileceği bu mukaddes armağanı öylesine acımasız ve hoyratça kullanıyor ki sonuna geldiğinde elinde kalanlar sadece koskocaman pişmanlıklar denizinden başka bir şey olmuyor.

Çocukluk yaşlarımızda anne baba içgüdüselliği ile bir iki renkli oyuncaklar, legolar, robot adamlar ellerimize tutuşturuluyor sonrasında daha onların renklerinin ve avuçlarımızda hissetmelerimizin tadına varamadan çekip alıyorlar ve bir süreç başlıyor. 

Eskiden sadece çalışan annelerin çocuklarını emanet edecek kimseleri ve yerleri olmadığı için istemeyerek de olsa tercih ettikleri ana okulları şimdilerde her ailenin büyük bir istekler tercih ettiği mekanlar olup çıktılar. Bizler ana okullarına gitmedik ama şimdilerde aileler ana okulunun çocuk için elzem olduğunu düşünüyor ve çocuklarını erken saatlerde uyandırıp evde oturan kadınlar oldukları halde ana okullarına gönderiyorlar. Kısa bir süre sonra zaten okul hayatları başlıyor ve birer yarış atına döndürülen çocuklar üzerinde bin türlü bahisler oynanıyor. 

Çocuk şaşkın … oyun oynamak istiyor ama oyuncağı elinden çok dan alınmıştır. Ve çocuğun her türlü itiraz ve diretmelerine rağmen söylenen sözler hep aynıdır  “ilerde bu yaptıklarımız için bizlere dua edeceksin”

Çalınan bir hayat için kim kime dua eder oda göreceli bir kavram. Anne baba haksız değiller onlarda çocuklarını topluma en güzel şekilde hazırlamak ve sunmak istiyorlar ama baştan sona haklı biri var ki oda hayatının tüm kontrolünü elinde tutamayan çocuk.

Anadolu liseleri etabı, hemen arkasında üniversite sendromu ve bir bakıyorsunuz  ki çocuk ne olduğunu anlayamadan erginliğe doğru hızlı adımlar atıyor. 

Çocukluğunun elinden uçup gittiğini anlayamıyor. Göğüslerinde kabaran tomurcuklarıyla,yada kalınlaşan sesiyle ben artık on sekizimi doldurdum diyor ve yılların içinde biriktirdiği isyan bayraklarını açıyor.

Gönlünce gezemiyor gönlünce istediği kitapları okuyamıyor. Çünkü onun okuması gerekli ders kitapları var.  Tatillerde gideceği kurslar var nerede okusun istediği kitapları.

Sonra karşısına biri çıkıyor gönlünü kaptırıyor  ve büyük ihtimalle ilk aşk acısını yaşıyor. 

İhanetler görüyor, ne yapsa da sevdiği avuçlarının arasından  kaçıp gidiyor. Meslek seçme telaşı başlıyor. Üniversite bitiyor tabi ki girebildiyse çünkü giremediyse işler daha da zorlaşıyor. 

Toplumda yer edinme,  para kazanma, aidiyet  duyguları peşin sıra geliyor. Evleniyor sonrasında. Belki evlilikte aradığını hiç ama hiç bulamıyor ve en büyük hüsranlarını yaşıyor. 

Mutlu veya mutsuz çocuk sahibi oluyor ve büyüklerinden aldığı terbiye ile çocuklarını topluma kazandırma yarışına oda başlıyor. Ve bir süreçtir dönüp gidiyor.

Yıllar yılları kovalıyor çocuklar büyüyor ve aynı yollardan geçerek onlarda evlenip yuvadan bir bir uçup gidiyorlar. Ellili yaşlara gelindiğinde insan bir sabah bakıyor ki sabah kahvesini ağır ağır ve yapayalnız içiyor. Ölüm denen kaçınılmaz ayrılık mutlu veya mutsuz iki hayat arkadaşını bir birinden ayırıyor.

Gece olduğunda  başımızı yastığa koyduğumuzda o geriye dönmesi mümkün olmayan hayatımız bir film şeridi gibi gözlerimizin önünden geçiyor.

Biz nerede hata yaptık? 

Bir bakıyoruz ki bize sadece bir sefer sunulan yaşam denilen armağanı bizler ne kadar umarsızca ve hoyratça fani işler için harcamışız.

Ama artık yapılacak hiçbir şey yoktur,  koskocaman pişmanlık denizinin içinde küçücük bir balık gibi çaresiz ve yalnızız, koskoca hayattan bize geriye kalan keşkelerle dolu bir hayatın anılarıdır sadece.', 'Yaşam  yüce yaratıcı tarafından bize sadece bir kere sunulmuş en açık en güzel ve en mukaddes  armağandır.  Ama insan oğlu sadece bir kere s...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/keskelerden-uzak-bir-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçiyorum', 'vazgeciyorum-elif-sude-tidx7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyorum sevdiğim

Senin de istediğini biliyorum

Uğruna ölünecek sevdaların

Hayalinde olduğumuzu biliyorum

Yıllar sonraki mutluluğun

Kalbimizde doğduğunu biliyorum

Birkez sevseydin beni

Ahh bir sevebilseydin

Belki de bizimdi hayallerimiz

Belki de yaşatırdık umutlarımızı

Gel gör ki olmuyor sevdiğim

Sev deyince de sevilmiyor

Biliyorum sevdiğim 

Biliyorum sevmek istediğini

Maviayı da biliyorum

Unutamadığın anılarını hepsini

Bilmek istemediğim herşeyi

Biliyorum ve anlıyorum

Sonra birkez daha ahh ediyorum

Seni üzenlere içten içe feryad ediyorum

Ve tekrar yeminler ediyorum

Eğer birgün bensiz mutlu olacaksan

Senin için senden geçeceğime dair

Aşk şiirlerini okuyorum birdaha

Ağlıyorum hazin bitişinize

Ağlıyorum başlayamayan sevdamıza

Yanındayım...çaresiz bir fısıldayış...

Hergece duyamadığın ses işte bu

Ve güzel kız günlerini böylece tüketmiş

Ardı ardına geçen günlerde hep

Bir işi vardır diye avutmuş kendini

Gün gelmiş yorulmuş beklemekten

Gün gelmiş resmi eskimiş koynunda

Gözyaşları ulaşmamış yağmura karışıp da sevdasına

Ve vazgeçmiş düşlerinden,

Kalbinden, tertemiz hayallerinden

İşte masal da bitiyor sevdiğim

Ölümsüz hikayemizin sonu da geldi

Zor be sevdiğim inan ki zor

Geleceğini beklemek birgün

Birgün ondan kopacağının hayaliyle yaşamak

İnan ki zor 

Vazgeçiyorum sevdiğim

İnanki çok zor...

(24.07.2005)', 'Biliyorum sevdiğim Senin de istediğini biliyorum Uğruna ölünecek sevdaların Hayalinde olduğumuzu biliyorum Yıllar sonraki mutluluğun Kalbimi...', ARRAY['Türk Edebiyatı','Şiir','Elif Sude']::text[], 8.5, '{"poet":"Elif Sude","poet_slug":"elif-sude","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/vazgeciyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sensiz Yaşamak..', 'seni-sensiz-yasamak-elif-sude-sjaj9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine akşam oldu yine daldım senle dolu olan sensizliklerime

Dışarıda yağmur yağıyor sevdiğim

Bilmem beni hatırladın mı her yağmur tanesi bir bir düşerken

Bilmem beni özlüyormusun umutsuzca olsa bile

Neyse sadece bir iç çekişti bu...

Acaba bilir misin için ağlarken gülebilmeyi

Ve her gülüşünde acı çekmeyi

Yıldızlara baktığında nedensiz saatlerce ağlamayı

Buralarda bahar olmayacak sevdiğim

Neyse sadece bir iç çekişti bu...

Issız bir çölde bir gül arar mısın

Ve düşünür müsün o gülü vermeyi sevdiğine

Buralar kurak çöllere döndü

Buralara gül gelmez sevdiğim

Neyse sadece bir iç çekişti bu...

Sahi sen bilir misin aşkı

Anlatabilir misin benim gibi derdini mısralarında

Ve okunmayacağına emin olduğun sitem şiirleri yazar mısın

Yazar mısın sevdiğim aşkını bir hiç için

Neyse sadece bir iç çekişti bu...', 'Yine akşam oldu yine daldım senle dolu olan sensizliklerime Dışarıda yağmur yağıyor sevdiğim Bilmem beni hatırladın mı her yağmur tanesi bir...', ARRAY['Türk Edebiyatı','Şiir','Elif Sude']::text[], 8.5, '{"poet":"Elif Sude","poet_slug":"elif-sude","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-sensiz-yasamak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yamaçlarda Bir Giz', 'huzun-yamaclarda-bir-giz-arzu-gulucudur-3dg95', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün yamaçlarda bir giz olurdu bazen

Bazen dilden dökülemeyen,

Bakla içi misali söylenemeyen bir söz

Akla gelip de kaleme harf olamayan bir şiir

Notasız bir tını...isimsiz bir mektup...

Hüzün yamaçlarda bir giz olurdu bazen

Bazen çıkagelen tanınmayan bir misafir

Nereye gidildiğini bilmeden çıkılan bir yolculuk

Bir kaçış...umarsızca bir düşünüş...

Sessiz sedasız bir göçüş...

Hüzün yamaçlarda bir giz olurdu bazen

Saklandığı yerden çıkar gelirdi

Yapışırdı yakasına çelimsizliğin

İliklerine işlerdi öldürürcesine

Koyusuna düşürdü mü yalnızlığın

Vay haline....

Hüzün yamaçlarda bir giz olurdu bazen

Olumsuz fiil kipleriye biten şiirler yazdırırdı

Bensiz, sensizdi şahıs ekleri

Nereden geldiği ve nereye gittiği belirsizdi tümleçlerin...

Hüzün yamaçlarda bir giz olurdu

Nezaman

Nasıl

Hangi silahla vuracağı belli olmayan bir giz.....', 'Hüzün yamaçlarda bir giz olurdu bazen Bazen dilden dökülemeyen, Bakla içi misali söylenemeyen bir söz Akla gelip de kaleme harf olamayan bir...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/huzun-yamaclarda-bir-giz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kalp İki Kişi', 'bir-kalp-i-ki-kisi-ali-i-nal-5o6on', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kockoca bir yalansın sevdiğim

yok bir farkın diğerlerinden

geçen her bir dakika seninle

sahte bir hayaldir gördüğüm

sanma görmediğimi ışıltıyı

bakarken ona gözlerindeki

kedinin fareyle oynadığı gibi

sanma sakın oynatırım kendimi

dolduracak kim diye arıyorsan

kalbinde boş yeri, bilesin

ne bir kalbe iki kişi sığar

ne de iki kalbe üç kişi', 'kockoca bir yalansın sevdiğim yok bir farkın diğerlerinden geçen her bir dakika seninle sahte bir hayaldir gördüğüm sanma görmediğimi ışıltı...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-kalp-iki-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penceremden Bakarken', 'penceremden-bakarken-hikmet-kucuk-cvoku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cam buğulu, soğuk ve hissiz,

Sokak, yoksan ne kadar da sessiz.

Saatlerdir neredesin, kayıpsın, 

Seni bekleyen gözler ne yapsın? 

İşte yaklaştın, gölgen ince bir sır,

Seyredilmeye değer, bin asır.

Sokak doldu geçiyorken sen,

Ve hayran hayran bakmaktayım ben.

Manzarayı bir an donduruversem,

Ve başucuma, konduruversem.

Keskin nazarından elmas damlar,

Sakın bakma, eriyiverir camlar.

Sadece ayaklarının ve kalbimin sesi,

Yarılacak  birazdan göğüs kafesi.

Cam, pervaz,  ben ve perde,

Donup kaldık, küçücük yerde.

Halimiz bilmem ki, neyi andırır,

Bir rüyadayız ki, kim uyandırır.', 'Cam buğulu, soğuk ve hissiz, Sokak, yoksan ne kadar da sessiz. Saatlerdir neredesin, kayıpsın,  Seni bekleyen gözler ne yapsın?  İşte yaklaş...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/penceremden-bakarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-erdal-gisi-o1kgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bebeğim; 

Kollarım sonsuza kadar taşıyabilir,

gözlerim gözlerinden başka görmeyebilir,

gülmenden-ağlamandan gayri sese-soluğa kulağımı kapayabilir,

bir ömür saçlarını okşayabilir,

etrafında pervane olabilir... ağlayabilirim.

Her tebessümün anısına bir fidan dikebilir,

her ağlamanda birkaç damla yağmur olup yağabilir,

her nefesini dünyanın apayrı noktalarında, apayrı rayihalar-mevsimlerle zenginleştirebilirim.

Yaşaman ölmeme muhtaçsa,

ne yapar ne eder göçenler kervanını dahil olabilir,

Servet mi makam mı diliyorsun bırakabilirim.

Allah’ın mükemmel yarattığı şu insan bedeni, beyni, yüreği... nelere kadirse inan hepsini yapabilirim.

Ancak, Mutluluğun; 

yaşamanın, sevilmenin... öpülmenin mi,

yoksa bir yolunu bulup, bir nefes daha beklemeyip,

bir elveda tebessümüyle pervaz etmenin mi özünde saklı bilemiyorum.

Adına büyüttüğüm fidanlar...

yemişi, gölgesi, kokusu, rengiyle mi...

yoksa varolan hayat suyunu da sömürmekle mi karşılayacaklar... bilemiyorum.

gözyaşına karışan gözyaşımı,

tebessümünde kaybolan-eriyen benliğimi,

taşlaşan kollarımı, delik deşik uykularımı...

azabını derinleştiren, zindan yollarını süsleyen, zehrini altın kasesinde gizleyen... akrep gönüllü bir dilbere mi,

efsunlu, hoş kokulu, lalezar içinde ahşap çardaklarda bir içten huzura mı yorarsın onu da bilmiyorum…

Bebeğim, bu telaş, heyecan, karmakarışık...

bu her şeyimden vazgeçişimi,

beyazlayan ve dökülen saçlarımı,

bu sessiz yıkılışlarımı, kendine esin ve besin kaynağı mı,

yoksa tiksinmeye, vazgeçmeye, kaçmaya, tükenmeye sebep mi görürsün bilemiyorum.

Belki aydınlanman yanmamda saklı,

belki hezeyanlarımda huzurun var,

belki yok olmam varlığının sırlı anahtarı.

Ama, sensiz bir hayatın hayali, darağacında türkü söylemekten farksız,

sensiz bir rüya, yataklara kurulu akrep yuvası,

sensiz ben; baykuşların hüküm sürdüğü lanetli harabe.

Ve bebeğim, bir de son ihtimal, sen ve ben...

Sen ve ben, sedef  kakmalı taht ve tâc...

Semayı yıldızlarla süsleyen kandille som elmasın buluşması...

Bamteli avcılığına çıkan tınıların, güftelerin, seslerin en bütünü, en özü...

Bebeğim, bitmeyecek bir endişeyi, bir istifhamı yazıyorum yine...

ama ne senin dile gelmen  nede gelsen bile bilmen mümkün.

Öyleyse, ne yaşamam ne de ölmem mümkün.

Bir çaresi olmalı, bir hekimi olmalı...

hiç değilse bir anlamı-manası olmalı…

Bebeğim; 

Ölü gibi yaşamamın, yaşıyor gibi ölmenin... bir manası olmalı

2002', 'Bebeğim;  Kollarım sonsuza kadar taşıyabilir, gözlerim gözlerinden başka görmeyebilir, gülmenden-ağlamandan gayri sese-soluğa kulağımı kapay...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bebegim-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Nedir Diye Soruyor Gönlüm', 'sabir-nedir-diye-soruyor-gonlum-erdal-gisi-34mkd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağustos sıcağında…

gökten çizgi çizgi yere kadar uzanan,

incecik ipliklerle süzülen damlacıkların, 

kurumadan inebildiği kadar inişini bekleyip, 

susuzluğumuzu gidermeye çalışmak mı desem…

Ak güvercin...

yorgun güvercin kanadında, 

O’na ait kokulu hüzünlerin,

penceremize konacağını bilerek sukuta gömülmek mi desem.

Yıllar süren zindan hayatında,

cebin kıvrımlarında gizlenmiş ufacık, biricik karanfil tohumunu,

bahçenin en güneş alan yerine gizleyip… 

filiz hayaliyle… 

karanfil kokulu şiirler karalamak mı desem…

Bir gün… 

rahat arzusu, 

idealsizlik, güvensizlik şerareleriyle meteor fırtınalarına tutulan,

Cennetlik duyguların dikenli tellerle örüldüğü… 

ateşîn korkaklığın her şeyimize hükmettiği dünyamızda… 

azıcik inancımız, şefkatimiz, dostumuz ve ağır işiten kulaklarımıza rağmen… dualarımıza gömülüp, vicdanımıza gömülüp… 

Rahmet ufuklarının huzurunu hissedebilmek mi desem.

Ansızın buhar olup 

başka kıtalarda, duru gönlüne çiçekler davet ettiği gündür… 

ayağımızdan eksik olmayan diken iltihaplarına aldırmaksızın…

makamın, rahatın çıbanlaşmasını fırsat bilip, 

bâri ruhumuzu serinliğine atabilmek,

vefasızlığımızı itiraf edebilmek için…

vuslatın gölgesinden artık yüz çevirip…

O’na doğru koşma anını kollamak mı desem

Bu sürgün, bu bayrak mezarlığı…

erdemin her gece her gündüz koparıldığı-budandığı ülkede…

ardına bakmadan…

mataramızın son damlasına kadar birkaç çiçeğe su vererek, 

bir kaç gönle tebessüm ederek…

ayak izlerimizi silmek isteyenlere de beddua etmeden

güneşe doğru sessiz sedasız yürümek mi desem…

Uykusuzluk mu, 

içimizi dolduran lavlara tahammül mü… 

vefasız nefeslere alışmak mı desem…

Sabır nedir diye soruyor gönlüm

Bir bilsem…? 

1 nisan 2002', 'Ağustos sıcağında… gökten çizgi çizgi yere kadar uzanan, incecik ipliklerle süzülen damlacıkların,  kurumadan inebildiği kadar inişini bekle...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sabir-nedir-diye-soruyor-gonlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldürmeyen Oyun', 'guldurmeyen-oyun-ali-i-nal-h5gjp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gülüşü bile bir küçük kızın

en eğlenceli yerinde oyununun

eritirken en katı kalpleri

büyüdük ve soğuttuk

sürüp giden hayat oyununda

hınzırca gülerken 

en yumuşak yürekleri bile

hayatı yaşamak, 

oyun derken yaptıklarımıza

belki daha samimiydi

oyun diye yaşarken hayatı

kırdığımızda kapleri

en derininden

bizi severken dahi

mızıkçılık yapmak istiyorum

oynamıyorum artık demek

sonrada çekip gitmek

arkama bile bakmadan

kalmasa da dönülecek bir yuva

ayağımızın altında belkide

döneceğimiz son kucak

oynamıyorum artık yeter

ben bu acı oyunu

ister deli ister divane 

isterse kör aşık

ne derseniz deyin siz

yoksa o gülüşler 

bir daha görebileceğimiz

bir yaramaz küçük kızın

...

oyunuzda da sizin olsun

hayat dediğiniz oyununuzda', 'gülüşü bile bir küçük kızın en eğlenceli yerinde oyununun eritirken en katı kalpleri büyüdük ve soğuttuk sürüp giden hayat oyununda hınzırca...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/guldurmeyen-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkem Türkiyem', 'ulkem-turkiyem-i-lhan-koruyucu-g06c8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ülkem Türkiyem

Aşkınla yandım da hiç doymadım

Bulamadım dünyada senden güzelini

Bağlandım, ateşinle yandım yandım

Doya doya seni kendimde buldum Türkiye’m.

......

Her bir yanın ayrı bir dantel, ayrı örnek

Yazın da, kışın da, baharın da

Sana baktım aşık oldum

Türkiye’m seni kanıma işledim.

......

Ayyıldızın yükseldikçe coştuk coştuk

Millet olarak yüzyıllardır hep peşinden koştuk

Semanla yükseldik birleştikçe

Benim canım yurdum, güzel ülkem TÜRKİYEM.

İlhan KORUYUCU.', 'Ülkem Türkiyem Aşkınla yandım da hiç doymadım Bulamadım dünyada senden güzelini Bağlandım, ateşinle yandım yandım Doya doya seni kendimde bu...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ulkem-turkiyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama Özel', 'babama-ozel-mehmet-dag-p44fb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BABAMA ÖZEL

Hanı bir çiçek solar ya sonbaharda

İlkbahar da geri gelmek için

Sende gelecek misin baba

Okyanuslara açılan bir kaptanın

Limanına geri döndüğü gibi

Sende dönecek misin baba

Hani Akşam giden güneşin

Sabah geldiği gibi

Ne olur sende gel baba

Uçurtmasını rüzgâra kaptıran 

Çocuklar gibi uçtun ellerimden

Seni kaybettim baba

Üzgünüm hiçbir şey söyleyemiyorum

Nefesim gırtlağıma düğümleniyor

Sindiremiyorum ölümünü senin adına

Yüz yılı devirdin

Bir yüz yıl daha yaşasaydın

Birilerinin inadına

Bense sığınıyorum sadece anılarına

Hiç kimse ama hiç kimse kötü diyemedi sana

Adam gibi yaşayıp, Adam gibi öldün baba

Ne mutlu sana

Sen rahat uyu

20 –12- 2004-

Babam- Balabey DAĞ’IN anısına', 'BABAMA ÖZEL Hanı bir çiçek solar ya sonbaharda İlkbahar da geri gelmek için Sende gelecek misin baba Okyanuslara açılan bir kaptanın Limanın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/babama-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlıklar', 'pismanliklar-necmiye-sarpkaya-4fy7k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ya İlahi 

Ne yana dönsem uçurum 

Ne yana dönsem kem 

Ne yana dönsem şer

Kaderim dayandı çıkmazlara

Açmazlara dayandı 

Ben sözümde durmadım 

Yap dediklerini yapmadım 

Yasakların cazip geldi 

Daldım gittim dünyaya 

Her taraf toz duman 

Her taraf sis bulanık 

Ya Rabbi 

Diz çöküp itiraf ediyorum 

Kendimi tartmadım 

Onca hatamı  bilmedim 

Hep başkalarını eleştirdim 

Muazzam serveti tükettim 

Ya Rabbül Alemin 

Halim bununla da kalmadı 

Gizli aşikar her şeyi bilensin 

Giz perdesiyle örtensin günahları 

Ben  örtmedim 

Sevapları görmedim 

İyi halleri  bilmedim 

Ya İlahi 

İçimde  pişmanlıklar yeşermedi 

Kaygan zeminlerde dolaştım 

Nefsime söz dinletemedim 

Balyalar doldu taştı 

Mizan gününü bilemedim 

Engin hoşgörünü bile bile 

Dar bakış açımla baktım

Gönül kapımı açmadım 

Gün geldi yargıladım 

Gün geldi mahkum ettim 

Neye göre 

Kime göre İyi kötü 

Haklı Haksız 

Bilmedim bilemedim 

Huzurunda itiraf ediyorum 

Her olmaz davranışımdan sonra 

Kavruldum pişmanlık duydum 

Tövbe ettim 

Tövbelerimi bozdum 

Senden hiçbir şey saklayamam 

Gerçeği gizleyemem 

Duymadım  bilmedim 

Sen asileri bile affedensin

Asi olmamaya çalıştım 

Her şeyi temizleyensin 

Affedensin 

Halimsin 

Gafursun 

Muktedirsin

Affetmeyi  seversin 

Ya Rabbi 

Bana hak ettiğim şekilde muamele etme 

Şanına yakışır merhametine yakışır 

Sana yakışır şekilde muamele et

Ya Rabbi 

Sana  güvenim sonsuz 

Tövbelerimi kabul et 

Amin amin

Necmiye Sarpkaya', 'Ya İlahi  Ne yana dönsem uçurum  Ne yana dönsem kem  Ne yana dönsem şer Kaderim dayandı çıkmazlara Açmazlara dayandı  Ben sözümde durmadım  ...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/pismanliklar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tattın mı?', 'tattin-mi-i-lhan-koruyucu-c9nek', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tattın mı? 

Soruyorum sana hayatta acıyı,

Bırak acıyı, tatlıyı doyasıya tattın mı? 

Sevinçli gününde ansızın hüznü,

En karamsar anında uçtun mu havalara.

Aşkına kurban olabildin mi? 

Sevdiğinle en güzeli paylaşarak.

Bazen dağ olmuş sorunları atarak,

Hayatta hepsini harman edip tattın mı? 

İlhan KORUYUCU', 'Tattın mı?  Soruyorum sana hayatta acıyı, Bırak acıyı, tatlıyı doyasıya tattın mı?  Sevinçli gününde ansızın hüznü, En karamsar anında uçtun...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tattin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ait Olduğum Yer', 'ait-oldugum-yer-zuhal-aksulu-doct4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutma beni.. Tutsan da kayarım ellerinden.. İncecik kum taneleri gibi... 

Savur beni rüzgara... Ait olduğum yere gideyim.. 

Sonsuzluğa....', 'Tutma beni.. Tutsan da kayarım ellerinden.. İncecik kum taneleri gibi...  Savur beni rüzgara... Ait olduğum yere gideyim..  Sonsuzluğa.......', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ait-oldugum-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün bir hüzün var içimde', 'bugun-bir-huzun-var-icimde-neslihan-i-sler-v91mo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün bir hüzün var içimde 

Hiç duymadığım bir müziğin hüznü

Adlandıramadığım bir yokluk hissi

Bugün bir hüzün var içimde 

Gözlerimde uzaklara dalan

İçimden lıkır lıkır akan bir hüzün

Anlayamadığım bir boşluk duygusunda

Bugün bir hüzün var içimde

Cama vuran yağmurun sesinde

Menekşelerin morumsu renginde

Bugün bir hüzün var içimde

Mahallede oynayan cocukların sesinde

Kapının çalmayan zilinde

Komşunun kahvesinde..

Bugün bir özlem var içimde 

Ne olduğunu bilemediğim hüznü bana getiren...', 'Bugün bir hüzün var içimde  Hiç duymadığım bir müziğin hüznü Adlandıramadığım bir yokluk hissi Bugün bir hüzün var içimde  Gözlerimde uzakla...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugun-bir-huzun-var-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç mevsimde', 'goc-mevsimde-neslihan-i-sler-urqk3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin kuralların vardı

Benim duvarlarım..

Senin sağduyuların vardı

Benim hissettirdiklerin

Biran için sen geminin kaptanı oldun

Bense garip bir yolcu..

Senin sınırların vardı sevgin gibi..

Benimse bir hayat oyunum kurallarını bilmediğim

Dua ettim duvarları geçip beni bulman için

Sende geçip gittin umut duvarımın yanından..

Havalandı gönül kuşum 

Kimbilir şimdi nerde bir göç mevsimde.....', 'Senin kuralların vardı Benim duvarlarım.. Senin sağduyuların vardı Benim hissettirdiklerin Biran için sen geminin kaptanı oldun Bense garip ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goc-mevsimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Dün Gibi', 'daha-dun-gibi-saim-bastik-1wk90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha dün gibi; 

Gizlice buluştuğumuz park

Oklu kalp çizdiğimiz masa.

Bu gün bakınca aradaki fark

Yüzümüzdeki çizgiler olmasa.

Daha dün gibi; 

Hergün seni görmek için geçtiğim sokak

Senin koşarak balkona çıkışın.

Benim sana bakışım korkarak

Ve terleyişim  tam ortasında kışın.

Daha dün gibi; 

Bir dargın bir barışık geçen her günümüz

Ve sonunda sarılarak ağlayışımız.

Düşün ne zaman oldu düğünümüz

Hanım,galiba biz de yaşlanmışız.

Daha dün gibi; 

Hatırlıyorum boynuma astığım teypte çalan

Seninle en çok sevdiğimiz şarkımızı.

Gel sen de kabul et gel sende inan

Bak biz de evlendirdik çocuklarımızı

26/07/2005', 'Daha dün gibi;  Gizlice buluştuğumuz park Oklu kalp çizdiğimiz masa. Bu gün bakınca aradaki fark Yüzümüzdeki çizgiler olmasa. Daha dün gibi;...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daha-dun-gibi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-sair-acun-karo-qwuoo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çıglıktır ismin kulaklarımda; 

Nerden geldigi belirsiz

Bir güneş

Nerden dogdugun belirsiz.

Biliyorum varsın,bir yerlerdesin; 

Dedim ya biliyorum.

Ama yoksun işte...

Olsaydın özletmezdin kendini,

Elini tutarken bile özlemezdiim; 

Sarılırken bile aramazdım seni; 

Ama varsın... 

Hissediyorum,uzaklardasın.

Ve bir gün...', 'Bir çıglıktır ismin kulaklarımda;  Nerden geldigi belirsiz Bir güneş Nerden dogdugun belirsiz. Biliyorum varsın,bir yerlerdesin;  Dedim ya b...', ARRAY['Türk Edebiyatı','Şiir','Şair Acun_karo']::text[], 8.5, '{"poet":"Şair Acun_karo","poet_slug":"sair-acun-karo","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/biliyorum-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Denizi', 'sevda-denizi-hasan-gorgu-bekwc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Balıklama atladım sevda denizine

Takıldı oltama Lüferl er

Nilüferler 

Hülya lar Ebru lar Ayfer ler

Ağlarım dolu

Kucağımda Afroditler

Çekeyim dedim aşk sandalına 

Tamamını eksiksiz

Çok uğraştım kaldım nefessiz

Son bir hamle 

Kapadım gözümü daldırdım elimi 

Çektim birini çaresiz

Çıktım sandala baktım

Elimde kalan balık

Aysel Gürel gibi bir analık

Ne çare

Bonusu da yok ki kredi kartlarımın

Düzelttireyim orasını burasını

Anlıyacağınız

Vaziyetim Allahlık', 'Balıklama atladım sevda denizine Takıldı oltama Lüferl er Nilüferler  Hülya lar Ebru lar Ayfer ler Ağlarım dolu Kucağımda Afroditler Çekeyim...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevda-denizi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Adın Ayışığı', 'senin-adin-ayisigi-ozer-genc-ra7sk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece sen yine aklıma girdiğinde

Kadıköy''ün üstündeydi

O,Dünya Güzeli kentin altın madalyasıdır

Göktaşları değil bağrındaki yaraların nedeni

Onbinlerce yıllık tanıklığın yasıdır

Korkudan arkasını dönemez bize

Gelmiş geçmiş haksızlıkların sessiz tanığı

Yine de ışıl ışıl doğar gecelerimize

Taçlandırıp özlemin ve sevdanın tadını

Sen de hep ışıldayan yüzünü gösteresin diye 

Ayçadan dolunaya

Ayışığı koydum adını

Güzel ve umursamaz bir kent bu

Boşvermiş bir gece

Sürüyor o anlamsız telaş

O kara eğlence

Bir kedi yavrusu yola fırladı birden

Sarı benekli acemi şaşkın

Bir fren sesi lastikler feryat figan

Tam da hüznümü paylaştıracağım zaman

Ancak onyedisindeler

Elele tutuşmak yakışmış iki gence

Kızın sol elinde bir demet gül

Öğretmenine verecekmiş

Atandığı uzak kente gitmeden önce

Öğretmenlerimi hep sevdim bilir misin? 

Biz avuntularla büyürken

Kara lastikli çocukları onlar okuturlardı

Çırak olacaklarını bile bile

Beşi bitirince

Birden bir türkü yayıldı her yana

Bizim oralı bu türkü Karadenizli

Hüznü coşkusunda gizli

Otobüs yazıhanesi önünde 

Patron genç adama küfür kıyamet

İri yarı genç üniformalı

Şoför muavini olmalı 

Parmağında nişan yüzüğü

Ekmek parası sabrı  taşmak üzere

Gözleri hem kızgın hem ürkek

Yaşlı bir tanık umarsız

Of çekiyor 

La havle ve la kuvvet

Diyerek

Adam arabayı zar zor durdurdu,kedicik ölmedi işte

Güller birbirine benzer mi? 

Genç kızın elindeki güllerden biri

Sanki sana verdiğim gülün ikizi

Seninle dinlediğimiz türkü Kadıköy’ü kapladı da

Genç adam herifin suratına yumruğu oturttu ya

“Yalnız bunun için sevmek isterdim seni”', 'Dün gece sen yine aklıma girdiğinde Kadıköy''ün üstündeydi O,Dünya Güzeli kentin altın madalyasıdır Göktaşları değil bağrındaki yaraların ned...', ARRAY['Türk Edebiyatı','Şiir','Özer Genç']::text[], 8.5, '{"poet":"Özer Genç","poet_slug":"ozer-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/senin-adin-ayisigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekletme Beni...', 'bekletme-beni-i-brahim-ethem-bingul-ikzy4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde tüten sevda senindir

Sözümdeki yorum, mana senindir

Dün sensin, bugün sen, ferda senindir

Her şeyim senindir,söyletme beni...

Bakışların ne hoş, kalbe güvendir

Yaklaşman aşk sunan uzanan eldir

Sözlerin şarkıdır, dinle diyendir

Gel karşıma konuş, çıldırtma beni...

Seni görmeyince gözlerim yorgun

Sana akar kalbim, sen yoksan durgun

Hasrette bırakma, olurum solgun

Gel gönlüme, yeter... bekletme beni...

www.iebingul.com', 'Yüreğimde tüten sevda senindir Sözümdeki yorum, mana senindir Dün sensin, bugün sen, ferda senindir Her şeyim senindir,söyletme beni... Bakı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekletme-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat ne Garip', 'hayat-ne-garip-erdal-gisi-l7cs6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu güneş, bu toprak, bu yağmur belki

Ama bu karmaşa bu telaş değil

Bunca yılın bana vermediğini

Azıcık çırpınış verecek değil

Bu geliş ki nerden son ki nereye

Kaçtım onca sene o yön bu yöne

Bu hiç ummadığım düştüğüm sele

Attığım kulaçlar hiç çare değil

Her nefes içtiğim kazayı çile

Her dem kokladığım kaderi keyif

Ne hal bilmediğim göz göre göre

Kan revan dönüşler muradım değil

Ne koşmak elimde ne geri durmak

Ne kendime gelmek ne de el olmak

Açmamış güllere hasbihal olmak

Çocuksu heyecan gönlümde değil

Her şeyi elimle buldum mu desem

Suları göğünde boğdum mu desem

Yarınları dünden vurdum mu desem

Günler gibi ölmek elimde değil

3.6.04', 'Bu güneş, bu toprak, bu yağmur belki Ama bu karmaşa bu telaş değil Bunca yılın bana vermediğini Azıcık çırpınış verecek değil Bu geliş ki ne...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayat-ne-garip-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Yedi yoldaşım', 'ben-ve-yedi-yoldasim-suleyman-eser-q2j5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz kanlı örgütlerdeniz

Var elbet gizli amaçlarımız 

Biz kanlı örgütlerdeniz

Ben ve yedi yoldaşım

Hepimizde aynı sınıftan

Bir okul çıkışı

El ele tutuştuk

O dakika verdik karar

Çete kurulacaktı gün batmadan

Biz kanlı örgütlerdeniz

Yaşımız henüz sekiz

Ama belirlenmişti hedefimiz

Biz kanlı örgütlerdeniz

Ellerimizde ağır makineli

Benim elimde testere

Osman’da çekiç, İbiş’te çivi

Burgu, gazoz kapağı, ve diğerleri

Hani daha küçüğüz ya 

Haliyle testere bile ağır gelirdi

Biz kanlı örgütlerdeniz

Ayağıma üç kere çivi battı

Beni tekrar tekrar ağlattı

Biz kanlı örgütlerdeniz

Dağ bayır dolaşıyoruz

Bir bakarsın “göçük”teyiz

Az sonra ineriz balık tutmaya 

“değirmen kırı”na 

Bastıran yağmura aldırmadan

Dün ''köyün konduğu''nda piknik

Bu gün “küten”de tahta araba

Bir önceki gün hepimiz

“kara çayır”da top peşindeydik

Binemesek de altımızda dururdu

Mehmet Ali’nin kırmızı bisikleti

Biz kanlı örgütlerdeniz

Var elbet gizli amaçlarımız

Tahtadan araba yapacağız

Akü ve motor bulunacak

Farlarımızı da takıp

Hastalanan köylülerimizi

Sağlık ocağına taşıyacağız

Var elbet gizli amacımız

Bu yüzden her üye para verecek

Hasılat  “ayvaz”ın arkasına 

Herkesin önünde gömülecek

Biz kanlı örgütlerdeniz

Kan kusar kızılcık şerbeti deriz

Para yok demek yasak

Son ihtimal kümesten yumurta çalınıp

Bakkalda paraya çevrilecek

Biz kanlı örgütlerdeniz

Her birimiz davasına güveyi

Hani öyle olur ya 

Biz ayrılmayız derken

Ayrılığın varılmaz farkına 

İlk ben ayrıldım örgütten

Bir kasım sabahı

İstanbul hülyası içinde 

Ve masmavi bir günde 

İsmail bizi ebediyen terk etti

Ankara’da öğretmen olurken İsa 

Zekeriya köyde uğraşıyor

Kamil’in mekanıysa Manisa 

Biz en canlı örgütlerdeniz

Ellerimizde muhabbet gülleri

Yürek yürek dolaşıyoruz

Her bir şeyimiz aşikar

Her birimiz dostluklarla evli

                         -KTHY-

                       20.07.2005', 'Biz kanlı örgütlerdeniz Var elbet gizli amaçlarımız  Biz kanlı örgütlerdeniz Ben ve yedi yoldaşım Hepimizde aynı sınıftan Bir okul çıkışı El...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/ben-ve-yedi-yoldasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melda 1', 'melda-1-suleyman-eser-tto9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...melda 

Sen düştün aklıma 

Kor düştü bağrıma

Sen kimsin tanıyamadım

Sen yoksun, ben yoklukta

Görmedim hiç seni

Göremedim hiç sevgini

Aklımdaki bu çelişki

Ne seninle başladı bende

Nede seninle bitti.

Koştum koştum, nafile

Varamadım asla hedefime 

Ne seninle var oldum, ne sensiz.

Nede seni koydum hayalime

Ağladım,  yalvardım her gece

Hepsini attım sevemeden içime

Yerlere,  göklere sığdıramadım

Seni koyamadım bir biçime

Vurmak lazım benim başımı

Yuvarlamak bir dereye naaşımı

Yada sallandırmak darağacında

Belki de zehirlemek aşımı

Nedenini bilmem ama

Kapatmak lazım beni zindana

Belki akıllanırım o zaman

Koyarım sevgini aklıma

Belki de o zaman,

                          Melda...

                                   10.03.2003

                                   -Ümraniye-', '...melda  Sen düştün aklıma  Kor düştü bağrıma Sen kimsin tanıyamadım Sen yoksun, ben yoklukta Görmedim hiç seni Göremedim hiç sevgini Aklım...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/melda-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Zamansızlık Özler', 'bizi-zamansizlik-ozler-fidan-bulut-znh6t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haydi aşkım 

Eş zamanım

Elele tutuşalım

Düşler bekliyor.

Sen tenimin kokusunda

Ben gözlerinin kuytusunda

Yola koyulalım

Hazlar gülüyor.

Gül goncaları yolumuzda

Meltemler ruhumuzda

Arş halıları sermiş

Itırlar bize kokuyor.

Güzler gün bahar

Gece umut yarınlar

Şenlik başlıyor.

Dağlar basamak

Selviler sütun mermer

Bir kavaklar engel

Bülbüller dillerini besliyor.

Gel aşkım

Yer sema aralandı bak

Sar beni

Bizi zamansızlık özlüyor.........', 'Haydi aşkım  Eş zamanım Elele tutuşalım Düşler bekliyor. Sen tenimin kokusunda Ben gözlerinin kuytusunda Yola koyulalım Hazlar gülüyor. Gül ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bizi-zamansizlik-ozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '18 Yaşım/Gidiyor Ben Benden', '18-yasim-gidiyor-ben-benden-i-lknur-er-yimkk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir masa kurmuşlar 18 yaşıma

Birazdan gidecek çocukluk benden

Bir bilet almışlar bana sormadan

Yolumu çizmişler bir bilinmeze

Gözlerim bir başka bakıyormuş ya

Vaktiymiş artık 

evlenmeliymiş

Okumakta neymiş diyor babam

Yuva kurmak gerekmiş 

geçermiş yaşım

Bir masa kurmuşlar 18 yaşıma

Onlar kutlamada ben isyanlarda

Ruhumda kelepçelerde

Ellerim serbest

Gitmek çözüm değil zulüm ilk kez

Bir sofra kurulmuş onlara düğün

Birde bana sorun

Ölüm bu ölüm

26.07.05', 'Bir masa kurmuşlar 18 yaşıma Birazdan gidecek çocukluk benden Bir bilet almışlar bana sormadan Yolumu çizmişler bir bilinmeze Gözlerim bir b...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/18-yasim-gidiyor-ben-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-mehmet-dag-567nt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatımın en uzun yolculuğuna çıktım 

Dalıp giden gözlerini görünce

Kendimi ilk defa bu kadar suçlu hissettim

Gözlerinden damlacıklar dökünce 

Yaşamın tüm ezilmişliğini aldım sırtıma

Ant içtim, Yeminler ettim anama, avradıma 

Bir daha hiç kimseyi, ama hiçbir canlıyı

Senin gibi üzmeyeceğime

Sevmek kırmızı çizgilerini çekti beynime

Bilsem ki çözülecek sorunlar, razıyım öleceğime

Doyamadım yaşarken sevdiklerime

Ne ben isterim üzeyim seni, hele sen asla! 

Yaşamın zehir yanı bize sunulan pasta

Ne senin suçun var ne benim bu hususta

Bizi yönetenler Yaşamı parsellemişler, sevgilim

Bize de acıyı, kederi ve hüznü uygun görmüşler

Tel örgüler içinde mayınlı parklar yapıp

Ölümü bizim çocuklarınıza tahsis etmişler…

Adına yaşamak demişler….

Sevgilim adına yaşamak… demişler…', 'Hayatımın en uzun yolculuğuna çıktım  Dalıp giden gözlerini görünce Kendimi ilk defa bu kadar suçlu hissettim Gözlerinden damlacıklar dökünc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerin-169-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada Yirmi Adım', 'arada-yirmi-adim-fidan-bulut-94pp7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyleseydim kızardın değil mi

İlk ayakkabının topuğuna aşık olduğumu.

Yeni yetmeydim ne biliyim işte.......

Evimizin camı kaldırımla bir

Ayakkabı topuk manzara

Olacağı buydu ya.....

Gelip camımın önünde dönüşü topukların geriye

Ancak bileklerindi gözlerimde artakalan.

O topuklardan tanıdım ya saçının şeklini.......

Kulübelere maytap atarken bir jeton uğruna

Ne lükstü ama yirmi adım yakınlık sana.

Ya ilk elimi tutuşun

Sokak kavgasında yere yapıştığımda

Yine topuklarındı gözlerimin ilk gördüğü.

Elinin izi anamın sütü gibi büyyüttü beni o gün

Ütülü pantalon beyaz gömlek girdi sırtıma

Tarak ayna elimde durma senin peşinde.

Bir öğrenebilseydim nereye gittiğini

Elim ekmek te tutacaktı belki

Olmuştuk ya tam olmuştuk

Sen mahallenin yeni güzeli

Ben peşinde kaldırım iti......

Camının altındayım bir gece,

O şarkı bir nefes içimde.

Yanlız hayal etmiştim seni içerde

Masanın baş köşesi benim

Sen gözleri mahcup esirim.

Ah bir kez yirmi adımı geçebilseydim..........

O günlerden kalma tek resim

Ayakkbında donmuş ellerim

Sen karşı kaldırımda kızıl göl kuğusu

Tesadüftür ayakkabın da yirmi adım ötede

Ah bir geçebilseydim...................................', 'Söyleseydim kızardın değil mi İlk ayakkabının topuğuna aşık olduğumu. Yeni yetmeydim ne biliyim işte....... Evimizin camı kaldırımla bir Aya...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/arada-yirmi-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağrur Sevda', 'magrur-sevda-aydin-demirkan-dd0wd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dile düştüğünde özlemlerim

Sahipsiz kalır bir başına

Uzanmaz telefona elim

Duygularım mağrur, öylesine...

İçimden demek gelir; 

''yalancı ayrılık bu''

Bilirim... Değil! 

Evsiz kelimelere

Bir yenisi eklenir; 

Öylesine acır içim

Ağlayamam! 

Daralır cümle yollar

İstesem, yürüyemem...', 'Dile düştüğünde özlemlerim Sahipsiz kalır bir başına Uzanmaz telefona elim Duygularım mağrur, öylesine... İçimden demek gelir;  ''yalancı ayr...', ARRAY['Türk Edebiyatı','Şiir','Aydın Demirkan']::text[], 8.5, '{"poet":"Aydın Demirkan","poet_slug":"aydin-demirkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/magrur-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN ROMANıMSIN', 'sen-romanimsin-olgun-ekinci-sd4hr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yazacağım romanımın			

Kapak resmi			

İlk sözü			

Giriş''i			

Tek kahramanı			

Dip notlarısın…			

Sayfaları çevrilmeye kıyılmayan			

Harfler, kelimeler, satırlarımsın…			

Son sözü, finalini 			

Okurlara bırakacağım romanımın			

İçindekiler bölümünde			

Dizgi dizgi, satır satır			

Romanımı işgal edenimsin…			

Satırlarım			

Sayfalarım			

Roman''ımsın…			

22 / 07 / 2005 - Adana', 'Sen yazacağım romanımın			 Kapak resmi			 İlk sözü			 Giriş''i			 Tek kahramanı			 Dip notlarısın…			 Sayfaları çevrilmeye kıyılmayan			 Harf...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-romanimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızı….', 'deniz-kizi-olgun-ekinci-x8cq8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzüm kahvaltı masasın da uyanırken güne

Gözlerimin denize kilitlendiği

Nemli, kavuran sabah saatlerin deydim…

Dem kokan çayımın ilk yudumu

Dilimi yalarken... 

Yarı dalgalı denizin köpüklerine vuran

Siluetin miydi, serap mıydın uçsuz bucaksız? 

Orda mıydın? 

___Gelecek miydin? 

______Düş müydün? 

Sıcaktan ılığa dönüşen ikinci yudumda

İrkildim…

Ufukta, dalgaların doğduğu ilk anda

Beyaz, çileşen köpükler arasındaydın

Deniz kızıydın, beyaz, mavi, yeşil…

El salladın

El salladım, kayboldun, 

El salladın, kayboldum

Ağladım….

23 / 07 / 2005 - Arpaçbahşiş-Mersin', 'Yüzüm kahvaltı masasın da uyanırken güne Gözlerimin denize kilitlendiği Nemli, kavuran sabah saatlerin deydim… Dem kokan çayımın ilk yudumu ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deniz-kizi-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Hediye', 'son-hediye-cenk-beyazgul-71pg2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne el ele yürüyebildik seninle 

Ne de seni seviyorum diyebildik birbirimize 

Sevildiğimizi biliyorduk ya

O yetiyordu bize 

Sevgi üzerine yazılan her dize 

Anlatıyordu ikimizi 

Ağustos sıcağı değil 

Bir kaçamak bakış eritiyordu bizi

Kavga etmek için bahane aramıyorduk 

Çünkü biz gerçekten seviyorduk birbirimizi

Ama başkaları kırdı kalbimizi

Acı çektim, korktum, hemen sana koştum 

Bir şey oldu mu diye 

Yerinde yeller esiyordu 

Bir veda mektubuydu 

Bana bıraktığın en son hediye..', 'Ne el ele yürüyebildik seninle  Ne de seni seviyorum diyebildik birbirimize  Sevildiğimizi biliyorduk ya O yetiyordu bize  Sevgi üzerine yaz...', ARRAY['Türk Edebiyatı','Şiir','Cenk Beyazgül']::text[], 8.5, '{"poet":"Cenk Beyazgül","poet_slug":"cenk-beyazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Gözlerinde Yeniden Doğdum', 'ela-gozlerinde-yeniden-dogdum-olgun-ekinci-1ziwb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimin gözlerinle ilk randevusu; 

Bayram yeri çocuklarında ki çoşku

Anne sütüne saldıran bebekte ki açlık

Yüksekten korkan Puma kuşunun ilk heyecanıydı...

Durdum, baktım, vuruldum

Vuruldukça baktım, orada kaldım

Çoştum, bulutlara erdim dalgalarca

Göz bebeklerine kilitlendim, sonrası yok

Hüzün dolu gülümsemelerin

Yayılırken bedenime ılık ve dingin

Ela gözlerinde yeniden doğdum...

Sensiz özlemlerimin

Kentsel ayrılık ve iz düşümlerinde

Nerede gülen, ağlayan, hüzünlü

Bir çift ela göz görsem

Muzur ve hain gülümsüyorum, elimde değil

Evrende en güzel ve hüzünlü ela gözler

Sevgisel sıcağıyla  Akdeniz ılımanlığında

Senin yüzüne, kirpiklerinin arasına yerleşmiş çünkü

Ne zaman gözlerini düşünsem

Ne zaman gözlerinle buluşsam

Yeniden doğuyorum ela gözlerin de

Ela gözlerin de doğdum, yeniden doğdum

Oradayım... O gözlerde öleceğim…

23 / 07 / 2005 - Arpaçbahşiş - Mersin', 'Gözlerimin gözlerinle ilk randevusu;  Bayram yeri çocuklarında ki çoşku Anne sütüne saldıran bebekte ki açlık Yüksekten korkan Puma kuşunun ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ela-gozlerinde-yeniden-dogdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-suna-aras-l5ce0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm ölmek midir? 

Yoksa ertelemek mi yaşamı? 

Doğuma gitmektir ölüm belki de

Belki bir alış veriş

Varla yokta imece

Var etmek biraz da sürekliliği

Ya öldürmek ne oluyor? 

Kurmak mıdır sofrada ki dengeyi? 

Zaman nedir? 

Bir boşluk mu içinden geçtiğimiz? 

Bizi soğurarak sona götüren

O bilinmeyen süreç ömrümüz dediğimiz. 

Doğanın tanrıları

En eski halime götürün beni

Sevmem hayatıma karışanları.', 'Ölüm ölmek midir?  Yoksa ertelemek mi yaşamı?  Doğuma gitmektir ölüm belki de Belki bir alış veriş Varla yokta imece Var etmek biraz da süre...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sorular-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanma', 'i-nanma-cem-karadeniz-kis0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '*haki yeşilli şiirler

utanmadın mı? 

açmadın gözlerin hani

inanacaktın yıldızların yalanına

ve karabasanı kovup geceden

yokluğumla sevişecektin

boşalmamı beklemeden,

yıkayacaktın düşlerini 

inadına terimle...

söylemedim mi ben sana

inan dediğim rüyaydı

sen koştun peşine; 

yalnız mıydı sevişmelerin

beni ortak ettiğin 

resmimi kucakladığın

dürüst anlara selam

bensizliğe bir küfür korkusu düştü.

inanma

yalan söyleyemedim

dosta diye...

(Nisan 2001 & Saraybosna-Bosna Hersek)', '*haki yeşilli şiirler utanmadın mı?  açmadın gözlerin hani inanacaktın yıldızların yalanına ve karabasanı kovup geceden yokluğumla sevişecek...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/inanma-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan', 'kanayan-cem-karadeniz-f5ut6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '*haki yeşilli şiirler

yelken diktim düşlerine 

ifil ifil dolsun da

gel diye odama gecede,

kanat kanat türkü saldım uykuna

	ezgi ezgi notaya buladım sabahlarımı, 

kabusuna daldın inceden inceden

kolundan tuttum çıkardım geceden.

yine de kanmadı sevdam

damla damla 

	dudak yordamıyla tattım

sevgini...	

(Haziran 2001 - Mamak)', '*haki yeşilli şiirler yelken diktim düşlerine  ifil ifil dolsun da gel diye odama gecede, kanat kanat türkü saldım uykuna 	ezgi ezgi notaya ...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kanayan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Güncesi', 'askerin-guncesi-cem-karadeniz-6zedm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '*haki yeşilli şiirler

arka arkaya iki bardak sıcak çay

bir de sana yazabilme arzusu özlediğim,

bitmeyen bir tünelde gibiyim

karanlıkta kalabalık 

hırçınım gecelerde,

havada

seni bağıran bir saksağan öfkesi

bir de ışıksız yıldızlar uçuyor

öfke çığlıklarıyla dansediyor gözlerin,

hatırlıyorum

elele çevirirdik takvim yapraklarını

şimdi	

sana dair söylenen 

her yalnızlık şarkısını

süzgün bakışlarla izliyor ellerim,

istemez miydim

gözbebeklerini ışıtan 

mutluluk bakışlı satırlar dokumayı

gel gör ki yalnızlığım

yenik bir şahin kanadının 

hasret yürüyen yangısına tutsak

kalemim sana adanmış bir ömür

tutkuyla...

(10/12/00 & mamak)', '*haki yeşilli şiirler arka arkaya iki bardak sıcak çay bir de sana yazabilme arzusu özlediğim, bitmeyen bir tünelde gibiyim karanlıkta kalab...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/askerin-guncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buruk Vefa', 'buruk-vefa-cem-karadeniz-gerpz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '*haki yeşilli şiirler

koca kent nasıl kaybolur

bir tümce kapısında

sözcükler neden gizler

ağlamaklı ozanlarını şehrin

vefa mı dersin

yalan...

(Nisan 2001 & Zenica- Bosna Hersek)', '*haki yeşilli şiirler koca kent nasıl kaybolur bir tümce kapısında sözcükler neden gizler ağlamaklı ozanlarını şehrin vefa mı dersin yalan.....', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buruk-vefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-cem-karadeniz-jl8q8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '*haki yeşilli şiirler

yeter be 

düş değil

	gerçek bu

umur değil de elbet

ne ki başka

sus artık...

(Temmuz 2001&Mamak-Ankara)', '*haki yeşilli şiirler yeter be  düş değil 	gerçek bu umur değil de elbet ne ki başka sus artık... (Temmuz 2001&Mamak-Ankara)...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korku-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar?', 'neye-yarar-cenk-aksal-612g2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'neye yarar? 

kızkulesinde aşk sensiz,

ve sevişebilmek:hayelleri

rüyalarımda/bedensiz....

      neye yarar? 

      romantik şarkılarda:

      mavi renkli hüznüm,

      şarkılarım/dilsiz

neye yarar? 

buğulanmış rakı kadehi

ve yanında pilakim,

meyhaneci/kedersiz

      neye yarar? 

      yakamozların ışıltıları,

      mehtabın dinginliği,

      yüreğim isyanlarda...

bu gün,her gün

geçecekse sensiz:

yaşamak/hevessiz

neye yarar? 

 ''''yıldızım düşmüş gökyüzünden''''

''''mavinin hüzünlü enginlerine''''

''''neye yarar? ''''

''''deniz kızından öpüşlerim''''

''''hissiz kalmış dudaklarımda''''

''''neye yarar? 

''''baharım,yaz''ım''''', 'neye yarar?  kızkulesinde aşk sensiz, ve sevişebilmek:hayelleri rüyalarımda/bedensiz....       neye yarar?        romantik şarkılarda:      ...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neye-yarar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykırı Sevdaların FİRARİ Aşıkları', 'aykiri-sevdalarin-fi-rari-asiklari-olgun-ekinci-ppizv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '_______Firari

_________Göçebe

___________Çingene sevdamıza dair

Aynı coğrafyanın farkı iklimlerinde

Aykırı yürekleriz firari aşklar üreten 

Gün batımının farklı kızıllaşttığı  ayrı kent akşamlarında

Eleştirilerini ok gibi saplayanlara direnen yüreğin

Ay ışığı firarlarım oldu 

Tanırken seni….

Aykırı bir adam, öz eleştirisiz

Evreni, gökkuşağını yeniden yaratmaya soyunuyor…

Uçurum başlarına yasak ve yabanıl

Kır çiçekleri ekiyor topraksız…

Aynı coğrafyanın, uzak kentlerinin gecesinde

Ki…..

Sana varmak için bütün çabası…

İklim kuşağında savunurken aykırı sevdanı

Savunurken ben nem kokan gecelerde... 

Sensiz, sessiz ve şiir kokan özlemlerimde

_______Firari

_________Göçebe

___________Çingene sevdamıza

Yeni anlam ve kaçaklıklar yüklemek için

Bir yol çiziyorum geceden sabaha

Ve ayrı kentleri birleştirmek adına

Yollardan, dağlardan, ovalardan,

Yer altı nehirlerinin gizemli akışından

Toros''ların heybetli zirvelerinden uçarak

Sana ulaşıyorum, aykırılaşıyorum

Aykırılaşıyoruz iklimlerimizi birleştirerek…

Anlamlar katıyoruz yabancısı olduğumuz

Kentlerin, ilçelerin, deniz kenarında

Tahta masalı çay bahçelerinde

_______Firari

_________Göçebe

___________Çingene sevdamıza

Anlatacağız…

Anlayacaklar…..

Savaşımız, emeklerimiz; 

Göçebe obalarında filizlenen 

Sevdalar üreten masumiyetimize

Aykırılığımız, firarlarımız, militan aşkımıza

Özgür ve yaşanılası mutluluk  giydirmek için

22 / 07 / 2005 - Adana', '_______Firari _________Göçebe ___________Çingene sevdamıza dair Aynı coğrafyanın farkı iklimlerinde Aykırı yürekleriz firari aşklar üreten  ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/aykiri-sevdalarin-firari-asiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorma Beni', 'yorma-beni-cem-karadeniz-4lucy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '*hâki yeşilli şiirler

seni silerdim

arkama bakmazdım hem de...

gel gör ki korktum

kim kollarında saklardı gözbebeklerini

kim bilirdi kıymetini ellerinin

benim gibi

	kim okşardı gözlerinin beyazını

		kahvesini bırakıp...

kim yanardı kokunun sihrine ben gibi

kim ağlardı gördüğün kabusun resmine

kim sürerdi terinden akan

	sevgi tarlasını elleriyle

kim...

yorma beni 

seni nasıl bırakıp

	yadellere,

		kime güveneyim

yok ki bu dünyada...

(Mayıs 2001 & Sarajevo - Bosna Hersek)', '*hâki yeşilli şiirler seni silerdim arkama bakmazdım hem de... gel gör ki korktum kim kollarında saklardı gözbebeklerini kim bilirdi kıymeti...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yorma-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmansın', 'pismansin-cem-karadeniz-yvfx6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '*haki yeşilli şiirler

hangi mevsimdi küstüğün

bilmiyorsun

unutmuşsun esintisini baharın

kışa küsmüş, güze ağlamışsın

	                        sırtını dönüp

yaza kucak açtığında 

kovulan sensin bu kez

ter damlacıklarına hapis

tuzlu bir pişmanlık teninde...

(Mart 2001

Zenica / Bosna Hersek)', '*haki yeşilli şiirler hangi mevsimdi küstüğün bilmiyorsun unutmuşsun esintisini baharın kışa küsmüş, güze ağlamışsın 	                      ...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pismansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakkase', 'rakkase-i-lknur-er-p7j51', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhumda dans ederken, rakkaseler 

Bir oyanda bir bu yanda cilveler nazlar

Bir şen kahkaha koyup ortaya

Sende kısmetini buyur diyorlar

Yüzümde bir maske öyle yerleşmiş

Çıkarıp atma vakti çoktan geçmiş

Başlarken ruhumla çatışma

Kahkahalar, isyanlar ortada

Ben bir yanda, ruhum bir yanda', 'Ruhumda dans ederken, rakkaseler  Bir oyanda bir bu yanda cilveler nazlar Bir şen kahkaha koyup ortaya Sende kısmetini buyur diyorlar Yüzümd...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/rakkase-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Anılarımda Kal', 'hep-anilarimda-kal-burhanettin-akdag-ronyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski güzel günlerim geldi aklıma birden

Seninle yaşadığımız, çılgınca

Coştuğumuz, çağladığımız 

Kah eğlenip, kah ağladığımız 

Kırda bayırda koşuşturup ard arda

Papatya ve menekşelerin resitalinde

Gelincikleri okşayıp öptüğümüz

Sarılıp yuvarlandığımız yamaç aşağıya

Nefes nefese serilip yeşilliklere.

Ne güzeldi o günler

Bir günü bir seneye eşdeğer 

Doyumsuz, heyecanlı

İçimiz kıpır kıpır sevdalarda

Sevgiyle gülerdi gözlerimiz

Bir çiçek yumağı gibiydi gülüşün

Ama hepsi birer mazi şimdi aşkım

Ağır, kapalı ve kasvetli hava gibi

Göremiyor, seçemiyor ileriyi gözlerim

Süzemiyor güzelliğini, alamıyor sıcaklığını.

Oysa ne kadar şen, çocuklar gibiydik

İçimiz, içimizden taşardı fokur fokur

Şimdilerde ağır, boğucu hazan kokusu

Barut misali dağlıyor kalbimi

Pas tutmuş yüreğim, gıcırdıyor

Renkleri seçemiyorum, duyarsızım

Beni hayata bağlayan tek bir düğüm

Seninle yaşadıklarım  eskilerde

Düşündükçe mutlu bir tebessüm, o bile yetiyor.

O halde hep eskide kal aşkım

Olmasa da duyguların yüreğimde

Hep anılarımda kal

Diri, taptaze, sanki dün gibi

Olmasa da varlığın yanımda

Hep anılarımda kal

Bende kal...

(29.09.2004)', 'Eski güzel günlerim geldi aklıma birden Seninle yaşadığımız, çılgınca Coştuğumuz, çağladığımız  Kah eğlenip, kah ağladığımız  Kırda bayırda ...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hep-anilarimda-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Bekledi Yüreğim', 'hep-bekledi-yuregim-burhanettin-akdag-r6fcj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice yangınlarla yandım

Kara bulutlar çöktü kaderime

Sahte gülücüklerin, yarınsız aşkların 

İsimsiz, yavan sevgilerin

Bol olduğu âlemde.

Her şeye rağmen

Bozulmadı saflığı kalbimin

Aynı karatta duygularım 

Yılmadı, yüksünmedi

Ruhunu karartmadı olmazlarla

Darılmadı kimseye gönlüm.

Ama, 

Hep itildi sevgim, kakıldı yüreğim

Horlandı, aşağılandı ruhum

Verdikçe aldılar

Aldılar da, başka yok mu dediler? 

Yetmedi, bir daha, bir daha

Sonu yok.

Yılmadı yine sevdam

Yıkılmadı bu can

Beden sallansa da payanda oldu yüreğim

Dik durdu sevgim

Hep mutlu, hep umutlu

Aynı heyecanla, bıkmadan

Oğul vererek yeni sabahlarda

Geleceğe uyanıp, canlandı

Güneşle yeniden doğdu heveslerim.

Gecelerin gizeminde 

Gözyaşım susturdu umutsuzluğu

Hep bekledi yüreğim

Geri durmadı sevme inadından

Yine bekleyecek

Sabırsızca saracak yarınları

Sükunla, sessizce...

(22.07.2005)', 'Nice yangınlarla yandım Kara bulutlar çöktü kaderime Sahte gülücüklerin, yarınsız aşkların  İsimsiz, yavan sevgilerin Bol olduğu âlemde. Her...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hep-bekledi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evvel Zaman Öyküleri', 'evvel-zaman-oykuleri-selahattin-durna-7l9xh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evvel Zaman Öyküleri

           -Yalanlarımız vardı; ömrümüzü verdik.

		Kimseler inanmazdı,biz inanırdık.-

			1	*

                                                                                             

		Otuz yıl önce; dehrin pirleriydik.

		Uzun,ak sakallarımız vardı.

		Her şeye aklımız erer,herşeyi bilirdik; 

		Avcumuzun içindeydi evren; 

		Karanlıkta kara taşın üstünde gezen 

		Kara karıncayı görürdük gözü kapalı.

		Otuz yıl önce delikanlıydık; hani

		Pimi çekilmiş bir bomba yani.

		Bir kamyonu çeker gibi halatla

		Değildi ki yaşamak..

		Benzin dolu bir bidona çalıvermek kibriti,

		Silkivermek başaşağı içi dolu çuvalı,

		Bir tomruğu yuvarlamak dik bayırdan aşağı,

Taş sektirmek havuzunda kaymakam konağının...

2			*

Otuz yıl önce

Ayağımıza taş değmezdi

Kurşun işlemezdi tenimize

Suda ıslanmaz

Yanmazdık ateşte

Üşümezdik,yorulmazdık,acıkmazdık.

Korkmazdık yanlışlardan

Ölümlerden korkmazdık.

Otuz yıl önce

Şapkamızdan kuş çıkarırdık,

			Tavşan çıkarırdık.

Abartılmış Berec piller gibiydik,

			Mutluluk üreteci…

			*

3

Otuz yıl önce

Çoktuk,bir ülkeydik,memlekettik,halktık

Yürüdük mü,

Kırk milyon çift ayak yürürdü ardımızdan

Doğrularımız vardı

Yanıltmayan,utandırmayan,eskimeyen

Bıraksalar

Oturup anlatacaktık kırıp dökmeden.

			*

4

Otuz yıl önce

Yollarımız vardı,yoldaşlarımız vardı

Ellerinde bayrakları

Dünyayı çepeçevre kuşatırlardı.

Düşlerimiz vardı:

“Güzel günler görecektik,

Güneşli,güzel günler…”

			*

5

Otuz yıl önce kardeşlerimiz vardı

Birbirimizin sırtını kaşır,

Sivilcelerini patlatırdık.

Birimiz nezle olsa,hapşırırdık hepimiz

Parmağı kanasa birimizin

Kan olurdu ellerimiz

Ayakları üşürdü hepimizin

Yalın ayak kalsa birimiz.

Başımızda kavak yelleri esse de

Aklımız bir karış havada değildi.

Konuşurken ormandık,susarken dağ.

Önce büyük harflerini söktük hayatın.

Kestirmeden oyunun tam ortasında bulduk kendimizi; 

Ezbersiz,provasız…

6		

Otuz yıl önce

Dağlarımız vardı,ormanlarımız vardı,

Dal fidanlarımız…

Bedreddin sürgünü.

Gelip bir uçurumun önünde bırakmazdı hayat

Böyle çözümsüz.

Böyle dört duvar arasında sıkışıp kalmazdık

Böyle,bir çıkmaz sokakta kıstırılmış it gibi,

Böyle yapayalnız…

Çeklerle,vadelerle,taksitlerle kuşatılmak yoktu

Böyle pusuya düşmüş gibi..

Bir paket çay,iki yüz elli gram şeker

Geldi miydi denk,

Denkleşirdi bütçesi ülkemizin.

Bir Bafra paketini üleşirdik parmaklarımızı üleşir gibi…

			*

7

Otuz yıl önce

Doğum tarihlerinin yanında ölüm tarihleri olmayan

Şehitlerimiz vardı.

Ölmezler 

Yüreklerimizde yaşarlardı.

Cennete inanmazdık,cehenneme inanmazdık.

Yaşamak bu yanıydı işlemeli bir kapının; 

Ölüm,öbür yanı.

Yazıyla tura gibi,akreple yelkovan..

Şaraba dönüşmekti ölmek,üzümce.

8

Otuz yıl önce

İtirazımız vardı

Görülmemiş hesaplardaydık,ama görülecek

Dürülmemiş defterlerdeydik,ama dürülecek.

Namluya mermi sürmek gibiydi yaşamak

Ya da zorlamak bir dağın zirvesini.

Otuz yıl önce

Uçsuz bucaksız bir ovada

At sürmek gibiydi yaşamak

Dönüp ardına bakmadan.

9

Otuz yıl önce

Uyku ölümdü bizim için

Böyle sırt hamalı gibi

İki büklüm taşımazdık hayatı

Zifiri yalnızlığın en kıyısında

Doğrulur kalkardık bir arkadaş ıslığında.

10

Otuz yıl önce

Yakamızda kir,burnumuzda sümük,

Paçamızda çamurdu yokluk.

Ama karnımız doyardı gerçekten.

Karpuz,karpuz tadındaydı çünkü; 

İri,bol çekirdekli,kırmızı..

Kavun,kavun gibi kokardı.

Böğürtlenler ellerimizi kanatır.

Yüzümüze kan gelirdi kara dut lekesinden.

İnsanlar sıcacık gülerdi,ekmek gibi

Ekmeklerin kokusu ötelerden duyulurdu.

11

Otuz yıl önce

Duvarlarımız vardı

Üstüne oturur,sırtımızı dayardık.

Ekvator gibiydi; 

Başladığı yerde biten,bittiği yerde başlayan hep.

Gölgesinde koşardık.

Sevgilinin bahçesine gül atar gibi

Usulca,korkarak,ağır uykularda

Cahil,serseri,it

Ama yürek atışlı

Yazılar yazardık:

“Somedova! Somedova! 

Kavga sonuna kadar kavga! 

Seninleyiz Nikaragua! 

Şah bir yana,taht bir yana! “

Artık bütün balkonlarda

Siyah,üzüm sakallarıyla

		Fidel konuşmaktadır.

Yamacında Che Guevera..

12

Otuz yıl önce türkülerimiz vardı,

Gözlerimizi yumar yumar dinlerdik.

Terkilerinde büyük adımları gelirdi

Büyük,hızlı bir koşunun…

Çevresinde bağdaş kurup otururduk; 

Uzatıp ellerimizi ısıtırdık tandırında.

“Tanrının kullarından bir tanesi özgür değilse,

Tanrının kullarından hiçbiri özgür değildi.”

Ama biz özgürdük türkülerce,

Tel örgüler arkasında bile.

Bir yanımız Rahip Tutu,

Bir yanımız Zapatista..

Böyle at izi it izine karışmamıştı daha.

İçimiz aydınlık,ışıklı.

Bir kardeş sofrasıydı dünya.

Bir şafak tüfek çattık Bolivya dağlarında; 

Şili’de bir gece yenildik Allende’yle..

Gdanks’ta dok işçileriyle grevdeydik,

Tiyamennan meydanında önüne durduk tankların.

13

Otuz yıl önce

Tolstoy''duk,Şolohov''duk,Dostoyevski...

Uzun öyküler yazacaktık,

                                  Nehir romanlar..

Çünkü öykü tadında yaşanmıştı herşey,

Roman kıvamındaydı düşlerimiz bile.

Değilse yaşanmazdı

Değilse değmezdi.

Akıp giden bir derenin kıyısındaydık

Dere değildik,su değildik,

                                Çakıltaşı değildik ama,

Müdahildik yaşamak denen davaya.

14

Otuz yıl önce

Muhaliftik, marjinaldik, aykırı.

Darbeler gördük,darbeler yedik.

Mağluptan yanaydık illaki

Menderes''e üzülmüştük,yüzlerine bakıp büyüklerin; 

Kennedy''e ağlamıştık,süt tozumuz kesilecek diye; 

Yastaydık Cengiz Topel düştüğünde; 

Suphi Kaner küçük dayımızdı,yemeden içmeden kesildik.

Ama ilk kez Deniz''le yaşadık ölümü,içinden.

Sonra Mahir..sonra..daha..

Kardeşlerimiz öldü.

Kardeşlerimizi öldürdük, kardeşlerimiz öldü diye.

Kendi kitaplarımızı yaktık,kendi fidanlarımızı yaktık,

                                                  Geleceğini yaktık ülkemizin.

Beş bin yıllık bir toprak,ot bitmesin diye üstünde

Yakıldı göre göre.	

			

15

Otuz yıl önce

Promete’siydik çağın.

Büyük ateşler ölçerdik,

Büyük bayraklar taşıdık

			Yukarı,daha yukarı.

Büyük kapılardan baktık.

Bıraksalar,

Bütün kirli denizleri temizleyecektik.

Köprüler çatacaktık bütün ırmakların üstüne,

Yollar yapacaktık yüksek dağların üstünden aşan,

Bütün ağaçların dallarına salıncaklar kuracaktık,

Bütün çocukların ellerine uçurtmalar verecektik,

Ayaklarında kırmızı pabuçlar…

Bütün açlar doyacaktı.

Büyük ocaklar çatacaktık,

			Üşümeyecekti elleri annelerin.

İşsizlere iş verecektik; 

Babalar şapkalarından utanmayacaktı.

16

Otuz yıl önce

Büyük, beyaz bir tuvaldi hayat

Kırmızı elma resimleri çizecektik,büyük ağaçların yüksek dallarına

Yumuşak, beyaz,pamuk tüyler ekleyecekti kuzular

                                                            Yeşiline çimenlerin

Uzak denizler bakacaktık,

                          Derin ırmaklar, 

                                        Sık ormanlar...

Masallar masalları üretecek,

Çocukların elleri büyüyecekti.

17

Otuz yıl önce

Kulaklarımız ağır işitmezdi böyle

Gözlüklerimiz yoktu,takma dişlerimiz yoktu

Saçlarımız böyle ak pak,

Yüzümüz böyle buruş buruş değildi

Böyle kırık dökük,çatlak patlak değildik.

Damla sızdırmazdık bir yudum sevgi bulsak.

Zambaklar şahidimizdir

İğde çiçekleri şahidimizdir.

Güneşi,ayı bilirdik; 

Yıldızlar şahidimizdir.

Çoktuk,kalabalıktık

Yumruklarımızı sıkar sıkar bağırırdık.

Ama yalnız kaldık mı

Bir Bülent Ersoy şarkısının hicranına susar,

Oturur ağlardık.

18

Otuz yıl önce

Şiirlerimiz vardı,göğsümüzde taşırdık; 

Cevşen gibi,Mushaf gibi,muska gibi…

Mataramızda su

	Torbamızda ekmek

		Ve kemerimizde kurşun gibi

Taşıdık şiiri biz.

Kapı komşumuzdu Hasan Hüseyin

Bir bardak şeker,bir kaşık tuz istedik.

Ekmek istedik.

Kimi Atila İlhan’dık

Uzun burunlu ayakkabılarımızın

			Topuklarına basar

Tenha istasyonlarda/esrarengiz

Gece yolcuları beklerdik

Boynumuzda kırmızı fularlar..

“Ne kadınlar sevdik,zaten yoktular.”

Yakışırdı bize

Hilmi Yavuz’da hüznü keşfederdik.

Acının vergisini verir,

Zulmün haracını öderdik bir çilingir sofrasında.

Devrimciydik haddizatında ama

Ferdi Tayfur kadar derbederdik.

Arkadaşlık,der sık ormanlar getirirdik aklımıza

Omuzlar dayanırdı omuzlara

Omuzlar omuzlara

Arkadaş olduk Arif Damar’a.

Nazım’laydık

Bir toprak nasıl sevilir memleket diye

Ondan öğrendik.

Aynı koğuşta hapis yattık

Aynı göğe kaldırıp başımızı

Birlikte yıldızlara baktık.

Türküleri onunla sevdik,Türkçe’yi onunla,Türkiye’yi onunla…

Varna’da birlikteydik; 

Ondan öğrendik

Uzaktan nasıl okşanır sevdiğin bir insanın sıcacık başı.

Ellerimiz yandı.

19

Otuz yıl önce

Ruhi Su,seferberlik türküleri söylerdi; 

Biz,seferberlik türküleri dinlerdik otuz yıl önce.

Ve o,muhtemelen bin yaşındaydı 

				bu türküleri söylerken

Biz  muhtemelen onunla yaşıttık.

Yemen türkülerine uydururduk ayağımızı yürürken

Yemen türküleriyle bulurduk haritada yerimizi.

Memleketi sevmek ayıp değildi,böyle

“Vatansever,yurtsever”diye tanımlardık kendimizi.

Kılına zarar gelsin istemezdik ülkemizin.

“Satılmış”tık ama,

Kıyamazdık bir karış toprağını satmaya.

20

Otuz yıl önce,gazetelerimiz vardı/okurduk

Adını duyduk mu

Doğup büyüdüğümüz mahallemiz gelirdi aklımıza

Evimiz gelirdi.

Köşe yazarlarımız vardı

Köşe başındaki komşumuzdular

Akrabamız,yakınımız,dostumuzdular

Her sabah sofralarına buyur ederlerdi bizi

Bir tas sıcak çorba tadında okurduk 

Yazdıkları her yazıyı.

Onlar noksandan söz eder,

Biz tamı anlardık.

Onlar yanlışa yüklenir,

Biz doğruyla dost olurduk

Çirkinden dem vursalar,

Bir güzelin sevdası düşerdi içimize.

Kendilerinden önce

Bizi düşünürlerdi.

Kokmazlar,çürümezler,

Satılmazlar,

Dönmezlerdi.

21

Aşklarımız vardı otuz yıl önce

Çörden çöptendiler belki

Ama gerçektiler

Çoktular

Adları vardı

Bir de rüzgarda uçuşan sarı saçları

Adresleri vardı sade,aracısız

Bir otobüs durağıydılar

Bir okul çıkışıydılar.

Elleri var mıydı, bilmezdik

Ayakları var mıydı,bilmezdik

Bir yerlerden gelir

Bir yerlere giderlerdi

Ama hep yüreğimize basıp.

Gözleri vardı

Bir çimdik umut görsek gözlerinde

Sabaha kadar uyuyamazdık.

22

Otuz yıl önce

Fitil gibi sevdaydık

Usul sevdik

Kerem''dik Aslı''sız

Ferhat''tık Şirin''siz

Mecnun''duk Leyla''sız..

Yarımdık,yamalıydık,yaralı...

''Kendi saçlarımızı okşadık sevgilinin saçları niyetine''

Kendi dudaklarımızı öptük

Kendi gözlerimize baktık bakamadığımız gözler yerine

Eziktik,ağrılıydık,efkarlı..

Umutlar eskittik,hayaller örseledik,rüyalar gömdük.

Yiğittik yiğit olmasına da

Hep kendi ordularımızı yendik

               Kendi kalelerimizi fethettik

Kendi burçlarımıza diktik bayraklarımızı

Kendi yaptığımız putlara açtık avuçlarımızı

Dualar acıttık,dualar üzdük.

23

Otuz yıl önce

Okyanus değildik haşa,

Deniz değildik tamam,

Irmak değildik belki...

Büyük denizlere sevdalıydık ama.

Ummanlar taşıdık yüreklerimizde

Küçücük bir dere güzergahında.

24

Otuz yıl önce

Uzak mezralardan geldik

Köylerden,küçük kasabalardan

Kenar mahallelerden geldik.

Adlarımız vardı

Sahici,bildik,kendimizden...

Yenilen takımları tutuyorduk hep

Yenilen takımlara girdik

Ayağımızda lastik pabuçlar...

Topu taca attı kimimiz

Kimimiz kendi kalesine gol

Acelesi vardı kimimizin ofsayta düştük

Yenildik penaltılarda

25

Çoktuk

Gökte yıldız,denizde kum kadar

Aynı ağacın meyveleri gibiydik,tanırdık birbirimizi

Hoşlanırdık birbirimizden,

		Yaslanırdık birbirimize

Aynı kitapları okurduk,aynı türküleri söylerdik,

Çoktuk

Yüklensek

Yerçekimi onaylardı gücümüzü



26

Ama yenildik

27

Babalar oğullarından utandı

Analar yüzüne bakamadı kızlarının

Erdem ölümle sınandı

Hayaları buruldu yoldaşlığın

Yenenler

Sopalarını gösterip korkuttular gözümüzü

Işıklı kentlerini gösterip aklımızı çeldiler 

Kızlarımız etlerini,

Oğullarımız yüreklerini sattı sendikasız,sigortasız...

Uzak düştük,kenar düştük varoşlarda; mecalsiz...

28

Oysa biz kurmuştuk bu şehirleri taş taş,tuğla tuğla…

29

Yenildik

Sevdalar örselendi

Kardeşlikler örselendi,yoldaşlıklar örselendi

Mevsimler kışa vurdu

Uzak bir dönencede yitip gitti düşlerimiz

Kayıp uygarlıklar gibi

Umut yenildi,onur yenildi,emek yenildi

Yenildik 

Ellerinin kınasıyla kız kardeşlerimiz

Annelerimiz gümüş telli saçlarıyla

Yırtık şapkalarıyla babalarımız yenildi

Tarlada nasırı öpülesi ellerin

Fabrikada alın teri yenildi

Kıblesi yıkılmış Müslüman gibi şimdi

					Onca umut, onca yürek

Şakülsüz, terazisiz, gönyesiz…



30

Otuz yıl önce 

Yaşamak

Yasaktı,yasa dışıydı,anayasaya aykırıydı,tamam

Ama yaşıyorduk

Erik çalar gibi komşunun bahçesinden

Ayak parmaklarımızın ucunda.

Oysa şimdi

Tropikal bir meyve kıvamında artık

Tadı yok, kokusu yok, öyküsü yok

Bir şeyler çağrıştırmaz.

Bir suçtur,bir ayıptır,günahtır yaşamak

Kimselere söylenmez

Kimselere anlatılmaz.', 'Evvel Zaman Öyküleri            -Yalanlarımız vardı; ömrümüzü verdik. 		Kimseler inanmazdı,biz inanırdık.- 			1	*                           ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":432,"source_url":"https://www.antoloji.com/evvel-zaman-oykuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazar değmesin diye', 'nazar-degmesin-diye-halil-colak-oksne', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen kardelen çiçeğisin yükseklerdesin

Kimse koparmasın koklamasın diye

Ben senim,sen bensin çok sevdim seni

Aşkımı söyleyemem nazar değmesin diye

Halil Çolak 26.7.2005 Ankara', 'Sen kardelen çiçeğisin yükseklerdesin Kimse koparmasın koklamasın diye Ben senim,sen bensin çok sevdim seni Aşkımı söyleyemem nazar değmesin...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nazar-degmesin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Bozuğu', 'dus-bozugu-arzu-gulucudur-tkm48', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yamacına düşmüş düşlerim, dizelerimin...

Yer olmuş yüreğimde gözlerin

Damlaları yakışırdı  yüzüne izlerin...

Sen ağlama sevdiğim ben ağlarım senin için

Hançer iz bırakır sırtımda

Koca bir yük sevda kapımda

Ağırlığı hoştur belki aslında

Olsada olur olmasa da...

Yolu yokuştur belki oraların

Yarı çimen yarı çamur kırların

Sevdalısına yanık kokar zamanın

Sevmeyen ne bilsin kokusunu baharın

Bahar ki yürekte güneşler doğurur

Sevdaya susayan canı aşka doyurur

Gelen bir günle başlar umutlar

Umudun sevdasını dünyaya duyurur

Umut ki yürekler dağlatır

Sevdasına sevdalananı ağlatır

Damlaların izi sevdiğime pek yakışır

Sevda zordur geçilmez, acıdır suyu içilmez...

Dağ dağ gezdirir mecnunu

Feryad ettirir karunu

Leyla düşer çöllere mecnun olur

Yüreklerde kavrulur bir düş bozumu...

(adımı yazmak gelmdi içimden :)', 'Yamacına düşmüş düşlerim, dizelerimin... Yer olmuş yüreğimde gözlerin Damlaları yakışırdı  yüzüne izlerin... Sen ağlama sevdiğim ben ağlarım...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dus-bozugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyamın Adı', 'oyamin-adi-fidan-bulut-tddci', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babaannem iğne oyası yapardı,

El emeği göz nuru nevinden

İncecik ipeği büker

Ne de yakıştırırdı iğneye.

Gözlükleri kalındı anlıyorum şimdi........

Ben de seni bana öyle işlemiştim.

Oyamın adı

Saçının tek teline hasret olmamalıydı.

Cam gibiydi sevgimiz oysa

Saf temiz önü arkası aydınlık.

Sabahı iple çeker

Akşamı mahcup beklerdim.

Tarladan hasadımızı 

Bahçeden ürünümüzü

Çocuklarımız gibi toplardık.

Sırt sırta verip duru suya

Umutlarımızı yollardık.

Çiçekler bize açar

Kuşlar bize şakır sanırken 

Bir deste kağıda satmışsın sevdayı

Yüreğimde cam kırıkları onları da anlıyorum şimdi...........', 'Babaannem iğne oyası yapardı, El emeği göz nuru nevinden İncecik ipeği büker Ne de yakıştırırdı iğneye. Gözlükleri kalındı anlıyorum şimdi.....', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oyamin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrik cümle', 'devrik-cumle-gorkem-kaya-ue7bs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Satır

aralarına sıkıştırdım seni

Gözlerine her bakışımda

Parmağım geliyor aklıma

Sıkıştırdığın

kapı

arasına', 'Satır aralarına sıkıştırdım seni Gözlerine her bakışımda Parmağım geliyor aklıma Sıkıştırdığın kapı arasına...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/devrik-cumle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum', 'erzurum-halil-colak-yptyb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine vatan severliğinle düştün dilere

 Haykırarak sahip çıktın ay yıldızlı bayrağa

 Can verdinde uğrunda düşürmedin yerlere

 Dosta dost düşmana korku salan Erzurum

Kartalların uçuşur yüksek dağlarda

Dadaşlar haykırıyor yine yollarda

Kimi bebe,kimi doksan çağlarda

Hiçbir diyara benzemez benim Erzurum

Gönlümden çıkmıyor gam ile keder.

Hasretinle de oldum derbeder

Beyazlar giymiş kahraman diyar

Aklımdan çıkmazsın canım Erzurum.

Aras nehri coşmuş hazara akar

Erzurum sevdası beni de yakar

Ozanlar sana destanlar yazar

Uyuyanları uyandıran Erzurum

Horasanereni’yim tükenmez sözüm

Ne kadar, methetsem yetmezde gücüm

Sana doyamadım kalmıştır gözüm

Kahramanlar diyarı güzel Erzurum

Halil Çolak 3.5.2005 Ankara', 'Yine vatan severliğinle düştün dilere  Haykırarak sahip çıktın ay yıldızlı bayrağa  Can verdinde uğrunda düşürmedin yerlere  Dosta dost düşm...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/erzurum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnalar', 'turnalar-halil-colak-544sc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanat çırparsınız yüksek yerlerde

Uçun şu gökyüzü sizin turnalar

Dolaşıp  durun siz semalarda

Erzurum’un göllerine konun turnalar

Turnalar ucun gidin bizim ellere

Selam söyleyin bizim köylere

Sahip çıkın bizim mavi göklere

Erzurum’un göllerine konun turnalar

 Halil Çolak 64.2005 Ankara', 'Kanat çırparsınız yüksek yerlerde Uçun şu gökyüzü sizin turnalar Dolaşıp  durun siz semalarda Erzurum’un göllerine konun turnalar Turnalar u...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/turnalar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bencil İnsan', 'bencil-i-nsan-nedim-filiz-r5kgr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey bre gafil ve bencil insan! 

Bu öfken, bu kinin niye.

Birgün yalnız ve tek başına kaldığında,

Eşşeğe sarılırsın dost diye...', 'Ey bre gafil ve bencil insan!  Bu öfken, bu kinin niye. Birgün yalnız ve tek başına kaldığında, Eşşeğe sarılırsın dost diye......', ARRAY['Türk Edebiyatı','Şiir','Nedim Filiz']::text[], 8.5, '{"poet":"Nedim Filiz","poet_slug":"nedim-filiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bencil-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu', 'duygu-yurdagul-kurnaz-6tbac', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yangin söner közden önce

Yürek aglar gözden önce

Yüzümdeki cizgiler

Gecmisimden ezgiler

Siirlerim bir bir hayat buldu

''Siiri'' nefes nefes

Hece hece yasiyorum

Gecemi aydinlatan

Yalnizligimla

Noktadan sonra.

Yeni bir misrayla

Virgülden sonraki,

Heceyi

Icime cekercesine

Yasayarak

Okuyorum

Yaziyorum

''Umudun bittigi yerde Siirler yasar''', 'Yangin söner közden önce Yürek aglar gözden önce Yüzümdeki cizgiler Gecmisimden ezgiler Siirlerim bir bir hayat buldu ''Siiri'' nefes nefes He...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duygu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siir Sevgisi', 'siir-sevgisi-yurdagul-kurnaz-k0roo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim baktiysa sana seven gözlerle

Hicbiri benim gördügümü görmedi

Bastan basa Ask oldum

Siirsel yolculuklarda

Tesselliler, ümitlerimin yeri oldu

Nefret-i ise inkardayim

Ne darbeler yemis su kalbim

Hep sevgiyle atacak

Tik tak, tik tak...', 'Kim baktiysa sana seven gözlerle Hicbiri benim gördügümü görmedi Bastan basa Ask oldum Siirsel yolculuklarda Tesselliler, ümitlerimin yeri o...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siir-sevgisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu zar', 'ahu-zar-halil-colak-rq66c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cemre düştü gönlüme bitmez ahu zar ile

Gezmedim derde derman ol Bergüzar ile

Yalvardım yakardım,hey hat kar eylemedi

Hicran ile yandım tüttüm ol Bergüzar ile

Halil Çolak 26.7.2005 Ankara', 'Cemre düştü gönlüme bitmez ahu zar ile Gezmedim derde derman ol Bergüzar ile Yalvardım yakardım,hey hat kar eylemedi Hicran ile yandım tüttü...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ahu-zar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SeVgI', 'sevgi-yurdagul-kurnaz-a26s8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yer varsa sevgiye

Insanliktir kafiye

Filizlenen hediye

Gonca güldür sermaye

Vefayi sende iste

Insanoglu a-heste

Kim kalmis ki kafeste

Can gider bir nefeste...!', 'Bir yer varsa sevgiye Insanliktir kafiye Filizlenen hediye Gonca güldür sermaye Vefayi sende iste Insanoglu a-heste Kim kalmis ki kafeste Ca...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-190-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-galip-ozdemir-tj4uo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'elimin üstünde kimin eli var

yalnızlığımın eli

elimin üstünde kimin eli var

bir çocuğun eli

elimin üstünde kimin eli var

umudumun eli

elimin üstünde kimin eli var

bir kuşun eli

elimin üstünde kimin eli var

kuş uçup gitti

oyun bitti…', 'elimin üstünde kimin eli var yalnızlığımın eli elimin üstünde kimin eli var bir çocuğun eli elimin üstünde kimin eli var umudumun eli elimin...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oyun-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İnsan', 'ey-i-nsan-nedim-filiz-56fon', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanma ki bu dünya kalacak sana,

Ki kalmadı hiç kimseye, ne sultan Süleymana,

O zaman niye zulmedersin, zavallı mazluma,

Görmezmisin acı çekenleri, etrafına baksana', 'Sanma ki bu dünya kalacak sana, Ki kalmadı hiç kimseye, ne sultan Süleymana, O zaman niye zulmedersin, zavallı mazluma, Görmezmisin acı çeke...', ARRAY['Türk Edebiyatı','Şiir','Nedim Filiz']::text[], 8.5, '{"poet":"Nedim Filiz","poet_slug":"nedim-filiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-insan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-abdullah-ortak-967tf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin rengi siyah

Kalp atışları hüzün

Karanlığın gözbebekleri gülümsüyor

Tebessümleri hasret

Tebessümleri acı

..Ve ben kırık kaldırımlarda bir başıma 

Dudak aramda sigara

Seni arıyorum 

Yada sensizliği

Belki de Vuslatı.......

Sigara dumanımı alıyorum kılavuz

Küllerini bırakıyorum ıslak caddenin avuçlarına

Yalnız

Usul usul 

Ağırdan hasret türküleri söylüyor ıslığım,

Yağan yağmur göz yaşlarım

Islatıyor yanaklarımın yamaçlarını

Dudaklarımın eteğine doğru

..ve ben güzelim, ve ben ilk defa ağlıyorum böylesine

Sana 

Yada sensizliğe

Belki de vuslata.....

Patika yolları kıskandırıyorum

Soğuk adımlarla yürüyorum

Kara gecenin koynunda

Seni arıyorum

Yada sensizliği 

Belki de vuslatı...

Yitik çocukluğum 

Kaybolan gençliğim

Çamur kaldırımlarda gece serserileri gibi

Kor yangına buz gibi....

....ve derken anam geliyor aklıma

Islak pardösümün altında 

Ayaz kış gecelerindeki yorganımı üzerime çekişi

..ve mırıldanmaları geliyor aklıma

Kah sinirli, kah masum ama merhamet kokan

..ve derken sabah oluyor

Gün ağarıyor

Bende sensizliğin

Sende bensizliğin üstüne

Gün yakıyor kirpik uçlarımı

Pranga yemiş dizlerim, tutsak ayaklarım

Kelepçeli elerim

Yürüyorum

Açıyorum kara peçesini

Kırıyorum yalnızlığın dizginlerini

Geliyorum

Sana 

Yada sensizliğe 

Belki de vuslata.....

Gözümde yağmurları susmuş göz bebeklerimin

Yürüyorum

Islanmışım, üşüyorum

Titrek elerimde bir sigara yakıyorum

Dumanı seni çiziyor göz pınarlarıma

..Ve bu şehre yağmur yağıyor güzelim

..Ve ben ilk defa ağlıyorum böylesine

..Ve bu şehre yağmur yağıyor güzelim 

..Ve ben aldırmıyorum

Karanlığıma gün değil

Gözlerindeki tebessümü istiyorum

Seni arıyorum

Yada sensizliği

Belki de vuslatı

Kim bilir

Vur emriyle ayrılığı....

 [email protected]', 'Gecenin rengi siyah Kalp atışları hüzün Karanlığın gözbebekleri gülümsüyor Tebessümleri hasret Tebessümleri acı ..Ve ben kırık kaldırımlarda...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/vuslat-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hala Seviyorum', 'seni-hala-seviyorum-abdullah-ortak-fhi3q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevenim yok artık biliyorum

Ne yazdığım bu satırlar anlatır beni

Ne ben beni anlarım

Ey sevgilim yoksun ya

Kopardığım çiçeklerde soldu hani

Ya kuruttuklarıma ne demeli

Hep yorgun kaldı bilmezsin

Gözlerimdeki tebessümler

Hep yarım kalıyor dudaklarımda bir şeyler

Dar ağacına çekiliyor hislerim

..Ve hep yarım kalıyor şiirlerim

Bitmiyor o sensizliğin ayazı

İçimde kor yangınlar başlarken

Üşüyorum

Dinmiyor gözlerimde yağmurlar, ıslanıyorum, seni ıslatıyorum

..Ve ben hala yaşıyorum

Sabahları bensizliğim kaldırıyor uykudan

Dokunmuyor  senden öte hazanlar

Ciğerlerime dolan sigaramın dumanı da

Anlamıyor  beni

Her şeyi unuttum

Dalga sesinde sensizliği

Mavi yorganımın altında seni seviyorum demeyi

Telefonlardaki sessizliğini.....

..ve şimdi yağmurlar yağıyor

Sensizliğin toprağına ektiğin 

Hasretin çimenlerine

Gözlerim ıslak 

Bakmalarım keskin

Yağmur gibi

Burnumda üşüyorsun

..Ve ellerim buz,

Benzim sapsarı

Adımlarım korkak gecenin karanlığında

Ama sana gelmekten

Ama seni bulmaktan

Belki senin olmaktan ey gece

Bil ki ben ölüyorum bu şehrin bir sokağında

Bir yerlerde

Bir başıma

Beni ben yazdım kaldırım taşlarına

Öylesine bir geceydi yaşadığım sana

Ben benden uzakta.

Bu gün gece doğmuştu zaten

Güneşin gözleri

..Ve ben yine aldatmıştım seni

Ben seni hiç sevmemiş, bilmemiştim belki

Sensizliğe nikah kıyarken gün batımları

Sensizliğin sessizliğini sevmiştim

Belki de 

Kasım yağmurlarının göz yaşlarını....

Sen doğduğunda ben ölmeliydim

Görmemeliydi ellerim, silmemeliydi gözlerini

Sen doğduğunda ben ölmeliydim

Ama gerçekten 

Bin ölümün birinde,

Ölürcesine

...Ve sevdiğim

...ve can

Doğum günün kutlu olsun

Mutlu ol diyeceğim 

Ama

Seni hala Seviyorum

[email protected]', 'Bir sevenim yok artık biliyorum Ne yazdığım bu satırlar anlatır beni Ne ben beni anlarım Ey sevgilim yoksun ya Kopardığım çiçeklerde soldu h...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/seni-hala-seviyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daima', 'daima-abdullah-ortak-w1h2t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehrin bir sokağındayım; 

..ve bir başına,

Ne kadar uzak olsak da,

Ne kadar ayrı kalsak da,

Sana olan aşkımı hiç anlatamasam da

Burada,

Senden çok uzaklarda

Senin için çarpan bir yürek var

Daima....

21 Kasım............                  Zeynep Sudagezer''e', 'Bu şehrin bir sokağındayım;  ..ve bir başına, Ne kadar uzak olsak da, Ne kadar ayrı kalsak da, Sana olan aşkımı hiç anlatamasam da Burada, S...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/daima-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinin Aşığıyım', 'yureginin-asigiyim-caner-kuru-8o70a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığa bir bak da gör

Gözlerinin ışığıyım.

Nefret değil hep sevgi ör,

Yüreğinin aşığıyım.

Bir orama bir burama

Aşk pompalar her yanıma.

Gözlerin de güzel ama,

Yüreğinin aşığıyım.

Sevgisinin şefkatinin

Aşk olan tek servetinin

Ne butunun, ne etinin

Yüreğinin aşığıyım.

Dil değil ki bilsin yalan

El değil ki etsin talan

Doğduğuyla aynı kalan

Yüreğinin aşığıyım.', 'Karanlığa bir bak da gör Gözlerinin ışığıyım. Nefret değil hep sevgi ör, Yüreğinin aşığıyım. Bir orama bir burama Aşk pompalar her yanıma. G...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yureginin-asigiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşam doğmadı yıldızlar', 'bu-aksam-dogmadi-yildizlar-abdullah-ortak-2neas', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu akşam doğmadı yıldızlar

Oysa hiç aksatmazlardı

Her akşam aynı saattedir doğuşu

Aynı saattedir kara çarşafla sevişmesi

Bekleme boşuna güzelim

Açılmayacak gözlerin bu gece 

Yağmurla sevişiyor şimdi gökyüzü

Şimdi sen benim gibisin artık

Böyle bir geceydi çünkü 

Onun beni aldatması

Gururuna yenilmesi

Gözlerim de gülerdi benim eskiden

Yanaklarım allanırdı

Oysa şimdi...

Mevsimler değişmiyor artık

Her gün aynı

Her akşam hazan yaprakları dökülüyor içimde

Hayallerimde savuruyorum

..Ve geleceğim yaşlı ağacı

Bu akşam gözlerini çaldım yetim bayram çocuklarının

Dokunsalar ağlayacağım

Yine yağmur yağıyor şehrin saçlarına

Ben yine o yerdeyim

Bulup bıraktığın yerde

Varsın yağsın bulutlarda ağlasın bu gece

Zaten ben bana her gün yağıyorum

Sigaralarım yüreğimde sönüyor

Tırnakları sökülüyor hayallerimin, var oluşumun

Duygularım uçurumda,

İntihar çırpınışlarında

Köpük köpük deniz dalgasının çağrısı, 

Yağmur damlasında

Dar ağacına çektiğim sensizliğin urganında karanlık gölgesi

Adım adım sokuluyor gece serserilerinin topuk sesleri

Sokak çocuklarının ürpertileri

Teneke kutuların titrek alevleri

Hatırlar mısın? böyle bir günün sabahıydı

Bu şehre yine yağmur yağıyordu

..Ve seninde ağlıyordu gözlerinde bulutlar, yeşil yeşil

Oysa şimdi...

Karları yağıyor gözlere ayrılığın

Kopuşu var dalından sararan aşkın

Ve ben yemin etmiştim 

Ağlamayacaktım

Islanmayacaktı gözlerimde sensizliğim

Silinmeyecekti son bakışın izleri

Solmayacaktı akasya çiçeklerim

Kovulmamalıydı gözlerin

Kazınmamalıydı asi yüreğimden

Ölmemeliydi bu gece

Bu şehirde birileri

Vakit ayrılık vakti, gitmeli artık, ölmeli

Ölmeli be güzelim

Mecnun Leyla’sını sarsaydı

Biz aşka inanmaz, ağlamazdık

Git, git şimdi ey ruhum özgürsün işte

Taşımayacaksın bundan böyle benim yükümü

Dokunmayacak sana çaresiz kalmışlığım

Ey gece çökeceksen çök gayrı

Dokunma bir başkasına

Alma koynuna, bir sana sığındım, sende aldatma

Ey yağmur şimdi yağacaksan yağ gayrı

Benim her gün sana yağdığım gibi

Yıkar mısın bilmem günahlarımı

Ey yar sakın ağlama, gideceksen git gayrı

Az önce bir oyun oynandı

Ve..

Bir aşka perde kapandı 

Açılmaz gayrı..

[email protected]', 'Bu akşam doğmadı yıldızlar Oysa hiç aksatmazlardı Her akşam aynı saattedir doğuşu Aynı saattedir kara çarşafla sevişmesi Bekleme boşuna güze...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/bu-aksam-dogmadi-yildizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur', 'vur-abdullah-ortak-p9u7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah yağmur var bu kentin kucağında,

Tanrı döllemedi geceyi, 

Gece doğurmadı sabahı,

Sabah yüksündü belki de güneşi,

Kim bilir.

Öyle ya 

Ben hep yağmurlu akşamları sevdim,

Pencere önünde sensizliği beklemeyi,

Bir yudum şarap ve sigara, bir nefes hüzün

El ayak çekilince karanlık sokaklarda,

İçime sokulan ürpermeni sevdim

Gel  dedim,

Aslında hep korktum gelmenden biliyor musun

Ya gene gidersen

Bir  şey kalmazdı bana bu sefer

Hep söylerdin  ya hani 

Zaman alışmayı öğretir insana

Ama unutmayı asla

karanlığa alıştım 

Ve acılara 

Ve sensiz kalmalara.

Sende alışmış olmalısın 

Öyle ya gelmiyorsun

Yoksa unutmak daha mı kolay geldi

..ve yine yalnızlık 

Yine alabildiğine

Gözlerim 

Gecenin gözlerinden kopan

Yağmur yaşlarına takılmakta

Karanlığa karışmakta düşleyişlerim

Bekar odamın üşüyen penceresinden

Sensizliğe süzülmekte benliğim

Sensizliği süzmekte gözlerim

Diyorum ki yine gelsen artık

Zaman dursun, saatler sussun

Gidişin ne kadar koyarsa koysun 

Gözlerinde telaş

Yüreğinde ateş

Saçlarından yağmurlar süzülsün

Aldırma

Her gece bu saatler beni bin kez vurursun

Oysa can 

Bilmezsin nasıl isterdim

Yağan bu göz yaşlarının sana silinmesini

Nasıl isterdim bilmezsin 

Gözlerimden dökülüp günahımı yıkamasını

Bilsen ki, bir bilebilsen ki,

Oysa; 

Her damla dağlar kadar

Gözbebeğimden seni kopardılar,

Özlemini  törpüleyip suskun yüreğime koydular

Gecelerimi vurdular, tebessümlerimi çaldılar

Ey yar unuttun mu yoksa

Çalmayacak mısın kapımı

Şimdi aylardan Kasım,

Günlerden yağmur,

...ve senin gözlerin hala yeşil mi bilmiyorum ama

Seveceksen sev, yada adam gibi vur.

 [email protected]', 'Bu sabah yağmur var bu kentin kucağında, Tanrı döllemedi geceyi,  Gece doğurmadı sabahı, Sabah yüksündü belki de güneşi, Kim bilir. Öyle ya ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/vur-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyse', 'neyse-abdullah-ortak-papl8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle olmak vardı

Seninle olmak

Geceler ne kadar yalnız

Ne kadar karanlık olsa da

Gözlerine bakıp seni haykıramasam da

Bir Temmuz akşamında

Seninle yürümek vardı

Seninle yürümek

Tuğla döşeli kırmızı kaldırımlarda

Gecenin kıskandığı

Loş ışıklı sokaklarda

Seninle olmak vardı

seninle olmak

Güneş göz kapaklarını açıncaya kadar

İlk ışıklarında saçlarını yakıncaya kadar

Seninle yaşamak vardı

Seninle yaşamak

Leyla’nın Mecnun’un, Kerem’in Aslı’nın aşkını

Seninle yaşamak vardı varlığında 

Uykusuz sabahları

Seninle tatmak vardı,

Seninle tatmak

Ücra gecelerin kuytusunda masum kaçamakları

Seninle yaşamak vardı

Özlem dolu Tarsus akşamlarını

Seninle olmak vardı

Seninle olmak

Vardı, vardı ya...

Neyse', 'Seninle olmak vardı Seninle olmak Geceler ne kadar yalnız Ne kadar karanlık olsa da Gözlerine bakıp seni haykıramasam da Bir Temmuz akşamınd...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/neyse-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Yaşı', 'goz-yasi-abdullah-ortak-p3yzw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her tebessümü gülümseme sanma

Her gözyaşını ağlama

Tebessümlerinde ağlayanlar vardır

Gözyaşlarında gülümseyenler 

Mutlaka', 'Her tebessümü gülümseme sanma Her gözyaşını ağlama Tebessümlerinde ağlayanlar vardır Gözyaşlarında gülümseyenler  Mutlaka...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/goz-yasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığındaki günah', 'ayisigindaki-gunah-abdullah-ortak-hwz0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayışığı pencerenden süzüldüğünde

… ve gözlerine dokunduğunda ben yanında olacağım, 

önce telaşlı bakışların olacak 

Sonra ben doğacağım hüzmelerden

İnceden gözlerinden süzülüp yanağına ineceğim, 

Belki bir serinlik çökecek, belki bi ateş hissedeceksin

Belki özgür bir arzu, belki günaha davet,

Yankarından aşağı süzülen ürpertin olacağım,

Belki Dudaklarında öleceğim

Omuzlarına dokunacağım sonra

kollarından ellerine ve parmaklarına,

Ürpertilerin büyüyecek, 

Uyuyan büyün güzelliğinle geldiğim pencereden seni gökyüzüne kaçıracağım, 

Yıldızlarla serili gökyüzü alıp ayaklarımın altında saatlerce dans edeceğim

Ayın yüzüne serdiğim bordo kadife de Senin olacağım

Belki o an üzerindekilerden bile daha yakın

Ve şafak sökecek, ve gün doğacak, 

sonra, 

sen istemediğin bir rüyadan uyacanaksın, 

İki dudak aranda ıslaklığım kalacak

Ben yıldızlara üfleyeceğim,

Ve ertesi akşam yıldızları senin için yakacağım 

Cesaretin varsa gel

Sabah olmayabilir, yıldızlar sönmeyebilir, sen dönmeyebilirsin

Aşık olmandan korkarım

Ya sen der gibisin 

   Bense 

   Senin için bunları yapabildiğim zaman sana aşığım



[email protected])', 'Ayışığı pencerenden süzüldüğünde … ve gözlerine dokunduğunda ben yanında olacağım,  önce telaşlı bakışların olacak  Sonra ben doğacağım hüzm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ayisigindaki-gunah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzakta', 'senden-uzakta-abdullah-ortak-b8jlm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün gelecek sana yaktığım bütün yıldızlar sönecek,

Üfleyen ne ben olacağım, ne sen 

Yılların yorgunluğu  birikecek, tükeneceğim bir sabah

belki sabah bile gelmeyecek,  tan ağarırken bir selah verilecek,

Senden uzakta bir can sensiz toprağa gömülecek

     [email protected]', 'Gün gelecek sana yaktığım bütün yıldızlar sönecek, Üfleyen ne ben olacağım, ne sen  Yılların yorgunluğu  birikecek, tükeneceğim bir sabah be...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/senden-uzakta-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Vaktim Seslenir', 'ayrilik-vaktim-seslenir-burhanettin-akdag-okcd0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüküm sevda yükü müdür, çekilmez ağır mı ağır? 

Ayrılık vaktim paslanır, giderim ben bu diyardan 

Derde giriftar yüreğim, dindir hasretimi çağır

Ayrılık vaktim yaslanır, giderim ben bu diyardan. 

Kaç yıl hüzünle yoğrulup, topraktan sılaya uçtum

Deli gönlüm isyan edip, solgun yapraklar saçtım 

Ol âlemde yapayalnız, hasretten kendimden geçtim 

Ayrılık vaktim puslanır, giderim ben bu diyardan. 

Kaderimi sordum yelden, fayda yok geçmişten düne

Yüreğim bin türlü şaşkın, kalmaz ki hevesim güne

Korkulardan sarsılırım, muhtacım derman yok cana 

Ayrılık vaktim hislenir, giderim ben bu diyardan. 

Garip yolcuyum neyleyim, zevki duyamam sancıdan 

Tükendi gücüm yollarda, gecem ne umar hancıdan? 

Acılarım pek yamandır, bilmem ne yapsam önceden 

Ayrılık vaktim uslanır, giderim ben bu diyardan. 

Ey uslanmaz abdal Burhan, derlerse nedendir yaran? 

Yaram sevda yarasıdır, kapanmaz yoktur bir saran 

Bu hal-i pür melâlimden, var mıdır hiç sual soran? 

Ayrılık vaktim seslenir, giderim ben bu diyardan. 

(26.07.2005)', 'Yüküm sevda yükü müdür, çekilmez ağır mı ağır?  Ayrılık vaktim paslanır, giderim ben bu diyardan  Derde giriftar yüreğim, dindir hasretimi ç...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayrilik-vaktim-seslenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde beni yakmaktasın', 'gozlerinde-beni-yakmaktasin-abdullah-ortak-2nxt7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi hangi şarkıyı dinliyorsun, hangi ışığa bakıyorsun

Ne dokunuyor gözlerine,neye dokunuyor gözlerin, 

Neler geçiyor aklından 

Kızıl saçlarını tararken İstanbul akşamları,

Ben geçiyor muyum

Bilmiyorum……

“Belki ümidi”nin sancısını çekiyorum şimdi,

Ama

Gelme ihtimalini çoktan düşürdüm oysa geceden

Yine ayışığında hüzün gelen

Hangimizin gözleri takılacak önce, 

Ya da kimin gözleri ihanet eder bilinmez

Ay hangi şehirde yüzünü örter

Hangi şehirde kime sırtını döner

Hangi uykusuzluğum sana yeter

Yoksun……

Bu gece yıldızları yaksam ne fark eder

Ya da Hiç Söndürmesem kaç para,

Gelmeyeceğin o kadar aşikar,

Uzak kentin gün batımında sıkışmış,

belki dönülmez akşamın ufkundasın

Yoksun….	

..ve canım yanıyor…							

Belki Gözlerinde beni yakmaktasın,,,

  (msn: [email protected])', 'Şimdi hangi şarkıyı dinliyorsun, hangi ışığa bakıyorsun Ne dokunuyor gözlerine,neye dokunuyor gözlerin,  Neler geçiyor aklından  Kızıl saçla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozlerinde-beni-yakmaktasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
