INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suyun Düşü', 'suyun-dusu-ali-ender-cemgil-hyd1i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim olur musun balık?', 'Sevgilim olur musun balık?...', ARRAY['Türk Edebiyatı','Şiir','Ali Ender Cemgil']::text[], 8.5, '{"poet":"Ali Ender Cemgil","poet_slug":"ali-ender-cemgil","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/suyun-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aff-ı Mağfiret', 'aff-i-magfiret-fatih-taskin-dzny0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günah sokağında hızla ilerlemekteydim

Birden gözüm takıldı sokağın kenarındaki çiçeğe

Uzunca baktım…..

Hayallere daldım……

Toprağı, suyu, tohumu yaratmasaydın

Güneşi atmosfere koymasaydın 

Bu masum renk çümbüşü burada olur muydu? 

Sen hiçbir şeyi sebepsiz yaratmadın

Yarattığın her varlığa bir program çipi 

Buna uygunda görevler yerleştirdin	

Toplu iğne başı kadar incir çekirdeğinden 

İki kolun saramayacağı gövdede  ağaç

Bununda her meyvesinde yine yüzlerce ağaç

Hem kudretine hem,rahmetine muhtaç

Hastane de rastladım,rahatsız genç adama 

Reçetesinde gümüş ve kalsiyum eksikliği yazıyordu

Az ilerde başka birinde ise  demir  ve magnezyum

Neden acaba böyle  oluyor diye sebep ararken 

Bu elementlerin kaynağının toprak olduğunu

Öğrenmiştim zamanında kimya okurken

Yaratılan varlıkların en yücesi olan insanda 

Zaten topraktan yaratılmadı mı? 

O halde hala sebep aramaya ne hacet 

Hala SENi  arayanlara işte işaret! 

Yarattığın her canlının hem  görevi 

Hem de yaratılış sebebi mutlaka vardı

İneğin asli görevi et ve süt vermek

Bal arıdan gelir petek  petek

Tüm canlılar yaratılış gayelerini 

Doğduktan sonra yerine getirirken 

Bu yaratılanların en üstünü olan insan

Hala görevinin farkında bile değil! 

SENin ismin günde beş vakitle anılırken 

Kurtlar, kuşlar, ağaçlar,çiçekler 

Sana şükürlerini çıkardıkları seslerle zikrederken 

Senin yarattığın en yüce varlık ise

Hala neden bunun farkında değil….

Hala neden…

Daha  neyi bekliyor...

..........................bekliyoruz! 

                      

Siyahbereli

Temmuz-05', 'Günah sokağında hızla ilerlemekteydim Birden gözüm takıldı sokağın kenarındaki çiçeğe Uzunca baktım….. Hayallere daldım…… Toprağı, suyu, toh...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/aff-i-magfiret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
