INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledinmi yollarda', 'bekledinmi-yollarda-yilmaz-ozturk-o2qeh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçindeki hasrete yenilip bekledinmi onu

Özlemlerin ıstırap aydınlık görünürmü sonu

Geceleri ona dualar edip istedinmi mutluluğu

Evetse sanada yakın hicranın soğukluğu

Zannetme mutlu olacaksın bir ömür boyu

Çok gördüm sahte gözyaşı mutlu tiyatroyu

Seviyorsan bilki saklıyorsun kendinde asil ruhu

Ruhu asil olan hicranda bulur gamlı huzuru

Dostum sen gamda zevklere layıksın 

Bizlerin sevgisi avamdan uzak olsun

Sanmaki anlar göz yaşı akıtmayan

Sen bekledinmi hiç solarak misali hazan', 'İçindeki hasrete yenilip bekledinmi onu Özlemlerin ıstırap aydınlık görünürmü sonu Geceleri ona dualar edip istedinmi mutluluğu Evetse sanad...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekledinmi-yollarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B u l m a k s e n i...', 'b-u-l-m-a-k-s-e-n-i-zafer-zengin-etnika-i4zty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

Bulmak ellerini

Dudaklarını

Karanlıkta

Ulu orta

Takılıp bir kelimenin peşine seni bulmak

Hangi liman hangi adres umursamadan dolaşmak

Sokak kedilerine sigara ikram edip sohbetler yapmak

Hep sana hüznünü anlatan kelimeler yaratmak

Yaratmak dedin de hep aklımda

Bir heykel yapacağım sana ikisi bütün olmuş

Demir taşa nakışlanmış

Şarkılar biriktirip meydanlarda okuyacağım

Gürgenim yok mesela, keskim ve elime vuracağım çekicimi

Ulu orta arıyorum işte karanlıklarda dudaklarımla sarılacağım her yanına

Sonra kızacaklar biliyorum acı kesiyorken binlercesini ben seni içeceğim

Başka türkü kapanmaz yara kanım karışmaz hayata

Takılıp bir kelimenin peşine

Zoka yutmuş ayyaş balıklar gibi

Sevdalanmak yakamoza

Ah saçların kim inkar eder sonbahar rengi taranmasını

Ilık ılık gülüşün perişan eder cihanı, bak cihan dedim de dünya geldi aklıma

İçimde depremler olurken orta da denizde yokken can veriyorum ulu orta yerlerde

Kibarlaşıyorum ölüm ağır geldikçe nazikleşiyor insan ve sanki tüm sırları 

anlayacakmış gibi dikkat kesiyor tanrıya ve emirlerine. Sahi sormadım sana en çok kime inanırsın

Tanrıya mı insana mı, bilirim kitaplar dersin oku öğren..Unuttum ben gördüğüm aşk hikayelerinde

Sevenler kavuştuğunu..Hep yanlışlara denk gelmişim ve sevenler ayrılmış bu yüzden, yazgı yasak bana

Kitaplar var yeterince nasılsa.. Nasıl dedin de, nasıl oluyor kavuşmak ve ayrılmak

Anlatsana dizlerim uyuşmadı daha,  yavaş anlat sabaha çok var nasılsa.

Bulmak ellerini

Soldan sağa

Beş harfli kelimeyle

Dokunmak yarana

Sarmak sonra

Alıp elini

Altına saklanmak

Ne varsa

Saçıp ortalığa

Tatile kaçmak

Karanlıkta

Ulu orta meydanlarda

Bir kediler koklasın bizi

Bir onlar tanısın

Sakan sırtıma

Rüzgar bana baksın

Elimle kaparım dudağımı

Gece sana kalsın

Sonra takılıp bir kelimenin ardına  mesela “sen “olsun şiirler yazmak

Satırların arasında kaybolmak..bencileyin de egoistçe şey.. söylemesem de sana

Bu cihanda bak hatırladım bu kadar acı varken insanları deniz ateş yutarken

Seni söylemek ihanet bana..bir de can olmasan katlanmayacağım buna

Takıp hırkamı sırtıma düşeceğim yollara

Takılıp bir kelimenin ardına adı kara bu şehirle yaşlanmak var da

Çekilmez soğuk içinde seni saklamasa..

Şimdilik elveda..seni bekleyeceğim daha

Kavuşmak da bir kelime işte söyledim sana

Bulmak yüzünü karanlıkta

Yüzünü dudaklarıma sakla

Kör ebesi yok

Yalnız kalmasın korkularda

Bulmak seni ellerimle

Şehrin ortasında

Ulu orta

Ağrı bu

Sadece yanımda

29 12 2004

.', '. Bulmak ellerini Dudaklarını Karanlıkta Ulu orta Takılıp bir kelimenin peşine seni bulmak Hangi liman hangi adres umursamadan dolaşmak Soka...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/b-u-l-m-a-k-s-e-n-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azınlık olacaklar', 'azinlik-olacaklar-mikdat-bal-yunb4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün doğdu, ey Türk uyan

Kabus olmadan rüyan

Yok mudur beni duyan? 

Nerede bu insanlar? 

Düşmanlar bir oldular

İçimize doldular

Nice insan aldılar

Nerede müslümanlar? 

Müsamaha dediler

Kiliseler ettiler

Hiç hesap etmediler

Kim bunu dolduranlar? 

Bir çok kişi satıldı

Başka dine katıldı

Hâl böyleyken yatıldı

Artık beni kim anlar

Boşa değil feryatım

Senin benim evladım

Kayıyor adım adım

Yok mudur durduranlar? 

Nereye gidiyorlar? 

Bizi tüketiyorlar! 

Nasıl sabrediyorlar? 

Ülkemde oturanlar! 

Azınlık olacaklar

Hak hukuk alacaklar

Ülkeme dolacaklar

Sağda solda duranlar

Düşmanımız içerde

Mikdat bir gün göçer de.

Bela olur ilerde

Yeni bir din kuranlar', 'Gün doğdu, ey Türk uyan Kabus olmadan rüyan Yok mudur beni duyan?  Nerede bu insanlar?  Düşmanlar bir oldular İçimize doldular Nice insan al...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/azinlik-olacaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen eksiktin', 'sen-eksiktin-sair-gaddar-16-rbbno', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acılarla savaştığım yetmezmiş gibi,

Karşıma sen çıktın bi sen eksiktin.

Hüzünler geride kaldı derken,

Karşıma sen çıktın bi sen eksiktin.

...

Hayata yeni çizgi çektim derken,

Ruhuma sen girdin bi sen eksiktin.

Karanlık günler geride kaldı derken,

karşıma sen çıktın bi sen eksiktin.

...

Tüm dertlerim bitti özgürüm derken,

Aklıma sen girdin bi sen eksiktin.

Sevdayı aşkı ezipte geçerken,

Dünyama sen girdin bi sen eksiktin.

...

Doktorlar bulamadı derdime çare,

Keçka delal ev ji cane,

Acılarım damlaydı şimdi oldu dere,

Yaşamam bi daha,

Aşka sevdaya tövbe derken,

Kanıma sen girdin bi sen eksiktin.

...

Yaşadım ben aşkı bir kere,

Aşkı bana sorun,sorun çekene,

bu dünya yalan aşk yalan hayat yalan derken,

Kanıma ruhuma canıma sen girdin,

bi sen eksiktin.

...', 'Acılarla savaştığım yetmezmiş gibi, Karşıma sen çıktın bi sen eksiktin. Hüzünler geride kaldı derken, Karşıma sen çıktın bi sen eksiktin. .....', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-eksiktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dakikalara Mersiyenimdir Senden Sebep', 'dakikalara-mersiyenimdir-senden-sebep-volkan-yoruc-4z98n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittin

Gittiğin dakika başladı şimdi

Oysa 1 dakika önce daha iyiydim

Çünkü sende vardın

Ama gittin

Mecburiyetten gittin

Gitmeni istermiydim hiç

Elimde değildi

Gittin

Oysa 2 dakika önce daha iyiydim

Şimdi kimbilir ne yaparsın oralarda

Belki ayaktasın

Belki oturmaktasın

Ama gittin

Mecburiyettendi bu gidişin

Şimdi yine yanımda o var

Yine utanmadan geldi oturdu yanıma

Yalnızlık

Suskunluğun sesi

Sessizliğin nefesi

Sen olsaydın oturabilirmiydi şuraya

Ama gittin

Oysa 4 dakika önce nede mutluydum

Hala mutluyum

Ama senleyken ki kadar değil

Az biraz törpülenmiş

Birazda yontulmuş

Hatta ucundan da kırılmış

Sen olsaydın böyle olurmuydu

Oysa 6 dakika önce nede doluydum

Şimdi boşlar bana kaldı

Doldurmak nasip olurmu bilemem

Giderken nede üzülmüştüm bilirmisin

Sanki bi daha gelemiyecekmişin gibiydi

Oysa bi daha geldin

Gittin

Bir daha geldin

Yine gittin

Oysa 9 dakika önce nede sevinçliydim

Çünkü sen vardın

Varlığına sevinen oldumu

Ben oldum

Gittin işte

Belki diye düşünmeye yine başladım

Belkiler sardı yine gözlerimi

Bu gidişin gelişi olursa şayet

Aydınlanırım

Bu gidişin gelişi olursa şayet

Canlanırım

Oysa 12 dakika önce canlıydım

Çünkü sen vardın', 'Gittin Gittiğin dakika başladı şimdi Oysa 1 dakika önce daha iyiydim Çünkü sende vardın Ama gittin Mecburiyetten gittin Gitmeni istermiydim ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/dakikalara-mersiyenimdir-senden-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- Sensiz Saliseler, Yıllara EŞ..!', 'sensiz-saliseler-yillara-es-metin-eser-em99c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '……sıcak temmuz, serin sabah…

gül kokulu bir geceydi yaşanmışlıklara bırakılan,

bir tutam tebessüm,

birkaç damla gözyaşı, 

……dudağıma değdiğinde biri,

……fark ettim ki; çok tatlıydı…

sanki 

……bir öpücük kadar hayatlıydı….

Henüz 

“Ya Kuddüs” kuşları uyanmadan,

Ve sabahın ilk ışıkları pencereye dayanmadan,

Bir parça özlem giderdik,

……biraz da sohbet….

dudaklarımız değmedi hiç birbirine,

ne saçlarına dokunabildim,

ne de koynuna sokulabildim…. 

ellerimiz tutuşamadılar; oysa avuçlarımızdaydı ateş,

Yelkovandaydı gözüm, o akrebi ben onu takipte,

Zaman sudan ibaret, dakikalar saniyelere eş…

Ve bitti, saatin tik taklarıyle kovaladığı sayılı süre,

Elma şekerinin alınmasına ağlayan çocuk gibi,

Ağladım, saniyeler saate eş…

Bir telefon ne kadar sarıp sarmalıyorsa,

Kapandığı anda da bam teli kopan saz gibiydi içim; tınladı, 

Sen de mi aynı durumdaydın,

Çünkü; kulağım çınladı….

Seviyorsam….., seviyorsan…..,

……..………..umursamıyorsan,

Mutluluk bir saniye kadar yakın,

Yüreğim senden yana, ateş içinde ateş,

Bir tutsan elimi, görsen yüreğimi,

Ve bir bilsen 

…………yaşanmamış anlarda,

……………………saliseler yıllara eş….

23.07.05 / Frankfurt', '……sıcak temmuz, serin sabah… gül kokulu bir geceydi yaşanmışlıklara bırakılan, bir tutam tebessüm, birkaç damla gözyaşı,  ……dudağıma değdiği...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sensiz-saliseler-yillara-es-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Ben', 'neden-ben-hakan-tolunay-ia8c3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Masamın başında

Yine bir şeyler karalıyorum.

Karaladıkça içimi bir hüzün kaplıyor.

Radyoda çalan  müzik  yalnızlığımı paylaşıyor.

Yaşadıklarım bir bir gözümün önünden geçiyor.

Neden ben, neden bir başkası değil,

Yanlış olan neydi,

Her gece kendime sorduğum.

Cevaplanmayı bekleyen o kadar soru  var ki,

Belki de kendimle yüzleşmekten korkuyorum.', 'Masamın başında Yine bir şeyler karalıyorum. Karaladıkça içimi bir hüzün kaplıyor. Radyoda çalan  müzik  yalnızlığımı paylaşıyor. Yaşadıklar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Tolunay']::text[], 8.5, '{"poet":"Hakan Tolunay","poet_slug":"hakan-tolunay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/neden-ben-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kucağımda Uyuyan Bebek', 'kucagimda-uyuyan-bebek-kamber-bal-jtnd8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne dünya  umurunda, ne de olayları

Yere doğru sarkıtmış incecik kolları

Ne meçhuldür bilmez hayatın yolları

 Geçmişini yaşıyor kucağımda bebek

 Uyurken ağzından hiç düşmez memesi

 Telaşlı saat gibi çıkar göğsünde nefesi

 Bir baksanız birden büyümektir hevesi

 Nereye koşuyor kucağımda ki bebek? 

Oyuncaklarla oynar bir garip teknikle

Tekniğini her an durmadan geliştirmekte

Acaba bu çocuk bizlere neler demekte

Dilini öğretemedi kucağımda bebek

İsyanı avazında, ah bir anlatabilse

Neler söylüyordur dünya düzenine

Yürürken elleri kelepçeli bir bebekle

Ruhumun siperi oldu kucağımda bebek

Çok acı çektin yeter gülesi bebek

Kurtulmaz dünya böyle emekleyerek

Büyür kimileri sırtından Bal emerek

Yine mi aç uyudun kucağımda bebek

Kamber Bal

1991', 'Ne dünya  umurunda, ne de olayları Yere doğru sarkıtmış incecik kolları Ne meçhuldür bilmez hayatın yolları  Geçmişini yaşıyor kucağımda beb...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kucagimda-uyuyan-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikildim', 'dikildim-volkan-yoruc-bxd63', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dikildim 

Bir heykel gibi yahut bir duvar misali

Buhrana bulanmış gözlere

Dikildim ve gözledim cemallerini

Eğrilmedim önlerinde

Savrulupta düşmedim yerlere

Dikildim ki belki konuşmadanda beni anlayabilirler diye', 'Dikildim  Bir heykel gibi yahut bir duvar misali Buhrana bulanmış gözlere Dikildim ve gözledim cemallerini Eğrilmedim önlerinde Savrulupta d...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dikildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun açık olsun...', 'yolun-acik-olsun-selcuk-demir-xhg5a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreği büyütmüş gözleri melezimi.

Susamış ruhunda,

Yetiştirebildiğin kadar...

Senden olan sesimi ne olur al yanına! 

Yolun açık olsun! !', 'Yüreği büyütmüş gözleri melezimi. Susamış ruhunda, Yetiştirebildiğin kadar... Senden olan sesimi ne olur al yanına!  Yolun açık olsun! !...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Demir']::text[], 8.5, '{"poet":"Selçuk Demir","poet_slug":"selcuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yolun-acik-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme vakti değildi!', 'gitme-vakti-degildi-selcuk-demir-i6s5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sustuğunda söyleyeceklerin...

...söylediğinde huzuruna gam.

suçsuzluğun... kalbinin en temiz yerinden. 

Kolay değil dediğin.

Vakit tamam değildi! 

Peki niyeydi acelen? ! ! ? 

Hani düşlediğin... 

Hani bu  değil dediğin! 

Ve hak ederek biriktirdiğin; 

Mutluluğun... Huzurun...

Gitme vakti değildi! ! ! 

Peki neden? ! ! ?', 'sustuğunda söyleyeceklerin... ...söylediğinde huzuruna gam. suçsuzluğun... kalbinin en temiz yerinden.  Kolay değil dediğin. Vakit tamam değ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Demir']::text[], 8.5, '{"poet":"Selçuk Demir","poet_slug":"selcuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gitme-vakti-degildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-kemal-tahir-ozcan-rz6uy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni  her görüşte, dilim tutulur,

Gözlerin,sözümün bittiği yerdir.

Varlığım  süzülüp, sana  katılır,

Yüreğim nabzının, attığı  yerdir.

Aklımı  başımdan, alır  saçların,

Her teli, gönlümün gittiği yerdir.

Gözyaşın,bendeki tüm amaçların,

Yokluğa  gömülüp, battığı  yerdir.', 'Seni  her görüşte, dilim tutulur, Gözlerin,sözümün bittiği yerdir. Varlığım  süzülüp, sana  katılır, Yüreğim nabzının, attığı  yerdir. Aklım...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyân', 'i-sy-n-mehmet-bicik-e64yw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Getirdim 

Resmimizi yan yana..

Bir sana baktım,

Bir de kendime…

Anladım,

Yılların bazı şeyleri

Alıp götürdüğünü…

Ve,

İsyân edesim geldi

Bizi ayıran,

Bu hallere koyan

Kaderime…

Pişman oldum,

Dünyaya geldiğime; 

Utandım

İnsan olduğumdan…

Sonra

Ölüm,

Yok olup gitmek,

Vuslata ermek

Geldi aklıma…

Ve

Dalıp gittim

Hayaller âlemine…

30 Ocak 1998, Malatya', 'Getirdim  Resmimizi yan yana.. Bir sana baktım, Bir de kendime… Anladım, Yılların bazı şeyleri Alıp götürdüğünü… Ve, İsyân edesim geldi Bizi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isyan-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm', 'kustum-mehmet-bicik-onwzi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağları aşıran,

Dillere düşüren,

Huzur kaçıran,

Dile, küstüm…

Kocaya kalkan,

Yuvayı yıkan,

Mikrop kokan,

Ele, küstüm…

Kokusun yitirmiş,

Dikenin batırmış,

Sevgiyi bitirmiş,

Güle, küstüm…

3 Aralık 2000, Büyükdağdere', 'Dağları aşıran, Dillere düşüren, Huzur kaçıran, Dile, küstüm… Kocaya kalkan, Yuvayı yıkan, Mikrop kokan, Ele, küstüm… Kokusun yitirmiş, Dike...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kustum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Her Şeye İnat...', 'bu-gece-her-seye-i-nat-melih-coskun-nhato', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık her günümüze 

Bir acı sığdırabiliyor zaman

Ve her zamankinden fazla kanıyor şairler.

Zaman mı böylesine daralan 

Yoksa acılarımız mı

Gün be gün çoğalan.

Bu gece

Öfkem, sevincim karıştı birbirine 

Bu gece 

Sevişmek arzusu var 

Beynimdeki cehennemle.    

Bu gece romantik bir devrimin 

Aşka yenilişi var zulamda.

Biraz eksik kalışım 

Biraz fazla oluşum hayattan. 

Bu gece

Her şeye inat

Seni sensizliğinde sevmek var...', 'Artık her günümüze  Bir acı sığdırabiliyor zaman Ve her zamankinden fazla kanıyor şairler. Zaman mı böylesine daralan  Yoksa acılarımız mı G...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-gece-her-seye-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıp götüreyim seni', 'alip-gotureyim-seni-turk-oger-koc-1idlv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alıp götüreyim seni

Buralar sana göre değil

Özlemin olmadığı yerlere 

Gecenin derinliklerine doğru

Işık ol gözlerime dol

Ses ol kulaklarıma dol

İstersen sevgi olma 

Yüreğim dolu,dolu

Söyleme sende, biliyorum be canım

Bu sözleri senden de, yüreğimle dinliyorum

2005', 'Alıp götüreyim seni Buralar sana göre değil Özlemin olmadığı yerlere  Gecenin derinliklerine doğru Işık ol gözlerime dol Ses ol kulaklarıma ...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alip-gotureyim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gittin dünyam karardi', 'sen-gittin-dunyam-karardi-muhammed-murad-uzun-hvqqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir firtinaya kapildim

Sürüklüyor ötelere

Hüzün selinde takildim

Daldiriyor mechullere

Sen gittin gözüm yasardi

Seller gibi akar durur

Sen gittin dünyam karardi

Gönlüm artik sizlar durur

Kara bulutlar üstümde

Simsekler cakip duruyor

Kalmadi sabrim gücümde

Su firtina bir dinmiyor', 'Bir firtinaya kapildim Sürüklüyor ötelere Hüzün selinde takildim Daldiriyor mechullere Sen gittin gözüm yasardi Seller gibi akar durur Sen g...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gittin-dunyam-karardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yazsam', 'bir-siir-yazsam-kamber-bal-c3wpe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazsam kızar mısın sevgilim? 

    Eski aşklarımı anlatan bir şiir

    Sen saçlarımı hafifçe okşarken

    Okşan’ın senden daha güzel okşadığını,

    Dinlerken Dilara’nın dikkatle dinlediğini,

    Sen gözlerime bakarken

    Gözde’nin daha bir içten baktığını anlatan

    Bir şiir yazsam kızar mısın sevgilim? 

   

    Bir şiir yazsam eski aşklarımın içinde senin bir hiç olduğunu

    Kırlarda koşarken seni tavşan misali yakaladığımı

    Bir serçe gibi tekrar geri saldığımı anlatan,

    Ve 

    Her gün aldatan bir adamın şiirini yazsam

    Kızar mısın sevgilim? 

    Öpüşürken Gülşen’in şafak sökümü öpüşünü

    Sevişirken Sevgi’nin ateşli gecelerini hatırladığımı

    Uyurken Düşlerimde Ruya’nın dolaştığını anlatsam

    Anlatırken yanaklarım kızarsa, 

     Pinokyo gibi burnum uzasa

     Sana sıkı sıkı sarılarak uyansam

     Ağlasam

     Anlatsam rüyamı sana

     Affeder kıskanır mısın beni

     Rüyamdaki benden

     Yoksa sen de mi olursun çekip gidenlerden

   

     Kamber bal', 'Bir şiir yazsam kızar mısın sevgilim?      Eski aşklarımı anlatan bir şiir     Sen saçlarımı hafifçe okşarken     Okşan’ın senden daha güzel...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-siir-yazsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-ozgur-kokturk-mvcy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sırlara gömüldüm gecenin içinde 

Dertleri unuttum şafak özleminde 

Sevdayı sardım ruhuma can ile 

Gördüm kendimi aşkın özünde...', 'Sırlara gömüldüm gecenin içinde  Dertleri unuttum şafak özleminde  Sevdayı sardım ruhuma can ile  Gördüm kendimi aşkın özünde......', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sir-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Diktatör', 'i-ki-diktator-mehmet-halil-b94cp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne hayvan severmiş,

Ne hayvan severmiş ki Hitler,

Köpeğim taze et yesin diye…

Önüne süt çocuklarını kesmişler.

*

Ne insan düşmanı,

Ne insan düşmanıymış ki Stalin,

Yoksul insanlar da yaşasın diye,

Önünü kesmiş,

İnsan etiyle beslenen Hitler’in...', 'Ne hayvan severmiş, Ne hayvan severmiş ki Hitler, Köpeğim taze et yesin diye… Önüne süt çocuklarını kesmişler. * Ne insan düşmanı, Ne insan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iki-diktator-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Hal.', 'i-yi-hal-aysun-erat-ph36e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç üzmedim insanları bilerek.

      Bozmadım karıncaların yuvasını basarak, farkındayken.

      Hep serin tuttum yüreğimi,

      İyiye yordum bütün çiğlikleri

      Yani…

      Kusursuz değilim elbet ben de hiçbir kulun gibi

      Ama..

      Yine de..

      Bütün bunları göz önüne alarak,

      Mümkünse Tanrım! 

      Bana verdiğin ömürden,

      İyi hal indirimi istiyorum! 

       07/2005', 'Hiç üzmedim insanları bilerek.       Bozmadım karıncaların yuvasını basarak, farkındayken.       Hep serin tuttum yüreğimi,       İyiye yord...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iyi-hal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluksuz', 'soluksuz-ozgur-kokturk-hru3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykulara suskun gözlerim 

Geçiyorum artık güneşten 

Sır oluyorum sevdanın karanlık bulvarında 

Yaşıyorum 

Ölüyorum 

Her solukta 

Nefessiz kalıyorum 

Günce sayfalarına karışıyor 

Takvim yaprakları 

İnat isyanla birleşik 

Bir yalın kelime kalıyor aklımda 

Bir yalın özne 

Bir sen... 

Gece maskelerini takıyor iğrenç suratlara 

Yüzlerde kan 

Gözler iğne deliği 

Ve paramparça yanaklar 

Korkuyorum... 

En umulmadık zamanda geliyor bu zavallılık 

En olmadık yerde 

Ve en söylenmeyecek yerde söylüyorum adını 

Saat on iki otuz beşte... 

Gecenin en yıldızsız köşesinde... 

Neye çare bilmiyorum 

Bir yalın kelime kalıyor aklımda 

Bir yalın eylem 

S-e-v-i-y-o-r-u-m...', 'Uykulara suskun gözlerim  Geçiyorum artık güneşten  Sır oluyorum sevdanın karanlık bulvarında  Yaşıyorum  Ölüyorum  Her solukta  Nefessiz ka...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/soluksuz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yol', 'bir-yol-yavuz-agir-bpws1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu gönlüme yol göründü

Uzakmıdır,yakınmıdır bilmem.

Kara sevda boynum büker

Acımıdır,tatlımıdır bilmem...

Akşam olur gün ağarır

Sabah yakınmıdır bilmem

İçimden esen fırtınalar

Birgün dinermiki bilmem.

Bu gönlümün içine inci dizerim

Tespih tanesi gibi çekerim

Mecnuna döner gezerim

Kader kötümüdür,iyimidir bilmem..

Bilmem be cano bilmem....?', 'Şu gönlüme yol göründü Uzakmıdır,yakınmıdır bilmem. Kara sevda boynum büker Acımıdır,tatlımıdır bilmem... Akşam olur gün ağarır Sabah yakınm...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-yol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kez', 'son-kez-ozgur-kokturk-sekow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son çığlıklara bağlarım direnç kalıntılarımı 

Son rüzgârla eserim 

Son şarkı olurum 

Son söylenmemiş söz... 

Son olurum 

Son kez...', 'Son çığlıklara bağlarım direnç kalıntılarımı  Son rüzgârla eserim  Son şarkı olurum  Son söylenmemiş söz...  Son olurum  Son kez......', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-kez-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihi Yürüyüş', 'tarihi-yuruyus-serhat-karadumanli-x3haw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1.

Tarihin koynundan kopup düstük yollara 

Yasemen kokusunda, akik renginde

Geldiğimiz ve gideceğimiz yere ait bir ıslık dilimizde raksediyor

Buram buram kekik tadında.

Bizi ugurlayanlar

Onurlu bir gülüşün dövmesini işlediler dudaklarımıza.

Ne kıyımlar, kıtlıklar

Ne zulümler, sömürgenler, yılgınlar

Silemedi, eskitemedi o kadim gülüşümüzü.

Kimimiz göndere çekildi

Elimizde sancak oldu, bileğimizde güç

Gecemize yıldız oldu

Isıltıları yayıldı gökyüzünden derin koyaklara

Hırçın dağların kuytuluklarına

Yüzümüzün  karanlık kıvrımlarına gizledik öfkelerini

Taşlara, lahitlere, çinilere, kilimlere işledik

Sevdalarının çıngılarını

İnatla yürüdük, durmadan yürüdük

Onyıllarca, yüzyıllarca, binyıllarca yürüdük.

Tökezlendik, kapaklandık  bazen yere

Kendi dizimizden güç alıp

Nasıl düştüysek kalktık yine

-Aman- demeden

-Ah- demeden...

Bulutların demlerinden

Çağların buğularından

Sudan ve ateşten geçtik.

Ne mızraklar, kılıçlar

Ne oklar, baltalar

Gürzler, prangalar, yılan dilli hançerler

Hepsi ama hepsi

Kum misali dağıldı bedenlerimizde

Ne bombalar, kurşunlar

Ne sisler, hızarlar

İtfaiye kancaları, demir çubuklari

Binbir zehir kusan gazlar

Hepsi ama hepsi

Tatlı bir meltem gibi okşayıp

Aktı gitti libaslarımızdan

2.

Ve bengiler hırsla dövülürken

Yeni bir cenk başladı kıyasıya

Neslimiz yaşasın diye

Yüzbinlerce yıllık düşlerimiz solmasın diye

Fırladık ağzı köpüklü

Sağrısı terlı doru kısraklarımızla

Sürek avının acımasızlığında

Düştük ölüm meleğinin peşine.

Soluğumuzun kızgın yalımlarıyldı ensesini  yakan.

Tuttu yere çaldı ölümü en yiğitlerimiz...

3.

Dizginleri hiç kısmadan

Genzi yakan dumanların, yıkıntıların

Kopan kollarımızın, bacaklarımızın arasından

Yolumuzu aydınlatan

Meşaleye dönmüş bedenlerimizin

Parçalanmış cesetlerimizin önünden

Ağulu bir şıraymışcasına akan intikam nehrinden

Doldurdum mataramı

Ve

Şaha kaldırıp, doludizgin

Çatlatırcasına sürdüm

Ağzı köpüklü, sağrısı kanlı

Bastığı yerden kıvılcımlar saçan doru tayımı.

Çekip terkisinden mataramı diktim başıma

Kana kana içtim  ve..... sarıldım kabzasına...

Gözlerimin pususunda namlusunu okşuyor

Benden önce ölümsüzlük şarabını yudumlayan kardeşim...

Al yüreğimi arkamdan gelen

Al yüreğimi siper yap

Alnında kızıl şafaklar dalgalandıran

Ve gelenlere devret zamanı gelince

Nasıl devrettiysem sana...

Dalgalandırsınlar beni de 

Kumunu kanımızla kardığımız  ülkenin burçlarında...

(Yunanistan  2002)', '1. Tarihin koynundan kopup düstük yollara  Yasemen kokusunda, akik renginde Geldiğimiz ve gideceğimiz yere ait bir ıslık dilimizde raksediyo...', ARRAY['Türk Edebiyatı','Şiir','Serhat Karadumanli']::text[], 8.5, '{"poet":"Serhat Karadumanli","poet_slug":"serhat-karadumanli","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/tarihi-yuruyus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar', 'aforizmalar-kajin-jir-qd3hf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''...Kristal Düşler,

Hümanist Çağrışımlar,

Yıldız Tozları ve Aşk...''

''Sevgi Ruhani Bir Pratiktir.''

''Sevgi Emek İsteyen Ruhani Bir Güç ve Eylemdir''', '''...Kristal Düşler, Hümanist Çağrışımlar, Yıldız Tozları ve Aşk...'' ''Sevgi Ruhani Bir Pratiktir.'' ''Sevgi Emek İsteyen Ruhani Bir Güç ve Eyle...', ARRAY['Türk Edebiyatı','Şiir','Kajin Jir']::text[], 8.5, '{"poet":"Kajin Jir","poet_slug":"kajin-jir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aforizmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdiğim Kadar.........................', 'seni-sevdigim-kadar-nusret-akbayir-38yy8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey sevgili.. 

Kimseleri düşlemedim, 

''Seni düşlediğim kadar''.. 

Kimseleri beklemedim, 

''Seni beklediğim kadar''.. 

Kimseleri özlemedim, 

''Seni özlediğim kadar.''.. 

Ey sevgili.. 

Kimse için yanmadım, 

'' Seninle yandığım kadar''.. 

Kimseyi arzulamadım, 

''Seni arzuladığım kadar''.. 

Kimseye bağlanmadım,

'' Sana bağlandığım kadar''.. 

Ey sevgili..

Kimseleri sevmedim, 

''Seni sevdiğim kadar.''.. 

Kimseyi yüceltmedim, 

''Seni yücelttiğim kadar''.. 

Kimseden çekmedim, 

'' Senden çektiğim kadar''.. 

-

26/07/2005/n.a./ İzmir./', 'Ey sevgili..  Kimseleri düşlemedim,  ''Seni düşlediğim kadar''..  Kimseleri beklemedim,  ''Seni beklediğim kadar''..  Kimseleri özlemedim,  ''Sen...', ARRAY['Türk Edebiyatı','Şiir','Nusret Akbayır']::text[], 8.5, '{"poet":"Nusret Akbayır","poet_slug":"nusret-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-sevdigim-kadar-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödenen Anlık Bedeller', 'odenen-anlik-bedeller-hasan-can-v8654', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Caddenin yamacında oturmuşken,

Öğle vakti bir bankta,

Rüzgar yüzümü okşar gibiydi...

Aklımdan geçenleri tam olarak çözememiştim.

Suskun bir dudak, garip bir bakış,

Karşımdan geçen insanları süzüyordum.

Kimi benim gibi suskun, kimi bezgin,

Kimininde yüzünden düşen bin parça,

Herkes kendi halindeydi...

Bir kaç dakika sonra,

Rüzgarın ve bulutlarında haberiyle,

Bir yağmur başladı.

Hiç kendimi bozmadım, öylece kaldım.

Tüm Vücudumun ıslanmasını bekledim.

Huzur buluyordum,

Huzur yağmurun damlalarındaydı...

Hava kararmaya başlamıştı,

Erken tutmalıydım evimin yolunu,

Tekin değildi sokaklar,

Kim bilir kimin gölgesinde yürüyecektim,

Hangi korkularımı sıralayacaktım kaldırımlar boyu.

Bi an hiç kalkmayayım dedim kendi kendime,

Buracıkta sabahlasam ölmem ya,

En fazla gelen hırsız cebimden üç kuruş parayı alıp gidecekti,

Yada kolumdaki değersiz saati, boynumda ki nefret ettiren hatırayı.

Derin düşüncelerden uyandıktan sonra,

Kalktım ve evimin yolunu tutmaya başladım,

Yolu yarılamışken, havada tam olarak kararmıştı,

Korkum ölmek değildi, damlaların tadını çıkaramadan gitmek koyardı...

Epey yürüdükten sonra evimin kapısına dayanmak üzere,

Karşıma hiç ummadığım biri çıkmıştı, yağmur yerini rüzgara bıraktı o an,

Bütün sesler sustu ve rüzgarı dinlemeye koyuldu,

Karşımdaki ecel gibi birisiydi, yada ecelin ta kendisiydi,

Ecelin ne zaman geleceği bilinmez ya, buda onun gibi birşeydi,

O, Kap-kara gözlü, ihanet bakışlı sevgilimdi, yada sevgilim sandığım...

Geceyi ihanetin kokusu sardı,

Neden gelmişti acaba, bu kez öldürmek içinmi,

Giderken uçurumun kenarına kadar sürüklemişti beni,

Yoksa, yarım kalan işini mi tamamlamaktı niyeti,

Tam aklımdan bunları geçirirken, arkasını döndü ve gitmeye başladı,

O da anlamış olmalıydı ki, konuşmaya gerek duymadı,

Gidişini izlemek bile istemedim, evimin önünde diz çöktüm,

Ben sevgimin bedelini ödemiştim,

O da ihanetinin bedelini ödedi ve gitti... uğurlar olsun.', 'Caddenin yamacında oturmuşken, Öğle vakti bir bankta, Rüzgar yüzümü okşar gibiydi... Aklımdan geçenleri tam olarak çözememiştim. Suskun bir ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/odenen-anlik-bedeller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırdöndü', 'firdondu-zeynep-karabagli-etfmn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen küçük bir fırdöndüsün

 ya hepsini al  yada  hepsini koy diyorsun

 sen ne fırdöndüsün

 birer koyunuz  geldiğinde

 ya ben yokum yada   sen yoksun

  işte herşey hepsini koyla başlıyor

çünkü  sen hepsini alıyorsun.', 'Sen küçük bir fırdöndüsün  ya hepsini al  yada  hepsini koy diyorsun  sen ne fırdöndüsün  birer koyunuz  geldiğinde  ya ben yokum yada   sen...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Karabağlı']::text[], 8.5, '{"poet":"Zeynep Karabağlı","poet_slug":"zeynep-karabagli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/firdondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir KADIN Şarkı Söylüyor ERKEKÇE', 'bir-kadin-sarki-soyluyor-erkekce-asima-azra-c76zk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kadın tanıdım kırk dokuzunda

Sert şarkılarla yüzünü yıkardı

……………………….saçlarını şarapla...

Her sinekkaydı tıraşından sonra

kaygan zeminlerde sahne alırdı

ve sahte alkışların arasında

…………kimliğine meydan okurcasına/

……………...yazılmışa kafa tutarcasına

O mikrofonun önünde adam gibi yaşardı.', 'Bir kadın tanıdım kırk dokuzunda Sert şarkılarla yüzünü yıkardı ……………………….saçlarını şarapla... Her sinekkaydı tıraşından sonra kaygan zeminl...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-kadin-sarki-soyluyor-erkekce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm', 'omrum-celal-sahin-geurq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bardakta eksilen çay,

Tablada yanan sigara gibi

Eriyip heder oldu işte ömrümden bir gün.

Kim haklı, neden haklı? 

Derken iki günün tasası

Dün yaşadığım ihanet, yarın duyacağım hasret….

                                                      26/07/2005', 'Bardakta eksilen çay, Tablada yanan sigara gibi Eriyip heder oldu işte ömrümden bir gün. Kim haklı, neden haklı?  Derken iki günün tasası Dü...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/omrum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çorak Yürek', 'corak-yurek-ahmet-hakan-yilmazturk-vjsqd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sıradan gözyaşları dökemem uzaklaşırken

dolu büyüklüğünde, lakin sıcak olsun

sancıyayım, göz pınarlarımdan düşerken 

seni yolcu edip, beni harıyla kavursun

ahlara tuz, iç çekmelere buz basarak

beni sevdiğini acımdan anlayacağım

hazlara tat, haklara helallik sararak

seni boş hayatımdan uğurlayacağım

gittiğin yerde dirlik düzenlik, şenlik

ardın toz duman, hayat fırtına, tufan

mutluluğa müebbetsin, aşklara çelik*

bende yürek çorak, her demde hazan 

24-26 Temmuz 2005

* kök salması için yere dikilen dal.', 'sıradan gözyaşları dökemem uzaklaşırken dolu büyüklüğünde, lakin sıcak olsun sancıyayım, göz pınarlarımdan düşerken  seni yolcu edip, beni h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/corak-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keneler - Şahin Yılmaz''ın ''ASALAK'' şiirine nazire (uyduk bir deliye)', 'keneler-sahin-yilmaz-in-asalak-siirine-nazire-uyduk-bir-deliye-mikdat-bal-g9zcx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dini kitabı yok neyini satsın

İçer kanımızı şişer keneler

İçtiği kan irin, zehiri tatsın

Biraz kaşınırsak düşer keneler

İki yüzlü desem değil, yüzsüzdür

Yüzde yüz yuvarlak, kılsız tüysüzdür

Kötü ahlaklıdır, hem de huysuzdur

İşi gücü emmek, deşer keneler

Bir nokta çıkara virgul olurlar

Maskeyi takınıp bir kul olurlar

Vakte gore şekil, şekil alırlar

Asalaktır, değil beşer keneler

Dostu olur her kim olursa lehte

Ne dosta sadıktır, ne söz ne ahte

Gülüşü yapmacık, dostluğu sahte

Kendi  çukurunu eşer keneler

Dostunu da satan, bir sahtekardır

Sanmasın ettiği yanında kârdır

Bu dünyanın bir de, ötesi vardır

Ateşe düşünce pişer keneler

Malına mülküne, hiç vermem değer

Hakkım haram olsun var ise eğer

Cehennem çukuru, varacağı yer

Yerini buradan döşer keneler

Yanacak ebedi, nasıl yanmasın! 

Bu devir onundur içsin kanmasın

Aldığı rüşveti, nimet sanmasın! 

Milletin hakkını, leş yer keneler

Fırsat bu zalimler, kan irin içer

Sanmayın bu millet bir daha seçer

Mikdat der bu dünya, nasılsa geçer

Bir gün kurulacak mahşer, keneler', 'Dini kitabı yok neyini satsın İçer kanımızı şişer keneler İçtiği kan irin, zehiri tatsın Biraz kaşınırsak düşer keneler İki yüzlü desem deği...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/keneler-sahin-yilmaz-in-asalak-siirine-nazire-uyduk-bir-deliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye Zam Şampiyonu', 'turkiye-zam-sampiyonu-ali-dilki-cmnl5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarlasını eller alır

Köylüler gam şampiyonu

Ekin eker yeller alır

Çiftçiler sam şampiyonu

Fare görse hemen tutar

Çiğnemeden yalar yutar

Mart ayında cirit atar

Kediler dam şampiyonu

Bu ülkede hayat bitti

Çektiğimiz cana yetti

Olgunlaşamadı gitti

Alayı ham şampiyonu

Biri yapar biri yıkar

Feryatlara kulak tıkar

Pencereden seyre bakar

Olmuşlar cam şampiyonu

Tutmadılar söz verdiler

Hepside obur kediler

Bizleri çiğ çiğ yediler

Bunlar yamyam şampiyonu

Avrupadan getiriyor

Kendi yiyip bitiriyor

Zengin tonla götürüyor

Fakir gram şampiyomu

Gönlünüzü eylersiniz

Hakkımızı paylarsınız

Siz komedi oynarsınız

Bizler dram şampiyonu

Hiç bakmayın tiplerine

Güvenmeyin iplerine

Doldururlar ceplerine

Hepsi haram şampiyonu

Zaman olmuş kötü zaman

Aman dikkat dostlar aman

Villa için yanar orman

Olmuşlar çam şampiyonu

ALİ der geriçi olduk

Her şeyi yerici olduk

Dünyada birinci olduk

Türkiye zam şampiyonu.

Bizim Anadolu Gazetesi (Şiir Molası)

30.Nisan Cuma 2004 (Sayı:12730', 'Tarlasını eller alır Köylüler gam şampiyonu Ekin eker yeller alır Çiftçiler sam şampiyonu Fare görse hemen tutar Çiğnemeden yalar yutar Mart...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/turkiye-zam-sampiyonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-serdar-tekin-3f1vp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatin bir bilmece degil, bunu anla artik…

Icinde bir özlem var, bu özlemi doldurabilmek icin gözlerimi mana etme…

Ben degilim o senin istedigin ben…

Benden uzak olman senin icin daha iyi…

Bunu anlaman icin daha neler yasaman gerekiyor…

Ben hak etmedim seni, ne seni ne o mavi denizini…

Birak artik, sal kendini, hayatin akisina sal…

Tutunmaya calisma, tutunamazsin…

Sana o mavi mavi olan dünyani veremem…

Kendime veremedigim gibi, sanada veremem…

Anla artik…

Kursuni benim hayatim, zamanin kursuni oldugu gibi…

Gerceklerle hayaller arasindaki farklari gör, hayal kirikligina ugramadan, yürü yoluna…

Bazi seyler yasanmadan bilinmez bu bir gercek, ama gercekler daima, hayallerindekinin tam tersidir…

Dogru olanda budur, dön arkani ve mazine bak, gec olmadan…

Beni göremiyeceksin…

O maviye dogru ilerle, belki bulursun, belki…

Beni bana birak, ve bak kendi yoluna…

Cünkü senin istedigin ben, ben degilim, tasiyamam ben seni…

Ne seni ne hayallerini…

Yürü yoluna bana bakmadan, cesur ol…

Yolun dogru, ilerle, kanamadan, acimadan ilerle, arkani dönüp bakmadan…

Gözlerini kapat ve yürü…

Beni düsünme…

Birkerede dinlemeyi bil, yasamadan bazi seylere inanmak güc biliyorum, ama bu sefer dinle…

Benden uzak olmayi tercih et…

Duygularin, dogru senin…

Sandigin insan ben degilim…

Hicbirzaman degildim ve suanda degilim…

Seninki sadece bir düs, pesinde kosturdugun…

Bir düs gibi yansiyan o tek an, sadece düsüncelerindeki isteklerin dogrultusundaydi…

Gercek hayata yansimiyor biliyormusun…

Hayat acimasiz bir cark icinde dönüyor…

Koymus oldugun deynegi artik birazda olsa, asagiya cekmesini bilmen gerektigini benmi sana söylemeliyim…

Üzücü ama gercek bunlar biliyormusun…

Dogruyu yapiyorsun, icinin sesini dinle…

Kalbinin gözü görmez olmus, hayallerindeki insana duydugu özlemi haykiriyor sana…

Beyninse olanlara bitenlere asikar…

Ne yapacagini bilmiyor…

Dogru yolun nerede oldugunu göremiyor…

Sen bir arayisin icindesin, her sey senin düsündügün gibi mavi degil…

Mavi olsaydi yasadigimiz dünya, savaslar, katliamlar olmazdi…

Bu güzelim, kiymetini bilemedigimiz dünyada, eger nehirler hala akmaya devam ediyorsa sende ak onlarla…

Mutluluga dogru ak artik…

Bana akmaman icin elimden geleni yapiyorum, cirpiniyorum hatta…

Dokunma bana, dokundugun zaman yanarsin…

Ben dokunulmazim, ben ben degilim, beni ben yapan, ben degilim…

Ben ufacik bir insanim, hayallerini unutmus, hayati oldugu gibi kabullenmis, ufacik bir insanim…

Hayalinde kurdugun insanla ufacikta olsa benzer bir yanim yok…

Biliyormusun benim hic arkadasim olmadi…

Bunun nedenini anlaman icin fazla insana ihtiyacin yok…

Karsilastirma beni hic kimseyle…

Karsiligimi bulamazsin, benzerimi bulamazsin…

Beni sevemezsin…

Benle olamazsin, beni yasayamazsin…

Senin sevdigin, kafanda ürettigin bir hayalden baska bir sey degil…

O ben degilim seni sen yapan, benim yüzüm yok biliyormusun, benim cezmi ersöz´ün dedigi gibi, bana ragmen yüzüm yok…

Hic birzaman olmadi ve olmayacakta…

Tasiyamazsin sen, ne beni ne benle seni…

Dalamazsin sen benim denizime…

Benim denizimde hersey tersine akiyor…

Yüzemezsin, yüzemezsin…

Benim dünyam senin kurdugun dünyaya benzemiyor…

Bunu anla artik, zor olsada anla…

Bogulursun…

Benim icin deymez, sen hayallerinde kurdugun denizinde yüzmeye devam et…

O mavi mavi denizinde… 

Yanlizda olsan yüz…

Unut artik beni, sil beyninin heryerinden…

Eser kalmasin, ne benden, nede benimle yasadiklarindan, eser kalmasin…

Serdar 27 Temmuz 2005 Çarşamba 00:21:19', 'Hayatin bir bilmece degil, bunu anla artik… Icinde bir özlem var, bu özlemi doldurabilmek icin gözlerimi mana etme… Ben degilim o senin iste...', ARRAY['Türk Edebiyatı','Şiir','Serdar Tekin']::text[], 8.5, '{"poet":"Serdar Tekin","poet_slug":"serdar-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/gozlerim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Deniz', 'i-cimdeki-deniz-ethem-turan-dolvv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçim içime sığmıyor bu gece.

Seni düşünüyorum,özlüyorum yine.

Dokunmak değil meramım tenine,

Görmek istiyorum sadece son bir kere

Sitem ediyorum hayata ve kendime

”Neden ben,neden o”diye.

Olmaz bir aşkın ateşine,

Diziyorum odunları kendi elimle

Kalbim dayanamıyor heyecanımın ritmine,

 Bir çocuk ne yapacağını şaşırıyor,

Korkuyor benliğim,içim sızlıyor,

Ya terk edip giderse diye.

Çılgınlar gibi bağırasım geliyor,

Seni seviyorum,seni seviyorum diye.

Birden korkuyorum,soruyorum kendime.

“Deli mi ne” derler diye

Aşık olmakta deliliktir herhalde.

Olmaz…Olmaz bir aşk yaşıyorum.

Seviyorum onu.Hatta ölürüm istese.

Belki değmem onun gibi güzele,

Umarım zaman alıp götürür beni.

Onsuzda yaşayabileceğim bir yere.

Dayanamıyorum ne sesine ne de yüzüne

Sitem etmesi bile bir hediye,

Vursun, öldürsün eliyle diye

Çağırasım geliyor her sahte gülüşümde.

Olsaydı diyor insan işte,

Bir cinim olsaydı benim de.

Bir dilek isterdim ama sadece bir tane,

Diğer haklarımı feda ederdim sevenlere.

Dilerdim dileğimi cinimden.

“onunla”derdim,onunla mutluluk vadisinde,

Hiç durmadan ölesiye,

Biz bize yürümek isterdim,el ele.

Kuşların,kelebeklerin ve diğerlerinin

Kıskanmalarına hiç aldırmadan

Kaç insan böyle mutlu olabilir der,

Eşlik ederdim ona.

Dizimde derman tükenip; 

Elimde elini tutacak güç,

Gözümde yüzünü görecek fer,

Kalbimde kanımı pompalayacak hal

Kalmayıncaya   dek…….VE

Yine seni seviyorum diyerek ölmek isterdim', 'İçim içime sığmıyor bu gece. Seni düşünüyorum,özlüyorum yine. Dokunmak değil meramım tenine, Görmek istiyorum sadece son bir kere Sitem ediy...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/icimdeki-deniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Venüs'' ün Doğuşu', 'venus-un-dogusu-nevzat-erkol-r1s2j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cansız bir Venüs''ü çıkardı işçiler

İvrindi yolunun kıyıcığından,

Mahreme dokunur gibi dokunarak 

Çekinerek tuttular topraklı elleriyle

Usulca gün ışığına koydular.

Oturup karşısına mermer yontunun 

Yasaksız bakışlarla seyrine doydular.

Yeniden doğmanın şaşkınlığında

Bin yıllar öncesinden bakıyordu Venüs 

Gözleri öyle derin ve nemli,

Uyanıyor gibiydi, yalın ve ürkek 

Hâlâ bir leğen kucağında

Sanki tozlu ellerine su dökecek.

Bir gelin gibi aldılar, götürdüler

Akşamın çam kokulu serininde,

Geçmiş zamanları düşlüyor şimdi

Öyle mahzun ve yalnız

Bergama müzesinde.

		            2003', 'Cansız bir Venüs''ü çıkardı işçiler İvrindi yolunun kıyıcığından, Mahreme dokunur gibi dokunarak  Çekinerek tuttular topraklı elleriyle Usulc...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Erkol']::text[], 8.5, '{"poet":"Nevzat Erkol","poet_slug":"nevzat-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/venus-un-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunu bilmiyorsan', 'bunu-bilmiyorsan-mikdat-bal-thkst', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Milliyetçi demek, müslüman demek

Bunu bilmiyorsan, yuh der geçerim

Vatana bağlılık, din iman demek

Bunu bilmiyorsan, yuh der geçerim

Maçarların aslı Türktür, bizden mi? 

Bulgarların aslı Türktür sizden mi? 

Bizim uğraşımız sırf bu yüzden mi? 

Bunu bilmiyorsan, yuh der geçerim

Başka dine asla karşı değiliz

Ama biz onlara çarşı değiliz

Kimsenin borusu, marşı değiliz

Bunu bilmiyorsan, yuh der geçerim

Kendi evladına sahip çık dedik

Hem bunu aşikar, çok açık dedik

Onların dostluğu yapmacık dedik

Bunu bilmiyorsan, yuh der geçerim

Türk’üm müslüman’ım, Türk kalacağım

İman deryasına gark olacağım

Ebedi yaşayan ırk kalacağım

Bunu bilmiyorsan, yuh der geçerim', 'Milliyetçi demek, müslüman demek Bunu bilmiyorsan, yuh der geçerim Vatana bağlılık, din iman demek Bunu bilmiyorsan, yuh der geçerim Maçarla...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bunu-bilmiyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Suya Düşer', 'umutlarim-suya-duser-durmus-karakus-pczhv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün hayallerim bütün işlerim,

Gidiyor sevdiğim hepsi tersine,

Hayra yorulmuyor hiç bir düşlerim,

Umutlarım suya düşer her sene.

Ellere bakarım güllük gülüstan,

Ben hiç gülemedim kederden yastan,

Çok darbeler yedim en yakın dosttan,

Umutlarım suya düşer her sene.

Dikenleri tuttum dedim ya gülse,

Vefasız dost larım ah kıymet bilse,

Yakardım bu şehri elimden gelse,

Umutlarım suya düşer her sene.

Hep ben mi suçluyum ben mi yaramaz,

Neden birgün dostlar beni aramaz,

Gözyaşlarım bir an bile kurumaz,

Umutlarım suya düşer her sene.

Hayat vampir gibi içer kanımdan,

Ben bıktım usandım artık canımdan,

Talih çokkez geldi geçti yanımdan,

Umutlarım suya düşer her sene.

Nasıl anlatayım bilmem ki sana,

Dertler bölük bölük karışmış kana,

Ta gurbete çıktığımdan bu yana,

Umutlarım suya düşer her sene.

Bizim Anadolu Gazetesi (Şiir Molası)  

22 Haziran 2004 Sayı: 12783', 'Bütün hayallerim bütün işlerim, Gidiyor sevdiğim hepsi tersine, Hayra yorulmuyor hiç bir düşlerim, Umutlarım suya düşer her sene. Ellere bak...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/umutlarim-suya-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-kaj-n-j-r-gen16', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili koca bilge kent; anılarımın sürgün başkenti,Tarihin ve bilgeliğin kutsal coğrafyası,savaşların kavgalı denizini içinde saklayan kristal güzellik,yağmurlarında ruhumu yıkadığım duru isyanım,mahallelerinde aşka oynadığım,sokaklarında ise firari bir yalnızlığa cirit attığım sevgili yarim... 

Koynunda yıldızlarına aşık olduğum bir sevda masalısın sen..Boğaza yakın birahenelerinde deniz yosunlarını hayal ettiğim biranın ekşimtırak tadı....Kalabalık meydanlarında güneşe yürüdüğüm,deniz otübüslerinde alemlere daldığım,soylu güzellik! ...Irak topraklara uçarken güneşi selamlayan yüksek yüksek teyyarelerinle yeryüzüne ufuktan gülüşünü görüyorum senin…sirkeci garından raylara uzanan tatlı serüven....Her müzesinde sanatın ve kültürün devrim motifleri…sevmek başkadır sende gülümsemek’te öyle... 

Nasıl anlatsam seni bilemiyorum,galiba en güzel bir şair anlatabilir seni! benim gibi rakı kokusundan imrenen bir adam ne anlar istanbulun tanrı kokan güzelliğinden...Evet sevgili istanbul seni devrik ve kafiyesiz yazılarla anıyorum! Geceleri esin perilerinle seviştiğim bu fakir yalnızlığımla ancak bunu yapabiliyorum,bağışla! sevgili gökyüzüne bir kompozisyonla ellerimi uzatmak isteyişimde hep sen varsın düşümde,sana ilahi bir beste geçiyorum içimden,belki sesim yankılanırda cesaret bulurum,cennet iklimlerinde diye...Ah hiçbir şekilde adalarında körebe oynamadığımı bilsen de ağlasan bu yabancı halime....Eski bir keman konçertosu eşliğinde aziz ruhunun kanatlarıyla kız kulesine,aşka uçtuğum büyük gemi...Sen kanımı yüce bir edebiyat ve sanat zevki ile besliyorsun,teşekkürler yazıyorum uçurtmamı bıraktığım sonsuz ülkene... 

Kajîn Jîr', 'Sevgili koca bilge kent; anılarımın sürgün başkenti,Tarihin ve bilgeliğin kutsal coğrafyası,savaşların kavgalı denizini içinde saklayan kris...', ARRAY['Türk Edebiyatı','Şiir','Kajîn Jîr']::text[], 8.5, '{"poet":"Kajîn Jîr","poet_slug":"kaj-n-j-r","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-322-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-kaj-n-j-r-30e6t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat anlaşılması güç bir denge profili üzerine kurulu,siyasal ve politik söylemlerin yanı sıra çok’ta duygusal bir bilince sahiptir hayat! bu duygusal bilincin dışavurumu ise sözlü ve yazılı işaretler içerir! Mektup Duygusal mantığımızı yazılı olarak simgeleyen bir düş hazinesidir! Mektup içinde düşsel bir zenginlik içeren bir ruh,bir kimlik ve şahsiyettir aynı zaman da! Mektuplar sürgün yanımızı yaşadığımız bir kara parçası ve sualtı dünyasında ki antik kayıp kentler gibi bir yitiriliştir,Hep suyun yüzeyine çıkmayı düşleyen bir yürektir mektup! ...zamanın dinginliğini ve yitik anıların özlemlerini haykıran asi bir çığlıktır mektup! ...mektup bir güç otoritesi ve ihtiras bileşkesidir! Mektup çok sağlam bir dopingtir insanoğlu için! ... 

Mektuplarda aşk zaman ve insanlar vardır! İhanetler kara mürekkeplere,isyanlar kağıtlara aşklar ise zarfın kendisine iliştirilir! ...çok fonetik bir alfabe ve alaturka bir gelenektir mektup! ...yaşamın çağdaşlığını ve bilgeliğini taşıyan bir vicdan hürriyetidir mektup! ! ! kozmik ışıkların gölgesine sığınan bir barınaktır mektup! Gökyüzüne ağlıyan yıldızlara sitem eden bir esirin düşleridir mektup! ..bir askerin bir kaçağın güncesi bir kronolojik travmadır mektup! ... 

Ey sevgili hayatın karanlık takvimlerinde insanoğluna sırlarlarıyla eşlik eden sevgili eş ve dost,yani sevgili günlüğüm, mektubum! ...Anılarmıza biçim verirken hep saklı bir kentin postahanesine bıraktığımız isimsiz ve adressiz mektuplar! ...hayata mistik bir edayla yaklaştığımız küresel bir bilinç,istek ve arzudur mektup! ...yıldız tozlarının ruhumuzu okşadığı,tanrısal bir müzik ile edebiyatın kavgasıdır mektup! ..bir tango ve kavgalı bir şiirdir mektup! 

Alkolik hayatların beklentilerini her sabah denize bırakan bir liman şehridir mektup! Beyin terminolojilerimiz’deki keskin bir acıdır...yalnızlıktır,Sevgi orojinli bir yıldız kümesidir mektup! Mektup hayata duruş şeklimizi ifade eden bir anıt,ve Tanrının kendisine sunduğumuz bir çelenktir mektup! Romantik serseriliğimizi sokaklara taşıdığımız öfkeli bir kalabılıktır mektup...heyacanla beklediğimiz bir nutuk bir söylemdir,akdenizin güzel kuyularında hayata gülümseyen... 

Bir şiirsel aşk pratiğidir,Çiftlerin birbirleriyle güzel mekanlarda sevişirken kulaklarına söylemiş oldukları bilge fısıldaşmalardır mektup! şarap tadında bir sarhoşluktur içimizi ısıtan....ironik bir vaka bir cinayet sebebi ve paranoyak bir bilmecedir mektup! Şairlerden aldığımız ilhamla harikalar diyarında gezinirken yakamıza iliştirmiş olduğumuz bir slogan ya da cadde boyları boyunca sahipsiz mekanlara astığımız afişleridir mektup! ...harflere,kelimelere ondan sonra da cümlelere bağladığımız bir divan bir şölendir mektup! Sakıncalı sözcüklerini sakınarak yazdığımız,gizlediğimiz bir tılsımdır mektup! ... 

Mızıkacı çocukların Tanrıya ağlamasıdır....büyük metropollerde yitik aşıkların gazete sayfalarına büyük pontularla vermiş oldukları ilanlardır mektup! Varoşlarda ise insan topluluklarının birbirleriyle kurdukları ilişki ağıdır mektup,saf ve temiz! Eski zamanlarda beyaz güvercinlerin ayaklarına bağlamış olduğumuz özgür bir beklenti ve cavabını asırlar boyu beklediğimiz bir yarındır mektup! kısa ve özetle Aşkın bütün renklerine birer davetiyedir,mektup.... 

Kajîn Jîr', 'Hayat anlaşılması güç bir denge profili üzerine kurulu,siyasal ve politik söylemlerin yanı sıra çok’ta duygusal bir bilince sahiptir hayat! ...', ARRAY['Türk Edebiyatı','Şiir','Kajîn Jîr']::text[], 8.5, '{"poet":"Kajîn Jîr","poet_slug":"kaj-n-j-r","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mektup-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Oku Beni Düşününce', 'bir-siir-oku-beni-dusununce-bekir-mutlu-gokcesu-w88ma', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben o tepedeki

Işığı her gece yanan evde

Hayaller kuracağım

Hiç gerçekleşmeyecek...

Kış geçecek, bahar gülecek

Penceremden yüzüme

Yıldızlar benim için toplanacak

Yaz gecelerinde...

Ne bir çiçek koparacağım

Ne bir kuşa hasetle bakacağım

İsteyen çalacak kapımı

Hiç çekinmeden

Gönül sofram herkese açık olacak

Ben o tepedeki evde

Hayaller kuracağım

Hiç gerçekleşmeyecek...

Herkes beni orada bilecek

Sen de...', 'Ben o tepedeki Işığı her gece yanan evde Hayaller kuracağım Hiç gerçekleşmeyecek... Kış geçecek, bahar gülecek Penceremden yüzüme Yıldızlar ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-siir-oku-beni-dusununce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüğüm…', 'gordugum-zulfikar-yapar-kaleli-yyk1e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''1''

Olmadık zamanda hayaller kurup 

Yâr beni başından atmış gördüğüm.! 

Dünyanın yükünü sırtıma vurup 

Beni yalnız koyup gitmiş gördüğüm.! 

Bende kusur arar görmez kendini 

İşlediği günah geçti yüz bini 

Hatası yüz çuval, suçu yüz sini 

Dünyayı hıfzetmiş, yutmuş gördüğüm.! 

Derdimi açalı canan sultana 

Yaram tazelenir, boyanır kana 

Gönlü köprü yaptım, bakınca sona 

Dumanı başından tütmüş gördüğüm.! 

Gönül diyarına yaşlar döküldü 

Hayat duvarından taşlar döküldü 

Öyle bir zaman ki başlar döküldü 

Cahiller her yanı tutmuş gördüğüm.! 

Benimle her sözü söyleşen sistem 

Beni yar başında eğleşen sistem 

Züğürdü bey edip beyleşen sistem 

Gül diye sunduğu otmuş gördüğüm.! 

Anasından tırsan, babaya kızan

Belâyı arayan, şımaran, azan

İnsanı kurt eden, insanı bozan

Anadan emdiği sütmüş gördüğüm.! 

Ben neyi aldım da geri kalmadı 

Kime dert yandımsa çare olmadı 

Bulutları sağdım, fincan dolmadı 

Her sözüm bir kula batmış gördüğüm.! 

Her sırrımı sultan yâra yazmıştım 

Olmadı bir türlü, ''ara'' yazmıştım 

Kaleliyi tutup sırra yazmıştım 

Hayat yıllarını utmuş, gördüğüm.! 

25.7.2005', 'font face=''Comic Sans MS'' color=''black'' size=''1'' Olmadık zamanda hayaller kurup  Yâr beni başından atmış gördüğüm.!  Dünyanın yükünü sırtıma...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gordugum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bestenigâr', 'bestenig-r-nigar-adak-6d0ml', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidersen,

Geceler mezarın olur.

Seher yıldızı mezar taşına,

Boynunu büker de, 

Harf harf miadını yazar, 

Demedim mi? 

Özlemler beline dolanırken,

Sözler dilinde donar da,

Düşlerin uçurumlara kayar.

Zayıf umutların karşı koyamaz,

Hüzün kayalarında, 

Tek tek parçalanır,

Demedim mi? 

Cümbüşlü hülyalara aldanırsın.

Sahte aşkın mızrağına yakalanınca,

Sevda ırmakların kana bulanır da,

Yüreğindeki masum balık, 

Pul pul can verir,

Demedim mi? 

Onursuz nefsin pençesine takılırsın.

Aldığın her ölümcül darbeyle,

Beste-Nigâr´ındaki o yâr için,

Kirpiklerin ağıtlar yakar da,

Tel tel ağlar,

Demedim mi? 

Nigar Adak

26.07.2005



Dikkat: Şiirlerimin hepsi noter tasdiklidir..! Şair adı olmadan alıntı yapılamaz..!', 'Gidersen, Geceler mezarın olur. Seher yıldızı mezar taşına, Boynunu büker de,  Harf harf miadını yazar,  Demedim mi?  Özlemler beline dolanı...', ARRAY['Türk Edebiyatı','Şiir','Nigar Adak']::text[], 8.5, '{"poet":"Nigar Adak","poet_slug":"nigar-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bestenigar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senpitgalben türküsü', 'senpitgalben-turkusu-akin-akca-5k7hn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düldül değil, kaplan bir aygır; 

kişileri ayıran yalan sanrıdır ….

*

Ormana girdiğinde Bengal kaplan şemalini

sürünmüş adam, sağ alt kendi kol içinde

görmüştü akrebi, Pitbullaşacak griyi! 

O da gitti geldi, gır gır makinasında -

o overlok  piko dikişinde,

atarak toy yalpanın kendisi hoppala pike

- üzerini sol omuzun seçerek

başka bir ten resmi eskisinin üzerini

kapatacak bir biçimde –bir kalbi; 

eskizini bile, geri kalmış, 

çoktan unutulmuş bir dövmenin

- hayali çöreklenip yerleşti ….

(Yarın olacak! !) 

Hanüz daha temeli atılmadı çünkü.

Ama tarihlerden

’05, Salı,Temmuz yirmi altı; 

Sevdiceğini, ve hala bekliyor bilen, umudettiği ….

Üzgünüm, ama Travis’le mukayese edebiliyorlar 

Coldplay’i ya da bile Thom York’un grubunu.

Neden? çünkü benim için biraz fazla sakin.

Ama “side” şarkıları da güzeldi hani.

Halbuki ak kirpikleri, gözbebekleri kıpkırmızı 

o geri dönüşlü mutant, bumerang; albino! 

Ah, Adagio Albinoni’den, o bir ırk mıdır ki? 

: Sen bir ırk mısın? Irk kim, “gavur” der! 

ırk yoktur, geçmişse geçmiş, birleştiriciliktir! 

şu ötedeki ölümsüzün ölüsü üzerine...

Ve kaç gece gitti böyle bilmem.

Işık verdi durdu içinden yapay döşeklerin; 

cinsiyetini değiştirerek o 

kelaynak, hassas derili Bengal kaplanı - 

ki Sibirya Kaplanı, kaldı o da anca yüz elli …

sınır bir denge’de kaldı; doğurmadı, gerilemedi de,

eh, sanırım bu gidişle onun da nesli tükenecek

- kara kuru pitbull ile kendisinin …

Ve oturttu göz aşinalığı 

cinsinden olanları bir insan bedenine.

Ve kaç kişi yaşamıştı orada? 

Kaç kişi daha yaşayacak o mevkide? 

Ten üzerli o gün ışığı altındaki nakaratta? 

Sanki Orta Asya stepleri Ankara bozkırı da; 

bir de yalan yere insanı böldüler, acı versin diye! 

Zaten Orta Asya’dan döllenme çöller; 

o bozkır, stepler değil midir makiler? 

*

İki hayvan birbirleriyle bakışacaklar artık:

Alt içteki Bengalli; Pitbull ise

bakıyor bakar, sol omuzdan sarkık, hep baktı:

Baktıklarında, sorumluluk salgıladı her sefer …

Kereler, sadece çok kereler; yavaş ilerler

Ki ‘hatta keza’ istemsiz, savaş çünkü, 

çünkü doğru karanlık tarafa, gözü yaşlı enik.

-

Başlığa dair.

Bengal kaplanı isminden çıkarsanan “Senpit”, doğal olarak “Bengal” kelimesini de doğaçladı türetmesel.

“Senpit”, doğal olarak kedi’nin vahşi köpeğe dönüşümünü simgelese de; Bengal kaplanı zaten hala Bengal kaplanı olamasa,

“Senpit” de bir pitbula dönüşmüş gözükemez ve haliyle “senpit” olarak adlandırılamazdı. Buradaki mecazdan kokoreçsel :)    kasdedilen “Sen”,

yani o; yine de her koşul altında kendisi.

-

Albino: deri yapısındaki pigment sorunu sebebiyle derisi gün ışığı dahil olmak üzere her türlü etkiye karşı hassas olan şahıs. Kirpikler ve bilimum kıllar, tüyler beyaza yakın sarı olur ve b da pigmentlerle doğrudan bağlantılıdır.

 epidermiste en ustte yassi, sert ve olu hucreler bulunur.. bu bolume korun tabakasi denir.. korun tabakasinin altinda canli hucrelerden olu$an malpighi tabakasi yer alir.. burda deriye rengini veren melanin pigmenti sentezlenir.. albinolarda melanin olu$amadigi icin deri, kirpikler, saclar, killar vs. beyazdir..

(az espri katacak olursak) 

pigmentsizilik

(bkz: beyaz zenci) 

bir albino kanguru gormek icin; 

http://www.exzooberance.com/animal%20pictures/wildlife%20babies%2004/albino%20bennets%20wallaby%20471000.jpg

çok utangaç olduklarını gözlemlediğim bir insan türüdür bunlar.kesin uzaylıdır bunların atası.

eksisozluk', 'Düldül değil, kaplan bir aygır;  kişileri ayıran yalan sanrıdır …. * Ormana girdiğinde Bengal kaplan şemalini sürünmüş adam, sağ alt kendi k...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/senpitgalben-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-ufuk-coban-5vids', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin bir meltem esintisidir bana,

Eser sakin sakin en tatlı anında.

Hemen tatlı bir aptallık sarar beni,

O bakışlarda bir anlam bulduğumda.

Gözlerin bir fırtınadır bana,

Sinirlendiğin her anında.

Güzelliğin artar bir kat daha,

Her bakışından nefret bile aksa da.

Gözlerin dinmeyen yağmurdur bana,

Hüznün her hatırlanışında.

Bana hissettirdiği bir sel gibidir,

Seninle paylaştığım her güzel şeyin yanında.

Gözlerin bir hortumdur bana,

Aklım döner durur etrafında.

Bir sarhoş gibi olduğumda,

Çeker beni kendine sonsuza dek alırcasına.

Gözlerin bir kum fırtınasıdır bana,

Yardıma ihtiyacım olduğu bir anda.

Başka kimseyi göremez gözüm o çırpınışta,

Bilirim bir tek sen ve ben varım, o uçsuz çölün ortasında.

1999', 'Gözlerin bir meltem esintisidir bana, Eser sakin sakin en tatlı anında. Hemen tatlı bir aptallık sarar beni, O bakışlarda bir anlam bulduğum...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerin-170-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Plasii, Ayı Yogi Bo Bo', 'plasii-ayi-yogi-bo-bo-akin-akca-v9hhx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Temel katından yağmurlar yağdır English Summer Rain,

Ben Ankarada’yım.

Ben Ankara’dayım, sen orda değilsin:

Böylece gün ışığına çıkacak

Kim var ise. Bunu bilmesem,

Her ikisi de kavuşacak birbirine.

-

Brian Molko’ya atfen

doğaçlama dalai lama kalaylama', 'Temel katından yağmurlar yağdır English Summer Rain, Ben Ankarada’yım. Ben Ankara’dayım, sen orda değilsin: Böylece gün ışığına çıkacak Kim ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/plasii-ayi-yogi-bo-bo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-caglar-asik-3zlmw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlmek ilmek dokunur.

Nazlı nazlı korunur.

Deste deste edilir.

Buket buket sunulur.

&

Parça parça yitilir.

Pare pare edilir.

Sora sora bilinir.

Korlu korlu edilir.

&

Derman derman inlenir.

Medet medet umulur.

Hüngür hüngür ağlatır.

Sapır sapır dağıtır.

&

Ferman ferman duyulur.

Aman aman buyrulur.

Dolu dolu sanılır.

Bomboş bomboş kalınır.

&

Yudum yudum içilir.

Cayır cayır yanılır.

Sabır sabır umulur.

Nefes nefes verilir.

İstanbul – 26.07.2005

Çağlar Aşık – Gönül – (2+2+3=7)', 'İlmek ilmek dokunur. Nazlı nazlı korunur. Deste deste edilir. Buket buket sunulur. & Parça parça yitilir. Pare pare edilir. Sora sora bilini...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gonul-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefs', 'nefs-caglar-asik-afvsc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ele güne güldürtensin.

Derman derman inletensin.

Nasıl beni üzmektesin.

Zelil zefil etmektesin.

&

Neyler seni gönül tahtım.

Doymaz senle, kalbim bahtım.

Arar durur, Hakkı ruhum.

Sustur nefsi, konuş aklım.

&

Çağla, coşan bülbül gönlüm.

Ölüp gitsin, hakir nefsim.

Susmaz, yine azar nefsim.

Ölmez, ölsün desem nefsim.

&

Ne zor, dostlar, nefsle savaş.

Gazi yoktur, şehit yoktur.

Gülle yoktur, topta yoktur.

Mezar yoktur, gömen yoktur.

&

Aman çoktur, bıkan çoktur.

Zaman azdır, yükler çoktur.

Azan çoktur, uyan çoktur.

Düşen çoktur, ahlar çoktur. 

&

Güven azdır, vuran azdır.

Kalkan azdır, kovan azdır. 

Zafer alan, galip azdır.

Nefse uyan, garip candır. 

&

Günah artar, sevap azdır.

Sözler verir, tutmak azdır.

Sende gömsen nefsi azdır.

Sabrın varsa, mezar kazdır.

İstanbul – 26.07.2005

Çağlar Aşık – Nefs – (2+2+4=8)', 'Ele güne güldürtensin. Derman derman inletensin. Nasıl beni üzmektesin. Zelil zefil etmektesin. & Neyler seni gönül tahtım. Doymaz senle, ka...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/nefs-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ada gibi...', 'ada-gibi-neslihan-i-sler-6g1m2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kızımız olsun isterdim

Gözlerine baktığımda

Adı ada olsun...

Bizim sevda adamız..

Etrafı duru,suları derin

Gözlerinde parlayan yıldızlar gibi olsun saçları

Gece siyahı....

Yakamozlar gibi geceyi aydınlatsın yüreği

Bir kızımız olsun 

Adı ada olsun..

Yeşiline hayran sevda gemileri

Işıl ışıl olsun,sevgimizin çiçeği

Bir kızımız olsun 

Adı ada olsun

İkimize ait bir dünya 

Ve dünya ya bırakacağımız bir armağan 

Ada gibi...', 'Bir kızımız olsun isterdim Gözlerine baktığımda Adı ada olsun... Bizim sevda adamız.. Etrafı duru,suları derin Gözlerinde parlayan yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ada-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin Can', 'nerdesin-can-caglar-asik-jo256', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ten içinde misin? 

Nur içinde misin? 

Su içinde misin? 

Ruh içinde misin

&

Kalp içinde misin? 

Gönül içinde misin? 

Ben içinde misin? 

Sen bende misin? 

&

Var içimde misin? 

Gel görmez misin? 

Koş duymaz mısın? 

Sev korkmaz mısın? 

&

Duy okumaz mısın? 

Özü bulamaz mısın? 

Ona kavuşamaz mısın? 

Sonsuzda olamaz mısın? 

İstanbul – 26.07.2005

Çağlar Aşık – Nerdesin Can?', 'Ten içinde misin?  Nur içinde misin?  Su içinde misin?  Ruh içinde misin & Kalp içinde misin?  Gönül içinde misin?  Ben içinde misin?  Sen b...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerdesin-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitik Öykü', 'bitik-oyku-munire-aksaray-m133x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerim yorgun

Gözlerinden uzakta

Dudak suskun

Bitik bir öykünün

Son perdesi

Oyun daha bitmemişti

Ayrılığa kaç var  dersin? 

Çığlık çığlığa vagonlarda

Sere serpe sensizliğe

Yolcuyum.', 'Ellerim yorgun Gözlerinden uzakta Dudak suskun Bitik bir öykünün Son perdesi Oyun daha bitmemişti Ayrılığa kaç var  dersin?  Çığlık çığlığa ...', ARRAY['Türk Edebiyatı','Şiir','Münire Aksaray']::text[], 8.5, '{"poet":"Münire Aksaray","poet_slug":"munire-aksaray","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bitik-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Ağıt', 'sensizlige-agit-munire-aksaray-oacwm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokluğun yeni bir varoluş

İçimde sen,

Sen sen çoğalıyorsun

Aynalar kırık şimdi

Ümitler gibi

Düşler arkasında kalmış

Kapat bütün kapılarını

Ben kapıların ardında

Gölge gölge düşeceğim peşine.

Yorulma kaçmaktan

Usanmayan benim kovalamaktan

Elbet biter bu oyun

Biterse bitsin

İçimde sen, 

Sen sen çoğalıyorsun.', 'Yokluğun yeni bir varoluş İçimde sen, Sen sen çoğalıyorsun Aynalar kırık şimdi Ümitler gibi Düşler arkasında kalmış Kapat bütün kapılarını B...', ARRAY['Türk Edebiyatı','Şiir','Münire Aksaray']::text[], 8.5, '{"poet":"Münire Aksaray","poet_slug":"munire-aksaray","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensizlige-agit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-necati-keceli-h4nem', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalvardım, yakardım olmadı

    Gelsen de olur gelme sende

    Aşkından bir tek iz kalmadı

    Silsen de olur silme sende

    Eline vermiştim tapumu

    Yıktın sarayımı, yapımı

    Açmak için gönül kapımı

    Çalsan da olur çalma sanda

    Muhtaç ettin zalim kullara

    Mecnun gibi düştük çöllere

    Gençliğimi verdin yıllara

    Gülsen de olur gülme sende

    Zaman kalmadı aha, vaha

    Ümidim bitti yok bir daha

    Bir tek can borcum var Allah’a

    Bilsen de olur bilme sende

    Aşkından düşürdün yatağa

    Dönemez oldum sola, sağa

    Koymak için kara toprağa

    Olsan da olur olma sanda

    Necati yoruldum bitti söz

    Günden güne kurudum biraz

    Gelip de iki rekât namaz

    Kılsan da olur kılma sanda 

    Necati KEÇELİ

    ADANA 27.07.2005', 'Yalvardım, yakardım olmadı     Gelsen de olur gelme sende     Aşkından bir tek iz kalmadı     Silsen de olur silme sende     Eline vermiştim...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yoruldum-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-munire-aksaray-ixb9r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceler boyu

Ayışığında yıkanırdı yalnızlığım

Sensiz zamanlarda

Yalnızlığımdı avuçlarımda hapsolan

Yanılgılarda soysuz gecelerde paylaşılan

Zaman donuk

İçli her şarkımın

Notası buruk

Sevgisiz dudaklarımda

Eriyip giden zaman

Sensizliği vuruyor

Hiç durmadan

Dan! dan! dan..!', 'Geceler boyu Ayışığında yıkanırdı yalnızlığım Sensiz zamanlarda Yalnızlığımdı avuçlarımda hapsolan Yanılgılarda soysuz gecelerde paylaşılan ...', ARRAY['Türk Edebiyatı','Şiir','Münire Aksaray']::text[], 8.5, '{"poet":"Münire Aksaray","poet_slug":"munire-aksaray","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-263-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıyla Sarhoşum-"siz hiç ay aşığında ağladınız mı" Kitabından', 'askiyla-sarhosum-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-8kzst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalga dalga mehtap baktım yüzüne 

Bu gün ben bir hoşum değme keyfime 

Tılsımlı tebessüm daldım hüznüne 

Aşkıyla sarhoşum değme keyfime 

Nakış nakış ruhum nazar bitince 

Son buldu seherde horoz ötünce 

Çorbalar dualı kaşık atınca

İçmişim bir hoşum değme keyfime

Edep büklüm büklüm vefa yerinde 

Şeytan esir olmuş yok içlerinde 

Çaylarda demlenmiş içtim serinde 

Ruhumla doymuşum değme keyfime

Beka fenâ vüsul ilham aşk çile

“Seyr ü sulük” aşksız alınmaz dile

Edep berzahında “keşke”ler ile

Kendime gelmişi değme keyfime

Bu n/asıl güzellik bu n/asıl töre 

Sahabe neşvesi ermişler sırra 

Hakikat kaynağı koş gel o yâre 

Âşıklar bulmuşum değme keyfime

Bu dünya fânidir faniler duyun

Köpükten saltanat sırlı bir oyun

Kadem bastım sırra değişti huyum 

Ölmeden ölmüşüm değme keyfime 

Mahşer uğultusu gelmez gülmeye 

Unuttum ölümü geldim ölmeye

Yeter ki kul hakkı Ömer gelmeye 

Helallik almışım değme keyfime', 'Dalga dalga mehtap baktım yüzüne  Bu gün ben bir hoşum değme keyfime  Tılsımlı tebessüm daldım hüznüne  Aşkıyla sarhoşum değme keyfime  Nakı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askiyla-sarhosum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yastık altı umutlar', 'yastik-alti-umutlar-i-lhami-arslantas-9kxwt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen git…! pembe rüyalarına

Ben yalnızlığımla uyurum,

Katık edip kabuslarımı.

Zaten

Senden önce o vardı,

Onlarla  büyüdüm, 

Onlarla oldum an be an.

Özlem türkülerim,

 acılarım 

ve ben.

Bir de boğazıma düğümlenip de 

bir türlü söyleyemediğim

çaresi olmayan

şu derdim. 

zaten 

söyleyemez,

paylaşamazdım.

sana ölümcül acılar 

veremezdim,

umutlarımı tazelemek adına.

Sen git…! pembe rüyalarına

Ben yalnızlığımla uyurum

Katık edip kabuslarımı

Git…! 

Beni bilinmedik bir zamana bırak

Belki,

Yastık altı umutlar bulurum.

Sen yoksan ölmedik ya….!', 'Sen git…! pembe rüyalarına Ben yalnızlığımla uyurum, Katık edip kabuslarımı. Zaten Senden önce o vardı, Onlarla  büyüdüm,  Onlarla oldum an ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yastik-alti-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamayı Sorma', 'yasamayi-sorma-necati-keceli-o9wvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamayı sorma, dünyada bana

       Ak saçı gül yüzü kırıştırdım ben

       Hiç şansım olmadı kaderden yana

       Zenginle, fakiri yarıştırdım ben

       Beynimin arşivi eskidir, eski

       Ararsan bulursun her çeşit aşkı

       Yaşadım gördüm bin bir çeşit meşki

       Gök yüzünde kadeh vuruşturdum ben

       Çok zaman sel oldu gözümde yaşlar

       Sıkılmaktan düştü ağzımda dişler

       Yürüdüğüm yollar dikenler, taşlar

       Kurt ile kuzuyu araştırdım ben

       Ne doğum günüm, ne bayramım oldu

       Tanıdığım yüzler sararıp soldu

       Hayatta tutunmam, amortim oldu

       Felekle, kaderi yarıştırdım ben

       Zevk alamadım şu yalan dünyada

       Kâbusu yaşadım her gece rüyada

       Güller boyun büktü enson feryada

       Kediyle, köpeği barıştırdım ben

       Gurbet eller oldu sıla vatanım

       Şu deli gönüle hasret kokanım

       Elbetde bulunur kalbe akanım

       Ölümle, yaşamı soruşturdum ben

       Necati KEÇELİ

       İZMİR

       ADANA', 'Yaşamayı sorma, dünyada bana        Ak saçı gül yüzü kırıştırdım ben        Hiç şansım olmadı kaderden yana        Zenginle, fakiri yarıştır...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yasamayi-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana', 'bana-halil-colak-gqq3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Feryât-ı figan ediyordum ıskât ettiler beni

İshân-ı ayın etti o vefasız zalim gülizar beni

İsa re oldum İshân etti acımasız berivan beni 

Acı verdi,elem verdi,,keder verdi,bergüzar bana

Methi sana ettiler,ey gonca güzel seni

Falcılar söyledi ol berivan perişan eder seni

Medrüs olursun dediler ikaz ettiler beni

Acı verdi,keder verdi,ol bergüzar bana

Halil Çolak 27.7.2005 Ankara

İs kât –susturmak

İshân-ı ayn-ağlamak,göz kızarması

İsnan-yaşlanmak

Medrüs-deli', 'Feryât-ı figan ediyordum ıskât ettiler beni İshân-ı ayın etti o vefasız zalim gülizar beni İsa re oldum İshân etti acımasız berivan beni  Ac...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bana-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Mevsimimsin', 'bahar-mevsimimsin-huseyin-erdogan-na3xs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bulutlar sarmış  canım

gök yüzünü

hasret kaldım

hiç göremedim gül yüzünü

yayılıyor dünyaya

güzelliğinin ünü

sakın hiç düşünme

benden önceki dünü

sen bir güneşsin

dünyama doğan

pırıl pırıl  bir yıldızsın

geceme ışıldayan

bir baharsın

yüreğimde 

rengarek çiçekler açan

bir ateşsin

yüreğimi yakan

bir kraliçesin

gönlüme mutluluk saçan

sen benim hasretimsin

inan ki sen benim

hiç solmayacak

bahar mevsimimsin

                   27.07.2005', 'bulutlar sarmış  canım gök yüzünü hasret kaldım hiç göremedim gül yüzünü yayılıyor dünyaya güzelliğinin ünü sakın hiç düşünme benden önceki ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bahar-mevsimimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlüm - I', 'yagmur-gozlum-i-necati-keceli-9w1ur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vermeden, bir resim bile hediye

        Bilmiyorum,çekip gittin ne diye

        Kalp''de aşkın kaldı bana geriye

        Şimdi nerelerdesin yağmur gözlüm

        Sevgimi terk ettin yağmurla selle

        Kayıplara gittin rüzgarla yelle

        Göz yaşınmı kaldı bana mendille

        Şimdi nerelerdesin yağmur gözlüm

        Bir vedasız gittin üzgün biçimde  

        Aşk, sevgi hasretin kaldı içimde

        Selammı gönderdin, bana saçında

        Şimdi nerelerdesin yağmur gözlüm

        Kuşlar veda için ötmüyor damda

        Onlarda yas tutar sürekli gamda

        Bir kokunmu kaldı, bana odamda

        Şimdi nerelerdesin yağmur gözlüm

        Kalbimde büyüyor açtığın yara

        Göz yaşım akıyor her bir satıra

        Hayalmi bıraktın bana hatıra

        Şimdi nerelerdesin yağmur gözlüm

        Sen aşkmı bıraktın bu sevgiliye

        Bu şiirim mısram yağmur gözlüye

        Sabırmı bıraktın aşka sevgiye

        Şimdi nerelerdesin yağmur gözlüm

        Necati KEÇELİ

        ADANA', 'Vermeden, bir resim bile hediye         Bilmiyorum,çekip gittin ne diye         Kalp''de aşkın kaldı bana geriye         Şimdi nerelerdesin y...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yagmur-gozlum-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller ve Ölüm Arasında', 'hayaller-ve-olum-arasinda-ozan-ozel-j0w17', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sırtına bindiğim zaman

kah bulutların üzerinde

uçuruyor 

hayaller kurduruyor bana

aşka dair güzel hayaller...

kah dipsiz kuyulara

fırlatıyor

tepetaklak oluyor dünyam

ölmek istiyorum

ama olmuyor

yaşıyorum

aşk aralığında

hayaller ve ölüm arasında

gidip geliyorum...', 'sırtına bindiğim zaman kah bulutların üzerinde uçuruyor  hayaller kurduruyor bana aşka dair güzel hayaller... kah dipsiz kuyulara fırlatıyor...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayaller-ve-olum-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roma Hatırası', 'roma-hatirasi-asli-yildiran-6do7p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Can olmuştun canımda, yüreğime kazıdım

Sen gittin ben hergün yollarında ağladım

Unuttum sandın ama ben asla unutmadım

Yüreğimi yakıyor bir Roma hatırası

Aylar geçti aradan hep özlemin yanımda

Olmasaydı bu böyle demeseydik elveda

Daha ne kadar sürecek çektiğimiz bu ceza

Canımı acıtıyor bir Roma hatırası

Ne  hasretin bitecek ne de gönül yarası

Sürüp gidecek böyle bu ayrılık acısı

Bırakalım bir yana gururu ve inadı

Yüreğimde sızlıyor bir Roma hatırası

Eğer gelirsen yine bizim olacak dünya

Gülle bülbül kavuşmuş muhabbette baksana

Sensizlikle cezalı, ağlıyorum ben hala

Canımı acıtıyor bir Roma hatırası

Resmine bakıp hergün sensizlikle yandım ben

Bitsin bu kötü günler gel artık gel nerdeysen

Gömerdim yüreğime sevdiğini bilmesem

Yüreğimi yakıyor bir Roma hatırası

Hep benimle duruyor bir Roma hatırası

05.06.2005 / Zeytinburnu - ROMA HATIRASI', 'Can olmuştun canımda, yüreğime kazıdım Sen gittin ben hergün yollarında ağladım Unuttum sandın ama ben asla unutmadım Yüreğimi yakıyor bir R...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/roma-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne şaşkın', 'ne-saskin-gorkem-kaya-a8xdn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'be şaşkın 

bugün yine anason kokar satırların... 

kalk pencereyi aç, 

kapıyı aç, 

rakıyı aç... 

gir koynuna masanın, 

kıvrılsın ayakucuma buz gibi bakışların

değdiriver gözlerini mezeye

sava sıcak

rakı sıcak

can ver karlı avuçlarınla kadehe

be şaşkın 

birtek bu leş gibi terli İstanbul gecesinde

duble, 

duble gelir aklıma aşkın', 'be şaşkın  bugün yine anason kokar satırların...  kalk pencereyi aç,  kapıyı aç,  rakıyı aç...  gir koynuna masanın,  kıvrılsın ayakucuma bu...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-saskin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç derece?', 'kac-derece-gorkem-kaya-nbcbn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaç derecede kaynar kanın? 

bir kadeh rakıda 

kaç derece sen varsın? 

akıtsam kanını rakıya, 

kaç kadehte çarparsın...? 

İstanbul,

bu gece kaç derecede

kaynar kazanın?', 'kaç derecede kaynar kanın?  bir kadeh rakıda  kaç derece sen varsın?  akıtsam kanını rakıya,  kaç kadehte çarparsın...?  İstanbul, bu gece k...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kac-derece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-i-brahim-cetinkaya-e1nn1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelişin yalnızlığım 

ama sen değil 

Öyle ki zamansız 

Güpegündüz ve kızıl

Ben giderken gülümsemen 

Dönüşlerime sürgündü sadece gidişim yakındı 

Sayılı gülüşün kalmıştı dudaklarında

Dönüşüm uzak 

Kızılını sakladım saçlarının 

gülüşünün gölgesini 

ben yalnızdım ama uzak 

sen değildin ama yakın 

Sana dokunmak olmazdı 

Gidişim yakındı 

Dokunamamak hiç 

Dönüşüm sürgün 

Olmadı bu gidişim 

Ne kadar zamansız ne kadar arzusuz ne kadar uzak 

Üstelik gülüşünün gölgesi var aklımda gidecekken 

Nasıl dönülür onu da bilmemek 

Dönüşümde sürgün olmak yeniden 

Sen gülümse sadece yalan söyleyemeyen gözlerinle

Ben sürgünüm gülüşüne ve gözlerine

23.07.2005 

Ankara', 'Gelişin yalnızlığım  ama sen değil  Öyle ki zamansız  Güpegündüz ve kızıl Ben giderken gülümsemen  Dönüşlerime sürgündü sadece gidişim yakın...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/surgun-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmayı Öğretiyorsun', 'alismayi-ogretiyorsun-abdullah-ortak-otsvs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve alışmayı öğretiyorsun,,

Ama alışabildiğin kadar, yokluğuna

Bu suskunluğunla,

Uzak şehirlerin gün batımlarına dokunuyor artık

Geceler yabancılıyor ayı ve yıldızları

Senin olduğun gibi kokmuyor artık gecenin teni,

Ve gün açmıyor gözlerini 

Nerelerdesin,

Hangi meçhul nedenden bi’habersin söyle! 

Anlamını bilmediğim

Belki bilip de kabullenemediğim soru işaretlerimsin artık,

..ve yine bekliyorum her gecenin On ikisinde 

Ama doğmuyorsun..

İnce bir sızı oluyorsun, 

Bu kadarına hakkın var mı sanıyorsun…..', 'Ve alışmayı öğretiyorsun,, Ama alışabildiğin kadar, yokluğuna Bu suskunluğunla, Uzak şehirlerin gün batımlarına dokunuyor artık Geceler yaba...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Ortak']::text[], 8.5, '{"poet":"Abdullah Ortak","poet_slug":"abdullah-ortak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/alismayi-ogretiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlü Sözler', 'ozlu-sozler-bekir-gedikoglu-q0kdv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yarin tüm sevgisini içinde toplamak

Deniz feneri gibi ışık kaynağı olmak demektir

	Birisi yada gönlündeki için çabalamak

	Arabalar gibi homurdanarak yola koyulmak demektir

Şefkati ve merhameti her canlıya salmak

İki yürek arasındaki aşk nehrini yaşatmak gibidir

	Kırılan her yüreğe payanda olmak

	Tüm dünyada sevgi ve saygının artmasını sağlamak demektir

Bir zerrede dahi aşkı büyütmek

Her canlını sefaletini önlemek demektir

	Baki aşklara hamile kalmak

	Bir öksüzün dilinden ve elinden tutmak gibidir

Evrensel sevginin yasası olmak

Yardıma muhtaçlara gitmek demektir

	Bu dünyadaki zebanileri çoğaltmak

	Aşk dolu bir kalbe bıçak atmak gibidir

Yetişme çağındaki aşk çınarlarını devirmek

Ceylanlar ormanında maral oklamak gibidir

	Var olan karanlığı yırtmak

	Güneş gibi parlamak demektir

Kendinizi aşk cennetinde bulmak

Sevdiğinizle çiçek ormanına girmek gibidir

	Her canlıya gerekli suyu bulmak

	Sevdiğinize sevginizi sunmak gibidir

Ağıldaki koyunları teker, teker kırkmak

Sevgiliye şahane bir libas sunmak demektir

Ankara 27.07.2005', 'Bir yarin tüm sevgisini içinde toplamak Deniz feneri gibi ışık kaynağı olmak demektir 	Birisi yada gönlündeki için çabalamak 	Arabalar gibi ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozlu-sozler-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşma (1)', 'kavusma-1-bahri-yildirim-oo3xa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanki dün gibiyim,durmuş zamanım

Yanıyor yüreğim, çıkmaz dumanım

Sen de biliyorsun ki

Ben böyle ateşleri senin için yaktım.

Senin için yandım sevda ateşlerinde.

Saniyelerde bile yaşaması zorken ayrılığı

Kahrolası sensizliği.,yokluğu

Öylesine dolmuşsunki dünyama

Bebeğe sarılmış kundak misali

Benim için; 

Vatan,

Bayrak gibisin', 'Sanki dün gibiyim,durmuş zamanım Yanıyor yüreğim, çıkmaz dumanım Sen de biliyorsun ki Ben böyle ateşleri senin için yaktım. Senin için yandı...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kavusma-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-munire-aksaray-ppi2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ışıktın ansızın

Sönmüş korlar arasında

Küçük bir kıvılcım

İçine saklanmış

Ben biliyordum

Yangınlar

Kıvılcımlardan

çıkarmış

Hoşgeldin...', 'Bir ışıktın ansızın Sönmüş korlar arasında Küçük bir kıvılcım İçine saklanmış Ben biliyordum Yangınlar Kıvılcımlardan çıkarmış Hoşgeldin......', ARRAY['Türk Edebiyatı','Şiir','Münire Aksaray']::text[], 8.5, '{"poet":"Münire Aksaray","poet_slug":"munire-aksaray","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hosgeldin-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşma (2)', 'kavusma-2-bahri-yildirim-no5hr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyiki döndün,iyiki geldin

Halâ bir başka güzel gözlerin

Saçlarını dalga dalga yapınca

Bambaşka güzelleşiyor yüzün

Yıllara meydan okumuş belli

Sevda dolu yüreğin

Gülüşün muhteşem

Dönüşün muhteşem

Öptükçe ballanan dudak gibisin', 'İyiki döndün,iyiki geldin Halâ bir başka güzel gözlerin Saçlarını dalga dalga yapınca Bambaşka güzelleşiyor yüzün Yıllara meydan okumuş bell...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kavusma-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşma (3)', 'kavusma-3-bahri-yildirim-n3e1t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yok yok! İnkâr etme boşuna

Sende bir gariplik var bu sabah

Böyle yaşanmazki umut

Böyle yudumlanmazki sevda

Sanki benim sevdiğim değil karşımdaki

Yıllarımı paylaştığım can değil

Anlamını kaybetmiş sanki öpüşlerin

Gözlerinde dolu dolu korkular

Sararmış,solmuş yaprak gibisin

Umudu tükenmiş,omuzlar çökmüş

Gülücükler yitirmiş anlamını

Sanki  sen değilsin yıllardır çekip giden

Sanki sen değilsin  bu ayrılığa neden

Geri dönüşüne bir can bağışlayacaktım

Oysa....

Çok şeyleri alıp götürmüş yıllar

Ne sen eskisi gibi

Ne de ben eski ben

Sen yaban

Ben yabancı

Üstüme atılan toprak gibisin', 'Yok yok! İnkâr etme boşuna Sende bir gariplik var bu sabah Böyle yaşanmazki umut Böyle yudumlanmazki sevda Sanki benim sevdiğim değil karşım...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kavusma-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlumuyum', 'suclumuyum-ahmet-mansuroglu-3k05x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suçlumuyum bilmem seni sevdimse

Tüm benliğimi sana verdimse

Sen gel demeden geldimse

Sevmenin suç olduğunu sen öğrettin bana

Havvada Ademe sevgi ile eğildi

Dünya kurulalı sevmek günah değildi

Ben seni mecnunun Leylası gibi sevdim

Sevdimse günahmı suçmu işledim

Yalanda olsa tatlı sözlerine vuruldum

Peşin sıra koşmaktan inan yoruldum

Çağlayan su iken şimdi duruldum

Yüreğimde acı var, gözlerim seni aramaz oldu

Bir gün ahirette divan kurulur

Melekler suçlarını sayar yorulur

Ettiklerinin hesabı bir bir sorulur

Duygularımın katilisin sen

Perişan edecek seni ahım

Seni sevmek benim günahım

Sanada acı çektirsin Allahım

Yanılca seni sevmekti benim günahım.

   Antakya - Hatay

  Tlf: 0 326 2156779', 'Suçlumuyum bilmem seni sevdimse Tüm benliğimi sana verdimse Sen gel demeden geldimse Sevmenin suç olduğunu sen öğrettin bana Havvada Ademe s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/suclumuyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Mırra**', 'mirra-seyhmus-sevilmez-qirbs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yedi ayrı sevgi kabında damıtılmış.

Gümgümlerde fokurdayan, mırra gibidir aşkım! 

Diğer aşklara benzemez... 

Ateşinle bedenim kaynadıkça, 

Yüreğimin dibinde ruhumun özü kalır.. 

Tutunacak dalı olmayan 

Kulpsuz fincanlarda, 

İkram edilir sevgim… 

İçen bilir mırranın tadını.

Hayatın tecrübe cezvesinden taşmış sevgim. 

İhanetlere köpürüşüm bu yüzdendir! 

Ve bu yüzdendir acılığım... 

Benim doğduğum topraklarda, mırra; 

Düğünlerde ve taziyelerde içilir… 

Aşk gibi tadı acı, hatırı büyük 

Mırra gibidir özde aşkım… 

Beni içmeye hazır mısın?', 'Yedi ayrı sevgi kabında damıtılmış. Gümgümlerde fokurdayan, mırra gibidir aşkım!  Diğer aşklara benzemez...  Ateşinle bedenim kaynadıkça,  Y...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mirra-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımına Yolculuklar 2', 'gun-batimina-yolculuklar-2-galip-ozdemir-arfhp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“yasemen endamlı yakamoz çiçeğine''

ne bir yol

ne bir pusat…

ne bir yıldız vardır

ne de bir iz…

gönül kuşunun rehberliğinde 

ve marmara’ya atılan bir taşla başlar

günbatımına yolculuklar…

durduk yere

bir hüzün çağrısı…

ve sökün eylemektir

bir yakamoz çiçeğine 

günbatımına yolculuklar…

henüz keşfedilmemiş

ve adı konmamış renklerle yıkanan

bir düş

ve heyacanlı bir iççekiş gibidir

günbatımına yolculuklar…

ve günbatımına yolculuklarda

uzaklarda

ayyenisi kıyılarında

bir tutku ağlar

bir umut yanar…

ve günbatımı yolculuklarında

susar zaman

vurulur yelkovan

sonra bir akdeniz çığırtısı

ve sonra

paslı dillerimde

bir bozkır baladı…', '“yasemen endamlı yakamoz çiçeğine'' ne bir yol ne bir pusat… ne bir yıldız vardır ne de bir iz… gönül kuşunun rehberliğinde  ve marmara’ya at...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gun-batimina-yolculuklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda İsyan', 'umuda-i-syan-ercan-karakulah-bnaom', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onsekiz yaşında gencecik bir delikanlı

Umutlarıyla aynı torbaya koyuyor topladığı kağıtları,

Yüreği taşımıyor bazen içinde kopan fırtınaları,

Bazen yerlerde parçalanıyor utangaç bakışları,

Önce ürkekçe açıyor çöplerin kapağını,

Sonra sitemle topluyor çöpteki hasadını,

Su gibi duru yüzünden okunuyor,

Bu işlere yeni başladığı,

Uzun uzun seyredip hızla geçen lüks arabayı,

Bir küfür savuruyor çatlamış bakir dudakları,

Artık daha bir hırsla çalışıyor nasırsız parmakları,

And içmişti, zengin olacaktı,

Bunun için gelmişti bu yolları,

Böyle olmayacağını düşünürken yalnız uyandığı sabahları,

Okumaya başladı üzerine örttüğü kağıtları,

Bir sayfasındaki sosyete barlarını,

Diğer sayfasındaki cinayet ve hırsızlıkları,

Ne kadar benziyordu birbirine bunların suratları,

Artık Oda keşfetmişti zengin olmanın yollarını! ! !', 'Onsekiz yaşında gencecik bir delikanlı Umutlarıyla aynı torbaya koyuyor topladığı kağıtları, Yüreği taşımıyor bazen içinde kopan fırtınaları...', ARRAY['Türk Edebiyatı','Şiir','Ercan Karakülah']::text[], 8.5, '{"poet":"Ercan Karakülah","poet_slug":"ercan-karakulah","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umuda-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap Denizi', 'azap-denizi-sahin-erturk-e0060', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen evlendin diye

Ben sevineyim mi? 

Ziller takıp

Oynayayım mı? 

Yoksa diyorum yoksa

Dahada ileri gidip

Konak meydanında

Konser mi vereyim? 

Gazetelere

İlanlar mı vereyim? 

Kırılmışsın,darılmışsın

Düğünüme gelmedi

Bir mesaj bile çekmedi

Demişsin,demişsin de

Benim yüreğim

İZMİR de kalmış

Kanım,canım çekilmiş

Yaşayan ölüye dönmüşüm

Donmuş kalmışım

Bitmişim,çökmüşüm

Ağlamışım,üzülmüşüm

Azap denizine düşmüşüm

Cayır,cayır yanıyormuşum

Tüm bunlar

Her nedense

Hiç aklına gelmemiş

Bana darılmışsın

Sitemler etmişsin...? 

Mutluluk denizinde yüzen

Beni AZAP DENİZİNDE

Bırakıp giden sen

Suçlanan,acı çeken ben

Komik olduğunun

Farkındamısın sen

Farkındamısın? 

(27.07.2005-Yeni)', 'Sen evlendin diye Ben sevineyim mi?  Ziller takıp Oynayayım mı?  Yoksa diyorum yoksa Dahada ileri gidip Konak meydanında Konser mi vereyim? ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/azap-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaşam Anatomisi', 'bir-yasam-anatomisi-cemil-aygen-12k1l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni aldılar

Yalnızlığımın içine attılar

Yangınlarındayım yüreğimin

Çıkışı olmayan birine mahkumum

İçimde konuşacağım

Hiç kimseyi bırakmadılar

Önümdeki öyle bir ufuk ki

Uçsuz bucaksız

Sonu olmayan görünmeyen bir uzaklık

Ve bir yanımda kimsesizliğim var

Bir yanımda anlatamadığım yalnızlık

Aldım başımı yine

Ucu bucağı olmayan yollara düştüm

Neydi özlemim

Hayinliğin sevdaya hükmettiği

Bu diyarlara mahkum mu edildim ki

İçim dayanamıyor..Yaşamıyorum..

Yüreğimde büyüttüğüm biricik çocuğumdu SEVGİM

Hep eksik bıraktım onu

Yaşatamadım..

Şimdi yalnızlığımın,Gökyüzüne egemenliği var

Bir ağlamak...Bir pişmanlık ve de isyanlarım var

Herkesle kavgalıyım ben

Bu yüzden ne anlayanım oldu 

Ne de yaradanıma sığınmalarım oldu

İsyanımı hep kendime yaptım 

Şimdi koskoca bir boşluk içimdeki

O boşlukta beni yiyen bitiren 

İnsan kılıklı vahşi çakal sürüsü var

Veda et her şeye diyorlar ''Veda Et''

Dayanamayıp Hoş ''t'' Çakal diyorum

Şimdiye dek nasılsa 

Nasıl duyguysa...Nasıl yaşadıysa

Şimdi de sonra da öyle

Boş bomboş gerisi...Biliyorum...', 'Beni aldılar Yalnızlığımın içine attılar Yangınlarındayım yüreğimin Çıkışı olmayan birine mahkumum İçimde konuşacağım Hiç kimseyi bırakmadıl...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-yasam-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-nihat-tasdemir-7ag0h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zile basip kaçan haylaz çocuk.

Penceremden geçen meçhul.

Paranoya...

Odada biryerlerde saklı.

Aşk bana yatıya gelmez ki! 

Yorgansız yorgun gece.

Elim elinde sobe.

Bir içimlik sone.

Aşk bana yatıya gelmez ki! 

                          15 Şubat 2005', 'Zile basip kaçan haylaz çocuk. Penceremden geçen meçhul. Paranoya... Odada biryerlerde saklı. Aşk bana yatıya gelmez ki!  Yorgansız yorgun g...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-402-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'IIIII/Acı', 'iiiii-aci-ali-gencay-29epm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakın! 

Bana bakın

Yaktım gözlerimdeki narı

Yüreğimde yaşamın efkarı

Tenimde çıldırtan kaşıntı

Nafile yedim, bitirdim tırnaklarımı

Alan var mı satıyorum

Paha biçemediğim anıları

Çıkarıp pahalı ayakkabılarımı

Yalın ayak yarıyorum şehri 

Yarıyorum! 

Ucuz pazarlıklar kaldırımlarını

Sürüye dalan kurt gibi

Etleri beton, şaraptan kanları

Parçalayacağım sevdiğim insanları

Acı! 

Acı üstüne acı

Tüm nağmeler kulağımda

En ağlamaklı arabesk tadı

Baba kızına sövüyor

Ana rahmini deşiyor

Küçüğüm ben, küçücük

Yok ki çocukların günahı', 'Bakın!  Bana bakın Yaktım gözlerimdeki narı Yüreğimde yaşamın efkarı Tenimde çıldırtan kaşıntı Nafile yedim, bitirdim tırnaklarımı Alan var ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iiiii-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Saltanat Sürüyor', 'ozlem-saltanat-suruyor-necmi-unsal-34wjh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurulmuş özlem kalplere, 

.....................................saltanat sürüyor.

Mevsimler aynı, 

......................gökyüzü parçalı bulutlu.

Uçulmaz hoyrat zamanla, 

......................................kol kanat çürüyor.

Yaşını basan bağırlar 

...............................visale umutlu.

Acılar tartar, 

................ümidin ağırdır darası.

Tatmadan ölür vuslatı 

................................sevdalar ve düşler.

Her bahar kanar 

........................inceden bir hasret yarası.

Düşleri süsler 

...................özlenen visalde öpüşler.

3 Mayıs 2004 Pazartesi, Danimarka-Køge 00.27

3+2+3+3+3', 'Kurulmuş özlem kalplere,  .....................................saltanat sürüyor. Mevsimler aynı,  ......................gökyüzü parçalı bulu...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlem-saltanat-suruyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Sayıklamakları', 'yalnizlik-sayiklamaklari-abdulkadir-ogdum-81ral', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı gözünle değil, kalbinle hisset,

Konuversin ruhuna kara kara baykuşlar! 

Hep yalnızlar içindir kaygı, elem, sefâlet,

Ne güler elâ gözler, ne düzlenir yokuşlar! 

