INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bağları', 'sevgi-baglari-aysel-celik-jdgb9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yurdumun üzerinde kara fırtınaların  estiği,

Sefaletin, yokluğun açlığın kol gezdiği,

İnsanların, yiyecek yerine çarık yediği,

O yıllarda Sevgi Sevgi denen bir şey vardı

Sanmayın, onca düşman, onca savaş

Topla tüfekle yapılmadı

Cephane bitti, tüfek bitti

Birleşti bütün kalplerdeki vatan sevgisi

Büyük bir bağ kopmaz bir bağ oluştu

Güç, kuvvet sevgi bir araya geldi

Yenilmez Türk Ordusu meydana geldi

Bugünkü Türkiye ortaya çıktı

Görüyoruz hala o bağ kopmadı, kopmayacak

Anılacak kalplerde yaşayacak o Atalar

Gururluyuz! Sevgi bağı var aramızda', 'Yurdumun üzerinde kara fırtınaların  estiği, Sefaletin, yokluğun açlığın kol gezdiği, İnsanların, yiyecek yerine çarık yediği, O yıllarda Se...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgi-baglari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan Gelen Ses', 'uzaktan-gelen-ses-aysel-celik-pqgim', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin o ıssız sessizliğinde

Uzaktan taa uzaktan bir ses geliyordu

Haykırıp, haykırıp kalpleri çarpan

Bir ses geliyordu taa uzaktan

Sanki billur sesli çocuk çığlığı

Büyük yaygara yapan gözü yaşlı bir anne

Sevgiden yoksun, yalnız kalmış, boynu bükük

Bir ses geliyordu taa uzaktan

Duyulduğunda tüyleri diken diken yapan

Kulaklarda bir uğultu çarptıran

Kalpleri hızlı, hızlı vurduran

Uzaktan! Taa uzaktan bir ses geliyordu

Olamaz! Olamaz bu ses durgunlaştıran

Durup, durup gözleri yağmurlaştıran

Gözleri bir daldırıp, bir gerçekleştiren

Uzaktan! Taa uzaktan bir ses geliyordu', 'Gecenin o ıssız sessizliğinde Uzaktan taa uzaktan bir ses geliyordu Haykırıp, haykırıp kalpleri çarpan Bir ses geliyordu taa uzaktan Sanki b...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzaktan-gelen-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluk', 'umutsuzluk-aysel-celik-8kfif', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutsuzluktur, sevgiye bakan gözleri körelten

Umutsuzluktur! Açan çiçekleri solduran

Evet! Ama sonrada, umutsuzlukla hayır! Dediren

Umutsuzluktur! Uzayan ömrü kısaltan

Umutsuzluktur, gözlerden akan bir damla yaşı sellendiren

Umutsuzluktur! Hedefe bakan gözleri yanıltan

Kötülüğü sindiren sevgiyi yok eden umutsuzluktur

Umutsuzluktur! Açılan kapıları kilitleyen

Umutsuzluktur, dünyanı karartan, seni yalnız bıraktıran

Umutsuzluktur! Verdiğin cevaptan döndüren

Titrek, güçsüz, sevgisiz bırakan umutsuzluktur

Umutsuzluktur! Açılan kapıları kilitleyen

Umutsuzluktur, bunları yaptıran

Umutsuzluktur hiçbir kapıyı açmayan

Sevgi dolu, kararlı azimli umutludur

Umutlu olan her şeyi başarandır.', 'Umutsuzluktur, sevgiye bakan gözleri körelten Umutsuzluktur! Açan çiçekleri solduran Evet! Ama sonrada, umutsuzlukla hayır! Dediren Umutsuzl...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umutsuzluk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyamız', 'dunyamiz-aysel-celik-zr1al', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi yerde keder, üzüntü acı

Tektir çaresi sevgidir ilacı

Çocuklar mahsun, bir lokma ekmek bulamamışlar

Bir deri bir kemik kalmış, sevgiyi duyamamışlar

Kimi yerde yeşil, yemyeşil kırlar

Çocuklar mutlu, sevinç parlar

Ağaçlar kolkola mutluluk salar

İnsanlarda birbirlerine sevinç yayar

Kimi yerde bozkır dağlar ard arda

Sevgi ile acı bir arada

Yeşillikler sönmüş, yerini siyaha bırakmış

İnsanlar ölmüş, yerini kemiklere bırakmış

Dünyamızdır bu onu koruyalım

Her yerine sevgi, mutluluk koyalım

Dünyamızdır bu onu sevelim

Her yerini yeşil, yemyeşil koyalım', 'Kimi yerde keder, üzüntü acı Tektir çaresi sevgidir ilacı Çocuklar mahsun, bir lokma ekmek bulamamışlar Bir deri bir kemik kalmış, sevgiyi d...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunyamiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler', 'mevsimler-mehmet-lutfu-aydin-shkyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya dört mevsim,

dört ayrı dünya.

İnsan her mevsim, 

bir başka dünya.

Peki, ya benim dünyam? 

dört mevsim salatası', 'Dünya dört mevsim, dört ayrı dünya. İnsan her mevsim,  bir başka dünya. Peki, ya benim dünyam?  dört mevsim salatası...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mevsimler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin', 'kimin-aysel-celik-998b6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dendi! “Bu vatan kimin”

Denmesin mi? Bu insan kimin? 

Tarihten esen bu sessizlik,

Gelecekten gelen bu korkuluk

Dendi! “Atatürk Atam”

Denmesin mi? Bu vatan yatam

Geleceğin umudu,

Bu gençler kimin? 

Dendi! “Bu şanlı tarih benim”

Denmesin mi? Bu şehitler, bu gaziler kimin? 

Uğrunda yas tutan

Bu ana kimin? 

Dendi! “Bu bayrak benim”

Denmesin mi? Ya bu gök kimin? 

Uğrunda can veren,

Bu insanlar kimin? 

Dendi! “Bu vatan benim”

Denmesin mi? Bu dünya kimin? 

Kararmış gidiyor,

Bu yeşillik kimin?', 'Dendi! “Bu vatan kimin” Denmesin mi? Bu insan kimin?  Tarihten esen bu sessizlik, Gelecekten gelen bu korkuluk Dendi! “Atatürk Atam” Denmesi...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Tamam', 'vakit-tamam-mehmet-lutfu-aydin-hzc07', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asırlık çınar kadar, yaşasan da bahtiyar

Benzer senin de sonun, sessiz, solan yaprağa

Mevsim şimdi sonbahar, geldi çattı ihtiyar 

Ecel alır canları, düşer tenler toprağa', 'Asırlık çınar kadar, yaşasan da bahtiyar Benzer senin de sonun, sessiz, solan yaprağa Mevsim şimdi sonbahar, geldi çattı ihtiyar  Ecel alır ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vakit-tamam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Dostlar', 'yalnizim-dostlar-aysel-celik-nugby', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızım dostlar yalnızım

Suskun acı dolu diyarlardan

Yüreğimi kaplayan karanlıktan

Kaçıyorum dostlar, kaçıyorum

Hani vardı, iyilik mutluluk dolu insanlar

Bizde ki suç mu? Fakirse kaderler,

Bir ben tekmiyim? Yalnızlık dolu hayaller

Yalnızım dostlar yalnızım

Yok mu hiç geçmişinde fakir olan

Gam yemeyen, haksız çıkardan

Çaresizlikler içerisinde boğulan

Yalnızım dostlar, yalnızım

Bu ne yalancı, acımasız bir dünya

Keyfi sefa sürer zenginlerde dünyada

Bak şu boynu bükük çocuğada

Yalnızım dostlar, yalnızım

Unutmayalım; yokuz bir gün rüyada

Gerçekte varız mahşer-i alemde

Etmeyelim böyle, düzelelim kendimizce,

Yalnızım dostlar, yalnızım.', 'Yalnızım dostlar yalnızım Suskun acı dolu diyarlardan Yüreğimi kaplayan karanlıktan Kaçıyorum dostlar, kaçıyorum Hani vardı, iyilik mutluluk...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizim-dostlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak', 'tik-tak-mehmet-lutfu-aydin-j03fm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimi dinliyorum:

Tik tak, tik tak; Oh, ne hoş

Ah edip inliyorum,

Çünkü sensiz içi boş', 'Kalbimi dinliyorum: Tik tak, tik tak; Oh, ne hoş Ah edip inliyorum, Çünkü sensiz içi boş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tik-tak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı Bebek', 'hayati-bebek-aysel-celik-igs3g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluymuş doğduğunda o güzel bebek

Kan kırmızı yanakları, saçları gül bebek

Fazla itilme kakılma yokmuş altıya dek

Altıncıda vurulunca yere serildi bebek

Ah bahtszı bebek

Vah sevgisiz bebek

Başlamıştı oda hayat dersine

Evde hor görülünce koşardı öğretmenine

Gizli gizli ağlardı, yoktu evde dirlik düzene

Yemin etmişti kurtaracaktı bu aileyi o güne

Ah bahtsız bebek 

Vah sevgisiz bebek

Yalnızken düşünürdü dünyanın adaletsizliğini

Bir gün duyuracaktı oda ismini yurdunu, sevgisizliğini

O günü bekledi çalıştı çabaladı

Ancak çöktü karanlığa çabaladı çıkamadı

Ah bahtsız bebek

Vah sevgisiz bebek

Allah’a yalvardı yakardı yitirmedi umudunu

Tekrar baştan yemin etti durmadı

Ancak gördü sevgisiz olmadı

Oda Allah’ı insanları sevdi durdu

Ah bahtsız bebek

Vah sevgisiz bebek

Bir gün ansızın çaldı kapıyı mutluluk

Biliyordu umutla çalışınca mutluluk

Allah’a defalarca şükretti dünyalık

Oda öğrenmişti gülmeyi bütün günlük

Ah bahtsız bebek

Vah uçtu bebek', 'Mutluymuş doğduğunda o güzel bebek Kan kırmızı yanakları, saçları gül bebek Fazla itilme kakılma yokmuş altıya dek Altıncıda vurulunca yere ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayati-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşinayım', 'asinayim-aysel-celik-el7sl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşinâyım ben ona

Çaresi cenneti âlâ

Eğer birgün yok olursam

Kavuşmaktır arzu âlâ

Aşinâyım ben bu millete

Dağına, taşına ırmağına

Yükselen Türk bayrağına

Aşinâyım ben bu güzele

Aşinâyım ben bu orduya

Türk’e can veren anaya

Sana, ona dünyaya

Aşinâyım ben bu güzele

Aşinâyım ben bu sevgiye

Dünya’da tek duran barışa

Seven, sevilen hepinize

Aşinâyım ben güzele

Aşinâyım ben bu yeşile

Gökte mavisine, yerde şehidine

Ananı bağrında duran acıya

Aşinâyım ben bu güzele

Aşinâyım yerde duran güle

Yorganına sarılmış, uyuyan güzele

Kendini vermiş vatan uğruna

Aşinâyım ben bu güzele…', 'Aşinâyım ben ona Çaresi cenneti âlâ Eğer birgün yok olursam Kavuşmaktır arzu âlâ Aşinâyım ben bu millete Dağına, taşına ırmağına Yükselen Tü...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asinayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ki Kimsin', 'sen-ki-kimsin-aysel-celik-m307k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlıklar üzerine oturmuş düşünürsün

Ne gelenin var ne gidenin

Sen ki kimsin

Zavallı birisin

Bir de oturmuş güzel şeyler hayal ediyorsun

Elbiseler katlar, yatlar

Sen ki kimsin ki hayallerdesin

Daha bir ev yok ki dersin

Sen ki kimsin

Zavallı birisin

Oturmuş idealler kurarsın

Dünya çok adaletsiz dersin

Büyüyünce adaleti sağlayıp kol kanat olacağım

Sen ki kimsin

Zavallı birisin

Üstelik okumada bilmezsin

Diğer okuyanların hevesine kapılıp gidersin

Ana yok baba yok sonrada para yok

Sen ki kimsin

Zavallı birisin

Yine oturmuş düşlersin

Allah’a dua edersin

Hani yaptığın bir iş yok ki dersin

Birde istersin Allah’tan güzel güzel şeyler

Namaz yok oruç yok

Sen ki kimsin

Zavallı birisin', 'Karanlıklar üzerine oturmuş düşünürsün Ne gelenin var ne gidenin Sen ki kimsin Zavallı birisin Bir de oturmuş güzel şeyler hayal ediyorsun E...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-ki-kimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Bakışları', 'onun-bakislari-aysel-celik-5yuxm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onun yalnızca bakışları derindendi

Tarihten taa geçmişlerdendi

Mahsundu, ama gelecektendi

Mavi, yalnızca masmavi ışıldıyordu

Belki yaptıklarındandı, büyüklüğü

Belki de yalnızca çocukluğu

Ama ne olursa olsun

Yalnızca mavi gelecektendi

Onun bakışları ıstıraplardandı

Onca halkın binlerce kanıydı

Gelecekte düşünceleriydi

Ama ne olursa olsun, masmavi denizlerdendi

Belki fikirleriydi, kararlarıydı

Belki de kahramanlıklarıydı

Ama ne olursa olsun

Mavi masmavi çağdaşlardandı

Onun bakışları topraklardandı

O halkın kanlarıyla topraklardan

Gönlünde sevgi, belinde silahı

Vatanı canı gibi sevenlerdendi

Belki yalnızca görünüşündeki ihtişamdı

Belki de zaman, durdurak bilmeyişiydi

Ancak koca bir ilerleyişi,

Sığdırmıştı kafalardaki düşünceyi

Onun bakışları halkın sevgisindendi

Çanakkale zaferlerindendi

Türk ve dünya görüşünden

Yalnızca bir ön derdi

Belki yükselişinden, vatanı ilerletişinden

Belki de köylünün nefesinden

Yapışından, edişinden son defa

Uygarlığa yürüyüşündendi

Onun bakışları Türk’ün gururuydu

Sineminde yetiştirdiği insanıydı

O karanlıktan doğan güneşti

Yalnızca mavilerin arasından

Belki yalnızca son bakışlarıydı

Son ama sonsuza kadar uyuşuydu

Uyanmayacaktı ama çok rahattı

Çünkü bir yol, bir ışık vardı

Türkiye oradan gidecekti', 'Onun yalnızca bakışları derindendi Tarihten taa geçmişlerdendi Mahsundu, ama gelecektendi Mavi, yalnızca masmavi ışıldıyordu Belki yaptıklar...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/onun-bakislari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bugün Biraz Yol Yürüdüm', 'ben-bugun-biraz-yol-yurudum-dertli-ozan-0wzgc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eskisi gibi değil güneş

Artık daha bir yakıcı ve öfkeli

Kim ne derse desin.

Ekonomik göstergeler iyiye gidiyormuş

Bu gösterge bizim taraflara pek uğramıyor,

nedense...

İşte böyle günlerden birinde yakıcı güneş

altında çıktım yola

Bizim evden, biraz uzaktaki başka bir eve.

Bahçenin ortasında kedi yatmış iki seksen

Hareket bile etmiyor, öldü mü acaba

diye bakacak oldum

Yok nefes alıyor, 

yalnızca sıcaklardan bunalmış.

Belediyenin çöp toplama günü

Sıcak havaya çöp kokuları karışıyor.

Birkaç insan takmışlar güneş gözlüklerini

salına salına yürüyorlar.

Bende yürümeye devam ettim ve 

sokağın köşesini dönünce...

Dilenci teyze oturmuş ve kısık sesiyle

dilenmeye çalışıyor, halbuki

gerçek çok farklı.

Paraları topluyor, bizim bakkala gidiyor

Yettiği kadarıyla bira alıyor.

Günü kurtardı ya gerisi Allah Kerim! 

İçiyor içiyor ondan sonra başlıyor sağa sola

sallamaya.

O bile içmeden sallayamıyor, 

bense tövbe ettim artık içmiyorum.

Biraz daha yürüyünce, eskici ahbaplarım

selam veriyor.

Bende boş geçmiyorum onları.

Dört yolla geldiğimde herzamanki gibi

İki bina arasında ki patika yoldan geçiyorum.

Sağımdaki solumdaki ağaçlar güneşin önüne

geçiyor, serinliyorum biraz.

Bu arada bir cigara yakıyorum,

Derin bir nefes çekiyorum.

Sözde bırakacaktım sigarayı...

Aha! İlerde güzel güzel hatunlar,

gözüm kayıyor birine.

Biraz zayıfça, uzun ve kızıl gölgeli

saçları hafifçe esen rüzgarla dansediyor.

Sanki bir zerafet tanrıçası, yüzünü

görmek istiyorum ama aramızdaki mesafe

çok fazla ne mümkün...

Şans işte, benim yolumda gitmiyor, başka bir yol

seçiyor kendisine, aslında takip edebilirim

ama sonuca ulaşmayan bir yürüyüş olur,

bu sıcakta.

Biraz daha ilerliyorum,

Dükkan sahipleri sıcaktan bunalmışlar

atmışlar sandalyeleri bahçeye oturmuşlar

muhabet ediyorlar, kimbilir ne zamandan beri.

Daha ilerde karşılıklı iki fırın sahibi birbirlerini

yiyecekmiş gibi bakıyorlar birbirlerine,

bir gün kesinlikle birbirine girer bunlar.

Sabit pazarı da geçince yolun sonuda

geliyor, bundan sonrasında herkes işinde

gücünde... Kalabalalık...

Araba sesleri kulaklarımı tırmalıyor,

Aklım hala o kızıl saçlı dilberde...', 'Eskisi gibi değil güneş Artık daha bir yakıcı ve öfkeli Kim ne derse desin. Ekonomik göstergeler iyiye gidiyormuş Bu gösterge bizim taraflar...', ARRAY['Türk Edebiyatı','Şiir','Dertli Ozan']::text[], 8.5, '{"poet":"Dertli Ozan","poet_slug":"dertli-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/ben-bugun-biraz-yol-yurudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluşum Ve İhanetim', 'kurtulusum-ve-i-hanetim-aysel-celik-3qzpk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O namlularla göz göze

O kahpelerle göğüs göğse

Vatanı, malı, sevgisi hele canı pahasına

Bir derya gibi şu kan gölüne

Kellesi, kolu, bacağı gitmiş

Hâlâ ruhu vatanı kurtarmaya

Yeni filizlenen şu çocuğa

Bakta! Bakta sen de anla ama

Ne zillettir ki onların yaptıkları	

Yeyip içip yurda kattıkları

Eşkiyaymış, zerdüştmüş ya

Anla, anla! Kurtuluşa…

Bir ama o pak yüzüyle toprağa

Toprağa bastırtmaz o namerte

Şahlanan atıyla gök yaya

Yarab; Bu ne dehşettir bu hayasızca

Vatan parça parça gidiyor

Kendine gel arkadaş bu ne bir rüya

Ana, kardaş, bacı hepsi birden

Şu kafirlere bir dur ya

O zaman, işte o zaman

Geçmişin, geleceğin gördümü

Bir sefer sabahı buradan	

Güneş doğacak ülkü

Ana ana sen ağlama

Sen kara bahtına yanma

Gelecek! Gelecek analara

Gelecek oğulların hatırına…

Evin, barkın, canın gitmiş ne çıkar

Bir vatan kurtulacak

Güneş doğmasın ne çıkar

Eğer vatanım kurtulmazsa alçaklar

Bir gün sabaha güneş doğdu

Savaşmış, yorulmuş, gürgin ruhlara

O kanıyla sulanan toprağa

Vatan! Vatan! Kurtuluşa….

Şimdi senin yaptığın nedir? 

Sen şanlı tarihe vurdun kara

Sızlattın şehitlerin kemiklerini bir yara

Sen bu vatana kazığı çaktıran

Sen, senin için ölen bu atana

Sen namerde dedin dostum ya

Bu aziz vatan da

Kafiri yurt edindirdin, bark edindirdin

Hani senin Türklük gururun

Hani geçmişin kanlı göl deryaları

Unuttun yine dostun düşmanın

O yine bir ara vurur sabahlara

Senden hayır gelmez arkadaş

Senin aklın onlarda

Ruhun benzemiş onlara

Değil ruhun, aldattın vatana

Bir gün kurtulacaksın

Yine o gün iman göğsünde savaşacaksın

Yine var olma mücadelesiyle

Alçak! Bak şu vatana kaybedeceksin', 'O namlularla göz göze O kahpelerle göğüs göğse Vatanı, malı, sevgisi hele canı pahasına Bir derya gibi şu kan gölüne Kellesi, kolu, bacağı g...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/kurtulusum-ve-ihanetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özge', 'ozge-sami-akman-q6ojv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özge bir cansa eğer

Yaşıyorsa bir yerlerde

Bu yer yüreğinde bir yer olmalı

Aldığın nefesi almalı

Gördüğün düşü görmeli

Özge bir cansa eğer

Yaşıyorsa yüreğinde

Özge bir can’dır, o bir yaşam

O başka,  gayrıdır diyarda

Gökyüzünde yıldızdır

Saçlarında yağmur

Bahçende bir gül

Dudaklarında bir nefes

Özge bir gökkuşağıdır

Döner durur buralarda

Özge bir cansa eğer

Yaşıyorsa yüreğinde

Özge bir can’dır, o bir yaşam

O başka,  gayrıdır diyarda

O bir gecedir, bir gündüz

O bir güneştir, bazen dolunay

Bazen sarhoştur, tatlı bir dokunuş

Bazen dikendir, acı bir haykırış

Özge bir cansa eğer

Yaşıyorsa bir yerlerde

O yer yüreğinde bir yerdir….

®©', 'Özge bir cansa eğer Yaşıyorsa bir yerlerde Bu yer yüreğinde bir yer olmalı Aldığın nefesi almalı Gördüğün düşü görmeli Özge bir cansa eğer Y...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozge-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılırken', 'ayrilirken-sami-akman-98gkc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Veda  ederken    sana

İçimde  bir   burukluk

Elveda   diyemiyorum

Boğazımda  hıçkırık 

Ellerim   titriyor

Ellerini  tutarken

Ayrılmak  istemiyorum

O’  yaşlı  gözlerinden

Veda  ederken  sana 

İçimde bir  burukluk

Elveda  diyemiyorum

Boğazımda   hıçkırık

 ®©', 'Veda  ederken    sana İçimde  bir   burukluk Elveda   diyemiyorum Boğazımda  hıçkırık  Ellerim   titriyor Ellerini  tutarken Ayrılmak  istem...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilirken-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Diye', 'anla-diye-sami-akman-xcoxw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şarkılar yazdım sana

Şiirler okudum

Belki beni duyarsın

Diye..

Yollarda aradım

Parklarda gezdim

Belki beni görürsün 

Diye..

Kapına geldim

Divana durdum

Belki sevdamı anlarsın 

Diye..

®©', 'Şarkılar yazdım sana Şiirler okudum Belki beni duyarsın Diye.. Yollarda aradım Parklarda gezdim Belki beni görürsün  Diye.. Kapına geldim Di...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anla-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yerde', 'bu-yerde-sami-akman-4yhqt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekle beni yalnız

Ara yok olduğum bu yerde

Yarın, öbür gün ve sonra

Ara yok olduğum bu yerde

Takıl o sevdalı günlere

Uzasa da yılar gibi

Rakamlar gibi büyüse de

Ara yok olduğum bu yerde

®©', 'Bekle beni yalnız Ara yok olduğum bu yerde Yarın, öbür gün ve sonra Ara yok olduğum bu yerde Takıl o sevdalı günlere Uzasa da yılar gibi Rak...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-yerde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayacaksın', 'olmayacaksin-sami-akman-o0lxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bitecek ömür

Tozpembe günler bitecek

Yerini karanlıklar alacak

İşte o z aman sen olmayacaksın..

Kara toprak alacak bedenimi

Kurtaracak azaptan bu teni

Bensizlikte aratacak beni

İşte o zaman sen olmayacaksın..

Bir gün çalınacak kapın

Kurtulduğunu söyleyecekler

O öldü! Artık yok diyecekler

İşte o zaman sen olmayacaksın..

Dünya sana kalacak artık

Tek başına yaşaman için

Belki üzüleceksin ama

Teselliye ben olmayacağım..

®©', 'Bir gün bitecek ömür Tozpembe günler bitecek Yerini karanlıklar alacak İşte o z aman sen olmayacaksın.. Kara toprak alacak bedenimi Kurtarac...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmayacaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yeli', 'sevda-yeli-sami-akman-iebbb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen sevme beni

Bana bırak sevdamı

Benimle kalsın

Paylaşsın yalnızlığımı

Beni avutsun

Sen sevme beni

Kalbim seninle olsun

Güneş doğduğunda

Yalnızlık üstüne çöksün

Estikçe sevda yelleri

Sızlatsın kalbinin telini

Bırak sevme beni

Benimle kalsın sevda

Paylaşsın yalnızlığımı

Beni avutsun….

®©', 'Sen sevme beni Bana bırak sevdamı Benimle kalsın Paylaşsın yalnızlığımı Beni avutsun Sen sevme beni Kalbim seninle olsun Güneş doğduğunda Ya...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-yeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Seli', 'sevgi-seli-sami-akman-els1t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıktın karşıma birden

Ektin sevda tohumlarını

Bilmem haberin var mı? 

Sana olan duygulardan

Sen bilirmisin sevdayı

Her gün tutuşup alevlenen

Coştukta coşup içinde

Bir sel gibi köpük köpük

Bir sel oldu içimde

Sana olan sevgi

Coştukça coştu 

Bir sel oldu köpük köpük

®©', 'Çıktın karşıma birden Ektin sevda tohumlarını Bilmem haberin var mı?  Sana olan duygulardan Sen bilirmisin sevdayı Her gün tutuşup alevlenen...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-seli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Falcısı', 'gonul-falcisi-sami-akman-43uhi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu kısacık  ömrümde

Gönlümün  falcısı  ol

Söyle bana  ne olur

Bahtımın   rüzgarları

Yine  aynı  bahar da

Esme  deli deli

Bilmeden  kırarsın 

Aşkımın  dallarını

®©', 'Şu kısacık  ömrümde Gönlümün  falcısı  ol Söyle bana  ne olur Bahtımın   rüzgarları Yine  aynı  bahar da Esme  deli deli Bilmeden  kırarsın ...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gonul-falcisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Acı Daha Büyük Bir Çukur', 'her-aci-daha-buyuk-bir-cukur-yildiray-pilint-j3z88', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çukurlar,çukurlar, çukurlar

Her çukur büyük bir acı

Her acı daha büyük bir çukur

Yolu göremiyorum,kıpırdıyamıyorum

Tentelerin arasından bir toz bulutu

Durgun bir gece..

Bir sarsıntı, bir acı daha

Sonraki bir öncekinden büyük

Bir sonraki öncekindende...

Yol şakaklarıma çizilmiş

Bir çizgi

Alınyazısıymışçasına

Acıyla dolu...

Gözyaşlarım akıyor,

Benimle ilgili olmayan

Yalnızca ağladığımı biliyorum

Nedenini niçinini değil

İçimde vahşi bir kurt

Zincirlerini kırıp ulumak istiyor,

Görünen

Sünepe ağlayan bir köpek.', 'Çukurlar,çukurlar, çukurlar Her çukur büyük bir acı Her acı daha büyük bir çukur Yolu göremiyorum,kıpırdıyamıyorum Tentelerin arasından bir ...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Pilint']::text[], 8.5, '{"poet":"Yıldıray Pilint","poet_slug":"yildiray-pilint","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-aci-daha-buyuk-bir-cukur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Doğuyor', 'gun-doguyor-sami-akman-arwik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam  oldu  gülüm

İndir  kepenkleri 

Tak  kilitleri  çengeline

Tutalım  evimizin  yolunu

İyi  akşamlar dedin gülüm! 

Kime?   Niye? 

O’nun  akşamı  iyi olmaz

O’na geceler  umut

O’na  geceler  ışık 

Yalnızlığa  alışık… O…

Beklerken  sabahı

Gün  doğmasın diye 

Boğazında  hıçkırık,

Gözünde  yaş.

Gün  doğuyor  yavaş  yavaş

Yine mutsuzluğa,

Yine  umutsuzluğa,

Acıya,  hasrete

Gün  doğuyor  GÜLÜM! 

®©', 'Akşam  oldu  gülüm İndir  kepenkleri  Tak  kilitleri  çengeline Tutalım  evimizin  yolunu İyi  akşamlar dedin gülüm!  Kime?   Niye?  O’nun  ...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gun-doguyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-sami-akman-l49ak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok ama  çok  sevdim  seni

Her dakika  görmek  istedim

O güzel  gözlerini

Çok  ama  çok  sevdim  seni

Gözlerim  gözlerini  gördüğü  zaman

Kalbimin  delice  çarptığı  zaman

İçime  sevda  ateşi düştüğü zaman

Çok  ama  çok  sevdim  seni 

Öyle  mahsun    bakmasın  gözlerin

Akıtmasın  tane tane  yaşın

Ayrılık  saatinin  geldiği  yakın

Çok ama  çok  sevdim  seni

®©', 'Çok ama  çok  sevdim  seni Her dakika  görmek  istedim O güzel  gözlerini Çok  ama  çok  sevdim  seni Gözlerim  gözlerini  gördüğü  zaman Ka...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-sami-akman-zu6hi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Suçum  sevmek ise

Kıymetin bilmek  ise

Sana  değer  vermekse

Bunca  sitemin  niye

Gözlerim  gözlerini

Yüreğim  yüreğini

Bedenim  bedenini

Delice  sevdi  ise

Bunca  sitemin  niye

®©', 'Suçum  sevmek ise Kıymetin bilmek  ise Sana  değer  vermekse Bunca  sitemin  niye Gözlerim  gözlerini Yüreğim  yüreğini Bedenim  bedenini De...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sitem-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Onu', 'sevdim-onu-sami-akman-6b8dl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanrım  birini  çok sevdim

Ama imkansız  bir  sevgi bu

Biliyorum  O’nun  kalbi dolu

Yalvarırım  sen bana  akıl  doku

Ne  yapayım  sevdim! 

Delice  sevdim  O’nu

Dolmuyor   O’nsuz  saniyeler 

Biliyorum  bana  deli  derler

Ekmeğim,  aşım,   yaşantım “O”

Bedende  can, tenimde  kan “O”

Biliyorum  O’nun  kalbi  dolu

Yarabbi  sen bana  akıl   doku

Ne  yapayım  sevdim! 

Delice  sevdim  O’nu

®©', 'Tanrım  birini  çok sevdim Ama imkansız  bir  sevgi bu Biliyorum  O’nun  kalbi dolu Yalvarırım  sen bana  akıl  doku Ne  yapayım  sevdim!  D...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevdim-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Olsun', 'omur-olsun-sami-akman-29wmv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir  ışık  ver  gönlüme

Karanlık  dünyamda

Gören göz olsun

Bir  ümit  ver  yüreğime 

Yıkılan   umutlarım da

Filizlenen  dal olsun

Bir  can  ver  bana

Canıma   can  katsın

Bir  can  ver  bana

Ömür  olsun. 

®©', 'Bir  ışık  ver  gönlüme Karanlık  dünyamda Gören göz olsun Bir  ümit  ver  yüreğime  Yıkılan   umutlarım da Filizlenen  dal olsun Bir  can  ...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/omur-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ateş,Bir İntikam,Bir Yılan', 'bir-ates-bir-i-ntikam-bir-yilan-yildiray-pilint-73ztt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok derinlerde

Karanlık,nemli mahzende

Kırmızı ışıklar saçan

Bir çift göz bana bakmakta

Derinden derine 

Hırıltılar,iniltiler,ulumalar gelmekte

Kurt kızgın,çaresiz

Sesini duymam için bana yalvarmakta

Aniden birdenbire

Bir sıçrayışta fırlayacak ininden

Boğazıma yapışacak gibi

O nu görebilmem için,duyabilmem için

Parçalayacak belkide beni...

Bir ateş

Bir intikam 

Bir yılan

Ne kadar çöreklenip uyuyabilir

Esen poyrazda

Yürek acısında

Üstüne basılmasında...

Ya bir kurt ne zaman çıldırır

Ya bir kurt ne zaman çıldırır.', 'Çok derinlerde Karanlık,nemli mahzende Kırmızı ışıklar saçan Bir çift göz bana bakmakta Derinden derine  Hırıltılar,iniltiler,ulumalar gelme...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Pilint']::text[], 8.5, '{"poet":"Yıldıray Pilint","poet_slug":"yildiray-pilint","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-ates-bir-intikam-bir-yilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Gibi', 'toprak-gibi-sami-akman-v9syt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana   öyle  muhtacım  ki 

