INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Hüzün', 'sari-huzun-bahtiyar-arslan-7uv3x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine,

sen düştün aklıma

titrek ellerin

yorgun gözlerin.

yine

sen düştün aklıma

solgun yüzün

oooy yar

dört bir yanım sarı hüzün...', 'Yine, sen düştün aklıma titrek ellerin yorgun gözlerin. yine sen düştün aklıma solgun yüzün oooy yar dört bir yanım sarı hüzün......', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sari-huzun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık bulsun artık huzur', 'i-nsanlik-bulsun-artik-huzur-yilmaz-ozturk-8v55j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde hem bir sevinç hemde bir sızı var

Ben mutluyum ama acı çeken birileri var

Acı çekenler var iken mutluluk yarım kalıyor

Ben çileye razıyım İnsanlık bulsun artık huzur

Bireylerin acısı topluma yeter insan olan için

İnsanlıktan bihaber olan dünyada yaşar kendi için

Derman olmaktır maksadım çilede insanlık için

Ben dert çekmeye razıyım İnsanlığın mutluluğu için

Sev sevgi beklemeden iyilik insana insandan

Karşılısız olmalı sadakat makamı insanın

Sen sev sevilmesen bile birgün sevileceksin 

Ben çileye razıyım sen mutlu ol diye cancazım', 'İçimde hem bir sevinç hemde bir sızı var Ben mutluyum ama acı çeken birileri var Acı çekenler var iken mutluluk yarım kalıyor Ben çileye raz...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanlik-bulsun-artik-huzur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-elazigli-mustafa-kaya-k8wkr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'haziranın yirmidördü

şipşirin gecekondumuza ayak basıyoruz

bu kez yetişiyoruz kiraza

annem..

hoş annem..

yine bana yapacaklarımı

tek tek konuşan annem 

evin odalarında ''frig frig'' dönen annem

''toz toprak gidiyy''..''

evin içi ahır olmuş'' diyen annem

namazlarında gittikçe güzelleşen annem

günün ezanlarında rahmetliden ses arıyan annem

sabah.. her  sabah.. 

sessiz sessiz kahvaltı hazırlayan annem

kapıları muslukları usul usul açıp kapayan

ilerlemiş yaşına rağmen 

diri diri koşturan annem

kim bilir kaç kez döndü durdu 

temiz dursun diye bu gecekondu...

hatıralarım tazelenir ne zaman gelsem

işte şurada duran mini masa sandalye 

Kuran okuyan rahmetli babam

günün belli saatlerinde 

şimdi ben onu dinlerim..

babamı dinlerim

bahçenin her karesinde 

ayak izlerine rastlarım

annemin babamın kardeşlerimin

annem...annem..

güzel annem

kaç yıl çekti bu derdi 

kaç yıl daha sevecek bizleri

ve ben her gelişimde 

bizi bekler bulurum

annemi...

Mustafa KAYA

24.06.1999/Ankara', 'haziranın yirmidördü şipşirin gecekondumuza ayak basıyoruz bu kez yetişiyoruz kiraza annem.. hoş annem.. yine bana yapacaklarımı tek tek kon...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/annem-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elleri Boş Kaldı', 'elleri-bos-kaldi-ufuk-coban-z47il', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım çaldı bütün zamanımı,

Sormadı yüzümde olmayan gülümseyişin nedenini.

Sustum çaresiz, sessiz bırakmak için,

Sana giden bir selamı, bir de özürü.

Yıldızları sayamaz oldum yağmurun buğusundan,

Seni soramaz oldum kabahatimin büyüklüğünden.

Bir affı beklerken küçük bir umutla,

Daha uzak oldun hem benden, hem de kendinden.

Bir umut güneşe, diğeri sana bağlı.

Bir hasret ki, sonu her zamanki gibi.

Artık tebessüm ne sana, ne de başkasına.

Bu son karar suçu ne sana, ne de bana bağlı.

Ne yapsam ürkek, artık unutturmaz olanları,

Seni tanımasam belki bulurdum başka bir şansı,

Bahardan önce açtıramadığım için papatyaları,

Gönderilen özürün elleri boş kaldı.

1999', 'Yalnızlığım çaldı bütün zamanımı, Sormadı yüzümde olmayan gülümseyişin nedenini. Sustum çaresiz, sessiz bırakmak için, Sana giden bir selamı...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/elleri-bos-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekler ve hissettiklerim', 'gercekler-ve-hissettiklerim-sedat-emre-bolat-fcsrg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayallerim miydi                                            

Yoksa gerçekler miydi 

Seni geçmişten geleceğe taşıyan..? 

Ben seni başkalarından hatırlamadım

Ne de kendimden.

Unutulmayacak gülüşlerin hatırlattı,

Toz kaplamış bildiklerimden.

Söküp alan gözlerin hatırlattı.

Sensiz bir yaşamdan dolayı; 

Cümlelerim yarım kaldı,

Hayatımın sonu üç nokta.

Beni tamamlayacak melek hatırlattı,

Şeytanlara bırakma beni

Vesveselere...

Seni bana korkular hatırlattı.

    Erkek adam korkar mı? 

    Seni bana erkekliğim hatırlattı.

Unutmadım

Asla da unutmam.

Hayallerimde yaşatayım derken

Gerçeklerde kaybettim seni.

Bu da zaten hissettiklerimden.

Gördüklerimden olmasa gerek.

Bugünlerde düşünüyorum da,

Gördüklerimizin ne kadarı gerçek? 

Hislerimizin ne kadarı yalan? 

Ya da yaşantımızın hangi kısımları

Hissettiklerimizden geliyor? 

Ben seni gerçeklerde kaybettim.

Bir kadın ne kadar hissettiklerini yaşamak istese de

Yaşadıklarını sahiplenir sadece

Bu yüzden yaşadıkları hissettikleri gözükür.

Yoksa mutluluk hayatın neresinde,

Kadına ait pencere adetince? 

Sence bu diyarlarda az değil mi? 

Seni bana kadınlığım unutturdu.', 'Hayallerim miydi                                             Yoksa gerçekler miydi  Seni geçmişten geleceğe taşıyan..?  Ben seni başkalarınd...', ARRAY['Türk Edebiyatı','Şiir','Sedat Emre Bolat']::text[], 8.5, '{"poet":"Sedat Emre Bolat","poet_slug":"sedat-emre-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gercekler-ve-hissettiklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm, yaşanmamış bir temmuzdur', 'olum-yasanmamis-bir-temmuzdur-selahattin-yetgin-axbxb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz ki; zaman zaman bu dünyadan bunalmış iki gezgin gibi her gün yeniden çıkarız labirentlerimizden

Sessiz göz yaşlarımızla ormanları besler, gönlümüzü verdiğimiz nilüferleri sermaye yaparız şiirlerimize

Elmalarımızı çalar büyücüler, bir kuğunun kanatlarına tutunarak çocukların gülüştüğü  kentler ararız

Ölüm,  yaşanmamış kırmızı bir temmuzdur, külümüzü savurmaya hazır bir eylül dolanır başımızda.

Hayatımızın yuvarlak taşında gerdan kırar, göbek atarız utangaç gülümseyişlerle. Sokaklarda ceylan sürüleri, pusularda çakal gölgeleri ile milyon senedir döner bu dünya. Dal dal, gürül gürül, mevsim mevsim büyüyüşlerimizin ve kayboluşlarımızın umarsızlığında çalınır yaşamın garip tamtamları. Tırnağı her yerinden kırılmış, binlerce kadeh şuursuzca gırtlaklardan dökülmüş ve ar çivisi sökülmüştür bu hayatın.

Fısıltı ormanlarında kayıp bir hazinenin formüllerini birbirine ekleyerek bulmaktır yüreğini, seni anlamak. Tapınak yazıtlarının gölgesinde coşkulu halaylara durmaktır seni sevmek. Çocuk bakışlarının, bilge duruşlarının parklarında doyasıya yorulmaktır sevincine ortak olmak. Her kaybedişin hüznünde gülmektir varlığının sarmaşıklarına tutunarak bedenini kucaklamak. Seni sevmek, yeryüzünün atlasında varsıl kelimelere can vermektir bir tanem.

Yaşanası tüm duruşlarının yaşam bakışlarında tutkulu birkaç sözcüğe işlesem yüreğini, anlatabilir miyim seni? . Bir ney üfleyişinin ruhani sarılışlarında ne yaparsak yapalım, sarabilir miyim bedenini? . Kıyılır koca bir beden özleminle, çırılçıplak kalır deniz ötesi gözlerinde, tutuklanır sürgün yüreğinin hücrelerinde. Biriken sevgimizin hatıra tepelerinde bir yıldız gülüşüyle dokunmuştum oysa kutsal yüreğine. Gözlerin dalgalı denizleri çağrıştırırken gemilerimi sular basmıştı aniden. Geceler boyu korkak kürekler çektik biz bu aşka. Günlerce aşkın adasını aradık gizemli sözcüklerimizle yana yakıla. Çatlamış dudaklarımıza vefamızla dokunduk, umarsız bu sevdaya sen Leyla, ben Mecnun olduk. Sabır adasına biz bu aşkın bayrağını asarak dosta düşmana en büyük sevdamızı sunduk.

Gökteki sarı yıldızların ışıktan toplarla oyunlara daldığı, şarkıların sokaklarda müziğini aradığı, yalnızlığın kendi kahramanlarını sakladığı bu ömür limanında ne zaman aklıma düşsen yediveren güller açar içimde. Her gülüşünden güller ekerim kıraç topraklara. Ne zaman yalnız kalsam kızıl bir öfkenin sancısı basar bedenimi, parmaklarım ışık kümeleri toplar gökten, yalnızlığımın şehirleri yerle bir olur birden.

Koluma girince zaman, birlikte yürürüz bu kentin caddelerinde. Zamandan çaldığımız ne varsa ceplerimize doldurur, harcarız bir deniz meyhanesinde. Her kadeh kaldırışımda yüreğine, kucaklarım sevgini, tane tane olursun ellerimde ekerim denizlere gülüşlerini. Mavilikler avucumuza yakamozlarını sunar, inançlarımız büyür, karanlık yerlerde sevişerek öfkelerimizi gömeriz.

Her biri birbirine benzeyen, krokileri sonradan çizilmiş kaçak kentlerde biz en çok birbirimize benzediğimiz için severiz birbirimizi. Kendimizden olmayan tüm tutkuları atarız kapı dışarı. Her sorumuzda yanıt, her çölümüzde bir anıt, düşlerimizde büyür kimi binlerce sarkıt. Morunu beğenmeyiz dağların ve yeşil sevinçler ekeriz zirvelerine. Kendi sözümüzden başka hiçbir söz avutmaz, ağlatmaz bulut bulut yüreğimizi.

Çiçeklerin kırılmışlıktan dert yandığı, çıplaklığın utançlara soyunduğu bu yaşam kentinde gülü ustura yalnızlıklarına terk eden, bozgunlara doymamış yüreğimizi heder eden, acının hiçbir sofradan eksik olmadığı bir ömür talanı yaşanır sevgisiz. Hiçbir zaman kendi şiiri olmamış, ne yapsa kendi günlüğünü yazamamış kaçak yolcular vapurudur bu dünya. Fesat, yaban ve kendi dünyasında zavallı düşünüşlerle ömürlerini tüketenlerin dergahıdır bu kent.

Her şiir, her yazı mutluluğu anlatmıyor işte. Sesimizi kendi sularımızda boğdukça ve geleceğimizi konuşamadıkça bu olmazlar labirentinden çıkamayacağız birlikte. Senin tarotlarında, benim iskambil destelerimde hoşumuza giden ne var söyle. Binlerce şeytan taş atarken gövdelerimize neden korumaz bizi o çok sevdiğimiz yıldızlar, neden saklamaz kimliğimizi çok güvendiğimiz denizler? .

Biz ki; zaman zaman bu dünyadan bunalmış iki gezgin gibi her gün yeniden çıkarız labirentlerimizden. Sessiz göz yaşlarımızla ormanları besler, gönlümüzü verdiğimiz nilüferleri sermaye yaparız şiirlerimize. Elmalarımızı çalar büyücüler, bir kuğunun kanatlarına tutunarak çocukların gülüştüğü, acıların işlemediği kentler ararız. Ölüm, yaşanmamış kırmızı bir temmuzdur, külümüzü savurmaya hazır bir eylül dolanır başımızda.

Çağrısız gittiğimiz tüm şölenlerde dingin yokluklar içerisinde olmamız bundandır belki de. İhanetin hiç yazılmadığı yaşam sözlüğümüzde aşınan, taşınan ve solan bir bahardır yaklaştığımız. Acıların kimsesizliği çarpar yüzümüze deniz kıyılarında yürüdükçe biz. En büyük serüvenimizi yazmaz masalcı dedelerimiz. Her sigara dumanında, her çaresizliğin tufanında yeniden doğrulur, aşkları, sevdaları yangın yüreklerimize hapsederiz.', 'Biz ki; zaman zaman bu dünyadan bunalmış iki gezgin gibi her gün yeniden çıkarız labirentlerimizden Sessiz göz yaşlarımızla ormanları besler...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olum-yasanmamis-bir-temmuzdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim Yoldan Çıktı...!', 'siirlerim-yoldan-cikti-dilek-egri-6tqel', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arayışlarda kayboldu hayallerim

bulana yürek ödülü....

Armutun sapı

üzümün çekirdeği olmasın 

beyaz atlı prensimin hayatımdaki miladı..

Görür görmez olsun

aptala döneyim

sudan çıkmış balıkta iyi bir benzetme...

Üstünde ne olduğu

boyu posu

kokusu

silinsin hafızamdan...

O an...

havada ki aşk kokusundan başka birşey

hatırlamayım...

gözlerinin gülünü gözlerimden çekmesi kafi

aşk terleri dökmeme...

Ben bilirim bu hallerimi

şiirlerim beni dinlenmeden ellerimle iş birliği yapıp

yoldan çıkıyorsa

yazıyorsa aşk üstüne ne varsa

ve konu ayrılık değilse

bir ihanetin bedduası değilse şiirimin son cümlesi

eyvah...! 

......sıkı dur yüreğim

............kalemime şenlik bi sevda başlıyor', 'Arayışlarda kayboldu hayallerim bulana yürek ödülü.... Armutun sapı üzümün çekirdeği olmasın  beyaz atlı prensimin hayatımdaki miladı.. Görü...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/siirlerim-yoldan-cikti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer Dostluk', 'meger-dostluk-sedat-emre-bolat-gtp5z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki ben arasında,başka bir ben:

Dostluk dilde değilmiş

‘Nasıl yani? ’ diyeceksin

Bana bunu sen öğrettin aslında.

Her mutluluğum bir çiçekmiş

Ve hep çiçeği verdiklerime bakmışım

Bu çiçek nerden gelmiş? 

Hangi toprağın? 

Farklı renkler

Çeşit çeşit...

Verdiklerim 

Annem,sevgilim,işim....

Bazen gözyaşım olmuş.

Bazen parasızlığım

Bazen hovardalığım

Ama hep bunlardan sıyrılıp

Sana gülmüşüm 

Sana ağlamışım.

Geceleri düşün düşün..

Dönmüşüm Allah a c.c.

Sevgiliye,anneye,babaya,gardaşa

Dönmüşüm orda olmasam da memlekete

Orman dibi pikniklere

Koparmışım oralardan çiçek

Dönmüşüm yine aynı yere

Ama bir insan silüyeti  varmış yanımda

Fark edememişim.

Çöl ortasında bir pınar

Aç karında tatlı bir hurma

Çorba tasında son kaşık

Kendinden olmayan son dökülen kan

Dostluk.

Deli miyim öldüreyim..? 

Yanağına bir öpücük kondurayım.

Bakışlarında bakışlarımı dondurayım..

Dostum var göz bebeğinden ziyade yüreğini gördüğüm

Elinden ziyade dudaklarını tuttuğum', 'İki ben arasında,başka bir ben: Dostluk dilde değilmiş ‘Nasıl yani? ’ diyeceksin Bana bunu sen öğrettin aslında. Her mutluluğum bir çiçekmiş...', ARRAY['Türk Edebiyatı','Şiir','Sedat Emre Bolat']::text[], 8.5, '{"poet":"Sedat Emre Bolat","poet_slug":"sedat-emre-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/meger-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan bahçelerinden hüzün zindanlarına', 'hazan-bahcelerinden-huzun-zindanlarina-enes-ates-zpx17', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazan bahçelerinden hüzün zindanlarına

Eriyip giden bir hayatın çırpınış feryatları

İnletirken en ücra köşesini dünyanın

Bitâb düşmüş yürekle avuçladığım hüznü

Efsûn-u ömrün en güzel penceresine

İniltili insanlar yetiştirerek içimde

Bir kanaviçe ile örülü mağaralardan

Duygularımdan bir imbat yapıp 

Çıkardığım ''sen''le birleştirdim.

Sükûta çığlık atıp münzevî bir hicapla

Parçaladım perdesini bütün sensizliklerin

Kapalı kapılar adında bulduğum

En zalim, şehlâ ve derin

Kurtulmak isterken yine; 

                                                  Sendin...', 'Hazan bahçelerinden hüzün zindanlarına Eriyip giden bir hayatın çırpınış feryatları İnletirken en ücra köşesini dünyanın Bitâb düşmüş yürekl...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazan-bahcelerinden-huzun-zindanlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-arafat-arik-mwf5p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar akşamı hüznünden çıkıp,

Yüzünde en tatlı gülüşlerle gel! ,

Benliğin,akılın seddini yıkıp,

Göğümde ülker ol,saf düşlerle gel! ...

Zamandan sıyrılıp,vehminden arın,

Nefretini öldür,sevgiye bürün,

Kardelen ol yeşer,üstünde karın,

Yürek yangınına kar-kışlarla gel..

İsmini,cismini mekana bırak,

Kibrini,kahrını takana bırak,

Kendini gönlüne akana bırak,

Gönül gözü ile bakışlarla gel! ...

Ummanı,deryayı sığdır sedefe,

Muhabbet sırrını koyup hedefe,

Aşkını nakış et işle gergefe,

Özünde,gündoğar nakışlarla gel! ...', 'Bir bahar akşamı hüznünden çıkıp, Yüzünde en tatlı gülüşlerle gel! , Benliğin,akılın seddini yıkıp, Göğümde ülker ol,saf düşlerle gel! ... Z...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cagri-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-i-lknur-cekici-osgg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yırtılan aşk defterinin

Solan yapraklarısın

Bembeyaz bir geçmişin

Kapkara günlerisin

Kalemimin ucundan

Dökülen tek şiirsin

Hasret çiçeklerini

Geceme serensin

Beni boynu bükük

Bırakıp da gidensin

Yüreğimi yerden yere

Vurup da terk edensin', 'Yırtılan aşk defterinin Solan yapraklarısın Bembeyaz bir geçmişin Kapkara günlerisin Kalemimin ucundan Dökülen tek şiirsin Hasret çiçeklerin...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-606-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ol O Zaman', 'sen-ol-o-zaman-sedat-emre-bolat-3ia3e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek benim demeden

Benim demek..? 

Olabilmek kendini her şeye rağmen,

Her insana rağmen

Her aleme rağmen

Olabilmek kendini.

Vur bütün gücünle sokak ortasındaki tenekeye

Bağır boş sokaklarda avazın çıktığı kadar

Eğer çağıracaksa seni içinden

Anne edasıyla yaptıkların.

İçinden geliyorsa hıçkıra hıçkıra ağlamak 

Işık gibi bir günde siyah giyinmekse

Eğer ruhunu giydiriyorsa

Anne edasıyla yapıkların

Sen ol o zaman.

İstemediklerin istediklerindeyse

İstediğin zamanda istememekse

Karmaşalar içinde dahi sensen kendin

Sen ol o zaman! 

Kimsenin sen olmadığı bir zamanda

Kişiliklerin ödünç kullanıldığı bir zamanda

Ben olmanın mesel olduğu bir zamanda

Zamandan çıkıp yüreğinde olduğunda

Sen ol o zaman

                        Sen ol...!', 'Tek benim demeden Benim demek..?  Olabilmek kendini her şeye rağmen, Her insana rağmen Her aleme rağmen Olabilmek kendini. Vur bütün gücünle...', ARRAY['Türk Edebiyatı','Şiir','Sedat Emre Bolat']::text[], 8.5, '{"poet":"Sedat Emre Bolat","poet_slug":"sedat-emre-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-ol-o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemrem', 'cemrem-arafat-arik-ht6ve', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Candan can alırmış ağı gözlerin,

Enginde süzülür kuğu gözlerin...

Mahmur sabahımın asi goncası,

Ruhuma işlemiş buğu gözlerin...

Efsane efsane dilde söylenir,

Mücrim günahının çoğu gözlerin...', 'Candan can alırmış ağı gözlerin, Enginde süzülür kuğu gözlerin... Mahmur sabahımın asi goncası, Ruhuma işlemiş buğu gözlerin... Efsane efsan...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cemrem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız bedevi', 'yalniz-bedevi-enes-ates-2amd2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tozlu yüreklerin umut öksürdüğü bir dünya

Âlem kendi içinde kızıl kıyamet

Gerçekte asıl yok, icraat: rüya

Neredeyse baş tâcıdır ihanet

Gam ve keder yüklü kervanlarımda

Yalnız sana doğru uzar yollarım

Serâbınla güzîde bir göl çölün ortalarında

Sen varsın orda diye, kendimi oyalarım

Gaflet şerha şerha donandı şimdi

Örümcek ağ ördü çelikten, hayatıma

Ensemde haşeratlar gezindi

Mazeret bulmalıyım maruzatıma

Çocuklar neşeli, büyükler ölgün

Bir bölücü edâsı şahikâlarda

Seni ya''dedermiş gibi bütün gün

Dolanıp dururum helezonlarda

Efsunlu gözlerin gelir aklıma

Şehlâ ve mütevazi bir kahverengi

Bir yorgunluktur düşer ayaklarıma

Hatırlatıverir kötü ahengi

Hatıra kanlı bir urgan boynumda

Göğsümde yara gülleri filiz

Yılan hiç beslemedin koynumda

Hiç uçurtma uçurtmadım gökten habersiz...', 'Tozlu yüreklerin umut öksürdüğü bir dünya Âlem kendi içinde kızıl kıyamet Gerçekte asıl yok, icraat: rüya Neredeyse baş tâcıdır ihanet Gam v...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalniz-bedevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulunur', 'bulunur-arafat-arik-2dymc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün olur eskimez yüzler bulunur,

Özüne güvendik sözler bulunur.

Varsın gülistanı görmesin körler,

Karanlıkta gören gözler bulunur...

Bahara gülmeyen sarhoş arıya,

Yaprağı sararmış güzler bulunur,

Sevgiyi dileyen neden araya? 

Boran ortasında yazlar bulunur...

Damla koysan almaz,dolu olana

Atlas sersen gelmez,yolu olana

Çilesi vız gelir gülü olana

Bir ömür çekilir nazlar bulunur', 'Gün olur eskimez yüzler bulunur, Özüne güvendik sözler bulunur. Varsın gülistanı görmesin körler, Karanlıkta gören gözler bulunur... Bahara ...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulunur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Rüzgar', 'deli-ruzgar-arafat-arik-61149', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,içimde esen deli bir rüzgar,

Engel tanımaz yıkar duvarları,

Varsın bir tohuma gizlensin çınar,

Aç sen sonuna kadar gönlünde kapıları,

Yüreğin lugatinde hece hece adın var,

Eritir bir bakışın kutupta buzdağları...', 'Sen,içimde esen deli bir rüzgar, Engel tanımaz yıkar duvarları, Varsın bir tohuma gizlensin çınar, Aç sen sonuna kadar gönlünde kapıları, Yü...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/deli-ruzgar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsun Kokan Çiçek', 'efsun-kokan-cicek-arafat-arik-ekjr7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen onsekiz yaşımın çılgınlığı,

Efsun kokan çiçek...

Katran karası gecelerimin ışığı,

Aman sabahlar olmasın,güneş doğmasın,

Lodos esmesin,yağmur yağmasın bitmesin gönlümün dinginliği...', 'Sen onsekiz yaşımın çılgınlığı, Efsun kokan çiçek... Katran karası gecelerimin ışığı, Aman sabahlar olmasın,güneş doğmasın, Lodos esmesin,ya...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/efsun-kokan-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-arafat-arik-c3uji', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lugatlar birlik olsa gösterse sözlerini,

Anlatamaz saçının telinde gördüğümü,

Gözlerimin içine dikip te gözlerini 

Bir baksaydın anlardın bendeki kördüğümü...

Bilsen ıssız gecede,karanlıklar koynumda,

Hasretin; dayanılmaz,ağır yükü boynumda,

Yalnızlığın, en derin yalnızlığı beynimde,

Sensizlik zincirini seninle kırdığımı..

Hani açıp elleri,seni dileyip Hak''tan,

Ya dayanıp acıya,ya bitip ayrılıktan,

Hayaline koşarken kaybedip karanlıktan,

Hissettin mi kahrımı açığa vurduğumu..', 'Lugatlar birlik olsa gösterse sözlerini, Anlatamaz saçının telinde gördüğümü, Gözlerimin içine dikip te gözlerini  Bir baksaydın anlardın be...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kordugum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet', 'cumhuriyet-aysel-celik-1aw3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Millet elele vererek

Ya bağımsızlık! Ya ölüm dediler,

Korkusuzca düşman üzerine yürüdüler,

Bağımsızlığa, Cumhuriyet koştular

29 Ekim 1923’de

Yeni bir Cumhuriyet kuruldu

Hür, bağımsız ve korkusuz

Bir Cumhuriyet oldu

Şimdi ilerde taa ilerde,

Diğer devletlere ulaşmış biçimde,

Yaşıyor, Önder Atatürk kalplerde,

Unutulmayacak o Atalarda', 'Millet elele vererek Ya bağımsızlık! Ya ölüm dediler, Korkusuzca düşman üzerine yürüdüler, Bağımsızlığa, Cumhuriyet koştular 29 Ekim 1923’de...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cumhuriyet-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mizan', 'mizan-arafat-arik-wx4so', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün battı,ufkumu kapladı hüzün,

Ardından fırtına tufan vaktidir.

Tez bitti gülşeni,keyfi gündüzün,

Gönül mevsiminde hazan vaktidir.

Gözümü kapatsam içimden bir ses,

''Düşünü kurduğun dünyalar heves! '',

Ey sefil irade,aldığın nefes,

Düştüğün abesin mizan vaktidir.

Kalbinin üstünde bir sinsi hançer,

Sükutun nabzından çığlığı içer,

Vardığın her yerden öteye kaçar,

İçinin dışından aman vaktidir...', 'Gün battı,ufkumu kapladı hüzün, Ardından fırtına tufan vaktidir. Tez bitti gülşeni,keyfi gündüzün, Gönül mevsiminde hazan vaktidir. Gözümü k...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mizan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Kasım Sabahı', 'on-kasim-sabahi-aysel-celik-ck7ij', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masmavi deniz ve gök karardı,

Yemyeşil ormanlar sarardı,

Çağlayan ırmaklar duruldu,

Atam! Atam öldü diye.

Buğulu gözlerden akan yaşlar sellercesine,

Şu kaç göz yaşı binlercesine,

Eller açık dualarla,

Atam! Atam öldü diye.

Ocaklardan tüten neşe dumanı,

Bir anda üzüntüye dönüştü.

Müzikli çocuk cıvıltıları,

Bir anda çığlığa dönüştü.

Atam! Atam öldü diye.

Şimdi unutulmadı o büyük Atatürk,

Anılıyor her On Kasım da umutlarla,

Ağlamıyoruz, seviniyoruz bıraktıklarına,

Yaşa ölmez Atatürk’üm yaşa', 'Masmavi deniz ve gök karardı, Yemyeşil ormanlar sarardı, Çağlayan ırmaklar duruldu, Atam! Atam öldü diye. Buğulu gözlerden akan yaşlar selle...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/on-kasim-sabahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablo!', 'tablo-enes-ates-lqa9x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatlar çalıntı ruhlar ganimet

Bir devrin korkulu isyanıyız biz

Yanlış varken doğru ne büyük nimet

Hakk''ın koltuğunda bir sanığız biz.

Sokaklarda yürek pazarlanıyor

Fahişe suratlar her tarafta iz! 

Artık adalet de yargılanıyor

Pencerede gördük! , dost tanığız biz...', 'Hayatlar çalıntı ruhlar ganimet Bir devrin korkulu isyanıyız biz Yanlış varken doğru ne büyük nimet Hakk''ın koltuğunda bir sanığız biz. Soka...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tablo-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-arafat-arik-a681f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretin bozkırında gönlüm bir yaralı kuş,

Sen vuslat gülşeninde hergün bin kez varoluş...

Sensiz bütün iklimler,mevsimlerde karakış,

Sen gözümü yumunca, düşlerimdeki nakış...

İçimde bir ukde var kalpten kalbe bir akış,

Sen yeşil tabiata,mavi denize bakış...', 'Hasretin bozkırında gönlüm bir yaralı kuş, Sen vuslat gülşeninde hergün bin kez varoluş... Sensiz bütün iklimler,mevsimlerde karakış, Sen gö...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-607-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlayalım Sevgilerle', 'baslayalim-sevgilerle-aysel-celik-bchh7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden beri süren bu savaşlar,

Durmalı! Durmalı! 

Başlamalı en büyük sevgiler

En büyük arkadaşlıklar, dostluklar.

Göremiyorum! Gösterin bana,

Hani o tebessümlü gülen çocuklar? 

Göremiyor! Nerede o gonca güller? 

Dediğiniz güller; toplar, tüfekler, füzeler mi? ...

Başlamalı! Başlamalı! Sevgiler,

Donatılmalı parklara o çocuklar, 

Bitsin artık kinler, nefretler, 

Kurulsun yemyeşil kırlarda o dostluklar

Değer mi? Onca savaş, onca insan? 

Sevgiyle yok edilmeli onca düşman,

Donatalım dünyayı beyaz, kırmızı, pembe güllerle,

Gülelim o güzel gülüşlerimizle.

Çağırıyoruz tüm insanları Sevgiye! Sevgiye! 

Birleşsin tüm insanlar Yunus Emre’de

Yeni bir ışık doğuyor sevgi ışığı,

Başlasın! Başlasın tüm sevgiler', 'Eskiden beri süren bu savaşlar, Durmalı! Durmalı!  Başlamalı en büyük sevgiler En büyük arkadaşlıklar, dostluklar. Göremiyorum! Gösterin ban...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baslayalim-sevgilerle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayseri', 'kayseri-arafat-arik-uppzt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Marifet Kayseri''de değil senin özünde,

Mekan kanatlanır da uçar şair sözünde,

Yıllardır mahremimde sakladığım yüzünde,

Zemheri inadına,açan filiz görürüm...

Tutkuyla bağlanılan şehrin yakan narına,

Ve bu narın kor eden,yürekteki harına,

Hatıra kalan diye senden, bergüzarına,

Bakıp bakıp yanar da yine sensiz görürüm

Not:Bu şiir can dostum Mustafa GÖKGÖZ''ün Kayseri-1 adlı

       şiirine ithafen yazılmıştır.', 'Marifet Kayseri''de değil senin özünde, Mekan kanatlanır da uçar şair sözünde, Yıllardır mahremimde sakladığım yüzünde, Zemheri inadına,açan ...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kayseri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Olsun', 'bahar-olsun-arafat-arik-y55a6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar varki sensiz,yanan bu yürek,

Bir umut yeşert de can bahar olsun.

Yangınlar kavurur vuslatına dek,

Sunduğun yıl değil asırlar olsun.

Sabırla bekledim senle baharı,

Karanlık gecenin sensin seheri,

Gülüşün cemredir,gözün güheri,

Vuslatın ufukta gülen yar olsun...', 'Yıllar varki sensiz,yanan bu yürek, Bir umut yeşert de can bahar olsun. Yangınlar kavurur vuslatına dek, Sunduğun yıl değil asırlar olsun. S...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Aşk', 'umutsuz-ask-arafat-arik-0jmnq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yangın ki yüreğim birazcık sevgiye aç, 

Uzaktan olsa bile,bir tebessümün ilaç,

Seni mihrab eyledim,umutsuz aşkıma taç,

Bir ihtimal farzedip,daldığım düşler güzel..

Bir yaprak daha düşsün sararan ömrümüzden,

Kopup gitti birşeyler divane gönlümüzden,

Akan kan mı yaş mıdır -kahırla- gözümüzden,

Hicran,hüsran son bulsun ne olursun artık gel! ...', 'Bir yangın ki yüreğim birazcık sevgiye aç,  Uzaktan olsa bile,bir tebessümün ilaç, Seni mihrab eyledim,umutsuz aşkıma taç, Bir ihtimal farze...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umutsuz-ask-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-arafat-arik-b7sbz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nabzında atardım hani bir zaman,

Şimdi bir hayale daldı gözlerin.

Sende sensiz olmak ölümden yaman,

İçimde bir ukde kaldı gözlerin..

Ufuk çizgisiydi bana yol açan,

Bir adım yaklaşsam,bin arşın kaçan,

Önce yıldız oldu gülücük saçan,

Sonra güneşimi çaldı gözlerin..

Bir yol bulmalıydım,öteye nerden? 

Haber vermeliydi,ebedden,BİR''den,

Üstüme ok çekti baktığın yerden,

Avladı,derinden deldi gözlerin...

Sende miydi sırrı,ötenin rengi,

Bir bakışın mıydı,onun ahengi,

Fezada en parlak yıldızken dengi,

Ne yazık gözümde soldu gözlerin...', 'Nabzında atardım hani bir zaman, Şimdi bir hayale daldı gözlerin. Sende sensiz olmak ölümden yaman, İçimde bir ukde kaldı gözlerin.. Ufuk çi...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Ve Yeis', 'yagmur-ve-yeis-arafat-arik-ha2i5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurun zerreleri,hükmederken ruhuna,

Bir hüzün fırtınası,talan eyler hisleri,

Meyledip kahrolursan duygunun güruhuna,

Yüreğinin en tenha yerinde akisleri...

Her adımda bir girdap alır götürür seni,

Taşırsın sırılsıklam,acizane bedeni,

Çağırsan geri gelmez,bırakıp ta gideni,

Artık bir tek hal vardır,hasretin yeisleri...', 'Yağmurun zerreleri,hükmederken ruhuna, Bir hüzün fırtınası,talan eyler hisleri, Meyledip kahrolursan duygunun güruhuna, Yüreğinin en tenha y...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-ve-yeis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyada Yalnızlık', 'ruyada-yalnizlik-aysel-celik-0joke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitmek istemiyordu o muazzam eve,

Her yerde soluk, donuk hayaller,

Birkaç parça büyük anılar,

Yalnızdı, tek başına kalmıştı dünyada.

İçinde bir kıpırtı, bir heyecan vardı,

Yüzünde bir tebessüm bir gülüş vardı.

Ellerinde işlek, ayakları adımla,

Gönlü değil, ayakları gidiyordu.

Sokaklar arasında sinsi sinsi bir hava, 

Onu çekiyordu, büyük hayal yana,

Gitmek istemiyordu, gözü gönlü ondan yana

Yalnızdı, tek kalmıştı nerede? Hangi yana? 

O anda bir daldı hayaller alemine,

Mahsun gözlerini açtı baktı yalemu,

Yüzünde bir tebessüm bir gülüş,

Buğulu gözlerle baktı görüş, görüş.

Gözlerinde yansılanma hayal mi, gerçek mi? 

Etrafına bir baktı onu seven dostlar mı? 

Anladı, bir rüya bir yalnızlık,

Doluydu, gönlü gözü bir aralık.', 'Gitmek istemiyordu o muazzam eve, Her yerde soluk, donuk hayaller, Birkaç parça büyük anılar, Yalnızdı, tek başına kalmıştı dünyada. İçinde ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruyada-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Git ki', 'oyle-bir-git-ki-arafat-arik-i34dc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Git, hem öyle bir git ki; geri dönüş olmasın,

Bende seni hatırlar, anlatır iz kalmasın.

Gidişin olmalı ki; sanki başka âleme,

Yokluğun dolmalı hem yıkık gönül haleme.

Seni tanımayanlar, yine gözde saysınlar,

Yine gönül gönüle, yine sözde saysınlar.

Hercai arı oldun, meyhane çiçeklerde,

Sır’rı aradın durdun, cümbüş dolu renklerde,

Sen; arsız misafiri, girilmez gönüllerin,

Sen; kokusuna hasret, koku saçmaz güllerin.

Sen; uslanmaz varisi, kapı tutmaz hanların, 

Sen; sırtında ağır yük, iflah olmaz canların.

Sen; çölde kısır ağaç, dalında çiçek açmaz,

Sen; içinde yanamaz, dışına ışık saçmaz.

Sen; kuytusunda boran, rüzgâr esmez limanın,

Sen; kapkara bulutu, yanmaz, tütmez dumanın.

Sen; mecburundan kaçak, efsununda meçhulün,

Hem enkazını götür, bende kalmasın külün.

Haydi git tufanınla… ufukta batar gibi,

Bütün yaşananları, bir pula satar gibi…', 'Git, hem öyle bir git ki; geri dönüş olmasın, Bende seni hatırlar, anlatır iz kalmasın. Gidişin olmalı ki; sanki başka âleme, Yokluğun dolma...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyle-bir-git-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annenin Ninnilerinde', 'annenin-ninnilerinde-aysel-celik-iaacm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Er elde, gurbet yolda

Düşmanla vatan uğrunda

Şaha, şaha yarım durumda

Bütünlenir annenin ninnileriyle

Yankılanır! Yayılır billur sesler

Dağlara çarpan coşku sarar sesler

Çocukta sevinç, büyük şenler

Bütünlenir annenin ninnileriyle

Yıllar akar çağlayan ırmaklar durulur

Düğün şenlik olur, asker elde durulur

Solgun çiçekler hep birden yeşerir

Bütünlenir annenin ninnileriyle

Şimdi ne o billur sesli anne

Ne de çağlayan ninniler

Çocuklar doğma, Avrupa misali

Parçalandı! Annenin ninnileri.', 'Er elde, gurbet yolda Düşmanla vatan uğrunda Şaha, şaha yarım durumda Bütünlenir annenin ninnileriyle Yankılanır! Yayılır billur sesler Dağl...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annenin-ninnilerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Denir', 'ne-denir-arafat-arik-0h40e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nesebi bellisiz,fitne yumağı,

Kalbi katılaşmış,bozuk dimağı,

Gözüne soksan da ışıktan ağı,

Karaya tutulmuş zul’e ne denir? 

Kahrından,kibrinden gökler kaçışır,

Nifirsiz yüzünden, kuşlar uçuşur,

Emeğe göz diker,yanar tutuşur,

Vurguna katılmış ele ne denir? 

Düşlerinde kıtlık görür durmadan,

Efradına zarar verir durmadan,

Ervahında fire yoktur kırmadan,

Soyundan satılmış yola ne denir? 

Teskini kanları emmekte sayar,

Yağmurun yağdığı tarlaya kayar,

Namussuzluğunda yirmi dört ayar,

Haramdan çatılmış kula ne denir? ...', 'Nesebi bellisiz,fitne yumağı, Kalbi katılaşmış,bozuk dimağı, Gözüne soksan da ışıktan ağı, Karaya tutulmuş zul’e ne denir?  Kahrından,kibrin...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-denir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyada Doğa', 'ruyada-doga-aysel-celik-mcmbc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O buğulu gözleri birden kapandı

Geçmişten bir kapı açıldı

Yeşillikler saçan bir dünya

Masmavi deniziyle

Billur gibi akan ırmaklarıyla

Bembeyaz Pamukkale’siyle

Ne hoş insanlarıyla

Yeşil bir dünya saçıldı

Kol kola giren bozkır dağları

Birbiri ile koşuşan hayvanları

Mahsun güleç yüzlü çocuklarıyla

Yeşil bir dünya saçıldı

Mis gibi kokan havasıyla

Verimli topraklarıyla

Şifalı tatlı sularıyla

Yeşil bir dünya saçıldı

Mutluluk üreten fabrikası

Barış dolu ülkesi

Hayat veren ormanıyla

Yeşil bir dünya saçıldı

Rüyasında gören çocuk

Tebessümle güldü

Buğulu gözlerini yavaşça açarak

Keşke! Diye bağırdı', 'O buğulu gözleri birden kapandı Geçmişten bir kapı açıldı Yeşillikler saçan bir dünya Masmavi deniziyle Billur gibi akan ırmaklarıyla Bembey...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruyada-doga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-aysel-celik-9clkd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Huzurdur sevinçtir

Bayram güzeldir

Kuşun cıvıltısı

Çocuğun şarkısıdır

Biçare yetimin

Gözü yaşlı ananın

Köşede kalmış gazinin

Biçare sevincidir

Fakirin fukaranın

Gönlü sevinç dolanın

Mahsun çocukların

Biçare bayramıdır

Zulüm görenin

Huzur bulmayanın

Acı çekenin

Biçare bayramıdır

Bayram güzeldir

Sevinçle doludur

Biçare mahsundur

Bayram sevenindir', 'Huzurdur sevinçtir Bayram güzeldir Kuşun cıvıltısı Çocuğun şarkısıdır Biçare yetimin Gözü yaşlı ananın Köşede kalmış gazinin Biçare sevincid...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bayram-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2000''E 5 Kala', '2000-e-5-kala-aysel-celik-pvce2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamansız bir deryada uçuyorum

Dur! Diyecek yok mu? 

Hangi çağda yaşıyorum

Bunu bilecek yok mu? 

Kan gövdeyi götürmüş

Sefilim, ben de sefaletim

Çağdaş denen artıklarla yaşıyorum da yaşıyorum

Gurur, şeref, haysiyet kalmamış

Kim kime, dum duma dünyası

Ahlâksızlık başını almış

Hani nerde insan sevgisi

Değil sevmek, yok bile köpek kadar değeri

Bilmem ne haldeyim

Söyleyen yok mu

Bir yığın kadar tepe insan ölüsü

Beride gülüşen oynayan bir halkalısı

Kimi güler,kimi ağlar

İşte ya kıyamet bundan kopar

Kendileri öldürür öldürürler

Biz de “höst” biraz öte desek

Başımıza çorap sararlar

Desene ölüyoruz

Müslümanım Türk’üm diyen yok mu? 

Hadi artık tarihimizi

Yıkın öldürün kendinizi

Bir tarihte siz yazın

Siz geçmişten ders almadınız da

Gelecek sizden mi alacak? 

Medeniyet dediniz ardına takıldınız

Hadi oturup tarihi siz yazın

Buraya kadar, siz paydos etmezseniz

Sevgi, mutluluk paydos edecek

Siz daha viran yüce dağları yıkarsanız

Barış kalmayacak

Üzüntü, acı, keder

Şu garip bi çare ananın gözyaşı

Ne zaman, ne zaman dinecek

Söyleyen yok mu?', 'Zamansız bir deryada uçuyorum Dur! Diyecek yok mu?  Hangi çağda yaşıyorum Bunu bilecek yok mu?  Kan gövdeyi götürmüş Sefilim, ben de sefalet...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/2000-e-5-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaşız', 'gardasiz-aysel-celik-fll27', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun uzun oluk

Sevda bir soluk

Geçiyor ömür bak

Hani nerde telli duvak

Seni sana emanet etmiştim

Kalbime hayalin gömmüştüm

Bir ömür seni sevmiştim

Emanetime hıyanet etmişsin

Allah’ım dayanamaz

Bu acıya kalbim

Artık sana sevdiğim

Diyemez gönlüm

Bundan böyle Allah huzurunda

Gardaşız

Gardaşız

Gardaşız

Bacım', 'Uzun uzun oluk Sevda bir soluk Geçiyor ömür bak Hani nerde telli duvak Seni sana emanet etmiştim Kalbime hayalin gömmüştüm Bir ömür seni sev...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gardasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız Her Şey', 'anlamsiz-her-sey-muslum-firat-yasar-ncwu3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazmak isterim

İçimde mırıldanasın

Aklımda olasın,

Hayalimdeki kapıyı çalasın,

Hiç çıkmayasın ikisinden de

İşte o an; 

Ozanlar türkü söylemeli,

Mecnunlar tekrar dirilmeli.

İşte o an; 

En güzel kızları öpmek isterdim

Aklımdaki sen, hayalimdeki sen 

İşte o andan sonra; 

Güneşe uzanalım sen ve ben...', 'Bir şiir yazmak isterim İçimde mırıldanasın Aklımda olasın, Hayalimdeki kapıyı çalasın, Hiç çıkmayasın ikisinden de İşte o an;  Ozanlar türk...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Fırat Yaşar']::text[], 8.5, '{"poet":"Müslüm Fırat Yaşar","poet_slug":"muslum-firat-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlamsiz-her-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-aysel-celik-gobrv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey! Benim tarihim

Tarihimde yaşayan Fatihim! 

Ey! Benim Atam

Geleceğime yol gösteren talihim

Sana bunları kim öğretti Türküm! 

Nur yüzlü öğretmenim

Bahtım ne kara açılmadı

Vurdum yıktım anlayan olmadı

Ne ana ne baba hiç biri kalmadı

Taa uzakta bir ışık vardı

Işık değildi ufkumun kızılıydı

Öğretmenimin beni saran kollarıydı

Bu çocuk ki tarihimi değiştirecek

Öğretmen a, b, c yi öğretecek

Sana ilk ruhunu verecek

Bu genç ki yaşatacak

Din, millet, aile, sevgi anlayacak

Bunları veren öğretmene selam duracak

Ağlayan gözlerimde buğulanan ruhumda

Bana yol gösteren umudumda

Hani nerede? Her zaman orada

Çöken yok olan yurdumda

Beni dirilten, yontan, değiştiren sonunda

Beni saran aklı, zekası, kalemi var da

Nur yüzlü öğretmenim', 'Ey! Benim tarihim Tarihimde yaşayan Fatihim!  Ey! Benim Atam Geleceğime yol gösteren talihim Sana bunları kim öğretti Türküm!  Nur yüzlü öğr...', ARRAY['Türk Edebiyatı','Şiir','Aysel Çelik']::text[], 8.5, '{"poet":"Aysel Çelik","poet_slug":"aysel-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ogretmenim-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-muslum-firat-yasar-yd9zs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşayamıyorsan namusunla,

Sahiplenemiyorsan haysiyetine,

Uslan ulan uslan,

Diyar benimdir...', 'Yaşayamıyorsan namusunla, Sahiplenemiyorsan haysiyetine, Uslan ulan uslan, Diyar benimdir......', ARRAY['Türk Edebiyatı','Şiir','Müslüm Fırat Yaşar']::text[], 8.5, '{"poet":"Müslüm Fırat Yaşar","poet_slug":"muslum-firat-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasamak-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştükçe BÜYÜYORUM...!', 'dustukce-buyuyorum-dilek-egri-qgxnk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başatan ayağa aşktan ibaretim...

dualarım şiirlerimde

sitemlerim beddualarımda

ve 

kıyamayıp geri aldığım 

tövbelerimde isyanlarım...! 

ne bir son

ne bir başlangıç..

bakışlarınla kavrulup gidiyorum işte..

bronzluk yakışır bana

birde utanırsam  sözlerinden

seversin yanaklarımdaki çilek rengini...

kalıplardan sıkıldım artık

yüreğimin hacmi büyük

duygularıma sığmıyor

hüznüme rest çekiyorum..! 

yaşıyorsam aşkımı

aşıksam

tutmayın beni..! 

kartopu gibiyim şimdi

.......d

.........ü

...........ş

.............t 

..............ü

................k

..................ç

....................e

.........................M       

......................U

...................R

................O

..............y

..........ü

.......y

....ü

.b', 'Başatan ayağa aşktan ibaretim... dualarım şiirlerimde sitemlerim beddualarımda ve  kıyamayıp geri aldığım  tövbelerimde isyanlarım...!  ne b...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dustukce-buyuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-bahri-yildirim-iun6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte,gidiyorum

Hoşcakal! 

Sandığın gibi değil ama

Yine de kaçıyorum senden

Ağlama sakın arkamdan

Başka çare bırakmadın ki bana

Sensizliklleri koydun önüme

Sensizlikleri yazmaya başladı kalemim

En güzel duygularımın kanına girdin

Belkide gerçekten sevemedin beni

 Bu yüzden:

Ağlamaya bile hakkın yok arkamdan

Ben hiç sevmem 

Böyle timsah göz yaşlarını

Ben de dökmem.

Bunu önceden düşünecektin

Sakın yalvarma dön diye

Dönüşüm yok artık sana

Boşuna yorma kendini

Boşuna diller dökme

O treni çoktan kaçırdın

Sen: 

Gözyaşlarını

Başka bir ayrılığına sakla.', 'İşte,gidiyorum Hoşcakal!  Sandığın gibi değil ama Yine de kaçıyorum senden Ağlama sakın arkamdan Başka çare bırakmadın ki bana Sensizlikller...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglama-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıyamadan', 'taniyamadan-muslum-firat-yasar-68hoy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanımadığım çiçeği koklamak isterdim

Tanımadığım kokuyu hissetmek

Tanımadığım bir kızı sevmek

Tanımadığım o çiçeği, o kıza vermek

Ve,kendime hayatla uğraşımı sormak

Bazen yargılıyorum

Suçluyorum kendi kendimi

Sessizliğin loşu bunaltıyorken

Sesi duymak isteken

Biliyor musunuz kendimi tanıyamadan:

Hiç bilmediğimi

Şiirler okumak istiyorken,

Eşkiya olmak istiyorken,

Yumruğumu göğe kaldırmak istiyorken

Sevmek ve sevilmek istiyorken

Tanıyamadıklarını görmek istiyorken

Ne güzeldir hayat tanır iken.', 'Tanımadığım çiçeği koklamak isterdim Tanımadığım kokuyu hissetmek Tanımadığım bir kızı sevmek Tanımadığım o çiçeği, o kıza vermek Ve,kendime...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Fırat Yaşar']::text[], 8.5, '{"poet":"Müslüm Fırat Yaşar","poet_slug":"muslum-firat-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/taniyamadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazide kaldi', 'mazide-kaldi-husamettin-guven-hyg0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birzamnlar cok mutluyduk     

Yarinlardan umutluyduk

Kader buymus razi olduk

Mutlu olmak mazzide kaldi

Icin icin agliyormus

Karalari bagliyormus

Bence buna sebep oymus

Mutlu olmak mazide kaldi

Bende sandim tapar bana

Gulmek gayri haram sana

Var git baba ocagina

Mutlu olmak mazide kaldi', 'Birzamnlar cok mutluyduk      Yarinlardan umutluyduk Kader buymus razi olduk Mutlu olmak mazzide kaldi Icin icin agliyormus Karalari bagliyo...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mazide-kaldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediklerim', 'ozlediklerim-muslum-firat-yasar-xucfm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay ışığı var ama görünmüyor gözlerime. 

Gölgem kağıtıma vuruyor,

Kalemim gibi.

Sonra kalemim ise düşüncelerimi okşuyor:derinden

Derindeki düşüncelerimin adı özlediklerim

Özledim anne yaşamayı

Ve sonra,

Özlediklerimle ölmeyi.

Ay ışığı var ama görünmüyor gözlerime.', 'Ay ışığı var ama görünmüyor gözlerime.  Gölgem kağıtıma vuruyor, Kalemim gibi. Sonra kalemim ise düşüncelerimi okşuyor:derinden Derindeki dü...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Fırat Yaşar']::text[], 8.5, '{"poet":"Müslüm Fırat Yaşar","poet_slug":"muslum-firat-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozlediklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram olsun', 'haram-olsun-husamettin-guven-74xxj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben istedim yalniz sevmek

Mutlu ve mesut etmek

Kem gozlerden geri cekmak

Sana sevgim haram olsun

Istemedim kalbin kirmak

Sana bir fiske bile vurmak

Tek  dilegimmutlu yapmak

Mutluluklar haram olsun

Anlat senin nedir derdin

Sana buyuk sevgi verdim

Ondan ote kalbi verdim

Sana kalbim haram olsun

Her an icin aklimdasin

Beni sevmeyen utansin

Zaten  senbir ruhsuz malsin

Ruhum sana haram olsun', 'Ben istedim yalniz sevmek Mutlu ve mesut etmek Kem gozlerden geri cekmak Sana sevgim haram olsun Istemedim kalbin kirmak Sana bir fiske bile...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haram-olsun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-muslum-firat-yasar-rqp51', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın serinliği içime dolarken,

Sensizlik yine içimde tutsak.

Bir bağırabilsem,

Bir anlatabilsem,

Seni

Seni şu kahrolası kızlara

Haldan düşmüş fahişelere

Ve lanet olası boş sokaklara.', 'Sabahın serinliği içime dolarken, Sensizlik yine içimde tutsak. Bir bağırabilsem, Bir anlatabilsem, Seni Seni şu kahrolası kızlara Haldan dü...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Fırat Yaşar']::text[], 8.5, '{"poet":"Müslüm Fırat Yaşar","poet_slug":"muslum-firat-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olursem sebebim odur', 'olursem-sebebim-odur-husamettin-guven-ijk0v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalan dunyam zindan oldu

saclarima aklar doldu

sakin sorman neler oldu

olursem sebebim odur

daliyorum hep derine

soyleyemem kimselere

atiyorum ben icime 

olursem sebebim odur

kanser bile hafif kalir

bu dert bana agir gelir

bir gun gelir kalbim durur

olursem sebebim odur

eger birgun olur isem

musallah tasina konursam

kara topraga gomulursem

olursem sebebim odur', 'yalan dunyam zindan oldu saclarima aklar doldu sakin sorman neler oldu olursem sebebim odur daliyorum hep derine soyleyemem kimselere atiyor...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olursem-sebebim-odur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni S-e-v-m-i-y-o-r-u-m', 'seni-s-e-v-m-i-y-o-r-u-m-arzu-gulucudur-xzxrl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kabarmış duygularım var benim....

Beş para etmez hayallerim

Adınla başlayan devrik cümleler...

Torbada birikmiş düş kırıkları saklıyorum

Senden hatıra....

Birde adını söyleyemediğim şarkılar besteliyorum 

Ruhuna...

Şerfine kadeh kadırmıyorum belki ama

Sen yinede unutulduğunu.....UNUTMA....

Kor ateşte yanan resimlerin  bende...

Yok oluşunun adıdır yanan herbir kare

Sisleri ruhumun aydınlığı...

Herbir yanış gönlümün bayramı

Zafer benim....

Şan benim....

Hatrına çalıyor davullar

Kaçışına karışıyor herbir hece

Harf harf yazıyorum

G-İ-D-İ-Ş-İ-N-İ

Ve bir solukta söylüyorum

S-E-N-İ S-E-V-M-İ-Y-O-R-Y-U-M', 'Kabarmış duygularım var benim.... Beş para etmez hayallerim Adınla başlayan devrik cümleler... Torbada birikmiş düş kırıkları saklıyorum Sen...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-s-e-v-m-i-y-o-r-u-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olurum ben ondan iyi', 'olurum-ben-ondan-iyi-husamettin-guven-a07qs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'serefsiz dedirteceksem

dusmanlari gudureceksam

toplum  disi edileceksem

olurum ben ondan iyi

anlima leke sureceksem

utanarak gezeceksem

sevenleri uzeceksem

olurum ben ondan iyi

haysiyetsiz yasayacaksam

pis lekeyi tasiyacaksam

essiz, dostsuz  kalacaksam

olurum ben ondan iyi', 'serefsiz dedirteceksem dusmanlari gudureceksam toplum  disi edileceksem olurum ben ondan iyi anlima leke sureceksem utanarak gezeceksem seve...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olurum-ben-ondan-iyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanetin uc kursun var', 'emanetin-uc-kursun-var-husamettin-guven-bco5c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'baska birsey dusunemem

yemin ettim ben donenmem

oldurmeden ben olemem

emanetin uc kursun var

tam bes oldu bulamadim

zannetmeki unutmadim

geliyorum ben adim adim

emanetin uc kursun var

yaptigin yanina kalmaz

sen olmeden rahat olmaz

sanma sakin beni vuramaz

emanetin uc kursun var', 'baska birsey dusunemem yemin ettim ben donenmem oldurmeden ben olemem emanetin uc kursun var tam bes oldu bulamadim zannetmeki unutmadim gel...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/emanetin-uc-kursun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus-ma', 'sus-ma-bisar-ulutas-vem97', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedense susmayı öğütlerler

konuşmaktan acizler

Sen susma, anlat bana 

yüreğinin derinliklerinden kopan ne varsa

İksirine alışmalı hayatın

Kulaç atmayı öğrenmelisin

ve yüzmeyi

aşkın soluk kesen sularında

Anlatmalısın, bana

seni sevene,

kimi sevdiğini…

Benim 

yüreğine yandığım

çok mu önemli?', 'Nedense susmayı öğütlerler konuşmaktan acizler Sen susma, anlat bana  yüreğinin derinliklerinden kopan ne varsa İksirine alışmalı hayatın Ku...', ARRAY['Türk Edebiyatı','Şiir','Bişar Ulutaş']::text[], 8.5, '{"poet":"Bişar Ulutaş","poet_slug":"bisar-ulutas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sus-ma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendinle Hesaplaşma', 'kendinle-hesaplasma-hikmet-feridun-demir-7li5j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pazarlıkla gelmedin dünyaya

Kendin inandın kendin ikilemdesin..

Suclu aradın olup bitene yada sorumlu..

Şükret yaratıldığına, dön kendine...

Kendinle bağışık olmayı öğren...

Görünmeye çalıştığın kadar olumlu değilsin...

O seviyeye daha çok uzaktasın, irtifa farkı çok...

İnanmıyormusun bütün bunlara! ! ! 

Git o zaman kimsenin olmadığı bir mekana…

Tüm yaşamını sorgula,

Kendini  kendine sor....

Kendini sorgula.

kendini yargıla,

kendi yargıcın ol...

Ulaştığın Sonuç, 

işte o SEN sin..

Almanya/Köln 

Not: Lütfen kimse üzerine alınmasın, 

        bir özel kendinle hesaplaşma şiiri (2)', 'Pazarlıkla gelmedin dünyaya Kendin inandın kendin ikilemdesin.. Suclu aradın olup bitene yada sorumlu.. Şükret yaratıldığına, dön kendine......', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kendinle-hesaplasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak', 'sokak-aynur-sultan-0n1mg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kavga et benimle, 

sonra çık sokaklara. 

Yürürken bulduğun 

o tüm ıslak kaldırımlar 

akıttığım göz yaşları. 

Topla hepsini tek tek

senin onlar', 'Kavga et benimle,  sonra çık sokaklara.  Yürürken bulduğun  o tüm ıslak kaldırımlar  akıttığım göz yaşları.  Topla hepsini tek tek senin onl...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sokak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın!', 'kadin-aynur-sultan-kz8u3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey sen fırıtına kadını 

Öfken ve şiddetin ne zaman dinecek

bana karşı.

Ne olur biraz ara ver.

Bak şu küçük fidanlar

nasılda secdeye durmuş.

insafa gel artık', 'Hey sen fırıtına kadını  Öfken ve şiddetin ne zaman dinecek bana karşı. Ne olur biraz ara ver. Bak şu küçük fidanlar nasılda secdeye durmuş....', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kadin-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti', 'bitti-esma-ozdemir-zutmb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir yürek atımı mesafede

yaşayan ey sevgili! 

iki dudak arası yola

git gülüşümle de

gel, sağlık ile! 

kaptırma gönlünü

akreple yelkovanın 

aldanıp da dans edişine

bir daha bana deme

tik-tak, tik-tak; Aşkım

pilimiz bitti!', 'bir yürek atımı mesafede yaşayan ey sevgili!  iki dudak arası yola git gülüşümle de gel, sağlık ile!  kaptırma gönlünü akreple yelkovanın  a...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bitti-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-gulseren-onay-xvhho', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I 

Asya’dadır bir kolum, 

Diğeri Avrupa’da. 

Nice kültürler yaşattım bağrımda 

Ben Anadoluyum.. 

Anayım ben 

Memeleri süt dolu 

Kybeleyim Frigya’da 

Artemis olurum 

Lidya’da Pamphilya’da… 

Adaklar sunulur, 

Düğün dernek kurulur 

Bereketim adına … 

Olympos’da 

Zeus,Apollo, Hera 

Savaş meydanlarında Athena 

Benim çocuklarım 

Ben tanrıların anası Anadolu 

Anayım ben dolu dolu 

II 

Efsaneler yazıldı adıma 

Elimde bir testi su 

Dolaşırken bozkırda, 

Bir ordu çıktı karşıma 

Hepsi bir civan, 

Birbirinden kahraman 

Akıyordu Ege’ye gürül gürül 

Asya’dan…. 

Hava sıcak 

Yiğitler aç ve susuz 

Yürümüşler günlerce uykusuz 

Görünce beni dediler; 

Ana su, bir yudum su 

Tek bir yudum… 

O anda 

Oluk oldu testim 

Başladı çağlamaya…. 

İçti yiğitler kana kana 

İçtikçe 

Doldur ana dediler 

Ana dolu dolu..

III 

Ben Anadoluyum 

Milyonlarca bebe doğuran 

Bir ana… 

Bereketlidir topraklarım 

Geçmişten bu güne 

Tarihi kucaklarım. 

Medeniyeti 

Beşiğimde sallayıp büyüttüm.. 

Nice oğullar yetiştirdim 

Her biri birer komutan 

Her biri sınırlarımda bir nefer… 

Nice canlar yetiştirdim 

Yunus, Mevlana 

Hacı Bektaş olup 

Sevginin sırrına erdiler 

Aşıklar sazlarda okudu 

Gelinlik kızlar 

Çeyizlerde dokudu beni 

Analarım bebelerine 

Beni anlatan ninniler yaktılar 

Ben Anadoluyum 

Anayım ben dolu dolu 

Ben Anadolu….', 'I  Asya’dadır bir kolum,  Diğeri Avrupa’da.  Nice kültürler yaşattım bağrımda  Ben Anadoluyum..  Anayım ben  Memeleri süt dolu  Kybeleyim Fr...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/anadolu-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şafak bin eziyet', 'bir-safak-bin-eziyet-gokhan-dilsiz-wal1d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yine şafak doğuyor...

yine kıramadık zincirlerimizi

bağıra, bağıra kusamadık...

içimizdeki nefreti

yüzlerce insan siraya dizilmiş 

kendilerine sövdürmek için

yüzüne sövemessin, cezası büyük 

ardından sövemessin yüreyin delikanlı

hep yüreyine atarsın...

hep yüreyine atarsın...

gün gelir yürek dolar

ve işte ozaman isyan başlar.', 'yine şafak doğuyor... yine kıramadık zincirlerimizi bağıra, bağıra kusamadık... içimizdeki nefreti yüzlerce insan siraya dizilmiş  kendileri...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Dilsiz']::text[], 8.5, '{"poet":"Gökhan Dilsiz","poet_slug":"gokhan-dilsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-safak-bin-eziyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Hoşçakal de', 'bana-hoscakal-de-ebru-temizkan-d8e5e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana hoşça kal de

Güneş kızıllığını almış 

Denize doğru güne veda ya hazırlanırken

Yüzüme bak ama

Gözlerinin buğusunu sil 

Işıldamalı gözlerin 

Titrese de dudakların ki gülmeli her daim

gözlerime bak ve söyle

Meltemin o saçlarını hafif hafif dalgalandırmasına aldırma

Bak yaz bitiyor artık hazan zamanı 

Yapraklar dallara veda etmeye başlamış…

Bana hoş çakal de 

Geceye doğru ilerlerken zaman

Yıldızları gökyüzünde

Seni sende bırakıyorum 

Ayaklarım külçeleşmiş

Gözlerimi senden ayıramıyorum

Yüreğim sersem 

Yüzüne düşen perçemi kulağının arkasına alırken 

Kulağına yavaşça fısıldıyorum

“hadi, bana hoş çakal de”

Ebru Temizkan

28.07.2005', 'Bana hoşça kal de Güneş kızıllığını almış  Denize doğru güne veda ya hazırlanırken Yüzüme bak ama Gözlerinin buğusunu sil  Işıldamalı gözler...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bana-hoscakal-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Gözler', 'umutsuz-gozler-ebru-temizkan-49jzd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutsuz gözlerle bakmıştın giderken arkana

Sevdanı yanına alarak

Niçindi bu ayrılık acısını çektirmen bilmem ikimize de 

Buğulu gözlerindeki keder bunca yıl geçse de çıkmıyor aklımdan

Bir sır mı vardı sakladığın yada bir günah mı bilinmez

Ama gel gör çıkmıyor aklımda o sarhoş adımlar 

Sen hep böyleydin 

Sevinsen de üzülsen de içmeden yalpalar

Bir oyana bir buyana sarhoşmuşçasına adımlar atardın

Mutluluğu seninle yaşamak o kadar kolay

Hüznü seninle paylaşmak bir o kadar zordu

İki birbirine kardeş duyguyu

Ancak seninle yaşayabilirdi insan

Sevincini Karun kadar zengin biri paylaşırken

Üzüntünü fakirin lokmasını sakınır gibi bencilce saklardın benden

Kim bilir belki tersi olsaydı 

O sarhoş adımlara gerek kalmazdı

Bazen yaşam acımasız  olabiliyor

Yıllar sonra bile içimde saklı bu duygular 

Önümden yürüyen her sarhoş adımlı da gelir aklıma

Galiba bir tek ben ayıramam 

Bir insanı gerçekten sarhoş mu yoksa duygusal mı diye...', 'Umutsuz gözlerle bakmıştın giderken arkana Sevdanı yanına alarak Niçindi bu ayrılık acısını çektirmen bilmem ikimize de  Buğulu gözlerindeki...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umutsuz-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidecekmiydin...', 'gidecekmiydin-aysel-ozguler-stlds', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir sonbahar tenhalıgında bırakıp gönlümü

çorak topraklar misali çiçeksiz dalsız 

ardında hiç sönmeyen bir ateş ve dinmeyen bir 

özlem bırakıp gidecekmiydin....

oy yuregı yaralım kaderi karalım

alıp elıne yokluklardan koca bır demet

ne yaşanmışsa kaderine razı

başın önünde yüregin kırık 

demeden bir tek of 

gidecekmiydin...', 'bir sonbahar tenhalıgında bırakıp gönlümü çorak topraklar misali çiçeksiz dalsız  ardında hiç sönmeyen bir ateş ve dinmeyen bir  özlem bırak...', ARRAY['Türk Edebiyatı','Şiir','Aysel Özgüler']::text[], 8.5, '{"poet":"Aysel Özgüler","poet_slug":"aysel-ozguler","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidecekmiydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yükmüdür?', 'sevda-yukmudur-ebru-temizkan-v6gry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derin bir nefes çektim sigaramdan 

Ve öylece baktım boşluğa doğru

Boşluk

Ne kadar benziyoruz birbirimize

Senin elinde de bir şey yok benim elimde de

Hayat 

Ne garip dimi 

O kadar karmaşanın arasında

Ve hatta onca derdin arasında

Yine de insan olduğumuzu hatırlatan

Şey sizce aşk mı? 

Öyle çok şey geliyor ki içimden

Kelimeler birleştiğinde anlamsız gelen

Baktığında ise hayatım olan

O kadar çok şey geliyor ki

Sadece benim değil bizim olan

Sevda yük müdür insana? 

Yada yük mü olmalı

Bilmiyorum…', 'Derin bir nefes çektim sigaramdan  Ve öylece baktım boşluğa doğru Boşluk Ne kadar benziyoruz birbirimize Senin elinde de bir şey yok benim e...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevda-yukmudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninim', 'seninim-ebru-temizkan-yzr1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprağıma düşmüş yağmur damlası gibisin

Ay ışıyordu gözlerinde

Kıraç toprağın üzerindeki çatlaklar

Engerek gibi kıvrılmıyor 

Seni içiyorum 

Artık seninim', 'Toprağıma düşmüş yağmur damlası gibisin Ay ışıyordu gözlerinde Kıraç toprağın üzerindeki çatlaklar Engerek gibi kıvrılmıyor  Seni içiyorum  ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seninim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiire İsim Bulamadım', 'siire-i-sim-bulamadim-ebru-temizkan-f605d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinden bir sevda akar yüreğime doğru

Bazen ılık rüzgarlar hissederim içimde

Beni hoş duygulara iten 

Bazen de soğuk rüzgarlar eser ürperirim

Korku kalpler her yanımı

Anlamsız

Gözlerin gözlerime değdiğinde bir sevgi akar yüreğime doğru

Ilık bir su gibi içimi yumuşatır

Mıyışırım tatlı bir tebessüm kaplar yüzümü

Birde buz gibi aktığı anlar vardır

O an çekilirim kabuğuma yaşlara boğulurum

İşte tüm bu zamanlarda anlarım sevgimizin büyüklüğünü.', 'Gözlerinden bir sevda akar yüreğime doğru Bazen ılık rüzgarlar hissederim içimde Beni hoş duygulara iten  Bazen de soğuk rüzgarlar eser ürpe...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siire-isim-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetsiz Misafir', 'davetsiz-misafir-esma-ozdemir-wi3c1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecelerimde çalmadan içeri girersin kapımı

Bu teklifsiz davranışlar eski günlerin bir alışkanlığı mı? 

Bütün bir gece düşüncelerimi işgal etmeye hakkın var mı

Yoksa, kendine acındıracak başka kimse bulamadın mı? 

Aç mısın, hasta mısın, çıplak mısın

Benden başka seni düşünecek kalmadı mı? 

Gülünce dudağımda, kızınca gözümün ucunda ne işin var

Öpücüklerimde, dokunuşumda, duygularımda

Aradığını hâla bulamadın mı? 

Neden çekip gitmiyorsun ait olduğun yere

Hatırlamalı mıyım sanki seni yeni birini her sevdiğimde? 

Oynamakla yorulmadın mı duygularımla? 

Benden başka üzeceğin kimse kalmadı mı

Koca dünyada!', 'Uykusuz gecelerimde çalmadan içeri girersin kapımı Bu teklifsiz davranışlar eski günlerin bir alışkanlığı mı?  Bütün bir gece düşüncelerimi ...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/davetsiz-misafir-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye..', 'sevgiliye-adem-tetik-9xsaq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Selam yoladım yar hüzünlere sensizlikle 

Hani ben yolları  sen ayrılıkları severdin ya

Düşündün mü.? neden sever insan sevdiğinden ayrılmayı

Oysa ki hiç bilmedin ben yoları seninle sevdim

Sensizlikle hep ezdim hep çiğnedim

Başımı kaldırıp bakmadım  bir defa

Mutluluk aramadım senden uzaklar 

Sen vardın ya nasılsa her an yanı başım da

Giderken bile öyle sevdim ağladığında

Depremler koptu yüreğimde

Ama yüreğim yanıyor yar canım yanıyor

Keşkeler dökülüyor dilimden ama olmuyor

Geri dönüş yok biliyorum zamanımız yok 

Sen kaybettiklerine yanarken benden uzaklarda

Bende burda sensizliklere ağlamaktayım yoruldum hayat yolun da

Hıçkırıklar takılda ya boğulmadım inat hayata', 'Selam yoladım yar hüzünlere sensizlikle  Hani ben yolları  sen ayrılıkları severdin ya Düşündün mü.? neden sever insan sevdiğinden ayrılmayı...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümü uzatan!', 'omrumu-uzatan-evren-dalgic-3lk1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yanda deli hasretin,

ne yana dönsem,

gerçekleşmeyen düşlerim bulur gözlerimi.

Sönmüş dalların,

soluk yüzlü yapraklarında; 

ismini yazılı bulurum,

ve son olur o bakışım

karşılıksız sonbaharına..

Yüreğimde takılısın,

kelepçesin düşlerime,

sensizlik ölüm,

zehirsin gülüşlerime.

Bir meleksin aslında,

yanımdan eksik olmayan,

ve aslında hiç yoksun,

yokluktan varolan...

Gecenin siyahısın,

kalemimin sitemi,

güneşin yanığısın,

acılarımın dermanı.

Sen yokluksun,

varlığının armağanı.

Bir pınar gibi taşkınsın,

bolluğun kuraklığı.

Sen cansın benim canımsın,

Farketmeden benim; 

ömrümü uzatansın..

(Ankara 2005)', 'Her yanda deli hasretin, ne yana dönsem, gerçekleşmeyen düşlerim bulur gözlerimi. Sönmüş dalların, soluk yüzlü yapraklarında;  ismini yazılı...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/omrumu-uzatan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Şiir', 'yorgun-siir-sezer-odabasioglu-rli0y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün güneşle sevişmiş, belli yorgun

yorgun akşam üstü

eli yorgun kolu yorgun

yüzü yorgun insanların

ve de gönlü yorgun aşıkların

az önce geçmiş bir göğün yüzünden

bir ara sokağın içinden

bir ormandan bir rüzgâr

sesi kalmış bir yaprağın yüzünde, belli 

çamaşırdan çıkmış bir kadın

yorgun yüzünün teri

yorgun elinin emeği

bir yorgunluk kahvesi de içmemiş, belli

... ve yorgunluk girmiş usulca

bir yerlerinden şiirime

sende soluklansın şiirim, bırak.

''Senden Yana Büyür Çığlığım'' adlı şiir dosyamdan.', 'gün güneşle sevişmiş, belli yorgun yorgun akşam üstü eli yorgun kolu yorgun yüzü yorgun insanların ve de gönlü yorgun aşıkların az önce geçm...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yorgun-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Onlardasın', 'sen-onlardasin-sezer-odabasioglu-bonq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yedi iklimde, dört mevsimdesin

renkli kuşakta, son yağmurdasın

tutamadığım bir şeyler var ya

sen onlardasın

esen rüzgârda, mor dağlardasın

mavi denizde, fırtınasın

soramadığım bir şeyler var ya

sen onlardasın

doğan güneşte, ilkbahardasın

yüklü bulutta, berekettesin

bilemediğim bir şeyler var ya 

sen onlardasın.

''Senden Yana Büyür Çığlığm'' adlı şiir dosyamdan.

*** Şiir, sayın İbrahim Erdem tarafından bestelenmiştir.', 'yedi iklimde, dört mevsimdesin renkli kuşakta, son yağmurdasın tutamadığım bir şeyler var ya sen onlardasın esen rüzgârda, mor dağlardasın m...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-onlardasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüregin kanasın', 'yuregin-kanasin-cemil-yasin-cigdem-btii4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sesimi duyan kulaklar aglasın

gozumde yas goren gozler aglasın

dunyanın derdi bitmez ceken kul aglasın

sana doymadan gidersem yuregin kanasın

ellerimde titreme basımda agrı

bitmiyor artıyor dertler bu hayatın tadı

hic kesilmesin aksın damlalar gonul pınarı

sana doymadan gidersem yuregin kanasın

kucagım acık kos bana

engel cıkarsada hayat pes yok sakınha

savasmadan mutluluk nasip degil insanogluna

sana doymadan gidersem yuregin kanasın

herseyi sevmeyen bilmez ask nedir

kendisinden baska seven yok diyen delidir

ferhatın yukunu keremin zulmunu gormeyen necidir

sana doymadan gidersem yuregin kanasın

gercekte olan pes etmez asla 

yurekten seven dert cekmez asla

hayata isyan eden mutlu olmaz asla

sana doymadan gidersem yuregin kanasın

belki sacma sozlerim bilemezsin

belki sarhos bedenim hissedemezsin

benim gozumden bir gorsen

sende baska yer istemezsin 

sana doymadan gidersem yuregin kanasın

sevda iki hece

nice okumasını bilmeyenler var nice

a yazar b okur ogretir hayat zamanı gelince 

kul olurda kimse gormez bilmez kıvılcım tenine girince

sana doymadan gidersem yuregin kanasın', 'sesimi duyan kulaklar aglasın gozumde yas goren gozler aglasın dunyanın derdi bitmez ceken kul aglasın sana doymadan gidersem yuregin kanası...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yasin Çiğdem']::text[], 8.5, '{"poet":"Cemil Yasin Çiğdem","poet_slug":"cemil-yasin-cigdem","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuregin-kanasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol yanım tutmuyor anne', 'sol-yanim-tutmuyor-anne-cemil-yasin-cigdem-q53f6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'slm anne ben geldim 

sana dag gulleri getirdim 

papatyalar kadar sarı guller kadar guzel dag gulu 

nasıl uyudun aksamları sessizlikte ben uyamadım 

seni dusundum gozlerini tenini saclarını hayalledim 

resmini opup opup kokladım uyuyamadım 

damlalara bir turlu engel olamadım 

bir cicege su verir gibi ince narin tek tek dokulduler 

anne baska kimseye soyleme hele babama hic deme 

biliyorsun uzulur o uzulurse bende uzulurum 

dun okulda cocuklar hep annelerine hediye alacaklarmıs onu konustular ben hep sustum 

onlar anlattı ben kan kustum 

belli etmedim ama birden kendimden gectim 

kacam dedim denedim ama 

sol yanım tutmadı anne yapamadım 

hocam geldi zeynep dedi ben kim dedim 

zeynep dedi dayanamadım hungur hungur agladım 

nerde bilecekti senin adın zeynep anne 

herkes guluyor annesiyle babasıyla oynuyor parklar dolup bosalıyor ben gidemiyorum sensiz anne 

neden bıraktın bizi geride bizide al yanına dayanamıyorum anne 

sabah oldu beni sen gotur dedim babam is dedi 

banane dedim as dedi yıkıldı 

herkes eline takmıs annesini kos dedi 

ben yıgıldım kosamadım sol yanım tutmadı anne 

alinin annesi mavi boncuklu bir kazak ormus babam orguyu bilmem dedi anne 

ayse hergun annesiyle yuruyuse cıkıyormus babam isten yıgın gibi geliyor yemek yapıyor anne 

gule annesi bir kopek almıs onunla kosuyor 

benim bir oyuncagım bile olmadı anne 

senden kalşan tek resimle konusuyor onunla oynuyor onunla uyuyorum 

geceleri bana camdan bak alnımdan op bari yanlızlıgımı sen ort sen anne 

bizimde bir evimiz bir arabamız ve senin teninde uyuyacagımız buyuk bir yatagımız olacakmı olacakmı anne 

ne olur beni her gece ruyalarımda sar sarmala op anne sıkıca sar birdaha bırakmayacakmıs gibi anne 

seni cok seviyorum ne olursun geri don geri gel bizi unutma topragındaki fidan yasadıkca bende yasayacagım ona guc ver sen koru anne', 'slm anne ben geldim  sana dag gulleri getirdim  papatyalar kadar sarı guller kadar guzel dag gulu  nasıl uyudun aksamları sessizlikte ben uy...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yasin Çiğdem']::text[], 8.5, '{"poet":"Cemil Yasin Çiğdem","poet_slug":"cemil-yasin-cigdem","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sol-yanim-tutmuyor-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prenses', 'prenses-cemil-yasin-cigdem-utyaa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hey sehvetine paha bicilmeyen prenses 

hey gozlerinden ates yureginden gul kopan prenses 

duymazmısın yukselen sesi 

gormezmisin sana dokulen nefesleri 

tut elimden kaybolmasın askım

tut beni sarmala kahrolmasın umutlarım 

cezbeden bedenin ruhumuda oksasın 

tutki ben bir seytan 

tutki sen bir melek 

ikimiz arasında bir ask neden olmasın', 'hey sehvetine paha bicilmeyen prenses  hey gozlerinden ates yureginden gul kopan prenses  duymazmısın yukselen sesi  gormezmisin sana dokule...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yasin Çiğdem']::text[], 8.5, '{"poet":"Cemil Yasin Çiğdem","poet_slug":"cemil-yasin-cigdem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/prenses-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-sadik-dursun-9l5kr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzakların uğultusu mutluluğa bir sebep,

Çektiğim ızdırapları şimdi affediyorum.

Ben hasretin yalnızlığında biçare olan garip,

Dostsuz kaldığım bu hayatta dostu keşfediyorum.

Uyuturmuş gözlerimi karanlığın esrarı,

Sonu olmayan düşlerde bunu seyrediyorum.

Terketmiyor bedenimi sensizliğin ısrarı,

Görmediğim bir yerdesin seni hissediyorum.

26 Şubat 2001 ALACA', 'Uzakların uğultusu mutluluğa bir sebep, Çektiğim ızdırapları şimdi affediyorum. Ben hasretin yalnızlığında biçare olan garip, Dostsuz kaldığ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Dursun']::text[], 8.5, '{"poet":"Sadık Dursun","poet_slug":"sadik-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensizlik-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tonlarca Gözyaşı', 'tonlarca-gozyasi-sahin-erturk-api6v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen tonlarca akan gözyaşlarımsın

Sen hatalarımın tüm toplamısın

Çok büyük,kocaman pişmanlığımsın

Söyle kalbim seni,nasıl affetsin

(06.08.2005) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Sen tonlarca akan gözyaşlarımsın Sen hatalarımın tüm toplamısın Çok büyük,kocaman pişmanlığımsın Söyle kalbim seni,nasıl affetsin (06.08.200...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tonlarca-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum', 'korkum-fidan-bulut-b0dqu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana kalsa şımarığım

Aslında kaçmaktayım.

Gecende ışığın,

Gözünde nurun,

Kalbinde onurun,

Teninde tuzun olmaktan; 

Sende can bulmaktan korkmaktayım.

Bilsen ki; 

Kaç geceler,

Omuzlarıma saçlarım gibi dökülmektesin.

Yastığımda en güzel desenimsin.

Bilsen ki; 

Ellerimi neden saklarım,

Sormadan uzanacak bilirim.

Yatağımı toplamam,

Kalktığımda seni uyur bırakırım.

Sen sanırsın,

Sokakçı mahalle kızıyım,

Oysa sabah uğurlayan,

Akşam karşılayanım.

Bildiğin; 

Herkesle oynaştayım

Ama ben sana sevdalıyım.

Bir olur diyemem, gel, al,

Seninim diyemem...

Duydum ya! 

Ateşler kor,korlar kül olurmuş

    Korkmaktayım.....................', 'Sana kalsa şımarığım Aslında kaçmaktayım. Gecende ışığın, Gözünde nurun, Kalbinde onurun, Teninde tuzun olmaktan;  Sende can bulmaktan korkm...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/korkum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkolsun', 'askolsun-hakki-hakan-kaya-32a0e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aslolan yürek

başka sevdalara yelkenli

bir başka limanın 

rotasında hisleri

rüzgar 

arkanda olsun sevgili

yine karanlık 

inzivasında yürek

şartlı tahliyesinde sevdam

kendine kalan

bir yürek

bir ceketi

ve 

üzerinde yapıştırılan

talimat etiketi', 'Aslolan yürek başka sevdalara yelkenli bir başka limanın  rotasında hisleri rüzgar  arkanda olsun sevgili yine karanlık  inzivasında yürek ş...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/askolsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller Kırmızıya Açıyor', 'guller-kirmiziya-aciyor-mehmet-zeki-yildirim-cy0as', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgiyi sorgulamanın anlamı yok artık

Kırılgan duygularımızla,

Daha da derinleşiyor

Yalnız benliklerimiz

Ben yine de

Gözlerinin gördüğü yerde olmak isterim

Sisli sabahlarda

Aşık akşamlarda

Yanıbaşında.

Çünkü,

Hiçbir şeyle kıyaslayamayacağım,

Hiçbir şeyle ölçemeyeceğim

sensin

Sığınmak isteyeceğim liman

Özlem dalğalarımın 

Sakinleştiği kayalıklar sensin

Güller kırmızıya açıyor

Ben sana.

Ruhumun aydınlık yüzü

Kalp ağrılarım

Titremelerim

Sevilmiş hissediyorum seninle

Seni düşününce 

Bir gülümseme kaplıyor içimi

Uzattım ellerimi,

Tut ellerimi

Sevdiğini söyle bana.

5 Mart 2005', 'Sevgiyi sorgulamanın anlamı yok artık Kırılgan duygularımızla, Daha da derinleşiyor Yalnız benliklerimiz Ben yine de Gözlerinin gördüğü yerd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Yıldırım']::text[], 8.5, '{"poet":"Mehmet Zeki Yıldırım","poet_slug":"mehmet-zeki-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/guller-kirmiziya-aciyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANA VERiLEN DEGER', 'sana-verilen-deger-mehmet-emin-yesilmen-7qfi3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN, SANA VERDiGiM DEGERiN FARKINDA DEGiLKEN,

SAVA$TIM SENi SEVMEYENLERLE.

RUHLARINA KADAR GiRDiM DONMESiNLER DiYE...

SEN, SANA VERDiGiM DEGERiN FARKINDA DEGiLKEN,

YIPRATTILAR BENi, SENi SEVDiKCE.

HiC DUYULMAK iSTENMEDi CIGLIKLARIM,

KONUSMAK iSTEDiKCE SUSTURDULAR,

SEN DUYMA DiYE...

LANETLi iKSiRLER ALDILAR BUYUCULERDEN,

OLUMU YAZDILAR CEYLAN DERiSiNE.

iNADINA YASADIM,

SAVA$AYIM KORKUYU YOK SAYIP,

A$K iCiN OLMASADA,

YETERLiDiR SENiN ADINA.

SEN, SANA VERDiGiM DEGERiN FARKINDA DEGiLKEN,

TARiHi BA$TAN YAZDIM SEVDAMLA.

SEVGiNE MUHTAC OLDUM YILLAR GECERKEN.

SEN, SANA VERDiGiM DEGERiN FARKINDA DEGiLKEN,

VAR OLDUGUMU BiLDiGiM TUM ZAMANLARDA,

YALNIZCA SENi SEVDiM.

VE $iMDi, SENi SEViYORUM DiYEMEDiGiME UZULURKEN,

SEN YiNE FARKINDA DEGiLSiN.

VE DE HALA SEVDiGiMiN...', 'SEN, SANA VERDiGiM DEGERiN FARKINDA DEGiLKEN, SAVA$TIM SENi SEVMEYENLERLE. RUHLARINA KADAR GiRDiM DONMESiNLER DiYE... SEN, SANA VERDiGiM DEG...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sana-verilen-deger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi orduları', 'sevgi-ordulari-yilmaz-ozturk-ty39t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi orduları çıktı yola sevgi ekmek için

İnsanlığa santim kare her yerde mutlu gözlerin

Gülmesi için ordular komutasında Serdar`ı ekremin

Her sevgi askeri huzurlu mutlu mağrur Serdar`ın

Sevgi seli taştı yer yüzüne gurur sevgi komutanında

Her yiğit mutlu olur insanlar olunca sıhattli hayatta

Komutan Serdar`ın makamı var olsun cennette

İnsanlık huzurlu sevgi ordularının sevgisinde', 'Sevgi orduları çıktı yola sevgi ekmek için İnsanlığa santim kare her yerde mutlu gözlerin Gülmesi için ordular komutasında Serdar`ı ekremin ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-ordulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 39', 'eskimez-beyitler-39-huseyin-avdic-8k8ex', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok nadir çalıyorsun kapımı, ey hastalık! 

Fazla özletmeden beni, çal kapımı sık sık...

******

Kalb, vücut memleketinin başşehri.

Sevgiyle fethetmeli bu has şehri.

******

İnsan, âlim olduğu kadar cahil,

Cahil olduğu kadar da zâlimdir.

******

Hayatın lezzeti kısadır, elemi uzun.

Kısayı terket ki, uzun da kısa olsun.

******

Bir vefat duydum mu ''vuslata erdi bir garib'' derim; 

Garib garib; ah eder, iç çeker, of der, inlerim.

******

Bir kuzu gibi sevip okşuyorum ölümü...

Bu sevgim olmasaydı, gösterirdi günümü! 

Batı Berlin, 1980-85.', 'Çok nadir çalıyorsun kapımı, ey hastalık!  Fazla özletmeden beni, çal kapımı sık sık... ****** Kalb, vücut memleketinin başşehri. Sevgiyle f...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eskimez-beyitler-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokununca', 'dokununca-esma-ozdemir-gpr1p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umuda açılan her pencere

Yayılır bedenine çepeçevre

Düşlediğin sevgi gelir dizine

Emek ister, yürek ister

Sıcacık akıverir kalbine...

Cana can, kana derman ister

Verirsin, cömertçe

Gözyaşlarını üstüne serpe serpe...

Sonra durup, bir yoklarsın kendini

Rüyalarının gerçeğine güvenin gelince

Tam, ''yakaladım'' derken 

Can damarından

Tutku olur, hasret olur

Dokununca, hayal olur

İnandığın bütün tatlı gerçekler...

Gözümün önünde 

Kaybolur

Acımasızca

Birer birer

Yalancı sevgiler...

(İstanbul; 7 Şubat 1995 Salı)', 'Umuda açılan her pencere Yayılır bedenine çepeçevre Düşlediğin sevgi gelir dizine Emek ister, yürek ister Sıcacık akıverir kalbine... Cana c...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dokununca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Kangren', 'kangren-turgut-gundogmus-dj3h8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çivi çiviyi söker 

dermanım olursun

düşüncesiyle

seni,yüreğimin kıyısına aldım

nerden bilebilirdim ki

yara açıp 

hergün bir parçamı 

alacağını', 'çivi çiviyi söker  dermanım olursun düşüncesiyle seni,yüreğimin kıyısına aldım nerden bilebilirdim ki yara açıp  hergün bir parçamı  alacağı...', ARRAY['Türk Edebiyatı','Şiir','Turgut Gündoğmuş']::text[], 8.5, '{"poet":"Turgut Gündoğmuş","poet_slug":"turgut-gundogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kangren-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-esma-ozdemir-tx0en', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşklar vurur başıma

İflahımı keser özlemler

Arzular, çoğalır içimde

Sana uzanır ellerim; 

Parmaklarım yumulur

Yumruk olur, sıkılır 

Balyoz gibi iner göğsüme

İner, inletir bağrımı

Bağırdıkça bağırırım

Feryatlar kâr''etmez

Zavallı gönlüme.

Vururum kendimi yerlere;

Toprak ses vermez sesime

Haykırırım göklere

Dolaşır ruhum semada

Kuşlar derman değil

Bilirim, derdime.

İçime gömerim hıçkırıklarımı 

Söylenirim kendi kendime

İsminin üç heceli nakaratı

Yankılanır, kalbimin duvarlarında.

Neyleyim adını sevdiğim

Dokunamam ki ismine! 

Okşamaz heceler ruhumu

Ağlatır, inletir, kahreder yalnız! 

Anılar...bizim anılarımız...

Yalnızlık... benim yalnızlığım.

Umutlu, umutsuz, ama

Bitmeyen, amansız bekleyişim...', 'Aşklar vurur başıma İflahımı keser özlemler Arzular, çoğalır içimde Sana uzanır ellerim;  Parmaklarım yumulur Yumruk olur, sıkılır  Balyoz g...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bekleyis-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harelenmiş Yalnızlıklar', 'harelenmis-yalnizliklar-bulent-kiraz-buxkm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım

Ayrılığımın acı sancısı.

Yalnızlığım

Kapımı çalan sağanak yağmurum.

Islanarak anıyoruz

Geçmiş günlerin 

                  “ya gelirse? ”sini.

Yağmur,

Ben,

Ve soyutun büyülü gücü

Resmediyoruz yalnızlığımızı hayata

                  yırtarak gecenin karanlığını.

Sesin yitiriyor

Dipsiz kuyularda 

                  tüm ahengini.

Ve yüzün

yüzün 

                 günde beş vakit hatırladığım

	      hatırlayamaz olduğum…

		II

Harmanlanmaz yüreğini 

Diyardan diyara atan 

Seni böyle bedbaht

Seni böyle halden bilmez

Seni böyle yalan yapan neydi? 

Parelenmiş  yüreğimi

Diyardan diyara iten 

Beni böyle yakan

Beni böyle derbeder

Beni böyle suskun yapan neydi? 

Yalnızlık derin yara 

Hangi kahraman 

Hangi merhem devadır buna? 

Soyutun sınırsızlığına sığındım şimdi.

		III

Tanrılar unuttu

Ya da kendinden saydı bizi.

Ey sanat! 

Var ettin beni 

Yakılan bir aşkın küllerinden.

Her aşk bizi tamamlar şimdi.

Her yanlış bir doğruyu getirdi 

Sonsuz devinimin gücüyle.

Zamanıdır sevilmenin şimdi 

Şimdi yaşamanın

Şimdi demenin cesaretiyle 

Bağırmanın zamanıdır

“ S E N İ   S E V İ Y O R U M ” 

	       diye…

		Bülent KİRAZ

		Kasım 2001 -Antalya', 'Yalnızlığım Ayrılığımın acı sancısı. Yalnızlığım Kapımı çalan sağanak yağmurum. Islanarak anıyoruz Geçmiş günlerin                    “ya ge...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kiraz']::text[], 8.5, '{"poet":"Bülent Kiraz","poet_slug":"bulent-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/harelenmis-yalnizliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehrin Bana Borcu Var', 'bu-sehrin-bana-borcu-var-selahattin-durna-j7yf2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu Şehrin Bana Borcu Var

Bu şehrin bana borcu var kızım

Ona iyi bak! 

Bu şehrin bana borcu var kızım; 

Otuz yıl önce bu şehirde başladım

Geceleri kalkıp şiir yazmaya.

Bu şehirde fark ettim hep

Ayakkabılarımın eski

Gömleğimin kirli

Ceplerimin kirli olduğunu.

Bu şehrin bana borcu var kızım

Onu iyi tanı! 

Otuz yıl önce de böyle sarı saçlı

Böyle güzel gözlü 

Böyle dalyan,böyle cillop

Kızları vardı gene; 

Penceremin önünden geçip giden

Pencerelerinin önünden geçip gittiğim

Hiçbirisi dönüp bakmadı yüzüme

Hiçbirinin yüzüne dönüp bakamadım…

Bu şehrin bana borcu var kızım,

Onu iyi belle! 

Sigaraya bu şehirde başladım ben

Bu şehirde tanıdım Nazım’ı ilk

En delikanlı düşlerime

Bu şehirde kıydım ben.

Acıktım,bir kase yoğurdu çok gördü bana

Ateşlendim,bir dilim portakala kıyamadı.

Çorap ördüm,kilim dokudum,şurup sattım

Karpuz yükledim kamyonlara.

Pamuk çapaladım,pamuk topladım.

Uçsuz bucaksız tarlalar vardı otuz yıl önce

Hani şu kapısından bile geçemediğimiz

Otellerin yerinde.

Gölgesinde Oğuz Özdeş,

Gölgesinde Esat Mahmut okuduğum

Fıstık çamları vardı.

Rahmet bekleyen tohumlar abarttım bu şehirde ben.

Bu şehrin bana borcu var kızım,

Onu iyi kolla! 

Birisi kör talih,kahpe felek biri,

Biri bu şehir.

En gece kondusunu bana münasip gördü

En kirli yorganını bana ayırdı hep.

Bütün yağmurlarına şemsiyesiz yakalandım

Bütün bayramlarına elbisesiz.

Üşüdüm ağustos sıcağında bir başıma

Şubat soğuğunda sırılsıklam terledim.

Büyük kapıların önünde kalakaldım hep

Küçük kapıların arkasında sahipsiz.

Ben bu şehri

“Bütün orduları dağıtılmış

Bütün tersanelerine girilmiş

Ve her köşesi bil fiil

İşgal edilmiş” buldum hep.

Ne denizinde bir kulaçlık su

Ne kaldırımında bir omuzluk yer.

Sinemalarında bütün biletler satılmış,

Tiyatrolarında bütün koltukları dolmuş buldum hep…

Bu şehrin bana borcu var kızım,

Bunu aklında tut! 

Senin şair,senin öğretmen baban,

Bir gün yanılıp da; 

“Bu şehre çok şey borçluyum; 

Çok şey öğrendim bu şehirden ben”

Derse çıkıp karşına; 

İnanma! 

Yokluk öğrenilmez ki,açlık öğrenilmez ki,

Ayrılık öğrenilmez ki,acı öğrenilmez ki…

Ölüm öğrenilmez ki…

Asıl olan hayattır.

Güzel yaşamalar içindir bu güzelim yeryüzü.

Ak saçlar biriktirme! ”gözlerde mor halkalar”

Biriktireceksen eğer

Gülücükler biriktir.

Işıl ışıl bir kahkaha göz yaşından gerçektir…

Bu şehir beni sevmedi,kara gözlüm; 

Ama biliyorum,seni sevecek…

Çünkü sen ta gözlerinin içine bakacaksın bu şehrin

Öyle kaçırmadan.

Toprağa sağlam basacaksın basarken.

Unutma bu şehir,

Artık ayaklarını sana uyduracak…

Denizleri var; eskiden de vardı; ta Karayipler’e kadar.

Korkma,daldır ayaklarını! 

Dağları var; eskiden de vardı; 

Bir ucu Tibet Yaylası’nda,bir ucu Alpler’i bulur.

Çekinme,savur saçlarını! 

Bu şehir senden öğrenecek,

Bir oyun havasında nasıl ağlandığını.

En güzel keman konçertosunu

Senden dinleyecek bu şehir.

Bu şehir Motzart’ı senden dinleyecek artık.

Bense yeşil bir köşesinde belki

Gözlerimi Akdeniz bir ufka dikip

“Bana olan borçlarını sildim

Hakkım helal olsun Antalya! ”diyeceğim.

Ödenmemiş senetleri var elimde; 

Arkası yazılmış çekleri…

Unutma sakın; 

Bu şehirden alacaklıyım ben kızım! ! ! 

                                                                Ocak-Şubat 2003

                                                                    ANTALYA', 'Bu Şehrin Bana Borcu Var Bu şehrin bana borcu var kızım Ona iyi bak!  Bu şehrin bana borcu var kızım;  Otuz yıl önce bu şehirde başladım Gec...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":103,"source_url":"https://www.antoloji.com/bu-sehrin-bana-borcu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşpalazı', 'kuspalazi-selahattin-durna-nq6q2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuşpalazı

-Yüreğinin tıptıp’ında

Kuşpalazındadır yürek-

Kızımsın sen,

Varsın diye

Günü,yıldızları,ay’ı sahiplendim.

Oğullar düşmüştüm ya

Bir uçurtma öyküsünün yanıbaşına

Oğulların sırtlandığı davayı sahiplendim.

Aktım gider,

Ulu damarlardayım.

Sensin diye

Dünya artık

Küçücük bir Birinci Tekil Kişi

Ben üstlendim şimdi

Doğrulup gelişi,uzayıp gidişi.

Baktım gider,

Erte durduğum yollarlayım…

Büyürsün,

Büyür içim.

Dudaklarındaki gül,yüzündeki pembelikle

Kavgaların adı bellidir artık.

Çocuklara daha güzel bir ülke

Bahçe,mavi bisiklet,salıncak,uçurtma,

Okul önlüğü vesaire…

Har vurulur gönlümde kör bir noktaya.

Yaktım gider,

Bitimsiz sevdalarlayım…

Kızımsın,

Gel et hadi! 

Çağların ömrü uzasın,çoğalsın elleri çocukların.

Çünkü senin ellerin konuşurken dünya

Kocaman bir Birinci Çoğul Kişi

Senin gözlerinde bütün evler bize çıkar

Bütün çocuklar kardeş,bütün kadınlar anne sen gülerken…

Kırmızı pabuçlarını giymeyegör hele

Yürümek vaktidir ayaklarında.

Vaktim gider,

Yürüyen ayaklarlayım…

                                                               

                                                                   29 Mart 1989', 'Kuşpalazı -Yüreğinin tıptıp’ında Kuşpalazındadır yürek- Kızımsın sen, Varsın diye Günü,yıldızları,ay’ı sahiplendim. Oğullar düşmüştüm ya Bir...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kuspalazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboluş', 'kaybolus-gunes-kara-0ms34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O gün buluştuğumuzda

Sımsıkı sarılmıştık

Aynı masada karşılıklı otururken

Ellerimi tutuyordun

Akıntıya kapılmış bir çiçek gibi

Kapılıyordum sana

Gözlerim dalmışken gözlerine

Bilmediğim uzaklara gidiyordum

Dalından koparılmış çiçek gibi unutulmuşken

Işıl ışıl sürüklenip, bir sevgi buluyordum

Kayboluşa doğru seninle birlikteydim

İkimiz o uzaklarda kayboluyorduk

Bu bir aşkın başlangıcı

Bir sevdanın karşılıklı birleşmesi

Bir sevginin sonsuza ulaşmasıydı

Seni çok seviyorum AŞKIM', 'O gün buluştuğumuzda Sımsıkı sarılmıştık Aynı masada karşılıklı otururken Ellerimi tutuyordun Akıntıya kapılmış bir çiçek gibi Kapılıyordum ...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaybolus-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Zaman Notları-', 'zaman-notlari-i-brahim-yamac-ei16t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kum saatine girmiş, çöl diye geziyorum

attığım her adımda kıyamet seziyorum

...

zaman ne uzun koridor, kısa bir o kadar

gözü açıp kapamak bazen bir ömür tutar

...

yaşa ve heybene koy, saate bakıp durma

bakarsın kalbin durur oturup saat kurma

...

sınanma günlerinin nöbet defteri takvim

sadece nöbetçidir günler gibi her kavim

...

kıvrak girilir ömre ve orda kıvranılır

kıvrandıkça pişenler üstad diye anılır

...

kırışıklar, kır saçlar geçmiş zaman imzası

hayalimde anılar elimde sefer tası

...

yaşımı senelerle ölçmeye yeltendimdi

bu sabah bir çocuğum dünkü ihtiyar kimdi

...

emir gelir öteden sen gel de beni tanı 

yüreğimdeki saat şu an vurur o anı', 'kum saatine girmiş, çöl diye geziyorum attığım her adımda kıyamet seziyorum ... zaman ne uzun koridor, kısa bir o kadar gözü açıp kapamak ba...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yamaç']::text[], 8.5, '{"poet":"İbrahim Yamaç","poet_slug":"i-brahim-yamac","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/zaman-notlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mustafa-erdogan-nyax7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen,

Siyahında gecenin, yastığıma düşen mavi,

Derinliğinde yalnızlığın, söylediğim türkü,

Çıkmaz sokaklarda tenimi okşayan rüzgar,

Islanan saçlarımdan süzülen damla! 

Sen,

Bir mucizenin hüzünlü güzeli,

Masallarında çocukluğun...

Ne akıl, ne fikir, ne şuur! 

Tenimde dolaşan sıcak sezgi...

Sen,

Cehennem ve Cennet arasındaki

İnce çizgi...', 'Sen, Siyahında gecenin, yastığıma düşen mavi, Derinliğinde yalnızlığın, söylediğim türkü, Çıkmaz sokaklarda tenimi okşayan rüzgar, Islanan s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erdoğan']::text[], 8.5, '{"poet":"Mustafa Erdoğan","poet_slug":"mustafa-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-608-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kız var orada', 'bir-kiz-var-orada-i-smail-hakki-kavurmaci-exeh2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir kız var orada

çok uzaklarda

benim kalbimde

onun yanında

çapkın bakışları

hayat verir bana

kimbilir kaç aşığın

kalbini çalmış daha

onsuz hayat olmaz

o güneştir ufkumda

onsuz ömür sürmez

o neşedir ömrümde

bir gün tutacağım ellerini

bağrıma basacağım onu

doyamam doyumsuzca

seveceğim seveceğim onu

İsmail Hakkı Kavurmacı', 'bir kız var orada çok uzaklarda benim kalbimde onun yanında çapkın bakışları hayat verir bana kimbilir kaç aşığın kalbini çalmış daha onsuz ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kiz-var-orada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-gunes-kara-vygch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün anlayacaksın

Sevgimin büyüklüğünü

Anlayacaksın

Sebepsiz inanmayışlarını

Öğreneceksin

Sensiz geçen günlerimin

Ne çok acı verdiğini

Bileceksin

Aniden çıkıp gitmelerinin

Ne boş olduğunu

Belki birgün

Bir pişmanlık saracak yüreğini

Arayacaksın güneşini

O gün göremeyeceksin

Etrafını karanlıklar kaplayacak

Güneş aydınlatmayacak 

Göreceksin

Çünkü GÜNEŞ in sönmüş olacak', 'Birgün anlayacaksın Sevgimin büyüklüğünü Anlayacaksın Sebepsiz inanmayışlarını Öğreneceksin Sensiz geçen günlerimin Ne çok acı verdiğini Bil...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunes-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah Gençliğim Vah!', 'vah-gencligim-vah-muharrem-cetinkaya-b8umq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olur bu çocuklarla* bizim halimiz,

Al_ı versek,mor derler,

Moru versek dar derler.

Ormanda ağacı fark etmez.

Gemide gider,

Denizi görmezler.

Yangın var der

Feryat-figan eder,

Yananı görmezler! 

On eşek versen say diye

Dokuz getirir,

Bindiği eşeği saymazlar! 

Otur! 

Dizimin dibine,

Akıl ….desek.

Girecek yer yok derler! 

*Vurdumduymaz gençlerimiz.', 'Ne olur bu çocuklarla* bizim halimiz, Al_ı versek,mor derler, Moru versek dar derler. Ormanda ağacı fark etmez. Gemide gider, Denizi görmezl...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vah-gencligim-vah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçeye Benzerdin', 'serceye-benzerdin-muharrem-cetinkaya-zdjnu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni hep bir serçeye benzetirdim,

Ürkek,şaşkın…

Küt,küt atan yüreğini görürdüm,

Duyardım sesini…

Ne yer,ne içerdin,

Nerden bulurdun suyu,

Ekmeği? 

Merak ederdim..

Merak ederdim,

Yokluğun pençesinde,

Nasıl yaşadığını…

Kartalların içindeki,

Mücadelene imrenirdim! 

İmrenirdim; 

Yoksulluğun denizinde,

Yavrularını doyurmana,

Martılarla oynaşmana,

Yuvanı korumana…

.

Taa  ki; 

Dost bildiğin,

…….yediğin taştan,

Can çekişirken gördüğüm ana kadar!', 'Ben seni hep bir serçeye benzetirdim, Ürkek,şaşkın… Küt,küt atan yüreğini görürdüm, Duyardım sesini… Ne yer,ne içerdin, Nerden bulurdun suyu...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/serceye-benzerdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Hırsızı', 'gonul-hirsizi-muharrem-cetinkaya-dxpkb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün bizim eve hırsız girmiş,

Ne var ne yok dağıtmış,

Saçmış ortalığa anıları…

Biliyor ki,

Hazine,

Yıkık,virane de yatar.

Kırmış dökmüş,

Alacakmış kendince,

Kendine ait ne varsa,

Oysa

Hiç hesap etmemiş,

Saysan,sayıya sığmaz,

Yüklense; 

Altında ezilecek…

Biliyor,

Kaybettiği hazine burada,

Ama

Nasıl geri götürsün…

Tabi,hiçbir şey alamamış,

Götürememiş,

Yastıkta kalan,

Bir tel saçından başka! ...', 'Dün bizim eve hırsız girmiş, Ne var ne yok dağıtmış, Saçmış ortalığa anıları… Biliyor ki, Hazine, Yıkık,virane de yatar. Kırmış dökmüş, Alac...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gonul-hirsizi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikri Uzun-Aklı Kısa', 'fikri-uzun-akli-kisa-muharrem-cetinkaya-mb4hy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne uzunluk kaldı,

Ne kısalık.

Ne darlık,ne genişlik,

Ne de yükseklik.

Hani kalıbımıza göre biçerdik elbiseyi,

Ekmeği taştan çıkarırdık.

Ne oldu bize,

Dostlar ne oldu? 

Şimdi her yere uzarız,

İstenilen kadar kısalırız.

Verilen her elbise,

Üzerimizde,

Hangi şekli verirlerse alırız,

Uysa da,uymasa da…

Sohbetlerimizde değişti; 

Hülya mı rüküş? 

Derya mı? 

Ebru’nun selüloitleri,

 Karasularımızdan önemli! 

İki kulakta üç küpe,

Saçı saç değil,

Başı baş…

Donu yırtık,

Saç-sakal karışık,

Kiminin,

Göbeği fırtık! 

Ne uzunluk kaldı,

Ne kısalık.

Zamane deyip geçeriz.

Hemen karalanırız,

Bu gün moda zencilik deseler.

Deseler,

Moda dişilik! 

Çarşafa gireriz…

Artık ne uzunuz,

Ne kısa

Anamız belli,

Ya babamız? 

Babamız,

Bizim için fark etmez,

İster eb,

İster ısa,

Nasıl olsa; 

Aklımızda, donumuz gibi,

Kısa! ....', 'Ne uzunluk kaldı, Ne kısalık. Ne darlık,ne genişlik, Ne de yükseklik. Hani kalıbımıza göre biçerdik elbiseyi, Ekmeği taştan çıkarırdık. Ne o...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/fikri-uzun-akli-kisa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyzen! Neredesin?', 'neyzen-neredesin-ali-osman-yilmaz-hp5a8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vatanın her bir kalesi elden gitti gider,

Kemal denen hergele, hep buna güler,

Babası deyyusu ekberidir halbuki, ülkenin,

Ta dinini s...yim  o pe........ki dinleyenin.

Sümerbank mı? girmiş ta anasının ortasına,

Durmaz  kafirin oğlu, Atatürk’e bile küfreder,

O nun bunun çocuğu,Düşünmez mi ki hiç? 

Elbet Gün gelir hesap sorulur,ta vartasına,.

Seyreder istihzayla, tayyibi muktedir kişi,

Vatanı parsel parsel satmaktır  tek işi,

Menfaat nerde ise o tarafa yollanırız,

Dini biz,halkı uyuşturmak için kullanırız.

Özüköklü paşa, gideremezsin kuru laf ile endişemi,

Bumudur, bu halkın sana verdiği vatan görevi,

Yapacak kudretin yoksa,sus da adam sansınlar seni,

 İstersen ver emrini, üzülmem,aldır da assınlar beni

Bu danışıklı döğüşte, mahkemelere bakın,

Para paylaşılsın da,rezaletle barış olmaz,

Seyredenler ama dır,görürler sanma sakın,

Kafese koysalar da, kargadan bülbül olmaz.

Anlatırım size,işte memleketimin hali,

Kalmadı harice karşı,yüzümüz olsa dahi,

Yüzümüz mü kaldı,bakacak kabrine ecdadımızın,

Tükürür billahi yüzümüze, şehitleri vatanın.

Şu yeni ampulcü düzen nasıldır bilmem,

Bizde değer,adamın servetidir,parasıdır,

Eğer bu halk,hırsızlığı etmeyecekse kabul,

O zaman bu ampulcü rejim bize aykırıdır.

Yeni yüz yılın bir ilkesi var,hak kapanındır,

Söz medyada haykıranın,mantık ise şarlatanındır,

Geçer mi ele bir makam,..öt yalamayınca,

Bütün makamlar,pez.......enk ile buşh''t olanındır.

Herkes susmuş,istemem böylesi bir kader,

Dersimi aldım,nasihat bile istemem,eğer,

Varsa halkımın gidişe dur diyecek hali,

Zalimin her yumruğu,öldürse de değer.', 'Vatanın her bir kalesi elden gitti gider, Kemal denen hergele, hep buna güler, Babası deyyusu ekberidir halbuki, ülkenin, Ta dinini s...yim ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/neyzen-neredesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...''Gregor Samsa'' Kuraklığı! ...', 'gregor-samsa-kurakligi-naime-erlacin-fbmk8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sayarak kum tanelerini bir bir

yürüdük çölde

bilirdi yürek 

nasıldı susuz ve 

sancılı olmak köklerinde

korkutmadı hiç göç kuraklığı

çünkü kalple aklın 

kıyasıya seviştiği bir aşk vardı

adına “şiir” dediler…

ağır çöküyor kanamalı ağustos

vakanüvisler boşta geziyor şu sıra

tanımıyorlar öğütülmüş atlasları

zılgıtına kına yak ey gönül! 

bir yabancı yürüyor 

fikrimin dar sokaklarında

kam ana 

hüzünle tüttürüyor çubuğunu 

iç’i 

''gregor samsa’* göç’ünden kalmış 

bir içimlik yabancı…

……………

(*)      Gregor Samsa: Franz Kafka’nın “Dönüşümler” romanındaki baş kahraman…

(6 Ağustos 2005) 

(YENİ ADANA GAZETESİ, Mayıs 2013)', 'sayarak kum tanelerini bir bir yürüdük çölde bilirdi yürek  nasıldı susuz ve  sancılı olmak köklerinde korkutmadı hiç göç kuraklığı çünkü ka...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gregor-samsa-kurakligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay..', 'dolunay-soner-demir-cpn2l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece yarısına gecikmiş saatler

yağmurdan yeni döndü gökyüzü

ay bulutlardan yıkıyor yüzünü

ay şimdi ışıl ışıl

ay..; 

dolunay...

içim yanıyor, yüreğim kıpır kıpır

korkuyorum gözlerine bakmaya

sen okursun gözlerimi hemen

duyarsın içimde onu...

halka halka zincir zincir

ellerimde kelepçe, ayağımda pranga

mıhlanmışım bu yere...

yinede aldırmıyor yüreğim

yasaksa yasak ona ne 

içimde bir deli çocuk, daha ağzı süt kokan

hiç gün ışığı görmemiş; 

senin ışığında bile yanan...

al onu götür benden,

sendeki çukurlarda sakla! .....

gözümsün

ay...

dolunay...', 'gece yarısına gecikmiş saatler yağmurdan yeni döndü gökyüzü ay bulutlardan yıkıyor yüzünü ay şimdi ışıl ışıl ay..;  dolunay... içim yanıyor,...', ARRAY['Türk Edebiyatı','Şiir','Soner Demir']::text[], 8.5, '{"poet":"Soner Demir","poet_slug":"soner-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dolunay-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Peygamber Nur Muhamed', 'gul-peygamber-nur-muhamed-nuri-yilmaz-lw0d2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ya Ressullulah,

Bahar gelmezse açılmaz gül.

Benim alemimde ise bilakis...

Güller açılmazsa  gelmez baharım.

Güller olmazsa gülmez  yüzüm.

Gülün ruhumda açılmazsa ötemez bülbülüm.

Elinizi sokmasanız çoşmaz nehirim.

Siret-ı siretiniz olmazsa neşelenmez suretim.

Sevgin olmazsa açılmaz çiçeklerim.

Işıl ışıl bir bakışınız olmazsa  parlamaz yıldızım

Ruhumda Nil olmazsanız çöle döner kalbim.

Tebesüm etmeseniz dalgalanmaz denizim.

Gönül esintiniz olmazsa havasızlıktan buğulurum.

Asumanımda yağmur olmzsanız kavrulurum.

                                  2004/Ümraniye-İst.', 'Ya Ressullulah, Bahar gelmezse açılmaz gül. Benim alemimde ise bilakis... Güller açılmazsa  gelmez baharım. Güller olmazsa gülmez  yüzüm. Gü...', ARRAY['Türk Edebiyatı','Şiir','Nuri Yılmaz']::text[], 8.5, '{"poet":"Nuri Yılmaz","poet_slug":"nuri-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gul-peygamber-nur-muhamed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi bana elveda', 'haydi-bana-elveda-husamettin-guven-dtqk6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'vargit canim ugurlar olsun

senin bahtin acik olsun

mutluluklar senin olsun

haydi bana elveda

kizmadim kizamadim

sendin benim agiz tadim

yarim kaldi benim muradim

haydi bana elveda

sevdigimi sorman sakin

supen varsa kalbime bakin

unutamam olum yakin

haydi bana elveda

seni ben biliyorum

senin icin oluyorum

simdi kalkip gidiyorum

haydi bana elveda', 'vargit canim ugurlar olsun senin bahtin acik olsun mutluluklar senin olsun haydi bana elveda kizmadim kizamadim sendin benim agiz tadim yari...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haydi-bana-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenik mi Düştün', 'yenik-mi-dustun-arafat-arik-5cjdt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara bulutlara pabuç bırakıp, 

Yağmursuz sellere yenik mi düştün? 

Denizsiz nehirde tersine akıp, 

Derede yellere yenik mi düştün? 

Yağacakmış gibi şimşekce çakıp, 

Kartal edasıyla sarplardan bakıp, 

Dönülmez yollara gemiler yakıp, 

Kokusuz güllere yenik mi düştün? 

Sen çağlayanıydın yürek selinin, 

Sen hamiyetiydin mazlum elinin, 

Sen şafaklarında hayal elinin, 

Tutulmaz dallara yenik mi düştün? 

Sen son damla gibi bardaktan taşıp,

Sen yılmaz ruhlarda kahramanlaşıp,

Sen olamazlarda ummanlar aşıp,

Bir damla göllere yenik mi düştün?', 'Kara bulutlara pabuç bırakıp,  Yağmursuz sellere yenik mi düştün?  Denizsiz nehirde tersine akıp,  Derede yellere yenik mi düştün?  Yağacakm...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yenik-mi-dustun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız kulesi', 'kiz-kulesi-elazigli-mustafa-kaya-p4dtk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'neden  hüzün  yüklüsün

   ıslak  bedeninde

   sakladığın  acıları  söyle

   mavişin  ortasında

   hangi  sırları  tutuyorsun

   odacıklarında

   ve  hangi  fısıltıları  vuruyor  zamanın

   duvarlarına çığlıklar sinmiş

   beni de al yanına

   benide  sar  yalnızlığına

  

    gün iniyor  şehir  sarı

    günlerdir  aklıma  getiriyorum

    günlerdir  seni dileniyorum

    bir  garip  yolcu 

    bir deniz feneri gibisin

    geçip  giden  gemiler

    senin hikayeni dinler

    salacak sahilinde 

    sırdaş tuttum kendime

    bir yalnızlık şarkısı dilimde

    denizin ortasında

    durup bakıyor gözleri 

    beni de  yanına  al

    kız kulesi...

  

                                                                        11.03.2000 / İstanbul

                                                                         Mustafa kaya

                                                                         www.mustafakaya.net', 'neden  hüzün  yüklüsün    ıslak  bedeninde    sakladığın  acıları  söyle    mavişin  ortasında    hangi  sırları  tutuyorsun    odacıklarınd...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kiz-kulesi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gececik', 'bir-gececik-ugur-aydin-2-oepq3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kaç gece uyumadım. senlizilikte 

ve bu gece uyumayacağım, sen mutlu ol diye. 

sokaklarda dolaşacağım sabaha kadar...seninle 

konuşacağım...yine üzerime ayrılık doğacak. 

her gün doğduğu gibi... 

ve ben  hayallerimde, 

hayalinle yaşatacağım. seni

akıp gidecek zaman olacak akşamda ''da '' 

senin için uyumayacağım. 

dayanamıyacaksın,acı çektiğime belki ''de''

üzüleçeksin, belki de gülüp geçeceksin halime. 

ama bana her gece,hayallerimde ki 

hayalinle sabah ettireceksin.', 'kaç gece uyumadım. senlizilikte  ve bu gece uyumayacağım, sen mutlu ol diye.  sokaklarda dolaşacağım sabaha kadar...seninle  konuşacağım...y...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gececik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basra Düştü', 'basra-dustu-selahattin-durna-yefxn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Basra Düştü

Fatima,Fatimacık! 

Elma dersem, çık! 

Bomba dersem,çıkma! 

Bekle,n’olur azıcık! 

Oturup Dicle’nin kıyısına

Göçmen kuşlar sayacağız,tamam; 

Az dur,yıldızlar sayacağız Bağdat gecelerinde.

Uzatıp parmaklarımızı sayacağız; 

Ayak parmaklarımızı da,evet! 

Karıncalar sayacağız çöle odun taşıyan…

Fatima,Fatimacık! 

Armut dersem,çık! 

Bomba dersem,çıkma! 

Dur be gülüm,azıcık! 

Ellerin ne kadar küçük,küçücük.

Ayakların ne kadar küçük,küçücük.

Ben şimdi sana…

Gözlerini kocaman açıp bakma,kuzucuk! 

Ben şimdi sana

“Dünya petrol rezervleri…”desem anlamazsın ki.

Uçak desem,yakıt desem,üs desem…

Hava sahası,sınır ticareti,lojistik destek…

Ben şimdi sana

“Yurtta sulh,cihanda sulh”

Küçücük parmaklarını ayırıp bir bir,

“Bu tutmuş,bu pişirmiş,bu yemiş…”

Der gibi; 

Gökten cemre düşer gibi; 

“Birinci tezkere,ikinci tezkere…”

Desem anlamazsın ki! 

Bu bombalar bizim sularımızda aldı boy abdestini; 

Bu bombalar bizim topraklarımızdan geçti,evet! 

Urfa’dan,Şanlıurfa’dan evet! 

Antep’ten,Gaziantep’ten evet! 

Portakal bahçelerini gördü; 

Çağla çiçeklerini kokladı,kaçamak.

Fatima,Fatimacık! 

Elma dersem,çık! 

Armut dersem,çık! 

Bomba dersem,çıkma! 

Daha altını ıslatacaksın be kuzucuk! 

Daha ateşleneceksin gecenin bi yarısı…

Alnına ıslak havlu koyacağız.

Kabus göreceksin,

Deli adamlar gelecek üstüne üstüne

Uyandırıp bağrımıza basacağız seni.

Bademciklerin şişecek,öksürük şurubu vereceğiz.

Kabakulak olacaksın,kızamık çıkaracaksın daha! 

Daha tırnakların uzayacak,

Saçlarında bit bulacağız.

Ellerin çatlayacak soğuktan,

Kremle ovacağız,

Gözüne toz kaçacak; 

Daha,bir Pazar yerinde kaybolacaksın,

Arayıp bulacağız seni.

Daha uzaklara “addaaa..”diyeceksin.

Arı sokacak,böcek ısıracak yumuşacık tenini.

Salıncaktan düşeceksin,yüzünde sivilceler çıkacak.

Yağmur yağacak,ıslanacaksın,

Çamura bulanacak üstün başın.

Burnun akacak,sümüğünü sileceğiz.

Daha çember çevireceğiz,ip atlayacağız birlikte.

Saklanacaksın arkasına bir duvarın,

Sobeleyeceğiz seni.

Kaçacaksın,kovalayacağız,

Düşüp dizlerini yaralayacaksın; 

Tütün basacağız yarana.

Ayağın burkulacak,kolun çıkacak; 

Alçıya alacağız.

Fatima,Fatimacık! 

Ne yaptın be kuzucuk! 

Daha çember çevirecektik,uçurtma uçuracaktık seninle.

Topun suya kaçacak; 

Lastiği patlayacaktı bisikletinin; 

Okula gidecektik birlikte; 

Kuş resimleri çizecektik sınıfın duvarlarına.

Çiçekli etekler dikecektik sana.

Daha aşık olacaktın; 

Başka bir kızla görecektin çıktığın oğlanı.

Daha gönül ağrıları yaşayacaktın.

Bu araçlar bizim yollarımızdan geçti,evet! 

Mardin’den evet,Silopi’den evet! 

Bu cehennem bizim sokaklarımızdan geçti elleri ceplerinde; 

Papatyalar ürktü,annelerinin eteğine sığındı çocuklar.

Önce bizim göğümüzü yırttı bu tarrakalar; 

Önce bizim köpeklerimiz havladı,

Önce bizim tavuklarımız kaçıştı kümeslerine.

Çanakkale gelir aklıma,Sakarya,Dumlupınar…

Utançtan yüzlerini kapatır Kocatepe’de Kurtuluş’un paşaları; 

Yemen’de şehitler

Fesini arar,postalını arar.

Şimdi ben sana

Umm Kasr düştü diye,

Hisse senetlerinin değeri yükseldi İstanbul Borsası’nda

Desem inanmazsın ki…

Basra’da kadınlar aşağılandı,kolu koptu çocukların,

Ayaklar altına alındı insanlık onuru diye

TL,Dolar karşısında değer kazandı,

Bono faizleri geriledi ülkemde

Desem bilemezsin ki…

Taş taş üstünde kalmadı Kerbela’da,

Necef’te Cumhuriyet Muhafızları

Yüzlerce ölü verdi diye

Ham petrolün varili yirmi beş dolara düştü

Desem duyamazsın ki…

Fatima,Fatimacık! 

Ne yaptın be deli çocuk! 

Daha erik yiyecektik,

Daha üzüm yiyecektik,

Daha dondurma…

Fatimacık! 

elma dersem,çık! 

Unutma! 

                                                               4-5-6 Nisan 2003', 'Basra Düştü Fatima,Fatimacık!  Elma dersem, çık!  Bomba dersem,çıkma!  Bekle,n’olur azıcık!  Oturup Dicle’nin kıyısına Göçmen kuşlar sayacağ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":115,"source_url":"https://www.antoloji.com/basra-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm - 1', 'olum-1-elazigli-mustafa-kaya-4y2fz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ömür kapısı çaldı

işte geldi ölüm meleği 

bir feryat oldu

insanın ölümü 

koptu kıyameti

göründü uhrevi alem

ya,

cennet bahçesi olacak yeri

ya da,

cehennem çukuru 

işte ölüm sonrası hayat

Allah sözünde durdu...

                   Mustafa  kaya

                   10.07.2005', 'ömür kapısı çaldı işte geldi ölüm meleği  bir feryat oldu insanın ölümü  koptu kıyameti göründü uhrevi alem ya, cennet bahçesi olacak yeri y...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olum-1-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmit'' de', 'i-zmit-de-rengin-ozesmi-agztl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum oradasın,

Gelirsem mutlaka; bulabilirim seni

Çınarların; cadde boyu dikilip

Durduğu; tren yolunun geçtiği,

O büyük caddede 

Yıkılmamış ayakta kalmış

Apartmanların birinde,

Varsın; 

İhtiyarlamış olacaksın', 'Biliyorum oradasın, Gelirsem mutlaka; bulabilirim seni Çınarların; cadde boyu dikilip Durduğu; tren yolunun geçtiği, O büyük caddede  Yıkılm...', ARRAY['Türk Edebiyatı','Şiir','Rengin Özesmi']::text[], 8.5, '{"poet":"Rengin Özesmi","poet_slug":"rengin-ozesmi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/izmit-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarıma Gülleri Sersen', 'yollarima-gulleri-sersen-salim-erben-b5t2k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıkma karşıma bir daha sakın

Hüzün sana sevda bana yakın

Mutlu olmak benim de hakkım

Artık yollarıma gülleri sersen

Dönmem sana dünyayı versen

        

Göçer oldu dağların  dumanı

Bırakmış rüzgara dini imanı

Sarmış ovayı yalanı dolanı

Artık yollarıma gülleri sersen

Dönmem  sana dünyayı versen

Dönersem sana namert olayım 

Görürsem cehennemde yanayım

Hakkın divanında hesap sorayım

Artık yollarıma gülleri sersen

Dönmem sana dünyayı versen

Zalım dediler var olan adıma

Boyun eğmedim hiç bir kadına

Cevabım hayır hasret inadına

Artık yollarıma gülleri sersen

Dönmem sana dünyayı versen

Nerde ilmi hekim doktoru lokman

Anlamı kalmadı dönüp bakmam

Mezarına bile bir mum yakmam

Artık yollarıma gülleri sersen

Dönmem sana dünyayı versen', 'Çıkma karşıma bir daha sakın Hüzün sana sevda bana yakın Mutlu olmak benim de hakkım Artık yollarıma gülleri sersen Dönmem sana dünyayı vers...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yollarima-gulleri-sersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat Yok ki...', 'vuslat-yok-ki-serap-demirturk-m346k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adam,yüreği yanarak

Baktı kuyuya,

Ta derindeki suda,

İçindeki özde

Gördü ağlayan gözleri.

Sardı içini pişmanlık,

Sardı da sustu...

Yol boyunca gitmek,

Hep gitmek istedi.

Ayaklarına dur dedi aklı,

Yüreği ağladı, gidemedi.

Sarıp sarmalayıp

Sakladı sevgiyi...

Umut bir sonsuz düş,

Hiç göremediği, bilemediği.

Gerçekler, koskoca bir dev; 

Sevdayı ezip geçen.

Diyemedi ki sevdim diye,

Susup kaldı...

Vuslat ağacının meyvesi,

Acı ile sulanmış.

Kavuştuk deyince diller,

Tenlerinden sıyrılmış  sevda.

Ayrılıktaymış aşk,

Gözyaşındaymış sevda,

Vuslat  yok ki...', 'Adam,yüreği yanarak Baktı kuyuya, Ta derindeki suda, İçindeki özde Gördü ağlayan gözleri. Sardı içini pişmanlık, Sardı da sustu... Yol boyun...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/vuslat-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke', 'ofke-mikdat-bal-uy08s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öfke her nerden çıkar

Önce orayı yıkar

Kalbi daraltıp sıkar

Öfke bir şaşkınlıktır

Akıl idrak kör olur

Her hareket şer olur

Nefsi tutmak zor olur

Bir anlık taşkınlıktır

Öfkesini yenenler

Bunlar güçlü denenler

Öfkeyle işlenenler

Aciz bir düşkünlüktür

Mikdat bir şey karalar

Dostluk dolsun buralar

Açılmasın aralar

Bu dünya üç günlüktür', 'Öfke her nerden çıkar Önce orayı yıkar Kalbi daraltıp sıkar Öfke bir şaşkınlıktır Akıl idrak kör olur Her hareket şer olur Nefsi tutmak zor ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ofke-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heey Karadeniz Gülü', 'heey-karadeniz-gulu-hasan-cam-d1ql1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karadeniz''in hırçın dalgaları gibisin

Her bakışın öldürüyor, beyin hücrelerimi

Deli hoyrat rüzgarlar gibi, sözlerinde sert esişin

Talıyor tozlarla örtercesine, pare pare yüregimi

Heey, karadenizin sahil kokulu mor gülü

Önce temmuz sıcakları oldun, sıcak Akdeniz gibi

Sonra ekim rüzgarları gibi coştun, hoyrat gönlümde

Hasatlarıma karıştın, ektigim gönül bahçemde

Ayrılık yarım ölüm, artık sensiz yaşamak niye

Pamuk gibi toplayıp, tütün gibi dizmişim gönlüme

Nakışlar gibi işlemişim, sevdanı seni beynime

Anlam veremiyorum, bendeki seni seven senligime

Heey, karadenizin sahil kokulu mor gülü

Önce temmuz sıcakları oldun, sıcak Akdeniz gibi

Sonra ekim rüzgarları gibi coştun, hoyrat gönlümde

Hasatlarıma karıştın, ektigim gönül bahçemde

05,08,2005,

Ümraniye İstanbul

[email protected]', 'Karadeniz''in hırçın dalgaları gibisin Her bakışın öldürüyor, beyin hücrelerimi Deli hoyrat rüzgarlar gibi, sözlerinde sert esişin Talıyor to...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/heey-karadeniz-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleten sevgilim', 'bekleten-sevgilim-elazigli-mustafa-kaya-47z2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'geldim

bin defaydı bekledim

piyer loti de

beklettin

hem  çokça bekledim

sevgililer  geldi

aşk kokuları sardı 

buradan şehir bir düş masalı

buradan haliç sen kadar güzel

senin kadar acı  veriyor

hiç kimse  bizim kadar sevişmedi

neden  gelmedin…neden..? 

bir ben  isyan etti

bir de mezarlık çiçekleri…

                  

                                 10.10.2001

                                 Mustafa kaya / İstanbul', 'geldim bin defaydı bekledim piyer loti de beklettin hem  çokça bekledim sevgililer  geldi aşk kokuları sardı  buradan şehir bir düş masalı b...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleten-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın yazısı', 'alin-yazisi-elazigli-mustafa-kaya-m9wix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'al  götür  beni de

             al getirme  geriye

             alın  yazısı desinler

             sevdim  bir kere....

                                       11.07.2005

                                       Mustafa kaya', 'al  götür  beni de              al getirme  geriye              alın  yazısı desinler              sevdim  bir kere....                     ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/alin-yazisi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevebilseydin', 'sevebilseydin-serdar-erkenekli-zss9y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık bir gecede yine sen geldin aklıma,

Gözlerim doldu ağladım yokluğuna,

Gözlerine baktığımda yanıyordum, aşkınla

Seni sensiz mi? asla! 

Hep uykularım bölünmdü; senin olmadiğında,

Sol tarafıma baktığımda; yoktun orada.

Ellerimi kaldırdım dualar ettim Allah a

Ne olursun yalvarırım sana; onu benden alma

Benim sevdiğim insan sen olamazsın.

Beni bırakıp nasıl başkasıma bakarsın? 

Yanılmışım; sen koynumda ki kara yılan

Zehrini şerbet gibi tattırdın! 

Gidiyorum arkama bile bakmadan; tek başıma.

Sevmeyecegim senin gibi zalimi asla! 

İki çift sözüm olacak sana; ne olur bana kızma.

Beni bir daha Arayıp sorma ve benim için ağla.

Demiştim ben sana,senden ayrıldıgımda

Atarım kendimi o serin sulara

İmanmamıstın,sen benim aşkıma

Git ve bak babanın mezarının yanına! 

     

                                                         06.08.2005

                                                             gölbaşı', 'Karanlık bir gecede yine sen geldin aklıma, Gözlerim doldu ağladım yokluğuna, Gözlerine baktığımda yanıyordum, aşkınla Seni sensiz mi? asla!...', ARRAY['Türk Edebiyatı','Şiir','Serdar Erkenekli']::text[], 8.5, '{"poet":"Serdar Erkenekli","poet_slug":"serdar-erkenekli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevebilseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz akşam - 2', 'sessiz-aksam-2-elazigli-mustafa-kaya-sykph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir akşam dı 

martıların derdi ne 

içimdeki çığlıklara benziyor 

rıhtıma öfkesi var bir vapurun 

el ele iki sevgili 

kalabalıklara karişan yalnızlığıma güldü 

şehir alacakaranlık 

gül kırmızısı güneşe ne oldu..? 

geceyi yorgan yapmak düştü yine bana 

uzanıp soğuk kaldırımlara 

sessiz insin akşam... sessizce ruhuma

                                      Mustafa kaya / 12.05.2005

                                      çengelköy', 'bir akşam dı  martıların derdi ne  içimdeki çığlıklara benziyor  rıhtıma öfkesi var bir vapurun  el ele iki sevgili  kalabalıklara karişan y...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sessiz-aksam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz akşam - 3', 'sessiz-aksam-3-elazigli-mustafa-kaya-vwwh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ürkek gün

saçlarımı okşamakta

bir sokak kedisi gibi halim

kırılıp duran zaman

ve içimi yakan  şehir

ve pas tutan dostluklar

hiç sevilmemiş yıllarım

eski bir giysi gibi..

sahil  sessiz bu erken saatte

köpüklere karışan hayallerime takıldım

içimde kıpırdayan sevgi

uzundu kara saçları üstelik gamzesi..

benimle alay etti deniz

sessizce inen gün kandırdı beni

ve sessiz akşama saldım umutlarımı…

                                               

                                                 Mustafa kaya

                                                 12.05.2005/ çengelköy', 'ürkek gün saçlarımı okşamakta bir sokak kedisi gibi halim kırılıp duran zaman ve içimi yakan  şehir ve pas tutan dostluklar hiç sevilmemiş y...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sessiz-aksam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz akşam - 4', 'sessiz-aksam-4-elazigli-mustafa-kaya-cyrjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mavi bir kumaş

benim yaşadığım şehir

sahillerinde yosun kokusu  keskin

iskelelerde vapurları görmelisin

göğe uzanan mabedler  büyüler seni

kollarını açmış minareler

bir seda yedi tepeden

sınırsız sevinç davetine

kalbim  çarpıyor  7.30 vapurunda

yine o gamze var karşımda

bir uçurtmaya bağlansam

uçsam diyorum..uçsam

akşamın bu derin sessizliğinde..

ve yıldız yağmuruna dönüşen süzüşler geçmiyor

serin taşlara kaldım ben

serin sokaklara düştüm ben

sessiz akşam düştü yine 

derinden…derinden..

                                13.05.2005

                                Mustafa kaya / çengelköy', 'mavi bir kumaş benim yaşadığım şehir sahillerinde yosun kokusu  keskin iskelelerde vapurları görmelisin göğe uzanan mabedler  büyüler seni k...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sessiz-aksam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemize sahip cik', 'ulkemize-sahip-cik-muhammed-murad-uzun-ck3t8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah vah su halimize 

Gelmeli kendimize 

Sarilip dinimize 

Ülkemize sahip cik 

Bizi icten yikanlar 

Iki yüzlü yilanlar 

Sarmis bizi düsmanlar 

Ülkemize sahip cik 

Ne tavuk ol ne ördek 

Olma sakin bir ödlek 

En derinden bir dilek 

Ülkemize sahip cik 

06/08/2005', 'Ah vah su halimize  Gelmeli kendimize  Sarilip dinimize  Ülkemize sahip cik  Bizi icten yikanlar  Iki yüzlü yilanlar  Sarmis bizi düsmanlar ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ulkemize-sahip-cik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sevdam', 'sen-sevdam-elazigli-mustafa-kaya-e2xua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 've artık her gün batımında

resmimi çeken gök

sarıyor kimsesizliğimi

ve kederli rüzgarlar kucaklar beni

bir ekmek kırığından

kan damlar

ve ben sessiz sokakların yolcusuyum

elimden tutmaz yıldızlar

ve

bir geminin batmasına benziyor

yok olan hatıralar

sen kurtul yeter...sen  sevdam

ister uzat başını kalabalıklardan

ister geç.. beni tanımadan

ve bir sessiz akşamda...istanbul da

hangi rüzgarlar gelecek

tek başıma kalmışlığıma....

                         14.05.2005 / çengelköy

                         Mustafa kaya', 've artık her gün batımında resmimi çeken gök sarıyor kimsesizliğimi ve kederli rüzgarlar kucaklar beni bir ekmek kırığından kan damlar ve be...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-sevdam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Kırıldı', 'ayna-kirildi-dilek-dagtekin-n9p5t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden sevmek için yasak insanları seçerdi? 

Sonu sorgularda biten savaşları..

Her gazete ilanında

O da yolculuk ilanı verirdi düşlerine.

Her kentte birkaç aşk kalırdı,

Boynu vurulmuş.

Hasret çekmek için mi? 

Yoksa her aşkın kimliği

Atlasında mı ne mutlu idi? 

her sevgilinin bakışında 

Özgürsüzlük mü çarpardı yüreğine? 

Neden her sevgi sözcüğü

Yıldırıyordu içindeki ışığı? 

Her seni seviyorum başlangıcında,

Bakışlarını öldürüp,

Gözlerine sakladığı gizleriyle

Gitmek oluyordu O.

Ne kalmayı becerebiliyordu ne gitmeyi..

tek bildiği soru; 

Coğrafyamı kim çaldı Ninhursag''dan? 

Nerede İnanna? 

Nedir bu yabancılık? 

Koşsam yollara,

Kovulmuşcasına..

Ve gitsem derdi.

Sadece bu kadar,ondan sonrası yok.

O,her seni seviyorum başlangıcında

Yolcu olurdu burukluklara.

Bu haliyle,

Bir çocuğun istese de 

Elmalı şekeri reddeşindeydi.

''Yağmur derdi,''yağmur''

Kapkaranlık, ıssız sokaklarda

  Çırılçıplak değiyorsa tenine

Zihnine aktığını hissediyorsan

İşte o zaman güzeldir.

Duyumsayarak seversin,

Yağmurun kim olduğunu anlarsın,üşüsen bile.

Ama...Ama derdi..

yanıbaşında ateş,

Sıcak yatak,gözlerin tavanda

Suyun duvarlara saldırışı

Ürküten sesler,

Her an gökyüzü üstüne çökmede.

''anlasana ''diye bağırırdı

Yağmurla senin aranda duvarlar

O duvarlarda

Korku düşlerinin renkleri,gardiyanları..

Yağmur seni çoğaltmıyor.

Suyu tanımıyorsun ve üşümekten korkuyorsun.

''Neyse,boşver ''derdi sonra

Belki anlaşılmayacağını düşünürdü

zaten anlaşılmak için anlatmazdı.

Her sır verişinde,sırtını dönüp gitmek olurdu O.

.................

Siyahların sahipleri vardı

Ve bir gün özgür kaldı beyazlar.

Sahip olmamalı insan,özgür olmak için,der

Her seni seviyorum başlangıcında yok olurdu.

Konuşmak ne kadar gereksizdi,

Tartışmak,anlatmak..

Hele insana hayvanı,

Tanrısal olmanın gücü karşısında.

Hayat kilidi kaybolmuş kapılar ardında

Yitik bir harita değildi.

Ne kapılar arkasına hayal kur

Ne de onlara ulaşmak için anahtar ara.

Payna düşen gerçektir.

Yoksa sen hayal kurarken

Gözlerin ele verir seni aidiyat aramalarında

Düşlerini bile çürütürler

Geçip karşısına karanlık bir askıda seyredersin onları.

Ya İsa olursun ya da kurtarıcısı İsa''nın.

Öyle der,nemlenen her bakışta gitmek olurdu O.

Gitmek neydi? 

Terkediş mi arayış mı? 

Yaşamın şiiri mi? 

Hiçbir insana,atlasa zincirlenmeden

İçinde bir kan emici gibi.

Her geçen gün benzini sarartan

Dilini kurutan..

Ölümü ve hakikati beşiğinde sallayan kan emici.

Gizdi O,

Başkalrınca çözülmeyen tılsım.

Esrardı ama soruları yine O soruyordu.

sevgi neydi,kimdi? 

Hangi peygambere çaldırmıştı insanlık onu? 

Hangi zihnin rahminde sancılanıyordu? 

Hangi devrim devrimdi; balığı denizden

İnsanı topraktan kaçıran? 

Kimdi aşk-ı İlahi*

Her sinir bombardımanında

Camlar iniyor yerlere..

darmadağın oluyor muustanın hayalleri? 

Parmakları can çekişyor mu? 

Kaç bardak kaç vardiya..

Emek neydi? 

Aşk onu bilir miydi? 

Dar sokaklarda doğman değil mesele? 

Ya da cecedimin bulunmaması? 

Sevgi neydi? 

Hangi kelepçede yitirmişti tarih onu? 

sevgi ne renkti? 

Kim kahraman kılıyordu ırkları? 

Genetik miydi ezilen olmak? 

İçimiz mi zindandı,

Biz mi ihbar etmiştik onu? 

Kimdi içime zar dikip,

Kendi söküğünü dikemeyen tanrı? 

Sordu...Sordu..

Hiç yrulmadan sordu..

Ve biliyorum

Cevap vermekten daha zordu bu.

Sustu.

Gözlerine baktım; son kalışlardı,

Yine uzaklar haykırıyordu.

Sesi konuştu; 

Bütün odalar boş

Onları gizli ben-lerle dolduruyorum.

Her adım -ben-gerçeğinden doluluk.

Kapısını kapattım,

Çıkmayacağım.

Dışımdaki ben-in cesedi elimde kalana dek.

Çıkmayacağım.

Biliyorum bekliyorlar..

Tecavüz edip tanımak uğruna...

Duvarlardan ben-lerim var benim.

Çarpan parçalansın,ölsün diye kapısı da yok.

........Susmuştu,uzaklar olmuştu yine

Sormadım,sarılamadım suskunluğuna..

Anladı.

''Kalk aynaya bak''dedi

Ben aynaya,O uzaklara,sesi bana baktı

''Dışarıda dişiyim

Dışarıda öteki

Dışarıda ait olmayan

Dışarıda sürgün

Dördüncü duvarda ya kırılır ayna

Ya beyaz ölürüz ''

..............

Hava karanlığını atıyor üzerinden

Ve ben ellerime bakıyorum,ellerim beyaz.

Bütün kadınlığım

Kokuşmuş dilsizliğim,

İçimdeki piçliğim,

Kırsız çiçekliğim...

Mezarsız cesedim

Yurtsuz ömrümün çığlığıyla vurdum,

Vurdum

Vurdum

Vurdum..

Uğursuzluk bitti,

Ayna kırıldı! 

(1998)', 'Neden sevmek için yasak insanları seçerdi?  Sonu sorgularda biten savaşları.. Her gazete ilanında O da yolculuk ilanı verirdi düşlerine. Her...', ARRAY['Türk Edebiyatı','Şiir','Dilek Dağtekin']::text[], 8.5, '{"poet":"Dilek Dağtekin","poet_slug":"dilek-dagtekin","theme":"Türk Şiiri","is_hero":false,"total_lines":154,"source_url":"https://www.antoloji.com/ayna-kirildi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-melek-bagac-lq3va', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel sözler söylen yar

Ruhumu oksayan yar

Herdem fikirime zara yar

Beni pesinden sürükleyen yar

Müptelayim sana yar

Söz gecmiyor yürek firarda yar

Hayaline dalmisim  yar

Aklim gitmis avuclarinda yar

Anlayamadim  yar

Bu elem bu keder niye yar

Sarilmisim bir kördügüme yar

Cözmek ne mümkün  yar

Yollara bakiyor gözlerim yar

Gel bu bahar kavusalim yar

Gem vurmadan yüregime yar

Ayrilik güz gibi esmeden yar

Ah yar 

Gözyasima seni yazdigim  yar

Gözlerinde seyyah oldugum  yar

Etmeden terki diyar 

Gecmeden ömür gel  artik yar 

06.08.05

19:44', 'Güzel sözler söylen yar Ruhumu oksayan yar Herdem fikirime zara yar Beni pesinden sürükleyen yar Müptelayim sana yar Söz gecmiyor yürek fira...', ARRAY['Türk Edebiyatı','Şiir','Melek Bağaç']::text[], 8.5, '{"poet":"Melek Bağaç","poet_slug":"melek-bagac","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yar-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrime Özlemi', 'esrime-ozlemi-yusuf-varol-947a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unuttum harflerin nasıl çizildiğini

Sözcüklerin, sessizliklerin ölümüyle doğduğunu

Ve ölümün,

Sözcüklerle başlayıp

Sessizlikle devam ettiğini...

   İç dudaklarımda koparılacak parça kalmadı

Ağız dolusu yalnızlık kusuyorum

Unutmayayım diye kanın tadını

Ve rengini, 

      kimsesizliğimin.

   Kim sessizliğimin engini? 

Muammasın ahh siyah gece! 

Sokakların, balkonların, düşlerim

dalgasız denizlerin o hüzünlü gözleri

Sen, sonu olmayan karanlığım

Benim,

      Düşlerimin 

          ve sözcüklerimin toplamı.', 'Unuttum harflerin nasıl çizildiğini Sözcüklerin, sessizliklerin ölümüyle doğduğunu Ve ölümün, Sözcüklerle başlayıp Sessizlikle devam ettiğin...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/esrime-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmuru Bekleme', 'yagmuru-bekleme-yusuf-varol-mh8wr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesine kanayan gözlerimle cann parçaları içiyorum,

süzülen çiselerin biriksede dudaklarımda

ben ağmıyorum aslında...

küf rengi sesime koşan kelimelerim donupta kalıyorlar

bu sessizliklede ben

           yağmıyorum aslında...

Belleğimdeki  tüm resimlerini içtim

Seni çiseliyorum gözlerimle zamana

Sesin dinmiyor,

Sensizliğim beni hiç dinlemiyor

Bu sensizliklede ben ağlayamıyorum aslında...

Araladım tenimi,

             bırak aksın

Sen kuru kalmaktan sakın

Sadece ıslan,bekleme yağmuru

Yağamasada gül

Gül ve ıslan.', 'Sesine kanayan gözlerimle cann parçaları içiyorum, süzülen çiselerin biriksede dudaklarımda ben ağmıyorum aslında... küf rengi sesime koşan ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmuru-bekleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-hikmet-kucuk-7w61k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pek te nazlıdır, 

Öyle kolay gelivermez. 

Duygu bekler, sessizlik bekler, 

Gününü bekler, anını bekler. 

Yazılınca da bir heyecan, 

Koşuşturur melekler. 

Çünkü melekler,

Aşk için, sevda için, 

İyiliği yaymak için, 

Sabahlara dek dolaşır. 

Şiir sayesinde de, 

İşleri kolaylaşır.

(Eskişehir 6/8/2005)', 'Pek te nazlıdır,  Öyle kolay gelivermez.  Duygu bekler, sessizlik bekler,  Gününü bekler, anını bekler.  Yazılınca da bir heyecan,  Koşuştur...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acısı Bana Kaldı', 'acisi-bana-kaldi-abdulkadir-karaca-quwhy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluluğun büyüsünü tatmaya yönelik bir aşktı

İlkin ben sevmiştim seni

İlk o söyledi sevdiğini

İlkin onunlaydın sonra bana geldin

Aslında sen ondaykende benimleydin

Heralde ben rolümü tükettim senin filminde

Seni benim yapan herşeyi paramparça edip

Bendende üçüncü bir tekil şahısa gittin

Şimdi anlıyorum sen çoğul yaşanmış bir aşktın

Peki neden sensizliği tek ben çektim? 

Bazen bir sarhoş kahkahan siniyor ruhuma

Galiba sevmeyi becerebilen sadece bendim

Gidebilense her zaman sen

(06,08,2005)', 'Mutluluğun büyüsünü tatmaya yönelik bir aşktı İlkin ben sevmiştim seni İlk o söyledi sevdiğini İlkin onunlaydın sonra bana geldin Aslında se...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/acisi-bana-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben gidiyorum', 'ben-gidiyorum-ugur-aydin-2-y2jvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben gidiyorum

Hiç bir şey bırakmadın bende giderken 

ne varsa sormadan alıp ta gittin. 

Oysa ben sana seni seviyorum demiştim. 

Ne sevgimi bıraktın bende ne kendini! 

Kaç yıl geçti aradan, 

önce hayalin geldi geceme 

sonra birden karşıma cıktın.

 Ansızın 

bir şey demiyecekmisin diye sordun. 

Evet, şimdi söylüyorum giderken 

görmediğim için seni’’ 

şunu bil ki seni sen gibi sevdim. 

Ben seninle sendim! 

Daha bitmedi söyleyeceklerim! 

Ne seni sevecek bir kalp, 

nede içine sevgi koyacağım bir yürek bıraktın. 

Bende 

şunu bil ki bir tek şeyi bıraktın. 

Bende 

kolayca gitmeyi arakama bakmadan 

güle güle demeyi 

bana sen, öğrettin bunları artık istemiyorum 

sendeki emanetleri. 

Artık bakmıyorum arkama 

tıpkı senin gibi, 

ne sevebiliyorum nede sevgimi saklıyorum! 

sana gerçek vedamdır! Bu ben gidiyorum...', 'Ben gidiyorum Hiç bir şey bırakmadın bende giderken  ne varsa sormadan alıp ta gittin.  Oysa ben sana seni seviyorum demiştim.  Ne sevgimi b...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-gidiyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-ugur-aydin-2-4qx4b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne adam diyebilirim artık kendime 

ne de adam gibi sevebilirim seni.. 

uzak yollardan gelmek isterdim.. 

biliyorsun gelemem... 

ne adam gibi sevebilirim seni artık. 

ne de tertemiz bir  sevgiyle.. 

beni unutuğun bu şehirde kirlettiler 

ben artık bıraktığın ben degilim. 

ben artık sendeki sen değilim.. 

ben ne bendeyim ne de bıraktığın gibi temizim.. 

bulamıyoırum artık suçluyu 

ben miyim yoksa beni kimsesizce 

bu şehirde sessiz bırakıp giden miydi.. 

bekleme artık gelmeyeceğim 

istesemde gelemiyeceğim 

ne beni bırakır bu şehir 

ne de ben bırakıpta geleceğim... 

bu son gece doğum günüm degil. 

yine yalnızlardayım 

hiç bekleme gelmeyeceğim 

bu gece  refikaala  duasın da senimleyim', 'ne adam diyebilirim artık kendime  ne de adam gibi sevebilirim seni..  uzak yollardan gelmek isterdim..  biliyorsun gelemem...  ne adam gibi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/veda-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''ü ölün, Bellis Perenis', 'gul-u-olun-bellis-perenis-yusuf-varol-zcv1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çekmeli 

kuru ve sarı yaprakları enn derine

Dinginliğe yükselmenin soluğunu duyumsamalı

Ve öğlen sonrasındaki sıcak sessizliğe gömülmeli

Adım,

hayatım,

zamanım...

Varım,

Yarılanmış gözkapaklarımda puslu ışıltılar titreşiyor işte

Hoş ve mistik bir uzamda dönüp duruyorum

Akolastik bir ayine kapıldım inip çıkıyorum

Uçuşan yapraklar,konuşan ırmaklarla...

Sanrısal bir uzaklığa gömülüyüm

Sesimi taşısada rüzgar bilinki ben bir ölüyüm

Sessizlikler ortasında yaşamanın vecd hali...

yaşamanın ve ölümün ortasında 

ince bir 

bölü’yüm.', 'Çekmeli  kuru ve sarı yaprakları enn derine Dinginliğe yükselmenin soluğunu duyumsamalı Ve öğlen sonrasındaki sıcak sessizliğe gömülmeli Adı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-u-olun-bellis-perenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-mehmet-dorttepe-47paw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zararı yok, faydası var her ademe 

Sevilmekten geçer, her türlü felsefe 

Sen beni bil, ben seni, kimseye deme 

Gel  bakalım.madde için mana''yı eleme 

Bir tek cümlen ile seni yutup bağlandım 

Akıl köşkünden Gönül sarayına taşındım 

Gelince yeşerdim bin renk, gidince yaşlandım 

Simanı aradım yabancı,olmayana dadandım 

Geçen ay yine aynı böyle olmuştum 

Seni aradım yine senle dolmuştum 

Yalnızlık soframda, karşıma koymuştum 

Arıyordum, seni tanımadan çok sormuştum 

Gördüklerimin arasında hep seni zorladım 

Avrupa''da,Asyada yer bırakmadım turladım 

Basitce, böyle yazdım elden ele dolandım 

Tarifini bile yapamadım, derya''da bulandım 

Gönül sarayında sultan, yalnız neylesin 

Vezir firarda, ferman elde, kim okusun dinlesin 

Kendim çıksam haykırsam bir bilsem kimlesin 

Fakiriyim'' bulamaz isem gelme, sen sinemdesin', 'Zararı yok, faydası var her ademe  Sevilmekten geçer, her türlü felsefe  Sen beni bil, ben seni, kimseye deme  Gel  bakalım.madde için mana''...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dörttepe']::text[], 8.5, '{"poet":"Mehmet Dörttepe","poet_slug":"mehmet-dorttepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arayis-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıramı bekliyorum', 'sirami-bekliyorum-ugur-aydin-2-cjwsi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kapanmaz Azrail''in defderi...

ne yaşlı der ne de gence sitemi..

tanımaz ana baba arkadaş..

ölüm acımasızdır bırakmaz sırası geleni...

sakın üzülme akmasın gözlerinden yaş...

çıkar içindeki kederi gamı...

yapacak bir şey yok,

bende bekliyorum defterdeki sıramı

götürmeyeceğim giderken arkamdan.

arkadaşımı babamı anamı...

sokmuyorum içime kederi gamı

bende bekliyorum defterdeki sıramı...', 'kapanmaz Azrail''in defderi... ne yaşlı der ne de gence sitemi.. tanımaz ana baba arkadaş.. ölüm acımasızdır bırakmaz sırası geleni... sakın ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sirami-bekliyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-ali-aydogan-xvdq5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bilmemki aşk nasıl anlatılır sevdigine

mutlu gözlerine kıyamaz bakamzsın ki

dilin tutulur söyleyemezsin sevdigini

umutların içinde düğümlenir kalır sanki

bildigin tüm aşk sözcüklerini unutur

bir titreme düşer sanki içine o anda

o titreme korkudan deyildir sevmektendir

işte o an dafa fazla baglanırsın sevdigine

sevdigini nerde görsen dizinde can kalmaz 

koşmak isterde koşamazsın sevmek bambaskadır

içinde bişiler bilmedigin duygular kaplar bedenini

kendi kendine mutlu olur kalbin küt küt atar

işte o anda ne kalbine söz gecer ne yuregine

ister sevdigini can gecede gündüzde 

ve sevmenin anlatılamadıgı en güzel duygu ve an

sevdiginle yanyana olmak ve onunla bir ömür boyu aynı

yolda aynı adımlarla el ele yürümek 

işte sevmek böyle sevmek yürek ister 

seni sevdim ve seni seven asil yüregimi

seninle vardım sevmenin tadına', 'bilmemki aşk nasıl anlatılır sevdigine mutlu gözlerine kıyamaz bakamzsın ki dilin tutulur söyleyemezsin sevdigini umutların içinde düğümleni...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydogan']::text[], 8.5, '{"poet":"Ali Aydogan","poet_slug":"ali-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgiliye-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadıklarımıza', 'unutamadiklarimiza-ugur-aydin-2-wiimf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dostlar beni tek tek, 

bırakıp gittiler. 

öyle dostlar vardır ki, 

gitseler bile hep seninle. 

beraberdirler. 

ne ben onları Unuttum 

bilmem onlar unuttular mı Beni 

ben Unutamadım. 

bırakıpta gidenleri....', 'dostlar beni tek tek,  bırakıp gittiler.  öyle dostlar vardır ki,  gitseler bile hep seninle.  beraberdirler.  ne ben onları Unuttum  bilmem...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutamadiklarimiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Morphe', 'morphe-yusuf-varol-as3rz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmayanın varlığını kendime kazımanın sancısını yavaş yavaş oluşturdum

şimdi

süzül ve ak beyaz kanım,

parçala kuruluğunu...

Ben sana siyahın kaçıncı silüetini kazıdım bilmiyorum

sayamıyorum,

Ölüm,

resmime benziyor.

Göziçlerimin çoraklığına yağıyorsun sen

Ben, 

  şiddetini ölçemediğim bir bellek yitimine tutuluyorum

sen,ya adını değiştir yazgım olmasın benim

ya da izin ver ben sende öleyim.', 'Olmayanın varlığını kendime kazımanın sancısını yavaş yavaş oluşturdum şimdi süzül ve ak beyaz kanım, parçala kuruluğunu... Ben sana siyahın...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/morphe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-osman-koca-nse4e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben aşkı senin bedeninde değil 

Ben aşkı senin kalbinde buldum

Hayallerimi seninle paylaştım

Anılarımı seninle paylaştım

Ben senin gözlerini sevdim

Unutma gözler yalan söylemez

Ben senin dudaklarını sevdim

Unutma dudakta kelimeler bitmez

Ben senin cesaretini sevdim

Unutma cesaret güveni artırır

Ben senin güvenmeni sevdim

Unutma güven insanı yüceltir', 'Ben aşkı senin bedeninde değil  Ben aşkı senin kalbinde buldum Hayallerimi seninle paylaştım Anılarımı seninle paylaştım Ben senin gözlerini...', ARRAY['Türk Edebiyatı','Şiir','Osman Koca']::text[], 8.5, '{"poet":"Osman Koca","poet_slug":"osman-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutma-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayanın Olumlanması', 'olmayanin-olumlanmasi-yusuf-varol-4re42', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Descartes''a, oluşu''na



Dilde doğar,olan olmayan ne var ise

Olmayan tek şey ol''mamış olandır.

Ama bundan da ötedir düşüncenin içreği; 

Varolmayan yoktur olmayanın içinde 

Sadece sensindir mahrum kişi olan’a nerede diyen.

Varolanı varedendir ses ki tanrı’sıdır nefes

O’dur olanı vareden olmayanı sesleyen.

Duyulardır varkılan olanı,olumlayan varolanı

Ama ses’tir vareden olanı,olmayanı

Var’dır oysa herşey

Dil’lesen,ses’lesen,görmeyipte bilmesen

Yok değildir hiçbirşey

Yalnızca mahrumdur kişi bu herşeyden

Fakat hiçbirşeyden değildir bu mahrumluğu.', 'Descartes''a, oluşu''na Dilde doğar,olan olmayan ne var ise Olmayan tek şey ol''mamış olandır. Ama bundan da ötedir düşüncenin içreği;  Varolma...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmayanin-olumlanmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misâfirlik', 'mis-firlik-mehmet-bicik-4hqvc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün

Misâfirliğe gitsem…

Yollarda karşılasalar beni..

Rakkâseler

Halil İbrahim sofrasında

Bâdelerle ağırlasalar…

En güzel günümü yaşasam

O gün…

1 Aralık 2002, Burhaniye', 'Bir gün Misâfirliğe gitsem… Yollarda karşılasalar beni.. Rakkâseler Halil İbrahim sofrasında Bâdelerle ağırlasalar… En güzel günümü yaşasam ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/misafirlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-ahmet-kesici-0hhme', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlık yollarından,

Kaldırım asfaltlarından yürüdüm.

Paketinden sigarayı çektim.

Ateşim hiç olmaz aşkım olmadığı gibi,

Neyse ki yoldan geçen bir adamdan ateş aldım.

Yaktım sigaramı,

içtim.

Ahh çektim.

Hep kendime kızdım.

Ahh ulan ahh dedim.

Menderes caddesinin birahanelerinde gezdim.

Çektim kafayı.

İçtim rakıları.

Efkar dağıttım dağıtabildiğim kadar.

Okkalı bir ses geldi Orhan abiden ''''bir teselli ver''''.

Bir teselli ver be insafsız verebildiğin kadar.

Hani çok sevmiştin anlatamayacağın kadar.

Sonrası güzelim,başım dönüyor.

Sarhoş oluyorum.

Dayak yemeden meyhaneciden kalkıp gidiyorum.

Ayakta duramıyorum.

Sağa sola çarpıyorum.

Ateşim hiç olmaz aşkım olmadığı gibi,

Sönmeden sigaram,sigaramı sigaramla yakıyorum.

Kızıyorum vefasız dostlara.

İsyan ediyorum ayyaşlığıma.

sonra bu sarhoşluğuma.

Sonrası güzelim,kapının önünden geçiyorum 

Şeytan diyor sarhoş feryadıyla bağır,

Melekler diyor çek git evine ağır,ağır.

Neyse ki gidiyoruz evimize. 

Efendiliğimizi bozmuyoruz.

Soytarılık etmiyoruz elaleme.

Nede olsa delikanlı takılıyoruz bu alemde.

Işığın sönse de,hani perden çekilse de, 

İçimize gömüyoruz sevdamızı acıyla,kederle,hasretle.

Kendi kendime konuşuyorum karanlık yollarda.

Gören,deli sanıyor.

Deliyim ama kanlıyım da.

Sonrası güzelim, 

Sarhoş oluyorum aşkınla,

.....................................Sevdanla,

.....................................................Rakıyla, 

................................................................Rakıyla ulan rakıyla.', 'Gecenin karanlık yollarından, Kaldırım asfaltlarından yürüdüm. Paketinden sigarayı çektim. Ateşim hiç olmaz aşkım olmadığı gibi, Neyse ki yo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sarhos-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Asır Yalnızlık', 'bin-asir-yalnizlik-ekrem-kemal-kirmaci-ed0at', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim vefakar dostum yalnızlığım.

Ben sana yaşam boyu bağımlıyım.

Bana ikramın hıçkırık, gözyaşım.

Sensin  benim  en yakın arkadaşım.

Bir an'' gülsem ''üzülür,darılırsın.

Acılar verip, intikam alırsın.

''Mutluluğum'' ihanet olur sana.

Koca dünyayı dar edersin bana.

Bundan böyle asla gülmeyeceğim.

Senin koynunda geceleyeceğim.

Hep  sana sarılıp, ağlayacağım.

Söz dostum! Sana sadık kalacağım.', 'Benim vefakar dostum yalnızlığım. Ben sana yaşam boyu bağımlıyım. Bana ikramın hıçkırık, gözyaşım. Sensin  benim  en yakın arkadaşım. Bir an...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kemal Kırmacı']::text[], 8.5, '{"poet":"Ekrem Kemal Kırmacı","poet_slug":"ekrem-kemal-kirmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bin-asir-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal meyal', 'hayal-meyal-ugur-aydin-2-j7lcw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayal meyal görebilmek 

seni 

hayal meyal sevebilmek 

seni 

hayal meyal tutmak ister ölüm elleri 

hayal meyal almak ister bu bedeni 

gitmek kolay ayrılık zor 

hayal meyal nasıl unutur...seni', 'hayal meyal görebilmek  seni  hayal meyal sevebilmek  seni  hayal meyal tutmak ister ölüm elleri  hayal meyal almak ister bu bedeni  gitmek ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayal-meyal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbinde miyim?', 'kalbinde-miyim-veysel-alkan-5dnkt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklım hiç kar etmez,

Düşünemem yar! 

Bilmiyorum yönümü,

İzinde miyim? 

Peşine düşmüşüm,

Durunamam yar! 

Görür müsün çabamı,

Gözünde miyim? 

Dilime dolanmış,

Güzelliğin yar! 

Söylüyorum bıkmadan,

Sözünde miyim? 

Ben bilemem yerimi,

Sen bilirsin yar! 

Kazandım mı ben seni,

Kalbinde miyim?', 'Aklım hiç kar etmez, Düşünemem yar!  Bilmiyorum yönümü, İzinde miyim?  Peşine düşmüşüm, Durunamam yar!  Görür müsün çabamı, Gözünde miyim?  ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbinde-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkıların Bir Anlamı Kalmadı', 'sarkilarin-bir-anlami-kalmadi-ekrem-kemal-kirmaci-0kheh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana bir şiir yazmaya çalıştım.

Yazdım, yazdım  hiç biride olmadı.

Aşıklara,şairlere danıştım.

Sözün, sazın  bir anlamı kalmadı. 

Eskiden türküler bir başka güzeldi.

İnsan hayal aleminde yaşardı.

Duygulanıp, bir kaç kadeh içerdi.

Şarkıların bir anlamı  kalmadı.

Mahzun mahzun gözlerime bakınca.

İçin, için sen kalbimi yakınca.

Mor  sümbüllü dağlar  gibi  kokunca.

Mevsimlerin bir anlamı kalmadı.

Yüreğimde çaresizlik yaşardı.

Boz bulanık seller gibi  taşardı.

Sen gülerken bülbül bile susardı.

Notaların  bir anlamı kalmadı.

Hızır gibi zamanında  yetiştin.

Korkuları, endişeyi  bitirdir.

Kucak, kucak sevgileri getirdin.

Tabuların bir anlamı kalmadı', 'Sana bir şiir yazmaya çalıştım. Yazdım, yazdım  hiç biride olmadı. Aşıklara,şairlere danıştım. Sözün, sazın  bir anlamı kalmadı.  Eskiden tü...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kemal Kırmacı']::text[], 8.5, '{"poet":"Ekrem Kemal Kırmacı","poet_slug":"ekrem-kemal-kirmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sarkilarin-bir-anlami-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyl-i ak', 'leyl-i-ak-yusuf-varol-rus4z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'l e y l a a a a a k.... 

ince telden çıkan bu çığlığı örtüyorum tenime 

rengin var sesin yok sesinsizim

örtüyorum tenimi sensizim 

olmadı

gidemedim, 

yoktun 

gidemezdim

muammasın hayalim böyle bana kalamam

kalamazsam gidermiydik.

Olmadı...

tenimi araladım kırmızıya kandım 

çığlığında kaldım gidemedim

gidemezdim, 

seninle kaldım.

T a n r ı ı ı ı ı m...

iç çekişli bu çağrı kime

kim''in kimsesizliğinden kime ne

ahh begonya 

seni tutmak vardı bu hayatta

sana dokunmak,

budur senin tek mahrumiyetin 

yine de rengin var beni sarmalayan

ama sesin yok sesinsizim

örtüyorum tenimi sensizim', 'l e y l a a a a a k....  ince telden çıkan bu çığlığı örtüyorum tenime  rengin var sesin yok sesinsizim örtüyorum tenimi sensizim  olmadı gi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/leyl-i-ak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Ayıramadılar', 'bizi-ayiramadilar-mustafa-dogan-kuzgun-nk3hd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynı sınıftaydık ayrıldın

sınıfımı değiştirdim.

Başka bir okula gittin

okulumu değiştirdim.

Mahalleden taşındınız

gene peşinden geldim.

Bizi ayıramadılar

Bizi ölüm bile ayıramadı.

Merak etme:

Yanındaki mezarı da benim için kazdılar...', 'Aynı sınıftaydık ayrıldın sınıfımı değiştirdim. Başka bir okula gittin okulumu değiştirdim. Mahalleden taşındınız gene peşinden geldim. Bizi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bizi-ayiramadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazdan Sabah Olacak..', 'birazdan-sabah-olacak-ayse-i-smetoglu-v515z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birazdan sabah olacak,

Güvenimi, cesaretimi sevgimi biriktirdiğim 

O apansız gece sona erecek

Savruk saatler tükenecek

Ve sen gideceksin

Yanında benden bir parça 

Bir kor tanesi …

Bense soğuk duvarlarla  yüz yüze 

Yaban ağrılarımla baş başa …

Aslında gecenin bir yarısı 

Yara almıştı hislerim! 

İçimde üşüyen bir çocuk vardı 

Ve kurumayan yaralar..

Aşkın; 

Büyüsü,

Sırları,

Bilgeliği vardı 

Zamanla anlaşamazdı 

Bu yüzden tuhaftı dakikalar bu gece 

Önemsemiyordu zamanı

Saatlerse aklına eseni yapıyordu! ! 

“Ya aşk zamanı yenecekti ya da yenilip sabahı getirecekti “

Birazdan  sabah olacak Sevgili 

Ben, sitemli bakışlarla 

Titreyen ellerimle 

Yönelmiştim sana 

Nedensiz yere kimsesiz kalmamalıydım 

Bütün varlığını yitirmiş gibi

Anlamsız bir kimsesizlikti bu …

Kolayları yaşamak vardı

Zorları aşmak 

Ve imkansızlıklara alışmak! ! 

“Kolaydı gidişin,ardından bakmak zor,yokluğuna alışmak imkansız! ! ”

Birazdan sabah olacak 

Felaketim olacak 

Sensiz sabaha uyanmak! ! 

Derin bir boşluğa düşüştü gerisi 

Anlatmaya değmez bu oyulmuş sevgiyi

Zaten anlamayacaktır, bu hoyrat kalabalık,

Bu dalgın insan topluluğu..

Güneş doğacak birazdan 

Sen gideceksin! 

Gidişin ey sevgili gidişin; 

“Benim batışım olacak ama sen bilmeyeceksin! ! ”', 'Birazdan sabah olacak, Güvenimi, cesaretimi sevgimi biriktirdiğim  O apansız gece sona erecek Savruk saatler tükenecek Ve sen gideceksin Yan...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/birazdan-sabah-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin Çöl Yağmurudur Susuzluğumda', 'sesin-col-yagmurudur-susuzlugumda-melih-coskun-8sau7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesin çöl yağmurudur susuzluğumda 

Susma 

Sararıyor yapraklarım 

Dalından zamansız kopan bir meyve oluyorum 

Kokusuz, tatsız. 

Koparma dalımdan 

Bir kurşun atımı zamanda 

Bitiyor bütün baharlarım 

Eski bir Temmuz gibi düşüyorsun aklıma 

Susma 

Kuruyor bütün kelimelerim 

Çatlaklar açılıyor cümlelerimin göğsünde 

Ama diyorum ki yine de sana 

Madem ki sadece bir sonu var bu sararmış hikayenin 

En güzelidir 

Susuzluğunda ölmek...', 'Sesin çöl yağmurudur susuzluğumda  Susma  Sararıyor yapraklarım  Dalından zamansız kopan bir meyve oluyorum  Kokusuz, tatsız.  Koparma dalım...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sesin-col-yagmurudur-susuzlugumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Santor (MERAL TAŞKIN'' a)', 'santor-meral-taskin-a-mustafa-dogan-kuzgun-083ie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerindeki parıltıda gördüm sevgiyi

Sende gördüm, görmediğim ilgiyi

Bana sen öğrettin hayatı sevmeyi

Sanki sende varoldum santor.

Sevginle solan gülü yeşerttin

Umudunla ölüyü dirilttin

Sevgiyi, kardeşliği senden öğrendim

Sanki sende yaşıyorum santor.', 'Gözlerindeki parıltıda gördüm sevgiyi Sende gördüm, görmediğim ilgiyi Bana sen öğrettin hayatı sevmeyi Sanki sende varoldum santor. Sevginle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/santor-meral-taskin-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sabah Ve Ben Uykusuz', 'yine-sabah-ve-ben-uykusuz-mustafa-dogan-kuzgun-oke21', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin ilk ışıkları gözlerimde,

Sabahın rüzgarı yine dans ediyor,

Günün ilk anları, kuşlar huysuz

Yine sabah ve ben uykusuz.

Deniz bir başka bu sabah

Dalgalar sanki yüreğime çarpıyor

Sanki bugün deniz de susuz

Yine sabah ve ben uykusuz...', 'Güneşin ilk ışıkları gözlerimde, Sabahın rüzgarı yine dans ediyor, Günün ilk anları, kuşlar huysuz Yine sabah ve ben uykusuz. Deniz bir başk...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yine-sabah-ve-ben-uykusuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Vakti! ...', 'ayrilik-vakti-suskun-resital-agzvu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '..................Ayrılık vakti geldi! Kabus gibi karabulut gibi çöktü içime.Bundan sonra günlerim,sensiz nasıl geçer bilmiyorum ama,sensiz geçen her günümü,hiç yaşanmamış sayacağım.Taa ki sana yeniden kavuşuncaya dek.Her dakika her saniye seni anmasam da,kalbimde hep sensizliğin rahatsızlığını hissedecek ve hep o an ki halini merak edeceğim.Biliyorum ki bir gün buralardan gittiğinde artık,ne bu şehir ne de ben aklına gelmeyeceğim ancak resimlerde belki de mektuplar da kalacağım.Ve geriye dönüp baktığında benim için,iyi bir insandı diyebiliyorsan,ne mutlu sana,ne mutlu sana...

....................Doğru mu olurdu yoksa yanlış mı bilemiyorum ama,seni öpmediğim ve koklamadığıma yandığım kadar da,bundan mutluluk duyabiliyorum çünkü,ben seni bunlar için sevmemiştim bana senin o eşsiz varlığın yetiyordu zaten.Bir şeyler var ki sana nasıl anlatsam bilemiyorum,inan anlatması o kadar güç ki! Yine de birgün güneş üzerimize doğar,aynı yağmur damlası ikimizide ıslatırsa,ben anlatmış,sende anlamış olursun...Ve dilerim birgün sevdiğim,aradığını kaybettiğin yerde bulursun...Hoşçakal büyük sevdam...', '..................Ayrılık vakti geldi! Kabus gibi karabulut gibi çöktü içime.Bundan sonra günlerim,sensiz nasıl geçer bilmiyorum ama,sensiz ...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ayrilik-vakti-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'K a r ı ş ı k ş i i r...', 'k-a-r-i-s-i-k-s-i-i-r-zafer-zengin-etnika-wifq9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

dağlar/

küstüm

dört duvar olmuş dağlara

çağırmayın beni cenginize

vurdukça

çocuklar gelir aklıma

sokmayın gece düşlerime

elinde yağlı ekmek ağlayanları

ölenler/

ki; en iyi şeydi savaş

tanrı gibi gezinen  soytarılar

hırs oyuncaklarını alıp

düşerlerdi meydanlara

illa ilk kursun

gülümseyen çocuklara

barış/

kendim için istiyorsam namerdim

ütopya/

çiçekler var elimde

cennet sosyalist kokular sürmüş göğsüne

herkes

biri birine şeker verme derdinde

huriler yok

dem tutmuş yüzler

bir birine gülerler

kapalı

tadilatdayız

ve mesela /

çok şey dolardı bardağa

gözyaşı mesela

çay /

renk dedikçe

külü olsa

kırmızı boyansa

ağzında sigarayla

denize sarılan adamı anla

işte böyle

keyif rüzgarı çarpar bağrına

aşk /

orda sus/an kazanır

ayrılık /

gelirken yol sormuştun

dolandın durdun

kavuşup kavuşup bir akıyordun

dolanıyordun

işin çıkıyordu her gece

uyuyordun

köşe /

suyu arıyordu

burnunun dibinde

kanla sarılmış gölge

tutar eli

ılık kanı işte

görünmez

o kadar yakın dişe

sus/

tanımadığım

tanınmadığım tek yer

tek hece

körpedir kendince

özledim sen gelmeyince

kalabalık/

parmaklarımı saydım

yalnız değil

k/alabalıkmışım

boş /

kahve fincanı

fal satıcısı

ihanet

gölgenin ressamı

hala

mutluluğun resmin yapamadı

nasır /

- nasıl bilirdiniz

azrailin kılıcıdır

keser kan akıtmaz

güleni unutmaz

içi sevda

dışı naz

olsa sonbahar

olmasa yaz

mülteci/

içimde sınırlarım

köşe bucak kaçamam

14 03 2005

.', '. dağlar/ küstüm dört duvar olmuş dağlara çağırmayın beni cenginize vurdukça çocuklar gelir aklıma sokmayın gece düşlerime elinde yağlı ekme...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/k-a-r-i-s-i-k-s-i-i-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni hatırlatmayacak bir yer...', 'seni-hatirlatmayacak-bir-yer-zafer-zengin-etnika-dj7p4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

seni hatırlatmayacak bir yer

birin olduğu yer/

madem ki sevda

erkek adama

zırhından kopan parça

soyunup eski yüz yıllara

yüreği takmalı

mızrağın ucuna

toz kalkmasın...

İki gelmemişti /

iki yüreğin cephesidir

| ahh çok yenildim kendime..gücüm yettiğince |

seyreder al''ı can

aşkta arada kalan

rahvan atın sesidir

titreten iç''i

şimdi 

kaybetmeli

üç yukarıda yenilmişti/

hem köylünün işi ne ki

şovalye ölmedi mi

kadına uzak bakış /

seni hatırlatmayacak yer var mı

kan gibi

güz

kendi rengi olmalı

gitmeli

ses çakar birazdan

dal kopar

hatırlanmaz

iç göçtüğünden beri

iç çökmeli

kopan parça

yerine gelmeli

ara taksim gülen adamın iç''ten soğuması/

iğne ucu

mavi sıcak

ah sıcak

can yakacak

umut var

uzak el

batıyorsun ya

dört ona sevdalı hala/

hatırla yakacak

hatırlı sıcak 

ağır okusaydınız keşke

22.01.2005

.', '. seni hatırlatmayacak bir yer birin olduğu yer/ madem ki sevda erkek adama zırhından kopan parça soyunup eski yüz yıllara yüreği takmalı mı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/seni-hatirlatmayacak-bir-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmedin', 'gitmedin-mustafa-dogan-kuzgun-xl1dd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni görüyorum sigaramın dumanında

Gene gülüyorsun gözlerin ayışığı gibi

Karanlık odamı bir zerre olsun aydınlatıyor.

Bir nefeste içime çekiyorum

Zehir gibi damarlarımdasın

Gene de içimi aydınlatıyorsun.

Seni görüyorum mavi göklerde

Bulutların arasından göz kırpıp

Gene ısıtıyorsun güneş gibi.

Bir solukta içime çekiyorum

Gökyüzünden gelen nefesini

Gene de içimi ferahlatıyorsun.

Seni görüyorum şimşeklerin parıltısında

Nisan yağmuru gibi tenimdesin

Gitmedin, sen gene de benimlesin...', 'Seni görüyorum sigaramın dumanında Gene gülüyorsun gözlerin ayışığı gibi Karanlık odamı bir zerre olsun aydınlatıyor. Bir nefeste içime çeki...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitmedin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S e v g i l i m e d e r d i ...', 's-e-v-g-i-l-i-m-e-d-e-r-d-i-zafer-zengin-etnika-eysbc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

Ciddi olanlar

Yırtılan göğün sesi kadar

Memede süt

Çocuk ağzında hayat

Isırma elleri mi.. şiir yazıyorum /

Gece dertleri değil

Şu sancının çıkardığı ses

Ağlar sanıyorsun martıları

O kadar uzakları olmadı

Ne de yakınlarında sevdaları

Bir balık kaçıyor gözüme /

Dinleyiciler koşuyor

Yangın varmış bir yerlerde

Yüzlerine bakıyor

Hangi gözden ateş çıkacak

Onu sayıyorlar / biraz zor

Ben kedileri seviyorum.. her mart kedi oluyorum /

Çılgınlığı tutmuş o tekne

Seni bırakırken o yerde

Kayalara yapışmış midyeler

Küsüyorlar denize

İçinde olup kaçmak böylesine

Sevgilim derdi.. sonra gülerdi

Bildim ki; 

İstanbul ve 

on martı

sevgilim ederdi

Kedi öldü.. martı göçtü.. istanbul çök’tü

Severken bile istanbul hüzündü

Bahçelerine bakın

Hüzün gülüydü

Kedi gülden öldü

14 05 2005

.', '. Ciddi olanlar Yırtılan göğün sesi kadar Memede süt Çocuk ağzında hayat Isırma elleri mi.. şiir yazıyorum / Gece dertleri değil Şu sancının...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/s-e-v-g-i-l-i-m-e-d-e-r-d-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyor', 'agliyor-mikdat-bal-ir2xs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlüm hüzün dolu, neşeden yoksun

Yaşlar şıpır şıpır, gözler ağlıyor

Hayalin gözümde yanımda yoksun

Dilimde kıvranan sözler ağlıyor

Virane gönlümün baykuşu öter

Yanlızlık çok acı, ölümden beter

Bitsin şu ayrılık, artık gel yeter

Geç’lerden geçmişim tezler ağlıyor

Nazlanmasın artık gaddar tarafın

Nerde merhametin, nerede affın

Yaktın kül eyledin yok mu insafın

Beni kül eyleyen közler ağlıyor

Bal der benim sabrım bittikten beri

Birbirine veda ettikten beri

Ardına bakmadan gittikten beri

Evde senden kalan izler ağlıyor', 'Gönlüm hüzün dolu, neşeden yoksun Yaşlar şıpır şıpır, gözler ağlıyor Hayalin gözümde yanımda yoksun Dilimde kıvranan sözler ağlıyor Virane g...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agliyor-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su sızıya bağlandı...', 'su-siziya-baglandi-zafer-zengin-etnika-s8x8h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

bir |

kağıda sığınır harfler

şiir düşer

körpenin dudağına

düşer göz karanlığa

kanatır

elleri şişer

ad koyar bakışa

ağlar kırılma

paris ölür

helen darılır hayata

ağlar truva 

ağlar bahtına

kanlı kılıç uçlarında

iki |

sızının eli varsa

unutmalar yok arsıza

acıtsa da

yollar  uzunsa

yaşa bağla

şiir kondu dudağına

anımsa

yer altına iner  su

sahipsiz kalınca

akması

inceden inceye kanama

üç |



bilirim gecedir

ellerin en sıcak sesi

söyle 

içim içinde

titreşmen gülümseme

bendim ses içinde fısıltı

sen yüreğe girince

uyku gelir ötelere

dinlemeden gitme

dört |

kadının sevinci

ismin şiir hali

düşer gül 

şiir katar suyuna

körpe ağlar canıyla

can kırılır kurudukça

suyu anla

anımsa

gelmesin yüreğin ağzına

düşündüm yazmayı rüyamda

beş |

üryan düşme karşıma

aklıma zarar

bırakma ortasına

yaşamak zor susun da

unuturum sonra

ayaklarımı yollarda

altı |

siper kaz dalgalara

kıyısında denizin

en sessizin

maviliğin

yeterse gücün

hasret koy karşısına

tuzlansın bekleyenin elleri

son |

zamanın sabırlı yoldaşı

umut kaldı

adını bağışladı

su sızıya bağlandı

14 05 2005

.', '. bir | kağıda sığınır harfler şiir düşer körpenin dudağına düşer göz karanlığa kanatır elleri şişer ad koyar bakışa ağlar kırılma paris ölü...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/su-siziya-baglandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günü Gördüm', 'gunu-gordum-orhun-basat-srbpn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

dünden sıyrılmış / yarını hissetmeyen

içinde yokluğu oluşturan mutlak sessizliğin 

parmak uçlarına basmış / bekliyormuş yeni gün 

gizlenip  tebessümüne

bir damla yağmur yüreğim / bir avuç toprak ve tohum 

umudun bahara yatkın kozasında

ben kelebeğin son rengi 

paletinde bulduğum 

dur / dinle şimdi..

yaşlı bir ağaç türkü söyleyecek / fidan edasında 

yüreği yoksul güvercin duyacak bu ahengi 

II

açık kalsın penceresi sevişmelerimizin 

çünkü  hep eksiğini arar insan 

ellerin / titremelerin dokununca geceye

uykusuzluklarım seni giyinecek 

rengine boyadığım duvardan 

yosunlu hüzünler silinecek 

bir düş yaktığımda uzattığın sigaradan 

III

suya değdi ayaklarım çöl gecede / günü gördüm 

ne ezgiler varmış duyulmadık

bildik yağmur sesinde / 

nefesime karışan nefesinde

sil beni / yeniden yağmurlara yaz 

ertelenmiş doğumlarda 

gözlerimde ışıdığın bu vakit

hadi git şimdi / bana git..

IV

ellerimin tılsımı / sen / kadınım 

uzun soluklu acılar sanatıdır aşk 

ben / yıllarca unutturulmuş adınım 

yarı/n/ım..', 'I dünden sıyrılmış / yarını hissetmeyen içinde yokluğu oluşturan mutlak sessizliğin  parmak uçlarına basmış / bekliyormuş yeni gün  gizlenip...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gunu-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendim', 'bendim-serhat-karadumanli-upuv1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen nereden bileceksin  be peri kızı

Şu suyun ötesinden 

Bir adım bile uzaklaşamazsın ki! 

Şu bir damla gözyaşım kadar suya mahkumsun...

-Hoş ben de sana-

Binlerce yıldır gördüğün göreceğin sadece

Şu gölcükteki nilüferler

Bir de balıklar.

Ha bir de salkım söğütler

Severler suyu çünkü çok...

Oysa ben

Yüzbinlerce yıldır yarenlik yapıyorum tarih babaya...

.......... Tanrıları bile korkutan Typhon''un fırtınalarında

Açıp kanatlarını süzülen bendim.

Bendim kılavuzu

Hephaistos''tan ateşi çalarken Prometheus''un.

Akheron''da kana kana susuzluğunu gideren bendim.

-Hades''in bile ağzı bir karış açık kalmıştı-

Bendim 922''de Bağdat''ta derisi yüzülürken Mansur''un

Tüyleriyle sarmalayan yaralarını.

Jean D''arc'' ın küllerini 1431'' de geleceğe savuran bendim.

Bendim Tupac Amoru''nun heybetini 1572'' de

Condor''lara armağan eden.

Osman Nevres''e 1919''da o ''ilk kurşun'' u veren bendim.

Bendim 19''unu gösterirken takvimler bir senenin sonunda

Simurg''larla ateş dansı yapan...

....... Sen nereden bileceksin be peri kızı

Şu suyun ötesinden

Bir adım bile uzaklaşamazsın ki! 

Şu bir damla gözyaşım kadar suya mahkumsun

Binlerce yıldır gördüğün göreceğin sadece

Şu gölcükteki nilüferler

Bir de balıklar. 

Ha bir de salkım söğütler

Severler suyu çünkü çok.

Oysa ben... 

(Ağustos 2005)', 'Sen nereden bileceksin  be peri kızı Şu suyun ötesinden  Bir adım bile uzaklaşamazsın ki!  Şu bir damla gözyaşım kadar suya mahkumsun... -Ho...', ARRAY['Türk Edebiyatı','Şiir','Serhat Karadumanli']::text[], 8.5, '{"poet":"Serhat Karadumanli","poet_slug":"serhat-karadumanli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bendim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz kızları Mani - deneme', 'karadeniz-kizlari-mani-deneme-mikdat-bal-ep893', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir başkadır bakışı

Gözden kalbe akışı

Acıdır can yakışı

Karadeniz kızları

Neşe sevinç saçarlar

Güller gibi açarlar

Yaklaşırsan kaçarlar

Karadeniz kızları

Ateş saçar gözleri

Tatlı olur sözleri

Naz cilvedir özleri

Karadeniz kızları

Bülbül gibi dilleri

Açar gonca gülleri

İnce olur belleri

Karadeniz kızları

Endamlı boyludurlar

Çok asil soyludurlar

Ahlaklı huyludurlar

Karadeniz kızları

Kaşları yay gibidir

Yüzleri ay gibidir

Mertlikte bay gibidir

Karadeniz kızları

Onlar hile bilmezler

Kolay yola gelmezler

Yabancıya gülmezler 

Karadeniz kızları

Onlar yapar işleri

Var hayali düşleri

Dünya da yok eşleri

Karadeniz kızları

Mikdat der böyle imiş

Aradan yıllar geçmiş

Bilmem şimdi ne etmiş

Karadeniz kızları', 'Bir başkadır bakışı Gözden kalbe akışı Acıdır can yakışı Karadeniz kızları Neşe sevinç saçarlar Güller gibi açarlar Yaklaşırsan kaçarlar Kar...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/karadeniz-kizlari-mani-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir hazine buldum', 'bir-hazine-buldum-mikdat-bal-ioitv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıkılan dünyamın, enkazlarında

Bir hazine buldum sabırdır, sabır

Hayatın akışı çıkmazlarında

Bir kurtuluş buldum kabirdir, kabir

Bu dünya yalancı bir dünya imiş

Emel, arzu, dilek, hep hülya imiş

Hayatımın tümü bir rüya imiş

Ölüm bu rüya ya tabirdir, tabir

İnsanın maddesi yürüyen bir leş

Canı çıktığında çürüyen bir leş

Böcekler yiyerek eriyen bir leş

İnsanı mahveden kibirdir, kibir

Affetsin meccanen Ol Ulu Hünkâr

Rabbe teslim oldum böyle günahkar

Her ne işlemişsem gizli aşikâr

O her şeyi bilir Habirdir, Habir', 'Yıkılan dünyamın, enkazlarında Bir hazine buldum sabırdır, sabır Hayatın akışı çıkmazlarında Bir kurtuluş buldum kabirdir, kabir Bu dünya ya...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-hazine-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum be ustam...!', 'seviyorum-be-ustam-yurdagul-kurnaz-bt5f7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ciraga sormuslar; isini severmisin? 

Dikeni batsada güllerin, ekermisin? 

Seviyorum be ustam! 

Sevgidir yol alir, diyar diyar gezdiren

Sevgidir gülünün dikenini sevdiren

Seviyorum be ustam! 

Dostun acisi, acim oldu sol yanimda

Sevmekse hüner; ordayimdir, olmasamda

Seviyorum be ustam! 

Mutlulugun pesin sira kosar dururuz

Sevmekse; ömürde bir anlik,unuturuz

Seviyorum be ustam! 

Aci, gam, kederi; yazilan bu kaderim

Güller kan aglasada, ben yine gülerim! 

Seviyorum be ustam!', 'Ciraga sormuslar; isini severmisin?  Dikeni batsada güllerin, ekermisin?  Seviyorum be ustam!  Sevgidir yol alir, diyar diyar gezdiren Sevgi...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seviyorum-be-ustam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik yıldönümü...', 'evlilik-yildonumu-ercan-eyvaz-177kc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıcak bir havada, buz gibi suyumsun

Meşrubatım, sıcak bir çayım, umudum

Gözlerinle rahatlatan ruhumu

Tek sırdaşımsın, hayat arkadaşımsın 

Tanıdım, İyi ki tanıdım seni.

Evlilikten bugüne... 

Bunca zaman, yalnız bırakmayışın 

Hastalıkda sağlığımda,ağladığımda,güldüğümde 

Tek destek verenim sen oldun bana

Büyüdü çocuklarımız, ak düştüde saçlarımıza

Döküldü tek tek, her kes gitti kendi yoluna

Biz yine değişmeyen iki küçük odada

Kaldık seninle ilk günki gibi baş başa.

İyiki sen varsın karıcım 

Sen iyiki yanımdasın 

Sen olmasaydın 

Ne yapardım tek başıma …

Seninle nice yıllara …', 'Sıcak bir havada, buz gibi suyumsun Meşrubatım, sıcak bir çayım, umudum Gözlerinle rahatlatan ruhumu Tek sırdaşımsın, hayat arkadaşımsın  Ta...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/evlilik-yildonumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her şeyin zıddı var!', 'her-seyin-ziddi-var-mikdat-bal-9fn9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her ne olursa olsun, buna sevinenler var 

Onunla gurur duyup bir de övünenler var 

Diğer yandan üzülüp hem de dövünenler var 

Her şey iki boyutlu, her şeyi böyle görün! 

Her şeyin bir zıddı var dünyada budur kanun

Mesela bir maç düşün, ya senindir ya onun

Eğer kaybetti isen bu da değildir sonun! 

Bencillikten kurtulup biraz empati kurun! 

Her olay aynı anda, hem güzel hem çirkindir 

Her şey içinde mevcut, birbirine girgindir 

Bakarsın iki gurup, araları gergindir 

Olay olup bitmişse, çıkar yeni bir sorun 

Ne kadar acı olsa gerçek böyledir beyler 

Taraftarlık doğaldır, değişmez bazı şeyler 

Bir kısım alkışlarsa, bir kısmı da vah söyler 

Geniş olmak gerekir, buna da kafa yorun 

Kâr ve zararını bil, ne keser ol, ne rende 

Hızar ol müşterek ol, bir sende bir de bende 

Birbirini anlarız bu bilince erende 

BAL der çok şey hallolur, çözülür birçok sorun

 Ozan Mikdadi', 'Her ne olursa olsun, buna sevinenler var  Onunla gurur duyup bir de övünenler var  Diğer yandan üzülüp hem de dövünenler var  Her şey iki bo...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-seyin-ziddi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana senden nice senler gerektir', 'sana-senden-nice-senler-gerektir-i-lhami-arslantas-3sqqx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk eyle figanım dindir acını

Sev gönülden halkın giydir tacını

Yetimin mazlumun ver ilacını

Sana senden nice senler gerektir

Sevindir yetimi tüttür bacasın

Ezilmiş horlanmış garip nicesin

Can ümükten çıksa bir bilmecesin

Sana senden nice senler gerektir

İşte geldi çattı tecelli  yakın

Ölüm var yarında dürülür çıkın

İnsanı kırmaktan üzmekten sakın

Sana senden nice senler gerektir

Der İlhami sevdam bu garip canlar

İnsanın gönlüne girenler anlar

Az  ile yetinen erdemli onlar

Sana senden nice senler gerektir', 'Aşk eyle figanım dindir acını Sev gönülden halkın giydir tacını Yetimin mazlumun ver ilacını Sana senden nice senler gerektir Sevindir yetim...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-senden-nice-senler-gerektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Çınar', 'koca-cinar-ahmet-turan-altunsu-lr1q5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mutluluğunuzu siz

mevsimlik çiçeklerde arayın

ben kocamış bir çınarım

öyle serpme suyla yanıma yaklaşmayın

ta kök uçlarımdadır saçaklarım

gövdem size tepkisiz! 

gövdemde dinlenirdiniz sıcak mevsimlerde

döşeğiniz hazanda yapraklarımdı

yuvarlanırdınız gölgemde / yerde

üryân halime hayran, resimlerken üzerimdeki kışı

yaşlı gövdemi her dem ayakta tutan

toprağı kucaklamış köklerimdi / saçaklarımdı

anlamadınız değerimi

oysa mevsimlik çiçeklerinize özenle baktınız

gölgemde alevlendirdiğiniz mangalınızla

gövdemi ağır ağır yaktınız

sessiz göz yaşlarımla

beni bir başıma bıraktınız! 

hatırlayın gövdeme çaktığınız paslı çivilerinizi

kör baltalarınızı / nasıl da vururdunuz? 

koparırdınız kozalaklarımı henüz olgunlaşmadan

/ ne de korkusuzca kullanırdınız ellerinizi

dallarımda salıncaklarınızı hoyratça savururdunuz! 

siz, mevsimlik çiçeklerde arayın mutluluğunuzu

ben ki koca çınar / kocamış çınar / ölümsüz bilirsiniz

hep vardınız dededen toruna

hiç görmedim yokluğunuzu

lâkin artık vakit tamam

çıkar mıyım çıkmaz mıyım yarına

anlayamadan kıymetimi henüz siz

artık ölümümü görebilirsiniz! ..

mevsimlik çiçeklerde arayın mutluluğunuzu siz

dünü gördünüz / bugünü görüyorsunuz / yarını göreceksiniz

bir de köklerimin özlemiyle yanıp tutuşacak olan

yaşlı toprağın efkârını göreceksiniz

müşfik kollarına sarıldığınız zaman! 

ah vefasız yaratıklar:

siz var ya siz! 

__________________ 07.08.2005 / Ankara

_________________ Ahmet Turan Altunsu', 'mutluluğunuzu siz mevsimlik çiçeklerde arayın ben kocamış bir çınarım öyle serpme suyla yanıma yaklaşmayın ta kök uçlarımdadır saçaklarım gö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/koca-cinar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlikte Son Akşam', 'sensizlikte-son-aksam-nevzat-erkol-ld3rg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denize salsam ellerimi

Tenindir dokunduğum

Bağrımı rüzgârlara versem

Serinliğindir duyduğum

Gecelere koyduğumda kendimi

Gözlerindir sokulduğum

Bitti, dediğim anlarda 

Umutlarımdır bulduğum

Guruba çağrılıyım bu akşam

Özleminde solduğum.', 'Denize salsam ellerimi Tenindir dokunduğum Bağrımı rüzgârlara versem Serinliğindir duyduğum Gecelere koyduğumda kendimi Gözlerindir sokulduğ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Erkol']::text[], 8.5, '{"poet":"Nevzat Erkol","poet_slug":"nevzat-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizlikte-son-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marmaraya Attım Sesimi', 'marmaraya-attim-sesimi-galip-ozdemir-wb3yx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'avcunda bir yıldız,

mışıl mışıl...

boynunun altında dirseğim.. 

akdeniz ayaklarını öpsün,

akdeniz nefesi boynunu.. 

tül uçuşsun açık kalan pencerenden 

yakamozlar uykularına su serpsin 

ve bir şair sesi kulaklarında; 

sen,

kimse

ve ben

uyanmadan 

yıldızlara dönsün.', 'avcunda bir yıldız, mışıl mışıl... boynunun altında dirseğim..  akdeniz ayaklarını öpsün, akdeniz nefesi boynunu..  tül uçuşsun açık kalan p...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/marmaraya-attim-sesimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölenle Ölünmüyor', 'olenle-olunmuyor-selahattin-olmez-j0qg3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖLENLE ÖLÜNMÜYOR

Rüyalar görüyorum sen yanımdasın mezarda,

Gezdim gördüm şebboylar açmış,güllerin lalezarında.

Bizler mücadeleye tabiiyiz,halen,sen ise şimdi huzurda,

Hasretim sana baba,özledim seni tüm zamanlarda…

Diyorlar ki senin sözün tutup,sana umut bağlayan,

Mezarına gelip,diz çöküp te dua ederek,ibretler alan,

Umduğunu bulurmuş,her daim ve her zaman……

Dualar edip te sana,Senin feyzini almaya geldim….

Sevda şerbetini içemedin son zamanlarında,

Güller goncalar tam açmadan lalezarında,

Saygıya sevgiye,hizmete doyamadan daha dünyada,

Göç ettin gittin,bıraktın bizi yalnız,hasretin ve sevdanla..

Yazdırdım mermerine,okunsun diye sana her dem Fatiha,

Fatiha okuyanlarda nasiplensin senin tahtında,

Ecel kapıyı çalınca,günün bilinmeyen bir anında,

Meleklerden yardım umdum,mezarının başında…..

			02.MAYIS.2005

		Babamın ölüm yıldönümü

	         Selahattin Ölmez', 'ÖLENLE ÖLÜNMÜYOR Rüyalar görüyorum sen yanımdasın mezarda, Gezdim gördüm şebboylar açmış,güllerin lalezarında. Bizler mücadeleye tabiiyiz,ha...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olenle-olunmuyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sımsıcak', 'simsicak-selahattin-olmez-ua3vl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SIMSICAK

Sözlerin içimi ısıtır konuşunca,

Bir sıcaklık vardır tüm kelimelerinin ucunda.

Ateş gibi esen,rüzgar gibi,yel gibi,meltem gibi,

Akar gider cümle olur bir biri ardı sıra,

Irmak gibi,nehir gibi,coşkun akan sel gibi..

Öyle sıcak ve içten konuşursun ki,

Karı erimemiş dağlarda bile açar mor menevşalar

Güller,çiğdemler papatyalar, lale,sevdiğim leylak,

Sen öyle konuşursun ki konuştuğun zamana

Ateş gibi sımsıcak,

Şu yüreğim seni hiç unutmayacak…….,

Çapa yapardık köy dışındaki tarlada,

Otları bile kesmeye kıyamazdın o anda,

Toprağın sıcaklığını anlatırdı sözlerin,

O sıcaklığı bana nasılda yansıtırdı gözlerin.

Ve ceylanlar gibi, sekerdi dilinde kelimelerin,

Sevdayı anlatırdın,yaşamı,yaşamın acımasızlığını anlatırdın,

Otları bile öldürmenin,merhametsizlik olduğunu,

Dağların,bulutlarla; Irmakların denizlerle sevgiyle buluştuğunu,

Bulutların sevenleri sıcaktan koruduğunu,

Öyle güzel tümcelerle anlatırdın ki:Sımsıcak

Şu yüreğim seni hiç unutmayacak……

Gün biter akşam olur elinde oya,

Gir demet kır çiçeğiyle dönerdin yuvaya.

Ve asla unutmazdın selam vermeyi,

Merhaba diyerek,sımsıcak bir edayla.

Sanki en yanık türküleri söylersin,

Ve işlesin,kelimelerinle yüreğime, işlersin

Sen öyle konuşursun ki akşamları yanı başımda,

Isıtırsın yüreğimi:Sımsıcak,

Şu yüreğim seni hiç unutmayacak……



Zaman gelir çapa yapar pamuk toplardık,

Sarı,beyaz açan papatyalar var ya,hani taç yapardık,

Ben sana,sen bana,birbirimize takardık

Laf olsun diye tibili kuşlarına taşlar atardık,

Ürkütünce onları,yine dillerinden dökülürdü kelimeler,

Sevgi dolu sımsıcak; 

Sevgi bu değil derdin,ürküttüğün kurt,kuş bile olsa.

Ve üzülürdün,bu sefer onlara ağıt yakardın,

Sen öyle konuşurdun ki; sevda üstüne:Sımsıcak,

Şu yüreğim seni hiç unutmayacak…..

Ve hala durur gözlerimin önünde hala o anılar,

Ömrümüzden geçmiş olsa da çoktan yarılar,

Çoğalmış olsa da saçlarımızdaki beyazlar,

Yine de hiç eksilmeden sımsıcak dökülür dillerinden,

Sıcacık kelimelerle dolu billurumsu anılar…

İkimiz birlikte içtik seninle sevda şerbetini,

Bir film şeridi gibi geçse de  yıllar.

Geride kalsa da,paylaşılmış ve yaşanmış,

Bazen özgürce,bazen yasaklanmış,

Ateşi sönmüş olsa da bazen,bazen umutlar tükenmiş,

Sen öyle anlatırsın ki,cümlelerin umut üstüne; Sımsıcak

Şu yüreğim seni hiç unutmayacak…….

Ömür bitiyor diye yeislensede insanlar,

Kaybolan zaman içinde,ah edip ağlayanlar,

Sevgiyi bir kerecik olsun yaşamayanlar,

Seni dinlesin,seni izlesin örnek alsınlar,

Gönül gözlerini açsın sana kulak versinler..

Sen öyle konuşursun ki hayat üstüne; Sımsıcak.,

İşledin sevdanla yüreğime

Sen ve senin sevgin yüreğimden hiç çıkmayacak………………

						SELAHATTİN ÖLMEZ

						 26,MART,2005', 'SIMSICAK Sözlerin içimi ısıtır konuşunca, Bir sıcaklık vardır tüm kelimelerinin ucunda. Ateş gibi esen,rüzgar gibi,yel gibi,meltem gibi, Aka...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/simsicak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Tükenince', 'sevda-tukenince-selahattin-olmez-7wwsc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEVDA TÜKENİNCE

Issız gecenin sessizliğinde uyandım,

Uykularımdan.

Dizeler dizilmişti dizi, dizi seherde,

Tan yerinin ağardığı erken saatlerde,

Al kalemi yaz diyordu sanki yürek,

Ta derinlerden gelen garip seslerle…….

Ürpertiyordu seher vakti beni,

Üşütüyordu sanki  eserken,

Yarık kaya timsali bir rüzgar.

Islanıyordu sanki gönül çiçeklerim,

Yeşili yeşerten şebnem damkacıklarının,

Domurcuklarıyla…

Sevda dünyalarında,

Görsel gösteriler düzenliyordu,

Sevenler oturmuş seyrediyor

Gönlünü hoş edecek güzeller arıyorlarda.

Ve bir hançer saplandı yüreğime

Sanki yüreğim oldu toprak.

Ve o toprak beni unutmamış olacak

Aldı beni bitirdi,kendinden olan yaşamımı,

Ve yıkıldı dünyam ve tüm hayallerim….

Sormayın hüzün kimin adressi,

Alacağı varsa dünyanın gösterin beni.

Sevda değimlidir dünyadaki yaşantının değeri,

O Kalmayınca,gök kuşağı olsun benim

Mezarımın kemeri………..

   

			Selahattin ÖLMEZ

			 02,04,2005', 'SEVDA TÜKENİNCE Issız gecenin sessizliğinde uyandım, Uykularımdan. Dizeler dizilmişti dizi, dizi seherde, Tan yerinin ağardığı erken saatler...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevda-tukenince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Vakti Sessizliğinda', 'seher-vakti-sessizliginda-selahattin-olmez-60jsa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEHER VAKTİ SESSİZLİĞİNDE

Seher vakti sessizliğinde,

Bedeninde sıcaklığımı hissediyorsan,

Nefesimi hissediyorsan teninin yumuşaklığında

Ve nidalarım uğulduyorsa kulaklarında,çınlarcasına,

Ve o kulaklar bir şeyler işitmek istiyorsa

Dillerimden; 

Sevgiden,aşktan,sevdadan yana…

Seher vakti sessizliğinde,

Yalnızlığına ortak olmamı istersen,

Alaca karanlıklardan kurtulmak

Güneşin pırıltılı ışıklarına koşmak istiyorsan,

O güneşi yakalamak,kucaklamak,sarılmak

Ve yeni bir güne başlamak istiyorsan

Sahiden; 

Ve bir sevda varsa o yüreğinde saklı,

Hayatı benimle paylaşmaktan yana.

Koşa,koşa gelirim sana

Seher vakti sessizliğinde

Ve yaşamın tüm zamanlarında…….

			SELEHETTİN ÖLMEZ

			  11.NİSAN.2005', 'SEHER VAKTİ SESSİZLİĞİNDE Seher vakti sessizliğinde, Bedeninde sıcaklığımı hissediyorsan, Nefesimi hissediyorsan teninin yumuşaklığında Ve n...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seher-vakti-sessizliginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama Veda', 'babama-veda-selahattin-olmez-jkm42', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BABAMA VEDA

Ellerimle aldım seni, ben musalla taşından,

Belki binlerce dostun yürüyordu ardından,

Helallik verdiler kılınan namazının ardından,

Hakka teslim etmeye hazırladık,biz seni.

Yolculuk başladı,musalla taşı başından,

Bir mücevher gidiyor, omuzların üstünden,

Senin için ne söylenir,ne dökülür dillerden

Nasıl iz bırakmışsan,dostlar üstünde…..

Biliyordun elbet, doğanlar,bir gün ölecek

Yaşadığı dünyadan bir gün göçüp gidecek,

Akıbetin nasıldır,kimler nerden nasıl bilecek,

Ancak bir Allah bilir,bir de dostların seni….

Doldurduysan yüreğini,sevgiye değer,

İmanınla birlikte,borçsuzsan hakka eğer,

Mal,mülk,makam,hepsi seni terk eder,

Yoktur götüreceğin oraya kendinden gayrı.

Söyleyeyim sana,ardından neler oluyor,

Senin yokluğuna yalnız dostlar yanıyor,

Her kes seni anlatıp iyi yanın söylüyor,

Cismin gitti toprak oldu,ismin kaldı dünyada….

				SELAHATTİN ÖLMEZ

					02.MAYIS.2005', 'BABAMA VEDA Ellerimle aldım seni, ben musalla taşından, Belki binlerce dostun yürüyordu ardından, Helallik verdiler kılınan namazının ardınd...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/babama-veda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan dünyaların Üstüne', 'sevdan-dunyalarin-ustune-selahattin-olmez-rzof8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEVDAN DÜNYALARIN ÜSTÜNE

Seni özlemişim ben,

Toprağın nisan yağmurlarına özlemi gibi.

Seni özlemişim ben,

Arının çiçeğe özlemi gibi.

Öylesine özlemişim ki seni 

Özlediğim sevgin hayat veriyor bana,

Nil’in sahralara hayat verdiği gibi….

Sevgin güneşe benzer senin,ısıtıyor içimi,

Anlaşılmaz bir huzur veriyor,

Mutluluk ırmaklarının serin sularını,

Akıtıyor yüreğime

Her anım senin sevginle dolu geçiyor,

Sevda türkülerin tespih oldu sanki,dillerime

Seni sevdim ben, sevdan,başım gözüm üstüne….. 

Sevdan dünyaların üstünde……

Kurgularım,

 Hep seninle yaşayacak olduğumuz yıllarımız üstüne,

Acılarımız,mutlu anlarımız üstüne

Olumsuzlukların olmadığı zamanların üstüne; 

Öyle kapılmışım ki senin güzelliğine,

Gözlerim görmüyor başka güzel,güzelliğin; 

Yeşilden bile,doğadan bile,dünyadan bile ehven,

Senin başka bir özelliğin var,

Sanki cennetten gelen,

Sen en nadide çiçeklerden daha da çok özlenen,

İsmi bende baki  gonca gibisin……

Seni özlemişim ben,

Sevdanı özlemişim ben,

Kulun Allah’a özlemi gibi.

Ulaşamasam bile sevda bahçelerine,

Dokunamasam bile sevgi çiçeklerine

Gözlerim hasret kalsa da gülücüklerine,

Sevdanı,ismini tespih yaparım dillerime,

Ben seni çok özledim,

Ben seni sevdim,sevdan başım gözüm üstüne,

Sevdan dünyaların üstüne…….

			SELAHATTİN ÖLMEZ

			  11,NİSAN.2005', 'SEVDAN DÜNYALARIN ÜSTÜNE Seni özlemişim ben, Toprağın nisan yağmurlarına özlemi gibi. Seni özlemişim ben, Arının çiçeğe özlemi gibi. Öylesin...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevdan-dunyalarin-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamam Ki', 'yasayamam-ki-selahattin-olmez-a94yk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YAŞAYAMAM Kİ

Dünyanın çatısı çatılmış sevgi üstüne,

İçinde sevgi olmayan kalbi taşıyamam ki.

Yaşamak için,ben bu dünyaya geldimse,

Ben sevgisiz,ben duygusuz yaşayamam ki….

Sevdalarım,umutlarım benzer aya güneşe,

Sevgiyle gecelerim gündüz olur,gamlarım neşe.

Sevgidir derim,yüreği kıpırdatan,benzer ateşe,

Ben sevgisiz,ben duygusuz yaşayamam ki….

Okusun dudaklar,yazsın kalemler,sevgiyi ansın,

Sevgi yüreğimdeki ateştir,her zaman yansın,

Sevdan benim tutkumdur,ve aşkın ilk heyecanım,

Ben seni zikretmesem dünyada,yaşayamam ki…

Yüreğim çarptıkça,durdukça bedende canım,

Desturunla dolaşıyor her daim,damarda kanım,

Sevgi yaşama tarzım,islamdır,dinim,imanım,

Hazzını tatmasam,bu dünyada yaşayamam ki….

Günleri geceleri,yıldızları görür gözlerim,

Ağacı yeşili,dünyada nimetlerini sever özlerim,

Bir mimarı vardır bunların,bunu bilir söylerim,

 Mimarını bilmediğim,bir dünyada yaşayamam ki,……

				Selahattin ölmez

				 12.nisan.2005', 'YAŞAYAMAM Kİ Dünyanın çatısı çatılmış sevgi üstüne, İçinde sevgi olmayan kalbi taşıyamam ki. Yaşamak için,ben bu dünyaya geldimse, Ben sevgi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasayamam-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceyhana Özlem', 'ceyhana-ozlem-selahattin-olmez-e983d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'CEYHAN’A ÖZLEM

Kar yağmıştır torosların başına,

Kardelenler boy vermiştir,dostuma,

Dinle dostum,bir ricadır bu sana,

Ben ölürsem,yad ellerde bırakma….

Karanfiller katre, katre açsa da,

Yaseminler,erguvanlar koksa  da

Gül dalında bülbüller hep ötse de,

Hiç birisi Ceyhan’ıma kokmuyor…

Bir vasiyet eyledim,ölmeden dostlarım size,

Doyamadın yaşarken Ceyhan’a Akdenize

Gezemedim üstünde toprağının güzelce,

Gömün beni Ceyhan’ımın toprağına sessizce.

				

Selahattin ölmez

					06,01,2005', 'CEYHAN’A ÖZLEM Kar yağmıştır torosların başına, Kardelenler boy vermiştir,dostuma, Dinle dostum,bir ricadır bu sana, Ben ölürsem,yad ellerde...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ceyhana-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-selahattin-olmez-3my3n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ANNE

Anne diye ağlarım,her insan gibi,

Canımı acıttığında yaşamın bütün halleri.

Ben ağlarken yanar seninde yüreğin bilirim,

Derdime derman olamadığın için üzülür,

Ezilirsin kendi dünyanda ve benim içidir 

Dilerinden akıttığın sevgi dolu sözleri….

Her rüzgar esişinde saçlarımı okşar sanki ellerin,

Umut sözcükleri döker bana,sımsıcacık dillerin

Sanki  bir dünya saklamaktadır içerisinde gözlerin

Seni hep bu halinle hayal eder,özlerim,

Ben gurbette çaresizce yatarken,

Yorganımı üstüme örtersin değil mi anne.

Sen çok uzaklardasın belki şu anda anne,

Zira hayalin yüreğimde yanımda içimde anne.

Omzuna yaslamışım başımı,okşuyorsun saçlarımı,

Gönül bağın var burada,sunuyorsun ilaçlarımı,

Başucumdasın almışsın ellerinin içine avuçlarımı,

Okşuyorsun beni sen,hayal olsan da anne…..

Her zaman en güzel anne benim annem oldu,

Hayallerimde de olsa.

Sen hayallerde bile bir gerçeksin anne,

Senin sevgin daima olmuştur yüreğimde,

Resmin duvarımda, sevgin yüreğimde,ellerin ellerimde,

Yeter ki sen sağlıklı bu bana yeter be anne…..

Ne yaptığın börekler,pastalar kekler,

Yetiştirdiğin bin bir türlü meyve, üzüm, çilekler,

Yoktan var eyleyip giydirdiğin giysiler,

Elinle pişirerek soframıza koyduğun taze çörekler,

Önemli değil,bana sen gereksin anne,

Senin için sağlıklı gelecekler…..

Anne diye seslenip nefesini dinlediğim geceler,

Hayallerimde değil,hep yanımda olmanı istediğim 

Ellerinle,dillerinle,nefesinle dolu gerçek seneler……….

					Selahattin ölmez

					  12,04,2005', 'ANNE Anne diye ağlarım,her insan gibi, Canımı acıttığında yaşamın bütün halleri. Ben ağlarken yanar seninde yüreğin bilirim, Derdime derman ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/anne-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sana geldim Anne', 'ben-sana-geldim-anne-selahattin-olmez-av5gz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BEN SANA GELDİN ANNE

Duvardaki resmime bakıp ta dalıyor muşsum,

Ne zaman gelecek diye hep arıyormuşsun

Ellerimi tutmak okşamak istiyormuşsun,

Duydum ki beni çok, çok özlüyormuşsun,

Bekle beni geliyorum üzülme,Ben sana anne.

Hala eski beni biliyor,bebeğim diyormuşsun,

Sıcacık kucağında beni uyutmak istiyormuşsun,

Büyüyüp serpildiğimi kabüllemniyormuşsun

Duydum ki her gün yolumu gözlüyormuşsun,

Bekle beni geliyorum üzülme,Ben sana anne..

Albümde alıp saatlerce,saatlerce bakıyormuşsun,

Yatağıma bakıyor hep beni kokluyormuşsun,

Bazen gömleklerimi kendin giyiyormuşsun

Duydum gurbetlerde yalnızlığıma üzülüyormuşsun,

Bekle beni geliyorum üzülme,Ben sana anne….

Her zil çalışında benim girmemi bekliyormuşsun,

Girmeyince de sukut-u hayal ediyormuşsun,

Sonrada sabır edip, içinden dualar ediyormuşsun,

Duydum ki,göz yaşlarını içine akıtıyormuşsun,

Bekle beni geliyorum üzülme,Ben sana anne..

O beni üzmek ister mi  diye, teselli buluyormuşsun,

Çaresizce her gün postadan mektup bekliyormuşsun,

Her an gelirim diye vazoya güller koyuyormuşsun

Duydum ki  canı sağ olsun,elbet gelir diyormuşsun,

Bekle beni geliyorum üzülme,Ben sana anne…

Dökme göz yaşlarını sana kurban olayım anne,

Saçının bir teline dünyalar veririm bilesin anne

Sen bana gel diyemem,ben sana gelirim anne,

Anladım ki hasretlik zormuş,çekilmiyor be anne,

Koştum ta uzaklardan üzülme,Ben sana geldim anne…

					Selahattin ölmez

					  1975—Jidanof', 'BEN SANA GELDİN ANNE Duvardaki resmime bakıp ta dalıyor muşsum, Ne zaman gelecek diye hep arıyormuşsun Ellerimi tutmak okşamak istiyormuşsun...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ben-sana-geldim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceyhan Nehri', 'ceyhan-nehri-selahattin-olmez-6axtt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'CEYHAN NEHRİ

Nehirlerin gem vurulmaz küheylanıydın sen,

Bir tarih gibi Toroslardan çağlayarak akarken,

Çevrendeki insanlara bereketli nimetlerin verirken,

Şimdi nasılda aheste, aheste akıyorsun derinden.

Üstüne barajlar mı kurdular senin,akmasın diye deli,

İnsanlara mutluluk sunsun, zarar vermesin diye seli,

Kim bilir kaç kavmin söyledi,Ceyhan türküsü dili,

İnsanları tarih boyu sürmüş belli ki sana sevgisi..

Şimdi suluyorsun çukur ovayı ağır, ağır derinden,

İnsanlık saygı duyuyor sana,belli oluyor yüzlerinden,

Sen akmasan dursan,onlar da duracak  edeplerinden,

Bereketi gidecek toprakların,bunu bildiklerinden..

Akar gelirsin dere tepe demeden  ta Pınar Başından,

Beslenirsin bulutların  suyundan gözün yaşından,

Gıda alısın hakkın varlığı; toprağı, taşı ve havasından,

Bereket sunarsın seni dost bilen insanlara rızk tasından.

Ovalarda,ekinlere otlara ağaçlara, bilumum nebatata,

Barajlarda,balıklara,yosunlara,bir cümle haşarata

Çevrende el açıp dua ile şükreyleyen top yekun insanlara,

Umut oldun,nimet oldun,rızık oldun,sen varlığınla,..

Çiftçiler,balıkçılar,hayat buldu sende, bütün insanlar,

Her katre suyunda bereket,çevrende cennet buldular,

Bereketli toprağında,Rab’lerine edep ile secde durdular

Toroslardan aşağıya inişinden,daim mutlu oldular…..

					15,05,2000

				SELAHATTİN ÖLMEZ', 'CEYHAN NEHRİ Nehirlerin gem vurulmaz küheylanıydın sen, Bir tarih gibi Toroslardan çağlayarak akarken, Çevrendeki insanlara bereketli nimetl...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ceyhan-nehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin liman Senin', 'yuregin-liman-senin-selahattin-olmez-3l2ur', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YÜREĞİN LİMAN SENİN

Sevginin filizlenip doğduğu yerde,

Kavuşmak özlemle sana,bir seher vakti

Sevda şarkıları dudaklarda bir güzel ezgi

Baksam gözlerinin içine,doya,doya bir seher vakti.

Gözlerin sanki bir ateş sanki deniz feneri,

Sığınsam yüreğinin limanlarına bir seher vakti…..

Ak Denizin sularında,bu gece yakamoz varken,

Fütursuzca sahilde koşsam seninle.

Ellerini avuçlarımdan hiç bırakmadan

Sığınsam yüreğine ben,sığınsam bir seher vakti.

Avuçların sanki bir ateş,sanki alev parçası,

Sığınmak istiyor yüreğine,yon bu sevdanın rotası…..

Zor geliyor,bu şehri sensiz bırakıp gitmek,

Yüreğimde vesvese,fikrimde sorularla.

Sevda şarkıları,dudaklarımda bir güzel ezgi,

Sığınmak istiyorum,ezgilerle yüreğine bir liman gibi,

Gözlerin bir ateş,yakıyor yüreğimi bir seher vakti,

Yüreğim bu gece açıklarda kalan sanki bir gemi,

Seninse ellerin güvecin gibi,telaşlı ve ürkek,ama yürekli,

Yüreğinse bir liman senin,sığınayım sana bir seher vakti…..

                                                                      SELAHATTİN ÖLMEZ

					 01.MAYIS,1976', 'YÜREĞİN LİMAN SENİN Sevginin filizlenip doğduğu yerde, Kavuşmak özlemle sana,bir seher vakti Sevda şarkıları dudaklarda bir güzel ezgi Baksa...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yuregin-liman-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Diyemem', 'gel-diyemem-selahattin-olmez-87o60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GEL DİYEMEM

Kimselere düş peşime sende,gel diyemem ki,

Şu güzel haftada peygamberi sev diyemem ki,

Gözleri görmeyen insanlara kör diyemem ki,

Elbet gün olur devran döner,görür onlarda..

Her duyduğum söze aldırmayıp  es geçemem ki,

Hazreti  Muhammet Peygamberim,vaz geçemem ki

O son Peygamber bilirim,başkasını ben seçemem ki

Elbet bir gün,insanlar tanıyacak onu bütün dünyada.

Birkaç güzel söz, kelam ile insanlar alim olmaz ki,

Son kez geldi peygamber,bundan gayrı gelmez ki,

O gül kokar idi ondan daha güzel güller kokmaz ki

Elbet bir gün insanlar o kokuyu koklar dünyada.

Yanlışlık yapınca insan bir kere zalim olmaz ki,

Nedamet duyup  af dileyen haktan,nakıs olmaz ki,

Sevgisini bir kez tadanlar,resulden ayrılamaz ki

Elbet bir tün insanlar bu sevgiyi tadacaktır dünyada.

Ondan gayri güzel örnek yoktur,olmayacak ki,

Onun yolundan çıkanlar asla mutlu olmayacak ki,

Onun emri İslamdır, ondan sonra din olmayacak ki,

Elbet bir gün tün insanlar döner İslam’a bu dünyada.

Ben biçare ÖLMEZ’İM yanlışlara  sessiz kalamam ki

Bu dünya bir fanidir,akan pınarlar, gibi değimlidir ki,

Destini doldur hakka varmadan,Resulüm söylemedi mi

Elbet doğruları görür insanlar,Peygamberle dünyada.

Sen bu hafta doğdun,yeryüzü seninle uyanmadı mı,

Sevdan yüreklere girdi,İslam’ı seninle anlamadı mı,

İyiyi,güzeli,doğruyu,hakkı, senin dilinden dinlemedi mi

Elbet kutlu doğum haftası her yıl kutlanacak dünyada…..

					Selahattin ÖLMEZ,

						14,04,2005-

			                 Kutlu Doğum  Haftası', 'GEL DİYEMEM Kimselere düş peşime sende,gel diyemem ki, Şu güzel haftada peygamberi sev diyemem ki, Gözleri görmeyen insanlara kör diyemem ki...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gel-diyemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldüm Bu Gün', 'uzuldum-bu-gun-selahattin-olmez-lwi4i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÜZÜLDÜM BU GÜN

Hatıralar önüme bir,bir sıra,sıra dizildi,

Göz yaşı döktüm,ağladım,üzüldüm bu gün.

Aktı seneler,dertlerim üredi çığa benzedi,

Geçmişe ağladım,hüzünlendim,üzüldüm bu gün.

Neler, neler gelmedi ki,şu cefalı başıma,

Ben kaderime ağlarım,eller benim göz yaşıma,

Hatıralar birer abide gibi durur karşımda,

Geçmişe ağladım,hüzünlendim,üzüldüm bu gün.

Yedi düvel gezdim dünyayı,Divane oldum,

Çok özledim belli ki,burnuma kokuyor yurdum,

Ben yad ellerde ne mutluluk budum ne sefa sürdüm,

Geçmişime ağladım,hüzünlendim,üzüldüm bu gün.

Ömür geçiyor,yıllar tükendi,bitmedi derdim,

Ben kendimi değil uzaktaki yurdumu sevdim,

Vatan özlemi ile yandım,bittim kavruldum,

Geçmişi özledim,hüzünlendim,üzüldüm bu gün..

Güneş deniz,toprak sanki yok buralarda,

Karanfil,leylek,gül kokusu yok buralarda,

Dostluk,sevgi sadakat yok,görünmüyor ortada

Özledim geçmişi,hüzünlendim,üzüldüm bu gün.

 Sevgiyi mutluluğu,hoşgörüyü,bulamıyorum burada,

Şimdi ne güzellikler yaşanıyordur bilirim Çukur ovada,

Ölmez şimdi uzaklarda yurdundan,aklı fikri sılada,

Özledim yurdumu,göz yaşı döktüm,ağladım bu gün..

                                                              SELAHATTİN ÖLMEZ

				          5, OCAK.2004

				EREĞLİ—ZONGULDAK', 'ÜZÜLDÜM BU GÜN Hatıralar önüme bir,bir sıra,sıra dizildi, Göz yaşı döktüm,ağladım,üzüldüm bu gün. Aktı seneler,dertlerim üredi çığa benzedi,...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uzuldum-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Haziran Gecesi', 'bir-haziran-gecesi-selahattin-olmez-32z3k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR HAZİRAN GECESİ

	

Senin gelişin,mutluluğun gelmesiydi

Senin gelişin,kışların bitimi,baharın müjdesiydi,

Senin gelişin,bir devrin bitmesi,zamanın çağ atlaması,

Gönlüme gün ışığının akması,gözlerimde yıldızların çakması,

Senin gelişin bir hayatın yeniden başlamasıydı…

Gözlerin gök yüzüydü senin,

Gözlerine bakmak,yüzlerce yıldızı seyretmekti,

Gözlerine bakmak uzayı güneşi ve doğayı görmekti,

Ve aradığım dünyayı buluş olmak,o dünyaya girmekti..

Ve senin gelişinde,sanki ak deniz vardı,

Bir HAZİRAN GECESİ gönlünün derinliğinde,

Mehtap gezintisine çıkmak,

Yakamozların sergilediği pamuk köpüklerine dalmaktı,

Senin gelişin,ellerini ellerime değmesi,

O sonsuz sevgi denizini ellerime vermekti,

Bir Haziran gecesi,denizlerin,gökyüzüyle,evlenmesi,

Ve sevgimizin birbiriyle bütünleşmesi demekti…

				06.HAZİRAN.2005

		                 SELAHATTİN ÖLMEZ

				Evlilik yıl dönümü', 'BİR HAZİRAN GECESİ 	 Senin gelişin,mutluluğun gelmesiydi Senin gelişin,kışların bitimi,baharın müjdesiydi, Senin gelişin,bir devrin bitmesi,...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-haziran-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Düştü Gönlüme', 'sevdan-dustu-gonlume-selahattin-olmez-33g7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEVDAN DÜŞTÜ GÖNLÜME

 	

                                                Mevlit kandili

Sevdan düştü gönlüme,

Sen yerleştin yüreğime

Ateşinle çeşni oldun kalbime,

Bir ben vardım kendimde,

Sende yaşar oldun içimde.

Sevdan düştü gönlüme,

Sevgin girdi kalbime,…..,

Şavkın vurdu,gözlerimin içine,

Mühür oldun iz bıraktın yüreğime,

Şimdi  benden ala sen yaşarsın içimde…..

Gül oldun,güller açtı bahçemde,

Bülbül oldun, hep hak oldu lehçemde

Hak korkusu daim oldu sinemde,

Kainatta mutluluğu buldum  seninle,

Bir ben vardım,sen de oldun içimde….

Sevdan düştü gönlüme,

Varlığın kandil oldu anlımda,

Yoldaş arar iken seni buldum dünyamda,

Aşkın yanar oldu,acizane bağrımda,

Bir ben vardım sen de oldun dünyamda.

Sevdan düştü yüreğime,

Şükür olsun, nasip oldu dileğime

Yolun buldum,ben koyuldum peşine,

Nazar değmez inşallah sana olan sevgime,

Bir ben vardım,şimdi sen yerleştin içime……..

			SELAHATTİN ÖLMEZ

		                20.NİSAN.2005', 'SEVDAN DÜŞTÜ GÖNLÜME  	                                                 Mevlit kandili Sevdan düştü gönlüme, Sen yerleştin yüreğime Ateşinle...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevdan-dustu-gonlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınarlar Göç Ediyor Bire Birer', 'cinarlar-goc-ediyor-bire-birer-selahattin-olmez-eqiuy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÇINARLAR GÖÇ EDİYOR BİRER, BİRER

Göç ediyor dünyadan, ardı sıra birbirinin,

Gölgesine sığınıp hayat bulduğum çınarlar,

Daha sönmeden yüreğimdeki ateşi birinin,

Göçtü diğeri diye sanki müjdeliyor insanlar.

Gölgesi genişti  dünyada o asırlık çınarın 

Yansımasıydı adeta yüreğindeki sevdaların

Şimdi bilmez,ne yaptığını ardında kalanların,

Sadece hatırası yaşayacak gönlümde o çınarın.

Dalları uzundu,fersah,fersah o ulu çınarın,

Derdini bilirdi,yardımına koşardı insanların,

Yüreğinde gizliydi,hasret acısı ayrılıkların,

Gölgesi de eli gibi cömertti o koca çınarın.

Ah etmezdi acısına, gövdesine çakılan çivilerin,

Hoş görürdü  önemsemezdi hatalarını insanların,

Kin tutmazdı,bir olmasını isterdi tüm gönüllerin,

Gölgesini çok özleyeceğiz,ömür boyu koca çınarın..

O bir şemsiyeydi sanki başında tüm evlatların,

Tütmesini sağladı ocaklarını, tüm çocukların,

Özlemini çekerek göçtü dünyadan yavrularının,

Farkı sonra fark edilecek sanırım o ulu çınarın.

Ana gibi yar olmaz demiş atalar,alasıdır sözlerin,

Sende anasıydın cümle alemin ve de  bizlerin,

Kulaklarda küpe olup  kalacaktır senin sözlerin,

Sözlerin bizlere rehber olacak,ey ulu çınar,

Günler geçti bazıları tadını alamadı belki sevginin,

Dünya hali bu ne olduğu bilinmez kimin renginin,

Sen göçmedin dünyadan,yüreklerin içine girdin,

Ölmez derki yüreğimde filiz verdin,sen ulu çınar.

                                                                      Selahattin Ölmez

					 24,04,2005', 'ÇINARLAR GÖÇ EDİYOR BİRER, BİRER Göç ediyor dünyadan, ardı sıra birbirinin, Gölgesine sığınıp hayat bulduğum çınarlar, Daha sönmeden yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cinarlar-goc-ediyor-bire-birer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaf bir rüya üzerine uyku ertesi doğaçlama', 'tuhaf-bir-ruya-uzerine-uyku-ertesi-dogaclama-akin-akca-6uwg5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1. 

Uyku arasında bir bardak su içirilmesiyle sıcak yaz’ın; başladığında, hayaller belirdiğinde; 

huzurlanacak bazı adamlar, sıçraya sıçraya mobilyalar üzerindeki yerlerini alıyor. 

* 

Geniş salonunda kör uzayın, tersyüz mobilyalar; geçit vermez yüzücülük paylaşım adına. 

Seyir ettirme zevkleridir ve tanıdıkları olanak da üzerlerinde, etraf izleyicilerine. 

Bir kanepe, yüzüyor baş aşağı, beş metre ötede aynen durmakta bir sandalye. 

İnsanlar var hepsinin ters-üzerleri’nde; bakışları bitimsiz, yakın-uzaklar’da bir sürü yıldız … 

Ufku süzüyorlar arsız! Gözbebek, görünmeyen çeperli evin tabanı ile bu mobilyalar 

arasına sığışmış gibi, bir yer edinmiş: insanlarda yumurtanın akı kalmış; 

gözbebekleri mobilyaların altında sıkışmış kalmış; bu şekliyle, insanlara pür huzur kalmış. 

Bilemiyorlar, umudu bilmediklerinden umutsuzluk da ne … 

Huzur içinde, ışıltının altında, gördükleri o her şeyi sessizce ve coşkulu, süzüyorlar. 

* 

Sümerlerden “Akrep Adamlar”, ‘gel’ kapısını açmış gözükür bu bakışlara. 

Aslında, ışıltılı kör seyr’e bakan gözbebeksiz gözler birer güneş gibisinden. 

Gün her, geçit veriyor “Güneş-Tanrı Amash” a; ve geceye de gitmesi için, başka bir kapıda. 

2 

Kim verebilir öğrenebileceklerinden fazlasını, amaçlamazsan yok etmeye kendi korkunu! 

Ve kim uygun düşürebilir bu duruma; “sen, o’sun, bu’yum ben! ”, desene sorunu! 

* 

Uzaklardaki bir dağda ‘Koç-Kadınlar’ ise, bir gezegende; çarmıha dokumaktalar. 

Geniş arazili konaklarında; bir milyon kişiden hepsi onlar, nüfustaki dokuz yüz bin robot harici. 

Mutlu, huzurlu, şezlonglarına kurulmuşlar, durağan maden işçiliği yaptı bunu  bilmiyorlar. 

Yine de o esas akrepler, mobilyalar üzerli o kendinden yumurta akı gözleri 

de huzurlu yapıyorlar. bu, vidalı halkalar! kancalar! ve vibramlar! ah, koruyucu başlık! 

ila metal halkalar! ha, uzun kazmalı dağcı değneği! Aho merdiven, işte: 

hemen hepsi, o uzaydaki dağcı ipi için ya; Koç-Kadın’ların köprüde durabilmesi için. 

O dağ, gezegende mi; yoksa “Akrep Adamlar’ın güneşe kapı tuttuğu parıltılı uzayda mı? 

Sümerler mi bukalemun, “ Akrep Adamlar”ı mı onların? her ikisi olmalı. 

Çocuğun, lavabo başında eğlence tuttuğu ellerinde bir oyun aleti ile; havaya 

serpiştirilen oradan oraya, sabun köpüklerinin arası dengesinde belki her ikisi de; 

- 

2. bölümdeki bazı terimler, dağcının malzemesi 

1. bölümün son kıtasındaki (üçlükteki)     çift tırnak içindekiler, bir Sümer efsanesinden.', '1.  Uyku arasında bir bardak su içirilmesiyle sıcak yaz’ın; başladığında, hayaller belirdiğinde;  huzurlanacak bazı adamlar, sıçraya sıçraya...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tuhaf-bir-ruya-uzerine-uyku-ertesi-dogaclama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aça-76e - Phlasin Phantasûr', 'aca-76e-phlasin-phantas-r-akin-akca-dl8t6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'CO: Bir gidiş daha kopuyor; 

kopmak için kopmuyor, kopmak için gitmek için kopuyor …

E:   Nerden anladın? Evet, öyle …

CO: Aksi olmuş olsaydı şu an gülümsüyor olmazdın …

E:   Nasıl? kopan benim hayat eğrim olmamasına rağmen

neden güleyim ki zaten? 

CO: Bu ise, kopmayanların psikopatlığını

kanıtlamaz mı, peki? 

Olay ufku gibi değil, sonsuza dek ışık ışınının dönüp duracağı! dönüp dolaştığı bir biçim de değil evren boyunca onların, bir yıldızdan yola çıkıp da! 

PhlaSûr Eşiği’nde..

ve Nur Kayalığı’nın az ilerisinde, bu bataklık, alıp salacak bir yer seni! ! Durmadan. Fakat gel-git dalgalarına 

da benzemiyor Ay’ın ya da sıradan bir kara deliğin! İyice yandan sırıtarak geliyor çarkıfelek ne tamamen salacak ne de devamlı hapsedecek! 

Yine de ilerisine geçmem lazım bekaretin. Tehlikeye terk edilebilir mi hiç sevginin? ? 

Bu plazma oldukça nettir, görebilene: 

Phlasin Phantasûr.. 

Ve devamlı tümsekleşir ve çukurlaşır.Yediğidir çevredeki orman, bir besi kaynağı ona. Tekrar kendisinden çıkarır öldürdüklerini canlandırır geri verir 

o bekleşen zavallı ağaçlara. İşte bundan onların ses çıkaramaz hiçbirisi. Geri verir plazma onları yine onlara. Geri dönen bireyler olur mu aynı, 

o başka konu. 

İşte bunun için olunur burada ya! Böyle yerden kurtaracağım, özellikle, Eryphelia’yı da! ! 

Büyük denklik yaklaşıyor, bir yerlerde en azından, hissedilir.. kaptırmadan  kendini ait etmeli, yavaştan ve sessiz ama göstere göze soka.. dolu dizgin! 

Chateau Icno, Icnoeau; 

içerde, bu bataklığın çok, çok ötesinde. Bir sıçramayla gidilebilecek gibi, sırf geçildiğinde burası! O yüzden şu an işimiz zor. Ancak boş gelmedik:

Yolda bir han vardı, espirisi iyi, yemeği kötü. Bu fiyonklarla şenlendirip azap üzümlerini onları yerleştirecek satın almıştım şarap şişelerini, yani kurşunların içine doluşacağı kovanlar misali.. bazı silahları: İyi huycul bunlar, saldırılmadan ateş almazlar ve ateş almazlar saldıranlara bile, şekilsiz değilse salgıladıkları ısıl formasyonları bir kör amaca hükmetme sevdalılarının! 

Athoxm via Shadon! ! !   *

Rüyaların dili, ölçün olsun hayal gücü! Ölçün olsun gölgelerin kudreti! Ölçün olsun ilk etapta ışın kuvveti! ! ve sonra kullan ölge imza sırtlan gölgeleri! 

Şaşıracaklar, olsun, bir meydan savaşı bu! Galip kutlu, mağlup zaten mutlu. Yoksa başka tarz bilmeyenler, neden artırdıklarını asla azaltmasınlardı ki? 

Bunu da bilecekler ama artık, ya da hiç bilmeyecekler ve böyle postu serecekler bak orda işte bataklık ve kabarıyor şu an konukseverliğini ispat ederce,

sinsicesine yayılıyor izdüşümlerinden karanlığın zamanının ve çirkef lordu üzerine bu gecenin kio can vermedi mi onlara da, ben de gidiyorum işte! 

Safir böcekler her yerde! Sarmışlar her bir yanı! Kumandan kurt böceği başlarında, daha zararlı bir kemirgen -mutantik- Kurt Örümceği’nden (genetik, seçilime uğrayan..)  Sarmışlar tüm bir Icnoweasle çevresini. Ama görüyorum, yine o en yukarıdaki pencerenin camı açık, son bıraktığım gibi duruyor ve göz kırpıyor, davet eder gibi –

yaratıkları da beni de- buyur ediyor; neden bekleteyim –ardılı onun aynaların küçük kızını? 

Zamanın günahı bu sanki bu lanet, Whisco ve Octo oğulları’nın* üzerine sinen. Böylece tüneyen onların izbe, ürkek köşelerine, işte hatta şarap bile yer bulamaz o kötücül ruhların ışık göremez değil –kendinden tetikli- görmez.. kara kuru mahzenlerinde! Ve Lizaifer ile Samara* ise her zamanki şekliyle hepsinin başında, büyük komutan edasıyla! Bak işte geliyorum Eryphelia, veya Rapndrell,* kuyunun kızı, kulelerin sarı saçı, sarkıt lülelerini ve düz düşeylerini ya da açık tut pencereni, geliyorum! ! ! 

-

Türetilen:

Samara: ‘The Ring (Halka) ’ kaçkını, çamurlu beyaz elbiseli zarar verici küçük kız

Önceden ve çok uzak olmayan zaman dilimleri içerisinde ürettiklerim:

Phlasin phantasur: Plazma’daki iyicil günahın içerisi mevki’nin sur öttürülen ışık ışınının fantazi kaynak yeri

Eryphelia=Rapn’drell=Şatonun içinde bekleyen segili

Athoxm:Her yöne ışık saçarak karanlıktakilere ışınlayan güçlü bir silah

Shadonake:Athoxm’dan sonra kullanılır. Gölge verir. Son noktayı koyma bakımından daha etkilidir.

Icno: Icnoweasle şatosu,icnoeau:şato ıcno (icy snowy castle) 

Whisco=whiscorpio: Islıksı akrepler (Octo’lar tarafınca kullanılır bunlar.) 

Octo=Octovill: Ahtapotumsu biçimli kötücül yaratıklar

Lizaifer: Lucifer’in oğlu. Samara bir atabey kıvamında olmasına karşın, kral Lizaifer ona hükmeder.', 'CO: Bir gidiş daha kopuyor;  kopmak için kopmuyor, kopmak için gitmek için kopuyor … E:   Nerden anladın? Evet, öyle … CO: Aksi olmuş olsayd...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/aca-76e-phlasin-phantasur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Emrine Karşı', 'vur-emrine-karsi-sait-kucuk-ttxs3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-sev emrini 

 kim verdi

-kim olacak

 seven yürek', '-sev emrini   kim verdi -kim olacak  seven yürek...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vur-emrine-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmadım Anne', 'seni-unutmadim-anne-mehmet-sait-akkus-szi80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorulupta bir gün yana düşersem

Al başımı dizine koy ANNE

Gözlerimi kapatıp bir gün ölürsem

Dizine vurupta ağlama ANNE

Bir gün olurda kapını çalarsam

Hoş geldin oğlum de bana ANNE

Olurda sana bir yanlış yaparsam

Suçumu bağışla olurmu ANNE

Gönül isterdi hep yanımda olaydın

Sıcaklığını hissetmek istiyorum ANNE

İki laf edip bana bir şey sorsaydın

Ömrümü sana verirdim biliyormusun ANNE

Unutmak kolay değil seni hep anacağım

Mezarına geldim bağışla beni ANNE

Ömür boyu hasretini hep çekeceğim

Mezarında rahat uyu canım ANNEEEEE', 'Yorulupta bir gün yana düşersem Al başımı dizine koy ANNE Gözlerimi kapatıp bir gün ölürsem Dizine vurupta ağlama ANNE Bir gün olurda kapını...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-unutmadim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşa Karşı', 'savasa-karsi-sait-kucuk-tj68m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüreğimden

güvercinler

uçurdum

gagasında

zeytin dalı

taşıyan', 'yüreğimden güvercinler uçurdum gagasında zeytin dalı taşıyan...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/savasa-karsi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalenderi', 'kalenderi-asik-dertli-3ak3i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İkbale zeval erse ne var,sende kemal var

Mağrur-ı kemal olma ki ardınca zeval var

Her bir kişinin talii devlette bir olmaz

Bir lokması yoktur ki yesin bunca rical var

Ahval-i perişanımı hiç de sorma efendim

Vallahi beğim boynuna, bu işte vebal var

Tek başıma olsam şaha gedaya kul olmam

Viran olası hanede evlad ü ıyal var

Dur olmayı ister mi kişi öz vatanından

Ey DERTLİ-i biçare bu esrarda ne hal var', 'İkbale zeval erse ne var,sende kemal var Mağrur-ı kemal olma ki ardınca zeval var Her bir kişinin talii devlette bir olmaz Bir lokması yoktu...', ARRAY['Türk Edebiyatı','Şiir','Aşık Dertli']::text[], 8.5, '{"poet":"Aşık Dertli","poet_slug":"asik-dertli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kalenderi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşek kültürü.', 'esek-kulturu-i-shak-ozlu-92osf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarda bir yazı! 

Buraya işeyen eşektir,

Hatta eşekoğlu eşek.

Bunu okuyan eşek üzülür,

Oğluna iki tepik atar,

Oğulun canı fena yanar.

İşeyeni sin-kafla anar.

Ana eşek pusuya yatar,

Görür duvarı sulayanı.

Yazıyı yazana gider.

Ey yazıcı gördüm onu,

Benim oglum değildir,

Azcık size meyildir.

İki ayağı var,

Bana çok uzak,

Sana oldukça yakın.

İftira atma ırkıma,

Yok Eşek Kültüründe,

Böyle duvara işeme.', 'Duvarda bir yazı!  Buraya işeyen eşektir, Hatta eşekoğlu eşek. Bunu okuyan eşek üzülür, Oğluna iki tepik atar, Oğulun canı fena yanar. İşeye...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/esek-kulturu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mozart Çalıyor Tüm Duyguları Hırçın', 'mozart-caliyor-tum-duygulari-hircin-funda-bahceci-o7w62', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen gideli beri

her şey bıraktığın gibi

aynı diyorum 

bitip bitip başlayanları saymıyorum

''başkaları uyanıyor yanımda 

konuşuyor senin yerine

bense hep yabancı ben

tanırsın''

sık sık yürüyüşler yapıyorum bir başıma

gitarım sırtımda

balkonuna bakan banka oturuyorum

sen yerine 

başkaları bakıyor pencerenden

konuşmadan kalıyorum belki saatlerce

varım yoğum

Mozart çalıyor tüm duyguları hırcın

yağmur yağıyor,

kalkmıyorum

rüzgar çıkıyor,

gitmiyorum

kar yağıyor,

bembeyaz bekliyorum

tenhalara vurulup kaldıkça

hep şu gerçeğe varıyorum

beni gözden düşüren

sana sessiz kalışımdı', 'sen gideli beri her şey bıraktığın gibi aynı diyorum  bitip bitip başlayanları saymıyorum ''başkaları uyanıyor yanımda  konuşuyor senin yerin...', ARRAY['Türk Edebiyatı','Şiir','Funda Bahçeci']::text[], 8.5, '{"poet":"Funda Bahçeci","poet_slug":"funda-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mozart-caliyor-tum-duygulari-hircin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayırdır inşallah.', 'hayirdir-insallah-i-shak-ozlu-0svo7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayırdır inşallah,

Dün gece rüyamda,

Çocukluk arkadaşlarımla buluştum.

Anacım karpuz getirdi,

Sokak başına kadar.

Sıcakta iyidir yiyin diye,

Paylaştım onu,

Arkadaşım Bekir ve kardeşi İlyasla.

Kesilmedi rüyam,

27 yıl önce ölen köpeğimi gördüm,

Yaşlanmıştı.

Şakalaşıp konuştum onunla,

Okulamı gidiyorsun dedim,

Ağır ağır evet dedi.

Dün gece ben rüya gördüm,

Yaşarken yalnızım dillerim lal.

Yarıölü iken dolu dolu,

Hayvanla bile konuşuyorum,

Ya tam ölü olsam....................

Yoksa ben yanlış mı belledim.

Yaşamı,

Uykuyu,

Ve ölümü.', 'Hayırdır inşallah, Dün gece rüyamda, Çocukluk arkadaşlarımla buluştum. Anacım karpuz getirdi, Sokak başına kadar. Sıcakta iyidir yiyin diye,...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayirdir-insallah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükür.', 'tukur-i-shak-ozlu-jiv2m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tükür,

Bir daha tükür,

Az geldi,

Dolu dolu tükür.

Nasıl olsa yerler müsait.

Bak etraf bomboş,

Gelip geçenler önemli mi? 

Yeterki sen rahatla.

Kirleteceğini mi sandın,

Bir tükrükle,

Güzel dünyamızı.

Yetmez tükrüğün-sümküğün,

Senin düşüncesizliğin yeter.', 'Tükür, Bir daha tükür, Az geldi, Dolu dolu tükür. Nasıl olsa yerler müsait. Bak etraf bomboş, Gelip geçenler önemli mi?  Yeterki sen rahatla...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tukur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetiş Güzel', 'yetis-guzel-sahin-erturk-kl4wy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu bekliyorum

Yüreğime kramp girdi

Belli sıra bana geldi

Yetiş güzel,gidiyorum

Hergün dünü arıyorum

Gram,gram eriyorum

Yavaş,yavaş bitiyorum

Yetiş güzel,gidiyorum

Ali,Ahmet çoktan gitti

Altan,Aydın yeni gitti

Belli sıra bana geldi

Yetiş güzel,gidiyorum

Ne zor şeymiş,hasret çekmek

Hergün milyon kere ölmek

Yaşarken ölmek bu demek

Yetiş güzel,gidiyorum

Yarın çok geç,çabuk davran

Kalmadı hiç eski havam

Doktor sensin,belli yaram

Yetiş güzel,gidiyorum

(07.08.2005) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Yıllar oldu bekliyorum Yüreğime kramp girdi Belli sıra bana geldi Yetiş güzel,gidiyorum Hergün dünü arıyorum Gram,gram eriyorum Yavaş,yavaş ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yetis-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir', 'sehir-elazigli-mustafa-kaya-xdgte', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içim içime sığmaz bazı

bazı da dar gelir şehir

dumanlı dağlara alıp başımı kah,

kah yalınayak dolaşasım gelir..

harap ediyor ruhumu 

hiç sebepsiz toplanan düşünceler

bir ömre değişmeyeceğim dostlar nerede..? 

ve seni görmekle sevineceğim gülüşlerin nerede..? 

beğenmediğin tüm huylarımı sulara bırakıyorum

şehrin kaldırımları söylesin

sırdaş kaldığım gecelerce ne haldeyim

ben şehri beklerim..şehir beni

ne ebabil kuşlarıdır gözüken

ne de nuh un gemisi...

ve kendime kaçıyorum..

bir umuttur diye sarıldığım şehir 

en bencilce kanımı emiyor..

kafamı kıran hatalar çıldırmış

ve içimde gezdirdiğim günahlar

şehirde meçhul bir rüzgar

şehrin kahrını bindirdim bulutlara

ve uykulara vurdum sevdamı

içimde yalnızlık yaşadıkça...

                mustafa kaya / ankara

               01.08.2001', 'içim içime sığmaz bazı bazı da dar gelir şehir dumanlı dağlara alıp başımı kah, kah yalınayak dolaşasım gelir.. harap ediyor ruhumu  hiç seb...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehir-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaline Susamak', 'hayaline-susamak-yusuf-varol-4zd99', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ötesin...

Hangi sözcüklere sığdırayım seni

Hangi harflerin kıvrımlarına bulaşarak kendi sessizliğini ve sensizliğini bitirebilirki bu senli dilim

Ne kadar konuşursam o kadar da kapatmak istiyorum dudaklarımı,

Kendimi duymak seni duymak değil ki...

Sözcüklerle başlayıp sözcüklerle bitmiyor hiçbirşey

sesimle doğup sesimle son bulmuyor uzaklığın yankısı

Sığamadın,

Seni 

sesini 

ve hayalini hiçbir sözcüğe sığdıramadım

yetmedi dilim,

yetmezdi kelimeler bilirdim.

Kuruyacağını bile bile parıldayan bir kırmızı ile sağdım sesimi ak kağıtlara

Yine de sığdıramadım seni o lal damlaya

Seni anlatamadım onlara

alamadılar seni satırları arasına 

alamazlardı bilirdim 

zira sen öte’ydin 

şiirden bile.

Aslında ben hiç konuşmadım ve hiç yazmadım da

susu’yorum halen

hiçbirşey ifade edemeyen yansımasız cümleler kuruyorum

sözcükler sarfediyorum dilsizliğimle ıssızlığa

ıssızlıklara,

sana

üşüyen parmaklarım kapalı dudaklarım seni susuyorlar

sesini ve sevgini

bir de ben susuyorum seni

yazmadan ve konuşmadan susamak istiyorum sana

o hüzünlü gözlerine 

esriten gülüşlerine

yalnız’ca ve sadece susamak.', 'Ötesin... Hangi sözcüklere sığdırayım seni Hangi harflerin kıvrımlarına bulaşarak kendi sessizliğini ve sensizliğini bitirebilirki bu senli ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hayaline-susamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlham', 'i-lham-muammer-karatas-qc5em', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlham bir mum ışığı,

Duygu insanın irşatıdır.

Şiir yaşamın gerçeği,

Nakaratsa şiirin kalbidir.', 'İlham bir mum ışığı, Duygu insanın irşatıdır. Şiir yaşamın gerçeği, Nakaratsa şiirin kalbidir....', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilham-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mısın', 'var-misin-feride-omur-427xm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birden girdin düşlerime

Bir daha çıkmaz oldun

Sevgiyi, muhabbeti, arzuyu

Bir tek sende buldum

Kokladıkça açıldım

Sevilmeyince soldum

Benimle mutluysan

Bu dünyada yaşamaya

Var mısın

Her gün yeniden ölsem

Alevden kucağında

Ruhum kapkara olsa da

Aşkının ocağında

Gül yerine dikenler bulsam

Gönül bağında

Benimle bu dünyada

Yaşamaya var mısın', 'Birden girdin düşlerime Bir daha çıkmaz oldun Sevgiyi, muhabbeti, arzuyu Bir tek sende buldum Kokladıkça açıldım Sevilmeyince soldum Benimle...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/var-misin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abc Değil Umut', 'abc-degil-umut-suna-aras-lqmtn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkı bağışlatmak değil dileğim

Ya da tanrısını od’una yunmak

Yüreğim okundan fırlamış sanki

Beklenti

Yarama tuz seren boşluk

Adımı alfabene alma

ABC değil umut

Sen beni ağlarken gördün mü hiç? 

Keşke incitmesen aşkı

Ona dünyasız sarılsak.

Hani bana dokunduğun an? 

Verebilir misin o anı bana? 

Nasıl desem

Tenim gibi

Hep bende kalan

Anları durduran güce eriştir beni

Korkum yok

Sen de korkma

Ben seni tarihe geçiyorum

Sen bana sıkılan zaman ötesi.

Bulan saçlarıma öyle dur

Yasakmışız aldırma

Dinleme korkuların bataklık seslerini

Yüreğim üşüyor bak

Yaşam ne ki? 

Hırsızın bir kibrit çakımı gibi.

Nasıl dönüyorum içimde bilsen

Tutuşur kerem küllerin

Vurulup düşmek nasılsa öyle

Nasılsa işkenceye gerilen çığlık

Binlercesi yürüyor üstüme dinle

Ve düş…

Yaram derindir benim

Kanat kendi ellerinle

Sonra git…

Başka hiçbir şey söyleme.', 'Aşkı bağışlatmak değil dileğim Ya da tanrısını od’una yunmak Yüreğim okundan fırlamış sanki Beklenti Yarama tuz seren boşluk Adımı alfabene ...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/abc-degil-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum seni', 'ariyorum-seni-elazigli-mustafa-kaya-o8zao', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hangi sesleri seçtim sendin

ve hangi gözlere rastladım sendin

daha ne kadar sır kalacaksın söyle..! 

yorgun başıma yastık oldu sokaklar

yaralarım kanıyor

sensiz gecelerle çatışıyorum

felçliyim

gel artık

gel ki gül olsun yaralarım

sevgisizlikten kuleler dikili 

kentin bulvarlarında

seni arıyor 

gözlerim çaresiz

kolum kanadım kırık haldeyim

gel artık

gül kadar ömrüme, 

güller katarak gel...

                                                                     07.08.2005 / istanbul

                                                                      mustafa kaya', 'hangi sesleri seçtim sendin ve hangi gözlere rastladım sendin daha ne kadar sır kalacaksın söyle..!  yorgun başıma yastık oldu sokaklar yara...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ariyorum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-muammer-karatas-74rw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldız yazarım sana,

Güneş yazarım gözlerine,

İnce ince kar yağarken...

Soğu içime; sıcağı tenine yazarım.

Yağmur yazarım üzerine,

Damla yazarım saçlarına,

Dolu dolu koklarken...

Aşkı ellerime; ellerimi bedenine yazarım.

Bir mutluluk yazarım defterlerime,

İsmini en başına yazarım,

Satırlar dolarken...

Sevgini damarlarıma; damarlarımı yüreğine yazarım.

Aşk yazarım sana,

Aşk yazarım,

Doğuşu bilinmeyen nehirlerde,

Doğduğunu doyduğuma yazarım.

Şırıl şırıl akarken dağlardan,

Taşlarda parıltımı yoğurur,

Üstüne derinliklerimden...

Derinliklerine doğru AŞK yazarım,

Sadece; AŞK.........', 'Yıldız yazarım sana, Güneş yazarım gözlerine, İnce ince kar yağarken... Soğu içime; sıcağı tenine yazarım. Yağmur yazarım üzerine, Damla yaz...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-407-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-muammer-karatas-54uh5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taşıma sürünmüş bir rüzgar, Ana! 

Kumumu alıpta gitmesin Anam,

Gözlerin kapalı bakma bana,

Yalnızlığım senide üzmesin Anam.

Akıtma, yanaklarından nur damlalarını,

Burak onlar yanaklarında güzel.

Akvaryumu dök üstüme kır camlarını,

Ruhum ateşe uçmasın Anam.

Topraklarımı okşa okşa hafiften,

Ellerinle bir avuç su getir bana.

Etrafımı çevir çakıl taşlarla,

Üzerime kimse basmasın Anam.

Ağlama lütfen şiirlerimi okurken; 

Gözyaşların, umutlarımı bozmasın Anam,

Bir güzel peşinden gitti, de; satırlara,

Kalemler üzülmesin yazmasın Anam.

Yanmış anılarımın külünü tutma,

Bir mum yak üstümde dursun Anam,

Bir eşk yeter başka yaş dökme,

Şiir misali bedenimi sorsun ANAM...', 'Taşıma sürünmüş bir rüzgar, Ana!  Kumumu alıpta gitmesin Anam, Gözlerin kapalı bakma bana, Yalnızlığım senide üzmesin Anam. Akıtma, yanaklar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anam-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasa Gözlerin', 'olmasa-gozlerin-yusuf-varol-gm4lz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmasa yansıması bu aşkın 

güz erken gider

suya iner gözlerim ve ölüm unutmaz beni.

Dirilirse sancıyan sözcüklerim

Karanlığa maruz kelimeleri alır götürür akşam yeli

Henüz vakit varken

ölemeyenlerde ölmeyi öğrenir...

Yoksa karşılığı seni sevmenin

suyu kurur,kanı vurur gözlerimin

yanaklarımdan düşersin diye korkarım

dudaklarımda kalır ayak izlerin.

Olmasa karşılığı bu aşkın

Güz erken biter,

sözlerim göğe gider

yarım bırakılmış ağlayışlar başlar 

ardından ayrılışlar; 

         yeşil yapraklar dallarından

         yaş’lar gözlerden.

Sen gidersen güz de durmaz 

o da gider

ve ölüm unutmaz yine beni

sözlerim suya iner.', 'Olmasa yansıması bu aşkın  güz erken gider suya iner gözlerim ve ölüm unutmaz beni. Dirilirse sancıyan sözcüklerim Karanlığa maruz kelimeler...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Varol']::text[], 8.5, '{"poet":"Yusuf Varol","poet_slug":"yusuf-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olmasa-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Gönderilmemiş Mektuplar', '01-gonderilmemis-mektuplar-cem-karadeniz-e6edw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana doğan günlerde, seni çizdiğim tuvalimde ince bir gözyaşı damlası hapsolmuş hüznüme ve dut kurusu, süpürge tohumu bir vazgeçiş tınısı yankılanmış ıssız anlarında sevgi ormanının...

             Sensiz geçen anlarım da sana ait artık. Sinsi acılara satmaktansa yüreğimin resmini: gülücüğüne kilitledim apansız sevişmelerimizin buğulu aksini.

              Dost bir merhaba sıcaklığı içimi titreten, adını yüreğimle paylaştığım her satır başında. Ürkek bir tavşan kaygısı, gözbebeklerini incitme tedirginliği apansız. Ve tekrar tekrar çözebilme çabası bir denklem anlatısındaki matematik karmaşasını. ''Keşke söylemez olsaydım! '' da sözedilen pişmanlık tanısı.

               Koskoca bir yürek dolusu, canımın içi bir gülümseyiş buğusu ya da ıslak bir göbek kokusu, sana dair anlarda parmak ucumda adınla doğan şarkıyı söyleyen dostk bakışlı serçe kanadındaki gerçe.

               Aynamdan yansıyan dost bakışın tanrısı; 

                SEVDİM SENİ...

(3/10/99 - pendik)', 'Sana doğan günlerde, seni çizdiğim tuvalimde ince bir gözyaşı damlası hapsolmuş hüznüme ve dut kurusu, süpürge tohumu bir vazgeçiş tınısı ya...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/1-gonderilmemis-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '02 Gönderilmemiş Mektuplar', '02-gonderilmemis-mektuplar-cem-karadeniz-arhj2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgârların çığlığıyla uyandım az önce; yılgın gözlerimi üşüten, anımsamaların yansıttığı boşluğu sürüklerken bir yandan, bir yandan sigaramı paylaşan ıssızlıkta ve oysa öylesine kısa sen dolu anlarca.

                      Adımlarımla yarışırken yorgun voltalarda, kanım yetişmek çabasında gözyaşlarımın sessizliğine. Seni anımsatan dizelerle kavga, önleyebilseydi tutkun duyguları; özlemlerin anlatımı yerine yalnızlığında kaybolduğum anlardan kopmaz, ıssızlığı seçer, mutlulukla birleştirmeye çabalardım.

                     Nedense gülmez oldu gözbebeklerim yokluğunda. Yüreğim kafes kafes, özleyişim hücre hücre, dünyam perde perde, ağlayışım bebek bebek, sevdam canlı canlı bir sesleniş sızısı. Seni özlemeye kalkıyor ıssız bir vapur yine bir şafak. Üsküdar yansıması bir sıcaklık ve katran karası anlar söylencesi yokluğun yine kadranında saatimin. Seni yaşayabilme rüyasında, seni görememek endişesi saklı…

                     Seni özledim…', 'Rüzgârların çığlığıyla uyandım az önce; yılgın gözlerimi üşüten, anımsamaların yansıttığı boşluğu sürüklerken bir yandan, bir yandan sigaram...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/2-gonderilmemis-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi''şey Demem', 'bi-sey-demem-muammer-karatas-3q378', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boş kağıt defterlerde kalem üstünde güzel durur,

Yazmak ister el ama; hayal onla gezer durur

Sen karşıma geçince, şiirimden güzel durursun,

Eh be! kalemim yazsana sen ne? süzer durursun.

Kıskanırım seni defterimden kalemimden ve kendimden,

Senin için deliyim kendi kendime engelim ben,

İphamın, kederin, acın, aceb; bir kinin varmıdır,

Düşünürüm her gece bir bakışın bana kar mıdır? 

Hayal de olsa; ellerini rüyamda, bir zerre uzat bana,

Rüyasız geçen her uyku sanki, bin kere azap bana.

Allı tenin üstüne serpilen kuşa yanam,

Her genç sever, ama; ben delirmekteyim anam

Kimbilir! şu; gök,deniz kaç kişiye bedel ve kaçına,

Bense değişmem hiç birini senin bir tel saçına.

Sensiz bahçelerde, çiçekler şaibeli süs gibidir,

senin nefesin, ter kokun bence; canım mis gibidir.

Karanlık saçlarına, aydınlığı içirir geceler,

Benim şifam sensin fayda etmez heceler.

Mehtapla bir olup her gece karşıma geçersin,

İksir senin demindir niye ki, yudum yudum içersin? 

Güneş sende parlaktır, ama geceme karışamaz,

Binlece yıldızı yanar senin nuruna erişemez.

Sigara elimde güzel durur dumanı içimde is olur,

Gece senin eserin güneş önünde sis olur.

Bu kadar güzelliğin anlattırdı bana bunları; 

Es es be! rüzgar o, gelmesede vursun yüzüme kumları.

Seni anlatırım anlatmaktayım ama hiç hiç bi''şey demem 

Hayalinlede güzelsin iç iç bi''şey DEMEM', 'Boş kağıt defterlerde kalem üstünde güzel durur, Yazmak ister el ama; hayal onla gezer durur Sen karşıma geçince, şiirimden güzel durursun, ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bi-sey-demem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çalarım', 'ask-calarim-muammer-karatas-c42et', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu deniz aşk denizi,

Olanın gider burda gemisi,

Elime davulu alırım,

Hem söylerim hem çalarım.

Çalan elim değil gönlüm,

Daha çalarım yeterse ömrüm,

Ben ne aşklar gördüm! 

Daha da üstüne aşk çalarım.

Aşım bir tencere aşktır.

Yerim yerim karnım açtır.

Kaşıklarım ardarda,

Ekmeğime de aşk çalarım.

Sabah güllerini koklarım,

O, kokuyla nefesimi paklarım,

İçime sevgimi saplarım,

Geceleri aşk çalarım.

Gözlerin bakar yeşil yeşil,

Parlar karşımda ışıl ışıl,

Uyuturum dizimde mışıl mışıl

Alır bir de saz çalarım.

O, uyur ben sıvışırım,

Karanlığa karışırım,

Gökte yıldız burakmam,

Bir de üstüne Ay çalarım.', 'Bu deniz aşk denizi, Olanın gider burda gemisi, Elime davulu alırım, Hem söylerim hem çalarım. Çalan elim değil gönlüm, Daha çalarım yeterse...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-calarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 40', 'eskimez-beyitler-40-huseyin-avdic-zl96d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hissin esiridir gençlik, aklın da kör şeytanı.

Yemeden sefâhatin tokadını, Hakk''ı tanı.

******

Günümüzde gazete,

Okumamaya recete! 

******

Nerde görse fisdansız bir kadın,

Ordadır bizim vicdansız basın! ..

******

Doğu''dan doğar doğrular.

Batı''dan biter bâtıllar.

******

Özde hayat yok özde.

''Müslüman''iz ''sözde''.

******

Ararken kendini kaybedenler,

Izm''lere adlarını verirler.

Batı Berlin, 1980-85.', 'Hissin esiridir gençlik, aklın da kör şeytanı. Yemeden sefâhatin tokadını, Hakk''ı tanı. ****** Günümüzde gazete, Okumamaya recete!  ****** N...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eskimez-beyitler-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ömür Yarası', 'omur-yarasi-cihan-kaya-p3h0u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdim olmuş bahta, kömür karası

Ayrılık ki olur, ömür yarası.

Git gözün önünden, gözün elası,

Dar etti dünyayı, bu aşk belası…

Gece haram olmuş, sevene yazık,

Unutturdu bu dert, ne su ne azık…

Kızamam yârime, başkadır yeri

Derman verin bana, kesin de seri…', 'Derdim olmuş bahta, kömür karası Ayrılık ki olur, ömür yarası. Git gözün önünden, gözün elası, Dar etti dünyayı, bu aşk belası… Gece haram o...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/omur-yarasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03 Gönderilmemiş Mektuplar', '03-gonderilmemis-mektuplar-cem-karadeniz-y9c3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana dair ne varsa yazmak boynumun borcu olsun derken kendi kendime, senin bu denli uçsuz bucaksız, bu kadar bitimsiz olabileceğini hesaplayamamıştım. Oysa hesapsız kitapsız verilmiş – tabii ki kendime- bir sözün ağırlığı altında öylesine ezginim ki… Yine de o kadar sıcak ki sana yazma işkencesi, öylesine muhteşem kokular salgılıyor yürek kulakçıklarıma bilemezsin. 

          Seni özlemekten arda kalan vakitlerimi, nasıl yapsam da sana nasıl yazsam endişesiyle geçiriyorum ve bir fırsatını bulup iki sigara fırtı arasında ya da bıkkın bir tuvalet kaçamağında nasıl oluyorsa sana yazıyor ve hatta utanmadan bunları ben yazdım diye embesil salak gururlanarak sana okutmaya savaşıyorum. Geleyim de kendimden nefret etmeyeyim.

Elin oğlu binlerce hatta mıltıryonlarca sözcükle mülakat edip, bu işe en usturuplularıyla üç senelik sözleşme yapsın ve bunları sana yazılabilecek cümleleri kenara dantel niyetine işlesin, ben oturayım – bak hem de oturduğum yerden – iki kelimeyi üç otuz paraya bağladım diye keyif çatıp gözlerini seyrin kıymetini biliyor havalarında kalbini kırıp gözyaşı akıttırayım.            

         Bak utanmaza desen yeridir ekmek nimet eze ki. Şimdi bunları yazarken bile kendime karşı şiddetli bir esef duygusuna kapılmaktan kendimi tutup çıkartamıyorum. Ben bir neyim diye sormak şaşkınlığına düşmek ilk yaptığım şey olsaydı, gider kendimi Taksim semalarına bayrak niyetine dikerdim.

          Hakkımda bu kadar kötü düşünen bir ben kişi olarak, esefsel bir başkaldırının kendimi ayrı bir kalıba sokacağını sanmaksa ayrı bir salakya. Üç kuruşluk aklımıza giydirecek başka takke yokmuş gibi sen yakala beni, bul da koy o sevgili anlatımındaki coşkun koltuğa. İki kelimeye bir pişti oynatamazken ben tutayım da valse nota arayayım öyle mi? 

          Bak utanmaza, arlanmaza, terbiyesize! Kasabın dükkânında asılı o harap post benimkisi olsaydı, ben de kendime seviliyor hissededurur, bir yandan da miyav bir gece korkusu tırmalardım mart akşamlarının karasına kırmızı renkli bir ampul ışığında.

          Eylül bile hüznünü esirgemiş benden. Neyime ki martın kedisel erotizm kaygıcağı? 

          Hastir bir vazgeçişle çınlayan bu gecede, yine senin sevgine düştüysem, sana yoldaş bir bakış fırtınası tadında, gizli elma akıllı bir özleyiş kelkintisinde kaybolmuşum diye. 

          Yoksa yalnızlık ne ki?', 'Sana dair ne varsa yazmak boynumun borcu olsun derken kendi kendime, senin bu denli uçsuz bucaksız, bu kadar bitimsiz olabileceğini hesaplay...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/3-gonderilmemis-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim seni', 'sevdim-seni-muammer-karatas-8rky7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni gecelerin içinde sabahlara yakın sevdim,

Ağaç dallarının uçlarında baharlara yakın sevdim,

Seni damarlarımın içinde kalbime yakın sevdim,

Ben sevdim senin hep uzaklardan gelişini ve gidişini yakınlarıma,

Seni bezediğim duvarlarımda,

Duvarlarımın arkasını sevdim sana  yakın diye,

Ben sevdim dudaklarımı, sevdim ağzımı,

Sevdim dilimi sevdim söylerken ismini

İçime çektiğim nefesimi sevdim,

Senli maneviyata erişirken; 

Ben tütüşünü sevdim yüreğimde,

Ve itişini arkamdan sana...

Ben geçmişimi sevdim,

Sana gideceğim yollar adına,

Ve geçmişimden dönüşümü sevdim,

Sana rastladığımda....

Ben kipriklerinin acısını sevdim, yüreğime saplanan,

Ve gözlerimin eşkini gözlerimde,

Ben tutunduğum dalı sevdim senden düşerken; 

Ve tırmandığım kayalıkları, sana...

Çok şeyi sevdim senin adına

Hiç sevmediğim nenleri bile sevdim...

Bir tek seni sevemedim; 

Şöyle, kollarıma alıp doyasıya,

Saçlarını okşamayı, gözlerine,doya doya bakmayı,

Ve öpmeyi dudaklarından...

Ben seni herşeyde herşeyle sevdim,

Fakat birtek seni sende sevemedim

Sen hiç sende durmadın ki; 

Seni sevmeye yetişebileyim...

Ben işte öylece sevdim seni,

Durgunluğunu sevdim denizlerinin

Ve kuru ekmekle kaldığımda TUZUNU...', 'Ben seni gecelerin içinde sabahlara yakın sevdim, Ağaç dallarının uçlarında baharlara yakın sevdim, Seni damarlarımın içinde kalbime yakın s...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevdim-seni-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...4 İşlemde Sen', '4-i-slemde-sen-cihan-kaya-mvze4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günlerden bir çıkara çıkara 

Geceleri dost bildim... 

Hasreti akılda toplaya toplaya 

Yaşla dolu gözü sildim... 

Acıları bedene çarpa çarpa 

Konuşmaya aciz dildim... 

Uykumu rüyanla böle böle 

Saat başı çalan zildim.. 

Neyi ekleyip neyi çıkarsam nafile 

Sen aklımdan çıkmıyorsun... 

Neye çarpıp neye bölsem nafile 

Sen gönülde bütünleşiyorsun...', 'Günlerden bir çıkara çıkara  Geceleri dost bildim...  Hasreti akılda toplaya toplaya  Yaşla dolu gözü sildim...  Acıları bedene çarpa çarpa ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/4-islemde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En iyi arkadaşım', 'en-iyi-arkadasim-gulcin-aksekili-8fwkc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En iyi arkadaşım kendim

Sorularımın cevaplarını benden doğru bilen varmı

Uzun uzun laflarız efkar dağıtırız

En iyi sırdaşım kendim

Zorlukları birlikte aşarız

Uçurumun kenarında benden başka kanat varmı

Uçarız tam düşecekken güneşli gökyüzüne

Beni benden iyi anlayan var mı

Hasret değilim ki bir dost sözüne

Herkesin telaşı kendine yeter zaten

Kendimi severim, kendimi bilirim

Beni benden iyi bilen var mı

Kimi öyle der, kimi böyle kulak asmam 

Onların elbet sevdiği şeyle vardır, sevmediği şeyler

Herkesin bir tabiatı var

Herkes kendi tarzıyla güzel

Kınamamayı öğrendim insanları bu saatten sonra

Keşke daha hoşgörülü olsaydım eskiden de 

Daha çok mutlu uyandığım sabahlarım olurdu

Çok önceden barışırdım kendimle

Zamanı değilmiş, yahut vakit olmamış

Dünden yarına gider içimde bir ben

Daha sağlıklı akar kanım damarlarımda

Her güne bir özlem duyarım kollarımda

Özlemekte güzeldir 

Özlemek dedim de insan güzellikleri özler

Sevdiklerini ve sevenlerini özler

Kendimi de özlüyordum bir zamanlar

Şimdi artık o benim,  keyfim yerinde

Ben bana aitim kavgam yok kimseyle', 'En iyi arkadaşım kendim Sorularımın cevaplarını benden doğru bilen varmı Uzun uzun laflarız efkar dağıtırız En iyi sırdaşım kendim Zorluklar...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/en-iyi-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Geldim', 'ben-geldim-muammer-karatas-w9l5t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben geldim yüreğine,

Ben ümtlerim tutuşurken; 

Söndüğü yerden geldim.

Ve mutlulukların dans ederken; ağladığı,

Ben gözlerin alev alev yanarken; 

Soğuğa yüzük yüreğimle geldim.

Bir tutam sevgi getirdim gelirken; 

Ve sana tamamlanmamış gelecekler,

Hoyrat rüzgarlara buraktığım ıslıklarla,

Selamlar getirdim tüm kalbimle sana.

Ben geldim kendimden emin ve yapa yalnız,

Kendi güneşimle büyüttüğüm,

Tomurcuklar getirdim açılmamış.

Yüreğimi getirdim sana koşarak,

İncitmediğim topraklarına basarak,

Dökmeden gözyaşlarımı getirdim sana,

Hiç ağlamadım daha dayandım! 

Ve tüm gururumu sana getirdim,

Ve gururla geldim 

Ve anlıma bezediğim onurla,

Ve tüm gülüşümü sana getirdim; yanaklarıma gizleyip,

Dudaklarımda sana şiirler 

Kollarımda sevgimi getirdim; bedenimde büyüttüğüm.

Sana sarılmaya geldim

Kabul edersen hepsini burakmaya geldim,

Sana SARILIP,', 'Ben geldim yüreğine, Ben ümtlerim tutuşurken;  Söndüğü yerden geldim. Ve mutlulukların dans ederken; ağladığı, Ben gözlerin alev alev yanark...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-geldim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkmak Geliyor İçimden', 'sikmak-geliyor-i-cimden-muammer-karatas-iyzqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yırtarak bağrımı aşkın; 

Taşmak geliyor içimden,

Nehirlere doğru coşkun,

Akmak geliyor içimden.

Islanmak denizlerinde,

Ve soğumak ateşinden; 

Gizlice şu dünyadan,

Kaçmak geliyor içimden.

Nefretleri yüreğime; 

Dilekçemle gereğine; 

Arz ederek şu ölüme,

Gitmek geliyor içimden.

Silah koyup başıma,

Son bir kez geçip karşına,

İki çift laf edip sana...

Sıkmak geliyor içimden.', 'Yırtarak bağrımı aşkın;  Taşmak geliyor içimden, Nehirlere doğru coşkun, Akmak geliyor içimden. Islanmak denizlerinde, Ve soğumak ateşinden;...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sikmak-geliyor-icimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Alam Gayrı', 'alam-gayri-cihan-kaya-x4sln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılıkla geçmez anım

Gece gündüz perişanım

Seninledir bir dermanım

Seni gönle alam gayrı...

Hasret ile keder gece

Sensiz olur halım nice

Anlatamam yetmez hece

Derdi sele verem gayrı...

Derdim beni gör neyledi

Aşk ölümü bir eyledi

Herkes bakıp seyreyledi

Gel de gurur bilem gayrı...

Cihan der ki ölüm geldi

Bana bir dem huzur verdi

Mutluluğu cana serdi

Git de mutlu olam gayrı...', 'Ayrılıkla geçmez anım Gece gündüz perişanım Seninledir bir dermanım Seni gönle alam gayrı... Hasret ile keder gece Sensiz olur halım nice An...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alam-gayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-muammer-karatas-9l4wq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin derinliklerine daldım,

Seni bulurum diyerek dün gece...

Kaybettiğim o karanlıklardan; 

Söker alırım diyerek dün gece...

Akan yıldızlar vardı yollarımda,

Ve sırasını bekleyen umutlar,

Bir sürü ümütlerin içinde; 

Seni aradım o bütün gece...

Yoktun oysa ki sen o gecede,

Ve beklediğim sabahın doğuşunda,

Tutunduğum saat kadranlarında,

Seni aradım bulamadım dün gece...

Yıldızlardan ismini yazdım göğe,

Ay ışığından resmini çizdim oysa ki; 

Bir tek sevgini çizemedim diye,

Hepsini sildim gözyaşlarımla dün gece...', 'Gecenin derinliklerine daldım, Seni bulurum diyerek dün gece... Kaybettiğim o karanlıklardan;  Söker alırım diyerek dün gece... Akan yıldızl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dun-gece-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca Şiiri', 'karinca-siiri-gulseren-onay-9p7bm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Minnacık boyuna bakmadan,

Koskoca bir yaprak 

Taşıyordu 

Yuvasına minik karınca…

Farkında değildi adam! 

O,

Çok büyüktü karıncadan……

GÜLSEREN ONAY', 'Minnacık boyuna bakmadan, Koskoca bir yaprak  Taşıyordu  Yuvasına minik karınca… Farkında değildi adam!  O, Çok büyüktü karıncadan…… GÜLSERE...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karinca-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak!', 'sicak-muharrem-cetinkaya-lukxa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıcak! 

Yanıyor ortalık,

Kaynıyor sular! 

………………? 

……………….! 

Yürekler kanıyor! 

.

Bir şeyler olmalı,

Doludizgin,

Apansız! 

…………………….! 

İçimde bir his var,

Olacak,

Biliyorum…

Yağmura gebe bu kara kara bulutlar,

Gözler dolu dolu! 

Gök gürlemede,şimşek çakmada,

Yağmur geliyor! 

Sağnak,sağnak…

.

Sıcak! 

Ortalık yanıyor,

Bir şeyler,

Bir şeyler olacak!', 'Sıcak!  Yanıyor ortalık, Kaynıyor sular!  ………………?  ……………….!  Yürekler kanıyor!  . Bir şeyler olmalı, Doludizgin, Apansız!  …………………….!  İçimd...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sicak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Gözü', 'gonul-gozu-muharrem-cetinkaya-3v5u6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sihirbazı gördüm; 

Pek acayip huyu.

Yok etti,

Kağıda koyduğu suyu…

Ardından; kesti,biçti,parçaladı

Sandığa koyduğu kızı…

Bir de baktım; 

Kız sapasağlam (!) 

Kör etti onca gören gözü(!) 

Dedim ki; bu gözler benim

Her şeyi görür sanırdım.

Ve

Gördüklerime inanırdım…

Ama göremedim…

Aklım olmasa,

Bu sihire kanar,

İnanırdım…

Dedim ki; 

Görmek için hileyi

Pusuyu,

Gönül gözü,

Akıl gerek…

Dedim ki; 

Ayırmak için güzel ile çirkini,

Kara ile akı,

Görmeli gönül gözüyle,

Bu gözler kapalı! ...', 'Bir sihirbazı gördüm;  Pek acayip huyu. Yok etti, Kağıda koyduğu suyu… Ardından; kesti,biçti,parçaladı Sandığa koyduğu kızı… Bir de baktım; ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gonul-gozu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-aynur-sultan-vx6vv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baktığın aynalarımı  bile silmiyorum

ne diyorsun sen? 

gel

bak aynı

bıraktığın gibi bulacaksın aynalarımı 

öyle tozlu, öyle perişan', 'Baktığın aynalarımı  bile silmiyorum ne diyorsun sen?  gel bak aynı bıraktığın gibi bulacaksın aynalarımı  öyle tozlu, öyle perişan...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayna-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim', 'gidecegim-sedat-kocabey-3ind3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehirde son gecemdir,

Artık veda edeceğim,

Son hoşçakal son hecemdir,

Yarın burdan gideceğim.

Yüreğimde bir acıyla,

Unutulmak amacıyla,

Yanımda bir yabancıyla,

Yarın burdan gideceğim.

Ne öfkem var ne darıldım

Kaç gündür böyle duruldum,

Artık iyice yoruldum.

Yarın burdan gideceğim.

Bütün resimleri yakıp,

Gözyaşıyla akıp akıp,

Ve ardıma son kez bakıp,

Yarın burdan gideceğim.

Kıymetini bilecekken,

Her derdini silecekken,

Mutluluktan ölecekken

Yarın burdan gideceğim.

Sevdam ile çağlasan da,

Sabaha dek ağlasan da,

Durmam artık bağlasan da,

Yarın burdan gideceğim.

Ne öfkem var ne darıldım,

Kaç gündür böyle duruldum,

Artık iyice yoruldum,

Yarın burdan gideceğim.

Umutları ipe dizip,

Bir veda mektubu yazıp,

Bütün yeminleri bozup,

Yarın burdan gideceğim.

Sen uyurken döşeğinde,

Bir an durdum eşiğinde,

Sabahın ilk ışığında,

Yarın burdan gideceğim.', 'Bu şehirde son gecemdir, Artık veda edeceğim, Son hoşçakal son hecemdir, Yarın burdan gideceğim. Yüreğimde bir acıyla, Unutulmak amacıyla, Y...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gidecegim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yıldız Kaydı', 'bir-yildiz-kaydi-reyhan-sur-f57t2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR ''YILDIZ'' KAYDI

''Çalıştığım yerde iş azlığından olsa gerek, çoğu kişi; 

onun bunun işi aşı

kim kimin arkadaşı

saat başı

laf savaşı yaparken, kitaplarla kurduğum dostluktan son derece memnunum...'' 

demişim ''98-''99 yıllarında çıkardığımız kültür- sanat, haber- yorum içerikli Cemre Dergisinin Eylül sayısında...

Üniversitedeki görevim sırasında emekli olup da, hemen özel bir yerde yeniden işe başlamam sevindiriciydi benim için.. Nerden bilirdim özel yaşamım allak bullak olacak..şiir dilim tutulacak, ellerime kağıtlardan kelepçeler vurulacak.. ve benim gönül yorgunluğuyla yattığım yeri beğenmemek gibi bir lüks! üm olamayacak...

Akşama dek aralıksız süren çalışmalarımın ardından, duygularımla başbaşa kalabilmek için, düşünebilmek için yürüyorum..

Dünün, yarının, ve an''ın irdelemesini yapmak için yürüyorum... Yarım saatlik bu yürüyüş iyi geliyor bana.. Sonra bir parka oturup yarım saat de kitap okuyorum veya dağınık düşüncelerimi toparlamaya çalışıyorum..

Eşim geliyor sonra.. birer bardak çay da birlikte içip eve yürüyoruz el ele...

Konuyu dağıttığımın farkındayım... 

Geçenlerde eski dergileri karıştırıken Cemre Dergisinin üçüncü sayısında yer alan bir yazımı paylaşmak istedim sizlerle; 

BİR ''YILDIZ'' KAYDI

Çalıştığım yerde iş azlığından olsa gerek, çoğu kişi; 

onun bunun işi aşı

kim kimin arkadaşı

saat başı

laf savaşı yaparken, kitaplarla kurduğum dostluktan son derece memnunum...

Kimi zaman kitabın içinde yaşadığım olaylarla dudağımın kenarında beliren bir tebessüm, kimi zaman da gözlerimde biriken yaşlarla, insanların odak noktası olduğum bakışlarını hissettiğim andaki suskunluğumu alaya alanlara aldırmadan sürdürürüm kitaplarla dostluğumu...

Okuduğum onca kitap arasında üç yıldır vitrin bekleyen ''Kara Vagon''u neden okumadığıma hala şaşarım. Birçok eserini okuduğum Bekir Yıldız''ın ölümünü öğrenince, anısına ''Kara Vagon'' kitabını da okudum..

Güneydoğudaki yaşamı anlatan bu kısa hikayelerde kinlendiğim, üzüldüğüm, içimin bulandığı, acıdığım, güldüğüm anlar oldu.

Kara Vagon öyküsünü okurken, insanların çektikleri çilede başka vagonları gözardı edemedim...

Biz küçükken, demiryolunun içinden geçtiği ''tarla'' dediğimiz, yazın yeşil otlaklarla kaplı, insanların piknik yaptığı bir yer vardı.. Şeker fabrikasına giden yolu kesen demiryolu geçitinin olduğu alan. Biz de komşularla yiyeceklerimizi alır ailemizle sık sık oraya giderdik.. Annelerimiz, ablalarımız ''kuzu kulağı'' dedikleri, ekşi tadı olan otlardan toplarlardı..

Ben, piknik dışında, canımın sıkıldığı zamanlarda da kara trenin geçeceği saatleri seçip tarlaya gider kendibaşıma otururdum bir süre.. Tren geçip giderken o çocuk yaşımda ruhumda koca fırtınaların koptuğu anlar yaşardım..Katarın arka sıralarında yer alan yük vagonlarının birinde, demir parmaklıkları olan küçücük pencerelerden burunlarını uzatan ineklere el sallardım.. Diğer vagonlardaki yolcuların çeşitli duygularını içimde yaşar, hayallere dalardım...

Bekir Yıldız''ın tüm eserleri, kendi hayatının izdüşümüdür..

Kara Vagon adlı öyküsünde geçen bir olayın bir benzeri de ağustos ayında yaşandı yurdumuzda... 18 Ağustos tarihli Milliyet Gazetesinde yayımlanan bir haber vardı ki; Bekir Yıldız''ın pamuk işçileriyle ilgili yazısını aratmıyordu fındık işçilerinin bindiği ''utanç treni''...

**

Güneydoğu Anadolu insanının yaşamını ve kentteki yabancılaşmayı konu aldığı yapıtlarıyla tanınan öykü ve roman yazarı Bekir Yıldız 3 mart 1933''te Urfa''da doğdu. Polis olan babasının görevi nedeniyle çocukluğu Anadolu''nun çeşitli kentlerinde geçti.Adana Sanat Enstitüsü''nde başladığı eğitimini Mersin ve İstanbul Sanat Enstitülerinde tamamladı. Bir yıl çeşitli fabrikalarda çalışan Yıldız 1954''te İstanbul Matbaacılık Okulunu bitirdi. Bir süre dizgi operatörlüğü öğretmenliği yaptı. 1962''de işçi olarak Almanya''ya giden Yıldız, çeşitli fabrikalarda çalıştı.

Sanat hayatına, 1951''de Tomurcuk dergisinde yayımlanan bir öyküsüyle başlayan Bekir Yıldız, Kaçakçı Şahan''la 1971 Sait Faik Armağanı''nı kazandı.

Ününü; konularını Urfa ve çevresinden alan ilk öykü kitabı olan ''Reşo Ağa''yla kazandı. Çeşitli dergi ve gazetelerde yazıları, röportaj ve öyküleri yayımlandı.

''Bedrana'' ve ''Kara Çarşaflı Gelin'' adlı eserleri sinemaya uyarlandı. ''Kara Vagon''la öykü dalında ''May Edebiyat Ödülü''nü, ''Darbe'' adlı romanıyla ''1990 Milliyet Yayınları Roman Yarışması''nda birincilik ödülünü aldı.

Öykülerinde daha çok Anadolu insanının yaşamını, ağa- köylü ilişkilerini, törelerin katılığı, kadının ezilmişliği, kan avası ve kaçakçılık gibi konuları işledi.

Almanya''ya çalışmaya giden Anadolu insanının yaşantısını yansıtan öykülerinde ise kahramanların batı toplumuna yabancılaşmasını, iç ve dış çatışmalarını anlattı. Ayrıca, evlilik kurumunun çarpık yanlarını ve kırsal kesim insanının kentteki bunalımını ele aldı.

Diğer yapıtları; 

Sahipsizler, Evlilik Şirketi, Beyaz Türkü, Alman Ekmaği, Dünyadan Bir Atlı Geçti, Demir Bebek, Mahşerin İnsanları, BBozkır Gelini adlı öykü kitapları

Halkalı Köle, Aile Savaşları, Ve Zalim Ve İnanmış Ve Kerbela adlı romanları

Ölümsüz Kavak, Arılar Ordusu, Canlı Tabanca va Şahinler Yuvası adlı çocuk kitaplarıdır.

**

Bekir Yıldız, 8 Ağustos 1998'' de aramızdan ayrıldı. Bir Yıldız daha kaydı.. Ruhu şad olsun...', 'BİR ''YILDIZ'' KAYDI ''Çalıştığım yerde iş azlığından olsa gerek, çoğu kişi;  onun bunun işi aşı kim kimin arkadaşı saat başı laf savaşı yapark...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-yildiz-kaydi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir', 'misafir-ugur-aydin-2-x3wrd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir selem gibi girsen geceme 

dilimde mutluluk olsan heceme 

kar taneleri gibi düşsem mahşere 

devetsiz misafir kabulum bugün 

bana  hatıra kaldı dilimde dua  ismin 

cüzdanım ''da ''duruyor yırtılmış  resmin 

ne zaman istersen gözlerime gir 

kabulumsun her gün davetsiz misafirim', 'bir selem gibi girsen geceme  dilimde mutluluk olsan heceme  kar taneleri gibi düşsem mahşere  devetsiz misafir kabulum bugün  bana  hatıra ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/misafir-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle ölüyüm ki...', 'oyle-oluyum-ki-zafer-zengin-etnika-68o3x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

I.

ikiye ayırmışım

kan gölü içine

göz yaşı mayalandığında gövdemi

yenilgim 

bayrağım indiğinde başlar

yaman yanında taş kalırdı

sus kadındı

adım orada susardı

II.

- kitabım hayinin elinde suç unsuru -

dilimde aşk yalvardım

kapılar kırdım

kendimi doğradım

anlatamadım

sus’da

tanrı unutulurmuş

düşünce anladım

derzime, kan yakındım

III.

ince giymiş ömrü

ikimizi büyütür

arsız bağrımızda uslanmaz

usandırmaz

hepsi kül ederse kendini

bilmeyecekler

susun ömrü yediğini

sen bil ki

beni boğ içinde

mazlumum düştüğüm yerde

sus

öyle ölüyüm ki

titrerken susun elleri

saplanıp zehirimin kabuğuna

kayıptır içeri attığım

üşümek değil

sus

IV.

mabedinde kokum

ayağım elim

görmediğim yüzü sevdim

yemek kadar yapışkan değil ki

su için kan döker rengi

şair keser elleri

ya öpüşleri

kimse kleopatra dememeli

kendini öldürür güzeller

yüzlerinde renkleri

çıbanlar öksürür

et kokusu sinmiş çarşaflarda

hepsini yazdılar

yazdırdılar sana

madem ki irin var

sus

V.

aklım zayi tutanaklarda

savaş zayiatı

kim bulsa ben öleyimler de

/denizi düşünüyorum bu aralar.. yangın içim..sözümle besleniyor balıklar 

sayıyorum larvaların dansını adım adım.. biliyorum içlerinde ışık varken

ağır ağır sönüyorlar..duyuyorum sızılarını.. sızlıyorum..acıyorum./

öyle güzel düşmesi

sardunya kadar nefesi

bel ki destina

koşsa yaprağın kenarını anlatsa

anlasa

iki iklim yetmez çığlığına

konuşmayacaksan

sus

getir dilini

imgesi kendisi

koparsam 

içime düşer sesi

böylesi sevmeli

unuttum

bakılmamış analara

zehir sürülmüş bıçak uçlarına

umuttum

unuttum

gençliğim tapınak anadolu

dönmüşsen sırtını

sus

unut

VI.

hançerim gelip geçmeli içinden

sorgulanmalı ayrılıp kavuşmalar

sus’a henüz çok var

seslerim fısıltı şimdi

başlıyorum

titreme

sarı ölgün gülün yüzünde

leke sürseler

kirpiği düşer gövdeye

ahh inleme

hasret uzaktır öpülmeye

bitmemiş işlerden başlar su

akışkan ki

civa sürülse durmaz yerinde

ağrılı yüzünde ömür pembe

satıh

el konan perdahlı sehpa

asıldıkça bir zulüm

gül gelir insana ölüm

sus

adı şimdi hiç

VII.

gölgeye süzülür tüysüz kanatlar

uçlarında geçilen yolların ortası

çıksa kar kapatır

sel basar

tipi boran

yakalasa sus

kurgu kırılmadan..unutulmadan/

yeşil yazılar yeniden doğuşa

kırmızılar ayrılığa

bordolar hüzne

siyah düşe

beyaz hiçe

nefesinden ver yüzüme

bırak gülümsemeni gözüme

şimdi ilişme

sızım düşer dizlerime

s a k l a n m a 

asit kokar koltuk altımda

yasla dudağını yasla alnıma

a y r ı l m a 

sus

02 05 2005

.', '. I. ikiye ayırmışım kan gölü içine göz yaşı mayalandığında gövdemi yenilgim  bayrağım indiğinde başlar yaman yanında taş kalırdı sus kadınd...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/oyle-oluyum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dipsiz Kuyularda Delik Kovalar', 'dipsiz-kuyularda-delik-kovalar-adnan-durmaz-xecwj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuza uzanan bozkırın bilinmez gizeminde 

Kara kışla kar altında 

Şahmaran gibi uykuya dalan 

Sarı sıcaklarında amansız ağustosların 

Cenderek yelleri estiği zaman 

Üzerinde toz burgaçları kurulan 

İnce ve deri bir yoldur hüzün 

Nereye varır bilinmez 

Bazan savaş- bazan ekmek kavgası 

Gidilir gidilir gelinmez... 

Hüzündür gözleri körpe gelinin 

Gurbet yollarına dikilmiş 

Bekler yılları işleyip yüreğinin alnına 

Feri biter bakışlarının 

Özlemin destanı yazılır 

Solgun güllere dönen yüzüne... 

Yad elden dönmeyenin dağılır dirliği 

Yavuklusu yad koynuna sürülür 

Hüzün ki gurbet dönüşlerinde 

Açlığın- kıranın yıkamadığı 

Yıkan kara haberdir... 

Hüzündür 

Kısır göğün karnındaki ölü bulut 

Anasının yevmiyeci gittiği 

Tarlanın anında yatan bebedir 

Mor sinekler oğul verir yüzünde 

Ala yılan kayıp kanını emer 

Babası ister dönsün gayrı gurbetten 

İsterse dönmesin varsın... 

Susuzluktan yarık yarık yarılmış 

Taşa kesmiş sarı göğün altında 

Yağmur dualarıdır hüzün 

El kadarcık tarlalarda körpe ekinler 

Sararıp boyun büker- can çekişir 

Yağmayacak yağmurları bekleyen gözdür hüzün 

Ve harman yerinde yığılınca çeç 

Bin bir çile ile harmanlanarak 

Ansızın inen sağanak 

Ansızın deliren su 

Alır gider bir yılın umudunu 

Toprak ağası mübarek 

Evlat acısından beter 

Hüzün ki... anlatılmaz... 

Sonsuza uzanan bozkırın bilinmez gizeminde 

Dipsiz bir kuyudur hüzün 

Dudaklarda çatlayacak yer kalmayınca 

Delik bir kovası vardır kim bilir kimden kalmış 

Çekesiye akıp gider bir avuççuk kirli su... 

Sevgilim gözlerine bakan gözlerim 

Dipsiz kuyularda delik kovadır 

Hüzündür... anlatılmaz... 

Adnan DURMAZ 

02.06.1993', 'Sonsuza uzanan bozkırın bilinmez gizeminde  Kara kışla kar altında  Şahmaran gibi uykuya dalan  Sarı sıcaklarında amansız ağustosların  Cend...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/dipsiz-kuyularda-delik-kovalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S i z e d e m e d i m...', 's-i-z-e-d-e-m-e-d-i-m-zafer-zengin-etnika-f7sy9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

I.

size demedim

ellerimi sevdim

II.

siyah saçları aklımda

ilk kurtarılacak

yangın cıksa

III.

kapıya konan  kuşun

uzun kanatları

sesi kıpırdamasın

ağır ninnilerle seveceğim

kapalıyım dışarı

sarı lokma  ‘ceviz ağacı kırılgan

dal gibi boynu

toplasam meyvelerini 

kopartır avuçlarımı

tutamam yelinden

önüme düşen adamı

ki; ben

soracakken yaşını

yüzü ki; ‘şen gülen bir şey

takılıyor boynuma kollarıyla

adın diyorum ‘unutuyorum

diyor aslında

 ilk gelen fırtına 

| anımsadım..rüzgar soğuk ve sıcaktı |

IV.

kabartıp tüylerini taşlıyorum

toz var elbet

burnuma kaçıyor

burnum bana  ağlıyor

musa heykeli geliyor aklıma

olmasaydı

bu olurdu şansıma

o çocuk taslak 

kimse gülmesin ona

çeşme bulmalıyız yanağına

sunak yapardık

ağlarken bu kadar güzel olmasa

V.

saydım hecelerini ‘güpe gündüz

düm düz ‘titreye titreye

yazken kış geliverse

öyle titredim işte

dayanmazdı kimse

böyle dönen güne

onu görünce deli olunan zaman/

ısır et’imi, açlık görmedi

bak aynaya kocamansın 

dağ yıkılsa ‘çocuk kalmaz altında

her kaya ‘yerinden oynar nasılsa

sevmiştim işte’nasılsa

VI.

Elde sabır beklerken/

size demedim

sevişmek için gelmiştim

VII.

yazdı ‘susamıştım

kana kana ‘sev içtim

zaten sizi görmemiş

size dememiştim

içim yanarken ‘sev içmiştim

kendimi de sevmiştim

durulan yer/

akar su sana…

23 01 2005

.', '. I. size demedim ellerimi sevdim II. siyah saçları aklımda ilk kurtarılacak yangın cıksa III. kapıya konan  kuşun uzun kanatları sesi kıpır...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/s-i-z-e-d-e-m-e-d-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çengili Meyhaneler Sokağı', 'cengili-meyhaneler-sokagi-adnan-durmaz-wnuyg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karanlıkta çınlayan kahkahaları 

alabilesiye şuh 

fevkalâde haşarı 

birbirine düşerdi onun yüzünden 

Ege’nin en namlı korsanları 

dağlardan eşkıya indirir 

midillili eleni 

güneş sarısı saçları 

sevdası insanı bitirir 

sanki buz mavisi teni 

ve bütün bunlara ağlıyor şimdi 

yaşlı bir yosma gibi unutulmuş 

eli kolu inmeli-mecal vermez ayağı- 

kanar suskunluğuna derbeder 

çengili meyhaneler sokağı... 

hani o akşamlar 

coşkuyla açardı yıldızlı perdesini 

cıvıl cıvıl yosmalar 

zil ve kadeh sesleri 

havada 

kadın 

kumar 

kavga kokusu 

hani uzak adaların denizcileri 

koç boynuzu bıyıklı zeybekler. 

silinmiş esamisi 

bir daha dönmez zamanda 

kurumuş toz olmuş gülün yaprağı 

terkedilmiş aşıkların gözleri kadar ıssız 

zamandan habersiz boşuna bekler 

çengili meyhaneler sokağı... 

gülüşünden çıngılar saçılırdı geceye 

çingeneler gül satardı-yalın ayaklı-güleç 

gözlerinde zühre yıldızı yanardı 

sazendeler meşk vurur 

eleni göbek atardı 

her gece mutlaka cıngar çıkardı 

bir gecelik aşklardan 

yıllarca kaçak gezer 

hapis yatardı 

adı dokuza çıkardı 

intizar alırdı-umursamazdı 

böylesine yıkılışı ah tutmasından 

gayri tek söz söyleyemez dudağı 

elbizli kirpikleri hüzne saplanmış 

çengili meyhaneler sokağı... 

iki parçaya böldüler 

denize çıkan yanına barlar dizildi 

kalanına gar sokağı dediler 

şirketler-matbaalar-ve sair iş yerleri 

başka gözlü adamlar ve kadınlar 

yalnızca arada bir 

eski ehl-i keyifler 

geçip gider utanır gibi sessiz 

yıkılır her soluk anlamsız bir boşluğa 

sahipsiz mazilerin son durağı 

ölür öldüğünden habersiz 

çengili meyhaneler sokağı...- 

20.7.l995 

adnan durmaz,ben gidersem ay sen-deler,art yay,ank', 'karanlıkta çınlayan kahkahaları  alabilesiye şuh  fevkalâde haşarı  birbirine düşerdi onun yüzünden  Ege’nin en namlı korsanları  dağlardan ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/cengili-meyhaneler-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnziva', 'i-nziva-ugur-aydin-2-lri4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne hatır soracak ses 

ne de kelam edecek nefes 

ne söylencek söz...

ne de konusacak dil bıraktılar...

bilirim söylecek çok şey..var 

sende  ki bitmez tükenmez nefes

sabır bendeki..adı...inziva  duymak istiyorum 

seni seviyorum diye bir ses...

gel al kalbim senin hiç düşünmden aç bak içine

kendine bir  yer seç...

derinlere inme  sakın irkilme.... 

duyacaksın  seni seviyorum diye bir  ses.....

ne hatır soracak ses 

nede kelam edecek nefes 

ne söylencek söz...

nede konusacak dil bıraktılar...

işte bundandır ki sessizliğimin,

adı inziva oldu...

pınarlarından yaş dökülemeyen gözlerim doldu,

kim alabilir ki seni... benden

kim  aldı

işte bundandır  kalbimde bir ses 

seni seviyorum kaldı....', 'ne hatır soracak ses  ne de kelam edecek nefes  ne söylencek söz... ne de konusacak dil bıraktılar... bilirim söylecek çok şey..var  sende  ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/inziva-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Öyle Yatma*', 'oyle-yatma-kubilay-enginol-mrjt8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle Yatma! 

Heyecanlanıyorum...

Bilirsin, güzelliklere

Dayanamıyorum...

Şimdi yaraşır yanına

Buz gibi duble rakı

Şöyle limonu bol

Akdeniz salatası

Öyle yatma

Tabakta

Ağzım sulanıyor,

Bu yürek ızgara balığa

Dayanamıyor', 'Öyle Yatma!  Heyecanlanıyorum... Bilirsin, güzelliklere Dayanamıyorum... Şimdi yaraşır yanına Buz gibi duble rakı Şöyle limonu bol Akdeniz s...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oyle-yatma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlaşılması Zor Kelimeleri Seçiyorum Yazarken Vasiyetimi', 'anlasilmasi-zor-kelimeleri-seciyorum-yazarken-vasiyetimi-haldun-gezer-en783', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyorum,

                                                                                      Sen bilmeden

                                                             ellerimde bıraktığın sıcaklığı.

                                                                              her gitmenin içinde

                                                            bir git varmış şimdi anlıyorum.

                                                               özür diliyorum çözememişim 

                                                                         gözlerinde git deyişini

                                                                  ve  şimdi çok zor kelimeler

                                                                                            seçiyorum

                                                                                     anlaşılmıyacak

                                                                              yazarken sana dair

                                                                                        vasiyetimi …

ANLAŞILMASI ZOR KELİMELERİ SEÇİYORUM YAZARKEN VASİYETİMİ

hafif bir çıplaklık gıdıklıyor,

dinlediğim şarkıları.

sonra bana dönen güneş

halbuki gölgesi sarnıça düşüyor

ki o sarnıç

yüzyıllık anılarla ayakta kalıyor

insanlar nasıl bekler ki 

benden düşmememi.

benim köklerim yok ki yanarım küllerimi

çaldırırım

sen yine gözlerimle aranırsın

şartlı refleks.

sen yine yalan söyleyerek iğnelersin umutlarımı

olsun.

firari bir şiir çıkar belki ağzımdan 

hakkını helal eden bir otostop düşer belki payına.

insanlar vardır yaşamımızda

beklerken bir bayırda çıkmışken yükseğe

beklerken,

''belleksiz bir tanrıyı''

ben atarım kendimi boşluğa

şartlı refleks.

kaybederim onca varlığıyla aklımıza giren bu kentte kaybederim.

kafa yapar elimin tersiyle ittiğim müzik

şairler kafa yapar anlamazsın.

senin kazandığın yerde benliğim dışarda kalır.

sokak yosmaları aldanırmış benim gibi; 

yalan tek sensin bu kentin aldatıcısı

rölün bu belki yazdığım bu kitapta.

korkarsın sen şimdi

sen korkunca ellerim terler

sen korkunca ben girerim oyuna

dans et dans et korkmazsın

dans ederiz korkmayız

ayrılırız anlarız ki aynıyız', 'Gidiyorum,                                                                                       Sen bilmeden                               ...', ARRAY['Türk Edebiyatı','Şiir','Haldun Gezer']::text[], 8.5, '{"poet":"Haldun Gezer","poet_slug":"haldun-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/anlasilmasi-zor-kelimeleri-seciyorum-yazarken-vasiyetimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Demirden Gemi II*', 'demirden-gemi-ii-kubilay-enginol-nzp6k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demir kapılar açılınca,

Bir avuç dert saçıldı avluya.

Kahırları içlerine gömülmüş

Dağıldılar bir o yana, bir bu yana.

Güneşe hasretlik çektin mi hiç? 

Sevgiliye kavuşur gibi baktın mı ona? 

Gözlerini yakmasına aldırmadan,

Bir saatlik zamanının inadına.

Yeşil ne renkti hakikatten? 

Ya deniz mavisi? 

Küstüler sanki, yok bile hayali.

Ezberledin duvarın kahverengini.

Gri kahrolası demirlerin rengi.

En son ayrıldığını söylemeye gelen

Nişanlısında gördüğü yeşili,

Gözyaşlarıyla siyaha gömdü.

Kapanırken ağır demir kapılar

O, kaderini paylaşan griliğe dönüyordu.', 'Demir kapılar açılınca, Bir avuç dert saçıldı avluya. Kahırları içlerine gömülmüş Dağıldılar bir o yana, bir bu yana. Güneşe hasretlik çekti...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/demirden-gemi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızımız Gelin Oluyor/Komedi Serisi', 'kizimiz-gelin-oluyor-komedi-serisi-mehmet-akif-gulhan-wvzca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evimize dünür geldi,yanında güvey ile 

Kızımızı isterler,Allahın emri,peygamber kavli ile 

Damadı beğendik amma biraz korkutalım

Fikri halis ise kalır,yada kaçar, can havli ile 

Gelin bizim kızımız,damada’da bizim diyelim

Kızımız narindir,nazdır,bin kese altına verelim.

Kıyamadık damada, tartalım sabrını,usul ile

Bin kese sabır ile tahammüle verelim.

Değdirmedik yüzüne,tokat gibi gelir narin yel

Çeşmeyi usul açtık,zannetmesin akan sel

Bir eli yağda bir eli balda istemeyiz,haşa

Kırmaz isen gönlünü,üzmez isen verelim 

Hanım hanımcıktır,kaldırmaz asla kaşını

Harç yoksa mutfakta,bir avuç un ile yapar aşını

Akşam koyar ise sofraya,ekmek ile soğan başını

Öf! ! demez, daralmaz isen  verelim 

Yirmi kişide gelse akrabadan misafir

Hamur işi tatlı baklava hepsi çarşı işi, hazır

Komşu kek yapmış yirmi santim kabarmış,özenmiş

Onunki var,yok bir buçuk santim tepsiden kazır.

“Ne güzel olmuş hanım” dersen verelim

Bebek iken alçak sesle dinledi ninniyi

Asla üzmedi kimseyi ne anneyi ne emmiyi

Akşam ezanını ağır aksak okuttuk müezzine 

Avaz niyaz etmez,korkutmaz  isen verelim 

Ağzı var dili yok biliriz,biz dedik diye güvenme 

Bazen tadı tuzu diyorlar evliliğin hırı,dalaşı

“Ben duymadım” diyenlerin yalancısıyım,

Dır dır ederse, kulağını tıkarsan verelim 

Sakarlık nedir bilmez,kap kacağı asla tutmaz

Önünde gördüğü eşyayı şeytan aldı der bulamaz

Aniden seslenince döner,belki Çin vazoyu kırmaz

Kırar ise,parmak arasından bakarsan verelim 

Eli açıktır yardım sever,bütün mahalle ondan giyer

Sevmez dolapta fazla eşyayı hayrına sadaka eder

Bir yıl çalışıp aldığın takım elbise gitti gider.

Sık dişini efendim,protezin sağlam ise verelim

On yıl ayrı kalsa anasından, yemin ederiz aramaz.

Evlenince aileden inan kimse yanına varamaz

Annemde “kediyi özledim nicedir” derse yaramaz.

Her hafta anasına,dadısına yollarsan verelim. 

Kırılmasın darılmasın diye niceden

Sakınırız bir tek sözden bir tek heceden

Kızından ayrılamaz, gözü yaşlı, paşa babadan

Destur isteyelim,ikrar alalım da verelim.

Süt hakkıdır gül yüzlü ananın, yemedi yedirdi

Altı ayına geldi,emeklemedi,sayesinde yürüdü.

Tartsak, kemiksiz, kesin doksan okka gelirdi,

Süt hakkını verir,helalleşir isen verelim.

Biz sana anlattık,baştan söyledik,bu sabır işi

Burada gördüğün akraba-ı talukattan  her kişi

Ne yarım bırakırlar,nede tam bitirirler bu işi

Dalda gösterirler sana kuşu,ağzın ile tut da verelim.

20 Mayıs 2004 Mehmet Akif Gülhan', 'Evimize dünür geldi,yanında güvey ile  Kızımızı isterler,Allahın emri,peygamber kavli ile  Damadı beğendik amma biraz korkutalım Fikri halis...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kizimiz-gelin-oluyor-komedi-serisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ışık ben kelebek', 'sen-isik-ben-kelebek-sair-yatakkusu-zapgr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben kelebek,

ben neyim? 

zaten dar, azcık bir zamanım vardı 

hafif ömrüm ancak sürecekti guruba dek

rüzgarda savrulmuş inanılmaz kısa, tek,

sehersiz, yağmursuz bir yaz günüm vardı.

sen ışık,

sen Yârim.', 'ben kelebek, ben neyim?  zaten dar, azcık bir zamanım vardı  hafif ömrüm ancak sürecekti guruba dek rüzgarda savrulmuş inanılmaz kısa, tek, ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yatakkuşu']::text[], 8.5, '{"poet":"Şair Yatakkuşu","poet_slug":"sair-yatakkusu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-isik-ben-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesellinin Tükenişi.. (düzyazı)', 'tesellinin-tukenisi-duzyazi-ayse-i-smetoglu-c1tvz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep sana ''seni seviyorum'' demeyi arzuladım ve yığdım arzuları kalbime,teker teker yok ettim,yok saydım,yok yere aşıktım zaten,yokluğunda yaşadım,yokluğuna yandım,yokluğunda tükendim ve tükettim yokları...

   Şimdilerde '' teselli ''   kelimesini yeni öğrendim..Ağlayan çocuğu,yaşlı teyzeyi,ayakkabı boyacısını, simitçiyi teselli ediyorum.Onlara hayatın güzel yüzünü (!) ,yoksuz yüzünü gösteriyorum.Mavilik diliyorum onlara, umuttan hediyeler veriyorum.Kimi zaman ellerinden tutuyorum beraber koşuyoruz,kimi zaman da dertlerini çalıyorum, ortak oluyorum acılarına...

   Bugünlerde kendimi yaşama kaptırdım.kitaplar okuyorum, sinemaya gidiyorum,mistik takılıyorum, dostlarla buluşuyorum..derken geçiyor hayat ama sanırım bunlarda tesellinin hayatıma girişiyle ilgili,belki de bunlarda buluyorum teselliyi..

Yok hayır aslında ben ayakta kalbilmenin savaşını veriyorum desem daha doğru olacak..

   Başka uğraşlar olunca hayatımda ölüm gelmiyor aklıma, yorgun düşüyorum akşamları! Çarçabuk dalıyorum uykuya,rüyalarımsa karmakarışık..! Senli günlerim geliyor da aklıma, yaşadığımız bir şeyin benzeriyle karşılaşınca,eziliyorum,büzülüyorum...Kendimi toparlayamıyorum,tokat yemiş gibi kalıyorum ortada..sarsıyor beni çevremdekiler,kendime geldiğimde yanaklarım ıslak, hıçkırıklar ayyuka....

   Acaba sen bensiz ne yapıyorsun? Teselli kelimesi girdi mi hayatına? Belki başka sevgilerde buldun  teselliyi, belki de yaşama kaptırdın kendini...Kim bilir belki senin de simitçiyle muhabbetin vardır, farkındayım bunlar da teselli...? ? 

   Ben ne zaman kopsam hayattan, hemen seni düşünüyorum, o kadar sen olmuşum ki,o kadar benden geçmişim ki..Ne teselli yetiyor ne de hayatın akışı! Artık ağır bir yükle yaşıyorum..Ve dönüp geleceğin, gelip aynı hataları yapmayacağımız günü bekliyorum..Ama başka bir sevgiye kapıldığım, senin kapıldığını duyduğum gün, işte o gün yokları da alıp buralardan gideceğim....

05.07.2003', 'Hep sana ''seni seviyorum'' demeyi arzuladım ve yığdım arzuları kalbime,teker teker yok ettim,yok saydım,yok yere aşıktım zaten,yokluğunda yaş...', ARRAY['Türk Edebiyatı','Şiir','Ayşe İsmetoğlu']::text[], 8.5, '{"poet":"Ayşe İsmetoğlu","poet_slug":"ayse-i-smetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tesellinin-tukenisi-duzyazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidan boylum', 'fidan-boylum-ugur-aydin-2-y8p1q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüzünde tebessüm kaybolup durdu 

gözlerin bu akşam neden mahmurdu

sesinde ki hüzün derinden vurdu

gel gitme bu akşam kal fidan boylum 

yeşil  gözlerin  yaşlarla  dolu

söyleyen  dilin  söylemez  oldu 

sesinde  ayrılık  saklanıp  durdu 

gel gitme bu akşam kal fidan boylum

ayrılık bu akşam beni ''de'' vurdu

beni bensiz bırakma kal fidan boylum 

ruhum bedenimden kopup kayboldu 

gel gitme bu akşam kal fidan boylum 

ellrin elimden kacıversede

ayrılık saati geliversede..

bedenim ayrıysa ruhum seninle

gel gitme bu akşam kal fidan boylum', 'yüzünde tebessüm kaybolup durdu  gözlerin bu akşam neden mahmurdu sesinde ki hüzün derinden vurdu gel gitme bu akşam kal fidan boylum  yeşil...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fidan-boylum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-ugur-aydin-2-s132v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YORGUNUM

yorgunum artık yıllardan 

yorgunum zamansız zamanlardan 

yorgunum sensizlik dolu sabahtan 

yorgunum seni senle yaşayamamaktan 

yorgunum yalnızlıktan 

yorgunum ayrılıktan 

yorgunum yarınsızlıtan 

yorgunum seni sensiz yaşamaktan', 'YORGUNUM yorgunum artık yıllardan  yorgunum zamansız zamanlardan  yorgunum sensizlik dolu sabahtan  yorgunum seni senle yaşayamamaktan  yorg...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yorgunum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-ugur-aydin-2-bm9ua', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çoktan kelepcelediler elleri çoktan

çoktan  yandı  bu  şehir  içinde 

yanmayan  kim  var  yar

sana bırakmadılar bu şehri 

zalim galata bankerleri

onlar aşksız yakmıştı 

istanbulu ve içindekileri 

kalmadı bu şehirde ne sana ait ne bana ait aşk....

bu cırpınışlar boşuna...

yakılacak şehirmi var arkadaş', 'çoktan kelepcelediler elleri çoktan çoktan  yandı  bu  şehir  içinde  yanmayan  kim  var  yar sana bırakmadılar bu şehri  zalim galata banke...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/arkadas-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Öldün Bende', 'sen-oldun-bende-i-lknur-cekici-n94ca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüm sabah dalgalara

Dalıp gitti gözlerim

Yılmadı martılara

Eşlik etti düşlerim

Ne zaman bu şehire 

Dönsem unuttum diye

Köşe başı hayalin

Bırakmaz bir an bile

Banklarda sevgililer

Elele göz gözeyken

Hırçınlaşan dalgalar

Karayı dövüyorken

Martı sesleri ruhumda

Rüzgarlar estirirken

Gülen her yeşil gözde

Ben seni arıyorken

Unutmam mümkün değil

Seni sensiz yaşıyorken

Son gecenin matemi

Doğuyor gecelere

Son bakışın izleri 

Duruyor gözlerimde

Seviyorum diyen sesin

Hala burda bu evde

Kara topraklara verdim

Yüreğimi ben seninle

Sen öldün bende senle

Gömüldüm gecelerde', 'Tüm sabah dalgalara Dalıp gitti gözlerim Yılmadı martılara Eşlik etti düşlerim Ne zaman bu şehire  Dönsem unuttum diye Köşe başı hayalin Bır...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-oldun-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahır mektubu', 'kahir-mektubu-ugur-aydin-2-9mdcf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir son vardır son için ben buna şaşıyorum..

bırakıp gitsen bile bak  hala yaşıyorum...

o kahır mektubunu boynumda taşıyorum...

kalbimin üzerine ismini yazıyorum...

kurmuşsun dar ağacını ben beni asıyorum..

aydınlık gündüzlerde karanlık yaşıyorum...

o kahır mektubunu boynumda taşıyorum..

bedenimin üstüne ismini kazıyorum....

dizilmiş şişelerle kafayı cekiyorum...

kadehlari kaldırıp şerefine diyorum..

yıkılmış ümitlerim berduşu yaşıyorum...

bu kahır mektubunu al sana yazıyorum...', 'bir son vardır son için ben buna şaşıyorum.. bırakıp gitsen bile bak  hala yaşıyorum... o kahır mektubunu boynumda taşıyorum... kalbimin üze...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahir-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son durak', 'son-durak-ugur-aydin-2-bfgfk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'el sallanmaz dil konuşmaz 

çıkılan son yolculukta

hava puslu gözler yaşlı 

varılınca  sondurakğa....

bir sessiz karanlık çöker..

sevenlerin yüregine,

el sallanmaz dil konuşmaz 

çıkalan bu yolculukta...

eller üstünden inersin 

kara toprağa gecersin 

el sallanmaz dil konuşmaz 

varılınca  sondurağa...', 'el sallanmaz dil konuşmaz  çıkılan son yolculukta hava puslu gözler yaşlı  varılınca  sondurakğa.... bir sessiz karanlık çöker.. sevenlerin ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-durak-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Migren', 'migren-sedat-kocabey-db8gd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen uykunun en tatlı yerinde,

İnsana hayatı zor eder migren.

Canından bezdirir her seferinde,

Ağrıdan gözünü kör eder migren.

Doğduğuna pişman olurcasına,

İnletir adamı ulurcasına,

Sanki zorla nefes alırcasına,

Ciğerini yakar kor eder migren.

Gül gibi boynunu büküp solarsın,

Saçlarını çekip çekip yolarsın,

Alnına bir tülbent sıkıp dolarsın,

İnsanı ölüyle bir eder migen.

İnan ki hayatla kesilir bağın,

Sofraya boş gelir gider tabağın,

Bir gün solun tutar bir günde sağın,

Saçını zamansız kır eder migren.

Bozulur yiğitlik kalır mı serde,

Işığı yaktırmaz açtırmaz perde,

Bir de ilacının bittiği yerde,

Vallahi hayatı dar eder migren...', 'Bazen uykunun en tatlı yerinde, İnsana hayatı zor eder migren. Canından bezdirir her seferinde, Ağrıdan gözünü kör eder migren. Doğduğuna pi...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/migren-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Ve Aşka Dair Kardeş Dizeler', 'hayata-ve-aska-dair-kardes-dizeler-kamil-aydemir-vzqni', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben memleketim gibi çok renkli kültür bahçesiyim 

kardeşliğin adresi 

aşkın susturulmak istenen sesiyim 

memleket kokulum 

seni sevmek tek lüksüm 

garibanlara analık eden hayata küsüm 

varsın benim suçum olsun 

yaşamdan ve aşktan yana onurlu yürüyüşüm 

günler mayın tarlası 

dudaklarımızda kekremsi bir tad olsa da hayat 

koynumuzda imbat 

gözlerimizde kadifekale 

martılarla konser vereceğiz kordonboyu’nda 

denizdeki balıklara 

havada uçan kuşlara 

ordan gelip geçenlere 

yüreğinde sevgiye yer açanlara 

konserimizde yer yok aşkı yaralı bırakıp kaçanlara 

bizi alkışlasın yeter 

karşıyaka güzelyalı bornova gültepe 

alsancak basmahane buca karabağlar narlıdere 

sevdamız dolaşsın istiyorum 

ilden ile 

dilden dile 

kürt kızları sevdamızı düşsün kilime 

lazlar gürcüler 

kafkasların eteğinde ezgi büyüttürsün 

kemençeye tuluma 

sevgimizin sıcağında yaslanıp akordeona 

çerkezler hüzünlerini unutsun 

yürek tezgahımdaki sözcükler gibi halaya dursun 

zeybek sırtakiyle kadeh dokuştursun 

mardin sokaklarındaki suryani çocuk gülsün 

çok acımasızdır hayat 

zorlu yollarında düşlerini düşürürsün 

sevdiğim benden uzaklarda üşürsün 

sevdamda mutlulukla buluşursun 

biz söyleyelim kardeşliğin türküsünü 

sonlarını başımızdakiler düşünsün 

hayatın tuzağına 

insanlığın uzağına düşenler 

sevgimizin ışığında yolunu bulsun 

varoşlar yoksulluktan kurtulsun 

isterim ki aşk 

sivas’ın alnındaki kara lekeyi silsin 

ama çıkmayan lekeler vardır istendiği kadar yıkansın 

sevdiğim var mısın 

sevgimizi işlemeye maviye 

karadeniz’de hiç solmayan yeşile 

düşlediğimiz günlere yürüyelim elele 

ölüm bile önümüzde eğilsin 

sen acıların oyuncağı değilsin', 'ben memleketim gibi çok renkli kültür bahçesiyim  kardeşliğin adresi  aşkın susturulmak istenen sesiyim  memleket kokulum  seni sevmek tek l...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/hayata-ve-aska-dair-kardes-dizeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıran', 'hatiran-ugur-aydin-2-panoy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saate ilişiyor gözlerim

Sensizlik kor gibi düştü yüregime 

Böyle gecsin yalancı günlerim

Dilimde elveda cıkıyor  yüreğimde kal... 

Yetmiyor sevgiler yetmiyor aşklar

Aynı saatlerde sensizlik başlar

Aydınlık içinde karanlıklar var

Dilimde elveda yüreğimde kal... 

Ne gelen bulunur ne hatır soran 

Sensizliktir beni bergahta yoran 

Bende bıraktığın bir tek hatıran 

Dilimde elveda yüreğimde kal', 'Saate ilişiyor gözlerim Sensizlik kor gibi düştü yüregime  Böyle gecsin yalancı günlerim Dilimde elveda cıkıyor  yüreğimde kal...  Yetmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatiran-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-ugur-aydin-2-i8sr8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ah ah öyle yalnızım ki koca istanbulda 

yarınlar içinde yarınsızlarda 

treni kaçırdım çok zaman oldu... 

bekleyen beklemez...yalnızlık oldum 

suclu kim  dir diye sorma bana sen 

makinistti kactığında o tren

zaman gelince yalnız kalınca ben 

ne beklemeyen ne kaçan tren 

suçlu kim 

biliyorum

sadece....BEN', 'ah ah öyle yalnızım ki koca istanbulda  yarınlar içinde yarınsızlarda  treni kaçırdım çok zaman oldu...  bekleyen beklemez...yalnızlık oldum...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-187-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölen biri', 'olen-biri-ugur-aydin-2-gey2g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sende öleceğim,bu gece  Sende... 

sen hiç ölmeyi bildin mi 

seni senle yaşarken sensizlikte 

bana sorma sakın? 

seni senle yaşarken ölmeyi 

kimse bilemez benden iyi 

seni sensiz ölmeyi 

kimse bilmez güzelim. 

senle yaşarken sensiz ölmeyi 

benden daha iyi

seni senle yaşarken senlizlikte ölen 

Biri', 'Sende öleceğim,bu gece  Sende...  sen hiç ölmeyi bildin mi  seni senle yaşarken sensizlikte  bana sorma sakın?  seni senle yaşarken ölmeyi  ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olen-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-ugur-aydin-2-nz9q5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'söylenir dilden dile 

yaşanmış bir efsane 

beklemekse nafile..

adın konmuş  efsane..

ne gündüzdür ne gece 

adın dilimde hece

beklenir senelerce 

adın kaldı efsane...

bekleme geri dönmem 

bitmiştir bu hikaye

söylenir dilden dile 

adın konmuş efsane 

sabır derler telkinde 

belki gelir kırkında 

hayal bile farkın da 

bende oldun  efsane.....', 'söylenir dilden dile  yaşanmış bir efsane  beklemekse nafile.. adın konmuş  efsane.. ne gündüzdür ne gece  adın dilimde hece beklenir senele...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/efsane-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Dünya', 'yarim-dunya-mehmet-metin-senturk-351il', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ilkokul aşkımın okulu bırakmasıyla başladı

''bir bölü iki''lere tutsaklığım

yarım kaldı ilk kaçış

Ulam''ın gecesinde

hırçın düdük sesiyle

...

yarımdı o günlerde

ekmek arası köfte

benim de yarım kaldı eğitimim lisede

yarım değil binde bir

sadece küçükayı

gökyüzü penceremde

yarım kaldı dostluklar faili meçhullerde

''otuzbeş''in yarısı

duy beni ey Tarancı

yiğitler ölümlerde

...

kavgam da yarım kaldı

şubat doksandokuzda

sevdam da yarım artık

sevin ne mutlu sana', 'ilkokul aşkımın okulu bırakmasıyla başladı ''bir bölü iki''lere tutsaklığım yarım kaldı ilk kaçış Ulam''ın gecesinde hırçın düdük sesiyle ... y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Metin Şentürk']::text[], 8.5, '{"poet":"Mehmet Metin Şentürk","poet_slug":"mehmet-metin-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yarim-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak buysa', 'yasamak-buysa-durmus-karakus-d3oxg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dostan öğrendim beni sormuşsun

Öldümü kaldımı diye doğruysa

Hatta kırılmışsın hatır olmuşsun

Yaşıyorum işte yaşamak buysa. 

Biryanım sılada biryanım burda

Biryanım sağlamsa biryanım hurda

Dünya dedikleri bu kör çukurda

Yaşıyorum işte yaşamak buysa.

Kaderim böyleymiş buna sözüm yok 

Benbende değilim çünkü özüm yok

Ne huzur ne neş e yok üstüne yok

Yaşıyorum işte yaşamak buysa.', 'Bir dostan öğrendim beni sormuşsun Öldümü kaldımı diye doğruysa Hatta kırılmışsın hatır olmuşsun Yaşıyorum işte yaşamak buysa.  Biryanım sıl...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamak-buysa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-mehmet-metin-senturk-aya5c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben sana git dediysem

gökyüzünü yalnızlığa bulayıp,

yıldızları varlığının bağrına,

al demedim ki

ben sana git dediysem

yollarımı kördüğümle dolayıp,

uzaklarda yalın yürek,

yit demedim ki

ben sana git dediysem

düşlerimi ihanetle dağlayıp,

anıları lime lime,

yak demedim ki

gittin

boynu bükük öksüz kaldı gökyüzü

gittin

bir coğrafya telörgüyle çevrildi

gittin

düş atlasım mayınlarla bürüldü', 'ben sana git dediysem gökyüzünü yalnızlığa bulayıp, yıldızları varlığının bağrına, al demedim ki ben sana git dediysem yollarımı kördüğümle ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Metin Şentürk']::text[], 8.5, '{"poet":"Mehmet Metin Şentürk","poet_slug":"mehmet-metin-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gitme-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah belani versin..', 'allah-belani-versin-haci-murat-ates-0zbe1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni kahredip giderken dusuneydin 

Burda issiz bir odada birakdin gittin 

Hani sen benle mutlu olamazdin 

Ne icin geldin.. Git allah belani versin... 

Sana ne kadar yalvardim ne olur gitme diye 

Ama umursamadin beni bir hic sayip kapidan ciktin 

Bir kalbsiz gibi haykirisimi duymadin arkana bile bakmadin 

Ne icin geldin... Git allah belani versin... 

Ben nice geceler kahroldum senin icin cok agladim 

Elime resmini aldim yastigima sarildim 

Bir hafta gecmez ozler gelirsin sandim 

Ne icin geldin... Git allah belani versin.. 

Yillar gecti aradan tam yokluguna alismistim 

En sonunda degerimi anladin kabul edecekmi sandin 

Ben senin yerine bagrima kara tasi bastim 

Ne icin geldin.. Git allah belani versin..vermesin...', 'Beni kahredip giderken dusuneydin  Burda issiz bir odada birakdin gittin  Hani sen benle mutlu olamazdin  Ne icin geldin.. Git allah belani ...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-belani-versin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunun Adı Sevda', 'bunun-adi-sevda-kamil-aydemir-20ky5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğimin tam ortasında

bir hayat yeşerir

adı sevda

benim yarım

yarınlarım sende

ne zaman gülmek istesem gözlerinde

asılı kalırım kipriklerin ucunda

öpücük çiçeği olayım

kölyeliğe taşı gerdanında

narınciye kokulu bahçeler gibi saçların

her dalında yuva yapar düşlerim

kaf dağı’ndan daha zorsun ak gülüm

inadına mı durursun bu sevdanın uzağında

senin için mutluluklar var

sevdamın kucağında

hiç düşündün mü

neden içindeki piyanoda hep hüzün makamları

ve hayata neden kapalı arzuların camları

aç hayatla arana çektiğin perdeleri

göreceksin ki sana uzalı sevdamın elleri

ah bal gülüşlerin çıplak düşlerin

ah o yürüyüşlerin ah

kalçaların sanki karadeniz’deki dalgalar

her yürüyüşünde

kalçaların gelir yüreğimin kıyılarını yalar

mayıs yürekli işçiler gibi yasak dinlemez

arzularım zincirlerini kırar

sevişmeye açlığıyla yürür sana

narın gülüşü dudakların dudaklarımı karşılar

bende dişiliğin izleri kalır

teninde dudaklarımla yazdığım sevişmenin günlüğü

sevdan da olmasa nasıl taşırım bu sürgünlüğü

yarısız yollarda yürüme

acılara tosladıkça çok üzülürsün

karadeniz’de yakamoz

kafkaslar’ın ak gülüsün

işin ne sevgisiz yerlerde

hoyrat ellerde kurursun

sevgim hep yanında dursun

günün birinde muhtaç olursun

fırtınalı deniz’den kaçıp

sevinç çığlıklarıyla sevgi limanıma sığınırsın

aradığın mutluluğu ancak sevdamda bulursun

çaresizliğin pençesinde kanıyor bu şair

seni anlatırken lâl oluyor her şiir

sevdamda konuşan

güzelliğin karşısında susuyor

istanbul dahil her şehir

aşkın içimde nehir

yokluğun sevinçlerime zehir

artvin’e yeşilin

nazım hikmet’e şiirin

cheguara’ya  devrimciliğin

nasretin hocaya mizahın

mizaha lazın

türkülerimize sazın

bahara kirazın

geceye ayın

gündüze güneşin

yakıştığı kadar yakışırsın sevdama

sevdamda olamaz eşin

damarlarımda akan kanın rengi sevda

“benim meskenim dağlardır” diyor selda

ben sendeki dağlarda yaşamak istiyorum

sendeki bağlarda

sen benim göğümde uçan mavi kanatlı uçurtma

ben o uçurtmanın kanatları altında

mutluluk türküleri çığıran çocuk

ayrılıkta zaman memleketimin yolları gibi bozuk

yaşattığın acılarda bile

mutluluk bulacak kadar seviyorum seni

bunun adı sevda

köksüz ne kadar tutunabilir hayata bu gövde

gelde 

beni kurutma

ne kadar güzel diyor sezen aksu

“beni unutma”', 'yüreğimin tam ortasında bir hayat yeşerir adı sevda benim yarım yarınlarım sende ne zaman gülmek istesem gözlerinde asılı kalırım kiprikleri...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/bunun-adi-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne giyse yakışıyor', 'ne-giyse-yakisiyor-durmus-karakus-goefb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün gözler üstünde

Hep o na bakışıyor

Bir sımı var kostümde

Ne giyse yakışıyor.

Ne gözleri sürmeli

Ne yanağı gamzeli

Kırmızılı pembeli

Ne giyse yakışıyor

Takmasada tülleri 

Fetheder gönülleri

Kıskandırır gülleri

Ne giyse yakışıyor.

Çok çekingen birisi

Yok sözümün gerisi

Güzellikler perisi

Ne giyse yakışıyor.', 'Bütün gözler üstünde Hep o na bakışıyor Bir sımı var kostümde Ne giyse yakışıyor. Ne gözleri sürmeli Ne yanağı gamzeli Kırmızılı pembeli Ne ...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-giyse-yakisiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorsun', 'bilmiyorsun-durmus-karakus-h16fw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah gün doğuyorken

Aklıma sen geliyorsun

Seni nasıl sevdiğimi

Bilmiyosun bilmiyorsun.

Hep adını anan benim 

Seni mutlu sanan benim

Cayır cayır yanan benim

Bilmiyorsun bilmiyorsun

Sürmeleyip gözü kaşı

Geçirirsin yazı kışı

Oysa Durmuş KARAKUŞU

Bilmiyorsun bilmiyorsun', 'Her sabah gün doğuyorken Aklıma sen geliyorsun Seni nasıl sevdiğimi Bilmiyosun bilmiyorsun. Hep adını anan benim  Seni mutlu sanan benim Cay...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmiyorsun-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-seyithan-mahiroglu-1xvoq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk, dilin acze düştüğü 

sevinç ve ağlamanın bileşkesindeki

ifade edilmezliğin dilindedir...

Aşk, gözlerinden ruhuma akıp 

tüm vücudumu esaretine alan 

efsunlu bakışlarının gizemindedir...

Aşk, fildişi heykelinin bile 

vecd eylediği 

sendeki güzelliğin simetrisindedir...

Aşk, zamanın

akrep ve yelkovansız 

senli saatindedir...

Aşk, pervanenin uğruna yanıp

kül olmaktan sakınmadığı

yakıcı vuslatın esrarındadır...

Aşk, senli 

düşüncelerin ve düşlerin 

büyüdüğü hayatın fotoğrafındadır...', 'Aşk, dilin acze düştüğü  sevinç ve ağlamanın bileşkesindeki ifade edilmezliğin dilindedir... Aşk, gözlerinden ruhuma akıp  tüm vücudumu esar...', ARRAY['Türk Edebiyatı','Şiir','Seyithan Mahiroğlu']::text[], 8.5, '{"poet":"Seyithan Mahiroğlu","poet_slug":"seyithan-mahiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-408-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son gece', 'son-gece-ugur-aydin-2-bvcv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gece korkuyorum son 

yalnızım yine 

ellerim aradı ellerini karanlıklar içinde..

inan tükendim  sen yoksun

ne değişir dönsen bile 

bu sabahı olmayacak gece''de ''', 'bu gece korkuyorum son  yalnızım yine  ellerim aradı ellerini karanlıklar içinde.. inan tükendim  sen yoksun ne değişir dönsen bile  bu saba...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-gece-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şans Daha Bana', 'bir-sans-daha-bana-volkan-yoruc-ynji3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şans daha bana

Gün gibi yeniden doğsun simama

Yeni bir mevsim gibi

Dolsun içime beyaz bir rüya

Bir şans daha bana

Gök mavisi tonlarıyla

Gül çiçeği kokularıyla

Ve yeni doğmuş bebenin meraklı dokunuşlarıyla

Bir şans daha bana

Gidemediğim yollara

Tutamadığım avuçlara

Göremediğim bakışlara erişeyim

Bir şans daha bana

Duyamadığım şarkılara

Tadamadığım duyulara

Söyleyemediğim mısralara erişeyim

Bir şans daha bana

Koklayamadığım saçlara

Uzanamadığım yanına erişeyim

Bir şans daha bana

Ve bundan başka bir rüya kalmadı artık senden yana', 'Bir şans daha bana Gün gibi yeniden doğsun simama Yeni bir mevsim gibi Dolsun içime beyaz bir rüya Bir şans daha bana Gök mavisi tonlarıyla ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-sans-daha-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyen sevgi', 'gelmeyen-sevgi-elazigli-mustafa-kaya-9pqql', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sanki yanıyor bu şehir

saçlarından tutuşmuş

dalıp gidiyorum yıkık kentler içine

bir bir sarılıp çocuk gözlere

kaç gece bekledim ve kaç kez bakındım

yere düştüğüm günlerde

korkularım  olurdu 

yağmurlu günlerde

ve oyuncaksız üzüntülerim

ne zaman gelecektin anne...! 

sevinçli günlerim

bayram sevinçlerim olurdu

nerede kalmıştın anne..

bir yabancı gibi kalırdım sensiz

ve sessiz

içinde yaşadığım şehir dar gelirdi

bulamadığım zamanlarda seni

unutulmuş hissederdim

ne şehrin yedi rengi

ne de doğum günleri

beni güldürmedi anne..

ellerini merak ediyorum

saçlarımı okşayan

yeni elbiseler diken

sıkı sıkı ellerimden tutan

dilsiz kalırdım..anneler döver mi..? 

kızılır mı annelere..? ben kızmazdım hiç

sen anne

hayatın rengi

ateşi..suyu..nefesi

toprağın bereketi.olmalısın

senin olmadığın da insan ne yapar..? 

ve çocuklar anne..

ezilmedim..ayaktayım...kırılmadım  anne..

rüyalarımda yüzün pırıl pırıl

öksüzlüğüme değil

kıymet bilinmezliklere dargınım anne....

                                                                             07.08.2005 / istanbul

                                                                               mustafa kaya', 'sanki yanıyor bu şehir saçlarından tutuşmuş dalıp gidiyorum yıkık kentler içine bir bir sarılıp çocuk gözlere kaç gece bekledim ve kaç kez b...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gelmeyen-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Durma Gel Ý aklas...', 'uzak-durma-gel-aklas-haci-murat-ates-ppjhp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gercekden seveceksen 

Degerimi bileceksen 

Beni üzmeyeceksen 

Uzakdurma gel yaklaş.. 

Ömür boyu kalacaksan 

Hep benle olacaksan 

Benle açıp benle solacaksan 

Uzakdurma gel yaklaş.. 

Bir gün gitmeyeceksen 

Beni terk etmeyeceksen 

Benden vazgeçmeyeceksen 

Uzakdurma gel yaklaş', 'Gercekden seveceksen  Degerimi bileceksen  Beni üzmeyeceksen  Uzakdurma gel yaklaş..  Ömür boyu kalacaksan  Hep benle olacaksan  Benle açıp ...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzak-durma-gel-221-aklas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mesafe Tanırmı...', 'ask-mesafe-tanirmi-haci-murat-ates-y35sk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden korkuyorsun soyle 

Seven uzaklasirmi 

Aramizda daglar olsa bile 

Ask mesafe tanirmi... 

Daglari asip gelememmi 

Yollari asip gorememmi 

Seni bulup sevememmi 

Soyle Ask mesefa tanirmi.. 

Denemeden pesetme 

Hafife alma benim sevgimi 

Karsilik verdikten sonra sevgime 

Soyle ask mesafe tanirmi... 

Gel biz destan yazalim 

Anla artik seni sevdigimi 

Sevdikten sonra sevgilim 

Ask mesafe tanirmi... 

Sen uzaklardaki sen...', 'Neden korkuyorsun soyle  Seven uzaklasirmi  Aramizda daglar olsa bile  Ask mesafe tanirmi...  Daglari asip gelememmi  Yollari asip gorememmi...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-mesafe-tanirmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tombulsun sen tombul', 'tombulsun-sen-tombul-husamettin-guven-hdhlc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cok guzel ve tombulsun

kucagimi doldurursun

sen adami oldurursun

tombulsun sen tombul

gicik vede  ozelsin

gozlerinle suzersin

sevenleri cok uzersin

tombulsun sen tombul

sevgi dolu neselisin

acik sozlu duzeylisin

su alemin ozelisin

tombulsun sen tombul', 'cok guzel ve tombulsun kucagimi doldurursun sen adami oldurursun tombulsun sen tombul gicik vede  ozelsin gozlerinle suzersin sevenleri cok ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tombulsun-sen-tombul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silme Gozyaslarimi....', 'silme-gozyaslarimi-haci-murat-ates-dtnhe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elleme ugruna aksin gozyaslarim 

Birak mendilini silme gozyaslarimi 

Elleme ugruna islansin yanaklarim 

Birak mendilini silme gozyaslarimi.... 

Zaten.. 

Yuregimde sevgin yakacak beni 

Gozlerim her yerde arayacak seni 

Sen gidince Can terkedecek bedeni 

Birak mendilini silme gozyaslarimi... 

Ne yazik degilmi.ne yeminler etmistik 

Ayrilmak yok olumune beraberiz demistik 

Ikimizinde gozleri dolmus aglamistik 

Birak mendilini silme gozyaslarimi.... 

Seni her seyden cok seviyorum derdin 

Sensiz yasayamam deyip sarilirdin 

Kafani gogsume koyup hayel kurardin 

Birak mendilini silme gozyaslarimi.... 

Bendim hani denizler mavisi rengin 

Bendim hani...yuregindeki sevgin 

Bendim hani.... yasama sevincin 

Birak mendilini silme gozyaslarimi... 

Zaten.. 

Gunler dar gelecek aksamlar zindan 

Kalbim zorlanacak senin askindan 

Dusecek yapraklar guller dalindan 

Birak mendilini silme gozyaslarimi.... 

Seni unutamam.. biliyorum kendimi 

Silemem yuregime isledigin sevgini 

Biliyorsun sensiz hayati dusunmedigimi 

Birak mendilini silme gozyaslarimi... 

Kanimda canimda aldigim solugumda 

Ekmegimde asimda bir yudum suyumda 

Sen olacaksin gidecegim yollumda 

Birak mendilini silme gozyaslarimi.... 

Hayat sensiz nedirki hayat sendin 

Gulduren yasatan..sen herseyimdin 

Sen benim icin yasama sebebimdin 

Birak mendilini silme gozyaslarimi...', 'Elleme ugruna aksin gozyaslarim  Birak mendilini silme gozyaslarimi  Elleme ugruna islansin yanaklarim  Birak mendilini silme gozyaslarimi.....', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/silme-gozyaslarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimden Sevginide Goturseydin..', 'kalbimden-sevginide-goturseydin-haci-murat-ates-ledd6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kac yil oldu gideli beni terkedeli 

Sen unuttun bende unutabilseydim 

Hep ayni his ayni huzun degismedi 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin.. 

Gittin gideli yuzum bir gun gulmedi 

Gonlume el koydun baska gonul sevmedi 

Gozler seni aradi baska guzel gormedi 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin... 

Anilarla yasamaya alistirdim kendimi 

Belki gelir diye hep bekledim seni 

Bir damla bile eksitmedim sevgimi 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin... 

Saclarima aklar dustu yuregim yorgun 

Dizlerimde derman yok bedenim solgun 

Bu kalbim sana daha halen vurgun 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin.. 

Yasim 27 gecligimi yasayamadim 

Heves nedir huzur nedir anlayamadim 

Her yerde seni aradim ama bulamadim 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin... 

Siirlerimde seni yasattim seni andim 

Sen gideli degisemedim hep ayni kaldim 

Gun gecmeden ozler gelirsin sandim 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin... 

Goren deli dedi sen manyak sin dedi 

Kime derdimi acsam beni dinlemedi 

Haklilar kim ciddiye alir bir derbederi 

Kalbimden sevginide goturseydin 

Gonlumdende cikip gitseydin... 

Sen giderken zaten ben kahrolmustum 

Can cana kusmus sararip solmustum 

Zaten bir yasayan olu olmustum 

Kalbimi sokupde aysaydin keske... 

Beni oldurupde gitseydin keske', 'Kac yil oldu gideli beni terkedeli  Sen unuttun bende unutabilseydim  Hep ayni his ayni huzun degismedi  Kalbimden sevginide goturseydin  Go...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kalbimden-sevginide-goturseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faka bastim', 'faka-bastim-husamettin-guven-59ybm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cok guvendim dost sandim

sirtimdan bir darbe aldim

anlasilan aldandim

galiba ben faka bastim

saka yapip aldattilar

gururumla oynadilar

bilerek beni sattilar

galiba ben faka bastim

dunya alem beni tanir

iyi neyet suistimal olur

sozde benim dostum olur

galiba ben faka bastim', 'cok guvendim dost sandim sirtimdan bir darbe aldim anlasilan aldandim galiba ben faka bastim saka yapip aldattilar gururumla oynadilar biler...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/faka-bastim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Renkleri', 'kaderin-renkleri-ufuk-coban-2nkzn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaderi anlatan renkler vardır bilmediğin,

Kimi aktır, kimi kara, belki de sevmediğin.

Soluk bir tondur alnına işlediğin,

Bir yazı ki, ne yapsan önüne geçemediğin.

Mavidir özgürlüklere bürünen şekli.

Yeryüzünde tutamaz hiç bir ilgi, bu sevgi selini.

Hiçbir zaman bulamazsın yerinde elini,

Verdiğin gibi bir maviliğe benliğini.

Siyahtır fırtınaların gürültüsü.

Hiçbir şimşek aydınlatmaz bu kara dürtüyü.

Aydınlığa muhtaçtır, dost bilir üzüntüyü,

Unutmaya çalışır dağlara gömerek hüznünü.

Kırmızı güvendir dostluğun pençesinde.

Tutkuya dönüşür sevginin merceğinde,

Paylaşıldığında yemindir sadakate,

Ya da bir kan damlasıdır uğrunda damladığı yerde.

Rengi çoktan seçildi senin kaderinin,

Elinde değil imkanı yok değiştirmenin.

Adını düşün hafta sonu gideceğin filmin,

Kaçış yok bu senin en doğal kaderin.

1999', 'Kaderi anlatan renkler vardır bilmediğin, Kimi aktır, kimi kara, belki de sevmediğin. Soluk bir tondur alnına işlediğin, Bir yazı ki, ne yap...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaderin-renkleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim Anam...', 'sensizim-anam-haci-murat-ates-8f3gn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Of anam derken icim sizliyor 

Ne bir gun dizinde uyudum anam 

Ne de hayellerimde seni gordum 

Bir resmin bile yok sensizim anam... 

Gunler zorgeciyor yanlizim burda 

Babam kahvede okey oynuyor anam 

Bir dilim peynir bir tek yumurta 

Kuru ekmekle yasiyom anam... 

Isim var allaha sukur calisiyorum 

Babamin tutun parasina yetmiyor anam 

Bir somun biraz peynir zeytin 

Geri Kalan parami sakliyom anam.... 

Dun gece sarhos haliyle aldim kahveden 

Her kese rezil oldum utandim anam 

Ben burda gelecek icin cabalarken 

Onun eziyetinden ben biktim anam... 

Evi temizle elbise utule bilasiklari yikiyom 

Bir dakika oturmadan cagiriyor anam 

Aciktim yemek yokmu diyor yapiyom 

Onu bile begenipde yemiyor anam... 

Giravatini yanlis utulemisim cok kizdi bana 

Utuyu aldi vurdu yuzume aciyor anam 

Neyi dogru yapsam bir turlu yaranamadim ona 

Herseyime bir sebeb bulup kiziyor anam... 

Bir yanda senin yoklugun senin hasretin 

Dayanamiyorum kacmak istiyorum anam 

Bir yanda onun kahvesi ve ickisi 

Her seye sonvermek geliyor icimden anam... 

Yavrun sensiz yasiyor anam sensiz yok olup bitiyor anam...', 'Of anam derken icim sizliyor  Ne bir gun dizinde uyudum anam  Ne de hayellerimde seni gordum  Bir resmin bile yok sensizim anam...  Gunler z...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sensizim-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatandaşın suçu ne! Harun Yiğit''in Ne mutlu Türk''üm diyene şiirine nazire', 'vatandasin-sucu-ne-harun-yigit-in-ne-mutlu-turk-um-diyene-siirine-nazire-mikdat-bal-4r9fc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yabancı marka mal dolmuş yurdumuz

Vatandaşın burda suçu ne beyler? 

Yabancıya pazar olmuş yurdumuz

Vatandaşın burda suçu ne beyler? 

Patronumuz hain, işçimiz açsa

İş yapan devamlı hileye kaçsa

Yaptığı kötülük en hafif suçsa

Vatandaşın burda suçu ne beyler? 

İtimat kalmamış içten kokmuşuz

Başka pazarlarda bizler yokmuşuz

Yabancı ne varsa alıp sokmuşuz

Vatandaşın burda suçu ne beyler? 

Domadeslerimiz tarlada çürür

İtalyan salcası sofrada durur

Meyvalar toplanmaz dalında kurur

Vatandaşın burda suçu ne beyler? 

Madden böyle çöktük manen kültürle

Söylemek faydasız istersen gürle

Müzik pop caz olmuş her çeşit türle

Vatandaşın burda suçu ne beyler? 

Ben Türk’üm söylemek asil deyiştir

Her şeyi maddeyle ölçmek yanlıştır

Abesle iştigal faydasız iştir

Vatandaşın burda suçu ne beyler? 

Ben Türk’üm doğruyum her zaman derim

Hiç olmazsa öyle olmak dilerim

Mikdat der herkese selam ederim

Vatandaşın burda suçu ne beyler?', 'Yabancı marka mal dolmuş yurdumuz Vatandaşın burda suçu ne beyler?  Yabancıya pazar olmuş yurdumuz Vatandaşın burda suçu ne beyler?  Patronu...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vatandasin-sucu-ne-harun-yigit-in-ne-mutlu-turk-um-diyene-siirine-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İştik! ! ! ! ! !', 'i-stik-harun-kaya-3-swgfm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmeli derler gerekirse ölümsüz sevgi için,

Düşündüm gerçekten değermi diye sevgili için,

Ve yollar çakıştı bulduk birbirimizi sevmek için,

Sevgili beni sevdi, ben sevgiliyi 

            SEVİŞTİK! ! ! ! ! ! 

kaderden derdi babam, ne gelirse başına,

Tuz verirse tuzlu yersin, tuz koyarsın aşına,

Dedim ey kader ya bırak peşimi ya şimdi çık karşıma,

Kader bana güldü ben kadere,

    GÜLÜŞTÜK! ! ! ! ! ! ! ! 

Anlam veremezdim herşeyin yerinde güzelliğine,

İnanmazdım bir gülün bu kadar güzel öleceğine,

Derken bırakı verdi nahif yapraklarını ellerime,

Gül öldü, ben öldüm,

             ÖLÜŞTÜK! ! ! ! ! ! ! ! ! 

 Harun KAYA

 (c)     bu şiirin her türlü telif hakkı şairin kendisine  ve / veya temsilcisine aittir', 'Ölmeli derler gerekirse ölümsüz sevgi için, Düşündüm gerçekten değermi diye sevgili için, Ve yollar çakıştı bulduk birbirimizi sevmek için, ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilikten Maraz Doğar', 'i-yilikten-maraz-dogar-ali-dilki-48zqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kime ekmek verdiysem dönüp bana taş attı

Nankör silahlarıyla etrafımı kuşattı

İyilikten maraz doğar demiş atalarımız

Yapılan haksızlıklar gözlerimi yaşarttı.', 'Kime ekmek verdiysem dönüp bana taş attı Nankör silahlarıyla etrafımı kuşattı İyilikten maraz doğar demiş atalarımız Yapılan haksızlıklar gö...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iyilikten-maraz-dogar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Atölyesi', 'sair-atolyesi-mutlu-ayar-fa7ot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim art ucum başladığınız yer

Ben ki gemilerimi sizin gözlerinizde gördüm

Yaklaştıkça yürüdüm dumanı zaferin

Savaşlarınızı benzettim iki kardeşin kavgasına

Ehliyetsiz, en belalı sözcükleri sizin için sürdüm

Tehlikeli uyarısız yolunda bu düzenin, 

Yaşamaya âşık olmuş şair gibi çaresizdiniz 

Uykuyu anımsamadım hiç geceler sarılınca 

İmkânsızları sandım bir büyüteç var aklımda

Ansızın sevinçleri sizin için gömdüm 

Şimdi yirmidördünde bu kör sözlerim 

Ölmediği her şeye öldü yeterince, 

Aksanı yok kendiliğinden bakar görünce

Tasasız yaşama başlıyorken az daha 

Ben şairliğimi sizin gözlerinizde gördüm...', 'Benim art ucum başladığınız yer Ben ki gemilerimi sizin gözlerinizde gördüm Yaklaştıkça yürüdüm dumanı zaferin Savaşlarınızı benzettim iki k...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sair-atolyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ter ve Yağmur', 'ter-ve-yagmur-gulsen-gonenc-tyaba', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hava sıcaktı,

Yorgundu,

Terliyordu; 

Sıcaktan da değil, yorgunluktan da.

Yağmur başladı.

Pencereden giren yağmur damlaları teriyle karışıyordu,

Sıkışan ruhumun kapağını açıyordu.', 'Hava sıcaktı, Yorgundu, Terliyordu;  Sıcaktan da değil, yorgunluktan da. Yağmur başladı. Pencereden giren yağmur damlaları teriyle karışıyor...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ter-ve-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-abbas-yurt-jg4m8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beyhude süs verdin kendine gönül,

Yaramı deştin sen gayri neyleyim.

Bütün bu ihtişam neyine gönül,

Haddini aştın sen gayri neyleyim.

Kartal gibi yüksek uçarken gönül,

Yolundan şaştın sen gayri neyleyim.

Şahin pençesinden kaçarken gönül,

Tuzağa düştün sen gayri neyleyim.

Coşarak çağlama boşuna gönül,

Bendinden taştın sen gayri neyleyim.

Ateşle iş açma başına gönül,

Odunsuz piştin sen gayri neyleyim.

(Bizim Ece Dergisinde yayımlanmıştır.) 

21.05.2003

Kaynak: Yeniden Doğmak...Yeniden Yaşamak...

Abbas Yurt', 'Beyhude süs verdin kendine gönül, Yaramı deştin sen gayri neyleyim. Bütün bu ihtişam neyine gönül, Haddini aştın sen gayri neyleyim. Kartal ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inmisin yoksa cinmi', 'inmisin-yoksa-cinmi-husamettin-guven-6u3dt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'firtina oldun esip gittin

su kalbimi sokup gittin

yetim gibi atip gittin

inmisin yoksa cinmi

simsek olup patladin

bulut oldun kapladin

hep kendini sakladin

inmisin yoksa cinmi

aymisali parlattin

gunes gibi cok yaktin

sanki rahmet islattin

inmisin yoksa cinmi', 'firtina oldun esip gittin su kalbimi sokup gittin yetim gibi atip gittin inmisin yoksa cinmi simsek olup patladin bulut oldun kapladin hep k...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inmisin-yoksa-cinmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yağmur', 'son-yagmur-cevat-aras-y0xvz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son yağmur gözlerime yağdı...

Rüzgarın insafına kalmış 

İki yapraktık.

Neresinden tutunsak hayata

İlla ki kopacaktık.

Ayrılıklara çıkan bir yolda yürüyorduk,

Ne korkular umurumuzdaydı oysa,

Ne de pişmanlıklar.

Biz sadece dillendirilmemiş 

Bir sevdayı yaşıyorduk doyasıya.

Ne kadar da masumduk,

Bir günahı yaşarken.

Ne kadar da zavallıydık,

Mağrur yüreklerimizde

Kahreden bir ezikliği taşırken.

Hep hüzünlü türkülerde

Buluyorduk kendimizi.

Ve suçlu çocuklar gibi

Başımız önümüzde

Söylüyorduk sevgimizi.

Bir fırtına akşamıydı,

Ansızın kayboldun.

Son yağmur gözlerime yağdı,

Sen gözyaşım oldun...', 'Son yağmur gözlerime yağdı... Rüzgarın insafına kalmış  İki yapraktık. Neresinden tutunsak hayata İlla ki kopacaktık. Ayrılıklara çıkan bir ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Aras']::text[], 8.5, '{"poet":"Cevat Aras","poet_slug":"cevat-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-yagmur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Han''fendileri', 'gunesin-han-fendileri-selahattin-durna-as643', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin Han''fendileri

Bu şehirde kadınlar

Bedenlerinden utanmıyorlar

Saklamıyorlar bedenlerini

Barışıklar bedenleriyle

Bu şehirde kadınlar Allah’a inanıyor

Ama güneşe tapıyorlar

Göğüslerinde cevşen,

Göbeklerinde şeytan dövmesi.

Çünkü bu şehirde özgürlük

Güneşin sofrasından alıyor gıdasını

Palmiyeler gibi öyle,portakal çiçekleri gibi öyle…

Yanaklarında al,yanaklarında mor değil

Güneş yanığı tenleriyle susuyor sevdasını

Bu şehirde kadınlar…

Bu şehirde özgürlük güneşten besleniyor

Güneş yumuşatıyor denizlerin suyunu,insanların huyunu

Güneş kesip biçiyor eteklerin boyunu

Özgürlük kadın kılığında çıkıyor bu şehirde sokaklara

Güneş bu şehirde kadınları kullanıyor

Ulaşmak için amacına.

Bu şehirde kadınlar

Bir tek kadınları sevmiyorlar

Bir de sabah güneşini

Kimi mevsim gerekçesi kıtlığın

Kimi mevsim bereketin ta kendisi.

Güneşi arkalarına almışlar

Denizi arkalarına almışlar

Sözleri kanun hükmünde

Önce bıyıklarını budamışlar erkeklerin

Kısa pantolonlar giydirmişler altlarına

Oğlan çocukları gibi

Düşürmüşler krallıktan

Parayı erkekler kazanıyor burada

Kadınlar harcıyorlar

Bu şehirde kadınlar önden yürüyor

Erkekler arkasında.

Bu şehirde kadınlar

Topuklarından başlıyor kendini göstermeye

En son gözlerinin rengine bakıyorsun

Aşkı şiirsiz düşünüyorsun burada

Şiir aşktan münezzeh

Bu şehirde kadınlar

Memnunlar kadın olduklarından

Mor üzüm nasıl memnunsa hayatından

Portakal nasıl mutluysa portakal olduğu için

Akdeniz

Uçsuz bucaksız bir buğday ovasıdır burada

Kadınların ekip biçtiği

Kadınlar bu şehirde

Akdeniz’in efendisi

Güneşin han''fendisi…

                                                        Temmuz 2003

                                                          ANTALYA', 'Güneşin Han''fendileri Bu şehirde kadınlar Bedenlerinden utanmıyorlar Saklamıyorlar bedenlerini Barışıklar bedenleriyle Bu şehirde kadınlar A...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gunesin-han-fendileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Bekçileri', 'gece-bekcileri-selahattin-durna-vp0di', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece Bekçileri

Sizin orda

Daha güneş

Horozların bile aklına düşmezden

Biz burada

Koğuşlar dolusu adam-eşkıya

Güneşin önünü kesiyoruz.

Biraz daha uyuyasınız diye siz,

Biraz daha geç uyanasınız diye…

                                                               Patnos/AĞRI

                                                                     1983', 'Gece Bekçileri Sizin orda Daha güneş Horozların bile aklına düşmezden Biz burada Koğuşlar dolusu adam-eşkıya Güneşin önünü kesiyoruz. Biraz ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gece-bekcileri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Bahar Olacak', 'hep-bahar-olacak-huseyin-mustafa-guvendag-nfvhx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yılları çalan zaman

Nasıl oldu anlamadım

Su gibi akıp

İçimizden

Giderken

Götürmüş olabilir

Bir aynada asılı kalmış yüzümüzü

Bir yıl

İki, üç yıl derken

Devamında boşluğa bıraktığımız gülücükler

Yıkım zamanı gelmeden

Solmasın diye

Saklı durur yıldızlarda

Hangi şiirin parçası olacağım

Hangi çizgide dolaşacağız

Gideceksin diye

Oturmuşsun yolun

Kenarına

Gelecek ilk otobüs

Tarifeli değil biliyorsun

Ne zaman gelir

Ne zaman götürür

Kaç yıl daha geçer

Yılları saymak adetten mi

Aynaya bakmak

Üzülmek içinse

Bırak 

Gitmişleri

Aslında hep bahardı

Hep bahar olacak inan

22.07.2005', 'Yılları çalan zaman Nasıl oldu anlamadım Su gibi akıp İçimizden Giderken Götürmüş olabilir Bir aynada asılı kalmış yüzümüzü Bir yıl İki, üç ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Mustafa Güvendağ']::text[], 8.5, '{"poet":"Hüseyin Mustafa Güvendağ","poet_slug":"huseyin-mustafa-guvendag","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hep-bahar-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim', 'severim-selvi-celik-i3la7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni uzaktan sevmeyi,

Hasretini dopdolu yaşamayı,

Seni gülerken ağlatmayı,

Ben seni sensiz sevmeyi,

________Severim.

Benim sevgim rezildir.

Senin sevgin vezirdir.

Benim sevgim delidir.

Senin  sevgin doludur.

Benim sevgim cılızdır.

Senin sevgin cesurdur.

Aşkı yasaksız yaşarım.

Ama,Neden,Niçin''leri katmadan.

Kuşkuları perde yapmadan.

Sorgusuzca,yanlişlarla 

_________Severim.

Yaşanan güzelliği sormadan.

Karşılık istemeden.

Kalbime sınır vermeden.

Oyuncak dedirtmeden.

________Severim.', 'Seni uzaktan sevmeyi, Hasretini dopdolu yaşamayı, Seni gülerken ağlatmayı, Ben seni sensiz sevmeyi, ________Severim. Benim sevgim rezildir. ...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/severim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebabil Kuşları', 'ebabil-kuslari-selahattin-durna-g3mhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ebabil Kuşları

Düş

Görmediniz

Boşuna ölmediniz

Kavganın tam sırasıydı

Kara dememişsinizdir

Sarı dememişsinizdir

Yaban değildir ya hani

Toprağını sürmediğiniz bi enlemin bile

Ölülerini sayan anasının gözleri

Boynunuzu aydınlık için

İpe verdiniz

Bir arkadaş ıslığını temize çeker gibi

Kurşuna dizildiniz

Derin kuyu bakar gibi

Karanlıklar baktınız ya

Paşa paşa diz çöktü ya dostlarım

Ayaklarınızın dibinde ölüm

Ölmediniz gülüm

Karanlığın göbeğinde ışık ışık

Karanlığın göbeğinde iri iri

Kedi gözleri

Zincir kırılmamışsa/kırılacak

Defter dürülmemişse/dürülecek

Kavganın tam sırasıydı

Boşuna ölmediniz…', 'Ebabil Kuşları Düş Görmediniz Boşuna ölmediniz Kavganın tam sırasıydı Kara dememişsinizdir Sarı dememişsinizdir Yaban değildir ya hani Topra...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ebabil-kuslari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoklaşmak', 'coklasmak-selahattin-durna-rf3xi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çoklaşmak

Et

Kemik

Kan

Hepimiz can

İnsanız

İnsanız

Hepimiz aynı güne boyun kırmış

Hepimiz aynı geceye

Kafa yormuşuz

İnsanız

Aynı tespihle solumuş ellerimiz

Yaşamakla yüce bir tapınışa diz çökmüş

Bir oyuna girmişiz

Kağıtları görülmüş

İnsanız

Yüreğim yüreğinizle çoğalır

Merhabamla sıcak merhabalar

Aynı soğuğa üşüyoruz

İnsanız

En azından

İncil kadar kutsal

Kur’an kadar mukaddes

Tevrat kadar,Zebur kadar

Allah’la bir huydanız.

Et

Kemik

Kan

Hepimiz can

İnsanız…', 'Çoklaşmak Et Kemik Kan Hepimiz can İnsanız İnsanız Hepimiz aynı güne boyun kırmış Hepimiz aynı geceye Kafa yormuşuz İnsanız Aynı tespihle so...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/coklasmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur Yolcusu', 'huzur-yolcusu-omer-kucukkaya-hezz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adımı sen koy benim 

ister huzurun yolcusu de 

istersen acıların adamı 

adımı sen koy benim her satırda...

Bu yolculuğun sahibi yok sonu yok,

bu yolculuk huzura, mutluluğa ve merhamete..

Kimsesi olmayanların değil,

Yalnız kalmışların,

yüreksiz olanların değil,

yüreğine dur diyemeyenlerin yolu bu....

Bu yol huzura

Ve bende Huzur yolcusu....', 'adımı sen koy benim  ister huzurun yolcusu de  istersen acıların adamı  adımı sen koy benim her satırda... Bu yolculuğun sahibi yok sonu yok...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzur-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce Yalnızdım Senden Sonra Hep Sürgün', 'senden-once-yalnizdim-senden-sonra-hep-surgun-koksal-akar-ghpr7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdan bir diken gibi yüreğime batıyor 

Aşk renginde ruhumun, taşıyor izlerini 

Nice yıllar avare gönlümü taşıdım da 

Şimdi hayal köşkümde bir vefasız yatıyor 

Ve üstüme dikiyor bir yılan gözlerini 

Uçurdum ak kanatlı kuşlarımı semaya 

Yıkıldı sarayları, gönül sultanlarımın 

Artık dargın değilim, ne güneşe ne aya! 

Sonsuzluk ki benliğim kadar değildir yalnız 

Hangi deniz taşımaz yıldızların rengini 

Doğduğu gün ağlarmış bahtımız yeryüzünde 

Canlanırmış mürekkep senin resminde ansız 

Ay düşünce bulurmuş göllerde ahengini 

Birkaç karanfil yeter gülmeyen şu bahtıma 

Varsın hayallerine almasın kuşlar beni 

Varsın hüzün otursun gelsin, gönül tahtıma 

Oysa intihar kadar ürkütücüdür bahar 

Geceler ümidimi yalnızlığıyla deler. 

Alevsiz bir yangının odunudur oysa gül 

Gözyaşı bu şehirde şimdi ummanlar kadar 

Her veda bir ölümün geldiğini müjdeler 

Baykuşun gözlerinde bir hiçtir yanan ümran 

Istırabını bilmez kıvılcım, yanan suyun 

Bir gün hayata küser, delirip aksa da kan 

Kâh çileye gülümser, kâh neşeye küser baht; 

Kâinat her mevsimi, çaresiz kabullenir 

Uludukça semaya pervasızca çakallar 

Bir sultanı ağırlar en koyu hüzünle taht 

Bu hevesle an gelir tüm ahrazlar dillenir 

Maziyi karaladı kahır dolu bir sancı 

Gittiğin gün hicranı daha başka tanıdım 

Bu eller benim değil gülüm, bu yüz yabancı 

Vurulsam da ruhumun göklerinde kaç kere 

Bilirim ki arzuyla son durağa varılır 

Bahar bizden uzağa götürür rüzgârını 

Yine durmadan akar bu ırmak ve bu dere 

Toprak yeniden cana özlem ile sarılır 

Fakat unutmaz seni ne yarın ne de bugün 

Bir Mecnun'' a bilenir yeniden, hevesle, aşk 

Ruh hicreti sayıklar, beden yorgun, can üzgün... 

Senden önce yalnızdım, senden sonra hep sürgün 

Her şeyimde öldürdü maviyi avuçlarım; 

Ayaklarım nicedir özlemiyor bir şehri 

Dikenleri batıyor nicedir, gonca gülün 

Nicedir bu hüzünle tutuşuyor saçlarım 

Kaç asırdır sürükler beni hicranın nehri 

Önce gama gülümser mutluluğa küserdim 

Bilmezdim neden kayar her yıldız bir gönüle 

Bilseydim, rüzgâr olur sana doğru eserdim. 

Küllenen ateşlerin yüreğinde saklı su, 

Dudaklarından ab-ı hayat misali damlar 

Sonsuz sabırla bekler yeryüzü yağmurunu 

Gece kanatlanırken perilerin uykusu

Ay mehtaba yaklaşır ve buğulanır camlar 

Seher vakti içli bir ezan sesiyle uyan 

Anla ki, gurbet budur, öz yurdunda ey güzel! 

Bu yüzden zehir kusar, yılan, akrep ve çıyan... 

Gözlerin, yapayalnız, gözlerin ve hayaller... 

İyi bak, gözlerinde yazan kaderin midir? 

Masallarda büyüyen devin yalnızlığıdır 

Sana neyi anlatır, bu yaşlar ve bu eller 

Seni sevdama muhtaç kılan, kederin midir? 

Bilmedin ey sevgili adını sen hasretin, 

Hangi kapıyı açar yüzünün güzelliği 

Hangi sevdaya eştir söyle bana nefretin 

Yine bir katil bilmez çekerken silahını; 

Kesilen bir dal için bin kök salarmış çınar 

Zifiri karanlığa gömülse de kâinat, 

Müjdeler yeni güne, gecenin sabahını 

Yalnız yürekte hicran bitmez; yandıkça yanar 

Zaman gelir yıkılır sultanların kalesi 

Hasret kalır bir damla suya bütün çiçekler 

Solar gönül dağının menekşesi, lalesi... 

Zaman elbet senin de belini büker bir gün, 

Senden önce yalnızdım, senden sonra hep sürgün...', 'Sevdan bir diken gibi yüreğime batıyor  Aşk renginde ruhumun, taşıyor izlerini  Nice yıllar avare gönlümü taşıdım da  Şimdi hayal köşkümde b...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/senden-once-yalnizdim-senden-sonra-hep-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Çanakkale ve Şehitlerimiz...(ilk şiirim)', 'canakkale-ve-sehitlerimiz-ilk-siirim-cihan-kaya-ydpks', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ç oktan ilan edilmişti seferber,

A vrupalılar akın ettiler beraber,

N aliş başlar gelince Çanakkale''ye,

A yılınca bağırırlar af eyle diye...

K albinle karşı koy düşmana mütemadiyyen

K orkma! Ölürsen cennettesin ebdiyyen...

A llah aşkı ile yanan kalbinin ateşi, 

L akin olmamalı bu aşkın bir eşi,

E rvah yukarı doğru süzüldükçe; 

Ş ahadet sesleri yükseldikçe; 

E celin geldiysede korkma sakın! 

Haydi saldır düşmana akın akın...

İ manın seni durmadan yüceltir; 

T epelerin en büyüğüne sacağını yükseltir,

L eke getirmez adına şanına,

E lmas gibi vatanın bir taşına...

R efah bıraktınız yaptıklarınızla bende,

İ hya ettiniz beni olayım size bende (köle) ,

M ethiyelerin nicesini yapsak azdır sizlere,

İ yi ve güzel bir örnek oldunuz bizlere

Z afer sizin, zafer bizim, zafer hepimizin....

1998-  Konya', 'Ç oktan ilan edilmişti seferber, A vrupalılar akın ettiler beraber, N aliş başlar gelince Çanakkale''ye, A yılınca bağırırlar af eyle diye......', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/canakkale-ve-sehitlerimiz-ilk-siirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz', 'kimsesiz-omer-kucukkaya-tp6lx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer adımı bilmiyorsa melek suretliler,

eğer ki bir tutam sevgi vermiyorlarsa insanlar

bir tutam neşe yoksa kuşlarda benim için

ben yalnız kimsesiz kalmışım demekki....

kime nasıl anlatabilirim ki

kimsesizliğimi ve sessiz gözyaşlarımı....

adımı yaratan değil yarattıkları koymuş

anası babası olan bir kimsesizim ben

kim bilir belkide onlarcasından biriyim

yalnız kalmış sokak köşelerindeyim...

kimi zaman bir annenin gözyaşlarında

kimi zaman bir babanın nasırlı avuçlarında 

ama sonuçta hep kimsesizim

evet ben varlığın içinde oluşan yokluk

evet ben kimsesizim....', 'Eğer adımı bilmiyorsa melek suretliler, eğer ki bir tutam sevgi vermiyorlarsa insanlar bir tutam neşe yoksa kuşlarda benim için ben yalnız k...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimsesiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kukumav Kuşu', 'kukumav-kusu-zeki-akcali-ju26p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığa yok çare.

Züğürt tesellisidir

Umarak günlerce beklemek

Aşık olunacak adam gibi birini.

Ya da yazmaktır son çare,

Yine tepelere bakarak

''Birileri vardı da

Ben mi görmüyorum'' diye.

(06/08/2005, Cumartesi, Kozyatağı)  

(2.dönem)  

(Bu şiir Pakize Suda''nın bir yazısı üzerine yazılmıştır.)', 'Yalnızlığa yok çare. Züğürt tesellisidir Umarak günlerce beklemek Aşık olunacak adam gibi birini. Ya da yazmaktır son çare, Yine tepelere ba...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kukumav-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alabora', 'alabora-halil-kesken-j4anv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün alabora olmuş bir tekne gördüm,

Kendime benzettim nedense...

Taam kalbinin ortasından ikiye bölünmüş,

Üzerine başıboş martılar üşmüş..

Bir zamanlar kalbinde oturup,

Bütün fırtınalara beraber karşı koyduğu,

Geceleri yüreğinde uyuttuğu,

Canı kadar sevdiği kaptanıda terketmiş onu.

Yavaş yavaş su almakta tekne,

Yavaş yavaş batmakta...

Sevdiğinin, kaptanının, canının, ciğerinin,

Terkedenin gelip kendisini kurtarmasını bekliyor.

Yeniden ona gözü gibi bakmasını

Yeniden elini vücudunda dolaştırmasını,

Yeniden okşamasını, boyamasını bekliyor.

Alaboranın üzerinden tam üçüncü gün batımı geçmiş.

Artık kayık karanlık sulara daha yakın

Artık bir sonraki gün doğumunu göremeyeceğini biliyor.

Ve artık kurtulmak için hiç gayret etmiyor.

Elveda sevgili kayık diyecektim ki tam

Birden güneşin henüz batmamış olduğunu farkettim

Benimse batmak istemediğimi

Gömleğimi fırlattım sahile, koşup yakaladım onu

Kan ter içinde çektim kumlara

Onun bir kaptana ihtiyacı vardı,

Benimse bir sonraki gün doğuşunu görmeye

Onun bir kaptanı vardı,

Benimse yarını görecek gücüm.', 'Bu gün alabora olmuş bir tekne gördüm, Kendime benzettim nedense... Taam kalbinin ortasından ikiye bölünmüş, Üzerine başıboş martılar üşmüş....', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/alabora-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın günah yazsın yobazlar,', 'varsin-gunah-yazsin-yobazlar-ali-osman-yilmaz-ynil4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece düşümde,

Yepyeni bir hazza daldım,

Seninle sarmaş dolaş,

Bütün gece harman oldum.

Bir melek ve bir şeytan,

Dikildi karşıma sabah, 

Şeytan gece boyunca,

Günah işledin derken,

Melek’ sen insansın,

Tanrının lütfu ne zaman,

Günah yazılmıştır ki,

Yaşadığın sana,

Tanrının bir lütfudur,dedi.

Sahi güzelim seni,

Hayalde olsa yaşamak,

Seni sensiz,ama seninle,

Doyasıya tatmak,

Günah mıdır,helal mi,

Söyler misin bana? 

Seni seninle yaşayamadan,

Bıraktın gittin beni,

Seni hayal de olsa,

Yaşamak suç mu? 

Varsın günah yazsın yobazlar,

Ben seni,

Sensizde olsa,

Doyasıya yaşıyacağım,

Sen yoksun ama,

Düşlerim benim,

Seni nasıl olursa,

Öyle düşleyeceğim.', 'Dün gece düşümde, Yepyeni bir hazza daldım, Seninle sarmaş dolaş, Bütün gece harman oldum. Bir melek ve bir şeytan, Dikildi karşıma sabah,  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/varsin-gunah-yazsin-yobazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Kalan', 'bende-kalan-ozgur-kokturk-pkp0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bende kalan bir akşam sızısı 

Bir gece karanlığı hece hece 

Yürek burkan feryatlar kulaklarımda 

Göz yaşlarıyla ıslanmış bir avuç 

Parmaklarımın her boğumunda isyan... 

Geri dönüşsüz yolculuklarda umudum 

Hücrelerim kıyılmış parça parça 

Titrek buğulara karışmış nefesim 

Kırılgan seslenişlerde kalır sükût 

Geceyle biten geceyle başlayan...', 'Bende kalan bir akşam sızısı  Bir gece karanlığı hece hece  Yürek burkan feryatlar kulaklarımda  Göz yaşlarıyla ıslanmış bir avuç  Parmaklar...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bende-kalan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim....', 'zalim-cihan-kaya-0m1ma', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarımla hasretini sularken 

Senin aşkının çınar olduğunu 

Seni sensiz yaşarken nerden bileceksin.... 

Kendine bir ekleyen hasrete

yeşilimsi gözlerle yaprak mı olacaksın? 

İçimde ki aşkın çocukluğu 

sen çocuğunu öldürecek kadar zalimsin

ama ben buna izin vermem....', 'Göz yaşlarımla hasretini sularken  Senin aşkının çınar olduğunu  Seni sensiz yaşarken nerden bileceksin....  Kendine bir ekleyen hasrete yeş...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zalim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Olmak', 'cocuk-olmak-sair-hasret-n-qtftt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çocuk olmak 

ve  korkmak çok sevdigin kedinin senden önce ölmesinden

ve senin yerine annenin ölebilmesi olasılıgından 

ve hasta oldugunda mikroplar  karınca olmalıydı görebildigim demek

ve  karıncalara yalvarmak çekirdek kabuklarını yuva agzına  yıgarak 

ve avunuvermek çabucak her hüzünde, hüznü ertelemek yetenegi 

ve uçan balonunun dünyayı dolaşacagını sanmak gözlerini baglayarak ipine

ve o çocugu  saklayabilmek köşe bucak içinde,ayaklarının göründüğü o perdenin arkasına 

ve ''bu gece kar yagdı mı? '' diye  uykunu bölüp burnunu dayadıgın camlara

ve birdenbire büyüyebilme merakı çocukluk edip

ve ilk aşkının pantolonu yırtıldıgında sana badem çalarken, üzülmek

aglamak birlikte onunla 

dünyanın  ne kadar, her nesnenin ne kadar büyük oldugunu düşünmek devler dünyasında yaşamak 

ve büyümek... büyümek...  büyümek arzusu 

bir güvercinin seninle konuşmak istedigini sanmak

masallarda yolculuklar yapmak, umacılardan kaçmak

saçının acıması taranırken,banyo firarları 

ve  hep ne zaman uzayacagını merak ettigin yetişkin  burunları

çocuk olmak

iyi,kötü,mutlu,mutsuz,yoksul,zengin 

ama hep gözbebekleri kocaman,kocaman bir  çocuk  olmak

işte marifet  bu!', 'çocuk olmak  ve  korkmak çok sevdigin kedinin senden önce ölmesinden ve senin yerine annenin ölebilmesi olasılıgından  ve hasta oldugunda mi...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cocuk-olmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma', 'hesaplasma-sair-hasret-n-83lfj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen  orada  bekliyorsun ,  sen  suskun ,  sen  sabırlı

     sen  biliyorsun  ki

     toprak  dolar  taşar  birgün

     sular  yol  bulur 

     buz gibi  içersin  kaynaklardan

     oysa hayat  kimseyi  beklemez     

     ırgatlar  işçiler  arılar  çiçekler   ve  sömürenler 

     SEn  BEKLİYORSAN     

     demir  parmaklıklar  kesmez  yolunu ... Bil ki

     Yolunu   kesenlerle  hesaplaşır  bu  dünya

      hesaplaş sen de! ..', 'sen  orada  bekliyorsun ,  sen  suskun ,  sen  sabırlı      sen  biliyorsun  ki      toprak  dolar  taşar  birgün      sular  yol  bulur    ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hesaplasma-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Sen', 'once-sen-sair-hasret-n-kzqqp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'önce sen ses ver,sen söyle, sen konuş

ki zırhımı ne kadar  çıkaracagıma karar vereyim 

güvenemiyorum...

ne kadar kaldıracagım maske mi? bilemiyorum...

gözlerim görünmesin belki de 

gizlenmeliyim hep nolur nolmazlarda

önce sen, sen de hele  bakalım

kimsin? 

tartımın eşitligindeki yerini bulmalıyım,

işte  bu yüzden 

önce sen konuş! 

yani

sınırlarımın güvenligini korumalıyım 

parola sormam gerekirse 

yanlış sözcüklerde bocalamak,

inkar,

ve  kaçmak için zamanım olmalı

tam da bu yüzden 

önce sen konuş 

sen anlat

Kimsin?', 'önce sen ses ver,sen söyle, sen konuş ki zırhımı ne kadar  çıkaracagıma karar vereyim  güvenemiyorum... ne kadar kaldıracagım maske mi? bile...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/once-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-sair-hasret-n-fp44k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sihirli olan  hiçbir şey  yoktur Keşke  olsaydı ...İşte bu  sözcük, ''keşke''   _öyle sadece iki heceli,iki sesli üç sessiz harften oluşmuş bu sözcük _,  sihirli  bir şey bulmaya  iten insanları  o,lambadaki  cine,dilek kuyularındaki boşlugu dileklerle doldurmak istegine iten, inandıran....  Ben suçluyu buldum belki  de  ondan bir  parça  rahatım  artık.''Keşke'' yaşanılanı yaşamamış  olmak arzusu ,pişmanlık  duygusu. Yorar  insanı ,sorular yanıt bulmayınca sorun olur ,  gün güneşsiz,yagmur batak olur .Kötü bir  iklimde savunmasız kalıverir insan.İçindeki  boşluk duygusu insanın hiçbir şeyle dolmaz,yalnızca biraz alanı daraltılabilir  belki Çünkü bence yitirilen bir şeylerdir  boşluklar,maddenin kapladıgı  yer  gibi,kapınızın önündeki  araba gibi ,gittiginde  boşalan alan.Duyguların maddesel olamadıgı  düşünüldügünde  hele,  boşluklar  kimi  gerçek hayatta ,kimi de  düşlerimizde  bizi içine çeken anafor olurlar ,savrulur dururuz Ve bu arada  tutunacak birşeyler  ararız Eller hep açıktır ,yakalamak  ve  yakarmak için.

Keşke  demekten vazgeçmek zor  ama  denemek gerek .Suçluyu buldum demiştim ya  öyleyse  ne ile neye karşı savaştıgımı da biliyorum demektir.Degiştiremiyorsanız olanları  ''''peki ''  ''tamam'' Yaşadıgım şeyler hoşuma gitmese de  benim tercihimdi.Hata yapmışım,insanca bir şey yapmışım  sonuçta.Öyleyse çok fazla hesaplaşmanın alemi yok.'''' demek gerek.Dünyaya gelme olayı,anne rahmine tutunmamız, öncelikli  olarak  kazandıgımız ilk  koşuydu,biz kazandık  ilk başarımızdı bu  Yani yaşam hakkımızı kullanmalıyız  öyleyse.Birileri, sonradan gelip yaşamdaki  seyir  defterimize  dahil olanlar _  evlendigimiz kişi gibi,komşularımız gibi, iş arkadaşlarımız gibi_bizi etkileyebilirler  iyi ya da kötü  fakat egemen olamamalılar , buna izin vermemek  gerek.Bu arada  canınız yanabilir ,isyan edebilirsiniz  ama yalnız olmadıgınızı düşünün ...

üzgünüm  görüyorsunuz ya sihirli olan tek şey var  PAYLAŞMAK Dostlarımız var,çocuklarımız,SEVENLERİMİZ var, şiirler  var ...Birey olarak  BEN varım  demeyi  ögrenmek te var :) Bunlar  boşlukların alanlarını  daraltıyor  işte...', 'Sihirli olan  hiçbir şey  yoktur Keşke  olsaydı ...İşte bu  sözcük, ''keşke''   _öyle sadece iki heceli,iki sesli üç sessiz harften oluşmuş bu...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/keske-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Yok', 'adim-yok-sair-hasret-n-737uy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nerden geldigimi soruyorsun ya... 

 Bir söyleşi kadar kısadır yolum ...

  Ama dünyanın geçmişi kadar da  köklü ...

Ter döken ilk insandan gelmeyim...

Akşam olurken bir su kıyısında belini  agaca verip de ilk türküyü söyleyenim 

 Adım yok...', 'nerden geldigimi soruyorsun ya...   Bir söyleşi kadar kısadır yolum ...   Ama dünyanın geçmişi kadar da  köklü ... Ter döken ilk insandan ge...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adim-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delinin Sözleri', 'delinin-sozleri-ali-osman-yilmaz-rmz9p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey dostum’! 

Ben,

Senin gördüğünden,

Başka bir şey değilim.

Gördüğün,

Benim giysilerimdir,

Görmediğin ben ise,

İçimde yaşayan,

Sessizlik dünyasından,

Başka bir şey değildir.

Senden,

Söylediklerime,

Ve yaptıklarıma,

İnanmanı isteyemem.

Söylediklerim,

Senin öz düşüncelerinin,

Yankısından,

Başka bir şey değildir.

Rüzgar,

Doğudan esiyor desen,

Ben sahil boyunda,

Enginlere bakarken,

Sana hayır demeyeceğim.

Sen esen yele bakarken,

Ben aklımın yelkenine binip,

Uzaklara,

Gitmiş olacağım.

Senin için gün ışıdığında,

Bende gece,

Yeni başlıyor olacak.

Sen bana hayretle bakıp,

Deli mi ne bu,

Dediğinde,

Ben sana hayır bile,

Demeyeceğim.

Çünkü sen akılla,

Yeni yeni tanışırken,

Ben veda ediyor olacağım.', 'Hey dostum’!  Ben, Senin gördüğünden, Başka bir şey değilim. Gördüğün, Benim giysilerimdir, Görmediğin ben ise, İçimde yaşayan, Sessizlik dü...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/delinin-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokun Kalbime', 'dokun-kalbime-mustafa-murat-aydogdu-j2eg0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hala inanmadıysan sevgime

Kalbime dokun bir kere

Her atışında; sen

Dakikada atıyor belki binlerce kere! 

Ya seni çok seviyorum

Ya da kalp hastasıyım.

Hala inanmadıysan sevgime

Gözlerime bak bir kere

Gözbebeklerimin taa içine

Seni bulacaksın her zerresinde

Hala inanmadıysan sevgime

Benim içimden gelen bu kadar

Ve ne kadar uğraşsamda sevgim

Senin gözünde anlayabildiğin kadar

Yinede inanmadıysan sevgime

Kalbine dokun bir kere

Dokunki gerçekle yüzleş; 

Bir taş bulacaksın yerinde', 'Hala inanmadıysan sevgime Kalbime dokun bir kere Her atışında; sen Dakikada atıyor belki binlerce kere!  Ya seni çok seviyorum Ya da kalp ha...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dokun-kalbime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen İçin', 'sadece-sen-i-cin-sair-hasret-n-budpo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gidişin bir ayrılık,küçük bir ölüm.

Giderken benden neler götürdün sevgilim,

Her ölümde biraz daha eksilerek bu kaçıncı dirilişim? 

Ömür boyu seninle olmak istediğim için,

Sadece sen için,

Bu kaçıncı kendimden vazgeçişim? 

Evet biliyorum hayat hiç romantik olmadı

Ve aşk da hiç adil değildi.

Ama şimdi sana hala aşıkken

Ve hayatımda ilk kez

Acı çekmeden özlüyorum seni...', 'Her gidişin bir ayrılık,küçük bir ölüm. Giderken benden neler götürdün sevgilim, Her ölümde biraz daha eksilerek bu kaçıncı dirilişim?  Ömür...', ARRAY['Türk Edebiyatı','Şiir','Şair Hasret_n']::text[], 8.5, '{"poet":"Şair Hasret_n","poet_slug":"sair-hasret-n","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sadece-sen-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Dostane Bir İkaz', 'sevgiliye-dostane-bir-i-kaz-nuri-yilmaz-av3xm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynalara itimat etme.

Savudukça rüzgar bir bir kırılacak.

Yere çarpılmış bir cam gibi kalbin  parçalanacak.

Azap içinde yanacak.

Yandıkça azabı seni yakacak.

*****                     *****                *****

Gölgelerin peşinden koşma.

Benide koşturma.

Şişeleri elmas sayıp avunma.

Benide avutma.

Gençliğimizin bitmesiyle aşkımızı bitirme.

Güneşin batmasıyla aşkımızı batırma.

Yıldızların sönmesiyle aşkımızı söndürme.

Ölmün gelmesiyle aşkımızı öldürme.

Ölüm ötesini gör,fenaya gittiğimizi sanma.

Yalan küfre kanma.

İbrahim aleyhiselam gibi ebedin formülünü bul.

Ondan şaşma.

*****                *****               *****

Gel ölümün tebessümlü cehresine gülelim.

Bizden ne istiyor,bilelim.

Korkulacak bir şey yok,sevinelim.

Bu baki bestenin şarkısını beraber dinliyelim.

Ne sen bana,ne de ben sana...

İkimizde Allah''a kul olalım.

Allah rızaslyla yaşayalım.

O''nun uğruna ölelim.

Bu şerefle sultanlığımızı kutlayalım.

2005/Üsküdar-İST.', 'Aynalara itimat etme. Savudukça rüzgar bir bir kırılacak. Yere çarpılmış bir cam gibi kalbin  parçalanacak. Azap içinde yanacak. Yandıkça az...', ARRAY['Türk Edebiyatı','Şiir','Nuri Yılmaz']::text[], 8.5, '{"poet":"Nuri Yılmaz","poet_slug":"nuri-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevgiliye-dostane-bir-ikaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / OZAN''IM', 'bir-dortluk-de-sen-yaz-ozan-im-siir-perisi-grubu-cd1w7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/OZAN''IM'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

****OZAN''IM**** 

Nice diyarlar gezip, görmedim gerçek seven 

Oysa sadakat dolmuş, kalbe AKAN Ozanım 

Feryat’la acı çekip, durmadan dizi döven 

Sonunda pişman olmuş, yürek YAKAN Ozanım*******Ayak Dörtlüğü 

1. 

Sevince küle dönen, terk edişle savrulan 

İhanetlerle sönen, ateşlerle kavrulan 

Aşk rahvanına binen, bir çelmeyle devrilen 

Acımasız maziye, dönüp BAKAN Ozanım**********Şeyhmus Sevilmez 

2. 

Bir aşkın soluğuna, gül kokusu ekmedim 

Sevgili ağlar iken, sineye gam çekmedim 

Mızrapla tele vurup, türkülere dökmedim 

Bağlama''nın bam''ına, hüzün TAKAN Ozanım******Turan Orak 

3. 

Analar mahzun gördüm, haram süte ağladım 

Ol Resulü dinlerken hakikate ağladım 

Taşrada ölür yiğit, sadarete ağladım 

Bir yanında gözyaşı, bir yanı KAN Ozanım.*****Zülfikar Yapar Kaleli 

4. 

Yakarlar meşaleyi çıkarlar Hak yoluna, 

Yiğit olur kelleyi kor halkının halına, 

Taşarlar bedeninden söz söyletmez nalına, 

Türkü deyiş tadında mis KOKAN Ozanım.***********İsmail Doğan 

5. 

Mızrap oldum ellere, düştüm sazın teline, 

Türkü oldum yellere, kapıldım aşk seline, 

Name oldum dillere, Orkun kurban eline, 

Namerdin şakağına, güller SIKAN Ozanım.*************Orkun IŞIK 

6. 

Usta,çırak atışır,açılır gerçek yürek, 

Vurur sazın teline,gamı olsa da dilek, 

Saygıyla eğilerek,kırılır sazda bilek, 

Sonra öper elini,ustanın CAN Ozanım.*************Sevim E.Tezel 

7. 

Ozan milletin dili, susmak yakışmaz ona, 

Bağlamayı duvara asmak yakışmaz ona, 

Haksızlık yapılsa da küsmek yakışmaz ona, 

Zalime çivi gibi sözü çakan Ozanım. *************Şahin Yılmaz 

8. 

İyileri savunur, hakka kafa yorarsın; 

Kötülüğü azmini direncinle kırarsın; 

Bıkmadan usanmadan gerçek aşkı ararsın; 

Girdiği yüreklerde ateş YAKAN Ozanım.*************Ayşe Korkmaz 

9 

Hasret kalbe vurunca,gözden akar selimiz 

Eller kalem tutunca,kağıt olur dilimiz 

Gönüller bir olunca,bağda solmaz gülümüz 

Her iklim her mevsimde,yeşil HIRKAN Ozanım*****Tuncay Akdeniz 

10. 

Dökülür avucumdan, sevdalı duygularım 

Avunur mısralarla, hasreti vurgularım 

Kaybolur yağmurlarda, maziyi sorgularım 

Gözyaşımla dağları delip YIKAN Ozanım***********Feride Özmat 

11. 

Ömür geçti geçiyor, zamanın yok ilacı, 

Düşmanlık ayak altı, sevgi başların tacı, 

Mecnun dilinde rahmet, Leyla sana duacı, 

Şu çekilmez hayata güller TAKAN Ozanım.**********Necmi ÜNSAL 

12. 

Nice mihnetlere hep, eğip durdum başımı, 

Çile mihnet bir türlü bırakmadı peşimi, 

Kayıp ettim ararım, akranımı eşimi, 

Can bağına, can için mihnet EKEN Ozanım.**********Hasan Ulusoy 

13. 

Olmayacaksan benim, şiirimde işin ne? 

Haklı haksız kim diye hiç baktın mazine? 

Sevgi, en büyük dindir, aşk mezheptir biline 

İbadet olur diye türkü YAKAN Ozanım.****************Metin Yaltı 

14. 

Kimi zengin atadan, kimi ezelden fakir 

Kiminin kalbi fesat, kimininki saf, bâkir 

El elden üstün deyip, kimse görmesin hakir 

İnsan insana muhtaç, erdem kokan Ozanım.********* Mehmet Lütfü Aydın 

15. 

Şiirlerde ki anlam saklıdır hece, hece? 

Ders alır bazıları,iyice düşününce 

Ömrümün sonuna tek, hem gündüz hem de gece 

Haksızın sarayına incir DİKEN Ozanım****************Mustafa Kemal Bal 

16. 

türküler de yaşatır kültürümü dilimi 

sazın telinde aşkı, mızrabın da bilimi 

işliyor nakış nakış şiirler de kilimi 

halkımın gözü, dili çile ÇEKEN Ozanım.*************Sevil Nizamoğulları 

17. 

Anadolu''mun süsü, mana dolu nakışı. 

Sevda çekenin dili, aşıkların bakışı. 

Yüreklerin atiye şiir şiir akışı. 

Karanlığa gönlünden ışık YAKAN Ozanım.***********Necmi ÜNSAL 

18 

Mutluluğu misafir etmeksizin ser''ine 

Hiç bir gün üzülmeyip, boşa akan terine. 

Ömür boyu gülmeyip, gözlerden yaş yerine, 

Bir sevgili uğrunda ağu DÖKEN ozanım.****** Mustafa Erkenekli

(Şiir Perisi Grubumuzun her hafta düzenlediği ''Bir Dörtlük de Sen Yaz'' aktivitesi sonucu oluşan ortak bir eserdir.)', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/OZAN''IM'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun Şİİ...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-ozan-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-gulnare-leman-rs9zw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen her zaman uykumdasın,uyanırım seher sensiz

Acı dolu gamla geçir, günlerim bir beter sensiz.

Talihimi bağlamışım,bir tek senin ümitine,

Emin ol ki,vermeyecek,arzularım beher sensiz.

Sevda sensin,özlem benim,yüreğimin sözlerini,

Aman vermez deyim sana,yüreğimde keder sensiz.

Neyleyim ki,umutum yok,yetmek için visaline,

Dayanamam ayrılığa,içerim bil zehir sensiz.

Gulnare Leman

beher- meyve,semere,kazanç', 'Sen her zaman uykumdasın,uyanırım seher sensiz Acı dolu gamla geçir, günlerim bir beter sensiz. Talihimi bağlamışım,bir tek senin ümitine, E...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-ugur-aydin-2-61gv8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittiğin günden beri tütmez oldu dumanım 

Her şeyimi kaybettim yok sığınacak limanım 

Bu kaptanı derya da bana da var bir liman 

Yerini  bilmiyorum  adı  ise  kabristan

Artık rotam bellidir  gidilecek tek liman 

Vakit yaklaştı  sende üzülme inan 

Bu gemiye de vardır sığınacak bir liman 

Yerini  bilmiyorum  adı  ise  kabristan', 'Gittiğin günden beri tütmez oldu dumanım  Her şeyimi kaybettim yok sığınacak limanım  Bu kaptanı derya da bana da var bir liman  Yerini  bil...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/liman-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-huseyin-alan-6pnzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğan ışıklarıyla sabahın

Hayellerime indi umut

Sevgiye tutulan acıyla

Döndü başım 

Dilime dolanan sözler gibi

Beni senden uzak tutan

Ne varsa

Yıkılsın 

Dağılsın...

Kuralım el ele 

Aşk ülkesini

Dikelim sevda ağaçlarını

Her gönülün,yemişimden yemesi için

Düşüme girdi bir gece yarısı

Güzel yüzün

Işıktan demet demet

Gözlerin

Duydum sesini

Ötelerden gelircesine

Severcesine...

Salkım Salkım yüreğim

Derinlerde

Delice

Duygularımda ismin

Dokunuyor her zerresiyle

Yanık tenime

Sarılarak sıcaklığına 

Adına...

Gönül sevmiş

Göz bakmış

Kalbine ilişmiş

Anlına yazılmış

Seni sevmek

Bu yürek dayanmaz

Sensiz kalışına

Uzaklaşıp gidişine

Bakışını çekişine

Nefesini alışına

Kaçarcasına

Sevgisizliğe

Sevmek candan 

Aşk olmadan

Zor ellerine değmek

Dokunmak hislerine

İnan çok zor

Seni sevmek...', 'Doğan ışıklarıyla sabahın Hayellerime indi umut Sevgiye tutulan acıyla Döndü başım  Dilime dolanan sözler gibi Beni senden uzak tutan Ne var...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/seni-sevmek-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla yürek', 'agla-yurek-gulnare-leman-1b5ix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağla yürek,ağla ele yürekten,

Akan göz yaşını gören olmasın.

Sızla yürek,sızla ele yürekten,

Çıkan od-dumanı gören olmasın.

Başını uca tut,yıkılma bir an

Bu zor zamanında,gülen olmasın.

Yalnızlığını unut,sıkılma bir an

Senin bu halini duyan olmasın.

Bir içim suya, hasret kalsanda,

Kimseye yalvarma bu halında da.

Zor ile sevdirme kendini hiç vaht

Sevgi dünyasıntan kam almasanda.', 'Ağla yürek,ağla ele yürekten, Akan göz yaşını gören olmasın. Sızla yürek,sızla ele yürekten, Çıkan od-dumanı gören olmasın. Başını uca tut,y...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agla-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Ölesim Var', 'bu-gece-olesim-var-umit-engin-zkaj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece ölesim var,

Kor kuytularda kaybolurcasına,

Kimsenin bilmediği yollara vurasım var kendimi,

Dipsiz kuyularda kaybolurcasına,

Bu gece ölesim var,

Hayata ilk defa gözlerimi açarcasına,

Tuzakların arasında parçalanırcasına,

Kalbine tutsak kalırcasına….

07.08.2005 / 22:35 / Ümit Engin', 'Bu gece ölesim var, Kor kuytularda kaybolurcasına, Kimsenin bilmediği yollara vurasım var kendimi, Dipsiz kuyularda kaybolurcasına, Bu gece ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Engin']::text[], 8.5, '{"poet":"Ümit Engin","poet_slug":"umit-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-gece-olesim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki', 'yeter-ki-fevzi-kunucen-v6nf8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al beni

Götür dilediğin yerlere

Yeter ki oralarda

Gök mavi

Sevgiler gerçek

Toprak bereketli olsun', 'Al beni Götür dilediğin yerlere Yeter ki oralarda Gök mavi Sevgiler gerçek Toprak bereketli olsun...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeter-ki-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Hüznüm', 'eylul-huznum-bahtiyar-arslan-t2fbd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey dökülen yaprağım

Aşım

Ekmeğim

Suyum

Hayal yaram

Alın yazım

Eylül yaram 

Neredesin...

Ey gözlerimin karası

Yürek yaram 

Ölümlere git-gellerim

Eylül hüznüm 

Neredesin...', 'Ey dökülen yaprağım Aşım Ekmeğim Suyum Hayal yaram Alın yazım Eylül yaram  Neredesin... Ey gözlerimin karası Yürek yaram  Ölümlere git-gelle...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eylul-huznum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değil Miydin', 'sen-degil-miydin-mustafa-dogan-kuzgun-ux4j8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece acılarımı; 

Bir büyük şişesine boşaltıp,

Kadehlerde yudum tudum içtiğim.

İzmaritlerde kaybedip,

Ciğerime nefes nefes çektiğim.

Sayfalara döküp te,

Kalemlerde satır satır dizdiğim.

Söyle,

Sen değil miydin

Söyle,

O zalim...', 'Her gece acılarımı;  Bir büyük şişesine boşaltıp, Kadehlerde yudum tudum içtiğim. İzmaritlerde kaybedip, Ciğerime nefes nefes çektiğim. Sayf...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-degil-miydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-asli-yildiran-r4haw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Balık ekmek yemek gibi tehlikeli seni düşünmek

boğazıma kılçık takılabilir ve kanatabilir içimi

Bilsen çılgınlığım almış başını gitmiş

senin gibi o da beni terketmiş

ve hem sana hem çılgınlığıma hasretimi bilsen

koşup gelmezdin biliyorum, sarılmazdın boynuma.

Rüzgarlı havalarda saçlarını salık bırakmak gibi birşey seni düşünmek

Dağılacağını bile bile, savrulup gideceğini bile bile

Seni düşünmek yüreğin yana yana ve bu yangına bir damla su düşmeyeceği halde.

Sokak çocuklarının gözlerindeki çaresizlik gibi birşey seni düşünmek

Kuytularda hayallere dalıp gitmek, aniden sırtına inen darbeyle yere 

serilmek gibi birşey

Ağrı dağına çıkabilmek ve hiç ummadığın anda yuvarlanıp düşmek gibi 

birşey seni düşünmek

07.08.2005', 'Balık ekmek yemek gibi tehlikeli seni düşünmek boğazıma kılçık takılabilir ve kanatabilir içimi Bilsen çılgınlığım almış başını gitmiş senin...', ARRAY['Türk Edebiyatı','Şiir','Aslı Yıldıran']::text[], 8.5, '{"poet":"Aslı Yıldıran","poet_slug":"asli-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-dusunmek-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayende', 'sayende-mustafa-dogan-kuzgun-y1cxq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmura dost oldum, kışa komşu

Ne yazım kaldı, ne bahar... Hepsi yok oldu.

Evet dediğinde dünya benimdi

İşte o an geldi, eridim yok oldum.

Gökkuşağı kardeşimdi, sayende oldu düşman

Önümde diz çöksende olacaksın çok pişman.

Baharla aramız iyiydi, şimdi uğramaz oldu.

Sonbahar hiç gelmezdi, Şimdi gidemez oldu.

Sen gittin gideli, güneşi bile göremiyorum

Gündüzleri özlüyordum, şimdi nefret ediyorum.

Sayende tatlı dillim sayende

Gözler önünde yok oluyorum, ölüyorum, sayende...', 'Yağmura dost oldum, kışa komşu Ne yazım kaldı, ne bahar... Hepsi yok oldu. Evet dediğinde dünya benimdi İşte o an geldi, eridim yok oldum. G...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sayende-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-mustafa-dogan-kuzgun-jx4mz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gene gözümün önünde hayalin

Bir türlü gitmek bilmiyor

Sen gidip unuttun ya! 

Hayalin unutmadım diyor.

Belki sen de unutmadın beni

Belki gözlerinde eski günleri

Belki cüzdanındaki resmin sahibi

Sana unutturmuyor, hayalin öyle söylüyor.

Senden başka sevemedim kimseyi

Senden başka tutamadım bir eli

Senden başkasına veremedim bu kalbi

Sen de veremedin, hayalin öyle söylüyor.

Her gece rüyamdaki sevgilim

Her sabah başucumdaki resmin

Her an gözümün önündeki hayalin

Unutmadı diyor, hayalin öyle söylüyor.

Sen gittin gideli yüzüm gülmüyor

Resmin elimde, bir an bile düşmüyor

Yürüdüğün yollar geri dönecek diyor.

Hayalin, hayalin sevdiğim öyle söylüyor.', 'Gene gözümün önünde hayalin Bir türlü gitmek bilmiyor Sen gidip unuttun ya!  Hayalin unutmadım diyor. Belki sen de unutmadın beni Belki gözl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayalin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakiki dostunu bilmek istersen', 'hakiki-dostunu-bilmek-istersen-mikdat-bal-u50v5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hakiki dostunu bilmek istersen

Dost bildiğin dosta dertteyim söyle

Benim dediğime gelmek istersen

Düştüm bir batağa dertteyim söyle

Bir bakarsın dostlar yok olur birden

Onların da derdi çok olur birden

İçleri dışına dökülür birden

Yeter ki bir kerre dertteyim  söyle

Can dostum diyerek avutur seni

Dara düştüğünde unutur seni

Mazeret gösterip uyutur seni

Sahte dosta bir kez dertteyim  söyle', 'Hakiki dostunu bilmek istersen Dost bildiğin dosta dertteyim söyle Benim dediğime gelmek istersen Düştüm bir batağa dertteyim söyle Bir baka...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hakiki-dostunu-bilmek-istersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-fami-ezer-x84aq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülü seven bülbül aldırmaz dikende, Acısı zevk verir sevdasını çekende, Sevgi yürekte büyür tohumu ekende, Ayrılmaz bülbül gülden gülse dikende... Aşık sevgiyi tadar bana bana, Ana yavrusunu arar yana yana, Toprak suya muhtaç kana kana, Sevdan yüklenmişse fami cana, Bende sana muhtacım gülüm anlasana....', 'Gülü seven bülbül aldırmaz dikende, Acısı zevk verir sevdasını çekende, Sevgi yürekte büyür tohumu ekende, Ayrılmaz bülbül gülden gülse dike...', ARRAY['Türk Edebiyatı','Şiir','Fami Ezer']::text[], 8.5, '{"poet":"Fami Ezer","poet_slug":"fami-ezer","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/anlasana-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Bir Müsvettesi Olsaydı Yaşamın', 'keske-bir-musvettesi-olsaydi-yasamin-pakize-arpaci-m253c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '--------------------

Keşke bir müsvettesi olsaydı yaşamın

Silebilseydik, hatalarımızı

Karalayıp, atabilseydik çöpe,

iz bırakmasaydı, attıklarımız bizde.

Keşke, keşke müsvettesi olsaydı yaşamın

Yaşamadan evvel prova etseydik

Ne kalbiz kırılır, nede kalp kırar idik.

Niye yok, niye? 

Niçin hiçbir söz, 

Hiçbir bakış tekrar edilemez,

Bir müsvettesi olsaydı yaşamın,

Kimbilir belkide daha az acı çekerdik.

Keşke bir müsvettesi olsaydı yaşamın', '-------------------- Keşke bir müsvettesi olsaydı yaşamın Silebilseydik, hatalarımızı Karalayıp, atabilseydik çöpe, iz bırakmasaydı, attıkla...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/keske-bir-musvettesi-olsaydi-yasamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Kan Ağlıyor', 'dunya-kan-agliyor-pakize-arpaci-6qymt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya kan ağlıyor

kan var avuçlarımızda

her zulmü olur kıldık

kendi varlığımıza,

evren kan ağlıyor

sorun var insanlığımızda

yıldızları küstürdük,

doğa kırıldı bize

huzuru saldık rüyalara

Dünya kan ağlıyor

kan var avuçlarımızda

Her zulmü olur kıldık

vurdumduymazlığımızla.

Herşeyi lüksümüze bağladık

insanlığımızı en uzak gezeğene yolladık

Ruhumuzu da boyutlar arasına saldık

Dünya kan ağlıyor

kan var avuçlarımızda

Her zulmü olur kıldık

bencil, kibirli duyarlılığımızla.', 'Dünya kan ağlıyor kan var avuçlarımızda her zulmü olur kıldık kendi varlığımıza, evren kan ağlıyor sorun var insanlığımızda yıldızları küstü...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunya-kan-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-muhammed-murad-uzun-ivgw8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan Yalan Yalan

Fani dünya yalan

Gülüsler yalan 

Yalan Yalan Yalan 

Gercek dostlar 

Gecmiste kalan 

Göcmüsler birer birer

Kim bilir kimler hak er 

Zalim düzen zulum keder

Dostu dosta dusman eder', 'Yalan Yalan Yalan Fani dünya yalan Gülüsler yalan  Yalan Yalan Yalan  Gercek dostlar  Gecmiste kalan  Göcmüsler birer birer Kim bilir kimler...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalan-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Karınca İzinde Kala!', 'gozlerin-karinca-i-zinde-kala-zulfikar-yapar-kaleli-i98rx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

-M.Nihat Malkoç''a-

Canım boğazımda sevgili dostum

Seni arıyorum, nerelerdesin? 

Ne hikmetse bu gün hayata küstüm

Hangi suya muhtaç derelerdesin? 

Görmez misin? Erciyes’in karını

Akçay’da unutmuş namus, arını

Aras’a yüklemiş arzularını! 

Ulaşılması zor yörelerdesin…

Hasretle Hazar’a akıyor Aras

Talihi bohçala dut dalına as

Anasının bahtı kızına miras

Zamansız aşınmış sürelerdesin…

Baharın kara kış olmasın sakın

Kem talihin seni bulmasın sakın

Dikkat et bu güle. solmasın sakın

Hakikate inat törelerdesin! ! ! 

Muradın karganın gözünde kala

Ahirin sarhoşun sözünde kala

Gözlerin karınca izinde kala

Hala boşalmakta firelerdesin…

Arzu zıbınıyla sararım seni

Hayal kuşlarına sorarım seni

Gönül fincanımda  ararım seni

Sense güney yarım kürelerdesin!', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' -M.Nihat Malkoç''a- Canım boğazımda sevgili dostum Seni arıyorum, nerelerdesin?  Ne hikmet...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gozlerin-karinca-izinde-kala-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüsran Gazeli', 'husran-gazeli-kenan-yasar-uij9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dolu bilinen küpleri açtım gördüm boş çıktı

nice  hayır  sandığım şer, kem sandığım hoş çıktı

vefakarım cefakarım ben umudum diyenler

bir balonmuş anlaşıldı  hafta geçti fos çıktı

dar günü görmeyen dost seçemez imiş. doğru

nice yarenlerim yaban,el sandığım dost çıktı.

geceleyin kaf dağının ardı gibi söylenen

nice cennet bahçeleri gün ağardı boz çıktı

mangalda kül bırakmayan yiğitlik taslayanın

er meydanı gördüğünde kaçışından toz çıktı

dün derdiniz derdim diyenler bugün

gamsız çıktı hissiz çıktı yoz çıktı

devim diyen cüce çıktı çoğum diyen az çıktı

kurnazlığın abidesi tüyü dökük kaz çıktı

kırıldı çubuğu koro şefinin

yalnız amma doğru çalan saz çıktı', 'dolu bilinen küpleri açtım gördüm boş çıktı nice  hayır  sandığım şer, kem sandığım hoş çıktı vefakarım cefakarım ben umudum diyenler bir ba...', ARRAY['Türk Edebiyatı','Şiir','Kenan Yaşar']::text[], 8.5, '{"poet":"Kenan Yaşar","poet_slug":"kenan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/husran-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Gazeli', 'sevda-gazeli-kenan-yasar-yjzea', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilmek yanmak demekmiş, bilerek yanıyorum

yandıkça   seviyorum,   sevdikçe  tanıyorum

gördüm bakışlarından bir nehir aktı geçti

sevdanın  oltasını   gönlüme  taktı   geçti

gözlerinde açıyor lalelerim güllerim

bir düşsel gezintidir saçlarında ellerim

elem koydum adını,hasret var ayrılık var

sesinden mahrum etme sözünde mutluluk var

gitmesen hiç yanımdan ömür boyu beklesen

benim gibi damlaya okyanusu yüklesen

ben bu toprağın canı akan suların sesi

rüzgarların  nefesi,  ateşin ta  kendisi

ben sevgi ağacının incecik bir dalıyım

nirvanaya ulaşmış bir kara sevdalıyım.

kelimeler yetersiz arifler de anlamaz

sözler başlangıç yapar cümleler tamamlamaz

yaşamamışsa şair yetmez  ki  bilgeliği

hangi hayal giydirir aşka bu güzelliği

bu  aşkın  bedelidir   diyerek  bir şeyleri

haydi durmayın serpin üstüme kederleri

bilmek yanmak demekmiş bilerek yanıyorum

yandıkça   seviyorum, sevdikçe   tanıyorum.', 'bilmek yanmak demekmiş, bilerek yanıyorum yandıkça   seviyorum,   sevdikçe  tanıyorum gördüm bakışlarından bir nehir aktı geçti sevdanın  ol...', ARRAY['Türk Edebiyatı','Şiir','Kenan Yaşar']::text[], 8.5, '{"poet":"Kenan Yaşar","poet_slug":"kenan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-gazeli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışların Dile Geldiği Yer', 'bakislarin-dile-geldigi-yer-melih-coskun-zekju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Artık çocuk değiliz, susarak da bir şeyler diyebiliriz''

Hasan Hüseyin Korkmazgil

Bakışların dile geldiği yerdir 

Büyümek

Sessiz hecelerim göz ucumda

Gebedir gecenin o büyük yangınına.

Gözlerim anlatır sana 

Hasretin en büyüğünü 

En güzelini kavuşmaların 

En temiz öpücüğümü 

Bembeyaz teninde hayatın

Büyüdüm, 

Eskisi gibi küçük değil artık gözümde hiçbir şey 

Ve büyüdü aşk gözlerimizde

Sadece küçücük bir bakışla...

Sahte sevişmelere ayarlanmışken bütün saatler 

Çıkartıp attım gönlümden 

Bütün yalanlarını ömrümün

Kendimi bile soyutladığım

Bir ben sunuyorum sana. 

Al sar beni

Yavru ceylan bakışlarına...', '''Artık çocuk değiliz, susarak da bir şeyler diyebiliriz'' Hasan Hüseyin Korkmazgil Bakışların dile geldiği yerdir  Büyümek Sessiz hecelerim g...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bakislarin-dile-geldigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Arama Baktığın Yerdeyim', 'beni-arama-baktigin-yerdeyim-mustafa-dogan-kuzgun-epz1k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni arama baktığın yerdeyim

Güneşin kızıl renginde, gün batımındayım

Denizin uçsuz maviliklerinde, bir martının kanadındayım

Beni arama, belki bir deniz kabuğundayım.

Beni arama baktığın yerdeyim

Bir yıldızın parıltısında,

Boşlukta gezen taş parçasıyım

Beni arama, belki de ayın dolunayındayım.

Beni arama baktığın yerdeyim

Belki pencerendeki saksı,

O saksıdaki gül fidanıyım

Beni arama, saksıdaki toprak parçasıyım.

Beni arama baktığın yerdeyim

Gecenin karanlığında, sabahın ilk ışıklarındayım

Beni arama, belki bir yağmur damlasıyım.

Beni arama ben baktığın yerdeyim...', 'Beni arama baktığın yerdeyim Güneşin kızıl renginde, gün batımındayım Denizin uçsuz maviliklerinde, bir martının kanadındayım Beni arama, be...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-arama-baktigin-yerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğanın senfonisini dinlerken', 'doganin-senfonisini-dinlerken-ali-osman-yilmaz-55rmh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin aydınlığında,

Bir tepeye çıktım,

Yaşamın bestelediği.

Sessizliğin senfonisi yankılanıyordu,

Uzaklardan.

Yaşama karşı,

Yenilgilerimi düşündüm,

Yalnızlığım,

Ve kimsesizliğim yanımdayken.

Geçmişte kazandığım,

Binlerce yengilerden,

Bana kalan en güzel şey,

Sen.

Yaşamdaki başarılarımdan,

Yüreğime en yakın olan,

Sen.

Seninle olduğum için ben,

Ayakları yerde,

Defne yaprakları peşinde koşmayan,

Biri olduğumu biliyorum,

Ben sende kendimi,

Yalnızlığımı buldum,

Gözlerine baktığımda,

Sevgiyi değil,

İkbal arayanın,

Kendisine kul olduğunu,

Gördüm.

Şimdi,

Doğanın senfonisini dinlerken

Anladım ki,

Birinin özünü anlayabilmek için,

İçindeki sevginin gücünü,

Söndürmek gerekirmiş.

O zaman,

Duyamazmış insan,

Doğanın senfonisini,

Şu anda ben,

Seni düşlüyorum,

Ve içimdeki sevgin,

Yanardağlar gibi,

Yüreğimi dağlamakta.

Yanaklarımda ıslaklık,

Galiba yine,

Gözlerim ağlamakta.', 'Gecenin aydınlığında, Bir tepeye çıktım, Yaşamın bestelediği. Sessizliğin senfonisi yankılanıyordu, Uzaklardan. Yaşama karşı, Yenilgilerimi ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/doganin-senfonisini-dinlerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasılsa Unutacaksınız Yaşadığımı', 'nasilsa-unutacaksiniz-yasadigimi-mustafa-dogan-kuzgun-iv40u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasılsa unutacaksınız yaşadığımı

Bırakın o hayallerin yapmacığını

Ömrümdeki yalnızlığın duvarına

Harç olarak kullandınız gözyaşlarımı...', 'Nasılsa unutacaksınız yaşadığımı Bırakın o hayallerin yapmacığını Ömrümdeki yalnızlığın duvarına Harç olarak kullandınız gözyaşlarımı......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nasilsa-unutacaksiniz-yasadigimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşünü Sulara Dök', 'gulusunu-sulara-dok-meral-vurgun-qqpw2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülüşünü sulara dök

akıp gelsin doludizgin

yaralı bir denizim ben

ırmakların 

değişen yataklarına ser uykularını

içinin acılarını çağlayanlara bırak

köpük köpük ört üstünü 

bir sel gelir, götürür dünyanın yalanını

gülüşünü sulara dök

sabır taşları bıraktım koyaklarda

nergizler açmazsa kuytularda

adına ölüm denir elbette

sen bir gelincikle yürü 

ben gelirim ardından karafillerle

gülüşünü sulara dök

ve beni orada bekle

mezhepsizdir yoksulluk

susku imansız, dinsiz, ve Allah’lı

işkence vatansız/ırkçı

zulüm küresel

düşünce tutsak/esir

direniş evrensel ve destansı

gülüşünü sulara dök

dök ki, gelip içsin çocuklar

beni suretinde arama

şarapnel parçalarıdır yutkunduğum sözcükler

yüzünü görsem kanatlanır gözlerim

uçabilsem düşüp ölmezdim

yüklendiğim çiçeklerle

gülüşünü sulara dök

adalet dedikleri

kralların koynunda çürüyen bir yosmadır

mezar aralarımızda dolaşan kara gölgeleri

yakmak için tutuşan meşale

acının steplerini harlandırır

gülüşünü sulara dök

gelip suretini öpeceğim....', 'gülüşünü sulara dök akıp gelsin doludizgin yaralı bir denizim ben ırmakların  değişen yataklarına ser uykularını içinin acılarını çağlayanla...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gulusunu-sulara-dok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berzah alemí', 'berzah-alem-mikdat-bal-lutz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her nefs. Her can sahibi, ölümü tadacaktır

Toprak emanetini, alacak yutacaktır

Artık yeni bir hayat, alemi berzah başlar

Orası nasıl bir şey, dinleyin arkadaşlar

Can çıkınca ruh gelir, bu alem başka alem

Menzile ulaşıldı, ya sefadır ya elem

Sorgu melekleri var Munkir Nekir adında

Sorarlar Rabbin Kimdir, ne ettin hayatında? 

Rabbi, Nebisi,  dini, üç sualde sorulur

Cevap veremeyenin, ensesine vurulur! 

Artık mezar ya cennet bahçesinden bir bahçe! 

Ya cehennem çukuru, ateş dolar ilk önce! 

Varacağı makamı seyreder akşam sabah 

Her anı pişmanlıktır, faydasızdır ahü- vah! ! 

Hesap gününe kadar, beklenilir orada

Ondan daha dehşetli, bir gün var ki sırada! 

Önce dünya yıkılır, buna kıyamet derler

Dünya altüst olacak, dümdüz olacak yerler

İsrafil Sür’a üfler, insanlar dirilecek

Bu dünya hayatının hesabı verilecek! 

Gözleri şaşkın şaşkın mezarlardan çıkarlar

O sese doğru koşar, bir sel gibi akarlar

Herkes kendi derdinde, kaçacak kardeşinden,

Hem anne babasından, evlatından, eşinden

O gün bir takım yüzler sevinçten ağaracak 

Yüzleri kararanlar, yalvarıp yakaracak! 

Bir anlık bile olsa, dünya ya dönmek ister

İbadede dalarak sevap edinmek ister

Ona sus denilecek,mazeretin kalmadı

Ömrünü boş geçirdin, hesap derdin olmadı

İnananlara yobaz, dine safsata dedin

Tat bakalım azabı, kendine zulüm ettin

Bu gördüklerin şimdi, gerçek değil mi söyle

İstersen bağır çağır, istersen de sabreyle', 'Her nefs. Her can sahibi, ölümü tadacaktır Toprak emanetini, alacak yutacaktır Artık yeni bir hayat, alemi berzah başlar Orası nasıl bir şey...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/berzah-alemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulaşılmazım Sevdiğim', 'ulasilmazim-sevdigim-hatice-bediroglu-q0fzj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerden

Demetler yapıyorum

Yeni düşlerde 

Seni görebilmek için. 

Ulaşılmazım… 

Sevdiğim…. 

Dokunamıyorum 

Yoksun...yoksun işte 

Canım öyle yanıyor ki 

İçim çekiyor 

Daralıp küçücük oluyor 

Senin içinde olduğun 

Tek bir hece bile 

Beynime

Ulaşsın istemiyoru 

Tonlarca 

Kum yığıyorum kalbime 

Altında kalman için 

Yarıp çıkıyorsun üstüne 

Silemiyorum beynimden

Hiç gitmedin ki zaten

Dalıp gidiyorum yine 

Gözlerim sana takılı 

Bilmediğim, görmediğim 

Sulara açılmış

Seni aramaya 

Devam ediyorum 

Salımın üzerinde 

Göz yaşlarımdan 

Gölcükler oluşmuş 

Başım ağır 

Gözlerim yorgun 

Sersem sersem 

Yol alıyorum

Belki… Belki 

Uçsuz bucaksız 

Mavilerin içinde 

Maviye aşık

Sen varsın diye

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Düşlerden Demetler yapıyorum Yeni düşlerde  Seni görebilmek için.  Ulaşılmazım…  Sevdiğim….  Dokunamıyorum  Yoksun...yoksun işte  Canım öyle...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ulasilmazim-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahvede Randevun Var -(Hiciv)', 'kahvede-randevun-var-hiciv-kemal-tahir-ozcan-smwso', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saat dokuzdan önce, gelme sakın işine,

Üzüleyim deme  hiç, işlerin gidişine,

Mesai gelir geçer,  tak canını  dişine,

Bırak  işin  ucunu,  vatandaşı  oyala,

Kahvede randevun var, beş buçuğa beş kala.

Nasıl olsa aybaşı, alırsın maaşını,

Yetmez diye maaşım, ağrıtma hiç başını,

Sana iş yaptırana, çat şöyle bir kaşını,

Tut biraz sende baldan, parmaklarını yala,

Kahvede randevun var, beş buçuğa beş kala.

İşin sıkı zamanı, yirmi gün rapor patlat,

Şefini müdürünü, sinirlendirip çatlat,

Şimdi gelirim diye, bekleyenlari atlat,

Sıvış arka kapıdan, çaktırmadan dört nala,

Kahvede randevun var, beş buçuğa beş kala.

Bazen kazı kazan al, bazen de spor toto,

Bazen altılı ganyan, bazen sayısal loto,

Hele birde çıkarsa, şöyle süper bir oto,

Saat beşi geçiyor, ne duruyorsun hala,

Kahvede randevun var, beş buçuğa beş kala.', 'Saat dokuzdan önce, gelme sakın işine, Üzüleyim deme  hiç, işlerin gidişine, Mesai gelir geçer,  tak canını  dişine, Bırak  işin  ucunu,  va...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahvede-randevun-var-hiciv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim Başımda', 'ellerim-basimda-kamber-bal-8kphb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerim başımda

Selamın başım üstüne

Sen orada ben burada

Hasretin gözümde

Ah çekip her gece

Adın dilimde hece

Gelirsin diye gizlice

Yerin yüreğim üstüne

Yıldızları  sayarak geceleri

Uçup giderler niceleri

Çağırdım onca hocaları

Günahın boynum üstüne

Ah dedim ahım oldun bir an

Çıkıp geldin beni yaralayan

Kabirde satır satır karalayan

Günahın da sevabın üstüne

Ellerim başım üstünde

Bastım kırk yaşım üstüne

Vurun Bal’ı kaşı üstüne

Musallada yatar döşü üstüne', 'Ellerim başımda Selamın başım üstüne Sen orada ben burada Hasretin gözümde Ah çekip her gece Adın dilimde hece Gelirsin diye gizlice Yerin y...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ellerim-basimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozledigim sevgi', 'ozledigim-sevgi-husamettin-guven-j0a0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'asik olup sevismak

medenice bulusmak

tatli dille konusmak

ozledigim sevgi

yalan filan olmasin

sakin kalp,ler kirilmasin

olumsuz bir ask olsun

ozledigim sevgi

gel deyince gelmeli

ilel ebet sevmeli

yalniz benim olmali

ozledigim sevgi', 'asik olup sevismak medenice bulusmak tatli dille konusmak ozledigim sevgi yalan filan olmasin sakin kalp,ler kirilmasin olumsuz bir ask olsu...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozledigim-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozlemisim be gulum', 'ozlemisim-be-gulum-husamettin-guven-7nq9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'pamuk elden tutmali

goz,gozede bakmali

dudaklardan opmeli

ozlemisim be gulum

doyasiya sarilmayi

gul tenini koklamayi

seviserek oksamayi

ozlemisim be gulum

islak islak opmeyi

gulsinede yatmayi

gunaydinla kalkmayi

ozlemisim be gulum', 'pamuk elden tutmali goz,gozede bakmali dudaklardan opmeli ozlemisim be gulum doyasiya sarilmayi gul tenini koklamayi seviserek oksamayi ozle...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemisim-be-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arap Şükrü''de Çilingir Sofrası', 'arap-sukru-de-cilingir-sofrasi-birsen-sahin-0ue2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arap Şükrü Sokağı''nda 

Küçük bir çilingir sofrası 

Masamda sen 

İçip içip bitirmek istiyorum 

Ne kadar içsem 

Şişe hep dolu 

Hiç birşeyin tadı yok 

Ne soframda şarabın 

Ne dinlediğim udun 

Ne zamandır hasretim ya sana 

İçmek istediğim hep sen... 

Tüketmek istediğim hep sen... 

23/07/2005', 'Arap Şükrü Sokağı''nda  Küçük bir çilingir sofrası  Masamda sen  İçip içip bitirmek istiyorum  Ne kadar içsem  Şişe hep dolu  Hiç birşeyin ta...', ARRAY['Türk Edebiyatı','Şiir','Birsen Şahin']::text[], 8.5, '{"poet":"Birsen Şahin","poet_slug":"birsen-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/arap-sukru-de-cilingir-sofrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlangıçlar', 'baslangiclar-onur-yilmaz-hs8q4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başlangıçlar güzeldir

Son gözükmez başlarken

Başlangıçlar güzeldir 

Çünkü herşeyin başı heveslidir

Başlangıçlar güzeldir

Çünkü hiçbirşeyi bitirmek için başlamazsın

Başlangıçlar güzeldir

Güzeldir ilk adımlar

Herşey yepyenidir başlangıçlarda

Geçmişin güzellikleri yoktur ama

Geçmişin yaraları da yokdur başlangıçlarda

Sıfır kilometredir herşeyin başı

Başlangıçlar güzeldir

Güzeldir birşeylere başlamak

Başlangıçlar sonsuzdur aslında

Çünkü son da bir başka başlangıcın ilk kapısıdır...

Başlangıçlar güzeldir

Güzeldir birşeylere başlamak! ! !', 'Başlangıçlar güzeldir Son gözükmez başlarken Başlangıçlar güzeldir  Çünkü herşeyin başı heveslidir Başlangıçlar güzeldir Çünkü hiçbirşeyi bi...', ARRAY['Türk Edebiyatı','Şiir','Onur Yilmaz']::text[], 8.5, '{"poet":"Onur Yilmaz","poet_slug":"onur-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baslangiclar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin', 'hos-geldin-onur-yilmaz-cghgs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki bir ilk belki de bir sonsun

İlkimsin çünkü ilk defası bir gelişin vardı hayatıma

Sonsun çünkü uçurumdan atlamadan önceki son umutsun

Sana demekten başka birşey kalmıyor hoşgeldin

Ve her sesini duyuşumdaki gibi yine bana hoşgeldin

Mısralarım uzuyor seni düşünerek yazıldıklarında

Bu aşk büyüyor her yalnız kalmalarımda

Hoş geldin ama gitme

Hoş geldin ama bitme

sss', 'Belki bir ilk belki de bir sonsun İlkimsin çünkü ilk defası bir gelişin vardı hayatıma Sonsun çünkü uçurumdan atlamadan önceki son umutsun S...', ARRAY['Türk Edebiyatı','Şiir','Onur Yilmaz']::text[], 8.5, '{"poet":"Onur Yilmaz","poet_slug":"onur-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hos-geldin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İşte Burada', 'ask-i-ste-burada-onur-yilmaz-gfyw5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk yanı başımda

Günler, aylar ve hatda yıllar sonra! 

Aşk işte burada

Bu odada, bu evde ve hatda bu çıkmaz sokaklarımda! 

Aşk bedenimde yaşamımda

Dudaklarımda, nefes alışlarımda ve hatda ruhumda! 

Aşkım Aşkısı Aşkına Aşık derken 

Aşk işte burada bu sözcüklerin arasında

Ve iki çift dudağın arasında...

sss', 'Aşk yanı başımda Günler, aylar ve hatda yıllar sonra!  Aşk işte burada Bu odada, bu evde ve hatda bu çıkmaz sokaklarımda!  Aşk bedenimde yaş...', ARRAY['Türk Edebiyatı','Şiir','Onur Yilmaz']::text[], 8.5, '{"poet":"Onur Yilmaz","poet_slug":"onur-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-iste-burada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Bitersek', 'bir-gun-bitersek-onur-yilmaz-uhrvn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün gelecek

Belki ayrı düşeceğim yanından

Doymamışken ve dahalarımız bitmemişken...

Gün gelecek

Bir insafsız çıkacağım

Belki terkeden olup seni uçrumlara atacağım...

Gün gelecek

Korktuğun başına gelecek

Belki ben, belki eller, belki de sen bitireceksin bu sevdayı! 

Günler geçsede

Ayrılıklar essede

Sende bir mısram ve bir hatıram varsa hala

Ve bakıyorsan doya doya

Emin ol ki aryılmalar yalandır

Mutluluklar her aşkda karşına çıkacaktır

Kalbin temiz için rahattır

Seni bekleyen yeni umut yolculukları var iken

Bil ki koyup da giden perişandır...

sss', 'Gün gelecek Belki ayrı düşeceğim yanından Doymamışken ve dahalarımız bitmemişken... Gün gelecek Bir insafsız çıkacağım Belki terkeden olup s...', ARRAY['Türk Edebiyatı','Şiir','Onur Yilmaz']::text[], 8.5, '{"poet":"Onur Yilmaz","poet_slug":"onur-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-gun-bitersek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdat Hocam yazar durur', 'mikdat-hocam-yazar-durur-muhammed-murad-uzun-cvrpp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mikdat Hocam yazar durur 

Ilham gelir cosar durur 

Rabbimiz yetenek vermis 

Kalbimizden bizi vurur

Mest ediyor siirleri

Çoktur ilham perileri

Hep on ikiden diziyor

Tam yerinde heceleri

Korkmuyor o hiç kimseden

Yaziyor taviz vermeden

Onun bütün siirleri

Bir hittir daha bitmeden

Hic durmadan gündüz gece

Yeni siir hece hece

Tuta bilene ask olsun

Cözmesi zor bir bilmece

Ask Sairi jest eyledi

Üstadini meth eyledi

Asik Mikdat Bal’a

Bunu hediye eyledi

8/08/2005', 'Mikdat Hocam yazar durur  Ilham gelir cosar durur  Rabbimiz yetenek vermis  Kalbimizden bizi vurur Mest ediyor siirleri Çoktur ilham periler...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Murad Uzun']::text[], 8.5, '{"poet":"Muhammed Murad Uzun","poet_slug":"muhammed-murad-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mikdat-hocam-yazar-durur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-yok dedi bana!', 'a-yok-dedi-bana-mikdat-bal-fsqhq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok dedi bana!

Çukura düşmüştü herifin biri

El verdim gel dedim yok dedi bana!

Üstüne bulaşmış çamuru kiri

Temizle sil dedim yok dedi bana!

Senin dediklerin kemane dedi

Şimdi moda böyle zamane dedi

Halimden memnunum sana ne dedi

Akıllı ol dedim yok dedi bana!

Ne söylersen söyle aklına girmez

Hayat benim diyor hiç taviz vermez

Pislik içindedir kendisi görmez

Bir çıkış bul dedim yok dedi bana!

Kendinde toplamış bütün şerleri

Onun yoldaşıdır kendi türleri

Gider arar bulur kötü yerleri

Evinde kal dedim yok dedi bana!

Hayatı boyunca pislikte yüzdü!

Kurtulsun diledim o beni üzdü

Üstüne düştükçe ağzını bozdu

Haddini bil dedim yok dedi bana!

Mikdadi bir daha merhaba demem

Çok gittim peşinden daha gidemem

Nasihat mı tövbe, artık edemem

Yakamı sal dedim yok dedi bana!

Şair Mikdat Bal', 'Yok dedi bana! Çukura düşmüştü herifin biri El verdim gel dedim yok dedi bana! Üstüne bulaşmış çamuru kiri Temizle sil dedim yok dedi bana! ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yanlis-anladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılan Kaç Kere Isırdı', 'yilan-kac-kere-isirdi-ekrem-sama-o7lfj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kandırmışlardı seni etrfındakiler,

Sen büyük bir lidersin, öne geç dediler.

Kandın çıkarcılara, da atladın hemen,

Uyarmıştım o zaman, hatırla seni ben.

Amerikayı dostum, sandın kandırıldın,

Bir yere gelmek için, yılana sarıldın.

Hep kandırdılar seni, ''gerçek dostuz'' diye,

Şimdi ne kaldı eski, gömlekten geriye.

Irak''ta destek verdin, sen tuttun sözünü,

Şimdi olanlara bak, bak da döv dizini.

Rektörler kandırdılar, dört veya beş kere,

Bak şimdi YÖK eliyle, serildiğin yere.

Avrupaya güvendin, Kıbrıs için ''evet''

Kandırılmışsın çıktı, ortaya nihayet.

Bir Fransızın telefon, sözlerine kandın,

Rum''u tanımam ama, imzalarım sandın.

Bir telefona nasıl, kandırıldın gördük.

Rumlara Kıbrıs''ta tek, devlet kozu verdik.

Şimdi ''üzgünüm'' dedin, yalancı Fransaya,

Hep kandırılılıyorsun, bıktık saya saya.

Kandırmışlardı seni, ''İkinci Özal''sın''

Bari bırak da her şey, bu şekilde kalsın.

Mümin aynı delikten, ısırılır bir kez,

Sözlerin şahıdır bu, başka söz gerekmez.

Onbeş yıl beraberce, çalıştık hatırla,

Seni ikaz etmiştik, inatla israrla.

O seni kandıranlar, Allah''ından bulsun,

İşi ehline bırak, şu ülke kurtulsun...

(İstanbul:07.08.2005)', 'Kandırmışlardı seni etrfındakiler, Sen büyük bir lidersin, öne geç dediler. Kandın çıkarcılara, da atladın hemen, Uyarmıştım o zaman, hatırl...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yilan-kac-kere-isirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takas', 'takas-gulseren-saritas-joael', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baktıkça sana 

Nasırım kadar acıyorum.

Eski ağaç yası gibi 

Yanılmalarım 

Kenelenmiş kökümde.

Ödeşme zamanı şimdi 

Bir darağacı yapmalıyım senden

Karanlığın kuytusunda

Üşümelisin ayaz vuran teninde.

Arzulara yataklık eden düşleride vermeliyim...

Anlık olmalı muhabbetin.

Leke gibi anıları asmalıyım sonra

Vicdanını ezmeli hırıltıları.

Mumdan yapraklar yeşertmelisin

Sonbaharda kışa karşı.

Ve bir çocuk sevinci beklemelisin

Mızıkçılık etmeden.

Dur! 

Besleme hemen korkuları

Oyun bitmedi aslında.

Kötürüm giyer siyahını

Takas ettim sadece

Anlayasın diye...

24/07/2005

Adana/ Kozan', 'Baktıkça sana  Nasırım kadar acıyorum. Eski ağaç yası gibi  Yanılmalarım  Kenelenmiş kökümde. Ödeşme zamanı şimdi  Bir darağacı yapmalıyım s...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Sarıtaş']::text[], 8.5, '{"poet":"Gülseren Sarıtaş","poet_slug":"gulseren-saritas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/takas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cik Kuş', 'cik-kus-akin-akca-5rurf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cik kuş, öt hoş

Sabahlarımız şenlensin

Gecelerimiz demlensin

Bundan, alabildiğine öt:

“Cik'', ''cik'', ''ciik! ''

Çok neşe arzulusun; 

Bir kez olunca,

Susuyorsun.', 'Cik kuş, öt hoş Sabahlarımız şenlensin Gecelerimiz demlensin Bundan, alabildiğine öt: “Cik'', ''cik'', ''ciik! '' Çok neşe arzulusun;  Bir kez ol...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cik-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sevgilim', 'sen-sevgilim-elazigli-mustafa-kaya-f8ihx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen,

göklerden yere inmiş

bir sevgi incisi.

sen,

ne zaman dua etsen

ve ne zaman seherlerde gezinsen

umutların..bakışların...gözyaşların

hepsi..evet hapsi göklere ulaşmakta

güzel kelimeler Allah a  yükselir

biliyor musun..? 

ve sevgi cennetine çeviren gülüşlerin

yağmur damlalarına benziyor

ve senin duanla

cennetler iner yeryüzüne

sen,

bende unutulan olmayacaksın

seni yüreğimde taşıyorum

gülüşlerini ekiyorum ruhuma

sen,

benim huzur köşemsin

her sabah içimde açan

kır çiçrğimsin.

                                                mustafa kaya / 08.08.2005

                                                istanbul', 'sen, göklerden yere inmiş bir sevgi incisi. sen, ne zaman dua etsen ve ne zaman seherlerde gezinsen umutların..bakışların...gözyaşların heps...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güven', 'guven-mehmet-bicik-tsalx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağladım gecelerce,

Gözyaşlarım oldu deniz…

Mutluyduk hâlimizce,

Niye ayrıldık böyle biz? ..

Ayrılmanın olmaz hayrı,

Kalamam kızımdan ayrı,

Yaşayamam bundan gayrı,

Güzel kızım Ahsen’siz…

Sarılmadı yaralar,

Bozuldu gitti aralar,

Kafamda cevapsız sorular,

Yürümez evlilik güvensiz…

5 Aralık 2001, Burhaniye', 'Ağladım gecelerce, Gözyaşlarım oldu deniz… Mutluyduk hâlimizce, Niye ayrıldık böyle biz? .. Ayrılmanın olmaz hayrı, Kalamam kızımdan ayrı, Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guven-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskandım', 'kiskandim-elazigli-mustafa-kaya-tz00h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kat kat altında göğün

sahil de akşamdı

gecenin bembeyaz dişleri arasında

kıskandım  gülüşlerini

yol bulup siyah gözlerine

güller açan sözlerine

ve iki beyaz güvercin kollarına ulaşamadım..

yıldız kaynıyordu gözlerin

sesin,

karanlığa düşen bir yıldız gibi.

saçlarını okşayan rüzgarı kıskandım

bir sevgi doğuyor içime

rüyalarımı süslüyor sıcak gülüşlerin

ve aynalarda saçlarını tarıyor

ellerim.. 

bunca ses ışık arasında

duyarsızım dünyaya

kıskançlığım var 

sahilde  bu akşam...', 'kat kat altında göğün sahil de akşamdı gecenin bembeyaz dişleri arasında kıskandım  gülüşlerini yol bulup siyah gözlerine güller açan sözler...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kiskandim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler', 'maniler-mehmet-isikoglu-di3jt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sohbetlerin haz dolu

Bakışların naz dolu

Açıkca görünüyor

Aşka imtiyaz yolu

İncinmişsin birinden

Yaralısın yerinden

Hiç boşuna saklama

İnliyorsun derinden

Derman kesik dizlerden

Aşk solursun gözlerden

İnkar etme güzelim

Sır okunur yüzlerden

Gülüş saçıyor neşe

Yüzler benzer güneşe

Hurma gibi dudaklar

Davet ediyor dişe', 'Sohbetlerin haz dolu Bakışların naz dolu Açıkca görünüyor Aşka imtiyaz yolu İncinmişsin birinden Yaralısın yerinden Hiç boşuna saklama İnliy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/maniler-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pisi Pisine Ölmek', 'pisi-pisine-olmek-ozan-ozel-pva6h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşama dalmak için 

derin bir soluk al

orada tutunmak için 

nefesini uzunca tut

unutkanlığına gelsin

ve pisi pisine öl

- meni istemem...', 'yaşama dalmak için  derin bir soluk al orada tutunmak için  nefesini uzunca tut unutkanlığına gelsin ve pisi pisine öl - meni istemem......', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pisi-pisine-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Gel Türk Milleti', 'kendine-gel-turk-milleti-ozan-ozel-r54mp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çıplak sokaklarda

çıplak gezen insanlar

''ten'' defilesinin mankenleri

ve ardında sıralanan sürü

böyle nereye gidiyorlar

veya nereden geliyorlar

hangi hanenin günahı

neyin bedeli bunlar...

titreyeceksen titre artık

kendine gel Türk milleti

özündeki cevheri keşfet

ve hep birlikte yürü, ileri...', 'çıplak sokaklarda çıplak gezen insanlar ''ten'' defilesinin mankenleri ve ardında sıralanan sürü böyle nereye gidiyorlar veya nereden geliyorl...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendine-gel-turk-milleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DoğaÇ 08.08.’05', 'dogac-08-08-05-akin-akca-xvt54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçindeki enerji yetmediğinde insana, nefret edilebiliyor ondan kolayca.

Mantıksal görünen yozlaştırılmışlıklar, akıl sınıfına sokulmak istendiklerinde.

Sanma ki bu çeşit mantık ustur, darağacın senin baş elçin olduğunda.

An be an kabarmayı bekleyen, duygular; an be an secde vurur 

Ötelenip duraksamayan bir sekteye inançsızlık adına; 

Sonraları hep olacak, Tanrı’nın savaş demek olmayan hadislerinde. 

Sevgi bir rutubettir, en tepede ısıl ışık belirir! 

Bundan, gene barış götürür; arkadaşlık da aşkta gebedir! 

08.08.’05', 'İçindeki enerji yetmediğinde insana, nefret edilebiliyor ondan kolayca. Mantıksal görünen yozlaştırılmışlıklar, akıl sınıfına sokulmak isten...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogac-08-08-05-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızı', 'coban-yildizi-gulsen-gonenc-i5wts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çoban yıldınızı seviyorum,

Çünkü o benden birşey BEKLEMİYOR diyor; 

Her gece çıkmasını,

Yolunu göstermesini BEKLEDİĞİNİ,

Ve çoban yıldızının bunu onun için yapmadığını

düşünmeden.

O da benim çoban yıldızım.

Bunu bilmiyor.', 'Çoban yıldınızı seviyorum, Çünkü o benden birşey BEKLEMİYOR diyor;  Her gece çıkmasını, Yolunu göstermesini BEKLEDİĞİNİ, Ve çoban yıldızının...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/coban-yildizi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak', 'hak-gulsen-gonenc-9iwuh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boşuna hak arama! 

Hak sende, haksızlık yerde.

Tüm haksızlıklara karşı koyabilirsin ama

Aşk''a gelince dur orada! 

Aşkta adalet olsa aşk olmazdı be güzelim.

Bunu da bilmiyorsun ya, aşkolsun sana!', 'Boşuna hak arama!  Hak sende, haksızlık yerde. Tüm haksızlıklara karşı koyabilirsin ama Aşk''a gelince dur orada!  Aşkta adalet olsa aşk olma...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmak Çocuk ve Yamyam Kazanı serüveni', 'parmak-cocuk-ve-yamyam-kazani-seruveni-akin-akca-u1ijw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşler parlıyordu, çünkü kütle bu evrene miras bırakılmıştı.

Sadece delice uçuşanlar vardı, her şey bir küvezdeykense.

Sıcak olması gerekliydi, evet ama hiç de öyle değildi.

Orda bir tür huzur bulunurdu hali hazır, hep ama değişik.

‘Aşk bu olmalı’ diye düşündüm, işte bu kadar karmaşık.

Ne sıcak, ne soğuk ya da hepsinden biraz; bir koca iletici soluk –

kütleli parçacıklar daha oluşmamışken,

ışık hızlı fotonlar vardı ancak; onlar da kuramsal, kütlesiz.

Demek çorba içerken bile, ışık kozmik yumruda, evvala, varmış:

İçen kimdi çorbayı esas onu bilmek gerek.

Çorba kasesinin içiydi burası, kendi eteklerine doğru; 

karıncanın gözünde insan, petek gözlerden bakışlı.

İnsan bu çağda zor anlar arıların yaptığı bal gibi emek sarf ettirici bir işi.

Bozonlar ve ki graviton menşei, çeker, büker; aşk olmalı.

*

Zıplayarak birden parmak çocuk kaseden; nerden bittiği belli olmayan,

yukarı bir ağaca tutundu onun dallarından tekine …

.

Üzerine yunulmuş tuz ve glikoz kristallerini ve ayıkladı 

üst başından, suyunu tarhana özünün.

Ağaç dallandı bıdaklandı; yukarı, seri serpildi! 

(Düşmemek için çırpındı, sağa sola savrulan parmak çocuk.)

Boyuna ve/ ama enine de büyüdü. 

Sarmaşık dünyayı kuşattı! 

(Yukarıda oluşum farklıydı.

Bütün o, radyo dalgaları frekansı harici tutulmuş 

spektrumunu uçuşkan bozonların tutmaya çalıştı.

Bunu başarsa, 

dünyayı kuşatan o sarmaşığın kovulmasına 

Gerek kalmaksızın, aşk yeryüzünde kalabilecek gibi bir şeydi.

-

Soluk=nefes

Bıdaklanma: gıdaklayan budaklanma gibi bi şey. Türetme oldu. Anlamsal yumuşatma için kullandım.

sevgiler', 'Güneşler parlıyordu, çünkü kütle bu evrene miras bırakılmıştı. Sadece delice uçuşanlar vardı, her şey bir küvezdeykense. Sıcak olması gerekl...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/parmak-cocuk-ve-yamyam-kazani-seruveni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak İmkansız', 'unutmak-i-mkansiz-mehmet-baki-erfidan-6yf7s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine Hatırladım seni gecenin ıssız karanlığında,

Sanki gece değil, karşımdasın güneşin aydınlığında.

Ne gecenin sessizliğinde, ne kuzeyden esen poyrazda,

Ne de düşünceye ket vurulan bu ortamda.

Unutmak imkansız hep yanımdasın, hep yanıbaşımda.

Düşündükçe ürperiyorum gecenin dört buçuğunda,

Zira senin yerine soğuk bir cisim yanıbaşımda,

Tuttuğum ellerin değil, ölüm makinesinin kabzesi,

Başın değil göğsümdeki, kana susayan silahın soğuk gövdesi,

Saçların değil okşadığım, O’nun demirden soğuk namlusu,

Senin değil burnuma gelen, onun barut kokusu,

Ve kolların değil boynumdaki, ahtapotun örülü askı kayışı.

12.08.1994', 'Yine Hatırladım seni gecenin ıssız karanlığında, Sanki gece değil, karşımdasın güneşin aydınlığında. Ne gecenin sessizliğinde, ne kuzeyden e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutmak-imkansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekten Sevebilmek', 'gercekten-sevebilmek-i-smail-demirci-58uee', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeminler olsun,Paylaşmayacağım artık hiç bir şeyi.Ve almıyacağım kimseden hiç bir şey.Zulum olmuştu paylaşmak artık benim için.Kendilerine ait olmayanları,nasıl da sahipleniyordu insanlar,Sonra da Güya bu paylaşımın ardında insanları sevmek yatıyordu. 

Hiç bir şey onların değildi,Durumları eve giren hırsızın Ev sahibinle evi paylaşma lütfuna benziyordu. 

Aramayacağım artık,çok küçükken terk ettiğim ailemi.Canım Annem kızma bana,asiyim hepsi bu kadar. 

Evlenmek mi? Artık değişti bu konudaki fikrim.Evlilik deyince,sahiplenme duygusunun bir insanla tatmin edilmesi geliyor aklıma. 

Artık ben hiç bir şeye sahip değilim.Ve hiçbir şey de sahiplenmesin beni istemiyorum.. 

Neydi aradığım bunca yıl? 

Gerçek,yalnızca gerçek. 

Okuduğum bir kitapta şöyle yazıyordu:''Gerçek aramakla bulunmaz,Ama her arayana verilir'' 

Ümitlenmiştim bu sözden,hayat bana çok sırrını öğretti yaşadığım yıllar boyunca,sevgi evet sevgi varoluşun tek sırrıydı. 

O günden sonra bir başka bakıyordum hayata. 

Boş ver be İsmail,''Güzelliğin güzel yüzünde güzelliği yaratan,Elbette o güzelliğe aşık olanı da yaratmıştır. 

Ve yaklaşık 5 Yıl sonra,20 yaşlarında hamfendi bir kız çıkar karşıma. 

_ Merhaba benim adım ismail, 

_memnun oldum Nuran ben, 

Taaa ilk tanışıklıktan beri aklımı kurcalayan tatlı bir soru oldu nuran,Ve düşünmeye başladım içimi yakan olaylardan sonra. 

Şaşırdım bir an,gerçeği arayan birisine Nuran gibi bir serabın gönderilmesi doğal gelmedi bana. 

Ben böyle düşünürken o zaten bende değildi.O da aşk arıyordu.Beni hiç sallamıyordu bile.Ama biliyordum,gözü yaşlı bir şekilde yazıklar olsun haykırışları ile yine gerçeği arayacaktı.Bunu o zaman adım gibi biliyordum.Doğmuştu içime işte. 

Akla hayale gelmeyen,bazı şeyler yaşanırken,ben sessiz bir şekilde dönmesini bekliyordum serabımın. 

Tarihi tam olarak hatırlamıyorum..E-postalarımı kontrol ederken,''Merhaba güzel insan,özledim seni bana ulaşır mısın'' cümlesinin yanına cep telefonuf numarasını sıkıştırmıştı. 

Ve aman Allahım,inanmıyorum! Bu cümle Nuran''nın imzasını taşıyordu. 

Ellerimi kaldırdım semaya,Yarabbi Sana hamd olsun dedim.. 

Ve biraz daha zaman geçmişti.Güllerim açıyordu Nuranda,bir tek dokunuş bilhe yetmişti hüzünlü güllerimin hüzünlerini dağıtmaya(ağlayacaklarından habersiz bir şekilde)

Ve şimdi özel olarak düşünmüyorum hiç bir insan üzerinde,Evet biliyorum çok garipleşeceğim 

Ve şimdi şu topluma bakar mısın? Gördüğün birçok insan ve sen maskelerimizle yaşıyoruz.Maskeli bir balo hem de..Zamana,kişilere ve olaylara göre değişen maskelerin kullanıldığı bir balo... 

Anlamlı gelmiyor bana yürekten sevmek artık.Ama yine de anlam veremediğim gibi yine de seviyorum. 

Artık insanlardan hiçbir şey almamayı yeğiliyorum.Buna rağmen her şeyimi vermeye razıyım onlara.Evet,insanların sevgisini de reddediyorum.Bu anın sahte sevgileri insanın kalbini yaralamak için seçilen en tehlikeli yol oldu artık.Doğru,insan sevilmeden yaşayamaz,ama aslında sanıldığının aksine sevilerek değil severek yaşar insan. 

Sevmek bir insanı kendi içinde hissetmendir,Sevilmek ise kendini bir insanın içinde hissetmen. 

Bak ne güzel söylemiş şair: 

''Donuk sevgiler çağındayız 

Sıcak sevgiler cehennemde yanıyor 

Sevgi... 

Yaşanmayacak kadar güzel, 

Farkedilmeyecek kadar sade 

Duyulmayacak kadar doğaldır. 

Biliyor musun Nuran,bir çoçuğa verileek en değerli besin şefkat ve cesarettir.Bunlar öyle hassas bir dengeye sahiptir ki,denge bozuldu mu işte sevmesini beceremeyen insanları görürsün karşında. 

Bu insanlar,küçücük bir dünya kurmak ister kendilerine.Güçsüzdür bu insanlar kolayca kırılırlar,Dünya çok acımasızdır böylelerine göre.Kendilerini sevecek birilerini ararlar hep,O kadar yoğunlaşırlar ki,bazen şiddetli bir arzuyla birine doğru akmak isterler.Cesurca sevemezler,cesareti öğrenememiştir bu insanlar. 

Öte yandan,cesur insanlar dünyayı bile devirebilirler,ama basit bir sevgi oyunuyla kolayca yıkılıverirler.Dünyayı titretecek cesareti taşıyan bu insanlar kalplerine dokunan bir parmakla diz üstü çöküverirler.Ve şu sözleri duyar gibi olursun onlardan: 

Dağ düştü üzerimize,Yıkılmadık ama,insan değdi tenimize,Acısı yaktı bizi. 

Cesaret onları o kadar sertleştirmiştir ki,Sevdikleri insanı kolları ile kalpleri arasında neredeyse öldürürler.Oysa bana şefkat de öğretilmedi sevgi de.İnsanların nefretinden sevgiyi,ihanetlerinden sadakati,korkularından cesareti öğrendim. 

Evet insanlar gerçekten bu kadar acımasız,Ve gerçekten seven insan çok az. 

Bırak sevgilerini,gülmeleri bile doğal değil onların,Senin için değil kendileri için severler,o kadar iyi o kadar güzel ve o kadar severler ki hayran kalmamak elde değil biliyor musun? 

Sevgi ve ihaneti sanatsal bir uyarlama ile o kadar güzel sahneye koyarlar ki,öleceğini bile bile seyredersin oyunu.Mükemmel bir katildir onlar.Seve seve öldürürler seni.Dudaklarından sevgi sözcükleri yükselir.Yapacağın tek şey:Gözlerini kapatıp sevgi atmosferi içinde sevgi sözcüklerinin sağanak yağmurları altında ölümünü beklemendir anlıyor musun? 

Evet,ben sevilmekten korkuyorum artık.Neden mi? Ben her insanı kalbime misafir edebilirim,sevebilirim yani.Kalbimden eminim çünkü.Sevdiğim insanı rahatsız edecek hiç bir şey yok kalbimde.Ama kimsenin kalbine girmek istemiyorum artık,Çünkü bilmiyorum nelerle karşılacağımı,bilmiyorum hangi tuzaklar bekliyor beni,Ve bilmiyorum Sen bunlardan haberdar mısın? 

Evet sevgili,bitir artık oyunu,Kendini tanı.Kaçma yalnızlıktan.Yalnız kalarak tanıyacaksın kendini.Bir düşünsene,doğarken de yalnızdın ölürken de yalnız olacaksın.O zaman yaşarken yalnız kalmaktan niye kaçıyorsun. 

Yalnızlıkta ne bulabilir insan sıkıntı ve boşluktan başka diye düşünüyor olabilirsin... 

Bak sevgili,Kendini gerçekten tanıyabilseydin,uzaydaki derinliklerden daha derin bir uzay olduğunu görebilirdin.Bizler ruhumuzu öldürüyor sonra da geçip başına ağıt yakıyoruz.Benliğinde ki zenginliği fark etseydin dünyada ikinci bir insan aramazdın biliyor musun? 

Anlamadın değil mi? 

Dünyada tek bir kişi var aslında,o bir tek kişinin içinde 5 milyar insan, 

Evet,benliğin bu kadar kalabalık,benliğin tüm varlığının merkezidir.Tüm acılar ve sevinçler yüreğindedir senin.Ölenleri yüreğine gömdüğün gibi,doğacak çoçuğun kalbi de senin için de atar.Hem acıyı hem hem sevinci yaşarsın iç içe yanyana.Hatta o kadar acı çekersin ki acılar acı olmaktan çıkar 

Çok karışık değil mi? Belki haklısın bu konuda.Bazı insanlar başlı başına bir paradokstur.Düşünceleri de öyle.İnsanlar çelişik düşünmeye alışık değiller bu yüzden anlaşılmıyoruz zaten.Ve şunu da unutma; 

Yüreğin ölmüş olabilir, 

Hiçbir yürek sevgiyle dirilmeyecek kadar ölmüş değildir.Yeter ki sev... 

İsmail Demirci (4 Ocak 2005)', 'Yeminler olsun,Paylaşmayacağım artık hiç bir şeyi.Ve almıyacağım kimseden hiç bir şey.Zulum olmuştu paylaşmak artık benim için.Kendilerine a...', ARRAY['Türk Edebiyatı','Şiir','İsmail Demirci']::text[], 8.5, '{"poet":"İsmail Demirci","poet_slug":"i-smail-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/gercekten-sevebilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-mehmet-baki-erfidan-erwu7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözler yetmez, şiirler perişan,

Mürekkep yetişmez, dünya dar bir mekan,

Seni anlatmaya gücüm yetmiyor,

O eşsiz sevgine tasvir bende hüsran.

Benim gündüzümsün, gündüzümde güneş,

Gecemsin, gecemde süreyya.

İlk ağlayışım sana, ilk nazım da,

İlk gülüşüm ve son ağlayışım da sana.

Uyanıp da uykumun en tatlı anında,

Sadece sensin benim rüyalarımda,

Bilmem biliyor musun, haberdar mısın,

Gözlerimden yaşlar düşüyor şimdi başucunda.

Eskiden ellerin anlımı silerdi,

Gözyaşımla dolan senin gözlerindi,

Şimdi bilmem sıra bende mi? 

Ana bak anlını silen benim ellerimdi.

Bilmem biliyor musun, hatırlar mısın? 

Ben yemek yemezken bana yalvarandın,

Doyurmak için peşimden koşan sen,

Hadi aç gözlerini bak elimde ekmek,

Ne olur aç gözlerini bir lokma ye elimden.

Hasta yatağımda inlerken benimle inleyen,

Başucumda uyumadan, sabahları sabırla bekleyen,

Pamuk ellerle gökyüzüne el açmış yalvaran sen,

Şimdi bilmem sıra bende mi? 

Ana bak elleri gökyüzüne açık olan şimdi ben.

Anasın sevdan çok büyük, yağsız bırakmadın beni,

Sırtında taşıdın yıllarca, tuz ekmedin yüreğime,

Şimdi bilmem sıra bende mi? 

Ana bak başucunda bekleyen,

Her zaman gönlünde minicik olan ben...', 'Sözler yetmez, şiirler perişan, Mürekkep yetişmez, dünya dar bir mekan, Seni anlatmaya gücüm yetmiyor, O eşsiz sevgine tasvir bende hüsran. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ana-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlat', 'evlat-ahmet-mansuroglu-zncpn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evlat güzel, evlat sevinçtir

Evlatsız dünya bir hiçtir

Evladın olur sevinirsin

Kucağındayken övünürsün

Olmayanın bir ahı var

Olanın bin bir...

Hastalanır üzülürsün

Ders çalışmaz  üzülürsün

Üzülürsün istediğin gibi olmadığına

Dünyanın hem tatlı hem acı meyvesi

Gerekir evladı olanın bilmesi

Sevinci az üzüntüsü bol

Üzülmek istersen dostum

Sende baba ol.

  7 - Agustos - 2005

 Antakya - Hatay', 'Evlat güzel, evlat sevinçtir Evlatsız dünya bir hiçtir Evladın olur sevinirsin Kucağındayken övünürsün Olmayanın bir ahı var Olanın bin bir....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradan Bir Anti-faşizm Lirizmi', 'siradan-bir-anti-fasizm-lirizmi-akin-akca-8bax8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce su çimden akıyor …

ve adam sunulan sıvıdan içiyor …

kar yağmıyor, bu kırağı fuzuli gibisinden...

yandaşlar dağdan aşağıya kayan,

kurtarmaya...

Ağzında sigara olması tesadüfi …

çünkü melodiyi arzuluyor …

Küçük çocuklara silah vermişler,

onlar akıl edemezler, yine de suçlular …

Ama kalbim kan ağlıyor, gözlerimse yaş …

Tepeden düşene bakıyor dağ yandaşları …

*

Rammstein’in ‘Ochne Dich’inden seslen bana; 

Anadolu’nun yılmayan Çanakkale’lerinden …

Sessizlik ölümdür,

ama durağan akıl sır ermezler 

saklar da kendi iç hislerini en ön belleklerinde.

Dağa çıkmakta olan adamdır 

ya kadındır, düşer; 

Gözlerinde doğrularak zaferler inanç müjdesini –

bakarak kanı çekilmiş ayaklara sessiz,

gerek kalmadı bu suskunlukta

devam etmeye 

suskun bir aşağı çadırda,

arzulayan yukarıda.

yalandır aslında! 

tedavi ediliyordu...

balık gözlerden indirilen

kutsal uğraşı ''çıkın''

inat ile balık gözbebekleri kıpırtısız ve olacak,

hareketle gelen yalan doğaçlamalara...

her kes değil,

ama amaçtan do gg ma:

Doğmak, iç''tir,

baş olan güzel bir şey 

yine de.

Ekilen emekler olmasa bu bir hiçbir şeydi; 

zirveye çıkacaksa

bile orda ölecektir.

Yolunu biliyor isem yönelmeli o yöne,

yoksa asla hiç.

doğaçlama

rammstein-oche dich şarkısı klibi üzerine

ilk şekil doğaçlama

anakarasal, tuhaf bir gelişim olduğunu kabul etmeliyim. her yerde insan yüreklerine yelken açılması taraftarıyım.', 'Önce su çimden akıyor … ve adam sunulan sıvıdan içiyor … kar yağmıyor, bu kırağı fuzuli gibisinden... yandaşlar dağdan aşağıya kayan, kurtar...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/siradan-bir-anti-fasizm-lirizmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kere...', 'bir-kere-sezen-coban-v6w2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kere sevdim seni

Bir kere öptüm dudaklarından

Bir kez gittin

Ve hiç dönmedin...

Bin kere öldüm, oysa ardından! 

İstanbul,08.08.2005', 'Bir kere sevdim seni Bir kere öptüm dudaklarından Bir kez gittin Ve hiç dönmedin... Bin kere öldüm, oysa ardından!  İstanbul,08.08.2005...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-kere-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar.', 'yillar-sedat-alkan-fb29t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Batan bir gemi gördüğün.

Yeni aşklar bana ağır.

Yalnız el salla meçhule.

Bir damla gözyaşın bana kahır.

Dalgalı saçların bir tek aklımda.

Zaman çaldı resmini tutamadım.

Aklımı yıllar aldı usulca.

Bir seni sevdiğimi unutamadım.

Gençliğim sensizlikte eridi, bitti.

Sen anlardın bir tek, kimse görmedi.

Yüzümdeki çizgiler her gün derinleşti.

Ben yandım aşkım, daha küllerim sönmedi.', 'Batan bir gemi gördüğün. Yeni aşklar bana ağır. Yalnız el salla meçhule. Bir damla gözyaşın bana kahır. Dalgalı saçların bir tek aklımda. Za...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yillar-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Aşkı.', 'yaz-aski-sedat-alkan-tcfbv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yıl bekledim geldim yaza.

Kumsal bana da bir güzel yaza.

Gönlüme göre, kalbime göre.

Çevirmez İnşallah yazımı kışa.

Kedi gibi sokul, bu yaz koynuma.

Çalan şarkılar hep sana bana.

Gece disko bar, gündüz kumsala.

Aşkımızı da unutma al yanına.

Yaz aşkı deyip atma kenara.

Kumsal anlatır bütün dünyaya.

Bir sene bekler gene gelirim.

Bir güzel bulurum, kalırsın kışa.', 'Bir yıl bekledim geldim yaza. Kumsal bana da bir güzel yaza. Gönlüme göre, kalbime göre. Çevirmez İnşallah yazımı kışa. Kedi gibi sokul, bu ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaz-aski-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk.', 'ask-sedat-alkan-d21nx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmez sanırsın, gülersin, coşarsın.

Yağmur sana ağlar, güneş sana doğar sanırsın.

Kendi masalını yazar, okusun.

Anlarsın bir gün, ellerin boş kalırsın.

Aşk maskesini bir kez takarsın.

İstemesen de, maziye salarsın.

Elin kolun bağlı, bomboş gözlerle.

Oturur ağlar, her gün yanarsın.

Ah Aşk..

Güzel bir düş kadar kısa.

Islanmış kedi kadar ürkek.

İnandıran tüm yalanlara.

Gökkuşağı kadar gerçek.', 'Bitmez sanırsın, gülersin, coşarsın. Yağmur sana ağlar, güneş sana doğar sanırsın. Kendi masalını yazar, okusun. Anlarsın bir gün, ellerin b...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-409-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Bende.', 'kalem-bende-sedat-alkan-vdfbd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbime sordum, bir daha sordum.

Bak şeytanda fısıldıyor usulca.

Hiç şansın yok, artık yoruldum.

Mecalim kalmadı kanmam yalana.

Ayrılmak mı daha zor.

Yoksa yeniden sevmek mi.

Işıkları sönmüş kalbimin, kapıları kitli.

Bu ölümden beter değil mi.

Ağlayan gözler, hüzünler bende.

Bakma titreyen yaşlı ellerime.

Aşkımıza rağmen, silerim bilirsin.

Gözyaşları da kalem de bende.', 'Kalbime sordum, bir daha sordum. Bak şeytanda fısıldıyor usulca. Hiç şansın yok, artık yoruldum. Mecalim kalmadı kanmam yalana. Ayrılmak mı ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalem-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne ala.', 'ne-ala-sedat-alkan-8pea8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanağında gamzesi, ölürüm ben.

Değil öpmek, değil sevmek.

Görsem ne ala. Göremiyorum.

Gözlerinin mavisi çalmış denize.

Değil bakmak, değil yanmak.

Benim olsa ne ala, diyemiyorum.

Benim olan bi virane, bi hasır.

Meyhanede bir kadehlik hatır.

Değil almak, değil sevmek.

Silsem ne ala, silemiyorum.

Haber salmış dostlarımdan.

İstemişler anasından.

Kaçıracam en babasından.

Param olsa ne ala, gidemiyorum.

Kader güler bana, her gece.

Ben de kadere.

Yarim gelin, yarın ele.

Ölsem ne ala, ölemiyorum.', 'Yanağında gamzesi, ölürüm ben. Değil öpmek, değil sevmek. Görsem ne ala. Göremiyorum. Gözlerinin mavisi çalmış denize. Değil bakmak, değil y...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-ala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evimize Gidelim', 'evimize-gidelim-cansever-eyuboglu-wm7ak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evimize Gidelim

                            “Beni bana gösterecek aynamdı, almışlar”

                                                  Behçet Necatigil’in anısına

Gözümde tüttüğünüz bir akşamüstü sezinledim

Yaz dönemi, hüzün kana karışmadan önce:

- anılar derin ve dar - 

Düşlerimi okşardı mine gözlü bir gece

Çocukluğun soy adı, - evimize gidelim.

Aşklar, şairlerin yazdığı, beslediği evlerin

Avlusunda dilsiz mercanların seviştiği

- kollar nasıl da uzar -

Çok eskiden seninle – bağışlayın yüreğimi

Boş bakışlardan daraldı, evimize gidelim.

Göğsünüzde nilüferler ürperir elimi sürsem

Elveda yuvasız anka, çiçeksiz bahçe, anısız şiir

- serin göğüslü mezar - 

Hangi hırkayı bürünsek ısınmaz gözlerimiz

Gündüzler mi kısaldı, evimize gidelim,

İlk evler, ilk evlilikler albümü, kırgınlıklar...

En çok kimi tükettikse, en çok kimi aradıksa

- dar çağlarda döndü zar -

Sırça gençliğimizin yabancı sınavlarda

Kırıldı kolu kanadı – evimize gidelim.

Maskeli balo bitti.. Arayan kim soran kim...

Çok eskiden sizinle buluşurduk törensiz

- sokakların gözü var - 

Her köşede muskalı – kamçılı töreleriniz

Acı, çiğ hurma tadı – evimize gidelim

Gözümde tüttüğünüz her akşamüstü aynı resim:

Sayfalarda ellerin, solgun bir güllü desen

-hasret ne vakte kadar –

Kapatırken kitapları metal çağ, beni sizden

Başka hiç anlayan olmadı – evimize gidelim.

UZAKTAKİ SEVGİLİDEN MEKTUP

Bunu siz mi istediniz, gam yükünü yele verdi yüreğim

Bahçenizden özenle ayırdım ayrık günlerimi

Sancılarınıza giyotin kesildim, dirildiniz

Beni unutmalarınıza bengisu verdim, güreldiniz

Ben mineli akşam yeli

Gel git zaman renk bezedim kara toprağınıza

Öpülmemiş kollarımda çarmıh hasreti

Belleğimde eski aşklarım, telörgülerim.

Dolunaylı düşlerimi sizden miras bildim

Yeni akıntılara kapıldım dudağımın tuzuyla

Titredim uçurum bakışınızdan eksildim

Kaktüsleriniz yüreğimi kanatmadan önce

Serap düşkünüydüm ben kendi ıs’sız çölümde

Ben mineli bahar seli

Şimdi ipince yaz yağmurundan incinirim.

Kırılgan heveslerim, kadim sırdaşlarım benim

Hâlâ göğüs kafesimde gizemli putlarınız

Şirin dertlerinize derman oldum, şimdi devran

Değişti, odalar gitgide dar, sokaklar rüzgâr

Ben mineli hüzzam dili

Akdeniz’le bir kırlangıç ömrü söyleşemedim.

Üzgünüm, sizi hoyrat bir yüzyılda yitirdim

Çözümsüz saç örgülerim tel tel paslanırken

Kendime kuşbakışı serin bir avlu seçtim

Ben mineli dünya gülü

Yarın nemli balkonumda demlenen hasretimle

Bekliyor sizi akşam çayıma karanfillerim.

Ruhumu hüzünlerle incitmeyin, zaman benim

Göğüm sizinle gölgesiz, güneşiniz kolay gelsin

Nice görüşmeyeli

Zamanı gözlerinizle aldattım, başım dönüyor

Bilirsiniz sizi anımsadığım tan vakitleri

Tepeden tırnağa yaprak ve çiçek kesilirim.', 'Evimize Gidelim                             “Beni bana gösterecek aynamdı, almışlar”                                                   Behçe...', ARRAY['Türk Edebiyatı','Şiir','Cansever Eyüboğlu']::text[], 8.5, '{"poet":"Cansever Eyüboğlu","poet_slug":"cansever-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/evimize-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçlerle Dans', 'hiclerle-dans-bahri-yildirim-hghvt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç bir zaman

Hiç bir  yerde

Hiç kimseyi

Hiç bu kadar özlememiştim.

Hiç bir şey

Hiç bir şeye,

Hiç bu kadar  güzel uymamıştı

Hiç bu kadar güzel yakışmamıştı

Kimse kimseye

Hiçliklerin içine düştük 

Farkına bile varmadan

Hiç yoktan hiçlerle çevrildi

Yaşantımızın serseri noktaları

Hiç korkum yok ama; 

Yarın neler getirir,bilinmez yinede

Bazen bir hiç uğruna

Neler kaybediyor insan.!', 'Hiç bir zaman Hiç bir  yerde Hiç kimseyi Hiç bu kadar özlememiştim. Hiç bir şey Hiç bir şeye, Hiç bu kadar  güzel uymamıştı Hiç bu kadar güz...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hiclerle-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-dilek-kalindemir-csp0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giden bir geminin

arkasından bakmak...

O''na el sallamak...

Ağlamak.. Ama anlamak...

Bir yaşam armağan almak...

Yaşamına yaşam katmak...

Yılmadan, inanarak...

(Ağustos 2005)', 'Giden bir geminin arkasından bakmak... O''na el sallamak... Ağlamak.. Ama anlamak... Bir yaşam armağan almak... Yaşamına yaşam katmak... Yılm...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kalındemir']::text[], 8.5, '{"poet":"Dilek Kalındemir","poet_slug":"dilek-kalindemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gemi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakarya’nın Anlattıkları', 'sakarya-nin-anlattiklari-hikmet-kucuk-dgt9k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Araba Eskişehir’den Polatlı’ya doğru, 

Ağır ağır ilerliyordu.

Sakarya, bir sağımda, bir solumda.

Kıvrım kıvrım.

Belli ki anlatacakları var.

Belli ki, bir sırdaş arar.

O anda birden, hava sislendi,

Toprak benzini attı,

Derin derin hislendi.

Zamanın dehlizleri yerinden oynadı…

Sakarya, rengi değişti,

Kızıl kızıl kaynadı.

Hangi kahpe namludan çıktığı bilinmez,

Bir şarapnel ıslık çaldı.

Kızgın kızgın geldi, 

Yeni açan güle benzer,

Bir yüreği deldi.

Yirmi birindeydi.

Gözünü, doyamadığı toprağa dikti; 

Vatanım! dedi.

Taze kınalı bir gelin, 

Avuçlarına sabır ekti; 

Yiğidim, balayında toprakla yatanım! dedi.

Bir ana,  gururu alnına çekti; 

Mehmet’im, helal sütüme helaller, katanım! dedi. 

Gökten bin melek indi.

Her biri, bir Mehmet’i almak için.

Her bini, bin Mehmet’le, 

Cennete dalmak için.

Peşlerinden bakakaldım.

Kıskanç, mahçup…

(Eskişehir 8/8/2005)', 'Araba Eskişehir’den Polatlı’ya doğru,  Ağır ağır ilerliyordu. Sakarya, bir sağımda, bir solumda. Kıvrım kıvrım. Belli ki anlatacakları var. ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sakarya-nin-anlattiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Uyandırmayın', 'sakin-uyandirmayin-bahtiyar-arslan-ir0ol', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bağır bağır

Ellerinde çalıntı misketleriyle

Yalın ayak

Geçer çocuklar yaralı yüreğimden,

Giderler anne düşlerine.

Dokunmayın.

Düştür bu

Sakın ha

Beni uyandırmayın...', 'Bağır bağır Ellerinde çalıntı misketleriyle Yalın ayak Geçer çocuklar yaralı yüreğimden, Giderler anne düşlerine. Dokunmayın. Düştür bu Sakı...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Arslan']::text[], 8.5, '{"poet":"Bahtiyar Arslan","poet_slug":"bahtiyar-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sakin-uyandirmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse -paradoks şiirimsi-', 'gulumse-paradoks-siirimsi-cumhur-boratav-to7xg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içimde 

bir yerimde benden 

gizlenen kırılganlığımı 

hissettiğinde 

kışkırıveriyor 

içindeki o hep hissetmek 

istediğin kendini büyükseme 

beni incitmek 

seni besliyor 

krılganlığımı hissetmen 

senin kırılganlığını saklıyor senden 

ve ağzının iki yana çekilmesiyle görünen 

dişlerinin anlamı: bir gülümseme 

bende gördüğün kırılgan 

sana ait 

gülümse', 'içimde  bir yerimde benden  gizlenen kırılganlığımı  hissettiğinde  kışkırıveriyor  içindeki o hep hissetmek  istediğin kendini büyükseme  b...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulumse-paradoks-siirimsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Böyle Birşey', 'ayrilik-boyle-birsey-bahri-yildirim-g91js', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ferman dinlemeyen 

Bir asi gönlüm var

O gönül ki:

Sana düştü

Umutlarım dağlardan yüce

Sevdalarım,coşkun ırmaklar misali

Kavuşmak ister yare

O da gitti göle düştü.

Uğruna ölümleri sevdim

Geçtiği yerleri kutsadım sanki

Kim bilecek dedim ama,

Nede çabuk dile düştü.

Bulut bulut özlemlerim

Yağmur olup gelmeni bekledim hep

Kurudum gözyaşlarının maviliklerinde

Bereketim  orda idi

O da gitti,çöle düştü.

Ateşler içinde yandı yüreklerimiz

Ateş düştüğü yeri yakarmış

O da geldi bize düştü.

Ayrılık acısı çok zormuş meğer

İkimize bile düştü.', 'Ferman dinlemeyen  Bir asi gönlüm var O gönül ki: Sana düştü Umutlarım dağlardan yüce Sevdalarım,coşkun ırmaklar misali Kavuşmak ister yare ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayrilik-boyle-birsey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-serhat-alagoz-7e6ke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerin ellerimi kovduğundan beri ilk kez dolu göründü gözüme,

Kalbinin heyecanı, gözlerinin ışıltısı ve gülüşün,

Sana verebildiğim herşey belli ki dönmüştü yerine...

Oysa O’nun,

Benden uzun boyu, çok ince kaşları vardı,

Ve çok yakışıklıydı,

Çok şükür,

Hepsi sadece rüyaydı...

(18-06-2005)', 'Ellerin ellerimi kovduğundan beri ilk kez dolu göründü gözüme, Kalbinin heyecanı, gözlerinin ışıltısı ve gülüşün, Sana verebildiğim herşey b...', ARRAY['Türk Edebiyatı','Şiir','Serhat Alagöz']::text[], 8.5, '{"poet":"Serhat Alagöz","poet_slug":"serhat-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruya-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babası', 'babasi-serhat-alagoz-j0fd7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elinde olsa sendeki karanlıkları alır eklerdi gecelerine,

O senin için,

Biraz daha uzun ağlar, 

Tükenen sabrından bir yudum daha harcardı...

Biliyordu içindeki ızdırabı,

Oysa zaman kum saatinden akan taneler gibi,

Bu acı yetmiyormuş gibi,

Ayrılık,

Yavaş yavaş kendini gösterir gibi,

Gözler gülmeyi unutmuş gibi,

Hakedilmeyenleri bir derin boşluğa kaykırıp,

Ürküten yankısını tek başına dinlemek gibi,

Acı veriyordu herşey,

En zor masum anında bebeğini yalnız koymak gibi...

Ve sonunda,

Her gece vardı bir sabaha,

Gülmeyi unutan gözlerin tek verebildiği gözyaşı olmuş,

Kalbe dolan bir his,

Adı çok önceden mutluluk konmuş...

Seveni de bunu unutmuş...

Belli ki yerini bulmuştu senin için edilen her bir dua,

Babası,

Hoşgeldin yuvana...', 'Elinde olsa sendeki karanlıkları alır eklerdi gecelerine, O senin için, Biraz daha uzun ağlar,  Tükenen sabrından bir yudum daha harcardı......', ARRAY['Türk Edebiyatı','Şiir','Serhat Alagöz']::text[], 8.5, '{"poet":"Serhat Alagöz","poet_slug":"serhat-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/babasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Aşık', 'i-ki-asik-serhat-alagoz-379al', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul’da iki aşık, mutlulukları güne sığmayan,

Şimdi biri mutlu, diğeri hep ağlayan...

Öyle büyük bir aşkın dağıydı o,

Etekleri Kız Kulesinin karşısına dayanan,

Süphesiz o iki eldi,

İlk heyecanı, eski bir koltuğun üzerinde yaşatan...

Sevginin denizini yaptılar, sekiz mevsim yağan yağmurdan,

Beraber korudular, yalancı gözlerin nazarından,

Şimdi biri boşaltmış, diğeri boğulmaya razı,

En küçüğüne bile kıyamadan, her damlasını toplayan...

Elinde olsa hergün bir yaprak koparır yakardı,

Kirli geçmişinin yazılı olduğu defterden,

Biri ne hissetmezdi ki,

Diğeri kendinden nefret ederken...

Kendilerini erişilmez sandılar,

Ayrılık belası sessiz sedasız yanaşırken,

Şimdi biri uyuyor,

Diğeri kalbi atan, buz tutmuş bir ölüyken...

İstanbul’da bir aşık, özlemi güne sığmayan,

Bir gözü iflas etmiş, diğeri hala ağlayan...

(08-08-2005)', 'İstanbul’da iki aşık, mutlulukları güne sığmayan, Şimdi biri mutlu, diğeri hep ağlayan... Öyle büyük bir aşkın dağıydı o, Etekleri Kız Kules...', ARRAY['Türk Edebiyatı','Şiir','Serhat Alagöz']::text[], 8.5, '{"poet":"Serhat Alagöz","poet_slug":"serhat-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iki-asik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil Kokar Sevgilinin Çayları', 'karanfil-kokar-sevgilinin-caylari-bahri-yildirim-dxl1r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç bir şeye benzemez,

Sevgilinin:

Saçları,

Dudakları,

Elleri,

Gözleri,

Yüreği,

Gülüşü,

Sevdası.

Hiç bir şeye değişilmez

Yüzündeki gülücük.

Dilinden dökülen birkaç sözcük

Onun gibi salınan yoktur

Bu yollarda

Hele saçlarını şöyle bir savurursa; 

Erir görenlerin yüreği.

O ki; 

Sevgilidir.

Candır.

Canandır.

Ölümün diğer adıdır yokluğu.

O ki sevgilidir.

Çok güzeldir.

Güzel yoktur onun üstüne

Çok özeldir her yaptığı

Her şeyi bir başka bahar gibidir

Heyecanlara salar insanı.

O ki sevgilidir.

Yüzümüzde goncadır.

Dudağımızda şarkı

Yüreğimizde bir ince sızı

Hele bir çay yaparki sevgilim 

Doyumsuzdur tıpkı kendisi gibi

Karanfil kokuludur çayları.

Kendisi gibi siner içimize

Vazgeçilmez olur.

Bu akşam geleceğim sana

Karanfil kokulu  bir çay demle bana

Gül kokulu sevgilim', 'Hiç bir şeye benzemez, Sevgilinin: Saçları, Dudakları, Elleri, Gözleri, Yüreği, Gülüşü, Sevdası. Hiç bir şeye değişilmez Yüzündeki gülücük. ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/karanfil-kokar-sevgilinin-caylari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömer Hayyam''a...', 'omer-hayyam-a-sezen-coban-3tvl0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Benim halimden haber sorarsan

  Bir çift sözüm var sana yürekten; 

   Sevginle gireceğim toprağa,

    Sevginle çıkacağım topraktan...'' 

                                                            Ömer Hayyam

Ömer Hayyam''a....

''Allah Bir''dir'' dedik

Doğrumuza doğru kattık

Yanlışımızdan eksilttik.

İçtik içtik şarabımızdan şiirler yazdık

Sonra ''anlamadılar''dedik, dert yandık

Doldurduk aşk soframızı,

Leylalarla, Mecnunlarla

Döndük baktık,içimize

Ne Leylayı bulduk, ne Mecnun olduk.

Vuslatı bekledik,sabahladık

Geceyi bitiremedik,gündüze kattık

Aylar geçti şaşırdık

Aradık canı cananı başucumuzda, bulamadık.

İçtik içtik şarabımızdan sarhoş olduk

En son ne yazdığımızı unuttuk...

İstanbul,08.08.2005', '''Benim halimden haber sorarsan   Bir çift sözüm var sana yürekten;     Sevginle gireceğim toprağa,     Sevginle çıkacağım topraktan...''     ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Çoban']::text[], 8.5, '{"poet":"Sezen Çoban","poet_slug":"sezen-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/omer-hayyam-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaren 3', 'yaren-3-fazli-coban-p6u4b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaren

       Yaşam cümlesinin ortasını geçeli çok zaman olmadı. Yolculuğum düşe kalka sürüyor. Noktanın konduğu yerdesin.

       Kavurucu sıcaklar günü yakarken senin sevdanla küle dönen  kanlarım hala akıyor. 

       Biliyor musun. Günler vagon misali ardı ardına geçip gidiyor.Güneş her sabah doğum sancısı çekiyor bende senin sancınla başlıyorum güne. Güneş doğunca öpüyorum alnından.

       Kuşlar alkışlarken doğan günü kaldırımlar suskunluğunu bozuyor. Uçsuz mavi gerinip yıkıyor yüzümü. 

       Karamsarım yaren hem de çok. Bu karamsarlığıma  adın yüreğimin en kuytu köşelerinde  ıpıl ıpıl yanan küçük bir yıldız gibi. 

       Seni büyüteceğim yüreğimin sevda tarlalarında. Tohumlar çatlayalı çok olmuş. Yaşam koşturmacasın da ben aldırmadın onlara . Bana öyle bir hatırlattın ki …

        Yaren göz yaşarımla beni kabul eder misin. Ağlamak istiyorum hem de çok.Öylesine ağlamak ki yüreğimi gözyaşlarımla yıkayıp sana sunmak istiyorum. 

         Bir oyun bu. Ben rolümü çok ciddiye almışım. Bir figüranım sonuçta. Niye başrol vermediler diye sızlanmak yerine çalışmam gerekirmiş  yaren. 

         Anlıyorum. Belleğim bana oyun oynasa da. O belleğin kıvrımlarındaki  güzelliklere varmak istiyorum. 

          İstiyorum yaren. Küçük bir çocuğun annesini ister gibi  seni  istiyorum. Bana çok görme bu isteğimi. 

          Gün içinde çok gerginim  yaren. Senden uzaklaşınca geriliyorum. Geriyor beni her şey. Ama şimdi anladım ki sen gün içinde de varsın. 

           Bana sevdanı ver başka bir şey istemiyorum.', 'Yaren        Yaşam cümlesinin ortasını geçeli çok zaman olmadı. Yolculuğum düşe kalka sürüyor. Noktanın konduğu yerdesin.        Kavurucu sı...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaren-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Esmer Boyalarla Yazar', 'gunes-esmer-boyalarla-yazar-ertugrul-sakar-2aqe9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yedi ağustos pazar

Güneş esmer boyalarla yazar

Toprak yarılır sıkıntıdan

Görünmez bir akıntıdan

Geç ekilmiş bir tohum

İnadından der yokum

Var olmak bir kavga aslında

Yaşamak denen direnç faslında

Yaprak yeşil fakat dertli

İnce bir çubuk biraz etli

Suyu kimse bulmadı ki

Sudur bize hayat sunan saki

Her an bir fidanla sohbet

Dikenle ayrık otu memleket

Yer elması, teselli sarısı

Kışa doğru çıkar gönül perisi

Çaresizlik yanmış bir gömlektir tende

Bir çapa kaçar kök bedende

Öğle ortası aptal ıslatan bir yağmur

Belki de bulutlar küsmüş ağlıyordur

Bu ağustos şiiri de böyle olsun güzelim

Şiirsel bir eylüle uzanıyorken elim

Yedi ağustos pazar olmasına pazar

Esmer olmuşum, güneş olmuşum ne yazar', 'Yedi ağustos pazar Güneş esmer boyalarla yazar Toprak yarılır sıkıntıdan Görünmez bir akıntıdan Geç ekilmiş bir tohum İnadından der yokum Va...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunes-esmer-boyalarla-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Günlerim', 'cocukluk-gunlerim-can-ceylan-5xwus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vesile oldu döndüm çocukluk günlerime; 

Canlandı anılarım baktıkça dünlerime.

Elinde file vardı babam çıktı önüme; 

Hasret taşkın sel oldu bakınca gözlerime.

Çocukluğum yürüyor karşı ki kaldırımdan; 

Tutup çekiyor beni donup kalmışlığımdan,

Usulca gülümsüyor yılların ötesinden,

Tek kelime etmeden bir tek soru sormadan.

Sürüklenip giderken yürüyorduk biz bize

Ordan burdan laflarken geldik mahallemize

Fotoğrafını çektim birkaç poz evimizin; 

Balkonda belirince güleç yüzü annemin.

Ne çok kızardı annem eve geç gelişime; 

Banyo vakti gelince ipe un serişime.

Müthiş keyif alırdım babamla boğuşurken; 

Kokusunda kalırdım sımsıkı sarılırken.

Rastlarım belki diye aşina birkaç isme; 

Hafızam gezinmekte apartmanın zilinde.

Sıyrıldım uzaklaştım gelecek kaygısından; 

Çocuklaştım girdikçe bu zaman tüneline.

O sokak köpeğini ne kadar da sevmiştim; 

Evden süt kıyma çalıp günlerce beslemiştim.

Bir kulübe yapmıştım taş karton ne buldumsa; 

Derme çatma da olsa sevinmiştim çocukça.

Doğan amcayı gördüm mahallede gezerken; 

Anne babamı sordu haldi hatırdı derken.

Anılar teker teker canlandı konuşurken; 

Babam öldü deyince dedi ki; ne de erken.

Uyandı hatıralar derin kış uykusundan; 

Üşüştü üzerime girdiğim her sokaktan. 

Ölü toprağı mı vardı bunca yıl üzerinde; 

Çıkmak ister gibiydi zamanın kıskacından.

Sanki köprü atmıştım bugünlerden dünlere; 

Gülümsedi anılar canlandıkça yüzüme.

Kışları sert geçerdi bu Kayseri şehrinin; 

Buz tutan caddelerde dondu kaldı geçmişim.', 'Vesile oldu döndüm çocukluk günlerime;  Canlandı anılarım baktıkça dünlerime. Elinde file vardı babam çıktı önüme;  Hasret taşkın sel oldu b...', ARRAY['Türk Edebiyatı','Şiir','Can Ceylan']::text[], 8.5, '{"poet":"Can Ceylan","poet_slug":"can-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cocukluk-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gözün Elâsı', 'gozun-el-si-cihan-kaya-2xugr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dert olur sevene, aşkın alâsı

Git gözün önünden, gözün elâsı

Dar etti dünyayı, hasret belası

Git gözün önünden, gözün elâsı

Gecenin bengini, kimse bilmiyor

Hiç durmaz yaşım da sevda silmiyor

Ümit kesilse de dert kesilmiyor

Git gözün önünden, gözün elâsı

Hayatta her şeyi, kendim başardım

Yar olmasa bir an, bendim aşardım

Düşünmesem onu, arşa taşardım

Git gözün önünden, gözün elâsı

Aşkım yaram oldu, gözün elâsı

Uykum haram oldu, gözün elâsı

Doktor param oldu, gözün elâsı

Git gözün önünden, gözün elâsı', 'Dert olur sevene, aşkın alâsı Git gözün önünden, gözün elâsı Dar etti dünyayı, hasret belası Git gözün önünden, gözün elâsı Gecenin bengini,...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozun-elasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevdan', 'senin-sevdan-derya-cantimur-jutg0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SENİN SEVDAN

İnce ince kar yağıyor 

Ruhumun derinliklerine

Üşüyorum

Güneşli baharlarda olmak isterken

Seninle fırtınalı kışlarda dolaşıyorum

Ha bugün ha yarın diner fırtına

Baharlarımın çiçekleri yeniden yeşerir belki

Diye beklerken

Gönlümün yelkenini

Hazan mevsiminin acı rüzgarına 

Emanet ediyorum

Üşüyorum, donuyorum elinin sıcaklığında

Bedenimden ötesine dokunamıyor elin

Gözlerin sadece gözlerime bakıyor

Ne bir ses var sevgiden dilinde ne bir nefes

Kupkuru

Dilinle söylediğin yüreğinle buluşmuyor

Bildiğin hep tiz sesten bir aşk

Sadece senin olan

Yalnızca sen olan

Tek başına yaşadığın bir aşk

İçinde olmak için çırpındığım

Ama asla o kapıyı açamadığım 

Aşkının kapısında kaldığım bir aşk

Sonra

İki kişilik kahkahaların 

Bir senin için olanı var

Sadece kendin için aralanmış dudakların

Gülmüyoruz

Gülüyorsun

İki kişilik bir yaşamın

Sadece sen olan kısmını yaşıyorsun benimle

Aşkın sevdan olmuyor

Gözlerin çoğaltmıyor sevgini içimde

Kendinle birlikte sevgimi eksiltiyorsun

Senin olmam için

Eziyor, kırıyor, parçalıyorsun

Aşklar çoğaltmak için yaşanır sanırdım hep

Devrin sevdaları mı

Senin sevdan mı bilmem

Benim gönlümdekine hiç benzemiyor...

                                  04.02.2003

                                 saat: 13.30-15.30', 'SENİN SEVDAN İnce ince kar yağıyor  Ruhumun derinliklerine Üşüyorum Güneşli baharlarda olmak isterken Seninle fırtınalı kışlarda dolaşıyorum...', ARRAY['Türk Edebiyatı','Şiir','Derya Cantimur']::text[], 8.5, '{"poet":"Derya Cantimur","poet_slug":"derya-cantimur","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/senin-sevdan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlmek İlmek...', 'i-lmek-i-lmek-i-brahim-ethem-bingul-nuiy6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkımı ipek halı gibi dokudum

İlmeklere yâr senin adını koydum

Her motifte ah senin kokunu duydum

Renklerin âhenginde seni soludum...

Nasıl nasıl kıyarım söyle aşkıma

Nakşettim sevgimle ben seni halıma

Serer miyim ben onu yerlere böyle

Ulaşılmazımda o, gönül tahtımda...

www.iebingül.com', 'Aşkımı ipek halı gibi dokudum İlmeklere yâr senin adını koydum Her motifte ah senin kokunu duydum Renklerin âhenginde seni soludum... Nasıl ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilmek-ilmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Hayat', 'hangi-hayat-selim-oz-4mvrx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu değil yaşamak istediğim

Sonu ayrılık değil bildiğim

Uçurum kenarında beklerim

Benzemez hiçbirşeye sevgim.

Seni yaşar seni bilirim

Nefesinle mevsimlere dönerim

Kokunu çiçeklere veririm

Ellerinle bir dünya çizerim.

Adı ayrı bilirim

Tadı tek seninim

Gecesi yok batan

Güneşi yok açan.', 'Bu değil yaşamak istediğim Sonu ayrılık değil bildiğim Uçurum kenarında beklerim Benzemez hiçbirşeye sevgim. Seni yaşar seni bilirim Nefesin...', ARRAY['Türk Edebiyatı','Şiir','Selim Öz']::text[], 8.5, '{"poet":"Selim Öz","poet_slug":"selim-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hangi-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin', 'ne-dersin-derya-cantimur-55xew', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'NE DERSİN 

Bu hasretin sonu gelir mi dersin

Gönül yaram deva bulur mu bir gün

Yollar uzarken dağların arasından

Yorgun kalbim çırpınsa sana varır mı dersin

Sabretmeye takatim kalmadı artık

Unuttu gözlerim gülümsemeyi

Senden aşk dilenen yabancı gibi

El açıp da sana gelsem mi dersin

Bak soluyor güller gönül bahçemde

Bir bahçıvan gelip derse mi dersin

Hasretinse ölüm; yanı başımda

Bu yaşama bir son versem mi dersin 

                                      17-18.11.1994', 'NE DERSİN  Bu hasretin sonu gelir mi dersin Gönül yaram deva bulur mu bir gün Yollar uzarken dağların arasından Yorgun kalbim çırpınsa sana ...', ARRAY['Türk Edebiyatı','Şiir','Derya Cantimur']::text[], 8.5, '{"poet":"Derya Cantimur","poet_slug":"derya-cantimur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-dersin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Namaz', 'son-namaz-sitki-gokmen-j00yk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu son cenaze namazı.

Saf tutun insanlar saf.

Hatta sıklaştırın iyice.

Bir an önce defnedelim,

İnsanlık denen medeniyetsizi.

Evrim geçirdik ya.

Önemsiz bundan sonra erdem,

Hoşgörü,

Yardımseverlik,

Dürüstlük,

Yalansız dünya.

Açıkgözlük neresinde insanlığın? 

Zaten nedir ki insanlık bu devirde? 

Evrimimiz tamam artık.

Düzen ve kurallar ayak bağı,

Dürüstlük dolambaç.

Reflekslerde yaşamayı öğrendik,

Yıkmayı düzeni,

Bozmayı adaleti,

Göz boyamayı bir kaç kuruş için.

Para önemli.

Dürüstlük kaç para eder bozdursan? 

Ne gerek var zaten bunlara? 

Son mertebesindeyiz evrimin.

Başladığımız yerde,

Hayvanlar aleminde.

Ankara 08 Ağustos 2005 11:55', 'Bu son cenaze namazı. Saf tutun insanlar saf. Hatta sıklaştırın iyice. Bir an önce defnedelim, İnsanlık denen medeniyetsizi. Evrim geçirdik ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/son-namaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülünecek En Güzel', 'gulunecek-en-guzel-derya-cantimur-vkvau', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülünecek  en  güzel  çağımızda

Ağlattı hayat biziİ

Boşver

Hüzün yakışmaz gözlerine bilirsin

Acıları dağıt yüreğinden

Sevdalara aç yelkenlerini

Sende biliyorsun ki

Engin sevda denizinde 

Dinebileceğin bir liman bulabilirsin', 'Gülünecek  en  güzel  çağımızda Ağlattı hayat biziİ Boşver Hüzün yakışmaz gözlerine bilirsin Acıları dağıt yüreğinden Sevdalara aç yelkenler...', ARRAY['Türk Edebiyatı','Şiir','Derya Cantimur']::text[], 8.5, '{"poet":"Derya Cantimur","poet_slug":"derya-cantimur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulunecek-en-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hidiv kasrı', 'hidiv-kasri-elazigli-mustafa-kaya-jfi02', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hikayelerini bilmediğim

innsanlarını tanımadığım bir köşkün

heybetli çağrısına koştum

karşıda istinye sırtları

bir sevgili bekler gibi

boğaza nazır cilvelerine karıştı duygularım

yüksekçe tavanına

iç içe şehirler sığmış

usta bir nakkaşın sevdası

işlemeli tahtalar

ve kimbilir hangi ihanetleri fısıldıyor.

hamura dönüşen mermer,

kah yükseliyor sütun sütun

kah omuzunda bir osmanlı paşasının

geçmişin rengini taşıyor

inatçı ve çetin bir güzellik karşısındayım

odalar...odalar

kapı kapı sayısızlar.

ve görmüş geçirmiş bir sarayı

yaşamak kadar güzeldi görmek.

ince bir hatıranın kollarında,

uzaklaşıyor insan,

bir başka dünyalara.

ve bir devrin haşmeti,

aklımı başımdan aldı 

hidiv  kasrı...

sayısız el ayak izleri

küçük bir havuza akıyor

bir su sesidir yankılanan

yine kimbilir hangi ihanetlerin

dertli akışıdır

veya kimbilir

hangi sevinçlerin coşkusudur...

                                                                10.07.2004

                                                                 mustafa kaya / istanbul', 'hikayelerini bilmediğim innsanlarını tanımadığım bir köşkün heybetli çağrısına koştum karşıda istinye sırtları bir sevgili bekler gibi boğaz...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hidiv-kasri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrilen Sene ve Gidişimden Kalanlar', 'devrilen-sene-ve-gidisimden-kalanlar-gulay-yildiz-w3g29', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşün; 

Kanatsız uçuşu, gecemin tükettiği

Merakım; 

Senle gidilenin sensizce duruşu.

Yılı devirmeye kalan bir iki gün,

Hasretin katsayısı kadar acı.

Sızlanan yolun vedasızlığı

Ağlaşan kumsalın dalgasızlığı gibi

bir feribot, bir ada ve bir kumsal

Artık anım...', 'Düşün;  Kanatsız uçuşu, gecemin tükettiği Merakım;  Senle gidilenin sensizce duruşu. Yılı devirmeye kalan bir iki gün, Hasretin katsayısı ka...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/devrilen-sene-ve-gidisimden-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihlamur Zamanı', 'ihlamur-zamani-firat-altunyurt-we0qp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şehrin sokakları

Adım adım İstanbuldur,

Karanlıkları kör afet,

Işıkları sevdaya

Uzanan yoldur.

Yürürken başım döner,

Dolar içim, dolar..

Sen dolarsın,

Arada bir yağmur yağar,

Tutar beni

Bu şehrin sevdaları

Ihlamur zamanıdır.

Etime işler buram buram

Arada bir rüzgar eser,

Sen kokar ortalık,

Tutar beni yine

Sevdalı başım,

Ah be felek,

Ihlamur zamanıdır..

22.06.2005 Çarşamba 19:45', 'Bu şehrin sokakları Adım adım İstanbuldur, Karanlıkları kör afet, Işıkları sevdaya Uzanan yoldur. Yürürken başım döner, Dolar içim, dolar.. ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Altunyurt']::text[], 8.5, '{"poet":"Fırat Altunyurt","poet_slug":"firat-altunyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ihlamur-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Desem', 'ne-desem-kadir-koc-ewcwa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüküm biraz ağır gelmişti kambur sırtıma,

Sevda dediğin azık ağırdı ama,

Doyurmazdı yokluğunda.

Saçların vardı bilirim,fesleğen kokardı,

Bir kalbin vardı yumak yumak,

En büyük dileğimdi içine yuva yapmak.

Ağır gelmişti bu sevda biraz,

Mesela dayanamazdım yokluğuna,

Ah ederdim melek,

iç çekerdim yıldız düşerdi göklerden,tane tane

Tasvirindi saydığım onca çiçek,deniz,derya,

Benzemiyordu hiç,gördüğüm en güzel melek sana,

Ve soruyordu evrenin en güzelleri,

Kim bu gözlerindeki? 

Bilmem ki Aşkım demek yeter mi?', 'Yüküm biraz ağır gelmişti kambur sırtıma, Sevda dediğin azık ağırdı ama, Doyurmazdı yokluğunda. Saçların vardı bilirim,fesleğen kokardı, Bir...', ARRAY['Türk Edebiyatı','Şiir','Kadir Koç']::text[], 8.5, '{"poet":"Kadir Koç","poet_slug":"kadir-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-desem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deli Rüzgar', 'bir-deli-ruzgar-selahattin-durna-ls78w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Deli Rüzgar

Bi deli rüzgâr gibiydi ölüm

Bi

Deli

Rüzgâr

Gibiydi

Ölüm

Pusuda…

Bi deli rüzgâr gibi indi ölüm

Dağlardan ovalara.

Arpalar başağını döktü.

Buğdaylar kurudu evinsiz.

Buruştu kaldı üzüm salkımları çardaklarda.

Dutları geyis vurdu.

Bi deli rüzgâr gibiydi ölüm.

Bi deli hamaz…

Bütün evlerin kapısını çaldı.

Bütün evlerin bacasını

Salladı tutup tutup.

Çocuklar koşamadı arkasından

Teneke bağlayamadı kuyruğuna.

Büyüklerin dili tutuldu.

Askere uğurlamış gibi,

Gurbete yollamış gibi,

Ya da gelin etmiş gibi değil; 

Bi deli rüzgâr gibiydi ölüm.

Bi deli yangın…

Yaladı geçti buğday ovalarını

Patozlar kurudu kaldı.

Bi deli rüzgâr gibiydi ölüm, bu yaz.

Dedeleri sakallarından vurdu,

Gelinleri saçlarından:

“Ölç hadi! 

 Üleş hadi! ”

                                      12 Temmuz 1998

                                           BUCAK', 'Bir Deli Rüzgar Bi deli rüzgâr gibiydi ölüm Bi Deli Rüzgâr Gibiydi Ölüm Pusuda… Bi deli rüzgâr gibi indi ölüm Dağlardan ovalara. Arpalar baş...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-deli-ruzgar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisi Gibi', 'eskisi-gibi-firat-altunyurt-7wmqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deniz çekmez beni artık, 

Kuşlarla kanat çırpamam 

Eskisi gibi,

Eskisi gibi gülemem 

Oynayan çocuklara..

Koşamam onlarla

Eskisi gibi..

Direnemem belki

Haksızlığa, başkaldıramam..

Ama severim hiç bıkmadan,

Daha yeni tutulmuşum da ağına,

Çırpınıyormuş gibi,

Seni bir tanem, 

Eskisi gibi...

04.07.2005 PAZARTESİ', 'Deniz çekmez beni artık,  Kuşlarla kanat çırpamam  Eskisi gibi, Eskisi gibi gülemem  Oynayan çocuklara.. Koşamam onlarla Eskisi gibi.. Diren...', ARRAY['Türk Edebiyatı','Şiir','Fırat Altunyurt']::text[], 8.5, '{"poet":"Fırat Altunyurt","poet_slug":"firat-altunyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eskisi-gibi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Uyur', 'yedi-uyur-selahattin-durna-m8qkb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yedi Uyur

Doğdum çaylar şirketten

Borcum muydu yaşamak

Ödedim taksit taksit

Ben öldüm kim yaşadı

Anamdı şol bir garip

Düşler kurdum karnında

Yırtıp çıktım kozamı

İpeğe duramadı

Babam bir Yakup Nebi

Yusuf’a ağladı da

Kuyularda kaldım ben

Yusuf’um diyemedi.

İyi meyveler gibi

Güzel çiçekler gibi

Usulca kuşlar gibi

Sevdalar ılıştırdım

Dalıma konamadı

Sevda bir geçmez para

Avcumda gözün yumar

Bir yazı iki tura

Çağını bulamadı

Dağ dağla öpüşürdü

Menekşe fırtınası

Gönlüm bir kısmetsiz kız

Güzelim evde kaldı.

İçimde yedi uyur

Uyur uyanamadı…

                                                        Ağustos 1998

                                                             BUCAK', 'Yedi Uyur Doğdum çaylar şirketten Borcum muydu yaşamak Ödedim taksit taksit Ben öldüm kim yaşadı Anamdı şol bir garip Düşler kurdum karnında...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yedi-uyur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneni Sev Çocuğum', 'anneni-sev-cocugum-selahattin-durna-zcpk1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anneni Sev Çocuğum

Anneni sev çocuğum

Sevmek ne ki? 

Sevgiyle bak gözlerine hep

Ellerini sevgiyle tut sıcacık

Sevgiyle konuş konuşurken

Susarken sevgiyle sus.

O olmasa

Bütün ekmekler bayatlar çocuğum

Bütün zeytinler çürür o olmasa

Peynirleri küf tutar.

Annelerin yüzü gülse

Şavkı sokaklara vurur

Işır yüzü çocukların.

Yaşamak

Çelik çomak…

Annelerin yüzü gülse

Evlerde gül bereketi

Perdeler daha beyaz.

                                                                 -1993-', 'Anneni Sev Çocuğum Anneni sev çocuğum Sevmek ne ki?  Sevgiyle bak gözlerine hep Ellerini sevgiyle tut sıcacık Sevgiyle konuş konuşurken Susa...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anneni-sev-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaban Yaşatırdı Beni', 'merhaban-yasatirdi-beni-selahattin-durna-1h9tr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaban Yaşatırdı Beni

Merhaban yaşatırdı beni.

Vay,çekilip gittiğin odaların tenhalığına! 

Diz kapaklarına çivi çaktı çocuklar-verem değildik.

Yalnızlık takım elbise gezer içimizde bazı

Alan gitti, alan gitti mevsimlerimizi hep; başparmaklarımızı hep.

Olur mu,bilyelerimiz vardı,unuttuk mu hani? 

Bakılıp geçilmez ki,bakılıp geçilmez ki

İzi kalır içimizde telgraf direklerinin bile.

En verdindi,boy verdindi bana

Yedi dinin âmentüsü sana gayretti.

Vay,çekilip gittiğin odaların tenhalığına

Merhaban yaşatırdı beni…

                                                                  KONYA-1982', 'Merhaban Yaşatırdı Beni Merhaban yaşatırdı beni. Vay,çekilip gittiğin odaların tenhalığına!  Diz kapaklarına çivi çaktı çocuklar-verem değil...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/merhaban-yasatirdi-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-selahattin-durna-fhkxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimlik

Sen git başı dumanlı bir dağ olmak varken

İsimsiz bir tümsek ol; 

Yüzü ko,bini ko,milyonu ko bu yanda,

Git bir bir’e tutsak ol.

Kısacık bir ömrün öznesi olmak varken

Git sen bir belirtisiz nesne,

Bir dolaylı tümleç ol.

Defteri mi tutulur bir yalanın a fani

Hiç olmazsa izin kalır

Bir küçücük imleç ol

Her insan bir dünyadır,sen ise cihana bedel

Mümkünse sen herkes ol.

Bir kez keser ölüm inan,yolumuzu yaşarken

Sen bin yaşa be çocuk

Akıllıysan bir kez öl…

                                                        Kasım 1999', 'Kimlik Sen git başı dumanlı bir dağ olmak varken İsimsiz bir tümsek ol;  Yüzü ko,bini ko,milyonu ko bu yanda, Git bir bir’e tutsak ol. Kısac...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kimlik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Devri Sevmeleri', 'tas-devri-sevmeleri-selahattin-durna-vibhd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Taş Devri Sevmeleri

Çırılçıplak bir dağdım ben

Sizi sevdiğimde

Daha ağaçlarım yoktu

Daha dallarım yoktu

Daha filizlerim yoktu

Ben sizi sevdiğimde

Sizi sevdiğimde ben

Daha şiirler yazılmamıştı

Aşk şarkılarının besteleri

Kotarılmamıştı daha

Ben sizi sevdiğimde

“Seni seviyorum”demek

İcad edilmemişti daha.

Sizi sevdiğimde ben

Daha alfabelerin

Eni boyu çizilmemişti

Nerde eskiden böyle A,böyle B,böyle C…

Daha tekerlek

İcad edilmemişti

Ben sizi sevdiğimde

Nerde böyle E5,E24…

Sizi sevdiğimde ben

Daha çatıları çatılmamıştı evlerin.

Sizi sevdiğimde ben

Daha tam oturmamıştı

Göğün mavisi,yaprağın yeşili…

Güneş menzilinde değil

Ay kararın bulmamıştı.

Sizi sevdiğimde ben

Gömleğimin yakası kirli,

Pantolonum ütüsüzdü.

Çoraplarımın burnu delik

Ön dişlerim çürüktü 

Ben sizi sevdiğimde.

Sizi sevdiğimde ben

Daha nehirlerin adı konmamıştı.

Ovalar sahipsiz…

Sizi sevdiğimde ben 

Develer tellal

Pireler berber idi.', 'Taş Devri Sevmeleri Çırılçıplak bir dağdım ben Sizi sevdiğimde Daha ağaçlarım yoktu Daha dallarım yoktu Daha filizlerim yoktu Ben sizi sevdi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/tas-devri-sevmeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinden Yanarım', 'hasretinden-yanarim-muhammet-faruk-koca-fzcxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretinden yanarım, 

Bakışları kurşun yârim, 

Arar dururum diyar diyar seni, 

Haralardasın derdinden ben deliyim, 

Hiç haberin yoktur senin, 

Hardasın bakışları kurşun yârim, 

Yüreğime bir hançerdi sapladın, 

Bakışlarında kaldı yüreğim, 

Hardasın bakışı kurşun yârim, 

Gideli bir hayli zaman oldu, 

Geri dönmez hayallerin, 

Kara bağda kalın bakışım, 

Hardasın? 

Söndüremez oldu şarkılar, 

Yüreğimin ateşini, 

Bir bakışınla yaktın yüreği mi 

Hasretinden kul oldu yandı, 

Beni böyle çaresizce koyan yar, 

Hardasın? 

Hardasın? Kara bağlı güzel hardasın? 

(07.08.2005)', 'Hasretinden yanarım,  Bakışları kurşun yârim,  Arar dururum diyar diyar seni,  Haralardasın derdinden ben deliyim,  Hiç haberin yoktur senin...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasretinden-yanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksız', 'asksiz-selahattin-durna-uohwx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşksız

Topraktan suyu ayır

Çaydan şekeri al

Yemekten tuzu esirge

Sütten kaymağı çal

Gibi öyle…

Gülden kokuyu damıt

Zeytinden yağı…

Arıdan çiçeği sakla

Bebeleri sütten kes

Kuzuları soğut anasından

Gibi öyle…

Tavşanı dağa küstür

Balığı sudan kıskan

Ağaçtan kuşları ayıkla

Kuşu kafeslere göm

Gibi öyle…', 'Aşksız Topraktan suyu ayır Çaydan şekeri al Yemekten tuzu esirge Sütten kaymağı çal Gibi öyle… Gülden kokuyu damıt Zeytinden yağı… Arıdan çi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asksiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Tükendi', 'soz-tukendi-suna-aras-pokyp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk yüzüne tükürülmüş 

Bir çift yalandır gözlerin.

Ben acıtan aşklara düşen bitiş iziyim

İçimde ki o üşüyen çocukla

Yok iplikler düşerim hayatla arasına

Sen ağla

Hey su taşkını gönül

Derler ki

Ağlamak her sevdaya 

Bir tuz tadı aslında.

Söz tükendi

Yüreğimde ayak izi

Ölü bir aşk heykelinin.

Seni gözlerinden sorguluyorum

Seni gurbet renginden

İyi bak

Bu aşkı deneyen uzaklıklara

Ne kalmış senden ona? 

Tunç acılar dikiyorum durmadan

Kalbimin çukuruna.', 'Aşk yüzüne tükürülmüş  Bir çift yalandır gözlerin. Ben acıtan aşklara düşen bitiş iziyim İçimde ki o üşüyen çocukla Yok iplikler düşerim hay...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soz-tukendi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyun Beni', 'duyun-beni-selahattin-durna-yff47', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyun Beni

Kırkbeş yaşındayım

Kırkbeş yıldır

Dünya denen 

Bu garip gezegende

Yapayalnız…

Gölgesinde Araplar korkuttuğum

Çocuk gönlümün

Sularını denize dökmeyen

İhtiyar kuyuları

Taş attığım

Kurbağalar ürküttüğüm bütün kuyular

Duyun beni

Hakkımı helal etmiyorum.

Bütün tanrıların dinleri

Bütün dinlerin tanrıları

Adem,İdris,Nuh,Hud,

Salih,İbrahim,Lut…

Peygamberler,evliyalar,veliler…

Marks,Engels,Lenin,Mao..,

Franko,Hitler,Mussoloni..,

Duyun beni

Hakkımı helal etmiyorum.

Minareler,fabrika bacaları,uzun kavaklar,

Elektrik direkleri,telefon direkleri,televizyon antenleri,

Dağ başlarında bağdaş kurmuş

Ardıç ölüleri…

Deve dikenleri,dikenli teller…

“Kısa çöp uzun çöpten hakkın alacak.”

Bütün uzun çöpler

Duyun beni

Hakkımı helal etmiyorum.

Üzüm gözlüydünüz,kömür gözlüydünüz,mühür gözlüydünüz; 

Zeytin zeytin bakardınız hani,

Kimi badem…

Saçınızın tellerine yıldızlar kondururdum.

Topuklarınızın ekseninde rüyalar döndürürdüm.

Yaddınız,yabandınız,uzaktınız.

Elma yanak,kiraz dudak,keman kaş…

Kurtlanmış divanlardan beyitler düşürürdüm.

Bir kerecik dönüp bakmadınız.

Bütün güzel kadınlar,

Duyun beni

Hakkımı helal etmiyorum.

Balabanlar,guguk kuşları,takkeli kuşlar; 

Yüreğimin en gurbet yerinde

Yuvalar kurardınız hani

Yatılı okulların

Hacı leylekleri…

Duyun beni

Hakkımı helal etmiyorum.

Bütün büyük kitaplar,

Kur’an,İncil,Tevrat,Zebur..,

Mein Kamf,Das Kapital,Nutuklar…

Felsefeler,öğretiler,sistemler,

Yazdınız,sevmedim sizi

Dizdiniz,sevmedim sizi

Hakkımı helal etmiyorum

Duyun beni.

Karadeniz,Marmara,Ege,Akdeniz,

Adriyatik,Hazar Denizi,Büyük Okyanus,

Bir benim bindiğim gemileri.

 Taşımadı sularınız

Bir benim yelkenime rüzgâr tutamadınız.

Sen Nehri,Tuna Nehri,Nil Nehri,Missisipi…

Aden Körfezi,Cebelitarık,Bering Boğazı,Ümit Burnu

Hakkımı helal etmiyorum

Duyun beni…

                                                            4 Ağustos 1999', 'Duyun Beni Kırkbeş yaşındayım Kırkbeş yıldır Dünya denen  Bu garip gezegende Yapayalnız… Gölgesinde Araplar korkuttuğum Çocuk gönlümün Sular...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/duyun-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şile', 'sile-miyaser-gulsen-shj8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şirin kasaba o, İstanbul''un incisi

Yemyeşil zümrüt gibi bağı bahçesi ile

Koyları başka güzel sanki cennetten köşe

Görenleri kendine hayran ediyor Şile

Hangi köyünü desem hepsi de irembağı

Ağva deresi akıp giderken lüle lüle

Kumsala yayılıyor çılgın gibi dalgalar

Karadeniz''e kucak açmış gel diyor Şile

Bez dokuyan güzelim kızları gelinleri

Benzetirim her zaman yediveren al güle

Kar gibi yemeniler, siyah yeldirmeleri

Kendine has giyimli İstanbul''da tek Şile

Ağva''ya hiç gitmeden Şile''yi görmek olmaz

Ağlayan kayası var bir kere düşmüş dile

Fındık bahçelerinde keyifle fındık topla

Tanrı''dan her nimeti hak etmiş güzel Şile

Balıkçı motorları denizde kısmet arar

Martılar kanatlanır yol alırlar meçhule

Güneşi hayat verir solgun mahzun yüzlere

Hem tatil hem şifadır herkese güzel Şile

Doğasını korumak hepimizin görevi

Bir başka Şile''miz yok yanmayalım nafile

Yürekli insanları sevecen muhabbetli

Bizim eve de ''Gelin'' gönderdi Ağva-Şile.', 'Bir şirin kasaba o, İstanbul''un incisi Yemyeşil zümrüt gibi bağı bahçesi ile Koyları başka güzel sanki cennetten köşe Görenleri kendine hayr...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleket Hasreti', 'memleket-hasreti-necla-i-lhan-9oa4l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah hasret! 

İçin için ağlatır,ağladıkça kanatır

kor gibi yakar yüreği,

hoyrattır, dağdan esen azgın mı azgın yeli

ovaları var doyuran,ana gibi.bereketli

çatlayan toprağına yetişir

yağmurunun açık eli.

Dağında bayırında çalışan insanı

elleri nasırlı kadını,erkeği,kızı,kızanı

sofrasında bir tas çorbası,bir baş soğanı.

Ya ağlayan,

ezilen kadınlar,analar,bacılar

gözleri hep nemli.

Yiğittir evlatları anaların

can''dır,yar''dır,sevgisi sonsuz.

Memleketim,ahh memleketim! 

İnsanı,havası,dağı,taşı,herşeyi benim.', 'Ah hasret!  İçin için ağlatır,ağladıkça kanatır kor gibi yakar yüreği, hoyrattır, dağdan esen azgın mı azgın yeli ovaları var doyuran,ana gi...', ARRAY['Türk Edebiyatı','Şiir','Necla İlhan']::text[], 8.5, '{"poet":"Necla İlhan","poet_slug":"necla-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/memleket-hasreti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bende Kaldın', 'bir-bende-kaldin-muhammet-faruk-koca-332wa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde bir yalnızlığın kaldı, 

Öylece gittin, 

Yalnız şehirler var şimdi ardında bıraktığın, 

Gözümde yaşlarla bırakıp kaçtın hiç arkana 

Bakmadan, 

Şimdi şiirlerde ararım seni nerdesin? 

Bir bakışınla dünyalar yakan yârim nerdesin? 

Uçurumlar var şimdi içimde, 

Her dem sen dolusun, 

Yoksun anlıyor musun yoksun, 

Bakışlarımda kalan yârim yoksun, 

Geceleri ansızın içim kararır, 

Sen yoksundur, 

Duvarlar gelir üzerime, 

Yıldırımlar çakar beynimin en olmaz yerinde, 

Seni düşler seni ister ama yoksun, 

Yoksun işte yoksun. 

(07.08.2005)', 'İçimde bir yalnızlığın kaldı,  Öylece gittin,  Yalnız şehirler var şimdi ardında bıraktığın,  Gözümde yaşlarla bırakıp kaçtın hiç arkana  Ba...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-bende-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim Babacığım', 'melegim-babacigim-miyaser-gulsen-2o3di', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşeyimdin canımdın

Damarımda kanımdın

Sanki benim yarımdın

Sevgili Babacığım

Benim öğretmenimdin

Doğruluğu gösterdin

Kılavuzdun rehberdin

Sevgili Babacığım

Postacıyı gözlerdik

Mektubunu beklerdik

Mahzun boyun bükerdik

Gelmezse Babacığım

Gurbette arkadaştık

Neler neler paylaştık

Güzel günler yaşadık

Seninle Babacığım

Bende emeğin fazla

Severdin binbir nazla

İçim yanıyor közle

Yoksun ya Babacığım

Sensiz hayat gülmüyor

Yerin boş hiç dolmuyor

Gider geri gelmiyor

Anladım Babacığım

Bir kere kalp kırmadın

Bir kötü söz duymadım

Ben sana hiç doymadım

Doymadım Babacığım

Mekanın Cennet olsun

Her yanın nurla dolsun

Sevaplarım senin olsun

MELEĞİM  BABACIĞIM', 'Herşeyimdin canımdın Damarımda kanımdın Sanki benim yarımdın Sevgili Babacığım Benim öğretmenimdin Doğruluğu gösterdin Kılavuzdun rehberdin ...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/melegim-babacigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya', 'yalan-dunya-i-lknur-er-0vin9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Azrail geldi hadi kalk diyor

Ömür ne vakit bitti aklım almıyor

İtiyorum kakıyorum malım gelmiyor

Öte dünyaya tek başına gitmekte varmış

Üç gün daha dursam yalan dünyada

İyi bir insan olsam, ibadet yapsam

Malımı mülkümü satıp savursam

İmanımı koynuma alıp sarılsam

Ey gidi koca dünya almadın beni

Azraili görünce satıverdin gitti

Sana olan sevgimde şu anda bitti

Anladımki yarar değil hep zararmışsın

İmtihan dediler sınava çalışmadım hiç

İbadet dediler aldırmadım hiç

Göçecekmişim gibi gelmemişti hiç

Dünyada kazığı çakarım sandım

Ömürü bitirmişim yalan dolanla

Şimdi sıra geldi ahir zamana

Mallarım,mülklerim etmiyor para

Azrail beni bırak alma koynuna

Sizlere ibret olsun benim bu ahım

Sakın sizlerde yalan dünyaya kanmayın

El açın ALLAH a dualar yakın

Yalan dünyaya aldanıp sizde yanmayın.', 'Azrail geldi hadi kalk diyor Ömür ne vakit bitti aklım almıyor İtiyorum kakıyorum malım gelmiyor Öte dünyaya tek başına gitmekte varmış Üç g...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalan-dunya-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayana', 'anlayana-gulcin-aksekili-ybhci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanlara Allah öyle bir zeka vermiş ki

Ne tiyatrolar oynanır sabah akşam

Yalnızken bana bana yerken ekmeklerini

Tiyatroda serçe parmak havada

Bir edeyla yudumlarlar kadehlerini

Kabayken sevdiklerine

Bir ilah bir asilzade kesilirler

Ahmaklarla yok etmeye çalışırlar komplekslerini

Gören bak be ne büyük insan der

Hayran hayran ağzı kocaman açık seyreder

Kimseyi yüceltmemek lazım hayatta

Kimse senden üstün değil ki

Kimsenin çamurunda altın yok ki

Kimi anlatır kendini abarta abarta

Menfaati olan anlatır seni koltuklarını kabarta kabarta

Bundan başka dünya yok ki herkes bir

Ne o senden üstün ne o senden üstün

Herkes aynı limondan sıkılma

Ne tiyatrolar oynanır sabah akşam

Kimi sapa yollalardan çıkar sabaha

Kiminin mavi beyaz farlar aydınlatır yollarını

Herkes ağlar bir dertlinin feryadında

Sonra oh der bu benim başıma gelmese

Eskisinden de sevinçli uyanır yeni güne

Bu şükür onu üç gün idare eder

Kimi övünür okuduğu okullarla

Kimi övünür kazandığı paralarla

Kimi yarışır kendi hariç tüm dünyayla

İnsanlara kendini tanıt derler

Başlar anlatmaya

Hiç kimse ruhunu anlatmaz

Herkes giydiği gömlekleri anlatır hayat yarışında

Herkes başarılarını anlatır

Kendilerinde memnun olmadığı bir şeylerin üstünü kapatarak

Kocaman purolarını içerler

Etiketlerinden kendilerine dost seçerler

Hiç kimse üzerine alınmasın

Bu kimseyi kırmasın

Anlayana.............', 'İnsanlara Allah öyle bir zeka vermiş ki Ne tiyatrolar oynanır sabah akşam Yalnızken bana bana yerken ekmeklerini Tiyatroda serçe parmak hava...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Aksekili']::text[], 8.5, '{"poet":"Gülçin Aksekili","poet_slug":"gulcin-aksekili","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/anlayana-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlü Sevgili', 'gul-yuzlu-sevgili-mustafa-ayik-en8zm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir buğulu bakış bekler beni 

Bir de yarin gül benzi

Sevda türküleri söyler yüreğim

Yer gök sevgi denizi

Hayat ışıltıları saçılırken kara gözlerden

Ilık bir rüzgar eser efil efil

Bir Eylül akşamında yazın son sıcağı

Kavururken dudaklarımı 

Seni görürüm evimin penceresinde

Gülen gözlerle karşılarken beni

Tutuverir sımsıcak elleri

Ve bir buse kondurur dudağıma 

Kor düşer  özüme

Unutulmaz 

Sevgiyle yaşanırsa günler

Özlem dolu yürekle beklenir sevgililer

Her gün aşımında yeni bir heyecan 

Yeni bir aşk başlangıcı sarar beni

Her günü ayrı yaşarım seninle 

Ey gül yüzlü sevgili

18.09.2001 

Mustafa AYIK', 'Bir buğulu bakış bekler beni  Bir de yarin gül benzi Sevda türküleri söyler yüreğim Yer gök sevgi denizi Hayat ışıltıları saçılırken kara gö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gul-yuzlu-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hannane Direği', 'hannane-diregi-mehmet-nuri-gezmis-4hspt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mescid-i Nebi denince aklıma,

Gelir Hannane direği.

Resûl ondan ayyrılınca,

Neyledi Hannane direği? 

Yeni minber yapılınca,

Çıktı Resûl hutbe için.

Dayanamaz bu ayrılışa,

İnledi Hannane direği.

Bir direk nasıl da inler,

Bütün ashap bunu dinler.

Resûl kucaklar da diner,

Susar Hannane direği.

Anlayanlar alır çok ders,

Muslümanım diyen herkes.

Olmaz olsun onsuz nefes,

İnlerken Hannane direği.

Bir direk kadar olamazsan,

Ona tabi de olmazsan,

O gönlünde yaşamazsan,

İbret Hannane direği.

Anılır yanında duymazsın,

Sünnetine de uymazsın.

Sen nasıl bir müslümansın? 

Ağlarken Hannane direği.', 'Mescid-i Nebi denince aklıma, Gelir Hannane direği. Resûl ondan ayyrılınca, Neyledi Hannane direği?  Yeni minber yapılınca, Çıktı Resûl hutb...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Gezmiş']::text[], 8.5, '{"poet":"Mehmet Nuri Gezmiş","poet_slug":"mehmet-nuri-gezmis","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hannane-diregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan İnsanlığımızdı Aslında', 'unutulan-i-nsanligimizdi-aslinda-mustafa-ayik-bjxz0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşin ışığı, toprağın nemi

Otlardaki yeşillik, denizin mavisi

Dağlarda ılgın, yamaçta bir kuzu sesi

Çiçekler renk cümbüşü

Başını kaldırıp baktın mı dağlara

Akan derenin cılız şırıltısını dinledin mi

Çektin mi ciğerlerine kadar oksijen dolu havayı

Bak ne kadar cömert tabiat

Hep ayıplarımızı örttü

Canla başla çalıştı bizi doyurmaya

Çorak dedik hor gördük

Emek verip ter katmadık

Şu dağlara kazma vurup tohum atmadık

Çıplak kel bıraktık 

Sonra oturup suçlu aradık

Dönüp bakmadık iğreti talancı halimize

Biz çok çam devirdik ormanımız olmasa da

Beğenmediğimiz bir karış çorak toprak için 

Bir ormanı yaktık

Bir izmarite feda ettik insanlığımızı

Piknikte unuttuk ateşi

Unutulan insanlığımızdı aslında

Yaşayalım diye yaşamayı unuttuk

Canavarlaşan benliğimizi tatmin için 

Geleceğimizi unuttuk

Tembelliğimizi, vurdumduymazlığımızı

Ve aymazlığımızı unutup çorak topraklar diye kendimizi avuttuk

Ama aldanan biz olduk. 

18.09.2001 

Mustafa AYIK', 'Güneşin ışığı, toprağın nemi Otlardaki yeşillik, denizin mavisi Dağlarda ılgın, yamaçta bir kuzu sesi Çiçekler renk cümbüşü Başını kaldırıp ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/unutulan-insanligimizdi-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-mustafa-ayik-3cpap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba ey güzel gün, 

Merhaba doğaya düşen ışık

Bir kıpırtı yükselirken içimde

Ben ise hayata barışık

Bukle bukle siyah saçların 

Kömür karası kaşların

Ömre bedel bakışların

Sana ne de güzel yakışık

Tomurcukta çiy damlası

Gözlerimde ışıltı

Başımda sevda yeli 

Sevincim sellere karışık

Ayşe’mde işve naz

Elbet güzel nazlanır biraz

Bağırasım gelir avaz avaz

Sevdalı gönlüm sana aşık

Mustafa AYIK

15.10.2001 S 9:35', 'Merhaba ey güzel gün,  Merhaba doğaya düşen ışık Bir kıpırtı yükselirken içimde Ben ise hayata barışık Bukle bukle siyah saçların  Kömür kar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/merhaba-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Benzini Kattı Toprağa', 'gul-benzini-katti-topraga-mustafa-ayik-aeqls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir fidan düştü toprağa

Candan öte can verdi

Kök saldı tomurcuğa durdu

Vatan diye kan verdi

Tohum olarak düştü toprağa

Gün geldi bin fidan verdi

Bir ülküye sevdalandı

Yeşersin diye can verdi

Gül benzini kattı toprağa

Karanlık gecede tan verdi

Sevdalarını gömdü toprağa 

Bize bir güzel vatan verdi

Bu vatan bir ulu çınar

Her karışında şehit kanı var

Her gün yeni bir gün doğar

Doğan güne can verdi

Yıkılsın gönüllerdeki duvar

Gölgesinde hepimize yer var

Bu ulus ulu bir çınar

Tarihe şan verdi.

17.01.2000 S. 21.50', 'Bir fidan düştü toprağa Candan öte can verdi Kök saldı tomurcuğa durdu Vatan diye kan verdi Tohum olarak düştü toprağa Gün geldi bin fidan v...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gul-benzini-katti-topraga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-mustafa-ayik-osxw8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahçede gül açmış kokusunu yele verir

Aşka gelmiş bülbül avazını güle verir

Yardan özge düşen sevdasını dile verir

Çırpınır yüreğim dilim söylemez neyleyim

Bülbül feryat figan güle aşkını okur

Sevgilim çileli aşkını kilime dokur

Bir sevgi pınarı  gönlüme sığmaz akar

Çırpınır yüreğim dilim söylemez neyleyim

Gönlümdeki zincirleri kırasım gelir

Sevda dolu gözlerine dalasım gelir

Yarim ince bellerini sarasım gelir

Çırpınır yüreğim dilim söylemez neyleyim

04.12.1998	S. 01.08', 'Bahçede gül açmış kokusunu yele verir Aşka gelmiş bülbül avazını güle verir Yardan özge düşen sevdasını dile verir Çırpınır yüreğim dilim sö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neyleyim-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla yüreğim....', 'agla-yuregim-ayfer-yildiz-wxdti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağla yüreğim...

Ağla geçen yıllara,

Ağla tükenen yalancı sevdalara,

Yalnızlığının hapsettiği odanda,

Ömrünün baharında 

Yüreğini donduran kara kışa ağla...

Koynunda beslediğin dost yüzlü yılanlara,

Hazan gülleri gibi solan hayatına,

Seni senden eden vefasızlara,

Ve hepsinin sonunda 

Yaşanmamış gençliğine de ağla...

Yüzündeki çizgiler hangi acının izi,

Saçındaki beyazlar kavuşamadığın yarınların resmi,

Yaşadın ya sonunda geceden kara aşk ihaneti,

Utanma be yüreğim budur inan hayatın gerçek rengi.

Yüreklere sevgi ekmediysen eğer,

Kazanamadıysan bir dost

Bilemezsin gerçek dost koca bir ömre değer,

Öğrenemedinmi hala? 

 Yalnızlığın soğuk rüzgarı bomboş yüreklerde eser...

Anmak istedikçe kayboluyorsa gözünde koskoca mazi,

Ensende hissediyorsan ölümün soğuk nefesini,

Şimdi sakla gözyaşını kaybettiğin geleceğe AĞLA...', 'Ağla yüreğim... Ağla geçen yıllara, Ağla tükenen yalancı sevdalara, Yalnızlığının hapsettiği odanda, Ömrünün baharında  Yüreğini donduran ka...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Yıldız']::text[], 8.5, '{"poet":"Ayfer Yıldız","poet_slug":"ayfer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agla-yuregim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Aşk', 'umutsuz-ask-mustafa-ayik-z9lsq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutsuz başlar benim aşklarım

Vatan umutsuz, yar umutsuz

Bir sevda büyür ki yüreğimde

Dünyalara sığması zor umutsuz

Karabasan gibi memleketimin yarınları

Sorunlar yumak olmuş insanlar umutsuz

Evde ana, işte baba, okulda çocuk

Askerde memet yavuklusunu sayıklar

Ellerinde yemeni oya kızlar umutsuz

Rasgele deyip denize açılan balıkçı

Kavruk elleriyle ürünü hasat eden çiftçi

Sürüsünü otlatan çoban,

Tezgahını siftahsız açan esnaf

Anadolu’dan insan manzaraları

Türkü türkü  Türkiye’m umutsuz

Ben çifte sevdaya yanmışım, 

Vatandan umutsuz yardan umutsuz

Sevdalarım hep umutsuz

Ben ise mutsuzum mutsuz.

1998', 'Umutsuz başlar benim aşklarım Vatan umutsuz, yar umutsuz Bir sevda büyür ki yüreğimde Dünyalara sığması zor umutsuz Karabasan gibi memleketi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umutsuz-ask-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli yüreğim', 'deli-yuregim-ayfer-yildiz-o1zil', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Coştu yine deli yüreğim coştu,

Lafımı sözümü dinlemez oldu,

Bir garip hüzne dalmış yine,

Sazını dertli dertli çalar oldu.

Aktı yine deli yüreğim aktı,

Sabır nedir bilmez oldu,

Bir türkü dolamış diline,

İçli içli söyler oldu.

Şaştı yine deli yüreğim şaştı,

Hakikati görmez oldu,

Kapamış gözünü kara bi perde,

Döne döne haraboldu.

Yandı yine deli yüreğim yandı,

Çöllere kendini salar oldu,

Atmış kendini ateşe,

Bile bile yanaroldu.

Daldı yine deli yüreğim daldı,

Sarılmış bi büyük hasrete,

Göre göre kurban oldu....', 'Coştu yine deli yüreğim coştu, Lafımı sözümü dinlemez oldu, Bir garip hüzne dalmış yine, Sazını dertli dertli çalar oldu. Aktı yine deli yür...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Yıldız']::text[], 8.5, '{"poet":"Ayfer Yıldız","poet_slug":"ayfer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/deli-yuregim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Babam', 'nereye-babam-i-lknur-er-rh7ig', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir baba gidiyor 

Yüreğimizden değil

Dünyadan göç var bu kez

Mümkün olsaydı yerine ölmek

Gözümü bir an olsun kırpmazdım

Bir baba gidiyor

Gözleri arkada

Canı kadar sevdiği eşi

İki oğlu, iki kızı ve

Ben biricik gelini, ben

Çok sevdiği ben

Alnından son öptüğüm an

Gözlerimin önünden 

Bir an olsun gitmiyor

Gönlümün yıkıntıları arasında kaldı

Umutlarım, mutluluklarım 

Umut yok diyor doktorlar

İyileştirmek için değil

Yaşatmak için uğraşıyoruz

Belki bir gün, belki iki gün

En fazla üç

Nereye babam 

Nereye', 'Bir baba gidiyor  Yüreğimizden değil Dünyadan göç var bu kez Mümkün olsaydı yerine ölmek Gözümü bir an olsun kırpmazdım Bir baba gidiyor Göz...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nereye-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-mustafa-ayik-19wid', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pınar başında sevda olur

Ekin tarlasında başak

Yüce dağlarda ise kar

İnce bir sızı yürekte yar

Gelincik tarlasında bir çift kınalı el

Burçak tarlasında nasır olur

Anadolu’mda kızlar nehir olur akar', 'Pınar başında sevda olur Ekin tarlasında başak Yüce dağlarda ise kar İnce bir sızı yürekte yar Gelincik tarlasında bir çift kınalı el Burçak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yar-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Yavrum...', 'yavrum-dursun-elmas-9vsa6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '_______________Kızım Esra''ya

Okumak; erkeğe kadına farzdır

Hakkı söylemeyen insan arazdır.

Emrine itaat,Rab''be niyazdır

Haramdan helâli seçesin yavrum.

Aldanma zahirde melâmilere

Kapılma bezirgân haramîlere

Kapın açık olsun kirâmilere

Hakikat yoluna giresin yavrum...

İsra suresinde Mevlâm duyurur; 

''Anaya babaya merhametli dur.''

Lokman ondördünde ''şükür'' buyurur

Allah rızasını bulasın yavrum...

Allah''ın emridir itiraz etme

Sevgide saygıda hiç kusur etme

Değil kavga,niza,''üf''bile deme

Hayır dualarım alasın yavrum...

Esasta güzellik deride değil

Makyajda,boyada,cilâda değil

Kılıkta,çaputta,kabukda değil

Bâtında gerçeği göresin yavrum...

Unutma bunları yaz bir kenara

Namus lekesidir onulmaz yara.

''Uyma köksüzlere,olma maskara''

Emr-i bil maruf''u bilesin yavrum...', '_______________Kızım Esra''ya Okumak; erkeğe kadına farzdır Hakkı söylemeyen insan arazdır. Emrine itaat,Rab''be niyazdır Haramdan helâli seçe...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yavrum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya gibi geçti yıllar', 'ruya-gibi-gecti-yillar-miyaser-gulsen-igzms', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüya gibi geçti yıllar

Elimizde ah ne kaldı

Kimi kalpte mutluluk

Kiminde hicran kaldı

Sevdi sevildi bazen

Kaç kere yaralandı

Kimi kalpte mutluluk

Kiminde hicran kaldı.', 'Rüya gibi geçti yıllar Elimizde ah ne kaldı Kimi kalpte mutluluk Kiminde hicran kaldı Sevdi sevildi bazen Kaç kere yaralandı Kimi kalpte mut...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruya-gibi-gecti-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyesim Gelir', 'diyesim-gelir-mustafa-ayik-4iat7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sürme çekmiş ela göze 

Sevgilim diyesim gelir

Bir ateş ki düştü öze

Yudum yudum içesim gelir

Tel tel dağılmış saçların

Bir yol bulup geçesim gelir

Lal olmuş dilim söyleyemem

Yüreğimi satırlarla sana açasım gelir

İnce bellim gonca dudaklım

Ay yüzlüm elma yanaklım

Umman bakışlım buz yüreklim

Duygu yüklü göz yaşlarımı saçasım gelir

Bir sevda ki küllenmek bilmez

Bir kader ki gülmek bilmez

Bir sevgili ki gelmek bilmez

Çekilmez yaşamak kaçasım gelir

Duyulmadı aşkımın feryadı

Sevgisiz yok yaşamanın tadı

Şu gönlümün son muradı 

Yar elinden zehir içesim gelir', 'Sürme çekmiş ela göze  Sevgilim diyesim gelir Bir ateş ki düştü öze Yudum yudum içesim gelir Tel tel dağılmış saçların Bir yol bulup geçesim...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diyesim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam olsun', 'selam-olsun-mustafa-ayik-o4lgn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Selam olsun geleceğe

Işıl ışıl gözlerde fışkıran bilinç

Umut tarlasında olgunlaşan başaklar

Ve selam düşünce yüklü genç

İleriye dönük yaşa

Sen tut güneşi ellerinde

Ellerinde tut ki

Biz bilemedik, duyamadık, anlayamadık

Ama onlar anlasınlar nedir sevinç

İşte bu sevgiyle katmerlensin

Yüreğndeki hınç.', 'Selam olsun geleceğe Işıl ışıl gözlerde fışkıran bilinç Umut tarlasında olgunlaşan başaklar Ve selam düşünce yüklü genç İleriye dönük yaşa S...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/selam-olsun-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-miyaser-gulsen-3next', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin nakış nakış

Gözlerin iflah olmaz

Koşuyor duyguların gözlerinde

Yol yol oluyor

Bir yaramaz çocuk sanki

Gözlerinde soluyor.', 'Gözlerin nakış nakış Gözlerin iflah olmaz Koşuyor duyguların gözlerinde Yol yol oluyor Bir yaramaz çocuk sanki Gözlerinde soluyor....', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozlerin-174-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-mustafa-ayik-uxgk2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehrin göbeğinde köhne bir apartman.

Koridorlar karanlık, odalar loş.

İnsanlar yok, ışık yok, yıldızlar bile yok.

Caddeler ise bomboş.

Çıkıyorum dar merdivenlerini evimin,

Nefes nefese kalarak.

Başbaşayım odamla,

Bir köşesini kapmış çek yat.

Bomboş bir oda,

İster kal, ister çek git.

Kare kare kontrplak tavan,

Odamın duvarları yavanmı yavan.

Ortasında bir soba var kovalı,

Pencerem ıslık çalar sanki çoban kavalı.

Köşede iki sandalye, bir masa,

Yüreğimde gam tasa.', 'Şehrin göbeğinde köhne bir apartman. Koridorlar karanlık, odalar loş. İnsanlar yok, ışık yok, yıldızlar bile yok. Caddeler ise bomboş. Çıkıy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizligim-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla beni', 'anla-beni-mustafa-ayik-70jtu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğayım ben, toprak kokarım.

Denizim ben, dalga olur kıyıları yıkarım.

Ben nehirim gürül, gürül, akarım.

Ne olur türkülerimle anla beni.

Ben çileyim, ömür denizinde yüzen,

Ben sevdayım, ölümün koynunda gezen,

Ben ateşim, nasırım, kırışığım yüzlerde bazen,

Ne olur duygularımla anla beni.

Ben çobanım, dağların başında.

Ben tuzum, biberim ekmeğinde, aşında.

Ben köylüyüm tarlasında işinde.

Ne olur yüreğimle anla beni.', 'Doğayım ben, toprak kokarım. Denizim ben, dalga olur kıyıları yıkarım. Ben nehirim gürül, gürül, akarım. Ne olur türkülerimle anla beni. Ben...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anla-beni-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgam', 'kavgam-mustafa-ayik-wm1mv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sormayın bana 

Ellerimin neden nasırlı olduğunu

Neden alnımın çizgi çizgi saçlarımın ak

Bakışlarımın dalgın çehremin berrak

Ve bilmeyin nasıl yaşadığımı

Ve öğrenmeyin ne yaptığımı

Ama irkilmeyin çığlıklarımı duyarak

Bilmek isterseniz kavgamı

Şöyle bir tarihe bakın

Her şey yaşamak için

Savaşlar barışlar bilim teknik

Devletler halklar milletler 

Yaşamak için varız yaşamak

Dün kavgam buydu yarında bu 

Ve hep bu böyle olacak', 'Sormayın bana  Ellerimin neden nasırlı olduğunu Neden alnımın çizgi çizgi saçlarımın ak Bakışlarımın dalgın çehremin berrak Ve bilmeyin nası...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kavgam-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Tek Satırında...', 'siirin-tek-satirinda-melek-ayaz-lnstp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçindeki sana ulaşamayınca,

Dostum, yaralardan kan damlar,

Çiçeklerin gölgesinde barınamazsın

Silik bir gölge gibi süzülüp geçersin.

Sokaklarda izin kalmaz geride,

Hüzünlerin şahidi olmayı reddeder parke taşları,

Kalırsın sadece dizginlerinden boşanmış öfkenin,

Zaman kalmaz pişmanlık itiraf edecek kadar,

Cesaretin öfkene davetiye üstüne davetiye çıkarır,

Bir mermi gibi acı verir kalemin dizelerinden,

Sevgi ve dostluğun gücünü unutursun,

İçindeki sana ulaşamayınca.

Acıya tek başına çıkmak zorunda kalırsın,

Dalından erken düşmüş bir yaprak gibi,

Sürüklenirsin rüzgarların önünde,

Kendine tahammül edecek halin kalmaz,

Kendi içinde boş bir mağaraya sığınırsın

Geçmişe takılıp hiç gelmeyecek yarın olursun.

Söz biter sen düşlerinin katili olursun,

Önce vezirin, ardından şahın gider ensonunda,

Kendine güven yaptıklarına ruhunu kat, katki,

İnsanların ruhuna giresin, işte dostluk sevgi orada.

Yüreğini ve duygularını dinle,kendine güven,

Gün gelir yaşamaya değecek zaman biter,

Söz sadece bir şiirin tek satırında kalır..

İçindeki sana ulaşamayınca...', 'İçindeki sana ulaşamayınca, Dostum, yaralardan kan damlar, Çiçeklerin gölgesinde barınamazsın Silik bir gölge gibi süzülüp geçersin. Sokakla...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/siirin-tek-satirinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perşembe Akşamı', 'persembe-aksami-ahmet-karaca-hcjdp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle senin camdan bakmanla göremeyeceğin

 bir kuytuda bekleyeceğim seni birgün 

 farketmez isterse o gün altmış derece olsun hava 

 yada dolu yağsa, kar yağsa

 seller götürse yolları

 kopsada merhamet bilmez fırtınası

 seni bekleyeceğim senin kapında 

 bir perşembe akşamı

 farkında olmadan yürüyeceksin bana doğru

 usulca beni farketmeden geçeceksin yanımdan 

 biliyorum o an kesilecek dermanım

 kalmayacak mecalim

 keşke ama keşke

 omzuna dokunduğumda 

 olmasaydı git deme ihtimalin 

 olurya birgün sevgili 

 olurda omuzlarına dokunmamı istersen 

 bir perşembe akşamı

 benim o çok sevdiğim bilezik küpeleri tak kulağına

 ve balık sırtı yap saçlarını', 'Öyle senin camdan bakmanla göremeyeceğin  bir kuytuda bekleyeceğim seni birgün   farketmez isterse o gün altmış derece olsun hava   yada dol...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Karaca']::text[], 8.5, '{"poet":"Ahmet Karaca","poet_slug":"ahmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/persembe-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılırdı adım suya', 'yazilirdi-adim-suya-adnan-gul-u5030', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yazılırdı adım suya

tuzu kaçtı sadeliğin

nasılsa, yüreğe vakıf herkes...

inadım ya, akla...

kapılsaydım o an akıntıya

çekilmezdi ama kuru yanım

yazılırdı adım suya...

iyi ki değildin, karşımı süzen boşluk

iyi ki daraltmıştı aramızı uzaklar,

donuk nöbetiydin hasretin...

biraz suydun, biraz bulut

durusunu süzen yüzünde...

aranırken indiğimde, boştu oysa yeriniz,

el çırpıyordu gelişinize, çişli çocuklar,

düşüyordu iyi yüzünüzden postunuz...

üzmedi ayrılığı, gidenlerin aklımdan

değildi ki orası, arındığım yer...

dardım ama birkaç beden; 

uyardım çağrıldığım sese...

yakışırdım beyazına tuzun

kazanırdı gönlümü leke...

soyunmuşken ilk lanet makamına dünya,

habersizken pılı pırtıdan

dip çarşılara açılırmış deniz kızları,

bilicilik yapıp; 

açıklık getirmek üzere akşama,

yüzünü ovarmış eller buzulun! ..

bense doymamışcasına pavelliğime,

dünya görmüş mahlukatsa derdiniz; 

deniz yengecidir derdim,

iki başı tek bedene uyduran...

bağırırdım hıncımı, dönüp

ikiyüzlü imrenenlere...

işlerdi sanırdım kıyıya; dalga parçası sesim...

karanlığa yeni dokunurken geceler,

uzardı anırması beyaz eşeğin...

gece kafir düşer sahile...

nar ekşi,

şarap kekre...

yaşamak ve acılar yüzü hürmetine,

onulmaz sırlar saklı baharım...

doğrudan daha yalandır...

kim derse tanrılar, affetmez beni...

''sıcak vesika'' adlı kitaptan', 'yazılırdı adım suya tuzu kaçtı sadeliğin nasılsa, yüreğe vakıf herkes... inadım ya, akla... kapılsaydım o an akıntıya çekilmezdi ama kuru ya...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gül']::text[], 8.5, '{"poet":"Adnan Gül","poet_slug":"adnan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yazilirdi-adim-suya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteklerim...', 'i-steklerim-melek-ayaz-xcz8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsteklerim yönelince sana,

Kervan, kervan,

Denizlerin üstündeki ışıyan güneş,

Ağlatası olur masum sevgimi,

Yoluma yine bomboş mezarlar açılır,

Ben öveceğim masum sevgimi,sevdiğimi,

Giydir gözlerine masum sevgiyi,

Giydirde büyüyle bedenin ısınsın,

İşte ozaman yanlızlığı fethetmiş olursun,

Dolaşmak durmadan ince çizgilerde,

Sürünmek sevginin bayırında,

Yaz günlerine dokunan güneş gibi,

Yorgun düşünceye kadar gölgesinde,

Dolaş bütün masum sevgileri,

Boğmasın seni düşündeki bataklık,

Giydir gözlerine masum sevgiyi,

Giydir de büyüyle bedenin ısınsın,

İşte o zaman yanlızlığı fethetmiş olursun...', 'İsteklerim yönelince sana, Kervan, kervan, Denizlerin üstündeki ışıyan güneş, Ağlatası olur masum sevgimi, Yoluma yine bomboş mezarlar açılı...', ARRAY['Türk Edebiyatı','Şiir','Melek Ayaz']::text[], 8.5, '{"poet":"Melek Ayaz","poet_slug":"melek-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isteklerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrilik', 'ayrilik-okan-nar-9g0pi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Asiklar kavusamaz derlerdi inanmazdim.

Nereden bilirdim iki gönülde olacak gayrilik.! 

Olurmuydu onca yasanandan sonra ayrilik..? 

Yikildi gönül evim, oldu virane.

Okan nasil güler artik,

Gönül oldu deli divane.

Hersey bos,anlamsiz vede sadece bir bahane.

Yasam sanki bir sahne,yasananlar ise sadece bir oyun.', 'Asiklar kavusamaz derlerdi inanmazdim. Nereden bilirdim iki gönülde olacak gayrilik.!  Olurmuydu onca yasanandan sonra ayrilik..?  Yikildi g...', ARRAY['Türk Edebiyatı','Şiir','Okan Nar']::text[], 8.5, '{"poet":"Okan Nar","poet_slug":"okan-nar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-272-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyumdan Büyük Yaşıyorum', 'boyumdan-buyuk-yasiyorum-tulay-sustam-q5tw4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her düşüşümde

Hayatın bir kaburga kemiğini kırıyorum

Güneş''in saçlarından tutup

Ayağa kalkıyorum

Sevdalım hayat; 

Kaç gecedir koynundayım 

Beni her gece başka bir tende aldatsan bile

Seni yüz üstü bırakıp gitmeyeceğim

Ey Hayat! ...

Boyumdan büyük yaşıyorum seni...

(kabataş iskelesi)', 'Her düşüşümde Hayatın bir kaburga kemiğini kırıyorum Güneş''in saçlarından tutup Ayağa kalkıyorum Sevdalım hayat;  Kaç gecedir koynundayım  B...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/boyumdan-buyuk-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı', 'sari-ozgur-doran-9x7tw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarı...

bir renk değil...

üzgün bir bakış

bir  sevişme ardılı

dönülmeyecek bir yolun mihenk taşı

son nefeste söylenen 

sevgili...

düşmesin bedenin 

kurtlar kemirene dek...

ölme

ölüm yakışmaz sana', 'Sarı... bir renk değil... üzgün bir bakış bir  sevişme ardılı dönülmeyecek bir yolun mihenk taşı son nefeste söylenen  sevgili... düşmesin b...', ARRAY['Türk Edebiyatı','Şiir','Özgür Doran']::text[], 8.5, '{"poet":"Özgür Doran","poet_slug":"ozgur-doran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sari-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Kalemimden Kan Damlıyor Bugün', 'sair-kalemimden-kan-damliyor-bugun-i-lknur-er-0yng8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şair kalemimden kan damlıyor bugün

Yüreğime sıkıştı tüm sözcüklerim

Ürkek kanatlarımın altında kaldı

Güzel dizeler

Şimdi mutsuzluğa birleşiyor harfler

Siyahlar, beyaz sayfalar üzerinde

Nasılda göz alıyorlar 

Ne Aşk acısına benziyor

Ne ihanete nede ayrılığa

Ölüm diyorlar bu adı karaya

Tarifi yok 

Dünya ile ahiret arasında

Sıkışmış bir ruh

Bir el buradan uzanmış

Bir el oradan

Elimizde değil seçim yapmak

Vakti geldiği an 

Ne bir dakika eksik 

Ne bir dakika fazla

Kayacak parmak uçlarımız 

Dünyadan

Yinede yakıştıramıyor sevdiğine 

İnsan.', 'Şair kalemimden kan damlıyor bugün Yüreğime sıkıştı tüm sözcüklerim Ürkek kanatlarımın altında kaldı Güzel dizeler Şimdi mutsuzluğa birleşiy...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sair-kalemimden-kan-damliyor-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzümdü yüzünde buluşan cennet', 'yuzumdu-yuzunde-bulusan-cennet-adnan-gul-63ge2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüzümdü yüzünde buluşan cennet

ateşime erken döndüm...

el salladım gizlisinden spil''in

öptüm yamacın yeşeren yanağını,

sevdim düzlüğünü, seni gören tepenin...

belki daha çıplaktım adem''den

attığımda yüreğine taşı...

belki gelinen yolun ilk kıvrımıydım,

durma diyecektim helal...

uzağını süzme karşımda,

yüzümdür, yüzünde buluşan cennet...

hoştu hüzün dağı, girmeseydin altına...

nasıl doğru koyulduk ki söze,

patladı elinde dolma...

şimdi tufan,

şimdi zulüm, hazana yağma...

süslü peşine düşünce elindekinin,

kırılır, yüzümün ötesindeki gerçek...

ahhhhhhh, zangocun zahir sesleri

kanayan akşam olgunluğum,

gidip gelmeleri hasretin...

dayamıştı oysa dağlı rüzgar, sütlü dili,

bırakmıştı küreksiz salı sınıra...

mavi açan o güldü; 

ürkek dalın ağacına sığınan...

çırpınmakkkkk, rrüzgarsızzz,

ddurrmaaaakkk, ölümdüüüü.

diyelim ki zayıfım demirimden,

bekletmişim güneşi ayaküstü...

yokluğa denenmişim...

diyelim ki etimden uzak duramadı, kanım,

birleştikçe öldürmüşüm, içinizde kendimi...

oysa öyle yaşıttık ki zulme,

ruhun yansımıştı sesine...

belki nazire, belki dokunma telaşı

ateşten evvel yürümen, kandile...

''sıcak vesika'' adlı kitabından', 'yüzümdü yüzünde buluşan cennet ateşime erken döndüm... el salladım gizlisinden spil''in öptüm yamacın yeşeren yanağını, sevdim düzlüğünü, sen...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gül']::text[], 8.5, '{"poet":"Adnan Gül","poet_slug":"adnan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yuzumdu-yuzunde-bulusan-cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrak Mı Derim', 'bayrak-mi-derim-murat-kilic-2-sy1ly', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanrı eliyle kanatlanır melekler.

Namert önünde bükülmez mert bilekler.

Uğruna sorgusuzca yağız yürekler,

Adanmayan bayrağa bayrak mı derim.

Bir boz bağırda sıra sıra yatanla.

Göğsün gururla dolup taşar atanla.

Her bir zerresi damla damla kanla,

Islanmayan bayrağa bayrak mı derim.

Nazlı nazlı dalgalanmadıkça bayrak; 

Ne yar helaldir ne de bir avuç toprak.

Gölgesinde özgürce bir küçük ocak,

Yanmayan bayrağa bayrak mı derim.

Ben Türk oğluyum birdir dilim dinim.

Kalsa da canımda son nefes yine seninim.

Hainlere el değdireceksem kefenim,

Olmayan bayrağa bayrak mı derim.

Bayrağım! 

Coşkun türküsün bu milletin dilinde.

Dalgalanırken huzur buluruz yelinde.

Bir Ulubatlı’nın bir Mehmet’in elinde,

Salınmayan bayrağa bayrak mı derim.

(17.05.2004)', 'Tanrı eliyle kanatlanır melekler. Namert önünde bükülmez mert bilekler. Uğruna sorgusuzca yağız yürekler, Adanmayan bayrağa bayrak mı derim....', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bayrak-mi-derim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''e Mektup', 'eylul-e-mektup-murat-kilic-2-jxp5k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'özledim seni! 

her düşündükçe seni

bir katre daha arttı özlemim.

hali kendinden halsiz bir dere kenarında 

sadece kuş seslerine meyilli yalnız bir çardakta

uzadıkça ömrüme acılar süsleyen 

hayaller kurdum  sana dair.

ne kaldı geriye düşler ülkesinden 

umut ağacım yaprak döktü

haber gelmeyince sesinden

sen gittiğin günden beri bu hal

mevsimini tamamlayamadı güneş çehresinden

ne nisan da ne ağustos da tat var

yağmurla güneş küs oldu benimle bana 

uzadıkça uslanmaz oldu hasretliğin susuzluğundan öldüm

yine de düşmedi ramhetinden bir damla çatlamış toprağıma.

sonra bir yerden duyulur sesim dedim

sana bir mektup yazayım istedim

ve belki şu an ellerindeyim! 

inan ki; 

mektubun geldiği adres ve adresçi

seni tahmin ettiğinden çok daha fazla özledi', 'özledim seni!  her düşündükçe seni bir katre daha arttı özlemim. hali kendinden halsiz bir dere kenarında  sadece kuş seslerine meyilli yaln...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eylul-e-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-murat-kilic-2-d9aia', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içimdeki durgun nehir 

konuşmayan suskun şehir

akşam dediğin artık benim için

sahilime demir atmış gözlerin

uykumu bölen en keskin zehir

zifir saçlarına yüreğim bağladığım

uzak diyarların üzüm karası yürek yarası

sen belki herkes için sıradan birisin 

ama benim için herşeysin

bu dört duvar arasında uzayıp giden gözlerinle 

bana yenisin

sen olmanın ötesi; alışkanlık müptelalık

sen içimdeki güvercin

aşinalığımın yegane adresisin

öyle hasretimki teninin gül kokusuna

söyle şimdi neredesin

beni soracak olursan kendine

elini kalbinin üzerine koyup aynaya bak.

gözlerinde ve yüreğinde beni göreceksin....

(10.12.2007)', 'içimdeki durgun nehir  konuşmayan suskun şehir akşam dediğin artık benim için sahilime demir atmış gözlerin uykumu bölen en keskin zehir zif...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdigim-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum Oldu', 'umudum-oldu-hale-kazak-ghy2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Caresiz kus gibi cirpinirken,

Arta kalan nefesimide,heyecanimida,

Tutmak icin kanatlarimda,

Tasin,topragin,ruzgarin,

Yollarin,denizlerin ortasinda,

Kara bulutlari,carpisan yildirimlari,

Kullendirmeye calisirken,dunu

Yalniz ve caresizligime

Isteksizce boyun egip,

Sevgimi,askimi,umudumu,

Gomdugumde derinliklerime,

Kilitledim dedigim yuregimi,

Bir daha acamam,

Derken coskun nehirlere,

Ve ve korktugumu da itiraf ederek

Yeni sevdalara kalbimi,

Ben benligimi unutmaya yuz tutmusken

Artik ve yorgun gunlerin ardindan,

Herseyi bir kenera koyup,

Yasamla bogusmaya calistigim,

O buyuk dalgalarda,

Dip kuyulara vurdugum,

O son aksamda,

Yeniden dogdum,

Caresizliklerimi bir kenara koyarak,

Ben yine ben oldum.

Hani yine icindeki,

O sarkiyi dinleyen,

Bedeninde gunes gibi,

Atesi hisseden,

Halbuki caresiz kus gibi cirpinirken

Kanatlarini tutmak icin ayakta,

Ben yeniden kus oldum,

Ozgurlugume ucmak icin,

Sonsuz gokyuzune,

Ahengiyle salinmaya biraktim yeniden,

Hissettigim o mutlu yarinlara,

Umudum oldu...', 'Caresiz kus gibi cirpinirken, Arta kalan nefesimide,heyecanimida, Tutmak icin kanatlarimda, Tasin,topragin,ruzgarin, Yollarin,denizlerin ort...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/umudum-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 41', 'eskimez-beyitler-41-huseyin-avdic-6k81p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eroin

Beyaz bir adam geçti dün buradan,

Ardında bıraktı bin siyah adam! 

******

Onikili ayların sonucu

Damlaya damlaya göl oldu onikili aylar.

Albaylar geldi gitti, idam oldu bizim oylar...

******

Bediüzzaman

Bediüzzaman, zaman isteyene zaman.

Bediüzzaman, derman dileyene derman.

******

Hz.Muhammed(sav)  e

Sevda Çiçeği, Sevda Çiçeği! 

Sensin eflâkın günü güneşi.

---

Not: Sevda Çiçeği, gül''e işarettir.

Gül de, Hz. Muhammed''e.

******

Olması gereken eser

Bir eserim olsun, Müessir''e esir.

Esir olmazsa eser, olmaz müessir.

---

Not: Müessir: Etkili, etkileyen, herşeye tesir eden Allah.

Batı Berlin, 1980-85.', 'Eroin Beyaz bir adam geçti dün buradan, Ardında bıraktı bin siyah adam!  ****** Onikili ayların sonucu Damlaya damlaya göl oldu onikili ayla...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eskimez-beyitler-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dillere Dillere', 'dillere-dillere-kahraman-salta-4b9k0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kerem, Aslı için düşmüş yollara

Mecnun,Leyla için düşmüş çöllere

Bülbül, gül içinde konmuş dallara

Onun sevdası da güllere güllere

*

Bübülün çilesi gülün elinden

Sevdayı çekenler bilir halinden

Yaban ellerinde elin dilinden

Onun sevdası da güllere güllere

*

Baykuş gibi ötme viran yerlerde

Uçsuz bucaksız gurbet ellerde

Kapılıp gidersin gelmez yollara 

Onun sevdası da dillere dillere 

*

Sen kimselere ihanet de yapma

Doğrudan ayrılıp kötüye sapma

Çıkarın için insanı da satma

Düşersin acı hallere hallere

*

Yanar da ateşe kül de olursun

Olura olmaza kul da olursun

İyilik et yeter  gül de olursun

Sen de gidersin sellere sellere

*

Suçu önce kendine sordun mu? 

Yüce dağın arkasını gördün mü? 

Başkaları suçlayıp da durdun mu? 

Sonra düşersin dillere dillere

*

Ateş de düştüğü yeri de yakar

kamramani  de burada ne yapar? 

Dağdaki karlardan çığı da kopar

O da düşerse bellere bellere 

Kahraman SALTA

www.gunduzkitabevi.com.tr', 'Kerem, Aslı için düşmüş yollara Mecnun,Leyla için düşmüş çöllere Bülbül, gül içinde konmuş dallara Onun sevdası da güllere güllere * Bübülün...', ARRAY['Türk Edebiyatı','Şiir','Kahraman Salta']::text[], 8.5, '{"poet":"Kahraman Salta","poet_slug":"kahraman-salta","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dillere-dillere-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor Kanser Dedi', 'doktor-kanser-dedi-nazli-gizem-caglayan-v4olx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özge uzatacaktı gece kokulu saçlarını,

Annesi tarayacaktı gecenin kokusunu; 

Kendi gül kokusuna bulayacaktı.

Doktor kanser dedi; 

Geceyi topladılar güllerden,

Gül kokusu soldu...

Özge bilmiyordu acının bu kadar acı olduğunu,

Nerden bilsin daha umutlara boyanmış bir çocuktu o,

Ölemeyecek kadar,acı çekemeyecek kadar çocuktu; masumdu...

Azrailin elleri sarılmıştı gırtlağına,

Ama içindeki sevgiyi,umudu öldüremiyordu işte...

Annesi her saniye nefesini yokluyordu

Yaşıyor mu diye elleri titreyerek,

Doktor kanser dedi; 

Özge yavaş yavaş geceye karıştı, saçları gibi

Annesi yavaş yavaş soldu, Özge''si gibi

Ve artık hayat yoktu, Özge''min olmadığı gibi....

(05.08.05/TRABZON)', 'Özge uzatacaktı gece kokulu saçlarını, Annesi tarayacaktı gecenin kokusunu;  Kendi gül kokusuna bulayacaktı. Doktor kanser dedi;  Geceyi top...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Gizem Çağlayan']::text[], 8.5, '{"poet":"Nazlı Gizem Çağlayan","poet_slug":"nazli-gizem-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/doktor-kanser-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-rasit-erbek-bldg0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HATIRALAR

bazen insanın yanağına mutlu bir gülümseme konduruverir

bazen gözlerine birkaç damla yaş

bazen taze ekmek kokusu gibi

içine çekesin gelir

bazen ise insanın yüreğine oturuverir

ağlamak istersin de ağlayamazsın bazen

acıtır içini sesini çıkartamazsın..

raşit erbek   28.07.2005', 'HATIRALAR bazen insanın yanağına mutlu bir gülümseme konduruverir bazen gözlerine birkaç damla yaş bazen taze ekmek kokusu gibi içine çekesi...', ARRAY['Türk Edebiyatı','Şiir','Raşit Erbek']::text[], 8.5, '{"poet":"Raşit Erbek","poet_slug":"rasit-erbek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hatiralar-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delidir Deseler', 'delidir-deseler-ali-osman-yilmaz-4w0at', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırlarda geziniyorken,

Seni düşünüyordum,

Karşıma birden,

Bir bostan korkuluğu çıktı.

Kendi yalnızlığımdan yakınırken,

Bostan korkuluğuna bakıp,

Böyle yapayalnız,

Bostanda bir başına,

Beklemekten sıkılmış olmalısın dedim.

O da bana,

Sen beni yalnız mı sanıyorsun? 

Ben bostan korkuluğuyum,

Her gün kuşlarla,

Konuşuyorum ben,

Ya sen,

Her gün,

Kimlerle konuşuyorsun,

Diye sormaz mı? 

İşte O an,

Düşündüm şöyle bir,

Sen yoksan eğer,

Ben kimle ve nasıl,

Konuşuyorum.

O yüzden bana,

Delidir deseler,

Ne diyebilirim ki?', 'Kırlarda geziniyorken, Seni düşünüyordum, Karşıma birden, Bir bostan korkuluğu çıktı. Kendi yalnızlığımdan yakınırken, Bostan korkuluğuna ba...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/delidir-deseler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kız', 'ey-kiz-nobel-sairi-248ij', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden bir insan başlar başkalaşmaya,

Uyumaz,hep aklındadır geceden sabahlara,

Bazen deli olur karşılıksız olunca,

Başlar gözlerinden yaş akmaya,

Hava alması bile değişir onun için,

En soğuk havalarda bile içi sıcacıktır,niçin,

Şarkılar başka anlamlar kazanır,

Yıpranmaz dense de zamanla yıpranır,

Kimisi ilk defa karşılşınca dili tutulur,

Acaba onun derdine kim çare bulur,

Uyuyabildiğinde görse de rüyalarında,

Hani nerde o insan,yokki yanında,

Konuşulur ya kendi kendine,resmine baka baka,

Gecelerce teselli aranır bir kadeh rakıda,

Deniz dalgasız,gökyüzü güneşsiz,beden olmaz ya cansız,

Şimdi söyle,ben nasıl olurum sensiz EY KIZ! ! ! !', 'Neden bir insan başlar başkalaşmaya, Uyumaz,hep aklındadır geceden sabahlara, Bazen deli olur karşılıksız olunca, Başlar gözlerinden yaş akm...', ARRAY['Türk Edebiyatı','Şiir','Nobel Şairi']::text[], 8.5, '{"poet":"Nobel Şairi","poet_slug":"nobel-sairi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-murad-aktas-92bpv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu alemde tek sevdiğim,

Ecele gülüp geçtiğim,

Hayatımı sana verdim,

Ruhumuda vereceğim.

İsmine şiirler yazdım,

Başıma tacını taktım,

Anla ben sana aşığım,

Ne olursun ANLASANA! ...', 'Şu alemde tek sevdiğim, Ecele gülüp geçtiğim, Hayatımı sana verdim, Ruhumuda vereceğim. İsmine şiirler yazdım, Başıma tacını taktım, Anla be...', ARRAY['Türk Edebiyatı','Şiir','Murad Aktaş']::text[], 8.5, '{"poet":"Murad Aktaş","poet_slug":"murad-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlasana-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Kalan', 'senden-kalan-murat-kilic-2-j9fy6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerinde ışıyan yalancı yıldızlar artık

saçlarını savuran rüzgar; yalan

yüzünde bin yıllık özlemleri anımsatan 

güneş bile bir hayal

leylaklar menekşeler krizantemler....

seni bana anımsatan yüzlerce şey; 

olduğundan daha kederli solgun.

uzakları yazıma nakşeyleyen sebep! 

nağmelerinle ölen benim

bu yaşlanmış ruhumla 

umutsuzluk sarmaş dolaş

ufuk keşmekeş bir karanlık

bu yitik hayatla 

göğe doğru ağlayan

bu kırık kanatla 

sadece senden kalan

bu amansız hastalık', 'gözlerinde ışıyan yalancı yıldızlar artık saçlarını savuran rüzgar; yalan yüzünde bin yıllık özlemleri anımsatan  güneş bile bir hayal leyla...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senden-kalan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardindan', 'ardindan-hale-kazak-t712q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Disarda yagmur var,

Sessiz ve cizik,

Ardindan bulutlar

Getiriyorlar yenilerini,

Gozumde yas var,

Sensiz ve yitik,

Yuregimde sis bulutlari

Silmiyor acimin izlerini...', 'Disarda yagmur var, Sessiz ve cizik, Ardindan bulutlar Getiriyorlar yenilerini, Gozumde yas var, Sensiz ve yitik, Yuregimde sis bulutlari Si...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ardindan-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettim', 'kaybettim-murat-kilic-2-uhrm5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'cem oldum gezdim yıllar yılı diyar diyar

sultanım, o güzel hülyayı kaybettim

yoluma alemleri serseler ne çıkar

ben sığındığım yüce deryayı kaybettim

gözlerim görmez oldu ters yollara saptım

acılardan denizime gemiler yaptım

mecnun oldum sevilen dedim O''na taptım

gönül gözüm dağlandı, o Leylayı kaybettim

sürüklenirken bir yerden diğer bir yere

uçurumlar çizdim ellerimle sehere

inandıklarımla göğsümü gere gere

haykırış ardındaki rüyayı kaybettim

şimdi kimden medet dilenir bu yaralı

fikir dediğin öz sonsuzumda sıralı

bilinmezleri sırtıma vurdum vuralı

gizler içinde yitip dünyayı kaybettim

bir bilinmez içinde hayat sandığın

ürperişin alevidir her dem yandığım

gönül gurbetinde sorgusuzca andığım

fikrimdeki tek gonca sevdayı kaybettim', 'cem oldum gezdim yıllar yılı diyar diyar sultanım, o güzel hülyayı kaybettim yoluma alemleri serseler ne çıkar ben sığındığım yüce deryayı k...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaybettim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesafelere', 'mesafelere-tunahan-ermihan-dpzjd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derin ve manasız bir sessizlikte

Hafif dalgalı olduğunu sandığım sularda almışım

En derin yaraları

Halin vaktin yerindedir diye

Sayıklarken düşlerimde masumca

Yaban topraklarda hüzzam türküler söylermişsin

Haberin yeni aldım

Uzanmak istedim gücüm yetmedi

Bir çırpıda yanına varayım istedim mesafeler engelledi

Ben adını bile dilime alırken itina gösterirken

Kimler hangi mazeretle üzebilirlerdi seni

Çok kızdım çok öfkelendim

Yinede bir tutam sıcaklığımı sana gönderemedim

Mesafelerdi sadece aramızdaki duvar

Ne gücüm yetti aşabildim

Nede bir çırpıda yanına varabildim', 'Derin ve manasız bir sessizlikte Hafif dalgalı olduğunu sandığım sularda almışım En derin yaraları Halin vaktin yerindedir diye Sayıklarken ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesafelere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayana', 'anlayana-sinan-gundog-wwuye', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazımız ikiyüzlü; bazımız kinci,

Kimimiz taştan farksız, kimimiz inci

Hepimiz sonuçta ahirete yolcu,

Nedir bu didişme nedir gardaşım.

Müdür ol, patron ol aynı çeşittir,

Küçük ol, büyük ol herkes eşittir,

Kazık mı çaktınız koltuğa,bu gurur nedir,

Nedir bu gidiş be nedir gardaşım.

Kimimiz çağdaşmış, kimimiz dinci,

Kimimiz sağcı olmuş kimimiz solcu,

Anlayın artık biz yolcuyuz, yolcu,

Nedir bu çekişme nedir gardaşım.

Birisinde yat vardır, birinde yalı,

Garajında eksik olmaz arabaları,

Elleri pek sıkıdır, kıymetlidir paraları,

Azıcık değiş be değiş gardaşım.

Kiminin gönlü zengin, kiminin kendi,

Kimisi ukaladır kimi efendi,

Sorarım o malı size kim verdi,

Ne olurdu azıcık versen gardaşım.

Kimimiz açlıktan uyku uyuyamaz,

Kimimiz çok yemiş nefes alamaz,

Kimi çekmiş kafayı, evi bulamaz,

Keşke insan,insanı sevse gardaşım.

Bu satırlar konuyu anlayanadır,

Ak kaşık değiliz herkeste hata vardır,

Hatasız kul olmaz, ama dönüşü vardır,

Keşke herkes hatasından,dönse gardaşım.', 'Bazımız ikiyüzlü; bazımız kinci, Kimimiz taştan farksız, kimimiz inci Hepimiz sonuçta ahirete yolcu, Nedir bu didişme nedir gardaşım. Müdür ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Gündoğ']::text[], 8.5, '{"poet":"Sinan Gündoğ","poet_slug":"sinan-gundog","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anlayana-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatla Ölüm Arasında', 'hayatla-olum-arasinda-necmiye-sarpkaya-6gzlw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koşuyorum hayat ile ölüm arasında biteviye

Bir ölüyor bir diriliyor

Bir gidiyor bir geliyorum

Var ile yok arası bir med-cezir

Sonunda her fani gibi

Bir ömür

Bir ölüm

Ayrılan zaman dilimin sonunda

Gelecek var mı bilmeden bilemeden

Yaşam ile ölüm arası gelgitler

Mezar taşlarında

Bir safa

Bir Merve

Bir silüet silik soluk

Hacer silüeti

Telaşlar koşuşturmalar arasında

Günde beş noktada göklerle irtibatlanan

Dikey boyutlara taşınan

Yitirilen ruhların çağrılması

Göğsümün üzerinde birleştirdiğim

Ellerimde hayatın önemsizleşmesi

Sonsuzluğa uzanan köprü

Toprakla buluştuğunda alnım

Her daim beni beklediğini duyumsadığım

Toprak ananın sevincini duyarım 

Dudaklarımda dinmez nağmeler

Sonsuzluğa inat

Bir ömrün bitişi

Bir ateşle imtihan

Payına düşen dur sadece dur

Metanetle dur

İstenen beklenen

Hakikata ulaşmak

Gerçekleri kavramak

Koşuyorum hayat ile ölüm arasında biteviye', 'Koşuyorum hayat ile ölüm arasında biteviye Bir ölüyor bir diriliyor Bir gidiyor bir geliyorum Var ile yok arası bir med-cezir Sonunda her fa...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hayatla-olum-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm - I -', 'olum-i-murat-kilic-2-v1g7f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ıslandım yol üzeri

yağan yağmur altında sırılsıklamım

üzerimdeki bu kar beyazlığı nedir? 

neden suskun dilim

neden kıpırdamıyor elim ayaklarım

bu kısık sessizliğin sebebi ben miyim? 

oysa uyumaklı gibiyim

yarım yamalak yarı uyanık

hayal mi desem yoksa rüya mı

cisimler geçiyor gözlerimin önünden

bazı soluk bazı bulanık

güvercinler konuyor ayak parmaklarıma

el uzatıp dokunayım diyorum

kalkmıyor elim kolum

nefes desem nefes değil aldığım

hava desen olduğundan daha başka

dönmek istiyorum kalkmak istiyorum 

olmuyor

hasta mıyım yoksa? 

ses verin ben neredeyim? 

neresi bu garip yer

.............................................', 'ıslandım yol üzeri yağan yağmur altında sırılsıklamım üzerimdeki bu kar beyazlığı nedir?  neden suskun dilim neden kıpırdamıyor elim ayaklar...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olum-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizdim İşte....', 'sensizdim-i-ste-omer-golge-xi2td', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin sanıpta bu gece.....

Bir yıldızı uzanıp öptüm sessizce..

Martılar fısıldadı.......

Yakamozlar döktüğünü denize.

Gözyaşlarındı avuçladığım

Boğazın tuzlu suları içinde.....

Dipsiz bir boşluktu sensizlik....

Hergün biraz daha yuvarlandığım.

Göğümde en uzak yıldızdın bu gece

Varolduğunu bilmek yine degüzel

Mavi siyah karanlıklar inerken...

Adındı dilimden dökülen hece hece

Ve ben çaresizlikle arkadaş Boğaziçinde

Sensizdim..sensizdim...sensizdim işte....', 'Gözlerin sanıpta bu gece..... Bir yıldızı uzanıp öptüm sessizce.. Martılar fısıldadı....... Yakamozlar döktüğünü denize. Gözyaşlarındı avuçl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensizdim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni SeviyoruM', 'seni-seviyorum-emine-deniz-yhsg4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni Seviyorum 

Avuçlarımda inciler gizledim sana dair 

Çiçekler adadım yokluğunda 

Zeus’a 

Uçurumlardan attım boğazımda düğümlenen kelimeleri 

Hiçbiri geri dönmedi... 

En çok inandığımdın 

En az bildiğim 

Canavarlar doğurdum babasız 

Kendi kendine çoğalan 

İçimde büyüyen kıskançlık adına ‘arsız’ 

Şimdi bir ölüyüm 

Mezarsız 

Bir sevgiyle doğdum, 

Çoğaldım binler oldum 

Düşlerim düşüncelerimin avındaydı 

Bir gece yarısıydı,sabırlar dökülürken dağlardan 

Aşka düştü yolum. 

O sendin 

Aynada kendini seyreden sonsuzluk 

Güneşini kaybedip 

Dağlarımda kendini arayan umutsuzluk 

Çoğalıp binlerce sevgiden 

Doğurduğum 

Bilekleri kırmızı masum çocuk.. 

Seni avuçlarımdaki incilere gizledim 

Alnımdaki çizgilere 

Yedi ölüm yaşadım okyanus gözlüm 

Seni 

Yedi ölüme eşdeğer sevdim...', 'Seni Seviyorum  Avuçlarımda inciler gizledim sana dair  Çiçekler adadım yokluğunda  Zeus’a  Uçurumlardan attım boğazımda düğümlenen kelimele...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-seviyorum-277-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**(B) ir (B) it (B) öceği**', 'b-ir-b-it-b-ocegi-seyhmus-sevilmez-xlv0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bari Birgün 

Bana Beni Barıştırsaydı

Bu Ballı Badem Buselerin 

Bes Belli! 

Birkaç Bahaneden Bekletmelerin 

Buruklaştırdı Bedenimi..

Böylemi Bölecektin Birlikteliğimizi..

Bir Baka Bilsen,

Bir Baksan,

Bana Bakamıyorsun ki…

Biliyorsun, 

Bir Bakışım, 

Barındırır Boranları,

Bir Bakışla Bölerim

Bin Bir Bendi….

Bendeki Bilinmeyen Bela

Bükmeden Boynunu,

Bağıracak Bağrına Beklemeden

Boğacak Belki de.. 

Bilinmeyen Bölgelerde

Beni Bana Bıraktın ya…

Böyle Bitsin Bu Bela,

Başlamasın Bidaha…

Boşunaymış

Bakışımdaki Büyüklüğün,

Bir Balina Balığına Benzeyişin

Bir Balonmuş…

Boşaldıkça Büzüldün

Beli Bükülesi

Bastır Bacak Bit Böceği…

08.08.2005', 'Bari Birgün  Bana Beni Barıştırsaydı Bu Ballı Badem Buselerin  Bes Belli!  Birkaç Bahaneden Bekletmelerin  Buruklaştırdı Bedenimi.. Böylemi ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/b-ir-b-it-b-ocegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-murat-kilic-2-h9u11', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artıları eksileriyle bende insanım

ağlamayı da bilirim gülmek kadar

sadece bunu bilerek

ağlatman mı gerek beni? 

sana büyüttüğüm laleleri fesleğenleri

gökkuşağı renkli orkideleri

böyle acımasızcasına

hatta umarsızcasına

ezmen mi gerek? 

sana tüm benliğimle 

uygun adım koşarken

yollarımı uçurumun kenarına 

getirmen mi gerek? 

şimdi hayatım solgun ve durgun bir deniz

tam ortasında ıssız bir ben

sağım solum önüm arkam hiç...

ve sen hala yalnızlığa inat

aklımın ekseninde son sürat

dönüyor 

döndürüyorsun', 'artıları eksileriyle bende insanım ağlamayı da bilirim gülmek kadar sadece bunu bilerek ağlatman mı gerek beni?  sana büyüttüğüm laleleri fe...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/inat-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnci Zelzelesi', 'i-nci-zelzelesi-mehmet-nuri-gezmis-mi4x8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sunağından dökülen,

İncilerin dağıldı.

Parçalandı yüreğim,

Tek tek toplayana kadar.

Tavuk boyundurluğunda,

Horozlara toplatmaya koyuldular.

İnciler yumurtlamayınca,

Zelzele üstüne zelzele.

Sunağın üstüne uzanan eller,

Gözümün önünde,

Kurdular darağacımı.

Bereket versin,

Sicim benden yanaydı.

Tanrılarını elde edemeyenler,

Baş kaldırdı.

Zelzelelerinden sonra,

Kasırgalar, hortumlar çıkardılar,

Tanrılarının kilitli olduğu,

Kasayı kırana kadar.

Oysa tanrılar rahat uyuyordu,

Asiler inatla onu istiyordu.

Zannettim, linç için.

Güldüler aklıma,

Ceplerine indirmek için.

    (25.07.1997)', 'Sunağından dökülen, İncilerin dağıldı. Parçalandı yüreğim, Tek tek toplayana kadar. Tavuk boyundurluğunda, Horozlara toplatmaya koyuldular. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Gezmiş']::text[], 8.5, '{"poet":"Mehmet Nuri Gezmiş","poet_slug":"mehmet-nuri-gezmis","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/inci-zelzelesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Bak....', 'aska-bak-mehmet-demir-atmali-z41hp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Metres tutan bir Güruh,

Hep Aşk''tan bahsediyor...

Laşka olmuş nice Ruh,

Hep Meşk''ten bahsediyor...

Ne Yiv kalmış, ne de Set,

Gel de Aşk''ı tarif et...

Dokuz oynaşlı Avrat,

Hep Aşk''tan bahsediyor...

9.7.2001', 'Metres tutan bir Güruh, Hep Aşk''tan bahsediyor... Laşka olmuş nice Ruh, Hep Meşk''ten bahsediyor... Ne Yiv kalmış, ne de Set, Gel de Aşk''ı ta...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aska-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahlaklı Teklif', 'ahlakli-teklif-nazmi-orsel-13nem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün olsa hasretle sevgiyle ateşle dolsan

Bana gözümden yakın,

Bir dudak uzaklığı kadar uzakta olsan...', 'Gün olsa hasretle sevgiyle ateşle dolsan Bana gözümden yakın, Bir dudak uzaklığı kadar uzakta olsan......', ARRAY['Türk Edebiyatı','Şiir','Nazmi Örsel']::text[], 8.5, '{"poet":"Nazmi Örsel","poet_slug":"nazmi-orsel","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ahlakli-teklif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ve Can', 'gul-ve-can-osman-erdogmus-amig9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül ve can 

Dalında bir gül görsem kaplar beni heyecan 

Dünya bir çöp eder mi sen yanımdayken gülcan 

Gülün ruhu kokuysa, benim ruhum da candır 

Hayatıma renk katan, sevda salan gülcandır 

Ömür kısa olsa da, dolsa hüzün ve kanla 

Dünya değil sadece, ahiretim gülcanla 

Güllere aşık bülbül, nasıl öterse candan 

Dünyam zindan olsa da ben vazgeçmem gülcandan 

Bu ihtiras bu hasret eritse de bu canı 

Güle tutkun yürekle seviyorum gülcanı 

Sevda dolu bir bakış çok mu seven insana 

Bir tebessüm tatlı dil, can kurbandır gülcana 

Bu kadar naz aşığı usandırır sonunda 

Benim nazlı çiçeğim, pembe gülüm gülcanda 

Peşinden gidilmez ki kapkara bir sevdanın 

Bulamadım dengini şu dünyada gülcanın 

Güllerime şaheser sadece bana sultan 

Dertlerime de derman olur musun be gülcan 

Osman ERDOĞMUŞ', 'Gül ve can  Dalında bir gül görsem kaplar beni heyecan  Dünya bir çöp eder mi sen yanımdayken gülcan  Gülün ruhu kokuysa, benim ruhum da can...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdoğmuş']::text[], 8.5, '{"poet":"Osman Erdoğmuş","poet_slug":"osman-erdogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-ve-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncitme', 'i-ncitme-murat-kilic-2-eb9yt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüreğimde sana ait kurumaz yaşlar var

hepsi seninle yaşıyor sevgimi reddetme

tanrının önünde bile eğilmez başlar var

senin önünde eğilen; gönlümü incitme

bahtiyar olurum yolun olur yollarım

sana muhtaç kalsın ne çıkar yıllarım

gidersen kuruyup kırılır dallarım

kaderine tutukludur; hüznümü incitme

yazdığın tüm mektuplar yığınla masada

yokluğunda gönlüm gam kederde; tasada

bütün mevsimlerin yaz bahar olsada

sen yine de gülüm; gülümü incitme

sal beni bilinmez azaplara, ben çekerim

pınarların kurumasın, yerine yaş dökerim

rüyalarıma gelmez isen boyun bükerim

hayalinle uykusuz kalan; yüzümü incitme

sen baharlardan öte goncalardan güzelsin

tek dileğim o ki; yalnız bana gelesin

uğrunda can veririm bunu böyle bilesin

kollarında can verirsem; ölümü incitme', 'yüreğimde sana ait kurumaz yaşlar var hepsi seninle yaşıyor sevgimi reddetme tanrının önünde bile eğilmez başlar var senin önünde eğilen; gö...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/incitme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel desen de demesen de', 'gel-desen-de-demesen-de-nazmi-orsel-hosoa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gel demesen de,

Kapıdan da kovsan,

Baca beni çağırır.

Ah be güzelim,

Seni görmesem saçlarım ağarır..', 'Sen gel demesen de, Kapıdan da kovsan, Baca beni çağırır. Ah be güzelim, Seni görmesem saçlarım ağarır.....', ARRAY['Türk Edebiyatı','Şiir','Nazmi Örsel']::text[], 8.5, '{"poet":"Nazmi Örsel","poet_slug":"nazmi-orsel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gel-desen-de-demesen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçler Dışlar Çarpımı', 'i-cler-dislar-carpimi-selahattin-durna-xyrhq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçler Dışlar Çarpımı

Sizi bir yerlerden gözüm ısırıyor,

Gerçekten siz,siz misiniz

Durun hele,

Ne çok değişmişsiniz.

Siz hatırlamazsınız,ip atlarken bacaklarınıza bakardım.

Kaydıraktan kayarken,salıncakta…

Daracık pantolonlar giyerdiniz,

Kısacık etekler..

Çocuk günahlar kotardım; bilmezsiniz.

Ne çabuk büyüdünüz böyle,

Ne çabuk yaşlandınız

Daha okul çıkışı peşinizden gelecektim

Daha ıslık çalacaktım arkanızdan

Bahçe kapınıza çiçekler bırakacaktım geceleri

Gündüzleri ayna tutacaktım pencerenize

Hayret bi’şeysiniz,daha size

Arkadaşlık teklif edecektim.

Ne zaman evlendiniz,

Ne çabuk böyle çoluk çocuk,torun morun..

Daha duvarlara adınızı yazacaktım

Kalp resimleri çizecektim ağaç dallarına

İçinden oklar geçen

“I love you”lu balonlar bağlayacaktım 

 Balkon korkuluğunuza

Daha “seni seviyorum” diyecektim.

Kulaklarınız ağır mı işitiyor ne

Hayret bi’şeysiniz,güzel sözler öğrenmiştim

Güzel şiirler ezberlemiştim oysa ben

Sevda türküleri…

Ilık düşler fısıldayacaktım,ıslak düşler fısıldayacaktım daha

Bir kuzuyu sever gibi,

Bir kediyi okşar gibi düşledim sizi ben.

Ne çabuk buruşmuş elleriniz böyle

Ne çok kilo almışsınız.

Saçlarımı yıkayıp gelecektim,

Traş olmaya gitmiştim,az bekleseydiniz.

Bi koşu gidip çoraplarımı değiştirecektim

Tırnaklarımı kesecektim,niye beklemediniz.

Hayret bi’şeysiniz,alt tarafı

Dişlerimi fırçalayacaktım,kaç dakka sürer

Bir arkadaştan borç para bulup gelecektim

Geldim işte.

İnanmam,otuz beş yıl mı oldu siz beni görmeyeli,

Çok şakacısınız,gerçekten üçüncü evliliğiniz mi

Sizi bir yerlerden gözüm ısırıyor,

Gerçekten siz,siz misiniz

Durun hele,

Ne çok değişmişsiniz', 'İçler Dışlar Çarpımı Sizi bir yerlerden gözüm ısırıyor, Gerçekten siz,siz misiniz Durun hele, Ne çok değişmişsiniz. Siz hatırlamazsınız,ip a...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/icler-dislar-carpimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Aydınlık', 'hoscakal-aydinlik-cenk-aksal-ly9b5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her saat başı çalan

karanlık....

aydınlıklar içinde yüzün,

mavi hüznün sessizliği,

hüküm sürüyor:

görüyormusun? 

çala kalem yazılmış sanki,

kader defterine sonumuz! 

bütün dertlerimiz:

terazinin bir kefesin de...

dingin aydınlıkların ortasında:

karanlık yollarımız,

mutsuz mutluluklar yaşanıyor

gönlümüzün aşk bahçesin de...

duyuyor musun? 

çalıyor bak:vuslat saati,,,,

ben hazırlandım gülüm,

karanlığın orta yerine...

hazırla sen de artık:

tüm yaşanan günlerin boğçasını:

gidiyoruz ikimiz de...

verilmemiş hesabımız kalmasın,

karanlık,aydınlıklar ülkesine..

gidiyoruz sevdiğim....

haydi aydınlık,hoşçakal...', 'her saat başı çalan karanlık.... aydınlıklar içinde yüzün, mavi hüznün sessizliği, hüküm sürüyor: görüyormusun?  çala kalem yazılmış sanki, ...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hoscakal-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Arınma', 'arinma-guclu-sonmez-v22ng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyanın kuzey yarı küresinde upuzun bir çöl

Buzdağlarının arasından yürüyen bir adam

Satılık ya da kiralık bir kalp taşıyan

Onun olmayan

Nasır tutmuş ayakları

Soğuktan ve sıcaktan

Yüreğinde duygunun her türünü tadan

Derin izler var kazılmaya devam eden

Bırakmak istenmeyen ama elden kayıp giden

Dış etkenlere burun kıvıran

Ona çevrili silahları görmeyen

Hedefi olduğu kurşunları hissetmeyen

Canı yanmayan ama yere yığılan

Kendinden geçen

Sonra gözlerini açan

Yüreğindeki deliğin girdabına esir olan

Kurtulmayı istemeyen

Sadece aşkı vuranlara acıyan

Çaldığı elmaları vermeyen

Direnen

Günahlarını sırtlayan

Taşıyan

Yalan aşklara

İnanan

Gerçeğini bulduğunda

Kaybeden

Aramak için yola koyulan

Ve tükenen

Yalnızlığa mahkum edilen...

Yağmur damlaları

Bir fincan kahve

Dizilmiş notalar

Yalnızlığa eşlik adında

Koyu turuncu sonbahar

Küçük göl kenarına

Uzanmış asırlık ağacın üzerine oturup

Dünyasını şekillendirmeye koyulmuş

Sonbahar gitmiş

Rengarenk yaz çıkmış karşısına

Ardında bıraktığı upuzun bir çöl ve buzullar

Yıllarca hatırlamak istemediği...

Yaz getirir aşkını ona

Başka bir yüz altında

Tanır gözlerinden

Ve gülümser bir daha

(İstanbul, Temmuz 2005)', 'Dünyanın kuzey yarı küresinde upuzun bir çöl Buzdağlarının arasından yürüyen bir adam Satılık ya da kiralık bir kalp taşıyan Onun olmayan Na...', ARRAY['Türk Edebiyatı','Şiir','Güçlü Sönmez']::text[], 8.5, '{"poet":"Güçlü Sönmez","poet_slug":"guclu-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/arinma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-i-lknur-er-ynrbt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Babam

Güzel yürekli babam

Kalbi pamuk, ruhu çocuk babam

Sersem oyuncaklarımı

Benden önce oturursun oyuna

Hiç doyamamışsınki çocukluğuna

Dahası çocuk olamamışsın

Baban denizde boğulunca

Sen doğru dağlara çobanlığa

Bedavaya da değil

Senelik kiralığa

Haberini almışsın annen evlenmiş

Kızmışsın ya 

Yinede

Seni annene götürelim diyenlere takılmış

İnekleri,kuzuları ormanda bırakıp koşmuşsun

Hem annenin kapısından kovulmuş

Hemde işinden olmuşsun

Ah babacığım ah

Yüzünün derin çizgilerine haretle bakardım

Bilmezdim içine neler gizlemişsin

Ne baba görmüşsün, ne ana, nede kardeş

Hepsinden uzak büyümüşsün ya

Sen hiç kardeşte olamamışsın babam

Bayramında olmamış senin

Çektiklerini anlatmaya

Yetmiyor 

Yüreğimde, kalemimde

Sıkıntıların ödülünü almışsın ya bizimle

Bir kız, bir oğlan

Sevgi görmemişsin ya

Göstermedin bizede

Olsun be babam 

Ben gözlerinden anlıyorum

Yinede', 'Babam Güzel yürekli babam Kalbi pamuk, ruhu çocuk babam Sersem oyuncaklarımı Benden önce oturursun oyuna Hiç doyamamışsınki çocukluğuna Daha...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/babama-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak Bebek', 'oyuncak-bebek-umit-demir-0b7tt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dar bir sokakta vuruldum anne

hava karanlıktı, biraz da soğuk

bir köpek öldüren için bıçakladılar beni

bir kaç tane zeytin, bir dilim peynir

bilmem ki benim gibi garipten ne istenir

fotoğrafın vardı cebimde, bir de lanet sigaram

inan anne inan, o kadardı bütün param

yavruma, istediği oyuncak bebeği alacaktım

belki ben, ondan da çok mutlu olacaktım

oğlunun başına bu da mı gelecekti anne

yoksulluğumu yaşarken 

ve yaşatırken size utanarak

terk edilip ölüme bir sokak arasında

cebimden de yavrumun mutluluğu alınarak

gözlerim açık mı gidecekti bu dünyaya

n'' olursun kapat gözlerimi anne

utanıyorum yaşlı gözlerinle göz göze gelmeye

tiksiniyorum bakmaya, bu kokmuş düzene

değer miydi anne beni bir günaha satmaya

değer miydi yavrumun mutluluğunu çalmaya

artık kapat gözlerimi anne hayata

ve alıver oyuncağını benim güzel yavruma', 'dar bir sokakta vuruldum anne hava karanlıktı, biraz da soğuk bir köpek öldüren için bıçakladılar beni bir kaç tane zeytin, bir dilim peynir...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyuncak-bebek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-umit-demir-dgmlb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biraz gülsene, gül yüzlüm

anlarsan, gül bana, bal sözlüm

ağlarsan, gül sana, al gözlüm

gül bana, gül sana, gül bize

gülersen göz değer mi bu yüze

biraz gelsene sel yüzlüm

akarsan, sel sana, kem sözlüm

bakarsan, sel bana, kin gözlüm

sel sana, sel bana, sel bize

gelirsen söz değer mi bu tene', 'biraz gülsene, gül yüzlüm anlarsan, gül bana, bal sözlüm ağlarsan, gül sana, al gözlüm gül bana, gül sana, gül bize gülersen göz değer mi bu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gulum-145-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşanmayın', 'bosanmayin-umit-demir-dneij', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'duydun mu bu iç ürperten çığlığı

zavallı bir çocuk ağlıyordu

gördün mü hep çekegeldiğimiz bu yarayı

orda, burda.... hep içimizde kanıyordu

sorma bana, neden deme

nedeni insandaki kahrolası ene

cevabı zor, sorma; neden, niye

nedeni bir baba, bir anne

bak yine bağırdı zavallı yavrum

bu, dağılan bir yuvanın yıkılma sesleri

''ayrılık olursa bu benim sonum''

doğruydu yavrucağızın masum hisleri

cevabı zor, sorma; neden, niye

nedeni bir baba, bir anne

dur, ağlama, bulunur elbet bir çare

ölümden başka her bir derde', 'duydun mu bu iç ürperten çığlığı zavallı bir çocuk ağlıyordu gördün mü hep çekegeldiğimiz bu yarayı orda, burda.... hep içimizde kanıyordu s...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bosanmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-umit-demir-6uffm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölüm meleği

bir ılık nisan ayında

bulsun beni

cenazeme gelenlerden

ne üşüsün bir kişi

ne de sıcaktan bunalsın

ölüm meleği 

bir seher vaktinde

bulsun beni

cenazem hemen kaldırılsın

namazımı az da olsa

aşıklar kılsın

ölüm meleği

bir beklenmedik anda

bulsun beni

cenazemin şekli 

yaşantımı yansıtsın

yalnızken mezarımda 

beni sevaplar sarsın', 'ölüm meleği bir ılık nisan ayında bulsun beni cenazeme gelenlerden ne üşüsün bir kişi ne de sıcaktan bunalsın ölüm meleği  bir seher vaktind...', ARRAY['Türk Edebiyatı','Şiir','Ümit Demir']::text[], 8.5, '{"poet":"Ümit Demir","poet_slug":"umit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dua-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin arka yüzü', 'siirin-arka-yuzu-orhan-tuncay-5luxy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanrılarla buğulanmış, kuşkuların ustası

Belagatta pek de güzel, lafazanlık yaftası

Gülüşleri zaten solgun hastalıklar hastası

Küçük oğlum en çapraşık  hor görmeyin amcası

Ortancası pek bi narin, hem saçları pileli

Biraz kaçık, her dem uçuk, bezirgandır hileli

Sağlam malzemeden kırılgandır bildim bileli

Okuyup üflemiş, ama kar etmemiş hocası

Büyüğü ne siz sorun ne ben söyleyeyim

Ettiği haltlardan Kaf dağına yol eyleyeyim

Onu şehzade kılıp bir masalda derleyeyim

Yine de bir tutam kötek atmak ona hakçası

Üç garip oğlumu sarmalayıp şiirde çattım

Mideme oturdular çıkıp kerevete yattım

Üzülürüm bakın, sanmayın palavra attım

Çevirince de pek hoştur şiirimin arkası.', 'Sanrılarla buğulanmış, kuşkuların ustası Belagatta pek de güzel, lafazanlık yaftası Gülüşleri zaten solgun hastalıklar hastası Küçük oğlum e...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirin-arka-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdam Sehpası', 'i-dam-sehpasi-gokhan-karaduman-dy1n5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün benimde 

Ölüm fermanım yazılırsa eğer

Gözlerim açık gitmeyim

İdam sehpasını sen kuruver.', 'Birgün benimde  Ölüm fermanım yazılırsa eğer Gözlerim açık gitmeyim İdam sehpasını sen kuruver....', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/idam-sehpasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-fatih-suretli-3snk0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çığlığım gecenin sessizliğini boğarken; 

Yalnızlığımın son şiirini yazıyorum.

Biraz tutsak,

Biraz suskundur mısralarım.

Yine divaneyim bu gece

Her sokak başında nara atıyor yüreğim! 

Ve yenik düşüyorum gecenin tılsımına

Sesin düşüyor soluksuzluğuma

Anlatamıyorum..... 

Yine dumanımla beraberim

Bu korkak gecede

Gökyüzü ürkek ve alabildiğine uzak

Koşmak istiyorum yıldızlara! 

Haykırmak istiyorum sevdamı! 

Sesin düşüyor soluksuzluğuma

Anlatamıyorum......

Şimdi en sersem halimle düşüyorum kavgaya

Bir başıma ve tutkun

Bir acayip oluyor bu geceler

Masalsı bir rüya gibi

Yüreğimde serseri bir sevda

Kavgamı alıp gelmek istiyorum

Sesin düşüyor soluksuzluğuma

Anlatamıyorum......', 'Çığlığım gecenin sessizliğini boğarken;  Yalnızlığımın son şiirini yazıyorum. Biraz tutsak, Biraz suskundur mısralarım. Yine divaneyim bu ge...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlatamiyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Sevgili', 'agla-sevgili-fatih-suretli-n6lyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağla sevgili; 

Gözyaşların aksın geceye

Geceler ki bu limanda

Kayıp bir gemi şimdi

Hasrete yenik kaç umut varsa

Gözyaşında boğulmalı artık

Çığlıklar can verirken

Karartıya boğulan gecede

Bir sesin kalmalı

Umudu haykıran

Ey sevgili; 

And olsun gözlerinin mavisine

Son ağlayışın olacak bu gece

Yıldızlar sönük kalacak

Ve deniz utanacak maviliğinden

Gözlerindeki gülüşün yanında

Güller açacak gönül bahçende

Ama hiç biri 

Senden güzel olmayacak

Ve sevgili; 

Artık umuda yolcusun

Umutsuzluğa inat', 'Ağla sevgili;  Gözyaşların aksın geceye Geceler ki bu limanda Kayıp bir gemi şimdi Hasrete yenik kaç umut varsa Gözyaşında boğulmalı artık Ç...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agla-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Anam Ah', 'ah-anam-ah-fatih-suretli-yr02v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah anam ah

Kaçıncı bahardır geçiyor

Bu kentin sahilinden

Farkına varmadan

Kaçıncı yaşım

Kaçıncı tükenişim darağacında

Yetmez mi artık

Karanlığa verdiğimiz

Umut dolu yürekler

Aha anam ah

Yar diye koynuma

Hasretler alır yatarım

İçtiğim sigaradan

Yanık bir tat kalıyor boğazımda

Hiç bir şeyin tadı yok

Ah anam ah

Uzanmak istiyorum

Gözlerinin derinliklerine

Yeniden emzirsen ben

Apak sütünle

Yeniden doğursan

Sonrada boğsan

Dicle’nin sularında

Aha anam ah

Biliyorum seninde gözleri yaşlı

Kan damlıyor yüreğinden

Ama anla beni

Sığınabildiğim tek limansın

Beni anlayan tek insan', 'Ah anam ah Kaçıncı bahardır geçiyor Bu kentin sahilinden Farkına varmadan Kaçıncı yaşım Kaçıncı tükenişim darağacında Yetmez mi artık Karanl...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ah-anam-ah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amed', 'amed-fatih-suretli-oo6iv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elveda Amed! 

Elveda yalnızlığımı paylaştığım sokaklar.

Bu gece yüreğimi,

Son defa bırakıyorum surlardan aşağıya.

Hayallerim ise; demli bir çay kıvamında kalsın.

Elveda yüreğimin yitik kenti! 

Gazi köşkü, Hevsel bahçesi.

Terkedilmiş kaderimin çocukları

Merhaba Dicle ırmağı

Al beni hırçın sularına

Asaletinden bir parça kalsın bende

Son bakışım bu sana Amed

Elveda yârime yarenlik eden

Sokaklar, parklar, çay bahçeleri

Dünyanın en güzel çiçeğini

Senin kalbine gömüyorum

Soldurma sakın yüreğini,

Yüreğimi yüreğine bırakıyorum.', 'Elveda Amed!  Elveda yalnızlığımı paylaştığım sokaklar. Bu gece yüreğimi, Son defa bırakıyorum surlardan aşağıya. Hayallerim ise; demli bir ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Suretli']::text[], 8.5, '{"poet":"Fatih Suretli","poet_slug":"fatih-suretli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/amed-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anı', 'bir-ani-muharrem-cetinkaya-nv0g8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolda gördüm

Tanıştık,

İran''lı..

Çat pat Türkçe,

......Arapça,

Derken Farsça.

Anlattık hoş-beş.

Kalender bi- delikanlı...

Dedim var mı sizde; 

Almak Dört karı*? 

................................

Derin bir ah çekti; 

Nerdee....! 

Niye,dedim; 

Derler ya:''Bir çiçek....bir yazla? 

Boynunu büktü,

Bizim yiğit delikanlı; 

-''Birinin yarısı bile fazla! ''

*Karı:sözcüğü sözün gelişi söylenmiş olup,tüm bayanları tenzih ederim.', 'Yolda gördüm Tanıştık, İran''lı.. Çat pat Türkçe, ......Arapça, Derken Farsça. Anlattık hoş-beş. Kalender bi- delikanlı... Dedim var mı sizde...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-ani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahta Kapı', 'tahta-kapi-mustafa-dilki-uoa94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşaymış gönlümün tüm emekleri

Sonunda anladım ben gerçekleri

Elimde kalırken kır çiçekleri

Yüzüme kapandı bir tahta kapı

Açıldı kalbimde derin bir yara 

Teselli vermiyor içki sigara

Maviye boyalı altı numara

Yüzüme kapandı bir tahta kapı

Bir sonbahar günü on yedi ekin

Ben onulmaz hasta o Lokman Hekim

Bu kadar severken oyun eden kim

Yüzüme kapandı bir tahta kapı

Sonunda bir avuç gözyaşı karım

Dağılmaz bir türlü derdim efkarım

Oradan geçmeye artık korkarım

Yüzüme kapandı bir tahta kapı', 'Boşaymış gönlümün tüm emekleri Sonunda anladım ben gerçekleri Elimde kalırken kır çiçekleri Yüzüme kapandı bir tahta kapı Açıldı kalbimde de...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tahta-kapi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miniciğim', 'minicigim-i-lknur-cekici-63txs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim herşeyim

Birtanem gözbebeğim

Mutlu eden tek eşim

Gonca gülüm biriciğim

Yaşayamam sensiz

Gidersen hiç sebepsiz

Ölmemi istiyorsan

Nereye istersen git bensiz

Yeşil gözlüm miniciğim

Sırma saçlım bal dudaklım

Sevgimi anla yeter

Ellerinde yüreciğim', 'Sen benim herşeyim Birtanem gözbebeğim Mutlu eden tek eşim Gonca gülüm biriciğim Yaşayamam sensiz Gidersen hiç sebepsiz Ölmemi istiyorsan Ne...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/minicigim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvim Yaprakları', 'takvim-yapraklari-mustafa-dilki-mcexb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu Zamansız ayrılık uzadıkça uzadı

Günden güne artıyor saçlarımın akları

Artık beklemek oldu bende sevdanın adı

Bu kaçıncı dökülen takvimin yaprakları

Gönül bir vefasızın sevdasına inandı

Yalandı bakışları sözleri hep yalandı

Yıllar yılı izledi aylar aya bağlandı

Bu kaçıncı dökülen takvimin yaprakları

Kadersiz benim aşkım ta başından kadersiz

Mümkün değil bir günüm geçip gitsin kedersiz

Vefasızın şu benim hallerimden habersiz

Bu kaçıncı dökülen takvimin yaprakları', 'Bu Zamansız ayrılık uzadıkça uzadı Günden güne artıyor saçlarımın akları Artık beklemek oldu bende sevdanın adı Bu kaçıncı dökülen takvimin ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/takvim-yapraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Sevgili', 'kayip-sevgili-ufuk-coban-k9jg0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum bir yerlerde beni bekliyorsun,

Yoksa olmazdı yaşamaya umudum

Hayatım hep seni aramakla geçse de

Gücüm hep var olacak dayanmaya.

Sonum bir gülüş olacak kalbinde, bunu hep düşlüyorum,

Sevgim parlayacak gözlerinin yağmurunda.

Karşında olacağım, derken kapılıp geldim fırtınaya,

Tanrı misafiriyim gönlüne, kilit vurma kapılara,

Geçit bulunamazsa bu fırtınaya, tekrar döner tanrıya.

Sen de düşler misin beni geceleri? 

Karanlığına ışık yapar mısın beni? 

Ya da ıssızlığında soğuk bir ürpertinin,

Gücü olur muyum gözlerinin? 

Bu belki özlemi bir sevgilinin

Ama değil herhangi birinin, kesinlikle senin.

Kim olduğunu biliyorum, henüz adını bilmesem de gözlerinin

Bulduğumda sığdıramam sevgimi bir güne, hani şu buluştuğu sevgililerin.

1999', 'Biliyorum bir yerlerde beni bekliyorsun, Yoksa olmazdı yaşamaya umudum Hayatım hep seni aramakla geçse de Gücüm hep var olacak dayanmaya. So...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kayip-sevgili-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlu...', 'bulutlu-ali-baksi-tdqtb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geldigim  gittigim düm cadde kaldırımları

Taşırmısınız bir daha akşamlara ve sabahalara

Baktıgım ilk bahar çicegim al beni doyumsuz kokunda

Sevdigim ilk kestane ne olur bir dalda ben olayım kollarında

Yarınım olacakmı bilmiyorum martılarla tutunayım bulutlarına

Sevğiyi ve saygıyı arıyorum cıkmazımda dar agacımda kollarında

Ardı sıra gelip gitmelerde ölümün korkusu ve durgunlugu var gülüşlerimde

Soruyorum yarınım varmı bir daha ilbaharda dokunmak koklamak icin

Aglayabiliyorum gülebiliyorum saatlerce sana varan son duragımda

Koşuyorum varmak istedigim dar sokaklardan martılarla bahara

Giden yolcu sen ve ben bilemedigimiz yelkenle fora

Dönermiyiz tekrar aynı koya belkilerimiz var bahara

İlk günkü gibi severmiyiz her gün daha 

Ardıma bakıyorum tatlı acı anılarla

Ben mutluyum ve umutlu yüregimde sen ve benler

Sen benim en büyük kaderimsin kazandıgımyaşamda

Bulutlu akşamın koynunda seni seviyorum bir daha

Kırılmadı yürekler sede bir tutam acı bıraktı sonsuza

Unutmadı hatıralar gönüllerin koynunda sonbahara kadar

Dualar ediyorum bu sözlerimin hepsi sana ne olur bir şans daha

Bulutlu akşamlara sabahlara her defasında ilk ve son defelarca seviyorum...', 'Geldigim  gittigim düm cadde kaldırımları Taşırmısınız bir daha akşamlara ve sabahalara Baktıgım ilk bahar çicegim al beni doyumsuz kokunda ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulutlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Nerde?', 'hani-nerde-mehmet-demir-atmali-2odqq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerde Osmanlı Kadını? 

Tarihe vermiş adını...

Zamane kadınına bak; 

Feminist koymuş adını...

Biri top mermisi taşır,

Mezarı cephede üşür...

Biri süs köpeğiyle yaşar.

Hümanist koymuş adını..

23.8.1994', 'Nerde Osmanlı Kadını?  Tarihe vermiş adını... Zamane kadınına bak;  Feminist koymuş adını... Biri top mermisi taşır, Mezarı cephede üşür... ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hani-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Parakende Yürekler...', 'ah-su-parakende-yurekler-ugur-bilgi-opvvu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özgürlüğüdür yüreğimizin sevgiler,

Bir tebessüme ömür yakanlardanız.

Kimse yakıştırmasın köleliğin zincirini,

Halka halka prangaları kıranlardanız.

Bir yanımızda bülbülce sevdalar tütsede,

Bir yanda korları sineye basanlardanız.

Sanılmasınki mazlumcadır duruşumuz,

Zamanı gelir öfkelerde kusanlardanız.

İsteyenin olsun parakende,

Parça bölük duygular,

Olduğu gibi yüreğindekileri

Yaşayanlardanız..', 'Özgürlüğüdür yüreğimizin sevgiler, Bir tebessüme ömür yakanlardanız. Kimse yakıştırmasın köleliğin zincirini, Halka halka prangaları kıranla...', ARRAY['Türk Edebiyatı','Şiir','Uğur Bilgi']::text[], 8.5, '{"poet":"Uğur Bilgi","poet_slug":"ugur-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-su-parakende-yurekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rûya', 'r-ya-mustafa-dogan-kuzgun-7m62v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece yatarken yatakta

Çok güzel kâbus gördüm, sanki rûya

Ormanların derinliğinde, yeşil çimenlerin içinde

Balta girmemiş ağaçlıklarda

Yürüyorum bilmediğim yollarda,

Yürüyorum...

Yürüyorum...

Bilinmezliğe doğru yol alıyorum.

Bir ışık, bir parıltı gözüme ilişiyor

İki maymun bir biriyle didişiyor.

Uzun ağaçların gölgeleri donduruyor,

Kuru otların üzerine düşen güneş kavuruyor.

Ben gittikçe ışık büyüyor, küçülüyor...

O da ne! 

Işık yok oluyor, her taraf kararıyor

Bütün hayvanlar bağırıyor, kaçıyor.

Ama hiç biri bana dokunamıyor.

Karanlık, her yer karanlık...

Göz gözü görmüyor.

Ben daha hızlı yürümeye başlıyorum,

Beni kendine çeken ışığı arıyorum.

Görüyorum! ..

Ama bu ışık gözlerimi kamaştırıyor

Yine de görüyorum.

O da ne! 

Biri bana bağırıyor.

Olamaz! ..

Hayır olamaz! ..

Tüh be, kardeşim uyanmış ağlıyor.', 'Dün gece yatarken yatakta Çok güzel kâbus gördüm, sanki rûya Ormanların derinliğinde, yeşil çimenlerin içinde Balta girmemiş ağaçlıklarda Yü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruya-187-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke (2)', 'keske-2-mustafa-alpaydin-5evis', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Salınarak gezinirdin hayran idim tavrına

Gönül bahçemde yerin kurulmuşsun tahtına

Seni bana versin diye çok yalvardım anana

Sevgim artık kine döndü üzülürüm çabama.

Pasta küçük olmuş dedin nişanda surat astın

Nikah günü tez davrandın ayağıma sen bastın

Hep bir adım önde gittin bana yol bırakmadın

Tebrikler olsun güzelim kendi kuyunu kazdın.

Tahammül kalmadı bende ne işteyim, ne güçte

Hemen döneceğim derdin her gezmeye gidişte

Kaprislerin sebep oldu yuvan yıkıldı işte

Seni anan benim için doğurmasaydı keşke.', 'Salınarak gezinirdin hayran idim tavrına Gönül bahçemde yerin kurulmuşsun tahtına Seni bana versin diye çok yalvardım anana Sevgim artık kin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keske-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-mustafa-alpaydin-qwoja', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertli olan çeker çile

İsyan etme hayır dile

İpe unu sermek bile

Maharettir derler dostum.

Bülbül aşık olmuş güle

Nazlanırmış gül bülbüle

Sevgiliyi sarmak bile

Yürek ister derler dostum.

Önce iş sonra aş gerek

Bütün bunlar ister emek

Bekarlara avrat dövmek

Kolay gelir derler dostum.', 'Dertli olan çeker çile İsyan etme hayır dile İpe unu sermek bile Maharettir derler dostum. Bülbül aşık olmuş güle Nazlanırmış gül bülbüle Se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın ibresi', 'yasamin-ibresi-yahya-akbulut-yvzob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Figanı düşerken sararmış yaprakların,

çelikten örülmüş sandığım 

ağaçlarından

Kasvetli rüzgara kokuyordu,

küçüklüğüme dokunuyordu

Yaşamın ibresi babamın 

gözünde.

Çocuk değilsin sen, diyordu

çocukluğumda bile.

Doğalmış meğer, yıllar geçti.

Babam bana - sen büyüdün 

asla demedi! 

Ben şimdi bilgeli gibi

sanki yeni doğan.

Erken doğduğumu sandığım

zaman zaman kavgaların peşinde.

Savaşıyorum mimarisiyle

çocuk ve orta yaşlılığımın,

beyaz kağıt üzerinde...

Akıntıya veriyorum

ağızımdan düşen kelimeleri.

Boyun eğmeden kıyasıya 

yarışıyorum kızıl korlar üzerinde,

kaçarken pusudan...

Yaşayan bir ölüden ziyade

Yaşlanmış çocuk olma 

korkusundan.

01.07.2005 / Çorlu', 'Figanı düşerken sararmış yaprakların, çelikten örülmüş sandığım  ağaçlarından Kasvetli rüzgara kokuyordu, küçüklüğüme dokunuyordu Yaşamın ib...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasamin-ibresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüyor Yine Sevda Gülü Yalnızlığıma', 'donuyor-yine-sevda-gulu-yalnizligima-goktu-kara-hc4wu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kış kesiyor saçlarımı

gözlerim ırak yollarla keşisiyor

düşlerim yapraklarla bezenmiş

dönüyor yine sevda gülü yalnızlığıma

derince mutluluklar diyarına

açılan yelkenliler

köpüklü dalgalarla sana geliyor', 'kış kesiyor saçlarımı gözlerim ırak yollarla keşisiyor düşlerim yapraklarla bezenmiş dönüyor yine sevda gülü yalnızlığıma derince mutlulukla...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/donuyor-yine-sevda-gulu-yalnizligima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzüne Karşı', 'huzune-karsi-sait-kucuk-egq8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bayrak

Açtı

Yüzümdeki 

Gülücük', 'Bayrak Açtı Yüzümdeki  Gülücük...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/huzune-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Yalnız Koyup', 'beni-yalniz-koyup-hasan-cam-n6wyy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni yalnız koyup gitme diyara

Gitme diyara

Ellerin olup da gül mü açarsın

Gül mü açarsın

Sevdim seni neden böyle kaçarsın 

Böyle kaçarsın

Gurbetim sılasız nasıl yaşarsın

Nasıl yaşarsın

Sevda doluydu hep benim bağlarım

Benim bağlarım

Kader vurdu neden ayrılığımız

Ayrılığımız

Hani nerde bebiş yavrularımız

Yavrularımız

Hep dillerde kaldı anılarımız

Anılarımız

Ben ölünce biter acılarımız

Acılarımız

Hayat neye yarar sen olmayınca

Sen olmayınca

Kışlar kaplar beni sen sarmayınca

Sen sarmayınca

Baharımsın benim gülüm olunca 

Gülüm olunca 

15,07,1986…

Türkü (söz müzik Hasan Çam)

Ümraniye istanbul', 'Beni yalnız koyup gitme diyara Gitme diyara Ellerin olup da gül mü açarsın Gül mü açarsın Sevdim seni neden böyle kaçarsın  Böyle kaçarsın G...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/beni-yalniz-koyup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koyusundayım Gecenin...', 'koyusundayim-gecenin-arzu-gulucudur-i26iu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koyusundayım gecenin

Ortasında...

Soğuyor nefesim adını anışlarda

A- dın! ! ! 

Akıyor kekeme dilimden

Ve çağlıyor gece

Soğuğa inat...

Ecel terleri boşalıyor 

Solgun benizlerden

Ve sen 

Dökülüyorsun gözlerden...

Ve sen 

Kayıyorsun yüreklerden

Ve sen

Yükseliyorsun nidalardan

Adın karışıyor sessiz sokaklara

Eller  buruk 

Elvedalarda

Bir sen bakıyorsun ardın sıra

Bir eller sana elveda...

Gecenin koyusundayım ben

Ortasında

Nefesim soğuk

Adın akıyor gece çağlıyor... 

Gece ağlıyor.....', 'Koyusundayım gecenin Ortasında... Soğuyor nefesim adını anışlarda A- dın! ! !  Akıyor kekeme dilimden Ve çağlıyor gece Soğuğa inat... Ecel t...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/koyusundayim-gecenin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köpekler Kadar', 'kopekler-kadar-ahmet-cagri-ozsema-nu15x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Köpekler istedikleri yere

gidebiliyorlar,

yemeği bedava buluyorlar,

istedikleri yere pisleyip

istedikleri yerde

istedikleriyle sevişebiliyorlar.

Kaçımız köpekler kadar

insanca yaşayabiliyor acaba?', 'Köpekler istedikleri yere gidebiliyorlar, yemeği bedava buluyorlar, istedikleri yere pisleyip istedikleri yerde istedikleriyle sevişebiliyor...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çağrı Özsema']::text[], 8.5, '{"poet":"Ahmet Çağrı Özsema","poet_slug":"ahmet-cagri-ozsema","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kopekler-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-pelin-goktekin-olrku', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yerlerde düğün var.

Davul sesleri yarıyor şehrin sessizliğini,

Çok uzaklarda ölümler var.

Ve şehirde koca bir sessizlik.

Yine gidenler var gönüllerde,

Ve kırılan kalplerin acı çatırtıları.

Çok uzaklarda dalga sesleri var.

Ve martıların dansı mehtapta.

Bir bebeğin doğuşu var uzaklarda,

Ve saniye saniye alınan soluklar.

Bir çiçeğin tomurcukları açılıyor toprakta,

Ve toprakların buram buram kokusu.

Ay eşlik ediyor onlara,

Ve ay yeni doğan sabaha koşuyor.

Yine bir el sallanıyor giden vapurun ardından,

Yağmurlar ağlıyor

Pul pul yaşlar dökülüyor ellerime.

Limanlarda hiç bitmeyen ayak izlerim

Yine vapurları bekliyorum

Yine sana gelmek için aynı yollardan geçiyorum.

Haplarımı alıyorum ellerime,

Sensizliğin acısını çektiğim günlerde,

İçtiğim haplarımı içiyorum yine,

Acımı birazcık olsun dindirsin diye.

Son adresim limanlardayım yine.

Ve her bekleyişte,

Gözyaşım var ellerimde.

Geleceksin biliyorum,

Ve her limanda beni bulacaksın

Elimi salladığım o limanlarda

Koptu bileklerim.

Siyahlara bürünmüş yaslardayım sevgilim.

Yine yapraklar dökülüyor,

Yine sonbahar ve yine ayrılık var.

Hiç dönmedin ki sevgili

Nasıl ayrılık çanları çalar.', 'Bir yerlerde düğün var. Davul sesleri yarıyor şehrin sessizliğini, Çok uzaklarda ölümler var. Ve şehirde koca bir sessizlik. Yine gidenler v...', ARRAY['Türk Edebiyatı','Şiir','Pelin Göktekin']::text[], 8.5, '{"poet":"Pelin Göktekin","poet_slug":"pelin-goktekin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/liman-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Varmı?', 'dost-varmi-omer-kucukkaya-qxnni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zaman içinde durak varmı? 

duran için zaman varmı? 

kelin öncesinde saç varmı? 

saçın sonrasında kellik varmı? 

adımı yazımı nazımı çekecek 

bu dünyada bir dostum varmı? 

var diyen dostumun 

bana bir mesajı varmı? 

sen kimsin diyenin 

benle tanışacak mecali varmı? 

allah söyletir dostluğu 

üfürür yağmurlar kuruyu 

bir dosttan mesajn alsak 

bizde buluruz doğru yolu....', 'zaman içinde durak varmı?  duran için zaman varmı?  kelin öncesinde saç varmı?  saçın sonrasında kellik varmı?  adımı yazımı nazımı çekecek ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dost-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve İnsan', 've-i-nsan-omer-kucukkaya-ipcpk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşamak susmak değil hareket göstermektir

hareket göstermek eyleme geçmektir

eylem camları kırmak değil

kalpleri onarmaktr

ve birtek insan oğludur

eylemi acıya

hareketi zarara

verdiği zarardanda kâra geçen...', 'yaşamak susmak değil hareket göstermektir hareket göstermek eyleme geçmektir eylem camları kırmak değil kalpleri onarmaktr ve birtek insan o...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ve-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelere sığınıyorum', 'gecelere-siginiyorum-yilmaz-ozturk-d8wod', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaçıyorum herşeyden ve senin hayalinden

Gece görmüyor gözlerim karanlığın içinden

Gündüz baktığım her canlı yerde sen varsın

Gecelere sığınıyorum kaçmak için senden 

Ne sevdiğin bellibeni; nede sevmediğin 

Acı çekiyorum bu merhametsizliğinden

Hergün çileliyim hayali gözümde gözlerinin

Geceye sığınıyorum kaçmak için gözlerinden

Geceler saklıyor beni bendeki senden

Her gece dertleniyorum sendeki benden

Bilmiyorum ne haldeyim gece karanlığından

Sığınıyorum geceye kaçmak için hayalinden', 'Kaçıyorum herşeyden ve senin hayalinden Gece görmüyor gözlerim karanlığın içinden Gündüz baktığım her canlı yerde sen varsın Gecelere sığını...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecelere-siginiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasan’ a Mektup /12 (Özeleştiri)', 'hasan-a-mektup-12-ozelestiri-ahmet-turan-altunsu-v0ntg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(candaş’ a, kandaş’ a, karındaş’ a selâm olsun!) 

ah be Hasan 

çaldılar ağzımıza bir parmak bal 

sanırsın bağ bağışlamışlar 

oysa, ortada ''''ne rütbe var ne de mal! ..'''' 

bu adam mı çok aptal? .. 

''''cep delik cepken delik''''

üstelik 

cem etmişler de varını yoğunu

alt alta toplamışlar 

çıka çıka bir ''''adam'''' çıkmış 

iki çocuk, bir de kadın 

bir başına yaşamı sırtlamış 

yani ''''adam'''' adeta hamal! ! ! 

buyruklarına âmâde efradın(!) 

yani Hasan 

doğuşumuz bir ilmî hal 

yaşamımız baştan sona ihmâl! 

büyük hâkîm çoktan kırmış kalemini 

-uygulanacaktır hüküm behemehal! - 

budur işte çetelemiz Hasan 

budur ahvâl 

hoşça kal... 

__________________ 08.08.2005 / Ankara

_________________ Ahmet Turan Altunsu', '(candaş’ a, kandaş’ a, karındaş’ a selâm olsun!)  ah be Hasan  çaldılar ağzımıza bir parmak bal  sanırsın bağ bağışlamışlar  oysa, ortada ''''...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hasan-a-mektup-12-ozelestiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fanatik bir fenerliyim', 'fanatik-bir-fenerliyim-husamettin-guven-22us4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'fanatik bir taraftarim

ben fenere hastayim

yenilince yastayim

fanatik bir fenerliyim

olsemde donmem ben

bu fenersiz olmam ben

basariya doymam ben

fanatik bir fenerliyim

hep ilk-leri yapariz

cimboma[6] atariz

[4] yildizi takacagiz

fanatik bir fenerliyim', 'fanatik bir taraftarim ben fenere hastayim yenilince yastayim fanatik bir fenerliyim olsemde donmem ben bu fenersiz olmam ben basariya doyma...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fanatik-bir-fenerliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecemde', 'gecemde-tuncay-akdeniz-pov0z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hanı gönül senden bir şey ummuştu

Mehtabı olmayan ayı gecemde

O uykusuz gözler bana uymuştu

Hayalımda zülfün boyu gecemde

Her gün yanıyorum geçen anıma

Sevdanı çektirdim tatlı canıma

Hayalinden başka gelmez yanıma

Sessiz sevdaların koyu gecemde

Nice sevdalılar yandı çölünde

Kuşlar bile feryat etti gölünde

Fırtına kopardın meltem yelinde

Dalgaların dansı toyu gecemde

Uykudan uyandım rüyamı yordum

Bu kabuslar nedir geceye sordum

İsyan ettim aşkın kalbini kırdım

Attığın okların yayı gecemde

Tuncay’ım karanlık her dem gecesi

Aşkın okunmaz ki satır hecesi

Bu aşkı sevdayı çeker nicesi

Ahuzar figanın vayı gecemde', 'Hanı gönül senden bir şey ummuştu Mehtabı olmayan ayı gecemde O uykusuz gözler bana uymuştu Hayalımda zülfün boyu gecemde Her gün yanıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecemde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancisin', 'yalancisin-husamettin-guven-biira', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'cok guzel bir rol oynadin

insanlari bak aldattin

bolkeseden hep sen attin

yalancisin, yalanci

nerden icap etti oyle

streslimi gunun soyle

oldunmu desarj boyle

yalancisin,yalanci

yalanlara yer yoktur

bosversene karnim tokdur

inancim tek durustluktur

yalancisin, yalanci', 'cok guzel bir rol oynadin insanlari bak aldattin bolkeseden hep sen attin yalancisin, yalanci nerden icap etti oyle streslimi gunun soyle ol...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalancisin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Insanlarla oynamayin', 'insanlarla-oynamayin-husamettin-guven-d97ia', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sahtekarlik yaparak

herkesi aldatarak

bol palavra sikarak

insanlarla oynamayin

bakin sizde insansiniz

birgun gelir dusersiniz

sonra ahlar cekersiniz

insanlarla oynamayin

severseniz gercek sevin

insanlari horgormeyin

seytana siz es olmayin

insanlarla oynamayin

hic sevmeye bilirsiniz

onursuzca oynarsiniz

kalp''''leri bak kirarsiniz

insanlarla oynamayin', 'sahtekarlik yaparak herkesi aldatarak bol palavra sikarak insanlarla oynamayin bakin sizde insansiniz birgun gelir dusersiniz sonra ahlar ce...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanlarla-oynamayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Bir Ezginin Güftesinde', 'yarim-bir-ezginin-guftesinde-vedat-koparan-cll43', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman buz tutan 

Donmuş bir dal ucuydu 

Gidip gelinmezde 

Oysa istemler ne çok 

Fırat geçerdi 

İçimizin yangınından 

Gece kaçakları uykusunda

Dicle ağlardı 

Munzur’da bir dağ lalesi 

Bir gül haresi kanardı 

Gavur dağları 

Derin koyların sancısı

Kaç kesik başın söyler ağıtını

Ah boynu bükük bebelerim

Benliğimin kırgın güneşi

Anadolu’m ateş alımı al yalımı 

Karadeniz’im kararmasın dalgaların 

Ak mavi köpüklerin hep çağlasın

Geçit ver Zigana geçit duy bu feryadı 

Akdeniz’im ak akabildiğince

Yanıktır narenciye kokuları içinde

Ak pamukta karayağız  canları 



Ege’de kararmasın şafaklar

Uyumasın dağlar uyumasın

Aksın su derya yatağında 

Marmara’da kırık bir dalga 

Yangın mavilerinde akar hep sana 

Sarınır solgun sarı ateş topuna 

Kaç mevsim açar 

kaç bahar gönenir 

Boynu bükük yediveren güller

Gelmek istedikçe gelememeler

Rehin, tutuk kaldığım

Uzun,uzak mı  o denli yollar

Kırık bir gül dalıdır sevdan 

Yinede kendindedir çoğalman

Karşı konulmaz sarı sıcak 

Ülkemin  nasırlı elleri çatlak 

Elleri ki dal budak pıtrak

Tarihin imbiğinden çektim sesleri 

Gidenler gitti duydum nice nefesleri 

“Geleceğe öteledim özgür geçmişi”

Dinlediğim bir ezginin yarım güftesiydi

Vedat Koparan 08.08.2005

Şiir sever,yazan sevgili can kardeşim

Erkan Şenyiğit’le sohbetten ortaya çıkan

ve en sondan  3 cü dize kendisine aittir. 

çok teşekkürler  sevgiler kardeşime

yarım kalmasın dinlenen ezgiler 

saygı sevgiler

http://vedatkoparan.sitemynet.com/vurgun', 'Zaman buz tutan  Donmuş bir dal ucuydu  Gidip gelinmezde  Oysa istemler ne çok  Fırat geçerdi  İçimizin yangınından  Gece kaçakları uykusund...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/yarim-bir-ezginin-guftesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinsin çoçuk göz yaşları', 'dinsin-cocuk-goz-yaslari-yilmaz-ozturk-21iza', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gücüm olsaydı sevgi ekseydim

Ayrık otlarını çekip kopartsaydım

Her insan sevinçten gülsün isterdim

Acı keder yerine çoçuklar mutlu olsun

Her akşam sokakta sevgi saçsaydım 

Tebessüm eden insanlar görseydim

Ağlamasın gülsün gözleri çoçukların

Bir gücüm olsaydı bunları yapabilseybim

Allah`ım sen herşeye kadirsin niyetimizi

Biliyorsun amacım güldürmek yetimleri

Bir bayramda güldürmek bütün çoçukları

Senden dileğim dinsin çoçuk göz yaşları

Babalar anneler ağlamasın; sevinç çığlığı

Dolsun bütün evlere; yeryüzü tatsın insanlığı

Gülsün her insan ve hayvanların yavruları

Allah`ım ağlatma benden başka çoçukları', 'Bir gücüm olsaydı sevgi ekseydim Ayrık otlarını çekip kopartsaydım Her insan sevinçten gülsün isterdim Acı keder yerine çoçuklar mutlu olsun...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dinsin-cocuk-goz-yaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mihman', 'mihman-aydin-demirkan-kgdpx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani gülünce yüzün,

Güller açardı yollarımda

Sevince hani gönlün,

Bahar oluru bana...

Dakikaydı saatlerim,

Erirdim bakışlarında

İpek gibi saçlarında,

Bağlanırdım sana...

Elerin karışınca ellerime,

Uçardı yüreğim kuş gibi

Söyleyince sevdiğini,

Donardım bakışlarında...

Dua gibiydi sesin,

Seninle yalvarırdım Allah''a

Şarkıydı adın,

Hiç bitmeyen dudaklarımda...

Ve özlerdim seni,

Yanımdayken bile

Sen bitme isterdim,

Ben biterdim yollarında...

Verdiğim her gül,

Sönük kalırdı yanında

Yaksam sigaramı,

Yanamazdı benden fazla...

Mihman eyledim seni gönlüme,

Gidemezsin

And içtim yüreğime,

İstesen de bitemezsin...

Rüya mı yaşadığım,

Yo... hayır. Bu bir kabus

Bitmedin sen bende ama,

Gitti buralardan bensiz...

YOLUN AÇIK OLSUN SEVDİĞİM...', 'Hani gülünce yüzün, Güller açardı yollarımda Sevince hani gönlün, Bahar oluru bana... Dakikaydı saatlerim, Erirdim bakışlarında İpek gibi sa...', ARRAY['Türk Edebiyatı','Şiir','Aydın Demirkan']::text[], 8.5, '{"poet":"Aydın Demirkan","poet_slug":"aydin-demirkan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mihman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen`den Sen`i', 'sen-den-sen-i-yilmaz-ozturk-g5m0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu senede olmadı kısmet gitmek hacca

Tek dileğimdi varmak Ravza -ı Mutahhara

Allah`ım senden yardım isterdim insanlığa 

Ah bir tavaf edebilseydim Arşın ortasında

Önce tüm insanlara senden yardım isterdim

Sonra bütün Adem nesline sevgi dilerdim

Belkide biracık olsun kendime Af umardım

Bu senede kısmet olmadı seneye Kabe dilerim

Herkes toplanmış Kabe`de andırıyor mahşeri

Kimi istiyor Sen`den Sen`i ve cenneti

Kimisi diler günahına Resul şefaati

Allah`ım sen ver isteyene istediğini

Kabul et samimi kullarının ziyaretini

Senden dilerim bana kulum demeni

Bir tek dileğim sev sevdir bizi bize

Ayrılığı olmasın insanın insan içinde', 'Bu senede olmadı kısmet gitmek hacca Tek dileğimdi varmak Ravza -ı Mutahhara Allah`ım senden yardım isterdim insanlığa  Ah bir tavaf edebils...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Öztürk']::text[], 8.5, '{"poet":"Yılmaz Öztürk","poet_slug":"yilmaz-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-den-sen-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarın başında', 'mezarin-basinda-mikdat-bal-m8xxn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hürafeye inanırlar

Bir de bunu din sanırlar

Kapısına dayanırlar

Körler mezarın başında

Mezara akın ederler

O yatıra bak ne derler

Yardım et ey Falan derler

Gürler mezarın başında

Oğlum sınıfını geçsin

Kızım falanı eş seçsin

Kocam bir iş yeri açsın

Derler mezarın başında

Namaz oruç nedir bilmez

Ömründe camiye gelmez

Fakire yetime gülmez

Şerler mezarın başında

Ağlarlar dertli çefalı

Bir çoğu geri kafalı

Kitapları yıldız falı

Kirler mezarın başında

Türbeler insan doluyor

Kimi saçını yoluyor

Her derde derman oluyor

Pirler mezarın başında

Bal der sorun gelmiş dile

Şirktir. sabit ayet ile

Böyle nane bile bile

Yerler mezarın başında', 'Hürafeye inanırlar Bir de bunu din sanırlar Kapısına dayanırlar Körler mezarın başında Mezara akın ederler O yatıra bak ne derler Yardım et ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mezarin-basinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Hayat', 'sensiz-hayat-suleyman-yavuz-b73j5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz gecelerde

Ay vurmuyor yüzüme 

Yıldızlar parlamıyor canım

Gündüzleri hiç sorma gitsin

Ne güneş güneşe benziyor

Ne esen rüzgâr rüzgâra

Nede o bin bir renk çiçekler 

Sen varken ki gibi asla kokmuyor

Anla canım anla işte 

Burada hayat sensiz de sürüp gidiyor

Ama inan hiçbir şey 

Senin olduğun zamanki kadar 

Güzel olmuyor

Hiçbir şey sen yokken beni 

İnan mutlu etmiyor

Şunu bil ki canım 

Burada hayat sensizde geçip gidiyor

Ama inan her günüm yıl oluyor

Bu adam sensiz

Yok, olup gidiyor 

İnan bunu haktan başkası 

Bilmiyor

İnan bu âşık senden başkasını

Hiç sevmedi

Sevmiyor

Ve her günü dönecekmişsin gibi

Bekliyor.', 'Sensiz gecelerde Ay vurmuyor yüzüme  Yıldızlar parlamıyor canım Gündüzleri hiç sorma gitsin Ne güneş güneşe benziyor Ne esen rüzgâr rüzgâra ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensiz-hayat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet Bırakma', 'emanet-birakma-murat-ceylan-knvx0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Giderken bavulunun bir köşesine

Canımı da koymayı unutma

Biliyorsun, sensiz canım neye yarar ki

Zaten herşeyi ile bu can sensindi

Ne olur bu canı bedenimde emanet bırakma

                                                     Murat Ceylan', 'Giderken bavulunun bir köşesine Canımı da koymayı unutma Biliyorsun, sensiz canım neye yarar ki Zaten herşeyi ile bu can sensindi Ne olur bu...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/emanet-birakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Gözlüm', 'yildiz-gozlum-murat-ceylan-gb7z3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyada en çok sevdiğim iş geceyi beklemekti

Çünkü yıldızları izlemek vardı

Gecenin sessiz karanlığında

Hele birde gece gökyüzü bulutsuz ise 

Gel de çıkarma gecenin keyfini 

O uçsuz,bucaksız gökyüzüne bakarken

Bir tek şeyi arardım

Gökyüzünün en parlak  ve en güzel yıldızını

Hiçbir güzelliğe değişmezdim bu güzelliği

Ve hep aynı soruyu kendi kendime

Şu yalan dünyada bu güzelliğine bedel 

Başka bir güzellik var mı diye

Yıldızlarda bütün güzelliklerini gece sergilerlerdi

Sabah yaklaştı mı biraz sönerler sonra birden kaybolurlardı

Bundan mıdır bilmem sabahı hiç sevmezdim

Bütün gün boyunca gece olmasını beklerdim

Ama bir zaman sonra sabahı bekler oldum

Çünkü gözlerine derin derin bakınca anladım 

Dünyanın en güzel yıldızı gökyüzünde değilmiş

Senin gözlerin gökyüzündeki bütün parlak yıldızlara bedelmiş

Yıldızlar gökyüzünde durdukça

Gözlerin yıldızlar gibi parladıkça

Bende de bu güzelliği görecek yürek oldukça

Ne gözlerindeki yıldızlar söner,ne güzelliği gider

Ne de bu yürek seni sevmekten vazgeçer 

YILDIZ GÖZLÜM sen sen olda sakına

Gözlerini yıldızların güzelliğinden anlamayan

Birine emanet bırakma

Çünkü her zaman bulunmuyor 

Böyle YILDIZ GÖZLER

Bunu sakın unutma

                                                    Murat CEYLAN', 'Dünyada en çok sevdiğim iş geceyi beklemekti Çünkü yıldızları izlemek vardı Gecenin sessiz karanlığında Hele birde gece gökyüzü bulutsuz ise...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yildiz-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Değil Ölüm Yağıyor', 'yagmur-degil-olum-yagiyor-murat-ceylan-9hakt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün yağmur yağıyor sokaklara

Hatırıma sen geldin yine yar

Hatırlıyor musun yağmur yağıyordu ayrıldığımızda

Sen unutsan da unutmadı yaptığını bu diyar

Sen şimdi bir türkünün sıcaklığındasın

Ne zaman dinlesem bir türkü içim burkulur

Sanki yüz yaşımdayım da ölüm gibi aklımdasın

Belki bir gün gelirde her şey unutulur

Sen her şeyi çoktan unutmuşsundur 

Hayatında güzeldir bir çok şey

Biliyorum tatlı hayaller içinde mutlusundur 

Ama ben diyorum ki kendime boş ver

Sağıma da baksam solumada baksam

Sanki sen varsın hemen yanı başımda

Oturup yeni doğmuş bebek gibi ağlasam

Faydası olmaz bilirim geri dönmesin bana

Gittin ardında bir ceset bırakarak

Giderken ahımdan başka hiçbir şey götürmedin

Ben ise dönersin diyordum içimden ağlayarak

Bir ömür bekledim seni ama sen gelmedin

Sakin dışarıda yağmur yere değil de

Öldürmek istercesine yağıyor

Şu benim zavallı,nazik yüreğime

Gökyüzünden yağmur değil ölüm yağıyor

Yağmur birazdan duracak belki

Belki de sende bakıyorsun ıslak sokağına

Şimdi tertemiz ve mutlu duygular kaplamıştır seni

Ben ise sen gittin gideli yaşarken girdim mezara

Seni anlatmak isterdim seni

Daha seni anlatacak söz söylenemedi

Bitanem,aşkım sordular değerini

Bu zavallı aşık sana değer biçecek bir şey bulamadı', 'Bu gün yağmur yağıyor sokaklara Hatırıma sen geldin yine yar Hatırlıyor musun yağmur yağıyordu ayrıldığımızda Sen unutsan da unutmadı yaptığ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yagmur-degil-olum-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Sevdin mi Yağmurları', 'sen-hic-sevdin-mi-yagmurlari-murat-ceylan-a18sc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hiç sevdin mi yağmurları

Koşmak istedin mi kırlarda 

Yürüdün mü ıslak kaldırımlarda

Yüreğin alev alev yanarken

Sen hiç ağladın mı sabahlara kadar 

Elinden elma şekeri alınmış bir kız gibi

Senin hiç gözlerin aradı mı yıldızları

Sabah oluncaya kadar sevdiğini düşünürken

Sen hiç hüzünlenip geceleri şiir yazdın mı

Ya da bir sigara yakıp düşündün mü bir çift gözü

Her içine çektiğin dumanda aşkını andın mı

Yalvardın mı Allah’a yaz günü üşürken

Sen ne yağmurları sevdin

Ne de ağladın,hüzünlendin geceleri

Bunları yapabilseydin

Şimdi bende mutlu olurdum diğer insanlar gibi

                                                 Murat CEYLAN', 'Sen hiç sevdin mi yağmurları Koşmak istedin mi kırlarda  Yürüdün mü ıslak kaldırımlarda Yüreğin alev alev yanarken Sen hiç ağladın mı sabahl...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-hic-sevdin-mi-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bitkinim ki Anlatamam', 'oyle-bitkinim-ki-anlatamam-murat-ceylan-dubz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyi seni sevdiğim kadar sevemiyorum

Sen başkaydın,sen aşkın ta kendisiydin

O ayrıldığım günden beri kimseye sevgi sözü söylemiyorum

Sen şu yalan dünyada aşık olunacak tek kişiydin

O kadar güzel ve mahzun bakardı ki gözlerin

Ben cesaret edemezdim bakmaya derin derin

Hayalimde yaşattığım o telli duvaklı gelin

Senden başka kim olabilirdi söyle güzelim

Sen buralardan ayrılalı uzun zaman oldu

Hala gözlerim o bakamadığım gözlerini arar

Belki Allah böyle olmasını istedi,bunlar ondan oldu

Sen gittin gideli bu yüreğimde peşinden koşar

Öyle bitkinim öyle yorgunum ki anlatamam kimseye 

Odamda masanın üstünde sürahi ve bardak 

Bir susadım ki sensizlik içinde,sanki çöldeymişçesine

Kim bana gelip kim bir bardak su katacak

                                                     Murat CEYLAN', 'Hiç kimseyi seni sevdiğim kadar sevemiyorum Sen başkaydın,sen aşkın ta kendisiydin O ayrıldığım günden beri kimseye sevgi sözü söylemiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyle-bitkinim-ki-anlatamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeliyim', 'olmeliyim-murat-ceylan-i8qhp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boğuyor beni hayat 

İçimden bir ses diyor ki

Ulan sök kalbini yere at

Atmamalıyım,bakarsın kapımı çalar mutluluk belki

Gece kararıyor sanki kaderime inat 

Canım neye sıkılıyor bilmiyor kalbim

Geçmiyor vakit,sanki  düşmandır bana saat

Dayanmalıyım,bakarsın belki bende doyasıya gülebilirim

Yakıyor içimi sensizlik alev alev

En olmadık,en savunmasız halde bıraktın beni

Şimdi gitsem bana seni hatırlatır o ev 

Unutmalıyım,bakarsın bir yar severim yeni

Bıktım her gece çocuk gibi ağlamaktan

Uyumak istiyorum yatağımda rahatça

Korkulu rüyalarla uyanıyorum her gün yataktan

Uyumalıyım,bakarsın bir sevgi fısıltısı duyarım kulağımda

Yaşıyorsam nefes aldığım için yaşıyorum

Zaten Tıpta yaşamın tanımı bu değil mi

Ölüme adım adım yaklaştığımı hissediyorum 

Yaşamalıyım,bakarsın hayat yaşamaya değer belki

Beni anlayan bir insan bulsam,ya da bir hayvan

Susup,durmadan gece gündüz dinlese beni

Beni anlayıp benim gibi ağladığı an

Susmalıyım,bakarsın bedduası bulur seni

Dayanmaya,unutmaya,susmaya,sensiz uyumaya

Bu can bedenimden çıkınca kadar varım ama

Hayalin girince geceleri ansızın hatırıma 

O an yaşamaya yokum  fakat varım ölmeye doyasıya

İşte o zaman durmamalıyım hayatta 

Hoş geldin demeliyim Azrail’e sevinçli

Onu unutturarak al canımı demeliyim çabukça

Ölmeliyim, dirimi sevmedin,ölümü seversin belki', 'Boğuyor beni hayat  İçimden bir ses diyor ki Ulan sök kalbini yere at Atmamalıyım,bakarsın kapımı çalar mutluluk belki Gece kararıyor sanki ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum...', 'biliyorum-aysun-erat-ak7k3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitecek elbet.

Biliyorum.

Çünkü, hiçbir kabus sonsuza kadar sürmez.

Alt tarafı…

Kan ter içinde bırakır beni.

Ama biter..

Biter sabaha…

Yıkarım yüzümü, aydınlanırım.

Hiçbir şeyciğim kalmaz.

Bir avuç serin su lazım bana

Bir de

Bir parça güneş kirpiklerimden sızan.

Biliyorum…

08/2005', 'Bitecek elbet. Biliyorum. Çünkü, hiçbir kabus sonsuza kadar sürmez. Alt tarafı… Kan ter içinde bırakır beni. Ama biter.. Biter sabaha… Yıkar...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biliyorum-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya''Rab', 'ya-rab-tuncay-akdeniz-v77b8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlahi ateşin yanar özümde

Gönülden inanan kul eyle YARAB

Hak için dökülen yaşı gözümde

Akıt ırmağından sel eyle YARAB

Hakkı hak bilip,hak yolda yürüdüm

Bu aşkın közünde yandım eridim

Sana kavuşmaktır en büyük derdim

Yandır ocağında kül eyle YARAB

Sevgiyi sevdayı vermiş bu cana

Aşkı ilan ettim sevdamla sana

Rahmet kokun gelir rüzgarla bana

Sıratın üstünden yel eyle YARAB

Gezdim yollarını ben diyar,diyar

Hayaline aşık ruhum bahtiyar

Gönül taze fidan beden ihtiyar

Gönülden gönüle yol eyle YARAB

Kulum kul hakkını nasıl öderim

Bağışlansam sevinerek giderim

Hakkım olanlara helâl ederim

Rahmetin kullara bol eyle YARAB

Allah,kurân Resulune inandım

Tuncay ezan sesi ile uyandım

Beş vakitin renkleriyle boyandım

Muhammed gülüne dal eyle YARAB', 'İlahi ateşin yanar özümde Gönülden inanan kul eyle YARAB Hak için dökülen yaşı gözümde Akıt ırmağından sel eyle YARAB Hakkı hak bilip,hak yo...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ya-rab-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İstiyorum', 'sevmek-i-stiyorum-ufuk-coban-kxhls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kader bağlamış geceleri ardısıra yaşantıma,

Günyüzünde ayırmamış bir canlık yer bana.

Karanlıkta kalıyor gözlerim aynalar karşısında,

Bir ben, bir de karşımdaki ben var yanımda.

Koşup kaçmak istiyorum karanlıklardan delice,

Çarpmak insanlara düşüp yuvarlanana kadar.

Yorulup yıkıldığım yerde öylesine durmak,

Birinin gözlerine düşene kadar kalmak istiyorum.

Gönül ister de kader izin verir mi sevdalara? 

Ayaklar gider de dudaklar yol verir mi başlangıçlara? 

Gözler yerleri ezberleyip dönüş yoluna vardığında,

Kaderin geceleri başlar ardısıra yaşantıma.

Ben de sevmek istiyorum yolda yürürken birini,

Kaderin elinden kaçıp sarılmak katıksız delice.

Gerçekten, sorgusu aklıma bile gelmeden,

Sevmek istiyorum, ama sevemiyorum birini.

08/08/2005 22:50', 'Kader bağlamış geceleri ardısıra yaşantıma, Günyüzünde ayırmamış bir canlık yer bana. Karanlıkta kalıyor gözlerim aynalar karşısında, Bir be...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmek-istiyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-selahattin-durna-3w34f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hikaye

Sarıdır

Dökülmüş omuz üstü

Yüreğin örse çekiç

Bir şiir,ölçü tutmaz

Denk düşmez kafiyesi

Diridir

Hayat geçer içinden

Camı deler mavisi

Sense bir göçük maden

Uçurulmuş kapısı

Yeridir

Kim yalan kim doğrusu

Gönül bir Karac’oğlan

Ölüm bir akça gelin

Hikayedir gerisi.

                                                                      1996 BUCAK', 'Hikaye Sarıdır Dökülmüş omuz üstü Yüreğin örse çekiç Bir şiir,ölçü tutmaz Denk düşmez kafiyesi Diridir Hayat geçer içinden Camı deler mavisi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hikaye-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük', 'yuk-selahattin-durna-ei057', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yük

Yüreğiniz bir dağdır

Kuş uçmaz kervan geçmez

Yalandır dağ dağa kavuşmaz

Yüreğiniz bir ağır yük

Çekip götüremezsiniz

Göğüs kafesiniz almaz

Sığmaz ki bagajlara

Sesinizi kimse duymaz

Ses gelmaz kimselerden

Bütün telefonlar kesik

Yollar hanidir kapalı

Dağ dağa kavuşur da

Tavşan tavşanın suda bulur izini

Ama sizin

Kimse bulamaz adresinizi

Ve zaman aşımındadır

Çalacağınız bütün kapıların zili

Bütün perdeler örtük

Bütün hatlar doludur

Bir sabahçı kahvesinde buluşan

Çay simit yoldaşlığı

Vurur kelepçesini güne

Yaşamak bir hüzündür artık

Yaşamak bir yük balki…

                                                             KIRKA-87', 'Yük Yüreğiniz bir dağdır Kuş uçmaz kervan geçmez Yalandır dağ dağa kavuşmaz Yüreğiniz bir ağır yük Çekip götüremezsiniz Göğüs kafesiniz alma...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuk-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Sokaklarda Bulmak Aşkı', 'i-mkansiz-sokaklarda-bulmak-aski-yildiray-pilint-7nlvi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ışık her zaman bakışlarımda

Dolaşırım gezerim sokakları

Ama nafile kalpler hep kırık

İmkansız sokaklarda bulmak aşkı

Bazen alevlenir gözlerim

Bir göze,bir bakışa,bir dudağa

Boşunadır aramakla geçen zaman

Zira öylesi bir kez çıkar karşına

Ararız bulamayız içimizde ümit

Yollarda; yorgun, boyun bükük

Ruhumuz bunalımlarda tükenmiş

Yaşarız hayallerimizle çaresiz', 'Bir ışık her zaman bakışlarımda Dolaşırım gezerim sokakları Ama nafile kalpler hep kırık İmkansız sokaklarda bulmak aşkı Bazen alevlenir göz...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Pilint']::text[], 8.5, '{"poet":"Yıldıray Pilint","poet_slug":"yildiray-pilint","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imkansiz-sokaklarda-bulmak-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Siz Bu İşi Biliyorsunuz', 'cocuklar-siz-bu-i-si-biliyorsunuz-selahattin-durna-ohrxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuklar Siz Bu İşi Biliyorsunuz

Bin yaşayın aklınızla çocuklar,

Siz bu işi biliyorsunuz.

Düşlerinizi kanatsız bırakıyoruz,

Göğünüzü uçurtmasız...,

Gene de darılmıyorsunuz.

Her sene başı böyle,

Koşup geliyorsunuz gene; 

Uçup geliyorsunuz.

Çocuklar,çocuklar,

Siz bu işi seviyorsunuz.

Merhabamız uygunadım,

Sevdamız hazırolda…

Gücenmiyorsunuz.

Onca bayram rapraplarda

Elleriniz alkış alkış,

Elleriniz salkım saçak,

Tekeden süt çıkarıyorsunuz,

Yontulardan gülücükler…

Çocuklar,siz bu işi biliyorsunuz.

Çocuklar,siz bu işi seviyorsunuz

En metal denklemler,

Dilinizde çiftetelli; 

En bayağı kesirlerle

Uzuneşek oynuyorsunuz.

Tınmıyorsunuz.

Biz

Everest bilmem kaç metre derken

Siz,

Ne zaman,nasıl,ne çabuk

Bir ağaç buluveriyorsunuz yüpyüksek

Salıncaklar kuruyorsunuz düşünüze layık; 

Elinize sağlık! 

Ne güzel kuruyorsunuz.

Çocuklar,siz bu işi biliyorsunuz.

Çocuklar,siz bu işi biliyorsunuz.

Biz “Atatürk…”diyoruz,

“Atatürkler…”diyoruz,

Asık surat,yalın kılıç,çatık kaş…

Siz,

Kimin aklına gelir,

Kaşla göz arasında

Atatürk’le arkadaş oluyorsunuz.

Çember çeviriyorsunuz birlikte

Misket oynuyorsunuz.

Bisiklete biniyorsunuz,yol bulup sınıflardan.

Dil çıkarıyorsunuz ensemizden dönüp dönüp; 

Bilmiyoruz sanıyorsunuz.

Laf aramızda çocuklar,

Biz ürküyoruz Atatürk’ten,

Siz Atatürk’ü seviyorsunuz.

Çocuklar,siz bu işi biliyorsunuz.

Gönlünüzle bin yaşayın çocuklar! 

Siz bu işi seviyorsunuz.', 'Çocuklar Siz Bu İşi Biliyorsunuz Bin yaşayın aklınızla çocuklar, Siz bu işi biliyorsunuz. Düşlerinizi kanatsız bırakıyoruz, Göğünüzü uçurtma...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/cocuklar-siz-bu-isi-biliyorsunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetiş Sevgili', 'yetis-sevgili-canan-motorcu-igs75', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünceler dans ederken kafamda

Gözlerimde hep resmin var

Sesin çınlarken kulaklarımda

Aklımda hep konuşmaların var

Ne duygularım oturuyor yerine

Ne kelimeler bir anlam buluyor

Sondan başa sarsam da filmi geriye

Hislerimdeki karmaşa sona ermiyor

Gel ey sevgili gel artık kurtar beni

Bu anafor beynimi bitirmeden yetiş

Seveceksen sev ya da bırak artık beni

Sözcükler anlamını yitirmeden yetiş

07.08.2005   (14:10)', 'Düşünceler dans ederken kafamda Gözlerimde hep resmin var Sesin çınlarken kulaklarımda Aklımda hep konuşmaların var Ne duygularım oturuyor y...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yetis-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitip Giden', 'yitip-giden-selahattin-durna-tjxlk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yitip Giden

Bir serçe ölüsüdür dudaklarımda hüzün.

Parmağımı basarım seslerin ortasına.

Ayak izlerim düşer.

Yüreğim kalakalır tahtanın karasında.

Damında göğünüzün

Yitik bir pabuç teki; 

Çıkıp alamazsınız,

Alıp bakamazsınız.

Bir mendilin içine özenle sarmalanmış

Kocaman düşleri çocukların; 

Tutar açarım,

İnanmazsınız.

Camında gözünüzün

İlle de dudaklarım…

Bir serçe ölüsüdür oysa

Dudaklarımda hüzün; 

Bakar göremezsiniz.

Yüreğim kalakalır karasında tahtanın.

Arar,bulamazsınız.', 'Yitip Giden Bir serçe ölüsüdür dudaklarımda hüzün. Parmağımı basarım seslerin ortasına. Ayak izlerim düşer. Yüreğim kalakalır tahtanın karas...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yitip-giden-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-canan-motorcu-yjor9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda dedikleri

Bir tutam mutluluk

Avuç avuç hüzün

Bir kaç heyecan kıpırtısı 

Bir iki minik tebessüm

Çok az unutulmayacak hoş an

Genelde acılarla bir bütün

25.07.2005   (01:07)', 'Sevda dedikleri Bir tutam mutluluk Avuç avuç hüzün Bir kaç heyecan kıpırtısı  Bir iki minik tebessüm Çok az unutulmayacak hoş an Genelde acı...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizce?', 'sizce-canan-motorcu-faxkd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir o yana bir bu yana

Koşup duran insanlara baktıkça 

Her zaman imrenirim

Bir telaş bir heyecandır yaşadıkları

Tüm dertleri gelecekleridir

Hayallerine kavuşamayacaklarını

Bile düşünmeden çabalarlar

Beklentileri kalmamış olanlarınsa

Hüzünlüdür bedbindir dünyaları

Geleceğe aldırmaz umutla bakmazlar

Öylece bir kenarda oturur

Arkalarında kalanı hatırlamaz

Önlerini araştırmaya ise

İnanın hiç yanaşmazlar

Peki sizce hangisi mutludur

Amaçlarına kavuşamayacaklarını 

Bilseler bile dinlenmeden koşanlar mı? 

Hayattan bir beklentisi kalmayıpta

Umutsuzca günlerini yaşayanlar mı? 

22.07.2005   (01:30)', 'Bir o yana bir bu yana Koşup duran insanlara baktıkça  Her zaman imrenirim Bir telaş bir heyecandır yaşadıkları Tüm dertleri gelecekleridir ...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sizce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sisteki Büyü', 'sisteki-buyu-selahattin-durna-84v5t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sisteki Büyü

Gözlerim bir tutam perçem,

Gözlerim çırılçıplak bir kelepçe sanki

Oysa inat mı inat

Bir Mayıs tutkunuyum.

Sisteki büyüye döker suyunu

İçimdeki kör kuyu.

Kasvete çiçekler dökerim.

Kelebekler ürer

Dantelinde içimin.

Yüreğimde

Çocuk boyaların huyu.

Ama gözlerim çırılçıplak bir kelepçe.

Gözlerim

Bir tutam perçem.

Sisteki büyüye dökerim suyumu.

Ama suların

Gölgesi büyür içimde.

Üşür ayakları yüzüme bakıp bakıp 

Gökteki bir yıldızın.

Gözlerinde bir tutam perçem.

                                                                     2Ocak 87', 'Sisteki Büyü Gözlerim bir tutam perçem, Gözlerim çırılçıplak bir kelepçe sanki Oysa inat mı inat Bir Mayıs tutkunuyum. Sisteki büyüye döker ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sisteki-buyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhlar Birleşsin', 'ruhlar-birlessin-canan-motorcu-0frvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sıkıntı nedir

Ne bu huzursuzluk

Silkelenelim artık

Yolun sonu mutluluk

Varmı bu dünya da

Umut ve sessizlik 

Bulunurmu aranırsa

O sonsuz derinlik

Amaçlar birleşse        

Sırt sırta verilse

Sukunet ve esenlikle       

Hep birlikte yürünse

Eminim vardır bir yerde

Başı sonu olmayan o beste

Ararız elele gözgöze dizdize

Yeter ki ruhlar biraraya gelse

07.08.2005   (16:15)', 'Bu sıkıntı nedir Ne bu huzursuzluk Silkelenelim artık Yolun sonu mutluluk Varmı bu dünya da Umut ve sessizlik  Bulunurmu aranırsa O sonsuz d...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ruhlar-birlessin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-canan-motorcu-e7q3h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel koş kollarıma

Sana mutluluk vereceğim

Yıllardır aradığın huzuru

Bütün samimiyetimle önüne sereceğim

Bir demet his sunup

Kalbimi tümüyle vereceğim

Seni zevk sarhoşu edip

Gökkuşağının yedi rengini göstereceğim

Hadi gel yanıma

Bırak kendini tamamen bana

Kırçiçeklerinden yatak yapıp

Ateş gibi duygularımı sunacağım sana

Sakın gelmemezlik yapma

Beni kurda kuşa bırakma

Seni istiyorum sadece yanımda

Çünkü güveni yeniden sen hatırlattın bana

07.08.2005   (16:55)', 'Gel koş kollarıma Sana mutluluk vereceğim Yıllardır aradığın huzuru Bütün samimiyetimle önüne sereceğim Bir demet his sunup Kalbimi tümüyle ...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-artik-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Sevgili', 'gel-sevgili-canan-motorcu-eepdl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel dünyam ışıldasın

Karanlık noktam kalmasın

Gel gözyaşlarım dinsin

Gözlerimdeki hüzün bitsin

Gel kollarım boş kalmasın

Doluluğun hazzını yaşasın

Gel umutlarım yeşersin

Binbir renk çiçek serpilsin

Gel ruhun ruhuma dokunsun

Beynim mutlulukla dolsun

Gel kalbim titresin

Heyecan içime işlesin

Gel ellerim elinde kalsın

Güven duygusunu hatırlasın

Gel bedenim üşümesin

Sıcaklığını hissetsin

Gel gözlerim gözlerine dalsın

Oradaki sonsuz aşkı yakalasın

Gel dizlerin dizlerime değsin

Vücudum tümüyle dile gelsin

Gel sevgiyi aşkı birlikte öğrenelim

Bu yarınsız ama sıcacık yolda 

Umutsuz ve sonuçsuz da olsa 

Elele beraberce yürüyelim

07.08.2005   (17:31)', 'Gel dünyam ışıldasın Karanlık noktam kalmasın Gel gözyaşlarım dinsin Gözlerimdeki hüzün bitsin Gel kollarım boş kalmasın Doluluğun hazzını y...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gel-sevgili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirde kuram kıvamı - I', 'siirde-kuram-kivami-i-mutlu-ayar-zvuqc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sür-realizmin ekmeğine yağını

görmesin kimse şiir yazamadığını 

göremesin herkes şiir yazamadığını

sür-realizmin ekmeğine yağını', 'sür-realizmin ekmeğine yağını görmesin kimse şiir yazamadığını  göremesin herkes şiir yazamadığını sür-realizmin ekmeğine yağını...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siirde-kuram-kivami-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emekçi Halk Durağı', 'emekci-halk-duragi-kamber-bal-nzan5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıktım bir tay, bir kervan yola 

Durak Emekçi –Halk Durağı

Hür herkes bu hakikat  yola

Durak Emekçi-Halk Durağı

Emek zahmet nedir ki bize? 

Düşmüşsek şayet bu ize

Döneriz belki milyon güze

Durak Emekçi-Halk Durağı

Sabret dostum, zahmet bizden

Neylesin kuru-nuru özden

Kesilene dek derman dizden

Durak Emekçi-Halk Durağı

Şaşmaz yolu, kulu şaşsa da

Yol erkanı, biri düşse de

Yesek o kazandan, aş pişse de

Durak Emekçi-Halk Durağı

Yürü biçarem, dağlar yol verdikçe

Bakma geriye, Mevla’n gel dedikçe

Durma sen, sana gelindikçe

Durak Emekçi-Halk Durağı

Darda kalmaz özü Bal olan

Sömürüdür gerçekten yok olan

Leş olmuş,Yolundur pak olan

Durak Emekçi-Halk Durağı

1989 Basın Emekçilerine Bir Armağandır', 'Çıktım bir tay, bir kervan yola  Durak Emekçi –Halk Durağı Hür herkes bu hakikat  yola Durak Emekçi-Halk Durağı Emek zahmet nedir ki bize?  ...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/emekci-halk-duragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Benim Sevdam', 'yine-benim-sevdam-ali-biyikli-romantik-yhxow', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir başka baharların esintisi

Tut ki başka sevdim seni

Yılların hezimetinden kurtulmuşum

Umut doldu,

Aşk oldu yüreğim.

Dağlara anlatırım coşkunu.

Şevkatine muhtaç olduğum,

Hayat savurur beni 

Adını koyamadığım yıldızlarına. 

Verebilsem son nefesi,,,

Demesi kolay oysa

Acımazmı kalbin

Sızlamazmı, Yankı olmazmı odan.

Gözüm dalar, bir hayal ederim seni

Anlatılacak sevdam da bitmedi 

Ne seni ikna kabiliyetim vardı sevgime ait,

Ne de senin inanma kudretin vardı.

Bu sabah uyanınca,

Düşlerimi göresin düşlerimde

Sen bilesin diye hayalimi

Anlayasın diye tutkunluğumu

Kanatlanıp pencerene konsam,

Minik kuşun olsam

Bilirimki Kafesine atarsın.

Rağzı olduğumu söylesem

Bilirimki hapsedersin oracıkta

Biliyorum merhamet yok sonsuza kadar 

Düşlerim de öyle 

Fanii, acımasız

Ama yine de tutkuyu bilen

Titremesiyle titreyen,

Ağlamasıyla ağlayan.

Küçük bir çocuğa sordum ben,

Hiç Yıldızları Gündüze sordunmu? 

Anlamadı...! 

Geceyi sordunmu Güneşe? 

Bilemedi...! 

Mutsuz olana sordunmu mutlu olmayı? 

Tüm şiirlerini paylaş dedi.

Önce hayalimi gördüm yazdıklarımda

Hepsini yaptım

Uygulamada da başardım

Müziğimi bile dinledim

Hatta adını bile anmadım 

Hatta dudaklarım isminin hiçbir harfini bile telaffus etmedi.

Ve anladım ki 

Sana karşı bu hal

Bu davranış içindeyim

Sen ise Kötü oyunlardasın

Hiç birzaman bilemediğim sitem

Yine de, 

Her gece olduğu gibi

Bu gece de Telefonum yastığımın altında olacak,

Beklenirki aranırım diye..

Biliyorum ki her çalışında 

İrkilip uyanacağım,

Acaba O Adını Koyamadığım mı arıyor

Göremiyince ismini

Sarılacağım senin yerine yastığıma

Sabaha dek 

Bu Sevdalara alışamadım hiçbirzaman

Yalnızlığa alışıktı oysa  hayalim

Ama şimdi bir dostum var

Gölgelerim.

Gölgemin dostu başaçıkabildiğim hırçın geceler 

O da ağlamaklı 

O da  yalnız.

Hayalimin bir adım bile önüne geçemediğim,,, 

Sensizliğin kaygısıydı oysa

Benim canımı acıtan Sevdam...

 Ali Bıyıklı (Romantik)', 'Bir başka baharların esintisi Tut ki başka sevdim seni Yılların hezimetinden kurtulmuşum Umut doldu, Aşk oldu yüreğim. Dağlara anlatırım coş...', ARRAY['Türk Edebiyatı','Şiir','Ali Bıyıklı (Romantik)']::text[], 8.5, '{"poet":"Ali Bıyıklı (Romantik)","poet_slug":"ali-biyikli-romantik","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/yine-benim-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-mehmet-bicik-yjhze', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bebek geldi dünyaya,

Günlerden Altı Nisan…

Sanki dalmıştım rüyâya,

Sevinçle kucağıma aldığım an…

Allah’ım! Ne güzel bir bebek! 

Bebek değil, bu bir kelebek.

Yok, yok o nûrânî bir melek.

Adı da kendi gibi güzel: Ahsen! ...

Tuğçe idi bebeğin ikinci adı,

Annesi de vardı âdi mi âdi,

Yuvamız yıkıldı, sevindi dadı,

Çıkamaz oldum insan içine ben…

Yazık oldu sevdâya, açmamış çiçeğe..

Yazık oldu kurda, kuşa, örümceğe..

Yazık oldu kızım Ahsen Tuğçe’ye..

Der de ağlarım gece gündüz demeden…

13 Kasım 2001, Burhaniye', 'Bir bebek geldi dünyaya, Günlerden Altı Nisan… Sanki dalmıştım rüyâya, Sevinçle kucağıma aldığım an… Allah’ım! Ne güzel bir bebek!  Bebek de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bebek-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonrası', 'sonrasi-deniz-yavuz-9dijt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyorum 

Koca bir hiçe 

Ve koca bir hiç uğruna,

Hayatın toy kollarında bu sözleri söylemek 

Çok çok kolay 

Ya sonrası...

Sonrası sadece ve sadece keşkelerden ibaret bir yaşam,

Ve ben biliyorum ki bu yazdıklarım 

İki kulak arası mesafede anlaşılacak 

Yani birinden girip, diğerinden çıkacak...', 'Gidiyorum  Koca bir hiçe  Ve koca bir hiç uğruna, Hayatın toy kollarında bu sözleri söylemek  Çok çok kolay  Ya sonrası... Sonrası sadece ve...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonrasi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deruni Hasbıhal -1-', 'deruni-hasbihal-1-zulfikar-yapar-kaleli-lwpxj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' 

Hevesi yol ettim, hayali yoldaş

Ne seherim, ne  sabahım var benim

Hasreti tutamam, arzu gözde yaş

Ne suç ettim, ne günahım var benim

Serverların dergâhına uğradım

Usulce sokuldum, atmadım adım

Pirim gözlerinde kaldı muradım

Başı duman dağca ahım var benim

Selam verdim selamımı almadı

Gönül verdim, davet ettim kalmadı

Boyun eğdim, “şükür” dedim olmadı

Deste derdim ve ervahım var benim

Böyle bir sevdaya bağlandı yolum

Tutsam kaldıramam, yok artık kolum

Sultana sevdalı, talihsiz kulum

Şaha şadlık veren şahım var benim

a target=''_blank'' href=''http://www.antoloji.com/siir/siir/siir_SQL.asp? sair=13612&siir=291029&order=oto

''Bu şiir Abdulkadir Öğdüm’ün “Kaleli’yle Hasbihâl” isimli şiirine cevaben yazılmıştır 

Bu şiir Abdulkadir Öğdüm’ün “Kaleli’yle Hasbihâl” isimli şiirine cevaben yazılmıştır

* Kaleli''yle Hasbıhâl - 1 * 

Yaşımdan daha fazla edebî hayatı olan, usta şair, Zülfikâr Yapar Kaleli''ye... 

Uyak atlar, redif oynar dostları, 

Can Kaleli kurup bağdaş, seyreder... 

* * * 

İfaden arıdır, hasletin paktır, 

Sesin duyan çavlan sanır Kaleli... 

Albeni diyenin çoğu tuzaktır, 

Seni bilen bilir, tanır Kaleli... 

* * * 

Derûnî haldaşın istirham eder, 

Hasbihâlin için serer postları... 

Kaleli Usta''nın bu şiire yazdığı cevap 

Özel Sayfam 

Abdulkadir Öğdüm', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''  Hevesi yol ettim, hayali yoldaş Ne seherim, ne  sabahım var benim Hasreti tutamam, arzu ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/deruni-hasbihal-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyarsız', 'duyarsiz-aysun-erat-1hupv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Diyorum ya hep! 

Ben, bencilin biriyim.

Galiba.. bu doğru.

Son günlerde…

Kendimden başka, hiçbir şey düşünemez oldum mesela.

Memleketin hali nicedir? Umurumda değil.

Ya da…

Ne bileyim…

Deniz kirliymiş,

Komşunun evine hırsız girmiş…

Bana ne! 

İçimdeki boşluğu dolduramıyor bir türlü, hiçbir güzellik.

Büyüdükçe büyüyor,

Boyumu aşıyor, sevdamın derdi.

Ben, beni bilirim yalnız.

Gerisi hikaye.

Şimdi…

Duyarsız deyin isterseniz bana,

En alasından.

Haksız da değilsiniz ama.

Antenlerimi hissetmiyorum zira! 

08/2005', 'Diyorum ya hep!  Ben, bencilin biriyim. Galiba.. bu doğru. Son günlerde… Kendimden başka, hiçbir şey düşünemez oldum mesela. Memleketin hali...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/duyarsiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik Kızım', 'biricik-kizim-mehmet-emin-altun-62zru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine mahçub sana karşı biliyorum

Ne kadar zaman oldu anlıyorum

Verdiğim sözü yerine getiremiyorum

Af et beni biricik kızım

Yine mahçubum sana karşı biliyorum

Ne olur dökme sen göz yaşı anlıyorum

Bu seferde gelemiyorum

Af et beni biricik kızım

Yine mahçubumm sana karşı biliyorum

Atlıyorsun yine bir yaşı anlıyorum

Uzaktayım yaş gününde bulunamıyorum

Af et beni biricik kızım

Yine mahçubum sana karşı biliyorum

Bugün senin doğum günün anlıyorum

İnanki sizleri seni çok çok özlüyorum

Gelemiyorum af et beni biricik kızım

Doğum günün kutlu olsun.', 'Yine mahçub sana karşı biliyorum Ne kadar zaman oldu anlıyorum Verdiğim sözü yerine getiremiyorum Af et beni biricik kızım Yine mahçubum san...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Altun']::text[], 8.5, '{"poet":"Mehmet Emin Altun","poet_slug":"mehmet-emin-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biricik-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim Sana', 'duslerim-sana-i-brahim-duskun-7x0f1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'düşlerim sana

bulurum seni bu gece

hilal doğanda ay sen

gözleri ufuklarda

bir martı durur kıyıda

güneş denizde boğulur

yine akşam burada

rüzgar eser için için

ritmini aşka bulur şarkılar

adına gelince dalgalar

divan kurulur yıldızlardan

karanlıklar vurulur

aşka yürek kurtulur

düşlerim sana

ha rüya ha gerçek

bulurum seni bu gece

hilal doğanda ay sen', 'düşlerim sana bulurum seni bu gece hilal doğanda ay sen gözleri ufuklarda bir martı durur kıyıda güneş denizde boğulur yine akşam burada rüz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duslerim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin Masum Değil', 'gidisin-masum-degil-kenan-yasar-mlyfb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hoşçakal derken fark ettim 

sesin merhaba diyen ses değil

yıldızlar kadar uzak 

gözlerine baktım tanıdık değil 

kokunda değişmiş sarılırken hissettim

yüzün bildik yüz değil

bulutlu gözlerinden dağılmadan akıyor

civa gibi damlalar 

saçının rengi solmuş

ve alnın kırış kırış

benzediğin nar değil

soğuk vurmuş sanki kış

mevsimin bahar değil

kalkanı delinmiş kargısı kırık

yüreği sevginle yanmış savaşçı 

kasırgayı mırıldanır yağmuru değil

bozkırları sular çınarlar filizlenir

toprağa kanı düşer cemresi değil

rüzgar kadar değil dağ kadar değil

bir damla su kadar güçlü nefesin 

ok geldiğin yerden yay gidiyorsun

deniz senin değil göl senin değil

vedalaşıp düştüğün yol senin değil

bir masanın örtüsünü çeker gibi düşüyor

yüreğimde sana ait ne varsa 

taşa düşen bir sırça 

bu senin yasın değil

ne varsa paramparça 

gidişin masum değil.', 'hoşçakal derken fark ettim  sesin merhaba diyen ses değil yıldızlar kadar uzak  gözlerine baktım tanıdık değil  kokunda değişmiş sarılırken ...', ARRAY['Türk Edebiyatı','Şiir','Kenan Yaşar']::text[], 8.5, '{"poet":"Kenan Yaşar","poet_slug":"kenan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gidisin-masum-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-cihan-kaya-yt61v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anıp adını 

bir sigara yakacağım, 

onu yanlızlığıma yoldaş edip 

bitince / bitince yine 

seninle olacağım...', 'Anıp adını  bir sigara yakacağım,  onu yanlızlığıma yoldaş edip  bitince / bitince yine  seninle olacağım......', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sigara-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Su/Sar', 'ask-su-sar-guzin-eye-dundar-i9y0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sendendir ruhumda ki 

kahrolası inkarlar

hak etmediğin düşten

uyandırılmak da var

bir gün isyan çıkarsa

tüm zincirleri kırar

uyanıp boş duvarda

gölgeme bakmak da var

hangi can hangi canan

böyle acımasızca

kurnaz bir avcı gibi

sevdiğini yaralar

gözlerinde renk susar

kulaklarında sesler

bensiz bomboş bakışlar

nabzındaki aşk susar....', 'Sendendir ruhumda ki  kahrolası inkarlar hak etmediğin düşten uyandırılmak da var bir gün isyan çıkarsa tüm zincirleri kırar uyanıp boş duva...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-su-sar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Gitsin', 'unut-gitsin-ali-osman-yilmaz-n1mr2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unut gitsin, 

Paylaştığımız bir lokma ekmeği,

Deniz kıyısında, 

Martılarla. 

Unut, 

Ilık ılık esen meltem rüzgarında savrulan, 

O güzelim saçlarını, 

Yüreğini ağu''layan, 

Bu zehirli sevdayı unut, 

Unut, 

Damla damla yanaklarından, 

Her akışında, 

Sana düşman, 

Ömrüne düşman, 

Bir yılanın masumiyeti kadar masum, 

bir gölgenin izi kadar senin, 

Kara gecelerde, 

Kamçılarla yaksa da bedenini, 

Düşlerinde karabasan olup, 

Cehenneme atsa da seni, 

O gitmiş, 

Sen bitmişsin, 

Unut.

En keskin zehirle, 

Zehirlemiş sevdanı, 

Unut gidişlerini, 

Unut ''O''nun gelişlerini, 

Unut, 

Ve bekleme bir daha, 

''O''nun gelmesini. 

O senin ömrüne düşman, 

O karanlık gecelerinin kabusu, 

O zehirli sevdaları sunan, 

Unut,o zehirli yaşamın efendisini, 

Uzat ellerini, 

Sen bir çiçeksin, 

Bazen beyaz gül sadeliğinde, 

Bazen çılgın kırmızı, 

Gül kadar sevda dolusun, 

Bırak sevdanı bedenin, 

Kırmızı gül gibi, 

Çılgınca yaşasın.', 'Unut gitsin,  Paylaştığımız bir lokma ekmeği, Deniz kıyısında,  Martılarla.  Unut,  Ilık ılık esen meltem rüzgarında savrulan,  O güzelim sa...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/unut-gitsin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sengül', 'sengul-hekim-coskun-v2mzy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen çok güzel bir çocuksun

ve bende seni çok ama çok seviyorum.

hüzün gibi uzağımda	

sevgi gibi yakınımdasın.

içten nefes alışların

derin iç çekişlerin,

birde anasını sattığımın,

sevgime kulak asmayışın.

sanki………

Sen çok güzel bir çocuksun

ve bende seni çok ama çok seviyorum.

Ak diyeceğim ama

kendine aklardan en güzelini seçmişsin bile; 

kızıl diyeceğim ama,

yok, yok yeşilde demiyorum,

sen gökkuşağı misalisin.

yarım dünyam, yavrum benim.

Sen çok güzel bir çocuksun

ve bende seni çok ama çok seviyorum.

özlemleri yaşarken sen,

mutlu olup ellerinle kucaklarken hayallerimi,

bana yer verdiğin küçücük yüreğin,

ve gözlerinin gülüşü.

Sen çok güzel bir çocuksun,

ve bende seni çok ama çok seviyorum.

Sen gül emi yavrum; 

sen gül ki; yanaklarında güller açsın,

mor menekşeler, zambaklar, yediveren,

ha bi de kardelen,

en çokta kardelen.

Sen gül.

Sen çok güzel bir çocuksun,

ve bende seni çok ama çok seviyorum.

……………..

……………', 'Sen çok güzel bir çocuksun ve bende seni çok ama çok seviyorum. hüzün gibi uzağımda	 sevgi gibi yakınımdasın. içten nefes alışların derin iç...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sengul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Barbarlar', 'esmer-barbarlar-rasim-eren-8235v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eski bir sokak tabelası asmışlar gökyüzüne

ne çok aşk var ne çok cenaze

birileri geçti boş kafatasları ellerinde

kör bir denizdir bu önümde söylemiştim bu yangını

işte yangın bu kez durup dinleyeceğim

bak bu iyi

sektirdiğim taşta kambur kaldım

bu da 

öldürebilirdim annemi

işte birileri daha geçti bunların yok elleri

aslında bunların hiçbiri ilgilendirmiyor beni

eski bir sokak tabelası asmışlar gökyüzüne

bir ok gözlerimin içi kan

esmer barbarlar çoktan geçmiştir nehri', 'eski bir sokak tabelası asmışlar gökyüzüne ne çok aşk var ne çok cenaze birileri geçti boş kafatasları ellerinde kör bir denizdir bu önümde ...', ARRAY['Türk Edebiyatı','Şiir','Rasim Eren']::text[], 8.5, '{"poet":"Rasim Eren","poet_slug":"rasim-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/esmer-barbarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulanık Düşler', 'bulanik-dusler-meral-vurgun-i9hwc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'su akıp geçtin 

içimin uçurumlarından

öfkenin kıyısında büyüttüğüm bir elma fidanı

umudun ırmaklarında uyuttuğum arzular

eli kanlı kahpelikler içinde bulduğum

güzel yosma

büyük aşk

ne desem, nasıl anlatsam bilmem ki

bulanık bir düştün sen 

anımsayamadığım

andıkça bir daha

bir daha öldüğüm

insana göre midir hep gitmeler

anlatabilir mi yıllar yaşadıklarımızı

bilir mi hasrtetin şaha kalkan öfkesini

öz yurdunda yurtsuz kalmaların kahrını

herşeyin bir öyküsü vardır

gölgelerin de rengi

ölümün yok

savaşmaksa kontra bir edim

sana benzeyen ve senden olmayana karşı

bilinir mi ölümün en kahpesi

zulümden olanı yani

oysa daha çok ekmek ve gül için

yaşatmak uğruna yaşamak ister döğüşenler

döğüşürken düşenler

yarına uzanan gecenin sinsi karanlığını 

keskin bir sancı ile kıran şafaklar gibi

iki parmak arası elinde yanan sigaranın

dumanı ben olsam diyen yalnız bir adam gibi

ooff... bir sigara içimlik bakamadığım yüzün

ve yüzünde bir ince çizgi hüzün

şimdi olsa diyorum bir kadeh şarabım

ve içsem acıyı... zehiri içsem

al götürsen beni en ıssız yerine steplerin

bir akça kavak gibi çak köklerimi toprağa

sonra bütün renklerin en yeşilini dallarıma taşısan 

rüzgarın alaca tayı olsan, okşasan yapraklarımı

gör o zaman nasıl direnirim kara kışına zemherinin

ve Temmuz’un yakan sıcağına...', 'su akıp geçtin  içimin uçurumlarından öfkenin kıyısında büyüttüğüm bir elma fidanı umudun ırmaklarında uyuttuğum arzular eli kanlı kahpelikl...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bulanik-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen Kuş', 'gocmen-kus-serhat-karadumanli-ytk2t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıvrıla kıvrıla akan bir ırmağı seyreder gibi

Büyülenirdim sen adımlarken yolları

Bilmezdim o zamanlar Oinone'' nin kardeşi olduğunu

Öylece bakakalırdım ardından

Anlamını çözmeye çalışırken göç yollarının...

Ama biliyorsun

Göçmen bir kuşum ben

Çok bile kaldım buralarda.

Bir bakış istemiştin çünkü

Seni düşündüğümü belli edecek...

-Bak, demiştim gözlerime

Okyanuslar kadar derin gözlerime.

Biliyorum neler gördüğünü oralarda

Sormadım, sormayacağım

Biliyorum çünkü

Tek bir canız biz iki ayrı bedende nefes alan...

...........  ''Fırtına havası var uzaklarda,beni çağırıyor fısıltılarıyla. Alışmışım bir kere o şehirden bu şehire, bu ülkeden o ülkeye sürüklenmeye.... ve bir acıdan diğerine sürüklenirken dudaklarımda hep aynı nemli ıslık..... ''

Usulca kayıp giderken saçlarının arasından

Bir not bıraktım arkamda.

Kağıda 

Yada

Camın buğusuna birşeyler karalamaktansa

Düşlerine kazımayı tercih ettim.

Her gece başını yastığa koyduğunda okurken onu

Ben haykıracağım adını okyanuslara...

Ve kimbilir belki bir gün...

(2005)', 'Kıvrıla kıvrıla akan bir ırmağı seyreder gibi Büyülenirdim sen adımlarken yolları Bilmezdim o zamanlar Oinone'' nin kardeşi olduğunu Öylece b...', ARRAY['Türk Edebiyatı','Şiir','Serhat Karadumanli']::text[], 8.5, '{"poet":"Serhat Karadumanli","poet_slug":"serhat-karadumanli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gocmen-kus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-gokhan-oflazoglu-1k2bg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buraya kadar dediğiniz,

hayata dahil değil.

Dahasını istediğiniz,

çoktan bitmiş.

Hep olacaksa, olmuş.

Siz gene kırık bir aynada

yüzünüzle başbaşa bekleyin.

Ne umuyordunuz, 

oyalandığınız gününüz

size kollarını açmış.

Dönüp dolaşıp geldiğiniz,

yol bile değilmiş.

09/08/2005', 'Buraya kadar dediğiniz, hayata dahil değil. Dahasını istediğiniz, çoktan bitmiş. Hep olacaksa, olmuş. Siz gene kırık bir aynada yüzünüzle ba...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yol-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel gülen...', 'guzel-gulen-zafer-zengin-etnika-ngtr6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

fakir sofrasın da

tabağa düşen bir kaç parça etim

hep saklayacaksın sona

üşürüm soğuk taslarda

kalırsam orada 

unutma

yüreğimde et/ten anla

güzel gülen

sırası gelmiş ayrılığın

özlemek attığın adımın

ağla

ağla ki

gül beklemesin solmayı

dikenim de feryat

hece düşüyor

yerini yurdunu kaybetmiş

türkü söyleyen göz yaşlarım

ağıtlar sarıyorum

güzel gülen

arabesk aşk

dağlarmış ellerini

düşünmez mum

eriyip aktığı yeri

ve duman beğenmez

ateşin son nefesini

güzel gülen

külse

muma bulaşmaz

ses kesildiğinde

söner

etim kopuyor yokluğun da

mum ışığında eriyor düşlerim

dumanı  taranmamış saçım

eklemi düşmüş ellerim

güzel gülen

gelmeyeceksen

gideyim...

13 12. 2004

.', '. fakir sofrasın da tabağa düşen bir kaç parça etim hep saklayacaksın sona üşürüm soğuk taslarda kalırsam orada  unutma yüreğimde et/ten anl...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/guzel-gulen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odur mevsimin en güzel hali...', 'odur-mevsimin-en-guzel-hali-zafer-zengin-etnika-148a4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

Mevsim /

Odur mevsimin en güzel hali

Karlar erirken

Sevdalı gülüş değil mi

Koca dağı zapt eden

Beyazı yerinden söküp

Nehir diye gözümüze süren

Can yanağı/

Dilim  ninni tadında 

Sokul yanağıma

Isıt renk ver canıma

Başın yaslansın omzuma

Yanağım yanağına

Sıcak ocak nasılsa

Suskun el /

Koşturan bulutlar

Kestikçe kendilerini

Ellerim bilmeli

Gözlerim sürmeli

Ve ne olur

Yüreğime dil eklemeli

Susmak geceye

hüznü iç’ime yer etmeli

Çocuğa /

bağırdım çocuk

nasıl dilendim

koca şehirden seni

şehir gitmeli

hayat kendiyle bilemiş gideni

| kim sormuş çöle adını

adı kumunda saklı

çibanlar sürülende yüreğe

yeni isim alır çölde

kızıl kanlar içinde |

ahh bağırmayın

(h) içim uyuyor

sabaha karşı...

ondadır 

aşkın şavkı...

15 02 2004

.', '. Mevsim / Odur mevsimin en güzel hali Karlar erirken Sevdalı gülüş değil mi Koca dağı zapt eden Beyazı yerinden söküp Nehir diye gözümüze s...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/odur-mevsimin-en-guzel-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustamı öldürdüler...', 'ustami-oldurduler-zafer-zengin-etnika-8am2e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

- Arkadaş Zekai  Özger''e...

ustamı öldürdüler joplarla

genç yaşta

son şiirinin başında

attığı sloganla

ustamı öldürdüler

cadde mithatpaşada

coplarla

kafasına vura vura

bundan gayrı küsüm yollara

bırakmadılar hayata

yazmaya

coplarla vura vura

hayınca

şiir öldü

şair öldü

ustamı öldürdüler ankara’da

coplarla 

kafasına vura vura

saçlarımız döküldü

hala orada

adı kara ankara’nın

kara yolunda

yola yakın

merdiven altında

şairi gömdüler genç yaşta

şiirin saf toprağına

usulca göz yaşıyla

02.02. 2005

.', '. - Arkadaş Zekai  Özger''e... ustamı öldürdüler joplarla genç yaşta son şiirinin başında attığı sloganla ustamı öldürdüler cadde mithatpaşad...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ustami-oldurduler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarar/sızımdır...', 'zarar-sizimdir-zafer-zengin-etnika-h71wc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

dokunamam

kedinin kopmuş kuyruğuna

çatılarda aşk ağlamasına

kırlangıcın kanat çırpışına

tezliğine telaşına

düşen yağmura

çalı dibinde kuru toprak

dokunamam

kanadında yazılı uçağa

uzaklara gittiğinden beri canıma

hangi yana

geceye karışan seslere

sigaradan tıkanmış gırtlağa

uzaktan geçen ışığa

lamba içinde sıcağa

iç''ime yanar ateş ''zarar/sızım''dır

dokunamam

masum elini tutan kadına

gözlerinde siyaha

canım deyip kaçmasına

ince mektuplarda avazlara

pullara zarflara

kurulmuş cümlelerde harflere

dilim sarı çıplak

ne olur kaçma  ''zarar/sızım''dır

dokunamam iç''imde sana

nefes kadar yakın olsan

sarılmam mı

sarılmam mı yalnızlığına

parmaklarım takılmış yanağına

korkma

dalında kalan son yaprağım

senden sonra kalmayacağım

dönüp içime

seni anlatacağım kendime

zarar/sızımdır...

21 01 2005

.', '. dokunamam kedinin kopmuş kuyruğuna çatılarda aşk ağlamasına kırlangıcın kanat çırpışına tezliğine telaşına düşen yağmura çalı dibinde kuru...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/zarar-sizimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut Ve Elveda', 'bulut-ve-elveda-emine-deniz-34o1n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su,

Senin ayaklarından mı akardı o zamanlar da

Nilüferler senden mi alırdı kokusunu

,ya burnumun direğini sızlatan çam kokusu,yanık

İsli bir lambadan sızan gaz..

Ya; eylül yağmurlarına gebe

Çatısından ayrılık  damlayan yaz…

Eski bir ezgidir şimdi,patlatan ciğerlerimi,

Ellerimde can çekişen çekirgelerin ahıyla zordayım biliyorum.

Mavi zeytin kutusu

İçinde kırmızı kelebek

Korkaksın hayat

…her zaman kolaydır aşkı  sokakbaşlarında  bitirmek.

Hadi git bulut

Yağmurlarını başka mevsimlerde uyut…

Sesin.

Titrek,içten ürpertilere gebe sesin

Dilim düştü

Anlamsız kelimelerin peşinde sürüklenip

Köhne bir kaldırımın yamacına.

Hiçbir zehir uyutmuyor kalbimi

Ve bastığım mayınlar hain

Acemi kesilmiş bıçaklar,kör,korkak

Nerdesin? 

Sığıntı bir sevdadan geriye

Yanık hanımeli kokuları sinmiş

Ellerime

Hadi sevdiğim

Bir kez de korkma...

Bak 

Ilık yaz akşamlarından kalma 

yürekli bir elveda bekliyor seni kapımda', 'Su, Senin ayaklarından mı akardı o zamanlar da Nilüferler senden mi alırdı kokusunu ,ya burnumun direğini sızlatan çam kokusu,yanık İsli bir...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bulut-ve-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimiz Birden', 'i-kimiz-birden-yasemin-cekic-qg1n4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Berabermiyiz sence hayat yolunda; 

Hüzünlerimiz,dertlerimiz,kederlerimizle...

Zor bir maratonda koşarken ikimiz durmaksızın

Soluk,soluğa...

Yine çaresizlik çıkıverdi karşımıza

Zorda olsa çekmeli,

Zorda olsa yaşamalı,

Zorda olsa sessizce çekip gitmeli bu şehirden

Terketmeli,kaçmalı çok uzaklara

Sonumuzu bilediğimiz ama huzurlu olabileceğimiz yere gitmeli.

Ölüme gitmeli sevgili...

Sonsuz huzura,

Sonsuz saadette,

Sonsuz hayallere gitmeli beraber.

İkimiz baş koyduk bu hayata

İkimiz birden gitmeli.

İkimiz birden', 'Berabermiyiz sence hayat yolunda;  Hüzünlerimiz,dertlerimiz,kederlerimizle... Zor bir maratonda koşarken ikimiz durmaksızın Soluk,soluğa... ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Çekiç']::text[], 8.5, '{"poet":"Yasemin Çekiç","poet_slug":"yasemin-cekic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ikimiz-birden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muştu', 'mustu-sait-kucuk-7tqg5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güzel günler görmemiz

uzak değil sevgilim

sabreyle ki

kar çiçeği

karı

ferhad

dağları

delmek

üzredir', 'güzel günler görmemiz uzak değil sevgilim sabreyle ki kar çiçeği karı ferhad dağları delmek üzredir...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mustu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
