INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi eşarp', 'mavi-esarp-elazigli-mustafa-kaya-wng7y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iki insandık,

iki arayış

iki ateş böceği.

iki kelebek,

çıkmaz sokaklarla sarılı şehirde....

ve

içimizde tereddütler

dolaşıp durdu dilimizde...

istemediğimiz bir vedalaşma yaşadık

yokuşlarda kaldık

caddelerin ortasında

gecelerin karanlığında.

ve bir eşarp gibi 

ruhumu saran denize koştum.

açtım kederimi

hıçkırıklarıma martılar geldi

başıma gelene toplandı sular

köz düştü yüreğime

sar beni mavi eşarp sar

hangisi sendin

sigara külü kadar yalnız ve solgun

hangisi

deniz kadar coşkulu derin

söyle şimdi...hangisi.

eşarbın içinde içimi delip geçen

gözyaşlarını farkettim

meğer 

yaşadığın acı depremden beter

hayalimde sen

mavi eşarbın  ve

biricik sırdaşın  seccaden....

                                                         09.08.2005 / istanbul

                                                          mustafa kaya', 'iki insandık, iki arayış iki ateş böceği. iki kelebek, çıkmaz sokaklarla sarılı şehirde.... ve içimizde tereddütler dolaşıp durdu dilimizde....', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mavi-esarp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kervan ve Haramiler', 'kervan-ve-haramiler-ozan-ozel-8kke7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yolunca ilerleyen

zengin bir kervan 

ve ardınca, yalın kılınç

koşturan haramiler...

bu bir serüven

dünden bugüne

bugünden yarına uzanan...

şairin kimliğinde 

kalem ucunda yaşanan

bir kovalamaca...', 'yolunca ilerleyen zengin bir kervan  ve ardınca, yalın kılınç koşturan haramiler... bu bir serüven dünden bugüne bugünden yarına uzanan... ş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kervan-ve-haramiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızımın kulesi', 'kizimin-kulesi-gorkem-kaya-nfqpe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baharlardan ilkinde,

bir sabah vakti

rüzgar eserken batıdan

bineceğim doğuya giden bir gemiye

güverteden bakarken

ne sen el salla

ne ben bir damla gözyaşı dökeyim ardımdan

güle güle

kızımın kulesi

''gül güle''

kızım', 'Baharlardan ilkinde, bir sabah vakti rüzgar eserken batıdan bineceğim doğuya giden bir gemiye güverteden bakarken ne sen el salla ne ben bir...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kizimin-kulesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-haluk-altinay-eo7pa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen giderken gözlerini görmek istedim

Ağacın yeşili miydi gözlerin? 

Denizin mavisi mi? 

Yoksa yalanın pembesi mi bilmek istedim? 

Üzgünüm derken yüzüne bakmak istedim

Melekler kadar güzel miydi? 

Şeytanlar kadar çirkin mi? 

Beni teselli edecek miydi bilmek istedim? 

Hoşçakal dediğinde dudaklarını görmek istedim

Korun kırmızısı mıydı? 

Taşın siyahı mı? 

Gerçeği mi söylüyorlar bilmek istedim?', 'Sen giderken gözlerini görmek istedim Ağacın yeşili miydi gözlerin?  Denizin mavisi mi?  Yoksa yalanın pembesi mi bilmek istedim?  Üzgünüm d...', ARRAY['Türk Edebiyatı','Şiir','Haluk Altınay']::text[], 8.5, '{"poet":"Haluk Altınay","poet_slug":"haluk-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-giderken-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-gulsen-gonenc-98trt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En büyük suçtur ihanet,

Cezası ölüm.

İntihardır ihanet.

Çünkü insan sadece kendine ihanet eder.

Aşk ölmez, insan ölür.

İhanet suçlularının mezarlığı kalbim.', 'En büyük suçtur ihanet, Cezası ölüm. İntihardır ihanet. Çünkü insan sadece kendine ihanet eder. Aşk ölmez, insan ölür. İhanet suçlularının m...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ihanet-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Çığlık', 'kayip-ciglik-umut-ulbegi-9kzek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybettim

ve o sessiz çığlığa dönüştüm yine

kucak oyuncağıyım artık

dudak tiryakiliğiyim

özüm 

gözbebeklerimden akarken

yıldırımlara direnecek

paratonerim kalmadı

ateşle terbiye edildim

Bir aşkı yitirince insan

konuşamayınca

sevişemeyince

düşünemeyince

yüreği büyümeyince

uyuyamazmış

hele öncesi yoksa

nefes bile alamazmış

öğrendim

Kaybettim

yatak oyuncağıyım artık

geçici körlüğüm

ve o sessiz çığlığa dönüştüm yine

tabutum 

uyku

uyursam kutluyum', 'Kaybettim ve o sessiz çığlığa dönüştüm yine kucak oyuncağıyım artık dudak tiryakiliğiyim özüm  gözbebeklerimden akarken yıldırımlara direnec...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kayip-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler 2', 'maniler-2-mehmet-isikoglu-1u01a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'At üstünden kaygıları

Paylaşalım duyguları

Gönüllere su dökelim

Kollayalım saygıları

İstenir ki şen olalım

Her yerde sevgi bulalım

İnsanlığın icabıdır

Dost olalım dost kalalım

İşleyelim diller ile

Süsleyelim güller ile

Kurumasın ıslatalım

Mahvolmasın seller ile

Tüm varlıklara yaradı

Sevilmek oldu muradı

Kalbe güzel yerleşmeli

Her canlı onu aradı

Göz beğenir dil tutuklar

Sevgi yüklü yaratıklar

Ruhu okşar tatlı sözler

Artar yürekte tık  tık lar', 'At üstünden kaygıları Paylaşalım duyguları Gönüllere su dökelim Kollayalım saygıları İstenir ki şen olalım Her yerde sevgi bulalım İnsanlığı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/maniler-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlizligim', 'yanlizligim-hale-kazak-yglv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kelimelerin anlamini yitirdigi,

Cumlelerin boslukta ucustugu,

Yasamin anlamini verdigi,

Heyecanlarin,sevinclerin

Ve hatta uzuntulerin,

yanlizligini yasiyorum...

Gunesin sicakligini yitirdigi,

Gokyuzunun maviliginin soldugu,

Ruzgarin bile es gectigi

Kapali kapilar ardinda 

Yanlizligimi yasiyorum...', 'Kelimelerin anlamini yitirdigi, Cumlelerin boslukta ucustugu, Yasamin anlamini verdigi, Heyecanlarin,sevinclerin Ve hatta uzuntulerin, yanli...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yanlizligim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıyor', 'kaniyor-fidan-bulut-5egzf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim dik kayalarda şelale,

Aktıkça çoğalıyor

Ruhum boğuluyor çağlayanımda...

Yüreğimin taşkın kırgınlığında

Yalanlar zapdedemiyor bağrımı.

Yangın öyle sıcak, öyle sızı

Gün batımı kızılında kanıyor sevgim,

Durduramıyorum,şafağın kızılına karışacak

Yıldızlar kana bulanacak bu gece.

Kahpe kurşunlar kıskanacak kahpece gidişini...

Başımda omzunun, belimde kollarının hayali

Söyle; ömür tuzağı sevgili

Nasıl silinecek şimdi.

Kartal pençesi sözlerin, sazımda tek nota

Kahpece gidişin, duvarlarımda tek resim.

Bıraktığın karabasan geceme

Tek ışık, kirpik artığı göz yaşım

Kırsam sazımı, yıksam duvarlarımı

Göz pınarlarımı kurutsam,

Çağlayanlarıma barajlar kursam

Zincirlesem yüreğimi

Cam fanuslara kapasam ruhumun fırtınasını,

Ama; 

Sevgim kanıyor....

Sarıyorum yedi kat yaramı

İlle bir yerlerden kan sızıyor.......', 'Gözlerim dik kayalarda şelale, Aktıkça çoğalıyor Ruhum boğuluyor çağlayanımda... Yüreğimin taşkın kırgınlığında Yalanlar zapdedemiyor bağrım...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kaniyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim?', 'ben-kimim-bekir-siddik-demircan-3m681', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimdeki çığlıklar volkan gibi patlarken

Dışımda inadına vurdum duymaz bir tavır.

Kızıyorum kendime,

Bu keşmekeş halime.

Vuruyorum,

Ellerime kelepçe, 

Ayağıma pranga,

Mahkumu götüren gardiyanım bir anda.

Önce sırtıma  savcı cübbesi geçirip,

iddia makamında idam çığırtkanlığı yapıyorum.

Sonra bir bakıyorum elimde hakim tokmağı.

Tam elde kalemimi kıracakken

Dilimden beraat cümlesi dökülüyor

Hem suçluyorum zalimce

Hem koruyorum hamice

Bir zalimi oynuyorum sinsice

Bir mazluma dönüyorum gizlice.

Kendimi tanımak için,

Soruyorum kendime.

Acaba BEN KİMİM? diye.', 'İçimdeki çığlıklar volkan gibi patlarken Dışımda inadına vurdum duymaz bir tavır. Kızıyorum kendime, Bu keşmekeş halime. Vuruyorum, Ellerime...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıddık Demircan']::text[], 8.5, '{"poet":"Bekir Sıddık Demircan","poet_slug":"bekir-siddik-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-kimim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane Kapadokya', 'efsane-kapadokya-fatma-tatli-x6zni', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erciyes dağının manzarasına doyulmaz

İçanadolu''da ondan güzeli bulunmaz

*

Volkanları püskürdü kayalar şekil aldı

Dünya ülkeleri seyrine hayran kaldı

*

Dünyanın sekiz tabiat harikasından biri

Görülmeli efsane Kapadokya''nın güzelliği

Fatma TATLI

www.gunduzkitabevi.com.tr', 'Erciyes dağının manzarasına doyulmaz İçanadolu''da ondan güzeli bulunmaz * Volkanları püskürdü kayalar şekil aldı Dünya ülkeleri seyrine hayr...', ARRAY['Türk Edebiyatı','Şiir','Fatma Tatlı']::text[], 8.5, '{"poet":"Fatma Tatlı","poet_slug":"fatma-tatli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/efsane-kapadokya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Kapıda Yine Aşk', 'i-ste-kapida-yine-ask-fidan-bulut-6quhy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bir çift göz,

Yine uzanmış eller,

Binbir iltifatların, vaatlerin

Esirgenmeden döküleceği dudaklar.

Hayal umut yeminlere hazır

Mühür bir kalp

İşte kapıda aşk...

Ya aç kapıyı

Gelsin teraneler

Ya da duyma zili,

Yak sigaranı, bak keyfine

Çok sıkıldığında, sayarken

Dört duvara

Arada tavanı da ekle.....

(sevgili ablam Sevim E. Tezele geçmiş olsun dileklrimle)', 'Yine bir çift göz, Yine uzanmış eller, Binbir iltifatların, vaatlerin Esirgenmeden döküleceği dudaklar. Hayal umut yeminlere hazır Mühür bir...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iste-kapida-yine-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım - Aşkım', 'askim-askim-mustafa-alpaydin-ozi04', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sende buldum sevdayı sen öğrettin sevmeyi

Sevdalanmazdan evvel bilmezdim kelimeyi

Şimdi çok seviyorum sana ''Aşkım'' demeyi

Ben sana sevdalıyım senden ayrılmam Aşkım.

Seninle tanışmadan sevmek nedir bilmezdim

Seviyorum diyene sevda nedir sormazdım

Seni sevmeden önce aşklara inanmazdım

Ben sana sevdalıyım senden ayrılmam Aşkım.

Kalbim hızlı atıyor nekadar daralmışım

Titreyip duruyorum sanki üryan kalmışım

İşler yolunda bugün fakat nedir telaşım

Bu akşam çıkıyoruz sakın geç kalma Aşkım.', 'Sende buldum sevdayı sen öğrettin sevmeyi Sevdalanmazdan evvel bilmezdim kelimeyi Şimdi çok seviyorum sana ''Aşkım'' demeyi Ben sana sevdalıyı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askim-askim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyetim Kötü Değil Benim...', 'niyetim-kotu-degil-benim-efsun-aydin-49q0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşündükçe kalbim sıkışıyor,

Başlarken neydik şimdi ne olduk biz böyle…

Sen her ölü çiçeğe hayat veren su misali

Girdin öylece hayatıma.

Tarif edemiyorum içimde ki sevgini

Tüm imkansızlıklarla seviyorum seni.

Bin defa düşünüp bir kere konuşmak yerine

Susmak neyi değiştirecek ki? 

Son günüm de yine senin gözlerine bakarak

Nefesini yine yüzümde hissetmek

Ve sadece küçük sıcak bir öpücükle

Akışımı hızlandırmak

SEni seviyorum ben…

Kötü niyetler çok geride artık...', 'Seni düşündükçe kalbim sıkışıyor, Başlarken neydik şimdi ne olduk biz böyle… Sen her ölü çiçeğe hayat veren su misali Girdin öylece hayatıma...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/niyetim-kotu-degil-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat Sanki', 'sanat-sanki-muammer-karatas-2kis6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçların rüzgarları estiren; 

Ruhun bembeyaz şehit sanki,

Kaşların iki mısralık şiir,

Gözlerin boylu boyuna beyit sanki.

O eller ne kucak açtı bana,

Öz bir yana damarda anne sanki,

Mutlu olmayı öğretti bana,

Evde okul misali sahne sanki.

Ellerin hayatımı döndürdü,

Düşüncen ayrı bir isim sanki; 

Duruşun sevginin çizgisi anne,

Güzelliğin tablolarda resim sanki.

Dudakların mehtabı söndürdü yüzümde,

İçin soğuğa yüzük sanki,

Dillerin acemice bir saz,

Şevkatın bestesiz müzik sanki,

Kar sıcağı bezenmiş gözlerine; 

Kolları sevgiden kanat sanki,

zerafet işlenmiş damarına annemin

Özlü özüne ayrı bir sanat sanki.', 'Saçların rüzgarları estiren;  Ruhun bembeyaz şehit sanki, Kaşların iki mısralık şiir, Gözlerin boylu boyuna beyit sanki. O eller ne kucak aç...', ARRAY['Türk Edebiyatı','Şiir','Muammer Karataş']::text[], 8.5, '{"poet":"Muammer Karataş","poet_slug":"muammer-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sanat-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalı kuşu 2', 'cali-kusu-2-ali-riza-unal-gzz8m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir garip kara çalıyım

Dalımda durur çalı kuşu

Zar’ı vuslat, pare halıyım

Sensiz haram oldu huşu! .

Hal ehli konağın gül dalıyım

Haz ehli dudağın dem balıyım

Ben kuşumun ak arası alıyım

Neylenir sensiz  çalı kuşu? .', 'Ben bir garip kara çalıyım Dalımda durur çalı kuşu Zar’ı vuslat, pare halıyım Sensiz haram oldu huşu! . Hal ehli konağın gül dalıyım Haz ehl...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cali-kusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Geldi', 'zamani-geldi-sinan-gundog-xb0vy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeter verdiğimiz şehitler,

Hesabı görmenin zamanı geldi,

Bitsin artık bu ağıtlar,

Defteri dürmenin zamanı geldi.

Dinsin akıtılan masum kanları,

Adice yaktılar onca canları,

Gebertin; gebertin artık bu yılanları,

Karşılık vermenin zamanı geldi.

Boşamı verildi onlarca şehit,

Bu zulme dur diyecek; yok mu bir yiğit? 

İmralıda keyif çatar o it oğlu it,

Bu piçi asmanın zamanı geldi.

Eli kolu bağlı oturur mu bu vatan,? 

El üstünde tutulur mu vatanı satan? 

Ne hallere düştük; kalk da gör atam,

Masaya vurmanın zamanı geldi.

Hariçten gazel sanmayın bu sözleri,

Çeşme oldu bu Sinan''ın gözleri,

Arar oldu  gözlerim çıkacak yiğitleri,

Ortaya çıkmanın zamanı geldi.

Terörist dağlarda cirit atıyor,

Sanmayın kandillide piknik yapıyor,

Terörle mücadele nasıl oluyor? 

Dağlara çıkmanın zamanı geldi.

Kopsun gayrı inceldiği, yerden de kopsun,

Dost kimmiş, düşman kimmiş meydana çıksın,

Canım feda bu yola isterse kanım aksın,

Artık şaha kalkmanın zamanı geldi.

Uykudan uyanmanın zamanı geldi.

YER:SAKARYA/Merkez', 'Yeter verdiğimiz şehitler, Hesabı görmenin zamanı geldi, Bitsin artık bu ağıtlar, Defteri dürmenin zamanı geldi. Dinsin akıtılan masum kanla...', ARRAY['Türk Edebiyatı','Şiir','Sinan Gündoğ']::text[], 8.5, '{"poet":"Sinan Gündoğ","poet_slug":"sinan-gundog","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zamani-geldi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağa ben', 'aga-ben-ali-riza-unal-5lyor', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düzden çıktım dağa ben

Pek dolandım bağa ben

Senin gızından turşu olmaz

Nettim neyledim ağa ben

Güzden çıktım ağa ben 

savurdum hasadı cebe ben

bı yıl başlık  bol oldu

düğünü davıl etcem ağa ben

türkü', 'Düzden çıktım dağa ben Pek dolandım bağa ben Senin gızından turşu olmaz Nettim neyledim ağa ben Güzden çıktım ağa ben  savurdum hasadı cebe ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aga-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu', 'arzu-halil-colak-wh8yk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senin gözlerinle dünyayı seninle görmek

Senin gecelerini gecelerimle birleştirmek 

Mutluluk denizinde seninle el ele yüzmek 

Sana kavuşmak hayatımda en büyük arzum

Mehtaplı gecelerde senle el ele gezmek.

Yakamozlara bakarak seni seyretmek

Geçtiğin yollara sevgi karanfil sermek

Hayatta  mutluk senle en büyük arzum

Halil Çolak 9.8.2005 Yenimahalle/Ankara', 'senin gözlerinle dünyayı seninle görmek Senin gecelerini gecelerimle birleştirmek  Mutluluk denizinde seninle el ele yüzmek  Sana kavuşmak h...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/arzu-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncitme beni,kırma beni ne olur.', 'i-ncitme-beni-kirma-beni-ne-olur-halil-colak-hky25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benlik denizinde yüzme ne olur

En olmadık zamanda üzme ne olur.

Rüyalarımı senle süsle ne olur

İncitme beni,kırma  beni ne olur.

Vuslata ermeden gitme ne olur.

Acıma başka acı katma ne olur.

sevdiğimi yaratan aşkına anla ne olur.

İncitme beni,kırma  beni ne olur.

Halil Çolak 9.8.2005 Yenimahalle/Ankara', 'Benlik denizinde yüzme ne olur En olmadık zamanda üzme ne olur. Rüyalarımı senle süsle ne olur İncitme beni,kırma  beni ne olur. Vuslata erm...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/incitme-beni-kirma-beni-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle oldukça', 'senle-oldukca-halil-colak-ucjto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arzularım bitmez tükenmez senle oldukça

Güllerim solmaz açar sürekli senle oldukça

Yaralarım kabuk bağlar iyileşir senle oldukça

Zaman nasıl geçer anlaşılmaz  senle oldukça

Küçük bir sevgi büyür olgunlaşır senle oldukça

Acılar diner mutluluk başlar sema senle oldukça

Ağlayan göz durur,gülmeye başlar senle oldukça

Bir ömür biter,bitiği anlaşılmaz senle oldukça

Halil Çolak 9.8.2005 Yenimahalle/Ankara 

Saat.01.08', 'Arzularım bitmez tükenmez senle oldukça Güllerim solmaz açar sürekli senle oldukça Yaralarım kabuk bağlar iyileşir senle oldukça Zaman nasıl...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senle-oldukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim sana sevgi', 'ozlemim-sana-sevgi-halil-colak-ffnid', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemim var sana berivanım sevgin içinde

Zarafet var aşkım her bir duruşunda

Letafet var yüzünün her gülüşünde

Erişil  bir feyiz var  canım her bakışında

Mesut oluyorum sevgi seninle konuştuğumda

Halil Çolak 9.8.2005 Yenimahalle Ankara', 'Özlemim var sana berivanım sevgin içinde Zarafet var aşkım her bir duruşunda Letafet var yüzünün her gülüşünde Erişil  bir feyiz var  canım ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlemim-sana-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı İster', 'bahari-i-ster-halil-colak-69via', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgim her zaman senden karşılık ister.

En güzel şekilde sevmeni  gönülden ister

Vermeni kalpını sevgini,aşkını ister

Gönül bahçesini kadınım dikensiz ister.

İlk değil ama senden ikinci baharı ister 

Halil Çolak 9.8.2005 Yeni mahalle Ankara 

Saat 04.45', 'Sevgim her zaman senden karşılık ister. En güzel şekilde sevmeni  gönülden ister Vermeni kalpını sevgini,aşkını ister Gönül bahçesini kadını...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bahari-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Zincir Vurmuşlar', 'sevgiye-zincir-vurmuslar-mustafa-ayik-4fdkn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir duygu kıpırdanırken içimde,

Söyleyemiyorum sana, yüreğim ezik.

Sevgiye zincir vurmuşlar, 

Seviyorum diyemiyorum yazık.

	Aşkım  kara sevda olmuş,

	Kara sevda ise gül.

	Sevgiye zincir vurmuşlar,

	Sana acırım gönül.

Ellerimi uzatırken sana,

Mazi içimde kanar.

Sevgiye zincir vurmuşlar,

Görsen içimde, ne ateşler yanar.

	Ben hep sana koşuyorum,

	Sen ise ne kadar uzak.

	Sevgiye zincir vurmuşlar, 

	Her şey boşuna, hepsi bize tuzak', 'Bir duygu kıpırdanırken içimde, Söyleyemiyorum sana, yüreğim ezik. Sevgiye zincir vurmuşlar,  Seviyorum diyemiyorum yazık. 	Aşkım  kara sevd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiye-zincir-vurmuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-feride-omur-iw0oj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani gitmeyecektin

Gittin

Ve...artık bittim

Ruhumu da götürdün giderken

Boş bir beden 

Gidişinden arda kalan

Ellerim üşüyor

Ellerin yok artık

Bomboş avuçlarım

Gidişinle hançer sapladığın

Yüreğim acıyor birtanem

Oysa hayaller vardı 

Senli, senle süslediğim

Hepsinde gelirdin bana

Hepsinde sarılırdın boynuma

Bazen bir söz

Gülümseten, kırgınlığı yok eden

Bazen bir öpüş

Beni benden eden

Tüm melodiler

Sevda türküsüne dönüşürdü

Ve ruhum ruhunla

Mütemadiyen dansederdi

Söz vermiştin

Hani gitmeyecektin

Ama gittin

Ve...artık bittim', 'Hani gitmeyecektin Gittin Ve...artık bittim Ruhumu da götürdün giderken Boş bir beden  Gidişinden arda kalan Ellerim üşüyor Ellerin yok artı...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gittin-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Vakti Değil Baba', 'aglama-vakti-degil-baba-mehmet-baki-erfidan-oz2jt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saat sabahın dördü,

Hastane kapısında,

Yapayalnız tek başıma,

Bekliyorum babamın başucunda,

Bir bilsen nasıl hasretim sana,sana ve gül kokuna,

Kokuna hasret, sesine hasret, sana hasret her yanım,

İki damla yaş saklarım gözlerimde, gönlümde,

Onu da bugün akittim hastane kapılarında.

Ya Rab sen büyüksün, babamı bize ver,

Nice bayramlar öpeyim onun ellerinden,

Çile bir imtihanmış,hem de ne zor imtihan,

Bana güç ver Allahım,

Babamı bir daha koklamak istiyorum.

İçim daraldı, gırtlağımda taş duvar,

Gözlerim yeter artık, bana lazım damlalar,

Baba dön bak yüzüme, gözlerini göreyim,

Ağlamak vakti değil, seni bir kez daha öpeyim.', 'Saat sabahın dördü, Hastane kapısında, Yapayalnız tek başıma, Bekliyorum babamın başucunda, Bir bilsen nasıl hasretim sana,sana ve gül kokun...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglama-vakti-degil-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyis', 'bekleyis-hale-kazak-5u7qa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Amansiz bir bekleyisdi bu,

Geceli gunduzlu

Kimse duyamazdi feryadimi! 

''feryatlar''sessizdiler...

Kimse bilemezdi kahrolusumu! 

''kahroluslar''gizliydiler...

Benim her umitsiz bekleyisimde

Ayrilik atesini korukleyen

Bir ruzgara kaptirdim kendimi! 

Amansiz bekleyislerde bile,

Bir care yuregim kizmadi sana

Hep sevdim ve bekledim', 'Amansiz bir bekleyisdi bu, Geceli gunduzlu Kimse duyamazdi feryadimi!  ''feryatlar''sessizdiler... Kimse bilemezdi kahrolusumu!  ''kahroluslar''...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekleyis-130-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zamanlar', 'o-zamanlar-mustafa-ayik-na39p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzü olabildiğince mavi,

Ufuklar sonsuz kadar uzak,

Dağlar gökyüzüne haykırırcasına ayakta. 

Güneş ısıtmıyor, 

Baksana ne kadar uzakta

Uçuşan güvercinler dahi cansız,

Zor çıkıyor türküler bile, 

Çatlamış dudakta

Zümrüt yeşili ovalar sessiz,

Bir zamanlar toz bulutu çökerdi yollara,

Ta uzakta kağnı gıcırtıları vardı,

Gıcırtılar yaklaşırdı aheste, aheste…

Yaşlılar yorgun düşerdi,

Yorgun, nefessiz,

Yinede kavruk dudaklarda,  gür bir,

Gür bir türkü duyulurdu,

Gür bir türkü ki, ta uzaklarda.

Her şey eğlenceydi, o zamanlar, 

Oyuncak olan şu yalan dünyada.', 'Gökyüzü olabildiğince mavi, Ufuklar sonsuz kadar uzak, Dağlar gökyüzüne haykırırcasına ayakta.  Güneş ısıtmıyor,  Baksana ne kadar uzakta Uç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/o-zamanlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-bahri-yildirim-ae3ss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen varya sen

Vallahi uslanmazsın

Akıllanmazsın

Sanki hiç bilmiyorsun

Bu diyarlarda sevmelerin

Ne kadar zor olduğunu

Ne dar ağaçlarında sallandığını umutların

Ne kahbe kurşunlara göğüs gerdiğini barışın

Ne zindanlarda yarınsızlığı

Yaşadığını sevdalıların

Nedense,hiç bilmedin.

Sen halâ; 

Şiirler yazmaya uğraşıyorsun

Sevdaların uğruna

Dostluklar adına

Aklına yanayım deli gönlüm

Çok sürmez bu gidişle 

Sen de düşersin sevda zindanlarına

Sana da yakındır dar ağaçları

Böyle devam edersen

İtiraf ediyorum:

Seni kendi ellerimle tutup

Sevgilimin gönül kapısından asacağım

Haberin olsun.

Belki geride kalanlar iyi birşeyler 

Söylerler arkamızdan

Türküler söylerler sevdamıza

Güller açar dost eline

Elden ele taşınırız.bizde

Sevdalıların göz bebeklerinde.

Akıllanır gönlümüz.

Kavuşmalatın tadında

Doyumsuz sevişiriz

Yıkılır dar ağaçları

Çöker zindanlar

Akıllan deli gönlüm

Göründü yolun sonu

Bahar geldi dağlara.', 'Sen varya sen Vallahi uslanmazsın Akıllanmazsın Sanki hiç bilmiyorsun Bu diyarlarda sevmelerin Ne kadar zor olduğunu Ne dar ağaçlarında sall...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/deli-gonlum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Gün', 'yeni-bir-gun-mustafa-ayik-jv7j4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar sabahı,

Çırpınırken sararmış yaprak,

Soyunuyordu kayısı dalı.

Küllenmiş, kurumuş toprak; 

Esen rüzgarla koşuşuyordu,

Sakin ve sessizdi bizim sokak.

Toprak gömülüyordu sessizliğe,

Akan derenin cılız şırıltısıyla.

Göçmen kuşlar gidiyordu, başka yere,

O güzelim göç şarkısıyla.

Bir güzellik sona eriyordu,

Yeni bir güzellikle birlikte.

Yeni bir gün doğuyordu, 

O ıssızlıkta, solgun renkte.

Bir sonbahar sabahında; 

Bir başlangıçtı sonun bittiği yer.

Bu güzelliğin her anında, 

Daha neler vardı; neler, neler.

			01.12.1985', 'Bir sonbahar sabahı, Çırpınırken sararmış yaprak, Soyunuyordu kayısı dalı. Küllenmiş, kurumuş toprak;  Esen rüzgarla koşuşuyordu, Sakin ve s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yeni-bir-gun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi ve Anadolu', 'sevgi-ve-anadolu-mustafa-ayik-9dx4u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anadolu’m! 

Berrak akan pınarlarından; 

Seni içtim, yudum, yudum.

Sayfa, sayfa destanlarından, 

Hep seni okudum.

Derelerin cılız şırıltısında; 

Sevgiyi, kardeşliği duydum.

Yeşeren baharında, süslenen kırında,

Hep sana doydum.

Sen dört başlı sevgisin,

Basmışsın bizi bağrına.

İnsanları severek kucaklamışsın, 

Neler değmez ki senin uğruna.

18.01.1986', 'Anadolu’m!  Berrak akan pınarlarından;  Seni içtim, yudum, yudum. Sayfa, sayfa destanlarından,  Hep seni okudum. Derelerin cılız şırıltısınd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-ve-anadolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapraklar', 'yapraklar-mehmet-baki-erfidan-tt9f8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaprak fisildasmasını bekler dururum kendimce,

Bana söz vermisti gelecem

Ve kulagina fısldayacam tüm gece.

Gelecem karanlıgın kasvetini atacam gonlünden.

Gelcem en guzel şiirlerin ahengi bozulacak ben konusunca,

Piramitlerin gizemi kalkar ortadan ben gelince.

İrem bağlarının rüzgarı da sicak kalir

Benimle gelen yarin selami ise.

Bilmem ruzgarlar mi küstü,

Yoksa gokyuzunde yildizlar mi kalmadi

Yapraklar kimildamaz oldular, fisildamaz oldular.

Oysa ne cok beklemistim bir yapragin sarkilarını,

Ne hayaller kurmustum,

Hercümerc etsin yuregimdeki efkari.

Ne rüyalar görmüstüm, 

Tanıklık ettikleri asklara dair.

Ne tomurcuklar hayal etmistim yüregimde açacak,

Açarken de yüregimdeki cerahatlar döküelcek...

O fisildayınca Karun kadar zengin, züleyha gibi düçar,

Nemrut gibi kral olacaktim.

Onunla oturmus onu dinlerken,

Ebabil kuslari tepeme taşlar yağdirsa

Farkına bile varmayacaktim..

Yağmurla islanmis yuzünde biriken damlalar

Teker teker yüregime duserken,

İbrahim’in atesini sonduren sular olacakti dustugu yer.', 'Bir yaprak fisildasmasını bekler dururum kendimce, Bana söz vermisti gelecem Ve kulagina fısldayacam tüm gece. Gelecem karanlıgın kasvetini ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Baki Erfidan']::text[], 8.5, '{"poet":"Mehmet Baki Erfidan","poet_slug":"mehmet-baki-erfidan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yapraklar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 Mayıs', '19-mayis-mustafa-ayik-0y5k8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gemi açıldı Bandırma’dan  Anadolu’ya,

Bir haber salındı Samsun’a, Bolu''ya,

Afyon’a, Sakarya’ya, bozkır içinde Kulu’ya,

Bağımsızlık meşalesi tutuşturuldu 19 Mayıs’da.

Sömürüye, gericiliğe dur denildi,

Topraklarımıza göz koyanlar bir bir yenildi,

Derneler, Çanakkaleler, nice şehit erler anıldı,

Mustafa Kemal Samsuna çıktı 19. Mayıs’da.

Savaştan bezmiş millet yine haykırdı çoştu,

Mehmetiyle birlikte ana, bacı cepheye koştu,

Zalim düşman meydanlarda yenildi şaştı,

Türk milleti tarihe haykırdı 19 Mayıs’da.

Doğudan batıya birer ağ örüldü,

Sana yapılan haksızlık, zulüm görüldü,

Bunca kahpeye bir bir hesap soruldu,

Kurtuluş savaşına adım atıldı 19. Mayıs’da.

Mustafa Kemal gerçek yolu çizdi

Türkiye’nin yarınlarını bir bir sezdi

Tarih onu altın harflerle yazdı

Açılan yaralara su serpildi 19 Mayıs’da

Bağrı yanık yağız yüzlü erler,

Özgürlük uğruna koyuyordu serler,

Buna cihanda görülmemiş olay derler,

Türk yeniden şahlanmıştı 19 Mayıs’da.

Porsuk’ta, Sakarya’da su kanlı aktı,

9 Eylül, İzmir’de düşmanı denize döktü,

Türk genci senin eşin, emsalin yoktu,

Yıktın engeli, aştın dağları 19. Mayıs’da.

Bir devir battı, bir güneş doğdu,

Tüm milleti neşe, sevinç boğdu,

Haksızı haklı yine kovdu,

Biz barışı kurduk 19. Mayıs’da

Atam; emaneti senden aldı Türk genci,

Kendin eşsizsin, her sözün inci,

Tüm dünyaya sen verdin bu bilinci,

Cehalete karşı and içtik 19 Mayıs’da.

Kemalist Türkiye’yi kurduk Anadolu’da,

Atatürkçülük’tü uygarlığa giden yoluda,

Bizim için yalandı, sağıda, soluda,

Biz yeniden uyandık 19 Mayıs’da.

Ey Türk genci! bu gün senin günün,

Sen yaptığın işle hep öğün,

Türk evladısın yoktur senin sonun, 

Sonsuzluğa el uzattın 19 Mayıs’da.

				19.05.1984', 'Bir gemi açıldı Bandırma’dan  Anadolu’ya, Bir haber salındı Samsun’a, Bolu''ya, Afyon’a, Sakarya’ya, bozkır içinde Kulu’ya, Bağımsızlık meşal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/19-mayis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıla', 'sila-mustafa-ayik-ihdzh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sılamdan çiçekler dersem 

Yardan haber getiren turnalara

Yaklaşsam bir yudum su için

Harıl harıl akan kurnalara

		1985', 'Sılamdan çiçekler dersem  Yardan haber getiren turnalara Yaklaşsam bir yudum su için Harıl harıl akan kurnalara 		1985...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sila-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Git', 'durma-git-mustafa-ayik-ad3mb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutla dolsun o solgun bakışların

Durma git

Senin için çırpınan yürekler var

Tut elimden götür benide

Ulaşılması gereken erekler var

Durma git

Önünde sonsuz ufuklar uzanıyor

Köy, köy, şehir, şehir insan

Sevgi dolu, barış dolu umut dolu

Nice canlar uğruna yanıyor

Durma git

Ulaşılması zor olan ufuklara

Belki bir gün bende gelirim ardın sıra

Birken bin oluruz

Sıra dağlar ardında sıra sıra

Durma git

Zafer bayrağının dalgalandığı günler var.

				18.10.1986', 'Umutla dolsun o solgun bakışların Durma git Senin için çırpınan yürekler var Tut elimden götür benide Ulaşılması gereken erekler var Durma g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/durma-git-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annename', 'annename-aynur-yazici-kgkdb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz bir sabaha erdik yine

Gecem sensizdi annem ve de sessiz

Yitik bırakma beni, ızdırabın seline

Günler boğuluyor, kalıyor nefessiz

Güller günlerde solgun

Şu sıralar, babamın gözleri de yorgun

Yollara bakmaktan, annem

Her gün sonunda o yollar oluyor cehennem

Bir umut tükenirken beyaz sayfalarda

Yıldızlar hüznün türküsünü söyler semalarda

Vuslata özlem bitmiyor, şu yürek darda

İftirak bitsin annem, ne olur gel bu baharda

Kapıdan her girişte sesini duyuyorum uzaktan

“Yine geç kaldın” diyorsun bana

Uykusuz gecenin sonunda, yine ağarıyor tan

Annem gelmez misin, hala doyamadım sana.

Bütün hüzünlü şarkılarda sen varsın

Hasret türkülerinde hep sen

Kolların artık ürkek bedenimi sarsın

Yar var mıdır annem, senden daha ahsen

Tükenmişliklerde can veriyor bedenim

Sabah meltemindeki yaprak gibi titriyor tenim

Bir sesin, bir nefesin, bir de gülen gözlerin

Sen annem sen şu yürekte gidip de dönmeyenim

Seni çok üzdüm,  çok kırdım, biliyorum

Ve diz çöküp önünde senden af diliyorum

Annem gel ne olur, annem ne olur

Ben, ben artık ölüyorum,

Ben artık ölüyorum,

Ben artık ölüyorum...

                                                           (nisan-2003  BURSA)', 'Sensiz bir sabaha erdik yine Gecem sensizdi annem ve de sessiz Yitik bırakma beni, ızdırabın seline Günler boğuluyor, kalıyor nefessiz Gülle...', ARRAY['Türk Edebiyatı','Şiir','Aynur Yazıcı']::text[], 8.5, '{"poet":"Aynur Yazıcı","poet_slug":"aynur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/annename-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G ü n b a t ı m ı 3', 'g-u-n-b-a-t-i-m-i-3-ali-riza-unal-oj8py', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O ne karalık gümüşten kızıla

Dalgalı bulutlarla gün batımı

Kime sükûn kimine hicran

Gecelerin habercisi gün batımı

Nice ızdıraba,nice ayıba haldaş

Nice gayb’ı gerdeğe sır olusun

Ey vuslat ile ölümün hicabı

Nur’u kızıl cemâl gün batımı.', 'O ne karalık gümüşten kızıla Dalgalı bulutlarla gün batımı Kime sükûn kimine hicran Gecelerin habercisi gün batımı Nice ızdıraba,nice ayıba ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/g-u-n-b-a-t-i-m-i-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-mustafa-ayik-kyxvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İsli günün ışığında ayak sesleri,

Günün yorgun sabahında kağnı gıcırtıları,

Köpüren tozlu yollarda yalın ayak analar, anam.

Dehlemiş öküzleri ufuklara doğru yavaş, yavaş.

Yavaş, yavaş.

Ufuklar çok uzak, öküzler yorgun.

Yürüyor bıkmadan, usanmadan yürüyor,

Yürüyor kutsal amaca doğru anam.

Kanayan yaralarında ince bir sızı,

Çatlamış dudağında yanık bir türkü,

Kendini dile getiriyor anam.

Ayağı gibi gönlüde çıplak,

Yüreğine özgürlük tutkusu çöreklenmiş,

Umutlarında hep sevgi kıpırdıyor,

Acılar, ağarmış saçlarında belirirken,

Katettiği yollar çizgi, çizgi çehresinde,

Çileler kat, kat nasır bağlamış,

Nasır bağlamış anamın ellerinde.

Barış anam, tutku anam, sevgi anam,

Dilden dile söylenen, 

Yanık bir türkü anam.

2.12.1986', 'İsli günün ışığında ayak sesleri, Günün yorgun sabahında kağnı gıcırtıları, Köpüren tozlu yollarda yalın ayak analar, anam. Dehlemiş öküzler...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anam-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-mustafa-ayik-t7bbb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürek yanar aşkına 

Beni çevirme şaşkına

Gönül döner coşkuna

Güzel seni görünce

Karşıdan gelişin belli

Ela gözlü yumak elli

Taze fidan körpe dallı

Gönül hoş seni sorunca

Ölürüm yana yana

İçeyim aşk şerbetini kana kana

Güzel kul olayım sana

Derdime derman olunca', 'Yürek yanar aşkına  Beni çevirme şaşkına Gönül döner coşkuna Güzel seni görünce Karşıdan gelişin belli Ela gözlü yumak elli Taze fidan körpe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor', 'sor-aynur-yazici-ioovn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne bir zulme karşı gözyaşı döktüm, 

Ne ölüme

Ne acıya üzüldüm

Ne sancıya

Sor! Adı dünya olan hancıya

Kaç kişi doğdu, öldü

Kalan kaç kişi? 

Dünya, toprak, para, mal, mülk

Hepsi şeytan işi

Doldu taştı bantlar günahlar ile

Her biri, diğerine vesile

Çaldı sevabı şeytan ve cinler

Her kul nefsin sözünü dinler

Güller günahkar oldu

Günler günahkar

Şeytana sorsan 

Eller günahkar.', 'Ne bir zulme karşı gözyaşı döktüm,  Ne ölüme Ne acıya üzüldüm Ne sancıya Sor! Adı dünya olan hancıya Kaç kişi doğdu, öldü Kalan kaç kişi?  D...', ARRAY['Türk Edebiyatı','Şiir','Aynur Yazıcı']::text[], 8.5, '{"poet":"Aynur Yazıcı","poet_slug":"aynur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sor-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Severim de O Anlamaz', 'ben-severim-de-o-anlamaz-bahri-yildirim-eswbk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağaçları severim 

Yemiş yüklü dallarıyla

 Ben severim de onlar anlamaz

Yine de kururlar bazen

Sevilen ölmemeli oysa

Kuşları severim

Gökyüzünün prensesleri,prensleridir onlar

Ben  severim de onlar bilmez

Yine de korkup kaçarlar hemen

Sevilenden korkulmaz oysa

Çiçekleri,böcekleri severim

Belki onlar da severler beni

Severler de söyleyemezler korkudan

Korkular sarmıştır yüreklerini

Aynen senin gibi...', 'Ağaçları severim  Yemiş yüklü dallarıyla  Ben severim de onlar anlamaz Yine de kururlar bazen Sevilen ölmemeli oysa Kuşları severim Gökyüzün...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-severim-de-o-anlamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahir-İ Evvel 1', 'ahir-i-evvel-1-aynur-yazici-ith66', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurudu camda ki buğu

Buğuyu seyretti kuğu

Sıçramadı beynime kan

Dişe diş bir savaş var nefsimle şu an

Sirke dönmüş dünya

Herkes bir cambazlık yapmakta

Yarını aratıyorlar

Dünü unutarak

Bugünü, güne yamamadan

Yamalı bohça oldu seneler

Seneler asırlara yetişme çabasına düşmüş evvelden

Evveli evvele kat

Bana tarihi anlat

Saçındaki teli, telli turnalara gönder

Sen de serhatta hediye eder gibi 

Can veren şühedaya 

Canını kat, kanını kat

Cananın seni beklediğini bilerek

Döndür sen de dünyayı

Batıdan doğuya doğru

Doğrul, kalk yerinden

Semaya uzansın ellerin

Ellerini gösterme kimseye

Göze gelir, gözlerinle birlikte.

05.01.1999-Bursa', 'Kurudu camda ki buğu Buğuyu seyretti kuğu Sıçramadı beynime kan Dişe diş bir savaş var nefsimle şu an Sirke dönmüş dünya Herkes bir cambazlı...', ARRAY['Türk Edebiyatı','Şiir','Aynur Yazıcı']::text[], 8.5, '{"poet":"Aynur Yazıcı","poet_slug":"aynur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ahir-i-evvel-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Bilmek İster', 'gonlum-bilmek-i-ster-mustafa-ayik-dvuwy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırda açılan nergisi

Gonca gonca filizi

Kalbine sakladığın gizi

Gönlüm bilmek ister

Gül için çağrışan bülbülü

Sevdiğine derd olan dikenli gülü

Şarkılar söyleyen dili

Gönlüm bilmek ister

Ahu gözlerinin rengini

Güzelliğinin ahengini

Varsa göstersinler dengini

Gönlüm bilmek ister

Seni saracak kolu

Senin gibi kokacak gülü

Senin için yeşerecek dalı 

Gönlüm bilmek ister

Ateş olup yakışını

Çağlayan olup akışını

Nice gönüller yakışını

Gönlüm bilmek ister

1984', 'Kırda açılan nergisi Gonca gonca filizi Kalbine sakladığın gizi Gönlüm bilmek ister Gül için çağrışan bülbülü Sevdiğine derd olan dikenli gü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonlum-bilmek-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az Şey Yaşamadık Senle', 'az-sey-yasamadik-senle-mesut-alp-9utul', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden diye sorma

Ne olur hiç bir şey deme

Gitmem gerek

Beni unut diyorsun

Seni unutabilmem için 

Hafızamı yitirmem gerek

Delice sevdim diye

Delide mi etmen gerek

Git 

Hadi git

Yolun açık olsun mu desem

Git

Hadi giiiiit

Ardından bedduamı etsem

Madem gidecektin

Bu kadar zaman niye

Dile kolay

Az şey yaşamadık senle

Hadi git

Yolun açık olsun

Başladığım yere döndüm

Hiç yol almamış gibi

Bütün aşklar böyle mi biter

Hiç yaşanmamış gibi.', 'Neden diye sorma Ne olur hiç bir şey deme Gitmem gerek Beni unut diyorsun Seni unutabilmem için  Hafızamı yitirmem gerek Delice sevdim diye ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Alp']::text[], 8.5, '{"poet":"Mesut Alp","poet_slug":"mesut-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/az-sey-yasamadik-senle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aslı Sen Kerem Misali', 'ben-asli-sen-kerem-misali-miyaser-gulsen-h8q40', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elbet bir gün yine karşılaşırız

Ben hancı sen yolcu olur misali

Hasretle özlemle kucaklaşırız

Kor alevde yanan Mecnun misali

Aşarız engeli engel olanı

Sevgiler sereriz yollar misali

Yüce dağlar olsa dayanmaz bize

Deleriz geçeriz Ferhat misali

Mevla yazmış bizi birbirimize

Sen bana ben sana kader misali

Bu sevgide yandık yandık kavrulduk

Ben Aslı Sen ise Kerem misali.', 'Elbet bir gün yine karşılaşırız Ben hancı sen yolcu olur misali Hasretle özlemle kucaklaşırız Kor alevde yanan Mecnun misali Aşarız engeli e...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-asli-sen-kerem-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahir-İ Evvel 2', 'ahir-i-evvel-2-aynur-yazici-w07ml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birin birinde birinciyi buldum

Sonuncusu yok

Yoka sordum sonu

Sonuna dek

Ak sakallı bir derviş 

Elinde bir değnek,

Değneğin ucu dayanıyor hiçe

Hiçi aradım ben de

Tende ürperdi can

Kemiklere sormadan

Sorguyu suali bıraktım artık

Münker ve Nekir’e

Dilim emanet oldu zikire

Fikri unuttum bilmem ki nerde? 

Dilimde kilit var, gözümde perde

Suları ıslatanlara baktım,

Islatamayanlara da 

Islatan, ıslatamayandan az

Güllerde destanın en güzelini yaz

Yazı sevme o kadar

Sonunda sonbahar var

Varı yoka ver

Yoklukta varlık biter

Bitin bittiği yerde bitmeyen tek şey sevgidir

Unutma, unutma, unutma

Sakın ola ki gözünde yaşı kurutma! 

06.01.1999-Bursa', 'Birin birinde birinciyi buldum Sonuncusu yok Yoka sordum sonu Sonuna dek Ak sakallı bir derviş  Elinde bir değnek, Değneğin ucu dayanıyor hi...', ARRAY['Türk Edebiyatı','Şiir','Aynur Yazıcı']::text[], 8.5, '{"poet":"Aynur Yazıcı","poet_slug":"aynur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ahir-i-evvel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Diye', 'gul-diye-mustafa-ayik-y91yo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siyah saçlarını demet demet dererim

Kor düşüren gözlerinde sevdamı ararım

Sensiz geçen bunca günlere yanarım

Gül deyip dalına konarım sevgilim

Kır çiçeğim sevda bahçemin gülü

Sana çıkar yüreğimdeki sevgilerin yolu

Ayrılık ölümden zor, gözlerim dolu dolu

Buseli bakışlarını hicranla anarım sevgilim

Rüyalarımı, hülyalarımı hep seninle süslerim

Duygularımı ummana dönmüş sevdanla beslerim

Zamanın her katresinde mutluluk heveslerim

Sevdamla coşup sana akan pınarım sevgilim

01.12.1999', 'Siyah saçlarını demet demet dererim Kor düşüren gözlerinde sevdamı ararım Sensiz geçen bunca günlere yanarım Gül deyip dalına konarım sevgil...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gul-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Sensiz Hayatı Söyle Nasıl Yaşasın', 'gonlum-sensiz-hayati-soyle-nasil-yasasin-miyaser-gulsen-tp6wm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçlarıma düşen ak kipriğimde damlasın

Gönlüm sensiz hayatı söyle nasıl yaşasın

Tanrı''nın büyük lütfu bahşedilen hayatsın

Gönlüm sensiz hayatı söyle nasıl yaşasın

Gündüzümün güneşi gecemin mehtabısın

Ruhumda ben değilim sen benim ruhumdasın

Ellerim gözlerimsin sen benden bir parçasın

Gönlüm sensiz hayatı söyle nasıl yaşasın.', 'Saçlarıma düşen ak kipriğimde damlasın Gönlüm sensiz hayatı söyle nasıl yaşasın Tanrı''nın büyük lütfu bahşedilen hayatsın Gönlüm sensiz haya...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonlum-sensiz-hayati-soyle-nasil-yasasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimin Adı Ayşe', 'sevdigimin-adi-ayse-mustafa-ayik-6p4po', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayşem,

Bir sonbahar günü

Sevginin tohumlarını ektin yüreğime

Esen rüzgarda savrulurken  duygularım 

Sana sığındım

Siyah saçların tenimi okşarken

Tutunuverdim pamuk ellerine

Ve gözlerin yüreğimde köz oldu

Sevda yüklü duygularım ise

Geziniyor bulut misali gökyüzünde

Seni anlatmaya yetmiyor sözler bile

Güller kifayetsiz solgun

Sevgin sığmıyor yüreğime

Bir çocuk gibi mutluyum 

Sığmıyor içim içime

Sevdiğimin adı Ayşe

Yüreğimde coşku, neşe

30.12.1999', 'Ayşem, Bir sonbahar günü Sevginin tohumlarını ektin yüreğime Esen rüzgarda savrulurken  duygularım  Sana sığındım Siyah saçların tenimi okşa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdigimin-adi-ayse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazsa Sen Giı Buralardan', 'olmazsa-sen-gii-buralardan-ahmet-nural-ozturk-dnf4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmazsa sen git buralardan usul usul

İstersen içinden bir de türkü tuttur 

Yol kısaltan, hüzün dağıtan

Ve beni aratmayan aşksavar bir türkü olsun

Bak sana nasıl da ahenk veriyor 

Yolu yorğun bu uçurum

Olmzsa ben de gelirim belki

Ahenk olursa tahenk tabiii

Olmazsa en iyisi sen

İstediğin yerde bekle beni

Hiç gelmeyecekmiş gibi...', 'Olmazsa sen git buralardan usul usul İstersen içinden bir de türkü tuttur  Yol kısaltan, hüzün dağıtan Ve beni aratmayan aşksavar bir türkü ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olmazsa-sen-gii-buralardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair Ne Varsa', 'aska-dair-ne-varsa-mustafa-ayik-lbiov', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda nedir bilir misin sen? 

Böldü mü hiç uykularını, 

Bir çift buğulu bakış? 

Siyah saçlar, 

Yolunu düşürdü mü hiç geceye? 

Sen hiç ufuklara daldın mı, 

Çıkıp pencereye? 

Ya meyvelere benzettin mi sevgilini? 

Güllerde aradın mı, yarin gül benzini? 

Giydirdin mi hiç gelincikler gibi? 

Kırlara çıkıp, çiçekler arasında aradın mı?

Sen hiç yar diye, vurdun mu dağlara kendini? 

Derelerin şırıltısında aşk şarkıları söylenir, 

Dinledin mi onları, kulak verip? 

Gördün mü, ayrı kalmış sevdalılara ağlayan bulutu? 

Sen hiç baharla  yeşerdin mi yeniden? 

Ak tomurcuklar misali açtın mı? 

Sen yaşadın mı onu söyle? 

Aşka dair ne varsa.

Mutlulukla hüznü, yaşadın mı aynı anda? 

Mutluluk öpücükleri kondu mu dudağına? 

Hiç ayrılmamak üzere birleşirken,

Yolun düştü mü, yine hicrana? 

Üzüldün mü hiç, boşa geçen bunca zamana? 

Ben bunları yaşıyorum, 

Sevgi  denizinin dalgalarında yunarak.

Yaşamayı  öğreniyorum, 

Aşkının ateşinde yanarak.

01.12.1999', 'Sevda nedir bilir misin sen?  Böldü mü hiç uykularını,  Bir çift buğulu bakış?  Siyah saçlar,  Yolunu düşürdü mü hiç geceye?  Sen hiç ufukla...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aska-dair-ne-varsa-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Yakışmaz Asla', 'olum-yakismaz-asla-bahri-yildirim-t6pqi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sapsarı saçlar

Çakmak  çakmak 

Masmavi gözler

Nasılda yakışmıştı O''na

Sadece ölüm yakışmadı.

Bir korkusuzdu ki

Korkular ondan titrerdi

Düşman korkar

Cehalet  korkardı

Sadece ölüm korkmadı

Ölüm ona yakışmadı.

Işımış Selanik''in ufku

Binlerce müjdeler içinde

Yok ki bizi düşünmediği bir zaman

Süslerdi tüm zamanlarımızı

Yurdumuzun her yanında asılı

Sanki:

Mustafa Kemal,bayrak

Sözcükler yetmiyorki anlatmaya

Bu da bizim çaresizliğimiz

Sen sığmazsın Dünyalara

Sözcükler ne yapsın? 

Bir işlemişsin ki içimize

Her yerde bizimlesin

Sen bize çok yakışmıştın

Ölüm sana yakışmadı', 'Sapsarı saçlar Çakmak  çakmak  Masmavi gözler Nasılda yakışmıştı O''na Sadece ölüm yakışmadı. Bir korkusuzdu ki Korkular ondan titrerdi Düşma...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olum-yakismaz-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İse Bir Hiç', 'ben-i-se-bir-hic-mustafa-ayik-o1a3e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahar gelir gün olur

Gün gelir düğün olur

Bir gün sevgi öğün olur

Ben ise bir hiç

Kırlar çiçek açar sevgi olur

Söylenen söz yare övgü olur

İstekler alyanaklara dövgü olur

Ben ise bir hiç

Gün olur ağaç meyveyle yüklenir

Gün olur günler sevgiyle renklenir	

Gün olur sevgiyle sevgili beklenir

Ben ise bir hiç', 'Bahar gelir gün olur Gün gelir düğün olur Bir gün sevgi öğün olur Ben ise bir hiç Kırlar çiçek açar sevgi olur Söylenen söz yare övgü olur İ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ayık']::text[], 8.5, '{"poet":"Mustafa Ayık","poet_slug":"mustafa-ayik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-ise-bir-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum yurdum', 'erzurum-yurdum-halil-colak-e2ypu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yunusların aşkı dadaş sende yaşar 

Hacı Ahmet baba Horasana.şan katar 

Duducu köyünde Tapduk Emre yatar 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Abdurrahman gazi  türbesi paladökende. 

Çifte kardeşler dağın eteğinde.yatmakta 

Habip baba aynı yurtta nazar etmekte 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Erzurum’da evliyalar canım bitmedi 

Abu İsak hatırımdan asla gitmedi 

Dumlu baba dağa vermişte adını 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

İbrahim Hakkı Hz.aslen Erzurum yurdu 

Alvarlı Efe Alvar’da manevi otağı kurdu. 

Hasan baba o güzel diyara adını verdi 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Çoban dede arasa tarihi köprüyü kurdu 

Tekman’la Hınıs’a tarihi bağlantı kurdu 

Toparlak baba toparlak köyünde divanı kurdu 

Benim güzel anayurdum.baba yurdum 

Manevi dinamitlerle dolu Erzurum yurdum 

Kesik baş derler eren senin namına 

Başın bir yerde yatar,gövden bir yerde 

Evliya Mısri Zinnuni senin yanında 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Rabia hatun kadınları ir şad eden evliya 

Çakır baba Norşen yöresini boğardı nura 

Ziyaretli köyü ayrı efsane olan bir yöre 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Horasan baba yüksek bir yerde 

Karanlık ziyaret merkezi yerde 

Çoban dede arasın üstünde harika yerde 

Benim güzel anayurdum.baba yurdum 

Manevi dinamitlerle dolu Erzurum yurdum 

Narman yol ortasında yatar Etem baba 

Hınıs sahip çıkar Şeyh ev dileli dağında 

Çatlı baba dereli de gitti hakkın yolunda 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Süleyman efendi karayazıda divanı kurdu 

Alacalı şey iğ Yusuf şeriatta ona da uydu 

Şeyh Abdülkerim,şeyh Resul aynı yolda buldu 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Horasan ereni de ermişlerle divan kurdu 

Hakka giden erenler bu vatanı korudu 

Erzurum da erenlerin yurdu mekanı oldu 

Benim güzel anayurdum.baba yurdum 

Manevi güzellik dolu Erzurum yurdum 

Halil Çolak 9.8.2005 Yenimahelle /Ankara', 'Yunusların aşkı dadaş sende yaşar  Hacı Ahmet baba Horasana.şan katar  Duducu köyünde Tapduk Emre yatar  Benim güzel anayurdum.baba yurdum  ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/erzurum-yurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-miyaser-gulsen-7pdf1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz susmuş içimdeki çocuksu coşkular

Sanki gecenin rengine bürünmüş yüreğim

Uzat ellerini haydi gel korkma

Topla açmakta olan duygularımın tomurcuklarını

Gel rüyalarıma arada bir

Seni beklemekten beni yorma

Sen gittikten sonra ne bu şehrin tadı var

Ne de havası

Gezdiğimiz mekanlar bile mahzun suskun

Uzat ellerini haydi gel korkma

Sana açık kollarım sarmak için

Ne bekliyorsun? 

Uzat ellerini haydi gel

Gel ne olursun.', 'Sensiz susmuş içimdeki çocuksu coşkular Sanki gecenin rengine bürünmüş yüreğim Uzat ellerini haydi gel korkma Topla açmakta olan duygularımı...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gel-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar Taşım Haykırdı Gerçeği', 'mezar-tasim-haykirdi-gercegi-necmi-unsal-d8eqs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyordum

Bir gün bana

Geleceğini.

O geciken gün

Bu gündü.

Biliyordum

Geçmişi sileceğini.

Sırtından attığın

İnat yükündü.

Biliyordum

Huzuruma gireceğini.

Titreyen ellerinde

Bir demet kır çiçeği.

Biliyordum

Onları toprağıma

Sereceğini.

Mezar taşım haykırdı

Yüzüne gerçeği.

27 Haziran 2004 Pazar, Danimarka-Koge 00.04', 'Biliyordum Bir gün bana Geleceğini. O geciken gün Bu gündü. Biliyordum Geçmişi sileceğini. Sırtından attığın İnat yükündü. Biliyordum Huzuru...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mezar-tasim-haykirdi-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin sen?', 'kimsin-sen-bilal-bavli-0gjtv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nasıl tarif etmeli seni bilmiyorum? 

bir rüzgar esiyor delice 

saçlarını anımsıyorum

''saçları'' diyorum kendikendime

''tıpkı saçları''

ardından bir rüzgar daha 

ve bir rüzgar daha 

kayboluyorum

''gözlerin'' diyorum

birden deniz mavisi oluyorum

tuzlu deniz mavisi



bir gece ansızın vazgeçiyorum

seni kartpostallarda aramaktan

sonra mektuplaştırıyorum seni

her mektubuma ''.....'' diye başlıyor

''Seni seviyorum'' diye bitiriyorum

binlerce mektup oluyorsun

her mektupta bambaşka bir ''sen''



belki bunlardan hiç biri değildin

belki yalancıydı düşlerim

belki seni düşlerken yalan söyledim

belki küçük, şirin bir kızdın

birazda şımarıktın.

yada! 

belki biraz olgun, biraz aşıktın

ne bileyim işte? 

ben ne zaman,kimi sevsem 

sen oluyordun...



Bilal Bavli', 'nasıl tarif etmeli seni bilmiyorum?  bir rüzgar esiyor delice  saçlarını anımsıyorum ''saçları'' diyorum kendikendime ''tıpkı saçları'' ardından...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kimsin-sen-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARANLIK ve...', 'karanlik-ve-bir-acayip-adam-ptoep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyorum! ! ! 

Kalbimde bir sızı 

yanakllarımda hafif bir ıslaklık

Ve tek dostum karanlık...

binalar üzerime geliyordu

sanki! ! ! 

Ve yalnızlığımı hatırlatıyordu

sokak lambaları...

Yalnızlığın iğrenç elleri

dolanmıştı tüm vücuduma

Ve ısırgan otu gibi

yakıyordu heryanımı

Kurtulmak istiyordum

Ama güneş doğuyordu

gitme bekaranlık! 

terk etme beni', 'Yürüyorum! ! !  Kalbimde bir sızı  yanakllarımda hafif bir ıslaklık Ve tek dostum karanlık... binalar üzerime geliyordu sanki! ! !  Ve yalnı...', ARRAY['Türk Edebiyatı','Şiir','Bir Acayip Adam']::text[], 8.5, '{"poet":"Bir Acayip Adam","poet_slug":"bir-acayip-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlik-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliler', 'deliler-bir-acayip-adam-6c0j7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birinci deli karasdevdalı

Elinde kağıt kalem

hep şiir yazıyor 

Ve bir kadın resmi yapıyor

buruşmuş bir mektup avuçlarında

Hem öpüyor hem ağlıyor

SALİH

İkinci deli tanrıya küskün 

çıkmış dinden imandan

Küfrediyor bütün gün 

Kadınları yarattın diye

Kocaman kocaman elleri var

Bir tutuşta parçalayacak gökyüzünü

Bıraksalar onu gardiyanlar

FELİT

Üçüncü deli zavallının biri

Bakışları bomboş cam gibi mavi gözleri

Bir yangında dört yıl önce 

Sevgilisi yanmış cayır cayır

Dayanamamış çıldırmış kahrından

MEMO

Dördüncü delinin aklı başında 

Besbelli hayalleri ömür tüketmiş

Beğenmemiş dünyanın gidişini

İşte ona bu yüzden deli demişler

MEHMET (bir acayip adam)', 'Birinci deli karasdevdalı Elinde kağıt kalem hep şiir yazıyor  Ve bir kadın resmi yapıyor buruşmuş bir mektup avuçlarında Hem öpüyor hem ağl...', ARRAY['Türk Edebiyatı','Şiir','Bir Acayip Adam']::text[], 8.5, '{"poet":"Bir Acayip Adam","poet_slug":"bir-acayip-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/deliler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmişim Sende', 'bitmisim-sende-bir-acayip-adam-6in8b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana yine hüzün geceden

Ellerimde kalan

Ruhumun derinliklerinden 

İnleyen bir zavalı var

Vuruldum kalpten; gülüşüne

Anlatamadım duygularımı

Neylersin bitkinim bitmişim sende', 'Bana yine hüzün geceden Ellerimde kalan Ruhumun derinliklerinden  İnleyen bir zavalı var Vuruldum kalpten; gülüşüne Anlatamadım duygularımı ...', ARRAY['Türk Edebiyatı','Şiir','Bir Acayip Adam']::text[], 8.5, '{"poet":"Bir Acayip Adam","poet_slug":"bir-acayip-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bitmisim-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sen değilim', 'ben-sen-degilim-bilal-bavli-l3n12', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nerden bakarsan bak

ben sen değilim, olamam

hiç bir sevişmekle olmadı işim

kayda alınacak sevgilimde olmadı

sen de olamazsın bilirim

bu yüzden ben sen değilim

bak kimler geçer rüyalarımdan 

sabaha kadar bir sen yoksun

neden diye sormam, bilirim çünkü

sen beni sevmiyorsun

işte bu yüzden 

hiç hayal etmedim senle oluşumu

bir hayal kadar uzaksın

istersen hemen yanı başındayım

ama görmek istemeyecek kadar korkaksın

kimsin, nesin bilmem ama

sen ben değilsin

ve olmak istemeyeceksin', 'nerden bakarsan bak ben sen değilim, olamam hiç bir sevişmekle olmadı işim kayda alınacak sevgilimde olmadı sen de olamazsın bilirim bu yüzd...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-sen-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-bilal-bavli-n4090', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nerde kaldın dost? 

bahara mı aldandın da 

unuttun bizi

içeri geç, aman sessiz ol! 

yanlızlık duymasın sesimizi

susarak konuşalım

gece dinlesin bizi

aslında ne anlatacağım 

halimden bellidir

ya anıları anlatacam

yada sevdiğimi

yinede susalım

gözlerimiz dinlesin gözlerimizi

karanlık uyanmadan gidersin

güneş ''günaydın'' demeden

gül alıngandır bilirsin

kıskanır seni, beni, ikimizi

solar gider ansızın 

yağmur yağar sabaha karşı

ıslanırım, ıslanırsın', 'nerde kaldın dost?  bahara mı aldandın da  unuttun bizi içeri geç, aman sessiz ol!  yanlızlık duymasın sesimizi susarak konuşalım gece dinle...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dost-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost II', 'dost-ii-bilal-bavli-ufk5s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hiç dost yitirmişliğim 

olmamıştı ara sokaklarda

hiç kimseyi sormadım buz gibi kaldırımlara

kimsenin ayak izi beni ilgilendirmiyordu

hep yaşadıklarım vardı

yaşayacaklarımın arkdasında

hep bilinmeyen bir yara kanardı 

göğsümün sol tarafında

ben; 

senden uzakları sevdim

sana yakın olmak için

arada hiç bir engel yok inan

gel desen, 

gelirim...

şimdi ''dost'' diye bağırsam

sen dönüp bakarsın 

binler arasından 

biliyorum! 

bir yerlerde hapsolmuşsun

seziyorum

ağlıyorsun, üşüyorsun.

sen yoksun

belki yitik bir çocuksun

hadi gel! 

bak bende üşüyorum...', 'hiç dost yitirmişliğim  olmamıştı ara sokaklarda hiç kimseyi sormadım buz gibi kaldırımlara kimsenin ayak izi beni ilgilendirmiyordu hep yaş...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dost-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan uzağa', 'uzaktan-uzaga-bilal-bavli-geru5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'unutulmuş bir şehirde

avutulamayan bir şairim

kimsenin şiirinde  gözüm yok

yakışıklı  oğlanları da kıskanmıyorum üstelik

ve kollarında ki güzel kadınları

beklediğim biri var

biraz uzak biraz yitik

karanlıkları örtüyorum 

kimsesizliklerimin üzerine

yalnızlığım hep açıkta kalıyor

gece bile yetmiyor

ufka bakar oldum mu? 

gözlerimde yaş birikiyor

mendilimde kan

uzaktan özledim seni

çok uzaktan', 'unutulmuş bir şehirde avutulamayan bir şairim kimsenin şiirinde  gözüm yok yakışıklı  oğlanları da kıskanmıyorum üstelik ve kollarında ki gü...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bavli']::text[], 8.5, '{"poet":"Bilal Bavli","poet_slug":"bilal-bavli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzaktan-uzaga-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp Neden gittin', 'birakip-neden-gittin-sahin-erturk-j0yyv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni hiç incitmedim

Gözyaşı dötürmedim

Yoksulluk çektirmedim

Bırakıp neden gittin? 

Yalnızlığı kovmuştuk

Acıları yenmiştik

Mutluluğu bulmuştuk

Bırakıp neden gittin? 

Tutsağındı kalemim

Hep seni yazıyordum

İlham perim olmuştun

Bırakıp neden gittin? 

Hani bendim taptığın

Senin bana yaptığın

Aşka büyük ihanet

Bırakıp neden gittin? 

(09.08.2005-Yeni)', 'Seni hiç incitmedim Gözyaşı dötürmedim Yoksulluk çektirmedim Bırakıp neden gittin?  Yalnızlığı kovmuştuk Acıları yenmiştik Mutluluğu bulmuşt...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birakip-neden-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Divanı sûbhâniye 2', 'divani-s-bh-niye-2-ali-riza-unal-ho6ff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ta ki ben ezelden sen ile var’em

Bu bi haddi fukara sen ile yâr’em

O bahrı ummana nur’u nigârem

İnadı ahraza hicap  hayayayı firarem

Gâh mecnuna leyli gâh aslıya keremem

Gâah Musaya asa gâah Nemrutu figânem

Dür-ü dildar avazı dellâl cüzden küle viranem

              NOT

Eserin tamamı değildir na ehle zarar hasıl olmasın

Diye kalanı ehline mahfuz eyledik elhamdûlillah.', 'Ta ki ben ezelden sen ile var’em Bu bi haddi fukara sen ile yâr’em O bahrı ummana nur’u nigârem İnadı ahraza hicap  hayayayı firarem Gâh mec...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/divani-subhaniye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Anam', 'benim-anam-osman-ergun-smvh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mıktad’ın kızıydı benim anam,

Otoriterdi; 

Evde o’nun sözü geçerdi her zaman.

Bütün işleri çekip çevirir, karışmazdı babam.

Bağırır, kızardı hatta bizi döverdi zaman zaman.

Güzeldi; 

Dağ gibiydi, sanki sultandı.

Güzelliği dillere destandı.

Fidan gibiydi, gülünce güller açardı,

Yüzü ay gibi, saçları simsiyahtı.

Çalışkandı; 

Sabah ezanıyla kalkar işe başlardı.

Bir dağdan sebze toplar,

Öbür dağda çalışanlara yemek yapardı.

Bizim kedimiz vardı,

Köpeğimiz, atımız, davarımız vardı.

Tavuklarımız, ineklerimiz vardı.

Onları besler, ineklerin sütünü sağardı.

O’na aitti tamamının tımarı.

Hepsine anam bakardı. Çok çalışkandı.

Sekiz kardeştik, bize çorba yapardı.

Çorbayı tabaklarla getirmez,

Sofraya leğenle koyardı.

Sekiz kaşıktan biri iner biri kalkardı.

Çamaşır vardı, bulaşık vardı, dam tokaçlardı.

Benim anam çok çalışkandı.

Cefakardı; 

Okula giderdik, harçlığımız ondandı.

Yırtık çorapları o yamardı.

Ekin biçer, bağ kazardı

Bir işi bostansa diğeri harmandı.

Usanmazdı; koşardı... koşardı.

Anam çok cefakardı.

Dindardı; 

Dini bilgisi zayıf, bildikleri babadan kalandı.

Ama her sabah, ezanla kalkar,

Başucunda duran beyaz tülbentini

Başına sarıp, namazını kılardı.

Anam, Rabbine çok yalvarırdı.

Saçını süpürge etmek derler ya

Anam için söylenmişti adeta

Çileliydi anam; 

Bir gün attan düştü, başının üstüne

Duymaz oldu, görmez oldu bir süre.

Dediler ki, ur oluşmuş beyninde.

Gezdi acıyla hastane hastane.

Ameliyat edip ur’u aldılar. İyileşti bir süre

Ama olmadı. Kurt girmişti bir kere.

Yıl ikibinbeş, yetmişsekiz yaşında bir nine.

Hastalık ilerlemiş, nüksetmiş yine.

Anam az görüyor, bir günde on adım yürüyor.

Ağlıyor, sızlıyor, çok üzülüyor.

Rabbim elden ayaktan koyma diyor.

Artık ölsem de kurtulsam diyor.

Ah benim anam, çileli anam gün görmeden gidiyor.

2005/Ankara', 'Mıktad’ın kızıydı benim anam, Otoriterdi;  Evde o’nun sözü geçerdi her zaman. Bütün işleri çekip çevirir, karışmazdı babam. Bağırır, kızardı...', ARRAY['Türk Edebiyatı','Şiir','Osman Ergün']::text[], 8.5, '{"poet":"Osman Ergün","poet_slug":"osman-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/benim-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affeyleyin', 'affeyleyin-omer-kucukkaya-q2lpz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmur olup yağsaydım

bereketli topraklara...

yaş olup aksaydım

mazlum yanaklara....

ter olur düşseydim emeğin ortasına

can olup gitseydim dost uğruna

hayat fani allah baki

affeylesin dostlar beni

inceden olsada 

kusurum varsa.....', 'yağmur olup yağsaydım bereketli topraklara... yaş olup aksaydım mazlum yanaklara.... ter olur düşseydim emeğin ortasına can olup gitseydim d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/affeyleyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimdi...', 'sevdigimdi-gurkan-kuzu-i7zg2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahar güneşiydi, sisliydi; 

Ulu kavakların sararma demiydi.

Kıpırdadı birden toprak, sessizdi; 

Sebep bir ilk yağmur tanesiydi.

Filizlenen sonbahar çiğdemiydi,

Masumdu yeni doğma gibi, ürkekti; 

Muhteşemdi, Sevdiğimdi! ! !', 'Sonbahar güneşiydi, sisliydi;  Ulu kavakların sararma demiydi. Kıpırdadı birden toprak, sessizdi;  Sebep bir ilk yağmur tanesiydi. Filizlene...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Kuzu']::text[], 8.5, '{"poet":"Gürkan Kuzu","poet_slug":"gurkan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevdigimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdi İşte', 'sevdi-i-ste-gurkan-kuzu-uxeho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni, 

Var mı ötesi? 

Duysan ki öldü birisi

Senin aşkından bil ki.

Bu birisi kim ki? 

Seviyor işte var mı ötesi! 

Umurunda da değil ötesi berisi,

Aldı kalemi daldı boşluğa; 

Aşkın değer bu sarhoşluğa.

Ey sevgili haykırdım seni, 

Sana uzanan İstanbul yoluna; 

Çınlarsa kalbin yalan sanma.

Sevdi işte seni,

Var mı ötesi?', 'Seviyorum seni,  Var mı ötesi?  Duysan ki öldü birisi Senin aşkından bil ki. Bu birisi kim ki?  Seviyor işte var mı ötesi!  Umurunda da deği...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Kuzu']::text[], 8.5, '{"poet":"Gürkan Kuzu","poet_slug":"gurkan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdi-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-gokhan-saluk-ddnhu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Giderken bir güle güle bile demedin

Oysa ben bütün benliğimle seni bekledim

Sana son kez bir şey söylemek istedim

Seni seviyorum ne olur gitme diyemedim

Öylece baka kaldım giderken

Arkandan bağırmak istedim bütün benliğimle

Ses tellerim isyan edinceye kopuncaya dek

Gitme sen benimsin gitme diyemedim

Oysa seninle ne düşlerim vardı

Şimdi ise ne düşler kaldı ne hatıra

Yalnızca sana bakmak yeterdi 

Onu bile yapamadım sen yine de gitme', 'Giderken bir güle güle bile demedin Oysa ben bütün benliğimle seni bekledim Sana son kez bir şey söylemek istedim Seni seviyorum ne olur git...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Saluk']::text[], 8.5, '{"poet":"Gökhan Saluk","poet_slug":"gokhan-saluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-giderken-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severdim Seni', 'severdim-seni-gurkan-kuzu-kib4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şehrin arka sokağında,

En beteri yalnızlık  ayazında; 

Üzeri çiğ yüklü Arnavut kaldırımında

Sabahçı kahvesi tadıyla son sokakta,

Severdim seni hep, 

	

Bilirsin.', 'Şehrin arka sokağında, En beteri yalnızlık  ayazında;  Üzeri çiğ yüklü Arnavut kaldırımında Sabahçı kahvesi tadıyla son sokakta, Severdim se...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Kuzu']::text[], 8.5, '{"poet":"Gürkan Kuzu","poet_slug":"gurkan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/severdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrindeyim', 'sehrindeyim-gurkan-kuzu-majjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Puslu bir sonbaharın sabahıydı,

Uyanmaya çırpınıyordu daha şehrin; 

Sıcaktı yatağın belki, 

Belki ısınmamıştı senin.

Vapur sesleri duyardım gece derinliklerinde.

Uykum bölünür martı kokardım.

Şimdi, el boyu uzaklıkta o vapur,

Sana gitmeye amade, bende.

Şehrindeyim yani, yani özlediğimdeyim.

İstanbul’dasın,

İstanbul’dayım, 

İstanbul’dayız.

Başlarken şehirde martıların uçuşu, 

Özüme koktu kalbinin çilek kokusu.', 'Puslu bir sonbaharın sabahıydı, Uyanmaya çırpınıyordu daha şehrin;  Sıcaktı yatağın belki,  Belki ısınmamıştı senin. Vapur sesleri duyardım ...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Kuzu']::text[], 8.5, '{"poet":"Gürkan Kuzu","poet_slug":"gurkan-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sehrindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Mevsim Sana..!', 'her-mevsim-sana-dilek-egri-fo62j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yaz akşamıydı 

seni bana getiren

götüren

...eylül 

.....ekim

.......bazende kasım! 

kışları,

rüzgarları sevmemem

hep buyüzden

yağmur seni

rüzgar kokunu

kış yazımı götürdü..

öylece bakakaldım arkalarından...

.....kir götürmeyen bir mevsimdi

.....hakaretler bile karda şakıyordu

önüne geleni 

alıp gidiyordu yağmur

tıpkı seni aldığı gibi

.....birde şimşek çakıyordu

.....yaklaşanı yakarım der gibi! 

şimdi yüreğimde sonbahar

sen dökümü yaşıyorum

gözlerimde de aynı mevsim

bakışlarım bile

kara ve kasvetli....

sende yaz, bahar

gözlerin yeşermiş sevgilim

çiçek kokurıu gönderde

içimdeki buzları eriteyim...

.......izin ver/sen

...............sev/sem 

.....................her mevsim!', 'bir yaz akşamıydı  seni bana getiren götüren ...eylül  .....ekim .......bazende kasım!  kışları, rüzgarları sevmemem hep buyüzden yağmur sen...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/her-mevsim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıya', 'askiya-aynur-sultan-lvfu3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tut ki 

eşkıyanım senin

bu dumanlı baş o yüzden

her yağmalağımda

seni

ince bir sızı 

kalıyor

şuramda', 'tut ki  eşkıyanım senin bu dumanlı baş o yüzden her yağmalağımda seni ince bir sızı  kalıyor şuramda...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyor musun', 'yasiyor-musun-isik-aktas-0tu0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin nasıl bakar acaba şimdi

denizi benim gibi seyreder misin? 

hayata isyanımdır deniz benim; 

kimi zaman umut,

kimi zaman sonsuzluk, 

kimi zaman ağıttır maziye

ellerin nasıldır ki? 

yüreğime dokunduğun günkü gibi sıcak mı,

yoksa

         yalnızlığım gibi soğuk mu? 

saçlarından her rüzgar geçtiğinde

         üşür müsün sen de? 

ya ayakların? 

gittin,

         ve yol bitti mi? 

yoksa 

         İhtiyar Aşıklar Kalesi''ne yürüyor musun? 

türkülerimizi söylüyor mu yüreğin,

yoksa

         sağır mısın bütün sevda şarkılarına? 

bedenini satmıştın bütün kahpeliklere 

                                                      giderken.

ya ruhun? 

bana bırakıp gitmiştin,

yaşıyor musun! 

YAŞIYOR MUSUN! ...

                                         01.08.2005/pazartesi-24.00 Şişli', 'Gözlerin nasıl bakar acaba şimdi denizi benim gibi seyreder misin?  hayata isyanımdır deniz benim;  kimi zaman umut, kimi zaman sonsuzluk,  ...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yasiyor-musun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pas', 'pas-aynur-sultan-gs0r3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'pas izi gibisin

icimde

hiç gitmiyorsun!', 'pas izi gibisin icimde hiç gitmiyorsun!...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/pas-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yılan Güldürdü Beni', 'bir-yilan-guldurdu-beni-ahmet-nural-ozturk-2gytb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Temmuz''un ilk haftası mıydı neydi işte öyle bir şeydi

Yılların en vefasız çayını içtim

Zehir gibi bir şeydi

Su yılanlarının oynaştığı deniz kaçkını bir yerdi

Kısa keselim o kolayı seçti

Tasasızdı gitti

İnanmazsınız tabii

Bodrum dönüşü Bafa gölünde

Bir yılan güldürdü beni...', 'Temmuz''un ilk haftası mıydı neydi işte öyle bir şeydi Yılların en vefasız çayını içtim Zehir gibi bir şeydi Su yılanlarının oynaştığı deniz ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-yilan-guldurdu-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdi', 'sevdi-talip-sinecikli-9qihd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adam sevdi kadını,

Öyle böyle değil,

Sevdi,

Doğru düzgün,

Olması gerektiği gibi.

Önce gözlerini sevdi,

Gözlerine bakan,

Saçlarını sonra,

Omuzlarına dökülen,

Omuzlarını sevdi,

O ipek saçları ağırlayan,

Dilini sevdi,

Sevgiyi fısıldayan,

Kadının dilinden dökülen 

Sözlerini sevdi,

Yalan söyledi kadın sonra,

Yalanı sevemedi,

İhanet etti kadın,

İhaneti sevemedi,

Kadın çekti gitti,

Gidişi de sevemedi.

Adam sevmişti kadını,

Olması gerektiği gibi,

Doğru düzgün sevmişti,

Oysa kadın,

Sevilmeyi becerememişti.', 'Adam sevdi kadını, Öyle böyle değil, Sevdi, Doğru düzgün, Olması gerektiği gibi. Önce gözlerini sevdi, Gözlerine bakan, Saçlarını sonra, Omu...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-aynur-sultan-noslr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her gece tenin tenime göz

kırpar

rüyalarımda

ama ne fayda uzaktasın

asırlarca yıl kadar

giderken

yüreğimide yağmalayıp gittin

bomboş şimdi

ne öfke 

nede hüzün 

nasıl oldu bilmem

sadece özlem var yüreğimin attığı yerde

ne zaman geldi, nasıl oluştu

sen yanımdaykende böylemiydi

yüreğim

hep sana özlem', 'her gece tenin tenime göz kırpar rüyalarımda ama ne fayda uzaktasın asırlarca yıl kadar giderken yüreğimide yağmalayıp gittin bomboş şimdi n...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemesi', 'beklemesi-halil-colak-j76o0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parlak güneşin ışıkları dağlardan aşağı süzülünce.

Kuşlar cıvıldaşıp, çekirgeler durmadan ötünce

Kaz dağının yeşil ormanları oksijeni teneffüs edince

Sevdalı yürekler cehennem ateşi gibi yakınca

Başka bir yaşam başlar akçay da ve dünyada

Sevenlerin ve sevmeyenlerin evrendeki yaşamı

Âşıkların bir birine kavuşmuş olmanın heyecanı.

El ele gönül gönüle birlikte olmanın mutluğu

Güneşin ufuktan ağır batması akşamın başlaması

Yeni bir yaşamın başlaması…..

Yalnızların gecenin sessizliğinde kaybolması.

Gökyüzünde yıldızların birer birer çıkması.

Yalnızlara yalnızlığını unutturması

Gökyüzünü seyrederek 

Yorgun düşüp sızıp öylece uyuması

Bir gün mutluluklar ülkesinden

Mutluk perisinin gelip mutluluk vermesi

Bir gün seveceği insanın karşısına çıkması

Özlemle, inançla yaratandan içten istemesi

 Sevgi seni gibi bir kadını beklemesi…..

 Halil Çolak 9.8.2005 Ankara', 'Parlak güneşin ışıkları dağlardan aşağı süzülünce. Kuşlar cıvıldaşıp, çekirgeler durmadan ötünce Kaz dağının yeşil ormanları oksijeni teneff...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beklemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-cihan-kaya-9y8ci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ev yapacağım,

oyun edasında.

İçine biraz sen koyup,

bozacağım,

ağlarcasına 

ayrılık vedasında

çocuksu huzurumu...', 'Bir ev yapacağım, oyun edasında. İçine biraz sen koyup, bozacağım, ağlarcasına  ayrılık vedasında çocuksu huzurumu......', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oyun-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-i-brahim-kilinc-gbe2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toplandık buraya aynı dilekle

Mutlu olun mutlu kalın dostlarım

Kurulur bir yuva iki yürekle

Mutlu olun mutlu kalın dostlarım

Şen olsun yuvanız tütsün bacanız

Çok fazla olmasın akıl hocanız

Kalsın dışarıda dost akrabanız

Mutlu olun mutlu kalın dostlarım

Aranıza soğuk perde almayın

Bir saatten fazla dargın durmayın

Hep şen şakrak olun gülün oynayın

Mutlu olun mutlu kalın dostlarımn

Çıktınız bir yola veripte karar

Yoklukta çoklukta vermesin zarar

Yarına anıdır şu yaşananlar

Mutlu olun mutlu kalın dostlarım

Hırs insanın kendisine düşmandır

Gelir gözü gider yüzü karartır

Hoşgörüde sonsuz güzellik vardır

Mutlu olun mutlu kalın dostlarım', 'Toplandık buraya aynı dilekle Mutlu olun mutlu kalın dostlarım Kurulur bir yuva iki yürekle Mutlu olun mutlu kalın dostlarım Şen olsun yuvan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dugun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimim Ben?', 'kimim-ben-selim-oz-nrhq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ben seninle yaşıyorum

Güneş yakıyor ben eriyorum

Ay parlıyor ben sönüyorum

Sen şerbet ben zehir içiyorum.

Halden anlamaz seni anlıyorum

Beni düşünmez seni düşünüyorum

Eller bilmez sana ağlıyorum

Nefesimle değil kokunla yaşıyorum.', 'Bir ben seninle yaşıyorum Güneş yakıyor ben eriyorum Ay parlıyor ben sönüyorum Sen şerbet ben zehir içiyorum. Halden anlamaz seni anlıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Selim Öz']::text[], 8.5, '{"poet":"Selim Öz","poet_slug":"selim-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimim-ben-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Gelecek', 'bir-gun-gelecek-atil-kesmen-twpfu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül gözlerime saklanmış

Bir dem sızısı

Çaresizliklere nöbet tutar gibi

Yaşam nefesimi

Acı olarak tetikliyordu

Bir şeyler oluyordu

Gönül çeşmemden damlayan duygularıma

Bir türlü kısamıyor

Hislerime kilitlenmiş benliğimle

Savrulup gidiyordum

Belki de

Bu anlaşılmaz yaşam nefesimi

İçime sindiremiyordum..

Var oluşun ince hesapları şekillenirken 

Hayat havuzun da

Kim kimde nerde ve nerede

Gülerken acı çekiyor, ağlıyor

Aydınlıklar karanlık olmuş

Her sevgi

Kendi yörünğesin de

Kendi çıkarına göre

Bir yol çiziyordu…

Saklanmak 

Sakıncalı yaşamlara damlamaksa

Sevginin özü

Bir gün gelecek

Dudakların kuruyacak

Kalp atışların susacak

Heyecan çığlıkların bedenini terk ederken

Olmayan duyguların

Senden hesap soracak

Ve yaşam yapraklarından kopan

Bir damla ter

Avuçlarına gizlenecek

Seni ağlayacak

Seni yıkayacak…', 'Gönül gözlerime saklanmış Bir dem sızısı Çaresizliklere nöbet tutar gibi Yaşam nefesimi Acı olarak tetikliyordu Bir şeyler oluyordu Gönül çe...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-gun-gelecek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Adayına', 'sevgili-adayina-i-brahim-cetinkaya-surpc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye koysam seni bilmiyorum

Nasırlı yüreğimin her yanı diken

Ya dokunursa hissetmeden

ya acıtırsa dudaklarını

Olmaz ben bu yükle SEVEMEM

Ağustos / 2005', 'Nereye koysam seni bilmiyorum Nasırlı yüreğimin her yanı diken Ya dokunursa hissetmeden ya acıtırsa dudaklarını Olmaz ben bu yükle SEVEMEM A...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgili-adayina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek Zamanı', 'gitmek-zamani-i-brahim-cetinkaya-eo31l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık gitmek zamanı

Kokusu sana emanet güllerimin

Kuşlarımın şarkılarını dinle 

yağmurlarımda ıslan benim yerime

ve gülümse her baktığında güneşe 

Çünkü bir Güneşle döneceğim evime

Ağustos /2005', 'Artık gitmek zamanı Kokusu sana emanet güllerimin Kuşlarımın şarkılarını dinle  yağmurlarımda ıslan benim yerime ve gülümse her baktığında g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gitmek-zamani-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılara Uyanmak', 'acilara-uyanmak-murat-kilic-2-sy73h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günüm fırtınalı bir mart gecesi.

Savrulurum bir öteden diğerine.

Acep mümkün ola mı 

Acısız uyanmak ölüm seherine? 

Kana bulanır geceler,

Rüyalar katıksız kalır.

Bu ağaçta kuruyan yaprağı,

İsimsiz, hoyrat rüzgarlar alır.

Kısa sürer sanıyorken hüznüm,

Sonun başlangıcını belirlediler. 

Sinsice ufkuma dalan yanılgılar,

Gemilerini zihnime demirlediler.

Göz ki gördüğüne meyletmiyor,

Çok incinmiş yaralıdır ruhum.

Nerde, nerde yüce adalet,

Neden böyle huzursuzum? 

Sesin öyle kibirliydi ki bir gün,

Seni duyunca sessiz kaldım.

Maskesi düşünce meleklerin,

Yıkıldım, kendimden utandım.

Gamzelerin, ışıkların yalanmış.

Al da götür benden seni.

İstediğin renklere boya, 

Bana uzak yalan gözlerini.

Ben yokum artık bu uykuda,

Özüm bedenime küsmüş.

Sen ne anlamışsın ki,

Can yanmış yada üzülmüş.', 'Günüm fırtınalı bir mart gecesi. Savrulurum bir öteden diğerine. Acep mümkün ola mı  Acısız uyanmak ölüm seherine?  Kana bulanır geceler, Rü...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/acilara-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Götür Beni', 'al-gotur-beni-murat-kilic-2-xi7nt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey bana maviliği öğreten gökyüzü! 

Öyle bir yağmur istiyorum ki senden; 

Akan göz yaşlarım kadar hisli olup,

Bardaktan boşalırcasına dert alsın benden.

Öyle bir rüzgar çıksın ki birden; 

Kendimi sonbahar yaprağı göreyim.

Özgürlüğe salayım her bir köşemi.

Bilmediğim sonsuzluğa el vereyim.

Öyle soğuklar başlasın ki sokaklarda; 

Yalnızlığı ona bırakıp kendimle kalayım.

Üşüyen bedenlere bir derman diyerek,

Kollarımı yastık, yüreğimi yorgan yapayım.

Son dileğim kaldı; belki imkansız ama,

Seni seyrettiğim gözlerimi alıp götür.

Sende yansısın tüm alemlere ve sonunda,

Bahar tarlasına bırak beni, orada öldür.', 'Ey bana maviliği öğreten gökyüzü!  Öyle bir yağmur istiyorum ki senden;  Akan göz yaşlarım kadar hisli olup, Bardaktan boşalırcasına dert al...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/al-gotur-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alçacık Ağaç', 'alcacik-agac-murat-kilic-2-17q3j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir alçak ağaççığım asırlık çınar değil.

Kırma dalımı ben de yaşayayım.

Gökte süzülen serçe bile naçar değil.

Kırma kanadımı, ben de uçayım.

Dağları delen coşkun nehir iken,

Siper ol bana sende durulayım.

Katıksız bir içki olup dudaklarında,

Gönül mahzeninde yıllanayım.

Kalem olayım narin ellerinde,

Bıkıp usanmadan parmaklarında dolanayım.

Özgürlük ol bayrak ol bana,

Senle coşkulanıp senle şahlanayım.

Zalimin eline salma kaderimi,

Bir başım var onu sana sunayım.

Üzerime giydir ak kadife tenini.

Öleceksem,

Uykularının gölgesinde uyuyayım.', 'Bir alçak ağaççığım asırlık çınar değil. Kırma dalımı ben de yaşayayım. Gökte süzülen serçe bile naçar değil. Kırma kanadımı, ben de uçayım....', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alcacik-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatılmaz', 'anlatilmaz-murat-kilic-2-u3d4f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana benzeyeni bulabilmek,

Anlatabilmek çok zor.

Belki bir meleğin tarifsiz güzelliğinde,

Belki bir mucizenin gizemindesin.

Uçsuz bucaksız hasretlerde yaşayan,

Belki her rengi birbirinden güzel,

Bir ilk bahar çiçeğindesin.

Gülüşündeki gamzeler aşkına,

Bakışındaki çocuk masumiyeti hatırına,

Uslanmaz, aynı zamanda yaramaz,

Afacan ve bendeki düşünülme payına,

Emin ol yakamozlar terk edilecek birisin.

Kısmetsizliğe sönmeyen fener,

Ümitsizliğe dolup taşan,

Sevecen yüreksin.

Sen bende tarifi imkansız güzellik,

Anlatılamama tanrıçası,

Sen özelsin.', 'Sana benzeyeni bulabilmek, Anlatabilmek çok zor. Belki bir meleğin tarifsiz güzelliğinde, Belki bir mucizenin gizemindesin. Uçsuz bucaksız h...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlatilmaz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaramla Birlikte', 'sigaramla-birlikte-baris-kayar-fwi6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'odama sızan karanlık 

devleşen gölgeler

duvarda

pencereden gelen köpek sesi

ve garip tıkırtılar

ve beynimde boğuşan iki kedi

sana kaçıyorum hepsinden

sığınağım

canım sevgilim

ne zaman korkunç düşünceler 

kuşatsa beynimi

kalkanım oluyorsun

ne güzel koruyorsun beni.', 'odama sızan karanlık  devleşen gölgeler duvarda pencereden gelen köpek sesi ve garip tıkırtılar ve beynimde boğuşan iki kedi sana kaçıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Barış Kayar']::text[], 8.5, '{"poet":"Barış Kayar","poet_slug":"baris-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sigaramla-birlikte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyin Beni', 'bekleyin-beni-murat-kilic-2-i23nw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah martıların meskeni.

Hayat bilgelerinin dergâhı,

Hilmi Baba meyhanesi.

Ezgin, özgün ve bilakis üzgün şahsiyet,

Bilmecesi çözülmemiş yoldaşım, divandaşım,

Kara yazığız Bahtiyar ve kulübesi.

Eskici Mustafa, çaycı Nedim, simitçi Halil

Kayıkçı Tahsin, ağların ağlatan ustası Selim…

Sesinizi soluğunuzu özledim be! 

Dostlarım, canlarım, ağalarım, atalarım…

Çok özledim sizleri.

Söylesenize, 

Yine aynı hayat kavgasında mısınız? 

Bir Fener bir Galata dalgasında mısınız? 

Gözümde tütüyor nargile sohbeti.

Meze zengini çilingir sofrasıyla,

Demli bir semaver muhabbeti…

Aldım katığımı vurdum omzuma

Geliyorum yine.

Bir yudum aldığımız hayatın,

Geri kalanını yudumlamaya geliyorum.

Bekleyin beni.', 'Ah martıların meskeni. Hayat bilgelerinin dergâhı, Hilmi Baba meyhanesi. Ezgin, özgün ve bilakis üzgün şahsiyet, Bilmecesi çözülmemiş yoldaş...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bekleyin-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C i b i l l e n k e s i r a', 'c-i-b-i-l-l-e-n-k-e-s-i-r-a-ali-riza-unal-6rmig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gördümkü şaşkın cibillen kesira

Rezili rüsva cibillet cibillen kesira

Bi daddi hesap ganmaz ciale ca’yile

Put olmuş büslet cibillen kesira.

  Divan’ı sûbhaniyeden

--osmanlıca lügâtı sûphaniye---------

cibillen kesira: çok insanlar.

Cibillet: huy,fıtrat, yaratılış  tabiat.

Ganmaz: Aç göz doymayı bilmeyen doyumsuz

Ciale ca’yile:.rüşvet.

Büslet: nam şöhret ün, şan.', 'Gördümkü şaşkın cibillen kesira Rezili rüsva cibillet cibillen kesira Bi daddi hesap ganmaz ciale ca’yile Put olmuş büslet cibillen kesira. ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/c-i-b-i-l-l-e-n-k-e-s-i-r-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Oradaydım', 'ben-oradaydim-murat-kilic-2-mhx6x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızlar kayıyorken meçhul dünyalara,

Yanı başlarındaydım, ben oradaydım.

Gelincikler uçuşuyorken dağ yamaçlarında,

Kokusunu almaktaydım, ben oradaydım.

Gece gerçeğiyle kararırken gök kubbe,

Yanıp sönen ışıklarını saymaktaydım.

Sessizce adımlarımı beklerken cadde,

Hayalinle arşınlamaktaydım, ben oradaydım.

Umudu hüzne dönüştürüyorken gözlerin,

Mahurluğuna nazar boncuğu takmaktaydım.

Sen uykularda tatlı rüyalara bürünmüşken,

Sokakla uyanmaktaydım, ben oradaydım. 

Sen doğan günle uyanmaktayken,

Ben batan günle parçalanmaktaydım.

Alaca karanlığa sürüklenirken umutlar,

Onla aynı karamsarlıktaydım, ben oradaydım.

Hatırlarsan baktığın zaman aynaya,

Ben gözlerindeydim, hep karşındaydım.

Dilin söylerken var olan ihtiyacın şarkısını,

İçinde kıpırdanmaktaydım, ben oradaydım', 'Yıldızlar kayıyorken meçhul dünyalara, Yanı başlarındaydım, ben oradaydım. Gelincikler uçuşuyorken dağ yamaçlarında, Kokusunu almaktaydım, b...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-oradaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni..', 'ben-seni-murat-kilic-2-voy3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni gökyüzünü çevrelemiş,

Yıldızlar gibi seviyorum; 

Işıl ışıl gözlerinle.

Ben seni dağlara hayat veren,

Bahar gibi seviyorum; 

Allı yeşilli çiçeklerinle.

Ben seni yağmurların başlangıcında,

Bir yağmur tanesi gibi seviyorum; 

Islak ama gönülden.

Ben seni ismini yazdığım,

Karalama kağıtlarda seviyorum; 

Yarım yamalak ama yürekten.

Ben seni 360 derece olasılığının yaşanabildiği,

Her ortamda seviyorum; 

Sabah akşam her anda.

Ben seni nefes alma ihtimalinin olabildiği,

Her mekanda seviyorum; 

Aydınlıkta karanlıkta, tüm dünyada.', 'Ben seni gökyüzünü çevrelemiş, Yıldızlar gibi seviyorum;  Işıl ışıl gözlerinle. Ben seni dağlara hayat veren, Bahar gibi seviyorum;  Allı ye...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-seni-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-murat-kilic-2-npsuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bilsen beni ne haldeyim...

Yokluğunda sandım ki öldüm.

Kollarım tutmaz oldu, dilim kuru bir çöl.

Kefene sarmaladım tebessümlerimi,

Sol yanımdan mızrak yemiş gibiyim.

Ansızın, hiç olmadık yerde, 

Ellerimde mayınlar patladı sanki,

Olduğum yerde yıkılıverdim.

Hâlâ seni can özümden alıp giden,

O karanlık yollarda beklemekteyim.

Şimdi, seni bir kez daha göremeyeceğim diye.

Olduğundan daha çok korku beslemekteyim. 

Sen gittin gideli boyun büktü çok sevdiğin

Bütün güzellikler, kurudu tüm yağmurlar.

Rüzgar özgür esmeyi unuttu.

Kendini gizler oldu muhabbet kuşları,

Ağıt yakar oldu türküler, sustu şarkılar.

Dünyanın en güzel yerinde olsam dahi

Gülücüklerime seni eklemeyince,

Sen yanımda olmayınca ne anlamı var.

Mucizelere gebe değil mi hayat, ki; 

Kanatlarımın altına tekrar girdiğinde,

Çiçek tarlası olacak bütün uçurumlar.', 'Bir bilsen beni ne haldeyim... Yokluğunda sandım ki öldüm. Kollarım tutmaz oldu, dilim kuru bir çöl. Kefene sarmaladım tebessümlerimi, Sol y...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-bilsen-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med Cezir', 'med-cezir-banu-balat-cs6eg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen coşuyor delice,

Şelaleden akan su gibi.

Bazen çıldırıyor beynim,

Kendini kaybetmiş bir deli...

Değişiyor durmadan düşüncelerim,

Bir an, senden nefret ederken

Birden ne çok seviyorum seni! ! ...

Yakıyor ama 

Eriyor.

Bitiyor biliyorum, olmuyor..

Sakin ve durgun bir göl değilim

Olamam ki! ! 

Sensiz yapamam,

Seninle hiç yapamam...

Bardaktaki sarhoşluk denizinde 

ve

Kalbimde arıyorum seni...

Sigaramın dumanı anlatmıyor,

İçim ezik

Buruk kalbim...

Gel düzelt istiyorum ama

İzinde vermiyorum sana

Tıpkı sonsuz yıldız kümesinin 

Işığı var şimdi gözlerimde

Artık güneş değil

Sönüyor hissediyorum

Yavaş yavaş ışığım...

Belli ki sonunda hiç kalmayacak

Kim sonsuza dek yaşamak ister ki,

Daha fazla acı çekmek.....

(1994 İstanbul)', 'Bazen coşuyor delice, Şelaleden akan su gibi. Bazen çıldırıyor beynim, Kendini kaybetmiş bir deli... Değişiyor durmadan düşüncelerim, Bir an...', ARRAY['Türk Edebiyatı','Şiir','Banu Balat']::text[], 8.5, '{"poet":"Banu Balat","poet_slug":"banu-balat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/med-cezir-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Bize Bağlayan Birşeyler Var', 'bizi-bize-baglayan-birseyler-var-murat-kilic-2-gt58n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz.

Yani sen ve ben.

Çok ayrıyız, çok farklıyız.

Birbirimize gece gündüz kadar uzağız.

Senin albenili halin var; 

Titrek sesin,

İstemli olarak derin uçurumlara itebilecek

Gamzeli gülüşün var.

Sen bir sahil kentisin.

Bense karlı bir doğu kasabası.

Senin kartpostallardan çıkmışçasına

Okyanus kokan teninle,

Cazibeli, yeşilli mavili ılıman hallerine karşı,

Benim bu bozkır vari,

Acılanmaya meyilli, tekdüze,

Oldurulmuş bir resmimden başka 

Hiçbir şeyim yok.

Belki yönünü yitirmiş bir pusulayım.

Sen ise hiç tanımadığım bir yabancılık.

Ancak anlayamadığım bir şeyler var içimde.

Ve sen gelince aklıma,

Tanımlayamıyorum kendimi.

Adı nedir bunun bilmiyorum.

Bilinmez bir paylaşım! 

Kaderin elleri dokunuverdi beklide bize.

Aynı anda kalbimize.

Ama bildiğim bir şey var ki; 

Bizi bize bağlayan bir şeyler var.

Bizi bize bağlayan bir şeyler var.', 'Biz. Yani sen ve ben. Çok ayrıyız, çok farklıyız. Birbirimize gece gündüz kadar uzağız. Senin albenili halin var;  Titrek sesin, İstemli ola...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bizi-bize-baglayan-birseyler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-ask-yazari-mustafa-cifci-4osjj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevgiliye

yaşamak öylesine güzel ki seninle,

çiçek tarlasında koşmak gibi

ve sırt üstü uzanıp toprağa

gökyüzünü içmek gibi

yaşamak öylesine güzel ki seninle

bunca yalnızlığın

bunca acının

bunca gozyaşının arasında 

her gün umuda koşmak gibi

yaşamak öylesine güzel ki seninle

sımsıcak ve içten bir öpücük gibi

ve seni tanımak 

en büyük şanş gibi', 'sevgiliye yaşamak öylesine güzel ki seninle, çiçek tarlasında koşmak gibi ve sırt üstü uzanıp toprağa gökyüzünü içmek gibi yaşamak öylesine ...', ARRAY['Türk Edebiyatı','Şiir','Aşk Yazarı Mustafa Çifci']::text[], 8.5, '{"poet":"Aşk Yazarı Mustafa Çifci","poet_slug":"ask-yazari-mustafa-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgiliye-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-murat-kilic-2-z5orf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç yağmur yağmadı.

Beklenen hiçbir günde düşmedi rahmet.

Kuru bir ayaz olurdu sabahları.

Gün boyu dudak çatlatan,

Olağan üstü bir gün ışığı,

Sarıverirdi tüm doğayı.

Bazı bazı ağaçlıklara rastlardım.

Etrafı kısacık otlarla yamalı,

Yüzeysel bir acıdan parçalar gibi.

Kenarlarında eski yağmurlardan arta kalan,

Çamur kıvamlı su birikintileri.

Bu durgun şehir,

Bizim memleketin ücra köşelerindeki,

Uzağı uzağa bağlayan yollar gibi.

Bu şehir yalnızlığın çınlayan sesi.

Sadece kendi hasretine ağlayan,

Aslı yağız bir tenin efendisi.

Gözün görebileceği

En keskinliklerin hayat bulduğu,

İçi kor dışı karanlığın ulu gölgesi.

Burası benim mevsimim,

Benim dünyam.

Bu şehir: 

Benim.', 'Hiç yağmur yağmadı. Beklenen hiçbir günde düşmedi rahmet. Kuru bir ayaz olurdu sabahları. Gün boyu dudak çatlatan, Olağan üstü bir gün ışığı...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-sehir-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuyorum', 'susuyorum-turhan-toy-lfzbv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kentin kuytu dipleriydi, gözyaşımla ıslanan

Hasret tırnaklarını geçirmişti beynime

Yanıyordu benliğim, sessiz, puslu gecede

Çaresiz sayfalarda, heceler ürkek, titrek

Aşk urganı boynumda ve şimdi

Susuyorum

Son nefes menzilimde, ahirimin evveli 

Gözlerinde cenneti gezdiğim, ab-ı hayat 

Sözleri biriktirip, harcadığım yüreğim 

Kırılmış satırlara yağmurunu dökerken 

Gecenin arkasında, şakağıma son feryat 

Balyoz gibi iniyor ve şimdi 

Susuyorum 

Gül kokusu seherde, yalnızlık geniz yakar 

Dokunduğun yapraklar, ruhsatsız ve fedakâr 

Gölgesi lal olmanın düşlerini titretir 

Yine çaresizlikle asarsın sözü gize 

Gözyaşında boğulur alev almış her dize 

Bekleyip bakıyorum karanlığın koynunda 

Hasbıhalim fezada ve şimdi 

Susuyorum 

Hep bendim söz söyleyen yosun rengi gözlere 

O kadar allı pullu yaldızlı olmasa da 

Yüreğimden dökülen her biri inci mercan 

Hem yanıp hem yakarken vuslatı arar bu can 

şimdi yorgun ve durgun uçmuyor güvercinim 

Sol yanımı acıtan söze kelepçe vurup 

Ummanın diplerinde yunus ile oturup 

Göz yaşımı döküyor ve şimdi 

Susuyorum 

Artık rahat uyusun düşlerim kuş tüyünde 

Vuslata iki adım mezar ve mahşer kaldı 

Vahalar kum yığını, gülşende güller kopmuş 

Dünya denen şu zindan, kurtuluşa tek kapı 

Vuslat için kapıyı kırıpta çıkıyorum 

O son güne merhaba ve şimdi 

Susuyorum

şiirlerime ve diğer edebi metinlerime turhantoy.com dan ulaşabilirsiniz', 'Kentin kuytu dipleriydi, gözyaşımla ıslanan Hasret tırnaklarını geçirmişti beynime Yanıyordu benliğim, sessiz, puslu gecede Çaresiz sayfalar...', ARRAY['Türk Edebiyatı','Şiir','Turhan Toy']::text[], 8.5, '{"poet":"Turhan Toy","poet_slug":"turhan-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/susuyorum-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduğum Gün', 'dogdugum-gun-cem-karadeniz-t3c6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğduğun güne doğru bir kuş kanadı uçurdum

Ki kutsasın diyegözlerini sımsıcak açtığın o anı,

Doğduğum güne dostça uzattım elimi

Minnete ne lüzum

Hakettiğinin verdi diye sana...

(09/08/2005 - ümraniye)', 'Doğduğun güne doğru bir kuş kanadı uçurdum Ki kutsasın diyegözlerini sımsıcak açtığın o anı, Doğduğum güne dostça uzattım elimi Minnete ne l...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dogdugum-gun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-murat-kilic-2-vltmq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolay sanırdım ayrılmayı.

Unuturum adını sesini diye…

Yanılmışım.

Aldanmışım.

Hem de çok...

Çok zor yokluğuna alışmak! 

Öyle büyük bir acı ki bu, sensiz; 

Çiçeği solgun bir bahar,

Sahipsiz bir yağmur,

Garip bir rüzgar gibiyim.

Öyle sonsuz bir hasret ki bu, yokluğunda; 

Yolunu yitirmiş bir serçe,

Lodosa  yenik bir sandal,

Yıldızı solmuş gece gibiyim.

Bahar yüzlüm! 

Biliyorum ki suç benim.

Zaten, seni suçlayacak kadar değilim.

Ki, öyle düşünüyor olacaksam,

Seni unutacak kadar zehir içerim.

Yokluğunda yalnızlık deryasıyken hayat,

Kadere el verip çaresizce,

Senin acını da çekerim.

Bugün gönül hazinemi,

Bugün dua sahibimi kaybettim.

Bilmiyorum artık,

Kim için dua edeceğim.

Şimdi bakıyorum da avuçlarıma,

Senden geriye sadece,

Bir çift kahverengi göz hayali,

Dudağımda hüzünlü bir buse,

Birde mavili beyazlı bir atkı kaldı.

Sonumun adı mı? 

Tahmin edemeyeceğin kadar; 

Canım yandı.', 'Kolay sanırdım ayrılmayı. Unuturum adını sesini diye… Yanılmışım. Aldanmışım. Hem de çok... Çok zor yokluğuna alışmak!  Öyle büyük bir acı k...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bugun-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olmak', 'seninle-olmak-cem-karadeniz-11xfh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle bir olmak, birarada olmak,

Sana haykırış bir sevda resmi çizmek saadetiyle

.                                                     yırtılıyorum duvarlara

Düzenli bir hayatın

Kırık resminde birleşebilme umudum

Hiç kaybolmadı,

Bu yürek hiç susmayacak

Bu sevda hiç dinmeyecek...

(10/09/99 - 02:30 &  Antalya)', 'Seninle bir olmak, birarada olmak, Sana haykırış bir sevda resmi çizmek saadetiyle .                                                     yır...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seninle-olmak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün Susuyordu', 'yuzun-susuyordu-murat-kilic-2-e5uhc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu rüyanın her bir sahnesinde,

Dokunduğum her şey sana benziyordu.

Kaybetmenin korkusuyla

Başbaşayken hayatımda,

Hayaller hasretle uçsuz bucaksız yaşıyordu.

Ben yitirilmişliğin en ızdıraplı

Müstesnalığını sarmışken kollarımda,

Yüzün susuyordu! 

Düşünsene! 

Zamanın birinde içimizde bir yarış vardı.

Kazanacağız derken umudu kaybettik.

Hep daha iyiyi istiyorduk ve sonunda,

Bencillikten dağlar yaratarak önümüze,

Senli benli olup “bizi” yitirdik.

Oysa çıkar yollar bulmak vardı.

Kaçırılan zamanları yeniden yakalamak…

Sese ses olmak! 

-    “ Merhaba öykücü, ben geldim ”

-    “ Hoş geldin günaydınım” diye,

Sevilene kır çiçekleri toplamak vardı.

Ama sesin hep susuyordu.

Yüzün hep…

Şimdi, benim hayattan alıntılarım,

İçimin derinliklerinde düş kırıkları kaldı.

Şu hasta kalbime yamadığım tek hatıra; 

Uzayıp giden caddelerde, parklarda,

Saçlarını sineme tarayan rüzgarlardı. 

Yüzün susuyor konuşmuyorken,

Anladım sonunda; 

Mevsim çoktan bitmişti, solan baharlardı.', 'Bu rüyanın her bir sahnesinde, Dokunduğum her şey sana benziyordu. Kaybetmenin korkusuyla Başbaşayken hayatımda, Hayaller hasretle uçsuz buc...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuzun-susuyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-murat-kilic-2-95r7f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanatlarında mutluluk taşıyor kelimeler.

Denizler mutluluk yüklü, sahile yanaşıyor.

Tüm renkleri kucaklamış hayat,

Yeniden,

Yenilenerek doğuyor.

Mevsimler anlaşmışlar sanki.

Hepsi bir bir mektup göndermiş; 

“Gel” diyor.

Gel de yaşamayı doyasıya kucakla.

Bu özlemler ülkesi seni bekliyor.

Koynuna alıver şarkılarını türkülerini.

Ellerini uzat yeniden,

Bu alabildiğine mavilik,

Bu kainat mucizesi seni bekliyor.

Bizimle paylaş sevinçlerini bizimle yaşa.

Yeniden,

Yeniden,

Yeniden doğalım sabahlara.', 'Kanatlarında mutluluk taşıyor kelimeler. Denizler mutluluk yüklü, sahile yanaşıyor. Tüm renkleri kucaklamış hayat, Yeniden, Yenilenerek doğu...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeniden-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Ağacın Ölümü', 'yalniz-agacin-olumu-haydar-okur-l3il5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tepenin yamacında 

kuru kıraç toprakta ve yapayalnızım...

saman çöpünce dikenlerin öbek öbek boy verdiği 

bozlak yazın alev alev 

ve sıcaklarında göğünerek yandığım

iki mevsim ölüşlerini 

iki mevsim yaşama tutunmayı yaşadığım 

bir tepenin yamacında

kuru kıraç toprakta yapayalnız ve yaşlıyım

Kurt kuş, börtü böcek yurt bellemişler 

sığınmışlar dallarıma 

onlarla hemhal olmuşum 

onlarla uyumuş ve uyanmışım 

ay şarkıları, yıldız tınıları dinlemişim birlikte 

yeri döşek, göğü yorgan yaparak

tan basımlarında

kuşların kuşça sevinçlerine paylaşmışım 

bir tepenin yamacında 

kuru kıraç toprakta yapayalnız ve yaşlıyım

Hangi rüzgar sürükledi 

hangi kuşun kanadında taşınışım buralara 

nasıl tutunmuşum kuru kıraç toprağa 

yalancı bir baharmıydı ilk uyanışım 

ilkyaz ve son güzmüydü bilemem ki 

bir tepenin yamacında 

kuru kıraç toprakta yapayalnız ve yaşlıyım

Bu yıl yaz hayli uzun ve sıcak geçiyor 

kışın buz kesen soğukları 

yazın kavuran sıcaklarına denk düşüyor 

ne yağmur, ne esinti 

mehtap bile nem vermiyor 

şu kaynağın, o pınarın suları çekilmiş 

bedenim dallarım ve yapraklarım yorgunlaşıyor 

kurumalar başladı ucun ucun 

fersizim ve gücüm tükeniyor

Bir tepenin yamacında /

kuru kıraç toprakta yapayalnız ve yaşlıyım 

dilimde bir tını

El vurmayın bedenime

dinmeyen acılarım var

dallarım kırık dökük

bin yaranın izi var

belki de son yazımdır bu yaşayacağım 

bir tepenin yamacında 

kuru kıraç toprakta yapayalnız yaşamı

şimdi ölen bir ağacım.', 'Bir tepenin yamacında  kuru kıraç toprakta ve yapayalnızım... saman çöpünce dikenlerin öbek öbek boy verdiği  bozlak yazın alev alev  ve sıc...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yalniz-agacin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavşaklar', 'kavsaklar-ali-orkac-eq5pa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey çoban! sana söylemedim mi? 

Çayırlar tükendiği zaman 

Gün olur yeniden yeşerir. 

Karanlık çöktüğü zaman 

Fenerler yine yanacak 

Ortalıklarda dolaşan 

Şu bendeki hevesat 

Yine verecek yeni hasat 

Karınca yolları 

birer meydan görünecek. 

Kına yaktığım güne, 

Haykıracak yeşile boyanan yaprak, 

Kavgalar,deryalar 

ve tüm hışırtılar birbirine dolanacak. 

veryansın edecek gözyaşlarıma. 

Toz penbe bir hayat için, 

Hicaz makamından, 

çalınacak şarkılar. 

Topraktan yollarım olacak, 

taştan yastığım. 

Ve yorganım örülecek, 

renk regk çiçeklerle. 

raks edecek mimiklerim, 

Yarına,düne ve kavşaklar dolusu 

yeni geçmişime. 

11.09.1999 

ali orkaç', 'Hey çoban! sana söylemedim mi?  Çayırlar tükendiği zaman  Gün olur yeniden yeşerir.  Karanlık çöktüğü zaman  Fenerler yine yanacak  Ortalıkl...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kavsaklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '04 Gönderilmemiş Mektuplar', '04-gonderilmemis-mektuplar-cem-karadeniz-khfnt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bir ucu sensiz bir gece, yine mutsuzluğa meydan okuyan duygular ve yine ellerine vurgun bir yürek türküsü yankılanıyor ıssız gözlerimde.

           Yanımda olmayışın ne acı. Yazık ki zaman dindirmiyor coşkun anlatışını sensizliğin. Yüreğine öykünmüş bir damla sızı sarsıyor gövdemi. Ayrı bir dünya hayali, parmak uçlarından göğsümün çeperine dökülüyor ılık ılık.

            Gözlerindeki pırıltının bir anlamı olmalı. Birşeyler anlatıyor olmalı dingin gözbebeklerin. Gri bir sabah esintisine kapılmış bir sevda hayali perde perde dökülüyor üzerime...

             Vücudunun terli coğrafyasında, buram buram sen kokan bir yolculuk arzusu dudaklarımı kavuran, ıslak dudaklarımın arzuladığı tenin kokan bir yaşam.

              Sana sarılabilme umuduyla ürperiyor içimdeki gezgin yaşam. Karnında başlayıp, bacak aranda biten bir gül bahçesi erotizminde saklı yaşayabilme arzusu. İmgesel bir seviş, kıyasıya bir sevişme ya da arzulu bir oynaşma hastalığı sana giden yol. Kenarında erguvan baharına tutulmuş zemheri ayazı.

            Durmamacasına süregelen bir koşma ışıltısında kayıp duygular. Her an; sana kalkan son vapuru da kaçırma endişesi. ''Keşke ölmeseydim! '' de adı geçen yaşayabilmenin kederi. Korkuların yansıdığı zamansız bir vazgeçiş.

             Dedim ya, bir tutam aydınlık esintisiyken içimde, ışıl ışıl bir yalnızlık şarkısı oluverdi mutsuzluk.

             Senin sayende; iyi ki varsın...', 'Yine bir ucu sensiz bir gece, yine mutsuzluğa meydan okuyan duygular ve yine ellerine vurgun bir yürek türküsü yankılanıyor ıssız gözlerimde...', ARRAY['Türk Edebiyatı','Şiir','Cem Karadeniz']::text[], 8.5, '{"poet":"Cem Karadeniz","poet_slug":"cem-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/4-gonderilmemis-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aktoprakta gün ağarırken (Anı)', 'aktoprakta-gun-agarirken-ani-ali-orkac-evbjl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toprakla özdeşleşen her canlı, canlı yaşar. 

Fırtınalı bir kış gününde misafirliğe gidiyoruz,içinde olduğumuz şubat ayında yolumuz Tepebaşı mezrasına düşüyor,mezra Aktoprak’tan uzak kayalık yere kurulmuş dizili evlerle bir kaleyi andırıyor. Hakkari’nin yolunu uzaktan seyredilebilecek bir yerde kurulmuş bir köy. Köyün aşağısındaki uçurumda küçük bir orman var,burası adeta servilerin boy ölçüştüğü mekan. İnsan seyre daldıkça gözlerini uçurumun diğer tarafındaki manzaradan almak istemiyor. Böyle bir manzaradan sonra davetli olduğumuz eve girdik. 

Ev sahibi bizi hoş karşılayarak içeri aldı. Şimdi de dışarıdan farklı bir manzarayla karşılaşıyorum. Akşamları köy ahalinin bir eve toplandığı, o günün dertlerini, sevinçlerini bir arada paylaştığı iki odalı bir ev burası. Odanın her tarafında fare yavruları gibi yuvalanmış çocuklar hanede dolup taşıyor. Ne gariptir ki televizyon ekranlarında ağalığı, toplumu, siyaseti ve ailevi sorunların eleştirildiği bir sinema şölenini hep birlikte seyre dalmışız; ama zıtlık bu ya! Aile reisi bunu sadece bir dramatik doğu koşullarının anlatıldığı bir film olarak görüyor. Kendi payına düşen o ailevi çokluğu gözünden kaçırıyor, ya da bunun bilincinde değil, çünkü her tarafında fare yavruları gibi dizinin dibine çömelen, çocuklarına hiç mi hiç aldırış etmiyor. Aslında ekranlarda ona yönelik bir eleştiri var; fakat kime anlatacaksın bunu. Sadece olumsuzlukları görmek yetmez. İnsan, kendi payına düşeni almalı, bu uğurda somut bir adım atmalı. 

Ve diğer yandan misafirleriyle ilgilenme telaşı içinde olan ev hanımı… insanın acınası gelir bu küçük Tepebaşı evinde yaşananlara tabi ki yaşantı deniliyorsa! Bizlerde koyu bir sohbete dalmışız, köylü günlük işlerden konuşurken söz köyün içinde bulunduğu durumdan açıldı. Herkesten farklı bir ses çıkıyordu. Oda adeta ses kavgasına dönüşmüş. Uzun bir sohbetten sonra ev ahalisiyle vedalaşarak yavaş yavaş köyden ayrılıyoruz. 

Her taraf zifiri karanlık, karlı patika yoldan yürüyoruz köyümüze doğru. Gökyüzü de yarı açık, gökyüzünde de tek tük yıldızlar gözüküyor, ama hafif kar taneleri yağıyor. Yolun kenarında bulunan söğüt ağaçları kar örtüsüyle kaplanmış. Bu puslu havada yürürken Aktoprak’ın ışıkları göründü. Bu ışıklar uzaktan adeta yalnızlığa terk edilmiş bir köy portresini çiziyor. Yolda biraz önce bir tavşanın gittiğini gösteren ayak izleri görünüyor. Arkadaşımız el feneriyle tavşanın izlerini takibe alıyor, ama nafile! Çünkü tavşan el fenerinin ışığıyla son sürat hızla dağın yamacına doğru kaçıyor. Gecenin bu karanlığında yabani tavşan kovalamacasına koyulduk. Bir taraftan arkadaşım Kazım diğer taraftan ben,fakat tavşan tırmandıkça biz yoruluyoruz, en sonunda pes ettik. Yolumuz koyun sürüsünün gittiği bir patika yola çıkıyor. Yol çok dardı. Bir o yana bir bu yana sallanıp duruyoruz yürürken. Nihayetinde Tepebaşı serüveniyle Aktoprak’a. yanımızdaki diğer arkadaşlarla birlikte daldık evlerimize. Kimimiz ders telaşında kimimiz kitap okuma derdinde kimimiz de televizyonda izleyecek film peşinde… 

Gece tüm çıplaklığıyla üzerimize çöküverdi. Odama çekildim. Biraz üşümüştüm. Odamda bulunan elektrik sobasıyla ısınmaya çalışıyorum. Isınmaya çalıştıktan sonra kendimi kitaplarımın kucağına attım ta gecenin geç vakitlerine kadar. Nebi arkadaşımız başını kuma sokan ördek misali o da başını sokmuş sobaya. Halsiz ve çok hastaydı. Ben Nebi’nin yatağını kurup Nebi de yatağına girdi. Şimdi kim bilir acıları ona dert mi yanacak yoksa sevinç ürpertilerini mi unutturacak. Her gece konuştuğumuz aşkları, düşünce düşlerini ve yaşlı köy çınarlarını galiba bu gece konuşmayacağız. Her gece ki dertli dolap görünümlü Nebi kendini koyuverdi. Ne yazık aşkı perçinlemediğimiz, sorunları anlatamadığımız, gelecek ve geçmişten planların birbirini tutmadığı geceleri bu gece ölümüne gömmeceğiz… 

Yine gölgeli kalemim Osman’ın kırıldığına isyan ediyor. Sen narinsin, kul germelisin, nazlı nazlı bir gülümsemenin peşinde koşmalısın, rotan gün doğusudur, günü ve günleri yükseltmek sevdasına tırmanmışsın. Şu biçare yurtsuz ve topraksız insanlara tarafınca kul kanat germelisin. Böyle yazılmalı defterine. Sana öğretilen doğruların davetçiliğiydi. Yıkılanı yapma, ahdini koruma idi. Ve uyuşukluğu değil dinamizmi sofralara sermendi. İlerliyoruz geceye, köyü ve köylüyü arkamıza bırakarak. Herkesin adeta ölüm uykusuna daldığı geceye, yorgunluktan elimdeki kitabı okuyamıyorum. 

Gözlerimde uyku sersemliği belirivermiş, ne okuduğumu bilmeden, anlamadan kitabın sayfalarını evirip çeviriyorum, galiba uykuya dalsam bundan çok daha iyi, çünkü bir şeyi anlamadan okumak, karga gibi boş yere cıyaklamaktan başka bir şey değil. Bu günde tepe taklak Tepebaşı’nın günlük sofrasına gül koyduk bakalım daha ne kadar dikenleri bertaraf edeceğiz. Ben bunları yaşadıkça beynimde ki sorularıma güzel bir yanıt beliriyor: 

Yaşadığın yerler yaşamaya layık değilse bile orada yaşadığın sürece kendin layık olmaya çalış, çünkü yaşadığın yerler ne kadar imkansızlığı önüne serse de bil ki oralarda sana yaşamayı vazgeçilmez 

kılacak hayatları öğretecektir. Yaşamaya bu pencereden baktıkça kendimi yaşamın baharında hissediyorum ve yaşam görev yaptığım nazlı Aktoprak’ın karlı ve karanlık gecelerine devamlı ışığını yansıtacaktır. Ve toprakla özdeşleşen her canlı, canlı yaşar tıpkı Aktoprak gecelerine teslim olanlar gibi… 

04.01.2005 

Ali orkaç', 'Toprakla özdeşleşen her canlı, canlı yaşar.  Fırtınalı bir kış gününde misafirliğe gidiyoruz,içinde olduğumuz şubat ayında yolumuz Tepebaşı ...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aktoprakta-gun-agarirken-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir köyde kandil yanar (Anı)', 'bir-koyde-kandil-yanar-ani-ali-orkac-ixkld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buzul dağlarının eteklerinde yalnızlığın,hüznün,sevincin birbiriyle sarmaş dolaş olduğu,birkaç barınağın adeta bu dağların dostluğuna soyunmuş görüntüsü,insanların yalnızlığına bir dem kusan,çarelerine sonbaharın sonlarına yaklaşırken kışa hazırlık feryatların duyulduğu kuş uçmaz kervan geçmez bir köy: Aktoprak. Dehşetli dağlara yoldaş olan bu güzel isim ismi kadar bahtiyarlık arz etmiyor ne yazık. İnsanları küçük grup yürekleri dağlar kadar,sevgileri dünyaya bedel sıcacık yürekleriyle insanlığın,dostluğun,misafirperverliğin engin denizler kadar ki sevdaları ve daha nice güzellikleri içinde barındıran küçücük diyar. Sevda sözcüklerin en güzel anlatıldığı,aşk sohbetlerin en çok sivri dillerinde dolandıran kara kaşlı köy. Kışın beyazına bürünen yamaçlı köyün, güzel insanlarının her birinin ayrı hikayeleri ve dolu dolu yaşanılan aşkları gömülü vermiş yüreklerine. Serilmiş sofralarına taze cicimsi yaşamlar. Yaşamı mutluca sürdükleri gibi acı,kederli portrelerde çizmiyor değil,kimi annesinde kimi babasından kimi de başka birinden alıyor nefretin acı meyvesini. Bazen birileri senin kapını çalarken belki dünyanın en sorunlu insanıyla karşılaşıyormuşsun gibi gelir sana,içini döktükçe hüzünlü bir sonbaharın sararmış yaprakları gibi acı dolu serüvenlerini,yeni hayatlarını sofrana sererler. Değişimi sürekli isteyen sürekli farklılıklar peşinde koşan,ama hep aynı sorunları yaşamlarına sinmiş olması, onları buhrana sürüklüyor. Her birinin ayrı bir hayal dünyasında gezinmek istemesi,yeni ve yaşanabilir hayat sürdürmek istemeleri onların gerçek köy felsefesini oluşturur. Köy insanlara yol açarken başka yolların kapanmasına kandil yakar,kandilleri yandıkça feryatlar duyulur yaşamlarında ve öyle yaşamlardır ki sabahın erken saatlerinde işe koyulurlar,yaptıkları işlerde hep aynı hayvanlara yem verme, su verme onlarla uğraşma,kızaklarıyla köyden uzak yerden ot getirme,koyunları için her öğün “düne”dedikleri temiz bir kar sofrası yere serme. Ne yapılabilir ki bunların dışında; ama bazen düşündürür insanları. Bu insanlar hayvanlarıyla kızaklarıyla özdeş olmuşlar,onlarla kalkar,onlarla oturur,güzellikleri bu masumvari varlıklarda bulur. Merhameti, şefkati onların o sessiz dünyalarından öğrenip yavrularına da bunlardan öğreterek insanlığın bu şirin dünyasında düşmanlıkları yok edecek öğretileri sunarlar yuvalarına. Belki ileri bir medeniyet değil onların içinde bulunduğu durum; fakat insanlığın kardeşçe yaşanabileceği,dayanışmanın asli gerçekliğiyle var olunabileceği gerçeğini bize öğretiyorlar. Bir yaşam felsefeleri vardır onlarda,hem taşlara yaslanarak hem de ak toprağa dayanarak geceleri kandil yakarlar. Birbirine darılırlar,birbirleriyle kavga ederler,gizli sevda kaçamaklarını da yaşarlar; fakat sevdalarını yüreklerine gömmeyi bildikleri gibi dargınlıklarını da unutmasını bilirler,tıpkı annesinin memesine diş atan bebek misali,anne incindiği için bebeğine kızar; yalnız anne sonradan can havliyle bebeğine sarılır. 

İşte Aktoprak,acıyı,sevinci ve neşeyi içinde barındıran onu yaşatan saydam ve cıvıl cıvıl insanlarıyla kim bilir daha nice seneleri ardına bırakacak nice insanlara merhaba diyecek bir köy. Hazin dolu buzul dağlarına sırdaşlık eden yamaçlı köy ne yolları var ne de yoldaşları her gelenden yemiş feleğin silesini,kimse yokluklarla mücadele eden bu köye uğramamış,uğrayan da: “ Zaten nazlı dağlara sırdaşlık ediyorsunuz,yollarınızın çamurlu olması,cevizli ağaçların varlığı size yeter bu doğal ortamı bozmaya kıyamıyoruz.”deyip köye bir daha da uğramaz olmuşlar. Hep yalnızlığına terk edilen,yokluklarla mücadele eden,yılların ağır yükü altında ezilen,zorlu kışlara göğüs germiş bu güzelim köy hep insanları kucaklayan ve kucaklamanın ötesinde onlara: “ben de insanım insan gibi yaşamaya, hakkım var,yollarımın çamurlu olması köyü görmeyen beylerin çamurlu düşünceleri ve görmeyen çamurlu gözleri nedeniyle hep yalnızlığa terk edilmiş.” Artık tarihten beri kimse görmedi köyü göreceklerini de sanmıyorum. Sana koşacaklardır ey güzel köyüm,sana hasret duyacaklardır,senin buzlu suyuna,karlı dağlarına... 

Ali Orkaç', 'Buzul dağlarının eteklerinde yalnızlığın,hüznün,sevincin birbiriyle sarmaş dolaş olduğu,birkaç barınağın adeta bu dağların dostluğuna soyunm...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-koyde-kandil-yanar-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı bulut', 'kirmizi-bulut-ali-orkac-no9at', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umutlar uçuşur gökyüzünde, 

bulutların ardına 

ve güneşin sevecenliğine 

kendini bırakır. 

bir yudum su isteyişine. 

içer...içer...ama duyamaz 

kırmızı bulut olsa su 

yine gökyüzüne veremez hoşu. 

Gam ve keder 

kırmızı bulut oldu, 

umutlar sıradanlık, 

insan sıradanlık, 

hayat bayağılık, 

kırmızı bulut yine sen, 

oldun başka bir umut. 

yollarında güneş ve masmavi gök 

Ardına düştün,umut oldun. 

kırmızı bulut kendini bulurken, 

Ayı,güneşi ve deniz mavisi gökyüzünü vurdun. 

kırmızı bulut; 

seninki güneşin açılacağına müjde idi 

yüzümü güldürecek, 

sevincime kurşun sıkmayacaktın. 

kurşuni renkteki parmaklarımı 

ve kararsız gündüzlerime 

adını yazacaktın. 

Söyle bakalım kırmızı bulut? 

Umutlar yine uçuşacak mı? 

Ali Orkaç', 'Umutlar uçuşur gökyüzünde,  bulutların ardına  ve güneşin sevecenliğine  kendini bırakır.  bir yudum su isteyişine.  içer...içer...ama duyam...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kirmizi-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekleri çiçeklere verirken', 'cicekleri-ciceklere-verirken-ali-orkac-a94iu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Verdiğin her çiçeği yüreğine işle ki yüreğin çiçek olsun. 

Sonsuza dek süren bir mücadele de kimi zaman hayallerin gerçek olur,kimi zaman da gerçekliğin hayal olur. Bu hayallerin içinde güler yüzle karşılanırsın,ama gerçekler hayal olunca inanmak istemezsin ya da inanmakta zorlanırsın,küçücük bir diyarda bunlar sahneleniyor,güleç yüzler göz yaşı döküyor arkanda. Sen ise aynı duygularla eşlik ediyorsun, fakat senin içinde olduğun durum çok daha farklı çünkü yaşadıkların onların güzel dünyalarına ait narince yaşamlardı.Sen bunları bir daha geri getiremem endişesini taşırken onlar ise seni kaybetme korkusu içerisindeler ve güleç gözler damla damla göz yaşı döker arkanda.Hepimiz bir faniyiz yaşadıklarımız ise yaşamaya başladığımız günden başlayarak hep anılır bir yaşam olur. İşte Aktoprak insanlarının sevimli ve huzur dolu dünyaları saflığı civanmertliği duygusallığı ve daha nice güzellikleri bize göstererek insanlığın varlığını bir kez daha gözler önüne serdirmeyi başardılar. Bu gün son akşam gün boyu dolaşıp durdum. O eski 

günleri yad ettim. Dağlarda renga renk çiçekler topladım. Çiçeklerimin hepsini çiçeklere verdim ve çiçeklerimi verirken de yüreğimi onlara işledim. Hepsi farklı çiçeklerdi tıpkı çiçekleri verdiğim çiçekler gibi. Sevmiştim onlardaki tüm güzellik ve çirkinlikleri, onlarla özdeşleşmiştim. Bazen kızar imalı sözlerle tepki gösterirdim söylenenlere bazen de söylenenlere gülüp geçerdim, ama her seferinde yine güler yüzle karşılanıyordum. 

Sevgi kaçamakları olurdu, çay sohbetlerinde; sevgiden,aşktan,yaşamdan ve daha nicelerinden bahs ederdik. Hele köyün yaşlı amcası Hacı İsmail, ne zaman görse beni hemen koşardı yanıma,bende habire bizim tarihi kökenimizi sorardım kendisine. 

“Hoca sana bir şey sorayım? ”dedi. 

“Buyurun Hacı seni dinliyorum.” 

“ Bak evladım, benim seksene dayanan bir ömrüm var,ama bu güne kadar hiç kimse senin beni sorguya çektiğin kadar sorguya çekemedi. Allah aşkına sen bu güzel soruları hangi amaçla soruyorsun? ” 

“Hacı amca inan ben bunda bir ard niyet taşımıyorum, fakat ömürlük çınardan, gün görmüş biri olarak senden biraz bilgilenmek istedim.” 

Yine başladı hayat macerasını anlatmaya Hacı İsmail. Hep acı çeken bir yürekle anlatır yaşadıklarını, ama biraz da yaşlılığına sitem ederdi. Sevenlerine de bir sitemi vardı. Çünkü ne arayanı ne de soranı vardı. Bazen filozofça deyimler kullanırdı ne de olsa yaşam tecrübesi edinmiş biri. 



Gün batımına doğru birlikte çay yudumlarken, 

“hoca biliyor musun? insan yaşlandıkça kadir kıymeti de azalıyor. Hayat her zaman vefasızlığa kucak açmış ki vefa yaşasın diye.”dedi. 

Ben de bu siteme nazikçe cevap vererek gönlünü almaya çalışıyordum,fakat o yine de olan bitene kırgındı. Hep gençliğin özlem dolu günlerinden konuşur,çevikliğini,cesaret abidesi olduğunu gösteren nice hikayelerini anlatır durur. Yaşlı çınar gün görmüş nazlı dağların nergislerini koklamış koklatmış insanlara,yaylaların soğuk sularını içmiş ve içenlere içirmiş,sevgisini dağlarla bütünleştirmiş. 

Koca yürek Halit Amca ha keza aynı süslemeden nasiplenmiş çok güleç ve esprili bir kişiliğe sahip,çoğu zaman odama gelir hanımı da vefat ettiği için sürekli kadın dünyasından konuşur,müstehcen kelimeler kullanırdı. Ben buna izin vermesem de o yine konuşur. Bülbül gibi şakırdamaya başlar. Bana hep takılır. 

“ Hoca, ya dul ninelerinden birini bana ver ya da bir karı bul. Vallahi karısız olmak canıma tak etti, alınma hoca! inan ki sadece takılıyorum.” 

Ben de söylenenlere ses çıkartmazdım ama gözden uzak gülüp geçerdim. Ve özellikle yaptığı dualar çok tuhaf olurdu. Yine bir ikindi namazından sonra duaya durmuş: “Allah’ım sen verdin daha da vereceksin, eğer vermezsen vallahi darılırım.”her seferinde farklı bir mantığa büründürerek okurdu bu duayı. Yaşamları böyle, inançla gelenek karışımı bir hayat benimsemişler. Yürekli, yerinde durmasını bilen şahsiyetler kazandırmış köy bu dehşetli dağlara, onlar erdemliğin içselleştirmiş halini yaşayaraktan yol alıyor... 

Aktoprak çiçeklerini çiçeklere vererek kandil eteklerinden ayrılıyorum. Sevgilerimizi orada yaşadıklarıma havale ederek onların yüreklerini onlardan çalarak göç ediyorum onların diyarından. Yeni çiçekleri çiçeklere emanet ederekten... 

Bizimki nazlı bir gülümsemenin ardına koşmaktı. Nerede yaşamın silesini yiyen varsa hep oraları mesken tutuyoruz. Şimdi de kimsesizler yurduna göç ediyoruz. Yeni sevgilere yelken açmak için. 

Ali orkaç', 'Verdiğin her çiçeği yüreğine işle ki yüreğin çiçek olsun.  Sonsuza dek süren bir mücadele de kimi zaman hayallerin gerçek olur,kimi zaman da...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cicekleri-ciceklere-verirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar ile halil', 'yar-ile-halil-ali-orkac-wi9c0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir halilim, birde yarim vardı, 

Birinde hepsi, diğerinde birkaçı vardı, 

duygularım. 

Halilim de bahtımı, 

Yarimde tahtımı, 

unuttum. 

Biri bana yol oldu, biri de yoldaş, 

Halilimle planladık, yarimle yaşadık, 

amaçlarımızı. 

Her baharda özlem çektik yanında 

bir tas kahır, 

Bir elde zehir tası, 

Diğerinde gönül tası. 

Yol aldık bir bilinmeze doğru, 

serptim,saçlarımı 

Yollarına yarimin ve vefalı halilimin. 

Kırlarda halilimle dolaşırken sessizce 

seç beğen gül, 

Toplamaya başlardık yarime. 

Ne zaman kırmızıya rastlasak bir 

kenarına 

Halilimin ismini,diğerine de yarimin 

ismini kazdırırdım. 

Dere kenarında patika yol olurdu. 

Yarim yukarıdan halilim aşağıdan 

sesleniyordu. 

Ey yar! sana fırtına oluyorum, 

Ey halil! kendimi sana adıyorum, 

yaklaş! 

Ne hacet yar! sevdamı avucun 

içine yazdın, 

Gönlüme halile,kendini yare, 

verdin. 

Sevdamı avucunun içine yazdın ki, 

çabuk silinebilsin. 

Gönlümü halilime verdin ki 

seni unutabilsin 

Ali Orkaç', 'Bir halilim, birde yarim vardı,  Birinde hepsi, diğerinde birkaçı vardı,  duygularım.  Halilim de bahtımı,  Yarimde tahtımı,  unuttum.  Biri...', ARRAY['Türk Edebiyatı','Şiir','Ali Orkaç']::text[], 8.5, '{"poet":"Ali Orkaç","poet_slug":"ali-orkac","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yar-ile-halil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah kahretsin', 'allah-kahretsin-durmus-karakus-fcpu2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çile çektim dert çektim hep senin için

Söylesene sen neyaptın benim için

Bir hiç uğruna beni terkedip gittin 

Senin gibi sevgiliyi Allah kahretsin

Geceleri senin için uyumuyordum

Mutlu yarınlara hep hayal kurdum

Sen beni kalleşçe sırtımdan vurdun

Senin gibi sevgiliyi Allah kahretsin.

Hiç bir zaman anlamadın bu bendeki sevdayı 

Sendin benim kalbimin kraliçe adayı

Gözlerime bakmadan ettinya son vedayı

Senin gibi sevgiliyi Allah kahretsin.

Sözlerin yalanmış sevgin hep yalan

Üç mektup bir resim elimde kalan 

Seni gidi kahbe zehirli yılan

Senin gibi sevgiliyi Allah kahretsin

Senin gibi sevgiliyi Allah kahretsin..', 'Çile çektim dert çektim hep senin için Söylesene sen neyaptın benim için Bir hiç uğruna beni terkedip gittin  Senin gibi sevgiliyi Allah kah...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/allah-kahretsin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamal...', 'hamal-mehmet-demir-atmali-mypzv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün bedenini sarmış bir gurur,

Helal Haram demeden aşır, aşır...

Burnunun dibine teper de durur; 

Mutfakta yiyip, tuvalete taşır...

Bilmeden yaradılış gayesini,

Anlık zevklerden alır hevesini,

Bacaklar zor taşır da ensesini; 

Üzerinde boza pişir de pişir...

6.8.2005', 'Bütün bedenini sarmış bir gurur, Helal Haram demeden aşır, aşır... Burnunun dibine teper de durur;  Mutfakta yiyip, tuvalete taşır... Bilmed...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hamal-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-selim-oz-tq6d4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Git tek yalnız ben değilim

Karanlık kalır belki içim

Sessiz deniz koyu bir sohbet ederim

Bakma aslında kimsesiz yıldızlarda benim.

Sonuna bilmem ama ilerlerim

Adını unutmam ezberimdesin

Sabaha kalmaz belki son nefesim

Sorma aslında bende sensiz kimsesizmişim.', 'Git tek yalnız ben değilim Karanlık kalır belki içim Sessiz deniz koyu bir sohbet ederim Bakma aslında kimsesiz yıldızlarda benim. Sonuna bi...', ARRAY['Türk Edebiyatı','Şiir','Selim Öz']::text[], 8.5, '{"poet":"Selim Öz","poet_slug":"selim-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/git-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Icimde Sakli', 'sevgim-icimde-sakli-hale-kazak-u5pjq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum demek,

Yayildigini hissetmek bir sarki gibi sonsuza

Sevildigini bilmek,

Bir cocuk gibi salinmak cicek bahcelerine

Hissettigini soylemek gerek,

Gercek olan sevip,sevilmek,

Cosan denizde birlikte yikanmak,

Sarabi birlikte yudumlamak gibi,

Soyleyemedim yuzune sevdigimi,

Guzeldi icimde yasatmak benligini

Seni tuttukca icimde...

Buyuyordum,buyudukce cogaliyordum,

Cogaldikca her zerresinde kendimin,

Sigmaz oluyordum kabina

Su kucuk dunyamin,

Bir kez daha gecisimi yasiyordum,

Baska baharlara,sen bunu hic bilmeden,

Ogreniyordum ''seni seviyorum''demedende sevilebilecegini,

Boylesine sevmeyide ogretiyordun,

Sen bilmeden! 

Seni sevdigimi bilmedigin gibi

Guzeldi boyle yasamak,yasatmak seni,

Guzelliginin yaninda,acittigi duygulari da yasamak,

Bu kiz buyudu sen gormeden,farketmeden

Verdigin o en guzel duygularla...

Simdi soruyorum sana,

Bilseydin bu kadar sevildigini,

Severmiydin sende, boylesine beni? ...', 'Seni seviyorum demek, Yayildigini hissetmek bir sarki gibi sonsuza Sevildigini bilmek, Bir cocuk gibi salinmak cicek bahcelerine Hissettigin...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgim-icimde-sakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Gelme', 'gelme-nurten-altinok-migve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelme üstüme üstüme

Dilime dolanırım

Sözlerime düştüğünde

Türkçe’mden utanırım

Adımı sorsan

Takılır kalırım sesinde

-Unuttum 

Neydi benim adım

Gelme

Gelme üstüme üstüme

-Korkarım

Gideceksen

Gelme…

13/07/2005', 'Gelme üstüme üstüme Dilime dolanırım Sözlerime düştüğünde Türkçe’mden utanırım Adımı sorsan Takılır kalırım sesinde -Unuttum  Neydi benim ad...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelme-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 42', 'eskimez-beyitler-42-huseyin-avdic-r8nke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şair olmak

Okumak! Okumak! : Okuduğunu okumak.

Okuduğunu okumak: İşte şair olmak.

******

Yine Şair olmak

Yazmak, şiir yazmak! : Kalem oynatmak, kolay...

Olmak, şair olmak! : Beyin oynatmak, olay! 

******

Hakikatin peşindeyim

Muhabbed''in izindeyim, düşmanlığa vaktim yok.

Hakikatin peşindeyim, sağ''a sol''a karnım tok.

---

Not: ''Muhabbed'' aynı zamanda Muhammed(sav) e de

işarettir.

******

Dünyayı vuran kurd

Hudson''u yutan Afrika kurdu,

Beyaz perdeden dünyayı vurdu! 

******

Açlık

Nerde Afrika nerde? Avrupa''nın karnında! 

Feryad ediyor açlık, insanlığın ruhunda! 

******

Bana yeter

Ne mekân isterim, ne zaman; 

Bana yeter Bediüzzaman.

Batı Berlin, 1980-85.', 'Şair olmak Okumak! Okumak! : Okuduğunu okumak. Okuduğunu okumak: İşte şair olmak. ****** Yine Şair olmak Yazmak, şiir yazmak! : Kalem oynatm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/eskimez-beyitler-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-belgin-turan-pnkgd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutmasanda bir an, gün gelir unutursun,

İçindeki sevdanı, gizlice uyutursun.

Bahar kışa erince, güller  boyun eğince,

Gönüle aşk girince, bu gün düne erince.

Unutursun sende beni, unutursun nur tanem,

Unutmaz gönül seni, der:O benim bir tanem.

                                              Belgin Turan', 'Unutmasanda bir an, gün gelir unutursun, İçindeki sevdanı, gizlice uyutursun. Bahar kışa erince, güller  boyun eğince, Gönüle aşk girince, b...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/unutamam-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin olayım', 'senin-olayim-halil-colak-0dsku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel bana nazlı çiçeğim 

Kadehte aşkımı  sana sunayım 

İste aşkım yeterki sen 

Ebedi sevgi senin olayım 

Halil Çolak 9.8.2005 Ankara', 'Gel bana nazlı çiçeğim  Kadehte aşkımı  sana sunayım  İste aşkım yeterki sen  Ebedi sevgi senin olayım  Halil Çolak 9.8.2005 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senin-olayim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dùsler Sokagi', 'd-sler-sokagi-ufuk-nazim-r2cjb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonsuz düşler sokağı 

Gözlerimiz ilk 

Ne zaman düştü 

O sokağa; 

Yolumuzda 

Şatolar yükseldi 

Umuttan yüce 

İş işten geçmeden 

Dirildik yeniden 

Düşler sokağında. 

Yürüdük sevişmelerimizle 

Yeşerdi dünya 

Şehirler 

Kahkahalarımızla şenlendi 

Ve daldı 

Aydınlığın orduları 

Zorbalığın içine. 

Düştü 

Kapakları gözlerimizin 

İçimizde kuruyan sevgi 

Yürüdü 

Bahar dallarınca.', 'Sonsuz düşler sokağı  Gözlerimiz ilk  Ne zaman düştü  O sokağa;  Yolumuzda  Şatolar yükseldi  Umuttan yüce  İş işten geçmeden  Dirildik yeni...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusler-sokagi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozlem', 'ozlem-ufuk-nazim-icii8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlem 

Yağmurlar yağdı üstüme 

Billur bir 

Damlaydın sen 

Ey yar! 

Göğün gözlerinden 

Süzülen. 

O en güzel 

Günler için. 

Savrulan insanlardandın 

Yaşanılası 

Bir dünya için 

Acıdan umuda 

Giden yolda 

Onurlu bir insandın sen. 

Doğruları ve umudu için 

Yaşamın gözlerinden 

Sağılan umuttun sen', 'Özlem  Yağmurlar yağdı üstüme  Billur bir  Damlaydın sen  Ey yar!  Göğün gözlerinden  Süzülen.  O en güzel  Günler için.  Savrulan insanlard...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlem-238-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyidir Yürümek Öfkelenince', 'i-yidir-yurumek-ofkelenince-bekir-mutlu-gokcesu-yl57z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimden ve neden kaçtığını bilmiyordu

Öfkeyi hissetmek istiyordu sadece ve özgürce

Bir buna hakkı olduğunu düşündü

Avazı çıktığı kadar bağırmak hani

Gökyüzüne...

Su sızmıyordu aralarından 

Sırt sırta, omuz omuza derme çatma evlerin

Üstüne yıkılacak kadar meyletmişti gölgeleri sokağa...

Bir ışık dahi yoktu yalnızlığını haykıracak yüzüne

Şöyle yüreklice...

Dışlanmamıştı aslında ama o öyle hissetti ya da hissetmek istedi

Lazım olunca bulunmuyordu işte, bulunmuyordu bir avuç gökyüzü de...

Ev evdi, sokak sokak oysa, kafasının içindeki kadardı insansa

Gerek yoktu bu kadar da kendini önemsemeye

Yürüdü öfkelerini eze eze, kaçtığı ne varsa üstüne üstüne

Ayakkabılarının çıkarabileceği en yüksek sesle

Bir buna hakkı olduğunu düşündü

Paldır küldür yürümek hani dilediğince

Yürüdü, güldü, güldü, yürüdü, güldü...', 'Kimden ve neden kaçtığını bilmiyordu Öfkeyi hissetmek istiyordu sadece ve özgürce Bir buna hakkı olduğunu düşündü Avazı çıktığı kadar bağırm...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iyidir-yurumek-ofkelenince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Say Ki Mustafa Kemal’im', 'say-ki-mustafa-kemal-im-selahattin-durna-isoq4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Say Ki Mustafa Kemal’im

Dur yok,durak yok,

Koşarım

Uzaklar yakın,uzaklar yakın; 

Dağların arkasını bulurum,öğretmenim

Bir kırlangıç kuşudur yüreğim,uçar gider

Mavisinde coğrafyanın.

Kış kim,kıyamet kim…? 

Uzatır ellerimi ısıtırım öğretmenim

Mucizeler yaratmış onurlu bir tarihin

Sıcacık belleğinde; 

Say,Mustafa Kemal’im.

Ölüm yok ki…

Nefesi tükenir kalır gündelik kaygıların

Canıma can katarsın,büyürüm gözlerinde

Dudaklarında,öğretmenim,yarını memleketin

Büyür güzele,güzele…

Dur yok,durak yok.

Yol olurum

İnan bana öğretmenim

Mucizeler yaratmış onurlu bir tarihin

Sıcacık belleğinde.

Say,Mustafa Kemal’im.', 'Say Ki Mustafa Kemal’im Dur yok,durak yok, Koşarım Uzaklar yakın,uzaklar yakın;  Dağların arkasını bulurum,öğretmenim Bir kırlangıç kuşudur ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/say-ki-mustafa-kemal-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz gözlüm.', 'deniz-gozlum-i-shak-ozlu-q5048', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '…

Bir seni sevdim,

Bir de denizi.

Deniz gözlerindi, 

Ruhuma işleyen. 

Dalgalar kolun, 

Tenimi saran.	 

Yosun saçların, 

Aşka çağıran. 

Mehtap düşünce, 

Umut saçan, 

Karanlık basınca, 

Hüzün çöken. 

Deniz gözlüm. 

Değişti rengi, 

Mavi denizin. 

Duramam buralarda, 

Dalgayı kayalara, 

Sesini martılara, 

Umudu yolculara, 

Hüznü bulutlara, 

Yükler giderim,

Denizden uzaklara.

İshak Özlü', '… Bir seni sevdim, Bir de denizi. Deniz gözlerindi,  Ruhuma işleyen.  Dalgalar kolun,  Tenimi saran.	  Yosun saçların,  Aşka çağıran.  Mehta...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deniz-gozlum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehitlerim Gazilerim', 'sehitlerim-gazilerim-muammer-baydere-j0gxu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vatana can katarsınız

Bu günlerim mazilerim

Siz gönlümde yatarsınız

Şehitlerim gazilerim

Sizden özür diliyorum

Hatalıyız biliyorum

Yüreğimle geliyorum

Şehitlerim gazilerim

Gözünüzü arkalarda

Bırakanlar kalsın darda

Kara,deniz,havalarda

Şehitlerim gazilerim

Yanınızda olamadım

Derde derman bulamadım

Arayıp da soramadım

Şehitlerim gazilerim

Ben insanım Hakk kuluyum

Ha batı ha doğuluyum

Müslüman’ım Türk oğluyum

Şehitlerim gazilerim

Sizden farklı sözüm yoktur

Yad ellerde gözüm yoktur

Karşınızda yüzüm yoktur

Şehitlerim gazilerim

Ölenlere olsun rahmet

Kalanlara neden zahmet

Kimi Mehmet kimi Ahmet

Şehitlerim gazilerim

Ayşe’niz var Fatma’nız var

Boynu bükük yatmanız var

Vatan için batmanız var

Şehitlerim gazilerim

Şov yapmasın kimse sizle

Elinizle dizinizle

İç içeyim hepinizle

Şehitlerim gazilerim

Öyle veya böyle dünya

Geçip  gider olur rüya

Sığınırız Ya Mevla’ya

Şehitlerim gazilerim

Hakkınızı vatan için

Bu uğurda yatan için

Helal edin Atam için

Şehitlerim gazilerim', 'Vatana can katarsınız Bu günlerim mazilerim Siz gönlümde yatarsınız Şehitlerim gazilerim Sizden özür diliyorum Hatalıyız biliyorum Yüreğimle...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sehitlerim-gazilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepinizle Kardeşim', 'hepinizle-kardesim-muammer-baydere-tbqsl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana beni sormayın kendimi anlatamam

Fakat şunu bilin ki güzelliktir her işim

Elbet eksiğim var da sevgim saygım tastamam 

“Önce insan” diyorsa Samsunlu da kardeşim

Aynı yerler değil de farklı olsa yöremiz

Değişse de şivemiz adetimiz töremiz

Eşit geldik dünyaya Yaradan’a göre biz

“Önce insan” diyorsa  Antepli de kardeşim

Mutluluksa dünyada kulların her emeli

İyi niyet olmalı yaşamanın temeli

Mazlumu ne ezmeli ne hakkını yemeli

“Önce insan” diyorsa Mersinli de kardeşim

Hayatın doğum gibi ölümü de mevcuttur

Hatalarla seyreden bölümü de mevcuttur

Ne yazık ki zalimi ve zulmü de mevcuttur

“Önce insan” diyorsa Sivaslı da kardeşim

Kimse “bizden” diyerek suçluyu kollamasın

Suçlunun cezasına masumu yollamasın

Herkes bir yol tutsun da ruhunu sollamasın

“Önce insan” diyorsa İzmirli de kardeşim

Sevmek sevilmek varken kavgayla ne işimiz

Canımız acımaz mı ağrısa bir dişimiz

Hoş görüyü bilmeyen kalmasın bir kişimiz

“Önce insan” diyorsa Bursalı da kardeşim

Sevgiyi yudum yudum içip mutlu olalım

Huzuru ve barışı seçip mutlu olalım

Bencillik duygusundan geçip mutlu olalım

“Önce insan” diyorsa ben herkesle kardeşim

“Önce insan” derseniz hepinizle kardeşim', 'Bana beni sormayın kendimi anlatamam Fakat şunu bilin ki güzelliktir her işim Elbet eksiğim var da sevgim saygım tastamam  “Önce insan” diyo...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hepinizle-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Borcu', 'vatan-borcu-muammer-baydere-7t90l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Tüm Askerlerimize''

Sevginle aşarım ben bu günleri

Ne fala bakarım ne de burcuma

Ardımda bırakıp tüm sevenleri

Gidiyorum işte vatan borcuma

Anamı babamı sevdiğim kızı

abimi ablamı o yaramazı

İçimde saklayıp hatıramızı

Gidiyorum işte vatan borcuma

Gözümde büyüdü uzayan yollar

Boşluğa sarıldı uzanan kollar

Benimle ağlarken çiçeksiz dallar

Gidiyorum işte vatan borcuma

Zamansız bir sevda geldi başıma

Ne halime acır ne gözyaşıma

Elveda dostuma arkadaşıma

Gidiyorum işte vatan borcuma

Eğer Allah bana izin verirse

Gün gelir alırım ben de tezkere

Duayla gönderin beni askere

Gidiyorum işte vatan borcuma', '“Tüm Askerlerimize'' Sevginle aşarım ben bu günleri Ne fala bakarım ne de burcuma Ardımda bırakıp tüm sevenleri Gidiyorum işte vatan borcuma ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vatan-borcu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cibilliyetsiz', 'cibilliyetsiz-cenk-aksal-tt9hg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her an''ım bir ayrı cenk ile geçiyor,

ömrüm deli aşktan tükeniyor,

beni kör bir garp aşık''ı sanmayın,

bab-ı istanbul''dan uzaklarda yolum:

keşke bir serhat köşesine gitseydi,

bed nazar dı gördüğüm gözler,

beyt''imde bile rahat bırakmadı..

ırak cebellerde bir yerlerde,

bir dirhem bile etmezdi aşk''ın,

cevr ü zulm ettin hep bana,

ne desem boş cibilliyetin bu senin,

bütün niza''larımızdan anlamadın mı?', 'her an''ım bir ayrı cenk ile geçiyor, ömrüm deli aşktan tükeniyor, beni kör bir garp aşık''ı sanmayın, bab-ı istanbul''dan uzaklarda yolum: keş...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cibilliyetsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost''a', 'bir-dost-a-muammer-baydere-l7f10', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bir gelip geçerken bir ümitle seneler

Gözlerinde olmasın kederden bir damla yaş

Kabarsın duyguların kalmasın bahaneler

Yeni yılda yeni yaş aşk getirsin arkadaş

Gönlündeki prense “Ahmet,Mehmet” diyen yok

Sevilmeyi istersen “bana zahmet” diyen yok

Karşılıksız sevgiyi kürk olsa da giyen yok

Yeni yılda yeni yaş aşk getirsin arkadaş

İşin gücün rast gitsin sağlık sıhhat yerinde

Uyanırsa hislerin saklama hiç derinde

Nasıl olsa olacak elbet günün birinde

Yeni yılda yeni yaş aşk getirsin arkadaş

Zamanı geldiğinde sen de sevgiye eğil

Dostlarında arama ihanete bir meyil

Sakın yanlış anlama  bu bir beddua değil

Yeni yılda yeni yaş aşk getirsin arkadaş', 'Bir bir gelip geçerken bir ümitle seneler Gözlerinde olmasın kederden bir damla yaş Kabarsın duyguların kalmasın bahaneler Yeni yılda yeni y...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-dost-a-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulan..!', 'ulan-muammer-baydere-a2mp2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanın kanına girdiğin yeter

Sabrımı taşırıp çok olma ulan

Bir şiir yazarsam küfürden beter

Duyunca şaşırıp şok olma ulan

Çıkarın uğruna boynunu eğip

Beslenip büyüdün hep haram yeyip

Maddede açlıktan kırıldım deyip

Manaya gelince tok olma ulan

Nerede yetiştin hangi dolayda

Gerçeği görmezsin hiçbir olayda

Kazancın iyi de işin kolay da

Sıkıyı görünce yok olma ulan

Sen saki değilsin bir dem olmazsın

Güzellik adına dirhem olmazsın

En küçük yaraya merhem olmazsın

Garibin bağrına ok olma ulan

Kendini sıyırıp haklıdan haktan

Bir duvar örersin suçtan yasaktan

Vicdanın görünmez kirden pasaktan

Pislikten öteye bok olma ulan', 'İnsanın kanına girdiğin yeter Sabrımı taşırıp çok olma ulan Bir şiir yazarsam küfürden beter Duyunca şaşırıp şok olma ulan Çıkarın uğruna bo...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ulan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utan Be Adam', 'utan-be-adam-muammer-baydere-b0cro', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karakter yönünden değiştin hızla

Gel arkadaşından utan be adam

Gününü gün ettin karıyla kızla

Yaşından başından utan be adam

Sahte bir sevgiyle yaklaştın ama

Sırıttı gönlüne yaptığın yama

Hak yeyip haklıyı düşürdün gama

Yaşından başından utan be adam

Şimdi şer dolusun evvel hayırdın

Menfaat uğruna insan ayırdın

İşine geleni hepten kayırdın

Yaşından başından utan be adam

Birleşin yüzsüzler milleti soyun

Bu nasıl tezgahtır bu nasıl oyun

Dilerim Allah’tan devrilsin boyun

Yaşından başından utan be adam

Her şeyde yağ gibi üste çıkıp da

Gülmenin tanımı var mıdır tıpta

Sahtekar kullara edilmez gıpta

Yaşından başından utan be adam

Bir doktora görün hocaya okun

Yanlıştan vazgeçip gerçeğe dokun

Çıkmaz mı kokusu yediğin bokun

Yaşından başından utan be adam

Üzülme bu yolda bir değilsin ki

Kapkara lekesin kir değilsin ki

Sevgide çömezsin pir değilsin ki

Yaşından başından utan be adam', 'Karakter yönünden değiştin hızla Gel arkadaşından utan be adam Gününü gün ettin karıyla kızla Yaşından başından utan be adam Sahte bir sevgi...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/utan-be-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülemezsin', 'gulemezsin-muammer-baydere-ucenk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğinde sevgi yoksa

Mutluluğu bilemezsin

İnsanlığa karnın toksa

Servetinle gülemezsin

Gerçekleri aramazsan

Gönüllere varamazsan

Riyakarsan yaramazsan

Şöhretinle gülemezsin

İyiliğe baş koymasan

Gözlerimde yaş koymasan

Taş üstünde taş koymasan

Şiddetinle gülemezsin

Rolden role atlasan da

Sıkıntıdan patlasan da

Sinirinden çatlasan da

Hiddetinle gülemezsin

Adam diye üstelensen

Şiir olup bestelensen

Çiçek gibi destelensen

Hikmetinle gülemezsin

Destek olsa sana basın

Gizlenemez kirin pasın

Gözlerinden belli yasın

Heybetinle gülemezsin

Taşıma su neye yarar 

İnsanoğlu insan arar

Hiç kimseye verme zarar

Gıybetinle gülemezsin

Elçi şöhret Allah para

Ne gerek var duygulara

Huzur dolu uykulara

Hasretinle gülemezsin

Yarınımdın dünde kaldın

Bir asırken günde kaldın

Kör gözlerde ünde kaldın

Nefretinle gülemezsin', 'Yüreğinde sevgi yoksa Mutluluğu bilemezsin İnsanlığa karnın toksa Servetinle gülemezsin Gerçekleri aramazsan Gönüllere varamazsan Riyakarsan...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gulemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arta Kalan', 'arta-kalan-selahattin-durna-b8tah', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arta Kalan

Anısı değil

Güzel bir sevdanın

Ama ayak izlerin kalmış

Şuramda ya…

Yürüyüp gitmişsin

Yürüyüp gitmişsin

Adı belki

Güzelim bir ömrün

Çünkü parmak izlerin kalmış

Şuramda ya…

Tutup şuramda

Sigaranı söndürmüşsün

Şurda bir tutam sarı saç

Ve kirpiklerin kalmış

Çünkü parmakların kalmış şuramda

                                                                   Aralık 83', 'Arta Kalan Anısı değil Güzel bir sevdanın Ama ayak izlerin kalmış Şuramda ya… Yürüyüp gitmişsin Yürüyüp gitmişsin Adı belki Güzelim bir ömrü...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/arta-kalan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Daha', 'bi-daha-selahattin-durna-z8lq1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bi Daha

Bu çiçek bülbül ötümlü

İğdeyi kim çağırır yaza

Kaç sokak sarı sapar

Sende bu demde bu bahar

Nisbet mi bendeki ayaza? 

Kapılar çıkıp bekle

Siyahi koşturmalar…

Gel etmişsin kim gide? 

Hangi konak gül bakar

Yolladığı ölüye? 

İki gözün iki çeşme; 

Ne biçim hayatsın sen? 

Boyalı kalemler çağır,

Alfabeler çağır hadi! 

Maviyi bir daha dene!', 'Bi Daha Bu çiçek bülbül ötümlü İğdeyi kim çağırır yaza Kaç sokak sarı sapar Sende bu demde bu bahar Nisbet mi bendeki ayaza?  Kapılar çıkıp ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bi-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Ki Varsın', 'i-yi-ki-varsin-selahattin-durna-xfwxg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İyi Ki Varsın

Gelip bulurlar seni

“Sıkıysa hadi

Suya dokun

Sabuna dokun”

Gelip bulurlar seni

-hadi anlat

Ahmet Arif’i! 

Sen olmasan

Ne''ylen korkutacaklar

Açlığı,işsizliği…

Sen olmasan

Kime vuracaklar kelepçeyi…', 'İyi Ki Varsın Gelip bulurlar seni “Sıkıysa hadi Suya dokun Sabuna dokun” Gelip bulurlar seni -hadi anlat Ahmet Arif’i!  Sen olmasan Ne''ylen ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iyi-ki-varsin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlarda Ölür', 'yildizlarda-olur-zeki-altas-cwwot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yıldız ölüyor...

Kulaklarım,sessizliğin hazin çığlıklarını dinliyor.

Gözlerim,

karanlığın kör eden ışıklarında,

korku ile kapanıyor.

Ve bir yıldız ölüyor...

Ati saçmalıyor.

Soğuk ve titrek bir ten üzerinde 

hayaller yıkılıyor,

umutlar sönüyor.

Ve bir yıldız ölüyor...

Yılgın esen 

bir deli poyraz

savuruyor yapraktan canları,

ciğerler yanıyor,

karalar bağlıyor.

Ve bir yıldız ölüyor...

Yazık,

Sen,

ne ölen son yıldız,

ne düşen son yapraksın.

Yüreklerde hazan mevsimi şimdi.

Yarınlara ağıt düşüyor.

Ve bir yıldız ölüyor...

Hayal ne tatlı rüya,

göklerde yıldız oluyor.

Ve toprak öyle bir gerçek ki,

semadan bir bir topluyor.

Böceklere gün doğuyor.

Ve bir yıldız ölüyor...', 'Bir yıldız ölüyor... Kulaklarım,sessizliğin hazin çığlıklarını dinliyor. Gözlerim, karanlığın kör eden ışıklarında, korku ile kapanıyor. Ve ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Altaş']::text[], 8.5, '{"poet":"Zeki Altaş","poet_slug":"zeki-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yildizlarda-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesretem Sene', 'hesretem-sene-murat-kilic-2-iafdo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Garip turna idim göyde.

Gırıldı ganadım, uçabilmirem.

Yüzün gecemde durur hesretle,

Sensiz bir gece yatabilmirem.

Suya hesret galdı torpahlarım.

Sinemde odunla gün gün çaglarım.

Sünbüllerim solmuş, bozdur baglarım.

Sensiz kuru çiçegem, açabilmirem.

Uyanıram her seher yözüne hesretle.

Bir kere gel derem, hoş mehebbetle.

Gönüm geçer oldu özgün sohbetle.

Dilden gözel kelam saçabilmirem.

Men diyeridim olurda geder zaman.

Bilmez idim bu alav ki ah ne yaman.

Bir el etsen yeter, gelirem men heman.

Yollarım düğümlü sensiz, açabilmirem.

Felege neylemişem bırahmaz meni.

Aglatır da gurutmaz gözlerimi.

Bir kere duyuver acı sözlerimi,

Senden başkaya söz diyebilmirem.

Gözüm bulut kimi töker yaşı.

Sensiz galan könül elem yoldaşı.

Ha çatladı ha çallıyacah daşı,

Sabrım tökendi, sabr edebilmirem.

Ne ezadan ne ölümden korhum yohtur.

Könlüm hesretinden ziyade tohtur.

Maralım, bu hesret mene çohtur.

Özüni getir geri, bele yaşabilmirem.', 'Garip turna idim göyde. Gırıldı ganadım, uçabilmirem. Yüzün gecemde durur hesretle, Sensiz bir gece yatabilmirem. Suya hesret galdı torpahla...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hesretem-sene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin', 'kimsin-murat-kilic-2-rfr5n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yağmur olmalısın; 

Her bir damlanla,

Çiçek bahçemi ıslatan.

Canıma her dokunuşta,

Aşina gibi dolup taşan.

Yoksa güneş mi desem.

Her sabah pencereme doğup,

İçimi ısıtan.

Emsalsiz halleriyle,

Tüm benliğimi kaplayan.

Sen rüzgar olmalısın; 

Saçlarımda dolanıp,

Yüzümdeki tebessümü soluyan.

Bilmediğim yönlerden eserek,

Beni hayata yamayan.

Hayır, sen bahar olmalısın; 

Yeni yetme gülüşünle,

Dünyamı saran.

Elleri binbir renge kınalı,

Gündüz  gece benle yaşayan.

Söylesene,

Kimsin sen?', 'Sen yağmur olmalısın;  Her bir damlanla, Çiçek bahçemi ıslatan. Canıma her dokunuşta, Aşina gibi dolup taşan. Yoksa güneş mi desem. Her saba...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kimsin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar İçinde 1', 'ruzgar-i-cinde-1-murat-kilic-2-nto99', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sende dinmez rüzgarın içindesin.

Çırpınıyor can havliyle kanatların.

Sahibini yitirmiş gibi solgun sesin,

Üzerine yapışmış  kimsesiz suratların.

Düşünme zaman nedir nereye gider.

Bu zaafiyet tüketir sende seni.

Sadece gönüllerdeki çiçeği der.

Gerisini koklamak çürütür benliğini.

Gün olur bir gece şakağında birikir ter.

Saçın başın darmadağınık uyanırsın.

Pencerenden odana doğunca seher,

Kendini yeniden doğmuş sanırsın.

Küçük de olsa bir umudun varsa.

Sıkıca sarıl sakın ha sakın yitirme.

Bilmediğin karanlıklar çevreni sararsa,

İçindeki ışığın sönmesine izin verme.

Hayat girdabı iki şey; batmak ve çıkmak.

Yazılmışın kadar yaşarsın, dahası diyemezsin.

Amaç bakmak değil, görmek için çabalamak.

Sadece bakıyorsan önünü bile göremezsin.

Deryada geminin küçük olmasına gayret et.

Bil ki onu yönlendirmen kolay olacaktır. 

Söz söyleyeni değil suskun olanı seyret.

Eylemleri diğerinden çabuk başlayacaktır.', 'Sende dinmez rüzgarın içindesin. Çırpınıyor can havliyle kanatların. Sahibini yitirmiş gibi solgun sesin, Üzerine yapışmış  kimsesiz suratla...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruzgar-icinde-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yardım Ve Yataklık', 'yardim-ve-yataklik-selahattin-durna-74g6b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yardım Ve Yataklık

Sen üşürsün imansız bir hücrede/uzakta

Avazın gelir üç nöbet

Tabanlarım şişer burda benim

Deme ki duymamışam

Öksürürsün,buz...

Yüreğim kan öksürür

Deme ki bilmemişem', 'Yardım Ve Yataklık Sen üşürsün imansız bir hücrede/uzakta Avazın gelir üç nöbet Tabanlarım şişer burda benim Deme ki duymamışam Öksürürsün,b...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yardim-ve-yataklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Aşk', 'sessiz-ask-cenk-aksal-cwaa7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlatılmaz bazen aşk''ın 

hiç bir yan''ı

kitlenir dilde yüreğin ateşi,

suskunluk basar 

dört bir yanı,

gözler konuşur,anlayamazsın! 

anlaşılmaz aşk''ının

eda''sına dalarsın,

yetim kalır yüreğin nedensiz...

bilesin ki sevgi,

sözlerle anlatılmaz sadece,

en büyük mana gözlerde,', 'anlatılmaz bazen aşk''ın  hiç bir yan''ı kitlenir dilde yüreğin ateşi, suskunluk basar  dört bir yanı, gözler konuşur,anlayamazsın!  anlaşılma...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoğu bitti az kaldı', 'cogu-bitti-az-kaldi-mikdat-bal-1m613', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açıldı gözüm gönlüm  yeşerdi umutlarım 

Uyanan bu gençliği, tebrik eder kutlarım

Dağılıp gitti diye boş imiş korktuklarım

Şahlanışa geçtiler yeniden bozkurtlarım

Çoğu bitti az kaldı, biraz daha dayanın

Günleri sayılıdır bu milleti soyanın

Çok şeyler kaybederiz, şiddete karışarak

Anlaşıldı, bu dava yürümez vuruşarak

Her biriniz biriyle, dost olsun barışarak

Güven, hoş görü, saygı, sevgide yarışarak

Çok güzel yerdesiniz, biraz daha uyanın

Panzehiri sizsiniz bu milleti soyanın

Ok yaydan fırlamıştır, hedefi bulacaktır

Davamız tek başına ikdidar olacaktır

Türktür dilin kültürün, yine Türk kalacaktır

Bu millet sülüklerden hakkını alacaktır

Dikkati çekilmeli, sizleri yok sayanın

Hesabı sorulacak bu milleti soyanın

Adalet sözde değil, uygulanacak özde

Akraba dahi olsa taraf tutmak yok bizde

Ecdadımız böyleydi, yürüyün aynı izde

Haydi davranın gençler çok iş var önünüzde

Yardımcısı Allah’tır, Hak yoluna uyanın

Bal der az daha gayret, biraz daha dayanın', 'Açıldı gözüm gönlüm  yeşerdi umutlarım  Uyanan bu gençliği, tebrik eder kutlarım Dağılıp gitti diye boş imiş korktuklarım Şahlanışa geçtiler...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cogu-bitti-az-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz Bir Yokluğun Hikayesi', 'uykusuz-bir-yoklugun-hikayesi-murat-kilic-2-5mxbi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susadım.

Bir avuç su ver bana.

Çığlıkları yeri göğü inleten bu canıma.

Uslanmaz, kederli,

Bu talihsiz yangına,

Bir tas su dök hadi! 

Ben özlem denen kentin,

İsimsiz bir sokağında,

Yapayalnız yaşıyorum.

Kapılar kapalı

Alabildiğine kasvetli ve karanlık.

Kar adam boyu, gök kurşuni.

Yürüdükçe yürüyorum, üşüyorum.

Sonra bir köşeye büzülüp,

Karanlığa, geceye karışıyorum.

Birden beliriveriyorsun yanımda.

Sahte olsa da gülüyorsun.

Yani aklıma karışıyorsun.

Yani sen bir gece vakti,

Hiç bilmediğim bir kuytulukta,

Ummadığım bir saatte,

Gözlerini salıveriyorsun rüyama.

..........................................

Seni görünce yanımda ısınıyorum.

Ama kıpırdayamıyorum,

Soluğum kesiliyor.

Üzerime hiç bilmediğim,

Ve tarif edemediğim,

Acılar birikiyor, ağırlaşıyor bedenim.

Birileri sanki kulağıma,

Seninle başlayan bir ezgi fısıldıyor.

Kalbim kanlar içinde.

Yaramdan oluk oluk hasret boşalıyor.

.............................................

Ve hiç bilmediğim bir nedenle,

Uyanıyorum ağlayarak.

Sonsuzluğum, meskenim.

Umut limanım, yelkenim.

Saçlarımı okşayan ellerin kayboluyor.

Uzuyor gözlerin ırak şehirler kadar.

Sesin susuyor, gidiyorsun.

Seni kaybetmenin acısıyla,

Yollara düşüyorum yeniden; 

Yarım yamalak.

O günden beri girmez oldun rüyalarıma.

Bilmiyorum sebebini.

Umarım ölmeden önce bir kez görebilirim,

O güzel gözlerini.

“göklerin ve yerin,

dilimi döndürebileceğim kadar,

sayabildiğim ve sayamadığım her şeyin,

yaratıcısı ve sahibi.

bu acıyı bana veren kadar yaşat beni.”', 'Susadım. Bir avuç su ver bana. Çığlıkları yeri göğü inleten bu canıma. Uslanmaz, kederli, Bu talihsiz yangına, Bir tas su dök hadi!  Ben özl...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/uykusuz-bir-yoklugun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkek Ağlamaları', 'erkek-aglamalari-selahattin-durna-l6oc6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Erkek Ağlamaları

Bir mermere düşeceksin daracık,upuzun

Gurbet kendi adıyla anılmayacak

Göbek adıyla vuracak uykuna,ocağına...

Süphan diyeceksin

Kadeş gibi,Hammurabi gibi..

Dağlar kendi adıyla anılmayacak.

Bir türkü koşacaksın

                    Toplu komut/üç tekrar

Adıyla anılmayacak hüzünler

Susup için

Erkek ağlayacaksın.', 'Erkek Ağlamaları Bir mermere düşeceksin daracık,upuzun Gurbet kendi adıyla anılmayacak Göbek adıyla vuracak uykuna,ocağına... Süphan diyecek...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/erkek-aglamalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykularda', 'uykularda-murat-kilic-2-91qfx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşadım ne varsa bilinmeyeni.

Bazı yelkenli bazı kuş oldum.

Soluksuz tırmandım bitmez merdiveni,

Omzumda bin hayal bir tahta oturdum.

Gökyüzünün rengi sonsuz çiçek bahçesi.

Çehreler güleç, saçlar rüzgar musikisinde.

Tenlerde özgürlüğün yitmeyen busesi.

Ruhum yaşlanır mı bu seda gecesinde.

Uslanmaz çocuk gibi koştum uykularda.

Aklımdan geçirmedim bir kez bile uyanmayı.

Saçlarımı taradım yağmur denen sularda,

Yine de tamamlayamadım içimdeki ıslanmayı.

Her şey uykularda olur bilir misin! 

Uykular, saklı bahçelerde gezer gibi.

Uykular, sonsuzluğun hayalle birleştiği yerdir.

Uykular, mesut olmanın en tabii sebebi.

Uykular, bitmez gün batımı bitmez seherdir.

Bırakın sonsuza dek kalayım bu yerde.

Bırakın tüm bildiklerim bende yansın. 

Bu ahenkli mutluluk resimli perde,

Sorgusuz sualsiz gül mevsiminde kapansın.', 'Yaşadım ne varsa bilinmeyeni. Bazı yelkenli bazı kuş oldum. Soluksuz tırmandım bitmez merdiveni, Omzumda bin hayal bir tahta oturdum. Gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uykularda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Çizgilere Mersiye', 'kirmizi-cizgilere-mersiye-abdurrahim-karakoc-bcxs9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırmızı çizgilerimiz vardı

Asker-sivil üstüne titrerdik

Çok çok uzak ülkelerden

Mekanik dinozorlar geldiler

Kırmızı çizgilerimizi sildiler

Kesiliverdi sesimiz soluğumuz

Ucuz gittik ucuz...

Musul dedik Kerkük dedik

Esaret kabul etmez Türk dedik

Meğer ki Türkmenler bizden kof

Biz Türkmenlerden kofmuşuz

Dönüp geriye bakınca gördük

Birbirimizden yıllar önce kopmuşuz.

Hani Iraklı Kürtlere

Devlet kurdurmayacaktık

Onlar bile devletlerini kurdular

Bizi can evimizden vurdular

Melül mahzun gerilerden baktık.

Kayboldu kırmızı çizgilerimiz

Çuvallar dolusu boyalarımız soldular

Çuvallar dolusu adam oldular.

Kıbrıs''ı da kaybederiz bir gün

AB''nin beklediği gündür bugün

Böbürlenmemize hiç gerek yok

Kıbrıs''ta Rumların nüfusu

Türkiye''nin nüfusundan çok

Öyle ya

Sayısal değil, siyasal ağırlık önemli

Yeşil hat, kırmızı hat seraptır

Bence akıbetimiz haraptır.

Şimdi Şirak vuruyor ensemize

Yarın Merkel vuracak

Gideceklerin vurdukları gibi

Gelenler de teker teker vuracak

Bizde bu ense

Onlarda bitmeyen kin

Herkes engel çıtasını yükseltecek

Atlaya atlaya dermanımız kesilecek.

Derken

Biz burda birbirimizi yerken

Sevinip arkamızdan gülecekler.

Ne kaldı şurada iki bin yirmiye

Bekleyeceğiz geldi, gelecek diye

Bataklıkta yüzülmez ki

Bu düğüm maksatlı atılmış düğüm

İlelebet çözülmez ki

Koyu kırmızı bir çizgi daha çekeriz

Yani muhtemelen

O çizgiyi de ayaklarıyla silerler

Belki de gideni aratır gelen

Yoğun uykular arasında rüyalarımız

Nasıl uçup giderlerse

Öyle gidecek AB sevdamız.

Herkes dışarıya kör sağır

İçerde çekilen çizgilerimiz var

Kalınlaşıyorlar ağır ağır

Bizim ancak bize yetiyor gücümüz

Yâ Rab nedir suçumuz? 

Kim sardı başımıza bu sevdayı

Yok mudur bunun hiç kolayı? 

Belki var, belki yok

Amma çok bekleyeceğiz çok.

Umut, dağlar ardındaki sevgili

Çözülür elbette sabrımızın dili

O güne az kaldı az

Arzuhalci sen böyle yaz.

09 Ağustos-2005/Vakit', 'Kırmızı çizgilerimiz vardı Asker-sivil üstüne titrerdik Çok çok uzak ülkelerden Mekanik dinozorlar geldiler Kırmızı çizgilerimizi sildiler K...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/kirmizi-cizgilere-mersiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Kırgını', 'sevda-kirgini-aydin-demirkan-lmudy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Satılmış sabah gibi kokun,

Sevdan ciğerime dokunuyordu

Melankoli çığlığı gözlerin

Ve yitiyordu sesim...

Piç akşamlara duayen,

Bir tek seni bildim

Hayatım temizdi ama,

Yaşamayı seninle kirlettim.

Boğuyorum şiirleri şimdi,

En acımasız imgelerle

Küfre bulaşmış batnım,

Duygularım isyanlara gebe.

Ama bilesin; 

Seni hiç suçlamadım...

Varır her karanlık aydınlığa

Gayrı ziya değil arzum; 

Mum ışığı,

Ziyadesiyle yeter bana...', 'Satılmış sabah gibi kokun, Sevdan ciğerime dokunuyordu Melankoli çığlığı gözlerin Ve yitiyordu sesim... Piç akşamlara duayen, Bir tek seni b...', ARRAY['Türk Edebiyatı','Şiir','Aydın Demirkan']::text[], 8.5, '{"poet":"Aydın Demirkan","poet_slug":"aydin-demirkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevda-kirgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur 1', 'yagmur-1-murat-kilic-2-wqnbh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir nisan ikindisi.

İnceden ince yağmur yağıyordu.

Konuşmuyordum hiç.

Penceremden bakıyordum geçmişlere.

Küskündüm.

Gençliğimi ihtiyarlığıma dikiyordum.

Çırpınıyordum. 

Pencerem şehrin kalbine bakıyordu.

Parmaklarımda buğuların lekesi,

Yaralarımı sağaltıyordum.

Ağlıyordum.

Damlalar filizlerini ıslatırken yıldızlarımın,

Gün ışığını özümlerken dünyamdan,

Kahramanlar ölüyorken,

Hatıralarımı ebrularla süslüyordum.

Ağlıyordum.

Ayrılanları sıralıyorken akşamlar, 

Yaprakları ağırlaşıyordu ağaçların.

Sokağa çıktım.

Sokak ıslaklığını ayaklarıma seriyordu.

Yürüdüm.

Yürüdüm sokak sokak.

Sonra yüzün hatrına indim sahile.

Uykusuz gözlerimi ufka uzattım.

Ilıman bir hasret yüzümü yalıyordu.

Nice bulut alt alta üst üste göğü kaplıyordu.

Yosunlar yemyeşilliğe bürünmüş,

Tekneler, dev yarâsa dalgalara 

Göğüs vuruyordu.

Sıkıldım 

Dayanamadım geri döndüm.

Sokaklar yine ıssızdı.

Şakaklarımdan akan damlalar,

Ceketimi ıslatıyordu…

............................................

Islanmış ayaklarımla eve vardım nihayet.

Kederli gibiydi gökyüzü,

Durmadan yağıyordu.

Yıkılmaya yüz tutmuş toprak hanemizde,

Oymalı bir kapı yüzüme bakıyordu.

İçeriye girdim, sıcaktı evrenim; 

Sobamız yanıyordu.

Yeniden aldım pencere kenarındaki yerimi.

Sonra yine yeniden seyre başladım şehri…

Deniz kokan bir özlem içimi sardı.

Pencerem ağlıyordu.

Pencere pervazına yaslanmış minicik

Bir serçe inliyordu.

Bir serçe ağlıyordu.', 'Bir nisan ikindisi. İnceden ince yağmur yağıyordu. Konuşmuyordum hiç. Penceremden bakıyordum geçmişlere. Küskündüm. Gençliğimi ihtiyarlığıma...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yagmur-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur 2', 'yagmur-2-murat-kilic-2-6tdwx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sessiz bir bahar akşamıydı.

Gündüzden geceye kaçıyordu saatler.

Karanlık gözlerle bakıyordu şehre gökyüzü.

Korkuyordum karanlıktan.

Daha çocuktum,

Haberim yoktu yağmurdan.

Önce büyük bir gürültü duydum.

Sanki karanlık yırtılmışta içinden,

Beyaz kamçılı, gizemli bir hayal çıkmıştı.

Karanlığın beni yutacağını düşünüyordum.

Korkuyordum! 

Sokak öylesine yalnızdı.

Bir merdiven altı buldum gizlenecek.

Koşar adım girdim altına, merak ediyordum,

Kim bilir bu gürültü ne zaman bitecek? 

Bir ara ses kesildi, bitti sandım.

Merdiven aralığından yukarı baktım.

Küçük bir damla düştü yüzüme.

İrkildim! 

Garip bir şeydi! 

Bu hadise sanki,

Bir çiçeğin sulanması gibiydi.

Ilık küçük su damlaları; yüzümde, ellerimde,

Sokağın her yerinde vardı.

Bunlara benzeyen bir şey de göz yaşlarımdı.

Diz çöktüm, ellerimin arasına aldım çenemi.

İzlemeye başladım bu emsalsiz güzelliği.

Düşündüm! 

Bir anda nasıl düşüyordu,

Bu kadar damla gökyüzünden! 

İlahi kudret dökülüyordu sanki,

Tanrının ellerinden.

Usul usul sessiz sessiz düşüyordu damlalar.

Damlalara kılavuzluk ediyordu,

Sokaktaki lambalar.

Sonra bir el önümde belirip omzumu okşadı.

Kafamı kaldırıp baktım: Babamdı.

Kalktım yürümeye başladık.

Bir elinde poşetler vardı, tuttum diğerinden.

Yağmur yağıyordu biz yürürken.

Yaklaştıkça eve üzülüyordum.

Bu yeni heyecanın biteceğini sanıyordum.

Eve geldiğimizde kapı açılınca

Hemen içeri koşup, 

Pencerenin önüne oturdum.

Camların buğusunu çizgiler çizerek,

Seyre başladım tekrar güzelim yağmuru.

O gün öğrendim 

Ne demek olduğunu yağmurun.

Şimdi ne zaman yağmur yağsa,

Bir pencere seyyahlığında gezinirim.

Bulursam; buğulaşan camlarında,

Güneş ve çocuklar çizerim.', 'Sessiz bir bahar akşamıydı. Gündüzden geceye kaçıyordu saatler. Karanlık gözlerle bakıyordu şehre gökyüzü. Korkuyordum karanlıktan. Daha çoc...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yagmur-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandır Beni', 'uyandir-beni-murat-kilic-2-jl36b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mavilere yakıştırmışsın yine.

Suretin mevsimlerin en içli hali.

Garipsin vesselam bi o kadar sırlı.

İsmini arıyorum lügatlerde.

Lakin sana yakışacak kadar

Güzeli yok! 

Bir deyi ver ismini de,

Bizi gamzelerinden mahrum etme.

Adı sır mehtap.

Rüzgarın en özgür hali.

Uzaklara yatırıp esrarlı gözlerini,

Hoyrat teselliler yükleme omuzlarıma.

Varlığım gözünden düşen bir damla; 

İpek teninin sızısıdır dilimdeki.

Zaten aslı yetim bir lisanım,

Daha fazla yarım bırakma kelimelerimi.

Sana muzdarip olmuş bir çocuğum,

Ağlatma artık gözlerimi.

Uyuyorum asırlardır, yeter artık,

Sana uyandır beni.

Bakıyor da görmüyor duymuyor musun,

Bu gurbetin sahibini', 'Mavilere yakıştırmışsın yine. Suretin mevsimlerin en içli hali. Garipsin vesselam bi o kadar sırlı. İsmini arıyorum lügatlerde. Lakin sana y...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uyandir-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elanın Uykusu', 'elanin-uykusu-murat-kilic-2-jlkze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha başlayalı ne olmuştu ki bu rüyanın,

En güzel yerinde bıraktın beni ey ela.

Kendi dünyana dönüverdin, mutlu musun? 

Şimdi hangi rüyadasın söyle ey ela? 

Senin için yangınları bağrıma basmıştım.

Yüreğimde çarpan bir yürek var sanmıştım.

Aydınlığımı karanlığına adamıştım.

Kara hançerin deldi bağrımı ey ela.

Yokluğun sersemleştirir ruhumun her yerini.

Suskun gözlerim dalgınlıkla bekler ellerini.

Hasretin başa bela umarsız gemilerini,

Yüreğime demirleyip gittin ey ela.

Kimseden eser kalmadı bu kalbimde.

Sadece senden bahis var bil her demde.

Aylar yıllar geçsede şu deli divanemde,

Unutmaki bir tek sen varsın ey ela.

Artık uyku istemiyorum yaradandan.

Nefretle dolup taşan bu dünyadan.

En mühimi; sensiz olacak bir rüyadan,

Hiç ümit beklemiyorum ey ela.

Silemedim kaderimin suskun duygusunu.

Yenemedim yalnızlığın sitemli korkusunu.

Ne yaptıysam uyandıramadım uykusunu.

Uyuyor, uyuyorsun, uyanmıyorsun ey ela.', 'Daha başlayalı ne olmuştu ki bu rüyanın, En güzel yerinde bıraktın beni ey ela. Kendi dünyana dönüverdin, mutlu musun?  Şimdi hangi rüyadası...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elanin-uykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Dalında', 'gul-dalinda-murat-kilic-2-7vo4h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alev düştü uzaklardan gönül bağıma.

Yandım gül dalında.

Bir çift göz uğruna yalnız başıma.

Kaldım gül dalında.

Deniz derya yok gözümde, hepsi serap.

Viraneden farkı yok ruhumun, sinem harap.

Uyuyorken busesinden bir yudum şarap,

Aldım gül dalında.

Özge bir ızdırabın derdiyle yanarken.

Güle benziyordu gamze, sen gülerken.

Salınırken umanında bir çok yelken,

Saldım gül dalında.

Tahtına talibim, isterim saltanatını.

Bir kere tebessüm et, güldür vuslatını.

Her gecemde her günaydınımda adını,

Andım gül dalında.

Mutsuzluk kaderim mi, ne dem güleceğim.

Asır asır unuttum; bildiğim, bileceğim.

Yokluğunda kurudum, soldum, öleceğim,

Sandım gül dalında.

Ey rüya gözlü cisim, gül endam.

Sana olan fikrimi sorma; anlatamam.

Hüzünlü ezgilerini içimde makam makam,

Çaldım gül dalında.

Diken oldum, yüzüm göğe doğru.

Muhabbet sohbetim, sözüm göğe doğru.

Kapandı kapılar, gözüm göğe doğru,

Kaldım gül dalında.', 'Alev düştü uzaklardan gönül bağıma. Yandım gül dalında. Bir çift göz uğruna yalnız başıma. Kaldım gül dalında. Deniz derya yok gözümde, heps...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gul-dalinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-murat-kilic-2-trn0i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun demek! 

Güle güle eylül.

Güle güle yaşayamadığım bahar.

Hayallerin kelebek kadar güzel,

Mevsimlerin çiçek bahçesi,

Yüzün hep gülce olsun.

Hep sağlıcakla kal meleğim.

Her şey gönlünce olsun.

Yolun açık olsun kırlangıcım.

Güle güle…', 'Gidiyorsun demek!  Güle güle eylül. Güle güle yaşayamadığım bahar. Hayallerin kelebek kadar güzel, Mevsimlerin çiçek bahçesi, Yüzün hep gülc...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gule-gule-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olduk - Olmadık', 'olduk-olmadik-murat-kilic-2-qarpd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“ birdim iki oldum ”

Umutlu tüm zamanlarda günaydınımdın.

“ iki iken bir ”

Sonra sebepsiz bir ayrılık.

“ ne yalnızken birdim ”

Tüm ilk zamanlarda aklımdaydın.

“ ne de seninle iki ”

Sonunda uzaklara karıştık.

Şimdi sesimi duymak isteme, çünkü senle; 

“ var ve yokum ”', '“ birdim iki oldum ” Umutlu tüm zamanlarda günaydınımdın. “ iki iken bir ” Sonra sebepsiz bir ayrılık. “ ne yalnızken birdim ” Tüm ilk zaman...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olduk-olmadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serüvenim', 'seruvenim-murat-kilic-2-5wm08', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni dünyalara açılmış bir gemici gibi,

Yeni bir heyecanla ona gidiyorum.

Bilmediğim tufanlar arasında yaklaşıyorum.

Kayboluyor birden…

Gizemine ayak uyduramıyorum.

Kendimde garip bir eksiklik hissederek,

Gidiyorum.

Gidiyorum.

Başımı kaldırıp gökyüzüne baktığımda

Sanki bu alemin yaradılış sebebinin

O olduğunu düşünüyorum.

Bir nedeni var elbet:

Nereye baksam hep onu,

Yalnızca  onu görüyorum.

Sahiller sırtlayıp, ummanlar geçip

Issızlığın kol gezdiği maviliklerde,

İsimsiz o hayali arıyorum.

Ben yalnızca dünyanın 

Yedi harikasını duymuştum.

Başkalarının özelliği olmadığını bildim yıllarca.

Meğer hep kendimi kandırarak yaşamışım.

Onu tanıdıktan sonra anladım ki; 

Dünyada yalnızca bir harika var.', 'Yeni dünyalara açılmış bir gemici gibi, Yeni bir heyecanla ona gidiyorum. Bilmediğim tufanlar arasında yaklaşıyorum. Kayboluyor birden… Gize...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seruvenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum artık', 'gidiyorum-artik-mikdat-bal-wl0zj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Değerli dostlarım, 

İçinde bulunduğumuz mübarek üç aylar münasebetiyle, gidiyorum şiirini yazdım, bir yere gitmiyorum sadece bu aylarda başka şeylerle ilgileneceğim için şiir yazamıyacağım, yanlış anlaşılmalara sebebiyet verdiğim için özür dilerim, Receb, Şaban ayınız mübarek olsun, sağ salim Ramazana ulaşmanızı Yüce Allah''tan niyaz ederim.

Mikdat Bal

Dört ay olmuş yazıyorum

Bazen moral bozuyorum

Sevindirip, üzüyorum

Üzüp gidiyorum artık 

Şiirlerim böyle dursun

Görmek isteyenler görsün

İsteyen sayfama girsin

Bozup gidiyorum artık

Şiir diye düzdüklerim

Affetsinler üzdüklerim

Beni bağlar yazdıklarım

Yazıp gidiyorum artık

Bal der sevgi ile dolun

Allah’a emanet olun

Sonuna geldik bu yolun

Gezip gidiyorum artık', 'Değerli dostlarım,  İçinde bulunduğumuz mübarek üç aylar münasebetiyle, gidiyorum şiirini yazdım, bir yere gitmiyorum sadece bu aylarda başk...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidiyorum-artik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyade Zaman', 'piyade-zaman-selahattin-durna-ywuk0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Piyade Zaman

-Yurdumun en güzel E-5''ine

Yedinci koğuştan piyade bak bir de-

Yollara düşeriz

Dönen tekerleklere

Sıfır üç-sıfır beş

Saatler gün döner

Püften adımlarda çoğul takılar

Sıcak güneşleri 

Özler olmuşuz.

Çocuk uykular kime döndü,

Kim alır

           Terleyen bıyıkları

Kimedir delikanlılığımız.

Ak zambaklar düşünürsün

Haşhaş ovalarını düşünürsün

Barışı düşünürsün

Döşü gelir aklına üpüryan bir kadının

Güvercinler düşünürsün...

Ufukta denizin bal çizgisi

Güneşin bal çizgisi...

Martılar yosun kokusu taşırlar

Balık kokusu taşırlar,

Yalova vapurunun bacasını...

Trenleri kim akıl eder böyle

Denizlerin kıyısında

Uykuların kıyısında

Kocaman düdükleri kim akıl eder böyle

Gurbetlerin kıyısında.', 'Piyade Zaman -Yurdumun en güzel E-5''ine Yedinci koğuştan piyade bak bir de- Yollara düşeriz Dönen tekerleklere Sıfır üç-sıfır beş Saatler gü...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/piyade-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedeni Ne Söyle!', 'nedeni-ne-soyle-abdulkadir-karaca-mxeng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelme istersen üzerime

Korkularım yine yok ediyor beni

Hiç tanıma beni İstersen

Varlığım korkutuyor beni

Basamak basamak merkezi bilinmez bir acı alıyorum üzerime

Yavaş yavaş taşıyorum

Gidiyorum belli belirsiz bir sona

Sensizlik o kadar çok işlemiş ki dudaklarıma 

Her senin adını söylediğimde sanki zırhlılar geliyor üzerime

Atlılar geliyor

Tarihleri aşan bir savaş yaşıyorum içimde

Milat öncesiyle başlayıp günümüzde sonuçlanmaya debeleniyor

Hep kaybeden taraf oluyorum

Niçin bu savaşı hiç kazanamıyorum

Neden hiç kimse kadar hiç bir acı kadar 

Ben bu kadar zaferi neden haketmiyorum

Ben niye senin olamıyorum

Sensizliği alıyorum hep üzerime

Taşımak şöyle dursun

Hep ben kanıyorum

Nasıl bu kadar acıdan sonra bile sensiz kalıyorum

Anlamıyorum

Neden ölüm yaklaşıyor bana bu kadar

Niçin ben yaşamayı özlüyorum

Sen her defasında öldürüyorsun beni

Ben her defasında tekrar diriliyorum

Kaybediyorum

Kazanmak uğruna başladığım bir yalanı

Peki bu neden? 

(Ağustos 2005)', 'Gelme istersen üzerime Korkularım yine yok ediyor beni Hiç tanıma beni İstersen Varlığım korkutuyor beni Basamak basamak merkezi bilinmez bi...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nedeni-ne-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almayı Değil Vermeyi Severim', 'almayi-degil-vermeyi-severim-ekrem-kemal-kirmaci-9lsva', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Almayı değil, vermeyi severim.

Dünya deniz olsa, ben su dökerim.

Yar sevsin, sevmesin önemli değil.

Ben hergün yari daha çok severim.', 'Almayı değil, vermeyi severim. Dünya deniz olsa, ben su dökerim. Yar sevsin, sevmesin önemli değil. Ben hergün yari daha çok severim....', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kemal Kırmacı']::text[], 8.5, '{"poet":"Ekrem Kemal Kırmacı","poet_slug":"ekrem-kemal-kirmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/almayi-degil-vermeyi-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Casmin', 'casmin-ozgur-celik-znosm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''yaşanmış bir aşk hikayesi''

ne vakit yağmur yağsa buralara,

taa gözlerinin içi gülerdi

gamzelenirdi yanakların,

ölünce hep oraya gömülmek isterdim

yağmura aldırmadan yürürdün

sırılsıklam girerdin fakülte kapısından

işte o an ben ölürdüm

sen yağmura vurgundun

ben yosun yeşili gözlerine

ama sen bunu hiç bilmedin

o günden sonra hep 

sana ağladım

pekiya Casmin sen

o yosun yeşili gözlerle

en çok kime ağladın? 

kısa küttü saçların

okşardı saçlarını rüzgar,

kıskanırdım

sallanırdı yapraklar

dağlırdı saçların

üşürdün, ürperirdin

taa iliklerine kadar

o an sımsıkı sarılmak geçerdi içimden sana

utanırdım.

durakta beklerdik ders çıkışı

kocaman bir körüklü gelip

seni alıp giderdi

ardından bakıp kalırdım öylece

dalga geçerdi arkadaşlar

bilirlerdi sana olan tutkunluğumu

pekiya Casmin sen

hiç farketmedin mi 

sana olan vurgunluğu mu? 

kırmızı bir kazağın vardı

uzun kollu, boğazlı

onu her giydiğinde

gelincikleri andırırdın

ne vakit sonbahar gelse,

dökülüp kaybolmandan korkardım

bilmem nereden tutuldum sana

oysa öyle ayrıydı ki dünyalarımız

bunuda bilirdim

yinede seni her gördüğümde

daha bir hızlı çarpardı kalbim

elim ayağıma dolaşırdı

anlamandan korkardım

masumdugülüşün,

içtendi bakışların

sana ne olmuş böyle Casmin

neden siyahlar giydin 

oysa sen siyahtan nefret ederdin.

laboratuvar olduğu gün

beyaz bir önlük giyerdin

inan o önlüğün içinde,

melekler kadar güzeldin.

seni öyle görünce sakarlaşırdım

kırıp dökerdim herşeyi

birbirine karışırdı tüm formüller

bu yüzden atılırdım hep derslerden

bahçede beklerdim çıkışını

beni gördüğünde gülüp geçerdin

hiç tahmin etmezdin değil mi

sebebin sen olduğunu? 

hiç düşünmezdin değil mi

senin için yanıp tutuştuğu mu? 

olmadı işte Casmin olmadı

ne kadar kaçmak istesem de

sana çıkardı bütün yollar beni

pekiya sen Casmin 

seni sevdiğimi bilseydin

çıkıp gelir miydin? 

ne desem boş artık biliyorum

ben seni taa en başta kaybettim

daha bir kez olsun dokunmadan ellerine

dalıp gitmeden gözlerinin içine

dahası Casmin

seni sevdiğimi haykırmadan yüzüne

öylece çekip gittin

yıllar hiçte kolay geçmedi yokluğunda

oysa unuturum sanmıştım

olmadı işte Casmin 

yıllar daha bir geldi üstüme

seni unutmayı başaramadım

hiç birşey değişmeyecek belki

ama olsun

kaldır başını yerden 

bak gözlerimin içine ne olur

sana söylüyorum

SENİ SEVİYORUM..! 

                                      Konya 1999', '''yaşanmış bir aşk hikayesi'' ne vakit yağmur yağsa buralara, taa gözlerinin içi gülerdi gamzelenirdi yanakların, ölünce hep oraya gömülmek is...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/casmin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yoksunuz', 'artik-yoksunuz-selahattin-durna-nrldg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık Yoksunuz

Akıp giden sular gibi

Derin uykular gibi

Tenhalar,kuytular gibi

Kimse görmeyecek sizi.

Kimseler sizin için

Şahin uçurmayacak

Bir kaleden bir kaleye

Kimse bilmeyecek sizi.

Direkleri yeşerten

Selamlar gelmeyecek

Telgraf tellerinden

Kimse sormayacak sizi.

Belleği yetmeyecek

Bir aşkı taşımaya

Solgun bir fotoğrafın

Kimse anmayacak sizi.

Kırık bir testi gibi

Boşaltacak suyunu 

Kırdığınız gönüller

Sebil gideceksiniz.

Kimse sevmeyecek sizi.', 'Artık Yoksunuz Akıp giden sular gibi Derin uykular gibi Tenhalar,kuytular gibi Kimse görmeyecek sizi. Kimseler sizin için Şahin uçurmayacak ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Durna']::text[], 8.5, '{"poet":"Selahattin Durna","poet_slug":"selahattin-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/artik-yoksunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurma Gönül Hançerini Bağrıma', 'vurma-gonul-hancerini-bagrima-ekrem-kemal-kirmaci-ynw3e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben tende can,sen bende ruh,sen bensin.

Bırakıp gitsende sen, döneceksin! 

Vurma gönül hançerini bağrıma.

Sonunda üzülecek yine sensin.', 'Ben tende can,sen bende ruh,sen bensin. Bırakıp gitsende sen, döneceksin!  Vurma gönül hançerini bağrıma. Sonunda üzülecek yine sensin....', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kemal Kırmacı']::text[], 8.5, '{"poet":"Ekrem Kemal Kırmacı","poet_slug":"ekrem-kemal-kirmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vurma-gonul-hancerini-bagrima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm.ktb.alnt', 'kara-gozlum-ktb-alnt-sedat-kocabey-1tsgu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen karanlık gecelerimın sabahı,

Karlı dağlarımın yedi veren çiçeğisin.

Demet demet derdiğim,

Uğruna can verdiğimsin karagözlüm.

Kurak topraklarımın yağmuru,

Ekmeğimde yoğurduğum hamurumsun.

Dermansız dizlerimin dermanı,

Söz dinlemez gönlümün fermanısın sen karagözlüm.

Geceleri rüyalarda gördüğüm,

Hasretini yumak yumak ördüğümsün,

Damla damla gözlerimde gözyaşım,

Her soframda yemek gibi aşımsın karagözlüm

Buram buram hasret kokar burnuma,

Sensizliğin acıları kurşun olur bağrıma,

Kulak verip gelebilsen çağrıma

Canımsın,kanımsın, benimsim karagözlüm...', 'Sen karanlık gecelerimın sabahı, Karlı dağlarımın yedi veren çiçeğisin. Demet demet derdiğim, Uğruna can verdiğimsin karagözlüm. Kurak topra...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kara-gozlum-ktb-alnt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül İtleri', 'gonul-i-tleri-muharrem-cetinkaya-ciewp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül itlerine…………..

Çiğ ete alışmıştır dişleri

Çiğnemeden yutarlar,

Karanlıktır düşleri,

Hep köşe başı tutarlar…

Dolambaçlıdır  bütün işleri,

Hepte  kefeni yırtarlar.

Kana değmiştir dişleri,

Yarasa gibi gece uçarlar…

Hepimiz tanırız bu leşleri,

Varınca üstüne yıvışırlar.

Yalandır  dolandır tüm işleri

Sonra ortadan savuşurlar…

Her yerde bulunur eşleri,

Hep köşelerde kırıtırlar.

Bu pislik onların çişleri,

Onu yapınca bile sırıtırlar…', 'Gönül itlerine………….. Çiğ ete alışmıştır dişleri Çiğnemeden yutarlar, Karanlıktır düşleri, Hep köşe başı tutarlar… Dolambaçlıdır  bütün işler...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-itleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bitleri', 'gonul-bitleri-muharrem-cetinkaya-cw4yg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül bitlerine....................

Atsan atılmaz,

Götürsen pazara,

Satsan,satılmaz…

Ne sever,

Ne vazgeçerler.

Gönül evinde yuva kurup,

Gönül suyundan içerler…

Üstelik ‘t gibi,

Çok üreyip,

Ve üstelikte,

Gönülden,gönüle geçerler! ...', 'Gönül bitlerine.................... Atsan atılmaz, Götürsen pazara, Satsan,satılmaz… Ne sever, Ne vazgeçerler. Gönül evinde yuva kurup, Gönü...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-bitleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidin', 'gidin-elazigli-mustafa-kaya-8u9g9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sizin gözyaşlarınız,

kıymet bilmez bir dünyaya baş kaldırıyor..

sizin sevginizle boy ölçüşemez,

sıra dağlar bile.

kederli yüzleriniz bugün kanadı kırık bir güvercin.

okyanuslara doğru uçmak isteyen.

gidin,

yüreğnizin götürdüğü yere.

ve güneşi kıskandıran aydınlığınızla gidin..

kimse düşüremez bir gölge,

acıları güle dönüştüren sözlerinize..

şehrin şerifleri,

günahlardan kuleler diktiler,

özgür düşünce maskelerini takarak.

yasaklar icad edip fidanlar kestiler

ihtilaleri aratmaz acılar çektiniz

dikenli tellerle çevrildi

okul önlerine gelişiniz...

gidin,

barışın ve sevginin çiçekleri

dualar kadar güzel yüreklerinizle 

nefes almak kadar haklı isteklerinizle.... 

                                                                             mustafa kaya / istanbul

                                                                             20.03.2001', 'sizin gözyaşlarınız, kıymet bilmez bir dünyaya baş kaldırıyor.. sizin sevginizle boy ölçüşemez, sıra dağlar bile. kederli yüzleriniz bugün k...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Suyu', 'gonul-suyu-muharrem-cetinkaya-3878c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül suyu bu; 

Sirke de yapar,

Şarap ta.

Buldu mu üzüm suyunu,

Damaklara lezzet pekmezde…

Sirke yapar,

Surat asar.

Şarap yapar,

Sarhoş eder.

Buldu mu üzüm suyunu,

Pekmez yapar,

Yılanı deliğinden çıkarır…', 'Gönül suyu bu;  Sirke de yapar, Şarap ta. Buldu mu üzüm suyunu, Damaklara lezzet pekmezde… Sirke yapar, Surat asar. Şarap yapar, Sarhoş eder...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-suyu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yorgunu', 'gonul-yorgunu-muharrem-cetinkaya-3zgbq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başımı koyup taştan yastığa,

Bedenim oyanı-buyanı dönerken,

Gönlüm onu seyreder,

Yukarıdan…

.

Ve,

Yoruldum bunca yükü taşımaktan,

Dercesine,

Keyifle süzülür,

Gözümün önünde…

.

Bedenim dalınca uykuya,

Sevinir,

Var diye,

Uzaklara yolculuk…

.

Hiç bitmesin ister gece,

Hayal aleminde yaşayacak güya! 

Ya ben…? 

Bana bıraktığın,ne ki? 

Her gecenin sabahında; 

Yarım-yamalak,bir rüya!', 'Başımı koyup taştan yastığa, Bedenim oyanı-buyanı dönerken, Gönlüm onu seyreder, Yukarıdan… . Ve, Yoruldum bunca yükü taşımaktan, Dercesine,...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gonul-yorgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Büyük Adam', 'bir-buyuk-adam-aysel-akbulut-yojuu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevgi diledim,

senin kadar gerçek

............hayat kadar yalan.

Ben ona döndükçe

sende yarım kalan.

Geldim...

Bir sızı içimde

......an be an beni doyuran,

Bir sen ol istedim,

Yüreğinle biraz olsun rahatlatan.

Evet geldim,

Kucağında hıçkıra hıçkıra ağlamaya.

Avut beni! 

Küçük bir kızı sevdiğin gibi,

Avut beni baba! 

Aşk değilmiş en büyük servet,

Sevgiymiş meğer...

Bir tebessümün yeter ve artar

Avutur beni! 

Anlat...anlat bana baba, 

en büyük tutkular 

Nasıl köreldiğini zamanla.

Nasihatini unutmadım

Doymadım hala verdiğin inanca,

Kızma bana! 

Üzsem bile seni, kaçırma gözlerini

Hep içine bak, en derin sırrımı 

biliyormuş gibi yap

Ve sarıl bana, sımsıkı sarıl! 

Geldim - avut beni baba.

O en büyük aşklar var ya...

Acı sözlerin kadar yıkmaz,

Yıkamaz beni baba,

yıkamaz asla! 

Sana söyleyecek tek bir 

sözüm olsa

Veya son nefesimde çift sözüm - 

Seni seviyorum...derdim baba,

zaten hiç vazgeçmedim!', 'Bir sevgi diledim, senin kadar gerçek ............hayat kadar yalan. Ben ona döndükçe sende yarım kalan. Geldim... Bir sızı içimde ......an ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Akbulut']::text[], 8.5, '{"poet":"Aysel Akbulut","poet_slug":"aysel-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bir-buyuk-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gozyasi', 'gozyasi-hale-kazak-811c2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin ortasinda

Yanlizliginla kavrulmak,

Nedir bilirmisin? ...

Gecip giden zamanin

Seni beklerken! ...

Umutsuzca gelen herseyin ardindan,

Akittigim gozyasinin,

Caresini bulabilirmisin? ...

Yangin gibi vuran,

Yuregimin ortasindaki atesi sondurebilirmisin? ...

Huzunleri yeniden,

Mutluluga cevirebilirmisin? ...

Ve bana yeniden,

''Seni Seviyorum''diyebilirmisin? ...', 'Gecenin ortasinda Yanlizliginla kavrulmak, Nedir bilirmisin? ... Gecip giden zamanin Seni beklerken! ... Umutsuzca gelen herseyin ardindan, ...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozyasi-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan! ! !', 'i-syan-mehmet-demir-atmali-3sxqx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetmez mi bunca çileler,

Lekeyi yuttu hileler...

Nerde kaldı hesap günü? 

Zamana kustu Laleler...

Çuval geçti başımıza,

Zehir kattık aşımıza...

Girer oldu düşümüze; 

Efendi oldu köleler...

Türk''ün gücü bilinmeli,

Kara talih yenilmeli...

Bu intikam alınmalı,

Muradım, dize geleler...

5.8.2005', 'Yetmez mi bunca çileler, Lekeyi yuttu hileler... Nerde kaldı hesap günü?  Zamana kustu Laleler... Çuval geçti başımıza, Zehir kattık aşımıza...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/isyan-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çikolata', 'cikolata-cihan-kaya-jalnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elinden alacağım / kandırıp 

masum çocuğun, 

çok sevdiği çikolatasını

senin gözlerini 

.......................ve 

............................sözlerini 

.............................................vererek...', 'Elinden alacağım / kandırıp  masum çocuğun,  çok sevdiği çikolatasını senin gözlerini  .......................ve  .............................', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cikolata-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-hale-kazak-phswe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşarken insan neler vermez ki uğruna,

Engel tanımaz taş bayır,

Tene dokunan buz soğuk,

İçte yanan kor ateş,büyütür güneşini,

Deli gönül laftan anlamaz,

Yüreği sürükler onu,

Uğruna canını koyduğu 

Sevgiliye...', 'Yaşarken insan neler vermez ki uğruna, Engel tanımaz taş bayır, Tene dokunan buz soğuk, İçte yanan kor ateş,büyütür güneşini, Deli gönül laf...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiliye-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum Vagonu', 'erzurum-vagonu-esra-ocak-tjp1t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah; 

Akşamüstü vardı avucumda 

güneş doğarken.

Disari ciktim bulamadim 

oysa 

Ayak izlerini saklamıştım dun  gece avluda

sen giderken



Bu sevda bitmez demiştin

Ama bak ne oldu sonunda

Ne ben varim nede sevdam simdi

Gittiğin Erzurum vagonunda

Bu öğlen; 

Dün gece vardı kollarımda

Kuslar cıvıldarken

Seslendim duyuramadim

oysa

Bana seslenişine boyamistim duvarlari 

sen giderken 



Bu sevda bitmez demiştin ya hani

Bak ne oldu sonunda

Ne ben varim nede sevdam simdi

Gittiğin Erzurum vagonunda

 Bu aksam 

Ogleden sonra vardi huzursuzlugumda

Yuregime indim iki merdivenle ama kapisini acamadim

Anahtari  da goturmussun  giderken yaninda



Bu sevda bitmez demiştin

Ama bak ne oldu sonunda

Ne ben varim nede sevdam simdi

Gittiğin Erzurum vagonunda



Bu gece anladim ki artik yoksun hayatimda

Günlüğümü  actim son yapragi da doldurdum anılarla

Sensizligi yazayim diye dusunurken yalnizligimla

Biliyorum ki

Ne ben varim

Ne de sevdam simdi

Yürüdüğün  Erzurum yollarinda', 'Bu sabah;  Akşamüstü vardı avucumda  güneş doğarken. Disari ciktim bulamadim  oysa  Ayak izlerini saklamıştım dun  gece avluda sen giderken ...', ARRAY['Türk Edebiyatı','Şiir','Esra Ocak']::text[], 8.5, '{"poet":"Esra Ocak","poet_slug":"esra-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/erzurum-vagonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cüce....', 'cuce-mehmet-demir-atmali-qwmt1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üstad Necip Fazıl derki; 

''Cüceden hiç dahi olmaz''

Kıçı yere yakın çünki; 

Yer çekimi kafi gelmez...

Marifetname''de geçer,

Nakıs olurmuş Cüceler...

Hasedinden zehir içer,

Fitne fücur şahi olmaz...

30.5.1989', 'Üstad Necip Fazıl derki;  ''Cüceden hiç dahi olmaz'' Kıçı yere yakın çünki;  Yer çekimi kafi gelmez... Marifetname''de geçer, Nakıs olurmuş Cüc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cuce-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlaradır Sitemlerim', 'bulutlaradir-sitemlerim-esra-ocak-disi6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Berrak MAVİ geleceklerde

uzanmış yatıyor hayallerim

MAVİ; 

Ekmek balıkçıya

MAVİ; 

Serap çöldeki yolcuya

MAVİ; 

Huzur

Huzura koşan benler gibi bir hancıya

Ve MAVİ  ilaçtır yani gerçek aşktır

Sahibinden satılığa çıkmış

kelepir kalpler sokağındaki 

yalancıya

MAVİ derin

Ve MAVİlerin

Misafiridir ya gri beyaz bulutlar

onlaradır sitemlerim

Çünkü herakşam

O bulutlar gibi sessiz

O bulutlar gibi nedensiz

yok olup gider hayallerim', 'Berrak MAVİ geleceklerde uzanmış yatıyor hayallerim MAVİ;  Ekmek balıkçıya MAVİ;  Serap çöldeki yolcuya MAVİ;  Huzur Huzura koşan benler gib...', ARRAY['Türk Edebiyatı','Şiir','Esra Ocak']::text[], 8.5, '{"poet":"Esra Ocak","poet_slug":"esra-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulutlaradir-sitemlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-ufuk-coban-ctsew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tutam güvenmiş dalların ucundaki,

Her sabah güneşten güç alarak büyümeye çalışan,

Kendini hep birine saklayan, insanlara yüz çeviren.

Artık o çiçek koparıldı, amacı bile sorulmadan.

Başka bir serüvene feda edildi.

Biliyordu ki; tek şansıydı kısıtlı ömründe kullanabileceği.

Ya kullanmayıp solacak, ya da bir mutluluğun kokusu olacak.

Sensiz şimdi o yalnız, bambaşka,

Kalp kırık, yenik aşka.

Belki bir inattı, belki bir intikam,

Belki de bir kızgınlık.

Ama ne olur, artık bir ses ver.

1999', 'Bir tutam güvenmiş dalların ucundaki, Her sabah güneşten güç alarak büyümeye çalışan, Kendini hep birine saklayan, insanlara yüz çeviren. Ar...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mesaj-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasamin Ismi Sen Olan', 'yasamin-ismi-sen-olan-hale-kazak-lw5w0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün dediğimiz nedir ki? ...

Şu dünyada,

Akıp geçiyor sular gibi

Aslında ne çok yaşanacak şey var,

Farkında olunca yaşamın,

Güzellikler de bizim için,

Acılar da bizim için,

Tıpkı gülmek gibi bir an,

Ve de ağlamak gibi bazen,

İşte bir denge hep dünya

Tıpkı manavın terazisi gibi,

Hem artılar var yaşamda

Tabi ki bir de eksiler,

Akıp geçiyor zaman,

Aynı anda mutluluklar yaşanırken,

Başka bir yerde acılar vurur insanı,

Bazen mutluluğu yaşayan,

Yasamda acıyı tanır,

Bazen acıyı yaşayan,

Yaşamak için umuda tutunur,

Dünyayı,yasamı nereye çekersen çek,

Hep denklem misali,

İşte alemlerden biri belki de bu,

Yaşanması gereken,

Acısıyla, tatlısıyla

Akıp geçiyor zaman

Anlatmakla bitmez inan,

Ama bu zamanda hep yanımdasın,

Yaşamın ismi sen olan...

Ben var oldukça kalbimde yaşayan...', 'Gün dediğimiz nedir ki? ... Şu dünyada, Akıp geçiyor sular gibi Aslında ne çok yaşanacak şey var, Farkında olunca yaşamın, Güzellikler de bi...', ARRAY['Türk Edebiyatı','Şiir','Hale Kazak']::text[], 8.5, '{"poet":"Hale Kazak","poet_slug":"hale-kazak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasamin-ismi-sen-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Bir Şey', 'tek-bir-sey-seyhan-sevgili-mlkdv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şey asılıyor ipimize, koparmadan çekiyor, çektiriyor.

Şöyle bi bakalım hayatımıza; ilk ne zaman uykusuz kaldık,

ne zaman geceleri gezer olduk.

Önce neye ıslandı kirpiklerimiz,en çok neye ağladık.

Bir kalbimizin olduğunu sızladığında fark etmedik mi? 

İlk ne zaman ölmeyi istedik.

Bir kağıda ihanet yazıp da, vasiyet diye koyduğumuzda masamıza sebebi neydi? 

Bir şey asılıyor ipimize, koparmadan çekiyor, bir ömür çektiriyor.', 'Bir şey asılıyor ipimize, koparmadan çekiyor, çektiriyor. Şöyle bi bakalım hayatımıza; ilk ne zaman uykusuz kaldık, ne zaman geceleri gezer ...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgili']::text[], 8.5, '{"poet":"Seyhan Sevgili","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tek-bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-mustafa-kartal-an47w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aradım,buldum 

Buldum,sordum 

Sordum,vardım 

Vardım aldım 

Sararım sandım 

Ve ben aldandım 

Sonuç hep aynı 

Sen öyle yandın 

Ben böyle yandım', 'Aradım,buldum  Buldum,sordum  Sordum,vardım  Vardım aldım  Sararım sandım  Ve ben aldandım  Sonuç hep aynı  Sen öyle yandın  Ben böyle yandı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yangin-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Tavsiye', 'kucuk-bir-tavsiye-baran-baransel-5gjnn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen SEN OL’madan

Yollarımda yürüme KÜÇÜĞÜM,

Ardıma düşme yalınayak,

Kırık kalpler batar da ayaklarına

________________________Kıyamam…

Benim geçtiğim köprüler

Taşımaz senin aymazlığını,

Başka ağızlara kucak açmaların,

Keskin bir ustura gibi 

Keser ya avuçlarımı,

Ellerini tutamam.

Düşersin gönlümün burçlarından apansız,

Ölümün ölümüm olur,

________________________Dayanamam...', 'Sen SEN OL’madan Yollarımda yürüme KÜÇÜĞÜM, Ardıma düşme yalınayak, Kırık kalpler batar da ayaklarına ________________________Kıyamam… Benim...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kucuk-bir-tavsiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma ki', 'sanma-ki-ugur-aydin-2-tdets', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüzün ''de  ''çizgiler izler belirir 

ışığı  tükenir  gözlerin  dalar 

saçının  rengi  beyazla  birdir

senin ''de'' benzin sararır solar

sanma ki kalacak sen ''de ''güzellik 

kara toprak bir gün seni ''de ''sarar 

ellerin titrer tuzmaz dizlerin 

senin ''de'' benzin sararır solar

yaprak  dökümüdür mevsim sonbahar 

puslu gözlerin birini bekler 

gelip gidenlerden bir dost aranır 

senin ''de'' benzin sararır solar', 'yüzün ''de  ''çizgiler izler belirir  ışığı  tükenir  gözlerin  dalar  saçının  rengi  beyazla  birdir senin ''de'' benzin sararır solar sanma k...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanma-ki-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben erkegim sapina kadar', 'ben-erkegim-sapina-kadar-husamettin-guven-is6ph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'durustlukten vermem taviz

yalakalik olmus caiz

kivirttirmak kotuye haiz

ben erkegim sapina kadar

hakliyi ben savunurum

haksizliga tavir korum

zalimlere derim durun

ben erkegim sapina kadar

mucadelem hep bu yolda

sevenlerim bak yanimda

zafer benim en sonunda

ben erkegim sapina kadar', 'durustlukten vermem taviz yalakalik olmus caiz kivirttirmak kotuye haiz ben erkegim sapina kadar hakliyi ben savunurum haksizliga tavir koru...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-erkegim-sapina-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siradaki beni bekler', 'siradaki-beni-bekler-husamettin-guven-g5449', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saygi,sevgi ve iltifat

hemen kendini anlat

acele bir masal sat

siradaki beni bekler

yemegi yedik bakalim

haydi gidip yatalim

doyasiya keyf catalim

siradaki beni bekler

askli, meskli sohbetler

benden sana hormetler

bitsin artik gorusmekler

siradaki beni bekler', 'saygi,sevgi ve iltifat hemen kendini anlat acele bir masal sat siradaki beni bekler yemegi yedik bakalim haydi gidip yatalim doyasiya keyf c...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siradaki-beni-bekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cellat', 'cellat-alaaddin-kulcuoglu-qlpvd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum

Hangi cellat 

Uzatıp ellerini 

O eşsiz güzelligi 

Umut çiçeklerimi 

Hiç gözünü kırpmadan 

Ayırdı gövdesinden.', 'Bilmiyorum Hangi cellat  Uzatıp ellerini  O eşsiz güzelligi  Umut çiçeklerimi  Hiç gözünü kırpmadan  Ayırdı gövdesinden....', ARRAY['Türk Edebiyatı','Şiir','Alaaddin Külcüoğlu']::text[], 8.5, '{"poet":"Alaaddin Külcüoğlu","poet_slug":"alaaddin-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cellat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Aşklar.', 'olu-asklar-i-shak-ozlu-a11u2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Aşk ölür,

Binler bırakarak.

Biri Can,

Biri Canan.

Hakka yürür,

Sevdalar saçarak.

Ölü Aşklar deriz,

Binler yaşatarak.

Her bir sevdayı,

Yıldızlara yazarak,

Saçarız Evrende,

İlk sevenden,

Son sevdalıya.

Ölü Aşklar,

Yaşasın diye.', 'Bir Aşk ölür, Binler bırakarak. Biri Can, Biri Canan. Hakka yürür, Sevdalar saçarak. Ölü Aşklar deriz, Binler yaşatarak. Her bir sevdayı, Yı...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olu-asklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolera Zamanı', 'kolera-zamani-mehmet-akif-gulhan-lpum4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kolera zamanı indim

Bayrampaşa’ya

İçmedim soğuk sular

Yansa da yüreğim

Cebimde on lira 

Gün bayram

Ziyaret zamanımı

Bilmem Bayrampaşa’da

Sordum kardeşimi

Başlar yere döndü

Dediler hücrede

Elim cebimde

Cebimde on lira

Sal beni yanına tertip

Yansa da askerlik

Yanarsa baba yüreği

Askerliğin ne önemi var

Ben babama ne diyeceğim

Soğuk demir arkasında

Gülümsedi,dövmüşler

Anamıza sövmüşler

Koymaz bana dayak

Çocuklukta şerbetliyim dedi

Babama kardeşim iyi de

Söyle tertibe su getirsin

Soğumaz bu yürek bu yara 

İçeceğim kana,kana

Bayramda hücre gördüm

Yanaşamaz  bana kolera

Mehmet Akif Gülhan 08.05.2004', 'Kolera zamanı indim Bayrampaşa’ya İçmedim soğuk sular Yansa da yüreğim Cebimde on lira  Gün bayram Ziyaret zamanımı Bilmem Bayrampaşa’da Sor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kolera-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara bahtlı', 'kara-bahtli-ahmet-kesici-1ugci', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belediye otobüsünde bir çocuk, 

yaşlı bir adama oturması için yer vermez. 

Otobüsteki insanlar,

''''zamane gençliği saygısız''''diyerek ayıplarlar genç çocuğu. 

Çocuk hafiften dönerek, 

siz hiç okula gitmeniz gerekirken 

bir tamir atölyesine çırak olarak verildiniz mi.? 

Hem de ''''eti senin kemiği benim usta'''' 

deyip giden babanızın ardında kaldı mı gözleriniz.? 

Mesai gecelerinde, 

uykusuzluktan yanlış cıvatayı sıkınca,

ustanızdan küfür yediniz mi.? 

Son otobüsü de kaçırınca,

evinize kadar yayan yürüdünüz mü ki.? 

Her gece döndüğünüzde yorgun bedeninizle fakir evinize 

kireç boyalı odanızın yoksul divanına yükleyip hakir bedeninizi 

gözlerinizi tavana dikip, mutlu olmak için hayaller kurdunuz mu ki.? 

Sizin yaptığınız, 

sevgisiz büyümüş birinden saygı beklemektir sadece. 

Hem ben o kadar saygısız değilim. 

Buyur amca otur yerime. 

Kusura bakma görmedim seni. 

Gözlerim dalıp gitmiş. 

Yüreğim acıya gönül vermiş. 

Hem bakın yaşım daha 16 

Hangi kız sever beni ha.? 

Hangi güzel yüreğini açar bana.? 

Bakın ellerim kara, yüzüm kara 

gönlüm kalbim bembeyaz ama, bahtım kara. 

Hem ben 

O okulların, sınıflarındaki kara tahtalarına bir şeyler yazmadım. 

O tahta sıralarda oturmadım. 

Rengi mühim değil güzel bir çantam,

kitabım, kalemim, defterim olmadı.

Bana okumayı yazmayı

komşumuz emekli Öğretmen bahtiyar efendi öğretti. 

''''Okusaydın büyük adam olurdun sen evlat’’ derdi. 

Karne günlerin de, 

sınıfını geçen çocuklara karne hediyesi bisiklet alırdı babaları. 

Ne kadar ellerde ki bembeyaz karnelerde olsa da gönlüm, 

bisikletin parlayan jantların da kalırdı gözüm. 

Ve biraz daha büyürdü içimde sessiz kalmış hüznüm.

Biliyormusunuz? 

Kızardım dünyanın güzelliklerine. 

Kızardım baharın yazın gelmesine. 

Ve bozulurdum arkadaşlarımın beni bırakıp gitmesine. 

Bütün terslikler üst üste geliyordu. 

Mutlu olan insanlar beni anlamıyordu. 

Onlarda sızlatıyordu sizin gibi

bahtımın kanayan yarasını. 

Ne kadar geçse de yıkamayla elimin yüzünüm karası, 

bir türlü geçmek bilmiyordu 

aydınlanmıyordu bahtımın karası. 

Neyse, 

sizin ağrıdım başınızı. 

Ben artık ineyim ilk durakta. 

Sizde beni tanıyın, 

...................................ben bahtı kara...', 'Belediye otobüsünde bir çocuk,  yaşlı bir adama oturması için yer vermez.  Otobüsteki insanlar, ''''zamane gençliği saygısız''''diyerek ayıplarl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kesici']::text[], 8.5, '{"poet":"Ahmet Kesici","poet_slug":"ahmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/kara-bahtli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Men Sene Neylemişem', 'men-sene-neylemisem-murat-kilic-2-tnoew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ceylanım,

Cem - i cihanda gül yüzlü yarim.

Özüne canı feda eylemişem.

Hayz ederem bu elemlerden apar meni.

Gözümün nuru könül sultanım,

Gel de mehebbete halget özümi.

Men naçaram can.

Könüldeki çarasız yaranın,

Bir tek sendedir merhemi.

Aybala! 

Men sene neylemişem ki,

Mene bu zulmü reva görirsen.

Könül senden gayrısına meyl etmez,

Bilmez misen? 

Özünden ayrı geceler gündüzler geçirebilmerem.

Bilmez misen ki,

Yüzüne yüz sürmezisem; 

Men ölürem.

Menim könül hoyrattır belki.

Belki bir dem seyyah - ı deli.

Amma ve lakin möhtaçtır eline.

Fikrin özümün vazgeçilebilmezidir.

Sinem biçara, parça parça; 

Gözlerin gözlerime düştüğü günden ötedir.

Aycan! 

Senden tek arzuhalım şu ola:

Hani bizim ellerin

Kendine özge yaylaları bilirsen.

Oralarda mehebbetle gezinen

Ceylanları görebilirsen.

Ne gözeldirler değil mi bala.

Men de isteremki sen de özüme ele özge olasan.

Men sene “ can ” deyerem,

Sen de könlüme girip “ canan ” olasan.

Men dilemedikçe özümden ayrılmayasan.

Hep yanımda galasan.', 'Ceylanım, Cem - i cihanda gül yüzlü yarim. Özüne canı feda eylemişem. Hayz ederem bu elemlerden apar meni. Gözümün nuru könül sultanım, Gel ...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/men-sene-neylemisem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Polise Şükran', 'polise-sukran-kadir-kaya-ic99l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'POLİSİM

Barış için aşkla çarpar yüreği,

Halkına hizmete koşar Polisim.

Huzurla güvenin temel direği,

Zorluğu, engeli aşar Polisim.

Gecede, gündüzde, görev anında,

Haklıya arkadır, olur yanında,

Mazlumun sevgisi coşar kanında,

Sabır ocağında pişer Polisim.

İmdada, yardıma her zaman hazır,

Şer ocaklarının kökünü kazır,

Böylece sağlanır ülkemde huzur,

Her an hazır kıta yaşar Polisim.

Havadan, karadan aşılır dağlar,

Çevik kuvvet, trafik, düzeni sağlar,

Özel harekât’ım zalimi bağlar,

Cesur ekibiyle coşar Polisim.

Bilgi-işlem ister formu yazmanı,

Mangal yüreklidir bomba uzmanı,

Candan ister senin mutlu gezmeni,

Sevgin gönüllerden taşar Polisim.

Suçun oluşuna müsaade etmez,

Uyuşturucuyla savaşı bitmez,

Özel zamanlarda evine gitmez,

Herkes bu azmine şaşar Polisim.

Yaşayan şerefe  yüce şan gerek,

Hasretten vuslata tatlı an gerek,,

Kadirim,  ölmeye hazır can gerek,

Görev için şehit düşer Polisim.', 'POLİSİM Barış için aşkla çarpar yüreği, Halkına hizmete koşar Polisim. Huzurla güvenin temel direği, Zorluğu, engeli aşar Polisim. Gecede, g...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/polise-sukran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mühürlü Hasret', 'muhurlu-hasret-murat-kilic-2-z70e5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mucizedir gülüşün senle örülü ütopyamda.

Canıma yazdığım ad sorgusuz sualsizleşmiştir. 

Ne kadar uzakta olursan ol eminim ki,

O billur yüzünde mevsimler gamzeleşmiştir.

Seni bana yamayan onlarca şey; 

Bu sahil,  akşamlar… daha nicesi,

Bulut bulut, yağmur yağmur,

Gözlerinde yeşermiştir.

Uçuk kaçık hallerinin aşığı benim hâlâ.

Bırak beni kendime, hep böyle kalayım.

Sabahları seninle ıslansın yüzüm,

Kanatlarıma alıp ismini,

Seni en kesif rüzgarlara salayım.

Ezik bir türkü ol dilimde,

Islık ıslık, sokaklarda seni mırıldanayım.

Yağmur ne bilsin çölün halinden.

Bir ışık yakıver uzaklardan aydınlanayım.

Akasya kokan saçlarından

Bir tutam gönder de; 

Özlemlerime derman diye sarayım.

Kalbime mühürlediğin bu hasreti,

Bu sensizliği,

Ya gel al ya da iyice;

Kendimle sarıp sarmalayayım.', 'Mucizedir gülüşün senle örülü ütopyamda. Canıma yazdığım ad sorgusuz sualsizleşmiştir.  Ne kadar uzakta olursan ol eminim ki, O billur yüzün...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/muhurlu-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yollarmı Göründü..', 'sana-yollarmi-gorundu-sair-salma-pxgfe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç  ummadığım  bir   zamanda...

Çıktın  karşıma...

Gönlümün  nehirlerini....

Yine  taşırmaaa....

Ahhh....şu  gözlerimm...

Çağlaya  çağlaya....

Yine  ağlamaa.......

Sevdammm..  yine   sana...

Yollar mı   göründü....

Sen ki  artık  son  demedin mii...

Yaşadığım   şeylere...

Geri  dönemem  demedin mii....

Bir  daha  ayrılık  acısına..

Katlanamam   demedin mii....

Ahhhh....deli    gönlümm....

Ben  sana  söylemedim mi....

Yine  aldanır  kanarsın  demedim mi...

Sevdammm...yine  sana..

Yollar mı   göründü....

SALMA', 'Hiç  ummadığım  bir   zamanda... Çıktın  karşıma... Gönlümün  nehirlerini.... Yine  taşırmaaa.... Ahhh....şu  gözlerimm... Çağlaya  çağlaya....', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-yollarmi-gorundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Aynı', 'hep-ayni-murat-kilic-2-w1gok', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şey aynı, değişen bir şey yok.

İçimdeki burukluk aynı, hep aynı.

Takatim yok aynaya bakmaya,

Baksam da ser aynı, hep aynı.

Yalnızlığın esiri olmuş gidiyor can.

İçimde kalmamış bir damla heyecan.

Batan günün ardından ağlayan,

Buğulu gözler aynı, hep aynı.

Sedasızlığın sesidir şimdi duyulan.

Seçilmişlerde olur bende bulunan.

Belki bir gün gülecek diye umulan,

Umutsuz dilekler aynı, hep aynı.

İçimde söner mi bu yangın bir gün.

Ömrüm kader içinde bitmez sürgün.

Yaşama sırt çeviren bahar üzgün.

Yorgun yürekler aynı, hep aynı.

Aklımdan çıkmaz gözlerin asla.

Geçer gider ömrüm, gamla yasla.

Sana yürüyorum yaşama kıyasla; 

Uzattığım eller aynı, hep aynı.', 'Her şey aynı, değişen bir şey yok. İçimdeki burukluk aynı, hep aynı. Takatim yok aynaya bakmaya, Baksam da ser aynı, hep aynı. Yalnızlığın e...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hep-ayni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
